



CREATE OR REPLACE FUNCTION public._pay_timesheet_rotation_scope(p_timesheet_ids uuid[])
 RETURNS TABLE(requested_timesheet_id uuid, booking_id text, canonical_timesheet_id uuid, family_timesheet_id uuid, family_is_current boolean, family_version integer, requested_is_canonical boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH input_timesheets AS (
  SELECT DISTINCT
    input_timesheet_values.timesheet_id_value AS requested_timesheet_id
  FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_timesheet_values(timesheet_id_value)
  WHERE input_timesheet_values.timesheet_id_value IS NOT NULL
),
requested_timesheets AS (
  SELECT
    input_timesheets.requested_timesheet_id AS requested_timesheet_id,
    public.timesheets.timesheet_id AS matched_timesheet_id,
    public.timesheets.booking_id AS matched_booking_id
  FROM input_timesheets
  LEFT JOIN public.timesheets
    ON public.timesheets.timesheet_id = input_timesheets.requested_timesheet_id
),
requested_bookings AS (
  SELECT DISTINCT
    requested_timesheets.matched_booking_id AS booking_id
  FROM requested_timesheets
  WHERE requested_timesheets.matched_timesheet_id IS NOT NULL
    AND requested_timesheets.matched_booking_id IS NOT NULL
    AND BTRIM(requested_timesheets.matched_booking_id) <> ''
),
canonical_timesheets AS (
  SELECT DISTINCT ON (current_timesheets.booking_id)
    current_timesheets.booking_id AS booking_id,
    current_timesheets.timesheet_id AS canonical_timesheet_id
  FROM public.timesheets AS current_timesheets
  JOIN requested_bookings
    ON requested_bookings.booking_id = current_timesheets.booking_id
  WHERE current_timesheets.is_current = true
  ORDER BY
    current_timesheets.booking_id,
    current_timesheets.version DESC,
    current_timesheets.updated_at DESC,
    current_timesheets.created_at DESC,
    current_timesheets.timesheet_id
),
family_timesheets AS (
  SELECT DISTINCT
    family_rows.booking_id AS booking_id,
    family_rows.timesheet_id AS family_timesheet_id,
    family_rows.is_current AS family_is_current,
    family_rows.version AS family_version
  FROM public.timesheets AS family_rows
  JOIN requested_bookings
    ON requested_bookings.booking_id = family_rows.booking_id
),
resolved_scope_rows AS (
  SELECT
    requested_timesheets.requested_timesheet_id AS requested_timesheet_id,
    requested_timesheets.matched_booking_id AS booking_id,
    canonical_timesheets.canonical_timesheet_id AS canonical_timesheet_id,
    family_timesheets.family_timesheet_id AS family_timesheet_id,
    family_timesheets.family_is_current AS family_is_current,
    family_timesheets.family_version AS family_version,
    COALESCE(requested_timesheets.requested_timesheet_id = canonical_timesheets.canonical_timesheet_id, false) AS requested_is_canonical
  FROM requested_timesheets
  JOIN family_timesheets
    ON family_timesheets.booking_id = requested_timesheets.matched_booking_id
  LEFT JOIN canonical_timesheets
    ON canonical_timesheets.booking_id = requested_timesheets.matched_booking_id
  WHERE requested_timesheets.matched_timesheet_id IS NOT NULL
),
defensive_unresolved_rows AS (
  SELECT
    requested_timesheets.requested_timesheet_id AS requested_timesheet_id,
    NULL::text AS booking_id,
    requested_timesheets.requested_timesheet_id AS canonical_timesheet_id,
    requested_timesheets.requested_timesheet_id AS family_timesheet_id,
    NULL::boolean AS family_is_current,
    NULL::integer AS family_version,
    false AS requested_is_canonical
  FROM requested_timesheets
  WHERE requested_timesheets.matched_timesheet_id IS NULL
),
rotation_scope_output AS (
  SELECT
    resolved_scope_rows.requested_timesheet_id AS requested_timesheet_id,
    resolved_scope_rows.booking_id AS booking_id,
    resolved_scope_rows.canonical_timesheet_id AS canonical_timesheet_id,
    resolved_scope_rows.family_timesheet_id AS family_timesheet_id,
    resolved_scope_rows.family_is_current AS family_is_current,
    resolved_scope_rows.family_version AS family_version,
    resolved_scope_rows.requested_is_canonical AS requested_is_canonical
  FROM resolved_scope_rows

  UNION ALL

  SELECT
    defensive_unresolved_rows.requested_timesheet_id AS requested_timesheet_id,
    defensive_unresolved_rows.booking_id AS booking_id,
    defensive_unresolved_rows.canonical_timesheet_id AS canonical_timesheet_id,
    defensive_unresolved_rows.family_timesheet_id AS family_timesheet_id,
    defensive_unresolved_rows.family_is_current AS family_is_current,
    defensive_unresolved_rows.family_version AS family_version,
    defensive_unresolved_rows.requested_is_canonical AS requested_is_canonical
  FROM defensive_unresolved_rows
)
SELECT
  rotation_scope_output.requested_timesheet_id,
  rotation_scope_output.booking_id,
  rotation_scope_output.canonical_timesheet_id,
  rotation_scope_output.family_timesheet_id,
  rotation_scope_output.family_is_current,
  rotation_scope_output.family_version,
  rotation_scope_output.requested_is_canonical
FROM rotation_scope_output
ORDER BY
  rotation_scope_output.requested_timesheet_id,
  rotation_scope_output.booking_id NULLS LAST,
  rotation_scope_output.family_is_current DESC NULLS LAST,
  rotation_scope_output.family_version DESC NULLS LAST,
  rotation_scope_output.family_timesheet_id;
$function$;


CREATE OR REPLACE FUNCTION public._pay_policy_x_resolve_pre_draft_economic_key(
  p_timesheet_id uuid DEFAULT NULL::uuid,
  p_live_source_json jsonb DEFAULT '{}'::jsonb,
  p_item_type text DEFAULT NULL::text,
  p_key_type_hint text DEFAULT NULL::text,
  p_key_value_hint text DEFAULT NULL::text,
  p_work_date date DEFAULT NULL::date
)
RETURNS TABLE(
  timesheet_id uuid,
  key_type text,
  key_value text,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_source_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_live_source_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_live_source_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_timesheet_id uuid := p_timesheet_id;
  v_timesheet_id_text text;
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, '')), ''));
  v_direct_key_type text;
  v_direct_key_value text;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_failure_reason text := NULL::text;
  v_assert_ok boolean := false;
  v_assert_key_type text := NULL::text;
  v_assert_key_value text := NULL::text;
  v_assert_failure_reason text := NULL::text;
  v_work_date_text text := NULL::text;
  v_segment_id_text text := NULL::text;
  v_segment_key_text text := NULL::text;
  v_segment_stable_key_text text := NULL::text;
  v_ref_num_text text := NULL::text;
  v_adjustment_id_text text := NULL::text;
  v_additional_code_text text := NULL::text;
  v_expense_code_text text := NULL::text;
  v_segments_json jsonb := '[]'::jsonb;
  v_live_schedule_json jsonb := '{}'::jsonb;
  v_segment_match_found boolean := false;
  v_segment_match_date_text text := NULL::text;
  v_timesheet_start_date_text text := NULL::text;
BEGIN
  v_timesheet_id_text := NULLIF(BTRIM(COALESCE(v_source_json->>'timesheet_id', '')), '');
  IF v_timesheet_id IS NULL
     AND v_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_item_type IS NULL THEN
    v_item_type := UPPER(NULLIF(BTRIM(COALESCE(
      v_source_json->>'item_type',
      v_source_json->>'line_type',
      v_source_json->>'component_type',
      v_source_json#>>'{source_basis_json,item_type}',
      ''
    )), ''));
  END IF;

  v_direct_key_type := UPPER(NULLIF(BTRIM(COALESCE(
    p_key_type_hint,
    v_source_json->>'component_key_type',
    v_source_json->>'key_type',
    v_source_json#>>'{source_basis_json,component_key_type}',
    v_source_json#>>'{source_basis_json,key_type}',
    ''
  )), ''));

  v_direct_key_value := NULLIF(BTRIM(COALESCE(
    p_key_value_hint,
    v_source_json->>'component_key_value',
    v_source_json->>'key_value',
    v_source_json#>>'{source_basis_json,component_key_value}',
    v_source_json#>>'{source_basis_json,key_value}',
    ''
  )), '');

  IF v_direct_key_type IS NOT NULL OR v_direct_key_value IS NOT NULL THEN
    SELECT
      key_check.ok,
      key_check.key_type,
      key_check.key_value,
      key_check.failure_reason
    INTO
      v_assert_ok,
      v_assert_key_type,
      v_assert_key_value,
      v_assert_failure_reason
    FROM public._pay_policy_x_assert_economic_key(
      p_timesheet_id => v_timesheet_id,
      p_key_type => v_direct_key_type,
      p_key_value => v_direct_key_value,
      p_context => 'PRE_DRAFT_RESOLVE_DIRECT_KEY',
      p_authority_scope => 'PRE_DRAFT',
      p_resolution_source => 'PRE_DRAFT_LIVE_DIRECT_KEY',
      p_required => true,
      p_source_json => v_source_json
    ) AS key_check;

    IF COALESCE(v_assert_ok, false) THEN
      v_resolved_key_type := v_assert_key_type;
      v_resolved_key_value := v_assert_key_value;
      v_resolved_source := 'PRE_DRAFT_LIVE_DIRECT_KEY';
    ELSE
      v_failure_reason := v_assert_failure_reason;
    END IF;
  END IF;

  IF v_resolved_key_type IS NULL THEN
    v_work_date_text := COALESCE(
      CASE WHEN p_work_date IS NULL THEN NULL::text ELSE p_work_date::text END,
      NULLIF(BTRIM(COALESCE(v_source_json->>'work_date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json->>'date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,date}', '')), '')
    );

    v_segment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_id',
      v_source_json#>>'{source_basis_json,segment_id}',
      v_source_json#>>'{segment,segment_id}',
      v_source_json#>>'{segment_json,segment_id}',
      ''
    )), '');

    v_segment_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_key',
      v_source_json#>>'{source_basis_json,segment_key}',
      v_source_json#>>'{segment,segment_key}',
      v_source_json#>>'{segment_json,segment_key}',
      ''
    )), '');

    v_segment_stable_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_stable_key',
      v_source_json#>>'{source_basis_json,segment_stable_key}',
      v_source_json#>>'{segment,segment_stable_key}',
      v_source_json#>>'{segment_json,segment_stable_key}',
      ''
    )), '');

    v_ref_num_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'ref_num',
      v_source_json#>>'{source_basis_json,ref_num}',
      v_source_json#>>'{segment,ref_num}',
      v_source_json#>>'{segment_json,ref_num}',
      ''
    )), '');

    v_adjustment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'adjustment_id',
      v_source_json->>'adjustment_code',
      v_source_json#>>'{source_basis_json,adjustment_id}',
      v_source_json#>>'{source_basis_json,adjustment_code}',
      ''
    )), '');

    v_additional_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'additional_code',
      v_source_json#>>'{source_basis_json,additional_code}',
      ''
    )), '');

    v_expense_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'expense_code',
      v_source_json->>'mileage_code',
      v_source_json#>>'{source_basis_json,expense_code}',
      v_source_json#>>'{source_basis_json,mileage_code}',
      ''
    )), '');

    IF v_item_type IN ('SEGMENT_DELTA', 'SEGMENT', 'TIMESHEET_SEGMENT', 'HOURS') THEN
      IF v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_resolved_key_type := 'TS_DAY';
        v_resolved_key_value := v_work_date_text;
        v_resolved_source := 'PRE_DRAFT_LIVE_WORK_DATE';
      END IF;

      IF v_resolved_key_type IS NULL THEN
        IF jsonb_typeof(v_source_json->'segments') = 'array' THEN
          v_segments_json := v_source_json->'segments';
        ELSIF jsonb_typeof(v_source_json#>'{actual_schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{actual_schedule_json,segments}';
        ELSIF jsonb_typeof(v_source_json#>'{schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{schedule_json,segments}';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text)
              OR (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text THEN 0
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(latest_finance.actual_schedule_json, timesheet_row.actual_schedule_json, '{}'::jsonb)
        INTO v_live_schedule_json
        FROM public.timesheets AS timesheet_row
        LEFT JOIN LATERAL (
          SELECT finance_row.actual_schedule_json
          FROM public.timesheets_financials AS finance_row
          WHERE finance_row.timesheet_id = timesheet_row.timesheet_id
            AND finance_row.is_current = true
          ORDER BY finance_row.computed_at_utc DESC, finance_row.id DESC
          LIMIT 1
        ) AS latest_finance ON true
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF jsonb_typeof(v_live_schedule_json->'segments') = 'array' THEN
          v_segments_json := v_live_schedule_json->'segments';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          v_segment_match_found := false;
          v_segment_match_date_text := NULL::text;

          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(timesheet_row.worked_start_iso::date::text, timesheet_row.scheduled_start_iso::date::text)
        INTO v_timesheet_start_date_text
        FROM public.timesheets AS timesheet_row
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF v_timesheet_start_date_text IS NOT NULL THEN
          v_resolved_key_type := 'TS_DAY';
          v_resolved_key_value := v_timesheet_start_date_text;
          v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_START_DATE';
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL THEN
        v_resolved_key_type := 'TS_TOTAL';
        v_resolved_key_value := 'TOTAL';
        v_resolved_source := 'PRE_DRAFT_LIVE_TOTAL_FALLBACK';
      END IF;

    ELSIF v_item_type = 'ADJUSTMENT_DELTA' AND v_adjustment_id_text IS NOT NULL THEN
      v_resolved_key_type := 'ADJUSTMENT_CODE';
      v_resolved_key_value := v_adjustment_id_text;
      v_resolved_source := 'PRE_DRAFT_LIVE_ADJUSTMENT_KEY';

    ELSIF v_item_type = 'EXPENSE_DELTA' AND v_additional_code_text IS NOT NULL THEN
      v_resolved_key_type := 'ADDITIONAL_CODE';
      v_resolved_key_value := UPPER(v_additional_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_ADDITIONAL_CODE';

    ELSIF v_item_type IN ('EXPENSE_DELTA', 'MILEAGE_DELTA') AND v_expense_code_text IS NOT NULL THEN
      v_resolved_key_type := 'EXPENSE_CODE';
      v_resolved_key_value := UPPER(v_expense_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_EXPENSE_CODE';
    END IF;
  END IF;

  SELECT
    key_check.ok,
    key_check.key_type,
    key_check.key_value,
    key_check.failure_reason
  INTO
    v_assert_ok,
    v_assert_key_type,
    v_assert_key_value,
    v_assert_failure_reason
  FROM public._pay_policy_x_assert_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_key_type => v_resolved_key_type,
    p_key_value => v_resolved_key_value,
    p_context => 'PRE_DRAFT_RESOLVE_FINAL',
    p_authority_scope => 'PRE_DRAFT',
    p_resolution_source => COALESCE(v_resolved_source, 'PRE_DRAFT_KEY_RESOLUTION_FAILED'),
    p_required => true,
    p_source_json => v_source_json
  ) AS key_check;

  IF COALESCE(v_assert_ok, false) THEN
    timesheet_id := v_timesheet_id;
    key_type := v_assert_key_type;
    key_value := v_assert_key_value;
    key_resolution_source := v_resolved_source;
    key_resolution_failure_reason := NULL::text;
  ELSE
    timesheet_id := v_timesheet_id;
    key_type := NULL::text;
    key_value := NULL::text;
    key_resolution_source := 'KEY_RESOLUTION_FAILED';
    key_resolution_failure_reason := COALESCE(v_failure_reason, v_assert_failure_reason, 'PRE_DRAFT_KEY_RESOLUTION_FAILED');
  END IF;

  RETURN NEXT;
END;
$function$;

-- =========================================================
-- Helpers (private)
-- ==========================================================


-- Normalize percent: supports 20 or 0.2 -> returns 0.2
create or replace function public._pay_pct_to_frac(p_pct numeric)
returns numeric
language plpgsql
immutable
as $$
begin
  if p_pct is null then return 0; end if;
  if p_pct > 1 then return p_pct / 100; end if;
  return p_pct;
end;
$$;

-- 1 + pct (supports 15 or 0.15 -> 1.15)
create or replace function public._pay_pct_to_mult(p_pct numeric)
returns numeric
language plpgsql
immutable
as $$
declare
  v_frac numeric;
begin
  v_frac := public._pay_pct_to_frac(p_pct);
  return 1 + coalesce(v_frac, 0);
end;
$$;

-- Monday week-start for a given date
create or replace function public._pay_week_start_monday(p_date date)
returns date
language plpgsql
immutable
as $$
declare
  v_dow int;
  v_offset int;
begin
  if p_date is null then return null; end if;
  v_dow := extract(dow from p_date)::int;      -- 0=Sun..6=Sat
  v_offset := (v_dow + 6) % 7;                 -- days since Monday
  return (p_date - v_offset);
end;
$$;

-- Umbrella VAT calc: returns {ex, vat, inc}
create or replace function public._pay_umbrella_vat_calc(
  p_ex numeric,
  p_vat_rate_pct numeric,
  p_vat_chargeable boolean
)
returns jsonb
language plpgsql
immutable
as $$
declare
  v_ex numeric := coalesce(p_ex,0);
  v_vat numeric := 0;
  v_inc numeric := 0;
  v_frac numeric := public._pay_pct_to_frac(p_vat_rate_pct);
begin
  if coalesce(p_vat_chargeable,false) then
    v_vat := round(v_ex * v_frac, 2);
    v_inc := round(v_ex + v_vat, 2);
  else
    v_vat := 0;
    v_inc := round(v_ex, 2);
  end if;

  return jsonb_build_object(
    'ex', round(v_ex,2),
    'vat', round(v_vat,2),
    'inc', round(v_inc,2)
  );
end;
$$;

-- Conversion: PAYE(ex) -> UMBRELLA (ex after ERNI, then VAT if chargeable)
create or replace function public._pay_convert_paye_to_umbrella(
  p_paye_ex numeric,
  p_erni_pct numeric,
  p_vat_rate_pct numeric,
  p_vat_chargeable boolean
)
returns jsonb
language plpgsql
immutable
as $$
declare
  v_erni_mult numeric := public._pay_pct_to_mult(p_erni_pct);
  v_ex numeric := round(coalesce(p_paye_ex,0) * v_erni_mult, 2);
begin
  return public._pay_umbrella_vat_calc(v_ex, p_vat_rate_pct, p_vat_chargeable);
end;
$$;

-- Conversion: UMBRELLA(ex) -> PAYE(ex) (reverse ERNI; VAT not applicable on PAYE)
create or replace function public._pay_convert_umbrella_to_paye_ex(
  p_umbrella_ex numeric,
  p_erni_pct numeric
)
returns numeric
language plpgsql
immutable
as $$
declare
  v_erni_mult numeric := public._pay_pct_to_mult(p_erni_pct);
  v_ex numeric := coalesce(p_umbrella_ex,0);
begin
  if v_erni_mult <= 0 then v_erni_mult := 1; end if;
  return round(v_ex / v_erni_mult, 2);
end;
$$;

-- Robust CSV line parser (handles quoted fields, commas inside quotes)
create or replace function public._pay_csv_parse_line(p_line text)
returns text[]
language plpgsql
immutable
as $$
declare
  v text := coalesce(p_line,'');
  i int := 1;
  ch text;
  in_quotes boolean := false;
  cur text := '';
  out_arr text[] := array[]::text[];
begin
  while i <= char_length(v) loop
    ch := substr(v, i, 1);

    if ch = '"' then
      -- Double quote escape inside quoted field
      if in_quotes and i < char_length(v) and substr(v, i+1, 1) = '"' then
        cur := cur || '"';
        i := i + 1;
      else
        in_quotes := not in_quotes;
      end if;

    elsif ch = ',' and not in_quotes then
      out_arr := out_arr || array[cur];
      cur := '';

    else
      cur := cur || ch;
    end if;

    i := i + 1;
  end loop;

  out_arr := out_arr || array[cur];
  return out_arr;
end;
$$;

create or replace function public._pay_csv_trim_field(p_field text)
returns text
language plpgsql
immutable
as $$
begin
  return nullif(btrim(coalesce(p_field,'')), '');
end;
$$;


DROP FUNCTION IF EXISTS public.pay_batch_cancel(uuid, uuid, text);



create or replace function public.pay_batch_cancel(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_reason text,
  p_correction_request_id uuid DEFAULT NULL::uuid,
  p_work_item_id uuid DEFAULT NULL::uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_batch public.pay_batches%rowtype;
  v_evidence_json jsonb := '{}'::jsonb;
  v_result_json jsonb := '{}'::jsonb;
  v_progress_json jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_reason text := COALESCE(NULLIF(btrim(p_reason), ''), 'Pre-bank cancellation requested');
  v_idempotency_key text := NULL::text;
  v_correction_request_id uuid := p_correction_request_id;
  v_active_payment_item_count integer := 0;
  v_pending_work_count integer := 0;
  v_processing_work_count integer := 0;
  v_applied_work_count integer := 0;
  v_blocked_work_count integer := 0;
  v_failed_work_count integer := 0;
  v_live_signal_result jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED')::text;
  end if;

  if p_actor_user_id is null then
    raise exception 'PAY_BATCH_CANCEL_ACTOR_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_ACTOR_REQUIRED')::text;
  end if;

  select public.pay_batches.*
  into v_batch
  from public.pay_batches
  where public.pay_batches.id = p_pay_batch_id
  for update;

  if not found then
    raise exception 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id)::text;
  end if;

  v_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id, true);

  if COALESCE((v_evidence_json->>'has_external_provider_submission')::boolean, false)
     or COALESCE((v_evidence_json->>'has_pending_provider_outcome')::boolean, false)
     or COALESCE((v_evidence_json->>'has_unknown_provider_outcome')::boolean, false)
     or COALESCE((v_evidence_json->>'has_terminal_no_money')::boolean, false)
     or COALESCE((v_evidence_json->>'has_final_paid_or_settled')::boolean, false) then
    v_blockers := jsonb_build_array(jsonb_build_object(
      'code', 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT',
      'message', 'Whole-batch local cancellation is blocked because provider submission, terminal no-money, unknown outcome, pending provider state, or paid/settled evidence exists.',
      'submission_evidence', v_evidence_json
    ));

    raise exception 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT',
              'pay_batch_id', p_pay_batch_id,
              'blockers', v_blockers,
              'submission_evidence', v_evidence_json
            )::text;
  end if;

  if exists (
    select 1
    from public.banking_pay_operations as provider_operation
    where provider_operation.pay_batch_id = p_pay_batch_id
      and provider_operation.operation_type in ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      and provider_operation.phase in ('SUBMIT_PROVIDER_TRANSFERS', 'PROVIDER_SUBMIT', 'CLAIM_PROVIDER_SUBMIT', 'EXECUTE_PROVIDER')
      and provider_operation.status in ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED')
    limit 1
  ) then
    raise exception 'PAY_BATCH_CANCEL_PROVIDER_SUBMISSION_IN_PROGRESS'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_CANCEL_PROVIDER_SUBMISSION_IN_PROGRESS',
              'pay_batch_id', p_pay_batch_id
            )::text;
  end if;

  v_idempotency_key := COALESCE(
    CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE 'pay-batch-cancel-existing-request:' || v_correction_request_id::text END,
    'pay-batch-cancel:' || p_pay_batch_id::text
  );

  v_result_json := public.pay_payment_cancel_not_sent_and_recalculate(
    p_pay_batch_id => p_pay_batch_id,
    p_selection_json => jsonb_build_object(
      'scope_type', 'BATCH',
      'source_context', 'pay_batch_cancel',
      'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
      'legacy_entry_point', true,
      'db_status_rule', 'Only existing pay_batches.status values are written; derived partial lifecycle labels remain payload-only.'
    ),
    p_actor_user_id => p_actor_user_id,
    p_reason => v_reason,
    p_idempotency_key => v_idempotency_key,
    p_confirmation_json => jsonb_build_object(
      'confirmed_pre_provider_cancel', true,
      'legacy_pay_batch_cancel_entry_point', true,
      'called_from_work_item_id', CASE WHEN p_work_item_id IS NULL THEN NULL ELSE p_work_item_id::text END
    )
  );

  v_correction_request_id := COALESCE(
    NULLIF(v_result_json->>'correction_request_id', '')::uuid,
    v_correction_request_id
  );

  if v_correction_request_id is not null then
    select jsonb_build_object(
             'total', count(*)::integer,
             'pending', count(*) filter (where work_items.status = 'PENDING')::integer,
             'processing', count(*) filter (where work_items.status = 'PROCESSING')::integer,
             'applied', count(*) filter (where work_items.status = 'APPLIED')::integer,
             'blocked', count(*) filter (where work_items.status = 'BLOCKED')::integer,
             'failed_retryable', count(*) filter (where work_items.status = 'FAILED_RETRYABLE')::integer,
             'failed_final', count(*) filter (where work_items.status = 'FAILED_FINAL')::integer
           ),
           count(*) filter (where work_items.status = 'PENDING')::integer,
           count(*) filter (where work_items.status = 'PROCESSING')::integer,
           count(*) filter (where work_items.status = 'APPLIED')::integer,
           count(*) filter (where work_items.status = 'BLOCKED')::integer,
           count(*) filter (where work_items.status in ('FAILED_RETRYABLE', 'FAILED_FINAL'))::integer
    into v_progress_json,
         v_pending_work_count,
         v_processing_work_count,
         v_applied_work_count,
         v_blocked_work_count,
         v_failed_work_count
    from public.pay_payment_correction_work_items as work_items
    where work_items.correction_request_id = v_correction_request_id;
  else
    v_progress_json := COALESCE(v_result_json->'progress', '{}'::jsonb);
  end if;

  select count(*)::integer
  into v_active_payment_item_count
  from public.pay_batch_items as active_items
  join public.pay_batch_candidates as active_candidates
    on active_candidates.id = active_items.pay_batch_candidate_id
  where active_candidates.pay_batch_id = p_pay_batch_id
    and coalesce(active_items.is_voided, false) = false
    and active_items.item_type <> 'DEBT_CREATED';

  if coalesce(v_active_payment_item_count, 0) = 0
     and coalesce(v_pending_work_count, 0) = 0
     and coalesce(v_processing_work_count, 0) = 0
     and coalesce(v_blocked_work_count, 0) = 0
     and coalesce(v_failed_work_count, 0) = 0 then
    update public.pay_batches as batch_to_cancel
    set
      status = 'CANCELLED',
      cancelled_at_utc = coalesce(batch_to_cancel.cancelled_at_utc, v_now),
      cancelled_by_user_id = coalesce(batch_to_cancel.cancelled_by_user_id, p_actor_user_id),
      cancel_reason = coalesce(batch_to_cancel.cancel_reason, v_reason),
      schedule_kind = null,
      scheduled_at_utc = null,
      scheduled_by_user_id = null,
      funding_account_ref = null,
      funds_warning_hours_json = null,
      execution_commit_state = case
        when nullif(btrim(coalesce(batch_to_cancel.execution_commit_state, '')), '') is null then 'NOT_SUBMITTED'
        else batch_to_cancel.execution_commit_state
      end
    where batch_to_cancel.id = p_pay_batch_id;
  end if;

  v_live_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'PAY_BATCH_CANCEL',
    p_change_source := 'pay_batch_cancel',
    p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
      'correction_request_id', CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE v_correction_request_id::text END,
      'legacy_entry_point', 'pay_batch_cancel',
      'progress', COALESCE(v_progress_json, '{}'::jsonb),
      'active_payment_item_count_after', COALESCE(v_active_payment_item_count, 0)
    )),
    p_touch_payment_status := true,
    p_touch_correction_progress := true,
    p_touch_alerts := false,
    p_touch_overview := true
  );

  return COALESCE(v_result_json, '{}'::jsonb) || jsonb_build_object(
    'ok', COALESCE(NULLIF(v_result_json->>'ok', '')::boolean, true),
    'pay_batch_id', p_pay_batch_id::text,
    'legacy_entry_point', 'pay_batch_cancel',
    'correction_request_id', CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE v_correction_request_id::text END,
    'progress', COALESCE(v_progress_json, '{}'::jsonb),
    'active_payment_item_count_after', COALESCE(v_active_payment_item_count, 0),
    'batch_status', (select batch_status_after.status from public.pay_batches as batch_status_after where batch_status_after.id = p_pay_batch_id),
    'db_status_rule', 'CANCELLED may be written only after all payment-scope work items have applied; partial cancellation remains derived payload state only.',
    'submission_evidence', v_evidence_json,
    'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
    'policy_x_checked', true
  );
end;
$$;





create or replace function public.pay_set_paye_net_from_sage(
  p_pay_batch_id uuid,
  p_csv_raw text,
  p_actor_user_id uuid,
  p_source_filename text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lines text[];
  v_line text;
  v_fields text[];

  header_idx int := 0;
  i int := 0;

  works_col int := 0;
  net_col int := 0;

  works text;
  works_norm text;
  net_raw text;
  net_amt numeric;

  dup_check jsonb := '[]'::jsonb;

  v_matched jsonb := '[]'::jsonb;
  v_unknown jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_missing_net jsonb := '[]'::jsonb;

  v_applied_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_ins_loan_res int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_from_sage: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_from_sage: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_from_sage: batch is stale; regenerate draft before importing PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  v_lines := regexp_split_to_array(coalesce(p_csv_raw,''), E'\\r?\\n');

  for i in 1..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works_col := 0;
    net_col := 0;

    for header_idx in 1..coalesce(array_length(v_fields,1),0) loop
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Works Number') then
        works_col := header_idx;
      end if;
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Net Pay') then
        net_col := header_idx;
      end if;
    end loop;

    if works_col > 0 and net_col > 0 then
      header_idx := i;
      exit;
    end if;
  end loop;

  if header_idx = 0 then
    raise exception 'SAGE_IMPORT_INVALID: header row with Works Number and Net Pay not found';
  end if;

  create temp table if not exists _tmp_sage_net (
    works_number text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_net;

  for i in (header_idx+1)..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works := public._pay_csv_trim_field(case when works_col <= array_length(v_fields,1) then v_fields[works_col] else null end);
    if works is null then
      continue;
    end if;

    if lower(works) = 'totals' then
      continue;
    end if;

    works_norm := upper(regexp_replace(btrim(coalesce(works,'')), '\s+', '', 'g'));
    if works_norm = '' then
      continue;
    end if;

    net_raw := public._pay_csv_trim_field(case when net_col <= array_length(v_fields,1) then v_fields[net_col] else null end);

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    net_raw := replace(net_raw, ',', '');
    net_raw := regexp_replace(net_raw, '[^0-9\\.-]', '', 'g');

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    begin
      net_amt := net_raw::numeric;
    exception when others then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay not numeric for Works Number %', works;
    end;

    if net_amt < 0 then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay negative for Works Number %', works;
    end if;

    insert into _tmp_sage_net(works_number, works_norm, net_amount)
    values (works, works_norm, round(net_amt,2));
  end loop;

  select coalesce(jsonb_agg(t.works_norm), '[]'::jsonb)
  into dup_check
  from (
    select sn.works_norm
    from _tmp_sage_net sn
    group by sn.works_norm
    having count(*) > 1
  ) t;

  if jsonb_array_length(dup_check) > 0 then
    raise exception 'SAGE_IMPORT_INVALID: duplicate Works Number(s) %', dup_check::text;
  end if;

  create temp table if not exists _tmp_batch_paye (
    candidate_id uuid,
    pay_batch_candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye;

  insert into _tmp_batch_paye(candidate_id, pay_batch_candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.candidate_id,
    pbc.id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      sn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_sage_net sn
    join _tmp_batch_paye bp
      on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    group by sn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unknown
  from _tmp_sage_net sn
  left join _tmp_batch_paye bp
    on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
    or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
  where bp.candidate_id is null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm,
        'candidate_id', bp.candidate_id::text,
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text
      )
    ),
    '[]'::jsonb
  )
  into v_missing_net
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    );

  create temp table if not exists _tmp_sage_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_match;

  insert into _tmp_sage_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    sn.net_amount
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is not null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    )
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_unknown,'[]'::jsonb)) u
      where (u->>'works_norm') = sn.works_norm
      limit 1
    );

  select count(*)::int
  into v_applied_count
  from _tmp_sage_match sm;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_sage_match sm
  where pni.pay_batch_candidate_id = sm.pay_batch_candidate_id
    and pni.source = 'SAGE_IMPORT';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    sm.pay_batch_candidate_id,
    'SAGE_IMPORT',
    sm.net_amount,
    now(),
    p_source_filename,
    null
  from _tmp_sage_match sm;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text,
        'candidate_id', bp.candidate_id::text,
        'net_amount', sm.net_amount
      )
      order by bp.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_matched
  from _tmp_sage_match sm
  join _tmp_batch_paye bp
    on bp.pay_batch_candidate_id = sm.pay_batch_candidate_id;

  ---------------------------------------------------------------------------
  -- ✅ Recompute NET_DEDUCT items + net_bank_amount (PAYE candidates only)
  -- Gross-side recovery/addition items remain as created at draft time.
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type = 'LOAN_REPAYMENT';

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_advance_reservations par_del
  using _tmp_ded_item_ids di_res
  where par_del.pay_batch_item_id = di_res.id;

  get diagnostics v_deleted_ded_reservations = row_count;

  delete from public.pay_batch_items pbi_del2
  using _tmp_ded_item_ids di2
  where pbi_del2.id = di2.id;

  get diagnostics v_deleted_ded_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_loan_items as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      finance_case_id,
      reservation_id,
      paye_treatment,
      created_at,
      updated_at
    )
    with
    cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        'PAYE'::text as pay_channel,
        null::uuid as umbrella_id,
        pbc.awaiting_net_amount,
        ni.net_amount::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    cand_limits as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        cs.pay_channel,
        cs.umbrella_id,
        greatest(coalesce(cs.paye_net_amount, 0), 0)::numeric(12,2) as earnings_before_payment_advance_ex
      from cand_scope cs
      where cs.awaiting_net_amount = false
    ),
    paid_wtd as (
      select
        pbc2.candidate_id,
        round(sum(
          case
            when pbc2.net_bank_amount is not null then pbc2.net_bank_amount
            when pbc2.gross_preview is not null then pbc2.gross_preview
            else 0
          end
        ), 2)::numeric(12,2) as paid_wtd_before_ex
      from public.pay_batch_candidates pbc2
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
        and pb2.pay_date >= v_week_start
        and pb2.pay_date < (v_week_start + 7)
      group by pbc2.candidate_id
    ),
    cand_with_floor as (
      select
        cl.pay_batch_candidate_id,
        cl.candidate_id,
        cl.pay_channel,
        cl.umbrella_id,
        cl.earnings_before_payment_advance_ex,
        coalesce(pw.paid_wtd_before_ex, 0)::numeric(12,2) as paid_wtd_before_ex,
        coalesce(c.min_take_home_wtd, 0)::numeric(12,2) as floor_ex,
        round(
          greatest(
            least(
              cl.earnings_before_payment_advance_ex,
              (coalesce(pw.paid_wtd_before_ex, 0) + cl.earnings_before_payment_advance_ex) - coalesce(c.min_take_home_wtd, 0)
            ),
            0
          ),
          2
        )::numeric(12,2) as max_payment_advance_repayment_ex
      from cand_limits cl
      join public.candidates c
        on c.id = cl.candidate_id
      left join paid_wtd pw
        on pw.candidate_id = cl.candidate_id
      where cl.earnings_before_payment_advance_ex > 0
    ),
    payment_advances as (
      select
        pa.id as finance_case_id,
        pa.candidate_id,
        pa.outstanding_amount::numeric(12,2) as outstanding_amount,
        pa.weekly_due::numeric(12,2) as weekly_due,
        pa.start_week_start,
        pa.created_at
      from public.pay_advances pa
      where pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
        and pa.payout_status = 'PAID'::public.pay_advance_payout_status_enum
        and pa.status = 'ACTIVE'::public.pay_advance_status_enum
        and pa.outstanding_amount > 0
        and pa.weekly_due is not null
        and pa.weekly_due > 0
        and (pa.start_week_start is null or pa.start_week_start <= v_week_start)
    ),
    payment_advance_repaid_wtd as (
      select
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid as finance_case_id,
        round(coalesce(sum(-pbi2.amount_ex_vat), 0), 2)::numeric(12,2) as repaid_wtd_ex
      from public.pay_batch_items pbi2
      join public.pay_batch_candidates pbc2
        on pbc2.id = pbi2.pay_batch_candidate_id
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pbi2.item_type = 'LOAN_REPAYMENT'
        and pbi2.is_voided = false
        and pbi2.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
        and pbi2.repayment_week_start = v_week_start
        and pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
      group by
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid
    ),
    payment_advance_due as (
      select
        cwf.pay_batch_candidate_id,
        cwf.candidate_id,
        cwf.pay_channel,
        cwf.umbrella_id,
        cwf.max_payment_advance_repayment_ex,
        pa.finance_case_id,
        pa.outstanding_amount,
        pa.weekly_due,
        pa.start_week_start,
        pa.created_at,
        least(pa.weekly_due, pa.outstanding_amount)::numeric(12,2) as due_this_week_ex,
        greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        )::numeric(12,2) as remaining_due_ex
      from cand_with_floor cwf
      join payment_advances pa
        on pa.candidate_id = cwf.candidate_id
      left join payment_advance_repaid_wtd parw
        on parw.candidate_id = cwf.candidate_id
       and parw.finance_case_id = pa.finance_case_id
      where cwf.max_payment_advance_repayment_ex > 0
        and greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        ) > 0
    ),
    alloc_base as (
      select
        pad.candidate_id,
        pad.finance_case_id,
        pad.remaining_due_ex,
        pad.max_payment_advance_repayment_ex,
        sum(pad.remaining_due_ex) over (
          partition by pad.candidate_id
          order by pad.start_week_start nulls first, pad.created_at, pad.finance_case_id
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from payment_advance_due pad
    ),
    alloc as (
      select
        pad2.pay_batch_candidate_id,
        pad2.pay_channel,
        pad2.umbrella_id,
        pad2.finance_case_id,
        least(
          pad2.remaining_due_ex,
          greatest(pad2.max_payment_advance_repayment_ex - coalesce(ab.cum_before_ex, 0), 0)
        )::numeric(12,2) as take_ex
      from payment_advance_due pad2
      join alloc_base ab
        on ab.finance_case_id = pad2.finance_case_id
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      ('advance:' || a.finance_case_id::text) as source_ref,
      (-a.take_ex)::numeric(12,2) as amount_ex_vat,
      (0)::numeric(12,2) as amount_vat,
      (-a.take_ex)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      a.pay_channel as pay_channel,
      a.umbrella_id as umbrella_id,
      false as is_mismatch,
      false as is_voided,
      a.finance_case_id as finance_case_id,
      null::uuid as reservation_id,
      'NET_DEDUCT'::text as paye_treatment,
      now() as created_at,
      now() as updated_at
    from alloc a
    where a.take_ex > 0
    returning
      id,
      pay_batch_candidate_id,
      finance_case_id,
      repayment_week_start,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat
  ),
  ins_loan_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id
    )
    select
      gen_random_uuid() as id,
      ili.finance_case_id,
      p_pay_batch_id,
      ili.pay_batch_candidate_id,
      ili.id as pay_batch_item_id,
      abs(ili.amount_ex_vat)::numeric(12,2) as reserved_amount,
      ili.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id
    from ins_loan_items ili
    returning id, pay_batch_item_id
  ),
  upd_loan_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ilr.id,
      updated_at = now()
    from ins_loan_reservations ilr
    where pbi_upd.id = ilr.pay_batch_item_id
    returning pbi_upd.id
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    ili.id,
    'LOAN_REPAYMENT',
    null,
    'Payment Advance repayment',
    null::numeric,
    null::numeric,
    ili.amount_ex_vat,
    ili.amount_vat,
    ili.amount_inc_vat,
    '{}'::jsonb
  from ins_loan_items ili;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  select count(*)::int
  into v_ins_loan_res
  from public.pay_advance_reservations par_ct
  join public.pay_batch_items pbi_res
    on pbi_res.id = par_ct.pay_batch_item_id
  where par_ct.pay_batch_id = p_pay_batch_id
    and pbi_res.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_res.item_type = 'LOAN_REPAYMENT'
    and pbi_res.is_voided = false
    and par_ct.status = 'RESERVED';

  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'manual_debt_recovery', coalesce((
          select round(sum(-pbi_md.amount_ex_vat), 2)
          from public.pay_batch_items pbi_md
          where pbi_md.pay_batch_candidate_id = pbc_ret.id
            and pbi_md.is_voided = false
            and pbi_md.item_type = 'MANUAL_DEBT_RECOVERY'
        ), 0)::numeric(12,2),
        'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'imported_paye_net', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'gross_side_overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'gross_side_manual_debt_recovery', coalesce((
            select round(sum(-pbi_md2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_md2
            where pbi_md2.pay_batch_candidate_id = pbc_ret.id
              and pbi_md2.is_voided = false
              and pbi_md2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_md2.paye_treatment, '') = 'GROSS_DEDUCT'
          ), 0)::numeric(12,2),
          'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_bank', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'SAGE_IMPORT',
    'applied_count', v_applied_count,
    'matched', v_matched,
    'missing_net', v_missing_net,
    'unknown', v_unknown,
    'ambiguous', v_ambig,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_loan_reservations', v_ins_loan_res,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$$;









create or replace function public.pay_set_paye_net_manual(
  p_pay_batch_id uuid,
  p_entries_json jsonb,
  p_actor_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_entries jsonb := coalesce(p_entries_json, '[]'::jsonb);

  v_dup jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_unmatched jsonb := '[]'::jsonb;

  v_updated_count int := 0;
  v_cleared_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_deleted_manual_debt_breakdowns int := 0;
  v_released_manual_debt_reservations int := 0;
  v_voided_manual_debt_items int := 0;
  v_ins_manual_debt int := 0;
  v_ins_manual_debt_bd int := 0;
  v_ins_finance_reservations int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if jsonb_typeof(v_entries) <> 'array' then
    raise exception 'entries must be an array';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_manual: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_manual: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_manual: batch is stale; regenerate draft before setting PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  create temp table if not exists _tmp_manual_net (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    works_raw text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_net;

  insert into _tmp_manual_net(pay_batch_candidate_id, candidate_id, works_raw, works_norm, net_amount)
  select
    nullif(e->>'pay_batch_candidate_id','')::uuid as pay_batch_candidate_id,
    nullif(e->>'candidate_id','')::uuid as candidate_id,
    nullif(btrim(e->>'tms_ref'), '') as works_raw,
    case
      when nullif(btrim(e->>'tms_ref'), '') is null then null
      else upper(regexp_replace(btrim(e->>'tms_ref'), '\s+', '', 'g'))
    end as works_norm,
    case
      when nullif(btrim(coalesce(e->>'net_amount','')), '') is null then null
      else round((nullif(btrim(coalesce(e->>'net_amount','')), '')::numeric), 2)
    end as net_amount
  from jsonb_array_elements(v_entries) e
  where e is not null and jsonb_typeof(e)='object';

  if exists (
    select 1
    from _tmp_manual_net mn
    where mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and (mn.works_norm is null or mn.works_norm = '')
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: each entry must include pay_batch_candidate_id, candidate_id or tms_ref/NI (Works Number)';
  end if;

  if exists (
    select 1
    from _tmp_manual_net t
    where t.net_amount is not null
      and t.net_amount < 0
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: net_amount must be non-negative';
  end if;

  select coalesce(jsonb_agg(x), '[]'::jsonb)
  into v_dup
  from (
    select to_jsonb(
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    ) as x
    from _tmp_manual_net mn
    group by
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    having count(*) > 1
  ) d;

  if jsonb_array_length(v_dup) > 0 then
    raise exception 'MANUAL_NET_INVALID: duplicate entries %', v_dup::text;
  end if;

  create temp table if not exists _tmp_batch_paye2 (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye2;

  insert into _tmp_batch_paye2(pay_batch_candidate_id, candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.id,
    pbc.candidate_id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c
    on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      mn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_manual_net mn
    join _tmp_batch_paye2 bp
      on mn.pay_batch_candidate_id is null
     and mn.candidate_id is null
     and mn.works_norm is not null
     and mn.works_norm <> ''
     and (
       (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
       or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
     )
    group by mn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  if jsonb_array_length(v_ambig) > 0 then
    raise exception 'MANUAL_NET_INVALID: ambiguous Works Number(s) %', v_ambig::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', case when mn.pay_batch_candidate_id is null then null else mn.pay_batch_candidate_id::text end,
        'candidate_id', case when mn.candidate_id is null then null else mn.candidate_id::text end,
        'works_norm', mn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unmatched
  from _tmp_manual_net mn
  left join _tmp_batch_paye2 bp
    on (mn.pay_batch_candidate_id is not null and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id)
    or (mn.pay_batch_candidate_id is null and mn.candidate_id is not null and bp.candidate_id = mn.candidate_id)
    or (
      mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and mn.works_norm is not null
      and mn.works_norm <> ''
      and (
        (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
        or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
      )
    )
  where bp.pay_batch_candidate_id is null;

  if jsonb_array_length(v_unmatched) > 0 then
    raise exception 'MANUAL_NET_INVALID: entry candidate not found in pay batch PAYE candidates %', v_unmatched::text;
  end if;

  create temp table if not exists _tmp_manual_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_match;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is not null
   and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is not null
   and bp.candidate_id = mn.candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is null
   and mn.works_norm is not null
   and mn.works_norm <> ''
   and (
     (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
     or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
   );

  if exists (
    select 1
    from _tmp_manual_match mm
    group by mm.pay_batch_candidate_id
    having count(*) > 1
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: duplicate resolved candidates in request (internal match collision)';
  end if;

  select count(*)::int
  into v_updated_count
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  select count(*)::int
  into v_cleared_count
  from _tmp_manual_match mm
  where mm.net_amount is null;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_manual_match mm
  where pni.pay_batch_candidate_id = mm.pay_batch_candidate_id
    and pni.source = 'MANUAL_ENTRY';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    mm.pay_batch_candidate_id,
    'MANUAL_ENTRY',
    mm.net_amount,
    now(),
    null,
    null
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  ---------------------------------------------------------------------------
  -- ✅ Recompute deductions + net_bank_amount (PAYE candidates only)
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;


  create temp table if not exists _tmp_recovery_templates (
    item_type text not null,
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    finance_case_id uuid null,
    source_ref text null,
    pay_channel text null,
    umbrella_id uuid null,
    is_mismatch boolean null,
    paye_treatment text null,
    finance_component_id uuid null,
    frozen_component_snapshot_json jsonb null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    frozen_component_classification public.pay_finance_component_classification_enum null,
    frozen_source_basis_json jsonb null,
    frozen_source_pay_method text null,
    frozen_target_pay_method text null,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
    frozen_resolution_payload_json jsonb null,
    frozen_resolution_result_json jsonb null,
    frozen_source_amount numeric(12,2) null,
    frozen_target_amount_ex_vat numeric(12,2) null,
    frozen_target_amount_vat numeric(12,2) null,
    frozen_target_amount_inc_vat numeric(12,2) null,
    payout_instruction_snapshot_json jsonb null,
    template_sort_at timestamptz null,
    sort_order integer not null,
    frozen_case_type text null,
    frozen_payout_status text null,
    frozen_remaining_source_amount numeric(12,2) not null,
    frozen_weekly_due_amount numeric(12,2) not null,
    frozen_next_due_week_start date null,
    minimum_earnings_threshold numeric(12,2) null,
    take_home_floor_override numeric(12,2) null,
    default_take_home_floor numeric(12,2) null
  ) on commit drop;

  truncate table _tmp_recovery_templates;

  insert into _tmp_recovery_templates (
    item_type,
    pay_batch_candidate_id,
    candidate_id,
    finance_case_id,
    source_ref,
    pay_channel,
    umbrella_id,
    is_mismatch,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    template_sort_at,
    sort_order,
    frozen_case_type,
    frozen_payout_status,
    frozen_remaining_source_amount,
    frozen_weekly_due_amount,
    frozen_next_due_week_start,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor
  )
  select distinct on (
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, '')
  )
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    pbc_rt.candidate_id,
    coalesce(
      pbi_rt.finance_case_id,
      case
        when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
        else null::uuid
      end
    ) as finance_case_id,
    pbi_rt.source_ref,
    pbi_rt.pay_channel,
    pbi_rt.umbrella_id,
    pbi_rt.is_mismatch,
    pbi_rt.paye_treatment,
    pbi_rt.finance_component_id,
    pbi_rt.frozen_component_snapshot_json,
    pbi_rt.frozen_component_key_type,
    pbi_rt.frozen_component_key_value,
    pbi_rt.frozen_component_classification,
    pbi_rt.frozen_source_basis_json,
    pbi_rt.frozen_source_pay_method,
    pbi_rt.frozen_target_pay_method,
    pbi_rt.frozen_resolution_mode,
    pbi_rt.frozen_resolution_payload_json,
    pbi_rt.frozen_resolution_result_json,
    round(coalesce(pbi_rt.frozen_source_amount, 0), 2)::numeric(12,2) as frozen_source_amount,
    round(coalesce(pbi_rt.frozen_target_amount_ex_vat, 0), 2)::numeric(12,2) as frozen_target_amount_ex_vat,
    round(coalesce(pbi_rt.frozen_target_amount_vat, 0), 2)::numeric(12,2) as frozen_target_amount_vat,
    round(coalesce(pbi_rt.frozen_target_amount_inc_vat, 0), 2)::numeric(12,2) as frozen_target_amount_inc_vat,
    pbi_rt.payout_instruction_snapshot_json,
    coalesce(pbi_rt.created_at, pbi_rt.updated_at, now()) as template_sort_at,
    case
      when nullif(btrim(coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order')), '') ~ '^-?[0-9]+$'
        then (coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order'))::integer
      else 2147483647
    end as sort_order,
    upper(coalesce(
      nullif(btrim(pbi_rt.frozen_source_basis_json->>'case_type'), ''),
      case pbi_rt.item_type
        when 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT'
        when 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE'
        when 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_ADJUSTMENT'
        else null
      end
    )) as frozen_case_type,
    upper(nullif(btrim(pbi_rt.frozen_source_basis_json->>'payout_status'), '')) as frozen_payout_status,
    round(greatest(
      coalesce(
        case
          when nullif(btrim(pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'outstanding_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'outstanding_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'amount'), '') is not null then abs((pbi_rt.frozen_source_basis_json->>'amount')::numeric)
          when pbi_rt.frozen_source_amount is not null then abs(pbi_rt.frozen_source_amount)
          else 0::numeric
        end,
        0::numeric
      ),
      0::numeric
    ), 2)::numeric(12,2) as frozen_remaining_source_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'weekly_due'), '') is null then 0::numeric(12,2)
      else round(greatest(abs((pbi_rt.frozen_source_basis_json->>'weekly_due')::numeric), 0), 2)::numeric(12,2)
    end as frozen_weekly_due_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'next_due_week_start'), '') is null then null::date
      else (pbi_rt.frozen_source_basis_json->>'next_due_week_start')::date
    end as frozen_next_due_week_start,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold')::numeric, 0), 2)::numeric(12,2)
    end as minimum_earnings_threshold,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'take_home_floor_override'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'take_home_floor_override')::numeric, 0), 2)::numeric(12,2)
    end as take_home_floor_override,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'default_take_home_floor'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'default_take_home_floor')::numeric, 0), 2)::numeric(12,2)
    end as default_take_home_floor
  from public.pay_batch_items pbi_rt
  join public.pay_batch_candidates pbc_rt
    on pbc_rt.id = pbi_rt.pay_batch_candidate_id
  where pbc_rt.pay_batch_id = p_pay_batch_id
    and pbi_rt.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
  order by
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, ''),
    pbi_rt.is_voided desc,
    coalesce(pbi_rt.updated_at, pbi_rt.created_at) desc,
    pbi_rt.id desc;

  create temp table if not exists _tmp_manual_debt_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_manual_debt_item_ids;

  insert into _tmp_manual_debt_item_ids(id)
  select
    pbi_md_del.id
  from public.pay_batch_items pbi_md_del
  where pbi_md_del.pay_batch_candidate_id in (select sc_md_del.pay_batch_candidate_id from _tmp_paye_scope sc_md_del)
    and pbi_md_del.item_type = 'MANUAL_DEBT_RECOVERY'
    and pbi_md_del.is_voided = false;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT')
    and pbi_del.is_voided = false;

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_batch_item_breakdowns pbib_md_del
  using _tmp_manual_debt_item_ids mdi_del
  where pbib_md_del.pay_batch_item_id = mdi_del.id;

  get diagnostics v_deleted_manual_debt_breakdowns = row_count;

  update public.pay_advance_reservations par_del
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_del.pay_batch_item_id in (select di_res.id from _tmp_ded_item_ids di_res)
    and par_del.status = 'RESERVED';

  get diagnostics v_deleted_ded_reservations = row_count;

  update public.pay_advance_reservations par_md
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_md.pay_batch_item_id in (select mdi_res.id from _tmp_manual_debt_item_ids mdi_res)
    and par_md.status = 'RESERVED';

  get diagnostics v_released_manual_debt_reservations = row_count;

  update public.pay_batch_items pbi_d_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_d_void.id in (select di_void.id from _tmp_ded_item_ids di_void)
    and pbi_d_void.is_voided = false;

  v_deleted_ded_items := 0;

  update public.pay_batch_items pbi_md_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_md_void.id in (select mdi_void.id from _tmp_manual_debt_item_ids mdi_void)
    and pbi_md_void.is_voided = false;

  get diagnostics v_voided_manual_debt_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_overpay as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'OVERPAYMENT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    alloc_base as (
      select
        cs.pay_batch_candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        cs.paye_net_amount as available_pool_ex,
        sum(ct.frozen_remaining_source_amount) over (
          partition by cs.pay_batch_candidate_id
          order by ct.sort_order, ct.template_sort_at, ct.finance_case_id, ct.finance_component_id, coalesce(ct.source_ref, '')
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'OVERPAYMENT')) = 'OVERPAYMENT'
    ),
    alloc as (
      select
        ab.*,
        round(
          least(
            ab.frozen_remaining_source_amount,
            greatest(ab.available_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
          ),
          2
        )::numeric(12,2) as take_ex
      from alloc_base ab
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'OVERPAYMENT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(a.source_ref, 'advance:' || a.finance_case_id::text) as source_ref,
      round(-a.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(a.pay_channel, 'PAYE') as pay_channel,
      a.umbrella_id,
      coalesce(a.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      a.finance_case_id,
      null::uuid as reservation_id,
      coalesce(a.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      a.finance_component_id,
      a.frozen_component_snapshot_json,
      a.frozen_component_key_type,
      a.frozen_component_key_value,
      a.frozen_component_classification,
      a.frozen_source_basis_json,
      a.frozen_source_pay_method,
      coalesce(a.frozen_target_pay_method, coalesce(a.pay_channel, 'PAYE')) as frozen_target_pay_method,
      a.frozen_resolution_mode,
      a.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(a.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-a.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-a.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(a.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      a.payout_instruction_snapshot_json
    from alloc a
    where a.take_ex > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    io.id,
    'OVERPAYMENT_RECOVERY',
    null,
    'Overpayment recovery',
    null::numeric,
    null::numeric,
    io.amount_ex_vat,
    io.amount_vat,
    io.amount_inc_vat,
    '{}'::jsonb
  from ins_overpay io;

  get diagnostics v_ins_overpay_bd = row_count;

  select count(*)::int
  into v_ins_overpay
  from public.pay_batch_items pbi_ct
  where pbi_ct.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct.item_type = 'OVERPAYMENT_RECOVERY'
    and pbi_ct.is_voided = false
    and pbi_ct.repayment_week_start = v_week_start;

  with ins_loan as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    overpay_current as (
      select
        pbi.pay_batch_candidate_id,
        round(sum(-pbi.amount_ex_vat), 2)::numeric(12,2) as overpayment_recovery_taken_ex
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
        and pbi.repayment_week_start = v_week_start
      group by pbi.pay_batch_candidate_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'LOAN_REPAYMENT'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    loan_seed as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_take_home_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      left join overpay_current oc
        on oc.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'PAYMENT_ADVANCE')) = 'PAYMENT_ADVANCE'
        and upper(coalesce(ct.frozen_payout_status, 'PAID')) = 'PAID'
        and (ct.frozen_next_due_week_start is null or ct.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2) > 0
    ),
    loan_inputs as (
      select
        ls.pay_batch_candidate_id,
        ls.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ls.sort_order,
              'finance_case_id', ls.finance_case_id::text,
              'case_type', 'PAYMENT_ADVANCE',
              'payout_status', 'PAID',
              'nominal_due_amount', ls.nominal_due_amount,
              'minimum_earnings_threshold', ls.minimum_earnings_threshold,
              'take_home_floor_override', ls.take_home_floor_override
            )
            order by ls.sort_order, ls.template_sort_at, ls.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ls.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ls.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex
      from loan_seed ls
      group by ls.pay_batch_candidate_id, ls.candidate_id
    ),
    loan_alloc as (
      select
        li.pay_batch_candidate_id,
        li.candidate_id,
        lra.finance_case_id,
        round(coalesce(lra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from loan_inputs li
      cross join lateral public._pay_finance_protected_recovery_allocate(
        li.recovery_rows_json,
        li.run_earnings_headroom_ex,
        li.run_take_home_before_ex,
        null::numeric
      ) lra
    )
    select
      gen_random_uuid() as id,
      ct.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(ct.source_ref, 'advance:' || la.finance_case_id::text) as source_ref,
      round(-la.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(ct.pay_channel, 'PAYE') as pay_channel,
      ct.umbrella_id,
      coalesce(ct.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      la.finance_case_id,
      null::uuid as reservation_id,
      coalesce(ct.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      ct.finance_component_id,
      ct.frozen_component_snapshot_json,
      ct.frozen_component_key_type,
      ct.frozen_component_key_value,
      ct.frozen_component_classification,
      ct.frozen_source_basis_json,
      ct.frozen_source_pay_method,
      coalesce(ct.frozen_target_pay_method, coalesce(ct.pay_channel, 'PAYE')) as frozen_target_pay_method,
      ct.frozen_resolution_mode,
      ct.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(ct.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-la.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-la.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(la.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      ct.payout_instruction_snapshot_json
    from loan_alloc la
    join case_templates ct
      on ct.pay_batch_candidate_id = la.pay_batch_candidate_id
     and ct.finance_case_id = la.finance_case_id
    where round(coalesce(la.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    il.id,
    'LOAN_REPAYMENT',
    null,
    'Loan repayment',
    null::numeric,
    null::numeric,
    il.amount_ex_vat,
    il.amount_vat,
    il.amount_inc_vat,
    '{}'::jsonb
  from ins_loan il;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  with manual_debt_scope as (
    select
      pbc_md.id as pay_batch_candidate_id,
      pbc_md.candidate_id,
      round(greatest(coalesce(pbc_md.gross_preview, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
      round(
        greatest(
          coalesce(pni_md.net_amount, 0)
          - coalesce((
              select round(sum(-pbi_ov.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ov
              where pbi_ov.pay_batch_candidate_id = pbc_md.id
                and pbi_ov.is_voided = false
                and pbi_ov.item_type = 'OVERPAYMENT_RECOVERY'
                and pbi_ov.repayment_week_start = v_week_start
            ), 0)
          - coalesce((
              select round(sum(-pbi_ln.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ln
              where pbi_ln.pay_batch_candidate_id = pbc_md.id
                and pbi_ln.is_voided = false
                and pbi_ln.item_type = 'LOAN_REPAYMENT'
                and pbi_ln.repayment_week_start = v_week_start
            ), 0),
          0
        ),
        2
      )::numeric(12,2) as run_take_home_before_ex,
      round(greatest(coalesce((
        select max(rt.default_take_home_floor)
        from _tmp_recovery_templates rt
        where rt.pay_batch_candidate_id = pbc_md.id
          and rt.item_type = 'MANUAL_DEBT_RECOVERY'
      ), 0), 0), 2)::numeric(12,2) as default_take_home_floor
    from public.pay_batch_candidates pbc_md
    join _tmp_paye_scope sc_md
      on sc_md.pay_batch_candidate_id = pbc_md.id
    left join lateral (
      select pni_md_inner.net_amount
      from public.pay_batch_paye_net_inputs pni_md_inner
      where pni_md_inner.pay_batch_candidate_id = pbc_md.id
      order by pni_md_inner.imported_at_utc desc
      limit 1
    ) pni_md on true
    where pbc_md.awaiting_net_amount = false
  ),
  manual_debt_case_templates as (
    select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
      rt.*
    from _tmp_recovery_templates rt
    where rt.item_type = 'MANUAL_DEBT_RECOVERY'
      and rt.finance_case_id is not null
    order by
      rt.pay_batch_candidate_id,
      rt.finance_case_id,
      coalesce(rt.finance_component_id::text, ''),
      coalesce(rt.source_ref, ''),
      rt.sort_order,
      rt.template_sort_at,
      rt.finance_component_id nulls last,
      rt.source_ref nulls last
  ),
  manual_debt_template_values as (
    select
      mds.pay_batch_candidate_id,
      mds.candidate_id,
      mdt.finance_case_id,
      mdt.template_sort_at,
      mds.run_earnings_headroom_ex,
      mds.run_take_home_before_ex,
      nullif(mds.default_take_home_floor, 0)::numeric(12,2) as default_take_home_floor,
      upper(coalesce(mdt.frozen_case_type, 'MANUAL_DEBT_ADJUSTMENT')) as frozen_case_type,
      mdt.frozen_next_due_week_start,
      mdt.minimum_earnings_threshold,
      mdt.take_home_floor_override,
      mdt.frozen_weekly_due_amount,
      mdt.frozen_remaining_source_amount,
      mdt.sort_order,
      sched_md.scheduled_due_amount,
      mdt.source_ref,
      mdt.pay_channel,
      mdt.umbrella_id,
      mdt.is_mismatch,
      mdt.paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      mdt.frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      mdt.frozen_resolution_result_json,
      mdt.frozen_source_amount,
      mdt.frozen_target_amount_ex_vat,
      mdt.frozen_target_amount_vat,
      mdt.frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_scope mds
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mds.pay_batch_candidate_id
    left join lateral (
      select
        round(greatest(abs((sched_item.value->>'amount')::numeric), 0), 2)::numeric(12,2) as scheduled_due_amount
      from jsonb_array_elements(
        case
          when jsonb_typeof(coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)) = 'array'
            then coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)
          else '[]'::jsonb
        end
      ) as sched_item(value)
      where nullif(btrim(sched_item.value->>'week_start'), '') is not null
        and (sched_item.value->>'week_start')::date = v_week_start
      limit 1
    ) sched_md on true
  ),
  manual_debt_seed as (
    select
      mdtv.pay_batch_candidate_id,
      mdtv.candidate_id,
      mdtv.finance_case_id,
      mdtv.template_sort_at,
      mdtv.sort_order,
      round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      )::numeric(12,2) as nominal_due_amount,
      mdtv.minimum_earnings_threshold,
      mdtv.take_home_floor_override,
      mdtv.run_earnings_headroom_ex,
      mdtv.run_take_home_before_ex,
      mdtv.default_take_home_floor
    from manual_debt_template_values mdtv
    where mdtv.frozen_case_type = 'MANUAL_DEBT_ADJUSTMENT'
      and mdtv.frozen_remaining_source_amount > 0
      and (mdtv.frozen_next_due_week_start is null or mdtv.frozen_next_due_week_start <= v_week_start)
      and round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      ) > 0
  ),
  manual_debt_inputs as (
    select
      mds.candidate_id,
      mds.pay_batch_candidate_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'sort_order', mds.sort_order,
            'finance_case_id', mds.finance_case_id::text,
            'case_type', 'MANUAL_DEBT_ADJUSTMENT',
            'payout_status', null,
            'nominal_due_amount', mds.nominal_due_amount,
            'minimum_earnings_threshold', mds.minimum_earnings_threshold,
            'take_home_floor_override', mds.take_home_floor_override
          )
          order by mds.sort_order, mds.template_sort_at, mds.finance_case_id
        ),
        '[]'::jsonb
      ) as recovery_rows_json,
      max(mds.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
      max(mds.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex,
      nullif(max(mds.default_take_home_floor), 0)::numeric(12,2) as default_take_home_floor
    from manual_debt_seed mds
    group by mds.candidate_id, mds.pay_batch_candidate_id
  ),
  manual_debt_alloc as (
    select
      mdi.pay_batch_candidate_id,
      mdi.candidate_id,
      mdra.finance_case_id,
      round(coalesce(mdra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
    from manual_debt_inputs mdi
    cross join lateral public._pay_finance_protected_recovery_allocate(
      mdi.recovery_rows_json,
      mdi.run_earnings_headroom_ex,
      mdi.run_take_home_before_ex,
      mdi.default_take_home_floor
    ) mdra
  ),
  ins_manual_debt as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    select
      gen_random_uuid() as id,
      mdt.pay_batch_candidate_id,
      'MANUAL_DEBT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(mdt.source_ref, 'advance:' || mda.finance_case_id::text) as source_ref,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(mdt.pay_channel, 'PAYE') as pay_channel,
      mdt.umbrella_id,
      coalesce(mdt.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      mda.finance_case_id,
      null::uuid as reservation_id,
      coalesce(mdt.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      coalesce(mdt.frozen_target_pay_method, coalesce(mdt.pay_channel, 'PAYE')) as frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(mdt.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-mda.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-mda.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(mda.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_alloc mda
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mda.pay_batch_candidate_id
     and mdt.finance_case_id = mda.finance_case_id
    where round(coalesce(mda.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    imd.id,
    'MANUAL_DEBT_RECOVERY',
    null,
    'Manual debt recovery',
    null::numeric,
    null::numeric,
    imd.amount_ex_vat,
    imd.amount_vat,
    imd.amount_inc_vat,
    '{}'::jsonb
  from ins_manual_debt imd;

  get diagnostics v_ins_manual_debt_bd = row_count;

  select count(*)::int
  into v_ins_manual_debt
  from public.pay_batch_items pbi_ct3
  where pbi_ct3.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct3.item_type = 'MANUAL_DEBT_RECOVERY'
    and pbi_ct3.is_voided = false
    and pbi_ct3.repayment_week_start = v_week_start;

  with ins_finance_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    select
      gen_random_uuid() as id,
      pbi_fin.finance_case_id,
      p_pay_batch_id as pay_batch_id,
      pbi_fin.pay_batch_candidate_id,
      pbi_fin.id as pay_batch_item_id,
      round(abs(coalesce(pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_amount,
      pbi_fin.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id,
      pbi_fin.finance_component_id,
      pbi_fin.frozen_component_snapshot_json,
      pbi_fin.frozen_component_key_type,
      pbi_fin.frozen_component_key_value,
      pbi_fin.frozen_component_classification,
      pbi_fin.frozen_source_basis_json,
      pbi_fin.frozen_source_pay_method,
      pbi_fin.frozen_target_pay_method,
      pbi_fin.frozen_resolution_mode,
      pbi_fin.frozen_resolution_payload_json,
      pbi_fin.frozen_resolution_result_json,
      round(abs(coalesce(pbi_fin.frozen_source_amount, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_source_amount,
      round(abs(coalesce(pbi_fin.frozen_target_amount_ex_vat, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as frozen_rounded_target_amount
    from public.pay_batch_items pbi_fin
    where pbi_fin.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
      and pbi_fin.is_voided = false
      and pbi_fin.finance_case_id is not null
      and pbi_fin.reservation_id is null
      and pbi_fin.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
    returning id, pay_batch_item_id
  ),
  upd_finance_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ifr.id,
      updated_at = now()
    from ins_finance_reservations ifr
    where pbi_upd.id = ifr.pay_batch_item_id
    returning pbi_upd.id
  )
  select count(*)::int
  into v_ins_finance_reservations
  from upd_finance_items;
  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery_taken', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'loan_repayment_taken', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'gross_positive', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_payable', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'MANUAL_ENTRY',
    'updated_count', v_updated_count,
    'cleared_count', v_cleared_count,
    'unmatched', '[]'::jsonb,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_manual_debt_breakdowns', v_deleted_manual_debt_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'released_manual_debt_reservations', v_released_manual_debt_reservations,
      'voided_manual_debt_items', v_voided_manual_debt_items,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_manual_debt_items', v_ins_manual_debt,
      'inserted_manual_debt_breakdowns', v_ins_manual_debt_bd,
      'inserted_finance_reservations', v_ins_finance_reservations,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$$;




-- =========================================================
-- pay_snooze_upsert
-- Creates a new active snooze, or updates the snooze_until_date/note for an existing ACTIVE snooze
-- matching the identity key (candidate_id + timesheet_id + segment_id + source_ref + snooze_kind).
--
-- Identity rules:
--   - Segment snooze: timesheet_id + segment_id required
--   - Non-segment snooze: source_ref required (timesheet_id optional but recommended)
--
-- snooze_until_date:
--   - NULL => snooze forever
--   - date => snoozed until that date (inclusive)
-- =========================================================

CREATE OR REPLACE FUNCTION public.pay_snooze_upsert(
  p_candidate_id uuid,
  p_timesheet_id uuid,
  p_segment_id text,
  p_source_ref text,
  p_snooze_kind text DEFAULT 'DO_NOT_PAY'::text,
  p_snooze_until_date date DEFAULT NULL::date,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind text := UPPER(BTRIM(COALESCE(p_snooze_kind, 'DO_NOT_PAY')));
BEGIN
  IF v_kind = 'BLOCKED' THEN
    v_kind := 'BLOCKED_TIMESHEET';
  ELSIF v_kind = 'LOAN_REPAYMENT' THEN
    v_kind := 'PAYMENT_ADVANCE_REPAYMENT';
  END IF;

  IF v_kind IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET', 'TIMESHEET_PAYMENT') THEN
    RAISE EXCEPTION 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED',
              'message', 'This Banking Pay snooze must be validated and confirmed through the current Snooze workflow before it can be saved.',
              'required_rpc', 'pay_snooze_upsert_v2',
              'refresh_required', false
            )::text;
  END IF;

  IF v_kind IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND p_snooze_until_date IS NOT NULL THEN
    RAISE EXCEPTION 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED',
              'message', 'This dated finance snooze must be validated and confirmed through the current Snooze workflow before it can be saved.',
              'required_rpc', 'pay_snooze_upsert_v2',
              'refresh_required', false
            )::text;
  END IF;

  IF v_kind NOT IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY') THEN
    RAISE EXCEPTION 'SNOOZE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_KIND_INVALID',
              'snooze_kind', p_snooze_kind
            )::text;
  END IF;

  RETURN public.pay_snooze_upsert_v2(
    p_candidate_id,
    p_timesheet_id,
    p_segment_id,
    p_source_ref,
    v_kind,
    p_snooze_until_date,
    p_actor_user_id,
    p_note,
    NULL::text,
    NULL::text,
    NULL::text
  );
END;
$function$;

ALTER FUNCTION public.pay_snooze_upsert(uuid, uuid, text, text, text, date, uuid, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_snooze_upsert(uuid, uuid, text, text, text, date, uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pay_snooze_upsert(uuid, uuid, text, text, text, date, uuid, text) FROM anon;
REVOKE ALL ON FUNCTION public.pay_snooze_upsert(uuid, uuid, text, text, text, date, uuid, text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.pay_snooze_upsert(uuid, uuid, text, text, text, date, uuid, text) TO service_role;

CREATE OR REPLACE FUNCTION public.pay_snooze_clear(p_snooze_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row record;
  v_candidate_id_hint uuid := NULL::uuid;
  v_before jsonb := NULL;
  v_after jsonb := NULL;
  v_finance_case_id uuid := NULL;

  v_finance_case_record public.pay_advances%rowtype;
  v_effective_from_date date := NULL;
  v_requested_week_start_date date := NULL;
  v_current_operating_week_start_date date := NULL;
  v_target_week_start date := NULL;
  v_next_due_week_start_before_restore_date date := NULL;
  v_next_due_week_start_after_restore_date date := NULL;

  v_schedule_restore_result jsonb := NULL;
  v_schedule_before_restore_json jsonb := NULL;
  v_next_due_week_start_before_restore text := NULL;
  v_requested_week_start text := NULL;
  v_current_operating_week_start text := NULL;
  v_schedule_after_restore_json jsonb := NULL;
  v_next_due_week_start_after_restore text := NULL;
  v_installment_count integer := NULL;
  v_rate_resolution_clear_result jsonb := '{}'::jsonb;
BEGIN
  IF p_snooze_id IS NULL THEN
    RAISE EXCEPTION 'snooze_id is required';
  END IF;

  SELECT s.candidate_id
  INTO v_candidate_id_hint
  FROM public.pay_item_snoozes AS s
  WHERE s.id = p_snooze_id;

  IF v_candidate_id_hint IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_NOT_FOUND';
  END IF;

  -- Use the same candidate-then-row lock order as Snooze upsert, natural
  -- expiry and the final Create Draft guard.  Reading the immutable candidate
  -- identity first avoids a row-lock/advisory-lock inversion with a concurrent
  -- exact expense upsert or clear.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtext('public.banking_pay_candidate_snooze_guard'),
    pg_catalog.hashtext(v_candidate_id_hint::text)
  );

  SELECT
    s.id,
    s.candidate_id,
    s.timesheet_id,
    s.segment_id,
    s.source_ref,
    s.snooze_kind,
    s.snooze_until_date,
    s.note,
    s.created_at_utc,
    s.cleared_at_utc
  INTO v_row
  FROM public.pay_item_snoozes AS s
  WHERE s.id = p_snooze_id
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_row.candidate_id IS DISTINCT FROM v_candidate_id_hint THEN
    RAISE EXCEPTION 'SNOOZE_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_AUTHORITY_CHANGED',
              'snooze_id', p_snooze_id::text
            )::text;
  END IF;

  v_before := jsonb_build_object(
    'id', v_row.id::text,
    'candidate_id', v_row.candidate_id::text,
    'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
    'segment_id', v_row.segment_id,
    'source_ref', v_row.source_ref,
    'snooze_kind', v_row.snooze_kind,
    'snooze_until_date', CASE WHEN v_row.snooze_until_date IS NULL THEN NULL ELSE v_row.snooze_until_date::text END,
    'note', v_row.note,
    'cleared_at_utc', v_row.cleared_at_utc
  );

  IF v_row.cleared_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'london_current_date', (clock_timestamp() AT TIME ZONE 'Europe/London')::date::text,
      'action', 'NOOP_ALREADY_CLEARED',
      'id', v_row.id::text
    );
  END IF;

  IF v_row.source_ref IS NOT NULL
     AND v_row.source_ref LIKE 'advance:%'
     AND split_part(v_row.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  THEN
    v_finance_case_id := split_part(v_row.source_ref, ':', 2)::uuid;
  END IF;

  UPDATE public.pay_item_snoozes s
  SET
    cleared_at_utc = now(),
    cleared_by_user_id = p_actor_user_id,
    updated_at_utc = now(),
    updated_by_user_id = p_actor_user_id
  WHERE s.id = p_snooze_id;

  IF to_regprocedure('public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(uuid,uuid)') IS NOT NULL THEN
    v_rate_resolution_clear_result := public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(
      p_snooze_id,
      p_actor_user_id
    );
  ELSE
    RAISE EXCEPTION 'CROSS_PAY_WEEK_UNSNOOZE_HELPER_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CROSS_PAY_WEEK_UNSNOOZE_HELPER_UNAVAILABLE',
              'message', 'The snooze was not cleared because rate-resolution safety could not be verified.'
            )::text;
  END IF;

  IF v_finance_case_id IS NOT NULL
     AND upper(coalesce(v_row.snooze_kind, '')) IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND v_row.snooze_until_date IS NOT NULL
  THEN
    v_effective_from_date := (now() AT TIME ZONE 'Europe/London')::date;

    SELECT pa.*
    INTO v_finance_case_record
    FROM public.pay_advances AS pa
    WHERE pa.id = v_finance_case_id
    LIMIT 1
    FOR UPDATE;

    IF v_finance_case_record.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
        'code', 'FINANCE_CASE_NOT_FOUND',
        'message', '_pay_repayment_schedule_restore_after_snooze_clear: finance case not found',
        'finance_case_id', v_finance_case_id::text
      )::text;
    END IF;

    IF v_finance_case_record.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      v_schedule_before_restore_json := coalesce(v_finance_case_record.schedule_json, '[]'::jsonb);
      v_next_due_week_start_before_restore_date := v_finance_case_record.next_due_week_start;
      v_requested_week_start_date := public._pay_week_start_monday(v_effective_from_date);
      v_current_operating_week_start_date := public._pay_week_start_monday((now() AT TIME ZONE 'Europe/London')::date);

      IF v_requested_week_start_date < v_current_operating_week_start_date THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
          'code', 'EFFECTIVE_FROM_DATE_BEFORE_NOW',
          'message', '_pay_repayment_schedule_restore_after_snooze_clear: effective_from_date cannot restore the repayment schedule earlier than the current operating week',
          'finance_case_id', v_finance_case_id::text,
          'requested_week_start', v_requested_week_start_date::text,
          'current_operating_week_start', v_current_operating_week_start_date::text
        )::text;
      END IF;

      v_target_week_start := v_requested_week_start_date;

      WITH schedule_rows AS (
        SELECT
          row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
          round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
        FROM jsonb_array_elements(v_schedule_before_restore_json) WITH ORDINALITY AS elem(value, ordinality)
        WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
      )
      SELECT
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
              'amount', sr.amount_value
            )
            ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
          ),
          '[]'::jsonb
        ),
        count(*)::integer
      INTO v_schedule_after_restore_json, v_installment_count
      FROM schedule_rows AS sr;

      v_next_due_week_start_after_restore_date := CASE
        WHEN v_installment_count > 0 THEN v_target_week_start
        ELSE NULL
      END;

      UPDATE public.pay_advances AS pa
      SET schedule_json = v_schedule_after_restore_json,
          next_due_week_start = v_next_due_week_start_after_restore_date,
          updated_at = now()
      WHERE pa.id = v_finance_case_id;

      v_schedule_restore_result := jsonb_build_object(
        'ok', true,
        'finance_case_id', v_finance_case_id::text,
        'schedule_before_restore_json', v_schedule_before_restore_json,
        'next_due_week_start_before_restore', CASE WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_before_restore_date::text END,
        'requested_week_start', CASE WHEN v_requested_week_start_date IS NULL THEN NULL ELSE v_requested_week_start_date::text END,
        'current_operating_week_start', CASE WHEN v_current_operating_week_start_date IS NULL THEN NULL ELSE v_current_operating_week_start_date::text END,
        'schedule_after_restore_json', v_schedule_after_restore_json,
        'next_due_week_start_after_restore', CASE WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_after_restore_date::text END,
        'installment_count', v_installment_count
      );
    ELSE
      v_schedule_restore_result := public._pay_repayment_schedule_restore_after_snooze_clear(
        v_finance_case_id,
        v_effective_from_date
      );
    END IF;

    v_schedule_before_restore_json := v_schedule_restore_result -> 'schedule_before_restore_json';
    v_next_due_week_start_before_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_before_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_before_restore')::date
    END;
    v_next_due_week_start_before_restore := CASE
      WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_before_restore_date::text
    END;
    v_requested_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'requested_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'requested_week_start')::date
    END;
    v_requested_week_start := CASE
      WHEN v_requested_week_start_date IS NULL THEN NULL
      ELSE v_requested_week_start_date::text
    END;
    v_current_operating_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'current_operating_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'current_operating_week_start')::date
    END;
    v_current_operating_week_start := CASE
      WHEN v_current_operating_week_start_date IS NULL THEN NULL
      ELSE v_current_operating_week_start_date::text
    END;
    v_schedule_after_restore_json := v_schedule_restore_result -> 'schedule_after_restore_json';
    v_next_due_week_start_after_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_after_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_after_restore')::date
    END;
    v_next_due_week_start_after_restore := CASE
      WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_after_restore_date::text
    END;
    v_installment_count := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'installment_count', '')), '') ~ '^-?[0-9]+$'
      THEN (v_schedule_restore_result ->> 'installment_count')::integer
      ELSE NULL
    END;
  END IF;

  SELECT
    jsonb_build_object(
      'id', s.id::text,
      'candidate_id', s.candidate_id::text,
      'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
      'segment_id', s.segment_id,
      'source_ref', s.source_ref,
      'snooze_kind', s.snooze_kind,
      'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
      'note', s.note,
      'cleared_at_utc', s.cleared_at_utc
    )
    ||
    CASE
      WHEN v_schedule_restore_result IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('schedule_restore_result', v_schedule_restore_result)
    END
  INTO v_after
  FROM public.pay_item_snoozes s
  WHERE s.id = p_snooze_id;

  IF v_finance_case_id IS NOT NULL THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_finance_case_id,
      'SNOOZE_CLEARED',
      now(),
      p_actor_user_id,
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      v_row.note
    );

    PERFORM public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSIF v_row.timesheet_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'timesheets',
      v_row.timesheet_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSE
    PERFORM public._audit_insert(
      'pay_item_snoozes',
      v_row.id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  END IF;

  RETURN
    jsonb_build_object(
      'ok', true,
      'london_current_date', (clock_timestamp() AT TIME ZONE 'Europe/London')::date::text,
      'rate_resolution_review_required_after_cross_pay_week_unsnooze',
        COALESCE((v_rate_resolution_clear_result->>'review_required')::boolean, false),
      'rate_resolution_clear_result', COALESCE(v_rate_resolution_clear_result, '{}'::jsonb),
      'action', 'CLEARED',
      'id', v_row.id::text,
      'candidate_id', v_row.candidate_id::text,
      'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
      'segment_id', v_row.segment_id,
      'source_ref', v_row.source_ref,
      'finance_case_id', CASE WHEN v_finance_case_id IS NULL THEN NULL ELSE v_finance_case_id::text END,
      'snooze_kind', v_row.snooze_kind,
      'preview_visibility_hint', 'RELOAD_PREVIEW'
    )
    ||
    jsonb_build_object(
      'schedule_before_restore_json', v_schedule_before_restore_json,
      'next_due_week_start_before_restore', v_next_due_week_start_before_restore,
      'requested_week_start', v_requested_week_start,
      'current_operating_week_start', v_current_operating_week_start,
      'schedule_after_restore_json', v_schedule_after_restore_json,
      'next_due_week_start_after_restore', v_next_due_week_start_after_restore,
      'installment_count', v_installment_count
    );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_expired_snooze_refreshes_v1(
  p_session_id uuid DEFAULT NULL::uuid,
  p_session_limit integer DEFAULT 25,
  p_candidate_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_date_context jsonb := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk date;
  v_current_official_pay_date date;
  v_context_fingerprint text;
  v_timezone_id text;
  v_session_limit integer := LEAST(GREATEST(COALESCE(p_session_limit, 25), 1), 50);
  v_work_limit integer := LEAST(GREATEST(COALESCE(p_candidate_limit, 100), 1), 250);
  v_remaining_work_limit integer;
  v_session record;
  v_due record;
  v_last_checked_date date;
  v_cursor_candidate_id uuid;
  v_cursor_snooze_id uuid;
  v_last_candidate_id uuid;
  v_last_snooze_id uuid;
  v_due_count integer := 0;
  v_session_processed_count integer := 0;
  v_processed_session_count integer := 0;
  v_processed_snooze_count integer := 0;
  v_enqueued_count integer := 0;
  v_reused_job_count integer := 0;
  v_transition_changed_count integer := 0;
  v_more_due boolean := false;
  v_transition_result jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_job_id_text text;
  v_job_id uuid;
  v_job_created boolean := false;
  v_scope_job_key text;
  v_results jsonb := '[]'::jsonb;
BEGIN
  v_today_uk := (v_date_context->>'business_date')::date;
  v_current_official_pay_date := (v_date_context->>'current_official_pay_date')::date;
  v_context_fingerprint := v_date_context->>'configuration_fingerprint';
  v_timezone_id := NULLIF(BTRIM(COALESCE(v_date_context->>'timezone_id', '')), '');
  v_remaining_work_limit := v_work_limit;

  DROP TABLE IF EXISTS pg_temp._bpay_expiry_candidate_jobs;
  CREATE TEMP TABLE _bpay_expiry_candidate_jobs (
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    scope_job_key text NOT NULL,
    job_id uuid NOT NULL,
    PRIMARY KEY (session_id, candidate_id, scope_job_key)
  ) ON COMMIT DROP;

  FOR v_session IN
    SELECT session_row.id,
           session_row.actor_user_id,
           session_row.progress_json,
           session_row.created_at_utc
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.status = 'OPEN'
      AND session_row.discarded_at_utc IS NULL
      AND session_row.replacement_session_id IS NULL
      AND (p_session_id IS NULL OR session_row.id = p_session_id)
      AND (
        p_session_id IS NOT NULL
        OR COALESCE(session_row.progress_json->>'snooze_expiry_last_checked_london_date', '') <> v_today_uk::text
        OR NULLIF(BTRIM(COALESCE(session_row.progress_json->>'snooze_expiry_candidate_cursor', '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(session_row.progress_json->>'snooze_expiry_snooze_cursor', '')), '') IS NOT NULL
      )
    ORDER BY session_row.updated_at_utc, session_row.id
    LIMIT v_session_limit
  LOOP
    IF v_remaining_work_limit <= 0 THEN
      v_more_due := true;
      EXIT;
    END IF;

    v_processed_session_count := v_processed_session_count + 1;
    v_session_processed_count := 0;
    v_last_candidate_id := NULL::uuid;
    v_last_snooze_id := NULL::uuid;

    BEGIN
      v_last_checked_date := NULLIF(BTRIM(COALESCE(
        v_session.progress_json->>'snooze_expiry_last_checked_london_date',
        ''
      )), '')::date;
    EXCEPTION WHEN OTHERS THEN
      v_last_checked_date := NULL::date;
    END;

    IF v_last_checked_date IS NULL THEN
      v_last_checked_date := LEAST(
        v_today_uk,
        COALESCE(
          CASE
            WHEN v_timezone_id IS NULL THEN NULL::date
            ELSE (v_session.created_at_utc AT TIME ZONE v_timezone_id)::date
          END,
          v_today_uk
        )
      );
    END IF;

    BEGIN
      v_cursor_candidate_id := NULLIF(BTRIM(COALESCE(
        v_session.progress_json->>'snooze_expiry_candidate_cursor',
        ''
      )), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_candidate_id := NULL::uuid;
    END;

    BEGIN
      v_cursor_snooze_id := NULLIF(BTRIM(COALESCE(
        v_session.progress_json->>'snooze_expiry_snooze_cursor',
        ''
      )), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_snooze_id := NULL::uuid;
    END;

    SELECT COUNT(*)::integer
    INTO v_due_count
    FROM (
      SELECT 1
      FROM public.banking_pay_workbench_session_scope AS scope_row
      JOIN public.pay_item_snoozes AS snooze_row
        ON snooze_row.candidate_id = scope_row.candidate_id
       AND snooze_row.cleared_at_utc IS NULL
       AND snooze_row.cancelled_at_utc IS NULL
       AND snooze_row.snooze_until_date IS NOT NULL
       AND snooze_row.snooze_until_date >= v_last_checked_date
       AND snooze_row.snooze_until_date < v_today_uk
      WHERE scope_row.session_id = v_session.id
        AND (
          v_cursor_candidate_id IS NULL
          OR scope_row.candidate_id > v_cursor_candidate_id
          OR (
            scope_row.candidate_id = v_cursor_candidate_id
            AND v_cursor_snooze_id IS NOT NULL
            AND snooze_row.id > v_cursor_snooze_id
          )
        )
      ORDER BY scope_row.candidate_id, snooze_row.id
      LIMIT v_remaining_work_limit + 1
    ) AS bounded_due_probe;

    FOR v_due IN
      SELECT scope_row.candidate_id,
             snooze_row.id AS snooze_id,
             snooze_row.timesheet_id,
             snooze_row.snooze_until_date
      FROM public.banking_pay_workbench_session_scope AS scope_row
      JOIN public.pay_item_snoozes AS snooze_row
        ON snooze_row.candidate_id = scope_row.candidate_id
       AND snooze_row.cleared_at_utc IS NULL
       AND snooze_row.cancelled_at_utc IS NULL
       AND snooze_row.snooze_until_date IS NOT NULL
       AND snooze_row.snooze_until_date >= v_last_checked_date
       AND snooze_row.snooze_until_date < v_today_uk
      WHERE scope_row.session_id = v_session.id
        AND (
          v_cursor_candidate_id IS NULL
          OR scope_row.candidate_id > v_cursor_candidate_id
          OR (
            scope_row.candidate_id = v_cursor_candidate_id
            AND v_cursor_snooze_id IS NOT NULL
            AND snooze_row.id > v_cursor_snooze_id
          )
        )
      ORDER BY scope_row.candidate_id, snooze_row.id
      LIMIT v_remaining_work_limit
    LOOP
      v_transition_result := public.pay_snooze_resolution_transition_v1(
        p_snooze_id => v_due.snooze_id,
        p_actor_user_id => v_session.actor_user_id,
        p_transition_reason => 'NATURAL_EXPIRY'
      );

      IF COALESCE((v_transition_result->>'state_changed')::boolean, false) THEN
        v_transition_changed_count := v_transition_changed_count + 1;
      END IF;

      v_job_id := NULL::uuid;
      v_job_created := false;
      v_scope_job_key := CASE
        WHEN v_due.timesheet_id IS NOT NULL THEN 'TIMESHEET:' || v_due.timesheet_id::text
        ELSE 'FULL_CANDIDATE'
      END;

      SELECT candidate_job.job_id
      INTO v_job_id
      FROM pg_temp._bpay_expiry_candidate_jobs AS candidate_job
      WHERE candidate_job.session_id = v_session.id
        AND candidate_job.candidate_id = v_due.candidate_id
        AND candidate_job.scope_job_key = v_scope_job_key;

      IF v_job_id IS NULL THEN
        SELECT CASE
                 WHEN NULLIF(BTRIM(COALESCE(affected_session.value->>'job_id', '')), '')
                        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   THEN (affected_session.value->>'job_id')::uuid
                 ELSE NULL::uuid
               END
        INTO v_job_id
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_transition_result->'affected_sessions') = 'array'
              THEN v_transition_result->'affected_sessions'
            ELSE '[]'::jsonb
          END
        ) WITH ORDINALITY AS affected_session(value, ordinality)
        WHERE NULLIF(BTRIM(COALESCE(affected_session.value->>'session_id', '')), '') = v_session.id::text
          AND NULLIF(BTRIM(COALESCE(affected_session.value->>'candidate_id', '')), '') = v_due.candidate_id::text
        ORDER BY affected_session.ordinality
        LIMIT 1;
      END IF;

      IF v_job_id IS NULL THEN
        v_scope_job_key := 'FULL_CANDIDATE';

        SELECT candidate_job.job_id
        INTO v_job_id
        FROM pg_temp._bpay_expiry_candidate_jobs AS candidate_job
        WHERE candidate_job.session_id = v_session.id
          AND candidate_job.candidate_id = v_due.candidate_id
          AND candidate_job.scope_job_key = v_scope_job_key;
      END IF;

      IF v_job_id IS NULL THEN
        v_enqueue_result := public.pay_workbench_enqueue_session_candidate_refresh(
          p_session_id => v_session.id,
          p_candidate_id => v_due.candidate_id,
          p_reason => 'SNOOZE_EXPIRED_LONDON_DATE',
          p_actor_user_id => v_session.actor_user_id,
          p_payload_json => jsonb_build_object(
            'refresh_scope_kind', 'FULL_CANDIDATE',
            'targeted_timesheet_ids', '[]'::jsonb,
            'london_current_date', v_today_uk::text,
            'current_official_pay_date', v_current_official_pay_date::text,
            'configuration_fingerprint', v_context_fingerprint,
            'first_snooze_id', v_due.snooze_id::text,
            'reason', 'SNOOZE_EXPIRED_LONDON_DATE'
          )
        );

        v_job_id_text := BTRIM(COALESCE(
          v_enqueue_result->>'job_id',
          v_enqueue_result#>>'{enqueue_result,job_id}',
          v_enqueue_result#>>'{enqueue_result,job_ids,0}',
          v_enqueue_result#>>'{job_ids,0}',
          v_enqueue_result#>>'{enqueue_result,session_recompute_job_ids,0}',
          v_enqueue_result#>>'{session_recompute_job_ids,0}',
          ''
        ));

        IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          v_job_id := v_job_id_text::uuid;
        END IF;
        v_job_created := true;
      END IF;

      IF v_job_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS job_row
        WHERE job_row.id = v_job_id
          AND job_row.session_id = v_session.id
          AND job_row.candidate_id = v_due.candidate_id
          AND job_row.status IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
      ) THEN
        RAISE EXCEPTION 'WORKBENCH_EXPIRY_REFRESH_JOB_NOT_PROVEN'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_EXPIRY_REFRESH_JOB_NOT_PROVEN',
                  'session_id', v_session.id::text,
                  'candidate_id', v_due.candidate_id::text,
                  'snooze_id', v_due.snooze_id::text
                )::text;
      END IF;

      INSERT INTO pg_temp._bpay_expiry_candidate_jobs(session_id, candidate_id, scope_job_key, job_id)
      VALUES (v_session.id, v_due.candidate_id, v_scope_job_key, v_job_id)
      ON CONFLICT (session_id, candidate_id, scope_job_key) DO NOTHING;

      IF v_job_created THEN
        v_enqueued_count := v_enqueued_count + 1;
      ELSE
        v_reused_job_count := v_reused_job_count + 1;
      END IF;

      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET progress_state = 'PENDING',
          progress_json = jsonb_strip_nulls(
            COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'snooze_expiry_refresh_pending', true,
              'snooze_expiry_scan_in_progress', true,
              'snooze_expiry_scan_london_date', v_today_uk::text,
              'snooze_expiry_candidate_cursor', v_due.candidate_id::text,
              'snooze_expiry_snooze_cursor', v_due.snooze_id::text,
              'snooze_expiry_last_job_id', v_job_id::text
            )
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;

      v_session_processed_count := v_session_processed_count + 1;
      v_processed_snooze_count := v_processed_snooze_count + 1;
      v_remaining_work_limit := v_remaining_work_limit - 1;
      v_last_candidate_id := v_due.candidate_id;
      v_last_snooze_id := v_due.snooze_id;
      v_results := v_results || jsonb_build_array(
        jsonb_build_object(
          'session_id', v_session.id::text,
          'candidate_id', v_due.candidate_id::text,
          'snooze_id', v_due.snooze_id::text,
          'job_id', v_job_id::text,
          'scope_job_key', v_scope_job_key,
          'job_created_in_expiry_pass', v_job_created,
          'transition_result', v_transition_result
        )
      );
    END LOOP;

    IF v_due_count > v_session_processed_count
       AND v_last_candidate_id IS NOT NULL
       AND v_last_snooze_id IS NOT NULL THEN
      v_more_due := true;
    ELSE
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET progress_json = jsonb_strip_nulls(
            (
              COALESCE(session_update.progress_json, '{}'::jsonb)
              - 'snooze_expiry_candidate_cursor'
              - 'snooze_expiry_snooze_cursor'
            )
            || jsonb_build_object(
              'snooze_expiry_last_checked_london_date', v_today_uk::text,
              'snooze_expiry_scan_in_progress', false,
              'snooze_expiry_scan_london_date', v_today_uk::text,
              'snooze_expiry_refresh_pending', CASE
                WHEN v_session_processed_count > 0 THEN true
                ELSE LOWER(BTRIM(COALESCE(session_update.progress_json->>'snooze_expiry_refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END
            )
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    END IF;

    IF v_remaining_work_limit <= 0 THEN
      v_more_due := true;
      EXIT;
    END IF;
  END LOOP;

  IF p_session_id IS NULL AND EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_sessions AS remaining_session
    WHERE remaining_session.status = 'OPEN'
      AND remaining_session.discarded_at_utc IS NULL
      AND remaining_session.replacement_session_id IS NULL
      AND (
        COALESCE(remaining_session.progress_json->>'snooze_expiry_last_checked_london_date', '') <> v_today_uk::text
        OR NULLIF(BTRIM(COALESCE(remaining_session.progress_json->>'snooze_expiry_candidate_cursor', '')), '') IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(remaining_session.progress_json->>'snooze_expiry_snooze_cursor', '')), '') IS NOT NULL
      )
  ) THEN
    v_more_due := true;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'london_current_date', v_today_uk::text,
    'current_official_pay_date', v_current_official_pay_date::text,
    'configuration_fingerprint', v_context_fingerprint,
    'processed_session_count', v_processed_session_count,
    'processed_snooze_count', v_processed_snooze_count,
    'transition_changed_count', v_transition_changed_count,
    'enqueued_count', v_enqueued_count,
    'reused_job_count', v_reused_job_count,
    'work_limit', v_work_limit,
    'more_due', v_more_due,
    'results', v_results
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_snoozes_list(
  p_candidate_id uuid DEFAULT NULL,
  p_active_only boolean DEFAULT true,
  p_limit int DEFAULT 200,
  p_offset int DEFAULT 0,
  p_client_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_limit int := greatest(1, least(coalesce(p_limit,200), 500));
  v_offset int := greatest(coalesce(p_offset,0), 0);
  v_total int := 0;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  WITH base AS (
    SELECT
      s.id,
      s.candidate_id,
      s.timesheet_id,
      s.segment_id,
      s.source_ref,
      upper(COALESCE(s.snooze_kind,'')) AS snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.created_by_user_id,
      s.updated_at_utc,
      s.updated_by_user_id,
      s.cleared_at_utc,
      s.cleared_by_user_id,
      CASE
        WHEN s.source_ref IS NOT NULL
         AND s.source_ref LIKE 'advance:%'
         AND split_part(s.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN split_part(s.source_ref, ':', 2)::uuid
        ELSE NULL
      END AS finance_case_id
    FROM public.pay_item_snoozes s
    WHERE (p_candidate_id IS NULL OR s.candidate_id = p_candidate_id)
      AND (coalesce(p_active_only,true) = false OR s.cleared_at_utc IS NULL)
  ),
  enriched AS (
    SELECT
      b.id,
      b.candidate_id,
      c.tms_ref AS candidate_tms_ref,
      c.display_name AS candidate_display_name,
      b.timesheet_id,
      ts.week_ending_date,
      tf.client_id AS timesheet_client_id,
      cli_tf.name AS timesheet_client_name,
      b.segment_id,
      b.source_ref,
      b.finance_case_id,
      vfc.case_type,
      vfc.client_id AS finance_client_id,
      vfc.client_name AS finance_client_name,
      vfc.linked_shift_date,
      vfc.adjustment_comment,
      vfc.status AS finance_case_status,
      vfc.payout_status AS finance_case_payout_status,
      vfc.outstanding_amount,
      vfc.active_snooze_until_date,
      b.snooze_kind,
      b.snooze_until_date,
      b.note,
      b.created_at_utc,
      b.created_by_user_id,
      b.updated_at_utc,
      b.updated_by_user_id,
      b.cleared_at_utc,
      b.cleared_by_user_id,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'PAYMENT_ADVANCE_REPAYMENT'
            WHEN 'OVERPAYMENT' THEN 'OVERPAYMENT_RECOVERY'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'MANUAL_DEBT_RECOVERY'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'MANUAL_CREDIT_ADJUSTMENT'
            ELSE 'FINANCE_CASE'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
        ELSE 'SNOOZE'
      END AS line_type,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
            WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
            ELSE 'Finance item'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'Blocked timesheet line'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'Do not pay line'
        ELSE 'Snoozed item'
      END AS line_label,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          trim(
            both ' '
            from concat(
              CASE vfc.case_type
                WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
                WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
                WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
                WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
                ELSE 'Finance item'
              END,
              CASE
                WHEN nullif(btrim(coalesce(vfc.adjustment_comment,'')), '') IS NOT NULL
                  THEN ' - ' || nullif(btrim(coalesce(vfc.adjustment_comment,'')), '')
                ELSE ''
              END
            )
          )
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Blocked timesheet line - ' || b.segment_id
            ELSE 'Blocked timesheet line'
          END
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Do not pay line - ' || b.segment_id
            ELSE 'Do not pay line'
          END
        ELSE 'Snoozed item'
      END AS line_description,
      (b.snooze_until_date IS NULL) AS snooze_is_indefinite,
      (
        b.cleared_at_utc IS NULL
        AND (b.snooze_until_date IS NULL OR b.snooze_until_date >= current_date)
      ) AS is_currently_effective,
      CASE
        WHEN b.cleared_at_utc IS NOT NULL THEN 'CLEARED_HISTORY'
        WHEN b.snooze_until_date IS NULL THEN 'LOANS_SNOOZES_ONLY'
        WHEN b.snooze_until_date >= current_date THEN 'PREVIEW_VISIBLE_EXCLUDED'
        ELSE 'PREVIEW_ELIGIBLE'
      END AS visibility_hint
    FROM base b
    JOIN public.candidates c
      ON c.id = b.candidate_id
    LEFT JOIN public.timesheets ts
      ON ts.timesheet_id = b.timesheet_id
    LEFT JOIN public.timesheets_financials tf
      ON tf.timesheet_id = b.timesheet_id
     AND tf.is_current = true
    LEFT JOIN public.clients cli_tf
      ON cli_tf.id = tf.client_id
    LEFT JOIN public.v_finance_cases_register vfc
      ON vfc.finance_case_id = b.finance_case_id
  )
  SELECT count(*)::int
  INTO v_total
  FROM enriched e
  WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id);

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', e.id::text,
        'candidate_id', e.candidate_id::text,
        'candidate_tms_ref', e.candidate_tms_ref,
        'candidate_display_name', e.candidate_display_name,
        'client_id', CASE WHEN COALESCE(e.finance_client_id, e.timesheet_client_id) IS NULL THEN NULL ELSE COALESCE(e.finance_client_id, e.timesheet_client_id)::text END,
        'client_name', COALESCE(e.finance_client_name, e.timesheet_client_name),
        'timesheet_id', CASE WHEN e.timesheet_id IS NULL THEN NULL ELSE e.timesheet_id::text END,
        'week_ending_date', CASE WHEN e.week_ending_date IS NULL THEN NULL ELSE e.week_ending_date::text END,
        'linked_shift_date', CASE WHEN e.linked_shift_date IS NULL THEN NULL ELSE e.linked_shift_date::text END,
        'segment_id', e.segment_id,
        'source_ref', e.source_ref,
        'finance_case_id', CASE WHEN e.finance_case_id IS NULL THEN NULL ELSE e.finance_case_id::text END,
        'case_type', e.case_type,
        'finance_case_status', e.finance_case_status,
        'finance_case_payout_status', e.finance_case_payout_status,
        'finance_case_outstanding_amount', e.outstanding_amount,
        'adjustment_comment', e.adjustment_comment,
        'line_type', e.line_type,
        'line_label', e.line_label,
        'line_description', e.line_description,
        'snooze_kind', e.snooze_kind,
        'snooze_until_date', CASE WHEN e.snooze_until_date IS NULL THEN NULL ELSE e.snooze_until_date::text END,
        'snooze_is_indefinite', e.snooze_is_indefinite,
        'is_currently_effective', e.is_currently_effective,
        'visibility_hint', e.visibility_hint,
        'note', e.note,
        'created_at_utc', e.created_at_utc,
        'created_by_user_id', CASE WHEN e.created_by_user_id IS NULL THEN NULL ELSE e.created_by_user_id::text END,
        'updated_at_utc', e.updated_at_utc,
        'updated_by_user_id', CASE WHEN e.updated_by_user_id IS NULL THEN NULL ELSE e.updated_by_user_id::text END,
        'cleared_at_utc', e.cleared_at_utc,
        'cleared_by_user_id', CASE WHEN e.cleared_by_user_id IS NULL THEN NULL ELSE e.cleared_by_user_id::text END,
        'action_flags', jsonb_build_object(
          'can_clear', e.cleared_at_utc IS NULL,
          'can_amend_date', e.cleared_at_utc IS NULL,
          'can_set_indefinite', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NOT NULL,
          'can_set_dated', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NULL
        )
      )
      ORDER BY e.created_at_utc DESC, e.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT e.*
    FROM enriched e
    WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id)
    ORDER BY e.created_at_utc DESC, e.id DESC
    LIMIT v_limit OFFSET v_offset
  ) e;

  RETURN jsonb_build_object(
    'ok', true,
    'total_count', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows
  );
END;
$$;








-- =========================================================
-- A4.1 pay_preview(p_pay_date date, p_actor_user_id uuid)
-- UPDATED LOGIC FULLY APPLIED:
--  - Uses effective require_reference_to_pay = COALESCE(CASE WHEN ct.overrideclientsettings THEN ct.require_reference_to_pay END, cs.pay_reference_required, false)
--  - Segment-level reference gating using invoice_breakdown_json.segments[].ref_num (fallback uses timesheets.reference_number for non-SEGMENTS mode)
--  - Returns BLOCKED items (missing ref_num where required AND delta > 0) instead of filtering them out
--  - Returns DO_NOT_PAY items (exclude_from_pay=true), including those with no delta (informational)
--  - Applies snoozing via public.pay_item_snoozes:
--      * snooze_kind='BLOCKED' for blocked items
--      * snooze_kind='DO_NOT_PAY' for do-not-pay items
--    Active snooze: cleared_at_utc IS NULL AND (snooze_until_date IS NULL OR snooze_until_date >= p_pay_date)
--    Suppression rule:
--      * BLOCKED: suppressed if snoozed (always)
--      * DO_NOT_PAY: suppressed if snoozed AND raw_delta = 0 (informational-only)
--  - Payable deltas exclude blocked-positive segments (delta forced to 0) but still show them in blocked_items list
-- =========================================================




-- =========================================================
-- A4.2 pay_create_draft_batch(p_pay_date, p_actor_user_id, p_preview_decisions_json)
-- UPDATED LOGIC FULLY APPLIED:
--  - Candidate selection uses pay_preview but only includes candidates with has_any_delta=true
--  - Segment-level ref gating identical to pay_preview:
--      * Missing ref_num where required blocks ONLY positive delta for that segment (excluded from payable items)
--  - Uses effective require_reference_to_pay (overrideclientsettings-aware, client_settings fallback)
--  - Does not filter out missing refs at timesheet level
-- =========================================================






CREATE OR REPLACE FUNCTION public.pay_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_preview_decisions_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_preview_decisions_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_requested_mode text := UPPER(NULLIF(BTRIM(COALESCE(
    v_preview_decisions_json->>'preview_mode',
    v_preview_decisions_json->>'detail_mode',
    v_preview_decisions_json->>'mode',
    'SUMMARY'
  )), ''));
  v_context_json jsonb := '{}'::jsonb;
  v_full_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_scope_candidate_id_text text := '';
  v_candidate_baseline_json jsonb := '{}'::jsonb;
  v_candidate_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
  v_scope_candidate_count integer := 0;
  v_scope_page_count integer := 0;
  v_tiny_compat_threshold integer := 5;
  v_full_compat_requested boolean := false;
  v_scope_limit integer := 100;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('PREVIEW_PROGRESS');

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PREVIEW_PAY_DATE_REQUIRED')::text;
  END IF;

  IF v_requested_mode NOT IN ('SUMMARY', 'PAGE', 'FULL_COMPAT') THEN
    v_requested_mode := 'SUMMARY';
  END IF;

  v_full_compat_requested := (v_requested_mode = 'FULL_COMPAT');

  IF COALESCE(v_preview_decisions_json->>'scope_limit', '') ~ '^[0-9]+$' THEN
    v_scope_limit := LEAST(GREATEST((v_preview_decisions_json->>'scope_limit')::integer, 1), 100);
  ELSE
    v_scope_limit := 100;
  END IF;

  /*
    5.1: pay_preview is now strictly a pre-draft entry point.

    Normal Banking modal usage gets compact bootstrap/progress metadata and must
    page through the row-backed workbench/session APIs.  Full legacy preview
    payloads are only produced for tiny compatibility scopes.
  */
  v_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json
      || jsonb_build_object(
        'preview_context_mode', CASE WHEN v_requested_mode = 'PAGE' THEN 'PAGE' ELSE 'SUMMARY' END,
        'scope_limit', v_scope_limit
      )
  );

  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_preview_build_context must return a JSON object';
  END IF;

  v_scope_candidate_count := COALESCE(NULLIF(BTRIM(COALESCE(v_context_json->>'scope_candidate_count', '')), '')::integer, 0);
  v_scope_page_count := COALESCE(NULLIF(BTRIM(COALESCE(v_context_json->>'scope_page_count', '')), '')::integer, 0);

  IF v_full_compat_requested IS NOT TRUE
     OR COALESCE(v_scope_candidate_count, 0) > v_tiny_compat_threshold THEN
    RETURN jsonb_build_object(
      'ok', true,
      'preview_mode', CASE WHEN v_full_compat_requested THEN 'SUMMARY_FULL_COMPAT_SUPPRESSED' ELSE v_requested_mode END,
      'pre_draft', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'bootstrap_only', true,
      'full_preview_payload_returned', false,
      'full_preview_payload_suppressed', true,
      'tiny_compat_threshold', v_tiny_compat_threshold,
      'scope_candidate_count', COALESCE(v_scope_candidate_count, 0),
      'scope_page_count', COALESCE(v_scope_page_count, 0),
      'scope_has_more', COALESCE(NULLIF(v_context_json->>'scope_has_more', '')::boolean, false),
      'scope_next_cursor', COALESCE(v_context_json->'scope_next_cursor', NULL::jsonb),
      'workbench_session_paging_required', true,
      'recommended_next_api', 'pay_workbench_session_open',
      'recommended_page_api', 'pay_workbench_session_seed_scope_chunk',
      'context', v_context_json,
      'generated_at_utc', v_now::text
    );
  END IF;

  /*
    Tiny legacy compatibility path only.  This remains pre-draft and uses the
    existing live preview functions.  Larger Banking modal requests must use
    row-backed workbench paging.
  */
  v_full_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json || jsonb_build_object('preview_context_mode', 'FULL_COMPAT')
  );

  v_scope_candidate_ids := CASE
    WHEN jsonb_typeof(v_full_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_full_context_json->'scope_candidate_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  FOR v_scope_candidate_id_text IN
    SELECT BTRIM(scope_candidate.value)
    FROM jsonb_array_elements_text(v_scope_candidate_ids) AS scope_candidate(value)
    WHERE BTRIM(scope_candidate.value) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY BTRIM(scope_candidate.value)
  LOOP
    v_candidate_baseline_json := public.pay_preview_build_candidate_baseline(
      p_context_json => v_full_context_json,
      p_candidate_id => v_scope_candidate_id_text::uuid
    );

    v_candidate_effective_json := public.pay_preview_apply_candidate_overlay(
      p_candidate_baseline_json => v_candidate_baseline_json,
      p_case_resolutions_json => COALESCE(v_full_context_json->'preview_case_resolutions', '{}'::jsonb),
      p_overrides_json => COALESCE(v_full_context_json->'preview_decisions_json', '{}'::jsonb)
    );

    v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
      p_context_json => v_full_context_json,
      p_candidate_effective_json => v_candidate_effective_json
    );

    v_candidate_rollups_json := v_candidate_rollups_json || jsonb_build_array(v_candidate_rollup_json);
  END LOOP;

  RETURN public.pay_preview_assemble_payload(
    p_context_json => v_full_context_json || jsonb_build_object(
      'preview_mode', 'FULL_COMPAT',
      'pre_draft', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'full_preview_payload_returned', true,
      'tiny_compat_threshold', v_tiny_compat_threshold
    ),
    p_candidate_rollups_json => v_candidate_rollups_json
  );
END;
$function$;









CREATE OR REPLACE FUNCTION public.pay_create_draft_batch(p_pay_date date, p_week_ending_cutoff date, p_pay_channel_scope text, p_actor_user_id uuid, p_preview_decisions_json jsonb, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_override_reason text DEFAULT NULL::text, p_override_mode pay_override_mode_enum DEFAULT 'NONE'::pay_override_mode_enum, p_operation_id uuid DEFAULT NULL::uuid, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := UPPER(BTRIM(COALESCE(p_pay_channel_scope, '')));
  v_preview_decisions jsonb := p_preview_decisions_json;
  v_split_result jsonb := '{}'::jsonb;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_input jsonb := '{}'::jsonb;
  v_operation_scope text := NULL::text;
  v_operation_session_id uuid := NULL::uuid;
  v_operation_source_session_version bigint := NULL::bigint;
  v_operation_source_snapshot_run_id uuid := NULL::uuid;
  v_operation_source_session_signature text := NULL::text;
  v_operation_status text := NULL::text;
  v_is_terminal boolean := false;
  v_operation_pay_date date := NULL::date;
  v_operation_week_ending_cutoff date := NULL::date;
  v_operation_candidate_id uuid := NULL::uuid;
  v_operation_client_id uuid := NULL::uuid;
  v_operation_selected_json jsonb := '[]'::jsonb;
  v_operation_selected_ids text[] := ARRAY[]::text[];
  v_request_selected_ids text[] := ARRAY[]::text[];
  v_operation_force_include_json jsonb := '[]'::jsonb;
  v_operation_force_include_ids uuid[] := ARRAY[]::uuid[];
  v_request_force_include_ids uuid[] := ARRAY[]::uuid[];
  v_operation_override_proof jsonb := '{}'::jsonb;
  v_operation_override_reason text := NULL::text;
  v_operation_override_mode public.pay_override_mode_enum := 'NONE'::public.pay_override_mode_enum;
  v_operation_override_used boolean := false;
  v_requested_channel_batch_id uuid := NULL::uuid;
  v_json_key text;
  v_json_value jsonb;
  v_text_value text;
  v_unknown_keys text[] := ARRAY[]::text[];
  v_invalid_count integer := 0;
  v_raw_count integer := 0;
  v_distinct_count integer := 0;
  v_selection_field_count integer := 0;
  v_session_field_count integer := 0;
  v_version_field_count integer := 0;
  v_snapshot_field_count integer := 0;
  v_signature_field_count integer := 0;
BEGIN
  IF COALESCE(p_allow_legacy_unchunked, false) IS TRUE THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED',
        'message', 'Legacy all-at-once draft creation is permanently disabled. Use the Banking Pay DRAFT_CREATE operation flow.',
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'allow_legacy_unchunked', true
      )::text;
  END IF;

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'pay_date is required';
  END IF;
  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'week_ending_cutoff is required';
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'actor_user_id is required';
  END IF;
  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_REQUIRED',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
        'message', 'Draft creation requires an immutable Banking Pay DRAFT_CREATE operation.',
        'pay_date', p_pay_date::text,
        'week_ending_cutoff', p_week_ending_cutoff::text,
        'pay_channel_scope', v_scope
      )::text;
  END IF;
  IF v_preview_decisions IS NULL OR jsonb_typeof(v_preview_decisions) <> 'object' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'DRAFT_CREATE_PREVIEW_DECISIONS_INVALID',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_PREVIEW_DECISIONS_INVALID',
        'operation_id', p_operation_id::text,
        'message', 'preview_decisions_json must be an immutable operation-authority object.'
      )::text;
  END IF;

  SELECT COALESCE(array_agg(unknown_key ORDER BY unknown_key), ARRAY[]::text[])
    INTO v_unknown_keys
  FROM jsonb_object_keys(v_preview_decisions) AS decision_key(unknown_key)
  WHERE decision_key.unknown_key <> ALL (ARRAY[
    'selected_preview_row_ids', 'selectedPreviewRowIds',
    'draft_selected_preview_row_ids', 'draftSelectedPreviewRowIds',
    'scoped_selected_preview_row_ids', 'scopedSelectedPreviewRowIds',
    '__selected_preview_row_mode', 'selected_preview_row_mode', 'selectedPreviewRowMode',
    'pay_channel_scope', 'payChannelScope', 'draft_scope', 'draftScope', 'scope',
    'session_id', 'sessionId', 'workbench_session_id', 'workbenchSessionId',
    'session_version', 'sessionVersion', 'source_session_version', 'sourceSessionVersion',
    'snapshot_run_id', 'snapshotRunId', 'source_snapshot_run_id', 'sourceSnapshotRunId',
    'session_signature', 'sessionSignature', 'source_session_signature', 'sourceSessionSignature',
    'candidate_filter_id', 'candidateFilterId', 'client_filter_id', 'clientFilterId',
    'draft_selected_preview_row_contracts', 'draftSelectedPreviewRowContracts',
    'selected_preview_row_contracts', 'selectedPreviewRowContracts',
    'scoped_selected_preview_row_contracts', 'scopedSelectedPreviewRowContracts',
    'draft_selected_economic_keys', 'draftSelectedEconomicKeys',
    'selected_economic_keys', 'selectedEconomicKeys',
    'scoped_selected_economic_keys', 'scopedSelectedEconomicKeys'
  ]::text[]);

  IF COALESCE(array_length(v_unknown_keys, 1), 0) > 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_PREVIEW_DECISIONS_UNBOUND',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_PREVIEW_DECISIONS_UNBOUND',
        'operation_id', p_operation_id::text,
        'unsupported_fields', to_jsonb(v_unknown_keys),
        'message', 'Every supplied draft decision field must be bound to immutable operation input.'
      )::text;
  END IF;

  SELECT operation_row.*
    INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE OF operation_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_NOT_FOUND';
  END IF;
  IF v_operation_row.operation_type IS DISTINCT FROM 'DRAFT_CREATE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_TYPE_INVALID';
  END IF;
  IF v_operation_row.actor_user_id IS NULL OR v_operation_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_ACTOR_INVALID';
  END IF;
  IF v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SESSION_REQUIRED';
  END IF;

  v_operation_status := UPPER(BTRIM(COALESCE(v_operation_row.status, '')));
  IF v_operation_status NOT IN ('QUEUED', 'RUNNING', 'WAITING', 'COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_STATUS_INVALID';
  END IF;
  v_is_terminal := v_operation_status IN ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED');

  SELECT session_row.*
    INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_operation_row.workbench_session_id
  FOR UPDATE OF session_row;

  IF NOT FOUND OR v_session_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_SESSION_INVALID';
  END IF;

  v_operation_input := COALESCE(v_operation_row.input_json, '{}'::jsonb);
  IF jsonb_typeof(v_operation_input) <> 'object' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_INPUT_INVALID';
  END IF;

  IF COALESCE(v_operation_input ->> 'pay_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR COALESCE(
       NULLIF(BTRIM(COALESCE(v_operation_input ->> 'week_ending_cutoff', '')), ''),
       v_operation_input ->> 'week_ending_cutoff_date',
       ''
     ) !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CONTEXT_REQUIRED';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_operation_input ->> 'week_ending_cutoff', '')), '') IS NOT NULL
     AND NULLIF(BTRIM(COALESCE(v_operation_input ->> 'week_ending_cutoff_date', '')), '') IS NOT NULL
     AND BTRIM(v_operation_input ->> 'week_ending_cutoff') IS DISTINCT FROM BTRIM(v_operation_input ->> 'week_ending_cutoff_date') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CUTOFF_CONFLICT';
  END IF;

  BEGIN
    v_operation_pay_date := (v_operation_input ->> 'pay_date')::date;
    v_operation_week_ending_cutoff := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_input ->> 'week_ending_cutoff', '')), ''),
      v_operation_input ->> 'week_ending_cutoff_date'
    )::date;
  EXCEPTION
    WHEN invalid_text_representation OR datetime_field_overflow THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CONTEXT_INVALID';
  END;

  IF v_operation_pay_date IS DISTINCT FROM p_pay_date
     OR v_operation_week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff
     OR v_session_row.pay_date IS DISTINCT FROM p_pay_date
     OR v_session_row.week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CONTEXT_MISMATCH';
  END IF;

  IF COALESCE(v_operation_input ->> 'workbench_session_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(v_operation_input ->> 'session_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SESSION_AUTHORITY_REQUIRED';
  END IF;

  v_operation_session_id := (v_operation_input ->> 'workbench_session_id')::uuid;
  IF (v_operation_input ->> 'session_id')::uuid IS DISTINCT FROM v_operation_session_id
     OR v_operation_session_id IS DISTINCT FROM v_operation_row.workbench_session_id
     OR v_operation_session_id IS DISTINCT FROM v_session_row.id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SESSION_AUTHORITY_MISMATCH';
  END IF;

  IF COALESCE(v_operation_input ->> 'source_session_version', '') !~ '^[1-9][0-9]*$'
     OR COALESCE(v_operation_input ->> 'source_snapshot_run_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR NULLIF(BTRIM(COALESCE(v_operation_input ->> 'source_session_signature', '')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_REQUIRED';
  END IF;

  v_operation_source_session_version := (v_operation_input ->> 'source_session_version')::bigint;
  v_operation_source_snapshot_run_id := (v_operation_input ->> 'source_snapshot_run_id')::uuid;
  v_operation_source_session_signature := BTRIM(v_operation_input ->> 'source_session_signature');

  IF NOT v_is_terminal AND (
       v_session_row.status IS DISTINCT FROM 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL
       OR v_session_row.replacement_session_id IS NOT NULL
       OR v_operation_source_session_version IS DISTINCT FROM v_session_row.version
       OR v_operation_source_snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id
       OR v_operation_source_session_signature IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_session_row.session_signature, '')), '')
     ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_MISMATCH';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_operation_input ->> 'pay_channel_scope', '')), '') IS NOT NULL
     AND NULLIF(BTRIM(COALESCE(v_operation_input ->> 'draft_scope', '')), '') IS NOT NULL
     AND UPPER(BTRIM(v_operation_input ->> 'pay_channel_scope')) IS DISTINCT FROM UPPER(BTRIM(v_operation_input ->> 'draft_scope')) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SCOPE_CONFLICT';
  END IF;

  v_operation_scope := UPPER(BTRIM(COALESCE(
    NULLIF(v_operation_input ->> 'pay_channel_scope', ''),
    NULLIF(v_operation_input ->> 'draft_scope', ''),
    ''
  )));
  IF v_operation_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SCOPE_INVALID';
  END IF;
  IF v_operation_scope <> 'ALL' AND v_operation_scope IS DISTINCT FROM v_scope THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SCOPE_MISMATCH';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_operation_input ->> 'candidate_filter_id', '')), '') IS NOT NULL THEN
    IF COALESCE(v_operation_input ->> 'candidate_filter_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CANDIDATE_FILTER_INVALID';
    END IF;
    v_operation_candidate_id := (v_operation_input ->> 'candidate_filter_id')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_operation_input ->> 'client_filter_id', '')), '') IS NOT NULL THEN
    IF COALESCE(v_operation_input ->> 'client_filter_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_CLIENT_FILTER_INVALID';
    END IF;
    v_operation_client_id := (v_operation_input ->> 'client_filter_id')::uuid;
  END IF;

  IF p_candidate_id IS DISTINCT FROM v_operation_candidate_id
     OR p_client_id IS DISTINCT FROM v_operation_client_id THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_FILTER_MISMATCH',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_FILTER_MISMATCH',
        'operation_id', p_operation_id::text,
        'expected_candidate_id', CASE WHEN v_operation_candidate_id IS NULL THEN NULL ELSE v_operation_candidate_id::text END,
        'supplied_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
        'expected_client_id', CASE WHEN v_operation_client_id IS NULL THEN NULL ELSE v_operation_client_id::text END,
        'supplied_client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END
      )::text;
  END IF;

  IF jsonb_typeof(v_operation_input -> 'draft_selected_preview_row_ids') = 'array'
     AND jsonb_typeof(v_operation_input -> 'selected_preview_row_ids') = 'array'
     AND (v_operation_input -> 'draft_selected_preview_row_ids') IS DISTINCT FROM (v_operation_input -> 'selected_preview_row_ids') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SELECTION_CONFLICT';
  END IF;

  v_operation_selected_json := CASE
    WHEN jsonb_typeof(v_operation_input -> 'draft_selected_preview_row_ids') = 'array'
      THEN v_operation_input -> 'draft_selected_preview_row_ids'
    WHEN jsonb_typeof(v_operation_input -> 'selected_preview_row_ids') = 'array'
      THEN v_operation_input -> 'selected_preview_row_ids'
    ELSE '[]'::jsonb
  END;

  SELECT COUNT(*)::integer
    INTO v_invalid_count
  FROM jsonb_array_elements(v_operation_selected_json) AS selected_value(value)
  WHERE jsonb_typeof(selected_value.value) <> 'string'
     OR COALESCE(selected_value.value #>> '{}', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  IF COALESCE(v_invalid_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SELECTION_INVALID';
  END IF;

  SELECT
    COUNT(*)::integer,
    COUNT(DISTINCT BTRIM(selected_value))::integer,
    COALESCE(array_agg(DISTINCT BTRIM(selected_value) ORDER BY BTRIM(selected_value)), ARRAY[]::text[])
  INTO v_raw_count, v_distinct_count, v_operation_selected_ids
  FROM jsonb_array_elements_text(v_operation_selected_json) AS selected_value;

  IF COALESCE(v_raw_count, 0) = 0 OR v_raw_count <> v_distinct_count THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SELECTION_NOT_CANONICAL';
  END IF;

  v_operation_force_include_json := CASE
    WHEN jsonb_typeof(v_operation_input -> 'force_include_timesheet_ids') = 'array'
      THEN v_operation_input -> 'force_include_timesheet_ids'
    ELSE '[]'::jsonb
  END;

  SELECT COUNT(*)::integer
    INTO v_invalid_count
  FROM jsonb_array_elements(v_operation_force_include_json) AS force_value(value)
  WHERE jsonb_typeof(force_value.value) <> 'string'
     OR COALESCE(force_value.value #>> '{}', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  IF COALESCE(v_invalid_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_FORCE_INCLUDE_INVALID';
  END IF;

  SELECT
    COALESCE(array_agg(DISTINCT force_value::uuid ORDER BY force_value::uuid), ARRAY[]::uuid[]),
    COUNT(*)::integer,
    COUNT(DISTINCT force_value)::integer
  INTO v_operation_force_include_ids, v_raw_count, v_distinct_count
  FROM jsonb_array_elements_text(v_operation_force_include_json) AS force_value;

  IF v_raw_count <> v_distinct_count THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_FORCE_INCLUDE_NOT_CANONICAL';
  END IF;

  SELECT
    COALESCE(array_agg(DISTINCT supplied_force_id ORDER BY supplied_force_id) FILTER (WHERE supplied_force_id IS NOT NULL), ARRAY[]::uuid[]),
    COUNT(*)::integer,
    COUNT(DISTINCT supplied_force_id)::integer,
    COUNT(*) FILTER (WHERE supplied_force_id IS NULL)::integer
  INTO v_request_force_include_ids, v_raw_count, v_distinct_count, v_invalid_count
  FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS supplied_force(supplied_force_id);

  IF COALESCE(v_invalid_count, 0) > 0 OR v_raw_count <> v_distinct_count THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_FORCE_INCLUDE_NOT_CANONICAL';
  END IF;
  IF v_request_force_include_ids IS DISTINCT FROM v_operation_force_include_ids THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_FORCE_INCLUDE_MISMATCH';
  END IF;

  IF jsonb_typeof(v_operation_input -> 'same_week_paye_override') = 'object' THEN
    v_operation_override_proof := v_operation_input -> 'same_week_paye_override';
  ELSIF jsonb_typeof(v_operation_input -> 'same_week_paye_override_json') = 'object' THEN
    v_operation_override_proof := v_operation_input -> 'same_week_paye_override_json';
  ELSE
    v_operation_override_proof := '{}'::jsonb;
  END IF;

  IF jsonb_typeof(v_operation_input -> 'same_week_paye_override') = 'object'
     AND jsonb_typeof(v_operation_input -> 'same_week_paye_override_json') = 'object'
     AND (v_operation_input -> 'same_week_paye_override') IS DISTINCT FROM (v_operation_input -> 'same_week_paye_override_json') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_OVERRIDE_PROOF_CONFLICT';
  END IF;

  v_operation_override_used := COALESCE(
    CASE
      WHEN LOWER(COALESCE(v_operation_input ->> 'same_week_paye_override_used', '')) IN ('true', 'false')
        THEN (v_operation_input ->> 'same_week_paye_override_used')::boolean
      ELSE NULL::boolean
    END,
    CASE
      WHEN LOWER(COALESCE(v_operation_override_proof ->> 'used', '')) IN ('true', 'false')
        THEN (v_operation_override_proof ->> 'used')::boolean
      ELSE false
    END,
    false
  );
  v_operation_override_reason := NULLIF(BTRIM(COALESCE(
    v_operation_override_proof ->> 'reason',
    v_operation_input ->> 'override_reason',
    v_operation_input ->> 'same_week_paye_override_reason',
    ''
  )), '');

  IF NULLIF(BTRIM(COALESCE(v_operation_input ->> 'override_mode', '')), '') IS NOT NULL THEN
    IF UPPER(BTRIM(v_operation_input ->> 'override_mode')) NOT IN ('NONE', 'TIMESHEET_ADVANCE') THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_OVERRIDE_MODE_INVALID';
    END IF;
    v_operation_override_mode := UPPER(BTRIM(v_operation_input ->> 'override_mode'))::public.pay_override_mode_enum;
  END IF;

  IF COALESCE(p_override_mode, 'NONE'::public.pay_override_mode_enum) IS DISTINCT FROM v_operation_override_mode
     OR NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS DISTINCT FROM v_operation_override_reason THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_OVERRIDE_MISMATCH';
  END IF;

  IF v_operation_override_used THEN
    IF v_operation_scope NOT IN ('ALL', 'PAYE')
       OR COALESCE((v_operation_override_proof ->> 'used')::boolean, false) IS NOT TRUE
       OR COALESCE((v_operation_override_proof ->> 'continue')::boolean, false) IS NOT TRUE
       OR COALESCE((v_operation_override_proof ->> 'verified')::boolean, false) IS NOT TRUE
       OR v_operation_override_reason IS NULL
       OR COALESCE(v_operation_override_proof ->> 'verified_by_user_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR (v_operation_override_proof ->> 'verified_by_user_id')::uuid IS DISTINCT FROM p_actor_user_id
       OR NULLIF(BTRIM(COALESCE(v_operation_override_proof ->> 'verified_at_utc', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(v_operation_override_proof ->> 'reauth_purpose', ''))) <> 'PAYE_SAME_WEEK_OVERRIDE'
       OR UPPER(BTRIM(COALESCE(v_operation_override_proof ->> 'guardrail_code', ''))) <> 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_OVERRIDE_PROOF_INVALID';
    END IF;
  ELSIF v_operation_override_reason IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_OVERRIDE_PROOF_INVALID';
  END IF;

  IF jsonb_typeof(v_operation_input -> 'draft_selected_preview_row_contracts') = 'array'
     AND jsonb_typeof(v_operation_input -> 'selected_preview_row_contracts') = 'array'
     AND (v_operation_input -> 'draft_selected_preview_row_contracts') IS DISTINCT FROM (v_operation_input -> 'selected_preview_row_contracts') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_PREVIEW_CONTRACT_CONFLICT';
  END IF;

  IF jsonb_typeof(v_operation_input -> 'draft_selected_economic_keys') = 'array'
     AND jsonb_typeof(v_operation_input -> 'selected_economic_keys') = 'array'
     AND (v_operation_input -> 'draft_selected_economic_keys') IS DISTINCT FROM (v_operation_input -> 'selected_economic_keys') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_ECONOMIC_KEY_CONFLICT';
  END IF;

  FOR v_json_key, v_json_value IN
    SELECT decision_entry.key, decision_entry.value
    FROM jsonb_each(v_preview_decisions) AS decision_entry(key, value)
    ORDER BY decision_entry.key
  LOOP
    IF v_json_key = ANY (ARRAY[
      'selected_preview_row_ids', 'selectedPreviewRowIds',
      'draft_selected_preview_row_ids', 'draftSelectedPreviewRowIds',
      'scoped_selected_preview_row_ids', 'scopedSelectedPreviewRowIds'
    ]::text[]) THEN
      v_selection_field_count := v_selection_field_count + 1;
      IF jsonb_typeof(v_json_value) <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SELECTION_INVALID';
      END IF;
      SELECT COUNT(*)::integer
        INTO v_invalid_count
      FROM jsonb_array_elements(v_json_value) AS request_selected(value)
      WHERE jsonb_typeof(request_selected.value) <> 'string'
         OR COALESCE(request_selected.value #>> '{}', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
      IF COALESCE(v_invalid_count, 0) > 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SELECTION_INVALID';
      END IF;
      SELECT
        COUNT(*)::integer,
        COUNT(DISTINCT BTRIM(request_selected))::integer,
        COALESCE(array_agg(DISTINCT BTRIM(request_selected) ORDER BY BTRIM(request_selected)), ARRAY[]::text[])
      INTO v_raw_count, v_distinct_count, v_request_selected_ids
      FROM jsonb_array_elements_text(v_json_value) AS request_selected;
      IF v_raw_count <> v_distinct_count OR v_request_selected_ids IS DISTINCT FROM v_operation_selected_ids THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SELECTION_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'session_id', 'sessionId', 'workbench_session_id', 'workbenchSessionId'
    ]::text[]) THEN
      v_session_field_count := v_session_field_count + 1;
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) <> 'string'
         OR COALESCE(v_text_value, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR v_text_value::uuid IS DISTINCT FROM v_operation_session_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SESSION_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'session_version', 'sessionVersion', 'source_session_version', 'sourceSessionVersion'
    ]::text[]) THEN
      v_version_field_count := v_version_field_count + 1;
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) NOT IN ('string', 'number')
         OR COALESCE(v_text_value, '') !~ '^[1-9][0-9]*$'
         OR v_text_value::bigint IS DISTINCT FROM v_operation_source_session_version THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SESSION_VERSION_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'snapshot_run_id', 'snapshotRunId', 'source_snapshot_run_id', 'sourceSnapshotRunId'
    ]::text[]) THEN
      v_snapshot_field_count := v_snapshot_field_count + 1;
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) <> 'string'
         OR COALESCE(v_text_value, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR v_text_value::uuid IS DISTINCT FROM v_operation_source_snapshot_run_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SNAPSHOT_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'session_signature', 'sessionSignature', 'source_session_signature', 'sourceSessionSignature'
    ]::text[]) THEN
      v_signature_field_count := v_signature_field_count + 1;
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) <> 'string'
         OR v_text_value IS DISTINCT FROM v_operation_source_session_signature THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SIGNATURE_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'pay_channel_scope', 'payChannelScope', 'draft_scope', 'draftScope', 'scope'
    ]::text[]) THEN
      v_text_value := UPPER(BTRIM(COALESCE(v_json_value #>> '{}', '')));
      IF jsonb_typeof(v_json_value) <> 'string'
         OR v_text_value NOT IN ('PAYE', 'UMBRELLA')
         OR v_text_value IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SCOPE_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY['candidate_filter_id', 'candidateFilterId']::text[]) THEN
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) NOT IN ('string', 'null')
         OR (v_text_value IS NOT NULL AND v_text_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
         OR (CASE WHEN v_text_value IS NULL THEN NULL::uuid ELSE v_text_value::uuid END) IS DISTINCT FROM v_operation_candidate_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_CANDIDATE_FILTER_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY['client_filter_id', 'clientFilterId']::text[]) THEN
      v_text_value := NULLIF(BTRIM(COALESCE(v_json_value #>> '{}', '')), '');
      IF jsonb_typeof(v_json_value) NOT IN ('string', 'null')
         OR (v_text_value IS NOT NULL AND v_text_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
         OR (CASE WHEN v_text_value IS NULL THEN NULL::uuid ELSE v_text_value::uuid END) IS DISTINCT FROM v_operation_client_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_CLIENT_FILTER_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      '__selected_preview_row_mode', 'selected_preview_row_mode', 'selectedPreviewRowMode'
    ]::text[]) THEN
      v_text_value := UPPER(BTRIM(COALESCE(v_json_value #>> '{}', '')));
      IF jsonb_typeof(v_json_value) <> 'string'
         OR v_text_value IS DISTINCT FROM UPPER(BTRIM(COALESCE(v_operation_input ->> 'selected_preview_row_mode', ''))) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_SELECTION_MODE_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'draft_selected_preview_row_contracts', 'draftSelectedPreviewRowContracts',
      'selected_preview_row_contracts', 'selectedPreviewRowContracts',
      'scoped_selected_preview_row_contracts', 'scopedSelectedPreviewRowContracts'
    ]::text[]) THEN
      IF jsonb_typeof(v_json_value) <> 'array'
         OR v_json_value IS DISTINCT FROM COALESCE(
           v_operation_input -> 'draft_selected_preview_row_contracts',
           v_operation_input -> 'selected_preview_row_contracts',
           '[]'::jsonb
         ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_PREVIEW_CONTRACT_MISMATCH';
      END IF;

    ELSIF v_json_key = ANY (ARRAY[
      'draft_selected_economic_keys', 'draftSelectedEconomicKeys',
      'selected_economic_keys', 'selectedEconomicKeys',
      'scoped_selected_economic_keys', 'scopedSelectedEconomicKeys'
    ]::text[]) THEN
      IF jsonb_typeof(v_json_value) <> 'array'
         OR v_json_value IS DISTINCT FROM COALESCE(
           v_operation_input -> 'draft_selected_economic_keys',
           v_operation_input -> 'selected_economic_keys',
           '[]'::jsonb
         ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_REQUEST_ECONOMIC_KEY_MISMATCH';
      END IF;
    END IF;
  END LOOP;

  IF v_selection_field_count = 0
     OR v_session_field_count = 0
     OR v_version_field_count = 0
     OR v_snapshot_field_count = 0
     OR v_signature_field_count = 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_REQUEST_IMMUTABLE_AUTHORITY_REQUIRED',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_REQUEST_IMMUTABLE_AUTHORITY_REQUIRED',
        'operation_id', p_operation_id::text,
        'selection_present', v_selection_field_count > 0,
        'session_present', v_session_field_count > 0,
        'session_version_present', v_version_field_count > 0,
        'snapshot_present', v_snapshot_field_count > 0,
        'signature_present', v_signature_field_count > 0
      )::text;
  END IF;

  v_split_result := public.pay_create_draft_batches_split(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_preview_decisions_json => v_preview_decisions,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_force_include_timesheet_ids => p_force_include_timesheet_ids,
    p_override_reason => p_override_reason,
    p_override_mode => COALESCE(p_override_mode, 'NONE'::public.pay_override_mode_enum),
    p_override_continue => false,
    p_override_verified => false,
    p_override_verified_by_user_id => NULL::uuid,
    p_override_verified_at_utc => NULL::timestamptz,
    p_operation_id => p_operation_id,
    p_allow_legacy_unchunked => false
  );

  IF v_split_result IS NULL OR jsonb_typeof(v_split_result) <> 'object'
     OR jsonb_typeof(v_split_result -> 'ok') <> 'boolean' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_SPLIT_AUTHORITY_INVALID',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_SPLIT_AUTHORITY_INVALID',
        'operation_id', p_operation_id::text,
        'message', 'The operation-owned split authority returned an invalid result.'
      )::text;
  END IF;

  v_text_value := CASE
    WHEN v_scope = 'PAYE' THEN NULLIF(BTRIM(COALESCE(v_split_result ->> 'paye_pay_batch_id', '')), '')
    ELSE NULLIF(BTRIM(COALESCE(v_split_result ->> 'umbrella_pay_batch_id', '')), '')
  END;
  IF v_text_value IS NOT NULL THEN
    IF v_text_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_ROUTE_BATCH_ID_INVALID';
    END IF;
    v_requested_channel_batch_id := v_text_value::uuid;
  END IF;

  RETURN v_split_result
    || jsonb_build_object(
      'ok', COALESCE((v_split_result ->> 'ok')::boolean, false),
      'operation_mode', true,
      'legacy_unchunked_permanently_disabled', true,
      'no_direct_batch_creation', true,
      'immutable_operation_authority_verified', true,
      'requested_pay_channel_scope', v_scope,
      'operation_pay_channel_scope', v_operation_scope,
      'pay_batch_id', CASE WHEN v_requested_channel_batch_id IS NULL THEN NULL ELSE v_requested_channel_batch_id::text END,
      'selected_preview_row_count', COALESCE(array_length(v_operation_selected_ids, 1), 0)
    );
END;
$function$;













-- =========================================================
-- A4.10 pay_timesheet_impact_preview(p_timesheet_id)
-- Returns baseline totals, current totals, and estimated deltas (raw + payable under ref-blocking rules)
-- =========================================================
create or replace function public.pay_timesheet_impact_preview(p_timesheet_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tf record;
  v_ts record;

  v_require_ref boolean;

  v_base jsonb;
  v_base_segments jsonb;
  v_cur_segments jsonb;

  v_segment_ids text[];
  v_seg_id text;

  v_cur_pay numeric;
  v_cur_excl boolean;
  v_cur_ref text;

  v_base_pay numeric;
  v_base_excl boolean;

  v_cur_payable numeric;
  v_base_payable numeric;

  v_seg_delta_raw numeric;
  v_seg_delta_payable numeric;

  v_seg_sum_raw numeric := 0;
  v_seg_sum_payable numeric := 0;

  v_base_add numeric := 0;
  v_cur_add numeric := 0;

  v_base_exp numeric := 0;
  v_cur_exp numeric := 0;

  v_base_adj numeric := 0;
  v_cur_adj numeric := 0;

  v_delta_raw numeric := 0;
  v_delta_payable numeric := 0;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_id is required';
  end if;

  select
    tf.timesheet_id,
    tf.client_id,
    tf.invoice_breakdown_json,
    tf.total_pay_ex_vat,
    tf.additional_pay_ex_vat,
    tf.expenses_pay_ex_vat,
    tf.travel_pay_ex_vat,
    tf.accommodation_pay_ex_vat,
    tf.other_pay_ex_vat,
    tf.mileage_pay_ex_vat
  into v_tf
  from public.timesheets_financials tf
  where tf.timesheet_id = p_timesheet_id
    and tf.is_current = true
  limit 1;

  if v_tf.timesheet_id is null then
    raise exception 'timesheet_financials not found for timesheet';
  end if;

  select
    ts.timesheet_id,
    ts.contract_id,
    ts.reference_number
  into v_ts
  from public.timesheets ts
  where ts.timesheet_id = p_timesheet_id
    and ts.is_current = true
  limit 1;

  select
    coalesce(
      case when ct.overrideclientsettings then ct.require_reference_to_pay end,
      cs.pay_reference_required,
      false
    )
  into v_require_ref
  from public.contracts ct
  left join public.client_settings cs on cs.client_id = v_tf.client_id
  where ct.id = v_ts.contract_id
  limit 1;

  select coalesce(tps.last_settled_snapshot_json, '{}'::jsonb)
  into v_base
  from public.timesheet_pay_state tps
  where tps.timesheet_id = p_timesheet_id
  limit 1;

  v_base_segments := coalesce(v_base->'segments','[]'::jsonb);

  -- current segments
  if v_tf.invoice_breakdown_json is not null
     and jsonb_typeof(v_tf.invoice_breakdown_json) = 'object'
     and upper(coalesce(v_tf.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
     and jsonb_typeof(v_tf.invoice_breakdown_json->'segments') = 'array' then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
          'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
          'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean,false),
          'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), '')
        )
      ),
      '[]'::jsonb
    )
    into v_cur_segments
    from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') seg
    where seg is not null and jsonb_typeof(seg)='object';
  else
    v_cur_segments := jsonb_build_array(
      jsonb_build_object(
        'segment_id', ('ts:' || p_timesheet_id::text),
        'pay_amount', round(coalesce(v_tf.total_pay_ex_vat,0),2),
        'exclude_from_pay', false,
        'ref_num', nullif(btrim(coalesce(v_ts.reference_number,'')), '')
      )
    );
  end if;

  select coalesce(array_agg(distinct sid), array[]::text[])
  into v_segment_ids
  from (
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_cur_segments) s
    where s is not null and jsonb_typeof(s)='object'
    union
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_base_segments) s
    where s is not null and jsonb_typeof(s)='object'
  ) u
  where u.sid is not null;

  foreach v_seg_id in array v_segment_ids
  loop
    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
      nullif(btrim(coalesce(s->>'ref_num','')), '') as ref_num
    into v_cur_pay, v_cur_excl, v_cur_ref
    from jsonb_array_elements(v_cur_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_cur_pay is null then v_cur_pay := 0; end if;
    if v_cur_excl is null then v_cur_excl := false; end if;

    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay
    into v_base_pay, v_base_excl
    from jsonb_array_elements(v_base_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_base_pay is null then v_base_pay := 0; end if;
    if v_base_excl is null then v_base_excl := false; end if;

    v_cur_payable := case when v_cur_excl then 0 else v_cur_pay end;
    v_base_payable := case when v_base_excl then 0 else v_base_pay end;

    v_seg_delta_raw := round(v_cur_payable - v_base_payable, 2);

    v_seg_delta_payable := v_seg_delta_raw;
    if v_require_ref = true
       and v_cur_excl = false
       and nullif(btrim(coalesce(v_cur_ref,'')),'') is null
       and v_seg_delta_raw > 0 then
      v_seg_delta_payable := 0;
    end if;

    v_seg_sum_raw := round(v_seg_sum_raw + v_seg_delta_raw, 2);
    v_seg_sum_payable := round(v_seg_sum_payable + v_seg_delta_payable, 2);
  end loop;

  v_base_add := round(coalesce(nullif(v_base->>'additional_pay_ex_vat','')::numeric,0),2);
  v_cur_add := round(coalesce(v_tf.additional_pay_ex_vat,0),2);

  v_base_exp :=
    round(coalesce(nullif(v_base #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2);

  v_cur_exp :=
    round(coalesce(v_tf.expenses_pay_ex_vat,0),2)
    + round(coalesce(v_tf.travel_pay_ex_vat,0),2)
    + round(coalesce(v_tf.accommodation_pay_ex_vat,0),2)
    + round(coalesce(v_tf.other_pay_ex_vat,0),2)
    + round(coalesce(v_tf.mileage_pay_ex_vat,0),2);

  -- baseline adjustments sum
  select round(coalesce(sum(coalesce(nullif(a->>'delta_pay_ex_vat','')::numeric,0)),0),2)
  into v_base_adj
  from jsonb_array_elements(coalesce(v_base->'adjustments','[]'::jsonb)) a;

  -- current adjustments sum
  select round(coalesce(sum(coalesce(a.delta_pay_ex_vat,0)),0),2)
  into v_cur_adj
  from public.ts_pay_adjustments a
  where a.timesheet_id = p_timesheet_id
    and a.as_advance = false;

  v_delta_raw := round((v_seg_sum_raw + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);
  v_delta_payable := round((v_seg_sum_payable + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);

  return jsonb_build_object(
    'ok', true,
    'timesheet_id', p_timesheet_id::text,
    'require_reference_to_pay', v_require_ref,
    'baseline', jsonb_build_object(
      'segments_payable_ex_vat', round(coalesce(v_seg_sum_raw,0) - coalesce(v_seg_sum_raw - v_seg_sum_raw,0),2),
      'additional_pay_ex_vat', v_base_add,
      'expenses_total_pay_ex_vat', v_base_exp,
      'adjustments_total_ex_vat', v_base_adj
    ),
    'current', jsonb_build_object(
      'additional_pay_ex_vat', v_cur_add,
      'expenses_total_pay_ex_vat', v_cur_exp,
      'adjustments_total_ex_vat', v_cur_adj
    ),
    'delta', jsonb_build_object(
      'raw_delta_ex_vat', v_delta_raw,
      'payable_delta_ex_vat', v_delta_payable
    )
  );
end;
$$;





-- =========================================================
-- A4.6 pay_settle_monzo(p_pay_batch_id, p_actor_user_id, p_confirmed bool)
-- =========================================================
CREATE OR REPLACE FUNCTION public.pay_settle_monzo(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_confirmed boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_batch record;
  v_guard_json jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay_batch_id is required';
  END IF;

  IF p_confirmed IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'CONFIRM_REQUIRED';
  END IF;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.banking_system_snapshot,
    public.pay_batches.external_paye_system_snapshot,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.settlement_confirmation_json
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id
  FOR UPDATE;

  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay batch % not found', p_pay_batch_id;
  END IF;

  v_guard_json := jsonb_build_object(
    'error', 'USE_PAYMENT_CORRECTION_FLOW',
    'code', 'USE_PAYMENT_CORRECTION_FLOW',
    'message', 'pay_settle_monzo is deprecated because it bypasses the generic bank event ledger, no-money unwind, settled reversal, and remittance timing flow. Use pay_bank_event_ingest plus pay_settle_rail/pay_settle_manual_confirm instead.',
    'pay_batch_id', p_pay_batch_id::text,
    'status', v_batch.status,
    'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
    'banking_system_snapshot', v_batch.banking_system_snapshot,
    'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'execution_commit_state', v_batch.execution_commit_state,
    'execution_commit_ref', v_batch.execution_commit_ref,
    'execution_committed_at_utc', CASE WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch.execution_committed_at_utc::text END
  );

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_MONZO_BLOCKED_USE_GENERIC_RAIL_FLOW',
      v_guard_json,
      'pay_batch',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RAISE EXCEPTION '%', v_guard_json::text;
END;
$$;


