-- A4.9 pay_batches_list / pay_batch_get
-- =========================================================








DROP FUNCTION IF EXISTS public.pay_batch_get(uuid);




DROP FUNCTION IF EXISTS public.pay_batch_get(uuid, uuid);











create or replace function public.pay_batch_get(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_detail_mode text DEFAULT 'AUTO'::text,
  p_recommended_page_size integer DEFAULT NULL::integer
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch record;
  v_candidates jsonb := '[]'::jsonb;
  v_transfers jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;

  -- ✅ NEW: derived batch kind + channels
  v_batch_kind text := null;
  v_pay_channels_present jsonb := '[]'::jsonb;

  -- ✅ NEW: child modal support payloads
  v_candidate_breakdown jsonb := '[]'::jsonb;
  v_candidate_lines jsonb := '[]'::jsonb;
  v_finance_case_groups jsonb := '[]'::jsonb;
  v_finance_summaries jsonb := '{}'::jsonb;
