          'bulk_reference', v_batch.bulk_reference
        )
      ),
      'candidates', v_candidates,
      'transfers', v_transfers,
      'items', v_items
    );
end;
$$;















DROP FUNCTION IF EXISTS public.pay_batches_list(integer, integer, text);

DROP FUNCTION IF EXISTS public.pay_batches_list(integer, integer, text, uuid);


CREATE OR REPLACE FUNCTION public.pay_batches_list(p_limit integer DEFAULT 5, p_offset integer DEFAULT 0, p_status text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_display_mode text DEFAULT 'LIGHT'::text, p_include_diagnostics boolean DEFAULT false, p_include_alerts boolean DEFAULT false, p_include_correction_summary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 5), 200));
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_status text := UPPER(NULLIF(BTRIM(COALESCE(p_status, '')), ''));
  v_display_mode text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_display_mode, 'LIGHT')), ''), '-', '_'));
  v_include_diagnostics boolean := false;
  v_include_alerts boolean := COALESCE(p_include_alerts, false);
  v_include_correction_summary boolean := false;
  v_rows jsonb := '[]'::jsonb;
  v_returned_count integer := 0;
  v_total_count integer := 0;
  v_has_more boolean := false;
  v_next_offset integer := NULL::integer;
  v_previous_offset integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_cached_alert_summary jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('BATCH_LIST');

  IF v_display_mode IS NULL THEN
    v_display_mode := 'LIGHT';
  END IF;

  -- This list RPC is always the safe display path.  Diagnostic/correction
  -- enrichment requests are intentionally ignored here; explicit diagnostic
  -- routes must use their own RPCs.  Cached alert signal data may still be
  -- included when requested because it is read from banking_alert_display_summary.
  v_include_diagnostics := false;
  v_include_correction_summary := false;

  IF v_display_mode NOT IN ('LIGHT', 'SUMMARY', 'BOOTSTRAP') THEN
    RAISE EXCEPTION 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED',
              'display_mode', v_display_mode,
              'message', 'pay_batches_list only supports LIGHT/SUMMARY/BOOTSTRAP display modes on this safe list path.'
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  IF v_include_alerts AND p_actor_user_id IS NOT NULL THEN
    SELECT
      COALESCE(alert_summary.alert_hash, 'banking_alert_signal:v3:' || MD5('')),
      COALESCE(alert_summary.summary_hash, 'banking_alert_summary:v3:' || MD5('')),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label,
      COALESCE(alert_summary.summary_json, '{}'::jsonb)
    INTO
      v_cached_alert_hash,
      v_cached_summary_hash,
      v_cached_unacknowledged_count,
      v_cached_highest_severity,
      v_cached_highest_label,
      v_cached_alert_summary
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = p_actor_user_id;

    IF NOT FOUND THEN
      v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_cached_unacknowledged_count := 0;
      v_cached_highest_severity := NULL::text;
      v_cached_highest_label := NULL::text;
      v_cached_alert_summary := '{}'::jsonb;
    END IF;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_total_count
  FROM public.pay_batches AS pay_batch_count
  WHERE v_status IS NULL
     OR UPPER(COALESCE(pay_batch_count.status, '')) = v_status;

  WITH page_source AS (
    SELECT
      pay_batch_row.id,
      pay_batch_row.pay_date,
      pay_batch_row.authoritative_payment_date,
      pay_batch_row.authoritative_payment_date_source,
      pay_batch_row.created_at_utc,
      pay_batch_row.created_by_user_id,
      pay_batch_row.status,
      pay_batch_row.banking_system_snapshot,
      pay_batch_row.external_paye_system_snapshot,
      pay_batch_row.batch_kind_fixed,
      pay_batch_row.source_workbench_session_id,
      pay_batch_row.source_snapshot_run_id,
      pay_batch_row.source_session_version,
      pay_batch_row.execution_commit_state,
      pay_batch_row.execution_commit_ref,
      pay_batch_row.execution_committed_at_utc,
      pay_batch_row.rail_provider_snapshot,
      pay_batch_row.rail_env_snapshot,
      pay_batch_row.schedule_kind,
      pay_batch_row.scheduled_at_utc,
      pay_batch_row.funding_account_ref,
      pay_batch_row.total_bank_out,
      pay_batch_row.total_debt_created,
      pay_batch_row.freshness_validation_status,
      pay_batch_row.freshness_checked_at_utc,
      pay_batch_row.freshness_result_hash,
      display_summary.batch_status AS display_batch_status,
      display_summary.batch_kind AS display_batch_kind,
      display_summary.candidate_count,
      display_summary.item_count,
      display_summary.transfer_count,
      display_summary.total_payable,
      display_summary.total_bank_out AS display_total_bank_out,
      display_summary.execution_commit_state AS display_execution_commit_state,
      display_summary.rail_provider_label,
      display_summary.rail_env_label,
      display_summary.issue_summary_counts,
      display_summary.latest_operation_id,
      display_summary.latest_operation_status,
      display_summary.latest_operation_phase,
      active_execution_operation.id AS active_payment_operation_id,
      active_execution_operation.operation_type AS active_payment_operation_type,
      active_execution_operation.status AS active_payment_operation_status,
      active_execution_operation.phase AS active_payment_operation_phase,
      active_execution_operation.runner_state AS active_payment_operation_runner_state,
      active_execution_operation.requires_user_action AS active_payment_operation_requires_user_action,
      active_execution_operation.resume_reason AS active_payment_operation_resume_reason,
      active_execution_operation.updated_at_utc AS active_payment_operation_updated_at_utc,
      CASE
        WHEN active_execution_operation.id IS NULL THEN NULL::jsonb
        ELSE jsonb_strip_nulls(jsonb_build_object(
          'operation_id', active_execution_operation.id::text,
          'id', active_execution_operation.id::text,
          'operation_type', active_execution_operation.operation_type,
          'status', active_execution_operation.status,
          'phase', active_execution_operation.phase,
          'runner_state', active_execution_operation.runner_state,
          'requires_user_action', active_execution_operation.requires_user_action,
          'resume_reason', active_execution_operation.resume_reason,
          'pay_batch_id', active_execution_operation.pay_batch_id::text,
          'workbench_session_id', CASE WHEN active_execution_operation.workbench_session_id IS NULL THEN NULL::text ELSE active_execution_operation.workbench_session_id::text END,
          'progress_json', active_execution_operation.progress_json,
          'updated_at_utc', active_execution_operation.updated_at_utc
        ))
      END AS active_payment_operation,
      display_summary.display_label,
      display_summary.stale_summary_json,
      display_summary.freshness_validation_status AS display_freshness_validation_status,
      display_summary.freshness_checked_at_utc AS display_freshness_checked_at_utc,
      display_summary.freshness_result_hash AS display_freshness_result_hash,
      display_summary.summary_version,
      display_summary.updated_at_utc AS summary_updated_at_utc,
      COALESCE(batch_signal.version, 0) AS live_signal_version,
      COALESCE(batch_signal.payment_status_version, 0) AS payment_status_version,
      COALESCE(batch_signal.correction_progress_version, 0) AS correction_progress_version,
      COALESCE(batch_signal.alert_version, 0) AS alert_version,
      COALESCE(batch_signal.overview_version, 0) AS overview_version,
      batch_signal.last_status_hash,
      batch_signal.last_alert_hash,
      batch_signal.last_changed_at_utc,
      batch_signal.last_payment_status_changed_at_utc,
      batch_signal.last_correction_progress_changed_at_utc,
      batch_signal.last_alert_changed_at_utc,
      batch_signal.last_change_reason,
      batch_signal.last_change_source,
      COALESCE(batch_signal.last_change_scope_json, '{}'::jsonb) AS last_change_scope_json,
      COALESCE(batch_signal.last_changed_candidate_ids, '[]'::jsonb) AS last_changed_candidate_ids,
      COALESCE(batch_signal.last_changed_pay_batch_item_ids, '[]'::jsonb) AS last_changed_pay_batch_item_ids,
      COALESCE(batch_signal.last_changed_transfer_ids, '[]'::jsonb) AS last_changed_transfer_ids,
      ROW_NUMBER() OVER (ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC) AS row_ordinal
    FROM public.pay_batches AS pay_batch_row
    LEFT JOIN public.pay_batch_display_summary AS display_summary
      ON display_summary.pay_batch_id = pay_batch_row.id
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = pay_batch_row.id
    LEFT JOIN LATERAL (
      SELECT active_operation.*
      FROM public.banking_pay_operations AS active_operation
      WHERE active_operation.pay_batch_id = pay_batch_row.id
        AND upper(BTRIM(COALESCE(active_operation.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
        AND upper(BTRIM(COALESCE(active_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'RUNNABLE', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'WAITING_FOR_PROVIDER', 'AWAITING_PROVIDER', 'WAITING_USER', 'WAITING_USER_REVIEW', 'REVIEW_REQUIRED')
      ORDER BY
        CASE upper(BTRIM(COALESCE(active_operation.status, '')))
          WHEN 'RUNNING' THEN 0
          WHEN 'WAITING' THEN 1
          WHEN 'RUNNABLE' THEN 2
          WHEN 'QUEUED' THEN 3
          WHEN 'CONTINUING' THEN 4
          WHEN 'WAITING_RETRY' THEN 5
          WHEN 'WAITING_AUTHORISATION' THEN 6
          WHEN 'WAITING_AUTHORIZATION' THEN 6
          WHEN 'AWAITING_AUTHORISATION' THEN 6
          WHEN 'AWAITING_AUTHORIZATION' THEN 6
          WHEN 'WAITING_PROVIDER' THEN 7
          WHEN 'WAITING_FOR_PROVIDER' THEN 7
          WHEN 'AWAITING_PROVIDER' THEN 7
          WHEN 'WAITING_USER' THEN 8
          WHEN 'WAITING_USER_REVIEW' THEN 8
          WHEN 'REVIEW_REQUIRED' THEN 9
          ELSE 10
        END,
        active_operation.updated_at_utc DESC NULLS LAST,
        active_operation.created_at_utc DESC NULLS LAST,
        active_operation.id DESC
      LIMIT 1
    ) AS active_execution_operation ON true
    WHERE v_status IS NULL
       OR UPPER(COALESCE(pay_batch_row.status, '')) = v_status
    ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC
    LIMIT v_limit
    OFFSET v_offset
  ),
  page_json AS (
    SELECT
      page_source.row_ordinal,
      jsonb_strip_nulls(
        jsonb_build_object(
          'id', page_source.id::text,
          'pay_date', CASE WHEN page_source.pay_date IS NULL THEN NULL::text ELSE page_source.pay_date::text END,
          'authoritative_payment_date', CASE WHEN page_source.authoritative_payment_date IS NULL THEN NULL::text ELSE page_source.authoritative_payment_date::text END,
          'authoritative_payment_date_source', page_source.authoritative_payment_date_source,
          'created_at_utc', page_source.created_at_utc,
          'created_by_user_id', CASE WHEN page_source.created_by_user_id IS NULL THEN NULL::text ELSE page_source.created_by_user_id::text END,
          'status', page_source.status,
          'db_status', page_source.status,
          'batch_kind_fixed', page_source.batch_kind_fixed,
          'batch_kind', COALESCE(page_source.display_batch_kind, page_source.batch_kind_fixed),
          'display_label', page_source.display_label,
          'banking_system_snapshot', page_source.banking_system_snapshot,
          'external_paye_system_snapshot', page_source.external_paye_system_snapshot,
          'source_workbench_session_id', CASE WHEN page_source.source_workbench_session_id IS NULL THEN NULL::text ELSE page_source.source_workbench_session_id::text END,
          'source_snapshot_run_id', CASE WHEN page_source.source_snapshot_run_id IS NULL THEN NULL::text ELSE page_source.source_snapshot_run_id::text END,
          'source_session_version', page_source.source_session_version,
          'execution_commit_state', COALESCE(page_source.display_execution_commit_state, page_source.execution_commit_state),
          'execution_commit_ref', page_source.execution_commit_ref,
          'execution_committed_at_utc', page_source.execution_committed_at_utc
        )
        || jsonb_build_object(
          'rail_provider_snapshot', COALESCE(page_source.rail_provider_label, page_source.rail_provider_snapshot),
          'rail_env_snapshot', COALESCE(page_source.rail_env_label, page_source.rail_env_snapshot),
          'schedule_kind', page_source.schedule_kind,
          'scheduled_at_utc', page_source.scheduled_at_utc,
          'funding_account_ref', page_source.funding_account_ref,
          'total_bank_out', COALESCE(page_source.display_total_bank_out, page_source.total_bank_out, 0),
          'total_debt_created', COALESCE(page_source.total_debt_created, 0),
          'candidate_count', COALESCE(page_source.candidate_count, 0),
          'item_count', COALESCE(page_source.item_count, 0),
          'transfer_count', COALESCE(page_source.transfer_count, 0),
          'total_payable', COALESCE(page_source.total_payable, 0),
          'latest_operation_id', CASE WHEN page_source.latest_operation_id IS NULL THEN NULL::text ELSE page_source.latest_operation_id::text END,
          'latest_operation_status', page_source.latest_operation_status,
          'latest_operation_phase', page_source.latest_operation_phase,
          'active_payment_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_payment_operation_type', page_source.active_payment_operation_type,
          'active_payment_operation_status', page_source.active_payment_operation_status,
          'active_payment_operation_phase', page_source.active_payment_operation_phase,
          'active_payment_operation_runner_state', page_source.active_payment_operation_runner_state,
          'active_payment_operation_requires_user_action', page_source.active_payment_operation_requires_user_action,
          'active_payment_operation_resume_reason', page_source.active_payment_operation_resume_reason,
          'active_payment_operation_updated_at_utc', page_source.active_payment_operation_updated_at_utc,
          'active_payment_operation', page_source.active_payment_operation,
          'active_payment_execute_operation', page_source.active_payment_operation,
          'payment_execute_operation', page_source.active_payment_operation,
          'active_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_operation_type', page_source.active_payment_operation_type,
          'active_operation_status', page_source.active_payment_operation_status,
          'active_operation_phase', page_source.active_payment_operation_phase,
          'active_operation', page_source.active_payment_operation,
          'issue_summary_counts', COALESCE(page_source.issue_summary_counts, '{}'::jsonb),
          'stale_summary_json', COALESCE(page_source.stale_summary_json, '{}'::jsonb),
          'freshness_validation_status', COALESCE(page_source.display_freshness_validation_status, page_source.freshness_validation_status),
          'freshness_checked_at_utc', COALESCE(page_source.display_freshness_checked_at_utc, page_source.freshness_checked_at_utc),
          'freshness_result_hash', COALESCE(page_source.display_freshness_result_hash, page_source.freshness_result_hash),
          'summary_version', COALESCE(page_source.summary_version, 0),
          'summary_updated_at_utc', page_source.summary_updated_at_utc
        )
        || jsonb_build_object(
          'live_signal_version', page_source.live_signal_version,
          'payment_status_version', page_source.payment_status_version,
          'correction_progress_version', page_source.correction_progress_version,
          'alert_version', page_source.alert_version,
          'overview_version', page_source.overview_version,
          'last_status_hash', page_source.last_status_hash,
          'last_alert_hash', page_source.last_alert_hash,
          'last_changed_at_utc', page_source.last_changed_at_utc,
          'last_payment_status_changed_at_utc', page_source.last_payment_status_changed_at_utc,
          'last_correction_progress_changed_at_utc', page_source.last_correction_progress_changed_at_utc,
          'last_alert_changed_at_utc', page_source.last_alert_changed_at_utc,
          'last_change_reason', page_source.last_change_reason,
          'last_change_source', page_source.last_change_source,
          'last_change_scope_json', COALESCE(page_source.last_change_scope_json, '{}'::jsonb),
          'last_changed_candidate_ids', COALESCE(page_source.last_changed_candidate_ids, '[]'::jsonb),
          'last_changed_pay_batch_item_ids', COALESCE(page_source.last_changed_pay_batch_item_ids, '[]'::jsonb),
          'last_changed_transfer_ids', COALESCE(page_source.last_changed_transfer_ids, '[]'::jsonb),
          'draft_stale_hint', LOWER(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_hint', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'draft_stale_reason', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_reason', '')), ''),
          'draft_stale_policy_x_authority_scope', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'policy_x_authority_scope', '')), ''),
          'diagnostics_deferred', true,
          'diagnostics_included', false,
          'alerts_included', false,
          'correction_summary_included', v_include_correction_summary,
          'display_mode', v_display_mode
        )
      ) AS row_json
    FROM page_source
  )
  SELECT
    COALESCE(jsonb_agg(page_json.row_json ORDER BY page_json.row_ordinal), '[]'::jsonb),
    (SELECT COUNT(*)::integer FROM page_source)
  INTO
    v_rows,
    v_returned_count
  FROM page_json;

  v_returned_count := COALESCE(v_returned_count, 0);
  v_total_count := COALESCE(v_total_count, 0);
  v_has_more := (v_offset + v_returned_count) < v_total_count;
  v_next_offset := CASE WHEN v_has_more THEN v_offset + v_limit ELSE NULL::integer END;
  v_previous_offset := CASE WHEN v_offset > 0 THEN GREATEST(0, v_offset - v_limit) ELSE NULL::integer END;

  RETURN jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'display_mode', v_display_mode,
      'limit', v_limit,
      'offset', v_offset,
      'next_offset', v_next_offset,
      'previous_offset', v_previous_offset,
      'has_more', v_has_more,
      'returned_count', v_returned_count,
      'count', v_total_count,
      'total_count', v_total_count,
      'known_total_count', true,
      'rows', COALESCE(v_rows, '[]'::jsonb),
      'items', COALESCE(v_rows, '[]'::jsonb),
      'diagnostics_included', false,
      'diagnostics_requested', v_include_diagnostics,
      'alerts_requested', v_include_alerts,
      'correction_summary_requested', v_include_correction_summary
    )
    || jsonb_build_object(
      'banking_alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE NULL::text END,
      'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE NULL::text END,
      'banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'grouped_banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'banking_highest_alert_severity', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_severity, '') ELSE '' END,
      'banking_highest_alert_label', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_label, '') ELSE '' END,
      'banking_alerts', '[]'::jsonb,
      'banking_alert_summary', jsonb_build_object(
        'ok', true,
        'cached', true,
        'alerts', '[]'::jsonb,
        'unacknowledged_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
        'highest_severity', CASE WHEN v_include_alerts THEN v_cached_highest_severity ELSE NULL::text END,
        'highest_label', CASE WHEN v_include_alerts THEN v_cached_highest_label ELSE NULL::text END,
        'alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE 'banking_alert_signal:v3:' || MD5('') END,
        'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE 'banking_alert_summary:v3:' || MD5('') END,
        'summary_json', CASE WHEN v_include_alerts THEN COALESCE(v_cached_alert_summary, '{}'::jsonb) ELSE '{}'::jsonb END
      )
    )
  );
END;
$function$;




create or replace function public.pay_unpay_batch(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_reason text,
  p_force boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_batch record;
  v_timesheet_id uuid;

  v_aff_timesheets uuid[] := array[]::uuid[];

  v_latest record;

  v_patch record;
  v_old_outstanding numeric;
  v_old_schedule jsonb;
  v_old_next_due date;

  v_component_restore record;
  v_component_before_json jsonb;
  v_component_after_json jsonb;

  v_reverted_adv int := 0;
  v_removed_hist int := 0;
  v_rebuilt_states int := 0;
  v_restored_components int := 0;
  v_released_reservations int := 0;
  v_changed_channel_audit record;
  v_changed_channel_audit_before_json jsonb := null;
  v_changed_channel_audit_after_json jsonb := null;
  v_changed_channel_unwound_ct int := 0;
  v_correction_flow_guard jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if (
    upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
    or nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') is not null
    or v_batch.execution_committed_at_utc is not null
    or exists (
      select 1
      from public.pay_bank_transfers as pbt_guard
      where pbt_guard.pay_batch_id = p_pay_batch_id
        and (
          nullif(btrim(coalesce(pbt_guard.rail_tx_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.request_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.payment_reference, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.rail_state, '')), '') is not null
          or coalesce(pbt_guard.rail_meta_json, '{}'::jsonb) <> '{}'::jsonb
          or pbt_guard.completed_at_utc is not null
          or upper(btrim(coalesce(pbt_guard.status, ''))) in ('COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')
          or nullif(btrim(coalesce(pbt_guard.failed_reason, '')), '') is not null
          or upper(btrim(coalesce(pbt_guard.rail_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED','COMPLETED','SETTLED','PAID','EXECUTED')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'completed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'failed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'declined', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'rejected', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'returned', 'false'))) in ('true','1','yes','y','on')
        )
    )
    or exists (select 1 from public.pay_bank_transfer_events as pbte_guard where pbte_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.timesheet_pay_state_history as tpsh_guard where tpsh_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.pay_payment_correction_requests as ppcr_guard where ppcr_guard.pay_batch_id = p_pay_batch_id and ppcr_guard.status not in ('REJECTED','CANCELLED'))
    or exists (select 1 from public.pay_payment_correction_items as ppci_guard where ppci_guard.pay_batch_id = p_pay_batch_id)
  ) then
    v_correction_flow_guard := jsonb_build_object(
      'error', 'USE_PAYMENT_CORRECTION_FLOW',
      'code', 'USE_PAYMENT_CORRECTION_FLOW',
      'message', 'pay_unpay_batch is restricted to legacy/admin no-bank-evidence batches. Use the payment correction flow for submitted, failed, settled, returned, or corrected batches.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end
    );

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_UNPAY_BATCH_BLOCKED_USE_CORRECTION_FLOW',
        v_correction_flow_guard,
        'pay_batch',
        p_pay_batch_id::text,
        null::jsonb,
        null::text,
        null::text,
        null::text
      );
    exception when others then
      null;
    end;

    raise exception '%', v_correction_flow_guard::text;
  end if;

  if v_batch.status in
 ('SETTLED','PARTIAL') and p_force is distinct from true then
    raise exception 'UNPAY_REQUIRES_FORCE_FOR_SETTLED_BATCH';
  end if;

  -- Revert finance-case header patches first so header totals are restored
  for v_patch in
    select
      pap.advance_id,
      pap.old_outstanding_amount,
      pap.old_schedule_json,
      pap.old_next_due_week_start
    from public.pay_advance_patches pap
    where pap.pay_batch_id = p_pay_batch_id
  loop
    v_old_outstanding := v_patch.old_outstanding_amount;
    v_old_schedule := v_patch.old_schedule_json;
    v_old_next_due := v_patch.old_next_due_week_start;

    update public.pay_advances pa
    set
      outstanding_amount = v_old_outstanding,
      schedule_json = v_old_schedule,
      next_due_week_start = v_old_next_due,
      status = case
        when coalesce(v_old_outstanding, 0) <= 0 then 'PAID_OFF'::public.pay_advance_status_enum
        else 'ACTIVE'::public.pay_advance_status_enum
      end,
      updated_at = v_now
    where pa.id = v_patch.advance_id;

    v_reverted_adv := v_reverted_adv + 1;
  end loop;

  -- Restore component-level remainders from frozen snapshots on batch items first,
  -- then fall back to reservation snapshots only for components that had no batch item snapshot.
  for v_component_restore in
    with item_component_restore as (
      select
        pbi.finance_case_id,
        pbi.finance_component_id,
        round(
          sum(
            coalesce(
              pbi.frozen_source_amount,
              case
                when pbi.frozen_component_snapshot_json ? 'frozen_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'frozen_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'frozen_source_amount')::numeric
                else null::numeric
              end,
              case
                when pbi.frozen_component_snapshot_json ? 'reserved_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'reserved_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'reserved_source_amount')::numeric
                else null::numeric
              end,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.finance_component_id is not null
      group by
        pbi.finance_case_id,
        pbi.finance_component_id
    ),
    reservation_component_restore as (
      select
        par.finance_case_id,
        par.finance_component_id,
        round(
          sum(
            coalesce(
              par.reserved_source_amount,
              par.reserved_amount,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_advance_reservations par
      where par.pay_batch_id = p_pay_batch_id
        and par.finance_component_id is not null
        and par.status in ('RESERVED','COMMITTED','SETTLED')
      group by
        par.finance_case_id,
        par.finance_component_id
    ),
    combined_restore as (
      select
        icr.finance_case_id,
        icr.finance_component_id,
        icr.restore_source_amount
      from item_component_restore icr

      union all

      select
        rcr.finance_case_id,
        rcr.finance_component_id,
        rcr.restore_source_amount
      from reservation_component_restore rcr
      where not exists (
        select 1
        from item_component_restore icr2
        where icr2.finance_case_id is not distinct from rcr.finance_case_id
          and icr2.finance_component_id = rcr.finance_component_id
      )
    )
    select
      cr.finance_case_id,
      cr.finance_component_id,
      cr.restore_source_amount,
      pfc.source_amount,
      pfc.remaining_source_amount,
      pfc.closed_at_utc,
      pfc.classification,
      pfc.source_pay_method,
      pfc.saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      pfc.stale_reason
    from combined_restore cr
    join public.pay_finance_case_components pfc
      on pfc.id = cr.finance_component_id
    where cr.restore_source_amount > 0
    order by
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc,
      pfc.id
  loop
    select jsonb_build_object(
      'finance_component_id', v_component_restore.finance_component_id::text,
      'classification', v_component_restore.classification::text,
      'source_pay_method', v_component_restore.source_pay_method,
      'saved_target_pay_method', v_component_restore.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_restore.saved_resolution_mode is null then null else v_component_restore.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_restore.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_restore.saved_resolution_result_json,
      'stale_reason', v_component_restore.stale_reason,
      'source_amount', round(coalesce(v_component_restore.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_restore.remaining_source_amount, 0), 2),
      'closed_at_utc', v_component_restore.closed_at_utc
    )
    into v_component_before_json;

    update public.pay_finance_case_components pfc
    set
      remaining_source_amount = least(
        round(coalesce(pfc.source_amount, 0), 2),
        round(coalesce(pfc.remaining_source_amount, 0), 2) + round(coalesce(v_component_restore.restore_source_amount, 0), 2)
      )::numeric(12,2),
      closed_at_utc = null,
      updated_at_utc = v_now
    where pfc.id = v_component_restore.finance_component_id
    returning jsonb_build_object(
      'finance_component_id', pfc.id::text,
      'classification', pfc.classification::text,
      'source_pay_method', pfc.source_pay_method,
      'saved_target_pay_method', pfc.saved_target_pay_method,
      'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
      'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
      'saved_resolution_result_json', pfc.saved_resolution_result_json,
      'stale_reason', pfc.stale_reason,
      'source_amount', round(coalesce(pfc.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
      'closed_at_utc', pfc.closed_at_utc
    )
    into v_component_after_json;

    insert into public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_component_restore.finance_case_id,
      v_component_restore.finance_component_id,
      'COMPONENT_RESTORED_ON_UNPAY',
      v_now,
      p_actor_user_id,
      p_pay_batch_id,
      null,
      v_component_before_json,
      v_component_after_json,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'Restored finance component remainder from frozen batch-item/reservation snapshot during unpay.'
    );

    v_restored_components := v_restored_components + 1;
  end loop;

  -- Release any reservations tied to the batch so finance cases remain open correctly.
  update public.pay_advance_reservations par
  set
    status = 'RELEASED',
    settled_at_utc = null,
    released_at_utc = coalesce(par.released_at_utc, v_now),
    released_reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID')
  where par.pay_batch_id = p_pay_batch_id
    and par.status in ('RESERVED','COMMITTED','SETTLED');

  get diagnostics v_released_reservations = row_count;

  -- Revert LOANS payout status (if this batch paid out loans)
  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    with loan_ids as (
      select distinct
        replace(pbi.source_ref, 'advance:', '')::uuid as loan_id
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and pbi.item_type = 'LOAN_PAYOUT'
        and pbi.is_voided = false
        and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
    )
    update public.pay_advances pa
    set
      payout_status = 'PENDING'::public.pay_advance_payout_status_enum,
      payout_pay_batch_id = null,
      payout_transfer_id = null,
      updated_at = v_now
    from loan_ids li
    where pa.id = li.loan_id
      and pa.advance_kind = 'LOAN'::public.pay_advance_kind_enum
      and pa.payout_pay_batch_id = p_pay_batch_id;
  end if;

  -- Gather affected timesheets from history rows for this batch
  select coalesce(array_agg(distinct h.timesheet_id), array[]::uuid[])
  into v_aff_timesheets
  from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  -- Remove history rows for this batch
  delete from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  get diagnostics v_removed_hist = row_count;

  create temp table if not exists _tmp_unpay_timesheet_pay_display (
    timesheet_id uuid not null primary key,
    pay_batch_id uuid not null,
    settled_at_utc timestamptz not null,
    snapshot_json jsonb not null,
    signature text null,
    summary_pay_status_code text not null,
    summary_pay_icon_code text not null,
    summary_pay_paid_at_utc timestamptz not null,
    summary_net_delta_ex_vat numeric(12,2) not null
  ) on commit drop;

  truncate table _tmp_unpay_timesheet_pay_display;

  insert into _tmp_unpay_timesheet_pay_display(
    timesheet_id,
    pay_batch_id,
    settled_at_utc,
    snapshot_json,
    signature,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_pay_paid_at_utc,
    summary_net_delta_ex_vat
  )
  with affected_timesheets as (
    select distinct unnest(coalesce(v_aff_timesheets, array[]::uuid[])) as timesheet_id
  ),
  latest_history as (
    select distinct on (h.timesheet_id)
      h.timesheet_id,
      h.pay_batch_id,
      h.settled_at_utc,
      h.snapshot_json,
      h.signature
    from public.timesheet_pay_state_history h
    join affected_timesheets affected_history
      on affected_history.timesheet_id = h.timesheet_id
    order by h.timesheet_id, h.settled_at_utc desc, h.id desc
  ),
  affected_ids as (
    select coalesce(array_agg(distinct affected_timesheets.timesheet_id order by affected_timesheets.timesheet_id), array[]::uuid[]) as timesheet_ids
    from affected_timesheets
  ),
  outstanding_components as (
    select
      oc.timesheet_id,
      oc.truth_ex_vat,
      oc.baseline_ex_vat,
      oc.reserved_ex_vat,
      oc.outstanding_ex_vat
    from affected_ids
    cross join lateral public._pay_outstanding_components(affected_ids.timesheet_ids, p_pay_batch_id) oc
  ),
  summary_calc as (
    select
      lh.timesheet_id,
      round(coalesce(sum(coalesce(oc.truth_ex_vat, 0) - coalesce(oc.baseline_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_net_delta_ex_vat,
      round(coalesce(sum(coalesce(oc.reserved_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_reserved_ex_vat,
      round(coalesce(sum(coalesce(oc.outstanding_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_outstanding_ex_vat
    from latest_history lh
    left join outstanding_components oc
      on oc.timesheet_id = lh.timesheet_id
    group by lh.timesheet_id
  )
  select
    lh.timesheet_id,
    lh.pay_batch_id,
    lh.settled_at_utc,
    lh.snapshot_json,
    lh.signature,
    case
      when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'PARTIALLY_PAID'
      when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'PROCESSING'
      else 'PAID'
    end as summary_pay_status_code,
    case
      when coalesce(sc.summary_net_delta_ex_vat, 0) < -0.01 then 'RED_COIN'
      when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'HALF_COIN'
      when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'CLOCK'
      else 'COIN'
    end as summary_pay_icon_code,
    lh.settled_at_utc as summary_pay_paid_at_utc,
    coalesce(sc.summary_net_delta_ex_vat, 0)::numeric(12,2) as summary_net_delta_ex_vat
  from latest_history lh
  left join summary_calc sc
    on sc.timesheet_id = lh.timesheet_id;

  -- Rebuild timesheet_pay_state for affected timesheets
  foreach v_timesheet_id in array v_aff_timesheets
  loop
    select
      tpd.timesheet_id,
      tpd.pay_batch_id,
      tpd.settled_at_utc,
      tpd.snapshot_json,
      tpd.signature,
      tpd.summary_pay_status_code,
      tpd.summary_pay_icon_code,
      tpd.summary_pay_paid_at_utc,
      tpd.summary_net_delta_ex_vat
    into v_latest
    from _tmp_unpay_timesheet_pay_display tpd
    where tpd.timesheet_id = v_timesheet_id
    limit 1;

    if v_latest.timesheet_id is null then
      delete from public.timesheet_pay_state tps
      where tps.timesheet_id = v_timesheet_id;
    else
      insert into public.timesheet_pay_state(
        timesheet_id,
        last_settled_snapshot_json,
        last_settled_signature,
        last_settled_pay_batch_id,
        last_settled_at_utc,
        summary_pay_status_code,
        summary_pay_icon_code,
        summary_pay_paid_at_utc,
        summary_net_delta_ex_vat
      )
      values (
        v_timesheet_id,
        v_latest.snapshot_json,
        v_latest.signature,
        v_latest.pay_batch_id,
        v_latest.settled_at_utc,
        v_latest.summary_pay_status_code,
        v_latest.summary_pay_icon_code,
        v_latest.summary_pay_paid_at_utc,
        v_latest.summary_net_delta_ex_vat
      )
      on conflict (timesheet_id) do update
      set
        last_settled_snapshot_json = excluded.last_settled_snapshot_json,
        last_settled_signature = excluded.last_settled_signature,
        last_settled_pay_batch_id = excluded.last_settled_pay_batch_id,
        last_settled_at_utc = excluded.last_settled_at_utc,
        summary_pay_status_code = excluded.summary_pay_status_code,
        summary_pay_icon_code = excluded.summary_pay_icon_code,
        summary_pay_paid_at_utc = excluded.summary_pay_paid_at_utc,
        summary_net_delta_ex_vat = excluded.summary_net_delta_ex_vat;
    end if;

    v_rebuilt_states := v_rebuilt_states + 1;
  end loop;


  for v_changed_channel_audit in
    with settled_batch_item_portions as (
      select
        pbi.id as pay_batch_item_id,
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id as candidate_id,
        pbc.settled_at_utc as settled_at_utc,
        pbi.timesheet_id as timesheet_id,
        ts.booking_id as booking_id,
        pbi.pay_bank_transfer_id as pay_bank_transfer_id,
        pbi.item_type as item_type,
        pbi.segment_key as segment_key,
        pbi.source_ref as source_ref,
        pbi.description as description,
        upper(coalesce(nullif(btrim(coalesce(pbi.frozen_source_pay_method,'')), ''), '')) as source_pay_channel,
        upper(coalesce(nullif(btrim(coalesce(pbi.pay_channel,'')), ''), nullif(btrim(coalesce(pbi.frozen_target_pay_method,'')), ''), '')) as settled_pay_channel,
        case when pbi.frozen_component_key_type is null then null else pbi.frozen_component_key_type end as component_key_type,
        pbi.frozen_component_key_value as component_key_value,
        case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end as component_classification,
        case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end as resolution_mode,
        pbi.frozen_resolution_payload_json as resolution_payload_json,
        pbi.frozen_resolution_result_json as resolution_result_json,
        pbi.frozen_source_basis_json as frozen_source_basis_json,
        round(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0), 2) as item_source_amount_ex_vat,
        round(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0), 2) as item_settled_amount_ex_vat
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      left join public.timesheets ts
        on ts.timesheet_id = pbi.timesheet_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.item_type <> 'DEBT_CREATED'
        and pbi.timesheet_id is not null
        and pbc.settled_at_utc is not null
    ),
    portion_rows as (
      select
        sbip.pay_batch_item_id,
        sbip.pay_batch_candidate_id,
        sbip.candidate_id,
        sbip.settled_at_utc,
        sbip.timesheet_id,
        sbip.booking_id,
        sbip.pay_bank_transfer_id,
        sbip.source_pay_channel,
        sbip.settled_pay_channel,
        sbip.component_key_type,
        sbip.component_key_value,
        sbip.component_classification,
        sbip.resolution_mode,
        sbip.resolution_payload_json,
        sbip.resolution_result_json,
        sbip.segment_key,
        sbip.source_ref,
        sbip.description,
        pbib.id as pay_batch_item_breakdown_id,
        coalesce(
          nullif(btrim(coalesce(pbib.line_kind,'')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
            when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
            when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            else sbip.item_type
          end
        ) as line_kind,
        nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), '') as bucket_code,
        coalesce(
          nullif(btrim(coalesce(pbib.unit_name, '')), ''),
          nullif(btrim(coalesce(sbip.description, '')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'Timesheet portion'
            when sbip.item_type = 'EXPENSE_DELTA' then 'Expense'
            when sbip.item_type = 'MILEAGE_DELTA' then 'Mileage'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
            when sbip.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit payout'
            else 'Batch item'
          end
        ) as unit_name,
        case
          when pbib.units is not null then round(pbib.units, 4)
          when sbip.frozen_source_basis_json ? 'source_units'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)
          else null::numeric
        end as units,
        case
          when sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6)
          else null::numeric
        end as source_rate,
        case
          when pbib.rate is not null then round(pbib.rate, 6)
          else null::numeric
        end as settled_rate,
        case
          when pbib.units is not null
           and sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round(pbib.units * round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6), 2)
          else sbip.item_source_amount_ex_vat
        end as source_amount_ex_vat,
        round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2) as settled_amount_ex_vat,
        md5(concat_ws('|',
          sbip.pay_batch_item_id::text,
          coalesce(
            nullif(btrim(coalesce(pbib.line_kind,'')), ''),
            case
              when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
              when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
              when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
              when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
              when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
              when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
              when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
              when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
              when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
              else sbip.item_type
            end
          ),
          coalesce(nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), ''), ''),
          coalesce(
            case
              when pbib.units is not null then round(pbib.units, 4)::text
              when sbip.frozen_source_basis_json ? 'source_units'
               and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
                then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)::text
              else null::text
            end,
            ''
          ),
          coalesce(case when pbib.rate is not null then round(pbib.rate, 6)::text else null::text end, ''),
          round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2)::text
        )) as portion_identity_key
      from settled_batch_item_portions sbip
      left join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = sbip.pay_batch_item_id
    )
    select
      pr.pay_batch_item_id,
      pr.pay_batch_item_breakdown_id,
      pr.pay_batch_candidate_id,
      pr.candidate_id,
      pr.settled_at_utc,
      pr.timesheet_id,
      pr.booking_id,
      pr.pay_bank_transfer_id,
      pr.source_pay_channel,
      pr.settled_pay_channel,
      pr.component_key_type,
      pr.component_key_value,
      pr.component_classification,
      pr.resolution_mode,
      pr.resolution_payload_json,
      pr.resolution_result_json,
      pr.segment_key,
      pr.source_ref,
      pr.description,
      pr.line_kind,
      pr.bucket_code,
      pr.unit_name,
      pr.units,
      pr.source_rate,
      pr.settled_rate,
      pr.source_amount_ex_vat,
      pr.settled_amount_ex_vat,
      pr.portion_identity_key
    from portion_rows pr
    where pr.source_pay_channel <> ''
      and pr.settled_pay_channel <> ''
      and pr.source_pay_channel <> pr.settled_pay_channel
    order by
      pr.timesheet_id,
      pr.pay_batch_item_id,
      pr.line_kind,
      pr.bucket_code nulls first,
      pr.unit_name,
      pr.settled_amount_ex_vat desc
  loop
    v_changed_channel_audit_before_json := jsonb_build_object(
      'event_kind', 'TIMESHEET_CHANNEL_CHANGE_PORTION',
      'audit_effective_state', 'SETTLED_ACTIVE',
      'channel_changed', true,
      'timesheet_id', v_changed_channel_audit.timesheet_id::text,
      'booking_id', case when v_changed_channel_audit.booking_id is null then null else v_changed_channel_audit.booking_id::text end,
      'candidate_id', case when v_changed_channel_audit.candidate_id is null then null else v_changed_channel_audit.candidate_id::text end,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_candidate_id', case when v_changed_channel_audit.pay_batch_candidate_id is null then null else v_changed_channel_audit.pay_batch_candidate_id::text end,
      'pay_batch_item_id', case when v_changed_channel_audit.pay_batch_item_id is null then null else v_changed_channel_audit.pay_batch_item_id::text end,
      'pay_batch_item_breakdown_id', case when v_changed_channel_audit.pay_batch_item_breakdown_id is null then null else v_changed_channel_audit.pay_batch_item_breakdown_id::text end,
      'portion_identity_key', v_changed_channel_audit.portion_identity_key,
      'source_pay_channel', v_changed_channel_audit.source_pay_channel,
      'settled_pay_channel', v_changed_channel_audit.settled_pay_channel,
      'component_key_type', v_changed_channel_audit.component_key_type,
      'component_key_value', v_changed_channel_audit.component_key_value,
      'component_classification', v_changed_channel_audit.component_classification,
      'line_kind', v_changed_channel_audit.line_kind,
      'bucket_code', v_changed_channel_audit.bucket_code,
      'unit_name', v_changed_channel_audit.unit_name,
      'units', case when v_changed_channel_audit.units is null then null else round(v_changed_channel_audit.units, 4) end,
      'source_rate', case when v_changed_channel_audit.source_rate is null then null else round(v_changed_channel_audit.source_rate, 6) end,
      'settled_rate', case when v_changed_channel_audit.settled_rate is null then null else round(v_changed_channel_audit.settled_rate, 6) end,
      'source_amount_ex_vat', round(coalesce(v_changed_channel_audit.source_amount_ex_vat, 0), 2),
      'settled_amount_ex_vat', round(coalesce(v_changed_channel_audit.settled_amount_ex_vat, 0), 2),
      'resolution_mode', v_changed_channel_audit.resolution_mode,
      'resolution_selection_kind', case
        when v_changed_channel_audit.resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED'
        when v_changed_channel_audit.resolution_mode in ('MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') then 'MANUAL'
        else null
      end,
      'pay_bank_transfer_id', case when v_changed_channel_audit.pay_bank_transfer_id is null then null else v_changed_channel_audit.pay_bank_transfer_id::text end,
      'segment_key', v_changed_channel_audit.segment_key,
      'source_ref', v_changed_channel_audit.source_ref,
      'description', v_changed_channel_audit.description,
      'settled_at_utc', v_changed_channel_audit.settled_at_utc
    );

    v_changed_channel_audit_after_json := v_changed_channel_audit_before_json || jsonb_build_object(
      'audit_effective_state', 'UNWOUND',
      'unwound_at_utc', v_now,
      'unwind_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'reverses_action', 'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED'
    );

    begin
      perform public._audit_insert(
        'timesheets',
        v_changed_channel_audit.timesheet_id::text,
        'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND',
        v_changed_channel_audit_before_json,
        v_changed_channel_audit_after_json,
        coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
        p_actor_user_id
      );
      v_changed_channel_unwound_ct := v_changed_channel_unwound_ct + 1;
    exception when others then
      null;
    end;
  end loop;

  -- Mark candidate rows as UNPAID
  update public.pay_batch_candidates pbc
  set
    settlement_status = 'UNPAID',
    settled_at_utc = null,
    settled_via = null,
    settled_note = coalesce(nullif(btrim(coalesce(p_reason,'')),''), 'UNPAID'),
    paye_state = case when pbc.paye_state is null then null else 'READY' end
  where pbc.pay_batch_id = p_pay_batch_id;

  -- Mark batch as UNPAID (preserve audit; do not delete)
  update public.pay_batches pb
  set status = 'UNPAID'
  where pb.id = p_pay_batch_id;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'action', 'UNPAID',
    'reverted_advances', v_reverted_adv,
    'restored_components', v_restored_components,
    'released_reservations', v_released_reservations,
    'deleted_history_rows', v_removed_hist,
    'rebuilt_timesheet_states', v_rebuilt_states,
    'timesheet_channel_change_audit', jsonb_build_object(
      'unwound_event_count', v_changed_channel_unwound_ct
    )
  );
end;
$$;






DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean, uuid, jsonb, boolean, boolean);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean, uuid, jsonb, boolean, boolean);

CREATE OR REPLACE FUNCTION public.pay_execute_bank(
  p_pay_batch_id uuid,
  p_pay_channel_scope text,
  p_actor_user_id uuid,
  p_retry_blocked_funds boolean DEFAULT false,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_transfer_scope_ids jsonb DEFAULT NULL::jsonb,
  p_operation_mode boolean DEFAULT false,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_operation_type text := CASE WHEN coalesce(p_retry_blocked_funds, false) THEN 'PAYMENT_RETRY_BLOCKED_FUNDS' ELSE 'PAYMENT_EXECUTE' END;
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_id uuid := p_operation_id;
  v_created boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_progress_light jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_ACTOR_USER_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_ACTOR_USER_ID_REQUIRED', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_SCOPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_SCOPE_INVALID', 'pay_channel_scope', p_pay_channel_scope)::text;
  END IF;

  IF coalesce(p_allow_legacy_unchunked, false) IS TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_LEGACY_INLINE_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_LEGACY_INLINE_DISABLED',
        'message', 'Banking Pay execution is now backend-runner owned and cannot execute inline from the click path.'
      )::text;
  END IF;

  IF p_transfer_scope_ids IS NOT NULL
     AND jsonb_typeof(p_transfer_scope_ids) = 'array'
     AND jsonb_array_length(p_transfer_scope_ids) > 0 THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_ARRAY_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_ARRAY_DISABLED',
        'message', 'pay_execute_bank only starts or reuses a durable backend-owned operation. Transfer scope arrays are not accepted on the hot path.'
      )::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_ACTOR_NOT_ACTIVE'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_ACTOR_NOT_ACTIVE', 'actor_user_id', p_actor_user_id::text)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  IF v_execution_commit_state <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_EXECUTION_BOUNDARY_CROSSED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_strip_nulls(jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_EXECUTION_BOUNDARY_CROSSED',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref_present', nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
        'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END
      ))::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) = 'BLOCKED_FUNDS' AND coalesce(p_retry_blocked_funds, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_RETRY_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_RETRY_REQUIRED', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF coalesce(p_retry_blocked_funds, false) IS TRUE AND upper(btrim(coalesce(v_batch_row.status, ''))) <> 'BLOCKED_FUNDS' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_STATUS_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_STATUS_MISMATCH', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) NOT IN ('DRAFT', 'READY', 'PARTIAL', 'WAITING_BANK_CONFIRM', 'DRAFT_CREATED', 'BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BATCH_STATUS_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BATCH_STATUS_INVALID', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF v_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = v_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_NOT_FOUND', 'operation_id', v_operation_id::text)::text;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_BATCH_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_BATCH_MISMATCH', 'operation_id', v_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
    END IF;

    IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) <> v_operation_type THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_TYPE_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_TYPE_MISMATCH', 'operation_id', v_operation_id::text, 'operation_type', v_operation_row.operation_type, 'expected_operation_type', v_operation_type)::text;
    END IF;
  ELSE
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(operation_row.operation_type, ''))) = v_operation_type
      AND upper(btrim(coalesce(operation_row.status, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED')
      AND upper(btrim(coalesce(operation_row.input_json->>'pay_channel_scope', operation_row.input_json->>'payChannelScope', 'ALL'))) = v_scope
    ORDER BY operation_row.created_at_utc DESC NULLS LAST, operation_row.id DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      v_operation_id := v_operation_row.id;
    END IF;
  END IF;

  IF v_operation_id IS NULL THEN
    INSERT INTO public.banking_pay_operations (
      operation_type,
      status,
      phase,
      actor_user_id,
      pay_batch_id,
      idempotency_key,
      input_json,
      config_json,
      progress_json,
      result_json,
      error_json,
      total_units,
      completed_units,
      failed_units,
      current_chunk_index,
      chunk_count,
      runner_state,
      run_after_utc,
      requires_user_action,
      resume_reason,
      created_at_utc,
      started_at_utc,
      updated_at_utc
    )
    VALUES (
      v_operation_type,
      'RUNNING',
      'PREPARE_TRANSFER_SCOPE',
      p_actor_user_id,
      p_pay_batch_id,
      'pay_execute_bank:' || p_pay_batch_id::text || ':' || v_operation_type || ':' || v_scope,
      jsonb_strip_nulls(jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
        'source_rpc', 'pay_execute_bank'
      )),
      jsonb_build_object('entrypoint', 'pay_execute_bank', 'durable_operation', true, 'backend_owned', true),
      jsonb_build_object(
        'started_from_entrypoint_at_utc', v_now::text,
        'next_required_phase', 'TRANSFER_SCOPE_SEED',
        'progress_is_lightweight', true
      ),
      '{}'::jsonb,
      NULL::jsonb,
      0,
      0,
      0,
      0,
      0,
      'RUNNABLE',
      v_now,
      false,
      'TRANSFER_SCOPE_SEED_REQUIRED',
      v_now,
      v_now,
      v_now
    )
    RETURNING * INTO v_operation_row;

    v_operation_id := v_operation_row.id;
    v_created := true;
  ELSE
    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        actor_user_id = coalesce(operation_update.actor_user_id, p_actor_user_id),
        status = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.status
          ELSE 'RUNNING'
        END,
        phase = coalesce(nullif(btrim(operation_update.phase), ''), 'PREPARE_TRANSFER_SCOPE'),
        runner_state = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.runner_state
          ELSE 'RUNNABLE'
        END,
        run_after_utc = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.run_after_utc
          ELSE v_now
        END,
        requires_user_action = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION') THEN true
          ELSE coalesce(operation_update.requires_user_action, false)
        END,
        resume_reason = coalesce(nullif(btrim(operation_update.resume_reason), ''), 'TRANSFER_SCOPE_SEED_REQUIRED'),
        input_json = jsonb_strip_nulls(coalesce(operation_update.input_json, '{}'::jsonb) || jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
          'source_rpc', 'pay_execute_bank'
        )),
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_entrypoint_reuse_at_utc', v_now::text,
          'next_required_phase', coalesce(operation_update.progress_json->>'next_required_phase', 'TRANSFER_SCOPE_SEED'),
          'progress_is_lightweight', true
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = v_operation_id
    RETURNING * INTO v_operation_row;
  END IF;

  UPDATE public.pay_batches AS batch_update
  SET execution_intent_json = jsonb_strip_nulls(coalesce(batch_update.execution_intent_json, '{}'::jsonb) || jsonb_build_object(
        'operation_id', v_operation_id::text,
        'operation_type', v_operation_type,
        'pay_channel_scope', v_scope,
        'durable_execution', true,
        'backend_owned_execution', true
      ))
  WHERE batch_update.id = p_pay_batch_id;

  BEGIN
    PERFORM public.banking_pay_batch_signal_touch(
      p_pay_batch_id,
      'execution_operation_started',
      'pay_execute_bank',
      jsonb_build_object('actor_user_id', p_actor_user_id::text, 'operation_id', v_operation_id::text),
      true,
      false,
      false,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  v_progress_light := jsonb_strip_nulls(jsonb_build_object(
    'next_required_phase', coalesce(v_operation_row.progress_json->>'next_required_phase', 'TRANSFER_SCOPE_SEED'),
    'last_entrypoint_reuse_at_utc', v_operation_row.progress_json->>'last_entrypoint_reuse_at_utc',
    'last_advanced_at_utc', CASE WHEN v_operation_row.last_advanced_at_utc IS NULL THEN NULL ELSE v_operation_row.last_advanced_at_utc::text END,
    'heartbeat_at_utc', CASE WHEN v_operation_row.heartbeat_at_utc IS NULL THEN NULL ELSE v_operation_row.heartbeat_at_utc::text END,
    'total_units', coalesce(v_operation_row.total_units, 0),
    'completed_units', coalesce(v_operation_row.completed_units, 0),
    'failed_units', coalesce(v_operation_row.failed_units, 0),
    'current_chunk_index', coalesce(v_operation_row.current_chunk_index, 0),
    'chunk_count', coalesce(v_operation_row.chunk_count, 0),
    'progress_is_lightweight', true
  ));

  RETURN jsonb_build_object(
    'ok', true,
    'durable_operation', true,
    'operation_created', v_created,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', v_operation_id::text,
    'operation_type', v_operation_type,
    'operation_status', v_operation_row.status,
    'operation_phase', v_operation_row.phase,
    'runner_state', v_operation_row.runner_state,
    'run_after_utc', CASE WHEN v_operation_row.run_after_utc IS NULL THEN NULL ELSE v_operation_row.run_after_utc::text END,
    'requires_user_action', coalesce(v_operation_row.requires_user_action, false),
    'pay_channel_scope', v_scope,
    'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
    'progress_light', v_progress_light,
    'legacy_inline_execution_disabled', true,
    'backend_owned_execution', true,
    'provider_submission_events_insertable', false,
    'provider_submission_event_payloads', '[]'::jsonb,
    'transfers', '[]'::jsonb,
    'server_utc', v_now::text
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_case_update_count int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;
  v_preview_decisions_json jsonb := '{}'::jsonb;
  v_preview_context_json jsonb := '{}'::jsonb;
  v_preview_baseline_json jsonb := '{}'::jsonb;
  v_preview_candidate_row_json jsonb := '{}'::jsonb;
  v_preview_scope_context_json jsonb := '{}'::jsonb;
  v_preview_scope_candidate_ids_json jsonb := '[]'::jsonb;
  v_preview_candidate_loop_id uuid := NULL::uuid;
  v_preview_candidate_count integer := 0;
  v_requested_candidate_count integer := 0;
  v_missing_candidate_count integer := 0;
  v_missing_candidate_ids_json jsonb := '[]'::jsonb;
  v_authoritative_timesheet_scope_requested boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_explicit_empty_timesheet_scope boolean := false;
  v_preview_scope_strategy text := 'CANDIDATE_FULL_LIVE';
  v_sync_authority_token text := NULL::text;
  v_current_sync_authority_token text := NULL::text;
  v_workbench_session_id_text text := NULL::text;
  v_source_build_run_id_text text := NULL::text;
  v_session_version_text text := NULL::text;
  v_workbench_session_id uuid := NULL::uuid;
  v_source_build_run_id uuid := NULL::uuid;
  v_workbench_session_version bigint := NULL::bigint;
  v_authoritative_candidate_id uuid := NULL::uuid;
  v_existing_active_reserved_amount numeric(12,2) := 0;
  v_effective_case_amount_ex numeric(12,2);
  v_active_reservation_protection_applied boolean := false;

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_component_case_outstanding_amount numeric(12,2) := 0;
  v_component_open_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
  v_authoritative_negative_component_count integer := 0;
  v_authoritative_negative_component_digest text := NULL::text;
  v_expected_negative_component_digest text := NULL::text;
  v_authoritative_settled_baseline_digest text := NULL::text;
  v_expected_settled_baseline_digest text := NULL::text;
begin
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  v_requested_candidate_count := COALESCE(array_length(p_candidate_ids, 1), 0);

  v_authoritative_timesheet_scope_requested := LOWER(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authoritative_timesheet_scope',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_sync_authority_token := NULLIF(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(v_authoritative_timesheet_scope_requested, false)
     AND (
       p_force_include_timesheet_ids IS NULL
       OR v_sync_authority_token IS NULL
       OR v_current_sync_authority_token IS NULL
       OR v_sync_authority_token IS DISTINCT FROM v_current_sync_authority_token
     ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID',
              'message', 'Authoritative Timesheet scope is internal Workbench authority and requires the matching transaction-local source-build token.',
              'force_include_argument_supplied', p_force_include_timesheet_ids IS NOT NULL,
              'authority_token_supplied', v_sync_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_authoritative_timesheet_scope := COALESCE(v_authoritative_timesheet_scope_requested, false)
    AND p_force_include_timesheet_ids IS NOT NULL
    AND v_sync_authority_token IS NOT NULL
    AND v_sync_authority_token = v_current_sync_authority_token;

  v_explicit_empty_timesheet_scope := COALESCE(v_authoritative_timesheet_scope, false)
    AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) = 0;

  v_preview_scope_strategy := CASE
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
     AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
      THEN 'AUTHORITATIVE_EMPTY'
    ELSE 'CANDIDATE_FULL_LIVE'
  END;

  v_preview_decisions_json := (
      CASE
        WHEN jsonb_typeof(COALESCE(p_mismatch_choices, '{}'::jsonb)) = 'object'
          THEN COALESCE(p_mismatch_choices, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      - 'refresh_scope_kind'
      - 'targeted_timesheet_ids'
      - 'targeted_timesheet_ids_requested'
      - 'linked_timesheet_ids'
      - 'linked_timesheet_ids_requested'
      - 'source_build_allow_full_fallback'
      - 'overpayment_sync_authority_token'
      - 'overpayment_sync_authoritative_timesheet_scope'
      - 'authoritative_timesheet_scope'
      - 'exact_timesheet_scope'
      - 'workbench_session_id'
      - 'source_build_run_id'
      - 'source_change_seq'
      - 'session_version'
      - 'overpayment_sync_scope_digest'
      - 'overpayment_sync_negative_component_digest'
      - 'overpayment_sync_settled_baseline_digest'
      - 'policy_x_authority_scope'
    )
    || jsonb_build_object(
      'overpayment_sync_mode', true,
      'emit_raw_overpayment_components', true,
      'preview_context_mode', CASE WHEN v_requested_candidate_count = 1 THEN 'FULL_COMPAT' ELSE 'PAGE' END,
      'scope_limit', LEAST(GREATEST(COALESCE(v_requested_candidate_count, 1), 1), 100),
      'pay_channel_scope', v_scope,
      'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
      'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
      'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb),
      'overpayment_sync_preview_scope_strategy', v_preview_scope_strategy
    )
    || CASE
      WHEN v_preview_scope_strategy = 'TARGETED_TIMESHEETS' THEN
        jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false,
          'overpayment_sync_explicit_empty_scope', false
        )
      ELSE
        jsonb_build_object(
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'targeted_timesheet_ids', '[]'::jsonb,
          'targeted_timesheet_ids_requested', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'overpayment_sync_explicit_empty_scope', COALESCE(v_explicit_empty_timesheet_scope, false)
        )
    END;


  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID',
              'message', 'candidate_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS included_timesheet(timesheet_id)
    WHERE included_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID',
              'message', 'force_include_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])) AS excluded_timesheet(timesheet_id)
    WHERE excluded_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID',
              'message', 'exclude_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF v_requested_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE',
              'candidate_count', v_requested_candidate_count,
              'limit', 100,
              'message', 'Supply at most 100 explicit candidate IDs per bounded reconciliation call.'
            )::text;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    IF v_requested_candidate_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED',
                'candidate_count', v_requested_candidate_count
              )::text;
    END IF;

    v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), '');
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), '');
    v_session_version_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), '');

    IF v_workbench_session_id_text IS NULL
       OR v_workbench_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_session_version_text IS NULL
       OR v_session_version_text !~ '^[0-9]{1,18}$'
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH' THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID',
                'workbench_session_id', v_workbench_session_id_text,
                'source_build_run_id', v_source_build_run_id_text,
                'session_version', v_session_version_text,
                'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
              )::text;
    END IF;

    v_workbench_session_id := v_workbench_session_id_text::uuid;
    v_source_build_run_id := v_source_build_run_id_text::uuid;
    v_workbench_session_version := v_session_version_text::bigint;

    SELECT requested_candidate.candidate_id
    INTO v_authoritative_candidate_id
    FROM unnest(p_candidate_ids) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
    LIMIT 1;

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS authoritative_session
    JOIN public.banking_pay_workbench_session_scope AS authoritative_scope
      ON authoritative_scope.session_id = authoritative_session.id
     AND authoritative_scope.candidate_id = v_authoritative_candidate_id
    JOIN public.candidates AS authoritative_candidate
      ON authoritative_candidate.id = authoritative_scope.candidate_id
    WHERE authoritative_session.id = v_workbench_session_id
      AND UPPER(BTRIM(COALESCE(authoritative_session.status, ''))) = 'OPEN'
      AND authoritative_session.discarded_at_utc IS NULL
      AND COALESCE(authoritative_session.version, 1) = v_workbench_session_version
      AND authoritative_session.actor_user_id = p_actor_user_id
      AND authoritative_session.pay_date = p_pay_date
      AND authoritative_session.week_ending_cutoff = p_week_ending_cutoff
      AND UPPER(BTRIM(COALESCE(authoritative_candidate.pay_method, ''))) = v_scope;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID',
                'workbench_session_id', v_workbench_session_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'session_version', v_workbench_session_version,
                'candidate_id', v_authoritative_candidate_id::text,
                'pay_channel_scope', v_scope
              )::text;
    END IF;

    IF EXISTS (
      WITH candidate_authority_seed_timesheets AS (
        SELECT authoritative_tsfin.timesheet_id
        FROM public.timesheets_financials AS authoritative_tsfin
        WHERE authoritative_tsfin.candidate_id = v_authoritative_candidate_id
          AND authoritative_tsfin.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_case.linked_timesheet_id
        FROM public.pay_advances AS authoritative_case
        WHERE authoritative_case.candidate_id = v_authoritative_candidate_id
          AND authoritative_case.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_component.linked_timesheet_id
        FROM public.pay_finance_case_components AS authoritative_component
        WHERE authoritative_component.candidate_id = v_authoritative_candidate_id
          AND authoritative_component.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_override.timesheet_id
        FROM public.timesheet_payment_overrides AS authoritative_override
        WHERE authoritative_override.candidate_id = v_authoritative_candidate_id
          AND authoritative_override.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_adjustment.timesheet_id
        FROM public.ts_pay_adjustments AS authoritative_adjustment
        WHERE authoritative_adjustment.candidate_id = v_authoritative_candidate_id
          AND authoritative_adjustment.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_snooze.timesheet_id
        FROM public.pay_item_snoozes AS authoritative_snooze
        WHERE authoritative_snooze.candidate_id = v_authoritative_candidate_id
          AND authoritative_snooze.timesheet_id IS NOT NULL
          AND authoritative_snooze.cleared_at_utc IS NULL
          AND authoritative_snooze.cancelled_at_utc IS NULL

        UNION

        SELECT authoritative_batch_item.timesheet_id
        FROM public.pay_batch_candidates AS authoritative_batch_candidate
        JOIN public.pay_batch_items AS authoritative_batch_item
          ON authoritative_batch_item.pay_batch_candidate_id = authoritative_batch_candidate.id
        WHERE authoritative_batch_candidate.candidate_id = v_authoritative_candidate_id
          AND authoritative_batch_item.timesheet_id IS NOT NULL
          AND COALESCE(authoritative_batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT authoritative_correction.timesheet_id
        FROM public.pay_payment_correction_items AS authoritative_correction
        WHERE authoritative_correction.candidate_id = v_authoritative_candidate_id
          AND authoritative_correction.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(authoritative_correction.status, ''))) = 'APPLIED'
      ), candidate_authority_seed_array AS (
        SELECT COALESCE(
          ARRAY_AGG(
            DISTINCT candidate_authority_seed_timesheets.timesheet_id
            ORDER BY candidate_authority_seed_timesheets.timesheet_id
          ),
          ARRAY[]::uuid[]
        ) AS timesheet_ids
        FROM candidate_authority_seed_timesheets
      ), candidate_authority_timesheets AS (
        SELECT candidate_authority_seed_timesheets.timesheet_id
        FROM candidate_authority_seed_timesheets

        UNION

        SELECT authority_rotation.canonical_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.canonical_timesheet_id IS NOT NULL

        UNION

        SELECT authority_rotation.family_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.family_timesheet_id IS NOT NULL
      )
      SELECT 1
      FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS authoritative_timesheet(timesheet_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM candidate_authority_timesheets AS candidate_authority
        WHERE candidate_authority.timesheet_id = authoritative_timesheet.timesheet_id
      )
    ) THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_explicit_empty_timesheet_scope, false) THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
      jsonb_build_object(
        'pay_channel_scope', v_scope,
        'authoritative_timesheet_scope', true,
        'explicit_empty_timesheet_scope', true,
        'preview_scope_strategy', v_preview_scope_strategy,
        'candidate_count', v_requested_candidate_count,
        'cases_inserted', 0,
        'cases_touched', 0,
        'cases_amended', 0,
        'cases_reopened', 0,
        'cases_cleared', 0
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'pay_channel_scope', v_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'preview_scope_strategy', v_preview_scope_strategy,
      'scope_timesheet_ids', '[]'::jsonb,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', 0,
      'preview_candidate_coverage_complete', true,
      'negative_preview_timesheets_count', 0,
      'negative_preview_timesheets', '[]'::jsonb,
      'underpayment_case_count', 0,
      'underpayment_cases', '[]'::jsonb,
      'timesheet_finance_case_candidates_count', 0,
      'timesheet_finance_case_candidates', '[]'::jsonb,
      'cases_inserted', 0,
      'cases_touched', 0,
      'cases_amended', 0,
      'cases_reopened', 0,
      'cases_cleared', 0
    );
  END IF;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_preview_candidates (
    candidate_id uuid not null primary key,
    candidate_json jsonb not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_negative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_raw_negative_timesheet_rows (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    case_components_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;
  truncate table pg_temp.tmp_sync_preview_candidates;
  truncate table pg_temp.tmp_sync_authoritative_negative_components;
  truncate table pg_temp.tmp_sync_raw_negative_timesheet_rows;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    INSERT INTO pg_temp.tmp_sync_authoritative_negative_components (
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      reserved_ex_vat,
      outstanding_ex_vat,
      baseline_signature
    )
    WITH live_entitlement_components AS (
      SELECT
        entitlement_component.timesheet_id,
        UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
        BTRIM(entitlement_component.key_value) AS key_value,
        ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat
      FROM public._pay_current_timesheet_entitlement_components(
        COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
      ) AS entitlement_component
      WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
    ), active_entitlement_reservations AS (
      SELECT
        reserved_component.timesheet_id,
        UPPER(BTRIM(reserved_component.key_type)) AS key_type,
        BTRIM(reserved_component.key_value) AS key_value,
        ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat
      FROM public._pay_reserved_components(
        COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]),
        NULL::uuid
      ) AS reserved_component
      WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
    ), live_economic_keys AS (
      SELECT
        live_component.timesheet_id,
        live_component.key_type,
        live_component.key_value
      FROM live_entitlement_components AS live_component

      UNION

      SELECT
        reserved_component.timesheet_id,
        reserved_component.key_type,
        reserved_component.key_value
      FROM active_entitlement_reservations AS reserved_component
    ), raw_outstanding_components AS (
      SELECT
        live_key.timesheet_id,
        live_key.key_type,
        live_key.key_value,
        ROUND(COALESCE(live_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat,
        ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat,
        ROUND(
          COALESCE(live_component.truth_ex_vat, 0)
          - COALESCE(live_component.baseline_ex_vat, 0)
          - COALESCE(reserved_component.reserved_ex_vat, 0),
          2
        )::numeric(12,2) AS outstanding_ex_vat
      FROM live_economic_keys AS live_key
      LEFT JOIN live_entitlement_components AS live_component
        ON live_component.timesheet_id = live_key.timesheet_id
       AND live_component.key_type = live_key.key_type
       AND live_component.key_value = live_key.key_value
      LEFT JOIN active_entitlement_reservations AS reserved_component
        ON reserved_component.timesheet_id = live_key.timesheet_id
       AND reserved_component.key_type = live_key.key_type
       AND reserved_component.key_value = live_key.key_value
    )
    SELECT
      raw_component.timesheet_id,
      raw_component.key_type,
      raw_component.key_value,
      raw_component.truth_ex_vat,
      raw_component.baseline_ex_vat,
      raw_component.reserved_ex_vat,
      raw_component.outstanding_ex_vat,
      CASE
        WHEN COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          THEN active_settled_basis.active_settled_signature
        ELSE COALESCE(
          timesheet_pay_state.last_settled_signature,
          md5(COALESCE(timesheet_pay_state.last_settled_snapshot_json::text, '{}'))
        )
      END AS baseline_signature
    FROM raw_outstanding_components AS raw_component
    LEFT JOIN public.timesheet_pay_state AS timesheet_pay_state
      ON timesheet_pay_state.timesheet_id = raw_component.timesheet_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS active_settled_component_count,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_component.key_type,
            'key_value', active_settled_component.key_value,
            'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
            'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
          ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
        )::text, '[]')) AS active_settled_signature
      FROM public._pay_active_settled_components(
        ARRAY[raw_component.timesheet_id]::uuid[]
      ) AS active_settled_component
    ) AS active_settled_basis ON true
    WHERE raw_component.outstanding_ex_vat < 0;

    SELECT
      COUNT(*)::integer,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'timesheet_id', negative_component.timesheet_id::text,
          'key_type', negative_component.key_type,
          'key_value', negative_component.key_value,
          'truth_ex_vat', negative_component.truth_ex_vat,
          'baseline_ex_vat', negative_component.baseline_ex_vat,
          'reserved_ex_vat', negative_component.reserved_ex_vat,
          'outstanding_ex_vat', negative_component.outstanding_ex_vat
        ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
      )::text, '[]'))
    INTO
      v_authoritative_negative_component_count,
      v_authoritative_negative_component_digest
    FROM pg_temp.tmp_sync_authoritative_negative_components AS negative_component;

    SELECT md5(COALESCE(jsonb_agg(
      jsonb_build_object(
        'timesheet_id', settled_component.timesheet_id::text,
        'key_type', settled_component.key_type,
        'key_value', settled_component.key_value,
        'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
        'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
      ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
    )::text, '[]'))
    INTO v_authoritative_settled_baseline_digest
    FROM public._pay_active_settled_components(
      COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
    ) AS settled_component;

    v_expected_negative_component_digest := NULLIF(BTRIM(COALESCE(
      p_mismatch_choices->>'overpayment_sync_negative_component_digest',
      ''
    )), '');
    v_expected_settled_baseline_digest := NULLIF(BTRIM(COALESCE(
      p_mismatch_choices->>'overpayment_sync_settled_baseline_digest',
      ''
    )), '');

    IF v_authoritative_negative_component_digest IS DISTINCT FROM v_expected_negative_component_digest
       OR v_authoritative_settled_baseline_digest IS DISTINCT FROM v_expected_settled_baseline_digest THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                'expected_negative_component_digest', v_expected_negative_component_digest,
                'actual_negative_component_digest', v_authoritative_negative_component_digest,
                'expected_settled_baseline_digest', v_expected_settled_baseline_digest,
                'actual_settled_baseline_digest', v_authoritative_settled_baseline_digest,
                'message', 'The Workbench negative-component or settled-baseline authority changed before finance-case synchronisation.'
              )::text;
    END IF;
  END IF;
  IF v_requested_candidate_count > 0 THEN
    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT requested_candidate.candidate_id
      FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
      WHERE requested_candidate.candidate_id IS NOT NULL
      ORDER BY requested_candidate.candidate_id
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      IF jsonb_typeof(COALESCE(v_preview_baseline_json, '{}'::jsonb)) <> 'object' THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND COALESCE(v_authoritative_negative_component_count, 0) > 0
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NULL THEN
        PERFORM public.pay_preview_candidate_build_case_component_rows(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
        IF EXISTS (
          WITH preview_component_totals AS (
            SELECT
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(raw_component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS preview_component_count,
              ROUND(
                SUM((raw_component.value->>'component_amount_ex_vat')::numeric),
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM pg_temp.timesheet_case_rollup AS raw_case
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                  THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS raw_component(value)
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
              AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
              AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN preview_component_totals AS preview_total
            ON preview_total.timesheet_id = authoritative_component.timesheet_id
           AND preview_total.key_type = authoritative_component.key_type
           AND preview_total.key_value = authoritative_component.key_value
          WHERE preview_total.preview_component_count IS NULL
             OR ABS(ROUND(
                  COALESCE(preview_total.preview_truth_ex_vat, 0)
                  - authoritative_component.truth_ex_vat,
                  2
                )) > 0.01
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'message', 'Canonical negative component keys were not represented by preview metadata whose current component totals match authoritative live truth.'
                  )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          raw_case.candidate_id,
          raw_case.timesheet_id,
          raw_case.client_id,
          COALESCE(NULLIF(UPPER(BTRIM(raw_case.cand_pay_method)), ''), v_scope),
          COALESCE(raw_case.is_blocked, false),
          COALESCE((
            WITH matching_preview_components AS (
              SELECT
                authoritative_component.timesheet_id,
                authoritative_component.key_type,
                authoritative_component.key_value,
                authoritative_component.truth_ex_vat,
                authoritative_component.baseline_ex_vat,
                authoritative_component.reserved_ex_vat,
                authoritative_component.outstanding_ex_vat,
                raw_component.value AS component_json,
                raw_component.ordinality::integer AS component_ordinality,
                ROUND(
                  (raw_component.value->>'component_amount_ex_vat')::numeric,
                  2
                )::numeric(12,2) AS preview_truth_component_ex_vat,
                COUNT(*) OVER (
                  PARTITION BY
                    authoritative_component.timesheet_id,
                    authoritative_component.key_type,
                    authoritative_component.key_value
                )::integer AS physical_component_count,
                ROUND(
                  SUM(ABS((raw_component.value->>'component_amount_ex_vat')::numeric)) OVER (
                    PARTITION BY
                      authoritative_component.timesheet_id,
                      authoritative_component.key_type,
                      authoritative_component.key_value
                  ),
                  2
                )::numeric(12,2) AS preview_truth_weight_total_ex_vat,
                ROW_NUMBER() OVER (
                  PARTITION BY
                    authoritative_component.timesheet_id,
                    authoritative_component.key_type,
                    authoritative_component.key_value
                  ORDER BY
                    COALESCE(raw_component.value->'source_basis_json', '{}'::jsonb)::text,
                    raw_component.ordinality
                )::integer AS allocation_rank
              FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
              CROSS JOIN LATERAL jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                    THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                  ELSE '[]'::jsonb
                END
              ) WITH ORDINALITY AS raw_component(value, ordinality)
              WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
                AND authoritative_component.key_type = UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', '')))
                AND authoritative_component.key_value = BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
                AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            ), preliminary_allocations AS (
              SELECT
                matching_component.*,
                CASE
                  WHEN matching_component.physical_component_count = 1
                    THEN matching_component.outstanding_ex_vat
                  WHEN COALESCE(matching_component.preview_truth_weight_total_ex_vat, 0) <= 0.01
                    THEN CASE
                      WHEN matching_component.allocation_rank = 1
                        THEN matching_component.outstanding_ex_vat
                      ELSE 0::numeric
                    END
                  ELSE ROUND(
                    matching_component.outstanding_ex_vat
                    * ABS(matching_component.preview_truth_component_ex_vat)
                    / matching_component.preview_truth_weight_total_ex_vat,
                    2
                  )
                END::numeric(12,2) AS preliminary_outstanding_allocation
              FROM matching_preview_components AS matching_component
            ), final_allocations AS (
              SELECT
                preliminary_allocation.*,
                CASE
                  WHEN preliminary_allocation.allocation_rank = preliminary_allocation.physical_component_count
                    THEN ROUND(
                      preliminary_allocation.outstanding_ex_vat
                      - COALESCE(
                          SUM(preliminary_allocation.preliminary_outstanding_allocation) OVER (
                            PARTITION BY
                              preliminary_allocation.timesheet_id,
                              preliminary_allocation.key_type,
                              preliminary_allocation.key_value
                            ORDER BY preliminary_allocation.allocation_rank
                            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                          ),
                          0
                        ),
                      2
                    )
                  ELSE preliminary_allocation.preliminary_outstanding_allocation
                END::numeric(12,2) AS authoritative_outstanding_allocation
              FROM preliminary_allocations AS preliminary_allocation
            )
            SELECT jsonb_agg(
              allocated_component.component_json
              || jsonb_build_object(
                'component_amount_ex_vat', allocated_component.authoritative_outstanding_allocation,
                'authoritative_truth_ex_vat', allocated_component.truth_ex_vat,
                'authoritative_baseline_ex_vat', allocated_component.baseline_ex_vat,
                'authoritative_reserved_ex_vat', allocated_component.reserved_ex_vat,
                'authoritative_outstanding_ex_vat', allocated_component.outstanding_ex_vat,
                'overpayment_component_authority', 'PRE_DRAFT_LIVE_TRUTH'
              )
              ORDER BY
                allocated_component.key_type,
                allocated_component.key_value,
                COALESCE(allocated_component.component_json->'source_basis_json', '{}'::jsonb)::text,
                allocated_component.component_ordinality
            )
            FROM final_allocations AS allocated_component
          ), '[]'::jsonb)
        FROM pg_temp.timesheet_case_rollup AS raw_case
        WHERE raw_case.candidate_id = v_preview_candidate_loop_id
          AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
          AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
          )
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;
      END IF;

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope,
                  'baseline_candidate_id', NULLIF(BTRIM(COALESCE(
                    v_preview_candidate_row_json->>'candidate_id',
                    v_preview_baseline_json->>'candidate_id',
                    ''
                  )), '')
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'requested_pay_channel_scope', v_scope,
                  'current_pay_method', NULLIF(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', '')), '')
                )::text;
      END IF;

      v_preview_candidate_row_json := v_preview_candidate_row_json
        || jsonb_build_object(
          'candidate_id', v_preview_candidate_loop_id::text,
          'itemisation', CASE
            WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
            WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        );

      INSERT INTO pg_temp.tmp_sync_preview_candidates (
        candidate_id,
        candidate_json
      )
      VALUES (
        v_preview_candidate_loop_id,
        v_preview_candidate_row_json
      )
      ON CONFLICT (candidate_id) DO UPDATE
      SET candidate_json = EXCLUDED.candidate_json;
    END LOOP;
  ELSE
    v_preview_scope_context_json := public.pay_preview_build_context(
      p_pay_date => p_pay_date,
      p_week_ending_cutoff => p_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => p_client_filter_single,
      p_preview_decisions_json => v_preview_decisions_json
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', 100
        )
    );

    v_preview_scope_candidate_ids_json := CASE
      WHEN jsonb_typeof(v_preview_scope_context_json->'candidate_ids') = 'array'
        THEN COALESCE(v_preview_scope_context_json->'candidate_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF LOWER(BTRIM(COALESCE(v_preview_scope_context_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS',
                'message', 'The bounded candidate page is incomplete. Supply explicit candidate_ids rather than accepting a partial all-candidate reconciliation.',
                'pay_channel_scope', v_scope,
                'page_count', COALESCE(v_preview_scope_context_json->>'page_count', '0'),
                'limit', COALESCE(v_preview_scope_context_json->>'limit', '100'),
                'next_cursor_json', COALESCE(v_preview_scope_context_json->'next_cursor_json', 'null'::jsonb)
              )::text;
    END IF;

    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT scoped_candidate.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_preview_scope_candidate_ids_json, '[]'::jsonb)) AS scoped_candidate(value)
      WHERE scoped_candidate.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY scoped_candidate.value::uuid
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) = v_scope THEN
        v_preview_candidate_row_json := v_preview_candidate_row_json
          || jsonb_build_object(
            'candidate_id', v_preview_candidate_loop_id::text,
            'itemisation', CASE
              WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
              WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          );

        INSERT INTO pg_temp.tmp_sync_preview_candidates (
          candidate_id,
          candidate_json
        )
        VALUES (
          v_preview_candidate_loop_id,
          v_preview_candidate_row_json
        )
        ON CONFLICT (candidate_id) DO UPDATE
        SET candidate_json = EXCLUDED.candidate_json;
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_preview_candidate_count
  FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate;

  WITH requested_candidates AS (
    SELECT DISTINCT requested_candidate.candidate_id
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
  ), missing_candidates AS (
    SELECT requested_candidates.candidate_id
    FROM requested_candidates
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate
      WHERE preview_candidate.candidate_id = requested_candidates.candidate_id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(missing_candidates.candidate_id::text ORDER BY missing_candidates.candidate_id), '[]'::jsonb)
  INTO v_missing_candidate_count,
       v_missing_candidate_ids_json
  FROM missing_candidates;

  IF COALESCE(v_missing_candidate_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
              'pay_channel_scope', v_scope,
              'requested_candidate_count', v_requested_candidate_count,
              'preview_candidate_count', v_preview_candidate_count,
              'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with candidate_rows as (
    select
      preview_candidate.candidate_id,
      upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      case
        when jsonb_typeof(preview_candidate.candidate_json->'itemisation') = 'array'
          then coalesce(preview_candidate.candidate_json->'itemisation', '[]'::jsonb)
        else '[]'::jsonb
      end as itemisation_json
    from pg_temp.tmp_sync_preview_candidates as preview_candidate
    where upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or preview_candidate.candidate_id = any(p_candidate_ids)
      )
  ),
  itemisation_timesheet_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') = 'TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  authoritative_live_truth_totals AS (
    SELECT
      entitlement_component.timesheet_id,
      ROUND(COALESCE(SUM(COALESCE(entitlement_component.truth_ex_vat, 0)), 0), 2)::numeric(12,2) AS corrected_amount_ex
    FROM public._pay_current_timesheet_entitlement_components(
      CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false)
          THEN COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
        ELSE ARRAY[]::uuid[]
      END
    ) AS entitlement_component
    GROUP BY entitlement_component.timesheet_id
  ),
  authoritative_negative_timesheet_rows AS (
    SELECT
      raw_timesheet.candidate_id,
      raw_timesheet.candidate_pay_method,
      jsonb_build_object(
        'line_type', 'TIMESHEET_PAYMENT',
        'timesheet_id', raw_timesheet.timesheet_id::text,
        'client_id', CASE WHEN raw_timesheet.client_id IS NULL THEN NULL ELSE raw_timesheet.client_id::text END,
        'amount_ex_vat', ROUND(COALESCE(live_truth.corrected_amount_ex, 0), 2),
        'case_is_blocked', raw_timesheet.case_is_blocked,
        'case_components', raw_timesheet.case_components_json,
        'source_authority', 'AUTHORITATIVE_NEGATIVE_COMPONENT_FALLBACK'
      ) AS item_json,
      raw_timesheet.timesheet_id,
      raw_timesheet.client_id,
      ROUND(COALESCE(live_truth.corrected_amount_ex, 0), 2)::numeric(12,2) AS corrected_amount_ex,
      raw_timesheet.case_is_blocked,
      raw_timesheet.case_components_json
    FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
    LEFT JOIN authoritative_live_truth_totals AS live_truth
      ON live_truth.timesheet_id = raw_timesheet.timesheet_id
    WHERE COALESCE(v_authoritative_timesheet_scope, false)
      AND raw_timesheet.candidate_id = v_authoritative_candidate_id
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
        WHERE authoritative_component.timesheet_id = raw_timesheet.timesheet_id
      )
  ),
  timesheet_item_rows AS (
    SELECT
      itemisation_row.candidate_id,
      itemisation_row.candidate_pay_method,
      itemisation_row.item_json,
      itemisation_row.timesheet_id,
      itemisation_row.client_id,
      itemisation_row.corrected_amount_ex,
      itemisation_row.case_is_blocked,
      itemisation_row.case_components_json
    FROM itemisation_timesheet_rows AS itemisation_row
    WHERE NOT EXISTS (
      SELECT 1
      FROM authoritative_negative_timesheet_rows AS authoritative_row
      WHERE authoritative_row.candidate_id = itemisation_row.candidate_id
        AND authoritative_row.timesheet_id = itemisation_row.timesheet_id
    )

    UNION ALL

    SELECT
      authoritative_row.candidate_id,
      authoritative_row.candidate_pay_method,
      authoritative_row.item_json,
      authoritative_row.timesheet_id,
      authoritative_row.client_id,
      authoritative_row.corrected_amount_ex,
      authoritative_row.case_is_blocked,
      authoritative_row.case_components_json
    FROM authoritative_negative_timesheet_rows AS authoritative_row
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM public._pay_active_settled_components(ARRAY[distinct_timesheet_rows.timesheet_id]::uuid[]) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      UPPER(NULLIF(BTRIM(COALESCE(comp.value->>'component_key_type', '')), '')) AS component_key_type,
      NULLIF(BTRIM(COALESCE(comp.value->>'component_key_value', '')), '') AS component_key_value,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  finance_component_movements_raw as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      upper(btrim(coalesce(pfc.component_key_type, pbi.frozen_component_key_type, ''))) as component_key_type,
      nullif(btrim(coalesce(pfc.component_key_value, pbi.frozen_component_key_value, '')), '') as component_key_value,
      upper(btrim(coalesce(pbi.item_type, ''))) as item_type,
      round(abs(coalesce(
        par.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id),
        pbi.frozen_source_amount,
        pbi.amount_ex_vat,
        pbi.amount_inc_vat,
        par.reserved_amount,
        0
      )), 2)::numeric(12,2) as movement_amount_ex,
      true as is_settled_movement,
      false as is_active_reservation
    from public.pay_advances pa
    join public.pay_batch_items pbi
      on pbi.finance_case_id = pa.id
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
    left join public.pay_advance_reservations par
      on par.pay_batch_item_id = pbi.id
    left join public.pay_finance_case_components pfc
      on pfc.id = coalesce(par.finance_component_id, pbi.finance_component_id)
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and coalesce(pbi.is_voided, false) = false
      and upper(btrim(coalesce(pbi.item_type, ''))) in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and (
        upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
        or pbc.settled_at_utc is not null
        or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
        or pbt.completed_at_utc is not null
        or upper(btrim(coalesce(par.status, ''))) = 'SETTLED'
        or par.settled_at_utc is not null
      )
      and not exists (
        select 1
        from public.pay_payment_correction_items pci
        where pci.pay_batch_item_id = pbi.id
          and pci.status = 'APPLIED'
          and pci.correction_item_kind in ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      )

    union all

    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      upper(btrim(coalesce(pfc.component_key_type, pbi.frozen_component_key_type, ''))) as component_key_type,
      nullif(btrim(coalesce(pfc.component_key_value, pbi.frozen_component_key_value, '')), '') as component_key_value,
      upper(btrim(coalesce(
        pbi.item_type,
        case
          when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'OVERPAYMENT_RECOVERY'
          when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then 'UNDERPAYMENT_PAYMENT'
          else null
        end,
        ''
      ))) as item_type,
      round(abs(coalesce(
        par.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id),
        pbi.frozen_source_amount,
        pbi.amount_ex_vat,
        pbi.amount_inc_vat,
        par.reserved_amount,
        0
      )), 2)::numeric(12,2) as movement_amount_ex,
      false as is_settled_movement,
      true as is_active_reservation
    from public.pay_advance_reservations par
    join public.pay_advances pa
      on pa.id = par.finance_case_id
    left join public.pay_batch_items pbi
      on pbi.id = par.pay_batch_item_id
    left join public.pay_finance_case_components pfc
      on pfc.id = coalesce(par.finance_component_id, pbi.finance_component_id)
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and upper(btrim(coalesce(par.status, ''))) in ('RESERVED', 'COMMITTED')
      and par.released_at_utc is null
      and par.settled_at_utc is null
      and (pbi.id is null or coalesce(pbi.is_voided, false) = false)
      and upper(btrim(coalesce(
        pbi.item_type,
        case
          when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'OVERPAYMENT_RECOVERY'
          when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then 'UNDERPAYMENT_PAYMENT'
          else null
        end,
        ''
      ))) in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
  ),
  finance_component_movements as (
    select
      fcmr.candidate_id,
      fcmr.timesheet_id,
      fcmr.component_key_type,
      fcmr.component_key_value,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_underpayment_payment_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_underpayment_payment_ex,
      true as has_finance_movement
    from finance_component_movements_raw fcmr
    where fcmr.component_key_type is not null
      and fcmr.component_key_value is not null
    group by fcmr.candidate_id, fcmr.timesheet_id, fcmr.component_key_type, fcmr.component_key_value
  ),
  timesheet_exploded_with_signed_balance as (
    select
      tec.*,
      coalesce(fcm.settled_overpayment_recovery_ex, 0) as settled_overpayment_recovery_ex,
      coalesce(fcm.reserved_overpayment_recovery_ex, 0) as reserved_overpayment_recovery_ex,
      coalesce(fcm.settled_underpayment_payment_ex, 0) as settled_underpayment_payment_ex,
      coalesce(fcm.reserved_underpayment_payment_ex, 0) as reserved_underpayment_payment_ex,
      coalesce(fcm.has_finance_movement, false) as has_finance_movement,
      round(
        coalesce(tec.component_amount_ex, 0)
        + coalesce(fcm.settled_overpayment_recovery_ex, 0)
        + coalesce(fcm.reserved_overpayment_recovery_ex, 0)
        - coalesce(fcm.settled_underpayment_payment_ex, 0)
        - coalesce(fcm.reserved_underpayment_payment_ex, 0),
        2
      )::numeric(12,2) as signed_component_amount_ex
    from timesheet_exploded_components tec
    left join finance_component_movements fcm
      on fcm.candidate_id = tec.candidate_id
     and fcm.timesheet_id = tec.timesheet_id
     and fcm.component_key_type = tec.component_key_type
     and fcm.component_key_value = tec.component_key_value
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      bool_or(coalesce(tec.has_finance_movement, false)) as has_finance_movement,
      round(coalesce(sum(case when tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null then abs(tec.signed_component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null then tec.signed_component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.signed_component_amount_ex),
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.signed_component_amount_ex),
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_with_signed_balance tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
            or coalesce(tcr.has_finance_movement, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    v_selected_event_type := NULL;
    v_selected_reason := NULL;
    v_selected_note := NULL;
    v_case_update_count := 0;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(coalesce(
            component_element.value->>'source_pay_method',
            component_element.value->>'current_target_pay_method',
            v_target_case_row.candidate_pay_method,
            ''
          )), '')) AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from public.pay_finance_case_events sync_safety_events
        where sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.event_type, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_safety_events.reason, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      ) as old_has_manual_or_restructure_event,
      exists (
        select 1
        from public.pay_finance_case_events automatic_clear_event
        where automatic_clear_event.finance_case_id = pa.id
          and (
            (
              upper(btrim(coalesce(automatic_clear_event.event_type, ''))) = 'CASE_CLEARED'
              and lower(btrim(coalesce(automatic_clear_event.reason, ''))) = 'rail_settlement'
            )
            or (
              upper(btrim(coalesce(automatic_clear_event.event_type, ''))) = 'CLEARED'
              and upper(btrim(coalesce(automatic_clear_event.reason, ''))) = 'PREVIEW_FINANCE_SYNC'
            )
          )
      ) as old_has_automatic_reconcilable_clear,
      round(coalesce((
        select sum(abs(coalesce(
          settled_reservation.reserved_source_amount,
          public._pay_batch_item_source_reservation_amount_ex_vat(settled_item.id),
          settled_item.frozen_source_amount,
          settled_item.amount_ex_vat,
          settled_item.amount_inc_vat,
          settled_reservation.reserved_amount,
          0
        )))
        from public.pay_batch_items as settled_item
        join public.pay_batch_candidates as settled_candidate
          on settled_candidate.id = settled_item.pay_batch_candidate_id
        join public.pay_batches as settled_batch
          on settled_batch.id = settled_candidate.pay_batch_id
        left join public.pay_bank_transfers as settled_transfer
          on settled_transfer.id = settled_item.pay_bank_transfer_id
        left join public.pay_advance_reservations as settled_reservation
          on settled_reservation.pay_batch_item_id = settled_item.id
        where coalesce(settled_item.is_voided, false) is not true
          and coalesce(
            settled_reservation.finance_case_id,
            settled_item.finance_case_id,
            case
              when upper(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 1))) = 'ADVANCE'
               and nullif(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 2)), '')
                   ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then nullif(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 2)), '')::uuid
              else null::uuid
            end
          ) = pa.id
          and (
            (
              v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
            )
            or (
              v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_item.item_type, ''))) = 'UNDERPAYMENT_PAYMENT'
            )
          )
          and not exists (
            select 1
            from public.pay_payment_correction_items as settled_correction
            where settled_correction.pay_batch_item_id = settled_item.id
              and settled_correction.status = 'APPLIED'
              and settled_correction.correction_item_kind in (
                'PRE_BANK_CANCEL',
                'NO_MONEY_UNWIND',
                'SETTLED_REVERSAL'
              )
          )
          and (
            upper(btrim(coalesce(settled_candidate.settlement_status, ''))) = 'SETTLED'
            or settled_candidate.settled_at_utc is not null
            or upper(btrim(coalesce(settled_transfer.status, ''))) = 'COMPLETED'
            or settled_transfer.completed_at_utc is not null
            or upper(btrim(coalesce(settled_reservation.status, ''))) = 'SETTLED'
            or settled_reservation.settled_at_utc is not null
          )
      ), 0), 2)::numeric(12,2) as old_active_recovered_amount
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type = v_target_case_row.desired_case_type
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    v_existing_recovered_amount := greatest(
      coalesce(v_existing_case_row.old_active_recovered_amount, 0),
      0
    );

    v_existing_active_reserved_amount := 0::numeric(12,2);

    IF v_existing_case_row.finance_case_id IS NOT NULL THEN
      SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
        advance_reservation.reserved_source_amount,
        advance_reservation.reserved_amount,
        batch_item.frozen_source_amount,
        batch_item.amount_ex_vat,
        batch_item.amount_inc_vat,
        0
      ))), 0), 2)::numeric(12,2)
      INTO v_existing_active_reserved_amount
      FROM public.pay_advance_reservations AS advance_reservation
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = advance_reservation.pay_batch_item_id
      WHERE advance_reservation.finance_case_id = v_existing_case_row.finance_case_id
        AND UPPER(BTRIM(COALESCE(advance_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
        AND advance_reservation.released_at_utc IS NULL
        AND (batch_item.id IS NULL OR COALESCE(batch_item.is_voided, false) IS NOT TRUE);
    END IF;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or (
           v_existing_case_row.old_cleared_at_utc is not null
           and not (
             upper(coalesce(v_existing_case_row.old_status::text, '')) = 'PAID_OFF'
             and coalesce(v_existing_case_row.old_has_automatic_reconcilable_clear, false)
             and coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false) is not true
             and round(
               coalesce(v_target_case_amount_ex, 0)
               - coalesce(v_existing_recovered_amount, 0),
               2
             ) > 0
           )
         )
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event,
          'has_automatic_reconcilable_clear', v_existing_case_row.old_has_automatic_reconcilable_clear,
          'existing_recovered_amount', v_existing_recovered_amount
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'component_sync_skipped', true,
          'component_authority_preserved', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature,
          'target_pay_channel_scope', v_scope,
          'workbench_session_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), ''),
          'source_build_run_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), ''),
          'session_version', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), ''),
          'overpayment_sync_scope_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), ''),
          'overpayment_sync_negative_component_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), ''),
          'overpayment_sync_settled_baseline_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), ''),
          'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped case and component synchronisation because the existing case is written-off, cleared, closed, paused, manually resolved, or restructured.'
      );

      /* A protected case must not be inserted into tmp_sync_case_links with an
         empty component payload.  Every row in tmp_sync_case_links is processed
         later by pay_finance_components_sync_from_preview; an empty payload is
         authoritative removal input and can close open components.  The case
         clear pass already excludes protected cases by lifecycle state/event,
         so omitting the link preserves the complete protected case/component
         authority without allowing automatic sync to rewrite it. */
      continue;
    end if;

    IF v_existing_case_row.finance_case_id IS NOT NULL
       AND v_existing_case_row.old_case_type IS DISTINCT FROM v_target_case_row.desired_case_type
       AND COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'existing_case_type', v_existing_case_row.old_case_type::text,
                'target_case_type', v_target_case_row.desired_case_type::text,
                'active_reserved_amount', COALESCE(v_existing_active_reserved_amount, 0),
                'message', 'The finance-case direction cannot change while a frozen recovery or payment reservation remains active. Settle or cancel the active batch before reconciling the opposite direction.'
              )::text;
    END IF;

    v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
      AND COALESCE(v_target_case_amount_ex, 0) < ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2);
    v_effective_case_amount_ex := GREATEST(
      COALESCE(v_target_case_amount_ex, 0),
      ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2)
    )::numeric(12,2);
    v_new_outstanding_amount := greatest(v_effective_case_amount_ex - v_existing_recovered_amount, COALESCE(v_existing_active_reserved_amount, 0), 0)::numeric(12,2);

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_effective_case_amount_ex,
        v_new_outstanding_amount,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_effective_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id
        and row(
          pa.client_id,
          pa.case_type,
          pa.advance_kind,
          pa.reason,
          pa.linked_shift_date,
          pa.baseline_signature,
          pa.source_original_paid_amount,
          pa.source_corrected_paid_amount,
          pa.original_amount,
          pa.outstanding_amount,
          pa.status,
          pa.cleared_at_utc,
          pa.cleared_by_user_id,
          pa.taxability,
          pa.routing_kind
        ) is distinct from row(
          v_target_case_row.client_id,
          v_target_case_row.desired_case_type,
          v_target_case_row.desired_advance_kind,
          v_target_case_row.desired_reason,
          v_target_case_row.linked_shift_date,
          v_target_case_row.baseline_signature,
          v_target_case_row.source_original_paid_amount,
          v_target_case_row.source_corrected_paid_amount,
          v_effective_case_amount_ex,
          v_new_outstanding_amount,
          case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
            else pa.taxability
          end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
            else pa.routing_kind
          end
        );

      get diagnostics v_case_update_count = row_count;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if v_case_update_count > 0
         and upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF'
         and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      elsif v_case_update_count > 0 then
        v_cases_amended := v_cases_amended + 1;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      COALESCE(v_effective_case_amount_ex, v_target_case_amount_ex),
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    if v_selected_event_type is not null then
    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
    end if;

    IF COALESCE(v_active_reservation_protection_applied, false) THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_selected_finance_case_id,
        'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        v_case_before_json,
        jsonb_build_object(
          'target_case_amount_ex', v_target_case_amount_ex,
          'effective_case_amount_ex', v_effective_case_amount_ex,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount,
          'existing_recovered_amount', v_existing_recovered_amount,
          'outstanding_amount', v_new_outstanding_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred overpayment/underpayment case shrink because an active recovery reservation exists.'
      );
    END IF;
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from public.pay_finance_case_events sync_clear_safety_events
        where sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_clear_safety_events.reason, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      )
  loop
    SELECT ROUND(COALESCE(SUM(ABS(COALESCE(advance_reservation.reserved_source_amount, advance_reservation.reserved_amount, batch_item.frozen_source_amount, batch_item.amount_ex_vat, batch_item.amount_inc_vat, 0))), 0), 2)::numeric(12,2)
    INTO v_existing_active_reserved_amount
    FROM public.pay_advance_reservations AS advance_reservation
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = advance_reservation.pay_batch_item_id
    WHERE advance_reservation.finance_case_id = v_open_case_candidate.finance_case_id
      AND UPPER(BTRIM(COALESCE(advance_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND advance_reservation.released_at_utc IS NULL
      AND (batch_item.id IS NULL OR COALESCE(batch_item.is_voided, false) IS NOT TRUE);

    IF COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_open_case_candidate.finance_case_id,
        'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_open_case_candidate.old_case_type::text,
          'status', 'ACTIVE',
          'original_amount', v_open_case_candidate.old_original_amount,
          'outstanding_amount', v_open_case_candidate.old_outstanding_amount
        ),
        jsonb_build_object(
          'clear_deferred', true,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred finance case clear because an active recovery reservation exists.'
      );

      CONTINUE;
    END IF;

    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_existing_case_row.candidate_id::text,
                'timesheet_id', v_existing_case_row.timesheet_id::text,
                'operation', 'CLEAR',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'operation', 'RECONCILE',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    SELECT
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
    INTO
      v_component_case_outstanding_amount,
      v_component_open_remaining_total
    FROM public.pay_advances AS pa
    LEFT JOIN public.pay_finance_case_components AS pfc
      ON pfc.finance_case_id = pa.id
    WHERE pa.id = v_target_case_row.finance_case_id
    GROUP BY pa.outstanding_amount;

    v_component_case_mismatch_amount := round(
      coalesce(v_component_case_outstanding_amount, 0) - coalesce(v_component_open_remaining_total, 0),
      2
    )::numeric(12,2);

    IF abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'case_outstanding_amount', coalesce(v_component_case_outstanding_amount, 0),
                'open_component_remaining_total', coalesce(v_component_open_remaining_total, 0),
                'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', v_preview_candidate_count,
      'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
      'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
      'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
      'preview_scope_strategy', v_preview_scope_strategy,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'requested_candidate_count', v_requested_candidate_count,
    'preview_candidate_count', v_preview_candidate_count,
    'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
    'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb),
    'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
    'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
    'preview_scope_strategy', v_preview_scope_strategy,
    'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );
exception
  when others then
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_ensure_run(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
  v_effective_week_ending_cutoff date := DATE '9999-12-31';
  v_pay_eligibility_months_back integer := 6;
  v_pay_eligibility_weeks_ahead integer := 2;
  v_pay_week_start date;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_snapshot_run_id uuid;
  v_status text;
  v_is_active boolean;
  v_was_created boolean := false;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_error_json jsonb := '{}'::jsonb;
  v_error_message text := NULL;
  v_error_sqlstate text := NULL;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  v_pay_week_start := public._pay_week_start_monday(p_pay_date);

  BEGIN
    SELECT
      sd.pay_eligibility_months_back,
      sd.pay_eligibility_weeks_ahead
    INTO
      v_pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead
    FROM public.settings_defaults AS sd
    ORDER BY sd.id ASC
    LIMIT 1;
  EXCEPTION
    WHEN undefined_column THEN
      v_pay_eligibility_months_back := 6;
      v_pay_eligibility_weeks_ahead := 2;
  END;

  v_pay_eligibility_months_back := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_months_back, 6), 120));
  v_pay_eligibility_weeks_ahead := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_weeks_ahead, 2), 52));

  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;

  SELECT
    sr.id,
    sr.status,
    sr.is_active
  INTO
    v_snapshot_run_id,
    v_status,
    v_is_active
  FROM public.banking_pay_snapshot_runs AS sr
  WHERE sr.pay_date = p_pay_date
    AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
    AND sr.is_active = true
  ORDER BY sr.created_at_utc DESC, sr.id DESC
  LIMIT 1;

  IF v_snapshot_run_id IS NULL THEN
    BEGIN
      INSERT INTO public.banking_pay_snapshot_runs (
        pay_date,
        week_ending_cutoff,
        pay_week_start,
        eligibility_from_date,
        eligibility_to_date,
        status,
        is_active,
        summary_json,
        paye_guardrails_json,
        created_at_utc,
        updated_at_utc,
        ready_at_utc,
        failed_at_utc,
        last_error_json
      )
      VALUES (
        p_pay_date,
        v_effective_week_ending_cutoff,
        v_pay_week_start,
        v_eligibility_from_date,
        v_eligibility_to_date,
        'OPEN',
        true,
        '{}'::jsonb,
        '{}'::jsonb,
        v_now,
        v_now,
        NULL,
        NULL,
        NULL
      )
      RETURNING
        public.banking_pay_snapshot_runs.id,
        public.banking_pay_snapshot_runs.status,
        public.banking_pay_snapshot_runs.is_active
      INTO
        v_snapshot_run_id,
        v_status,
        v_is_active;

      v_was_created := true;
    EXCEPTION
      WHEN unique_violation THEN
        SELECT
          sr.id,
          sr.status,
          sr.is_active
        INTO
          v_snapshot_run_id,
          v_status,
          v_is_active
        FROM public.banking_pay_snapshot_runs AS sr
        WHERE sr.pay_date = p_pay_date
          AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
          AND sr.is_active = true
        ORDER BY sr.created_at_utc DESC, sr.id DESC
        LIMIT 1;

        v_was_created := false;
      WHEN exclusion_violation THEN
        SELECT
          sr.id,
          sr.status,
          sr.is_active
        INTO
          v_snapshot_run_id,
          v_status,
          v_is_active
        FROM public.banking_pay_snapshot_runs AS sr
        WHERE sr.pay_date = p_pay_date
          AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
          AND sr.is_active = true
        ORDER BY sr.created_at_utc DESC, sr.id DESC
        LIMIT 1;

        v_was_created := false;
    END;
  END IF;

  IF v_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'Unable to create or reuse active banking pay snapshot run for pay_date % and cutoff %', p_pay_date, v_effective_week_ending_cutoff;
  END IF;

  v_audit_after_json := jsonb_build_object(
    'id', v_snapshot_run_id::text,
    'pay_date', p_pay_date::text,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'pay_week_start', v_pay_week_start::text,
    'eligibility_from_date', v_eligibility_from_date::text,
    'eligibility_to_date', v_eligibility_to_date::text,
    'status', v_status,
    'is_active', v_is_active
  );

  IF v_was_created THEN
    PERFORM public._audit_insert(
      'banking_pay_snapshot_run',
      v_snapshot_run_id::text,
      'CREATED',
      NULL,
      v_audit_after_json,
      'SNAPSHOT_RUN_CREATED_OR_REUSED',
      p_actor_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', v_snapshot_run_id::text,
    'pay_date', p_pay_date::text,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'pay_week_start', v_pay_week_start::text,
    'eligibility_from_date', v_eligibility_from_date::text,
    'eligibility_to_date', v_eligibility_to_date::text,
    'status', v_status,
    'is_active', v_is_active,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
    'created_or_reused_at_utc', v_now
  );
EXCEPTION
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_error_message = MESSAGE_TEXT,
      v_error_sqlstate = RETURNED_SQLSTATE;

    IF v_snapshot_run_id IS NOT NULL THEN
      v_error_json := jsonb_build_object(
        'sqlstate', v_error_sqlstate,
        'message', v_error_message,
        'failed_at_utc', v_now
      );

      UPDATE public.banking_pay_snapshot_runs AS sr
      SET updated_at_utc = v_now,
          failed_at_utc = v_now,
          last_error_json = v_error_json
      WHERE sr.id = v_snapshot_run_id;

      PERFORM public._audit_insert(
        'banking_pay_snapshot_run',
        v_snapshot_run_id::text,
        'FAILED',
        NULL,
        jsonb_build_object(
          'id', v_snapshot_run_id::text,
          'pay_date', p_pay_date::text,
          'week_ending_cutoff', v_effective_week_ending_cutoff::text,
          'pay_week_start', v_pay_week_start::text,
          'eligibility_from_date', v_eligibility_from_date::text,
          'eligibility_to_date', v_eligibility_to_date::text,
          'status', v_status,
          'is_active', v_is_active,
          'last_error_json', v_error_json
        ),
        'SNAPSHOT_RUN_IMMEDIATE_FAILURE',
        p_actor_user_id
      );
    END IF;

    RAISE;
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_id uuid := NULL::uuid;
  v_session_id_text text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_actor_user_id uuid := p_actor_user_id;
  v_live_change_seq bigint := 0;
  v_payload_source_change_seq bigint := NULL::bigint;
  v_source_change_seq bigint := 0;
  v_job_type text := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_pay_channel_scope text := 'ALL';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_source_build_run_id_text text := NULL::text;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_build_hash text := NULL::text;
  v_source_build_seed_text text := NULL::text;
  v_initial_cursor_json jsonb := '{}'::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_stage_limit integer := 100;
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_insert_row_count integer := 0;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_CANDIDATE_SOURCE_BUILD');
  v_payload_out_json jsonb := '{}'::jsonb;
  v_classifier_result jsonb := '{}'::jsonb;
  v_force_legacy boolean := false;
  v_force_broad_legacy boolean := false;
  v_resolved_job_type text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_projection_run_id_text text := NULL::text;
  v_projection_mode text := 'LEGACY';
  v_projection_class text := 'UNKNOWN';
  v_resolved_mode text := 'LEGACY';
  v_no_job_reason text := NULL::text;
  v_delta_jobs_superseded integer := 0;
  v_delta_ids_hash text := NULL::text;
  v_delta_coalescing_key text := NULL::text;
  v_delta_coalescing_hash text := NULL::text;
  v_delta_active_running_job_id uuid := NULL::uuid;
  v_existing_delta_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_existing_delta_source_change_seq bigint := 0;
  v_existing_delta_event_count integer := 0;
  v_merged_delta_event_count integer := 1;
  v_existing_delta_projection_run_id_text text := NULL::text;
  v_delta_merge_reused_existing boolean := false;
  v_payload_shadow_compare_required boolean := false;
  v_payload_shadow_compare_enforced boolean := false;
  v_rotation_scope_json jsonb := '{}'::jsonb;
  v_early_preflight_result jsonb := '{}'::jsonb;
  v_early_preflight_action text := 'PROCEED';
  v_early_preflight_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_early_preflight_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.banking_pay_snapshot_runs AS snapshot_run
  WHERE snapshot_run.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_id',
    v_payload_json->>'source_session_id',
    v_payload_json->>'workbench_session_id',
    v_payload_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_session_id_text IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', NULL::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', 0,
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false,
      'full_snapshot_job', false,
      'no_op', true,
      'deferred', true,
      'requires_workbench_session', true,
      'reason', v_reason,
      'message', 'Banking Pay candidate refresh now requires a row-backed workbench session.'
    );
  END IF;

  IF v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID',
              'session_id', v_session_id_text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_session_id := v_session_id_text::uuid;

  SELECT COALESCE(array_agg(DISTINCT parsed_target_ids.timesheet_id_value ORDER BY parsed_target_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_targeted_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(targeted_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(array_agg(DISTINCT parsed_linked_ids.timesheet_id_value ORDER BY parsed_linked_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_linked_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  IF COALESCE(array_length(v_early_preflight_targeted_timesheet_ids, 1), 0) > 0 THEN
    SELECT public.pay_workbench_authorise_delta_hotkey_preflight(
      p_session_id => v_session_id,
      p_candidate_id => p_candidate_id,
      p_targeted_timesheet_ids => v_early_preflight_targeted_timesheet_ids,
      p_linked_timesheet_ids => v_early_preflight_linked_timesheet_ids,
      p_payload_json => v_payload_json || jsonb_build_object(
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      p_reason => v_reason,
      p_actor_user_id => v_actor_user_id,
      p_source_change_seq => NULL::bigint
    ) INTO v_early_preflight_result;

    v_early_preflight_action := COALESCE(v_early_preflight_result->>'action', 'PROCEED');

    IF v_early_preflight_action IN ('REUSED_QUEUED_SAME_FAMILY_JOB', 'UPDATED_WAITING_AFTER_RUNNING_JOB') THEN
      RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'job_id', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'job_id', '')), ''),
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', CASE WHEN COALESCE(v_early_preflight_result->>'latest_source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_early_preflight_result->>'latest_source_change_seq')::bigint ELSE NULL::bigint END,
        'dedupe_key', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'normalised_delta_family_key', '')), ''),
        'reason', v_reason,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'targeted_timesheet_ids', COALESCE(v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_early_preflight_result->'linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_targeted_timesheet_ids', v_early_preflight_result->'resolved_family_timesheet_ids', v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'source_build_required', false,
        'line_work_required', false,
        'line_work_only', false,
        'delta_refresh_required', true,
        'scope_status', 'DELTA_REFRESH_PENDING',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'full_snapshot_job', false,
        'reused', true,
        'early_preflight_action', v_early_preflight_action,
        'early_preflight_result', COALESCE(v_early_preflight_result, '{}'::jsonb),
        'early_preflight_returned_before_session_lock', true,
        'session_lock_skipped', true,
        'scope_lock_skipped', true,
        'classifier_work_skipped', true,
        'dirty_marking_skipped', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ));
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', v_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open', v_session_id;
  END IF;

  IF v_session_row.source_snapshot_run_id IS DISTINCT FROM p_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH',
              'session_id', v_session_id::text,
              'payload_snapshot_run_id', p_snapshot_run_id::text,
              'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_session_scope AS session_scope
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, v_session_id;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF COALESCE(v_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_seq')::bigint;
  ELSIF COALESCE(v_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_sequence')::bigint;
  ELSIF COALESCE(v_payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json#>>'{source_build,source_change_seq}')::bigint;
  END IF;

  v_source_change_seq := GREATEST(COALESCE(v_payload_source_change_seq, 0), COALESCE(v_live_change_seq, 0));

  SELECT COALESCE(jsonb_agg(parsed_target_ids.timesheet_id_text ORDER BY parsed_target_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(jsonb_agg(parsed_linked_ids.timesheet_id_text ORDER BY parsed_linked_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'refresh_scope_kind',
    v_payload_json#>>'{source_build,refresh_scope_kind}',
    v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
    ''
  ))), '');

  IF v_refresh_scope_kind IS NULL OR v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;
  END IF;


  v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
     AND to_regprocedure('public._pay_workbench_normalise_timesheet_rotation_scope_payload(uuid[],uuid[])') IS NOT NULL THEN
    SELECT public._pay_workbench_normalise_timesheet_rotation_scope_payload(
      COALESCE((
        SELECT array_agg(DISTINCT targeted_value.value::uuid ORDER BY targeted_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS targeted_value(value)
        WHERE targeted_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[]),
      COALESCE((
        SELECT array_agg(DISTINCT linked_value.value::uuid ORDER BY linked_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
        WHERE linked_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[])
    )
    INTO v_rotation_scope_json;

    v_payload_json := public._pay_workbench_merge_targeted_scope_payload(
      v_payload_json,
      jsonb_build_object(
        'targeted_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_linked_timesheet_ids', v_linked_timesheet_ids_json),
        'requested_timesheet_ids', COALESCE(v_rotation_scope_json->'requested_timesheet_ids', v_targeted_timesheet_ids_json),
        'family_timesheet_ids', COALESCE(v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids', COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'queue_identity_linked_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'rotation_family_scope_for_queue_identity', true,
        'queue_identity_preserves_targeted_linked_semantics', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );
    v_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json);
    v_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  END IF;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'pay_channel_scope',
    v_payload_json#>>'{source_build,pay_channel_scope}',
    v_payload_json#>>'{preview_decisions_json,pay_channel_scope}',
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_force_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_force_broad_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_broad_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF jsonb_typeof(v_payload_json->'classifier_result') = 'object' THEN
    v_classifier_result := v_payload_json->'classifier_result';
  ELSIF v_payload_json ? 'fast_path_allowed' OR v_payload_json ? 'resolved_job_type' THEN
    v_classifier_result := v_payload_json;
  ELSIF to_regprocedure('public.pay_workbench_delta_refresh_classify_v1(uuid,uuid,jsonb)') IS NOT NULL THEN
    v_classifier_result := public.pay_workbench_delta_refresh_classify_v1(
      v_session_id,
      p_candidate_id,
      v_payload_json
      || jsonb_build_object(
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'pay_channel_scope', v_pay_channel_scope,
        'force_legacy', v_force_legacy,
        'force_broad_legacy', v_force_broad_legacy
      )
    );
  ELSE
    v_classifier_result := jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'projection_mode', 'LEGACY',
      'projection_class', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_payload_json->>'projection_class', ''))), ''), 'UNKNOWN_TRIGGER'),
      'scope_status', 'SOURCE_BUILD_PENDING',
      'fallback_required', true,
      'fallback_reason', 'DELTA_CLASSIFIER_NOT_INSTALLED'
    );
  END IF;

  v_classifier_result := COALESCE(v_classifier_result, '{}'::jsonb)
    - 'old_row_json'
    - 'new_row_json'
    - 'old_row'
    - 'new_row'
    - 'source_row_json'
    - 'work_payload_json'
    - 'result_row_json'
    - 'preview_row_json'
    - 'row_payload_json'
    - 'line_payload_json'
    - 'projection_rows'
    - 'projected_rows';

  v_resolved_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', v_classifier_result->>'routing_decision', v_classifier_result->>'projection_mode', 'LEGACY')));
  IF v_resolved_mode NOT IN ('DELTA', 'PATCH_ONLY', 'CLONE_REBASE', 'LEGACY', 'BLOCKED') THEN
    v_resolved_mode := 'LEGACY';
  END IF;

  v_resolved_job_type := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_job_type', CASE WHEN v_resolved_mode = 'DELTA' THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH' WHEN v_resolved_mode = 'LEGACY' THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD' ELSE 'NOOP' END)));
  v_projection_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_mode', v_payload_json->>'projection_mode', 'LEGACY')));
  v_projection_class := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_class', v_payload_json->>'projection_class', 'UNKNOWN')));

  IF jsonb_typeof(v_classifier_result->'targeted_timesheet_ids') = 'array' THEN
    v_targeted_timesheet_ids_json := v_classifier_result->'targeted_timesheet_ids';
  END IF;
  IF jsonb_typeof(v_classifier_result->'linked_timesheet_ids') = 'array' THEN
    v_linked_timesheet_ids_json := v_classifier_result->'linked_timesheet_ids';
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_targeted_timesheet_ids') = 'array' THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_targeted_timesheet_ids', v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_linked_timesheet_ids') = 'array' THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_linked_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF v_force_legacy IS TRUE OR v_force_broad_legacy IS TRUE THEN
    v_resolved_mode := 'LEGACY';
    v_resolved_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  v_payload_shadow_compare_required := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_required',
    v_payload_json->>'shadow_compare',
    v_payload_json->>'shadow_mode',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_payload_shadow_compare_enforced := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_enforced',
    v_payload_json->>'enforce_shadow_compare',
    v_payload_json->>'shadow_enforced',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_shadow_compare_required := (
    lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,delta_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,payload_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_payload_shadow_compare_required
  );

  v_shadow_compare_enforced := COALESCE(v_shadow_compare_required, false) AND (
    COALESCE(v_payload_shadow_compare_enforced, false)
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
  );

  IF v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE', 'BLOCKED') THEN
    v_no_job_reason := CASE
      WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'PATCH_ONLY_NO_SOURCE_BUILD_JOB')
      WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLONE_REBASE_NOT_A_CANDIDATE_SOURCE_BUILD_JOB')
      ELSE COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLASSIFIER_BLOCKED_REFRESH')
    END;

    UPDATE public.banking_pay_workbench_session_scope AS no_job_scope
    SET status = CASE
          WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'PATCH_ONLY_PENDING')
          WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'CLONE_REBASE_PENDING')
          ELSE COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), no_job_scope.status)
        END,
        pending_job_id = NULL,
        dirty = false,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE no_job_scope.session_id = v_session_id
      AND no_job_scope.candidate_id = p_candidate_id
      AND v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE');

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'reason', v_reason,
      'resolved_mode', v_resolved_mode,
      'projection_mode', v_projection_mode,
      'projection_class', v_projection_class,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'pay_channel_scope', v_pay_channel_scope,
      'source_build_required', false,
      'line_work_required', false,
      'line_work_only', false,
      'delta_refresh_required', false,
      'patch_only', v_resolved_mode = 'PATCH_ONLY',
      'clone_rebase_required', v_resolved_mode = 'CLONE_REBASE',
      'blocked', v_resolved_mode = 'BLOCKED',
      'no_op', v_resolved_mode = 'BLOCKED',
      'deferred', v_resolved_mode = 'CLONE_REBASE',
      'fallback_required', lower(BTRIM(COALESCE(v_classifier_result->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'fallback_reason', v_no_job_reason,
      'classifier_result', v_classifier_result
    ));
  END IF;

  IF v_resolved_mode = 'DELTA'
     AND v_resolved_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
     AND lower(BTRIM(COALESCE(v_classifier_result->>'fast_path_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     AND v_force_legacy IS NOT TRUE
     AND v_force_broad_legacy IS NOT TRUE THEN
    v_job_type := 'WORKBENCH_CANDIDATE_DELTA_REFRESH';
  ELSE
    v_resolved_mode := 'LEGACY';
    v_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  IF COALESCE(v_payload_json->>'source_build_limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'source_build_limit')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json#>>'{stage_limits,source_build}', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json#>>'{stage_limits,source_build}')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSE
    SELECT LEAST(GREATEST(COALESCE(
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job')::integer
        ELSE NULL::integer
      END,
      25
    ), 1), 100)
    INTO v_stage_limit
    FROM public.settings_defaults AS settings_row
    WHERE settings_row.id = 1
    LIMIT 1;

    v_stage_limit := COALESCE(v_stage_limit, 25);
  END IF;

  v_initial_cursor_json := CASE
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object' THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object' THEN v_payload_json->'cursor'
    WHEN jsonb_typeof(v_payload_json->'source_cursor') = 'object' THEN v_payload_json->'source_cursor'
    WHEN jsonb_typeof(v_payload_json#>'{source_build,cursor}') = 'object' THEN v_payload_json#>'{source_build,cursor}'
    ELSE '{}'::jsonb
  END;

  v_cursor_token := md5(COALESCE(v_initial_cursor_json, '{}'::jsonb)::text);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'projection_run_id', v_classifier_result->>'projection_run_id', '')), '');
    IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_projection_run_id := v_projection_run_id_text::uuid;
    ELSE
      v_projection_run_id := gen_random_uuid();
    END IF;

    v_delta_ids_hash := md5(
      COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
      || ':'
      || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
    );

    v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
    v_delta_coalescing_hash := md5(v_delta_coalescing_key);

    SELECT running_delta_job.id
    INTO v_delta_active_running_job_id
    FROM public.banking_pay_workbench_jobs AS running_delta_job
    WHERE running_delta_job.session_id = v_session_id
      AND running_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
      AND (
        COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
    ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
    LIMIT 1;

    v_dedupe_key := CASE
      WHEN v_delta_active_running_job_id IS NOT NULL THEN
        v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
      ELSE
        v_delta_coalescing_key
    END;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'cursor_json', '{}'::jsonb,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
        'delta_coalescing_key', v_delta_coalescing_key,
        'delta_family_key', v_delta_coalescing_key,
        'normalised_delta_family_key', v_delta_coalescing_key,
        'delta_coalescing_hash', v_delta_coalescing_hash,
        'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_source_change_seq, 0)),
        'coalesced_event_count', 1,
        'latest_event_at_utc', v_now::text,
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      )
      || jsonb_build_object(
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'pay_channel_scope', v_pay_channel_scope,
        'refresh_scope_kind', COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'),
        'candidate_id', p_candidate_id::text,
        'dedupe_key', v_dedupe_key,
        'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
        'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
        'classifier_result', v_classifier_result,
        'fallback_required', false,
        'fallback_reason', NULL::text,
        'force_legacy', false,
        'force_broad_legacy', false
      )
      || jsonb_build_object(
        'mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'lifecycle_mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'authorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'authorise_boundary_changed', v_classifier_result#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'unauthorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'unauthorise_boundary_changed', v_classifier_result#>>'{complexity_flags,unauthorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'explicit_banking_pay_action', lower(BTRIM(COALESCE(v_payload_json->>'explicit_banking_pay_action', v_classifier_result#>>'{complexity_flags,explicit_banking_pay_action}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'banking_pay_dirty_required', lower(BTRIM(COALESCE(v_payload_json->>'banking_pay_dirty_required', v_classifier_result->>'banking_pay_dirty_required', v_classifier_result#>>'{complexity_flags,banking_pay_dirty_required}', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'ordinary_timesheet_edit_save_no_dirty', lower(BTRIM(COALESCE(v_payload_json->>'ordinary_timesheet_edit_save_no_dirty', v_classifier_result#>>'{complexity_flags,ordinary_timesheet_edit_save_no_dirty}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
    );
  ELSE
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      v_payload_json->>'source_build_run_id',
      v_payload_json#>>'{source_build,source_build_run_id}',
      v_payload_json#>>'{source_build,run_id}',
      v_initial_cursor_json->>'source_build_run_id',
      ''
    )), '');

    IF v_source_build_run_id_text IS NOT NULL THEN
      IF v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID',
                  'source_build_run_id', v_source_build_run_id_text,
                  'session_id', v_session_id::text,
                  'candidate_id', p_candidate_id::text
                )::text;
      END IF;
      v_source_build_run_id := v_source_build_run_id_text::uuid;
    ELSE
      v_source_build_seed_text := concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        p_snapshot_run_id::text,
        v_session_id::text,
        p_candidate_id::text,
        COALESCE(v_session_row.version, 0)::text,
        COALESCE(v_source_change_seq, 0)::text,
        v_refresh_scope_kind,
        md5(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)::text),
        md5(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)::text),
        v_pay_channel_scope,
        v_reason
      );
      v_source_build_hash := md5(v_source_build_seed_text);
      v_source_build_run_id := (
        substr(v_source_build_hash, 1, 8) || '-' ||
        substr(v_source_build_hash, 9, 4) || '-' ||
        substr(v_source_build_hash, 13, 4) || '-' ||
        substr(v_source_build_hash, 17, 4) || '-' ||
        substr(v_source_build_hash, 21, 12)
      )::uuid;
    END IF;

    v_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      || ':session:' || v_session_id::text
      || ':version:' || COALESCE(v_session_row.version, 0)::text
      || ':snapshot:' || v_session_row.source_snapshot_run_id::text
      || ':signature:' || v_session_signature_token
      || ':candidate:' || p_candidate_id::text
      || ':source_change:' || COALESCE(v_source_change_seq, 0)::text
      || ':source_build:' || v_source_build_run_id::text
      || ':cursor:' || v_cursor_token;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'resolved_mode', 'LEGACY',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'session_signature_token', v_session_signature_token
      )
      || jsonb_build_object(
        'candidate_id', p_candidate_id::text,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'source_build_run_id', v_source_build_run_id::text,
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
      )
      || jsonb_build_object(
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'delta_refresh_required', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD_THEN_SEED',
        'source_build_limit', v_stage_limit,
        'limit', v_stage_limit,
        'source_cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_json', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_token', v_cursor_token
      )
      || jsonb_build_object(
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'dedupe_key', v_dedupe_key,
        'created_by_helper', 'pay_workbench_enqueue_candidate_refresh',
        'created_at_utc', v_now::text,
        'classifier_result', v_classifier_result
      )
      || jsonb_build_object(
        'source_build', jsonb_strip_nulls(jsonb_build_object(
          'required', true,
          'run_id', v_source_build_run_id::text,
          'source_build_run_id', v_source_build_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'session_version', COALESCE(v_session_row.version, 0),
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_pay_channel_scope,
          'limit', v_stage_limit,
          'cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
          'reason', v_reason
        ))
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    SELECT existing_delta_job.*
    INTO v_existing_delta_job
    FROM public.banking_pay_workbench_jobs AS existing_delta_job
    WHERE existing_delta_job.session_id = v_session_id
      AND existing_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(existing_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(existing_delta_job.status, ''))) = 'QUEUED'
      AND (
        COALESCE(existing_delta_job.payload_json->>'normalised_delta_family_key', existing_delta_job.payload_json->>'delta_family_key', existing_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.session_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.candidate_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    ORDER BY
      CASE
        WHEN COALESCE(existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (existing_delta_job.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END DESC,
      existing_delta_job.priority ASC,
      existing_delta_job.run_at_utc ASC,
      existing_delta_job.created_at_utc ASC,
      existing_delta_job.id ASC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      -- Reused queued latest-state heads must not inherit an old projection/cursor identity.
      v_existing_delta_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_existing_delta_job.payload_json->>'projection_run_id', '')), '');
      v_projection_run_id := gen_random_uuid();

      v_existing_delta_source_change_seq := GREATEST(
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );
      v_existing_delta_event_count := CASE
        WHEN COALESCE(v_existing_delta_job.payload_json->>'coalesced_event_count', '') ~ '^[0-9]{1,9}$'
          THEN GREATEST((v_existing_delta_job.payload_json->>'coalesced_event_count')::integer, 1)
        ELSE 1
      END;
      v_merged_delta_event_count := v_existing_delta_event_count + 1;

      v_payload_out_json := public._pay_workbench_merge_targeted_scope_payload(
        COALESCE(v_existing_delta_job.payload_json, '{}'::jsonb),
        COALESCE(v_payload_out_json, '{}'::jsonb)
      ) || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      );

      v_source_change_seq := GREATEST(
        COALESCE(v_live_change_seq, 0),
        COALESCE(v_source_change_seq, 0),
        COALESCE(v_existing_delta_source_change_seq, 0),
        CASE WHEN COALESCE(v_payload_out_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );

      SELECT COALESCE(jsonb_agg(merged_target_ids.timesheet_id_text ORDER BY merged_target_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_targeted_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'array' THEN v_payload_out_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'targeted_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS targeted_values(value)
        WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_target_ids;

      SELECT COALESCE(jsonb_agg(merged_linked_ids.timesheet_id_text ORDER BY merged_linked_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_linked_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'array' THEN v_payload_out_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'linked_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS linked_values(value)
        WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_linked_ids;

      v_delta_ids_hash := md5(
        COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
        || ':'
        || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
      );

      v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
      v_delta_coalescing_hash := md5(v_delta_coalescing_key);

      v_payload_out_json := jsonb_strip_nulls(
        (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
          'cursor',
          'cursor_json',
          'next_cursor',
          'next_cursor_json',
          'source_cursor',
          'write_cursor_json',
          'candidate_cursor',
          'cursor_token',
          'has_cursor',
          'continuation_reason',
          'source_job_id',
          'continuation_source_job_id',
          'bounded_continuation_source_job_id',
          'parent_job_id',
          'next_phase',
          'write_phase',
          'source_result_summary',
          'source_result_has_more',
          'source_result_next_cursor_present'
        ]::text[])
        || jsonb_build_object(
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash
        )
      );

      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND running_delta_job.id IS DISTINCT FROM v_existing_delta_job.id
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
              SELECT
                'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.session_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                  ''
                )), ''), 'none')
                || ':version:' || COALESCE(
                  CASE
                    WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                      THEN delta_family_values.session_version_text::bigint
                    ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                  END,
                  0
                )::text
                || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_mode_text, ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))), ''), 'DELTA')
                || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_class_text, ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))), ''), 'UNKNOWN')
                || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                  CASE
                    WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                      OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                      THEN 'TARGETED_TIMESHEETS'
                    ELSE 'CANDIDATE_FULL_LIVE'
                  END
                ))), ''), 'CANDIDATE_FULL_LIVE')
                || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.candidate_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                  ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                  ''
                )), ''), 'none')
                || ':timesheets:' || md5(
                  COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                  || ':'
                  || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                )
              FROM (
                SELECT
                  NULLIF(BTRIM(COALESCE(
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                    CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                    '0'
                  )), '') AS session_version_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                    NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                    'DELTA'
                  ))) AS projection_mode_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                    NULLIF(v_projection_class, ''),
                    'UNKNOWN'
                  ))) AS projection_class_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                    NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                  ))) AS refresh_scope_kind_text
              ) AS delta_family_values
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                      WHEN NULLIF(BTRIM(COALESCE(
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                             ''
                           )), '') IS NOT NULL
                        THEN jsonb_build_array(COALESCE(
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                        ))
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_targeted_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_targeted_sorted
              ) AS delta_family_targeted
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_linked_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_linked_sorted
              ) AS delta_family_linked
            ) = v_delta_coalescing_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      v_dedupe_key := CASE
        WHEN v_delta_active_running_job_id IS NOT NULL THEN
          v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
        ELSE
          v_delta_coalescing_key
      END;

      v_payload_out_json := jsonb_strip_nulls(
        v_payload_out_json
        || jsonb_build_object(
          'dedupe_key', v_dedupe_key,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
          'projection_run_id', v_projection_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash,
          'coalesced_event_count', GREATEST(COALESCE(v_merged_delta_event_count, 1), 1),
          'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_existing_delta_source_change_seq, 0), COALESCE(v_source_change_seq, 0)),
          'latest_event_at_utc', v_now::text,
          'scope_merge_applied', true,
          'scope_merge_at_utc', v_now::text,
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END
        )
      );

      UPDATE public.banking_pay_workbench_jobs AS existing_delta_update
      SET dedupe_key = v_dedupe_key,
          priority = LEAST(existing_delta_update.priority, 43),
          run_at_utc = LEAST(existing_delta_update.run_at_utc, v_now),
          payload_json = v_payload_out_json,
          updated_at_utc = v_now
      WHERE existing_delta_update.id = v_existing_delta_job.id
      RETURNING existing_delta_update.id,
                existing_delta_update.status,
                false
      INTO v_job_id,
           v_job_status,
           v_job_was_inserted;

      v_delta_merge_reused_existing := true;
    END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_payload_out_json := jsonb_strip_nulls(
      (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
        'old_row_json',
        'new_row_json',
        'old_row',
        'new_row',
        'source_row_json',
        'work_payload_json',
        'result_row_json',
        'preview_row_json',
        'row_payload_json',
        'line_payload_json',
        'projection_rows',
        'projected_rows',
        'cursor',
        'cursor_json',
        'next_cursor',
        'next_cursor_json',
        'source_cursor',
        'write_cursor_json',
        'candidate_cursor',
        'cursor_token',
        'has_cursor',
        'continuation_reason',
        'source_job_id',
        'continuation_source_job_id',
        'bounded_continuation_source_job_id',
        'parent_job_id',
        'next_phase',
        'write_phase',
        'source_result_summary',
        'source_result_has_more',
        'source_result_next_cursor_present'
      ]::text[])
      || jsonb_build_object(
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
        'phase', 'INIT_PREFLIGHT'
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    UPDATE public.banking_pay_workbench_jobs AS queued_delta_job
    SET status = 'SUCCEEDED',
        completed_at_utc = v_now,
        updated_at_utc = v_now,
        payload_json = jsonb_strip_nulls(
          COALESCE(queued_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_legacy', true,
            'superseded_by_legacy_at_utc', v_now::text,
            'superseded_reason', COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'LEGACY_REFRESH_WINS'),
            'legacy_source_change_seq', COALESCE(v_source_change_seq, 0)
          )
        )
    WHERE queued_delta_job.session_id = v_session_id
      AND queued_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(queued_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(queued_delta_job.status, ''))) = 'QUEUED';
    GET DIAGNOSTICS v_delta_jobs_superseded = ROW_COUNT;
  END IF;

  IF v_job_id IS NULL THEN
    INSERT INTO public.banking_pay_workbench_jobs AS enqueue_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    VALUES (
      v_job_type,
      'QUEUED',
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 43 ELSE 44 END,
      v_now,
      0,
      8,
      v_dedupe_key,
      p_snapshot_run_id,
      v_session_id,
      p_candidate_id,
      v_payload_out_json,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(enqueue_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = CASE
          WHEN EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
            jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', CASE
                  WHEN lower(BTRIM(COALESCE(EXCLUDED.payload_json->>'waiting_after_running_delta_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'LATEST_RERUN_AFTER_RUNNING'
                  ELSE 'LATEST_STATE_HEAD'
                END,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            )
          ELSE public._pay_workbench_merge_targeted_scope_payload(
            COALESCE(enqueue_job.payload_json, '{}'::jsonb),
            COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
          )
        END,
        updated_at_utc = v_now
    WHERE NOT (
      UPPER(BTRIM(COALESCE(enqueue_job.status, ''))) = 'RUNNING'
      AND EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    )
    RETURNING enqueue_job.id,
              enqueue_job.status,
              (xmax = 0)
    INTO v_job_id, v_job_status, v_job_was_inserted;

    GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;

    IF COALESCE(v_insert_row_count, 0) = 0
       AND v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
          OR running_delta_job.dedupe_key = v_dedupe_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      IF v_delta_active_running_job_id IS NOT NULL THEN
        v_dedupe_key := v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text;

        v_payload_out_json := jsonb_strip_nulls(
          COALESCE(v_payload_out_json, '{}'::jsonb)
          || jsonb_build_object(
            'dedupe_key', v_dedupe_key,
            'delta_active_running_job_id', v_delta_active_running_job_id::text,
            'waiting_after_running_delta_job', true,
            'waiting_after_running_enqueued_at_utc', v_now::text,
            'delta_running_conflict_fail_closed', true
          )
        );

        INSERT INTO public.banking_pay_workbench_jobs AS waiting_enqueue_job (
          job_type,
          status,
          priority,
          run_at_utc,
          attempt_count,
          max_attempts,
          dedupe_key,
          snapshot_run_id,
          session_id,
          candidate_id,
          payload_json,
          created_at_utc,
          updated_at_utc,
          started_at_utc,
          completed_at_utc,
          failed_at_utc,
          last_error_json
        )
        VALUES (
          v_job_type,
          'QUEUED',
          43,
          v_now,
          0,
          8,
          v_dedupe_key,
          p_snapshot_run_id,
          v_session_id,
          p_candidate_id,
          v_payload_out_json,
          v_now,
          v_now,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::jsonb
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
        DO UPDATE
        SET priority = LEAST(waiting_enqueue_job.priority, EXCLUDED.priority),
            run_at_utc = LEAST(waiting_enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
            payload_json = jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(waiting_enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
                'waiting_after_running_delta_job', true,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            ),
            updated_at_utc = v_now
        WHERE UPPER(BTRIM(COALESCE(waiting_enqueue_job.status, ''))) <> 'RUNNING'
        RETURNING waiting_enqueue_job.id,
                  waiting_enqueue_job.status,
                  (xmax = 0)
        INTO v_job_id, v_job_status, v_job_was_inserted;

        GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;
      END IF;
    END IF;

    IF v_job_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT'
        USING ERRCODE = '55000',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT',
                'session_id', v_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type,
                'delta_coalescing_key', v_delta_coalescing_key,
                'dedupe_key', v_dedupe_key,
                'active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
                'message', 'A running delta refresh head was detected during enqueue conflict handling and a safe waiting-head could not be created.'
              )::text;
    END IF;
  END IF;

  UPDATE public.banking_pay_workbench_session_scope AS session_scope
  SET status = CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
      pending_job_id = v_job_id,
      dirty = true,
      error_json = NULL::jsonb,
      updated_at_utc = v_now
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL::jsonb,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
      'status', v_job_status,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'dedupe_key', v_dedupe_key,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
      'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_count', jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)),
      'linked_timesheet_count', jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)),
      'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
      'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
      'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
      'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
      'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0)
    ),
    'WORKBENCH_CANDIDATE_REFRESH_JOB_ENQUEUE',
    v_actor_user_id
  );

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'canonical_job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
    'snapshot_run_id', p_snapshot_run_id::text,
    'session_id', v_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'source_change_seq', COALESCE(v_source_change_seq, 0),
    'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
    'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
    'dedupe_key', v_dedupe_key,
    'reason', v_reason,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
    'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'pay_channel_scope', v_pay_channel_scope,
    'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_only', false,
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'scope_status', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
    'projection_mode', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA') ELSE NULL::text END,
    'projection_class', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_projection_class ELSE NULL::text END,
    'full_snapshot_job', false,
    'reused', NOT v_job_was_inserted,
    'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
    'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
    'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
    'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
    'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0),
    'classifier_result', v_classifier_result
  ));
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_session_candidate_refresh(
  p_session_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_actor_user_id uuid := p_actor_user_id;
  v_page_limit integer := 100;
  v_cursor_scope_ordinal bigint := -1;
  v_page_candidate_ids jsonb := '[]'::jsonb;
  v_page_next_cursor jsonb := NULL::jsonb;
  v_page_enqueue_result jsonb := '{}'::jsonb;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_direct_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);

  v_targeted_timesheet_ids_json := CASE
    WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
    WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
    WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
    ELSE '[]'::jsonb
  END;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = p_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
    END IF;

    IF jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 THEN
      v_direct_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => p_candidate_id,
        p_reason => COALESCE(p_reason, 'SESSION_CANDIDATE_TARGETED_REFRESH'),
        p_actor_user_id => v_actor_user_id,
        p_payload_json => v_payload_json || jsonb_build_object(
          'session_id', p_session_id::text,
          'source_session_id', p_session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', v_targeted_timesheet_ids_json
        )
      );

      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'job_type', v_direct_result->>'job_type',
        'delta_queued_count', CASE WHEN UPPER(BTRIM(COALESCE(v_direct_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 1 ELSE 0 END,
        'legacy_queued_count', CASE WHEN UPPER(BTRIM(COALESCE(v_direct_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 0 ELSE 1 END,
        'paged', false,
        'candidate_count', 1,
        'next_cursor', NULL::jsonb,
        'has_more', false,
        'enqueue_result', COALESCE(v_direct_result, '{}'::jsonb)
      );
    END IF;

    v_page_enqueue_result := public.pay_workbench_enqueue_candidate_refresh_many(
      p_session_id => p_session_id,
      p_candidate_ids => jsonb_build_array(p_candidate_id::text),
      p_reason => COALESCE(p_reason, 'SESSION_CANDIDATE_LINE_WORK'),
      p_actor_user_id => v_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'job_type', v_page_enqueue_result->>'first_stage_job_type',
      'delta_queued_count', COALESCE((v_page_enqueue_result->>'delta_queued_count')::integer, 0),
      'legacy_queued_count', COALESCE((v_page_enqueue_result->>'legacy_queued_count')::integer, 0),
      'paged', false,
      'candidate_count', 1,
      'next_cursor', NULL::jsonb,
      'has_more', false,
      'enqueue_result', COALESCE(v_page_enqueue_result, '{}'::jsonb)
    );
  END IF;

  IF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json#>>'{cursor,limit}', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_payload_json#>>'{cursor,limit}')::integer, 1), 100);
  ELSE
    v_page_limit := 100;
  END IF;

  BEGIN
    v_cursor_scope_ordinal := COALESCE(
      NULLIF(BTRIM(COALESCE(v_payload_json#>>'{cursor,last_scope_ordinal}', '')), '')::bigint,
      NULLIF(BTRIM(COALESCE(v_payload_json->>'last_scope_ordinal', '')), '')::bigint,
      -1
    );
  EXCEPTION WHEN OTHERS THEN
    v_cursor_scope_ordinal := -1;
  END;

  WITH page_scope AS (
    SELECT scope_row.candidate_id,
           scope_row.scope_ordinal,
           ROW_NUMBER() OVER (ORDER BY scope_row.scope_ordinal, scope_row.candidate_id) AS page_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.scope_ordinal > COALESCE(v_cursor_scope_ordinal, -1)
    ORDER BY scope_row.scope_ordinal, scope_row.candidate_id
    LIMIT (v_page_limit + 1)
  ),
  selected_scope AS (
    SELECT page_scope.candidate_id,
           page_scope.scope_ordinal,
           page_scope.page_ordinal
    FROM page_scope
    WHERE page_scope.page_ordinal <= v_page_limit
  )
  SELECT
    COALESCE(jsonb_agg(to_jsonb(selected_scope.candidate_id::text) ORDER BY selected_scope.scope_ordinal, selected_scope.candidate_id), '[]'::jsonb),
    CASE
      WHEN EXISTS (SELECT 1 FROM page_scope WHERE page_scope.page_ordinal > v_page_limit) THEN
        jsonb_build_object(
          'last_scope_ordinal',
          (SELECT selected_cursor.scope_ordinal FROM selected_scope AS selected_cursor ORDER BY selected_cursor.scope_ordinal DESC, selected_cursor.candidate_id DESC LIMIT 1)
        )
      ELSE NULL::jsonb
    END
  INTO
    v_page_candidate_ids,
    v_page_next_cursor
  FROM selected_scope;

  IF COALESCE(jsonb_array_length(v_page_candidate_ids), 0) > 0 THEN
    v_page_enqueue_result := public.pay_workbench_enqueue_candidate_refresh_many(
      p_session_id => p_session_id,
      p_candidate_ids => jsonb_build_object(
        'candidate_ids', v_page_candidate_ids,
        'skip_candidate_ids', CASE WHEN jsonb_typeof(v_payload_json->'skip_candidate_ids') = 'array' THEN v_payload_json->'skip_candidate_ids' ELSE '[]'::jsonb END
      ),
      p_reason => COALESCE(p_reason, 'SESSION_SCOPE_PAGE_LINE_WORK'),
      p_actor_user_id => v_actor_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', NULL::text,
    'paged', true,
    'limit', v_page_limit,
    'cursor_scope_ordinal', v_cursor_scope_ordinal,
    'candidate_count', COALESCE(jsonb_array_length(v_page_candidate_ids), 0),
    'next_cursor', v_page_next_cursor,
    'has_more', v_page_next_cursor IS NOT NULL,
    'delta_queued_count', COALESCE((v_page_enqueue_result->>'delta_queued_count')::integer, 0),
    'legacy_queued_count', COALESCE((v_page_enqueue_result->>'legacy_queued_count')::integer, 0),
    'clone_skipped_ready_count', COALESCE((v_page_enqueue_result->>'clone_skipped_ready_count')::integer, 0),
    'enqueue_result', COALESCE(v_page_enqueue_result, '{}'::jsonb)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_refresh_candidate(
  p_snapshot_run_id uuid,
  p_candidate_id uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_session_id uuid := NULL::uuid;
  v_line_action text := 'SEED';
  v_line_limit integer := 100;
  v_line_result jsonb := '{}'::jsonb;
  v_still_pending boolean := true;
  v_source_change_seq bigint := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  SELECT snapshot_run.*
  INTO v_snapshot_run_row
  FROM public.banking_pay_snapshot_runs AS snapshot_run
  WHERE snapshot_run.id = p_snapshot_run_id
  LIMIT 1;

  IF v_snapshot_run_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_payload_json->>'session_id', v_payload_json->>'source_session_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_session_id := NULLIF(BTRIM(COALESCE(v_payload_json->>'session_id', v_payload_json->>'source_session_id', '')), '')::uuid;
  END IF;

  v_line_action := UPPER(NULLIF(BTRIM(COALESCE(v_payload_json->>'line_work_action', v_payload_json->>'line_action', 'SEED')), ''));
  IF v_line_action NOT IN ('SEED', 'PROCESS', 'MATERIALISE', 'MATERIALIZE') THEN
    v_line_action := 'SEED';
  END IF;

  IF COALESCE(v_payload_json->>'line_limit', '') ~ '^[0-9]+$' THEN
    v_line_limit := LEAST(GREATEST((v_payload_json->>'line_limit')::integer, 1), 100);
  ELSE
    v_line_limit := 100;
  END IF;


  SELECT COALESCE(change_counter.seq, 0)
  INTO v_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF v_session_id IS NOT NULL THEN
    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS session_scope
    WHERE session_scope.session_id = v_session_id
      AND session_scope.candidate_id = p_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, v_session_id;
    END IF;

    IF v_line_action = 'PROCESS' THEN
      v_line_result := public.pay_workbench_candidate_line_work_process_chunk(
        p_session_id => v_session_id,
        p_candidate_id => p_candidate_id,
        p_cursor_json => COALESCE(v_payload_json->'line_process_cursor', v_payload_json->'cursor', NULL::jsonb),
        p_limit => v_line_limit
      );
    ELSIF v_line_action IN ('MATERIALISE', 'MATERIALIZE') THEN
      v_line_result := public.pay_workbench_preview_rows_materialise_chunk(
        p_session_id => v_session_id,
        p_candidate_id => p_candidate_id,
        p_cursor_json => COALESCE(v_payload_json->'line_materialise_cursor', v_payload_json->'cursor', NULL::jsonb),
        p_limit => v_line_limit
      );
    ELSE
      v_line_result := public.pay_workbench_candidate_line_work_seed(
        p_session_id => v_session_id,
        p_candidate_id => p_candidate_id,
        p_cursor_json => COALESCE(v_payload_json->'line_seed_cursor', v_payload_json->'cursor', NULL::jsonb),
        p_limit => v_line_limit
      );
    END IF;

    v_still_pending := COALESCE(NULLIF(BTRIM(COALESCE(v_line_result->>'has_more', '')), '')::boolean, false)
      OR COALESCE(NULLIF(BTRIM(COALESCE(v_line_result->>'pending', '')), '')::boolean, false)
      OR COALESCE(v_line_result->'next_cursor', NULL::jsonb) IS NOT NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'candidate_id', p_candidate_id::text,
      'session_id', v_session_id::text,
      'bounded_line_work', true,
      'line_work_action', v_line_action,
      'still_pending', COALESCE(v_still_pending, false),
      'candidate_still_pending', COALESCE(v_still_pending, false),
      'line_result', COALESCE(v_line_result, '{}'::jsonb),
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'no_op', false
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', p_snapshot_run_id::text,
    'candidate_id', p_candidate_id::text,
    'session_id', NULL::text,
    'bounded_line_work', false,
    'still_pending', true,
    'candidate_still_pending', true,
    'deferred', true,
    'reason', 'SESSION_REQUIRED_FOR_ROW_BACKED_LINE_WORK',
    'reason_code', 'SESSION_REQUIRED_FOR_ROW_BACKED_LINE_WORK',
    'source_change_seq', COALESCE(v_source_change_seq, 0),
    'no_op', true
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_payee_readiness_ensure(
  p_candidate_id uuid,
  p_payees_json jsonb,
  p_snapshot_run_id uuid DEFAULT NULL::uuid,
  p_session_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_source_change_seq bigint := 0;
  v_session_version bigint := NULL;
  v_resolved_snapshot_run_id uuid := p_snapshot_run_id;
  v_readiness_fingerprint text := md5(COALESCE(p_payees_json::text, '[]'));
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_completed_job_id uuid := NULL;
  v_completed_job_status text := NULL;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.candidates AS c
  WHERE c.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  IF p_payees_json IS NULL THEN
    RAISE EXCEPTION 'payees_json is required';
  END IF;

  IF jsonb_typeof(p_payees_json) <> 'array' THEN
    RAISE EXCEPTION 'payees_json must be a JSON array';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT ws.source_snapshot_run_id, ws.version
    INTO v_resolved_snapshot_run_id, v_session_version
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
    END IF;
  END IF;

  IF v_resolved_snapshot_run_id IS NOT NULL THEN
    SELECT COALESCE(snap.source_change_seq, 0)
    INTO v_source_change_seq
    FROM public.banking_pay_snapshot_candidate_state AS snap
    WHERE snap.snapshot_run_id = v_resolved_snapshot_run_id
      AND snap.candidate_id = p_candidate_id;
  END IF;

  IF v_source_change_seq = 0 THEN
    SELECT COALESCE(acc.seq, 0)
    INTO v_source_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_dedupe_key := 'PAYEE_READINESS_ENSURE:'
    || COALESCE(v_resolved_snapshot_run_id::text, 'no-run')
    || ':'
    || COALESCE(p_session_id::text, 'no-session')
    || ':'
    || p_candidate_id::text
    || ':s'
    || v_source_change_seq::text
    || ':'
    || v_readiness_fingerprint;

  SELECT j.id, j.status
  INTO v_completed_job_id, v_completed_job_status
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.job_type = 'PAYEE_READINESS_ENSURE'
    AND j.dedupe_key = v_dedupe_key
    AND j.completed_at_utc IS NOT NULL
    AND j.failed_at_utc IS NULL
  ORDER BY j.completed_at_utc DESC, j.id DESC
  LIMIT 1;

  IF v_completed_job_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_completed_job_id::text,
      'NO_OP',
      NULL,
      jsonb_build_object(
        'id', v_completed_job_id::text,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'status', v_completed_job_status,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'dedupe_key', v_dedupe_key,
        'reason', p_reason,
        'readiness_fingerprint', v_readiness_fingerprint
      ),
      'WORKBENCH_JOB_ENQUEUE',
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_completed_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint,
      'no_op', true,
      'reused', false
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    'PAYEE_READINESS_ENSURE',
    'QUEUED',
    100,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_resolved_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    COALESCE(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'reason', p_reason,
        'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'payees_json', p_payees_json,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'readiness_fingerprint', v_readiness_fingerprint
      ),
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
      updated_at_utc = v_now
  RETURNING public.banking_pay_workbench_jobs.id, public.banking_pay_workbench_jobs.status, (xmax = 0)
  INTO v_job_id, v_job_status, v_job_was_inserted;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'status', v_job_status,
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint
    ),
    'WORKBENCH_JOB_ENQUEUE',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', 'PAYEE_READINESS_ENSURE',
    'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
    'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_change_seq', v_source_change_seq,
    'dedupe_key', v_dedupe_key,
    'reason', p_reason,
    'readiness_fingerprint', v_readiness_fingerprint,
    'no_op', false,
    'reused', (NOT v_job_was_inserted)
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_workbench_claim_due_jobs(integer, timestamptz);
DROP FUNCTION IF EXISTS public.pay_workbench_claim_due_jobs(integer, timestamptz, uuid, uuid, jsonb);


CREATE OR REPLACE FUNCTION public.pay_workbench_claim_due_jobs(p_limit integer DEFAULT 25, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_allowed_job_types text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 25), 500));
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, v_now);
  v_stale_running_seconds integer := 180;
  v_configured_lease_seconds integer := NULL::integer;
  v_stale_cutoff timestamptz := NULL::timestamptz;
  v_recovered_stale jsonb := '[]'::jsonb;
  v_dead_stale jsonb := '[]'::jsonb;
  v_claimed jsonb := '[]'::jsonb;
  v_recovered_stale_count integer := 0;
  v_dead_stale_count integer := 0;
  v_claimed_count integer := 0;
  v_claimed_delta_refresh_count integer := 0;
  v_claimed_clone_rebase_count integer := 0;
  v_stale_row record;
  v_stale_before_json jsonb := NULL;
  v_stale_after_json jsonb := '{}'::jsonb;
  v_stale_error_json jsonb := NULL;
  v_claimed_row record;
  v_stale_job_source_change_seq bigint := 0;
  v_stale_job_session_version bigint := 0;
  v_stale_live_candidate_change_seq bigint := 0;
  v_stale_snapshot_state_status text := NULL;
  v_stale_snapshot_state_source_change_seq bigint := 0;
  v_stale_session_status text := NULL;
  v_stale_session_version bigint := 0;
  v_stale_session_candidate_status text := NULL;
  v_stale_session_candidate_source_change_seq bigint := 0;
  v_stale_session_candidate_session_version bigint := 0;
  v_stale_other_active_job_id uuid := NULL::uuid;
  v_stale_completed_equivalent_id uuid := NULL::uuid;
  v_stale_obsolete boolean := false;
  v_stale_obsolete_reason text := NULL;
  v_stale_canonical_job_type text := NULL::text;
  v_stale_failed_line_work_count integer := 0;
  v_stale_failed_source_row_count integer := 0;
  v_allowed_job_types text[] := NULL::text[];
  v_stale_recovery_limit integer := 0;
  v_preclaim_due_queued_count integer := 0;
  v_preclaim_due_queued_sample jsonb := '[]'::jsonb;
  v_claim_lock_contention_detected boolean := false;
  v_claim_lock_contention_count integer := 0;
  v_delta_queued_coalesced_count integer := 0;
  v_delta_queued_coalesced_hot_key_count integer := 0;
  v_projection_lifecycle_repair_json jsonb := '{}'::jsonb;
  v_invalid_source_build_poison_repair_json jsonb := '{}'::jsonb;
  v_stale_source_build_run_id_text text := NULL::text;
  v_stale_invalid_source_build_without_run_id boolean := false;
  v_delta_stale_continuation_superseded_count integer := 0;
  v_delta_stale_continuation_sample jsonb := '[]'::jsonb;
  v_delta_stale_projection_terminalised_count integer := 0;
  v_delta_stale_projection_terminalisation_sample jsonb := '[]'::jsonb;
  v_claim_mismatch_detected boolean := false;
  v_claim_mismatch_reason text := NULL::text;
  v_claim_mismatch_json jsonb := '{}'::jsonb;
  v_claimable_sample jsonb := '[]'::jsonb;
  v_claim_reject_summary jsonb := '{}'::jsonb;
  v_advisory_lock_reject_count integer := 0;
  v_candidate_serial_reject_count integer := 0;
  v_skip_locked_or_concurrent_lock_count integer := 0;
  v_allowed_job_types_reject_count integer := 0;
  v_status_changed_before_claim_count integer := 0;
  v_obsolete_or_superseded_reject_count integer := 0;
  v_active_projection_reject_count integer := 0;
  v_unknown_claim_query_mismatch_count integer := 0;
BEGIN
  IF p_allowed_job_types IS NOT NULL THEN
    SELECT ARRAY(
      SELECT DISTINCT normalised_allowed.job_type
      FROM (
        SELECT
          CASE
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
              THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE normalised_raw.raw_value_text
          END AS job_type
        FROM unnest(p_allowed_job_types) AS allowed_job_type(raw_value)
        CROSS JOIN LATERAL (
          SELECT UPPER(BTRIM(COALESCE(allowed_job_type.raw_value, ''))) AS raw_value_text
        ) AS normalised_raw
        WHERE normalised_raw.raw_value_text <> ''
      ) AS normalised_allowed
      WHERE normalised_allowed.job_type <> ''
      ORDER BY normalised_allowed.job_type
    )
    INTO v_allowed_job_types;

    IF COALESCE(array_length(v_allowed_job_types, 1), 0) = 0 THEN
      v_allowed_job_types := ARRAY[]::text[];
    END IF;
  ELSE
    v_allowed_job_types := NULL::text[];
  END IF;

  IF p_session_id IS NOT NULL
     AND (
       v_allowed_job_types IS NULL
       OR 'WORKBENCH_SESSION_SCOPE_SEED' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_SOURCE_BUILD' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_SESSION_CLONE_REBASE' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_PREVIEW_ROWS_MATERIALISE' = ANY(v_allowed_job_types)
     ) THEN
    v_stale_running_seconds := 25;
  ELSE
    v_stale_running_seconds := 180;
  END IF;

  SELECT sd.banking_pay_workbench_db_worker_lease_seconds
  INTO v_configured_lease_seconds
  FROM public.settings_defaults AS sd
  WHERE sd.id = 1
  LIMIT 1;

  IF v_configured_lease_seconds IS NOT NULL THEN
    v_stale_running_seconds := LEAST(GREATEST(v_configured_lease_seconds, 25), 3600);
  END IF;

  v_stale_cutoff := v_cutoff - make_interval(secs => v_stale_running_seconds);
  v_stale_recovery_limit := LEAST(v_limit, 3);

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types) THEN
    v_projection_lifecycle_repair_json := public.pay_workbench_projection_lifecycle_repair(
      p_session_id => p_session_id,
      p_candidate_id => p_candidate_id,
      p_safe_age_seconds => GREATEST(v_stale_running_seconds, 300),
      p_limit => LEAST(GREATEST(v_limit, 1), 100),
      p_reason => 'CLAIM_DUE_JOBS_PROJECTION_LIFECYCLE_REPAIR'
    );
  END IF;

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_SOURCE_BUILD' = ANY(v_allowed_job_types)
     OR 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' = ANY(v_allowed_job_types) THEN
    IF to_regprocedure('public.pay_workbench_repair_invalid_source_build_poison(uuid,uuid,integer,timestamp with time zone,text)') IS NOT NULL THEN
      BEGIN
        EXECUTE 'SELECT public.pay_workbench_repair_invalid_source_build_poison($1, $2, $3, $4, $5)'
        INTO v_invalid_source_build_poison_repair_json
        USING
          p_session_id,
          p_candidate_id,
          LEAST(GREATEST(v_limit, 1), 10),
          v_now,
          'CLAIM_DUE_JOBS_INVALID_SOURCE_BUILD_POISON_REPAIR';
      EXCEPTION WHEN OTHERS THEN
        v_invalid_source_build_poison_repair_json := jsonb_build_object(
          'ok', false,
          'deferred', true,
          'reason', 'CLAIM_DUE_JOBS_INVALID_SOURCE_BUILD_POISON_REPAIR_FAILED',
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;
    END IF;
  END IF;

  FOR v_stale_row IN
    WITH stale_candidates AS (
      SELECT
        stale_job.id,
        stale_job.job_type,
        stale_job.status,
        stale_job.priority,
        stale_job.run_at_utc,
        stale_job.attempt_count,
        stale_job.max_attempts,
        stale_job.dedupe_key,
        stale_job.snapshot_run_id,
        stale_job.session_id,
        stale_job.candidate_id,
        stale_job.payload_json,
        stale_job.created_at_utc,
        stale_job.updated_at_utc,
        stale_job.started_at_utc,
        stale_job.completed_at_utc,
        stale_job.failed_at_utc,
        stale_job.last_error_json,
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.run_at_utc,
          stale_job.created_at_utc
        ) AS last_activity_utc
      FROM public.banking_pay_workbench_jobs AS stale_job
      WHERE stale_job.status = 'RUNNING'
        AND (
          CASE
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE UPPER(BTRIM(COALESCE(stale_job.job_type, '')))
          END
        ) IN (
          'WORKBENCH_SESSION_SCOPE_SEED',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'WORKBENCH_SESSION_CLONE_REBASE',
          'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
        )
        AND (p_session_id IS NULL OR stale_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR stale_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
                WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                  THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(stale_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
        AND stale_job.completed_at_utc IS NULL
        AND stale_job.failed_at_utc IS NULL
        AND COALESCE(
              stale_job.updated_at_utc,
              stale_job.started_at_utc,
              stale_job.run_at_utc,
              stale_job.created_at_utc
            ) <= v_stale_cutoff
      ORDER BY
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.run_at_utc,
          stale_job.created_at_utc
        ) ASC,
        stale_job.priority ASC,
        stale_job.run_at_utc ASC,
        stale_job.created_at_utc ASC,
        stale_job.id ASC
      LIMIT v_stale_recovery_limit
      FOR UPDATE SKIP LOCKED
    )
    SELECT
      stale_candidates.id,
      stale_candidates.job_type,
      stale_candidates.status,
      stale_candidates.priority,
      stale_candidates.run_at_utc,
      stale_candidates.attempt_count,
      stale_candidates.max_attempts,
      stale_candidates.dedupe_key,
      stale_candidates.snapshot_run_id,
      stale_candidates.session_id,
      stale_candidates.candidate_id,
      stale_candidates.payload_json,
      stale_candidates.created_at_utc,
      stale_candidates.updated_at_utc,
      stale_candidates.started_at_utc,
      stale_candidates.completed_at_utc,
      stale_candidates.failed_at_utc,
      stale_candidates.last_error_json,
      stale_candidates.last_activity_utc
    FROM stale_candidates
  LOOP
    v_stale_job_source_change_seq := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_job_session_version := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'session_version', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'session_version')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_live_candidate_change_seq := 0;
    v_stale_snapshot_state_status := NULL;
    v_stale_snapshot_state_source_change_seq := 0;
    v_stale_session_status := NULL;
    v_stale_session_version := 0;
    v_stale_session_candidate_status := NULL;
    v_stale_session_candidate_source_change_seq := 0;
    v_stale_session_candidate_session_version := 0;
    v_stale_other_active_job_id := NULL::uuid;
    v_stale_completed_equivalent_id := NULL::uuid;
    v_stale_obsolete := false;
    v_stale_obsolete_reason := NULL;
    v_stale_failed_line_work_count := 0;
    v_stale_failed_source_row_count := 0;
    v_stale_source_build_run_id_text := NULL::text;
    v_stale_invalid_source_build_without_run_id := false;
    v_stale_canonical_job_type := CASE
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
        THEN 'WORKBENCH_SESSION_SCOPE_SEED'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
        THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
          THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
        THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
        THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      ELSE UPPER(BTRIM(COALESCE(v_stale_row.job_type, '')))
    END;

    IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
      v_stale_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
        v_stale_row.payload_json->>'source_build_run_id',
        v_stale_row.payload_json#>>'{source_build,source_build_run_id}',
        v_stale_row.payload_json#>>'{source_build,run_id}',
        v_stale_row.payload_json#>>'{cursor,source_build_run_id}',
        v_stale_row.payload_json#>>'{cursor_json,source_build_run_id}',
        v_stale_row.payload_json#>>'{result_json,source_build_run_id}',
        ''
      )), '');

      IF v_stale_source_build_run_id_text IS NULL
         OR v_stale_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_stale_source_build_run_id_text := NULL::text;
        v_stale_invalid_source_build_without_run_id := true;
      END IF;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
      IF v_stale_row.snapshot_run_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
        INTO v_stale_snapshot_state_status, v_stale_snapshot_state_source_change_seq
        FROM public.banking_pay_snapshot_candidate_state AS snap
        WHERE snap.snapshot_run_id = v_stale_row.snapshot_run_id
          AND snap.candidate_id = v_stale_row.candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_stale_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> v_stale_row.id
          AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
          AND j.snapshot_run_id = v_stale_row.snapshot_run_id
          AND j.candidate_id = v_stale_row.candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        ELSIF v_stale_other_active_job_id IS NOT NULL THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_stale_snapshot_state_status, '')) = 'READY'
              AND v_stale_snapshot_state_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
        END IF;
      END IF;
    ELSIF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'SESSION_CANDIDATE_RECOMPUTE' THEN
      IF v_stale_row.session_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SESSION_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_stale_session_status, v_stale_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_stale_row.session_id
        LIMIT 1;

        IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSE
          SELECT COALESCE(scs.status, NULL),
                 COALESCE(scs.source_change_seq, 0),
                 COALESCE(scs.session_version, 0)
          INTO v_stale_session_candidate_status,
               v_stale_session_candidate_source_change_seq,
               v_stale_session_candidate_session_version
          FROM public.banking_pay_workbench_session_candidate_state AS scs
          WHERE scs.session_id = v_stale_row.session_id
            AND scs.candidate_id = v_stale_row.candidate_id
          LIMIT 1;

          SELECT j.id
          INTO v_stale_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
            AND j.session_id = v_stale_row.session_id
            AND j.candidate_id = v_stale_row.candidate_id
            AND j.status IN ('QUEUED', 'RUNNING')
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'session_version')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= v_stale_session_version
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'source_change_seq')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
          ORDER BY COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'session_version')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'source_change_seq')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   j.updated_at_utc DESC NULLS LAST,
                   j.created_at_utc DESC NULLS LAST,
                   j.id DESC
          LIMIT 1;

          IF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          ELSIF v_stale_other_active_job_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
          ELSIF UPPER(COALESCE(v_stale_session_candidate_status, '')) = 'READY'
                AND v_stale_session_candidate_session_version >= v_stale_session_version
                AND v_stale_session_candidate_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_ALREADY_CURRENT';
          END IF;
        END IF;
      END IF;
    ELSIF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'PAYEE_READINESS_ENSURE' THEN
      IF v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_READINESS_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        IF v_stale_row.session_id IS NOT NULL THEN
          SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
          INTO v_stale_session_status, v_stale_session_version
          FROM public.banking_pay_workbench_sessions AS ws
          WHERE ws.id = v_stale_row.session_id
          LIMIT 1;

          IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
          ELSIF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          END IF;
        END IF;

        IF NOT v_stale_obsolete AND v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        END IF;

        IF NOT v_stale_obsolete THEN
          SELECT j.id
          INTO v_stale_completed_equivalent_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_stale_row.dedupe_key
            AND j.completed_at_utc IS NOT NULL
            AND j.failed_at_utc IS NULL
          ORDER BY j.completed_at_utc DESC, j.id DESC
          LIMIT 1;

          IF v_stale_completed_equivalent_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
          ELSE
            SELECT j.id
            INTO v_stale_other_active_job_id
            FROM public.banking_pay_workbench_jobs AS j
            WHERE j.id <> v_stale_row.id
              AND j.job_type = 'PAYEE_READINESS_ENSURE'
              AND j.dedupe_key = v_stale_row.dedupe_key
              AND j.status IN ('QUEUED', 'RUNNING')
            ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
            LIMIT 1;

            IF v_stale_other_active_job_id IS NOT NULL THEN
              v_stale_obsolete := true;
              v_stale_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
            END IF;
          END IF;
        END IF;
      END IF;
    ELSIF (
      CASE
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
          THEN 'WORKBENCH_SESSION_SCOPE_SEED'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
        THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
          THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
          THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
          THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
          THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
        ELSE UPPER(BTRIM(COALESCE(v_stale_row.job_type, '')))
      END
    ) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE') THEN
      IF v_stale_row.session_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_WORKBENCH_SESSION_CONTEXT';
      ELSE
        SELECT COALESCE(workbench_session.status, NULL), COALESCE(workbench_session.version, 0)
        INTO v_stale_session_status, v_stale_session_version
        FROM public.banking_pay_workbench_sessions AS workbench_session
        WHERE workbench_session.id = v_stale_row.session_id
        LIMIT 1;

        IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSIF v_stale_job_session_version > 0 AND v_stale_session_version > v_stale_job_session_version THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        END IF;
      END IF;

    END IF;

    v_stale_before_json := jsonb_build_object(
      'id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'status', v_stale_row.status,
      'priority', v_stale_row.priority,
      'run_at_utc', v_stale_row.run_at_utc,
      'attempt_count', v_stale_row.attempt_count,
      'max_attempts', v_stale_row.max_attempts,
      'dedupe_key', v_stale_row.dedupe_key,
      'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
      'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
      'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
      'payload_json', v_stale_row.payload_json,
      'created_at_utc', v_stale_row.created_at_utc,
      'updated_at_utc', v_stale_row.updated_at_utc,
      'started_at_utc', v_stale_row.started_at_utc,
      'completed_at_utc', v_stale_row.completed_at_utc,
      'failed_at_utc', v_stale_row.failed_at_utc,
      'last_error_json', v_stale_row.last_error_json,
      'last_activity_utc', v_stale_row.last_activity_utc
    );

    v_stale_error_json := jsonb_build_object(
      'code', CASE
        WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             AND v_stale_invalid_source_build_without_run_id IS TRUE THEN 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_RUN_ID_MISSING_FAILED_CLOSED'
        WHEN v_stale_obsolete THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
        WHEN COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
        ELSE 'STALE_RUNNING_WORKBENCH_JOB_RECOVERED'
      END,
      'message', CASE
        WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             AND v_stale_invalid_source_build_without_run_id IS TRUE THEN 'Failed stale running-like Banking Pay source-build job because its payload is missing source_build_run_id and cannot safely authorise source-row mutation.'
        WHEN v_stale_obsolete THEN 'Failed stale running-like Banking Pay workbench preview job because its context is obsolete or superseded.'
        WHEN COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN 'Failed stale running-like Banking Pay workbench preview job because max attempts are exhausted.'
        ELSE 'Recovered stale running-like Banking Pay workbench preview job during due-job claim cycle.'
      END,
      'job_id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'previous_status', v_stale_row.status,
      'attempt_count', COALESCE(v_stale_row.attempt_count, 0),
      'max_attempts', COALESCE(v_stale_row.max_attempts, 8),
      'last_activity_utc', v_stale_row.last_activity_utc,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'recovered_at_utc', v_now,
      'obsolete', v_stale_obsolete,
      'obsolete_reason', v_stale_obsolete_reason,
      'source_change_seq', v_stale_job_source_change_seq,
      'session_version', v_stale_job_session_version,
      'live_candidate_change_seq', CASE WHEN v_stale_live_candidate_change_seq = 0 THEN NULL ELSE v_stale_live_candidate_change_seq END,
      'snapshot_state_status', v_stale_snapshot_state_status,
      'snapshot_state_source_change_seq', CASE WHEN v_stale_snapshot_state_source_change_seq = 0 THEN NULL ELSE v_stale_snapshot_state_source_change_seq END,
      'session_status', v_stale_session_status,
      'current_session_version', CASE WHEN v_stale_session_version = 0 THEN NULL ELSE v_stale_session_version END,
      'session_candidate_status', v_stale_session_candidate_status,
      'session_candidate_source_change_seq', CASE WHEN v_stale_session_candidate_source_change_seq = 0 THEN NULL ELSE v_stale_session_candidate_source_change_seq END,
      'session_candidate_session_version', CASE WHEN v_stale_session_candidate_session_version = 0 THEN NULL ELSE v_stale_session_candidate_session_version END,
      'other_active_job_id', CASE WHEN v_stale_other_active_job_id IS NULL THEN NULL ELSE v_stale_other_active_job_id::text END,
      'completed_equivalent_job_id', CASE WHEN v_stale_completed_equivalent_id IS NULL THEN NULL ELSE v_stale_completed_equivalent_id::text END
    );

    IF v_stale_obsolete
       OR (
         v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
         AND v_stale_invalid_source_build_without_run_id IS TRUE
       )
       OR COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN
      UPDATE public.banking_pay_workbench_jobs AS dead_job
      SET status = 'FAILED',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_stale_error_json,
          payload_json = jsonb_strip_nulls(
            COALESCE(dead_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('last_failure_json', v_stale_error_json)
            || CASE
              WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
                   AND v_stale_invalid_source_build_without_run_id IS TRUE THEN
                jsonb_build_object(
                  'invalid_source_build_without_run_id_failed_closed', true,
                  'invalid_source_build_without_run_id_non_blocking', true,
                  'non_blocking_terminal_failure', true,
                  'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
                  'non_blocking_terminal_failure_at_utc', v_now::text,
                  'source_build_run_id_required', true,
                  'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
                )
              ELSE '{}'::jsonb
            END
          )
      WHERE dead_job.id = v_stale_row.id
      RETURNING
        dead_job.id,
        dead_job.job_type,
        dead_job.status,
        dead_job.priority,
        dead_job.run_at_utc,
        dead_job.attempt_count,
        dead_job.max_attempts,
        dead_job.dedupe_key,
        dead_job.snapshot_run_id,
        dead_job.session_id,
        dead_job.candidate_id,
        dead_job.payload_json,
        dead_job.created_at_utc,
        dead_job.updated_at_utc,
        dead_job.started_at_utc,
        dead_job.completed_at_utc,
        dead_job.failed_at_utc,
        dead_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
         AND v_stale_obsolete IS NOT TRUE
         AND (
           v_stale_invalid_source_build_without_run_id IS TRUE
           OR COALESCE(v_stale_row.attempt_count, 0) >= GREATEST(COALESCE(v_stale_row.max_attempts, 8), 1)
         )
         AND v_stale_row.session_id IS NOT NULL
         AND v_stale_row.candidate_id IS NOT NULL THEN
        IF v_stale_source_build_run_id_text IS NULL THEN
          v_stale_failed_source_row_count := 0;

          PERFORM public._audit_insert(
            'banking_pay_workbench_candidate_source_lines',
            v_stale_row.candidate_id::text,
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'old_status', 'CURRENT_OR_DIRTY',
              'reason', 'STALE_SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'affected_row_count', 0,
              'source_rows_marked_error_count', 0,
              'new_status', 'UNCHANGED',
              'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
            NULL
          );

          PERFORM public._audit_insert(
            'banking_pay_workbench_session_scope',
            v_stale_row.candidate_id::text,
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'reason', 'STALE_SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'scope_status_changed', false,
              'session_progress_changed', false,
              'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
            NULL
          );
        ELSE
          IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NOT NULL THEN
            WITH failed_source_rows AS (
              UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
              SET status = 'ERROR',
                  source_row_json = COALESCE(source_line.source_row_json, '{}'::jsonb)
                    || jsonb_build_object(
                      'stale_source_build_error', jsonb_build_object(
                        'code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                        'job_id', v_stale_row.id::text,
                        'job_type', v_stale_row.job_type,
                        'source_build_run_id', v_stale_source_build_run_id_text,
                        'failed_at_utc', v_now::text,
                        'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb),
                        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                      )
                    ),
                  updated_at_utc = v_now
              WHERE source_line.session_id = v_stale_row.session_id
                AND source_line.candidate_id = v_stale_row.candidate_id
                AND source_line.status IN ('CURRENT', 'DIRTY')
                AND source_line.source_build_run_id::text = v_stale_source_build_run_id_text
              RETURNING source_line.id
            )
            SELECT COUNT(*)::integer
            INTO v_stale_failed_source_row_count
            FROM failed_source_rows;
          END IF;

          UPDATE public.banking_pay_workbench_session_scope AS source_scope_row
          SET status = 'SOURCE_BUILD_ERROR',
              dirty = true,
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                'message', 'Candidate source build job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'job_type', v_stale_row.job_type,
                'source_build_run_id', v_stale_source_build_run_id_text,
                'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0),
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE source_scope_row.session_id = v_stale_row.session_id
            AND source_scope_row.candidate_id = v_stale_row.candidate_id;

          UPDATE public.banking_pay_workbench_sessions AS source_session_row
          SET progress_state = 'ERROR',
              progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(source_session_row.progress_json, '{}'::jsonb), true) || jsonb_build_object(
                'last_source_build_failure_at_utc', v_now::text,
                'last_source_build_failure_job_id', v_stale_row.id::text,
                'last_source_build_failure_code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                'last_source_build_failure_source_build_run_id', v_stale_source_build_run_id_text,
                'last_source_build_source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0)
              ),
              progress_counter_version = COALESCE(source_session_row.progress_counter_version, 0) + 1,
              progress_updated_at_utc = v_now,
              updated_at_utc = v_now
          WHERE source_session_row.id = v_stale_row.session_id;
        END IF;
      END IF;

      IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
         AND v_stale_obsolete IS NOT TRUE
         AND COALESCE(v_stale_row.attempt_count, 0) >= GREATEST(COALESCE(v_stale_row.max_attempts, 8), 1)
         AND v_stale_row.session_id IS NOT NULL
         AND v_stale_row.candidate_id IS NOT NULL THEN
        WITH failed_lines AS (
          UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
          SET status = 'ERROR',
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'message', 'Candidate line work was marked failed because its stale process job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'job_type', v_stale_row.job_type,
                'session_id', v_stale_row.session_id::text,
                'candidate_id', v_stale_row.candidate_id::text,
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE line_work.session_id = v_stale_row.session_id
            AND line_work.candidate_id = v_stale_row.candidate_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
          RETURNING line_work.id
        )
        SELECT COUNT(*)::integer
        INTO v_stale_failed_line_work_count
        FROM failed_lines;

        IF COALESCE(v_stale_failed_line_work_count, 0) > 0 THEN
          UPDATE public.banking_pay_workbench_session_scope AS scope_row
          SET status = 'ERROR',
              dirty = true,
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'message', 'Candidate line work process job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'line_work_failed_count', v_stale_failed_line_work_count,
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE scope_row.session_id = v_stale_row.session_id
            AND scope_row.candidate_id = v_stale_row.candidate_id;

          UPDATE public.banking_pay_workbench_sessions AS session_row
          SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_stale_failed_line_work_count, 0), 0),
              line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_stale_failed_line_work_count, 0), 0),
              progress_state = 'ERROR',
              progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true) || jsonb_build_object(
                'last_line_process_failure_at_utc', v_now::text,
                'last_line_process_failure_job_id', v_stale_row.id::text,
                'last_line_process_failure_code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'last_line_process_failure_count', v_stale_failed_line_work_count
              ),
              progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
              progress_updated_at_utc = v_now,
              updated_at_utc = v_now
          WHERE session_row.id = v_stale_row.session_id;
        END IF;
      END IF;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.run_at_utc,
          v_stale_row.created_at_utc
        ),
        'stale_recovery', true,
        'failed_terminal', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', v_stale_obsolete,
        'obsolete_reason', v_stale_obsolete_reason,
        'line_work_failed_count', COALESCE(v_stale_failed_line_work_count, 0),
        'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0),
        'invalid_source_build_without_run_id_non_blocking', COALESCE(v_stale_invalid_source_build_without_run_id, false),
        'non_blocking_terminal_failure', COALESCE(v_stale_invalid_source_build_without_run_id, false)
      );

      v_dead_stale := v_dead_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'failed_at_utc', v_stale_row.failed_at_utc,
          'last_error_json', v_stale_row.last_error_json,
          'obsolete', v_stale_obsolete,
          'obsolete_reason', v_stale_obsolete_reason,
          'source_build_run_id', v_stale_source_build_run_id_text,
          'invalid_source_build_without_run_id_failed_closed', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'invalid_source_build_without_run_id_non_blocking', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'non_blocking_terminal_failure', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0)
        )
      );

      v_dead_stale_count := v_dead_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'FAILED',
        v_stale_before_json,
        v_stale_after_json,
        CASE
          WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND v_stale_invalid_source_build_without_run_id IS TRUE
            THEN 'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED'
          ELSE 'WORKBENCH_JOB_STALE_RUNNER_FAILED'
        END,
        NULL
      );
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS requeue_job
      SET status = 'QUEUED',
          run_at_utc = v_cutoff,
          updated_at_utc = v_now,
          started_at_utc = NULL,
          completed_at_utc = NULL,
          failed_at_utc = NULL,
          last_error_json = v_stale_error_json
      WHERE requeue_job.id = v_stale_row.id
      RETURNING
        requeue_job.id,
        requeue_job.job_type,
        requeue_job.status,
        requeue_job.priority,
        requeue_job.run_at_utc,
        requeue_job.attempt_count,
        requeue_job.max_attempts,
        requeue_job.dedupe_key,
        requeue_job.snapshot_run_id,
        requeue_job.session_id,
        requeue_job.candidate_id,
        requeue_job.payload_json,
        requeue_job.created_at_utc,
        requeue_job.updated_at_utc,
        requeue_job.started_at_utc,
        requeue_job.completed_at_utc,
        requeue_job.failed_at_utc,
        requeue_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.run_at_utc,
          v_stale_row.created_at_utc
        ),
        'stale_recovery', true,
        'requeued', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', false,
        'obsolete_reason', NULL
      );

      v_recovered_stale := v_recovered_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'updated_at_utc', v_stale_row.updated_at_utc,
          'last_error_json', v_stale_row.last_error_json
        )
      );

      v_recovered_stale_count := v_recovered_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'REQUEUED',
        v_stale_before_json,
        v_stale_after_json,
        'WORKBENCH_JOB_STALE_RUNNER_REQUEUED',
        NULL
      );
    END IF;
  END LOOP;

  BEGIN
    WITH visible_due AS (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.session_id,
        claim_job.candidate_id,
        claim_job.created_at_utc
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR claim_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
                WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                  THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
      ORDER BY claim_job.priority ASC, claim_job.run_at_utc ASC, claim_job.created_at_utc ASC, claim_job.id ASC
      LIMIT v_limit
    )
    SELECT
      COALESCE(COUNT(*), 0)::integer,
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'job_id', visible_due.id::text,
            'job_type', visible_due.job_type,
            'priority', visible_due.priority,
            'run_at_utc', visible_due.run_at_utc,
            'session_id', CASE WHEN visible_due.session_id IS NULL THEN NULL ELSE visible_due.session_id::text END,
            'candidate_id', CASE WHEN visible_due.candidate_id IS NULL THEN NULL ELSE visible_due.candidate_id::text END,
            'created_at_utc', visible_due.created_at_utc
          )
          ORDER BY visible_due.priority ASC, visible_due.run_at_utc ASC, visible_due.created_at_utc ASC, visible_due.id ASC
        ),
        '[]'::jsonb
      )
    INTO v_preclaim_due_queued_count, v_preclaim_due_queued_sample
    FROM visible_due;
  EXCEPTION WHEN OTHERS THEN
    v_preclaim_due_queued_count := 0;
    v_preclaim_due_queued_sample := '[]'::jsonb;
  END;

  -- Latest-wins queue compaction for queued DELTA jobs.
  -- This collapses repeated lifecycle flips for the same session/candidate/timesheet hot key
  -- before expensive projection work is claimed.  It does not touch payment economics.
  BEGIN
    WITH queued_delta AS (
      SELECT
        delta_job.id,
        delta_job.priority,
        delta_job.run_at_utc,
        delta_job.created_at_utc,
        delta_job.updated_at_utc,
        delta_job.payload_json,
        delta_job.dedupe_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(
            delta_job.payload_json->>'normalised_delta_family_key',
            delta_job.payload_json->>'delta_family_key',
            delta_job.payload_json->>'delta_coalescing_key',
            ''
          )), ''),
          (
          SELECT
            'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
            || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
              delta_job.session_id::text,
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
              ''
            )), ''), 'none')
            || ':version:' || COALESCE(
              CASE
                WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                  THEN delta_family_values.session_version_text::bigint
                ELSE COALESCE(NULL::bigint, 0)::bigint
              END,
              0
            )::text
            || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.projection_mode_text, ''),
              NULLIF(NULL::text, ''),
              'DELTA'
            ))), ''), 'DELTA')
            || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.projection_class_text, ''),
              NULLIF(NULL::text, ''),
              'UNKNOWN'
            ))), ''), 'UNKNOWN')
            || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.refresh_scope_kind_text, ''),
              NULLIF(NULL::text, ''),
              CASE
                WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                  OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                  THEN 'TARGETED_TIMESHEETS'
                ELSE 'CANDIDATE_FULL_LIVE'
              END
            ))), ''), 'CANDIDATE_FULL_LIVE')
            || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
              delta_job.candidate_id::text,
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
              ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
              ''
            )), ''), 'none')
            || ':timesheets:' || md5(
              COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
              || ':'
              || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
            )
          FROM (
            SELECT
              NULLIF(BTRIM(COALESCE(
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'session_version',
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'version',
                CASE WHEN NULL::bigint IS NULL THEN NULL ELSE (NULL::bigint)::text END,
                '0'
              )), '') AS session_version_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                NULLIF(NULL::text, ''),
                'DELTA'
              ))) AS projection_mode_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                NULLIF(NULL::text, ''),
                'UNKNOWN'
              ))) AS projection_class_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                NULLIF(NULL::text, '')
              ))) AS refresh_scope_kind_text
          ) AS delta_family_values
          CROSS JOIN (
            SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
            FROM (
              SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
              FROM jsonb_array_elements_text(
                CASE
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                    THEN (COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                    THEN jsonb_build_array((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                  WHEN NULLIF(BTRIM(COALESCE(
                         (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                         (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                         ''
                       )), '') IS NOT NULL
                    THEN jsonb_build_array(COALESCE(
                      (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                      (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                    ))
                  ELSE '[]'::jsonb
                END
              ) AS delta_family_targeted_raw(value)
              WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) AS delta_family_targeted_sorted
          ) AS delta_family_targeted
          CROSS JOIN (
            SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
            FROM (
              SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
              FROM jsonb_array_elements_text(
                CASE
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                    THEN (COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                    THEN jsonb_build_array((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                  ELSE '[]'::jsonb
                END
              ) AS delta_family_linked_raw(value)
              WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) AS delta_family_linked_sorted
          ) AS delta_family_linked
          )
        ) AS hot_key,
        GREATEST(
          CASE WHEN COALESCE(delta_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
          CASE WHEN COALESCE(delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
          CASE WHEN COALESCE(delta_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
        ) AS source_change_seq
      FROM public.banking_pay_workbench_jobs AS delta_job
      WHERE delta_job.status = 'QUEUED'
        AND delta_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR delta_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR delta_job.candidate_id = p_candidate_id)
        AND UPPER(BTRIM(COALESCE(delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND (
          v_allowed_job_types IS NULL
          OR delta_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(delta_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types)
        )
      ORDER BY delta_job.priority ASC, delta_job.run_at_utc ASC, delta_job.created_at_utc ASC, delta_job.id ASC
      LIMIT GREATEST(v_limit * 10, 50)
      FOR UPDATE SKIP LOCKED
    ),
    ranked_delta AS (
      SELECT
        queued_delta.*,
        ROW_NUMBER() OVER (
          PARTITION BY queued_delta.hot_key
          ORDER BY queued_delta.source_change_seq DESC, queued_delta.priority ASC, queued_delta.run_at_utc ASC, queued_delta.updated_at_utc DESC NULLS LAST, queued_delta.created_at_utc DESC, queued_delta.id DESC
        ) AS hot_key_rank,
        COUNT(*) OVER (PARTITION BY queued_delta.hot_key) AS hot_key_count,
        MAX(queued_delta.source_change_seq) OVER (PARTITION BY queued_delta.hot_key) AS latest_hot_key_seq
      FROM queued_delta
      WHERE NULLIF(BTRIM(COALESCE(queued_delta.hot_key, '')), '') IS NOT NULL
    ),
    kept_heads AS (
      UPDATE public.banking_pay_workbench_jobs AS head_job
      SET payload_json = jsonb_strip_nulls(
            COALESCE(head_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_coalesced_queue_head', true,
              'delta_coalesced_queue_duplicate_count', GREATEST(ranked_delta.hot_key_count - 1, 0),
              'latest_source_change_seq', ranked_delta.latest_hot_key_seq,
              'source_change_seq', ranked_delta.latest_hot_key_seq,
              'source_change_sequence', ranked_delta.latest_hot_key_seq,
              'claim_coalesced_at_utc', v_now::text,
              'delta_family_key', ranked_delta.hot_key,
              'normalised_delta_family_key', ranked_delta.hot_key,
              'delta_coalescing_key', ranked_delta.hot_key
            )
          ),
          updated_at_utc = v_now
      FROM ranked_delta
      WHERE head_job.id = ranked_delta.id
        AND ranked_delta.hot_key_rank = 1
        AND ranked_delta.hot_key_count > 1
      RETURNING head_job.id, ranked_delta.hot_key
    ),
    superseded_delta AS (
      UPDATE public.banking_pay_workbench_jobs AS obsolete_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb,
          payload_json = jsonb_strip_nulls(
            COALESCE(obsolete_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_delta_queue_coalescing', true,
              'superseded_by_delta_queue_coalescing_at_utc', v_now::text,
              'superseded_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ_BEFORE_CLAIM',
              'latest_source_change_seq', ranked_delta.latest_hot_key_seq,
              'coalesced_hot_key', ranked_delta.hot_key,
              'delta_family_key', ranked_delta.hot_key,
              'normalised_delta_family_key', ranked_delta.hot_key
            )
          )
      FROM ranked_delta
      WHERE obsolete_job.id = ranked_delta.id
        AND ranked_delta.hot_key_rank > 1
      RETURNING obsolete_job.id, ranked_delta.hot_key
    )
    SELECT
      COALESCE((SELECT COUNT(*) FROM superseded_delta), 0)::integer,
      GREATEST(
        COALESCE((SELECT COUNT(DISTINCT superseded_delta.hot_key) FROM superseded_delta), 0),
        COALESCE((SELECT COUNT(DISTINCT kept_heads.hot_key) FROM kept_heads), 0)
      )::integer
    INTO v_delta_queued_coalesced_count, v_delta_queued_coalesced_hot_key_count;
  EXCEPTION WHEN OTHERS THEN
    -- Queue compaction is an optimisation.  Claiming must continue if diagnostic payloads are malformed.
    v_delta_queued_coalesced_count := 0;
    v_delta_queued_coalesced_hot_key_count := 0;
  END;

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types) THEN
    WITH queued_delta_continuation AS (
      SELECT
        stale_job.id,
        stale_job.session_id,
        stale_job.candidate_id,
        stale_job.payload_json,
        stale_job.created_at_utc,
        COALESCE(live_change.seq, 0) AS live_source_change_seq,
        GREATEST(
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'latest_source_change_seq')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'source_change_seq')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'source_change_sequence')::bigint END, 0)
        ) AS payload_source_change_seq,
        GREATEST(
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor_json,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}')::bigint END, 0)
        ) AS cursor_source_change_seq,
        COALESCE(projection_run.source_change_seq, 0) AS projection_run_source_change_seq,
        COALESCE(stale_job.payload_json->>'normalised_delta_family_key', stale_job.payload_json->>'delta_family_key', stale_job.payload_json->>'delta_coalescing_key', '') AS normalised_delta_family_key,
        projection_id.projection_run_id_text,
        projection_id.projection_run_id
      FROM public.banking_pay_workbench_jobs AS stale_job
      CROSS JOIN LATERAL (
        SELECT
          COALESCE(
            stale_job.payload_json->>'projection_run_id',
            stale_job.payload_json#>>'{cursor,projection_run_id}',
            stale_job.payload_json#>>'{cursor,cursor,projection_run_id}',
            stale_job.payload_json#>>'{cursor_json,projection_run_id}',
            stale_job.payload_json#>>'{cursor_json,cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor,cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor_json,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,projection_run_id}',
            ''
          ) AS projection_run_id_text
      ) AS projection_id_text
      CROSS JOIN LATERAL (
        SELECT
          projection_id_text.projection_run_id_text,
          CASE
            WHEN projection_id_text.projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN projection_id_text.projection_run_id_text::uuid
            ELSE NULL::uuid
          END AS projection_run_id
      ) AS projection_id
      LEFT JOIN public.app_change_counters AS live_change
        ON live_change.entity_key = 'pay_candidate:' || stale_job.candidate_id::text
      LEFT JOIN public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
        ON projection_run.id = projection_id.projection_run_id
      WHERE stale_job.status = 'QUEUED'
        AND stale_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR stale_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR stale_job.candidate_id = p_candidate_id)
        AND UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND (
          lower(BTRIM(COALESCE(stale_job.payload_json->>'continuation', 'false'))) IN ('true','t','1','yes','y','on')
          OR UPPER(BTRIM(COALESCE(stale_job.payload_json->>'run_mode', ''))) = 'BOUNDED_CONTINUATION'
          OR jsonb_typeof(stale_job.payload_json->'cursor') = 'object'
          OR jsonb_typeof(stale_job.payload_json->'cursor_json') = 'object'
          OR jsonb_typeof(stale_job.payload_json#>'{result_json,next_cursor}') = 'object'
          OR jsonb_typeof(stale_job.payload_json#>'{result_json,next_cursor_json}') = 'object'
        )
      ORDER BY stale_job.priority ASC, stale_job.run_at_utc ASC, stale_job.created_at_utc ASC, stale_job.id ASC
      LIMIT GREATEST(v_limit * 10, 50)
      FOR UPDATE OF stale_job SKIP LOCKED
    ), stale_delta_continuation AS (
      SELECT qdc.*
      FROM queued_delta_continuation AS qdc
      WHERE (
        (COALESCE(qdc.cursor_source_change_seq, 0) > 0 AND GREATEST(COALESCE(qdc.live_source_change_seq, 0), COALESCE(qdc.payload_source_change_seq, 0)) > COALESCE(qdc.cursor_source_change_seq, 0))
        OR (COALESCE(qdc.projection_run_source_change_seq, 0) > 0 AND GREATEST(COALESCE(qdc.live_source_change_seq, 0), COALESCE(qdc.payload_source_change_seq, 0)) > COALESCE(qdc.projection_run_source_change_seq, 0))
      )
    ), terminalised_delta_projection AS MATERIALIZED (
      SELECT
        stale_delta_continuation.*,
        public._pay_workbench_delta_projection_terminalise_if_orphaned(
          p_projection_run_id => stale_delta_continuation.projection_run_id,
          p_session_id => stale_delta_continuation.session_id,
          p_candidate_id => stale_delta_continuation.candidate_id,
          p_superseded_job_id => stale_delta_continuation.id,
          p_payload_source_change_seq => stale_delta_continuation.payload_source_change_seq,
          p_cursor_source_change_seq => stale_delta_continuation.cursor_source_change_seq,
          p_projection_run_source_change_seq => stale_delta_continuation.projection_run_source_change_seq,
          p_live_candidate_source_change_seq => stale_delta_continuation.live_source_change_seq,
          p_reason => 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
          p_now_utc => v_now,
          p_actor_user_id => NULL::uuid
        ) AS terminalise_json
      FROM stale_delta_continuation
    ), superseded_delta_continuation AS (
      UPDATE public.banking_pay_workbench_jobs AS upd_stale
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb,
          payload_json = jsonb_strip_nulls(
            COALESCE(upd_stale.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_stale_continuation_before_claim', true,
              'superseded_reason', 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
              'superseded_at_utc', v_now::text,
              'payload_source_change_seq', terminalised_delta_projection.payload_source_change_seq,
              'cursor_source_change_seq', terminalised_delta_projection.cursor_source_change_seq,
              'projection_run_source_change_seq', terminalised_delta_projection.projection_run_source_change_seq,
              'live_candidate_source_change_seq', terminalised_delta_projection.live_source_change_seq,
              'normalised_delta_family_key', terminalised_delta_projection.normalised_delta_family_key,
              'projection_run_id', NULLIF(terminalised_delta_projection.projection_run_id_text, ''),
              'projection_run_terminalised', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'projection_run_status_after', terminalised_delta_projection.terminalise_json->>'projection_run_status_after',
              'projection_run_terminalised_reason', terminalised_delta_projection.terminalise_json->>'projection_run_terminalised_reason',
              'projection_run_terminalisation_json', terminalised_delta_projection.terminalise_json,
              'no_active_continuation_job', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'candidate_serial_unblocked', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          )
      FROM terminalised_delta_projection
      WHERE upd_stale.id = terminalised_delta_projection.id
      RETURNING upd_stale.id,
                terminalised_delta_projection.session_id,
                terminalised_delta_projection.candidate_id,
                terminalised_delta_projection.normalised_delta_family_key,
                terminalised_delta_projection.payload_source_change_seq,
                terminalised_delta_projection.cursor_source_change_seq,
                terminalised_delta_projection.projection_run_source_change_seq,
                terminalised_delta_projection.live_source_change_seq,
                terminalised_delta_projection.projection_run_id_text,
                terminalised_delta_projection.projection_run_id,
                terminalised_delta_projection.terminalise_json
    )
    SELECT COALESCE(COUNT(*), 0)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'job_id', superseded_delta_continuation.id::text,
             'session_id', superseded_delta_continuation.session_id::text,
             'candidate_id', superseded_delta_continuation.candidate_id::text,
             'normalised_delta_family_key', superseded_delta_continuation.normalised_delta_family_key,
             'payload_source_change_seq', superseded_delta_continuation.payload_source_change_seq,
             'cursor_source_change_seq', superseded_delta_continuation.cursor_source_change_seq,
             'projection_run_source_change_seq', superseded_delta_continuation.projection_run_source_change_seq,
             'live_candidate_source_change_seq', superseded_delta_continuation.live_source_change_seq,
             'projection_run_id', NULLIF(superseded_delta_continuation.projection_run_id_text, ''),
             'projection_run_terminalised', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_run_status_after', superseded_delta_continuation.terminalise_json->>'projection_run_status_after',
             'projection_run_terminalised_reason', superseded_delta_continuation.terminalise_json->>'projection_run_terminalised_reason',
             'no_active_continuation_job', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'candidate_serial_unblocked', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_terminalisation_json', superseded_delta_continuation.terminalise_json
           ) ORDER BY superseded_delta_continuation.id), '[]'::jsonb),
           COALESCE(COUNT(*) FILTER (WHERE lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')), 0)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'job_id', superseded_delta_continuation.id::text,
             'projection_run_id', NULLIF(superseded_delta_continuation.projection_run_id_text, ''),
             'projection_run_terminalised', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_run_status_after', superseded_delta_continuation.terminalise_json->>'projection_run_status_after',
             'projection_run_terminalised_reason', superseded_delta_continuation.terminalise_json->>'projection_run_terminalised_reason',
             'no_active_continuation_job', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'candidate_serial_unblocked', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           ) ORDER BY superseded_delta_continuation.id) FILTER (WHERE lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')), '[]'::jsonb)
    INTO v_delta_stale_continuation_superseded_count,
         v_delta_stale_continuation_sample,
         v_delta_stale_projection_terminalised_count,
         v_delta_stale_projection_terminalisation_sample
    FROM superseded_delta_continuation;

    IF COALESCE(v_delta_stale_continuation_superseded_count, 0) > 0 THEN
      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        'delta_stale_continuation_preclaim',
        'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
        NULL::jsonb,
        jsonb_build_object(
          'superseded_stale_continuation_count', v_delta_stale_continuation_superseded_count,
          'projection_run_terminalised_count', COALESCE(v_delta_stale_projection_terminalised_count, 0),
          'projection_run_terminalised', COALESCE(v_delta_stale_projection_terminalised_count, 0) > 0,
          'projection_terminalisation_sample', COALESCE(v_delta_stale_projection_terminalisation_sample, '[]'::jsonb),
          'sample', v_delta_stale_continuation_sample,
          'claim_session_filter', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
          'claim_candidate_filter', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'session_progress_lock_skipped', true,
          'claimed_running_skipped', true,
          'candidate_serial_unblocked', COALESCE(v_delta_stale_projection_terminalised_count, 0) > 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        ),
        'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
        NULL::uuid
      );
    END IF;
  END IF;

  FOR v_claimed_row IN
    WITH claim_source AS (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.attempt_count,
        claim_job.max_attempts,
        claim_job.snapshot_run_id,
        claim_job.session_id,
        claim_job.candidate_id,
        claim_job.payload_json,
        claim_job.created_at_utc,
        public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json) AS candidate_serial_candidate_id,
        public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json)) AS candidate_serial_key,
        public._pay_workbench_candidate_serial_is_candidate_job(claim_job.job_type, claim_job.candidate_id, claim_job.payload_json) AS candidate_serial_required,
        (
          lower(BTRIM(COALESCE(claim_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
          OR lower(BTRIM(COALESCE(claim_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR (
            lower(BTRIM(COALESCE(claim_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            AND NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
          )
          OR (
            NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'source_job_id', claim_job.payload_json->>'continuation_source_job_id', claim_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
            AND UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
          )
        ) AS candidate_serial_is_chain_continuation,
        CASE
          WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
            THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
        END AS canonical_job_type,
        CASE
          WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN
            COALESCE(
              NULLIF(BTRIM(COALESCE(
                claim_job.payload_json->>'normalised_delta_family_key',
                claim_job.payload_json->>'delta_family_key',
                claim_job.payload_json->>'delta_coalescing_key',
                ''
              )), ''),
              (
              SELECT
                'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  claim_job.session_id::text,
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'source_session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'target_session_id',
                  ''
                )), ''), 'none')
                || ':version:' || COALESCE(
                  CASE
                    WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                      THEN delta_family_values.session_version_text::bigint
                    ELSE COALESCE(NULL::bigint, 0)::bigint
                  END,
                  0
                )::text
                || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_mode_text, ''),
                  NULLIF(NULL::text, ''),
                  'DELTA'
                ))), ''), 'DELTA')
                || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_class_text, ''),
                  NULLIF(NULL::text, ''),
                  'UNKNOWN'
                ))), ''), 'UNKNOWN')
                || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                  NULLIF(NULL::text, ''),
                  CASE
                    WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                      OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                      THEN 'TARGETED_TIMESHEETS'
                    ELSE 'CANDIDATE_FULL_LIVE'
                  END
                ))), ''), 'CANDIDATE_FULL_LIVE')
                || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  claim_job.candidate_id::text,
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'candidate_id',
                  ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                  ''
                )), ''), 'none')
                || ':timesheets:' || md5(
                  COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                  || ':'
                  || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                )
              FROM (
                SELECT
                  NULLIF(BTRIM(COALESCE(
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'session_version',
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'version',
                    CASE WHEN NULL::bigint IS NULL THEN NULL ELSE (NULL::bigint)::text END,
                    '0'
                  )), '') AS session_version_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'mode', ''),
                    NULLIF(NULL::text, ''),
                    'DELTA'
                  ))) AS projection_mode_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                    NULLIF(NULL::text, ''),
                    'UNKNOWN'
                  ))) AS projection_class_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                    NULLIF(NULL::text, '')
                  ))) AS refresh_scope_kind_text
              ) AS delta_family_values
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                        THEN (COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                      WHEN NULLIF(BTRIM(COALESCE(
                             (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                             (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                             ''
                           )), '') IS NOT NULL
                        THEN jsonb_build_array(COALESCE(
                          (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                          (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                        ))
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_targeted_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_targeted_sorted
              ) AS delta_family_targeted
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                        THEN (COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_linked_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_linked_sorted
              ) AS delta_family_linked
              )
            )
          ELSE COALESCE(
            NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'coalescing_key', '')), ''),
            claim_job.dedupe_key,
            claim_job.id::text
          )
        END AS hot_key
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR claim_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
      ORDER BY
        candidate_serial_is_chain_continuation DESC,
        claim_job.priority ASC,
        claim_job.run_at_utc ASC,
        claim_job.created_at_utc ASC,
        claim_job.id ASC
      LIMIT GREATEST(v_limit * 5, v_limit)
      FOR UPDATE SKIP LOCKED
    ),
    claim_pool AS (
      SELECT
        claim_source.*,
        ROW_NUMBER() OVER (
          PARTITION BY CASE
            WHEN claim_source.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN claim_source.hot_key
            ELSE claim_source.id::text
          END
          ORDER BY claim_source.priority ASC, claim_source.run_at_utc ASC, claim_source.created_at_utc ASC, claim_source.id ASC
        ) AS hot_key_rank,
        ROW_NUMBER() OVER (
          PARTITION BY COALESCE(claim_source.candidate_serial_key, claim_source.id::text)
          ORDER BY
            CASE WHEN claim_source.candidate_serial_required IS TRUE AND claim_source.candidate_serial_is_chain_continuation IS TRUE THEN 0 ELSE 1 END ASC,
            claim_source.priority ASC,
            claim_source.run_at_utc ASC,
            claim_source.created_at_utc ASC,
            claim_source.id ASC
        ) AS candidate_serial_rank
      FROM claim_source
    ),
    claim AS (
      SELECT claim_pool.*
      FROM claim_pool
      CROSS JOIN LATERAL (
        SELECT public._pay_workbench_candidate_serial_active_state(
          claim_pool.id,
          claim_pool.candidate_serial_candidate_id,
          claim_pool.job_type,
          claim_pool.payload_json,
          v_now
        ) AS state_json
      ) AS candidate_serial_state
      WHERE claim_pool.hot_key_rank = 1
        AND (
          claim_pool.candidate_serial_required IS NOT TRUE
          OR claim_pool.candidate_serial_rank = 1
        )
        AND (
          claim_pool.candidate_serial_required IS NOT TRUE
          OR pg_try_advisory_xact_lock(hashtextextended(claim_pool.candidate_serial_key, 24062027))
        )
        AND (
          claim_pool.candidate_serial_required IS NOT TRUE
          OR lower(BTRIM(COALESCE(candidate_serial_state.state_json->>'blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND (
          claim_pool.canonical_job_type <> 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          OR pg_try_advisory_xact_lock(hashtextextended(COALESCE(NULLIF(BTRIM(claim_pool.hot_key), ''), claim_pool.id::text), 24062026))
        )
        AND NOT (
          claim_pool.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          AND (
            lower(BTRIM(COALESCE(claim_pool.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'run_mode', ''))) = 'BOUNDED_CONTINUATION'
            OR jsonb_typeof(claim_pool.payload_json->'cursor') = 'object'
            OR jsonb_typeof(claim_pool.payload_json->'cursor_json') = 'object'
          )
          AND COALESCE((
            SELECT
              (
                COALESCE(delta_claim_staleness.cursor_source_change_seq, 0) > 0
                AND GREATEST(
                  COALESCE(delta_claim_live_change.seq, 0),
                  COALESCE(delta_claim_staleness.payload_source_change_seq, 0)
                ) > COALESCE(delta_claim_staleness.cursor_source_change_seq, 0)
              )
              OR (
                COALESCE(delta_claim_projection_run.source_change_seq, 0) > 0
                AND GREATEST(
                  COALESCE(delta_claim_live_change.seq, 0),
                  COALESCE(delta_claim_staleness.payload_source_change_seq, 0)
                ) > COALESCE(delta_claim_projection_run.source_change_seq, 0)
              )
            FROM (
              SELECT
                GREATEST(
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'latest_source_change_seq')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'source_change_seq')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'source_change_sequence')::bigint END, 0)
                ) AS payload_source_change_seq,
                GREATEST(
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor_json,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}')::bigint END, 0)
                ) AS cursor_source_change_seq,
                COALESCE(
                  claim_pool.payload_json->>'projection_run_id',
                  claim_pool.payload_json#>>'{cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor_json,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor_json,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor_json,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,projection_run_id}',
                  ''
                ) AS projection_run_id_text
            ) AS delta_claim_staleness
            LEFT JOIN public.app_change_counters AS delta_claim_live_change
              ON delta_claim_live_change.entity_key = 'pay_candidate:' || claim_pool.candidate_id::text
            LEFT JOIN public.banking_pay_workbench_candidate_delta_projection_runs AS delta_claim_projection_run
              ON delta_claim_projection_run.id = CASE
                   WHEN delta_claim_staleness.projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN delta_claim_staleness.projection_run_id_text::uuid
                   ELSE NULL::uuid
                 END
          ), false)
        )
        AND NOT (
          claim_pool.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          AND EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_jobs AS running_delta_job
            WHERE running_delta_job.status = 'RUNNING'
              AND running_delta_job.id IS DISTINCT FROM claim_pool.id
              AND running_delta_job.session_id IS NOT DISTINCT FROM claim_pool.session_id
              AND running_delta_job.candidate_id IS NOT DISTINCT FROM claim_pool.candidate_id
              AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              AND COALESCE(
                    NULLIF(BTRIM(COALESCE(
                      running_delta_job.payload_json->>'normalised_delta_family_key',
                      running_delta_job.payload_json->>'delta_family_key',
                      running_delta_job.payload_json->>'delta_coalescing_key',
                      ''
                    )), ''),
                    (
                    SELECT
                      'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                      || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                        running_delta_job.session_id::text,
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                        ''
                      )), ''), 'none')
                      || ':version:' || COALESCE(
                        CASE
                          WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                            THEN delta_family_values.session_version_text::bigint
                          ELSE COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END, 0)::bigint
                        END,
                        0
                      )::text
                      || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.projection_mode_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_mode', claim_pool.payload_json->>'resolved_mode', ''))), ''), ''),
                        'DELTA'
                      ))), ''), 'DELTA')
                      || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.projection_class_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_class', ''))), ''), ''),
                        'UNKNOWN'
                      ))), ''), 'UNKNOWN')
                      || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'refresh_scope_kind', ''))), ''), ''),
                        CASE
                          WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                            OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                            THEN 'TARGETED_TIMESHEETS'
                          ELSE 'CANDIDATE_FULL_LIVE'
                        END
                      ))), ''), 'CANDIDATE_FULL_LIVE')
                      || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                        running_delta_job.candidate_id::text,
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                        ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                        ''
                      )), ''), 'none')
                      || ':timesheets:' || md5(
                        COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                        || ':'
                        || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                      )
                    FROM (
                      SELECT
                        NULLIF(BTRIM(COALESCE(
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                          CASE WHEN CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END IS NULL THEN NULL ELSE (CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END)::text END,
                          '0'
                        )), '') AS session_version_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_mode', claim_pool.payload_json->>'resolved_mode', ''))), ''), ''),
                          'DELTA'
                        ))) AS projection_mode_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_class', ''))), ''), ''),
                          'UNKNOWN'
                        ))) AS projection_class_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'refresh_scope_kind', ''))), ''), '')
                        ))) AS refresh_scope_kind_text
                    ) AS delta_family_values
                    CROSS JOIN (
                      SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                      FROM (
                        SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                        FROM jsonb_array_elements_text(
                          CASE
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                              THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                              THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                            WHEN NULLIF(BTRIM(COALESCE(
                                   (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                                   (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                                   ''
                                 )), '') IS NOT NULL
                              THEN jsonb_build_array(COALESCE(
                                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                              ))
                            ELSE '[]'::jsonb
                          END
                        ) AS delta_family_targeted_raw(value)
                        WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      ) AS delta_family_targeted_sorted
                    ) AS delta_family_targeted
                    CROSS JOIN (
                      SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                      FROM (
                        SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                        FROM jsonb_array_elements_text(
                          CASE
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                              THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                              THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                            ELSE '[]'::jsonb
                          END
                        ) AS delta_family_linked_raw(value)
                        WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      ) AS delta_family_linked_sorted
                    ) AS delta_family_linked
                    )
                  ) = claim_pool.hot_key
          )
        )
      ORDER BY claim_pool.priority ASC, claim_pool.run_at_utc ASC, claim_pool.created_at_utc ASC, claim_pool.id ASC
      LIMIT v_limit
    ),
    upd AS (
      UPDATE public.banking_pay_workbench_jobs AS upd_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(upd_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(upd_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = NULL,
          last_error_json = NULL,
          payload_json = CASE
            WHEN claim_row.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
              jsonb_strip_nulls(
                COALESCE(upd_job.payload_json, '{}'::jsonb)
                || jsonb_build_object(
                  'latest_source_change_seq', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'source_change_seq', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'source_change_sequence', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'claim_live_source_guard_applied', true,
                  'claim_live_source_seq', COALESCE(live_change.seq, 0),
                  'claimed_delta_hot_key', claim_row.hot_key,
                  'delta_family_key', claim_row.hot_key,
                  'normalised_delta_family_key', claim_row.hot_key,
                  'delta_coalescing_key', claim_row.hot_key,
                  'claimed_at_utc', v_now::text,
                  'candidate_serial_key', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN claim_row.candidate_serial_key ELSE NULL END,
                  'candidate_serial_candidate_id', CASE WHEN claim_row.candidate_serial_candidate_id IS NULL THEN NULL ELSE claim_row.candidate_serial_candidate_id::text END,
                  'candidate_serial_active_chain_id', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN COALESCE(NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''), upd_job.id::text) ELSE NULL END,
                  'candidate_serial_source_job_id', NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''),
                  'candidate_serial_started_at_utc', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN v_now::text ELSE NULL END,
                  'candidate_serial_reason', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN 'CANDIDATE_SERIAL_CLAIM_GRANTED' ELSE NULL END
                )
              )
            ELSE
              CASE WHEN claim_row.candidate_serial_required IS TRUE THEN
                jsonb_strip_nulls(
                  COALESCE(upd_job.payload_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'claimed_at_utc', v_now::text,
                    'candidate_serial_key', claim_row.candidate_serial_key,
                    'candidate_serial_candidate_id', CASE WHEN claim_row.candidate_serial_candidate_id IS NULL THEN NULL ELSE claim_row.candidate_serial_candidate_id::text END,
                    'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''), upd_job.id::text),
                    'candidate_serial_source_job_id', NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''),
                    'candidate_serial_started_at_utc', v_now::text,
                    'candidate_serial_reason', 'CANDIDATE_SERIAL_CLAIM_GRANTED'
                  )
                )
              ELSE upd_job.payload_json END
          END
      FROM claim AS claim_row
      LEFT JOIN public.app_change_counters AS live_change
        ON live_change.entity_key = 'pay_candidate:' || COALESCE(claim_row.candidate_serial_candidate_id, claim_row.candidate_id)::text
      WHERE upd_job.id = claim_row.id
      RETURNING
        upd_job.id,
        upd_job.job_type,
        upd_job.priority,
        upd_job.run_at_utc,
        upd_job.attempt_count,
        upd_job.max_attempts,
        upd_job.snapshot_run_id,
        upd_job.session_id,
        upd_job.candidate_id,
        upd_job.payload_json,
        upd_job.started_at_utc,
        upd_job.created_at_utc
    )
    SELECT
      upd.id,
      upd.job_type,
      upd.priority,
      upd.run_at_utc,
      upd.attempt_count,
      upd.max_attempts,
      upd.snapshot_run_id,
      upd.session_id,
      upd.candidate_id,
      upd.payload_json,
      upd.started_at_utc,
      upd.created_at_utc
    FROM upd
    ORDER BY upd.priority ASC, upd.run_at_utc ASC, upd.created_at_utc ASC, upd.id ASC
  LOOP
    v_claimed := v_claimed || jsonb_build_array(
      jsonb_build_object(
        'job_id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'priority', v_claimed_row.priority,
        'run_at_utc', v_claimed_row.run_at_utc,
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END,
        'payload_json', v_claimed_row.payload_json,
        'started_at_utc', v_claimed_row.started_at_utc,
        'created_at_utc', v_claimed_row.created_at_utc
      )
    );

    v_claimed_count := v_claimed_count + 1;
    IF UPPER(BTRIM(COALESCE(v_claimed_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN
      v_claimed_delta_refresh_count := v_claimed_delta_refresh_count + 1;
    ELSIF UPPER(BTRIM(COALESCE(v_claimed_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN
      v_claimed_clone_rebase_count := v_claimed_clone_rebase_count + 1;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_claimed_row.id::text,
      'RUNNING',
      NULL,
      jsonb_build_object(
        'id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'status', 'RUNNING',
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'run_at_utc', v_claimed_row.run_at_utc,
        'started_at_utc', v_claimed_row.started_at_utc,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END,
        'candidate_serial_key', v_claimed_row.payload_json->>'candidate_serial_key',
        'candidate_serial_active_chain_id', v_claimed_row.payload_json->>'candidate_serial_active_chain_id'
      ),
      'WORKBENCH_JOB_CLAIMED',
      NULL
    );

    IF NULLIF(BTRIM(COALESCE(v_claimed_row.payload_json->>'candidate_serial_key', '')), '') IS NOT NULL THEN
      PERFORM public._pay_workbench_candidate_serial_audit(
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        v_claimed_row.id,
        public._pay_workbench_candidate_serial_candidate_id(v_claimed_row.candidate_id, v_claimed_row.payload_json),
        jsonb_build_object(
          'job_type', v_claimed_row.job_type,
          'candidate_serial_key', v_claimed_row.payload_json->>'candidate_serial_key',
          'candidate_serial_active_chain_id', v_claimed_row.payload_json->>'candidate_serial_active_chain_id',
          'claimed_at_utc', v_now::text
        ),
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        NULL::uuid
      );
    END IF;
  END LOOP;

  v_claim_mismatch_detected := (
    v_claimed_count = 0
    AND v_preclaim_due_queued_count > 0
    AND v_recovered_stale_count = 0
    AND v_dead_stale_count = 0
  );
  v_claim_lock_contention_detected := false;
  v_claim_lock_contention_count := 0;
  IF v_claim_mismatch_detected IS TRUE THEN
    BEGIN
      WITH visible_due AS (
        SELECT
          claim_job.id,
          claim_job.job_type,
          claim_job.status,
          claim_job.priority,
          claim_job.run_at_utc,
          claim_job.created_at_utc,
          claim_job.started_at_utc,
          claim_job.attempt_count,
          claim_job.max_attempts,
          claim_job.session_id,
          claim_job.candidate_id,
          claim_job.dedupe_key,
          COALESCE(claim_job.payload_json, '{}'::jsonb) AS payload_json,
          CASE
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
              THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
          END AS canonical_job_type
        FROM public.banking_pay_workbench_jobs AS claim_job
        WHERE UPPER(BTRIM(COALESCE(claim_job.status, ''))) = 'QUEUED'
          AND claim_job.run_at_utc <= v_cutoff
          AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
          AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        ORDER BY claim_job.priority ASC, claim_job.run_at_utc ASC, claim_job.created_at_utc ASC, claim_job.id ASC
        LIMIT 5
      ),
      enriched AS (
        SELECT
          vd.*,
          public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json) AS derived_candidate_id,
          public._pay_workbench_candidate_serial_is_candidate_job(vd.job_type, vd.candidate_id, vd.payload_json) AS is_candidate_job,
          public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json)) AS derived_candidate_serial_key,
          public._pay_workbench_candidate_serial_active_state(
            vd.id,
            public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json),
            vd.job_type,
            vd.payload_json,
            v_now
          ) AS serial_state_json
        FROM visible_due AS vd
      ),
      rejected AS (
        SELECT
          e.*,
          (
            SELECT same_job.id
            FROM public.banking_pay_workbench_jobs AS same_job
            WHERE same_job.id IS DISTINCT FROM e.id
              AND UPPER(BTRIM(COALESCE(same_job.status, ''))) = 'RUNNING'
              AND public._pay_workbench_candidate_serial_candidate_id(same_job.candidate_id, same_job.payload_json) = e.derived_candidate_id
              AND public._pay_workbench_candidate_serial_is_candidate_job(same_job.job_type, same_job.candidate_id, same_job.payload_json)
            ORDER BY same_job.started_at_utc ASC NULLS FIRST, same_job.created_at_utc ASC, same_job.id ASC
            LIMIT 1
          ) AS same_candidate_active_job_id,
          (
            SELECT same_projection.id
            FROM public.banking_pay_workbench_candidate_delta_projection_runs AS same_projection
            WHERE same_projection.candidate_id = e.derived_candidate_id
              AND UPPER(BTRIM(COALESCE(same_projection.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
            ORDER BY same_projection.started_at_utc ASC NULLS FIRST, same_projection.updated_at_utc ASC NULLS FIRST, same_projection.id ASC
            LIMIT 1
          ) AS same_candidate_active_projection_run_id,
          CASE
            WHEN UPPER(BTRIM(COALESCE(e.status, ''))) <> 'QUEUED' THEN 'JOB_STATUS_CHANGED_BEFORE_UPDATE'
            WHEN e.run_at_utc > v_cutoff THEN 'RUN_AT_CHANGED_OR_NOT_DUE'
            WHEN v_allowed_job_types IS NOT NULL AND NOT (e.canonical_job_type = ANY(v_allowed_job_types) OR e.job_type = ANY(v_allowed_job_types) OR UPPER(BTRIM(COALESCE(e.job_type, ''))) = ANY(v_allowed_job_types)) THEN 'ALLOWED_JOB_TYPES_FILTER_MISMATCH'
            WHEN lower(BTRIM(COALESCE(e.serial_state_json->>'candidate_serial_blocked', e.serial_state_json->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'CANDIDATE_SERIAL_BLOCKED'
            WHEN e.serial_state_json->>'blocking_projection_run_id' IS NOT NULL OR e.serial_state_json->>'projection_run_id' IS NOT NULL THEN 'ACTIVE_PROJECTION_RUN'
            WHEN lower(BTRIM(COALESCE(e.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AND e.serial_state_json->>'blocked_chain_job_id' IS NOT NULL THEN 'ACTIVE_CONTINUATION'
            ELSE 'UNKNOWN_CLAIM_QUERY_MISMATCH'
          END AS claim_reject_reason
        FROM enriched AS e
      )
      SELECT
        COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
          'job_id', r.id::text,
          'job_type', r.job_type,
          'status', r.status,
          'candidate_id', CASE WHEN r.candidate_id IS NULL THEN NULL ELSE r.candidate_id::text END,
          'session_id', CASE WHEN r.session_id IS NULL THEN NULL ELSE r.session_id::text END,
          'dedupe_key', r.dedupe_key,
          'priority', r.priority,
          'run_at_utc', r.run_at_utc,
          'created_at_utc', r.created_at_utc,
          'started_at_utc', r.started_at_utc,
          'attempt_count', r.attempt_count,
          'max_attempts', r.max_attempts,
          'payload_candidate_serial_key', r.payload_json->>'candidate_serial_key',
          'payload_candidate_serial_wait_reason', r.payload_json->>'candidate_serial_wait_reason',
          'payload_projection_run_id', COALESCE(r.payload_json->>'projection_run_id', r.payload_json#>>'{cursor,projection_run_id}', r.payload_json#>>'{cursor_json,projection_run_id}'),
          'payload_source_change_seq', r.payload_json->>'source_change_seq',
          'payload_latest_source_change_seq', r.payload_json->>'latest_source_change_seq',
          'payload_continuation', r.payload_json->>'continuation',
          'payload_source_job_id', r.payload_json->>'source_job_id',
          'payload_run_mode', r.payload_json->>'run_mode',
          'payload_targeted_timesheet_ids', r.payload_json->'targeted_timesheet_ids',
          'is_candidate_job', r.is_candidate_job,
          'derived_candidate_id', CASE WHEN r.derived_candidate_id IS NULL THEN NULL ELSE r.derived_candidate_id::text END,
          'derived_candidate_serial_key', r.derived_candidate_serial_key,
          'candidate_serial_active_state', r.serial_state_json,
          'same_candidate_active_job_id', CASE WHEN r.same_candidate_active_job_id IS NULL THEN NULL ELSE r.same_candidate_active_job_id::text END,
          'same_candidate_active_projection_run_id', CASE WHEN r.same_candidate_active_projection_run_id IS NULL THEN NULL ELSE r.same_candidate_active_projection_run_id::text END,
          'advisory_lock_attempted', false,
          'advisory_lock_granted', NULL,
          'claim_filter_passed', false,
          'allowed_job_types_filter_passed', NOT (v_allowed_job_types IS NOT NULL AND NOT (r.canonical_job_type = ANY(v_allowed_job_types) OR r.job_type = ANY(v_allowed_job_types) OR UPPER(BTRIM(COALESCE(r.job_type, ''))) = ANY(v_allowed_job_types))),
          'claim_reject_reason', r.claim_reject_reason,
          'worker_id', NULL,
          'origin', 'pay_workbench_claim_due_jobs'
        )) ORDER BY r.priority ASC, r.run_at_utc ASC, r.created_at_utc ASC, r.id ASC), '[]'::jsonb),
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'CANDIDATE_SERIAL_BLOCKED'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'ACTIVE_PROJECTION_RUN'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'ALLOWED_JOB_TYPES_FILTER_MISMATCH'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'JOB_STATUS_CHANGED_BEFORE_UPDATE'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'OBSOLETE_OR_SUPERSEDED'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'UNKNOWN_CLAIM_QUERY_MISMATCH'), 0)::integer,
        COALESCE((array_agg(r.claim_reject_reason ORDER BY r.priority ASC, r.run_at_utc ASC, r.created_at_utc ASC, r.id ASC))[1], 'UNKNOWN_CLAIM_QUERY_MISMATCH')
      INTO
        v_claimable_sample,
        v_candidate_serial_reject_count,
        v_active_projection_reject_count,
        v_allowed_job_types_reject_count,
        v_status_changed_before_claim_count,
        v_obsolete_or_superseded_reject_count,
        v_unknown_claim_query_mismatch_count,
        v_claim_mismatch_reason
      FROM rejected AS r;
    EXCEPTION WHEN OTHERS THEN
      v_claimable_sample := COALESCE(v_preclaim_due_queued_sample, '[]'::jsonb);
      v_claim_mismatch_reason := 'UNKNOWN_CLAIM_QUERY_MISMATCH';
      v_unknown_claim_query_mismatch_count := GREATEST(COALESCE(v_preclaim_due_queued_count, 0), 1);
    END;

    v_claim_reject_summary := jsonb_strip_nulls(jsonb_build_object(
      'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
      'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
      'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
      'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
      'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
      'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
      'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
      'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0)
    ));
    v_claim_mismatch_json := jsonb_strip_nulls(jsonb_build_object(
      'claim_mismatch_detected', true,
      'claim_mismatch_reason', COALESCE(v_claim_mismatch_reason, 'UNKNOWN_CLAIM_QUERY_MISMATCH'),
      'claimable_count', COALESCE(v_preclaim_due_queued_count, 0),
      'claimed_count', COALESCE(v_claimed_count, 0),
      'claimable_sample', COALESCE(v_claimable_sample, '[]'::jsonb),
      'claim_reject_summary', COALESCE(v_claim_reject_summary, '{}'::jsonb),
      'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
      'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
      'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
      'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
      'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
      'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
      'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
      'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0),
      'function_name', 'pay_workbench_claim_due_jobs',
      'stage', 'CLAIMABLE_BUT_UNCLAIMED_EXPLAIN',
      'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'allowed_job_types', CASE WHEN v_allowed_job_types IS NULL THEN NULL ELSE to_jsonb(v_allowed_job_types) END
    ));
    BEGIN
      PERFORM public._temp_diag_log(
        'TEMP_WORKBENCH_CLAIM_DIAG',
        'CLAIMABLE_BUT_UNCLAIMED_EXPLAIN',
        COALESCE(p_session_id::text, p_candidate_id::text, 'pay_workbench_claim_due_jobs'),
        v_claim_mismatch_json
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'limit', v_limit,
    'stale_recovery_limit', v_stale_recovery_limit,
    'due_queued_count', v_preclaim_due_queued_count,
    'visible_due_queued_count', v_preclaim_due_queued_count,
    'claimable_count', v_preclaim_due_queued_count,
    'claimable_due_count', v_preclaim_due_queued_count,
    'claim_mismatch_detected', COALESCE(v_claim_mismatch_detected, false),
    'claim_mismatch_reason', CASE WHEN v_claim_mismatch_detected THEN COALESCE(v_claim_mismatch_reason, 'UNKNOWN_CLAIM_QUERY_MISMATCH') ELSE NULL END,
    'claim_mismatch_json', COALESCE(v_claim_mismatch_json, '{}'::jsonb),
    'claimable_sample', CASE WHEN v_claim_mismatch_detected THEN COALESCE(v_claimable_sample, '[]'::jsonb) ELSE COALESCE(v_preclaim_due_queued_sample, '[]'::jsonb) END,
    'claim_reject_summary', COALESCE(v_claim_reject_summary, '{}'::jsonb),
    'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
    'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
    'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
    'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
    'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
    'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
    'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
    'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0),
    'claim_lock_contention_detected', v_claim_lock_contention_detected,
    'lock_contention_detected', v_claim_lock_contention_detected,
    'claim_lock_contention_count', v_claim_lock_contention_count,
    'lock_contention_count', v_claim_lock_contention_count,
    'delta_queued_coalesced_count', COALESCE(v_delta_queued_coalesced_count, 0),
    'delta_queued_coalesced_hot_key_count', COALESCE(v_delta_queued_coalesced_hot_key_count, 0),
    'delta_stale_continuation_superseded_before_claim_count', COALESCE(v_delta_stale_continuation_superseded_count, 0),
    'delta_stale_continuation_superseded_before_claim_sample', COALESCE(v_delta_stale_continuation_sample, '[]'::jsonb),
    'delta_stale_projection_terminalised_before_claim_count', COALESCE(v_delta_stale_projection_terminalised_count, 0),
    'delta_stale_projection_terminalised_before_claim_sample', COALESCE(v_delta_stale_projection_terminalisation_sample, '[]'::jsonb),
    'claim_lock_contention_sample', CASE
      WHEN v_claim_lock_contention_detected THEN COALESCE(v_claimable_sample, '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  )
  || jsonb_build_object(
    'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'allowed_job_types', CASE WHEN v_allowed_job_types IS NULL THEN NULL ELSE to_jsonb(v_allowed_job_types) END,
    'recovered_stale_count', v_recovered_stale_count,
    'dead_stale_count', v_dead_stale_count,
    'failed_stale_count', v_dead_stale_count,
    'projection_lifecycle_repair', COALESCE(v_projection_lifecycle_repair_json, '{}'::jsonb),
    'projection_lifecycle_repaired_count', CASE WHEN COALESCE(v_projection_lifecycle_repair_json->>'repaired_count', '') ~ '^[0-9]+$' THEN (v_projection_lifecycle_repair_json->>'repaired_count')::integer ELSE 0 END,
    'invalid_source_build_poison_repair', COALESCE(v_invalid_source_build_poison_repair_json, '{}'::jsonb),
    'invalid_source_build_poison_repaired_count', CASE WHEN COALESCE(v_invalid_source_build_poison_repair_json->>'repaired_count', '') ~ '^[0-9]+$' THEN (v_invalid_source_build_poison_repair_json->>'repaired_count')::integer ELSE 0 END,
    'claimed_count', v_claimed_count,
    'claimed_delta_refresh_count', COALESCE(v_claimed_delta_refresh_count, 0),
    'claimed_clone_rebase_count', COALESCE(v_claimed_clone_rebase_count, 0),
    'recovered_stale', v_recovered_stale,
    'dead_stale', v_dead_stale,
    'failed_stale', v_dead_stale,
    'claimed', v_claimed
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_complete_job(p_job_id uuid, p_result_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_result_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_job_type text := NULL::text;
  v_stage_job_type text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_has_open_session boolean := false;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_seeded_count integer := 0;
  v_new_scope_count integer := 0;
  v_processed_count integer := 0;
  v_ready_count_delta integer := 0;
  v_materialised_count integer := 0;
  v_error_count integer := 0;
  v_source_rows_written integer := 0;
  v_current_source_row_count integer := 0;
  v_source_build_run_id_text text := NULL::text;
  v_source_change_seq bigint := NULL::bigint;
  v_result_session_version bigint := NULL::bigint;
  v_source_seed_cursor_json jsonb := '{}'::jsonb;
  v_pending_line_work_exists boolean := false;
  v_ready_line_work_exists boolean := false;
  v_continuation_result jsonb := '{}'::jsonb;
  v_continuation_job_id_text text := NULL::text;
  v_continuation_jobs jsonb := '[]'::jsonb;
  v_continuation_count integer := 0;
  v_continuation_enqueued boolean := false;
  v_continuation_reused_count integer := 0;
  v_next_recommended_action text := NULL::text;
  v_existing_completion_json jsonb := '{}'::jsonb;
  v_payload_limit integer := 100;
  v_duplicate_completion boolean := false;
  v_completed_at_utc timestamptz := NULL::timestamptz;
  v_scope_pending_job_cleared_count integer := 0;
  v_scope_status_before_continuation text := NULL::text;
  v_scope_status_after_continuation text := NULL::text;
  v_scope_bucket_before_continuation text := NULL::text;
  v_scope_bucket_after_continuation text := NULL::text;
  v_scope_continuation_pending_delta integer := 0;
  v_scope_continuation_ready_delta integer := 0;
  v_scope_continuation_failed_delta integer := 0;
  v_scope_continuation_counter_adjusted boolean := false;
  v_finalisation_should_evaluate boolean := false;
  v_finalisation_actual_precheck_required boolean := false;
  v_finalisation_actual_precheck_passed boolean := false;
  v_current_candidate_terminal_success boolean := false;
  v_finalisation_evaluated boolean := false;
  v_finalisation_progress_json jsonb := '{}'::jsonb;
  v_finalisation_session_ready boolean := false;
  v_finalisation_ready_for_draft boolean := false;
  v_finalisation_ready_empty boolean := false;
  v_finalisation_stored_ready_mismatch boolean := false;
  v_finalisation_counter_reconciliation_required boolean := false;
  v_finalisation_counter_reconciliation_applied boolean := false;
  v_finalisation_counter_reconciled boolean := false;
  v_finalisation_counter_reconciliation_json jsonb := '{}'::jsonb;
  v_finalisation_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_draft_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_blocker_counts jsonb := '{}'::jsonb;
  v_final_progress_state text := NULL::text;
  v_final_phase text := NULL::text;
  v_final_status_text text := NULL::text;
  v_final_next_recommended_action text := NULL::text;
  v_authoritative_scope_total integer := 0;
  v_authoritative_scope_seeded integer := 0;
  v_authoritative_scope_ready integer := 0;
  v_authoritative_scope_pending integer := 0;
  v_authoritative_scope_failed integer := 0;
  v_authoritative_line_total integer := 0;
  v_authoritative_line_pending integer := 0;
  v_authoritative_line_ready integer := 0;
  v_authoritative_line_failed integer := 0;
  v_authoritative_preview_row_count integer := 0;
  v_authoritative_selected_row_count integer := 0;
  v_authoritative_section_counts_json jsonb := '{}'::jsonb;
  v_authoritative_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_completion_finalisation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_applied boolean := false;
  v_source_reconciliation_deferred boolean := false;
  v_source_reconciliation_deferred_reason text := NULL::text;
  v_source_empty_session_progress_deferred boolean := false;
  v_source_empty_session_progress_deferred_reason text := NULL::text;
  v_source_empty_cleanup_source_row_count integer := 0;
  v_source_empty_cleanup_line_work_count integer := 0;
  v_source_empty_cleanup_preview_row_count integer := 0;
  v_source_empty_targeted_timesheet_count integer := 0;
  v_continuation_scope_counter_deferred boolean := false;
  v_continuation_scope_counter_deferred_reason text := NULL::text;
  v_finalisation_deferred boolean := false;
  v_finalisation_deferred_reason text := NULL::text;
  v_delta_fallback_required boolean := false;
  v_delta_fallback_reason text := NULL::text;
  v_delta_refresh_complete boolean := false;
  v_delta_more_due boolean := false;
  v_delta_made_progress boolean := false;
  v_delta_projection_run_id_text text := NULL::text;
  v_delta_next_cursor_json jsonb := NULL::jsonb;
  v_delta_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_source_rows_written integer := 0;
  v_delta_line_rows_written integer := 0;
  v_delta_preview_rows_written integer := 0;
  v_delta_rows_superseded integer := 0;
  v_delta_shadow_compare_status text := NULL::text;
  v_delta_shadow_compare_required boolean := false;
  v_delta_shadow_compare_enforced boolean := false;
  v_delta_shadow_compare_failed boolean := false;
  v_clone_more_due boolean := false;
  v_clone_complete boolean := false;
  v_clone_copied_candidate_count integer := 0;
  v_clone_copied_preview_row_count integer := 0;
  v_clone_legacy_refresh_enqueued_count integer := 0;
  v_clone_continuation_job_id uuid := NULL::uuid;
  v_clone_source_session_id_text text := NULL::text;
  v_clone_source_session_id uuid := NULL::uuid;
  v_clone_source_session_retired_count integer := 0;
  v_delta_fallback_enqueue_result jsonb := '{}'::jsonb;
  v_delta_fallback_job_id_text text := NULL::text;
  v_delta_scope_total_count integer := 0;
  v_delta_scope_ready_count integer := 0;
  v_delta_scope_pending_count integer := 0;
  v_delta_scope_failed_count integer := 0;
  v_delta_line_units_total integer := 0;
  v_delta_line_units_ready integer := 0;
  v_delta_line_units_pending integer := 0;
  v_delta_line_units_failed integer := 0;
  v_delta_preview_row_count integer := 0;
  v_delta_selected_row_count integer := 0;
  v_delta_section_counts_json jsonb := '{}'::jsonb;
  v_delta_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_live_source_change_seq bigint := 0;
  v_delta_superseded_by_live_source_guard boolean := false;
  v_delta_superseded_projection_runs integer := 0;
  v_delta_projection_mode text := 'DELTA';
  v_delta_projection_class text := 'UNKNOWN';
  v_delta_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_delta_lifecycle_context text := NULL::text;
  v_delta_is_normal_targeted_lifecycle boolean := false;
  v_delta_recovery_enqueue_result jsonb := '{}'::jsonb;
  v_delta_recovery_job_id_text text := NULL::text;
  v_delta_recovery_job_id uuid := NULL::uuid;
  v_delta_recovery_source_change_seq bigint := 0;
  v_delta_recovery_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_delta_recovery_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  SELECT workbench_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS workbench_job
  WHERE workbench_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  v_duplicate_completion := UPPER(BTRIM(COALESCE(v_job_row.status, ''))) = 'SUCCEEDED'
    AND v_job_row.completed_at_utc IS NOT NULL;

  IF v_duplicate_completion THEN
    v_existing_completion_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_result_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)
      ELSE v_result_json
    END;

    v_continuation_jobs := CASE
      WHEN jsonb_typeof(COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)) = 'array'
        THEN COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    v_continuation_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_count')::integer
      ELSE jsonb_array_length(v_continuation_jobs)
    END;

    v_continuation_reused_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_reused_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_reused_count')::integer
      ELSE 0
    END;

    v_continuation_enqueued := COALESCE(v_continuation_count, 0) > 0
      OR LOWER(BTRIM(COALESCE(v_existing_completion_json->>'continuation_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_next_recommended_action := NULLIF(BTRIM(COALESCE(v_existing_completion_json->>'next_recommended_action', '')), '');
    v_completed_at_utc := v_job_row.completed_at_utc;
  END IF;

  v_job_type := UPPER(BTRIM(COALESCE(v_job_row.job_type, '')));
  v_stage_job_type := CASE
    WHEN v_job_type IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED') THEN 'WORKBENCH_SESSION_SCOPE_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE') THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    WHEN v_job_type IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN 'WORKBENCH_SESSION_CLONE_REBASE'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS', 'LINE_WORK_PROCESS') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
    WHEN v_job_type IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE') THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    WHEN v_job_type IN ('SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
      AND v_job_row.session_id IS NOT NULL
      AND COALESCE((v_job_row.payload_json->>'line_work_only')::boolean, false) IS TRUE THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    ELSE v_job_type
  END;

  IF COALESCE(v_result_json->>'has_more', '') ~* '^(true|t|1|yes)$' THEN
    v_has_more := true;
  ELSE
    v_has_more := false;
  END IF;

  v_next_cursor := CASE
    WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
    WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
    WHEN jsonb_typeof(v_result_json->'nextCursor') = 'object' THEN v_result_json->'nextCursor'
    WHEN jsonb_typeof(v_result_json->'nextCursorJson') = 'object' THEN v_result_json->'nextCursorJson'
    ELSE NULL::jsonb
  END;

  v_seeded_count := CASE WHEN COALESCE(v_result_json->>'seeded_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'seeded_count')::integer ELSE 0 END;
  v_new_scope_count := CASE WHEN COALESCE(v_result_json->>'new_scope_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'new_scope_count')::integer ELSE 0 END;
  v_processed_count := CASE WHEN COALESCE(v_result_json->>'processed_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'processed_count')::integer ELSE 0 END;
  v_ready_count_delta := CASE WHEN COALESCE(v_result_json->>'ready_count_delta', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'ready_count_delta')::integer ELSE 0 END;
  v_materialised_count := CASE
    WHEN COALESCE(v_result_json->>'materialised_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialised_count')::integer
    WHEN COALESCE(v_result_json->>'materialized_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialized_count')::integer
    ELSE 0
  END;
  v_error_count := CASE
    WHEN COALESCE(v_result_json->>'error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'error_count')::integer
    WHEN COALESCE(v_result_json->>'materialisation_error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialisation_error_count')::integer
    ELSE 0
  END;
  v_source_rows_written := CASE
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    ELSE 0
  END;
  v_current_source_row_count := CASE
    WHEN COALESCE(v_result_json->>'current_source_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'current_source_row_count')::integer
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    ELSE 0
  END;
  v_source_build_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,source_build_run_id}', '')), '')
  );
  v_source_change_seq := CASE
    WHEN COALESCE(v_result_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_sequence')::bigint
    ELSE NULL::bigint
  END;
  v_result_session_version := CASE
    WHEN COALESCE(v_result_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'session_version')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'session_version')::bigint
    ELSE NULL::bigint
  END;
  v_source_seed_cursor_json := jsonb_strip_nulls(jsonb_build_object(
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_result_session_version,
    'source_snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'source_row_cursor', 'START'
  ));
  v_payload_limit := LEAST(
    GREATEST(
      CASE
        WHEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''), '') ~ '^[0-9]+$'
          THEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''))::integer
        ELSE 100
      END,
      1
    ),
    100
  );

  IF v_job_row.session_id IS NOT NULL THEN
    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_job_row.session_id;

    v_has_open_session := FOUND
      AND UPPER(BTRIM(COALESCE(v_session_row.status, ''))) = 'OPEN'
      AND v_session_row.discarded_at_utc IS NULL;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN',
              'job_id', p_job_id::text,
              'session_id', v_job_row.session_id::text,
              'job_type', v_stage_job_type,
              'status', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.status END,
              'discarded_at_utc', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.discarded_at_utc END
            )::text;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_delta_fallback_required := LOWER(BTRIM(COALESCE(v_result_json->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_fallback_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'fallback_reason', '')), ''), 'DELTA_REFRESH_FALLBACK_REQUIRED');
    v_delta_refresh_complete := LOWER(BTRIM(COALESCE(v_result_json->>'delta_refresh_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_made_progress := LOWER(BTRIM(COALESCE(v_result_json->>'made_progress', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_projection_run_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_run_id', '')), '')
    );
    v_delta_next_cursor_json := CASE
      WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
      WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
      WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
      ELSE '{}'::jsonb
    END;
    v_delta_targeted_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_linked_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_source_rows_written := CASE WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer ELSE 0 END;
    v_delta_line_rows_written := CASE WHEN COALESCE(v_result_json->>'line_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'line_rows_written')::integer ELSE 0 END;
    v_delta_preview_rows_written := CASE WHEN COALESCE(v_result_json->>'preview_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'preview_rows_written')::integer ELSE 0 END;
    v_delta_rows_superseded := CASE WHEN COALESCE(v_result_json->>'rows_superseded', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'rows_superseded')::integer ELSE 0 END;
    v_delta_shadow_compare_status := UPPER(BTRIM(COALESCE(v_result_json->>'shadow_compare_status', '')));
    v_delta_shadow_compare_required := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_required',
      v_job_row.payload_json->>'shadow_compare_required',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_enforced',
      v_job_row.payload_json->>'shadow_compare_enforced',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := COALESCE(v_delta_shadow_compare_required, false)
      AND COALESCE(v_delta_shadow_compare_enforced, false);
    v_delta_shadow_compare_failed := LOWER(BTRIM(COALESCE(v_result_json->>'shadow_compare_failed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR v_delta_shadow_compare_status = 'MISMATCH'
      OR (
        COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
        AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
      );
    IF v_delta_shadow_compare_failed IS TRUE THEN
      v_delta_fallback_required := true;
      v_delta_fallback_reason := CASE
        WHEN COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
         AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
          THEN 'SHADOW_REFERENCE_UNAVAILABLE'
        ELSE 'SHADOW_COMPARE_MISMATCH'
      END;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT parsed_target.timesheet_id ORDER BY parsed_target.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_targeted_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(target_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) AS target_value(value)
      WHERE NULLIF(BTRIM(target_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_target;

    SELECT COALESCE(array_agg(DISTINCT parsed_linked.timesheet_id ORDER BY parsed_linked.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_linked_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(linked_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
      WHERE NULLIF(BTRIM(linked_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_linked;

    v_delta_projection_mode := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_mode',
      v_job_row.payload_json->>'projection_mode',
      v_result_json->>'resolved_mode',
      v_job_row.payload_json->>'resolved_mode',
      'DELTA'
    ))), ''), 'DELTA');

    v_delta_projection_class := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_class',
      v_job_row.payload_json->>'projection_class',
      'UNKNOWN'
    ))), ''), 'UNKNOWN');

    v_delta_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'refresh_scope_kind',
      v_job_row.payload_json->>'refresh_scope_kind',
      ''
    ))), ''), CASE
      WHEN COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
        OR COALESCE(array_length(v_delta_recovery_linked_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END);

    v_delta_lifecycle_context := LOWER(BTRIM(COALESCE(
      v_result_json->>'lifecycle_mutation_context',
      v_job_row.payload_json->>'lifecycle_mutation_context',
      v_result_json->>'mutation_context',
      v_job_row.payload_json->>'mutation_context',
      v_result_json->>'lifecycle_context',
      v_job_row.payload_json->>'lifecycle_context',
      v_result_json->>'trigger_source',
      v_job_row.payload_json->>'trigger_source',
      v_result_json->>'reason',
      v_job_row.payload_json->>'reason_latest',
      v_job_row.payload_json->>'reason',
      ''
    )));

    v_delta_is_normal_targeted_lifecycle := v_delta_projection_mode = 'DELTA'
      AND v_delta_projection_class = 'NORMAL_TIMESHEET'
      AND v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS'
      AND COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
      AND COALESCE(v_delta_shadow_compare_failed, false) IS NOT TRUE
      AND (
        COALESCE(v_delta_fallback_required, false) IS NOT TRUE
        OR UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
        OR LOWER(BTRIM(COALESCE(v_result_json->>'identical_cursor_self_reuse_suppressed', v_result_json->>'continuation_not_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_legacy', v_job_row.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_broad_legacy', v_job_row.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'source_build_required', v_job_row.payload_json->>'source_build_required', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'ordinary_timesheet_edit_save_no_dirty', v_job_row.payload_json->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND (
        LOWER(BTRIM(COALESCE(v_result_json->>'authorise_boundary_changed', v_job_row.payload_json->>'authorise_boundary_changed', v_result_json->>'timesheet_authorise_boundary_changed', v_job_row.payload_json->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR v_delta_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%authorise%'
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
      );

    v_delta_next_cursor_json := COALESCE(v_delta_next_cursor_json, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'projection_run_id', v_delta_projection_run_id_text,
        'phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'next_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_result_json->>'phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'phase', '')), '')),
        'cursor', CASE
          WHEN jsonb_typeof(v_delta_next_cursor_json->'cursor') = 'object' THEN v_delta_next_cursor_json->'cursor'
          WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
          ELSE '{}'::jsonb
        END,
        'write_phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'write_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'write_phase', '')), '')),
        'write_cursor_json', CASE
          WHEN jsonb_typeof(v_result_json->'write_cursor_json') = 'object' THEN v_result_json->'write_cursor_json'
          WHEN jsonb_typeof(v_delta_next_cursor_json->'write_cursor_json') = 'object' THEN v_delta_next_cursor_json->'write_cursor_json'
          WHEN jsonb_typeof(v_job_row.payload_json->'write_cursor_json') = 'object' THEN v_job_row.payload_json->'write_cursor_json'
          ELSE NULL::jsonb
        END,
        'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', CASE WHEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq', '') ~ '^-?[0-9]+$' THEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END
      ));

    IF v_job_row.candidate_id IS NOT NULL
       AND v_source_change_seq IS NOT NULL THEN
      SELECT COALESCE(change_counter.seq, 0)
      INTO v_live_source_change_seq
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

      v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);

      IF COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
        v_delta_superseded_by_live_source_guard := true;
        v_delta_more_due := false;
        v_delta_fallback_required := false;
        v_delta_refresh_complete := true;
        v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';

        v_result_json := jsonb_strip_nulls(
          COALESCE(v_result_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'complete_job_live_source_guard_applied', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'live_source_change_seq', v_live_source_change_seq,
            'fallback_required', false,
            'delta_refresh_complete', true,
            'more_due', false,
            'has_more', false,
            'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
          )
        );

        IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
          SET status = 'FAILED',
              fallback_required = false,
              fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
              diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                || jsonb_build_object(
                  'superseded_by_newer_source_change_seq', true,
                  'complete_job_live_source_guard_applied', true,
                  'source_change_seq', v_source_change_seq,
                  'newer_source_change_seq', v_live_source_change_seq,
                  'terminalised_by', 'pay_workbench_complete_job',
                  'terminalised_at_utc', v_now::text
                ),
              updated_at_utc = v_now,
              completed_at_utc = v_now
          WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
            AND projection_run_update.session_id = v_job_row.session_id
            AND projection_run_update.candidate_id = v_job_row.candidate_id
            AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

          GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
        END IF;
      END IF;
    ELSE
      v_live_source_change_seq := 0;
    END IF;

    IF v_delta_superseded_by_live_source_guard IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := '[]'::jsonb;
      v_continuation_count := 0;
      v_continuation_reused_count := 0;
      v_continuation_enqueued := false;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_more_due IS TRUE THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => v_job_row.candidate_id,
        p_job_type => 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        p_cursor_json => COALESCE(v_delta_next_cursor_json, '{}'::jsonb),
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'DELTA_REFRESH_MORE_DUE',
        p_priority => COALESCE(v_job_row.priority, 43),
        p_limit => v_payload_limit
      );

      v_continuation_job_id_text := NULLIF(BTRIM(COALESCE(v_continuation_result->>'job_id', '')), '');

      IF LOWER(BTRIM(COALESCE(
           v_continuation_result->>'identical_cursor_self_reuse_suppressed',
           v_continuation_result->>'continuation_not_enqueued',
           'false'
         ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        IF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL THEN
          SELECT COALESCE(change_counter.seq, 0)
          INTO v_live_source_change_seq
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

          v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
        END IF;

        IF v_delta_is_normal_targeted_lifecycle IS TRUE THEN
          v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
          v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'identical_cursor_self_reuse_suppressed', true,
              'delta_identical_cursor_self_reuse_no_source_build', true,
              'fallback_required', false,
              'fallback_reason', v_delta_fallback_reason,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
              'next_recommended_action', 'DELTA_REFRESH_CHUNK'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'delta_identical_cursor_self_reuse_no_source_build', true,
                    'successor_required', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'source_change_seq', COALESCE(v_source_change_seq, 0),
                    'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                    'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              (COALESCE(v_job_row.payload_json, '{}'::jsonb) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present',
                'projection_run_id'
              ]::text[])
              || jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'workbench_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', false,
                'force_broad_legacy', false,
                'fallback_from_delta', false,
                'fallback_reason', v_delta_fallback_reason,
                'projection_mode', 'DELTA',
                'projection_class', 'NORMAL_TIMESHEET',
                'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                'phase', 'INIT_PREFLIGHT',
                'cursor_json', '{}'::jsonb,
                'source_build_required', false,
                'line_work_required', false,
                'delta_refresh_required', true,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'successor_for_job_id', p_job_id::text,
                'previous_projection_run_id', v_delta_projection_run_id_text,
                'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                'lifecycle_mutation_context', CASE
                  WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                    OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                  THEN 'timesheet_unauthorise'
                  ELSE 'timesheet_authorise'
                END,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                'policy_x_dirtying_only', true,
                'economic_truth_mutation_allowed', false
              )
            )
          );

          v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

          IF v_delta_recovery_job_id_text = p_job_id::text THEN
            v_delta_recovery_job_id_text := NULL;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL THEN
            v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
              p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
              p_scope_kind => 'CANDIDATE',
              p_scope_id => v_job_row.candidate_id::text,
              p_candidate_id => v_job_row.candidate_id,
              p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
              p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
              p_payload_json => jsonb_strip_nulls(
                COALESCE(v_job_row.payload_json, '{}'::jsonb)
                || jsonb_build_object(
                  'session_id', v_job_row.session_id::text,
                  'source_session_id', v_job_row.session_id::text,
                  'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'session_version', COALESCE(v_session_row.version, 0),
                  'session_signature', v_session_row.session_signature,
                  'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                  'projection_mode', 'DELTA',
                  'projection_class', 'NORMAL_TIMESHEET',
                  'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                  'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                  'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
                  'fallback_reason', v_delta_fallback_reason,
                  'source_build_required', false,
                  'line_work_required', false,
                  'delta_refresh_required', true,
                  'identical_cursor_self_reuse_suppressed', true,
                  'delta_identical_cursor_self_reuse_no_source_build', true,
                  'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'lifecycle_mutation_context', CASE
                    WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                      OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                      OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                    THEN 'timesheet_unauthorise'
                    ELSE 'timesheet_authorise'
                  END,
                  'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                  'policy_x_dirtying_only', true,
                  'economic_truth_mutation_allowed', false
                )
              ),
              p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
              p_priority => -1000,
              p_run_at_utc => v_now
            );

            v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

            IF v_delta_recovery_job_id_text IS NULL
               AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
              SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
              INTO v_delta_recovery_job_id_text
              FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
              WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
                AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              LIMIT 1;
            END IF;

            IF v_delta_recovery_job_id_text = p_job_id::text THEN
              v_delta_recovery_job_id_text := NULL;
            END IF;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL
             OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
              USING ERRCODE = 'P0001',
                    DETAIL = jsonb_build_object(
                      'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                      'job_id', p_job_id::text,
                      'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                      'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                      'projection_run_id', v_delta_projection_run_id_text,
                      'source_change_seq', v_source_change_seq,
                      'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                      'message', 'Normal targeted lifecycle DELTA self-reuse suppression could not create or reuse a cron-claimable recovery job.'
                    )::text;
          END IF;

          v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

          UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
          SET status = CASE
                WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
                 AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
                  THEN 'PENDING'
                ELSE 'DELTA_REFRESH_PENDING'
              END,
              dirty = true,
              pending_job_id = v_delta_recovery_job_id,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_recovery_scope.session_id = v_job_row.session_id
            AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
          v_continuation_count := 1;
          v_continuation_reused_count := CASE
            WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            THEN 1
            ELSE 0
          END;
          v_continuation_enqueued := true;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSIF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL
           AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';
          v_delta_superseded_by_live_source_guard := true;

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'complete_job_live_source_guard_applied', true,
              'identical_cursor_self_reuse_suppressed', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'live_source_change_seq', v_live_source_change_seq,
              'fallback_required', false,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'superseded_by_newer_source_change_seq', true,
                    'complete_job_live_source_guard_applied', true,
                    'identical_cursor_self_reuse_suppressed', true,
                    'source_change_seq', v_source_change_seq,
                    'newer_source_change_seq', v_live_source_change_seq,
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

            GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
          END IF;

          UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
          SET dirty = true,
              pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_superseded_scope.session_id = v_job_row.session_id
            AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result);
          v_continuation_count := 0;
          v_continuation_reused_count := 0;
          v_continuation_enqueued := false;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSE
          v_delta_more_due := false;
          v_delta_fallback_required := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FALLBACK_REQUIRED',
                fallback_required = true,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => v_delta_fallback_reason,
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', true,
                'fallback_from_delta', true,
                'fallback_reason', v_delta_fallback_reason,
                'projection_run_id', v_delta_projection_run_id_text,
                'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
                'source_build_required', true,
                'line_work_required', true,
                'delta_refresh_required', false,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
              )
            )
          );

          v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');

          UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
          SET status = 'SOURCE_BUILD_PENDING',
              dirty = true,
              pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_fallback_scope.session_id = v_job_row.session_id
            AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_fallback_enqueue_result);
          v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
          v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
          v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
          v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
        END IF;
      ELSE
        IF v_continuation_job_id_text IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta more_due completion did not receive a concrete continuation job id.'
                  )::text;
        END IF;

        IF v_continuation_job_id_text = p_job_id::text THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta continuation helper returned the currently completing job as its own continuation.'
                  )::text;
        END IF;

        v_continuation_jobs := jsonb_build_array(v_continuation_result);
        v_continuation_count := 1;
        v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_continuation_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
        v_continuation_enqueued := true;
        v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
      END IF;
    ELSIF v_delta_fallback_required IS TRUE
          AND v_delta_is_normal_targeted_lifecycle IS TRUE
          AND UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED' THEN
      IF v_job_row.candidate_id IS NOT NULL
         AND v_source_change_seq IS NOT NULL THEN
        SELECT COALESCE(change_counter.seq, 0)
        INTO v_live_source_change_seq
        FROM public.app_change_counters AS change_counter
        WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

        v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
      END IF;

      v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
      v_delta_more_due := false;
      v_delta_fallback_required := false;
      v_delta_refresh_complete := true;
      v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
      v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'action', 'DIRECT_FALLBACK_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD',
        'continuation_not_enqueued', true,
        'identical_cursor_self_reuse_suppressed', true,
        'delta_identical_cursor_self_reuse_no_source_build', true,
        'normal_targeted_lifecycle_delta', true,
        'successor_required', true,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
        'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
        'projection_run_id', v_delta_projection_run_id_text
      );

      v_result_json := jsonb_strip_nulls(
        COALESCE(v_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'fallback_required', false,
          'fallback_reason', v_delta_fallback_reason,
          'delta_refresh_complete', true,
          'more_due', false,
          'has_more', false,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
          'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRECT_FALLBACK_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
          'next_recommended_action', 'DELTA_REFRESH_CHUNK'
        )
      );

      IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
        SET status = 'FAILED',
            fallback_required = false,
            fallback_reason = v_delta_fallback_reason,
            diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
              || jsonb_build_object(
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'direct_fallback_intercepted', true,
                'successor_required', true,
                'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                'source_change_seq', COALESCE(v_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                'terminalised_by', 'pay_workbench_complete_job',
                'terminalised_at_utc', v_now::text
              ),
            updated_at_utc = v_now,
            completed_at_utc = v_now
        WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
          AND projection_run_update.session_id = v_job_row.session_id
          AND projection_run_update.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) IN ('RUNNING', 'FALLBACK_REQUIRED');
      END IF;

      v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'workbench_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', false,
          'force_broad_legacy', false,
          'fallback_from_delta', false,
          'fallback_reason', v_delta_fallback_reason,
          'projection_mode', 'DELTA',
          'projection_class', 'NORMAL_TIMESHEET',
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'phase', 'INIT_PREFLIGHT',
          'cursor_json', '{}'::jsonb,
          'source_build_required', false,
          'line_work_required', false,
          'delta_refresh_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
          'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'successor_for_job_id', p_job_id::text,
          'previous_projection_run_id', v_delta_projection_run_id_text,
          'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
          'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'lifecycle_mutation_context', CASE
            WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
              OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
            THEN 'timesheet_unauthorise'
            ELSE 'timesheet_authorise'
          END,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'policy_x_dirtying_only', true,
          'economic_truth_mutation_allowed', false
        ))
      );

      v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

      IF v_delta_recovery_job_id_text = p_job_id::text THEN
        v_delta_recovery_job_id_text := NULL;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL THEN
        v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
          p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          p_scope_kind => 'CANDIDATE',
          p_scope_id => v_job_row.candidate_id::text,
          p_candidate_id => v_job_row.candidate_id,
          p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
          p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
          p_payload_json => jsonb_strip_nulls(jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'refresh_scope_kind', 'TARGETED_TIMESHEETS',
            'projection_mode', 'DELTA',
            'projection_class', 'NORMAL_TIMESHEET',
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
            'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
            'fallback_reason', v_delta_fallback_reason,
            'source_build_required', false,
            'line_work_required', false,
            'delta_refresh_required', true,
            'identical_cursor_self_reuse_suppressed', true,
            'delta_identical_cursor_self_reuse_no_source_build', true,
            'direct_fallback_intercepted', true,
            'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
            'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'lifecycle_mutation_context', CASE
              WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
              THEN 'timesheet_unauthorise'
              ELSE 'timesheet_authorise'
            END,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true,
            'economic_truth_mutation_allowed', false
          )),
          p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
          p_priority => -1000,
          p_run_at_utc => v_now
        );

        v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

        IF v_delta_recovery_job_id_text IS NULL
           AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
          SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
          INTO v_delta_recovery_job_id_text
          FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
          WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
            AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          LIMIT 1;
        END IF;

        IF v_delta_recovery_job_id_text = p_job_id::text THEN
          v_delta_recovery_job_id_text := NULL;
        END IF;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL
         OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                  'projection_run_id', v_delta_projection_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                  'message', 'Normal targeted lifecycle DELTA self-reuse fallback could not create or reuse a cron-claimable recovery job.'
                )::text;
      END IF;

      v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

      UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
      SET status = CASE
            WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
             AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'PENDING'
            ELSE 'DELTA_REFRESH_PENDING'
          END,
          dirty = true,
          pending_job_id = v_delta_recovery_job_id,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_recovery_scope.session_id = v_job_row.session_id
        AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
      v_continuation_count := 1;
      v_continuation_reused_count := CASE
        WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        THEN 1
        ELSE 0
      END;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_fallback_required IS TRUE THEN
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => COALESCE(v_delta_fallback_reason, 'DELTA_REFRESH_FALLBACK_REQUIRED'),
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'force_legacy', true,
            'fallback_from_delta', true,
            'fallback_reason', v_delta_fallback_reason,
            'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
            'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
            'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
            'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
            'projection_run_id', v_delta_projection_run_id_text,
            'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
          )
        )
      );
      v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');
      UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
      SET status = 'SOURCE_BUILD_PENDING',
          dirty = true,
          pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_fallback_scope.session_id = v_job_row.session_id
        AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
      v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
      v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE
          AND LOWER(BTRIM(COALESCE(v_result_json->>'superseded_by_newer_source_change_seq', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_ready_scope
      SET status = 'READY',
          seeded = true,
          dirty = false,
          pending_job_id = NULL::uuid,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_ready_scope.session_id = v_job_row.session_id
        AND delta_ready_scope.candidate_id = v_job_row.candidate_id;

      -- Session counters/progress are recomputed authoritatively after the completing
      -- delta job is marked SUCCEEDED, so stored active_jobs never captures this job as stale.


      v_next_recommended_action := 'READ_PREVIEW_PAGE';
    ELSE
      v_delta_fallback_required := true;
      v_delta_fallback_reason := COALESCE(v_delta_fallback_reason, 'DELTA_RESULT_NOT_TERMINAL');
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => v_delta_fallback_reason,
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', true,
          'fallback_from_delta', true,
          'fallback_reason', v_delta_fallback_reason,
          'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
          'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
          'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
          'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
          'projection_run_id', v_delta_projection_run_id_text,
          'source_build_required', true,
          'line_work_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)
        )
      );
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := 1;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_delta_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'delta_completion_handled', true,
              'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
              'fallback_required', COALESCE(v_delta_fallback_required, false),
              'fallback_reason', v_delta_fallback_reason,
              'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
              'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
              'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
              'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
              'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
              'projection_run_id', v_delta_projection_run_id_text,
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_delta_job.id = p_job_id
    RETURNING update_delta_job.*
    INTO v_job_row;

    PERFORM public.pay_workbench_session_recompute_progress_counters(
      p_session_id => v_job_row.session_id,
      p_apply => true,
      p_reason => CASE
        WHEN COALESCE(v_delta_fallback_required, false) IS TRUE THEN 'DELTA_COMPLETE_JOB_FALLBACK_AUTHORITATIVE_RECOMPUTE'
        ELSE 'DELTA_COMPLETE_JOB_AUTHORITATIVE_RECOMPUTE'
      END,
      p_write_progress_json => true
    );

    PERFORM public.pay_workbench_projection_lifecycle_repair(
      p_session_id => v_job_row.session_id,
      p_candidate_id => v_job_row.candidate_id,
      p_safe_age_seconds => 300,
      p_limit => 50,
      p_reason => 'DELTA_COMPLETE_JOB_PROJECTION_LIFECYCLE_REPAIR'
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'stage_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_completion_handled', true,
      'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
      'fallback_required', COALESCE(v_delta_fallback_required, false),
      'fallback_reason', v_delta_fallback_reason,
      'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
      'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
      'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
      'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
      'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
      'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
      'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
      'projection_run_id', v_delta_projection_run_id_text,
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'next_recommended_action', v_next_recommended_action,
      'old_line_work_seed_enqueued', false,
      'old_line_work_process_enqueued', false,
      'old_preview_materialise_enqueued', false,
      'source_rows_written', COALESCE(v_delta_source_rows_written, 0),
      'line_rows_written', COALESCE(v_delta_line_rows_written, 0),
      'preview_rows_written', COALESCE(v_delta_preview_rows_written, 0),
      'rows_superseded', COALESCE(v_delta_rows_superseded, 0),
      'completed_at_utc', v_now::text
    );
  END IF;


  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_clone_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_clone_complete := LOWER(BTRIM(COALESCE(v_result_json->>'clone_rebase_complete', v_result_json->>'complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_clone_more_due IS NOT TRUE;
    v_clone_copied_candidate_count := CASE WHEN COALESCE(v_result_json->>'copied_candidate_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_candidate_count')::integer ELSE 0 END;
    v_clone_copied_preview_row_count := CASE WHEN COALESCE(v_result_json->>'copied_preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_preview_row_count')::integer ELSE 0 END;
    v_clone_legacy_refresh_enqueued_count := CASE WHEN COALESCE(v_result_json->>'legacy_refresh_enqueued_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'legacy_refresh_enqueued_count')::integer ELSE 0 END;
    v_clone_source_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'clone_from_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id_text', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'clone_from_session_id', '')), '')
    );
    IF v_clone_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_clone_source_session_id := v_clone_source_session_id_text::uuid;
    ELSE
      v_clone_source_session_id := NULL::uuid;
    END IF;

    IF v_clone_more_due IS TRUE THEN
      INSERT INTO public.banking_pay_workbench_jobs AS clone_continuation (
        job_type,
        status,
        priority,
        run_at_utc,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc
      )
      VALUES (
        'WORKBENCH_SESSION_CLONE_REBASE',
        'QUEUED',
        COALESCE(v_job_row.priority, 45),
        v_now,
        'WORKBENCH_SESSION_CLONE_REBASE:session:' || v_job_row.session_id::text || ':cursor:' || md5(COALESCE(v_next_cursor, '{}'::jsonb)::text),
        v_job_row.snapshot_run_id,
        v_job_row.session_id,
        v_job_row.candidate_id,
        jsonb_strip_nulls(
          COALESCE(v_job_row.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
            'cursor_json', COALESCE(v_next_cursor, '{}'::jsonb),
            'source_job_id', p_job_id::text,
            'continuation', true,
            'more_due_from_previous', true,
            'previous_result_summary', jsonb_build_object(
              'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
              'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
              'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0)
            )
          )
        ),
        v_now,
        v_now
      )
      ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
      DO UPDATE SET
        run_at_utc = LEAST(clone_continuation.run_at_utc, EXCLUDED.run_at_utc),
        priority = LEAST(clone_continuation.priority, EXCLUDED.priority),
        payload_json = COALESCE(clone_continuation.payload_json, '{}'::jsonb) || EXCLUDED.payload_json,
        updated_at_utc = v_now
      RETURNING clone_continuation.id
      INTO v_clone_continuation_job_id;

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'job_id', v_clone_continuation_job_id::text,
        'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
        'continuation_enqueued', true
      );
      v_continuation_jobs := jsonb_build_array(v_continuation_result);
      v_continuation_count := 1;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'CLONE_REBASE_CHUNK';
    ELSE
      v_next_recommended_action := CASE WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'WAIT_FOR_WORKER' ELSE 'READ_PREVIEW_PAGE' END;
    END IF;

    IF COALESCE(v_clone_more_due, false) IS NOT TRUE
       AND v_clone_source_session_id IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_clone_source_session_id IS DISTINCT FROM v_job_row.session_id THEN
      UPDATE public.banking_pay_workbench_sessions AS clone_source_session
      SET status = 'DISCARDED',
          discarded_at_utc = COALESCE(clone_source_session.discarded_at_utc, v_now),
          replacement_session_id = v_job_row.session_id,
          replacement_idempotency_key = COALESCE(
            clone_source_session.replacement_idempotency_key,
            'clone-rebase-complete:' || clone_source_session.id::text || ':replacement:' || v_job_row.session_id::text
          ),
          progress_state = 'DISCARDED',
          progress_json = jsonb_strip_nulls(
            COALESCE(clone_source_session.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'discard_reason', 'SUPERSEDED_BY_COMPLETED_CLONE_REBASE',
              'discarded_by_function', 'pay_workbench_complete_job',
              'replacement_session_id', v_job_row.session_id::text,
              'replacement_linked_at_utc', v_now::text,
              'clone_rebase_completed_by_job_id', p_job_id::text,
              'superseded_by_pay_date', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
              'superseded_by_week_ending_cutoff', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END
            )
          ),
          progress_counter_version = COALESCE(clone_source_session.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE clone_source_session.id = v_clone_source_session_id
        AND clone_source_session.status = 'OPEN'
        AND clone_source_session.discarded_at_utc IS NULL
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.actor_user_id = v_session_row.actor_user_id
        )
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.pay_date IS DISTINCT FROM v_session_row.pay_date
          OR clone_source_session.week_ending_cutoff IS DISTINCT FROM v_session_row.week_ending_cutoff
        );

      GET DIAGNOSTICS v_clone_source_session_retired_count = ROW_COUNT;
    END IF;

    UPDATE public.banking_pay_workbench_sessions AS clone_session_update
    SET progress_state = CASE
          WHEN v_clone_more_due IS TRUE THEN 'CLONE_REBASING'
          WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
          WHEN COALESCE(clone_session_update.scope_pending_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_pending, 0) = 0
           AND COALESCE(clone_session_update.scope_failed_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_failed, 0) = 0
          THEN 'READY'
          ELSE COALESCE(NULLIF(BTRIM(clone_session_update.progress_state), ''), 'REFRESHING_CANDIDATES')
        END,
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(clone_session_update.progress_json, '{}'::jsonb), true)
          || jsonb_build_object(
            'last_clone_rebase_job_id', p_job_id::text,
            'last_clone_rebase_completed_at_utc', v_now::text,
            'last_clone_rebase_more_due', COALESCE(v_clone_more_due, false),
            'last_clone_rebase_copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
            'last_clone_rebase_copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
            'last_clone_rebase_legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
            'last_clone_rebase_source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
            'last_clone_rebase_source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
            'next_recommended_action', v_next_recommended_action
          )
        ),
        progress_counter_version = COALESCE(clone_session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE clone_session_update.id = v_job_row.session_id;

    UPDATE public.banking_pay_workbench_jobs AS update_clone_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_clone_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'clone_rebase_completion_handled', true,
              'clone_rebase_complete', COALESCE(v_clone_complete, false),
              'more_due', COALESCE(v_clone_more_due, false),
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
              'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
              'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_clone_job.id = p_job_id
    RETURNING update_clone_job.*
    INTO v_job_row;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'stage_job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'clone_rebase_completion_handled', true,
      'clone_rebase_complete', COALESCE(v_clone_complete, false),
      'more_due', COALESCE(v_clone_more_due, false),
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
      'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
      'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
      'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
      'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
      'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
      'next_recommended_action', v_next_recommended_action,
      'completed_at_utc', v_now::text
    );
  END IF;

  IF v_duplicate_completion IS NOT TRUE THEN
    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_has_more IS NOT TRUE THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;

      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
        WHERE line_work_ready.session_id = v_job_row.session_id
          AND line_work_ready.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) = 'READY'
      )
      INTO v_ready_line_work_exists;
    END IF;

    IF v_stage_job_type IN (
         'WORKBENCH_CANDIDATE_SOURCE_BUILD',
         'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
         'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
         'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
       )
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_before_continuation.status, 'PENDING')))
      INTO v_scope_status_before_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_before_continuation
      WHERE scope_before_continuation.session_id = v_job_row.session_id
        AND scope_before_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
       AND v_has_more IS TRUE
       AND v_next_cursor IS NOT NULL THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => NULL::uuid,
        p_job_type => 'WORKBENCH_SESSION_SCOPE_SEED',
        p_cursor_json => v_next_cursor,
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'SCOPE_SEED_CURSOR_CONTINUATION',
        p_priority => 40,
        p_limit => v_payload_limit
      );
      v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
      v_next_recommended_action := 'SEED_SCOPE_CHUNK';
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', v_job_row.candidate_id::text,
                  'job_type', v_stage_job_type,
                  'source_build_run_id', v_source_build_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD returned has_more=true without a next cursor; refusing to start line seed early.'
                )::text;
      ELSIF v_has_more IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_CURSOR_CONTINUATION',
          p_priority => 44,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
      ELSIF COALESCE(v_current_source_row_count, 0) > 0 OR COALESCE(v_source_rows_written, 0) > 0 THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_source_seed_cursor_json,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_COMPLETE_SEED_LINE_WORK',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSE
        UPDATE public.banking_pay_workbench_session_scope AS source_empty_scope
        SET status = 'SOURCE_EMPTY',
            seeded = true,
            dirty = false,
            pending_job_id = NULL::uuid,
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE source_empty_scope.session_id = v_job_row.session_id
          AND source_empty_scope.candidate_id = v_job_row.candidate_id;

        DROP TABLE IF EXISTS pg_temp._bpay_complete_job_source_empty_timesheets;
        CREATE TEMP TABLE _bpay_complete_job_source_empty_timesheets ON COMMIT DROP AS
        WITH raw_timesheet_ids(timesheet_id_text) AS (
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
        )
        SELECT DISTINCT LOWER(BTRIM(timesheet_id_text))::uuid AS timesheet_id
        FROM raw_timesheet_ids
        WHERE NULLIF(BTRIM(timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

        SELECT COUNT(*)::integer
        INTO v_source_empty_targeted_timesheet_count
        FROM pg_temp._bpay_complete_job_source_empty_timesheets;

        UPDATE public.banking_pay_workbench_candidate_source_lines AS source_empty_source_line
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(source_empty_source_line.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_source_line.session_id = v_job_row.session_id
          AND source_empty_source_line.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_source_line.status, ''))) IN ('CURRENT', 'READY', 'PENDING', 'DIRTY')
          AND (
            COALESCE(v_source_empty_targeted_timesheet_count, 0) = 0
            OR source_empty_source_line.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_source_row_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_candidate_line_work AS source_empty_line_work
        SET status = 'SKIPPED',
            work_payload_json = jsonb_strip_nulls(
              COALESCE(source_empty_line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
              )
            ),
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE source_empty_line_work.session_id = v_job_row.session_id
          AND source_empty_line_work.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_line_work.status, ''))) IN ('PENDING', 'DIRTY', 'READY')
          AND (
            COALESCE(v_source_empty_targeted_timesheet_count, 0) = 0
            OR source_empty_line_work.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_line_work_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_preview_rows AS source_empty_preview_row
        SET status = 'SUPERSEDED',
            selected = false,
            selection_state = 'SUPERSEDED',
            row_json = jsonb_strip_nulls(
              COALESCE(source_empty_preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'not_payable_reason', 'SOURCE_EMPTY_AFTER_UNAUTHORISE_OR_SOURCE_CHANGE'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_preview_row.session_id = v_job_row.session_id
          AND source_empty_preview_row.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_preview_row.status, ''))) IN ('READY', 'DIRTY', 'PENDING')
          AND (
            COALESCE(v_source_empty_targeted_timesheet_count, 0) = 0
            OR source_empty_preview_row.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_preview_row_count = ROW_COUNT;

        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS source_empty_session_lock
          WHERE source_empty_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(source_empty_session_lock.status, ''))) = 'OPEN'
            AND source_empty_session_lock.discarded_at_utc IS NULL
            AND COALESCE(source_empty_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND source_empty_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND source_empty_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS source_empty_session
            SET scope_ready_count = COALESCE(source_scope_counts.ready_count, 0),
                scope_pending_count = COALESCE(source_scope_counts.pending_count, 0),
                scope_failed_count = COALESCE(source_scope_counts.failed_count, 0),
                progress_state = CASE
                  WHEN COALESCE(source_scope_counts.pending_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
                  WHEN COALESCE(source_scope_counts.failed_count, 0) > 0 THEN 'ERROR'
                  ELSE source_empty_session.progress_state
                END,
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(source_empty_session.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_source_build_empty_candidate_id', v_job_row.candidate_id::text,
                    'last_source_build_empty_at_utc', v_now::text,
                    'last_source_build_empty_job_id', p_job_id::text,
                    'next_recommended_action', 'READ_PREVIEW_PAGE',
                    'terminal_readiness_deferred', true,
                    'terminal_readiness_deferred_to', 'pay_workbench_complete_job',
                    'source_empty_session_progress_locking', 'NOWAIT',
                    'source_empty_session_progress_update_applied', true,
                    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
                    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
                    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
                    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
                  ),
                progress_counter_version = COALESCE(source_empty_session.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            FROM (
              SELECT
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer AS ready_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS failed_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS pending_count
              FROM public.banking_pay_workbench_session_scope AS scope_recount
              WHERE scope_recount.session_id = v_job_row.session_id
            ) AS source_scope_counts
            WHERE source_empty_session.id = v_job_row.session_id
            RETURNING source_empty_session.*
            INTO v_session_row;
          ELSE
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;

        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_CURSOR_CONTINUATION',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSIF COALESCE(v_seeded_count, 0) > 0 OR v_pending_line_work_exists IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_COMPLETE_PROCESS_PENDING',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_PROCESS_CURSOR_CONTINUATION',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;

      IF v_has_more IS NOT TRUE
         AND v_pending_line_work_exists IS NOT TRUE
         AND (COALESCE(v_ready_count_delta, 0) > 0 OR v_ready_line_work_exists IS TRUE) THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_READY_MATERIALISE_PREVIEW_ROWS',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := COALESCE(v_next_recommended_action, 'MATERIALISE_PREVIEW_ROWS_CHUNK');
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'PREVIEW_ROWS_MATERIALISE_CURSOR_CONTINUATION',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      ELSIF COALESCE(v_materialised_count, 0) > 0 THEN
        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    END IF;

    v_continuation_count := jsonb_array_length(COALESCE(v_continuation_jobs, '[]'::jsonb));
    v_continuation_enqueued := v_continuation_count > 0;

    SELECT COUNT(*)::integer
    INTO v_continuation_reused_count
    FROM jsonb_array_elements(COALESCE(v_continuation_jobs, '[]'::jsonb)) AS continuation_items(continuation_item)
    WHERE LOWER(BTRIM(COALESCE(continuation_items.continuation_item->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    IF COALESCE(v_continuation_count, 0) > 0
       AND v_scope_status_before_continuation IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_after_continuation.status, 'PENDING')))
      INTO v_scope_status_after_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_after_continuation
      WHERE scope_after_continuation.session_id = v_job_row.session_id
        AND scope_after_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;

      v_scope_bucket_before_continuation := CASE
        WHEN v_scope_status_before_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_before_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_bucket_after_continuation := CASE
        WHEN v_scope_status_after_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_after_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_continuation_pending_delta := CASE WHEN v_scope_bucket_after_continuation = 'PENDING' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'PENDING' THEN 1 ELSE 0 END;
      v_scope_continuation_ready_delta := CASE WHEN v_scope_bucket_after_continuation = 'READY' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'READY' THEN 1 ELSE 0 END;
      v_scope_continuation_failed_delta := CASE WHEN v_scope_bucket_after_continuation = 'FAILED' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'FAILED' THEN 1 ELSE 0 END;

      IF COALESCE(v_scope_continuation_pending_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_ready_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_failed_delta, 0) <> 0 THEN
        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS continuation_session_lock
          WHERE continuation_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(continuation_session_lock.status, ''))) = 'OPEN'
            AND continuation_session_lock.discarded_at_utc IS NULL
            AND COALESCE(continuation_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND continuation_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND continuation_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS continuation_session_update
            SET scope_pending_count = GREATEST(
                  COALESCE(continuation_session_update.scope_pending_count, 0)
                    + COALESCE(v_scope_continuation_pending_delta, 0),
                  0
                ),
                scope_ready_count = GREATEST(
                  COALESCE(continuation_session_update.scope_ready_count, 0)
                    + COALESCE(v_scope_continuation_ready_delta, 0),
                  0
                ),
                scope_failed_count = GREATEST(
                  COALESCE(continuation_session_update.scope_failed_count, 0)
                    + COALESCE(v_scope_continuation_failed_delta, 0),
                  0
                ),
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(continuation_session_update.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_continuation_scope_old_status', v_scope_status_before_continuation,
                    'last_continuation_scope_new_status', v_scope_status_after_continuation,
                    'last_continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
                    'last_continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
                    'last_continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
                    'last_continuation_scope_counter_adjusted_at_utc', v_now::text,
                    'last_continuation_scope_counter_locking', 'NOWAIT',
                    'last_continuation_scope_counter_lock_skipped', false
                  ),
                progress_counter_version = COALESCE(continuation_session_update.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            WHERE continuation_session_update.id = v_job_row.session_id;

            v_scope_continuation_counter_adjusted := true;
          ELSE
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;
      END IF;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'continuation_enqueued', v_continuation_enqueued,
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    v_completed_at_utc := v_now;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND v_source_change_seq IS NOT NULL
       AND COALESCE(v_has_more, false) IS NOT TRUE
       AND (COALESCE(v_source_rows_written, 0) > 0 OR COALESCE(v_current_source_row_count, 0) > 0) THEN
      BEGIN
        v_source_reconciliation_json := public.pay_workbench_reconcile_successful_source_build(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => COALESCE(v_result_session_version, v_session_row.version),
          p_success_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), '')
          ),
          p_targeted_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_linked_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_recompute_session_progress => true
        );

        v_source_reconciliation_deferred := LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'deferred', 'false')))
          IN ('true', 't', '1', 'yes', 'y', 'on');
        v_source_reconciliation_deferred_reason := CASE
          WHEN v_source_reconciliation_deferred THEN NULLIF(BTRIM(COALESCE(v_source_reconciliation_json->>'reason', '')), '')
          ELSE NULL::text
        END;
        v_source_reconciliation_applied := v_source_reconciliation_deferred IS NOT TRUE
          AND LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'ok', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off');
      EXCEPTION
        WHEN lock_not_available THEN
          v_source_reconciliation_applied := false;
          v_source_reconciliation_deferred := true;
          v_source_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
          v_source_reconciliation_json := jsonb_build_object(
            'ok', true,
            'deferred', true,
            'reason', 'SESSION_LOCK_NOT_AVAILABLE',
            'session_id', v_job_row.session_id::text,
            'candidate_id', v_job_row.candidate_id::text,
            'source_build_run_id', v_source_build_run_id_text,
            'source_change_seq', v_source_change_seq,
            'progress_recomputed', false,
            'counter_reconciled', false,
            'retry_safe', true
          );
      END;
    END IF;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_job_row.candidate_id IS NOT NULL
     AND COALESCE(v_continuation_count, 0) = 0 THEN
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET pending_job_id = NULL::uuid,
        updated_at_utc = v_now
    WHERE scope_update.session_id = v_job_row.session_id
      AND scope_update.candidate_id = v_job_row.candidate_id
      AND scope_update.pending_job_id = p_job_id;

    GET DIAGNOSTICS v_scope_pending_job_cleared_count = ROW_COUNT;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session THEN
    BEGIN
      SELECT session_row.*
      INTO v_session_row
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = v_job_row.session_id
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND COALESCE(session_row.version, 1) = COALESCE(v_session_row.version, 1)
        AND session_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_row.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      IF NOT FOUND THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
      END IF;
    EXCEPTION
      WHEN lock_not_available THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_finalisation_deferred IS NOT TRUE THEN
      IF v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS terminal_scope
        WHERE terminal_scope.session_id = v_job_row.session_id
          AND terminal_scope.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(terminal_scope.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
          AND COALESCE(terminal_scope.dirty, false) IS NOT TRUE
          AND (
            terminal_scope.error_json IS NULL
            OR terminal_scope.error_json = '{}'::jsonb
            OR terminal_scope.error_json = 'null'::jsonb
          )
      )
      INTO v_current_candidate_terminal_success;
    END IF;

    v_finalisation_should_evaluate := (
      COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_pending_count, 0) = 0
      AND COALESCE(v_session_row.scope_failed_count, 0) = 0
      AND COALESCE(v_session_row.line_units_pending, 0) = 0
      AND COALESCE(v_session_row.line_units_failed, 0) = 0
    )
    OR UPPER(BTRIM(COALESCE(v_session_row.progress_state, ''))) IN ('READY', 'READY_EMPTY');

    v_finalisation_actual_precheck_required := v_finalisation_should_evaluate IS NOT TRUE
      AND COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_next_cursor_json, '{}'::jsonb) = '{}'::jsonb
      AND (
        v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
        OR v_current_candidate_terminal_success
      );

    IF v_finalisation_actual_precheck_required THEN
      SELECT
        NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS unresolved_scope
          WHERE unresolved_scope.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_scope.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
              OR COALESCE(unresolved_scope.seeded, false) IS NOT TRUE
              OR COALESCE(unresolved_scope.dirty, false)
              OR NOT (
                unresolved_scope.error_json IS NULL
                OR unresolved_scope.error_json = '{}'::jsonb
                OR unresolved_scope.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS unresolved_line_work
          WHERE unresolved_line_work.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_line_work.status, ''))) NOT IN ('MATERIALISED', 'MATERIALIZED', 'SKIPPED')
              OR NOT (
                unresolved_line_work.error_json IS NULL
                OR unresolved_line_work.error_json = '{}'::jsonb
                OR unresolved_line_work.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_jobs AS active_job
          CROSS JOIN LATERAL (
            SELECT CASE
              WHEN COALESCE(active_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
                THEN (active_job.payload_json->>'session_version')::bigint
              ELSE NULL::bigint
            END AS job_session_version
          ) AS active_job_version
          WHERE active_job.session_id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(active_job.status, ''))) IN ('QUEUED', 'RUNNING')
            AND (
              active_job_version.job_session_version IS NULL
              OR active_job_version.job_session_version >= COALESCE(v_session_row.version, 0)
            )
        )
      INTO v_finalisation_actual_precheck_passed;

      v_finalisation_should_evaluate := COALESCE(v_finalisation_actual_precheck_passed, false);
    END IF;

    IF v_finalisation_should_evaluate THEN
      v_finalisation_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_job_row.session_id,
        p_apply => false,
        p_reason => 'COMPLETE_JOB_FINALISATION_AUTHORITATIVE_COUNTER_SNAPSHOT',
        p_write_progress_json => false
      );

      IF jsonb_typeof(COALESCE(v_finalisation_progress_json, '{}'::jsonb)) <> 'object'
         OR LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR NOT (v_finalisation_progress_json ? 'session_ready') THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID',
                  'job_id', p_job_id::text,
                  'session_id', v_job_row.session_id::text,
                  'progress_result', COALESCE(v_finalisation_progress_json, '{}'::jsonb)
                )::text;
      END IF;

      v_finalisation_evaluated := true;
      v_finalisation_session_ready := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'session_ready', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_for_draft := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_empty := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_empty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_stored_ready_mismatch := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'stored_ready_mismatch', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_draft_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_blocker_counts := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      v_authoritative_scope_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_total_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_total_count')::integer ELSE 0 END;
      v_authoritative_scope_seeded := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_seeded_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_seeded_count')::integer ELSE 0 END;
      v_authoritative_scope_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_ready_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_ready_count')::integer ELSE 0 END;
      v_authoritative_scope_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_pending_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_pending_count')::integer ELSE 0 END;
      v_authoritative_scope_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_failed_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_failed_count')::integer ELSE 0 END;
      v_authoritative_line_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_total', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_total')::integer ELSE 0 END;
      v_authoritative_line_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_pending', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_pending')::integer ELSE 0 END;
      v_authoritative_line_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_ready', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_ready')::integer ELSE 0 END;
      v_authoritative_line_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_failed', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_failed')::integer ELSE 0 END;
      v_authoritative_preview_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'preview_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'preview_row_count')::integer ELSE 0 END;
      v_authoritative_selected_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'selected_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'selected_row_count')::integer ELSE 0 END;
      v_authoritative_section_counts_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;
      v_authoritative_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;

      v_finalisation_counter_reconciliation_required := COALESCE(v_session_row.scope_total_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_total, 0)
        OR COALESCE(v_session_row.scope_seeded_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_seeded, 0)
        OR COALESCE(v_session_row.scope_ready_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_ready, 0)
        OR COALESCE(v_session_row.scope_pending_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_pending, 0)
        OR COALESCE(v_session_row.scope_failed_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_failed, 0)
        OR COALESCE(v_session_row.line_units_total, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_total, 0)
        OR COALESCE(v_session_row.line_units_pending, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_pending, 0)
        OR COALESCE(v_session_row.line_units_ready, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_ready, 0)
        OR COALESCE(v_session_row.line_units_failed, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_failed, 0)
        OR COALESCE(v_session_row.preview_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_preview_row_count, 0)
        OR COALESCE(v_session_row.selected_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_selected_row_count, 0)
        OR COALESCE(v_session_row.section_counts_json, '{}'::jsonb) IS DISTINCT FROM COALESCE(v_authoritative_section_counts_json, '{}'::jsonb);
      v_finalisation_counter_reconciliation_applied := v_duplicate_completion IS NOT TRUE;
      v_finalisation_counter_reconciled := v_finalisation_counter_reconciliation_applied;

      v_finalisation_counter_reconciliation_json := jsonb_build_object(
        'required', v_finalisation_counter_reconciliation_required,
        'applied', v_finalisation_counter_reconciliation_applied,
        'changed', v_finalisation_counter_reconciliation_required AND v_finalisation_counter_reconciliation_applied,
        'reconciled', v_finalisation_counter_reconciled,
        'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
        'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
        'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
        'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
        'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
        'line_units_total', COALESCE(v_authoritative_line_total, 0),
        'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
        'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
        'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
        'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
        'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
        'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb)
      );

      IF v_finalisation_session_ready THEN
        v_final_progress_state := CASE WHEN v_finalisation_ready_empty THEN 'READY_EMPTY' ELSE 'READY' END;
        v_final_phase := 'READY';
        v_final_status_text := 'Payment preview is ready.';
        v_final_next_recommended_action := 'READ_PREVIEW_PAGE';
      ELSE
        v_final_progress_state := UPPER(BTRIM(COALESCE(v_finalisation_progress_json->>'progress_state', '')));
        IF v_final_progress_state IN ('', 'READY', 'READY_EMPTY') THEN
          v_final_progress_state := CASE
            WHEN COALESCE(v_authoritative_scope_failed, 0) > 0
              OR COALESCE(v_authoritative_line_failed, 0) > 0
              OR (COALESCE(v_finalisation_blocker_codes, '[]'::jsonb) ? 'WORKBENCH_JOBS_FAILED') THEN 'ERROR'
            WHEN COALESCE(v_authoritative_line_ready, 0) > 0 THEN 'MATERIALISING_PREVIEW_ROWS'
            WHEN COALESCE(v_authoritative_line_pending, 0) > 0 THEN 'PROCESSING_LINE_WORK'
            ELSE 'REFRESHING_CANDIDATES'
          END;
        END IF;
        v_final_phase := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'phase'), ''), 'REFRESHING_CANDIDATES');
        v_final_status_text := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'status_text'), ''), 'Preparing payment preview.');
        v_final_next_recommended_action := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'next_recommended_action'), ''), 'WAIT_FOR_WORKER');
      END IF;

      IF v_duplicate_completion IS NOT TRUE THEN
        UPDATE public.banking_pay_workbench_sessions AS session_update
        SET scope_total_count = GREATEST(COALESCE(v_authoritative_scope_total, 0), 0),
          scope_seeded_count = GREATEST(COALESCE(v_authoritative_scope_seeded, 0), 0),
          scope_ready_count = GREATEST(COALESCE(v_authoritative_scope_ready, 0), 0),
          scope_pending_count = GREATEST(COALESCE(v_authoritative_scope_pending, 0), 0),
          scope_failed_count = GREATEST(COALESCE(v_authoritative_scope_failed, 0), 0),
          line_units_total = GREATEST(COALESCE(v_authoritative_line_total, 0), 0),
          line_units_pending = GREATEST(COALESCE(v_authoritative_line_pending, 0), 0),
          line_units_ready = GREATEST(COALESCE(v_authoritative_line_ready, 0), 0),
          line_units_failed = GREATEST(COALESCE(v_authoritative_line_failed, 0), 0),
          preview_row_count = GREATEST(COALESCE(v_authoritative_preview_row_count, 0), 0),
          selected_row_count = GREATEST(COALESCE(v_authoritative_selected_row_count, 0), 0),
          section_counts_json = COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
          candidate_sample_rows_json = COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
          progress_state = v_final_progress_state,
          progress_json = public.pay_workbench_session_compact_progress_json(
            jsonb_strip_nulls(
              jsonb_build_object(
              'ok', true,
              'server_utc', v_now,
              'updated_at_utc', v_now,
              'phase', v_final_phase,
              'status_text', v_final_status_text,
              'next_recommended_action', v_final_next_recommended_action,
              'progress_state', v_final_progress_state,
              'ready', v_finalisation_session_ready,
              'ready_flag', v_finalisation_session_ready,
              'session_ready', v_finalisation_session_ready,
              'ready_for_draft', v_finalisation_ready_for_draft,
              'can_create_draft', v_finalisation_ready_for_draft,
              'ready_empty', v_finalisation_ready_empty,
              'preview_ready', v_finalisation_session_ready,
              'work_queued', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'work_queued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'still_running', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'still_running', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'pending_refresh', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'pending_refresh', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_deferred', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_deferred', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'authoritative_session_ready', v_finalisation_session_ready,
              'authoritative_ready_for_draft', v_finalisation_ready_for_draft,
              'authoritative_ready_empty', v_finalisation_ready_empty,
              'authoritative_progress_state', v_final_progress_state,
              'session_blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
              'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_counts', COALESCE(v_finalisation_blocker_counts, '{}'::jsonb),
              'stored_ready_mismatch', v_finalisation_stored_ready_mismatch
            )
            || jsonb_build_object(
              'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
              'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
              'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
              'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
              'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
              'line_units_total', COALESCE(v_authoritative_line_total, 0),
              'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
              'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
              'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
              'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
              'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
              'selected_eligible_ready_row_count', CASE
                WHEN COALESCE(v_finalisation_progress_json->>'selected_eligible_ready_row_count', '') ~ '^[0-9]+$'
                  THEN (v_finalisation_progress_json->>'selected_eligible_ready_row_count')::integer
                ELSE COALESCE(v_authoritative_selected_row_count, 0)
              END,
              'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
              'candidate_sample_rows_json', COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
              'candidate_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'candidate_counts') = 'object'
                  THEN v_finalisation_progress_json->'candidate_counts'
                ELSE '{}'::jsonb
              END,
              'line_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'line_counts') = 'object'
                  THEN v_finalisation_progress_json->'line_counts'
                ELSE '{}'::jsonb
              END,
              'job_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'job_counts') = 'object'
                  THEN v_finalisation_progress_json->'job_counts'
                ELSE '{}'::jsonb
              END,
              'source_build_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'source_build_counts') = 'object'
                  THEN v_finalisation_progress_json->'source_build_counts'
                ELSE '{}'::jsonb
              END,
              'pending_job_ids_json', CASE
                WHEN v_finalisation_session_ready THEN '[]'::jsonb
                WHEN jsonb_typeof(v_finalisation_progress_json->'pending_job_ids_json') = 'array'
                  THEN v_finalisation_progress_json->'pending_job_ids_json'
                ELSE '[]'::jsonb
              END,
              'session_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'session_blockers') = 'array'
                  THEN v_finalisation_progress_json->'session_blockers'
                ELSE '[]'::jsonb
              END,
              'draft_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'draft_blockers') = 'array'
                  THEN v_finalisation_progress_json->'draft_blockers'
                ELSE '[]'::jsonb
              END
            )
            || jsonb_build_object(
              'finalisation_evaluated', true,
              'finalisation_evaluated_at_utc', v_now::text,
              'finalisation_source_job_id', p_job_id::text,
              'finalisation_source_job_type', v_stage_job_type,
              'terminal_readiness_deferred', v_finalisation_session_ready IS NOT TRUE,
              'finalisation_pending', v_finalisation_session_ready IS NOT TRUE,
              'finalised_at_utc', CASE WHEN v_finalisation_session_ready THEN v_now::text ELSE NULL::text END,
              'counter_reconciled', v_finalisation_counter_reconciled,
              'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb)
            )
            ),
            true
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
        WHERE session_update.id = v_job_row.session_id
        RETURNING session_update.*
        INTO v_session_row;
      END IF;
    END IF;
    END IF;
  END IF;

  v_completion_finalisation_json := jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason,
    'evaluated_at_utc', CASE WHEN v_finalisation_evaluated THEN v_now::text ELSE NULL::text END
  );

  IF v_duplicate_completion IS NOT TRUE THEN
    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'completion_json', COALESCE(update_job.payload_json->'completion_json', '{}'::jsonb)
              || v_completion_finalisation_json
          ),
        updated_at_utc = v_now
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      p_job_id::text,
      'SUCCEEDED',
      NULL,
      jsonb_build_object(
        'id', p_job_id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
        'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
        'attempt_count', v_job_row.attempt_count,
        'completed_at_utc', v_job_row.completed_at_utc,
        'continuation_count', COALESCE(v_continuation_count, 0),
        'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
        'next_recommended_action', v_next_recommended_action
      )
      || jsonb_build_object(
        'has_more', v_has_more,
        'next_cursor_present', v_next_cursor IS NOT NULL,
        'seeded_count', COALESCE(v_seeded_count, 0),
        'source_rows_written', COALESCE(v_source_rows_written, 0),
        'current_source_row_count', COALESCE(v_current_source_row_count, 0),
        'source_build_run_id', v_source_build_run_id_text,
        'source_change_seq', v_source_change_seq,
        'new_scope_count', COALESCE(v_new_scope_count, 0),
        'processed_count', COALESCE(v_processed_count, 0),
        'ready_count_delta', COALESCE(v_ready_count_delta, 0),
        'materialised_count', COALESCE(v_materialised_count, 0),
        'error_count', COALESCE(v_error_count, 0),
        'finalisation', v_completion_finalisation_json,
        'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
        'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
        'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason
      ),
      'WORKBENCH_JOB_COMPLETED',
      NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', 'SUCCEEDED',
    'completed_at_utc', COALESCE(v_completed_at_utc, v_job_row.completed_at_utc, v_now),
    'result_json', v_result_json,
    'continuation_enqueued', v_continuation_enqueued,
    'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
    'continuation_count', COALESCE(v_continuation_count, 0),
    'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
    'next_recommended_action', v_next_recommended_action,
    'has_more', v_has_more,
    'next_cursor_present', v_next_cursor IS NOT NULL,
    'line_work_pending_after_completion', CASE WHEN v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN v_pending_line_work_exists ELSE NULL END,
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'stage_job_type', v_stage_job_type,
    'duplicate_completion', v_duplicate_completion,
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb)
  )
  || jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_fail_job(p_job_id uuid, p_error_json jsonb, p_retry_after_seconds integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_type text;
  v_canonical_job_type text := NULL::text;
  v_attempt_count integer;
  v_max_attempts integer;
  v_retry_after_seconds integer;
  v_next_run_at_utc timestamptz;
  v_new_status text;
  v_failed_at_utc timestamptz;
  v_job_snapshot_run_id uuid := NULL::uuid;
  v_job_session_id uuid := NULL::uuid;
  v_job_candidate_id uuid := NULL::uuid;
  v_job_dedupe_key text := NULL;
  v_job_payload_json jsonb := '{}'::jsonb;
  v_job_source_change_seq bigint := 0;
  v_job_session_version bigint := 0;
  v_live_candidate_change_seq bigint := 0;
  v_snapshot_state_status text := NULL;
  v_snapshot_state_source_change_seq bigint := 0;
  v_current_session_status text := NULL;
  v_current_session_version bigint := 0;
  v_current_session_snapshot_run_id uuid := NULL::uuid;
  v_session_candidate_status text := NULL;
  v_session_candidate_source_change_seq bigint := 0;
  v_session_candidate_session_version bigint := 0;
  v_other_active_job_id uuid := NULL::uuid;
  v_completed_equivalent_job_id uuid := NULL::uuid;
  v_is_obsolete boolean := false;
  v_obsolete_reason text := NULL;
  v_error_code text := UPPER(COALESCE(p_error_json->>'code', ''));
  v_error_message text := UPPER(COALESCE(p_error_json->>'message', ''));
  v_is_statement_timeout boolean := false;
  v_is_no_change_loop boolean := false;
  v_failed_line_work_count integer := 0;
  v_failed_source_row_count integer := 0;
  v_source_build_run_id_text text := NULL::text;
  v_invalid_source_build_without_run_id boolean := false;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  IF p_error_json IS NULL THEN
    RAISE EXCEPTION 'error_json is required';
  END IF;

  SELECT j.job_type,
         j.attempt_count,
         j.max_attempts,
         j.snapshot_run_id,
         j.session_id,
         j.candidate_id,
         j.dedupe_key,
         COALESCE(j.payload_json, '{}'::jsonb)
  INTO v_job_type,
       v_attempt_count,
       v_max_attempts,
       v_job_snapshot_run_id,
       v_job_session_id,
       v_job_candidate_id,
       v_job_dedupe_key,
       v_job_payload_json
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  v_job_source_change_seq := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'source_change_seq')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );
  v_job_session_version := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'session_version', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'session_version')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );

  v_canonical_job_type := CASE
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
      THEN 'WORKBENCH_SESSION_SCOPE_SEED'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
      THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE')
      THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
      THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
      THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    ELSE UPPER(BTRIM(COALESCE(v_job_type, '')))
  END;

  v_is_statement_timeout := (
    v_error_code = '57014'
    OR v_error_message LIKE '%STATEMENT TIMEOUT%'
    OR v_error_message LIKE '%CANCELING STATEMENT DUE TO STATEMENT TIMEOUT%'
  );

  v_is_no_change_loop := (
    v_error_code IN ('SNAPSHOT_ALREADY_CURRENT', 'ALREADY_CURRENT', 'NO_EFFECTIVE_CHANGE', 'PAYEE_READINESS_NO_EFFECTIVE_CHANGE', 'STALE_SESSION_VERSION', 'SESSION_DISCARDED')
    OR v_error_message LIKE '%ALREADY CURRENT%'
    OR v_error_message LIKE '%NO EFFECTIVE CHANGE%'
    OR v_error_message LIKE '%STALE SESSION VERSION%'
    OR v_error_message LIKE '%SESSION DISCARDED%'
  );

  IF v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      v_job_payload_json->>'source_build_run_id',
      v_job_payload_json#>>'{source_build,source_build_run_id}',
      v_job_payload_json#>>'{source_build,run_id}',
      v_job_payload_json#>>'{cursor,source_build_run_id}',
      v_job_payload_json#>>'{cursor_json,source_build_run_id}',
      v_job_payload_json#>>'{result_json,source_build_run_id}',
      ''
    )), '');

    IF v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_build_run_id_text := NULL::text;
      v_invalid_source_build_without_run_id := true;
    END IF;
  END IF;

  IF v_job_type = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
    IF v_job_snapshot_run_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
      INTO v_snapshot_state_status, v_snapshot_state_source_change_seq
      FROM public.banking_pay_snapshot_candidate_state AS snap
      WHERE snap.snapshot_run_id = v_job_snapshot_run_id
        AND snap.candidate_id = v_job_candidate_id
      LIMIT 1;

      SELECT j.id
      INTO v_other_active_job_id
      FROM public.banking_pay_workbench_jobs AS j
      WHERE j.id <> p_job_id
        AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
        AND j.snapshot_run_id = v_job_snapshot_run_id
        AND j.candidate_id = v_job_candidate_id
        AND j.status IN ('QUEUED', 'RUNNING')
        AND COALESCE(
              CASE
                WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                  THEN (j.payload_json->>'source_change_seq')::bigint
                ELSE 0::bigint
              END,
              0::bigint
            ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
      ORDER BY COALESCE(
                 CASE
                   WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                     THEN (j.payload_json->>'source_change_seq')::bigint
                   ELSE 0::bigint
                 END,
                 0::bigint
               ) DESC,
               j.updated_at_utc DESC NULLS LAST,
               j.created_at_utc DESC NULLS LAST,
               j.id DESC
      LIMIT 1;

      IF v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      ELSIF v_other_active_job_id IS NOT NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
      ELSIF UPPER(COALESCE(v_snapshot_state_status, '')) = 'READY'
            AND v_snapshot_state_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
      END IF;
    END IF;
  ELSIF v_job_type = 'SESSION_CANDIDATE_RECOMPUTE' THEN
    IF v_job_session_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SESSION_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
      INTO v_current_session_status, v_current_session_version
      FROM public.banking_pay_workbench_sessions AS ws
      WHERE ws.id = v_job_session_id
      LIMIT 1;

      IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_NOT_OPEN';
      ELSE
        SELECT COALESCE(scs.status, NULL),
               COALESCE(scs.source_change_seq, 0),
               COALESCE(scs.session_version, 0)
        INTO v_session_candidate_status,
             v_session_candidate_source_change_seq,
             v_session_candidate_session_version
        FROM public.banking_pay_workbench_session_candidate_state AS scs
        WHERE scs.session_id = v_job_session_id
          AND scs.candidate_id = v_job_candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
          AND j.session_id = v_job_session_id
          AND j.candidate_id = v_job_candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'session_version')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= v_current_session_version
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'session_version')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        ELSIF v_other_active_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_session_candidate_status, '')) = 'READY'
              AND v_session_candidate_session_version >= v_current_session_version
              AND v_session_candidate_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_ALREADY_CURRENT';
        END IF;
      END IF;
    END IF;
  ELSIF v_canonical_job_type IN (
    'WORKBENCH_SESSION_SCOPE_SEED',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
  ) THEN
    IF v_job_session_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_WORKBENCH_SESSION_CONTEXT';
    ELSE
      SELECT COALESCE(workbench_session.status, NULL),
             COALESCE(workbench_session.version, 0),
             workbench_session.source_snapshot_run_id
      INTO v_current_session_status,
           v_current_session_version,
           v_current_session_snapshot_run_id
      FROM public.banking_pay_workbench_sessions AS workbench_session
      WHERE workbench_session.id = v_job_session_id
      LIMIT 1;

      IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_NOT_OPEN';
      ELSIF v_job_snapshot_run_id IS NOT NULL
            AND v_current_session_snapshot_run_id IS DISTINCT FROM v_job_snapshot_run_id THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_SNAPSHOT_MISMATCH';
      ELSIF v_job_session_version > 0
            AND v_current_session_version > v_job_session_version THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
      END IF;
    END IF;

    IF v_is_obsolete IS NOT TRUE
       AND v_canonical_job_type IN (
         'WORKBENCH_CANDIDATE_SOURCE_BUILD',
         'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
         'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
         'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
       ) THEN
      IF v_job_candidate_id IS NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'INVALID_WORKBENCH_CANDIDATE_CONTEXT';
      ELSE
        SELECT COALESCE(scope_row.status, NULL)
        INTO v_session_candidate_status
        FROM public.banking_pay_workbench_session_scope AS scope_row
        WHERE scope_row.session_id = v_job_session_id
          AND scope_row.candidate_id = v_job_candidate_id
        LIMIT 1;

        IF v_session_candidate_status IS NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'CANDIDATE_NOT_IN_SESSION_SCOPE';
        END IF;
      END IF;
    END IF;

    IF v_is_obsolete IS NOT TRUE
       AND v_job_candidate_id IS NOT NULL
       AND v_job_source_change_seq > 0 THEN
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      IF COALESCE(v_live_candidate_change_seq, 0) > COALESCE(v_job_source_change_seq, 0) THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      END IF;
    END IF;
  ELSIF v_job_type = 'PAYEE_READINESS_ENSURE' THEN
    IF v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_READINESS_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      IF v_job_session_id IS NOT NULL THEN
        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_current_session_status, v_current_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_job_session_id
        LIMIT 1;

        IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSIF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        END IF;
      END IF;

      IF NOT v_is_obsolete AND v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      END IF;

      IF NOT v_is_obsolete THEN
        SELECT j.id
        INTO v_completed_equivalent_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'PAYEE_READINESS_ENSURE'
          AND j.dedupe_key = v_job_dedupe_key
          AND j.completed_at_utc IS NOT NULL
          AND j.failed_at_utc IS NULL
        ORDER BY j.completed_at_utc DESC, j.id DESC
        LIMIT 1;

        IF v_completed_equivalent_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
        ELSE
          SELECT j.id
          INTO v_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> p_job_id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_job_dedupe_key
            AND j.status IN ('QUEUED', 'RUNNING')
          ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
          LIMIT 1;

          IF v_other_active_job_id IS NOT NULL THEN
            v_is_obsolete := true;
            v_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_is_statement_timeout THEN
    v_retry_after_seconds := GREATEST(
      300,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(COALESCE(v_attempt_count, 1), 1) * 300),
        14400
      )
    );
  ELSE
    v_retry_after_seconds := GREATEST(
      5,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(30, LEAST(COALESCE(v_attempt_count, 1) * 60, 3600))),
        86400
      )
    );
  END IF;

  IF v_is_obsolete
     OR v_is_no_change_loop
     OR (
       v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_invalid_source_build_without_run_id IS TRUE
     )
     OR COALESCE(v_attempt_count, 0) >= COALESCE(v_max_attempts, 8) THEN
    v_new_status := CASE
      WHEN v_canonical_job_type IN (
        'WORKBENCH_SESSION_SCOPE_SEED',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
        'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      ) THEN 'FAILED'
      ELSE 'DEAD'
    END;
    v_next_run_at_utc := NULL;
  ELSE
    v_new_status := 'QUEUED';
    v_next_run_at_utc := v_now + make_interval(secs => v_retry_after_seconds);
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS j
  SET status = v_new_status,
      run_at_utc = COALESCE(v_next_run_at_utc, j.run_at_utc),
      updated_at_utc = v_now,
      started_at_utc = CASE WHEN v_new_status = 'QUEUED' THEN NULL ELSE j.started_at_utc END,
      completed_at_utc = NULL,
      failed_at_utc = CASE WHEN v_new_status = 'QUEUED' THEN NULL ELSE v_now END,
      last_error_json = p_error_json,
      payload_json = jsonb_strip_nulls(
        COALESCE(j.payload_json, '{}'::jsonb)
        || jsonb_build_object('last_failure_json', p_error_json)
        || CASE
          WHEN v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND v_invalid_source_build_without_run_id IS TRUE THEN
            jsonb_build_object(
              'invalid_source_build_without_run_id_failed_closed', true,
              'invalid_source_build_without_run_id_non_blocking', true,
              'non_blocking_terminal_failure', true,
              'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'non_blocking_terminal_failure_at_utc', v_now::text,
              'source_build_run_id_required', true,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          ELSE '{}'::jsonb
        END
      )
  WHERE j.id = p_job_id
  RETURNING j.failed_at_utc
  INTO v_failed_at_utc;

  IF v_new_status = 'FAILED'
     AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_is_obsolete IS NOT TRUE
     AND v_job_session_id IS NOT NULL
     AND v_job_candidate_id IS NOT NULL THEN
    IF v_source_build_run_id_text IS NULL THEN
      v_failed_source_row_count := 0;

      PERFORM public._audit_insert(
        'banking_pay_workbench_candidate_source_lines',
        v_job_candidate_id::text,
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'old_status', 'CURRENT_OR_DIRTY',
          'reason', 'SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'affected_row_count', 0,
          'source_rows_marked_error_count', 0,
          'new_status', 'UNCHANGED',
          'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
        NULL
      );

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_scope',
        v_job_candidate_id::text,
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'reason', 'SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'scope_status_changed', false,
          'session_progress_changed', false,
          'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
        NULL
      );
    ELSE
      IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NOT NULL THEN
        WITH failed_source_rows AS (
          UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
          SET status = 'ERROR',
              source_row_json = COALESCE(source_line.source_row_json, '{}'::jsonb)
                || jsonb_build_object(
                  'source_build_error', jsonb_build_object(
                    'code', 'WORKBENCH_SOURCE_BUILD_JOB_FAILED',
                    'job_id', p_job_id::text,
                    'job_type', v_job_type,
                    'canonical_job_type', v_canonical_job_type,
                    'source_build_run_id', v_source_build_run_id_text,
                    'failed_at_utc', v_now::text,
                    'job_error_json', COALESCE(p_error_json, '{}'::jsonb),
                    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                  )
                ),
              updated_at_utc = v_now
          WHERE source_line.session_id = v_job_session_id
            AND source_line.candidate_id = v_job_candidate_id
            AND source_line.status IN ('CURRENT', 'DIRTY')
            AND source_line.source_build_run_id::text = v_source_build_run_id_text
          RETURNING source_line.id
        )
        SELECT COUNT(*)::integer
        INTO v_failed_source_row_count
        FROM failed_source_rows;
      END IF;

      UPDATE public.banking_pay_workbench_session_scope AS source_scope_row
      SET status = 'SOURCE_BUILD_ERROR',
          dirty = true,
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_SOURCE_BUILD_JOB_FAILED',
            'message', 'Candidate source build job failed terminally.',
            'job_id', p_job_id::text,
            'job_type', v_job_type,
            'canonical_job_type', v_canonical_job_type,
            'source_build_run_id', v_source_build_run_id_text,
            'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0),
            'job_error_json', COALESCE(p_error_json, '{}'::jsonb)
          ),
          updated_at_utc = v_now
      WHERE source_scope_row.session_id = v_job_session_id
        AND source_scope_row.candidate_id = v_job_candidate_id;

      UPDATE public.banking_pay_workbench_sessions AS source_session_row
      SET progress_state = 'ERROR',
          progress_json = COALESCE(source_session_row.progress_json, '{}'::jsonb) || jsonb_build_object(
            'last_source_build_failure_at_utc', v_now::text,
            'last_source_build_failure_job_id', p_job_id::text,
            'last_source_build_failure_code', COALESCE(NULLIF(BTRIM(p_error_json->>'code'), ''), 'WORKBENCH_SOURCE_BUILD_JOB_FAILED'),
            'last_source_build_failure_source_build_run_id', v_source_build_run_id_text,
            'last_source_build_source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
          ),
          progress_counter_version = COALESCE(source_session_row.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE source_session_row.id = v_job_session_id;
    END IF;
  END IF;

  IF v_new_status = 'FAILED'
     AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
     AND v_is_obsolete IS NOT TRUE
     AND v_job_session_id IS NOT NULL
     AND v_job_candidate_id IS NOT NULL THEN
    WITH failed_lines AS (
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET status = 'ERROR',
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED',
            'message', 'Candidate line work was marked failed because its process job failed terminally.',
            'job_id', p_job_id::text,
            'job_type', v_job_type,
            'session_id', v_job_session_id::text,
            'candidate_id', v_job_candidate_id::text,
            'job_error_json', COALESCE(p_error_json, '{}'::jsonb)
          ),
          updated_at_utc = v_now
      WHERE line_work.session_id = v_job_session_id
        AND line_work.candidate_id = v_job_candidate_id
        AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
      RETURNING line_work.id
    )
    SELECT COUNT(*)::integer
    INTO v_failed_line_work_count
    FROM failed_lines;

    IF COALESCE(v_failed_line_work_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_session_scope AS scope_row
      SET status = 'ERROR',
          dirty = true,
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED',
            'message', 'Candidate line work process job failed terminally.',
            'job_id', p_job_id::text,
            'line_work_failed_count', v_failed_line_work_count,
            'job_error_json', COALESCE(p_error_json, '{}'::jsonb)
          ),
          updated_at_utc = v_now
      WHERE scope_row.session_id = v_job_session_id
        AND scope_row.candidate_id = v_job_candidate_id;

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_failed_line_work_count, 0), 0),
          line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_failed_line_work_count, 0), 0),
          progress_state = 'ERROR',
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb) || jsonb_build_object(
            'last_line_process_failure_at_utc', v_now::text,
            'last_line_process_failure_job_id', p_job_id::text,
            'last_line_process_failure_code', COALESCE(NULLIF(BTRIM(p_error_json->>'code'), ''), 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED'),
            'last_line_process_failure_count', v_failed_line_work_count
          ),
          progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_row.id = v_job_session_id;
    END IF;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    CASE WHEN v_new_status = 'QUEUED' THEN 'REQUEUED' WHEN v_new_status = 'FAILED' THEN 'FAILED' ELSE 'DEAD' END,
    NULL,
    jsonb_build_object(
      'id', p_job_id::text,
      'job_type', v_job_type,
      'canonical_job_type', v_canonical_job_type,
      'status', v_new_status,
      'attempt_count', v_attempt_count,
      'max_attempts', v_max_attempts,
      'run_at_utc', v_next_run_at_utc,
      'failed_at_utc', v_failed_at_utc,
      'last_error_json', p_error_json,
      'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
      'obsolete', v_is_obsolete,
      'obsolete_reason', v_obsolete_reason,
      'statement_timeout', v_is_statement_timeout,
      'deterministic_no_change_loop', v_is_no_change_loop,
      'source_build_run_id', v_source_build_run_id_text,
      'invalid_source_build_without_run_id_failed_closed', COALESCE(v_invalid_source_build_without_run_id, false),
      'invalid_source_build_without_run_id_non_blocking', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
      'non_blocking_terminal_failure', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
      'line_work_failed_count', COALESCE(v_failed_line_work_count, 0),
      'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
    ),
    CASE
      WHEN v_new_status = 'QUEUED' THEN 'WORKBENCH_JOB_REQUEUED'
      WHEN v_new_status = 'FAILED'
           AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
           AND v_invalid_source_build_without_run_id IS TRUE THEN 'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED'
      WHEN v_new_status = 'FAILED' THEN 'WORKBENCH_JOB_FAILED'
      ELSE 'WORKBENCH_JOB_DEAD'
    END,
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', v_new_status,
    'canonical_job_type', v_canonical_job_type,
    'attempt_count', v_attempt_count,
    'max_attempts', v_max_attempts,
    'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
    'next_run_at_utc', v_next_run_at_utc,
    'failed_at_utc', v_failed_at_utc,
    'error_json', p_error_json,
    'obsolete', v_is_obsolete,
    'obsolete_reason', v_obsolete_reason,
    'statement_timeout', v_is_statement_timeout,
    'deterministic_no_change_loop', v_is_no_change_loop,
    'source_build_run_id', v_source_build_run_id_text,
    'invalid_source_build_without_run_id_failed_closed', COALESCE(v_invalid_source_build_without_run_id, false),
    'invalid_source_build_without_run_id_non_blocking', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
    'non_blocking_terminal_failure', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
    'line_work_failed_count', COALESCE(v_failed_line_work_count, 0),
    'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_enqueue_scope(
  p_snapshot_run_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_run_pay_date date;
  v_run_week_ending_cutoff date;
  v_run_pay_week_start date;
  v_run_eligibility_from_date date;
  v_run_eligibility_to_date date;
  v_run_status text := NULL::text;
  v_run_failed_at_utc timestamptz := NULL::timestamptz;
  v_candidate_id_value uuid;
  v_enqueued_count integer := 0;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_scope_payload_json jsonb := '{}'::jsonb;
  v_scope_context_json jsonb := '{}'::jsonb;
  v_page_candidate_ids jsonb := '[]'::jsonb;
  v_next_cursor jsonb := NULL::jsonb;
  v_has_more boolean := false;
  v_limit integer := 100;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  SELECT snapshot_run.pay_date,
         snapshot_run.week_ending_cutoff,
         snapshot_run.pay_week_start,
         snapshot_run.eligibility_from_date,
         snapshot_run.eligibility_to_date,
         snapshot_run.status,
         snapshot_run.failed_at_utc
  INTO v_run_pay_date,
       v_run_week_ending_cutoff,
       v_run_pay_week_start,
       v_run_eligibility_from_date,
       v_run_eligibility_to_date,
       v_run_status,
       v_run_failed_at_utc
  FROM public.banking_pay_snapshot_runs AS snapshot_run
  WHERE snapshot_run.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  IF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSE
    v_limit := 100;
  END IF;

  IF p_candidate_id IS NULL AND p_client_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'pay_date', v_run_pay_date::text,
      'week_ending_cutoff', v_run_week_ending_cutoff::text,
      'pay_week_start', v_run_pay_week_start::text,
      'eligibility_from_date', v_run_eligibility_from_date::text,
      'eligibility_to_date', v_run_eligibility_to_date::text,
      'candidate_filter_id', NULL::text,
      'client_filter_id', NULL::text,
      'enqueued_count', 0,
      'candidate_count', 0,
      'no_op', true,
      'reason', 'FULL_SCOPE_FORBIDDEN_USE_PAGED_SCOPE',
      'run_status', v_run_status,
      'run_failed_at_utc', v_run_failed_at_utc,
      'force_seed', false
    );
  END IF;

  v_scope_payload_json := public._pay_workbench_merge_targeted_scope_payload(
    v_payload_json,
    jsonb_build_object(
      'scope_pay_date', v_run_pay_date::text,
      'scope_week_ending_cutoff', v_run_week_ending_cutoff::text,
      'scope_candidate_filter_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'scope_client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'preview_context_mode', 'PAGE',
      'scope_limit', v_limit,
      'scope_cursor', COALESCE(v_payload_json->'scope_cursor', v_payload_json->'cursor', NULL::jsonb)
    )
  );

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => p_snapshot_run_id,
      p_candidate_id => p_candidate_id,
      p_reason => 'SNAPSHOT_SCOPE_WARMUP',
      p_actor_user_id => p_actor_user_id,
      p_payload_json => v_scope_payload_json
    );

    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'pay_date', v_run_pay_date::text,
      'week_ending_cutoff', v_run_week_ending_cutoff::text,
      'pay_week_start', v_run_pay_week_start::text,
      'eligibility_from_date', v_run_eligibility_from_date::text,
      'eligibility_to_date', v_run_eligibility_to_date::text,
      'candidate_filter_id', p_candidate_id::text,
      'client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'enqueued_count', 1,
      'candidate_count', 1,
      'next_cursor', NULL::jsonb,
      'has_more', false,
      'no_op', false,
      'force_seed', false
    );
  END IF;

  v_scope_context_json := public.pay_preview_build_context(
    p_pay_date => v_run_pay_date,
    p_week_ending_cutoff => v_run_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => NULL::uuid,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_scope_payload_json
  );

  v_page_candidate_ids := CASE
    WHEN jsonb_typeof(v_scope_context_json->'candidate_ids') = 'array' THEN COALESCE(v_scope_context_json->'candidate_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_next_cursor := COALESCE(v_scope_context_json->'next_cursor_json', v_scope_context_json->'next_cursor', NULL::jsonb);
  v_has_more := COALESCE(NULLIF(v_scope_context_json->>'has_more', '')::boolean, false);

  FOR v_candidate_id_value IN
    SELECT DISTINCT NULLIF(BTRIM(candidate_id_values.value), '')::uuid AS candidate_id
    FROM jsonb_array_elements_text(v_page_candidate_ids) AS candidate_id_values(value)
    WHERE NULLIF(BTRIM(candidate_id_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY candidate_id
  LOOP
    PERFORM public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => p_snapshot_run_id,
      p_candidate_id => v_candidate_id_value,
      p_reason => 'SNAPSHOT_SCOPE_WARMUP',
      p_actor_user_id => p_actor_user_id,
      p_payload_json => v_scope_payload_json
    );

    v_enqueued_count := v_enqueued_count + 1;
    v_candidate_ids := v_candidate_ids || jsonb_build_array(v_candidate_id_value::text);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', p_snapshot_run_id::text,
    'pay_date', v_run_pay_date::text,
    'week_ending_cutoff', v_run_week_ending_cutoff::text,
    'pay_week_start', v_run_pay_week_start::text,
    'eligibility_from_date', v_run_eligibility_from_date::text,
    'eligibility_to_date', v_run_eligibility_to_date::text,
    'candidate_filter_id', NULL::text,
    'client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
    'enqueued_count', COALESCE(v_enqueued_count, 0),
    'candidate_count', COALESCE(v_enqueued_count, 0),
    'candidate_ids_are_page_only', true,
    'limit', v_limit,
    'next_cursor', v_next_cursor,
    'has_more', COALESCE(v_has_more, false),
    'no_op', false,
    'force_seed', false
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_preview_build_context(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_preview_decisions_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
  v_effective_week_ending_cutoff date := COALESCE(p_week_ending_cutoff, DATE '9999-12-31');
  v_pay_week_start date;
  v_pay_eligibility_months_back integer := 6;
  v_pay_eligibility_weeks_ahead integer := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_last_candidate_id uuid := NULL::uuid;
  v_page_limit integer := 100;
  v_preview_decisions_root jsonb := '{}'::jsonb;
  v_preview_case_resolutions jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL::text;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_raw jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_raw jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_requested jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_requested jsonb := '[]'::jsonb;
  v_timesheet_rotation_scope_json jsonb := '[]'::jsonb;
  v_targeted_timesheet_input_count integer := 0;
  v_linked_timesheet_input_count integer := 0;
  v_distinct_timesheet_scope_input_count integer := 0;
  v_context_mode text := 'SUMMARY';
  v_effective_candidate_id uuid := p_candidate_id;
  v_effective_client_id uuid := p_client_id;
  v_full_compat_requested boolean := false;
  v_full_compat_downgraded boolean := false;
  v_source_build_internal_requested boolean := false;
  v_overpayment_sync_internal_requested boolean := false;
  v_internal_reconciliation_flags_requested boolean := false;
  v_internal_reconciliation_authorised boolean := false;
  v_source_build_authority_token text := NULL::text;
  v_current_overpayment_sync_authority_token text := NULL::text;
  v_lifecycle_mutation_context text := NULL::text;
  v_lifecycle_reconciliation_mode boolean := false;
  v_historic_metadata_allowed boolean := false;
  v_signed_finance_reconciliation boolean := false;
  v_exclude_lifecycle_ineligible_current_payability boolean := false;
  v_authoritative_timesheet_scope boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('PREVIEW_PROGRESS');

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PREVIEW_BUILD_CONTEXT_PAY_DATE_REQUIRED')::text;
  END IF;

  IF to_regclass('public.settings_finance_windows') IS NULL THEN
    RAISE EXCEPTION 'settings_finance_windows missing';
  END IF;

  v_pay_week_start := public._pay_week_start_monday(p_pay_date);

  SELECT
    finance_window.vat_rate_pct,
    finance_window.erni_pct
  INTO
    v_vat_rate_pct,
    v_erni_pct
  FROM public.settings_finance_windows AS finance_window
  WHERE p_pay_date >= finance_window.date_from
    AND p_pay_date <= COALESCE(finance_window.date_to, 'infinity'::date)
  ORDER BY finance_window.date_from DESC, finance_window.id DESC
  LIMIT 1;

  IF v_vat_rate_pct IS NULL OR v_erni_pct IS NULL THEN
    RAISE EXCEPTION 'No finance window found for pay_date %', p_pay_date;
  END IF;

  SELECT
    settings_defaults.rail_provider_default,
    settings_defaults.rail_env_default,
    settings_defaults.rail_supports_scheduling,
    settings_defaults.rail_supports_name_check,
    settings_defaults.rail_supports_auto_execute,
    settings_defaults.default_schedule_umbrella_local,
    settings_defaults.default_schedule_paye_local,
    settings_defaults.funds_warning_hours_json,
    settings_defaults.pay_eligibility_months_back,
    settings_defaults.pay_eligibility_weeks_ahead
  INTO
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead
  FROM public.settings_defaults AS settings_defaults
  ORDER BY settings_defaults.id ASC
  LIMIT 1;

  IF v_rail_provider_default IS NULL OR v_rail_env_default IS NULL THEN
    RAISE EXCEPTION 'settings_defaults missing or not populated';
  END IF;

  v_pay_eligibility_months_back := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_months_back, 6), 120));
  v_pay_eligibility_weeks_ahead := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_weeks_ahead, 2), 52));
  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;
  v_need_name_check := COALESCE(v_rail_supports_name_check, false) AND UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV';
  v_requires_payee_map := UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV';

  v_preview_decisions_root := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  IF v_effective_candidate_id IS NULL
     AND NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'candidate_id', v_preview_decisions_root->>'candidateId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_effective_candidate_id := NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'candidate_id', v_preview_decisions_root->>'candidateId', '')), '')::uuid;
  END IF;

  IF v_effective_client_id IS NULL
     AND NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'client_id', v_preview_decisions_root->>'clientId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_effective_client_id := NULLIF(BTRIM(COALESCE(v_preview_decisions_root->>'client_id', v_preview_decisions_root->>'clientId', '')), '')::uuid;
  END IF;

  v_source_build_internal_requested :=
    LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'workbench_source_build_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'source_build_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_preview_decisions_root->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD';

  v_overpayment_sync_internal_requested :=
    LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'overpayment_sync_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_source_build_authority_token := NULLIF(BTRIM(COALESCE(
    v_preview_decisions_root->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_overpayment_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  v_internal_reconciliation_flags_requested :=
    v_source_build_internal_requested
    OR v_overpayment_sync_internal_requested
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'lifecycle_reconciliation_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'historic_metadata_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'signed_finance_reconciliation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'exclude_lifecycle_ineligible_current_payability', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'authoritative_timesheet_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_internal_reconciliation_authorised :=
    (
      v_source_build_internal_requested IS TRUE
      AND v_source_build_authority_token IS NOT NULL
      AND v_current_overpayment_sync_authority_token IS NOT NULL
      AND v_source_build_authority_token = v_current_overpayment_sync_authority_token
    )
    OR (
      v_overpayment_sync_internal_requested IS TRUE
      AND v_current_overpayment_sync_authority_token IS NOT NULL
    );

  IF v_internal_reconciliation_flags_requested IS TRUE
     AND v_internal_reconciliation_authorised IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_INTERNAL_AUTHORITY_REQUIRED'
      USING ERRCODE = '42501',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_BUILD_CONTEXT_INTERNAL_AUTHORITY_REQUIRED',
              'source_build_requested', v_source_build_internal_requested,
              'overpayment_sync_requested', v_overpayment_sync_internal_requested,
              'source_build_authority_present', v_source_build_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_overpayment_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_lifecycle_mutation_context := UPPER(BTRIM(COALESCE(
    v_preview_decisions_root->>'mutation_context',
    v_preview_decisions_root->>'lifecycle_mutation_context',
    v_preview_decisions_root->>'lifecycle_context',
    ''
  )));

  v_preview_decisions_root := v_preview_decisions_root
    - 'overpayment_sync_authority_token'
    - 'lifecycle_reconciliation_mode'
    - 'historic_metadata_allowed'
    - 'signed_finance_reconciliation'
    - 'exclude_lifecycle_ineligible_current_payability'
    - 'authoritative_timesheet_scope';

  v_context_mode := UPPER(NULLIF(BTRIM(COALESCE(
    v_preview_decisions_root->>'preview_context_mode',
    v_preview_decisions_root->>'context_mode',
    v_preview_decisions_root->>'mode',
    'SUMMARY'
  )), ''));

  IF v_context_mode NOT IN ('SUMMARY', 'PAGE', 'FULL_COMPAT') THEN
    v_context_mode := 'SUMMARY';
  END IF;

  v_full_compat_requested := v_context_mode = 'FULL_COMPAT';

  IF v_context_mode = 'FULL_COMPAT' AND v_effective_candidate_id IS NULL THEN
    v_context_mode := 'PAGE';
    v_full_compat_downgraded := true;
  END IF;

  IF COALESCE(v_preview_decisions_root->>'scope_limit', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_preview_decisions_root->>'scope_limit')::integer, 1), 100);
  ELSIF COALESCE(v_preview_decisions_root#>>'{scope_page,limit}', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_preview_decisions_root#>>'{scope_page,limit}')::integer, 1), 100);
  ELSE
    v_page_limit := 100;
  END IF;

  IF NULLIF(BTRIM(COALESCE(
       v_preview_decisions_root#>>'{scope_cursor,last_candidate_id}',
       v_preview_decisions_root#>>'{scope_cursor,candidate_id}',
       v_preview_decisions_root->>'last_candidate_id',
       v_preview_decisions_root->>'cursor_candidate_id',
       ''
     )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_candidate_id := NULLIF(BTRIM(COALESCE(
       v_preview_decisions_root#>>'{scope_cursor,last_candidate_id}',
       v_preview_decisions_root#>>'{scope_cursor,candidate_id}',
       v_preview_decisions_root->>'last_candidate_id',
       v_preview_decisions_root->>'cursor_candidate_id',
       ''
     )), '')::uuid;
  END IF;

  v_preview_case_resolutions := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'case_resolutions') = 'object' THEN COALESCE(v_preview_decisions_root->'case_resolutions', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_preview_decisions_root->>'refresh_scope_kind', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL::text;
  END IF;

  v_targeted_timesheet_ids_raw := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'array' THEN v_preview_decisions_root->'targeted_timesheet_ids'
    WHEN jsonb_typeof(v_preview_decisions_root->'targetedTimesheetIds') = 'array' THEN v_preview_decisions_root->'targetedTimesheetIds'
    WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'targeted_timesheet_ids')
    WHEN jsonb_typeof(v_preview_decisions_root->'targetedTimesheetIds') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'targetedTimesheetIds')
    ELSE '[]'::jsonb
  END;

  v_linked_timesheet_ids_raw := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'array' THEN v_preview_decisions_root->'linked_timesheet_ids'
    WHEN jsonb_typeof(v_preview_decisions_root->'linkedTimesheetIds') = 'array' THEN v_preview_decisions_root->'linkedTimesheetIds'
    WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'linked_timesheet_ids')
    WHEN jsonb_typeof(v_preview_decisions_root->'linkedTimesheetIds') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'linkedTimesheetIds')
    ELSE '[]'::jsonb
  END;

  v_targeted_timesheet_input_count := jsonb_array_length(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb));
  v_linked_timesheet_input_count := jsonb_array_length(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb));

  SELECT COUNT(DISTINCT NULLIF(BTRIM(scope_input.timesheet_id_text), ''))::integer
  INTO v_distinct_timesheet_scope_input_count
  FROM (
    SELECT targeted_scope_input.value AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb)) AS targeted_scope_input(value)
    UNION ALL
    SELECT linked_scope_input.value AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb)) AS linked_scope_input(value)
  ) AS scope_input
  WHERE NULLIF(BTRIM(scope_input.timesheet_id_text), '') IS NOT NULL;

  IF COALESCE(v_targeted_timesheet_input_count, 0) > 100
     OR COALESCE(v_linked_timesheet_input_count, 0) > 100
     OR COALESCE(v_distinct_timesheet_scope_input_count, 0) > 100 THEN
    RAISE EXCEPTION 'PAY_PREVIEW_BUILD_CONTEXT_TIMESHEET_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_BUILD_CONTEXT_TIMESHEET_SCOPE_TOO_LARGE',
              'context_mode', v_context_mode,
              'targeted_timesheet_count', COALESCE(v_targeted_timesheet_input_count, 0),
              'linked_timesheet_count', COALESCE(v_linked_timesheet_input_count, 0),
              'combined_timesheet_count', COALESCE(v_distinct_timesheet_scope_input_count, 0),
              'raw_combined_timesheet_count', COALESCE(v_targeted_timesheet_input_count, 0) + COALESCE(v_linked_timesheet_input_count, 0),
              'max_timesheet_scope_ids', 100,
              'row_backed_scope_required', true,
              'message', 'Caller-supplied timesheet scope arrays are capped at 100 for preview context. Use the row-backed workbench session scope instead.'
            )::text;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_array.value), '') AS targeted_timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_raw, '[]'::jsonb)) AS targeted_scope_array(value)
    WHERE NULLIF(BTRIM(targeted_scope_array.value), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_array.value), '') AS linked_timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_raw, '[]'::jsonb)) AS linked_scope_array(value)
    WHERE NULLIF(BTRIM(linked_scope_array.value), '') IS NOT NULL
  ) AS linked_scope_ids;


  v_targeted_timesheet_ids_requested := COALESCE(v_targeted_timesheet_ids, '[]'::jsonb);
  v_linked_timesheet_ids_requested := COALESCE(v_linked_timesheet_ids, '[]'::jsonb);

  WITH requested_scope_values AS (
    SELECT
      'TARGETED'::text AS scope_kind,
      requested_targeted_values.timesheet_id_text AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_requested, '[]'::jsonb)) AS requested_targeted_values(timesheet_id_text)

    UNION ALL

    SELECT
      'LINKED'::text AS scope_kind,
      requested_linked_values.timesheet_id_text AS timesheet_id_text
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_requested, '[]'::jsonb)) AS requested_linked_values(timesheet_id_text)
  ),
  requested_scope_ids AS (
    SELECT DISTINCT
      requested_scope_values.scope_kind,
      NULLIF(BTRIM(COALESCE(requested_scope_values.timesheet_id_text, '')), '')::uuid AS requested_timesheet_id
    FROM requested_scope_values
    WHERE NULLIF(BTRIM(COALESCE(requested_scope_values.timesheet_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  rotation_scope_rows AS (
    SELECT
      requested_scope_ids.scope_kind,
      requested_scope_ids.requested_timesheet_id,
      rotation_scope.requested_timesheet_id AS scope_requested_timesheet_id,
      rotation_scope.booking_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM requested_scope_ids
    JOIN public._pay_timesheet_rotation_scope(
      (
        SELECT COALESCE(
          array_agg(DISTINCT requested_scope_ids_for_array.requested_timesheet_id ORDER BY requested_scope_ids_for_array.requested_timesheet_id),
          ARRAY[]::uuid[]
        )
        FROM requested_scope_ids AS requested_scope_ids_for_array
      )
    ) AS rotation_scope
      ON rotation_scope.requested_timesheet_id = requested_scope_ids.requested_timesheet_id
  ),
  resolved_requested_scope AS (
    SELECT DISTINCT ON (rotation_scope_rows.scope_kind, rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.scope_kind,
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      rotation_scope_rows.booking_id,
      COALESCE(rotation_scope_rows.requested_is_canonical, false) AS requested_is_canonical
    FROM rotation_scope_rows
    ORDER BY
      rotation_scope_rows.scope_kind,
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  )
  SELECT
    COALESCE(
      jsonb_agg(DISTINCT resolved_requested_scope.canonical_timesheet_id::text ORDER BY resolved_requested_scope.canonical_timesheet_id::text)
        FILTER (WHERE resolved_requested_scope.scope_kind = 'TARGETED'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(DISTINCT resolved_requested_scope.canonical_timesheet_id::text ORDER BY resolved_requested_scope.canonical_timesheet_id::text)
        FILTER (WHERE resolved_requested_scope.scope_kind = 'LINKED'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'scope_kind', resolved_requested_scope.scope_kind,
          'requested_timesheet_id', resolved_requested_scope.requested_timesheet_id::text,
          'canonical_timesheet_id', resolved_requested_scope.canonical_timesheet_id::text,
          'booking_id', resolved_requested_scope.booking_id,
          'requested_is_canonical', resolved_requested_scope.requested_is_canonical
        )
        ORDER BY resolved_requested_scope.scope_kind, resolved_requested_scope.requested_timesheet_id
      ),
      '[]'::jsonb
    )
  INTO
    v_targeted_timesheet_ids,
    v_linked_timesheet_ids,
    v_timesheet_rotation_scope_json
  FROM resolved_requested_scope;

  v_lifecycle_reconciliation_mode := v_internal_reconciliation_authorised IS TRUE
    AND (
      v_overpayment_sync_internal_requested IS TRUE
      OR v_lifecycle_mutation_context IN (
        'TIMESHEET_AUTHORISE',
        'AUTHORISE_TIMESHEET',
        'TIMESHEET_UNAUTHORISE',
        'UNAUTHORISE_TIMESHEET',
        'TIMESHEET_ARCHIVE',
        'ARCHIVE_TIMESHEET',
        'TIMESHEET_UNARCHIVE',
        'UNARCHIVE_TIMESHEET'
      )
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'archive_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(v_preview_decisions_root->>'unarchive_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    );

  v_signed_finance_reconciliation := v_internal_reconciliation_authorised IS TRUE
    AND (v_source_build_internal_requested IS TRUE OR v_overpayment_sync_internal_requested IS TRUE);
  v_authoritative_timesheet_scope := v_internal_reconciliation_authorised IS TRUE
    AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS';
  v_historic_metadata_allowed := v_signed_finance_reconciliation IS TRUE
    AND v_authoritative_timesheet_scope IS TRUE;
  v_exclude_lifecycle_ineligible_current_payability := v_lifecycle_reconciliation_mode IS TRUE;

  v_preview_decisions_root := v_preview_decisions_root || jsonb_build_object(
    'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
    'historic_metadata_allowed', v_historic_metadata_allowed,
    'signed_finance_reconciliation', v_signed_finance_reconciliation,
    'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
    'authoritative_timesheet_scope', v_authoritative_timesheet_scope
  );

  v_paye_guardrails := public.pay_paye_guardrails(
    p_pay_date => p_pay_date,
    p_ignore_pay_batch_id => NULL::uuid,
    p_actor_user_id => p_actor_user_id
  );

  IF v_context_mode IN ('PAGE', 'FULL_COMPAT') THEN
    /*
      Section 2 cutover: PAGE/FULL_COMPAT scope is keyset driven from
      public.candidates and uses EXISTS probes for eligibility.  This avoids
      constructing a full candidate-scope temp/list before applying LIMIT.
      SUMMARY mode deliberately skips this block and remains fixed-cost.
    */
    WITH targeted_scope_timesheet_ids AS (
      SELECT DISTINCT NULLIF(BTRIM(scope_timesheet_values.timesheet_id_text), '')::uuid AS timesheet_id
      FROM (
        SELECT jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids, '[]'::jsonb)) AS timesheet_id_text
        UNION ALL
        SELECT jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids, '[]'::jsonb)) AS timesheet_id_text
      ) AS scope_timesheet_values
      WHERE NULLIF(BTRIM(scope_timesheet_values.timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    page_rows AS (
      SELECT
        candidate_scope_row.id AS candidate_id,
        ROW_NUMBER() OVER (ORDER BY candidate_scope_row.id) AS page_ordinal
      FROM public.candidates AS candidate_scope_row
      WHERE (v_last_candidate_id IS NULL OR candidate_scope_row.id > v_last_candidate_id)
        AND (
          (
            v_effective_candidate_id IS NOT NULL
            AND candidate_scope_row.id = v_effective_candidate_id
          )
          OR EXISTS (
            SELECT 1
            FROM targeted_scope_timesheet_ids AS targeted_timesheet_scope
            JOIN public.timesheets AS targeted_timesheet_row
              ON targeted_timesheet_row.timesheet_id = targeted_timesheet_scope.timesheet_id
            LEFT JOIN public.timesheets_financials AS targeted_financials
              ON targeted_financials.timesheet_id = targeted_timesheet_row.timesheet_id
             AND targeted_financials.is_current = true
            LEFT JOIN public.contracts AS targeted_contract
              ON targeted_contract.id = targeted_timesheet_row.contract_id
            WHERE COALESCE(targeted_financials.candidate_id, targeted_contract.candidate_id) = candidate_scope_row.id
          )
          OR EXISTS (
            SELECT 1
            FROM public.timesheets_financials AS current_financials
            JOIN public.timesheets AS timesheet_row
              ON timesheet_row.timesheet_id = current_financials.timesheet_id
            LEFT JOIN public.timesheet_pay_state AS pay_state_row
              ON pay_state_row.timesheet_id = current_financials.timesheet_id
            WHERE current_financials.is_current = true
              AND current_financials.candidate_id = candidate_scope_row.id
              AND COALESCE(current_financials.pay_on_hold, false) = false
              AND COALESCE(current_financials.has_rate_issue, false) = false
              AND COALESCE(current_financials.has_pay_channel_issue, false) = false
              AND UPPER(COALESCE(current_financials.processing_status::text, '')) NOT IN ('UNASSIGNED', 'CLIENT_UNRESOLVED', 'RATE_MISSING', 'PAY_CHANNEL_MISSING')
              AND UPPER(COALESCE(candidate_scope_row.pay_method, '')) IN ('PAYE', 'UMBRELLA')
              AND (v_effective_client_id IS NULL OR current_financials.client_id = v_effective_client_id)
              AND (
                (
                  timesheet_row.authorised_at_server IS NOT NULL
                  AND timesheet_row.revoked_at IS NULL
                  AND timesheet_row.archived_at_utc IS NULL
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) >= v_eligibility_from_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_eligibility_to_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_effective_week_ending_cutoff
                )
                OR EXISTS (
                  SELECT 1
                  FROM public.timesheet_payment_overrides AS forced_override
                  WHERE forced_override.timesheet_id = current_financials.timesheet_id
                    AND forced_override.cleared_at_utc IS NULL
                    AND forced_override.consumed_at_utc IS NULL
                    AND forced_override.consumed_by_pay_batch_id IS NULL
                    AND UPPER(COALESCE(forced_override.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
                )
                OR (
                  pay_state_row.last_settled_snapshot_json IS NOT NULL
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) >= v_eligibility_from_date
                  AND COALESCE(
                    CASE
                      WHEN UPPER(COALESCE(timesheet_row.sheet_scope::text, '')) = 'DAILY'
                       AND timesheet_row.worked_start_iso IS NOT NULL
                        THEN (timesheet_row.worked_start_iso AT TIME ZONE 'Europe/London')::date
                      ELSE NULL::date
                    END,
                    timesheet_row.week_ending_date::date
                  ) <= v_effective_week_ending_cutoff
                )
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.v_finance_cases_register AS finance_case_row
            WHERE finance_case_row.candidate_id = candidate_scope_row.id
              AND finance_case_row.case_type IN (
                'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              AND UPPER(COALESCE(finance_case_row.status::text, '')) IN ('ACTIVE', 'PAUSED')
              AND COALESCE(finance_case_row.outstanding_amount, 0) > 0
              AND UPPER(COALESCE(candidate_scope_row.pay_method, '')) IN ('PAYE', 'UMBRELLA')
              AND (v_effective_client_id IS NULL OR finance_case_row.client_id = v_effective_client_id)
              AND (
                (
                  finance_case_row.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
                  AND (
                    UPPER(COALESCE(finance_case_row.payout_status::text, '')) <> 'PAID'
                    OR finance_case_row.next_due_week_start IS NULL
                    OR finance_case_row.next_due_week_start <= v_pay_week_start
                  )
                )
                OR (
                  finance_case_row.case_type IN (
                    'OVERPAYMENT'::public.pay_finance_case_type_enum,
                    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
                  )
                  AND (
                    finance_case_row.next_due_week_start IS NULL
                    OR finance_case_row.next_due_week_start <= v_pay_week_start
                  )
                )
              )
          )
        )
      ORDER BY candidate_scope_row.id
      LIMIT (v_page_limit + 1)
    ),
    selected_rows AS (
      SELECT page_rows.candidate_id,
             page_rows.page_ordinal
      FROM page_rows
      WHERE page_rows.page_ordinal <= v_page_limit
    )
    SELECT
      COALESCE(jsonb_agg(to_jsonb(selected_rows.candidate_id::text) ORDER BY selected_rows.candidate_id), '[]'::jsonb),
      COUNT(*)::integer,
      EXISTS (SELECT 1 FROM page_rows WHERE page_rows.page_ordinal > v_page_limit),
      CASE
        WHEN EXISTS (SELECT 1 FROM page_rows WHERE page_rows.page_ordinal > v_page_limit) THEN
          jsonb_build_object(
            'last_candidate_id',
            (SELECT selected_cursor.candidate_id::text FROM selected_rows AS selected_cursor ORDER BY selected_cursor.candidate_id DESC LIMIT 1)
          )
        ELSE NULL::jsonb
      END
    INTO
      v_candidate_ids,
      v_page_count,
      v_has_more,
      v_next_cursor_json
    FROM selected_rows;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_date', p_pay_date::text,
    'pay_week_start', v_pay_week_start::text,
    'week_ending_cutoff_date', v_effective_week_ending_cutoff::text,
    'context_mode_requested', CASE WHEN v_full_compat_requested THEN 'FULL_COMPAT' ELSE v_context_mode END,
    'context_mode', v_context_mode,
    'full_compat_downgraded_to_page', v_full_compat_downgraded,
    'pre_draft', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  )
  || jsonb_build_object(
    'eligibility', jsonb_build_object(
      'today_uk', v_today_uk::text,
      'from_date', v_eligibility_from_date::text,
      'to_date', v_eligibility_to_date::text,
      'months_back', v_pay_eligibility_months_back,
      'weeks_ahead', v_pay_eligibility_weeks_ahead
    ),
    'filters', jsonb_build_object(
      'candidate_id', CASE WHEN v_effective_candidate_id IS NULL THEN NULL ELSE v_effective_candidate_id::text END,
      'client_id', CASE WHEN v_effective_client_id IS NULL THEN NULL ELSE v_effective_client_id::text END,
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
    ),
    'finance', jsonb_build_object(
      'vat_rate_pct', v_vat_rate_pct,
      'erni_pct', v_erni_pct
    )
  )
  || jsonb_build_object(
    'settings', jsonb_build_object(
      'rail', jsonb_build_object(
        'provider_default', v_rail_provider_default,
        'env_default', v_rail_env_default,
        'supports_scheduling', v_rail_supports_scheduling,
        'supports_name_check', v_rail_supports_name_check,
        'supports_auto_execute', v_rail_supports_auto_execute,
        'need_name_check', v_need_name_check,
        'requires_payee_map', v_requires_payee_map
      ),
      'schedule_defaults', jsonb_build_object(
        'umbrella_local', v_default_schedule_umbrella_local,
        'paye_local', v_default_schedule_paye_local
      ),
      'funds_warning_hours_json', COALESCE(v_funds_warning_hours_json, '[]'::jsonb)
    ),
    'paye_guardrails', COALESCE(v_paye_guardrails, '{}'::jsonb)
  )
  || jsonb_build_object(
    'candidate_ids', COALESCE(v_candidate_ids, '[]'::jsonb),
    'candidate_ids_are_page_only', true,
    'count_unknown', v_context_mode = 'SUMMARY',
    'scope_count_unknown', v_context_mode = 'SUMMARY',
    'known_total_count', NULL::integer,
    'candidate_count', NULL::integer,
    'page_count', COALESCE(v_page_count, 0),
    'limit', v_page_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor_json', v_next_cursor_json,
    'next_cursor', v_next_cursor_json
  )
  || jsonb_build_object(
    'preview_decisions_json', v_preview_decisions_root,
    'preview_case_resolutions', v_preview_case_resolutions,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids, '[]'::jsonb)
  )
  || jsonb_build_object(
    'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_requested, '[]'::jsonb),
    'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_requested, '[]'::jsonb),
    'timesheet_rotation_scope', COALESCE(v_timesheet_rotation_scope_json, '[]'::jsonb)
  )
  || jsonb_build_object(
    'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
    'historic_metadata_allowed', v_historic_metadata_allowed,
    'signed_finance_reconciliation', v_signed_finance_reconciliation,
    'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
    'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
    'internal_reconciliation_scope', jsonb_build_object(
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids, '[]'::jsonb),
      'timesheet_rotation_scope', COALESCE(v_timesheet_rotation_scope_json, '[]'::jsonb)
    )
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_rollup(
  p_context_json jsonb,
  p_candidate_effective_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_effective_root jsonb := COALESCE(p_candidate_effective_json, '{}'::jsonb);
  v_candidate_row_source jsonb := '{}'::jsonb;
  v_candidate_id text := '';
  v_candidate_uuid uuid := NULL::uuid;
  v_session_id_text text := NULL::text;
  v_session_id uuid := NULL::uuid;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_candidate_state_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_candidate_row jsonb := '{}'::jsonb;
  v_lines_input jsonb := '[]'::jsonb;
  v_lines_input_count integer := 0;
  v_payees_input jsonb := '[]'::jsonb;
  v_display_name text := '';
  v_tms_ref text := '';
  v_inserted_preview_row_count integer := 0;
  v_tiny_compat_allowed boolean := false;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_ready_items_json jsonb := '[]'::jsonb;
  v_ready_count integer := 0;
  v_selected_count integer := 0;
  v_case_count integer := 0;
  v_blocked_count integer := 0;
  v_ready_amount numeric := 0;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_effective_root) <> 'object' THEN
    RAISE EXCEPTION 'p_candidate_effective_json must be a JSON object';
  END IF;

  v_candidate_row_source := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'candidate_row') = 'object'
      THEN COALESCE(v_candidate_effective_root->'candidate_row', '{}'::jsonb)
    ELSE v_candidate_effective_root
  END;

  v_candidate_id := BTRIM(COALESCE(
    v_candidate_row_source->>'candidate_id',
    v_candidate_effective_root->>'candidate_id',
    ''
  ));

  IF v_candidate_id = '' THEN
    RAISE EXCEPTION 'candidate_id is required on p_candidate_effective_json';
  END IF;

  IF v_candidate_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_ID_NOT_UUID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_ID_NOT_UUID',
              'candidate_id', v_candidate_id
            )::text;
  END IF;

  v_candidate_uuid := v_candidate_id::uuid;

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_candidate_effective_root->>'workbench_session_id',
    v_candidate_effective_root->>'session_id',
    v_candidate_effective_root#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_session_id := v_session_id_text::uuid;
  END IF;

  v_display_name := BTRIM(COALESCE(
    v_candidate_row_source->>'display_name',
    v_candidate_row_source->>'candidate_name',
    v_candidate_row_source->>'candidate_display_name',
    v_candidate_effective_root->>'display_name',
    v_candidate_effective_root->>'candidate_name',
    v_candidate_effective_root->>'candidate_display_name',
    ''
  ));

  v_tms_ref := BTRIM(COALESCE(
    v_candidate_row_source->>'tms_ref',
    v_candidate_row_source->>'candidate_tms_ref',
    v_candidate_effective_root->>'tms_ref',
    v_candidate_effective_root->>'candidate_tms_ref',
    ''
  ));

  v_payees_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'payees') = 'array' THEN COALESCE(v_candidate_effective_root->'payees', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'payees') = 'array' THEN COALESCE(v_candidate_row_source->'payees', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_tiny_compat_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'allow_tiny_compat',
    v_context_json->>'tiny_compat',
    v_context_json->>'explicit_tiny_compat',
    v_candidate_effective_root->>'allow_tiny_compat',
    v_candidate_effective_root->>'tiny_compat',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_session_id IS NOT NULL THEN
    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_FOUND',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_SESSION_NOT_OPEN',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    SELECT scope_row.*
    INTO v_scope_row
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = v_session_id
      AND scope_row.candidate_id = v_candidate_uuid
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_CANDIDATE_ROLLUP_CANDIDATE_NOT_IN_SCOPE',
                'session_id', v_session_id::text,
                'candidate_id', v_candidate_uuid::text
              )::text;
    END IF;

    SELECT candidate_state.*
    INTO v_candidate_state_row
    FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
    WHERE candidate_state.session_id = v_session_id
      AND candidate_state.candidate_id = v_candidate_uuid
    ORDER BY candidate_state.updated_at_utc DESC, candidate_state.id DESC
    LIMIT 1;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_candidate_rollup_rows;
    CREATE TEMP TABLE _tmp_pay_candidate_rollup_rows ON COMMIT DROP AS
    SELECT
      preview_row.id,
      preview_row.section,
      preview_row.row_ordinal,
      preview_row.row_json,
      preview_row.selected,
      preview_row.selection_state,
      public.pay_workbench_preview_section_from_line_json(preview_row.row_json) AS resolved_section,
      CASE
        WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((preview_row.row_json->>'amount_ex_vat')::numeric, 2)
        WHEN COALESCE(preview_row.row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((preview_row.row_json->>'preview_amount_ex_vat')::numeric, 2)
        ELSE 0::numeric
      END AS amount_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_session_id
      AND preview_row.candidate_id = v_candidate_uuid
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY';

    SELECT COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'canonical_preview_lines')::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'canonical_preview_lines' AND COALESCE(rollup_rows.selected, false))::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'cases_resolutions')::integer,
           COUNT(*) FILTER (WHERE rollup_rows.resolved_section = 'blocked_for_pay')::integer,
           ROUND(COALESCE(SUM(CASE WHEN rollup_rows.resolved_section = 'canonical_preview_lines' THEN rollup_rows.amount_ex_vat ELSE 0 END), 0), 2)
    INTO v_ready_count,
         v_selected_count,
         v_case_count,
         v_blocked_count,
         v_ready_amount
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS rollup_rows;

    SELECT COALESCE(jsonb_agg(case_rows.row_json ORDER BY case_rows.row_ordinal, case_rows.id), '[]'::jsonb)
    INTO v_case_resolution_states_json
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS case_rows
    WHERE case_rows.resolved_section = 'cases_resolutions';

    SELECT COALESCE(jsonb_agg(blocked_rows.row_json ORDER BY blocked_rows.row_ordinal, blocked_rows.id), '[]'::jsonb)
    INTO v_blocked_items_json
    FROM pg_temp._tmp_pay_candidate_rollup_rows AS blocked_rows
    WHERE blocked_rows.resolved_section = 'blocked_for_pay';

    SELECT COALESCE(jsonb_agg(ready_rows.row_json ORDER BY ready_rows.row_ordinal, ready_rows.id), '[]'::jsonb)
    INTO v_ready_items_json
    FROM (
      SELECT rollup_rows.*
      FROM pg_temp._tmp_pay_candidate_rollup_rows AS rollup_rows
      WHERE rollup_rows.resolved_section = 'canonical_preview_lines'
      ORDER BY rollup_rows.row_ordinal, rollup_rows.id
      LIMIT 100
    ) AS ready_rows;

    v_summary_fragment := COALESCE(v_candidate_state_row.effective_summary_fragment_json, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_count', 1,
        'row_backed', true,
        'requires_paging', true,
        'session_version', COALESCE(v_session_row.version, 1),
        'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
        'ready_preview_line_count', COALESCE(v_ready_count, 0),
        'selected_preview_line_count', COALESCE(v_selected_count, 0),
        'case_resolution_state_count', COALESCE(v_case_count, 0),
        'blocked_preview_line_count', COALESCE(v_blocked_count, 0),
        'ready_amount_ex_vat', COALESCE(v_ready_amount, 0)
      )
      || jsonb_build_object(
        'section_counts', jsonb_build_object(
          'canonical_preview_lines', COALESCE(v_ready_count, 0),
          'cases_resolutions', COALESCE(v_case_count, 0),
          'blocked_for_pay', COALESCE(v_blocked_count, 0)
        )
      );

    v_candidate_row := (v_candidate_row_source - 'canonical_preview_lines' - 'itemisation' - 'baseline_component_rows')
      || COALESCE(v_candidate_state_row.effective_candidate_fragment_json, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', true,
        'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
        'ready_preview_line_count', COALESCE(v_ready_count, 0),
        'selected_preview_line_count', COALESCE(v_selected_count, 0),
        'case_resolution_state_count', COALESCE(v_case_count, 0),
        'blocked_preview_line_count', COALESCE(v_blocked_count, 0),
        'is_ready_for_draft', COALESCE(v_selected_count, 0) > 0 AND UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED'),
        'is_review_required', UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('ERROR', 'FAILED')
      );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'workbench_session_id', v_session_id::text,
      'row_backed_candidate_rollup', true,
      'display_rows_written', 0,
      'summary_fragment', v_summary_fragment,
      'candidate_row', v_candidate_row,
      'case_resolution_states', COALESCE(v_case_resolution_states_json, '[]'::jsonb),
      'canonical_preview_lines', COALESCE(v_ready_items_json, '[]'::jsonb),
      'payees', COALESCE(v_candidate_state_row.effective_payees_json, v_payees_input, '[]'::jsonb),
      'itemisation', COALESCE(v_ready_items_json, '[]'::jsonb),
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0
    )
    || jsonb_build_object(
      'blocked_items', COALESCE(v_blocked_items_json, '[]'::jsonb),
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', CASE
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('ERROR', 'FAILED') THEN 'ERROR'
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 'READY'
        ELSE 'PENDING'
      END
    );
  END IF;

  IF v_tiny_compat_allowed IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'row_backed_candidate_rollup', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'tiny_compat_required_for_full_payload', true,
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'requires_paging', true,
        'tiny_compat_required_for_full_payload', true
      ),
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', false,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', COALESCE(v_payees_input, '[]'::jsonb),
      'itemisation', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PAGING_REQUIRED'
    );
  END IF;

  v_lines_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_effective_root->'canonical_preview_lines', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_row_source->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_lines_input_count := jsonb_array_length(COALESCE(v_lines_input, '[]'::jsonb));

  IF v_lines_input_count > 100 THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'row_backed_candidate_rollup', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'input_line_count', v_lines_input_count,
        'requires_paging', true
      ),
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_id,
        'display_name', v_display_name,
        'candidate_name', v_display_name,
        'tms_ref', v_tms_ref,
        'row_backed', false,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb,
      'hidden_recovery_template_line_count', 0,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PAGING_REQUIRED'
    );
  END IF;

  v_summary_fragment := jsonb_build_object(
    'candidate_count', 1,
    'canonical_preview_line_count', COALESCE(v_lines_input_count, 0),
    'ready_preview_line_count', COALESCE(v_lines_input_count, 0),
    'requires_paging', false,
    'tiny_compat', true
  );

  v_candidate_row := (v_candidate_row_source - 'canonical_preview_lines' - 'itemisation' - 'baseline_component_rows')
    || jsonb_build_object(
      'candidate_id', v_candidate_id,
      'display_name', v_display_name,
      'candidate_name', v_display_name,
      'tms_ref', v_tms_ref,
      'row_backed', false,
      'tiny_compat', true,
      'tiny_compat_explicit', true,
      'is_ready_for_draft', COALESCE(v_lines_input_count, 0) > 0,
      'is_review_required', false
    );

  RETURN jsonb_build_object(
    'candidate_id', v_candidate_id,
    'summary_fragment', v_summary_fragment,
    'candidate_row', v_candidate_row,
    'case_resolution_states', CASE WHEN jsonb_typeof(v_candidate_effective_root->'case_resolution_states') = 'array' THEN COALESCE(v_candidate_effective_root->'case_resolution_states', '[]'::jsonb) ELSE '[]'::jsonb END,
    'canonical_preview_lines', COALESCE(v_lines_input, '[]'::jsonb),
    'payees', COALESCE(v_payees_input, '[]'::jsonb),
    'itemisation', CASE WHEN jsonb_typeof(v_candidate_effective_root->'itemisation') = 'array' THEN COALESCE(v_candidate_effective_root->'itemisation', '[]'::jsonb) ELSE '[]'::jsonb END,
    'hidden_recovery_template_lines', '[]'::jsonb,
    'hidden_recovery_template_line_count', 0,
    'blocked_items', '[]'::jsonb,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'paye_candidate', v_candidate_row,
    'non_paye_payee', NULL::jsonb
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_baseline(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_candidate_uuid uuid := p_candidate_id;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_candidate_state_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_candidate_fragment_json jsonb := '{}'::jsonb;
  v_summary_fragment_json jsonb := '{}'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_scope_status text := 'PENDING';
  v_ready_state text := 'PENDING';
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF v_candidate_uuid IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF v_workbench_session_id IS NULL THEN
    RETURN jsonb_build_object(
      'candidate_id', v_candidate_uuid::text,
      'row_backed_candidate_baseline', false,
      'requires_paging', true,
      'large_candidate_safe', true,
      'candidate_row', jsonb_build_object(
        'candidate_id', v_candidate_uuid::text,
        'row_backed', false,
        'requires_workbench_session', true,
        'is_ready_for_draft', false,
        'is_review_required', false
      ),
      'summary_fragment', jsonb_build_object(
        'candidate_count', 1,
        'requires_paging', true,
        'status_text', 'Candidate preview requires a row-backed workbench session.'
      ),
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'pending_state', 'PENDING',
      'ready_state', 'PENDING'
    );
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_workbench_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_FOUND',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_SESSION_NOT_OPEN',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = v_workbench_session_id
    AND scope_row.candidate_id = v_candidate_uuid
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PREVIEW_CANDIDATE_BASELINE_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PREVIEW_CANDIDATE_BASELINE_CANDIDATE_NOT_IN_SCOPE',
              'session_id', v_workbench_session_id::text,
              'candidate_id', v_candidate_uuid::text
            )::text;
  END IF;

  SELECT candidate_state.*
  INTO v_candidate_state_row
  FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
  WHERE candidate_state.session_id = v_workbench_session_id
    AND candidate_state.candidate_id = v_candidate_uuid
  ORDER BY candidate_state.updated_at_utc DESC, candidate_state.id DESC
  LIMIT 1;

  v_scope_status := UPPER(BTRIM(COALESCE(v_scope_row.status, 'PENDING')));
  v_candidate_fragment_json := COALESCE(v_candidate_state_row.effective_candidate_fragment_json, '{}'::jsonb);
  v_summary_fragment_json := COALESCE(v_candidate_state_row.effective_summary_fragment_json, '{}'::jsonb);
  v_case_resolution_states_json := COALESCE(v_candidate_state_row.effective_case_resolution_states_json, '[]'::jsonb);
  v_canonical_preview_lines_json := COALESCE(v_candidate_state_row.effective_canonical_preview_lines_json, '[]'::jsonb);
  v_ready_state := CASE
    WHEN v_scope_status IN ('ERROR', 'FAILED') THEN 'ERROR'
    WHEN v_scope_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 'READY'
    ELSE 'PENDING'
  END;

  SELECT COALESCE(jsonb_agg(blocked_rows.row_json ORDER BY blocked_rows.row_ordinal, blocked_rows.id), '[]'::jsonb)
  INTO v_blocked_items_json
  FROM (
    SELECT preview_row.id, preview_row.row_ordinal, preview_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_workbench_session_id
      AND preview_row.candidate_id = v_candidate_uuid
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND lower(COALESCE(NULLIF(BTRIM(preview_row.section), ''), '')) = 'blocked_for_pay'
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    ORDER BY preview_row.row_ordinal, preview_row.id
    LIMIT 100
  ) AS blocked_rows;

  RETURN jsonb_build_object(
    'candidate_id', v_candidate_uuid::text,
    'workbench_session_id', v_workbench_session_id::text,
    'row_backed_candidate_baseline', true,
    'large_candidate_safe', true,
    'requires_paging', true,
    'candidate_row', jsonb_build_object(
      'candidate_id', v_candidate_uuid::text,
      'row_backed', true,
      'scope_status', v_scope_status,
      'is_ready_for_draft', CASE WHEN COALESCE(v_summary_fragment_json->>'selected_preview_line_count', '') ~ '^[0-9]+$' THEN (v_summary_fragment_json->>'selected_preview_line_count')::integer ELSE 0 END > 0 AND v_ready_state = 'READY',
      'is_review_required', v_ready_state = 'ERROR',
      'error_json', v_scope_row.error_json
    ) || CASE WHEN jsonb_typeof(v_candidate_fragment_json) = 'object' THEN v_candidate_fragment_json ELSE '{}'::jsonb END,
    'summary_fragment', jsonb_build_object(
      'candidate_count', 1,
      'row_backed', true,
      'requires_paging', true,
      'scope_status', v_scope_status,
      'session_version', COALESCE(v_session_row.version, 1),
      'pending_state', CASE WHEN v_ready_state = 'READY' THEN 'READY' ELSE 'PENDING' END
    ) || CASE WHEN jsonb_typeof(v_summary_fragment_json) = 'object' THEN v_summary_fragment_json ELSE '{}'::jsonb END,
    'case_resolution_states', CASE WHEN jsonb_typeof(v_case_resolution_states_json) = 'array' THEN v_case_resolution_states_json ELSE '[]'::jsonb END,
    'canonical_preview_lines', CASE WHEN jsonb_typeof(v_canonical_preview_lines_json) = 'array' THEN v_canonical_preview_lines_json ELSE '[]'::jsonb END,
    'payees', COALESCE(v_candidate_state_row.effective_payees_json, '[]'::jsonb)
  )
  || jsonb_build_object(
    'itemisation', '[]'::jsonb,
    'blocked_items', CASE WHEN jsonb_typeof(v_blocked_items_json) = 'array' THEN v_blocked_items_json ELSE '[]'::jsonb END,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'materialise_required', v_scope_status IN ('LINE_WORK_READY', 'PENDING', 'LINE_WORK_PENDING'),
    'pending_state', CASE WHEN v_ready_state = 'READY' THEN 'READY' WHEN v_ready_state = 'ERROR' THEN 'ERROR' ELSE 'PENDING' END,
    'ready_state', v_ready_state
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_assemble_payload(
  p_context_json jsonb,
  p_candidate_rollups_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_rollups_root jsonb := COALESCE(p_candidate_rollups_json, '[]'::jsonb);
  v_session_id_text text := NULL::text;
  v_session_id uuid := NULL::uuid;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_rollup_count integer := 0;
  v_tiny_compat_threshold integer := 25;
  v_tiny_compat_allowed boolean := false;
  v_rollup_sample jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_available_sections_json jsonb := '[]'::jsonb;
  v_ready_preview_line_count integer := 0;
  v_selected_preview_line_count integer := 0;
  v_case_resolution_state_count integer := 0;
  v_blocked_preview_line_count integer := 0;
  v_materialised_preview_row_count integer := 0;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_rollups_root) <> 'array' THEN
    RAISE EXCEPTION 'p_candidate_rollups_json must be a JSON array';
  END IF;

  v_candidate_rollup_count := jsonb_array_length(v_candidate_rollups_root);
  v_tiny_compat_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'allow_tiny_compat',
    v_context_json->>'tiny_compat',
    v_context_json->>'explicit_tiny_compat',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{session,id}',
    ''
  )), '');

  IF v_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_session_id := v_session_id_text::uuid;
  END IF;

  IF v_session_id IS NOT NULL THEN
    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_session_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error_code', 'WORKBENCH_SESSION_NOT_FOUND',
        'code', 'WORKBENCH_SESSION_NOT_FOUND',
        'session_id', v_session_id::text,
        'requires_paging', true,
        'ready', false,
        'ready_flag', false,
        'progress_only', true,
        'phase', 'REBASE_REQUIRED',
        'status_text', 'Payment preview needs refreshing.'
      );
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error_code', 'OBSOLETE_SESSION',
        'code', 'OBSOLETE_SESSION',
        'session_id', v_session_id::text,
        'requires_paging', true,
        'ready', false,
        'ready_flag', false,
        'progress_only', true,
        'phase', 'REBASE_REQUIRED',
        'status_text', 'Payment preview needs refreshing.'
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_preview_assemble_sections;
    CREATE TEMPORARY TABLE pg_temp._tmp_pay_preview_assemble_sections ON COMMIT DROP AS
    SELECT
      preview_row.id,
      preview_row.candidate_id,
      preview_row.section,
      preview_row.row_json,
      preview_row.selected,
      preview_row.selection_state,
      public.pay_workbench_preview_section_from_line_json(preview_row.row_json) AS resolved_section
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_session_id
      AND preview_row.session_version = COALESCE(v_session_row.version, 1)
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY';

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'canonical_preview_lines')::integer,
           COUNT(*) FILTER (
             WHERE section_rows.resolved_section = 'canonical_preview_lines'
               AND COALESCE(section_rows.selected, false) = true
               AND UPPER(BTRIM(COALESCE(section_rows.selection_state, ''))) = 'SELECTED'
               AND UPPER(BTRIM(COALESCE(section_rows.row_json->>'presentation_section', section_rows.row_json->>'readiness_state', ''))) = 'READY_TO_PAY'
               AND LOWER(BTRIM(COALESCE(section_rows.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           )::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'cases_resolutions')::integer,
           COUNT(*) FILTER (WHERE section_rows.resolved_section = 'blocked_for_pay')::integer
    INTO v_materialised_preview_row_count,
         v_ready_preview_line_count,
         v_selected_preview_line_count,
         v_case_resolution_state_count,
         v_blocked_preview_line_count
    FROM pg_temp._tmp_pay_preview_assemble_sections AS section_rows;

    SELECT COALESCE(jsonb_object_agg(section_counts.section_key, to_jsonb(section_counts.section_count) ORDER BY section_counts.section_key), '{}'::jsonb)
    INTO v_section_counts_json
    FROM (
      SELECT section_rows.resolved_section AS section_key,
             COUNT(*)::integer AS section_count
      FROM pg_temp._tmp_pay_preview_assemble_sections AS section_rows
      WHERE section_rows.resolved_section IN ('canonical_preview_lines', 'cases_resolutions', 'blocked_for_pay')
      GROUP BY section_rows.resolved_section
    ) AS section_counts;

    SELECT COALESCE(jsonb_agg(section_keys.section_key ORDER BY section_keys.section_key), '[]'::jsonb)
    INTO v_available_sections_json
    FROM (
      SELECT jsonb_object_keys(COALESCE(v_section_counts_json, '{}'::jsonb)) AS section_key
    ) AS section_keys;

    v_summary := jsonb_build_object(
      'candidate_count', COALESCE(v_session_row.scope_total_count, 0),
      'scope_rows_seeded', COALESCE(v_session_row.scope_seeded_count, 0),
      'scope_rows_ready', COALESCE(v_session_row.scope_ready_count, 0),
      'scope_rows_pending', COALESCE(v_session_row.scope_pending_count, 0),
      'scope_rows_failed', COALESCE(v_session_row.scope_failed_count, 0),
      'canonical_preview_line_count', COALESCE(v_ready_preview_line_count, 0),
      'ready_preview_line_count', COALESCE(v_ready_preview_line_count, 0),
      'selected_preview_line_count', COALESCE(v_selected_preview_line_count, 0),
      'case_resolution_state_count', COALESCE(v_case_resolution_state_count, 0),
      'blocked_preview_line_count', COALESCE(v_blocked_preview_line_count, 0),
      'preview_row_count', COALESCE(v_materialised_preview_row_count, 0)
    ) || jsonb_build_object(
      'section_counts', COALESCE(v_section_counts_json, '{}'::jsonb),
      'available_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'requires_paging', true
    );

    RETURN jsonb_build_object(
      'ok', true,
      'ready', COALESCE(v_session_row.scope_pending_count, 0) = 0
        AND COALESCE(v_session_row.scope_failed_count, 0) = 0
        AND COALESCE(v_session_row.line_units_pending, 0) = 0
        AND COALESCE(v_session_row.line_units_ready, 0) = 0
        AND COALESCE(v_session_row.line_units_failed, 0) = 0,
      'ready_flag', COALESCE(v_session_row.scope_pending_count, 0) = 0
        AND COALESCE(v_session_row.scope_failed_count, 0) = 0
        AND COALESCE(v_session_row.line_units_pending, 0) = 0
        AND COALESCE(v_session_row.line_units_ready, 0) = 0
        AND COALESCE(v_session_row.line_units_failed, 0) = 0,
      'requires_paging', true,
      'large_session_safe', true,
      'progress_only', false,
      'preview_page_rpc', 'pay_workbench_session_get_preview_page',
      'candidate_preview_rpc', 'pay_workbench_session_get_candidate_preview',
      'session_id', v_session_id::text,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'summary', v_summary,
      'progress', COALESCE(v_session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'candidate_count', COALESCE(v_session_row.scope_total_count, 0),
          'seeded_count', COALESCE(v_session_row.scope_seeded_count, 0),
          'ready_count', COALESCE(v_session_row.scope_ready_count, 0),
          'pending_count', COALESCE(v_session_row.scope_pending_count, 0),
          'failed_count', COALESCE(v_session_row.scope_failed_count, 0),
          'line_units_total', COALESCE(v_session_row.line_units_total, 0),
          'line_units_pending', COALESCE(v_session_row.line_units_pending, 0),
          'line_units_ready', COALESCE(v_session_row.line_units_ready, 0),
          'line_units_complete', GREATEST(COALESCE(v_session_row.line_units_total, 0) - COALESCE(v_session_row.line_units_pending, 0) - COALESCE(v_session_row.line_units_ready, 0) - COALESCE(v_session_row.line_units_failed, 0), 0),
          'line_units_error', COALESCE(v_session_row.line_units_failed, 0)
        ),
      'section_counts', COALESCE(v_section_counts_json, '{}'::jsonb),
      'section_cursors', '{}'::jsonb,
      'available_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'pageable_sections', COALESCE(v_available_sections_json, '[]'::jsonb),
      'samples', jsonb_build_object('scope', COALESCE(v_session_row.candidate_sample_rows_json, '[]'::jsonb)),
      'paye_candidates', '[]'::jsonb,
      'non_paye_payees', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb
    );
  END IF;

  IF v_tiny_compat_allowed IS NOT TRUE OR v_candidate_rollup_count > v_tiny_compat_threshold THEN
    SELECT COALESCE(jsonb_agg(v_candidate_rollups_root -> bounded_sample.sample_index ORDER BY bounded_sample.sample_index), '[]'::jsonb)
    INTO v_rollup_sample
    FROM generate_series(0, GREATEST(LEAST(v_candidate_rollup_count, 25) - 1, -1)) AS bounded_sample(sample_index)
    WHERE jsonb_typeof(v_candidate_rollups_root -> bounded_sample.sample_index) = 'object';

    RETURN jsonb_build_object(
      'ok', true,
      'requires_paging', true,
      'large_session_safe', true,
      'candidate_rollup_count', v_candidate_rollup_count,
      'tiny_compat_allowed', v_tiny_compat_allowed,
      'summary', jsonb_build_object(
        'candidate_count', v_candidate_rollup_count,
        'requires_paging', true,
        'tiny_compat_required_for_full_payload', true
      ),
      'samples', jsonb_build_object('candidate_rollups', COALESCE(v_rollup_sample, '[]'::jsonb)),
      'paye_candidates', '[]'::jsonb,
      'non_paye_payees', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'hidden_recovery_template_lines', '[]'::jsonb
    );
  END IF;

  SELECT jsonb_build_object(
    'candidate_count', v_candidate_rollup_count,
    'requires_paging', false,
    'tiny_compat', true,
    'tiny_compat_explicit', true
  )
  INTO v_summary;

  RETURN jsonb_build_object(
    'pay_date', v_context_json->'pay_date',
    'pay_week_start', v_context_json->'pay_week_start',
    'week_ending_cutoff_date', v_context_json->'week_ending_cutoff_date',
    'eligibility', COALESCE(v_context_json->'eligibility', '{}'::jsonb),
    'filters', COALESCE(v_context_json->'filters', '{}'::jsonb),
    'finance', COALESCE(v_context_json->'finance', '{}'::jsonb),
    'settings', COALESCE(v_context_json->'settings', '{}'::jsonb),
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'paye_guardrails', COALESCE(v_context_json->'paye_guardrails', '{}'::jsonb),
    'payees', '[]'::jsonb,
    'canonical_preview_lines', '[]'::jsonb,
    'case_resolution_states', '[]'::jsonb,
    'itemisation', '[]'::jsonb,
    'paye_candidates', '[]'::jsonb,
    'non_paye_payees', '[]'::jsonb,
    'blocked_items', '[]'::jsonb,
    'do_not_pay_items', '[]'::jsonb,
    'snoozed_items', '[]'::jsonb,
    'baseline_component_rows', '[]'::jsonb,
    'hidden_recovery_template_lines', '[]'::jsonb,
    'hidden_recovery_template_line_count', 0
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_preview_apply_candidate_overlay(
  p_candidate_baseline_json jsonb,
  p_case_resolutions_json jsonb DEFAULT NULL::jsonb,
  p_overrides_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_candidate_baseline_root jsonb := coalesce(p_candidate_baseline_json, '{}'::jsonb);
  v_case_resolutions_input jsonb := coalesce(p_case_resolutions_json, '{}'::jsonb);
  v_overrides_input jsonb := coalesce(p_overrides_json, '{}'::jsonb);
  v_candidate_id text := '';
  v_candidate_row jsonb := '{}'::jsonb;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_case_states jsonb := '[]'::jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_do_not_pay_items jsonb := '[]'::jsonb;
  v_snoozed_items jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_timesheet_snapshots_json jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines_input jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_hidden_recovery_template_line_count integer := 0;
  v_case_resolutions jsonb := '{}'::jsonb;
  v_exclude_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_map jsonb := '{}'::jsonb;
  v_bucket_applied_component_rows jsonb := '[]'::jsonb;
  v_final_component_rows jsonb := '[]'::jsonb;
  v_updated_case_states jsonb := '[]'::jsonb;
  v_case_state_map jsonb := '{}'::jsonb;
  v_updated_lines jsonb := '[]'::jsonb;
  v_updated_itemisation jsonb := '[]'::jsonb;
  v_case_resolution_entry record;
  v_case_resolution_json jsonb := '{}'::jsonb;
  v_resolution_case_key text := '';
  v_resolution_family text := '';
  v_resolve_all_linked_timesheets boolean := false;
  v_component_row jsonb := '{}'::jsonb;
  v_updated_component_row jsonb := '{}'::jsonb;
  v_component_scope text := '';
  v_component_case_key text := '';
  v_component_timesheet_id text := '';
  v_component_source_family_key text := '';
  v_component_key_type text := '';
  v_component_key_value text := '';
  v_component_bucket_code text := '';
  v_component_source_basis_fingerprint text := '';
  v_component_fingerprint text := '';
  v_component_source_units numeric := null::numeric;
  v_component_source_rate numeric := null::numeric;
  v_component_source_charge_rate numeric := null::numeric;
  v_case_state jsonb := '{}'::jsonb;
  v_line jsonb := '{}'::jsonb;
  v_case_state_case_key text := '';
  v_case_state_case_scope text := '';
  v_case_state_timesheet_id text := '';
  v_case_state_components jsonb := '[]'::jsonb;
  v_case_state_updated_components jsonb := '[]'::jsonb;
  v_case_state_updated jsonb := '{}'::jsonb;
  v_case_state_updated_components_count integer := 0;
  v_case_state_open_taxable_count integer := 0;
  v_case_state_open_reimbursement_count integer := 0;
  v_case_state_unresolved_taxable_count integer := 0;
  v_case_state_needs_resolution boolean := false;
  v_case_state_satisfied_now boolean := true;
  v_case_state_existing_blocked_reasons_count integer := 0;
  v_case_state_total_preview_amount_ex_vat numeric := 0;
  v_case_state_safe_amount_ex_vat numeric := 0;
  v_case_state_blocked_amount_ex_vat numeric := 0;
  v_case_state_unresolved_taxable_amount_ex_vat numeric := 0;
  v_case_state_taxable_manual_debt_resolution jsonb := null::jsonb;
  v_case_state_summary jsonb := '{}'::jsonb;
  v_case_state_resolved_detail_rows jsonb := '[]'::jsonb;
  v_template_base_line jsonb := null::jsonb;
  v_template_ready_line jsonb := null::jsonb;
  v_template_blocked_line jsonb := null::jsonb;
  v_template_do_not_pay_line jsonb := null::jsonb;
  v_case_ready_amount_ex_vat numeric := 0;
  v_case_blocked_amount_ex_vat numeric := 0;
  v_case_total_amount_ex_vat numeric := 0;
  v_case_is_excluded boolean := false;
  v_new_line jsonb := '{}'::jsonb;
  v_line_id_base text := '';
  v_line_preview_row_id text := '';
  v_item jsonb := '{}'::jsonb;
  v_component_match_found boolean := false;
  v_component_case_applies boolean := false;
  v_component_direct_case_match boolean := false;
  v_component_linked_case_match boolean := false;
  v_component_linked_ids jsonb := '[]'::jsonb;
  v_bucket_resolution_json jsonb := '{}'::jsonb;
  v_bucket_source_family_key text := '';
  v_bucket_component_key_type text := '';
  v_bucket_component_key_value text := '';
  v_bucket_source_basis_fingerprint text := '';
  v_bucket_bucket_code text := '';
  v_bucket_resolution_mode text := '';
  v_bucket_target_rate numeric := null::numeric;
  v_bucket_source_units numeric := null::numeric;
  v_bucket_source_rate numeric := null::numeric;
  v_bucket_source_charge_rate numeric := null::numeric;
  v_bucket_target_pay_ex_vat numeric := null::numeric;
  v_bucket_target_charge_ex_vat numeric := null::numeric;
  v_bucket_target_margin_ex_vat numeric := null::numeric;
  v_bucket_margin_delta_ex_vat numeric := null::numeric;
  v_nonbucket_resolution_entry record;
  v_nonbucket_resolution_mode text := '';
  v_nonbucket_target_amount_ex_vat numeric := null::numeric;
  v_nonbucket_case_row_count integer := 0;
  v_nonbucket_case_total_basis numeric := 0;
  v_nonbucket_case_allocated_so_far numeric := 0;
  v_nonbucket_case_row_index integer := 0;
  v_nonbucket_case_row_basis numeric := 0;
  v_nonbucket_case_row_target_amount_ex_vat numeric := 0;
  v_nonbucket_case_row_key text := '';
  v_nonbucket_case_row_match_key text := '';
  v_nonbucket_allocations jsonb := '{}'::jsonb;
  v_nonbucket_case_payload jsonb := '{}'::jsonb;
  v_nonbucket_case_row_allocations jsonb := '{}'::jsonb;
  v_component_lookup_key text := '';
  v_component_source_charge_ex_vat numeric := null::numeric;
  v_component_source_pay_ex_vat numeric := null::numeric;
  v_component_target_pay_ex_vat numeric := null::numeric;
  v_component_target_charge_ex_vat numeric := null::numeric;
  v_component_target_margin_ex_vat numeric := null::numeric;
  v_component_margin_delta_ex_vat numeric := null::numeric;
  v_component_preview_amount_ex_vat numeric := null::numeric;
  v_component_ready_preview_amount_ex_vat numeric := null::numeric;
  v_component_blocked_preview_amount_ex_vat numeric := null::numeric;
  v_component_requires_resolution boolean := false;
  v_component_is_actionable_resolution_row boolean := false;
  v_line_case_key text := '';
  v_line_case_scope text := '';
  v_line_timesheet_id text := '';
  v_line_presentation_section text := '';
  v_line_existing_blocked_reason_codes jsonb := '[]'::jsonb;
  v_line_existing_preview_row_id text := '';
  v_line_existing_line_id text := '';
  v_line_existing_presentation_parent_line_id text := '';
  v_excluded_timesheet_entry jsonb;
  v_excluded_timesheet_id text := '';
  v_case_state_component jsonb := '{}'::jsonb;
  v_component_requires_resolution_text text := '';
  v_component_preview_amount_text text := '';
  v_component_ready_amount_text text := '';
  v_component_blocked_amount_text text := '';
  v_case_state_exists boolean := false;
  v_case_state_from_map jsonb := '{}'::jsonb;
  v_case_state_summary_source jsonb := '{}'::jsonb;
  v_case_state_existing_due_amount_ex_vat numeric := 0;
  v_line_amount_ex_vat numeric := 0;
  v_do_not_pay_reason_codes jsonb := '[]'::jsonb;
  v_case_line_count integer := 0;
  v_case_ready_line_present boolean := false;
  v_case_blocked_line_present boolean := false;
  v_case_first_line jsonb := null::jsonb;
  v_case_component_row jsonb := '{}'::jsonb;
  v_component_order integer := 0;
  v_case_component_order integer := 0;
  v_component_sort_key text := '';
  v_case_scope_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_is_component_match boolean := false;
  v_line_blocked_reason_codes jsonb := '[]'::jsonb;
  v_existing_case_state_summary jsonb := '{}'::jsonb;
  v_nonbucket_resolution_applied boolean := false;
  v_nonbucket_case_allowed boolean := false;
  v_bucket_resolution_applied boolean := false;
  v_case_state_is_timesheet_scope boolean := false;
  v_itemisation_match_found boolean := false;
  v_itemisation_append_json jsonb := '{}'::jsonb;
  v_selected_case_line jsonb := null::jsonb;
  v_overlay_session_id uuid := NULL::uuid;
  v_overlay_session_id_text text := NULL::text;
  v_overlay_candidate_uuid uuid := NULL::uuid;
  v_overlay_now timestamptz := now();
  v_overlay_excluded_count integer := 0;
  v_overlay_preview_row_count integer := 0;
  v_overlay_draftable_row_count integer := 0;
  v_overlay_blocked_row_count integer := 0;
  v_overlay_do_not_pay_row_count integer := 0;
  v_overlay_total_amount_ex_vat numeric := 0;
  v_overlay_draftable_amount_ex_vat numeric := 0;
begin
  if jsonb_typeof(v_candidate_baseline_root) <> 'object' then
    raise exception 'p_candidate_baseline_json must be a JSON object';
  end if;

  if jsonb_typeof(v_case_resolutions_input) <> 'object' then
    v_case_resolutions_input := '{}'::jsonb;
  end if;

  if jsonb_typeof(v_overrides_input) <> 'object' then
    v_overrides_input := '{}'::jsonb;
  end if;

  v_candidate_id := btrim(coalesce(
    v_candidate_baseline_root->>'candidate_id',
    v_candidate_baseline_root #>> '{candidate_row,candidate_id}',
    ''
  ));

  if v_candidate_id = '' then
    raise exception 'candidate_id is required on p_candidate_baseline_json';
  end if;

  v_candidate_row := case when jsonb_typeof(v_candidate_baseline_root->'candidate_row') = 'object' then coalesce(v_candidate_baseline_root->'candidate_row', '{}'::jsonb) else '{}'::jsonb end;
  v_summary_fragment := case when jsonb_typeof(v_candidate_baseline_root->'summary_fragment') = 'object' then coalesce(v_candidate_baseline_root->'summary_fragment', '{}'::jsonb) else '{}'::jsonb end;
  v_case_states := case when jsonb_typeof(v_candidate_baseline_root->'case_resolution_states') = 'array' then coalesce(v_candidate_baseline_root->'case_resolution_states', '[]'::jsonb) else '[]'::jsonb end;
  v_lines := case when jsonb_typeof(v_candidate_baseline_root->'canonical_preview_lines') = 'array' then coalesce(v_candidate_baseline_root->'canonical_preview_lines', '[]'::jsonb) else '[]'::jsonb end;
  v_payees := case when jsonb_typeof(v_candidate_baseline_root->'payees') = 'array' then coalesce(v_candidate_baseline_root->'payees', '[]'::jsonb) else '[]'::jsonb end;
  v_itemisation := case when jsonb_typeof(v_candidate_baseline_root->'itemisation') = 'array' then coalesce(v_candidate_baseline_root->'itemisation', '[]'::jsonb) else '[]'::jsonb end;
  v_blocked_items := case when jsonb_typeof(v_candidate_baseline_root->'blocked_items') = 'array' then coalesce(v_candidate_baseline_root->'blocked_items', '[]'::jsonb) else '[]'::jsonb end;
  v_do_not_pay_items := case when jsonb_typeof(v_candidate_baseline_root->'do_not_pay_items') = 'array' then coalesce(v_candidate_baseline_root->'do_not_pay_items', '[]'::jsonb) else '[]'::jsonb end;
  v_snoozed_items := case when jsonb_typeof(v_candidate_baseline_root->'snoozed_items') = 'array' then coalesce(v_candidate_baseline_root->'snoozed_items', '[]'::jsonb) else '[]'::jsonb end;
  v_baseline_component_rows := case when jsonb_typeof(v_candidate_baseline_root->'baseline_component_rows') = 'array' then coalesce(v_candidate_baseline_root->'baseline_component_rows', '[]'::jsonb) else '[]'::jsonb end;
  v_timesheet_snapshots_json := case when jsonb_typeof(v_candidate_baseline_root->'timesheet_snapshots_json') = 'array' then coalesce(v_candidate_baseline_root->'timesheet_snapshots_json', '[]'::jsonb) else '[]'::jsonb end;
  v_hidden_recovery_template_lines_input := case
    when jsonb_typeof(v_candidate_baseline_root->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_baseline_root->'hidden_recovery_template_lines', '[]'::jsonb)
    when jsonb_typeof(v_candidate_row->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_row->'hidden_recovery_template_lines', '[]'::jsonb)
    else '[]'::jsonb
  end;

  select coalesce(jsonb_agg(elem.value order by elem.ord), '[]'::jsonb)
  into v_hidden_recovery_template_lines
  from jsonb_array_elements(v_hidden_recovery_template_lines_input) with ordinality as elem(value, ord)
  where jsonb_typeof(elem.value) = 'object';

  v_hidden_recovery_template_line_count := jsonb_array_length(v_hidden_recovery_template_lines);

  v_case_resolutions := case
    when jsonb_typeof(v_case_resolutions_input->'case_resolutions') = 'object' then coalesce(v_case_resolutions_input->'case_resolutions', '{}'::jsonb)
    when jsonb_typeof(v_case_resolutions_input) = 'object' then coalesce(v_case_resolutions_input, '{}'::jsonb)
    else '{}'::jsonb
  end;

  v_exclude_timesheet_ids := case
    when jsonb_typeof(v_overrides_input->'exclude_timesheet_ids') = 'array' then coalesce(v_overrides_input->'exclude_timesheet_ids', '[]'::jsonb)
    when jsonb_typeof(v_overrides_input->'timesheet_exclusions') = 'array' then coalesce(v_overrides_input->'timesheet_exclusions', '[]'::jsonb)
    else '[]'::jsonb
  end;

  v_overlay_session_id_text := NULLIF(BTRIM(COALESCE(
    v_candidate_baseline_root->>'workbench_session_id',
    v_candidate_baseline_root->>'session_id',
    v_candidate_baseline_root#>>'{workbench,session_id}',
    v_candidate_row->>'workbench_session_id',
    v_candidate_row->>'session_id',
    ''
  )), '');

  IF v_overlay_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_overlay_session_id := v_overlay_session_id_text::uuid;
  END IF;

  IF v_candidate_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_overlay_candidate_uuid := v_candidate_id::uuid;
  END IF;

  IF v_overlay_session_id IS NOT NULL THEN
    IF v_overlay_candidate_uuid IS NULL THEN
      RAISE EXCEPTION 'PAY_PREVIEW_OVERLAY_CANDIDATE_ID_NOT_UUID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_OVERLAY_CANDIDATE_ID_NOT_UUID',
                'candidate_id', v_candidate_id
              )::text;
    END IF;

    PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_overlay_session_id
      AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_PREVIEW_OVERLAY_SESSION_NOT_OPEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PREVIEW_OVERLAY_SESSION_NOT_OPEN',
                'session_id', v_overlay_session_id::text,
                'candidate_id', v_overlay_candidate_uuid::text
              )::text;
    END IF;

    IF jsonb_typeof(v_exclude_timesheet_ids) = 'array'
       AND jsonb_array_length(v_exclude_timesheet_ids) > 0 THEN
      WITH excluded_timesheets AS (
        SELECT DISTINCT NULLIF(BTRIM(excluded_id.value), '')::uuid AS timesheet_id
        FROM jsonb_array_elements_text(v_exclude_timesheet_ids) AS excluded_id(value)
        WHERE NULLIF(BTRIM(excluded_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), updated_preview_rows AS (
        UPDATE public.banking_pay_workbench_preview_rows AS preview_row
        SET selected = false,
            selection_state = 'EXCLUDED',
            row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'is_excluded_from_allocation', true,
                'is_do_not_pay', true,
                'presentation_section', 'DO_NOT_PAY',
                'readiness_state', 'DO_NOT_PAY',
                'draftable', false,
                'is_ready_for_draft', false,
                'overlay_applied_at_utc', v_overlay_now::text,
                'overlay_reason', 'SESSION_TIMESHEET_EXCLUSION'
              ),
            updated_at_utc = v_overlay_now
        FROM excluded_timesheets
        WHERE preview_row.session_id = v_overlay_session_id
          AND preview_row.candidate_id = v_overlay_candidate_uuid
          AND preview_row.timesheet_id = excluded_timesheets.timesheet_id
        RETURNING preview_row.id
      )
      SELECT COUNT(*)::integer
      INTO v_overlay_excluded_count
      FROM updated_preview_rows;
    ELSE
      v_overlay_excluded_count := 0;
    END IF;

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (
        WHERE COALESCE(preview_row.selected, false) = true
          AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY', 'CASES_RESOLUTIONS')
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(preview_row.row_json->>'presentation_section', ''))) = 'DO_NOT_PAY'
           OR LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_do_not_pay', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )::integer,
      COALESCE(SUM(CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric),
      COALESCE(SUM(CASE WHEN COALESCE(preview_row.selected, false) = true AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) NOT IN ('NOT_SELECTABLE', 'EXCLUDED') AND COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (preview_row.row_json->>'amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric)
    INTO
      v_overlay_preview_row_count,
      v_overlay_draftable_row_count,
      v_overlay_blocked_row_count,
      v_overlay_do_not_pay_row_count,
      v_overlay_total_amount_ex_vat,
      v_overlay_draftable_amount_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = v_overlay_session_id
      AND preview_row.candidate_id = v_overlay_candidate_uuid;

    v_summary_fragment := COALESCE(v_summary_fragment, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_count', 1,
        'canonical_preview_line_count', COALESCE(v_overlay_preview_row_count, 0),
        'ready_preview_line_count', COALESCE(v_overlay_draftable_row_count, 0),
        'blocked_preview_line_count', COALESCE(v_overlay_blocked_row_count, 0),
        'do_not_pay_line_count', COALESCE(v_overlay_do_not_pay_row_count, 0),
        'overlay_excluded_preview_row_count', COALESCE(v_overlay_excluded_count, 0),
        'total_amount_ex_vat', round(COALESCE(v_overlay_total_amount_ex_vat, 0), 2),
        'draftable_amount_ex_vat', round(COALESCE(v_overlay_draftable_amount_ex_vat, 0), 2),
        'row_backed', true
      );

    v_candidate_row := COALESCE(v_candidate_row, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_id', v_candidate_id,
        'row_backed', true,
        'preview_row_count', COALESCE(v_overlay_preview_row_count, 0),
        'draftable_preview_row_count', COALESCE(v_overlay_draftable_row_count, 0),
        'blocked_preview_line_count', COALESCE(v_overlay_blocked_row_count, 0),
        'do_not_pay_line_count', COALESCE(v_overlay_do_not_pay_row_count, 0),
        'is_ready_for_draft', (COALESCE(v_overlay_draftable_row_count, 0) > 0),
        'is_review_required', (COALESCE(v_overlay_blocked_row_count, 0) > 0 OR COALESCE(v_overlay_do_not_pay_row_count, 0) > 0)
      );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id,
      'workbench_session_id', v_overlay_session_id::text,
      'row_backed_overlay', true,
      'overlay_excluded_preview_row_count', COALESCE(v_overlay_excluded_count, 0),
      'candidate_row', COALESCE(v_candidate_row, '{}'::jsonb),
      'summary_fragment', COALESCE(v_summary_fragment, '{}'::jsonb),
      'case_resolution_states', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'hidden_recovery_template_lines', COALESCE(v_hidden_recovery_template_lines, '[]'::jsonb),
      'hidden_recovery_template_line_count', COALESCE(v_hidden_recovery_template_line_count, 0),
      'payees', COALESCE(v_payees, '[]'::jsonb),
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb,
      'timesheet_snapshots_json', '[]'::jsonb
    );
  END IF;


  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    if upper(btrim(coalesce(v_case_state->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
      v_case_scope_linked_timesheet_ids := case
        when jsonb_typeof(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}') = 'array'
          then coalesce(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}', '[]'::jsonb)
        when nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), '') is not null
          then jsonb_build_array(v_case_state->>'timesheet_id')
        else '[]'::jsonb
      end;

      v_linked_timesheet_map := v_linked_timesheet_map || jsonb_build_object(v_case_state_case_key, v_case_scope_linked_timesheet_ids);
    end if;
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_baseline_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_bucket_resolution_applied := false;

    v_component_scope := upper(btrim(coalesce(v_component_row->>'component_scope', '')));
    v_component_case_key := btrim(coalesce(v_component_row->>'case_key', ''));
    v_component_timesheet_id := btrim(coalesce(v_component_row->>'timesheet_id', ''));
    v_component_source_family_key := btrim(coalesce(v_component_row->>'source_family_key', ''));
    v_component_key_type := upper(btrim(coalesce(v_component_row->>'component_key_type', '')));
    v_component_key_value := btrim(coalesce(v_component_row->>'component_key_value', ''));
    v_component_bucket_code := upper(btrim(coalesce(v_component_row->>'bucket_code', '')));
    v_component_source_basis_fingerprint := btrim(coalesce(v_component_row->>'source_basis_fingerprint', ''));
    v_component_fingerprint := btrim(coalesce(v_component_row->>'component_fingerprint', ''));

    v_component_source_units := case when coalesce(v_component_row->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_units')::numeric, 6) else null::numeric end;
    v_component_source_rate := case when coalesce(v_component_row->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_rate := case when coalesce(v_component_row->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
    v_component_source_pay_ex_vat := case
      when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_entitlement_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_reservation_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
      else null::numeric
    end;

    for v_case_resolution_entry in
      select preview_resolution.key as case_key, preview_resolution.value as resolution_json
      from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
      where jsonb_typeof(preview_resolution.value) = 'object'
    loop
      v_case_resolution_json := v_case_resolution_entry.resolution_json;
      v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_case_resolution_entry.case_key, ''));
      v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));
      v_resolve_all_linked_timesheets := coalesce((v_case_resolution_json->>'resolve_all_linked_timesheets')::boolean, false);

      if v_resolution_family <> 'BUCKETED' then
        continue;
      end if;

      v_component_direct_case_match := (v_resolution_case_key <> '' and v_resolution_case_key = v_component_case_key);
      v_component_linked_case_match := false;

      if v_component_direct_case_match = false and v_resolve_all_linked_timesheets = true and v_component_scope = 'TIMESHEET' and v_component_timesheet_id <> '' then
        v_component_linked_ids := coalesce(v_linked_timesheet_map->v_resolution_case_key, '[]'::jsonb);
        if exists (
          select 1
          from jsonb_array_elements_text(v_component_linked_ids) as linked_id(value)
          where btrim(linked_id.value) = v_component_timesheet_id
        ) then
          v_component_linked_case_match := true;
        end if;
      end if;

      v_component_case_applies := (v_component_direct_case_match or v_component_linked_case_match);

      if v_component_case_applies = false then
        continue;
      end if;

      for v_bucket_resolution_json in
        select bucket_elem.value
        from jsonb_array_elements(coalesce(v_case_resolution_json->'bucket_resolutions', '[]'::jsonb)) as bucket_elem(value)
        where jsonb_typeof(bucket_elem.value) = 'object'
      loop
        v_bucket_source_family_key := btrim(coalesce(v_bucket_resolution_json->>'source_family_key', ''));
        v_bucket_component_key_type := upper(btrim(coalesce(v_bucket_resolution_json->>'component_key_type', '')));
        v_bucket_component_key_value := btrim(coalesce(v_bucket_resolution_json->>'component_key_value', ''));
        v_bucket_source_basis_fingerprint := btrim(coalesce(v_bucket_resolution_json->>'source_basis_fingerprint', ''));
        v_bucket_bucket_code := upper(btrim(coalesce(v_bucket_resolution_json->>'bucket_code', '')));
        v_bucket_resolution_mode := upper(btrim(coalesce(v_bucket_resolution_json->>'resolution_mode', '')));
        v_bucket_target_rate := case when coalesce(v_bucket_resolution_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'target_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_units := case when coalesce(v_bucket_resolution_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_units')::numeric, 6) else null::numeric end;
        v_bucket_source_rate := case when coalesce(v_bucket_resolution_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_charge_rate := case when coalesce(v_bucket_resolution_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_charge_rate')::numeric, 6) else null::numeric end;

        v_is_component_match := false;

        if v_bucket_source_family_key = v_component_source_family_key
           and v_bucket_component_key_type = v_component_key_type
           and v_bucket_component_key_value = v_component_key_value then
          if v_bucket_source_basis_fingerprint <> '' then
            v_is_component_match := (v_bucket_source_basis_fingerprint = v_component_source_basis_fingerprint);
          else
            v_is_component_match := true;

            if v_bucket_bucket_code <> '' then
              v_is_component_match := v_is_component_match and (v_bucket_bucket_code = v_component_bucket_code);
            end if;

            if v_bucket_source_units is not null then
              v_is_component_match := v_is_component_match and (v_component_source_units is not null and round(v_component_source_units, 6) = v_bucket_source_units);
            end if;

            if v_bucket_source_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_rate is not null and round(v_component_source_rate, 6) = v_bucket_source_rate);
            end if;

            if v_bucket_source_charge_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_charge_rate is not null and round(v_component_source_charge_rate, 6) = v_bucket_source_charge_rate);
            end if;
          end if;
        end if;

        if v_is_component_match = false then
          continue;
        end if;

        if v_component_key_type = 'TS_DAY' and not (v_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key for resolved component: %', v_component_key_value;
        end if;

        if v_bucket_component_key_type = 'TS_DAY' and not (v_bucket_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key in bucket resolution: %', v_bucket_component_key_value;
        end if;

        if v_bucket_target_rate is null or v_component_source_units is null or v_component_source_units = 0 then
          continue;
        end if;

        v_bucket_target_pay_ex_vat := round(v_bucket_target_rate * v_component_source_units, 2);
        v_bucket_target_charge_ex_vat := v_component_source_charge_ex_vat;
        v_bucket_target_margin_ex_vat := case when v_bucket_target_charge_ex_vat is null then null::numeric else round(v_bucket_target_charge_ex_vat - v_bucket_target_pay_ex_vat, 2) end;
        v_bucket_margin_delta_ex_vat := case when v_component_source_pay_ex_vat is null then null::numeric else round(v_component_source_pay_ex_vat - v_bucket_target_pay_ex_vat, 2) end;

        v_updated_component_row := (v_updated_component_row
          - 'approved_resolution_mode'
          - 'approved_target_rate'
          - 'requires_resolution'
          - 'case_resolution_satisfied_now_component'
          - 'suggestion_provenance'
          - 'is_fresh_suggested_resolution'
          - 'preview_component_amount_ex_vat'
          - 'ready_preview_amount_ex_vat'
          - 'blocked_preview_amount_ex_vat'
          - 'target_pay_ex_vat'
          - 'target_charge_ex_vat'
          - 'target_margin_ex_vat'
          - 'margin_delta_ex_vat'
          - 'resolution_state'
          - 'target_rate')
          || jsonb_build_object(
            'approved_resolution_mode', v_bucket_resolution_mode,
            'approved_target_rate', round(v_bucket_target_rate, 6),
            'requires_resolution', false,
            'case_resolution_satisfied_now_component', true,
            'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
            'is_fresh_suggested_resolution', false,
            'preview_component_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'ready_preview_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'blocked_preview_amount_ex_vat', 0,
            'source_pay_ex_vat', v_component_source_pay_ex_vat,
            'source_entitlement_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_reservation_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_units', v_component_source_units,
            'source_rate', v_component_source_rate,
            'source_charge_rate', v_component_source_charge_rate,
            'source_charge_ex_vat', v_component_source_charge_ex_vat,
            'target_units', v_component_source_units,
            'target_pay_ex_vat', v_bucket_target_pay_ex_vat,
            'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
            'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
            'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat,
            'resolution_state', 'RESOLVED',
            'target_rate', round(v_bucket_target_rate, 6),
            'resolution_mode', v_bucket_resolution_mode,
            'resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            )),
            'suggested_resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'suggested_resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            ))
          );

        v_bucket_resolution_applied := true;
        exit;
      end loop;

      if v_bucket_resolution_applied = true then
        exit;
      end if;
    end loop;

    v_bucket_applied_component_rows := v_bucket_applied_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_nonbucket_allocations := '{}'::jsonb;

  for v_nonbucket_resolution_entry in
    select preview_resolution.key as case_key, preview_resolution.value as resolution_json
    from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
    where jsonb_typeof(preview_resolution.value) = 'object'
  loop
    v_case_resolution_json := v_nonbucket_resolution_entry.resolution_json;
    v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_nonbucket_resolution_entry.case_key, ''));
    v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));

    if v_resolution_family <> 'NON_BUCKET' or v_resolution_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(v_case_states) as case_state_elem(value)
      where jsonb_typeof(case_state_elem.value) = 'object'
        and btrim(coalesce(case_state_elem.value->>'case_key', '')) = v_resolution_case_key
        and upper(btrim(coalesce(case_state_elem.value->>'case_scope', ''))) = 'FINANCE_CASE'
        and upper(btrim(coalesce(case_state_elem.value->>'case_type', ''))) = 'MANUAL_DEBT_ADJUSTMENT'
    ) into v_nonbucket_case_allowed;

    if v_nonbucket_case_allowed = false then
      continue;
    end if;

    v_nonbucket_resolution_mode := upper(btrim(coalesce(v_case_resolution_json->>'resolution_mode', '')));
    v_nonbucket_target_amount_ex_vat := case when coalesce(v_case_resolution_json->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_resolution_json->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

    if v_nonbucket_target_amount_ex_vat is null then
      continue;
    end if;

    v_nonbucket_case_row_count := 0;
    v_nonbucket_case_total_basis := 0;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_count := v_nonbucket_case_row_count + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;
        v_nonbucket_case_total_basis := v_nonbucket_case_total_basis + greatest(v_nonbucket_case_row_basis, 0);
      end if;
    end loop;

    if v_nonbucket_case_row_count <= 0 then
      continue;
    end if;

    v_nonbucket_case_row_index := 0;
    v_nonbucket_case_allocated_so_far := 0;
    v_nonbucket_case_row_allocations := '{}'::jsonb;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_index := v_nonbucket_case_row_index + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;

        if v_nonbucket_case_row_index < v_nonbucket_case_row_count and v_nonbucket_case_total_basis > 0 then
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat * (greatest(v_nonbucket_case_row_basis, 0) / v_nonbucket_case_total_basis), 2);
        elsif v_nonbucket_case_row_index < v_nonbucket_case_row_count then
          v_nonbucket_case_row_target_amount_ex_vat := 0;
        else
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat - v_nonbucket_case_allocated_so_far, 2);
        end if;

        v_nonbucket_case_allocated_so_far := v_nonbucket_case_allocated_so_far + v_nonbucket_case_row_target_amount_ex_vat;
        v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
        end if;
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_key_type', '')) || '|' || btrim(coalesce(v_component_row->>'component_key_value', '')) || '|' || v_nonbucket_case_row_index::text;
        end if;

        v_nonbucket_case_row_allocations := v_nonbucket_case_row_allocations || jsonb_build_object(v_nonbucket_case_row_key, jsonb_build_object(
          'resolution_mode', v_nonbucket_resolution_mode,
          'target_amount_ex_vat', v_nonbucket_case_row_target_amount_ex_vat
        ));
      end if;
    end loop;

    v_nonbucket_allocations := v_nonbucket_allocations || jsonb_build_object(v_resolution_case_key, v_nonbucket_case_row_allocations);
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_nonbucket_resolution_applied := false;
    v_resolution_case_key := btrim(coalesce(v_component_row->>'case_key', ''));

    if jsonb_typeof(v_nonbucket_allocations->v_resolution_case_key) = 'object' then
      v_component_lookup_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
      if v_component_lookup_key = '' then
        v_component_lookup_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
      end if;

      if v_component_lookup_key <> '' and jsonb_typeof((v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key) = 'object' then
        v_nonbucket_case_payload := (v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key;
        v_nonbucket_resolution_mode := upper(btrim(coalesce(v_nonbucket_case_payload->>'resolution_mode', '')));
        v_nonbucket_target_amount_ex_vat := case when coalesce(v_nonbucket_case_payload->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_nonbucket_case_payload->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

        if v_nonbucket_target_amount_ex_vat is not null then
          v_component_target_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
          v_component_target_margin_ex_vat := case when v_component_target_charge_ex_vat is null then null::numeric else round(v_component_target_charge_ex_vat - v_nonbucket_target_amount_ex_vat, 2) end;
          v_component_margin_delta_ex_vat := case when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric - v_nonbucket_target_amount_ex_vat, 2) else null::numeric end;

          v_updated_component_row := (v_updated_component_row
            - 'approved_nonbucket_resolution_mode'
            - 'approved_nonbucket_target_amount_ex_vat'
            - 'requires_resolution'
            - 'case_resolution_satisfied_now_component'
            - 'suggestion_provenance'
            - 'is_fresh_suggested_resolution'
            - 'preview_component_amount_ex_vat'
            - 'ready_preview_amount_ex_vat'
            - 'blocked_preview_amount_ex_vat'
            - 'target_pay_ex_vat'
            - 'target_charge_ex_vat'
            - 'target_margin_ex_vat'
            - 'margin_delta_ex_vat'
            - 'resolution_state')
            || jsonb_build_object(
              'approved_nonbucket_resolution_mode', v_nonbucket_resolution_mode,
              'approved_nonbucket_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'requires_resolution', false,
              'case_resolution_satisfied_now_component', true,
              'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
              'is_fresh_suggested_resolution', false,
              'preview_component_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'ready_preview_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'blocked_preview_amount_ex_vat', 0,
              'target_pay_ex_vat', v_nonbucket_target_amount_ex_vat,
              'target_charge_ex_vat', v_component_target_charge_ex_vat,
              'target_margin_ex_vat', v_component_target_margin_ex_vat,
              'margin_delta_ex_vat', v_component_margin_delta_ex_vat,
              'resolution_state', 'RESOLVED'
            );

          v_nonbucket_resolution_applied := true;
        end if;
      end if;
    end if;

    v_final_component_rows := v_final_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_updated_case_states := '[]'::jsonb;
  v_case_state_map := '{}'::jsonb;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_updated_components := '[]'::jsonb;
    v_case_state_updated_components_count := 0;
    v_case_state_open_taxable_count := 0;
    v_case_state_open_reimbursement_count := 0;
    v_case_state_unresolved_taxable_count := 0;
    v_case_state_total_preview_amount_ex_vat := 0;
    v_case_state_safe_amount_ex_vat := 0;
    v_case_state_blocked_amount_ex_vat := 0;
    v_case_state_unresolved_taxable_amount_ex_vat := 0;

    for v_case_component_row in
      select elem.value
      from jsonb_array_elements(v_final_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_case_component_row->>'case_key', '')) = v_case_state_case_key then
        v_case_state_updated_components := v_case_state_updated_components || jsonb_build_array(v_case_component_row);
        v_case_state_updated_components_count := v_case_state_updated_components_count + 1;

        if upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
          v_case_state_open_taxable_count := v_case_state_open_taxable_count + 1;
        elsif upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' then
          v_case_state_open_reimbursement_count := v_case_state_open_reimbursement_count + 1;
        end if;

        if coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        if coalesce(v_case_component_row->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'ready_preview_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        v_component_requires_resolution := coalesce((v_case_component_row->>'requires_resolution')::boolean, false);
        if v_component_requires_resolution then
          v_case_state_unresolved_taxable_count := v_case_state_unresolved_taxable_count + 1;
          if coalesce(v_case_component_row->>'blocked_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'blocked_preview_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
          end if;
        end if;
      end if;
    end loop;

    v_case_state_needs_resolution := (v_case_state_unresolved_taxable_count > 0);
    v_case_state_satisfied_now := not v_case_state_needs_resolution;
    if v_case_state_needs_resolution then
      v_case_state_blocked_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
      v_case_state_safe_amount_ex_vat := 0;
    else
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_safe_amount_ex_vat, 2);
    end if;

    v_case_is_excluded := false;
    if v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT') and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    if v_case_is_excluded then
      v_case_state_needs_resolution := false;
      v_case_state_satisfied_now := true;
      v_case_state_unresolved_taxable_count := 0;
      v_case_state_unresolved_taxable_amount_ex_vat := 0;
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
    end if;

    select count(*)::int
    into v_case_state_existing_blocked_reasons_count
    from jsonb_array_elements_text(
      case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end
    ) as blocker(value);

    v_existing_case_state_summary := case when jsonb_typeof(v_case_state->'case_resolution_summary') = 'object' then coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb) else '{}'::jsonb end;

    v_case_state_summary := (v_existing_case_state_summary
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'is_blocked'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'excluded_from_pay', v_case_is_excluded
      );

    v_case_state_taxable_manual_debt_resolution := case when jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then coalesce(v_case_state->'taxable_manual_debt_resolution', '{}'::jsonb) else null::jsonb end;
    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      if exists (
        select 1
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
      ) then
        select upper(btrim(coalesce(comp.value->>'approved_nonbucket_resolution_mode', ''))),
               case when coalesce(comp.value->>'approved_nonbucket_target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((comp.value->>'approved_nonbucket_target_amount_ex_vat')::numeric, 2) else null::numeric end
        into v_nonbucket_resolution_mode, v_nonbucket_target_amount_ex_vat
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
        limit 1;

        v_case_state_taxable_manual_debt_resolution := v_case_state_taxable_manual_debt_resolution
          || jsonb_build_object(
            'approved_resolution_mode', v_nonbucket_resolution_mode,
            'approved_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
            'case_resolution_satisfied_now', v_case_state_satisfied_now
          );
      end if;
    end if;

    v_case_state_updated := (v_case_state
      - 'components'
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'is_blocked'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'case_resolution_summary'
      - 'taxable_manual_debt_resolution'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'components', coalesce(v_case_state_updated_components, '[]'::jsonb),
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'case_resolution_summary', v_case_state_summary,
        'excluded_from_pay', v_case_is_excluded
      );

    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_taxable_manual_debt_resolution);
    end if;

    if coalesce(v_case_state_updated->>'due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('due_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    if coalesce(v_case_state_updated->>'payment_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('payment_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    v_updated_case_states := v_updated_case_states || jsonb_build_array(v_case_state_updated);
    if v_case_state_case_key <> '' then
      v_case_state_map := v_case_state_map || jsonb_build_object(v_case_state_case_key, v_case_state_updated);
    end if;
  end loop;

  v_updated_lines := '[]'::jsonb;

  for v_line in
    select elem.value
    from jsonb_array_elements(v_lines) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));
    if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
      continue;
    end if;
    v_updated_lines := v_updated_lines || jsonb_build_array(v_line);
  end loop;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_needs_resolution := coalesce(nullif(v_case_state->>'case_needs_resolution', '')::boolean, false);
    v_case_state_is_timesheet_scope := (v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT'));
    v_case_ready_amount_ex_vat := case when coalesce(v_case_state->>'safe_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'safe_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_blocked_amount_ex_vat := case when coalesce(v_case_state->>'blocked_case_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'blocked_case_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_total_amount_ex_vat := round(v_case_ready_amount_ex_vat + v_case_blocked_amount_ex_vat, 2);

    select coalesce(jsonb_agg(detail_component.value order by coalesce(detail_component.value->>'component_key_type', ''), coalesce(detail_component.value->>'component_key_value', ''), coalesce(detail_component.value->>'bucket_code', '')), '[]'::jsonb)
    into v_case_state_resolved_detail_rows
    from jsonb_array_elements(coalesce(v_case_state->'components', '[]'::jsonb)) as detail_component(value)
    where jsonb_typeof(detail_component.value) = 'object'
      and coalesce(detail_component.value->>'case_resolution_satisfied_now_component', '') in ('true', 'TRUE')
      and upper(btrim(coalesce(detail_component.value->>'component_key_type', ''))) in ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'ADJUSTMENT_CODE', 'EXPENSE_CODE');

    if v_case_state_resolved_detail_rows is null then
      v_case_state_resolved_detail_rows := '[]'::jsonb;
    end if;

    v_case_is_excluded := false;
    if v_case_state_is_timesheet_scope = true and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    v_template_base_line := null::jsonb;
    v_template_ready_line := null::jsonb;
    v_template_blocked_line := null::jsonb;
    v_template_do_not_pay_line := null::jsonb;

    for v_line in
      select elem.value
      from jsonb_array_elements(v_lines) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_line->>'case_key', '')) = v_case_state_case_key then
        if v_template_base_line is null then
          v_template_base_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'READY_TO_PAY' and v_template_ready_line is null then
          v_template_ready_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY' and v_template_blocked_line is null then
          v_template_blocked_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'DO_NOT_PAY' and v_template_do_not_pay_line is null then
          v_template_do_not_pay_line := v_line;
        end if;
      end if;
    end loop;

    if v_template_base_line is null and v_case_state_is_timesheet_scope = true then
      v_template_base_line := jsonb_build_object(
        'candidate_id', v_candidate_id,
        'tms_ref', nullif(btrim(coalesce(v_candidate_row->>'tms_ref', '')), ''),
        'display_name', nullif(btrim(coalesce(v_candidate_row->>'display_name', v_candidate_row->>'candidate_name', '')), ''),
        'line_type', 'TIMESHEET_PAYMENT',
        'finance_case_id', null,
        'case_key', v_case_state_case_key,
        'case_type', coalesce(nullif(btrim(coalesce(v_case_state->>'case_type', '')), ''), 'TIMESHEET_PAYMENT')
      )
      || jsonb_build_object(
        'case_is_blocked', true,
        'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
        'case_components', coalesce(v_case_state->'components', '[]'::jsonb),
        'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
        'booking_id', null,
        'client_id', nullif(btrim(coalesce(v_case_state->>'client_id', '')), ''),
        'client_name', nullif(btrim(coalesce(v_case_state->>'client_name', '')), ''),
        'week_ending_date', nullif(btrim(coalesce(v_case_state->>'week_ending_date', '')), ''))
      || jsonb_build_object(
        'role', null,
        'band', null,
        'linked_shift_date', null,
        'pay_channel', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', '')), ''),
        'paye_treatment', case when upper(btrim(coalesce(v_case_state->>'candidate_pay_method', ''))) = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
        'route_type', 'NORMAL_PAYMENT',
        'adjustment_comment', null
      )
      || jsonb_build_object(
        'has_active_timesheet_snooze', false,
        'has_active_segment_snoozes', false,
        'active_segment_snooze_count', 0,
        'active_segment_dated_snooze_count', 0,
        'active_segment_indefinite_snooze_count', 0,
        'whole_timesheet_snooze_action_blocked', false,
        'whole_timesheet_snooze_action_block_reason', null,
        'segment_snooze_action_blocked', false,
        'segment_snooze_action_block_reason', null
      )
      || jsonb_build_object(
        'snooze_identity', jsonb_build_object(
          'identity_type', 'TIMESHEET',
          'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
          'booking_id', null,
          'segment_id', null,
          'segment_stable_key', null,
          'source_ref', null
        ),
        'snooze_state', jsonb_build_object('state', 'NONE')
      );
    end if;

    if v_template_base_line is null then
      continue;
    end if;

    if v_template_ready_line is null then
      v_template_ready_line := v_template_base_line;
    end if;
    if v_template_blocked_line is null then
      v_template_blocked_line := v_template_base_line;
    end if;
    if v_template_do_not_pay_line is null then
      v_template_do_not_pay_line := v_template_base_line;
    end if;

    if v_case_is_excluded = true and round(v_case_total_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_do_not_pay_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;
      if right(v_line_existing_line_id, 11) <> ':do_not_pay' then
        v_line_existing_line_id := v_line_existing_line_id || ':do_not_pay';
      end if;

      v_do_not_pay_reason_codes := case
        when jsonb_typeof(v_template_do_not_pay_line->'blocked_reason_codes') = 'array' then coalesce(v_template_do_not_pay_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_do_not_pay_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'DO_NOT_PAY'
      ) then
        v_do_not_pay_reason_codes := v_do_not_pay_reason_codes || jsonb_build_array('DO_NOT_PAY');
      end if;

      v_new_line := (v_template_do_not_pay_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_section', 'DO_NOT_PAY',
          'presentation_reason', 'SESSION_TIMESHEET_EXCLUSION',
          'readiness_state', 'DO_NOT_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', true,
          'is_excluded_from_allocation', true,
          'blocked_reason_codes', v_do_not_pay_reason_codes,
          'amount_ex_vat', round(v_case_total_amount_ex_vat, 2),
          'amount_display', round(v_case_total_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = true and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := nullif(btrim(coalesce(v_case_state_timesheet_id, '')), '');
      if v_line_existing_line_id is not null then
        v_line_existing_line_id := v_line_existing_line_id || ':03:case';
      else
        v_line_existing_line_id := btrim(coalesce(v_template_base_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := 'case_resolution_required';
        end if;
        if right(v_line_existing_line_id, 8) <> ':03:case' then
          v_line_existing_line_id := v_line_existing_line_id || ':03:case';
        end if;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_case_state #> '{case_resolution_summary,blocked_reason_codes}') = 'array' then coalesce(v_case_state #> '{case_resolution_summary,blocked_reason_codes}', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_line_blocked_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'RESOLUTION_REQUIRED'
      ) then
        v_line_blocked_reason_codes := v_line_blocked_reason_codes || jsonb_build_array('RESOLUTION_REQUIRED');
      end if;

      v_new_line := (v_template_base_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'segment_rows'
        - 'segment_count'
        - 'section_amount_ex_vat'
        - 'section_amount_display'
        - 'section_segment_rows'
        - 'section_segment_count'
        - 'section_non_segment_amount_ex_vat'
        - 'presentation_advisory_text'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_parent_line_id', coalesce(nullif(v_case_state_timesheet_id, ''), v_line_existing_line_id),
          'real_business_timesheet_id', nullif(v_case_state_timesheet_id, ''),
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'is_excluded_from_allocation', false,
          'is_ready_for_draft', false,
          'draftable', false
        )
        || jsonb_build_object(
          'segment_rows', '[]'::jsonb,
          'segment_count', 0,
          'presentation_section', 'CASES_RESOLUTIONS',
          'presentation_role', 'PARENT',
          'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
          'presentation_advisory_text', 'Resolve this case before draft',
          'readiness_state', 'CASES_RESOLUTIONS'
        )
        || jsonb_build_object(
          'section_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'section_amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'section_segment_rows', '[]'::jsonb,
          'section_segment_count', 0,
          'section_non_segment_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = false and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_template_base_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;

      v_new_line := ((coalesce(v_template_blocked_line, v_template_base_line))
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'preview_row_id', '')), ''), v_line_existing_line_id),
          'line_id', v_line_existing_line_id,
          'presentation_line_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'presentation_line_id', '')), ''), v_line_existing_line_id),
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'CASE_BLOCKED',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', false,
          'is_excluded_from_allocation', false,
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    else
      if round(v_case_ready_amount_ex_vat, 2) <> 0 then
        v_line_existing_line_id := btrim(coalesce(v_template_ready_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key;
        end if;

        v_new_line := (v_template_ready_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'segment_rows'
          - 'segment_count'
          - 'section_amount_ex_vat'
          - 'section_amount_display'
          - 'section_segment_rows'
          - 'section_segment_count'
          - 'section_non_segment_amount_ex_vat'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'READY_TO_PAY',
            'presentation_reason', 'READY_TO_PAY',
            'readiness_state', 'READY_TO_PAY',
            'draftable', true,
            'is_ready_for_draft', true,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', '[]'::jsonb,
            'amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'amount_display', round(v_case_ready_amount_ex_vat, 2),
            'payment_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'source_pay_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_entitlement_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_reservation_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_reservation_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'section_amount_display', round(v_case_ready_amount_ex_vat, 2),
            'section_segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'section_segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_non_segment_amount_ex_vat', 0,
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;

      if round(v_case_blocked_amount_ex_vat, 2) <> 0 and v_case_state_needs_resolution = false then
        v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key || ':blocked';
        end if;
        if v_line_existing_line_id = btrim(coalesce(v_template_ready_line->>'line_id', '')) then
          v_line_existing_line_id := v_line_existing_line_id || ':blocked';
        end if;

        v_line_blocked_reason_codes := case
          when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
          when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
          else '[]'::jsonb
        end;

        v_new_line := (v_template_blocked_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'BLOCKED_FOR_PAY',
            'presentation_reason', 'CASE_BLOCKED',
            'readiness_state', 'BLOCKED_FOR_PAY',
            'draftable', false,
            'is_ready_for_draft', false,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', v_line_blocked_reason_codes,
            'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
            'amount_display', round(v_case_blocked_amount_ex_vat, 2),
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;
    end if;
  end loop;

  for v_line in
    select baseline_line.value
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));

    if v_line_case_key <> '' then
      if not exists (
        select 1
        from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
        where jsonb_typeof(rebuilt_line.value) = 'object'
          and btrim(coalesce(rebuilt_line.value->>'case_key', '')) = v_line_case_key
      ) then
        v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
      end if;
    elsif not exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
      where jsonb_typeof(rebuilt_line.value) = 'object'
        and btrim(coalesce(rebuilt_line.value->>'line_id', '')) = btrim(coalesce(v_line->>'line_id', ''))
    ) then
      v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
    end if;
  end loop;

  if jsonb_array_length(v_itemisation) > 0 then
    for v_item in
      select elem.value
      from jsonb_array_elements(v_itemisation) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      v_line_case_key := btrim(coalesce(v_item->>'case_key', ''));
      if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
        v_case_state_from_map := v_case_state_map->v_line_case_key;
        v_selected_case_line := null::jsonb;

        select line_choice.value
        into v_selected_case_line
        from (
          select
            line_elem.value,
            case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
              when 'CASES_RESOLUTIONS' then 0
              when 'READY_TO_PAY' then 1
              when 'BLOCKED_FOR_PAY' then 2
              when 'DO_NOT_PAY' then 3
              else 9
            end as sort_ord
          from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
          where jsonb_typeof(line_elem.value) = 'object'
            and btrim(coalesce(line_elem.value->>'case_key', '')) = v_line_case_key
        ) line_choice
        order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
        limit 1;

        if v_selected_case_line is not null then
          v_line_presentation_section := upper(btrim(coalesce(v_selected_case_line->>'presentation_section', '')));
          v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

          v_item := (v_item
            - 'preview_row_id'
            - 'line_id'
            - 'timesheet_id'
            - 'week_ending_date'
            - 'client_id'
            - 'client_name'
            - 'payment_amount_ex_vat'
            - 'payment_amount_inc_vat'
            - 'payment_amount'
            - 'source_pay_method'
            - 'candidate_pay_method'
            - 'segment_deltas'
            - 'presentation_section'
            - 'presentation_role'
            - 'total_segment_count'
            - 'ready_segment_count'
            - 'blocked_visible_segment_count'
            - 'hidden_indefinite_segment_count'
            - 'is_partially_ready'
            - 'is_partially_blocked'
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution'
            - 'excluded_from_pay'
            - 'is_do_not_pay')
            || jsonb_build_object(
              'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
              'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
              'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state_from_map->>'timesheet_id', '')), ''),
              'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state_from_map->>'week_ending_date', '')), ''),
              'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state_from_map->>'client_id', '')), ''),
              'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state_from_map->>'client_name', '')), ''),
              'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
              'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'source_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
              'candidate_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
              'segment_deltas', case
                when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
                when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            )
            || jsonb_build_object(
              'presentation_section', coalesce(v_selected_case_line->>'presentation_section', v_item->>'presentation_section'),
              'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
              'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
              'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
              'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
              'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
              'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
              'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false),
              'excluded_from_pay', (v_line_presentation_section = 'DO_NOT_PAY'),
              'is_do_not_pay', (v_line_presentation_section = 'DO_NOT_PAY')
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        else
          v_item := (v_item
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution')
            || jsonb_build_object(
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        end if;

        if upper(btrim(coalesce(v_case_state_from_map->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
          v_case_state_timesheet_id := btrim(coalesce(v_case_state_from_map->>'timesheet_id', ''));
          if v_case_state_timesheet_id <> '' and exists (
            select 1
            from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
            where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
          ) then
            v_item := v_item || jsonb_build_object('excluded_from_pay', true, 'is_do_not_pay', true);
          end if;
        end if;
      end if;
      v_updated_itemisation := v_updated_itemisation || jsonb_build_array(v_item);
    end loop;
  else
    v_updated_itemisation := v_itemisation;
  end if;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
      and upper(btrim(coalesce(elem.value->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT')
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_itemisation, '[]'::jsonb)) as item_elem(value)
      where jsonb_typeof(item_elem.value) = 'object'
        and btrim(coalesce(item_elem.value->>'case_key', '')) = v_case_state_case_key
    ) into v_itemisation_match_found;

    if v_itemisation_match_found then
      continue;
    end if;

    select line_choice.value
    into v_selected_case_line
    from (
      select
        line_elem.value,
        case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
          when 'CASES_RESOLUTIONS' then 0
          when 'READY_TO_PAY' then 1
          when 'BLOCKED_FOR_PAY' then 2
          when 'DO_NOT_PAY' then 3
          else 9
        end as sort_ord
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
      where jsonb_typeof(line_elem.value) = 'object'
        and btrim(coalesce(line_elem.value->>'case_key', '')) = v_case_state_case_key
    ) line_choice
    order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
    limit 1;

    if v_selected_case_line is null then
      continue;
    end if;

    v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

    v_itemisation_append_json := jsonb_build_object(
      'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
      'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
      'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state->>'timesheet_id', '')), ''),
      'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state->>'week_ending_date', '')), ''),
      'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state->>'client_id', '')), ''),
      'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state->>'client_name', '')), ''),
      'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
      'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'source_pay_method', nullif(btrim(coalesce(v_case_state->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
      'candidate_pay_method', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
      'segment_deltas', case
        when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
        when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
        else '[]'::jsonb
      end,
      'adjustment_deltas', '[]'::jsonb,
      'delta_additional_pay_ex_vat', 0,
      'additional_unit_deltas', '[]'::jsonb,
      'reservation_overrun_detected', false,
      'delta_expenses_pay_ex_vat', 0,
      'delta_travel_pay_ex_vat', 0,
      'delta_accommodation_pay_ex_vat', 0,
      'delta_other_pay_ex_vat', 0,
      'delta_mileage_pay_ex_vat', 0,
      'case_key', v_case_state_case_key,
      'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
      'components', coalesce(v_case_state->'components', '[]'::jsonb),
      'presentation_section', coalesce(v_selected_case_line->>'presentation_section', 'CASES_RESOLUTIONS'),
      'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
      'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
      'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
      'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
      'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
      'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
      'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false)
    );

    if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
      v_itemisation_append_json := v_itemisation_append_json || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
    end if;

    v_updated_itemisation := coalesce(v_updated_itemisation, '[]'::jsonb) || jsonb_build_array(v_itemisation_append_json);
  end loop;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'display_name', ''), coalesce(elem.value->>'line_type', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_updated_lines
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      (coalesce(elem.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((elem.value->>'amount_ex_vat')::numeric, 2) <> 0)
      or upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
    );


  if jsonb_array_length(coalesce(v_updated_lines, '[]'::jsonb)) = 0 and jsonb_array_length(coalesce(v_lines, '[]'::jsonb)) > 0 then
    select coalesce(jsonb_agg(baseline_line.value order by coalesce(baseline_line.value->>'candidate_id', ''), coalesce(baseline_line.value->>'display_name', ''), coalesce(baseline_line.value->>'line_type', ''), coalesce(baseline_line.value->>'line_id', '')), '[]'::jsonb)
    into v_updated_lines
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
      and (
        (coalesce(baseline_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((baseline_line.value->>'amount_ex_vat')::numeric, 2) <> 0)
        or upper(btrim(coalesce(baseline_line.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      );
  end if;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_blocked_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY';

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_do_not_pay_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      or coalesce((elem.value->>'is_do_not_pay')::boolean, false) = true
    );

  v_candidate_row := (coalesce(v_candidate_row, '{}'::jsonb)
    - 'case_resolution_states'
    - 'canonical_preview_lines'
    - 'itemisation'
    - 'blocked_items'
    - 'do_not_pay_items'
    - 'snoozed_items'
    - 'hidden_recovery_template_lines'
    - 'hidden_recovery_template_line_count')
    || jsonb_build_object(
      'candidate_id', v_candidate_id,
      'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
      'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
      'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
      'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
      'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
      'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
      'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count
    );

  return jsonb_build_object(
    'candidate_id', v_candidate_id,
    'candidate_row', coalesce(v_candidate_row, '{}'::jsonb),
    'summary_fragment', coalesce(v_summary_fragment, '{}'::jsonb),
    'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
    'canonical_preview_lines', coalesce(v_updated_lines, '[]'::jsonb),
    'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'payees', coalesce(v_payees, '[]'::jsonb),
    'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
    'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
    'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
    'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
    'baseline_component_rows', coalesce(v_final_component_rows, '[]'::jsonb),
    'timesheet_snapshots_json', coalesce(v_timesheet_snapshots_json, '[]'::jsonb)
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_preview_decisions_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_scope_candidate_id_text text := '';
  v_candidate_baseline_json jsonb := '{}'::jsonb;
  v_candidate_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
begin
  v_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => p_preview_decisions_json
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'pay_preview_build_context(...) must return a JSON object';
  end if;

  v_scope_candidate_ids := case
    when jsonb_typeof(v_context_json->'scope_candidate_ids') = 'array' then coalesce(v_context_json->'scope_candidate_ids', '[]'::jsonb)
    else '[]'::jsonb
  end;

  for v_scope_candidate_id_text in
    select btrim(scope_candidate.value)
    from jsonb_array_elements_text(v_scope_candidate_ids) as scope_candidate(value)
    where btrim(scope_candidate.value) <> ''
    order by btrim(scope_candidate.value)
  loop
    v_candidate_baseline_json := public.pay_preview_build_candidate_baseline(
      p_context_json => v_context_json,
      p_candidate_id => v_scope_candidate_id_text::uuid
    );

    v_candidate_effective_json := public.pay_preview_apply_candidate_overlay(
      p_candidate_baseline_json => v_candidate_baseline_json,
      p_case_resolutions_json => coalesce(v_context_json->'preview_case_resolutions', '{}'::jsonb),
      p_overrides_json => coalesce(v_context_json->'preview_decisions_json', '{}'::jsonb)
    );

    v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
      p_context_json => v_context_json,
      p_candidate_effective_json => v_candidate_effective_json
    );

    v_candidate_rollups_json := v_candidate_rollups_json || jsonb_build_array(v_candidate_rollup_json);
  end loop;

  return public.pay_preview_assemble_payload(
    p_context_json => v_context_json,
    p_candidate_rollups_json => v_candidate_rollups_json
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_canonical_lines(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;

  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_line_materialise_limit integer := 100;
  v_line_materialise_result jsonb := '{}'::jsonb;
  v_workbench_line_source_mode text := NULL::text;
  v_workbench_classifier_only boolean := false;
  v_source_build_mode boolean := false;
  v_source_build_context_required boolean := false;
  v_collect_called_inside_canonical boolean := false;
  v_collect_recollect_attempted boolean := false;
  v_collect_recollect_blocked boolean := false;
  v_canonical_started_at timestamptz := clock_timestamp();
  v_canonical_elapsed_ms numeric := 0;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;


  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_source_build_context_required := COALESCE(v_source_build_mode, false);


  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_line_materialise_limit := LEAST(GREATEST(COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit')::integer, 1), 100);
  ELSE
    v_line_materialise_limit := 100;
  END IF;

  v_workbench_line_source_mode := UPPER(NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_line_source_mode',
    v_context_json->>'line_source_mode',
    v_context_json#>>'{line_work,source_mode}',
    v_context_json#>>'{workbench,line_source_mode}',
    ''
  )), ''));

  v_workbench_classifier_only := COALESCE(v_workbench_line_source_mode, '') IN (
    'CLASSIFY_ONLY',
    'CLASSIFIER_ONLY',
    'LINE_SOURCE_CLASSIFY_ONLY',
    'CANONICAL_CLASSIFY_ONLY'
  );

  IF v_workbench_session_id IS NOT NULL AND COALESCE(v_workbench_classifier_only, false) IS NOT TRUE AND COALESCE(v_source_build_mode, false) IS NOT TRUE THEN
    v_line_materialise_result := public.pay_workbench_preview_rows_materialise_chunk(
      p_session_id => v_workbench_session_id,
      p_candidate_id => v_candidate_id,
      p_cursor_json => COALESCE(
        v_context_json->'line_materialise_cursor',
        v_context_json->'line_work_cursor',
        v_context_json#>'{line_work,cursor}',
        NULL::jsonb
      ),
      p_limit => v_line_materialise_limit
    );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'session_id', v_workbench_session_id::text,
      'row_backed_line_work', true,
      'canonical_display_rows_written', true,
      'canonical_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'ready_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'blocked_preview_line_count', 0,
      'hidden_recovery_template_line_count', 0,
      'manual_adjustment_carry_forward_line_count', 0,
      'next_cursor', v_line_materialise_result->'next_cursor',
      'has_more', COALESCE(NULLIF(v_line_materialise_result->>'has_more', '')::boolean, false),
      'materialise_result', COALESCE(v_line_materialise_result, '{}'::jsonb)
    );
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    v_collect_recollect_attempted := true;

    IF COALESCE(v_source_build_context_required, false) = true THEN
      v_collect_recollect_blocked := true;
      RAISE EXCEPTION 'SOURCE_BUILD_CANONICAL_REQUIRES_PRECOLLECTED_CONTEXT'
        USING DETAIL = 'WORKBENCH_CANDIDATE_SOURCE_BUILD canonical mode refuses to call pay_preview_candidate_collect_scope implicitly. Call pay_preview_candidate_collect_scope first with the bounded source-build payload.';
    END IF;

    v_collect_called_inside_canonical := true;
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.finance_case_resolution_rollup') is null then
    perform public.pay_preview_candidate_build_finance_case_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.hidden_recovery_template_lines, pg_temp.manual_adjustment_carry_forward_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup;

  create temporary table canonical_timesheet_lines on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tb.ts_booking_id as booking_id,
          tb.ts_role,
          tb.ts_band,
          tcr.client_id,
          tcr.ts_client_name as client_name,
          tcr.ts_week_ending_date as week_ending_date,
          tcr.ts_pay_method as source_pay_method,
          tcr.umb_vat_chargeable,
          cp.cand_pay_method as candidate_pay_method,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          cp.payee_bank_hash,
          cp.payee_name_check_status,
          cp.payee_name_check_has_override,
          cp.payee_map_present,
          coalesce(cp.blockers, '[]'::jsonb) as payee_blockers,
          (jsonb_array_length(coalesce(cp.blockers, '[]'::jsonb)) > 0) as has_payee_readiness_block,
          (cp.is_ready_for_draft and coalesce(tcr.is_blocked, false) = false) as is_ready_for_draft,
          ato.override_id,
          ato.override_reason,
          ats.snooze_id,
          ats.snooze_until_date,
          ats.note as snooze_note,
          round(coalesce(tcr.payment_amount_ex_vat,0),2) as amount_ex_vat,
          round(coalesce(tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, 0),2) as amount_display,
          coalesce(tcr.is_blocked, false) as case_is_blocked,
          coalesce(tcr.case_resolution_summary_json, '{}'::jsonb) as case_resolution_summary_json,
          coalesce(expense_components.expense_aware_case_components_json, tcr.case_components_json, '[]'::jsonb) as case_components_json,
          coalesce(expense_components.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(expense_components.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(expense_components.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(expense_components.ready_expense_count, 0) as ready_expense_count,
          coalesce(expense_components.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(expense_components.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(expense_components.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(expense_components.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                'segment_key', nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                'segment_stable_key', coalesce(
                  nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                ),
                'date', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')),
                'client_name', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'client_name','')), ''), tcr.ts_client_name),
                'role', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'role','')), ''), tb.ts_role),
                'band', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'band','')), ''), tb.ts_band),
                'start', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')),
                'finish', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'end_hhmm','')), '')),
                'start_utc', nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), ''),
                'end_utc', nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), ''),
                'break_start', nullif(btrim(coalesce(cur_seg.seg->>'break_start','')), ''),
                'break_end', nullif(btrim(coalesce(cur_seg.seg->>'break_end','')), ''),
                'break_mins', coalesce(nullif(cur_seg.seg->>'break_mins','')::numeric, nullif(cur_seg.seg->>'break_minutes','')::numeric),
                'breaks', coalesce(cur_seg.seg->'breaks', '[]'::jsonb),
                'ref_num', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')),
                'nhsp_shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'external_row_key', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'external_row_key','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'external_row_key','')), '')
                ),
                'hr_request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'source_system', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'source_system','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'source_system','')), '')
                ),
                'latest_import_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'latest_import_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'latest_import_id','')), '')
                ),
                'pay_amount_ex_vat', round(coalesce(nullif(delta_seg.seg->>'delta_pay_ex_vat','')::numeric,0),2),
                'snooze_identity', jsonb_build_object(
                  'identity_type', 'TIMESHEET_SEGMENT',
                  'timesheet_id', tcr.timesheet_id::text,
                  'booking_id', tb.ts_booking_id,
                  'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                  ),
                  'source_ref', null
                ),
                'snooze_state', case
                  when ass.snooze_id is null then jsonb_build_object('state','NONE')
                  when ass.snooze_until_date is null then jsonb_build_object(
                    'state', 'INDEFINITE_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', null,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                  else jsonb_build_object(
                    'state', 'DATED_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', ass.snooze_until_date::text,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                end
              )
              order by
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), '')) nulls last,
                nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') nulls last
            )
            from jsonb_array_elements(coalesce(tcr.segment_deltas_json, '[]'::jsonb)) as delta_seg(seg)
            left join lateral (
              select seg.value as seg
              from jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) as seg(value)
              where coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'date','')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num','')), '')
                    ) is not distinct from coalesce(
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_id','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')
                    )
              order by 1
              limit 1
            ) cur_seg on true
            left join active_segment_snoozes ass
              on ass.candidate_id = tcr.candidate_id
             and (
               (ass.booking_id is not null and ass.booking_id = tb.ts_booking_id and ass.segment_stable_key is not distinct from coalesce(
                 nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
               ))
               or (ass.booking_id is null and ass.timesheet_id = tcr.timesheet_id and ass.segment_id is not distinct from nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''))
             )
          ), '[]'::jsonb) as segment_rows_json
        from timesheet_case_rollup_effective tcr
        join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
        join ts_baseline tb
          on tb.timesheet_id = tcr.timesheet_id
         and tb.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_overrides ato
          on ato.timesheet_id = tcr.timesheet_id
         and ato.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_snoozes ats
          on ats.candidate_id = tcr.candidate_id
         and (
           (ats.booking_id is not null and ats.booking_id = tb.ts_booking_id)
           or (ats.booking_id is null and ats.timesheet_id = tcr.timesheet_id)
         )
        left join lateral (
          with component_rows as (
            select
              component_element.value as component_json,
              component_element.ordinality::integer as component_ordinal,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_type', '')), '')) as component_key_type,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_value', component_element.value#>>'{source_basis_json,expense_code}', '')), '')) as expense_code,
              case
                when jsonb_typeof(component_element.value->'source_basis_json') = 'object'
                  then coalesce(component_element.value->'source_basis_json', '{}'::jsonb)
                else '{}'::jsonb
              end as source_basis_json,
              lower(coalesce(
                nullif(btrim(coalesce(component_element.value->>'source_basis_fingerprint', '')), ''),
                md5(coalesce(component_element.value->'source_basis_json', '{}'::jsonb)::text)
              )) as source_basis_fingerprint,
              round(coalesce(
                case when coalesce(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'target_pay_ex_vat')::numeric else null::numeric end,
                0::numeric
              ), 2) as component_amount_ex_vat
            from jsonb_array_elements(
              case
                when jsonb_typeof(tcr.case_components_json) = 'array' then coalesce(tcr.case_components_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) with ordinality as component_element(value, ordinality)
          ), expense_identity_rows as (
            select
              component_rows.*,
              (
                component_rows.component_key_type = 'EXPENSE_CODE'
                and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
              ) as is_expense_component,
              case
                when component_rows.component_key_type = 'EXPENSE_CODE'
                 and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                 and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
                then lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  component_rows.expense_code || ':' || component_rows.source_basis_fingerprint
                )
                else null::text
              end as expense_source_ref,
              case component_rows.expense_code
                when 'EXPENSES' then 'Expenses'
                when 'TRAVEL' then 'Travel'
                when 'ACCOMMODATION' then 'Accommodation'
                when 'OTHER' then 'Other'
                when 'MILEAGE' then 'Mileage'
                else null::text
              end as expense_label
            from component_rows
          ), enriched_rows as (
            select
              expense_identity_rows.*,
              exact_snooze.snooze_id as exact_snooze_id,
              exact_snooze.snooze_until_date as exact_snooze_until_date,
              exact_snooze.note as exact_snooze_note,
              exact_snooze.snooze_kind as exact_snooze_kind,
              stale_snooze.snooze_id as stale_snooze_id,
              stale_snooze.source_ref as stale_source_ref,
              stale_snooze.snooze_until_date as stale_snooze_until_date,
              stale_snooze.note as stale_snooze_note
            from expense_identity_rows
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.snooze_until_date,
                active_snooze.note,
                active_snooze.snooze_kind
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) = expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as exact_snooze on true
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.source_ref,
                active_snooze.snooze_until_date,
                active_snooze.note
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and exact_snooze.snooze_id is null
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.timesheet_id = tcr.timesheet_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) like lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  expense_identity_rows.expense_code || ':%'
                )
                and lower(active_snooze.source_ref) is distinct from expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as stale_snooze on true
          ), state_rows as (
            select
              enriched_rows.*,
              case
                when not enriched_rows.is_expense_component then 'NOT_EXPENSE'
                when enriched_rows.exact_snooze_id is not null and enriched_rows.exact_snooze_until_date is null then 'HIDDEN_INDEFINITE'
                when enriched_rows.exact_snooze_id is not null then 'BLOCKED_DATED'
                when enriched_rows.stale_snooze_id is not null then 'BLOCKED_STALE_IDENTITY'
                else 'READY'
              end as expense_presentation_state
            from enriched_rows
          )
          select
            coalesce(
              jsonb_agg(
                case
                  when state_rows.is_expense_component then
                    state_rows.component_json
                    || jsonb_build_object(
                      'expense_code', state_rows.expense_code,
                      'expense_label', state_rows.expense_label,
                      'expense_item_type', case when state_rows.expense_code = 'MILEAGE' then 'MILEAGE_DELTA' else 'EXPENSE_DELTA' end,
                      'source_ref', state_rows.expense_source_ref,
                      'source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_json', state_rows.source_basis_json
                    )
                    || jsonb_build_object(
                      'presentation_section', case
                        when state_rows.expense_presentation_state = 'READY' then 'READY_TO_PAY'
                        when state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY') then 'BLOCKED_FOR_PAY'
                        else 'INTERNAL_ONLY'
                      end,
                      'expense_presentation_state', state_rows.expense_presentation_state,
                      'draftable', (state_rows.expense_presentation_state = 'READY'),
                      'is_ready_for_draft', (state_rows.expense_presentation_state = 'READY'),
                      'is_excluded_from_allocation', (state_rows.expense_presentation_state <> 'READY'),
                      'selection_allowed', (state_rows.expense_presentation_state = 'READY'),
                      'expense_identity_stale', (state_rows.expense_presentation_state = 'BLOCKED_STALE_IDENTITY')
                    )
                    || jsonb_build_object(
                      'snooze_identity', jsonb_build_object(
                        'identity_type', 'TIMESHEET_EXPENSE',
                        'timesheet_id', tcr.timesheet_id::text,
                        'booking_id', tb.ts_booking_id,
                        'segment_id', null,
                        'segment_stable_key', null,
                        'source_ref', state_rows.expense_source_ref,
                        'expense_code', state_rows.expense_code,
                        'source_basis_fingerprint', state_rows.source_basis_fingerprint
                      ),
                      'snooze_state', case
                        when state_rows.exact_snooze_id is null and state_rows.stale_snooze_id is null
                          then jsonb_build_object('state', 'NONE')
                        when state_rows.exact_snooze_id is not null and state_rows.exact_snooze_until_date is null
                          then jsonb_build_object(
                            'state', 'INDEFINITE_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', null,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        when state_rows.exact_snooze_id is not null
                          then jsonb_build_object(
                            'state', 'DATED_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', state_rows.exact_snooze_until_date::text,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        else jsonb_build_object(
                          'state', 'STALE_SOURCE_IDENTITY',
                          'snooze_id', state_rows.stale_snooze_id::text,
                          'snooze_until_date', case when state_rows.stale_snooze_until_date is null then null else state_rows.stale_snooze_until_date::text end,
                          'note', state_rows.stale_snooze_note,
                          'stale_source_ref', state_rows.stale_source_ref,
                          'refresh_required', true
                        )
                      end
                    )
                  else state_rows.component_json
                end
                order by state_rows.component_ordinal
              ),
              '[]'::jsonb
            ) as expense_aware_case_components_json,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            ), 0), 2) as ready_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            ), 0), 2) as blocked_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            ), 0), 2) as hidden_expense_amount_ex_vat,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            )::integer as ready_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            )::integer as blocked_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            )::integer as hidden_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.exact_snooze_id is not null
            )::integer as active_expense_snooze_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.stale_snooze_id is not null
            )::integer as stale_expense_identity_count
          from state_rows
        ) as expense_components on true
        where round(coalesce(tcr.payment_amount_ex_vat,0),2) <> 0
          and not (ats.snooze_id is not null and ats.snooze_until_date is null)
  
  ;

  create temporary table timesheet_active_segment_snooze_meta on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          count(*)::int as active_segment_snooze_count,
          count(*) filter (where ass.snooze_until_date is not null)::int as active_segment_dated_snooze_count,
          count(*) filter (where ass.snooze_until_date is null)::int as active_segment_indefinite_snooze_count
        from canonical_timesheet_lines ctl
        join active_segment_snoozes ass
          on ass.candidate_id = ctl.candidate_id
         and (
           (ass.booking_id is not null and ctl.booking_id is not null and ass.booking_id = ctl.booking_id)
           or (ass.booking_id is null and ass.timesheet_id = ctl.timesheet_id)
         )
        group by ctl.candidate_id, ctl.timesheet_id, ctl.booking_id
  
  ;

  create temporary table canonical_timesheet_segment_rows on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          cur_seg_norm.seg_ord,
          cur_seg_norm.segment_id,
          cur_seg_norm.segment_key,
          cur_seg_norm.segment_stable_key,
          cur_seg_norm.segment_date,
          cur_seg_norm.client_name,
          cur_seg_norm.role,
          cur_seg_norm.band,
          cur_seg_norm.start_hhmm,
          cur_seg_norm.finish_hhmm,
          cur_seg_norm.start_utc,
          cur_seg_norm.end_utc,
          cur_seg_norm.break_start,
          cur_seg_norm.break_end,
          cur_seg_norm.break_mins,
          cur_seg_norm.breaks,
          coalesce(cur_seg_norm.ref_num, ss_match.ref_num) as ref_num,
          round(
            case
              when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
              when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
              else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
            end,
            2
          ) as presentation_amount_ex_vat,
          round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) as raw_delta_ex_vat,
          round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) as effective_delta_ex_vat,
          coalesce(ss_match.is_blocked, false) as status_is_blocked,
          coalesce(ss_match.is_do_not_pay, false) as status_is_do_not_pay,
          ass_match.snooze_id as segment_snooze_id,
          ass_match.snooze_until_date as segment_snooze_until_date,
          ass_match.note as segment_snooze_note,
          ass_match.snooze_kind as segment_snooze_kind,
          case
            when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
            when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_blocked, false) = true
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'BLOCKED_VISIBLE'
            when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'READY'
            else 'IGNORED'
          end as presentation_segment_state,
          jsonb_build_object(
            'timesheet_id', ctl.timesheet_id::text,
            'booking_id', ctl.booking_id,
            'segment_id', cur_seg_norm.segment_id,
            'segment_key', cur_seg_norm.segment_key,
            'segment_stable_key', cur_seg_norm.segment_stable_key,
            'date', cur_seg_norm.segment_date,
            'client_name', cur_seg_norm.client_name,
            'role', cur_seg_norm.role,
            'band', cur_seg_norm.band,
            'start', cur_seg_norm.start_hhmm,
            'finish', cur_seg_norm.finish_hhmm,
            'start_utc', cur_seg_norm.start_utc,
            'end_utc', cur_seg_norm.end_utc,
            'break_start', cur_seg_norm.break_start,
            'break_end', cur_seg_norm.break_end,
            'break_mins', cur_seg_norm.break_mins,
            'breaks', cur_seg_norm.breaks,
            'ref_num', coalesce(cur_seg_norm.ref_num, ss_match.ref_num),
            'nhsp_shift_id', cur_seg_norm.nhsp_shift_id,
            'shift_id', cur_seg_norm.shift_id,
            'external_row_key', cur_seg_norm.external_row_key,
            'hr_request_id', cur_seg_norm.hr_request_id,
            'request_id', cur_seg_norm.request_id,
            'source_system', cur_seg_norm.source_system,
            'latest_import_id', cur_seg_norm.latest_import_id,
            'pay_amount_ex_vat', round(
              case
                when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
                when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
                else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
              end,
              2
            ),
            'raw_delta_ex_vat', round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2),
            'effective_delta_ex_vat', round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2),
            'is_blocked', coalesce(ss_match.is_blocked, false),
            'is_do_not_pay', coalesce(ss_match.is_do_not_pay, false),
            'presentation_segment_state', case
              when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
              when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_blocked, false) = true
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'BLOCKED_VISIBLE'
              when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'READY'
              else 'IGNORED'
            end,
            'is_ready_segment', (
              ass_match.snooze_id is null
              and coalesce(ss_match.is_blocked, false) = false
              and coalesce(ss_match.is_do_not_pay, false) = false
              and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              and round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
            ),
            'is_blocked_visible_segment', (
              (ass_match.snooze_id is not null and ass_match.snooze_until_date is not null)
              or (
                coalesce(ss_match.is_blocked, false) = true
                and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              )
              or coalesce(ss_match.is_do_not_pay, false) = true
            ),
            'is_hidden_indefinite_segment', (ass_match.snooze_id is not null and ass_match.snooze_until_date is null),
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', ctl.timesheet_id::text,
              'booking_id', ctl.booking_id,
              'segment_id', cur_seg_norm.segment_id,
              'segment_stable_key', cur_seg_norm.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', case
              when ass_match.snooze_id is null then jsonb_build_object('state', 'NONE')
              when ass_match.snooze_until_date is null then jsonb_build_object(
                'state', 'INDEFINITE_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', null,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
              else jsonb_build_object(
                'state', 'DATED_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', ass_match.snooze_until_date::text,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
            end
          ) as segment_base_json
        from canonical_timesheet_lines ctl
        join ts_baseline tb
          on tb.timesheet_id = ctl.timesheet_id
         and tb.candidate_id = ctl.candidate_id
        cross join lateral jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg_json, seg_ord)
        cross join lateral (
          select
            cur_seg.seg_ord,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), '') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), '') as segment_key,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_stable_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '')
            ) as segment_stable_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), '') as segment_date,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'client_name','')), ''), ctl.client_name) as client_name,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'role','')), ''), ctl.ts_role) as role,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'band','')), ''), ctl.ts_band) as band,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'start_hhmm','')), '')) as start_hhmm,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'end_hhmm','')), '')) as finish_hhmm,
            nullif(btrim(coalesce(cur_seg.seg_json->>'start_utc','')), '') as start_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'end_utc','')), '') as end_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_start','')), '') as break_start,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_end','')), '') as break_end,
            coalesce(nullif(cur_seg.seg_json->>'break_mins','')::numeric, nullif(cur_seg.seg_json->>'break_minutes','')::numeric) as break_mins,
            case when jsonb_typeof(cur_seg.seg_json->'breaks') = 'array' then cur_seg.seg_json->'breaks' else '[]'::jsonb end as breaks,
            nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '') as ref_num,
            nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '') as nhsp_shift_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'shift_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '')
            ) as shift_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'external_row_key','')), '') as external_row_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '') as hr_request_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'request_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '')
            ) as request_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'source_system','')), '') as source_system,
            nullif(btrim(coalesce(cur_seg.seg_json->>'latest_import_id','')), '') as latest_import_id
        ) cur_seg_norm
        left join lateral (
          select
            ss.segment_id,
            ss.segment_stable_key,
            ss.ref_num,
            ss.work_date,
            ss.delta_pay_ex_vat,
            ss.eff_delta_ex,
            ss.is_blocked,
            ss.is_do_not_pay
          from segment_status ss
          where ss.candidate_id = ctl.candidate_id
            and ss.timesheet_id = ctl.timesheet_id
            and (
              (cur_seg_norm.segment_stable_key is not null and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and ss.segment_id is not distinct from cur_seg_norm.segment_id
              )
            )
          order by
            case
              when cur_seg_norm.segment_stable_key is not null
               and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key
              then 0 else 1
            end,
            case
              when cur_seg_norm.segment_id is not null
               and ss.segment_id is not distinct from cur_seg_norm.segment_id
              then 0 else 1
            end,
            ss.segment_stable_key nulls last,
            ss.segment_id nulls last
          limit 1
        ) ss_match on true
        left join lateral (
          select
            round(sum(coalesce(ttre.preview_component_amount_ex_vat, 0)), 2) as preview_component_amount_ex_vat,
            round(sum(coalesce(ttre.ready_preview_amount_ex_vat, ttre.preview_component_amount_ex_vat, 0)), 2) as ready_preview_amount_ex_vat,
            bool_or(coalesce(ttre.requires_resolution, false)) as requires_resolution,
            bool_or(coalesce(ttre.is_actionable_resolution_row, false)) as is_actionable_resolution_row
          from transient_timesheet_component_review_rows_effective ttre
          where ttre.candidate_id = ctl.candidate_id
            and ttre.timesheet_id = ctl.timesheet_id
            and ttre.component_key_type in ('TS_DAY','TS_TOTAL')
            and (
              (
                cur_seg_norm.segment_stable_key is not null
                and coalesce(
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'work_date','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'ref_num','')), '')
                ) is not distinct from cur_seg_norm.segment_stable_key
              )
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), '') is not distinct from cur_seg_norm.segment_id
              )
            )
        ) ttre_match on true
        left join lateral (
          select
            ass.snooze_id,
            ass.snooze_until_date,
            ass.note,
            ass.snooze_kind,
            ass.segment_id,
            ass.segment_stable_key
          from active_segment_snoozes ass
          where ass.candidate_id = ctl.candidate_id
            and (
              (
                ass.booking_id is not null
                and ctl.booking_id is not null
                and ass.booking_id = ctl.booking_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
              or (
                ass.booking_id is null
                and ass.timesheet_id = ctl.timesheet_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
            )
          order by
            case when ass.segment_stable_key is not null then 0 else 1 end,
            ass.snooze_id
          limit 1
        ) ass_match on true
        where (
          ass_match.snooze_id is not null
          or coalesce(ss_match.is_blocked, false) = true
          or coalesce(ss_match.is_do_not_pay, false) = true
          or round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
          or round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) <> 0
        )
  
  ;

  create temporary table canonical_timesheet_segment_rollup on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          coalesce(tasm.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(tasm.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(tasm.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          count(*) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE'))::int as total_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'READY')::int as ready_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE')::int as blocked_visible_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE')::int as hidden_indefinite_segment_count,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'READY' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as ready_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'BLOCKED_VISIBLE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as blocked_visible_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'READY'),
            '[]'::jsonb
          ) as ready_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE'),
            '[]'::jsonb
          ) as blocked_visible_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE')),
            '[]'::jsonb
          ) as visible_segment_rows_json
        from canonical_timesheet_lines ctl
        left join timesheet_active_segment_snooze_meta tasm
          on tasm.candidate_id = ctl.candidate_id
         and tasm.timesheet_id = ctl.timesheet_id
         and tasm.booking_id is not distinct from ctl.booking_id
        left join canonical_timesheet_segment_rows ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
        group by
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.snooze_id,
          tasm.active_segment_snooze_count,
          tasm.active_segment_dated_snooze_count,
          tasm.active_segment_indefinite_snooze_count
  
  ;

  create temporary table canonical_timesheet_presentation_seed on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.ts_role,
          ctl.ts_band,
          ctl.client_id,
          ctl.client_name,
          ctl.week_ending_date,
          ctl.source_pay_method,
          ctl.umb_vat_chargeable,
          ctl.candidate_pay_method,
          ctl.cand_tms_ref,
          ctl.cand_display_name,
          ctl.payee_entity_kind,
          ctl.payee_entity_id,
          ctl.payee_bank_hash,
          ctl.payee_name_check_status,
          ctl.payee_name_check_has_override,
          ctl.payee_map_present,
          coalesce(ctl.payee_blockers, '[]'::jsonb) as payee_blockers,
          coalesce(ctl.has_payee_readiness_block, false) as has_payee_readiness_block,
          ctl.is_ready_for_draft,
          ctl.override_id,
          ctl.override_reason,
          ctl.snooze_id,
          ctl.snooze_until_date,
          ctl.snooze_note,
          ctl.amount_ex_vat,
          ctl.amount_display,
          ctl.case_is_blocked,
          ctl.case_resolution_summary_json,
          ctl.case_components_json,
          coalesce(ctl.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(ctl.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(ctl.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(ctl.ready_expense_count, 0) as ready_expense_count,
          coalesce(ctl.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(ctl.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(ctl.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(ctl.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce(ctsr.total_segment_count, 0) as total_segment_count,
          coalesce(ctsr.ready_segment_count, 0) as ready_segment_count,
          coalesce(ctsr.blocked_visible_segment_count, 0) as blocked_visible_segment_count,
          coalesce(ctsr.hidden_indefinite_segment_count, 0) as hidden_indefinite_segment_count,
          coalesce(ctsr.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(ctsr.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(ctsr.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          coalesce(ctsr.ready_segment_amount_ex_vat, 0) as ready_segment_amount_ex_vat,
          coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0) as blocked_visible_segment_amount_ex_vat,
          coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(ctsr.ready_segment_rows_json, '[]'::jsonb) as ready_segment_rows_json,
          coalesce(ctsr.blocked_visible_segment_rows_json, '[]'::jsonb) as blocked_visible_segment_rows_json,
          coalesce(ctsr.visible_segment_rows_json, '[]'::jsonb) as visible_segment_rows_json,
          (
            coalesce(ctsr.total_segment_count, 0) > 0
            and (
              lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or (
                coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
              )
            )
          ) as resolved_segment_rows_replace_source_total,
          case
            when coalesce(ctsr.total_segment_count, 0) > 0
             and (
               lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or (
                 coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                 and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
               )
             ) then round(coalesce(ctl.ready_expense_amount_ex_vat, 0), 2)
            else round(
              coalesce(ctl.amount_ex_vat, 0)
              - coalesce(ctsr.ready_segment_amount_ex_vat, 0)
              - coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0)
              - coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0)
              - coalesce(ctl.blocked_expense_amount_ex_vat, 0)
              - coalesce(ctl.hidden_expense_amount_ex_vat, 0),
              2
            )
          end as non_segment_amount_ex_vat,
          (ctl.snooze_id is not null) as has_active_timesheet_snooze,
          (coalesce(ctsr.active_segment_snooze_count, 0) > 0) as has_active_segment_snoozes
        from canonical_timesheet_lines ctl
        left join canonical_timesheet_segment_rollup ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
         and ctsr.booking_id is not distinct from ctl.booking_id
  
  ;

  create temporary table canonical_timesheet_presentation_state on commit drop as
        select
          ctps.*,
          coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) as case_needs_resolution,
          exists (
            select 1
            from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as case_component(value)
            where coalesce(nullif(case_component.value->>'requires_resolution','')::boolean, false) = true
              and coalesce(nullif(case_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
          ) as has_actionable_resolution_component,
          round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) as ready_section_amount_ex_vat,
          round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2) as blocked_section_amount_ex_vat,
          round(
            coalesce(
              nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
              0::numeric
            ),
            2
          ) as case_resolution_section_amount_ex_vat,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2),
                  v_vat_rate_pct,
                  ctps.umb_vat_chargeable
                )->>'inc')::numeric
              else round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2)
            end,
            2
          ) as ready_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2), v_vat_rate_pct, ctps.umb_vat_chargeable)->>'inc')::numeric
              else round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2)
            end,
            2
          ) as blocked_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(
                round(
                  coalesce(
                    nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                    0::numeric
                  ),
                  2
                ),
                v_vat_rate_pct,
                ctps.umb_vat_chargeable
              )->>'inc')::numeric
              else round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              )
            end,
            2
          ) as case_resolution_section_amount_display,
          (
            round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
            or coalesce(ctps.ready_segment_count, 0) > 0
          ) as has_ready_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.is_ready_for_draft = false
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
            and (
              ctps.case_is_blocked = false
              or coalesce(ctps.has_payee_readiness_block, false) = true
            )
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
          ) as has_non_resolution_readiness_block,
          (
            ctps.has_active_timesheet_snooze = true
            or coalesce(ctps.blocked_visible_segment_count, 0) > 0
            or coalesce(ctps.blocked_expense_count, 0) > 0
            or (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_blocked_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = true
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = true
            and (
              round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              ) <> 0
              or exists (
                select 1
                from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as actionable_component(value)
                where coalesce(nullif(actionable_component.value->>'requires_resolution','')::boolean, false) = true
                  and coalesce(nullif(actionable_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
              )
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) = 0
            and not (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_case_resolution_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_ready,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_blocked
        from canonical_timesheet_presentation_seed ctps

  ;

  create temporary table canonical_timesheet_presentation_rows on commit drop as
        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
