      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF (
       (TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets')
       OR (TG_OP IN ('INSERT', 'UPDATE') AND v_trigger_table = 'timesheets_financials')
     )
     AND (v_material_live_source_changed IS TRUE OR v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN
    SELECT COALESCE(array_agg(DISTINCT rotation_scope.family_timesheet_id ORDER BY rotation_scope.family_timesheet_id), ARRAY[]::uuid[])
    INTO v_signal_timesheet_ids
    FROM public._pay_timesheet_rotation_scope(
      ARRAY[COALESCE(v_new_timesheet_id, v_old_timesheet_id)]::uuid[]
    ) AS rotation_scope
    WHERE rotation_scope.family_timesheet_id IS NOT NULL;

    IF COALESCE(array_length(v_signal_timesheet_ids, 1), 0) = 0
       AND COALESCE(v_new_timesheet_id, v_old_timesheet_id) IS NOT NULL THEN
      v_signal_timesheet_ids := ARRAY[COALESCE(v_new_timesheet_id, v_old_timesheet_id)]::uuid[];
    END IF;

    SELECT COALESCE(array_agg(DISTINCT candidate_scope.candidate_id ORDER BY candidate_scope.candidate_id), ARRAY[]::uuid[])
    INTO v_signal_candidate_ids
    FROM (
      SELECT CASE
        WHEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re
          THEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS candidate_id
      UNION ALL
      SELECT CASE
        WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re
          THEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
        ELSE NULL::uuid
      END
      UNION ALL
      SELECT financial_row.candidate_id
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
      UNION ALL
      SELECT contract_row.candidate_id
      FROM public.timesheets AS timesheet_row
      JOIN public.contracts AS contract_row
        ON contract_row.id = timesheet_row.contract_id
      WHERE timesheet_row.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
    ) AS candidate_scope
    WHERE candidate_scope.candidate_id IS NOT NULL;

    v_signal_reason := CASE
      WHEN v_archive_boundary_changed IS TRUE
           AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL
        THEN 'TIMESHEET_ARCHIVED_LIVE_SOURCE_CHANGED'
      WHEN v_archive_boundary_changed IS TRUE
        THEN 'TIMESHEET_UNARCHIVED_LIVE_SOURCE_CHANGED'
      WHEN v_authorise_boundary_changed IS TRUE
           AND (
             NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
             OR NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NOT NULL
           )
        THEN 'TIMESHEET_UNAUTHORISED_LIVE_SOURCE_CHANGED'
      WHEN v_authorise_boundary_changed IS TRUE
        THEN 'TIMESHEET_AUTHORISED_LIVE_SOURCE_CHANGED'
      ELSE 'TIMESHEET_MATERIAL_LIVE_SOURCE_CHANGED'
    END;

    FOR v_signal_batch_row IN
      SELECT DISTINCT pay_batch.id AS pay_batch_id
      FROM public.pay_batches AS pay_batch
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = pay_batch.id
       AND batch_candidate.candidate_id = ANY(COALESCE(v_signal_candidate_ids, ARRAY[]::uuid[]))
      WHERE UPPER(BTRIM(COALESCE(pay_batch.status, ''))) = 'DRAFT'
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS batch_item
          LEFT JOIN public.pay_advances AS finance_case
            ON finance_case.id = batch_item.finance_case_id
          WHERE batch_item.pay_batch_candidate_id = batch_candidate.id
            AND batch_item.is_voided IS NOT TRUE
            AND (
              batch_item.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
              OR finance_case.linked_timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
            )
        )
      ORDER BY pay_batch.id
    LOOP
      BEGIN
        v_signal_result := public.banking_pay_batch_signal_touch(
          p_pay_batch_id => v_signal_batch_row.pay_batch_id,
          p_change_reason => v_signal_reason,
          p_change_source => 'pay_workbench_mark_candidate_dirty',
          p_change_scope_json => jsonb_build_object(
            'stale_hint', true,
            'stale_reason', v_signal_reason,
            'candidate_ids', COALESCE(to_jsonb(v_signal_candidate_ids), '[]'::jsonb),
            'timesheet_ids', COALESCE(to_jsonb(v_signal_timesheet_ids), '[]'::jsonb),
            'trigger_table', v_trigger_table,
            'trigger_operation', TG_OP,
            'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
          ),
          p_touch_payment_status => false,
          p_touch_correction_progress => false,
          p_touch_alerts => true,
          p_touch_overview => true
        );
      EXCEPTION
        WHEN OTHERS THEN
          v_signal_result := jsonb_build_object(
            'ok', false,
            'error_code', SQLSTATE,
            'error_message', SQLERRM,
            'pay_batch_id', v_signal_batch_row.pay_batch_id::text
          );
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'lightweight_draft_stale_signal_failed_non_blocking',
              'pay_batch_id', v_signal_batch_row.pay_batch_id::text,
              'signal_reason', v_signal_reason,
              'error_code', SQLSTATE,
              'error_message', SQLERRM,
              'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
            )
          );
      END;
    END LOOP;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        FOR v_signal_batch_row IN
          SELECT DISTINCT pay_batch.id AS pay_batch_id
          FROM public.pay_batches AS pay_batch
          JOIN public.pay_batch_candidates AS batch_candidate
            ON batch_candidate.pay_batch_id = pay_batch.id
           AND batch_candidate.candidate_id = NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
          WHERE UPPER(BTRIM(COALESCE(pay_batch.status, ''))) = 'DRAFT'
          ORDER BY pay_batch.id
        LOOP
          BEGIN
            v_signal_result := public.banking_pay_batch_signal_touch(
              p_pay_batch_id => v_signal_batch_row.pay_batch_id,
              p_change_reason => 'CANDIDATE_PAY_METHOD_CHANGED',
              p_change_source => 'pay_workbench_mark_candidate_dirty',
              p_change_scope_json => jsonb_build_object(
                'stale_hint', true,
                'stale_reason', 'CANDIDATE_PAY_METHOD_CHANGED',
                'candidate_ids', jsonb_build_array(NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')),
                'source_pay_method', v_route_source_method,
                'target_pay_method', v_route_target_method,
                'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
                'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
              ),
              p_touch_payment_status => false,
              p_touch_correction_progress => false,
              p_touch_alerts => true,
              p_touch_overview => true
            );
          EXCEPTION
            WHEN OTHERS THEN
              v_signal_result := jsonb_build_object(
                'ok', false,
                'error_code', SQLSTATE,
                'error_message', SQLERRM,
                'pay_batch_id', v_signal_batch_row.pay_batch_id::text
              );
              PERFORM public._temp_diag_log(
                'TEMP_TRIGGER_DIRTY_STAGE',
                'TEMP_BANKING_PAY_DIRTY',
                NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), ''),
                jsonb_build_object(
                  'function_name', 'pay_workbench_mark_candidate_dirty',
                  'stage', 'candidate_route_draft_stale_signal_failed_non_blocking',
                  'pay_batch_id', v_signal_batch_row.pay_batch_id::text,
                  'error_code', SQLSTATE,
                  'error_message', SQLERRM,
                  'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
                )
              );
          END;
        END LOOP;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;


REVOKE ALL ON FUNCTION public.pay_workbench_mark_candidate_dirty() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pay_workbench_mark_candidate_dirty() TO service_role;



CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_projection_contract()
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_projection_version integer := 4;
  v_hidden_recovery_template_projection_version integer := 1;
  v_requires_hidden_recovery_templates boolean := true;
BEGIN
  RETURN jsonb_build_object(
    'projection_version', v_projection_version,
    'hidden_recovery_template_projection_version', v_hidden_recovery_template_projection_version,
    'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_batch_item_source_reservation_amount_ex_vat(p_pay_batch_item_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pay_batch_id uuid;
  v_timesheet_id uuid;
  v_item_type text;
  v_finance_case_id uuid;
  v_finance_component_id uuid;
  v_amount_ex_vat numeric;
  v_frozen_source_amount numeric;
  v_frozen_target_amount_ex_vat numeric;
  v_frozen_resolution_mode public.pay_finance_component_resolution_mode_enum;
  v_frozen_resolution_payload_json jsonb;
  v_frozen_resolution_result_json jsonb;
  v_frozen_component_key_type text;
  v_frozen_component_key_value text;
  v_frozen_component_snapshot_json jsonb;
  v_frozen_source_basis_json jsonb;
  v_single_breakdown_meta_json jsonb := '{}'::jsonb;
  v_breakdown_count integer := 0;
  v_breakdown_source_amount_ex_vat numeric;
  v_breakdown_source_component_count integer := 0;
  v_resolved_key_type text;
  v_resolved_key_value text;
  v_key_resolution_failure_reason text;
  v_source_text text;
  v_has_source_target_split boolean;
BEGIN
  IF p_pay_batch_item_id IS NULL THEN
    RETURN NULL::numeric(12,2);
  END IF;

  SELECT
    pay_batch_candidate_row.pay_batch_id,
    pay_batch_item_row.timesheet_id,
    UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_row.item_type, '')), '')),
    pay_batch_item_row.finance_case_id,
    pay_batch_item_row.finance_component_id,
    pay_batch_item_row.amount_ex_vat,
    pay_batch_item_row.frozen_source_amount,
    pay_batch_item_row.frozen_target_amount_ex_vat,
    pay_batch_item_row.frozen_resolution_mode,
    pay_batch_item_row.frozen_resolution_payload_json,
    pay_batch_item_row.frozen_resolution_result_json,
    pay_batch_item_row.frozen_component_key_type,
    pay_batch_item_row.frozen_component_key_value,
    CASE
      WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)) = 'object'
        THEN COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END,
    CASE
      WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)) = 'object'
        THEN COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END
  INTO
    v_pay_batch_id,
    v_timesheet_id,
    v_item_type,
    v_finance_case_id,
    v_finance_component_id,
    v_amount_ex_vat,
    v_frozen_source_amount,
    v_frozen_target_amount_ex_vat,
    v_frozen_resolution_mode,
    v_frozen_resolution_payload_json,
    v_frozen_resolution_result_json,
    v_frozen_component_key_type,
    v_frozen_component_key_value,
    v_frozen_component_snapshot_json,
    v_frozen_source_basis_json
  FROM public.pay_batch_items AS pay_batch_item_row
  JOIN public.pay_batch_candidates AS pay_batch_candidate_row
    ON pay_batch_candidate_row.id = pay_batch_item_row.pay_batch_candidate_id
  WHERE pay_batch_item_row.id = p_pay_batch_item_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_item_type NOT IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA') THEN
    RETURN NULL::numeric(12,2);
  END IF;

  SELECT
    COUNT(*)::integer,
    CASE
      WHEN COUNT(*) = 1 THEN (ARRAY_AGG(breakdown_row.meta_json ORDER BY breakdown_row.id))[1]
      ELSE '{}'::jsonb
    END
  INTO
    v_breakdown_count,
    v_single_breakdown_meta_json
  FROM public.pay_batch_item_breakdowns AS breakdown_row
  WHERE breakdown_row.pay_batch_item_id = p_pay_batch_item_id;

  IF jsonb_typeof(COALESCE(v_single_breakdown_meta_json, '{}'::jsonb)) <> 'object' THEN
    v_single_breakdown_meta_json := '{}'::jsonb;
  END IF;

  SELECT
    resolved_key_row.key_type,
    resolved_key_row.key_value,
    resolved_key_row.key_resolution_failure_reason
  INTO
    v_resolved_key_type,
    v_resolved_key_value,
    v_key_resolution_failure_reason
  FROM public._pay_policy_x_resolve_post_draft_economic_key(
    p_pay_batch_item_id => p_pay_batch_item_id,
    p_pay_batch_id => v_pay_batch_id,
    p_timesheet_id => v_timesheet_id,
    p_item_type => v_item_type,
    p_frozen_key_type => v_frozen_component_key_type,
    p_frozen_key_value => v_frozen_component_key_value,
    p_frozen_component_snapshot_json => v_frozen_component_snapshot_json,
    p_frozen_source_basis_json => v_frozen_source_basis_json,
    p_breakdown_meta_json => v_single_breakdown_meta_json,
    p_target_snapshot_json => NULL::jsonb
  ) AS resolved_key_row
  LIMIT 1;

  IF v_key_resolution_failure_reason IS NOT NULL
     OR v_resolved_key_type IS NULL
     OR BTRIM(COALESCE(v_resolved_key_type, '')) = ''
     OR v_resolved_key_value IS NULL
     OR BTRIM(COALESCE(v_resolved_key_value, '')) = ''
     OR (v_resolved_key_type = 'TS_DAY' AND v_resolved_key_value !~ '^\d{4}-\d{2}-\d{2}$') THEN
    RETURN NULL::numeric(12,2);
  END IF;

  v_has_source_target_split :=
       v_finance_case_id IS NOT NULL
    OR v_finance_component_id IS NOT NULL
    OR v_frozen_target_amount_ex_vat IS NOT NULL
    OR v_frozen_resolution_mode IS NOT NULL
    OR v_frozen_resolution_payload_json IS NOT NULL
    OR v_frozen_resolution_result_json IS NOT NULL
    OR v_frozen_component_snapshot_json ? 'target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'frozen_target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_rate'
    OR v_frozen_component_snapshot_json ? 'target_units'
    OR v_frozen_component_snapshot_json ? 'resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_payload_json'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_result_json';

  IF v_has_source_target_split THEN
    WITH breakdown_source_rows AS (
      SELECT
        (
          SELECT source_candidates.source_text_value::numeric
          FROM (
            VALUES
              (breakdown_row.meta_json->>'source_reservation_amount_ex_vat'),
              (breakdown_row.meta_json->>'source_entitlement_amount_ex_vat'),
              (breakdown_row.meta_json->>'source_amount_ex_vat'),
              (breakdown_row.meta_json->>'source_pay_ex_vat'),
              (breakdown_row.meta_json->>'source_pay_amount_ex_vat'),
              (breakdown_row.meta_json->>'basis_source_amount_ex_vat'),
              (breakdown_row.meta_json->>'reserved_source_amount'),
              (breakdown_row.meta_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,source_pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{source_basis_json,amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_reservation_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_entitlement_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,basis_source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,reserved_source_amount}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,source_reservation_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,source_entitlement_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,source_pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,source_pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,basis_source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{case_component_json,source_basis_json,amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_payload_json,source_reservation_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_payload_json,source_entitlement_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_payload_json,source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_payload_json,source_pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_payload_json,source_pay_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_result_json,source_reservation_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_result_json,source_entitlement_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_result_json,source_amount_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_result_json,source_pay_ex_vat}'),
              (breakdown_row.meta_json#>>'{resolution_result_json,source_pay_amount_ex_vat}')
          ) AS source_candidates(source_text_value)
          WHERE source_candidates.source_text_value IS NOT NULL
            AND BTRIM(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
          LIMIT 1
        ) AS source_amount_ex_vat
      FROM public.pay_batch_item_breakdowns AS breakdown_row
      WHERE breakdown_row.pay_batch_item_id = p_pay_batch_item_id
    )
    SELECT
      COUNT(*)::integer,
      (COUNT(*) FILTER (WHERE breakdown_source_rows.source_amount_ex_vat IS NOT NULL))::integer,
      CASE
        WHEN COUNT(*) > 0
         AND COUNT(*) FILTER (WHERE breakdown_source_rows.source_amount_ex_vat IS NOT NULL) = COUNT(*)
          THEN ROUND(ABS(SUM(breakdown_source_rows.source_amount_ex_vat)), 2)::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END
    INTO
      v_breakdown_count,
      v_breakdown_source_component_count,
      v_breakdown_source_amount_ex_vat
    FROM breakdown_source_rows;

    IF COALESCE(v_breakdown_count, 0) > 0
       AND COALESCE(v_breakdown_source_component_count, 0) = COALESCE(v_breakdown_count, 0)
       AND v_breakdown_source_amount_ex_vat IS NOT NULL THEN
      RETURN v_breakdown_source_amount_ex_vat;
    END IF;
  END IF;

  IF v_frozen_source_amount IS NOT NULL THEN
    RETURN ROUND(ABS(v_frozen_source_amount), 2)::numeric(12,2);
  END IF;

  IF v_has_source_target_split THEN
    SELECT source_candidates.source_text_value
    INTO v_source_text
    FROM (
      VALUES
        (v_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
        (v_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
        (v_frozen_component_snapshot_json->>'source_amount_ex_vat'),
        (v_frozen_component_snapshot_json->>'source_pay_ex_vat'),
        (v_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
        (v_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
        (v_frozen_component_snapshot_json->>'reserved_source_amount'),
        (v_frozen_component_snapshot_json->>'frozen_source_amount'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_amount_ex_vat}'),
        (v_frozen_component_snapshot_json#>>'{source_basis_json,amount_ex_vat}'),
        (v_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
        (v_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
        (v_frozen_source_basis_json->>'source_amount_ex_vat'),
        (v_frozen_source_basis_json->>'source_pay_ex_vat'),
        (v_frozen_source_basis_json->>'source_pay_amount_ex_vat'),
        (v_frozen_source_basis_json->>'basis_source_amount_ex_vat'),
        (v_frozen_source_basis_json->>'reserved_source_amount'),
        (v_frozen_source_basis_json->>'frozen_source_amount'),
        (v_frozen_source_basis_json->>'pay_ex_vat'),
        (v_frozen_source_basis_json->>'pay_amount_ex_vat'),
        (v_frozen_source_basis_json->>'amount_ex_vat'),
        (v_frozen_source_basis_json->>'pay_amount'),
        (v_frozen_resolution_payload_json->>'source_reservation_amount_ex_vat'),
        (v_frozen_resolution_payload_json->>'source_entitlement_amount_ex_vat'),
        (v_frozen_resolution_payload_json->>'source_amount_ex_vat'),
        (v_frozen_resolution_payload_json->>'source_pay_ex_vat'),
        (v_frozen_resolution_payload_json->>'source_pay_amount_ex_vat'),
        (v_frozen_resolution_result_json->>'source_reservation_amount_ex_vat'),
        (v_frozen_resolution_result_json->>'source_entitlement_amount_ex_vat'),
        (v_frozen_resolution_result_json->>'source_amount_ex_vat'),
        (v_frozen_resolution_result_json->>'source_pay_ex_vat'),
        (v_frozen_resolution_result_json->>'source_pay_amount_ex_vat'),
        (v_single_breakdown_meta_json->>'source_reservation_amount_ex_vat'),
        (v_single_breakdown_meta_json->>'source_entitlement_amount_ex_vat'),
        (v_single_breakdown_meta_json->>'source_amount_ex_vat'),
        (v_single_breakdown_meta_json->>'source_pay_ex_vat'),
        (v_single_breakdown_meta_json->>'source_pay_amount_ex_vat'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,source_pay_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,pay_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,pay_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{source_basis_json,amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_reservation_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_entitlement_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_pay_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_pay_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,basis_source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_reservation_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_entitlement_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_pay_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_pay_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,basis_source_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,pay_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,pay_amount_ex_vat}'),
        (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,amount_ex_vat}')
    ) AS source_candidates(source_text_value)
    WHERE source_candidates.source_text_value IS NOT NULL
      AND BTRIM(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
    LIMIT 1;

    IF v_source_text IS NOT NULL THEN
      RETURN ROUND(ABS(v_source_text::numeric), 2)::numeric(12,2);
    END IF;

    RETURN NULL::numeric(12,2);
  END IF;

  SELECT source_candidates.source_text_value
  INTO v_source_text
  FROM (
    VALUES
      (v_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'reserved_source_amount'),
      (v_frozen_component_snapshot_json->>'frozen_source_amount'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,amount_ex_vat}'),
      (v_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'basis_source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'reserved_source_amount'),
      (v_frozen_source_basis_json->>'frozen_source_amount'),
      (v_frozen_source_basis_json->>'pay_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'amount_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount'),
      (v_frozen_resolution_payload_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_pay_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_pay_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_pay_ex_vat'),
      (v_frozen_resolution_result_json->>'source_pay_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_reservation_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_entitlement_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_pay_ex_vat'),
      (v_single_breakdown_meta_json->>'source_pay_amount_ex_vat'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,source_pay_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,pay_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,pay_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{source_basis_json,amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_reservation_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_entitlement_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_pay_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_pay_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,basis_source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_reservation_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_entitlement_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_pay_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,source_pay_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,basis_source_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,pay_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,pay_amount_ex_vat}'),
      (v_single_breakdown_meta_json#>>'{case_component_json,source_basis_json,amount_ex_vat}')
  ) AS source_candidates(source_text_value)
  WHERE source_candidates.source_text_value IS NOT NULL
    AND BTRIM(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
  LIMIT 1;

  IF v_source_text IS NOT NULL THEN
    RETURN ROUND(ABS(v_source_text::numeric), 2)::numeric(12,2);
  END IF;

  IF v_has_source_target_split THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_amount_ex_vat IS NOT NULL THEN
    RETURN ROUND(ABS(v_amount_ex_vat), 2)::numeric(12,2);
  END IF;

  RETURN NULL::numeric(12,2);
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_finance_case_taxable_channel_restructure_suggestion(p_finance_case_id uuid, p_actor_user_id uuid, p_effective_pay_date date DEFAULT NULL::date, p_resolution_path text DEFAULT 'SUGGESTED'::text, p_schedule_input_mode text DEFAULT NULL::text, p_weeks_total integer DEFAULT NULL::integer, p_weekly_due numeric DEFAULT NULL::numeric, p_manual_total_remaining numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_candidate record;
  v_finance_settings record;
  v_target_umbrella_vat_chargeable boolean := false;

  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));
  v_candidate_pay_method text := null;

  v_open_component_count integer := 0;
  v_source_total_ex numeric(12,2) := 0;
  v_taxable_source_total_ex numeric(12,2) := 0;
  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_taxable_target_total_ex numeric(12,2) := 0;
  v_fixed_target_total_ex numeric(12,2) := 0;
  v_fixed_target_total_vat numeric(12,2) := 0;
  v_fixed_target_total_inc numeric(12,2) := 0;
  v_taxable_manual_target_ex numeric(12,2) := 0;
  v_convertible_target_total_ex numeric(12,2) := 0;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_requires_restructure boolean := false;
  v_has_open_batch_item boolean := false;
  v_blocked_reason text := null;

  v_restructure_start_week_start date := null;
  v_existing_weeks_remaining integer := null;
  v_selected_weeks_total integer := null;
  v_existing_weekly_due numeric(12,2) := null;
  v_selected_weekly_due numeric(12,2) := null;
  v_existing_final_week_amount numeric(12,2) := null;
  v_suggested_weekly_due numeric(12,2) := null;
  v_suggested_final_week_amount numeric(12,2) := null;
  v_selected_final_week_amount numeric(12,2) := null;
  v_schedule_sign integer := -1;

  v_manual_total_remaining_ex numeric(12,2) := null;
  v_ratio numeric := 1;
  v_delta numeric(12,2) := 0;
  v_adjust_component_id uuid := null;

  v_component_breakdown jsonb := '[]'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  if v_schedule_input_mode_norm is null then
    v_schedule_input_mode_norm := 'BY_WEEKS';
  end if;

  if v_schedule_input_mode_norm not in ('BY_WEEKS', 'BY_WEEKLY_DUE') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'SCHEDULE_INPUT_MODE_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE',
      'schedule_input_mode', p_schedule_input_mode
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKS' and p_weekly_due is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKLY_DUE_NOT_ALLOWED_WITH_BY_WEEKS',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must not be supplied when schedule_input_mode is BY_WEEKS'
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKLY_DUE' and p_weeks_total is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKS_TOTAL_NOT_ALLOWED_WITH_BY_WEEKLY_DUE',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must not be supplied when schedule_input_mode is BY_WEEKLY_DUE'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  limit 1;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'CASE_TYPE_NOT_SUPPORTED'
    );
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'reason_code', 'CASE_NOT_ACTIVE'
    );
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method,
    c.umbrella_id as umbrella_id,
    u.id as target_umbrella_id,
    coalesce(u.vat_chargeable, false) as target_umbrella_vat_chargeable
  into v_candidate
  from public.candidates as c
  left join public.umbrellas as u
    on u.id = c.umbrella_id
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_candidate_pay_method = 'UMBRELLA' and v_candidate.target_umbrella_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'TARGET_UMBRELLA_CONTEXT_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate is currently UMBRELLA but no target umbrella company is configured for VAT/routing context',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_target_umbrella_vat_chargeable := case
    when v_candidate_pay_method = 'UMBRELLA' then coalesce(v_candidate.target_umbrella_vat_chargeable, false)
    else false
  end;

  select
    sfp.vat_rate_pct,
    sfp.erni_pct
  into v_finance_settings
  from public.settings_finance_pick(v_effective_pay_date) as sfp
  limit 1;

  if v_finance_settings.vat_rate_pct is null or v_finance_settings.erni_pct is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance settings missing vat_rate_pct and/or erni_pct',
      'effective_pay_date', v_effective_pay_date::text
    )::text;
  end if;

  v_relevant_erni_pct := round(v_finance_settings.erni_pct, 6);
  v_vat_rate_pct := round(v_finance_settings.vat_rate_pct, 6);

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where pbc.pay_batch_id = pb.id
      and coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    v_blocked_reason := 'CASE_ALREADY_IN_OPEN_BATCH';
  end if;

  drop table if exists pg_temp._tmp_taxable_channel_restructure_components;

  create temp table _tmp_taxable_channel_restructure_components on commit drop as
  select
    pfc.id as finance_component_id,
    pfc.finance_case_id as finance_case_id,
    pfc.candidate_id as candidate_id,
    pfc.client_id as client_id,
    pfc.linked_timesheet_id as linked_timesheet_id,
    pfc.source_family_key as source_family_key,
    pfc.component_key_type as component_key_type,
    pfc.component_key_value as component_key_value,
    pfc.classification as classification,
    upper(nullif(btrim(coalesce(pfc.source_pay_method, '')), '')) as source_pay_method,
    coalesce(pfc.source_basis_json, '{}'::jsonb) as source_basis_json,
    round(coalesce(pfc.source_amount, 0), 2)::numeric(12,2) as source_amount,
    round(coalesce(pfc.remaining_source_amount, 0), 2)::numeric(12,2) as remaining_source_amount,
    pfc.saved_target_pay_method as saved_target_pay_method,
    pfc.saved_resolution_mode as saved_resolution_mode,
    pfc.saved_resolution_payload_json as saved_resolution_payload_json,
    pfc.saved_resolution_result_json as saved_resolution_result_json,
    coalesce(pfc.is_resolution_stale, false) as is_resolution_stale,
    pfc.stale_reason as stale_reason,
    (
      pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    )::boolean as is_taxable_channel_component,
    false::boolean as requires_component_conversion,
    0::numeric(12,2) as target_remaining_ex,
    0::numeric(12,2) as target_remaining_vat,
    0::numeric(12,2) as target_remaining_inc
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

  select count(*)::integer
  into v_open_component_count
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'NO_OPEN_REMAINING_COMPONENTS'
    );
  end if;

  select coalesce(
    bool_or(
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    false
  )
  into v_requires_restructure
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_requires_restructure is distinct from true then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'candidate_pay_method', v_candidate_pay_method,
      'reason_code', 'NO_TAXABLE_CHANNEL_MISMATCH'
    );
  end if;

  v_umbrella_vat_chargeable := v_target_umbrella_vat_chargeable;

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set
    requires_component_conversion = (
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    target_remaining_ex = round(
      case
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'UMBRELLA'
         and v_candidate_pay_method = 'PAYE'
          then public._pay_convert_umbrella_to_paye_ex(trc.remaining_source_amount, v_relevant_erni_pct)
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'PAYE'
         and v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0)
        else trc.remaining_source_amount
      end,
      2
    ),
    target_remaining_vat = round(
      case
        when v_candidate_pay_method = 'UMBRELLA'
         and trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'PAYE'
         and v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_umbrella_vat_calc(
            coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0),
            v_vat_rate_pct,
            v_umbrella_vat_chargeable
          )->>'vat')::numeric, 0)
        else 0
      end,
      2
    );

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2);

  select
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.remaining_source_amount) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_vat) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_inc) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
  into
    v_source_total_ex,
    v_taxable_source_total_ex,
    v_target_total_ex,
    v_target_total_vat,
    v_target_total_inc,
    v_taxable_target_total_ex,
    v_fixed_target_total_ex,
    v_fixed_target_total_vat,
    v_fixed_target_total_inc,
    v_convertible_target_total_ex
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then
    v_manual_total_remaining_ex := round(p_manual_total_remaining, 2);
    if v_manual_total_remaining_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'MANUAL_TOTAL_REMAINING_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: manual_total_remaining must be > 0 when supplied',
        'manual_total_remaining', p_manual_total_remaining
      )::text;
    end if;

    select
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
    into
      v_fixed_target_total_ex,
      v_convertible_target_total_ex
    from pg_temp._tmp_taxable_channel_restructure_components as trc;

    if v_manual_total_remaining_ex < v_fixed_target_total_ex then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'MANUAL_TOTAL_BELOW_FIXED_COMPONENTS',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: manual_total_remaining cannot be below the unchanged fixed component total',
        'manual_total_remaining', v_manual_total_remaining_ex,
        'fixed_component_total_ex_vat', v_fixed_target_total_ex
      )::text;
    end if;

    if v_convertible_target_total_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'TAXABLE_TARGET_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: taxable target total must be > 0 before manual allocation'
      )::text;
    end if;

    v_taxable_manual_target_ex := greatest(round(v_manual_total_remaining_ex - v_fixed_target_total_ex, 2), 0);

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set
      target_remaining_ex = round((trc.target_remaining_ex / v_convertible_target_total_ex) * v_taxable_manual_target_ex, 2),
      target_remaining_vat = case
        when v_candidate_pay_method = 'UMBRELLA'
          then round(coalesce((public._pay_umbrella_vat_calc(round((trc.target_remaining_ex / v_convertible_target_total_ex) * v_taxable_manual_target_ex, 2), v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
        else 0
      end
    where trc.requires_component_conversion;

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2);

    select trc.finance_component_id
    into v_adjust_component_id
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    where trc.requires_component_conversion
    order by trc.target_remaining_ex desc, trc.finance_component_id desc
    limit 1;

    select round(v_taxable_manual_target_ex - coalesce(sum(trc.target_remaining_ex), 0), 2)
    into v_delta
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    where trc.requires_component_conversion;

    if v_adjust_component_id is not null and v_delta <> 0 then
      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set target_remaining_ex = round(trc.target_remaining_ex + v_delta, 2)
      where trc.finance_component_id = v_adjust_component_id
        and trc.requires_component_conversion;

      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set
        target_remaining_vat = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else 0
        end,
        target_remaining_inc = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(trc.target_remaining_ex + coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else trc.target_remaining_ex
        end
      where trc.finance_component_id = v_adjust_component_id
        and trc.requires_component_conversion;
    end if;

    select
      round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_vat) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_inc) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
    into
      v_target_total_ex,
      v_target_total_vat,
      v_target_total_inc,
      v_taxable_target_total_ex,
      v_fixed_target_total_ex,
      v_fixed_target_total_vat,
      v_fixed_target_total_inc,
      v_convertible_target_total_ex
    from pg_temp._tmp_taxable_channel_restructure_components as trc;
  end if;

  if v_source_total_ex <= 0 or v_target_total_ex <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'REMAINING_TOTAL_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: source and target totals must be > 0',
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  v_restructure_start_week_start := coalesce(v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));
  if public._pay_week_start_monday(v_restructure_start_week_start) <> v_restructure_start_week_start then
    v_restructure_start_week_start := public._pay_week_start_monday(v_restructure_start_week_start);
  end if;

  v_schedule_sign := case
    when v_case.case_type IN (
      'UNDERPAYMENT'::public.pay_finance_case_type_enum,
      'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
    ) then 1
    else -1
  end;

  select count(*)::integer
  into v_existing_weeks_remaining
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and abs(coalesce(
      case
        when coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
          then round((sched.schedule_row->>'amount')::numeric, 2)
        else null::numeric
      end,
      0::numeric
    )) > 0;

  if v_existing_weeks_remaining is null or v_existing_weeks_remaining < 1 then
    if round(coalesce(v_case.weekly_due, 0), 2) > 0 then
      v_existing_weeks_remaining := greatest(ceil(v_source_total_ex / round(coalesce(v_case.weekly_due, 0), 2))::integer, 1);
    elsif coalesce(v_case.weeks_total, 0) > 0 then
      v_existing_weeks_remaining := v_case.weeks_total;
    else
      v_existing_weeks_remaining := 1;
    end if;
  end if;

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_weekly_due
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date asc
  limit 1;

  v_existing_weekly_due := coalesce(nullif(round(coalesce(v_case.weekly_due, 0), 2), 0), v_existing_weekly_due, round((ceil((v_source_total_ex / greatest(v_existing_weeks_remaining, 1)) * 100) / 100), 2));

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_final_week_amount
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date desc
  limit 1;

  if v_existing_final_week_amount is null then
    v_existing_final_week_amount := round(least(v_existing_weekly_due, greatest(v_source_total_ex - (v_existing_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);
  end if;

  v_ratio := case when v_source_total_ex > 0 then v_target_total_ex / v_source_total_ex else 1 end;
  v_suggested_weekly_due := greatest(round(v_existing_weekly_due * v_ratio, 2), 0.01);
  v_suggested_final_week_amount := round(least(v_suggested_weekly_due, greatest(v_target_total_ex - (v_suggested_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);

  if v_schedule_input_mode_norm = 'BY_WEEKS' then
    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must be >= 1',
        'weeks_total', p_weeks_total
      )::text;
    end if;

    v_selected_weeks_total := coalesce(p_weeks_total, v_existing_weeks_remaining);
    v_selected_weekly_due := case
      when p_weeks_total is null then v_suggested_weekly_due
      else round((ceil((v_target_total_ex / p_weeks_total) * 100) / 100), 2)
    end;
  else
    if p_weekly_due is null or round(p_weekly_due, 2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKLY_DUE_REQUIRED',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must be > 0 when schedule_input_mode is BY_WEEKLY_DUE',
        'weekly_due', p_weekly_due
      )::text;
    end if;

    v_selected_weekly_due := round(p_weekly_due, 2);
    v_selected_weeks_total := greatest(ceil(v_target_total_ex / v_selected_weekly_due)::integer, 1);
  end if;

  v_selected_final_week_amount := round(least(v_selected_weekly_due, greatest(v_target_total_ex - (v_selected_weekly_due * greatest(v_selected_weeks_total - 1, 0)), 0)), 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', trc.finance_component_id::text,
          'linked_timesheet_id', case when trc.linked_timesheet_id is null then null else trc.linked_timesheet_id::text end,
          'source_family_key', trc.source_family_key,
          'component_key_type', trc.component_key_type,
          'component_key_value', trc.component_key_value,
          'classification', trc.classification::text,
          'source_pay_method', trc.source_pay_method,
          'target_pay_method', v_candidate_pay_method,
          'source_remaining_amount_ex_vat', trc.remaining_source_amount,
          'target_remaining_amount_ex_vat', trc.target_remaining_ex,
          'target_remaining_amount_vat', trc.target_remaining_vat,
          'target_remaining_amount_inc_vat', trc.target_remaining_inc,
          'requires_component_conversion', trc.requires_component_conversion,
          'is_taxable_channel_component', trc.is_taxable_channel_component,
          'is_fixed_component', (trc.requires_component_conversion is distinct from true),
          'fixed_component_unchanged', (trc.requires_component_conversion is distinct from true),
          'saved_target_pay_method', trc.saved_target_pay_method,
          'saved_resolution_mode', case when trc.saved_resolution_mode is null then null else trc.saved_resolution_mode::text end,
          'is_resolution_stale', trc.is_resolution_stale,
          'stale_reason', trc.stale_reason
        )
      )
      order by trc.allocation_priority_group nulls last, trc.allocation_priority_order nulls last, trc.finance_component_id
    ),
    '[]'::jsonb
  )
  into v_component_breakdown
  from (
    select
      trc.*,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    join public.pay_finance_case_components as pfc
      on pfc.id = trc.finance_component_id
  ) as trc;

  return jsonb_build_object(
    'ok', true,
    'requires_restructure', true,
    'can_apply', (v_has_open_batch_item is distinct from true),
    'blocked_reason', v_blocked_reason,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'source_pay_methods', (
      select coalesce(jsonb_agg(distinct trc.source_pay_method), '[]'::jsonb)
      from pg_temp._tmp_taxable_channel_restructure_components as trc
      where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    ),
    'target_pay_method', v_candidate_pay_method,
    'effective_pay_date', v_effective_pay_date::text,
    'resolution_path', v_resolution_path_norm,
    'schedule_input_mode', v_schedule_input_mode_norm,
    'existing', jsonb_build_object(
      'source_remaining_balance_ex_vat', v_source_total_ex,
      'taxable_source_remaining_balance_ex_vat', v_taxable_source_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'fixed_component_total_vat', v_fixed_target_total_vat,
      'fixed_component_total_inc_vat', v_fixed_target_total_inc,
      'weekly_due', v_existing_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_existing_final_week_amount,
      'start_week_start', v_restructure_start_week_start::text,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb)
    ),
    'suggested', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'target_remaining_balance_vat', v_target_total_vat,
      'target_remaining_balance_inc_vat', v_target_total_inc,
      'taxable_target_remaining_balance_ex_vat', v_taxable_target_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'fixed_component_total_vat', v_fixed_target_total_vat,
      'fixed_component_total_inc_vat', v_fixed_target_total_inc,
      'fixed_components_preserved', true,
      'weekly_due', v_suggested_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_suggested_final_week_amount,
      'erni_rate_pct', v_relevant_erni_pct,
      'erni_component_ex_vat', round(abs(v_taxable_source_total_ex - v_taxable_target_total_ex), 2),
      'vat_rate_pct', v_vat_rate_pct,
      'vat_amount', v_target_total_vat,
      'umbrella_vat_chargeable', v_umbrella_vat_chargeable
    ),
    'selected', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'taxable_target_remaining_balance_ex_vat', v_taxable_target_total_ex,
      'weekly_due', v_selected_weekly_due,
      'weeks_total', v_selected_weeks_total,
      'final_week_amount', v_selected_final_week_amount,
      'schedule_sign', v_schedule_sign,
      'start_week_start', v_restructure_start_week_start::text
    ),
    'component_breakdown', v_component_breakdown,
    'generated_at_utc', v_now_utc::text,
    'note', p_note
  );
end;
$function$;



CREATE OR REPLACE FUNCTION public.pay_finance_case_apply_taxable_channel_restructure(p_finance_case_id uuid, p_actor_user_id uuid, p_resolution_path text DEFAULT 'SUGGESTED'::text, p_schedule_input_mode text DEFAULT NULL::text, p_weeks_total integer DEFAULT NULL::integer, p_weekly_due numeric DEFAULT NULL::numeric, p_manual_total_remaining numeric DEFAULT NULL::numeric, p_effective_pay_date date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_updated_case public.pay_advances%rowtype;
  v_candidate record;

  v_suggestion jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_component_before_json jsonb := '[]'::jsonb;
  v_component_after_json jsonb := '[]'::jsonb;
  v_schedule_json jsonb := '[]'::jsonb;

  v_candidate_pay_method text := null;
  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));

  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_source_total_ex numeric(12,2) := 0;
  v_source_target_ratio numeric := 1;
  v_source_weekly_due numeric(12,2) := 0;
  v_source_final_week_amount numeric(12,2) := 0;
  v_source_schedule_json jsonb := '[]'::jsonb;
  v_weekly_due numeric(12,2) := 0;
  v_weeks_total integer := 0;
  v_final_week_amount numeric(12,2) := 0;
  v_schedule_sign integer := -1;
  v_start_week_start date := null;
  v_next_due_week_start date := null;
  v_recovered_or_paid_so_far_ex numeric(12,2) := 0;
  v_rebased_original_amount numeric(12,2) := 0;

  v_open_component_count integer := 0;
  v_new_component_remaining_total numeric(12,2) := 0;
  v_has_open_batch_item boolean := false;
  v_resolution_mode public.pay_finance_component_resolution_mode_enum := 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum;
  v_event_note text := null;
  v_case_taxability public.pay_finance_taxability_enum := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  perform pg_advisory_xact_lock(94201, 1);

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_TYPE_NOT_SUPPORTED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case type is not supported for taxable channel restructure',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_NOT_ACTIVE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case must be ACTIVE',
      'finance_case_id', p_finance_case_id::text,
      'status', v_case.status::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount, 0), 2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'NO_OUTSTANDING_BALANCE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text,
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2)
    )::text;
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method
  into v_candidate
  from public.candidates as c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  perform 1
  from public.pay_finance_case_components as pfc_lock
  where pfc_lock.finance_case_id = p_finance_case_id
    and pfc_lock.closed_at_utc is null
  for update;

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_ALREADY_IN_OPEN_BATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: cannot restructure while the case is already included in an open pay batch',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_suggestion := public.pay_finance_case_taxable_channel_restructure_suggestion(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_effective_pay_date => v_effective_pay_date,
    p_resolution_path => v_resolution_path_norm,
    p_schedule_input_mode => v_schedule_input_mode_norm,
    p_weeks_total => p_weeks_total,
    p_weekly_due => p_weekly_due,
    p_manual_total_remaining => p_manual_total_remaining,
    p_note => p_note
  );

  if coalesce((v_suggestion->>'requires_restructure')::boolean, false) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESTRUCTURE_NOT_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: taxable channel restructure is not required',
      'finance_case_id', p_finance_case_id::text,
      'suggestion', v_suggestion
    )::text;
  end if;

  if coalesce((v_suggestion->>'can_apply')::boolean, true) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', coalesce(nullif(v_suggestion->>'blocked_reason', ''), 'RESTRUCTURE_BLOCKED'),
      'message', 'pay_finance_case_apply_taxable_channel_restructure: restructure is currently blocked',
      'finance_case_id', p_finance_case_id::text,
      'blocked_reason', v_suggestion->>'blocked_reason'
    )::text;
  end if;

  if to_regclass('pg_temp._tmp_taxable_channel_restructure_components') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SUGGESTION_COMPONENT_TABLE_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: suggestion component table was not available'
    )::text;
  end if;

  select
    count(*)::integer,
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2)
  into
    v_open_component_count,
    v_source_total_ex,
    v_new_component_remaining_total
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 or v_source_total_ex <= 0 or v_new_component_remaining_total <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'COMPONENT_TARGET_TOTAL_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: target component total must be > 0',
      'open_component_count', v_open_component_count,
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_new_component_remaining_total
    )::text;
  end if;

  v_target_total_ex := round(coalesce((v_suggestion->'selected'->>'target_remaining_balance_ex_vat')::numeric, v_new_component_remaining_total), 2);
  v_weekly_due := round(coalesce((v_suggestion->'selected'->>'weekly_due')::numeric, 0), 2);
  v_weeks_total := coalesce((v_suggestion->'selected'->>'weeks_total')::integer, 0);
  v_final_week_amount := round(coalesce((v_suggestion->'selected'->>'final_week_amount')::numeric, 0), 2);
  v_schedule_sign := coalesce(
    (v_suggestion->'selected'->>'schedule_sign')::integer,
    case
      when v_case.case_type IN (
        'UNDERPAYMENT'::public.pay_finance_case_type_enum,
        'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      ) then 1
      else -1
    end
  );
  v_start_week_start := coalesce((v_suggestion->'selected'->>'start_week_start')::date, v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));

  v_source_total_ex := round(coalesce((v_suggestion->'existing'->>'source_remaining_balance_ex_vat')::numeric, v_source_total_ex), 2);
  v_source_target_ratio := case
    when round(abs(coalesce(v_source_total_ex, 0)), 2) = 0 then 1
    else coalesce(v_target_total_ex, 0) / nullif(v_source_total_ex, 0)
  end;
  v_source_weekly_due := round(
    case
      when round(abs(coalesce(v_source_target_ratio, 0)), 8) = 0 then coalesce(v_weekly_due, 0)
      else coalesce(v_weekly_due, 0) / v_source_target_ratio
    end,
    2
  );
  v_source_weekly_due := greatest(coalesce(v_source_weekly_due, 0), 0.01)::numeric(12,2);
  v_source_final_week_amount := round(
    least(
      v_source_weekly_due,
      greatest(coalesce(v_source_total_ex, 0) - (v_source_weekly_due * greatest(coalesce(v_weeks_total, 1) - 1, 0)), 0)
    ),
    2
  )::numeric(12,2);

  if v_target_total_ex <= 0 or v_source_total_ex <= 0 or v_weekly_due <= 0 or v_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SELECTED_SCHEDULE_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: selected source/target totals, weekly_due and weeks_total must be valid',
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex,
      'weekly_due', v_weekly_due,
      'weeks_total', v_weeks_total
    )::text;
  end if;

  if public._pay_week_start_monday(v_start_week_start) <> v_start_week_start then
    v_start_week_start := public._pay_week_start_monday(v_start_week_start);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_start_week_start + (gs.i * 7))::date,
        'amount', round(
          v_schedule_sign * least(
            v_weekly_due,
            greatest(v_target_total_ex - (v_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs(i);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_start_week_start + (gs.i * 7))::date,
        'amount', round(
          v_schedule_sign * least(
            v_source_weekly_due,
            greatest(v_source_total_ex - (v_source_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_source_schedule_json
  from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due_week_start
  from (
    select
      (v_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        v_schedule_sign * least(
          v_weekly_due,
          greatest(v_target_total_ex - (v_weekly_due * gs2.i), 0)
        ),
        2
      ) as amount
    from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs2(i)
  ) as x
  where abs(coalesce(x.amount, 0)) > 0;

  v_recovered_or_paid_so_far_ex := round(greatest(coalesce(v_case.original_amount, 0) - coalesce(v_case.outstanding_amount, 0), 0), 2);
  v_rebased_original_amount := round(v_recovered_or_paid_so_far_ex + v_source_total_ex, 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_before_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_before_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
      'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
      'original_amount', round(coalesce(v_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_case.weekly_due, 0), 2),
      'weeks_total', v_case.weeks_total,
      'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb),
      'components', v_component_before_json
    )
  );

  v_resolution_mode := case
    when v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
    else 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
  end;

  update public.pay_finance_case_components as pfc
  set
    saved_target_pay_method = v_candidate_pay_method,
    saved_resolution_mode = v_resolution_mode,
    saved_resolution_payload_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_path', v_resolution_path_norm,
        'schedule_input_mode', coalesce(v_schedule_input_mode_norm, 'BY_WEEKS'),
        'effective_pay_date', v_effective_pay_date::text,
        'source_pay_method', trc.source_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'target_source_ratio', case when round(coalesce(trc.remaining_source_amount, 0), 2) <> 0 then round(coalesce(trc.target_remaining_ex, 0) / trc.remaining_source_amount, 12) else null end,
        'relevant_erni_pct', v_suggestion->'suggested'->'erni_rate_pct',
        'vat_rate_pct', v_suggestion->'suggested'->'vat_rate_pct',
        'umbrella_vat_chargeable', v_suggestion->'suggested'->'umbrella_vat_chargeable',
        'weekly_due', v_weekly_due,
        'weeks_total', v_weeks_total,
        'final_week_amount', v_final_week_amount,
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    saved_resolution_result_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_mode', v_resolution_mode::text,
        'applied_at_utc', v_now_utc::text,
        'actor_user_id', p_actor_user_id::text,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'source_pay_method_before', trc.source_pay_method,
        'source_pay_method_after', v_candidate_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'case_source_remaining_amount_ex_vat', v_source_total_ex,
        'case_target_remaining_amount_ex_vat', v_target_total_ex,
        'case_source_weekly_due', v_source_weekly_due,
        'case_weekly_due', v_weekly_due,
        'case_weeks_total', v_weeks_total,
        'target_source_ratio', case when round(coalesce(trc.remaining_source_amount, 0), 2) <> 0 then round(coalesce(trc.target_remaining_ex, 0) / trc.remaining_source_amount, 12) else null end
      )
    ),
    resolution_fingerprint = public.pay_finance_component_fingerprint(
      pfc.source_family_key,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      pfc.source_pay_method,
      v_candidate_pay_method,
      coalesce(pfc.source_basis_json, '{}'::jsonb),
      round(coalesce(pfc.source_amount, 0), 2),
      NULL::numeric,
      coalesce(pfc.source_basis_json, '{}'::jsonb) || jsonb_build_object(
        'taxable_channel_restructure_effective_pay_date', v_effective_pay_date::text,
        'target_pay_method', v_candidate_pay_method,
        'target_remaining_amount_ex_vat', round(coalesce(trc.target_remaining_ex, 0), 2),
        'target_remaining_amount_vat', round(coalesce(trc.target_remaining_vat, 0), 2),
        'target_remaining_amount_inc_vat', round(coalesce(trc.target_remaining_inc, 0), 2),
        'resolution_mode', v_resolution_mode::text
      )
    ),
    is_resolution_stale = false,
    stale_reason = null,
    resolved_at_utc = v_now_utc,
    updated_at_utc = v_now_utc
  from pg_temp._tmp_taxable_channel_restructure_components as trc
  where pfc.id = trc.finance_component_id
    and pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and trc.requires_component_conversion;

  select
    case
      when count(*) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) = count(*)
        then 'TAXABLE'::public.pay_finance_taxability_enum
      when count(*) filter (where trc.classification in (
        'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
        'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
      )) = count(*)
        then 'NON_TAXABLE'::public.pay_finance_taxability_enum
      else null::public.pay_finance_taxability_enum
    end
  into v_case_taxability
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  update public.pay_advances as pa
  set
    original_amount = v_rebased_original_amount,
    outstanding_amount = v_source_total_ex,
    schedule_json = coalesce(v_source_schedule_json, '[]'::jsonb),
    weekly_due = v_source_weekly_due,
    weeks_total = v_weeks_total,
    start_week_start = v_start_week_start,
    next_due_week_start = v_next_due_week_start,
    taxability = v_case_taxability,
    routing_kind = case
      when v_candidate_pay_method = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
      else 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
    end,
    notes = coalesce(nullif(btrim(coalesce(p_note, '')), ''), pa.notes),
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    count(*)::integer
  into
    v_new_component_remaining_total,
    v_open_component_count
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENTS_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: no open components remained after update',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_new_component_remaining_total <> v_source_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENT_TOTAL_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated component remaining total must match selected source total',
      'finance_case_id', p_finance_case_id::text,
      'component_remaining_total', v_new_component_remaining_total,
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select pa.*
  into v_updated_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id;

  if v_updated_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case could not be reloaded',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if round(coalesce(v_updated_case.outstanding_amount, 0), 2) <> v_source_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_OUTSTANDING_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case outstanding_amount must match selected source total',
      'finance_case_id', p_finance_case_id::text,
      'updated_outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
          'saved_resolution_result_json', pfc.saved_resolution_result_json,
          'resolution_fingerprint', pfc.resolution_fingerprint,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_after_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_after_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_updated_case.candidate_id::text,
      'client_id', case when v_updated_case.client_id is null then null else v_updated_case.client_id::text end,
      'case_type', v_updated_case.case_type::text,
      'status', v_updated_case.status::text,
      'taxability', case when v_updated_case.taxability is null then null else v_updated_case.taxability::text end,
      'routing_kind', case when v_updated_case.routing_kind is null then null else v_updated_case.routing_kind::text end,
      'original_amount', round(coalesce(v_updated_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_updated_case.weekly_due, 0), 2),
      'weeks_total', v_updated_case.weeks_total,
      'start_week_start', case when v_updated_case.start_week_start is null then null else v_updated_case.start_week_start::text end,
      'next_due_week_start', case when v_updated_case.next_due_week_start is null then null else v_updated_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_updated_case.schedule_json, '[]'::jsonb),
      'components', v_component_after_json
    )
  );

  v_event_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Taxable finance channel restructure applied'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::uuid,
    v_before_json,
    v_after_json,
    'TAXABLE_CHANNEL_RESTRUCTURE',
    v_event_note
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_updated_case.candidate_id::text,
    'case_type', v_updated_case.case_type::text,
    'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
    'resolution_path', v_resolution_path_norm,
    'resolution_mode', v_resolution_mode::text,
    'effective_pay_date', v_effective_pay_date::text,
    'target_pay_method', v_candidate_pay_method,
    'source_remaining_balance_ex_vat', v_source_total_ex,
    'target_remaining_balance_ex_vat', v_target_total_ex,
    'before', v_before_json,
    'after', v_after_json,
    'suggestion', v_suggestion
  );
end;
$function$;


drop function if exists public.pay_manual_debt_adjustment_resolve_taxable_channel_change(uuid, uuid, text, text, integer, numeric, numeric, text);

create or replace function public.pay_manual_debt_adjustment_resolve_taxable_channel_change(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_resolution_path text,
  p_schedule_input_mode text default null::text,
  p_weeks_total integer default null::integer,
  p_weekly_due numeric default null::numeric,
  p_manual_total_remaining numeric default null::numeric,
  p_effective_pay_date date default null::date,
  p_note text default null::text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  return public.pay_finance_case_apply_taxable_channel_restructure(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_resolution_path => p_resolution_path,
    p_schedule_input_mode => p_schedule_input_mode,
    p_weeks_total => p_weeks_total,
    p_weekly_due => p_weekly_due,
    p_manual_total_remaining => p_manual_total_remaining,
    p_effective_pay_date => p_effective_pay_date,
    p_note => p_note
  );
end;
$function$;



CREATE OR REPLACE FUNCTION public._pay_batch_status_is_active_reservation(p_status text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT upper(btrim(coalesce(p_status, ''))) IN (
    'DRAFT',
    'DRAFT_CREATED',
    'READY',
    'WAITING_BANK_CONFIRM',
    'PARTIAL',
    'BLOCKED_FUNDS',
    'SCHEDULED',
    'EXECUTING',
    'AWAITING_AUTHORISATION',
    'AUTHORISED_FOR_PAYMENT'
  );
$function$;


CREATE OR REPLACE FUNCTION public._pay_current_timesheet_entitlement_components(p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with
inp as (
  select coalesce(
    (
      select array_agg(distinct t_input.x order by t_input.x)
      from unnest(coalesce(p_timesheet_ids, array[]::uuid[])) as t_input(x)
      where t_input.x is not null
    ),
    array[]::uuid[]
  ) as ts_ids
),
rotation_scope_rows as (
  select
    scope_rows.requested_timesheet_id,
    scope_rows.booking_id,
    scope_rows.canonical_timesheet_id,
    scope_rows.family_timesheet_id,
    scope_rows.family_is_current,
    scope_rows.family_version,
    scope_rows.requested_is_canonical
  from inp as input_scope
  join public._pay_timesheet_rotation_scope(input_scope.ts_ids) as scope_rows
    on true
),
rotation_scope_keyed as (
  select
    rotation_scope_rows.requested_timesheet_id,
    rotation_scope_rows.booking_id,
    rotation_scope_rows.canonical_timesheet_id,
    rotation_scope_rows.family_timesheet_id,
    rotation_scope_rows.family_is_current,
    rotation_scope_rows.family_version,
    rotation_scope_rows.requested_is_canonical,
    coalesce(rotation_scope_rows.booking_id, rotation_scope_rows.requested_timesheet_id::text) as scope_family_key
  from rotation_scope_rows
  where rotation_scope_rows.requested_timesheet_id is not null
),
projection_targets as (
  select
    rotation_scope_keyed.scope_family_key,
    coalesce(
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (
          where coalesce(rotation_scope_keyed.requested_is_canonical, false) = true
            and rotation_scope_keyed.canonical_timesheet_id is not null
        )
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.requested_timesheet_id order by rotation_scope_keyed.requested_timesheet_id)
        filter (where rotation_scope_keyed.requested_timesheet_id is not null)
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (where rotation_scope_keyed.canonical_timesheet_id is not null)
      )[1]
    ) as projected_timesheet_id,
    (
      array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
      filter (where rotation_scope_keyed.canonical_timesheet_id is not null)
    )[1] as canonical_timesheet_id
  from rotation_scope_keyed
  group by rotation_scope_keyed.scope_family_key
),
family_to_projection as (
  select distinct
    rotation_scope_keyed.family_timesheet_id,
    projection_targets.projected_timesheet_id,
    projection_targets.canonical_timesheet_id
  from rotation_scope_keyed
  join projection_targets
    on projection_targets.scope_family_key = rotation_scope_keyed.scope_family_key
  where rotation_scope_keyed.family_timesheet_id is not null
    and projection_targets.projected_timesheet_id is not null
),
canonical_projection as (
  select distinct
    family_to_projection.canonical_timesheet_id,
    family_to_projection.projected_timesheet_id
  from family_to_projection
  where family_to_projection.canonical_timesheet_id is not null
    and family_to_projection.projected_timesheet_id is not null
),
tf as (
  select
    canonical_projection.projected_timesheet_id as timesheet_id,
    canonical_projection.canonical_timesheet_id as canonical_timesheet_id,
    tfin.total_pay_ex_vat,
    tfin.invoice_breakdown_json,
    tfin.additional_units_json,
    tfin.expenses_pay_ex_vat,
    tfin.travel_pay_ex_vat,
    tfin.accommodation_pay_ex_vat,
    tfin.other_pay_ex_vat,
    tfin.mileage_pay_ex_vat,
    timesheet_rows.booking_id,
    upper(coalesce(timesheet_rows.sheet_scope::text,'')) as sheet_scope,
    timesheet_rows.reference_number,
    timesheet_rows.worked_start_iso as ts_worked_start_iso,
    timesheet_rows.worked_end_iso as ts_worked_end_iso,
    timesheet_rows.break_start_iso as ts_break_start_iso,
    timesheet_rows.break_end_iso as ts_break_end_iso,
    timesheet_rows.break_minutes as ts_break_minutes,
    timesheet_rows.actual_schedule_json as ts_actual_schedule_json,
    tfin.worked_start_iso as tf_worked_start_iso,
    tfin.worked_end_iso as tf_worked_end_iso,
    tfin.break_start_iso as tf_break_start_iso,
    tfin.break_end_iso as tf_break_end_iso,
    tfin.break_minutes as tf_break_minutes,
    tfin.actual_schedule_json as tf_actual_schedule_json
  from canonical_projection
  join public.timesheets_financials as tfin
    on tfin.is_current = true
   and tfin.timesheet_id = canonical_projection.canonical_timesheet_id
  join public.timesheets as timesheet_rows
    on timesheet_rows.timesheet_id = canonical_projection.canonical_timesheet_id
   and timesheet_rows.is_current = true
   and timesheet_rows.revoked_at is null
   and timesheet_rows.archived_at_utc is null
   and timesheet_rows.authorised_at_server is not null
),
truth_enriched as (
  select
    tf0.timesheet_id,
    tf0.canonical_timesheet_id,
    tf0.total_pay_ex_vat,
    tf0.invoice_breakdown_json,
    tf0.additional_units_json,
    tf0.expenses_pay_ex_vat,
    tf0.travel_pay_ex_vat,
    tf0.accommodation_pay_ex_vat,
    tf0.other_pay_ex_vat,
    tf0.mileage_pay_ex_vat,
    tf0.booking_id,
    tf0.sheet_scope,
    tf0.reference_number,
    coalesce(tf0.tf_worked_start_iso, tf0.ts_worked_start_iso) as effective_worked_start_iso,
    coalesce(tf0.tf_worked_end_iso, tf0.ts_worked_end_iso) as effective_worked_end_iso,
    coalesce(tf0.tf_break_start_iso, tf0.ts_break_start_iso) as effective_break_start_iso,
    coalesce(tf0.tf_break_end_iso, tf0.ts_break_end_iso) as effective_break_end_iso,
    coalesce(tf0.tf_break_minutes, tf0.ts_break_minutes) as effective_break_minutes,
    case
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'object' then tf0.tf_actual_schedule_json
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'array' then (
        select tf_sched_item.value
        from jsonb_array_elements(tf0.tf_actual_schedule_json) as tf_sched_item(value)
        where tf_sched_item.value is not null
          and jsonb_typeof(tf_sched_item.value) = 'object'
        limit 1
      )
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'object' then tf0.ts_actual_schedule_json
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'array' then (
        select ts_sched_item.value
        from jsonb_array_elements(tf0.ts_actual_schedule_json) as ts_sched_item(value)
        where ts_sched_item.value is not null
          and jsonb_typeof(ts_sched_item.value) = 'object'
        limit 1
      )
      else null::jsonb
    end as effective_daily_schedule_json
  from tf tf0
),
truth_segments as (
  select
    te.timesheet_id,
    te.canonical_timesheet_id,
    case
      when te.invoice_breakdown_json is not null
       and jsonb_typeof(te.invoice_breakdown_json) = 'object'
       and upper(coalesce(te.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
       and jsonb_typeof(te.invoice_breakdown_json->'segments') = 'array'
      then (
        select coalesce(
          jsonb_agg(seg.value),
          '[]'::jsonb
        )
        from jsonb_array_elements(te.invoice_breakdown_json->'segments') as seg(value)
        where seg.value is not null
          and jsonb_typeof(seg.value) = 'object'
      )
      when te.sheet_scope = 'DAILY'
      then jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false,
          'date', case
            when te.effective_worked_start_iso is not null then ((te.effective_worked_start_iso at time zone 'Europe/London')::date)::text
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'work_date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'ymd','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date_ymd','')), '')
            )
          end,
          'segment_key', ('ts:' || te.timesheet_id::text),
          'segment_stable_key', ('timesheet:' || coalesce(te.booking_id, te.timesheet_id::text)),
          'ref_num', nullif(btrim(coalesce(te.reference_number,'')), ''),
          'start_utc', case
            when te.effective_worked_start_iso is not null then te.effective_worked_start_iso::text
            else null
          end,
          'end_utc', case
            when te.effective_worked_end_iso is not null then te.effective_worked_end_iso::text
            else null
          end,
          'start', case
            when te.effective_worked_start_iso is not null then to_char((te.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'start','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_start','')), '')
            )
          end,
          'end', case
            when te.effective_worked_end_iso is not null then to_char((te.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'end','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_end','')), '')
            )
          end,
          'break_start', case
            when te.effective_break_start_iso is not null then to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '')
          end,
          'break_end', case
            when te.effective_break_end_iso is not null then to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '')
          end,
          'break_mins', coalesce(
            te.effective_break_minutes::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
            case
              when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                then greatest(
                  0::numeric,
                  round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                )
              else null::numeric
            end
          ),
          'breaks', case
            when jsonb_typeof(te.effective_daily_schedule_json->'breaks') = 'array' then te.effective_daily_schedule_json->'breaks'
            when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'end', to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    case
                      when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  )
                )
              )
            when nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '') is not null
             and nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '') is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), ''),
                  'end', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), ''),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                  )
                )
              )
            else '[]'::jsonb
          end
        )
      )
      else jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false
        )
      )
    end as segments_json
  from truth_enriched te
),
adjustment_truth_rows as (
  select distinct on (
    family_to_projection.projected_timesheet_id,
    adjustment_rows.id
  )
    family_to_projection.projected_timesheet_id as timesheet_id,
    adjustment_rows.id as adjustment_id,
    adjustment_rows.created_at as adjustment_created_at,
    round(coalesce(adjustment_rows.delta_pay_ex_vat, 0), 2) as delta_pay_ex_vat
  from family_to_projection
  join public.ts_pay_adjustments as adjustment_rows
    on adjustment_rows.timesheet_id = family_to_projection.family_timesheet_id
  where adjustment_rows.as_advance = false
    and adjustment_rows.timesheet_id is not null
    and adjustment_rows.id is not null
    and family_to_projection.projected_timesheet_id is not null
  order by
    family_to_projection.projected_timesheet_id,
    adjustment_rows.id,
    adjustment_rows.created_at nulls last,
    family_to_projection.family_timesheet_id
),
truth_snapshot_like as (
  select
    truth_segment_rows.timesheet_id,
    jsonb_build_object(
      'segments', truth_segment_rows.segments_json,
      'additional_units_json', coalesce(tf1.additional_units_json,'{}'::jsonb),
      'additional_pay_ex_vat', 0,
      'expenses', jsonb_build_object(
        'expenses_pay_ex_vat', round(coalesce(tf1.expenses_pay_ex_vat,0),2),
        'travel_pay_ex_vat', round(coalesce(tf1.travel_pay_ex_vat,0),2),
        'accommodation_pay_ex_vat', round(coalesce(tf1.accommodation_pay_ex_vat,0),2),
        'other_pay_ex_vat', round(coalesce(tf1.other_pay_ex_vat,0),2),
        'mileage_pay_ex_vat', round(coalesce(tf1.mileage_pay_ex_vat,0),2)
      ),
      'adjustments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', adjustment_truth_rows.adjustment_id::text,
            'delta_pay_ex_vat', adjustment_truth_rows.delta_pay_ex_vat
          )
          order by adjustment_truth_rows.adjustment_created_at nulls last, adjustment_truth_rows.adjustment_id
        )
        from adjustment_truth_rows
        where adjustment_truth_rows.timesheet_id = truth_segment_rows.timesheet_id
      ), '[]'::jsonb)
    ) as snap_json
  from truth_segments as truth_segment_rows
  join tf as tf1
    on tf1.timesheet_id = truth_segment_rows.timesheet_id
),
truth_components_raw as (
  select
    truth_snapshot_rows.timesheet_id,
    upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) as raw_key_type,
    nullif(btrim(coalesce(timesheet_component_rows.key_value, '')), '') as raw_key_value,
    timesheet_component_rows.amount_ex_vat,
    timesheet_component_rows.amount_inc_vat,
    case
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) in ('TS_DAY','TS_TOTAL')
        then 'SEGMENT_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) = 'ADJUSTMENT_CODE'
        then 'ADJUSTMENT_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) = 'EXPENSE_CODE'
       and upper(nullif(btrim(coalesce(timesheet_component_rows.key_value, '')), '')) = 'MILEAGE'
        then 'MILEAGE_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) in ('ADDITIONAL_CODE','EXPENSE_CODE')
        then 'EXPENSE_DELTA'
      else null::text
    end as resolver_item_type
  from truth_snapshot_like as truth_snapshot_rows
  join lateral public._pay_timesheet_components(truth_snapshot_rows.snap_json) as timesheet_component_rows
    on true
),
truth_components as (
  select
    truth_component_rows.timesheet_id,
    resolved_truth_keys.key_type,
    resolved_truth_keys.key_value,
    truth_component_rows.amount_ex_vat,
    truth_component_rows.amount_inc_vat
  from truth_components_raw as truth_component_rows
  join lateral public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => truth_component_rows.timesheet_id,
    p_live_source_json => jsonb_build_object(
      'timesheet_id', truth_component_rows.timesheet_id::text,
      'item_type', truth_component_rows.resolver_item_type,
      'component_key_type', truth_component_rows.raw_key_type,
      'component_key_value', truth_component_rows.raw_key_value,
      'work_date', case when truth_component_rows.raw_key_type = 'TS_DAY' then truth_component_rows.raw_key_value else null::text end
    ),
    p_item_type => truth_component_rows.resolver_item_type,
    p_key_type_hint => truth_component_rows.raw_key_type,
    p_key_value_hint => truth_component_rows.raw_key_value,
    p_work_date => case
      when truth_component_rows.raw_key_type = 'TS_DAY'
       and truth_component_rows.raw_key_value ~ '^\d{4}-\d{2}-\d{2}$'
        then truth_component_rows.raw_key_value::date
      else null::date
    end
  ) as resolved_truth_keys
    on true
  where resolved_truth_keys.key_resolution_failure_reason is null
),
active_settled_components as (
  select
    active_rows.timesheet_id,
    active_rows.key_type,
    active_rows.key_value,
    active_rows.amount_ex_vat,
    active_rows.amount_inc_vat
  from public._pay_active_settled_components((select inp.ts_ids from inp)) as active_rows
),
legacy_baseline_timesheets as (
  select distinct
    timesheet_pay_state_rows.timesheet_id as source_timesheet_id,
    family_to_projection.projected_timesheet_id as projected_timesheet_id
  from family_to_projection
  join public.timesheet_pay_state as timesheet_pay_state_rows
    on timesheet_pay_state_rows.timesheet_id = family_to_projection.family_timesheet_id
  where not exists (
    select 1
    from active_settled_components as active_check
    where active_check.timesheet_id = family_to_projection.projected_timesheet_id
  )
),
legacy_baseline_components_raw as (
  select
    legacy_baseline_timesheet_rows.projected_timesheet_id as timesheet_id,
    upper(nullif(btrim(coalesce(baseline_component_rows.key_type, '')), '')) as raw_key_type,
    nullif(btrim(coalesce(baseline_component_rows.key_value, '')), '') as raw_key_value,
    baseline_component_rows.amount_ex_vat,
    baseline_component_rows.amount_inc_vat,
    case
      when upper(nullif(btrim(coalesce(baseline_component_rows.key_type, '')), '')) in ('TS_DAY','TS_TOTAL')
        then 'SEGMENT_DELTA'
      when upper(nullif(btrim(coalesce(baseline_component_rows.key_type, '')), '')) = 'ADJUSTMENT_CODE'
        then 'ADJUSTMENT_DELTA'
      when upper(nullif(btrim(coalesce(baseline_component_rows.key_type, '')), '')) = 'EXPENSE_CODE'
       and upper(nullif(btrim(coalesce(baseline_component_rows.key_value, '')), '')) = 'MILEAGE'
        then 'MILEAGE_DELTA'
      when upper(nullif(btrim(coalesce(baseline_component_rows.key_type, '')), '')) in ('ADDITIONAL_CODE','EXPENSE_CODE')
        then 'EXPENSE_DELTA'
      else null::text
    end as resolver_item_type
  from legacy_baseline_timesheets as legacy_baseline_timesheet_rows
  join public.timesheet_pay_state as timesheet_pay_state_rows
    on timesheet_pay_state_rows.timesheet_id = legacy_baseline_timesheet_rows.source_timesheet_id
  join lateral public._pay_timesheet_components(coalesce(timesheet_pay_state_rows.last_settled_snapshot_json,'{}'::jsonb)) as baseline_component_rows
    on true
),
legacy_baseline_components as (
  select
    legacy_baseline_rows.timesheet_id,
    resolved_baseline_keys.key_type,
    resolved_baseline_keys.key_value,
    legacy_baseline_rows.amount_ex_vat,
    legacy_baseline_rows.amount_inc_vat
  from legacy_baseline_components_raw as legacy_baseline_rows
  join lateral public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => legacy_baseline_rows.timesheet_id,
    p_live_source_json => jsonb_build_object(
      'timesheet_id', legacy_baseline_rows.timesheet_id::text,
      'item_type', legacy_baseline_rows.resolver_item_type,
      'component_key_type', legacy_baseline_rows.raw_key_type,
      'component_key_value', legacy_baseline_rows.raw_key_value,
      'work_date', case when legacy_baseline_rows.raw_key_type = 'TS_DAY' then legacy_baseline_rows.raw_key_value else null::text end
    ),
    p_item_type => legacy_baseline_rows.resolver_item_type,
    p_key_type_hint => legacy_baseline_rows.raw_key_type,
    p_key_value_hint => legacy_baseline_rows.raw_key_value,
    p_work_date => case
      when legacy_baseline_rows.raw_key_type = 'TS_DAY'
       and legacy_baseline_rows.raw_key_value ~ '^\d{4}-\d{2}-\d{2}$'
        then legacy_baseline_rows.raw_key_value::date
      else null::date
    end
  ) as resolved_baseline_keys
    on true
  where resolved_baseline_keys.key_resolution_failure_reason is null
),
baseline_components as (
  select
    active_settled_components.timesheet_id,
    active_settled_components.key_type,
    active_settled_components.key_value,
    active_settled_components.amount_ex_vat,
    active_settled_components.amount_inc_vat
  from active_settled_components
  union all
  select
    legacy_baseline_components.timesheet_id,
    legacy_baseline_components.key_type,
    legacy_baseline_components.key_value,
    legacy_baseline_components.amount_ex_vat,
    legacy_baseline_components.amount_inc_vat
  from legacy_baseline_components
),
truth_grouped as (
  select
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(truth_components.key_value, '')), '') as key_value,
    round(sum(coalesce(truth_components.amount_ex_vat, 0)), 2) as truth_ex_vat,
    round(sum(coalesce(truth_components.amount_inc_vat, 0)), 2) as truth_inc_vat
  from truth_components
  where truth_components.timesheet_id is not null
    and truth_components.key_type is not null
    and btrim(truth_components.key_type) <> ''
    and truth_components.key_value is not null
    and btrim(truth_components.key_value) <> ''
    and truth_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (truth_components.key_type = 'TS_DAY' and truth_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')),
    nullif(btrim(coalesce(truth_components.key_value, '')), '')
),
baseline_grouped as (
  select
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(baseline_components.key_value, '')), '') as key_value,
    round(sum(coalesce(baseline_components.amount_ex_vat, 0)), 2) as baseline_ex_vat,
    round(sum(coalesce(baseline_components.amount_inc_vat, 0)), 2) as baseline_inc_vat
  from baseline_components
  where baseline_components.timesheet_id is not null
    and baseline_components.key_type is not null
    and btrim(baseline_components.key_type) <> ''
    and baseline_components.key_value is not null
    and btrim(baseline_components.key_value) <> ''
    and baseline_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (baseline_components.key_type = 'TS_DAY' and baseline_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')),
    nullif(btrim(coalesce(baseline_components.key_value, '')), '')
),
all_keys as (
  select
    truth_grouped.timesheet_id,
    truth_grouped.key_type,
    truth_grouped.key_value
  from truth_grouped

  union

  select
    baseline_grouped.timesheet_id,
    baseline_grouped.key_type,
    baseline_grouped.key_value
  from baseline_grouped
)
select
  all_keys.timesheet_id,
  all_keys.key_type,
  all_keys.key_value,
  round(coalesce(truth_grouped.truth_ex_vat, 0), 2) as truth_ex_vat,
  round(coalesce(baseline_grouped.baseline_ex_vat, 0), 2) as baseline_ex_vat,
  round(coalesce(truth_grouped.truth_inc_vat, 0), 2) as truth_inc_vat,
  round(coalesce(baseline_grouped.baseline_inc_vat, 0), 2) as baseline_inc_vat
from all_keys
left join truth_grouped
  on truth_grouped.timesheet_id = all_keys.timesheet_id
 and truth_grouped.key_type = all_keys.key_type
 and truth_grouped.key_value = all_keys.key_value
left join baseline_grouped
  on baseline_grouped.timesheet_id = all_keys.timesheet_id
 and baseline_grouped.key_type = all_keys.key_type
 and baseline_grouped.key_value = all_keys.key_value
where all_keys.timesheet_id is not null
  and all_keys.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
  and all_keys.key_value is not null
  and btrim(all_keys.key_value) <> ''
  and not (all_keys.key_type = 'TS_DAY' and all_keys.key_value !~ '^\d{4}-\d{2}-\d{2}$')
order by
  all_keys.timesheet_id,
  all_keys.key_type,
  all_keys.key_value;
$function$;


create or replace function public.pay_manual_credit_adjustment_create(
  p_candidate_id uuid,
  p_amount numeric,
  p_actor_user_id uuid,
  p_adjustment_comment text,
  p_note text default null,
  p_taxability text default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_pay_date date := (now() at time zone 'Europe/London')::date;

  v_settings record;
  v_candidate record;

  v_finance_case_id uuid := null;
  v_finance_component_id uuid := null;

  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_resolution_fingerprint text := null;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;

  v_warnings jsonb := '[]'::jsonb;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;

  v_pay_channel text := null;
  v_paye_treatment text := 'NONE';
  v_paye_net_effect text := null;

  v_taxability public.pay_finance_taxability_enum := null;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;
  v_component_classification public.pay_finance_component_classification_enum := null;

  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;

  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: actor_user_id is required'
    )::text;
  end if;

  if p_amount is null or round(p_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_credit_adjustment_create: amount must be > 0'
    )::text;
  end if;

  if nullif(btrim(coalesce(p_adjustment_comment,'')), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: adjustment_comment is required'
    )::text;
  end if;

  if nullif(upper(btrim(coalesce(p_taxability,''))), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: taxability is required and must be TAXABLE or NON_TAXABLE'
    )::text;
  end if;

  if upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_credit_adjustment_create: taxability must be TAXABLE or NON_TAXABLE',
      'taxability', p_taxability
    )::text;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_manual_credit_adjustment_create: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    upper(coalesce(c.pay_method,'')) as pay_method,
    c.umbrella_id
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_manual_credit_adjustment_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_credit_adjustment_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  v_pay_channel := v_candidate.pay_method;

  if v_pay_channel = 'PAYE' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_ADD';
    v_paye_net_effect := null;
  elsif v_pay_channel = 'PAYE' and v_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := 'NET_ADD';
  elsif v_pay_channel = 'UMBRELLA' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  end if;

  if v_oneoff_required = false then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED',
        'message', 'pay_manual_credit_adjustment_create: one-off bank fields are only allowed for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text,
        'pay_method', v_pay_channel,
        'taxability', v_taxability::text
      )::text;
    end if;
  else
    v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
    v_sort_code_norm := case
      when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
      else null
    end;
    v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');

    if v_beneficiary_name_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'BENEFICIARY_NAME_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: beneficiary_name is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_sort_code_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'SORT_CODE_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: valid sort_code is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_account_number_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'ACCOUNT_NUMBER_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: valid account_number is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
    if v_oneoff_bank_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'BANK_DETAILS_HASH_FAILED',
        'message', 'pay_manual_credit_adjustment_create: unable to derive bank_details_hash for umbrella non-taxable manual credit bank details',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id,
    taxability,
    routing_kind,
    oneoff_bank_details_required
  )
  values (
    p_candidate_id,
    null::uuid,
    'MANUAL_ADVANCE'::public.pay_advance_reason_enum,
    round(p_amount,2),
    round(p_amount,2),
    null::date,
    '[]'::jsonb,
    null::date,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LEGACY_ADVANCE'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    'PENDING'::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    null::numeric,
    null::int,
    null::date,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
    null::numeric,
    null::numeric,
    null::numeric,
    null::numeric,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid,
    v_taxability,
    v_routing_kind,
    v_oneoff_required
  )
  returning id into v_finance_case_id;

  if v_oneoff_required then
    insert into public.pay_finance_case_oneoff_payout_bank_details(
      finance_case_id,
      candidate_id,
      beneficiary_name,
      sort_code,
      account_number,
      bank_details_hash,
      note,
      created_at_utc,
      created_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    values (
      v_finance_case_id,
      p_candidate_id,
      v_beneficiary_name_norm,
      v_sort_code_norm,
      v_account_number_norm,
      v_oneoff_bank_hash,
      nullif(btrim(coalesce(p_bank_details_note,'')), ''),
      v_now_utc,
      p_actor_user_id,
      v_now_utc,
      p_actor_user_id
    );

    v_oneoff_after := jsonb_build_object(
      'finance_case_id', v_finance_case_id::text,
      'candidate_id', p_candidate_id::text,
      'beneficiary_name', v_beneficiary_name_norm,
      'sort_code_masked', case when v_sort_code_norm is null then null else 'XX-XX-' || right(v_sort_code_norm, 2) end,
      'account_number_masked', case when v_account_number_norm is null then null else lpad(right(v_account_number_norm, 4), length(v_account_number_norm), '*') end,
      'bank_details_hash', v_oneoff_bank_hash,
      'note', nullif(btrim(coalesce(p_bank_details_note,'')), '')
    );

    perform public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'ONEOFF_BANK_DETAILS_CREATED',
      v_oneoff_before,
      v_oneoff_after,
      'ONE_OFF_PAYOUT_BANK_DETAILS',
      p_actor_user_id
    );
  end if;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'amount', round(p_amount,2),
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'paye_treatment', v_paye_treatment,
      'paye_net_effect', v_paye_net_effect,
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
    v_component_resolution_payload_json := jsonb_build_object(
      'same_channel', true,
      'target_amount', round(p_amount,2),
      'target_pay_method', v_pay_channel
    );

    v_component_resolution_result_json := jsonb_build_object(
      'target_amount', round(p_amount,2),
      'target_amount_ex_vat', round(p_amount,2),
      'target_amount_vat', 0,
      'target_amount_inc_vat', round(p_amount,2),
      'target_pay_method', v_pay_channel
    );

    v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => 'case:' || v_finance_case_id::text,
      p_component_key_type        => 'CASE_TOTAL',
      p_component_key_value       => 'TOTAL',
      p_classification            => v_component_classification,
      p_source_pay_method         => v_pay_channel,
      p_current_target_pay_method => v_pay_channel,
      p_source_basis_json         => v_component_source_basis_json,
      p_source_amount             => round(p_amount,2),
      p_relevant_erni_pct         => null::numeric,
      p_target_basis_json         => jsonb_build_object('same_channel', true)
    );
  end if;

  insert into public.pay_finance_case_components(
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    'case:' || v_finance_case_id::text,
    'CASE_TOTAL',
    'TOTAL',
    v_component_classification,
    v_pay_channel,
    v_component_source_basis_json,
    round(p_amount,2),
    round(p_amount,2),
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_pay_channel else null end,
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum else null end,
    v_component_resolution_payload_json,
    v_component_resolution_result_json,
    v_component_resolution_fingerprint,
    false,
    null::text,
    0,
    0,
    v_now_utc,
    v_now_utc,
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_now_utc else null end,
    null::timestamptz
  )
  returning id into v_finance_component_id;

  v_component_snapshot_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', 'case:' || v_finance_case_id::text,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', v_component_classification::text,
    'source_pay_method', v_pay_channel,
    'source_basis_json', v_component_source_basis_json,
    'source_amount', round(p_amount,2),
    'remaining_source_amount', round(p_amount,2),
    'saved_target_pay_method', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_pay_channel else null end,
    'saved_resolution_mode', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT' else null end,
    'saved_resolution_payload_json', v_component_resolution_payload_json,
    'saved_resolution_result_json', v_component_resolution_result_json,
    'resolution_fingerprint', v_component_resolution_fingerprint,
    'is_resolution_stale', false
  );

  v_component_summary_json := v_component_snapshot_json;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null::uuid,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'amount', round(p_amount,2),
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'payout_pay_batch_id', null,
      'payout_status', 'PENDING',
      'paye_treatment', v_paye_treatment,
      'paye_net_effect', v_paye_net_effect,
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'oneoff_bank_details_required', v_oneoff_required,
      'component_summary', v_component_summary_json
    ),
    null::text,
    'Manual credit adjustment created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    v_component_summary_json,
    'MANUAL_CREDIT_ADJUSTMENT_CREATE',
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         then 'Created taxable total component for manual credit adjustment'
         else 'Created non-taxable fixed component for manual credit adjustment'
    end
  );

  if v_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := v_oneoff_bank_hash;
    v_readiness_payee_name := v_beneficiary_name_norm;
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  if v_routing_kind in ('NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum, 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum) then
    if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'BLOCKED_BANK_DETAILS',
          'message', case when v_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
                          then 'Bank details are missing; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.'
                          else 'One-off payout bank details are missing or incomplete; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.' end,
          'candidate_id', p_candidate_id::text
        )
      );
    else
      if v_need_name_check = true then
        select
          coalesce(bnc.status, 'UNVERIFIED') as status,
          (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
        into
          v_bnc_status,
          v_bnc_has_override
        from public.bank_name_checks bnc
        where bnc.rail_provider = v_settings.rail_provider_default
          and bnc.rail_env = v_settings.rail_env_default
          and bnc.entity_kind = v_readiness_entity_kind
          and bnc.entity_id = p_candidate_id
          and bnc.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NAME_CHECK',
              'message', 'Name check has not passed (or override missing) for the payout destination; the manual credit adjustment will appear as Blocked for Pay until resolved.',
              'candidate_id', p_candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;

      if v_requires_payee_map = true then
        select (bpm.payee_id is not null) as present
        into v_bpm_present
        from public.bank_payee_map bpm
        where bpm.rail_provider = v_settings.rail_provider_default
          and bpm.rail_env = v_settings.rail_env_default
          and bpm.entity_kind = v_readiness_entity_kind
          and bpm.entity_id = p_candidate_id
          and bpm.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bpm_present,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NO_PAYEE_MAP',
              'message', 'Payee map is missing for the payout destination on this rail; the manual credit adjustment will appear as Blocked for Pay until payee mapping exists.',
              'candidate_id', p_candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'finance_component_id', v_finance_component_id::text,
    'pay_batch_id', null,
    'pay_date', v_pay_date::text,
    'batch_kind_fixed', null,
    'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
    'worker_label', 'Manual credit adjustment',
    'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'oneoff_bank_details_required', v_oneoff_required,
    'oneoff_bank_details_present', v_oneoff_required,
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_oneoff_required then v_beneficiary_name_norm else null end,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;


create or replace function public.pay_manual_credit_adjustment_update(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_amount numeric default null,
  p_adjustment_comment text default null,
  p_note text default null,
  p_taxability text default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null,
  p_remove_oneoff_bank_details boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_batch public.pay_batches%rowtype;
  v_has_batch boolean := false;
  v_is_committed boolean := false;
  v_has_newflow_draft_item boolean := false;
  v_can_edit_pre_draft boolean := false;

  v_new_amount numeric(12,2);
  v_new_comment text;
  v_new_notes text;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_batch_item_id uuid := null;
  v_pay_batch_candidate_id uuid := null;

  v_component public.pay_finance_case_components%rowtype;
  v_component_before_json jsonb := null;
  v_component_after_json jsonb := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_resolution_fingerprint text := null;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
  v_component_changed boolean := false;
  v_component_classification public.pay_finance_component_classification_enum := null;

  v_candidate record;
  v_candidate_pay_method text := null;
  v_current_taxability public.pay_finance_taxability_enum := null;
  v_requested_taxability public.pay_finance_taxability_enum := null;
  v_current_routing_kind public.pay_finance_routing_kind_enum := null;
  v_requested_routing_kind public.pay_finance_routing_kind_enum := null;
  v_current_oneoff_required boolean := false;
  v_requested_oneoff_required boolean := false;

  v_paye_treatment text := 'NONE';
  v_paye_net_effect text := null;
  v_oneoff_change_requested boolean := false;
  v_existing_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;
  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;

  v_settings record;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;
  v_warnings jsonb := '[]'::jsonb;
  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;

  v_taxability_changed boolean := false;
  v_routing_changed boolean := false;
  v_amount_changed boolean := false;
  v_comment_changed boolean := false;
  v_effective_taxability_text text := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: Manual credit adjustment not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    upper(coalesce(c.pay_method,'')) as pay_method,
    c.umbrella_id
  into v_candidate
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := v_candidate.pay_method;
  if v_candidate_pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_credit_adjustment_update: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_case.payout_pay_batch_id is not null then
    select pb.*
    into v_batch
    from public.pay_batches pb
    where pb.id = v_case.payout_pay_batch_id
    limit 1;
    v_has_batch := v_batch.id is not null;
  end if;

  if v_has_batch then
    v_is_committed := (
      coalesce(v_batch.authoritative_payment_date is not null, false)
      or upper(coalesce(v_batch.status,'')) in ('SCHEDULED','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT','EXECUTING','SETTLED','COMPLETED','PARTIAL')
    );
  else
    v_is_committed := false;
  end if;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'MANUAL_CREDIT_PAYOUT'
      and pbi.is_voided = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status,'')) <> 'CANCELLED'
  ) into v_has_newflow_draft_item;

  if v_has_batch then
    v_can_edit_pre_draft := false;
  else
    v_can_edit_pre_draft := (v_has_newflow_draft_item = false);
  end if;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
    and pfc.closed_at_utc is null
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  if v_component.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_COMPONENT_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: linked total finance component not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select *
  into v_existing_oneoff
  from public.pay_finance_case_oneoff_payout_bank_details d
  where d.finance_case_id = p_finance_case_id
  for update;

  v_current_taxability := coalesce(
    v_case.taxability,
    case when v_component.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
         then 'NON_TAXABLE'::public.pay_finance_taxability_enum
         else 'TAXABLE'::public.pay_finance_taxability_enum
    end
  );

  if p_taxability is null then
    v_requested_taxability := v_current_taxability;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_requested_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_requested_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_credit_adjustment_update: taxability must be TAXABLE or NON_TAXABLE when provided',
      'taxability', p_taxability
    )::text;
  end if;

  if v_case.routing_kind is not null then
    v_current_routing_kind := v_case.routing_kind;
  elsif v_candidate_pay_method = 'UMBRELLA' and v_current_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_current_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
  elsif v_candidate_pay_method = 'UMBRELLA' and v_current_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_current_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
  else
    v_current_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
  end if;

  if v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_ADD';
    v_paye_net_effect := null;
  elsif v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := 'NET_ADD';
  elsif v_candidate_pay_method = 'UMBRELLA' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  else
    v_requested_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := true;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  end if;

  v_new_amount := coalesce(round(p_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_comment := case when p_adjustment_comment is null then v_case.adjustment_comment else nullif(btrim(p_adjustment_comment), '') end;
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;

  if p_amount is not null and v_new_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_credit_adjustment_update: amount must be > 0'
    )::text;
  end if;

  if p_adjustment_comment is not null and v_new_comment is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: adjustment_comment is required'
    )::text;
  end if;

  v_amount_changed := round(coalesce(v_case.original_amount,0),2) is distinct from v_new_amount;
  v_comment_changed := coalesce(v_case.adjustment_comment,'') is distinct from coalesce(v_new_comment,'');
  v_taxability_changed := v_current_taxability is distinct from v_requested_taxability;
  v_routing_changed := v_current_routing_kind is distinct from v_requested_routing_kind;
  v_oneoff_change_requested := (
    nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
    or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
    or nullif(btrim(coalesce(p_account_number,'')), '') is not null
    or p_bank_details_note is not null
    or coalesce(p_remove_oneoff_bank_details,false) = true
  );

  if not v_can_edit_pre_draft then
    if v_amount_changed or v_comment_changed or v_taxability_changed or v_routing_changed or v_oneoff_change_requested then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'PAYOUT_ALREADY_DRAFTED_OR_COMMITTED',
        'message', 'pay_manual_credit_adjustment_update: amount, adjustment_comment, taxability, destination and one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;
  end if;

  v_before_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'taxability', case when v_current_taxability is null then null else v_current_taxability::text end,
    'routing_kind', case when v_current_routing_kind is null then null else v_current_routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required, false),
    'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end
  );

  v_component_before_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'resolution_fingerprint', v_component.resolution_fingerprint,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  if v_candidate_pay_method = 'PAYE' then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_manual_credit_adjustment_update: one-off bank fields are not allowed for PAYE manual credits',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null and v_can_edit_pre_draft = true then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'PAY_METHOD_NOW_PAYE',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_requested_routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_UMBRELLA_TAXABLE',
        'message', 'pay_manual_credit_adjustment_update: one-off bank fields are only allowed for umbrella non-taxable manual credits',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null and v_can_edit_pre_draft = true then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'ROUTING_CHANGED_TO_UMBRELLA_COMPANY',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  else
    if v_oneoff_change_requested and not v_can_edit_pre_draft then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_LOCKED',
        'message', 'pay_manual_credit_adjustment_update: one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if coalesce(p_remove_oneoff_bank_details,false) = true then
      if v_existing_oneoff.finance_case_id is not null then
        v_oneoff_before := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        delete from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          'ONEOFF_BANK_DETAILS_REMOVED',
          v_oneoff_before,
          null::jsonb,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := null;
      v_readiness_payee_name := null;
    else
      if v_existing_oneoff.finance_case_id is not null then
        v_beneficiary_name_norm := coalesce(
          nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), ''),
          v_existing_oneoff.beneficiary_name
        );
        v_sort_code_norm := coalesce(
          case
            when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
            else null
          end,
          v_existing_oneoff.sort_code
        );
        v_account_number_norm := coalesce(
          nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), ''),
          v_existing_oneoff.account_number
        );
      else
        v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
        v_sort_code_norm := case
          when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
          else null
        end;
        v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');
      end if;

      if v_beneficiary_name_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'BENEFICIARY_NAME_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: beneficiary_name is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_sort_code_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'SORT_CODE_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: valid sort_code is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_account_number_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'ACCOUNT_NUMBER_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: valid account_number is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
      if v_oneoff_bank_hash is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'BANK_DETAILS_HASH_FAILED',
          'message', 'pay_manual_credit_adjustment_update: unable to derive bank_details_hash for umbrella non-taxable manual credit bank details',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_can_edit_pre_draft then
        v_oneoff_before := case
          when v_existing_oneoff.finance_case_id is null then null
          else jsonb_build_object(
            'finance_case_id', p_finance_case_id::text,
            'candidate_id', v_case.candidate_id::text,
            'beneficiary_name', v_existing_oneoff.beneficiary_name,
            'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
            'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
            'bank_details_hash', v_existing_oneoff.bank_details_hash,
            'note', v_existing_oneoff.note
          )
        end;

        insert into public.pay_finance_case_oneoff_payout_bank_details(
          finance_case_id,
          candidate_id,
          beneficiary_name,
          sort_code,
          account_number,
          bank_details_hash,
          note,
          created_at_utc,
          created_by_user_id,
          updated_at_utc,
          updated_by_user_id
        )
        values (
          p_finance_case_id,
          v_case.candidate_id,
          v_beneficiary_name_norm,
          v_sort_code_norm,
          v_account_number_norm,
          v_oneoff_bank_hash,
          case when p_bank_details_note is null then coalesce(v_existing_oneoff.note, null) else nullif(btrim(coalesce(p_bank_details_note,'')), '') end,
          v_now_utc,
          p_actor_user_id,
          v_now_utc,
          p_actor_user_id
        )
        on conflict (finance_case_id) do update
        set candidate_id = excluded.candidate_id,
            beneficiary_name = excluded.beneficiary_name,
            sort_code = excluded.sort_code,
            account_number = excluded.account_number,
            bank_details_hash = excluded.bank_details_hash,
            note = excluded.note,
            updated_at_utc = excluded.updated_at_utc,
            updated_by_user_id = excluded.updated_by_user_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        v_oneoff_after := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          case when v_oneoff_before is null then 'ONEOFF_BANK_DETAILS_CREATED' else 'ONEOFF_BANK_DETAILS_UPDATED' end,
          v_oneoff_before,
          v_oneoff_after,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := v_oneoff_bank_hash;
      v_readiness_payee_name := v_beneficiary_name_norm;
    end if;
  end if;

  if v_can_edit_pre_draft then
    v_component_source_basis_json := jsonb_strip_nulls(
      jsonb_build_object(
        'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
        'amount', v_new_amount,
        'taxability', v_requested_taxability::text,
        'routing_kind', v_requested_routing_kind::text,
        'paye_treatment', v_paye_treatment,
        'paye_net_effect', v_paye_net_effect,
        'adjustment_comment', v_new_comment,
        'note', v_new_notes
      )
    );

    if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
      v_component_resolution_payload_json := jsonb_build_object(
        'same_channel', true,
        'target_amount', v_new_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_result_json := jsonb_build_object(
        'target_amount', v_new_amount,
        'target_amount_ex_vat', v_new_amount,
        'target_amount_vat', 0,
        'target_amount_inc_vat', v_new_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
        p_source_family_key         => v_component.source_family_key,
        p_component_key_type        => v_component.component_key_type,
        p_component_key_value       => v_component.component_key_value,
        p_classification            => v_component_classification,
        p_source_pay_method         => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json         => v_component_source_basis_json,
        p_source_amount             => v_new_amount,
        p_relevant_erni_pct         => null::numeric,
        p_target_basis_json         => jsonb_build_object('same_channel', true)
      );
    else
      v_component_resolution_payload_json := null;
      v_component_resolution_result_json := null;
      v_component_resolution_fingerprint := null;
    end if;

    v_component_changed := (
      round(coalesce(v_component.source_amount,0),2) is distinct from v_new_amount
      or coalesce(v_case.adjustment_comment,'') is distinct from coalesce(v_new_comment,'')
      or v_current_taxability is distinct from v_requested_taxability
      or v_current_routing_kind is distinct from v_requested_routing_kind
      or v_component.classification is distinct from v_component_classification
      or v_component.source_basis_json is distinct from v_component_source_basis_json
    );

    update public.pay_advances pa
    set original_amount = v_new_amount,
        outstanding_amount = v_new_amount,
        adjustment_comment = v_new_comment,
        notes = v_new_notes,
        updated_at = v_now_utc,
        taxability = v_requested_taxability,
        routing_kind = v_requested_routing_kind,
        oneoff_bank_details_required = v_requested_oneoff_required
    where pa.id = p_finance_case_id;

    update public.pay_finance_case_components pfc
    set classification = v_component_classification,
        source_pay_method = v_candidate_pay_method,
        source_basis_json = v_component_source_basis_json,
        source_amount = v_new_amount,
        remaining_source_amount = v_new_amount,
        saved_target_pay_method = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_candidate_pay_method else null end,
        saved_resolution_mode = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum else null end,
        saved_resolution_payload_json = v_component_resolution_payload_json,
        saved_resolution_result_json = v_component_resolution_result_json,
        resolution_fingerprint = v_component_resolution_fingerprint,
        is_resolution_stale = false,
        stale_reason = null::text,
        updated_at_utc = v_now_utc,
        resolved_at_utc = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_now_utc else null end
    where pfc.id = v_component.id
    returning pfc.* into v_component;

    if v_has_batch then
      select pbc.id
      into v_pay_batch_candidate_id
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = v_batch.id
        and pbc.candidate_id = v_case.candidate_id
      limit 1;

      select pbi.id
      into v_batch_item_id
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc2
        on pbc2.id = pbi.pay_batch_candidate_id
      where pbc2.pay_batch_id = v_batch.id
        and pbc2.candidate_id = v_case.candidate_id
        and pbi.source_ref = ('advance:' || p_finance_case_id::text)
        and pbi.item_type = 'MANUAL_CREDIT_PAYOUT'
        and pbi.is_voided = false
      limit 1;

      if v_pay_batch_candidate_id is not null then
        update public.pay_batch_candidates pbc
        set gross_preview = v_new_amount,
            net_bank_amount = v_new_amount,
            updated_at = v_now_utc
        where pbc.id = v_pay_batch_candidate_id;
      end if;

      if v_batch_item_id is not null then
        v_component_snapshot_json := jsonb_build_object(
          'finance_component_id', v_component.id::text,
          'source_family_key', v_component.source_family_key,
          'component_key_type', v_component.component_key_type,
          'component_key_value', v_component.component_key_value,
          'classification', v_component.classification::text,
          'source_pay_method', v_component.source_pay_method,
          'source_basis_json', v_component.source_basis_json,
          'source_amount', round(coalesce(v_component.source_amount,0),2),
          'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
          'saved_target_pay_method', v_component.saved_target_pay_method,
          'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
          'saved_resolution_payload_json', v_component.saved_resolution_payload_json,
          'saved_resolution_result_json', v_component.saved_resolution_result_json,
          'resolution_fingerprint', v_component.resolution_fingerprint,
          'is_resolution_stale', v_component.is_resolution_stale
        );

        update public.pay_batch_items pbi
        set description = 'Manual credit adjustment',
            amount_ex_vat = v_new_amount,
            amount_vat = 0,
            amount_inc_vat = v_new_amount,
            updated_at = v_now_utc,
            finance_case_id = p_finance_case_id,
            reservation_id = null,
            paye_treatment = v_paye_treatment,
            finance_component_id = v_component.id,
            frozen_component_snapshot_json = v_component_snapshot_json,
            frozen_component_key_type = v_component.component_key_type,
            frozen_component_key_value = v_component.component_key_value,
            frozen_component_classification = v_component.classification,
            frozen_source_basis_json = v_component.source_basis_json,
            frozen_source_pay_method = v_component.source_pay_method,
            frozen_target_pay_method = v_component.saved_target_pay_method,
            frozen_resolution_mode = v_component.saved_resolution_mode,
            frozen_resolution_payload_json = v_component.saved_resolution_payload_json,
            frozen_resolution_result_json = v_component.saved_resolution_result_json,
            frozen_source_amount = v_component.source_amount,
            frozen_target_amount_ex_vat = v_new_amount,
            frozen_target_amount_vat = 0,
            frozen_target_amount_inc_vat = v_new_amount,
            payout_instruction_snapshot_json = case
              when v_requested_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum and v_existing_oneoff.finance_case_id is not null then
                jsonb_build_object(
                  'taxability', v_requested_taxability::text,
                  'routing_kind', v_requested_routing_kind::text,
                  'destination_label', 'one-off specified bank account',
                  'pay_channel', 'UMBRELLA',
                  'payee_entity_kind', 'CANDIDATE',
                  'payee_entity_id', v_case.candidate_id::text,
                  'beneficiary_name', v_existing_oneoff.beneficiary_name,
                  'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
                  'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
                  'bank_details_hash', v_existing_oneoff.bank_details_hash,
                  'bank_details_note', v_existing_oneoff.note,
                  'appears_on_umbrella_remittance', false,
                  'generates_candidate_payment_advice', true
                )
              else null
            end,
            pay_channel = v_candidate_pay_method,
            umbrella_id = case when v_candidate_pay_method = 'UMBRELLA' then v_candidate.umbrella_id else null::uuid end
        where pbi.id = v_batch_item_id;

        update public.pay_batch_item_breakdowns pbib
        set unit_name = 'Manual credit adjustment',
            amount_ex_vat = v_new_amount,
            amount_vat = 0,
            amount_inc_vat = v_new_amount,
            meta_json = jsonb_build_object(
              'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
              'worker_label', 'Manual credit adjustment',
              'adjustment_comment', v_new_comment,
              'finance_component_id', v_component.id::text,
              'taxability', v_requested_taxability::text,
              'routing_kind', v_requested_routing_kind::text,
              'paye_treatment', v_paye_treatment,
              'paye_net_effect', v_paye_net_effect
            )
        where pbib.pay_batch_item_id = v_batch_item_id;
      end if;
    end if;
  else
    update public.pay_advances pa
    set notes = v_new_notes,
        updated_at = v_now_utc
    where pa.id = p_finance_case_id;

    select pa.*
    into v_case
    from public.pay_advances pa
    where pa.id = p_finance_case_id;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  if v_requested_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_requested_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum and v_existing_oneoff.finance_case_id is not null then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_existing_oneoff.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_existing_oneoff.beneficiary_name,'')), '');
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  if v_requested_routing_kind in ('NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum, 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum) then
    if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'BLOCKED_BANK_DETAILS',
          'message', case when v_requested_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
                          then 'Bank details are missing; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.'
                          else 'One-off payout bank details are missing or incomplete; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.' end,
          'candidate_id', v_case.candidate_id::text
        )
      );
    else
      if v_need_name_check = true then
        select
          coalesce(bnc.status, 'UNVERIFIED') as status,
          (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
        into
          v_bnc_status,
          v_bnc_has_override
        from public.bank_name_checks bnc
        where bnc.rail_provider = v_settings.rail_provider_default
          and bnc.rail_env = v_settings.rail_env_default
          and bnc.entity_kind = v_readiness_entity_kind
          and bnc.entity_id = v_case.candidate_id
          and bnc.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NAME_CHECK',
              'message', 'Name check has not passed (or override missing) for the payout destination; the manual credit adjustment will appear as Blocked for Pay until resolved.',
              'candidate_id', v_case.candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;

      if v_requires_payee_map = true then
        select (bpm.payee_id is not null) as present
        into v_bpm_present
        from public.bank_payee_map bpm
        where bpm.rail_provider = v_settings.rail_provider_default
          and bpm.rail_env = v_settings.rail_env_default
          and bpm.entity_kind = v_readiness_entity_kind
          and bpm.entity_id = v_case.candidate_id
          and bpm.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bpm_present,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NO_PAYEE_MAP',
              'message', 'Payee map is missing for the payout destination on this rail; the manual credit adjustment will appear as Blocked for Pay until payee mapping exists.',
              'candidate_id', v_case.candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;
    end if;
  end if;

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required,false),
    'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end
  );

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'resolution_fingerprint', v_component.resolution_fingerprint,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_before_json,
    v_after_json,
    null::text,
    case when v_can_edit_pre_draft then 'Manual credit adjustment updated while Not processed yet' else 'Manual credit adjustment notes updated after draft/commit' end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_component.id,
    'COMPONENT_UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_component_before_json,
    v_component_after_json,
    case when v_component_changed then 'COMPONENT_BASIS_CHANGED' else null::text end,
    case
      when v_can_edit_pre_draft = false then 'Manual credit adjustment draft or later; component basis preserved'
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Manual credit adjustment taxable component updated before draft'
      else 'Manual credit adjustment non-taxable fixed component updated before draft'
    end
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'source_family_key', v_component.source_family_key,
    'component_key_type', v_component.component_key_type,
    'component_key_value', v_component.component_key_value,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'finance_component_id', v_component.id::text,
    'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end,
    'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
    'worker_label', 'Manual credit adjustment',
    'payout_editable', v_can_edit_pre_draft,
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required,false),
    'oneoff_bank_details_present', exists(
      select 1
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id
    ),
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_existing_oneoff.finance_case_id is null then null else v_existing_oneoff.beneficiary_name end,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;



CREATE OR REPLACE FUNCTION public.banking_alert_fingerprint(
  p_alert_kind text,
  p_entity_kind text,
  p_entity_id uuid,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_kind text;
  v_entity_kind text;
  v_payload jsonb;
  v_stable_key text := NULL::text;
  v_payload_stable_key text := NULL::text;
  v_payload_dedupe_key text := NULL::text;
  v_pay_batch_id text := NULL::text;
  v_issue_key text := NULL::text;
  v_provider_key text := NULL::text;
  v_rail_env text := NULL::text;
  v_retry_operation_id text := NULL::text;
  v_outage_window text := NULL::text;
  v_correction_request_id text := NULL::text;
  v_cancellation_operation_id text := NULL::text;
  v_transfer_id text := NULL::text;
  v_manual_blocker_key text := NULL::text;
  v_provider_event_key text := NULL::text;
  v_issue_window text := NULL::text;
  v_terminal_failure_group_key text := NULL::text;
BEGIN
  v_alert_kind := UPPER(NULLIF(BTRIM(COALESCE(p_alert_kind, '')), ''));
  v_entity_kind := LOWER(NULLIF(BTRIM(COALESCE(p_entity_kind, '')), ''));

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_KIND_REQUIRED')::text;
  END IF;

  IF v_entity_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_ENTITY_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_ENTITY_KIND_REQUIRED')::text;
  END IF;

  IF p_entity_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_ENTITY_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_ENTITY_ID_REQUIRED')::text;
  END IF;

  IF p_payload IS NOT NULL AND COALESCE(jsonb_typeof(p_payload), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_FINGERPRINT_PAYLOAD_MUST_BE_OBJECT',
              'alert_kind', v_alert_kind,
              'entity_kind', v_entity_kind,
              'entity_id', p_entity_id::text
            )::text;
  END IF;

  v_payload := COALESCE(p_payload, '{}'::jsonb);

  v_payload_stable_key := NULLIF(BTRIM(COALESCE(v_payload->>'stable_issue_key', '')), '');
  v_payload_dedupe_key := NULLIF(BTRIM(COALESCE(v_payload->>'dedupe_key', '')), '');

  v_pay_batch_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'pay_batch_id'), ''),
    CASE WHEN v_entity_kind IN ('pay_batch', 'pay_batches') THEN p_entity_id::text ELSE NULL END
  );

  v_provider_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'provider'), ''),
    NULLIF(BTRIM(v_payload->>'rail'), ''),
    NULLIF(BTRIM(v_payload->>'rail_provider'), ''),
    NULLIF(BTRIM(v_payload->>'provider_key'), ''),
    'UNKNOWN_PROVIDER'
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_payload->>'rail_env'), ''),
    NULLIF(BTRIM(v_payload->>'provider_env'), ''),
    NULLIF(BTRIM(v_payload->>'environment'), ''),
    'UNKNOWN_ENV'
  );

  v_retry_operation_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'retry_operation_id'), ''),
    NULLIF(BTRIM(v_payload->>'retry_operation_key'), '')
  );

  v_outage_window := COALESCE(
    NULLIF(BTRIM(v_payload->>'outage_window'), ''),
    NULLIF(BTRIM(v_payload->>'retry_window'), ''),
    NULLIF(BTRIM(v_payload->>'provider_outage_window'), '')
  );

  v_correction_request_id := NULLIF(BTRIM(COALESCE(v_payload->>'correction_request_id', '')), '');
  v_cancellation_operation_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'cancellation_operation_id'), ''),
    NULLIF(BTRIM(v_payload->>'correction_request_id'), '')
  );
  v_transfer_id := NULLIF(BTRIM(COALESCE(v_payload->>'pay_bank_transfer_id', '')), '');
  v_manual_blocker_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'carry_forward_id'), ''),
    NULLIF(BTRIM(v_payload->>'source_pay_batch_item_id'), '')
  );

  v_provider_event_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'provider_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_webhook_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_transaction_id'), ''),
    NULLIF(BTRIM(v_payload->>'provider_request_id'), '')
  );

  v_issue_window := COALESCE(
    NULLIF(BTRIM(v_payload->>'issue_window'), ''),
    NULLIF(BTRIM(v_payload->>'outcome_unknown_window'), ''),
    NULLIF(BTRIM(v_payload->>'outage_window'), ''),
    NULLIF(BTRIM(v_payload->>'retry_window'), '')
  );

  v_terminal_failure_group_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'terminal_failure_group_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_failure_reason_group'), ''),
    NULLIF(BTRIM(v_payload->>'failure_reason_group'), ''),
    NULLIF(BTRIM(v_payload->>'provider_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'dedupe_key'), '')
  );

  v_issue_key := CASE
    WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      v_provider_key,
      v_rail_env,
      COALESCE(v_retry_operation_id, v_outage_window, v_issue_window, 'NO_WINDOW')
    )
    WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      v_provider_key,
      COALESCE(v_issue_window, 'NO_WINDOW')
    )
    WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, 'NO_BATCH'),
      v_alert_kind,
      v_provider_key,
      COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
    )
    WHEN v_alert_kind = 'AUTO_UNWIND_PROGRESS'
      AND v_correction_request_id IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_correction_request_id
      )
    WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
      AND v_cancellation_operation_id IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_cancellation_operation_id
      )
    WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      COALESCE(v_correction_request_id, v_terminal_failure_group_key, v_transfer_id, 'NO_TERMINAL_FAILURE_KEY')
    )
    WHEN v_alert_kind IN (
      'PAID_SETTLED_RECOVERY_REQUIRED',
      'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
    )
      AND COALESCE(v_transfer_id, v_correction_request_id, v_terminal_failure_group_key) IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        COALESCE(v_transfer_id, v_correction_request_id, v_terminal_failure_group_key)
      )
    WHEN v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
      AND v_manual_blocker_key IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_manual_blocker_key
      )
    ELSE NULL::text
  END;

  v_stable_key := COALESCE(
    v_payload_stable_key,
    v_payload_dedupe_key,
    v_issue_key,
    CONCAT_WS(':', COALESCE(v_pay_batch_id, p_entity_id::text), v_alert_kind)
  );

  RETURN 'banking_alert:v2:' || MD5(CONCAT_WS(':', v_entity_kind, v_stable_key));
END;
$function$;


DROP FUNCTION IF EXISTS public.banking_alerts_active_for_user(uuid, text, uuid, boolean, integer);

CREATE OR REPLACE FUNCTION public.banking_alerts_active_for_user(
  p_actor_user_id uuid,
  p_entity_kind text DEFAULT NULL::text,
  p_entity_id uuid DEFAULT NULL::uuid,
  p_include_acknowledged boolean DEFAULT false,
  p_limit integer DEFAULT 100,
  p_alert_context text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_entity_kind text := LOWER(NULLIF(BTRIM(COALESCE(p_entity_kind, '')), ''));
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 0), 100);
  v_alert_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_alert_context, '')), ''), '-', '_'));
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_cached_summary_json jsonb := '{}'::jsonb;
  v_source_alerts jsonb := '[]'::jsonb;
  v_filtered_alerts jsonb := '[]'::jsonb;
  v_filtered_count integer := 0;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERTS_ACTIVE_FOR_USER_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERTS_ACTIVE_FOR_USER_ACTOR_REQUIRED')::text;
  END IF;

  IF v_alert_context IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_REQUIRED',
              'message', 'banking_alerts_active_for_user requires an explicit Alerts-panel or alert-management context.'
            )::text;
  END IF;

  IF v_alert_context IN (
    'LIST',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'WATCH',
    'WATCH_SIGNAL',
    'LIVE_WATCH',
    'PROGRESS',
    'PROGRESS_POLLING',
    'PREVIEW',
    'PREVIEW_OPEN',
    'PREVIEW_PROGRESS',
    'OPERATION_GET',
    'OPERATION_PROGRESS',
    'RPC_CHANGES_PING',
    'CHANGES_PING'
  ) THEN
    RAISE EXCEPTION 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_NOT_ALLOWED',
              'context', v_alert_context,
              'message', 'Live/cached alert detail loading is blocked from list, bootstrap, watch, progress, preview, operation polling, and rpc_changes_ping paths.'
            )::text;
  END IF;

  IF v_alert_context NOT IN (
    'ALERT_PANEL',
    'ALERTS_PANEL',
    'ALERT_MANAGEMENT',
    'ALERT_REFRESH_JOB',
    'EXPLICIT_ALERT_REFRESH',
    'USER_TRIGGERED_ALERTS'
  ) THEN
    RAISE EXCEPTION 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERTS_ACTIVE_FOR_USER_CONTEXT_NOT_EXPLICIT',
              'context', v_alert_context,
              'message', 'Banking alerts may only be loaded from an explicit Alerts-panel, alert-management, or alert-refresh flow.'
            )::text;
  END IF;

  SELECT
    COALESCE(alert_summary.alert_hash, v_cached_alert_hash),
    COALESCE(alert_summary.summary_hash, v_cached_summary_hash),
    COALESCE(alert_summary.unacknowledged_count, 0),
    alert_summary.highest_severity,
    alert_summary.highest_label,
    COALESCE(alert_summary.summary_json, '{}'::jsonb)
  INTO
    v_cached_alert_hash,
    v_cached_summary_hash,
    v_cached_unacknowledged_count,
    v_cached_highest_severity,
    v_cached_highest_label,
    v_cached_summary_json
  FROM public.banking_alert_display_summary AS alert_summary
  WHERE alert_summary.actor_user_id = p_actor_user_id;

  IF NOT FOUND THEN
    v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
    v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
    v_cached_unacknowledged_count := 0;
    v_cached_highest_severity := NULL::text;
    v_cached_highest_label := NULL::text;
    v_cached_summary_json := '{}'::jsonb;
  END IF;

  v_source_alerts := CASE
    WHEN jsonb_typeof(v_cached_summary_json->'alerts') = 'array' THEN v_cached_summary_json->'alerts'
    WHEN jsonb_typeof(v_cached_summary_json->'banking_alerts') = 'array' THEN v_cached_summary_json->'banking_alerts'
    ELSE '[]'::jsonb
  END;

  WITH alert_values AS (
    SELECT alert_item.alert_json,
           alert_item.ordinality
    FROM jsonb_array_elements(COALESCE(v_source_alerts, '[]'::jsonb)) WITH ORDINALITY AS alert_item(alert_json, ordinality)
  ),
  filtered_values AS (
    SELECT alert_values.alert_json,
           alert_values.ordinality
    FROM alert_values
    WHERE (
        v_entity_kind IS NULL
        OR LOWER(COALESCE(alert_values.alert_json->>'entity_kind', alert_values.alert_json->>'payload_entity_kind', '')) = v_entity_kind
      )
      AND (
        p_entity_id IS NULL
        OR COALESCE(alert_values.alert_json->>'entity_id', alert_values.alert_json->>'pay_batch_id', '') = p_entity_id::text
      )
      AND (
        COALESCE(p_include_acknowledged, false)
        OR LOWER(BTRIM(COALESCE(alert_values.alert_json->>'acknowledged_for_current_user', 'false'))) NOT IN ('true','t','1','yes','y','on')
      )
  ),
  limited_values AS (
    SELECT filtered_values.alert_json,
           filtered_values.ordinality
    FROM filtered_values
    ORDER BY filtered_values.ordinality ASC
    LIMIT v_limit
  )
  SELECT
    COALESCE(jsonb_agg(limited_values.alert_json ORDER BY limited_values.ordinality), '[]'::jsonb),
    (SELECT COUNT(*)::integer FROM filtered_values)
  INTO
    v_filtered_alerts,
    v_filtered_count
  FROM limited_values;

  RETURN jsonb_build_object(
    'ok', true,
    'generated_at_utc', now()::text,
    'actor_user_id', p_actor_user_id::text,
    'alert_context', v_alert_context,
    'include_acknowledged', COALESCE(p_include_acknowledged, false),
    'limit', v_limit,
    'alerts', COALESCE(v_filtered_alerts, '[]'::jsonb),
    'banking_alert_hash', COALESCE(v_cached_alert_hash, 'banking_alert_signal:v3:' || MD5('')),
    'banking_alert_summary_signature', COALESCE(v_cached_summary_hash, 'banking_alert_summary:v3:' || MD5('')),
    'banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
    'banking_highest_alert_severity', COALESCE(v_cached_highest_severity, ''),
    'banking_highest_alert_label', COALESCE(v_cached_highest_label, ''),
    'unacknowledged_count', COALESCE(v_cached_unacknowledged_count, 0),
    'filtered_count', COALESCE(v_filtered_count, 0),
    'highest_severity', v_cached_highest_severity,
    'highest_label', v_cached_highest_label,
    'cached', true,
    'summary_json', COALESCE(v_cached_summary_json, '{}'::jsonb)
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge(
  p_alert_fingerprint text,
  p_alert_kind text,
  p_entity_kind text,
  p_entity_id uuid,
  p_actor_user_id uuid,
  p_note text DEFAULT NULL::text,
  p_alert_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_fingerprint text := nullif(btrim(coalesce(p_alert_fingerprint, '')), '');
  v_alert_kind text := upper(nullif(btrim(coalesce(p_alert_kind, '')), ''));
  v_entity_kind text := lower(nullif(btrim(coalesce(p_entity_kind, '')), ''));
  v_alert_payload_json jsonb := '{}'::jsonb;
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_active_alert_json jsonb := NULL::jsonb;
  v_current_alert_fingerprint text := NULL::text;
  v_existing_id uuid := NULL::uuid;
  v_existing_alert_kind text := NULL::text;
  v_existing_entity_kind text := NULL::text;
  v_existing_entity_id uuid := NULL::uuid;
  v_existing_alert_payload_json jsonb := '{}'::jsonb;
  v_ack_id uuid;
  v_ack_alert_fingerprint text;
  v_ack_alert_kind text;
  v_ack_entity_kind text;
  v_ack_entity_id uuid;
  v_acknowledged_by_user_id uuid;
  v_acknowledged_at_utc timestamptz;
  v_acknowledge_scope text;
  v_ack_note text;
  v_ack_alert_payload_json jsonb;
  v_ack_resolved_at_ack boolean;
  v_created boolean := false;
  v_upsert_inserted boolean := false;
  v_remaining_count integer := 0;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF v_alert_fingerprint IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_FINGERPRINT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_FINGERPRINT_REQUIRED')::text;
  END IF;

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_KIND_REQUIRED')::text;
  END IF;

  IF v_entity_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_KIND_REQUIRED')::text;
  END IF;

  IF p_entity_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ACTOR_REQUIRED')::text;
  END IF;

  IF p_alert_payload_json IS NOT NULL AND coalesce(jsonb_typeof(p_alert_payload_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_ACKNOWLEDGE_PAYLOAD_MUST_BE_OBJECT',
              'alert_fingerprint', v_alert_fingerprint
            )::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge:' || v_alert_fingerprint),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  v_alert_payload_json := coalesce(p_alert_payload_json, '{}'::jsonb);

  SELECT
    public.banking_alert_acknowledgements.id,
    public.banking_alert_acknowledgements.alert_kind,
    public.banking_alert_acknowledgements.entity_kind,
    public.banking_alert_acknowledgements.entity_id,
    COALESCE(public.banking_alert_acknowledgements.alert_payload_json, '{}'::jsonb)
  INTO
    v_existing_id,
    v_existing_alert_kind,
    v_existing_entity_kind,
    v_existing_entity_id,
    v_existing_alert_payload_json
  FROM public.banking_alert_acknowledgements
  WHERE public.banking_alert_acknowledgements.alert_fingerprint = v_alert_fingerprint
    AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
    AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
  ORDER BY public.banking_alert_acknowledgements.acknowledged_at_utc ASC, public.banking_alert_acknowledgements.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    IF v_alert_payload_json = '{}'::jsonb THEN
      v_alert_payload_json := COALESCE(v_existing_alert_payload_json, '{}'::jsonb);
    END IF;
  ELSE
    v_active_json := public.banking_alerts_active_for_user(
      p_actor_user_id,
      v_entity_kind,
      p_entity_id,
      false,
      0
    );

    SELECT active_alert.alert_json
    INTO v_active_alert_json
    FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
    WHERE active_alert.alert_json ->> 'alert_fingerprint' = v_alert_fingerprint
      AND upper(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', ''))) = v_alert_kind
      AND lower(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', ''))) = v_entity_kind
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
      AND (active_alert.alert_json ->> 'entity_id')::uuid = p_entity_id
    LIMIT 1;

    IF v_active_alert_json IS NULL THEN
      SELECT
        public.banking_alert_acknowledgements.id,
        public.banking_alert_acknowledgements.alert_kind,
        public.banking_alert_acknowledgements.entity_kind,
        public.banking_alert_acknowledgements.entity_id,
        COALESCE(public.banking_alert_acknowledgements.alert_payload_json, '{}'::jsonb)
      INTO
        v_existing_id,
        v_existing_alert_kind,
        v_existing_entity_kind,
        v_existing_entity_id,
        v_existing_alert_payload_json
      FROM public.banking_alert_acknowledgements
      WHERE public.banking_alert_acknowledgements.alert_fingerprint = v_alert_fingerprint
        AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
        AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
      ORDER BY public.banking_alert_acknowledgements.acknowledged_at_utc ASC, public.banking_alert_acknowledgements.id ASC
      LIMIT 1;

      IF v_existing_id IS NOT NULL THEN
        IF v_alert_payload_json = '{}'::jsonb THEN
          v_alert_payload_json := COALESCE(v_existing_alert_payload_json, '{}'::jsonb);
        END IF;
      ELSE
        SELECT active_alert.alert_json ->> 'alert_fingerprint'
        INTO v_current_alert_fingerprint
        FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
        WHERE upper(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', ''))) = v_alert_kind
          AND lower(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', ''))) = v_entity_kind
          AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
          AND (active_alert.alert_json ->> 'entity_id')::uuid = p_entity_id
        ORDER BY active_alert.alert_json ->> 'alert_fingerprint'
        LIMIT 1;

        v_remaining_json := public.banking_alerts_active_for_user(
          p_actor_user_id,
          NULL::text,
          NULL::uuid,
          false,
          25
        );

        v_signal_json := public.banking_alert_signal_for_user(
          p_actor_user_id,
          NULL::text
        );

        v_remaining_json := v_remaining_json || jsonb_build_object(
          'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
          'banking_unacknowledged_alert_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
          'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
          'unacknowledged_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
          'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
        );

        RETURN jsonb_build_object(
          'ok', true,
          'created', false,
          'already_acknowledged', false,
          'acknowledged', false,
          'ignored', true,
          'ignored_count', 1,
          'reason', 'ALERT_NOT_CURRENT',
          'code', 'BANKING_ALERT_ACKNOWLEDGE_ALERT_NOT_ACTIVE',
          'alert_fingerprint', v_alert_fingerprint,
          'alert_kind', v_alert_kind,
          'entity_kind', v_entity_kind,
          'entity_id', p_entity_id::text,
          'current_alert_fingerprint', v_current_alert_fingerprint,
          'entity_alert_summary', v_active_json,
          'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
          'banking_unacknowledged_alert_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
          'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
          'remaining_alert_summary', v_remaining_json,
          'alert_summary', v_remaining_json
        );
      END IF;
    END IF;

    IF v_existing_id IS NULL AND v_alert_payload_json = '{}'::jsonb THEN
      v_alert_payload_json := coalesce(v_active_alert_json -> 'payload_json', '{}'::jsonb);
    END IF;
  END IF;

  INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
    alert_fingerprint,
    alert_kind,
    entity_kind,
    entity_id,
    acknowledged_by_user_id,
    acknowledged_at_utc,
    acknowledge_scope,
    note,
    alert_payload_json,
    resolved_at_ack
  )
  VALUES (
    v_alert_fingerprint,
    v_alert_kind,
    v_entity_kind,
    p_entity_id,
    p_actor_user_id,
    now(),
    'USER',
    nullif(btrim(coalesce(p_note, '')), ''),
    v_alert_payload_json,
    false
  )
  ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
  SET
    note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
    alert_payload_json = CASE
      WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
      ELSE EXCLUDED.alert_payload_json
    END
  RETURNING
    banking_alert_acknowledgement_upsert.id,
    banking_alert_acknowledgement_upsert.alert_fingerprint,
    banking_alert_acknowledgement_upsert.alert_kind,
    banking_alert_acknowledgement_upsert.entity_kind,
    banking_alert_acknowledgement_upsert.entity_id,
    banking_alert_acknowledgement_upsert.acknowledged_by_user_id,
    banking_alert_acknowledgement_upsert.acknowledged_at_utc,
    banking_alert_acknowledgement_upsert.acknowledge_scope,
    banking_alert_acknowledgement_upsert.note,
    banking_alert_acknowledgement_upsert.alert_payload_json,
    banking_alert_acknowledgement_upsert.resolved_at_ack,
    (banking_alert_acknowledgement_upsert.xmax = 0)
  INTO
    v_ack_id,
    v_ack_alert_fingerprint,
    v_ack_alert_kind,
    v_ack_entity_kind,
    v_ack_entity_id,
    v_acknowledged_by_user_id,
    v_acknowledged_at_utc,
    v_acknowledge_scope,
    v_ack_note,
    v_ack_alert_payload_json,
    v_ack_resolved_at_ack,
    v_upsert_inserted;

  v_created := coalesce(v_upsert_inserted, false);

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'created', v_created,
    'already_acknowledged', NOT v_created,
    'acknowledged', true,
    'ignored', false,
    'ignored_count', 0,
    'remaining_unacknowledged_count', v_remaining_count,
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json,
    'acknowledgement', jsonb_build_object(
      'id', v_ack_id::text,
      'alert_fingerprint', v_ack_alert_fingerprint,
      'alert_kind', v_ack_alert_kind,
      'entity_kind', v_ack_entity_kind,
      'entity_id', v_ack_entity_id::text,
      'acknowledged_by_user_id', v_acknowledged_by_user_id::text,
      'acknowledged_at_utc', v_acknowledged_at_utc::text,
      'acknowledge_scope', v_acknowledge_scope,
      'note', v_ack_note,
      'alert_payload_json', v_ack_alert_payload_json,
      'resolved_at_ack', v_ack_resolved_at_ack
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge_many(
  p_actor_user_id uuid,
  p_alerts_json jsonb,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_requested_count integer := 0;
  v_created_count integer := 0;
  v_already_acknowledged_count integer := 0;
  v_acknowledged_count integer := 0;
  v_ignored_count integer := 0;
  v_remaining_count integer := 0;
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_acknowledged_alerts jsonb := '[]'::jsonb;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_MANY_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_MANY_ACTOR_REQUIRED')::text;
  END IF;

  IF p_alerts_json IS NULL OR coalesce(jsonb_typeof(p_alerts_json), 'null') <> 'array' THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_MANY_ALERTS_ARRAY_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_MANY_ALERTS_ARRAY_REQUIRED')::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge_many'),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  WITH requested_fingerprints_for_count AS (
    SELECT DISTINCT
      nullif(btrim(coalesce(
        CASE
          WHEN jsonb_typeof(requested_alerts_for_count.requested_alert_json) = 'string'
            THEN trim(both '"' from requested_alerts_for_count.requested_alert_json::text)
          WHEN jsonb_typeof(requested_alerts_for_count.requested_alert_json) = 'object'
            THEN COALESCE(
              requested_alerts_for_count.requested_alert_json ->> 'alert_fingerprint',
              requested_alerts_for_count.requested_alert_json ->> 'fingerprint'
            )
          ELSE NULL::text
        END,
        ''
      )), '') AS alert_fingerprint
    FROM jsonb_array_elements(p_alerts_json) AS requested_alerts_for_count(requested_alert_json)
  )
  SELECT count(*)::integer
  INTO v_requested_count
  FROM requested_fingerprints_for_count
  WHERE requested_fingerprints_for_count.alert_fingerprint IS NOT NULL;

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    0
  );

  WITH requested_fingerprints AS (
    SELECT DISTINCT
      nullif(btrim(coalesce(
        CASE
          WHEN jsonb_typeof(requested_alerts.requested_alert_json) = 'string'
            THEN trim(both '"' from requested_alerts.requested_alert_json::text)
          WHEN jsonb_typeof(requested_alerts.requested_alert_json) = 'object'
            THEN COALESCE(
              requested_alerts.requested_alert_json ->> 'alert_fingerprint',
              requested_alerts.requested_alert_json ->> 'fingerprint'
            )
          ELSE NULL::text
        END,
        ''
      )), '') AS alert_fingerprint
    FROM jsonb_array_elements(p_alerts_json) AS requested_alerts(requested_alert_json)
  ),
  active_alerts AS (
    SELECT
      active_alert.alert_json ->> 'alert_fingerprint' AS alert_fingerprint,
      active_alert.alert_json ->> 'alert_kind' AS alert_kind,
      active_alert.alert_json ->> 'entity_kind' AS entity_kind,
      (active_alert.alert_json ->> 'entity_id')::uuid AS entity_id,
      active_alert.alert_json AS alert_json,
      coalesce(active_alert.alert_json -> 'payload_json', '{}'::jsonb) AS payload_json
    FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
    WHERE nullif(btrim(coalesce(active_alert.alert_json ->> 'alert_fingerprint', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
  ),
  matched_active_alerts AS (
    SELECT DISTINCT ON (active_alerts.alert_fingerprint)
      active_alerts.alert_fingerprint,
      upper(btrim(active_alerts.alert_kind)) AS alert_kind,
      lower(btrim(active_alerts.entity_kind)) AS entity_kind,
      active_alerts.entity_id,
      active_alerts.alert_json,
      coalesce(active_alerts.payload_json, '{}'::jsonb) AS payload_json
    FROM active_alerts
    JOIN requested_fingerprints
      ON requested_fingerprints.alert_fingerprint = active_alerts.alert_fingerprint
    WHERE requested_fingerprints.alert_fingerprint IS NOT NULL
    ORDER BY active_alerts.alert_fingerprint ASC
  ),
  upserted_acknowledgements AS (
    INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
      alert_fingerprint,
      alert_kind,
      entity_kind,
      entity_id,
      acknowledged_by_user_id,
      acknowledged_at_utc,
      acknowledge_scope,
      note,
      alert_payload_json,
      resolved_at_ack
    )
    SELECT
      matched_active_alerts.alert_fingerprint,
      matched_active_alerts.alert_kind,
      matched_active_alerts.entity_kind,
      matched_active_alerts.entity_id,
      p_actor_user_id,
      now(),
      'USER',
      nullif(btrim(coalesce(p_note, '')), ''),
      matched_active_alerts.payload_json,
      false
    FROM matched_active_alerts
    WHERE true
    ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
    SET
      note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
      alert_payload_json = CASE
        WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
        ELSE EXCLUDED.alert_payload_json
      END
    RETURNING
      banking_alert_acknowledgement_upsert.alert_fingerprint,
      banking_alert_acknowledgement_upsert.alert_kind,
      banking_alert_acknowledgement_upsert.entity_kind,
      banking_alert_acknowledgement_upsert.entity_id,
      banking_alert_acknowledgement_upsert.acknowledged_at_utc,
      (banking_alert_acknowledgement_upsert.xmax = 0) AS created
  ),
  already_existing_requested_acknowledgements AS (
    SELECT DISTINCT ON (public.banking_alert_acknowledgements.alert_fingerprint)
      public.banking_alert_acknowledgements.alert_fingerprint,
      public.banking_alert_acknowledgements.alert_kind,
      public.banking_alert_acknowledgements.entity_kind,
      public.banking_alert_acknowledgements.entity_id,
      public.banking_alert_acknowledgements.acknowledged_at_utc,
      false AS created
    FROM public.banking_alert_acknowledgements
    JOIN requested_fingerprints
      ON requested_fingerprints.alert_fingerprint = public.banking_alert_acknowledgements.alert_fingerprint
    LEFT JOIN upserted_acknowledgements
      ON upserted_acknowledgements.alert_fingerprint = public.banking_alert_acknowledgements.alert_fingerprint
    WHERE requested_fingerprints.alert_fingerprint IS NOT NULL
      AND upserted_acknowledgements.alert_fingerprint IS NULL
      AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
      AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
    ORDER BY public.banking_alert_acknowledgements.alert_fingerprint ASC,
             public.banking_alert_acknowledgements.acknowledged_at_utc ASC,
             public.banking_alert_acknowledgements.id ASC
  ),
  changed_acknowledgements AS (
    SELECT
      upserted_acknowledgements.alert_fingerprint,
      upserted_acknowledgements.alert_kind,
      upserted_acknowledgements.entity_kind,
      upserted_acknowledgements.entity_id,
      upserted_acknowledgements.acknowledged_at_utc,
      upserted_acknowledgements.created
    FROM upserted_acknowledgements

    UNION ALL

    SELECT
      already_existing_requested_acknowledgements.alert_fingerprint,
      already_existing_requested_acknowledgements.alert_kind,
      already_existing_requested_acknowledgements.entity_kind,
      already_existing_requested_acknowledgements.entity_id,
      already_existing_requested_acknowledgements.acknowledged_at_utc,
      already_existing_requested_acknowledgements.created
    FROM already_existing_requested_acknowledgements
  )
  SELECT
    coalesce(count(*) FILTER (WHERE changed_acknowledgements.created = true), 0)::integer,
    coalesce(count(*) FILTER (WHERE changed_acknowledgements.created = false), 0)::integer,
    coalesce(count(*), 0)::integer,
    coalesce(jsonb_agg(jsonb_build_object(
      'alert_fingerprint', changed_acknowledgements.alert_fingerprint,
      'alert_kind', changed_acknowledgements.alert_kind,
      'entity_kind', changed_acknowledgements.entity_kind,
      'entity_id', changed_acknowledgements.entity_id::text,
      'acknowledged_at_utc', changed_acknowledgements.acknowledged_at_utc::text,
      'created', changed_acknowledgements.created,
      'already_acknowledged', NOT changed_acknowledgements.created
    ) ORDER BY changed_acknowledgements.acknowledged_at_utc DESC, changed_acknowledgements.alert_fingerprint ASC), '[]'::jsonb)
  INTO
    v_created_count,
    v_already_acknowledged_count,
    v_acknowledged_count,
    v_acknowledged_alerts
  FROM changed_acknowledgements;

  v_ignored_count := greatest(coalesce(v_requested_count, 0) - coalesce(v_acknowledged_count, 0), 0);

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'requested_count', coalesce(v_requested_count, 0),
    'created_count', coalesce(v_created_count, 0),
    'already_acknowledged_count', coalesce(v_already_acknowledged_count, 0),
    'acknowledged_count', coalesce(v_acknowledged_count, 0),
    'remaining_unacknowledged_count', coalesce(v_remaining_count, 0),
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', coalesce(v_remaining_count, 0),
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'ignored_count', coalesce(v_ignored_count, 0),
    'acknowledged_alerts', coalesce(v_acknowledged_alerts, '[]'::jsonb),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.banking_alert_payload_for_pay_batch(text, uuid);

CREATE OR REPLACE FUNCTION public.banking_alert_payload_for_pay_batch(
  p_alert_kind text,
  p_pay_batch_id uuid,
  p_source_kind text DEFAULT NULL::text,
  p_source_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_kind text;
  v_source_kind text;
  v_batch record;
  v_funds_check_json jsonb := '{}'::jsonb;
  v_required_gbp_text text := NULL;
  v_available_gbp_text text := NULL;
  v_required_gbp numeric := NULL;
  v_available_gbp numeric := NULL;
  v_sufficient_text text := NULL;
  v_sufficient boolean := NULL;
  v_funding_account_ref text := NULL;
  v_rail_provider text := NULL;
  v_rail_env text := NULL;
  v_funds_check_checked_at_utc text := NULL;
  v_last_funds_check_at_utc_text text := NULL;
  v_execution_committed_at_utc_text text := NULL;
  v_last_status_checked_at_utc_text text := NULL;
  v_latest_transfer jsonb := NULL;
  v_latest_transfer_event jsonb := NULL;
  v_latest_correction_request jsonb := NULL;
  v_latest_correction_work_item jsonb := NULL;
  v_latest_remittance_failure jsonb := NULL;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL;
  v_review_reason_code text := NULL;
  v_provider_operation_id uuid := NULL::uuid;
  v_provider_title text := NULL;
  v_provider_description text := NULL;
  v_provider_action_label text := NULL;
  v_grouped_alert_payload jsonb := '{}'::jsonb;
  v_provider_failure_reason_code text := NULL::text;
  v_provider_failure_reason_group text := NULL::text;
  v_provider_failure_reason_label text := NULL::text;
  v_provider_event_key text := NULL::text;
  v_webhook_receipt_id uuid := NULL::uuid;
BEGIN
  v_alert_kind := UPPER(NULLIF(BTRIM(COALESCE(p_alert_kind, '')), ''));
  v_source_kind := lower(nullif(btrim(coalesce(p_source_kind, '')), ''));

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PAYLOAD_KIND_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PAYLOAD_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  v_alert_kind := CASE v_alert_kind
    WHEN 'BLOCKED_FUNDS' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
    WHEN 'BANK_REJECTED_PAYMENT' THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
    WHEN 'BANK_RETURNED_PAYMENT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'PAYMENT_PROVIDER_SUBMIT_REVIEW' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    WHEN 'PAYMENT_CORRECTION_AWAITING_APPROVAL' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    ELSE v_alert_kind
  END;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.bulk_reference,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.funding_account_ref,
    public.pay_batches.last_funds_check_at_utc,
    public.pay_batches.last_funds_check_json,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.last_status_checked_at_utc,
    public.pay_batches.cancelled_at_utc,
    public.pay_batches.completed_at_utc
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_PAYLOAD_PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_funds_check_json := COALESCE(v_batch.last_funds_check_json, '{}'::jsonb);

  v_required_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{required_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount}'), '')
  );

  IF v_required_gbp_text IS NOT NULL AND v_required_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_required_gbp := v_required_gbp_text::numeric;
  END IF;

  v_available_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{available_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount}'), '')
  );

  IF v_available_gbp_text IS NOT NULL AND v_available_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_available_gbp := v_available_gbp_text::numeric;
  END IF;

  v_sufficient_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{sufficient}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{is_sufficient}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{funds_sufficient}'), '')
  );

  IF v_sufficient_text IS NOT NULL THEN
    IF LOWER(v_sufficient_text) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_sufficient := true;
    ELSIF LOWER(v_sufficient_text) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_sufficient := false;
    END IF;
  END IF;

  v_funding_account_ref := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_id}'), ''),
    NULLIF(BTRIM(v_batch.funding_account_ref), '')
  );

  v_rail_provider := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_provider}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{provider}'), ''),
    NULLIF(BTRIM(v_batch.rail_provider_snapshot), '')
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_env}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{env}'), ''),
    NULLIF(BTRIM(v_batch.rail_env_snapshot), '')
  );

  v_last_funds_check_at_utc_text := CASE
    WHEN v_batch.last_funds_check_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.last_funds_check_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_execution_committed_at_utc_text := CASE
    WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.execution_committed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_last_status_checked_at_utc_text := CASE
    WHEN v_batch.last_status_checked_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.last_status_checked_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_funds_check_checked_at_utc := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{checked_at_utc}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{checked_at}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{created_at_utc}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{timestamp_utc}'), ''),
    v_last_funds_check_at_utc_text
  );

  SELECT
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_code, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_event_key, '')), ''),
    provider_failure_event.provider_webhook_receipt_id
  INTO
    v_provider_failure_reason_code,
    v_provider_failure_reason_group,
    v_provider_failure_reason_label,
    v_provider_event_key,
    v_webhook_receipt_id
  FROM public.pay_bank_transfer_events AS provider_failure_event
  WHERE provider_failure_event.pay_batch_id = p_pay_batch_id
    AND (
      v_source_kind IS DISTINCT FROM 'pay_bank_transfer_event'
      OR p_source_id IS NULL
      OR provider_failure_event.id = p_source_id
    )
    AND (
      NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(provider_failure_event.provider_event_key, '')), '') IS NOT NULL
      OR provider_failure_event.provider_webhook_receipt_id IS NOT NULL
      OR UPPER(BTRIM(COALESCE(provider_failure_event.mapping_status, ''))) IN ('UNMATCHED','NO_MATCH','MULTIPLE_MATCHES')
    )
  ORDER BY COALESCE(provider_failure_event.event_time_utc, provider_failure_event.received_at_utc, provider_failure_event.created_at_utc) DESC NULLS LAST,
           provider_failure_event.id DESC
  LIMIT 1;

  IF v_provider_failure_reason_group IS NOT NULL THEN
    v_provider_failure_reason_label := initcap(replace(lower(v_provider_failure_reason_group), '_', ' '));
  END IF;

  IF v_alert_kind IN (
    'PROVIDER_OUTAGE_RETRY_LATER',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
    'AUTO_UNWIND_PROGRESS',
    'WHOLE_BATCH_CANCELLATION_PROGRESS',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
  ) THEN
    WITH retry_plan_scope AS (
      SELECT COALESCE(public.pay_payment_correction_plan(
        p_pay_batch_id,
        jsonb_build_object(
          'scope_type', 'BATCH',
          'source_context', 'BANKING_ALERT_PAYLOAD',
          'requested_action', 'RETRY_PROVIDER_LATER'
        ),
        NULL::uuid
      ), '{}'::jsonb) AS retry_plan_json
    ),
    retry_operation_scope AS (
      SELECT
        retry_operation.id AS retry_operation_id,
        retry_operation.status AS retry_operation_status
      FROM public.banking_pay_operations AS retry_operation
      WHERE retry_operation.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(retry_operation.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
        AND UPPER(BTRIM(COALESCE(retry_operation.status, ''))) NOT IN ('COMPLETE','COMPLETED','SUCCEEDED','SUCCESS','FAILED','FAILED_FINAL','CANCELLED','CANCELED')
      ORDER BY COALESCE(retry_operation.updated_at_utc, retry_operation.created_at_utc) DESC NULLS LAST,
               retry_operation.created_at_utc DESC NULLS LAST,
               retry_operation.id DESC
      LIMIT 1
    ),
    retry_plan_counts AS (
      SELECT
        CASE
          WHEN COALESCE(retry_plan_scope.retry_plan_json->>'retry_eligible_count', '') ~ '^\d+$' THEN (retry_plan_scope.retry_plan_json->>'retry_eligible_count')::integer
          ELSE 0
        END AS retry_eligible_count,
        CASE
          WHEN COALESCE(retry_plan_scope.retry_plan_json->>'retry_ineligible_count', '') ~ '^\d+$' THEN (retry_plan_scope.retry_plan_json->>'retry_ineligible_count')::integer
          ELSE 0
        END AS retry_ineligible_count
      FROM retry_plan_scope
    ),
    item_counts AS (
      SELECT
        COUNT(DISTINCT pbi.id)::integer AS affected_payment_count,
        COUNT(DISTINCT pbc.candidate_id)::integer AS affected_candidate_count,
        COUNT(DISTINCT pbi.pay_bank_transfer_id) FILTER (WHERE pbi.pay_bank_transfer_id IS NOT NULL)::integer AS affected_transfer_count,
        COUNT(DISTINCT pbi.timesheet_id) FILTER (WHERE pbi.timesheet_id IS NOT NULL)::integer AS affected_timesheet_count,
        ROUND(COALESCE(SUM(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0)), 0), 2)::numeric AS amount_affected
      FROM public.pay_batch_candidates AS pbc
      JOIN public.pay_batch_items AS pbi
        ON pbi.pay_batch_candidate_id = pbc.id
      WHERE pbc.pay_batch_id = p_pay_batch_id
        AND COALESCE(pbi.is_voided, false) = false
        AND pbi.item_type <> 'DEBT_CREATED'
    ),
    correction_scope AS (
      SELECT
        (array_agg(ppcr.id ORDER BY ppcr.updated_at_utc DESC NULLS LAST, ppcr.created_at_utc DESC, ppcr.id DESC))[1] AS correction_request_id,
        COUNT(ppwi.id) FILTER (WHERE ppwi.status IN ('APPLIED','DONE','COMPLETE','COMPLETED'))::integer AS progress_completed,
        COUNT(ppwi.id)::integer AS progress_total,
        bool_or(ppcr.status IN ('AUTHORISED','EXPANDED','PROCESSING')) AS correction_running
      FROM public.pay_payment_correction_requests AS ppcr
      LEFT JOIN public.pay_payment_correction_work_items AS ppwi
        ON ppwi.correction_request_id = ppcr.id
      WHERE ppcr.pay_batch_id = p_pay_batch_id
        AND (
          (v_alert_kind = 'AUTO_UNWIND_PROGRESS' AND ppcr.correction_kind IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'))
          OR (v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' AND ppcr.correction_kind = 'PRE_BANK_CANCEL')
          OR v_alert_kind NOT IN ('AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS')
        )
    ),
    carry_forward_scope AS (
      SELECT
        COUNT(*)::integer AS carry_forward_count,
        (array_agg(cf.id ORDER BY cf.id DESC))[1] AS carry_forward_id,
        (array_agg(cf.source_pay_batch_item_id ORDER BY cf.id DESC))[1] AS source_pay_batch_item_id
      FROM public.pay_manual_adjustment_carry_forwards AS cf
      WHERE cf.source_pay_batch_id = p_pay_batch_id
         OR cf.target_pay_batch_id = p_pay_batch_id
    ),
    single_transfer_scope AS (
      SELECT pbt.id AS pay_bank_transfer_id
      FROM public.pay_bank_transfers AS pbt
      WHERE pbt.pay_batch_id = p_pay_batch_id
        AND v_source_kind = 'pay_bank_transfer'
        AND pbt.id = p_source_id
      LIMIT 1
    )
    SELECT jsonb_strip_nulls(
      jsonb_build_object(
        'stable_issue_key', CASE
          WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text, (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros), 'NO_WINDOW')
          WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_execution_committed_at_utc_text, 'NO_WINDOW')
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(p_pay_batch_id::text, 'NO_BATCH') || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
          WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_failure_reason_group, v_provider_event_key, 'NO_TERMINAL_FAILURE_KEY')
          WHEN v_alert_kind = 'AUTO_UNWIND_PROGRESS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), 'NO_CORRECTION_REQUEST')
          WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), 'NO_CORRECTION_REQUEST')
          WHEN v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs), (SELECT cfs.source_pay_batch_item_id::text FROM carry_forward_scope AS cfs), 'NO_BLOCKER_KEY')
          WHEN v_alert_kind IN ('PAID_SETTLED_RECOVERY_REQUIRED','CANCELLATION_RACED_WITH_PROVIDER_SUBMIT') THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts), (SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_event_key, 'NO_SCOPE_KEY')
          ELSE p_pay_batch_id::text || ':' || v_alert_kind
        END,
        'dedupe_key', CASE
          WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text, (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros), 'NO_WINDOW')
          WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_execution_committed_at_utc_text, 'NO_WINDOW')
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(p_pay_batch_id::text, 'NO_BATCH') || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
          WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_failure_reason_group, v_provider_event_key, 'NO_TERMINAL_FAILURE_KEY')
          WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NOT NULL THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT cs.correction_request_id::text FROM correction_scope AS cs)
          WHEN (SELECT sts.pay_bank_transfer_id FROM single_transfer_scope AS sts) IS NOT NULL THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts)
          WHEN (SELECT cfs.carry_forward_id FROM carry_forward_scope AS cfs) IS NOT NULL AND v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs)
          ELSE p_pay_batch_id::text || ':' || v_alert_kind
        END,
        'alert_kind', v_alert_kind,
        'issue_kind', v_alert_kind,
        'alert_severity', CASE
          WHEN v_alert_kind IN ('AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS') THEN 'PROGRESS'
          WHEN v_alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'INFO'
          ELSE 'ACTION_REQUIRED'
        END,
        'provider_failure_reason_code', v_provider_failure_reason_code,
        'provider_failure_reason_group', CASE WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(v_provider_failure_reason_group, 'WEBHOOK_UNMATCHED') ELSE v_provider_failure_reason_group END,
        'provider_failure_reason_label', CASE WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(v_provider_failure_reason_label, 'Webhook unmatched') ELSE v_provider_failure_reason_label END,
        'provider_event_key', v_provider_event_key,
        'provider_webhook_receipt_id', CASE WHEN v_webhook_receipt_id IS NULL THEN NULL ELSE v_webhook_receipt_id::text END,
        'pay_batch_id', p_pay_batch_id::text,
        'provider', v_rail_provider,
        'rail', v_rail_provider,
        'rail_env', v_rail_env,
        'outage_window', CASE WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text) ELSE NULL END
      )
      || jsonb_build_object(
        'retry_operation_id', CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NULL THEN NULL ELSE (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros) END,
        'retry_operation_status', (SELECT ros.retry_operation_status FROM retry_operation_scope AS ros),
        'retry_eligible_count', COALESCE((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0),
        'retry_ineligible_count', COALESCE((SELECT rpc.retry_ineligible_count FROM retry_plan_counts AS rpc), 0),
        'correction_request_id', CASE WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NULL THEN NULL ELSE (SELECT cs.correction_request_id::text FROM correction_scope AS cs) END,
        'cancellation_operation_id', CASE WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN CASE WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NULL THEN NULL ELSE (SELECT cs.correction_request_id::text FROM correction_scope AS cs) END ELSE NULL END,
        'pay_bank_transfer_id', CASE WHEN (SELECT sts.pay_bank_transfer_id FROM single_transfer_scope AS sts) IS NULL THEN NULL ELSE (SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts) END,
        'carry_forward_id', CASE WHEN (SELECT cfs.carry_forward_id FROM carry_forward_scope AS cfs) IS NULL THEN NULL ELSE (SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs) END,
        'source_pay_batch_item_id', CASE WHEN (SELECT cfs.source_pay_batch_item_id FROM carry_forward_scope AS cfs) IS NULL THEN NULL ELSE (SELECT cfs.source_pay_batch_item_id::text FROM carry_forward_scope AS cfs) END,
        'affected_payment_count', COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0),
        'affected_candidate_count', COALESCE((SELECT ic.affected_candidate_count FROM item_counts AS ic), 0),
        'affected_transfer_count', COALESCE((SELECT ic.affected_transfer_count FROM item_counts AS ic), 0),
        'affected_timesheet_count', COALESCE((SELECT ic.affected_timesheet_count FROM item_counts AS ic), 0),
        'amount_affected', COALESCE((SELECT ic.amount_affected FROM item_counts AS ic), 0),
        'current_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
        'required_user_action', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry unsent payments from Banking Pay Overview.'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Open Current Payment Status and check the provider outcome.'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Open Current Payment Status and rewind financials where no money moved.'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Monitor rewind progress.'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Monitor cancellation progress in Banking Pay Overview.'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Review carried-forward manual adjustments in the next pay run.'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Open Current Payment Status and review ambiguous manual adjustment blockers.'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Open Current Payment Status and recover overpayment in next pay run.'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Open Current Payment Status and check provider submission before continuing.'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Review the unmatched provider webhook and link it to the correct payment if safe.'
          ELSE 'Open Banking Pay.'
        END,
        'auto_unwind_running', v_alert_kind = 'AUTO_UNWIND_PROGRESS' AND COALESCE((SELECT cs.correction_running FROM correction_scope AS cs), false),
        'manual_rewind_required', v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
        'progress_completed', COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0),
        'progress_total', COALESCE((SELECT cs.progress_total FROM correction_scope AS cs), 0)
      )
      || jsonb_build_object(
        'link_target', 'banking_pay_batch',
        'link_tab', CASE
          WHEN v_alert_kind IN ('PROVIDER_OUTAGE_RETRY_LATER','AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS') THEN 'overview'
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'current_payment_status'
          ELSE 'current_payment_status'
        END,
        'user_label', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NOT NULL THEN 'Retrying unsent payments — ' || COALESCE(NULLIF((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' payments in progress' ELSE 'Bank unavailable — ' || COALESCE(NULLIF((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' unsent payments can be retried' END
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Provider outcome unknown — ' || COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0)::text || ' payments need checking'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Failed payments — Rewind financials available for ' || COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0)::text || ' payments'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Rewinding failed payments — ' || COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0)::text || ' of ' || COALESCE(NULLIF((SELECT cs.progress_total FROM correction_scope AS cs), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' complete'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Cancelling scheduled batch — ' || COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0)::text || ' of ' || COALESCE(NULLIF((SELECT cs.progress_total FROM correction_scope AS cs), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' payment scopes complete'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Manual adjustments carried forward — ' || COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0)::text || ' adjustments will appear in the next pay run'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Manual adjustment blockers — review required'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Paid — recovery required'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation conflict — provider submission already started'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched bank webhook — review required'
          ELSE initcap(replace(lower(v_alert_kind), '_', ' '))
        END,
        'user_description', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NOT NULL THEN 'CloudTMS is retrying payments confirmed as not sent. You can continue using CloudTMS while this runs.' ELSE 'The bank/provider was unavailable before the payment request was sent. Retry unsent payments from Banking Pay Overview.' END
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'A provider request may have been sent, but the outcome is not confirmed. Check provider state before retrying or unwinding.'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'The provider/bank outcome indicates no money moved. Financials can be rewound from Current Payment Status.'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Automatic no-money unwind is running and this alert updates progress instead of creating per-payment alerts.'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Scheduled local cancellation is running in chunks and this alert updates progress.'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Safe source-less manual adjustments were carried forward and will be included in the next pay run.'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'One or more manual adjustments cannot be safely carried forward automatically.'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Money appears to have moved. Amend the timesheet and recover the overpayment in the next pay run rather than unwinding the payment.'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation could not proceed because provider submission had already started.'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'A verified provider webhook was received but could not be matched safely to a payment.'
          ELSE 'Open Banking Pay for details.'
        END,
        'manual_adjustments_carried_forward_count', COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0),
        'carry_forward_count', COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0),
        'remittance_already_sent', EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS remittance_candidate
          WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
            AND remittance_candidate.remittance_sent_at_utc IS NOT NULL
        ),
        'payload_is_grouped', true
      )
    )
    INTO v_grouped_alert_payload;

    RETURN v_grouped_alert_payload;
  END IF;

  IF v_alert_kind = 'BLOCKED_FUNDS' THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', 'BLOCKED_FUNDS',
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'execution_commit_state', UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))),
      'execution_commit_ref', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), ''),
      'execution_committed_at_utc', v_execution_committed_at_utc_text,
      'last_funds_check_at_utc', v_last_funds_check_at_utc_text,
      'funds_check_checked_at_utc', v_funds_check_checked_at_utc,
      'required_gbp', v_required_gbp,
      'available_gbp', v_available_gbp,
      'sufficient', v_sufficient,
      'funding_account_ref', v_funding_account_ref,
      'rail_provider', v_rail_provider,
      'rail_env', v_rail_env
    ));
  END IF;

  IF v_alert_kind IN ('BANK_REJECTED_PAYMENT', 'BANK_RETURNED_PAYMENT', 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED', 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT') THEN
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'pay_bank_transfer_id', public.pay_bank_transfers.id::text,
      'candidate_id', CASE WHEN public.pay_bank_transfers.candidate_id IS NULL THEN NULL ELSE public.pay_bank_transfers.candidate_id::text END,
      'umbrella_id', CASE WHEN public.pay_bank_transfers.umbrella_id IS NULL THEN NULL ELSE public.pay_bank_transfers.umbrella_id::text END,
      'transfer_group_key', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.transfer_group_key, '')), ''),
      'amount', public.pay_bank_transfers.amount,
      'currency', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.currency, '')), ''),
      'status', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.status, '')), ''),
      'rail_state', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, '')), ''),
      'rail_provider', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_provider, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_env, '')), ''),
      'request_id', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.request_id, '')), ''),
      'rail_tx_id', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_tx_id, '')), ''),
      'payment_reference', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.payment_reference, '')), ''),
      'completed_at_utc', CASE
        WHEN public.pay_bank_transfers.completed_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfers.completed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'created_at_utc', CASE
        WHEN public.pay_bank_transfers.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfers.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'failed_reason_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NULL THEN NULL
        ELSE MD5(public.pay_bank_transfers.failed_reason)
      END,
      'provider_submission_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_submission_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{submission_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{rail_submission_id}'), '')
      ),
      'provider_payment_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{payment,id}'), '')
      ),
      'provider_transfer_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transfer,id}'), '')
      ),
      'provider_transaction_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transaction,id}'), '')
      ),
      'provider_response_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider,response,id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{response,id}'), '')
      )
    ))
    INTO v_latest_transfer
    FROM public.pay_bank_transfers
    WHERE public.pay_bank_transfers.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_bank_transfer'
        OR public.pay_bank_transfers.id = p_source_id
      )
      AND (
        (v_alert_kind = 'BANK_REJECTED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL
          ))
        OR (v_alert_kind = 'BANK_RETURNED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('RETURNED', 'REVERTED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('RETURNED', 'REVERTED')
          ))
        OR (v_alert_kind = 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) LIKE 'CREATE_ERROR%'
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) LIKE 'CREATE_ERROR%'
          ))
        OR (v_alert_kind = 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED')
      )
    ORDER BY COALESCE(public.pay_bank_transfers.completed_at_utc, public.pay_bank_transfers.created_at_utc) DESC NULLS LAST,
             public.pay_bank_transfers.id DESC
    LIMIT 1;
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'pay_bank_transfer_event_id', public.pay_bank_transfer_events.id::text,
      'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
      'provider_key', public.pay_bank_transfer_events.provider_key,
      'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
      'provider_reference', public.pay_bank_transfer_events.provider_reference,
      'provider_state', public.pay_bank_transfer_events.provider_state,
      'normalised_state', public.pay_bank_transfer_events.normalised_state,
      'mapping_status', public.pay_bank_transfer_events.mapping_status,
      'movement_classification', public.pay_bank_transfer_events.movement_classification,
      'correction_disposition', public.pay_bank_transfer_events.correction_disposition,
      'event_source', public.pay_bank_transfer_events.event_source,
      'event_time_utc', CASE
        WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfer_events.event_time_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'received_at_utc', CASE
        WHEN public.pay_bank_transfer_events.received_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfer_events.received_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_transfer_event
    FROM public.pay_bank_transfer_events
    WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_bank_transfer_event'
        OR public.pay_bank_transfer_events.id = p_source_id
      )
      AND (
        (v_alert_kind = 'BANK_REJECTED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.movement_classification, ''))) IN ('NO_MONEY_UNWIND', 'PRE_BANK_CANCEL')
          ))
        OR (v_alert_kind = 'BANK_RETURNED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('RETURNED', 'REVERTED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('RETURNED', 'REVERTED')
          ))
        OR (v_alert_kind = 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.mapping_status, ''))) IN ('AMBIGUOUS', 'UNMATCHED', 'NO_MATCH', 'MULTIPLE_MATCHES')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) IN ('AMBIGUOUS', 'ACTION_REQUIRED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.movement_classification, ''))) IN ('AMBIGUOUS_REVIEW_REQUIRED')
          ))
        OR (v_alert_kind = 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) LIKE 'CREATE_ERROR%'
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) LIKE 'CREATE_ERROR%'
          ))
      )
    ORDER BY COALESCE(public.pay_bank_transfer_events.event_time_utc, public.pay_bank_transfer_events.received_at_utc, public.pay_bank_transfer_events.created_at_utc) DESC NULLS LAST,
             public.pay_bank_transfer_events.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', v_alert_kind,
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'execution_commit_state', UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))),
      'execution_commit_ref', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), ''),
      'execution_committed_at_utc', v_execution_committed_at_utc_text,
      'last_status_checked_at_utc', v_last_status_checked_at_utc_text,
      'latest_transfer', v_latest_transfer,
      'latest_transfer_event', v_latest_transfer_event
    ));
  END IF;

  IF v_alert_kind IN ('PAYMENT_CORRECTION_FAILED', 'PAYMENT_CORRECTION_BLOCKED', 'PAYMENT_CORRECTION_AWAITING_APPROVAL') THEN
    IF v_source_kind = 'pay_bank_transfer_event' AND p_source_id IS NOT NULL THEN
      SELECT jsonb_strip_nulls(jsonb_build_object(
        'pay_bank_transfer_event_id', public.pay_bank_transfer_events.id::text,
        'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
        'provider_key', public.pay_bank_transfer_events.provider_key,
        'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
        'provider_reference', public.pay_bank_transfer_events.provider_reference,
        'provider_state', public.pay_bank_transfer_events.provider_state,
        'normalised_state', public.pay_bank_transfer_events.normalised_state,
        'mapping_status', public.pay_bank_transfer_events.mapping_status,
        'movement_classification', public.pay_bank_transfer_events.movement_classification,
        'correction_disposition', public.pay_bank_transfer_events.correction_disposition,
        'event_source', public.pay_bank_transfer_events.event_source,
        'event_time_utc', CASE
          WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.event_time_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'received_at_utc', CASE
          WHEN public.pay_bank_transfer_events.received_at_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.received_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'created_at_utc', CASE
          WHEN public.pay_bank_transfer_events.created_at_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END
      ))
      INTO v_latest_transfer_event
      FROM public.pay_bank_transfer_events
      WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id
        AND public.pay_bank_transfer_events.id = p_source_id
      LIMIT 1;
    END IF;

    SELECT jsonb_strip_nulls(jsonb_build_object(
      'correction_request_id', public.pay_payment_correction_requests.id::text,
      'correction_kind', public.pay_payment_correction_requests.correction_kind,
      'status', public.pay_payment_correction_requests.status,
      'source_bank_event_id', CASE WHEN public.pay_payment_correction_requests.source_bank_event_id IS NULL THEN NULL ELSE public.pay_payment_correction_requests.source_bank_event_id::text END,
      'requested_at_utc', CASE
        WHEN public.pay_payment_correction_requests.requested_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.requested_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'updated_at_utc', CASE
        WHEN public.pay_payment_correction_requests.updated_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.updated_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'authorised_at_utc', CASE
        WHEN public.pay_payment_correction_requests.authorised_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.authorised_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'applied_at_utc', CASE
        WHEN public.pay_payment_correction_requests.applied_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.applied_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'cancelled_at_utc', CASE
        WHEN public.pay_payment_correction_requests.cancelled_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.cancelled_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_correction_request
    FROM public.pay_payment_correction_requests
    WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_payment_correction_request'
        OR public.pay_payment_correction_requests.id = p_source_id
      )
      AND (
        (v_alert_kind = 'PAYMENT_CORRECTION_FAILED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('FAILED', 'FAILED_RETRYABLE', 'FAILED_FINAL'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_BLOCKED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_AWAITING_APPROVAL'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'PENDING_APPROVAL'))
      )
    ORDER BY COALESCE(public.pay_payment_correction_requests.updated_at_utc, public.pay_payment_correction_requests.requested_at_utc, public.pay_payment_correction_requests.created_at_utc) DESC NULLS LAST,
             public.pay_payment_correction_requests.id DESC
    LIMIT 1;

    SELECT jsonb_strip_nulls(jsonb_build_object(
      'correction_work_item_id', public.pay_payment_correction_work_items.id::text,
      'correction_request_id', public.pay_payment_correction_work_items.correction_request_id::text,
      'pay_bank_transfer_id', CASE WHEN public.pay_payment_correction_work_items.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_payment_correction_work_items.pay_bank_transfer_id::text END,
      'work_kind', public.pay_payment_correction_work_items.work_kind,
      'status', public.pay_payment_correction_work_items.status,
      'attempt_count', public.pay_payment_correction_work_items.attempt_count,
      'last_error_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.pay_payment_correction_work_items.last_error, '')), '') IS NULL THEN NULL
        ELSE MD5(public.pay_payment_correction_work_items.last_error)
      END,
      'created_at_utc', CASE
        WHEN public.pay_payment_correction_work_items.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_work_items.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'processed_at_utc', CASE
        WHEN public.pay_payment_correction_work_items.processed_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_work_items.processed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_correction_work_item
    FROM public.pay_payment_correction_work_items
    WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_payment_correction_work_item'
        OR public.pay_payment_correction_work_items.id = p_source_id
      )
      AND (
        (v_alert_kind = 'PAYMENT_CORRECTION_FAILED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('FAILED', 'FAILED_RETRYABLE', 'FAILED_FINAL'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_BLOCKED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_AWAITING_APPROVAL'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'PENDING_APPROVAL'))
      )
    ORDER BY COALESCE(public.pay_payment_correction_work_items.processed_at_utc, public.pay_payment_correction_work_items.created_at_utc) DESC NULLS LAST,
             public.pay_payment_correction_work_items.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', v_alert_kind,
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'latest_correction_request', v_latest_correction_request,
      'latest_correction_work_item', v_latest_correction_work_item,
      'latest_transfer_event', v_latest_transfer_event
    ));
  END IF;


  IF v_alert_kind = 'PAYMENT_PROVIDER_SUBMIT_REVIEW' THEN
    IF v_source_kind = 'banking_pay_operation' AND p_source_id IS NOT NULL THEN
      v_provider_operation_id := p_source_id;
    ELSE
      v_provider_operation_id := NULL::uuid;
    END IF;

    v_provider_submit_diagnostic_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := p_pay_batch_id,
      p_operation_id := v_provider_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := NULL::uuid,
      p_counts_only := false
    );
    v_provider_submit_diagnostic := COALESCE(v_provider_submit_diagnostic_result->'provider_submit_diagnostic', '{}'::jsonb);
    v_provider_submission_status := UPPER(BTRIM(COALESCE(v_provider_submit_diagnostic_result->>'provider_submission_status', v_provider_submit_diagnostic->>'provider_submission_status', '')));
    v_review_reason_code := COALESCE(NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic_result->>'review_reason_code', v_provider_submit_diagnostic->>'review_reason_code', '')), ''), 'PAYMENT_PROVIDER_SUBMIT_REVIEW');

    v_provider_title := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Provider submission outcome unknown'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider response unusable'
      WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider acceptance evidence missing'
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider outcome needs review'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
      ELSE 'Provider submission needs review'
    END;

    v_provider_description := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Submit chunk became stale with no provider response, transfer event, rail transaction ID, or rail state.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'A provider request may have been sent, but no usable provider response was recorded.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Manual reconciliation is required before retry.'
      WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider response/status was recorded, but no usable external provider transaction/reference was stored.'
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected the payment submission.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission failed before the provider payment request was sent.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists and retry is unsafe until reconciliation is complete.'
      ELSE 'Provider submission requires review before retry.'
    END;

    v_provider_action_label := COALESCE(NULLIF(BTRIM(v_provider_submit_diagnostic->>'recommended_action'), ''), 'Check Revolut/bank before retry. If no payment was made, record manual no-payment confirmation.');

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'alert_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'title', v_provider_title,
      'description', v_provider_description,
      'action_label', v_provider_action_label,
      'recommended_action', v_provider_action_label,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_review_reason_code,
      'manual_resolution_required', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'manual_resolution_required', v_provider_submit_diagnostic_result->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'safe_retry_available', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'safe_retry_available', v_provider_submit_diagnostic_result->>'safe_retry_available', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_response_present', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_response_present', v_provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'pay_batch_id', v_batch.id::text,
      'operation_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'operation_id', CASE WHEN v_provider_operation_id IS NULL THEN NULL ELSE v_provider_operation_id::text END, '')), ''),
      'chunk_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'chunk_id', '')), ''),
      'transfer_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'auth_request_id', '')), ''),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'rail_provider', v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'rail_env', v_batch.rail_env_snapshot, '')), ''),
      'provider_submit_diagnostic', v_provider_submit_diagnostic - 'provider_response_redacted' - 'provider_error_redacted' - 'raw_payload' - 'provider_raw_response' - 'raw_provider_response' - 'provider_raw_error' - 'raw_provider_error'
    ));
  END IF;

  IF v_alert_kind = 'REMITTANCE_SEND_FAILED' THEN
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'mail_outbox_id', public.mail_outbox.id::text,
      'type', public.mail_outbox.type,
      'status', public.mail_outbox.status::text,
      'reference', public.mail_outbox.reference,
      'recipient_kind', public.mail_outbox.recipient_kind,
      'recipient_id', CASE WHEN public.mail_outbox.recipient_id IS NULL THEN NULL ELSE public.mail_outbox.recipient_id::text END,
      'last_error_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.mail_outbox.last_error, '')), '') IS NULL THEN NULL
        ELSE MD5(public.mail_outbox.last_error)
      END,
      'created_at_utc', CASE
        WHEN public.mail_outbox.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.mail_outbox.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'failed_at', CASE
        WHEN public.mail_outbox.failed_at IS NULL THEN NULL
        ELSE TO_CHAR(public.mail_outbox.failed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_remittance_failure
    FROM public.mail_outbox
    WHERE public.mail_outbox.context_kind = 'pay_batches'
      AND public.mail_outbox.context_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'mail_outbox'
        OR public.mail_outbox.id = p_source_id
      )
      AND UPPER(BTRIM(COALESCE(public.mail_outbox.type, ''))) = 'REMITTANCE'
      AND (
        UPPER(BTRIM(COALESCE(public.mail_outbox.status::text, ''))) = 'FAILED'
        OR public.mail_outbox.failed_at IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(public.mail_outbox.last_error, '')), '') IS NOT NULL
      )
    ORDER BY COALESCE(public.mail_outbox.failed_at, public.mail_outbox.created_at_utc) DESC NULLS LAST,
             public.mail_outbox.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', 'REMITTANCE_SEND_FAILED',
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'latest_remittance_failure', v_latest_remittance_failure
    ));
  END IF;

  RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_KIND_NOT_SUPPORTED'
    USING ERRCODE = 'P0001',
          DETAIL = jsonb_build_object(
            'code', 'BANKING_ALERT_PAYLOAD_KIND_NOT_SUPPORTED',
            'alert_kind', v_alert_kind,
            'pay_batch_id', p_pay_batch_id::text
          )::text;
END;
$function$;




DROP FUNCTION IF EXISTS public.pay_batch_submission_evidence(uuid);
DROP FUNCTION IF EXISTS public.pay_batch_submission_evidence(uuid, boolean, uuid, uuid);

CREATE OR REPLACE FUNCTION public.pay_batch_submission_evidence(p_pay_batch_id uuid, p_counts_only boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_chunk_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'OPERATION_LIGHT'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_mode text := upper(btrim(coalesce(p_mode, 'OPERATION_LIGHT')));
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_id uuid := p_operation_id;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_progress_json jsonb := '{}'::jsonb;
  v_chunk_result_json jsonb := '{}'::jsonb;
  v_chunk_error_json jsonb := '{}'::jsonb;
  v_submitted_count integer := 0;
  v_accepted_count integer := 0;
  v_failed_count integer := 0;
  v_unknown_count integer := 0;
  v_review_required_count integer := 0;
  v_remaining_ready_count integer := 0;
  v_claimed_count integer := 0;
  v_request_sent_count integer := 0;
  v_total_scope_count integer := 0;
  v_last_provider_message text := NULL::text;
  v_last_provider_state text := NULL::text;
  v_last_provider_at_utc text := NULL::text;
  v_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_completed_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_transfer_count integer := 0;
  v_terminal_no_money_count integer := 0;
  v_final_money_moved_count integer := 0;
  v_materialised_transfer_count integer := 0;
  v_materialised_final_money_moved_count integer := 0;
  v_materialised_terminal_no_money_count integer := 0;
  v_materialised_pending_non_final_count integer := 0;
  v_materialised_unknown_or_review_count integer := 0;
  v_materialised_last_provider_state text := NULL::text;
  v_materialised_last_provider_at_utc text := NULL::text;
  v_transfer_classification_summary_json jsonb := '{}'::jsonb;
  v_transfer_classification_called boolean := false;
  v_should_classify_transfers boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('DISPLAY');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_mode IS NULL OR v_mode = '' THEN
    v_mode := 'OPERATION_LIGHT';
  END IF;

  IF v_mode NOT IN ('OPERATION_LIGHT', 'LIGHT', 'COUNTS_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_MODE_NOT_SUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_MODE_NOT_SUPPORTED', 'mode', p_mode)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT chunk_row.*
    INTO v_chunk_row
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = p_chunk_id
      AND (v_operation_id IS NULL OR chunk_row.operation_id = v_operation_id)
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT');

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_CHUNK_NOT_FOUND', 'chunk_id', p_chunk_id::text, 'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END)::text;
    END IF;

    IF v_operation_id IS NULL THEN
      v_operation_id := v_chunk_row.operation_id;
    END IF;

    v_chunk_result_json := coalesce(v_chunk_row.result_json, '{}'::jsonb);
    v_chunk_error_json := coalesce(v_chunk_row.error_json, '{}'::jsonb);
  END IF;

  IF v_operation_id IS NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
             operation_row.created_at_utc DESC NULLS LAST,
             operation_row.id DESC
    LIMIT 1;

    IF FOUND THEN
      v_operation_id := v_operation_row.id;
    END IF;
  ELSE
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = v_operation_id
      AND operation_row.pay_batch_id = p_pay_batch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH', 'pay_batch_id', p_pay_batch_id::text, 'operation_id', v_operation_id::text)::text;
    END IF;
  END IF;

  v_progress_json := coalesce(v_operation_row.progress_json, '{}'::jsonb);

  SELECT
    CASE WHEN coalesce(v_progress_json->>'submitted_count', v_progress_json->>'last_rail_update_count', v_chunk_result_json->>'updated_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'submitted_count', v_progress_json->>'last_rail_update_count', v_chunk_result_json->>'updated_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'accepted_count', v_progress_json->>'last_rail_update_accepted_count', v_chunk_result_json->>'accepted_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'accepted_count', v_progress_json->>'last_rail_update_accepted_count', v_chunk_result_json->>'accepted_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'failed_count', v_progress_json->>'last_rail_update_failed_count', v_chunk_result_json->>'failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'failed_count', v_progress_json->>'last_rail_update_failed_count', v_chunk_result_json->>'failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'unknown_count', v_progress_json->>'last_rail_update_unknown_count', v_chunk_result_json->>'unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'unknown_count', v_progress_json->>'last_rail_update_unknown_count', v_chunk_result_json->>'unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'review_required_count', v_chunk_result_json->>'review_required_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'review_required_count', v_chunk_result_json->>'review_required_count')::integer WHEN coalesce(v_operation_row.requires_user_action, false) IS TRUE OR upper(btrim(coalesce(v_operation_row.status, ''))) = 'REVIEW_REQUIRED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'remaining_ready_count', v_progress_json->>'operation_scope_provider_ready_count', v_progress_json->>'provider_ready_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'remaining_ready_count', v_progress_json->>'operation_scope_provider_ready_count', v_progress_json->>'provider_ready_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'claimed_count', v_progress_json->>'operation_scope_claimed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'claimed_count', v_progress_json->>'operation_scope_claimed_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'RUNNING' THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'request_sent_count', v_progress_json->>'last_rail_update_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'request_sent_count', v_progress_json->>'last_rail_update_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'transfer_count', v_progress_json->>'operation_transfer_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'transfer_count', v_progress_json->>'operation_transfer_count')::integer WHEN p_chunk_id IS NOT NULL THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'scope_count', v_progress_json->>'operation_scope_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'scope_count', v_progress_json->>'operation_scope_count')::integer WHEN p_chunk_id IS NOT NULL THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_message', v_chunk_result_json->>'last_provider_message', v_chunk_error_json->>'message', '')), ''), NULL::text),
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_state', v_chunk_result_json->>'provider_submission_status', v_chunk_error_json->>'provider_submission_status', '')), ''), NULL::text),
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_at_utc', v_chunk_result_json->>'rail_update_applied_at_utc', v_chunk_result_json->>'provider_chunk_finalised_at_utc', '')), ''), NULL::text),
    CASE WHEN coalesce(v_progress_json->>'chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'chunk_count')::integer WHEN p_chunk_id IS NOT NULL THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'running_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'running_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'RUNNING' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'pending_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'pending_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'PENDING' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'completed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'completed_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) IN ('COMPLETE', 'COMPLETED') THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'failed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'failed_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'FAILED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'terminal_no_money_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'terminal_no_money_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'final_money_moved_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'final_money_moved_count')::integer ELSE 0 END
  INTO v_submitted_count,
       v_accepted_count,
       v_failed_count,
       v_unknown_count,
       v_review_required_count,
       v_remaining_ready_count,
       v_claimed_count,
       v_request_sent_count,
       v_transfer_count,
       v_total_scope_count,
       v_last_provider_message,
       v_last_provider_state,
       v_last_provider_at_utc,
       v_chunk_count,
       v_running_chunk_count,
       v_pending_chunk_count,
       v_completed_chunk_count,
       v_failed_chunk_count,
       v_terminal_no_money_count,
       v_final_money_moved_count;

  v_should_classify_transfers := (
    v_operation_id IS NOT NULL
    AND upper(btrim(coalesce(v_operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (
      upper(btrim(coalesce(v_operation_row.phase, ''))) IN (
        'SUBMIT_PROVIDER_TRANSFERS',
        'SEND_PROVIDER_CHUNK',
        'APPLY_RAIL_UPDATES',
        'START_LOCAL_SETTLEMENT',
        'WAIT_LOCAL_SETTLEMENT',
        'PAYMENT_SETTLEMENT',
        'SETTLEMENT_SCOPE_SEED',
        'SEED_SETTLEMENT_SCOPE',
        'SETTLE_RAIL',
        'QUEUE_REMITTANCES',
        'REMITTANCE_SCOPE_SEED',
        'BUILD_REMITTANCE',
        'COMMIT_REMITTANCE',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_progress_json->>'phase', ''))) IN (
        'SUBMIT_PROVIDER_TRANSFERS',
        'SEND_PROVIDER_CHUNK',
        'APPLY_RAIL_UPDATES',
        'START_LOCAL_SETTLEMENT',
        'WAIT_LOCAL_SETTLEMENT',
        'PAYMENT_SETTLEMENT',
        'SETTLEMENT_SCOPE_SEED',
        'SEED_SETTLEMENT_SCOPE',
        'SETTLE_RAIL',
        'QUEUE_REMITTANCES',
        'REMITTANCE_SCOPE_SEED',
        'BUILD_REMITTANCE',
        'COMMIT_REMITTANCE',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_operation_row.status, ''))) IN (
        'WAITING_PROVIDER',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_operation_row.runner_state, ''))) IN (
        'WAITING_PROVIDER',
        'WAITING_USER_REVIEW'
      )
      OR p_chunk_id IS NOT NULL
    )
  );

  IF v_should_classify_transfers IS TRUE THEN
    WITH classified_transfer_rows AS (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      transfer_row.pay_batch_id,
      transfer_row.status AS transfer_status,
      transfer_row.rail_state,
      transfer_row.rail_tx_id,
      transfer_row.completed_at_utc,
      transfer_row.failed_reason,
      transfer_row.amount,
      transfer_row.currency,
      transfer_row.created_at_utc,
      classifier_row.cash_state,
      classifier_row.normalised_transfer_status,
      classifier_row.is_final_money_moved,
      classifier_row.is_terminal_no_money,
      classifier_row.is_pending_non_final,
      classifier_row.reason
    FROM public.pay_bank_transfers AS transfer_row
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      p_transfer_status => transfer_row.status,
      p_rail_state => transfer_row.rail_state,
      p_event_payload_json => COALESCE(transfer_row.rail_meta_json, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'normalised_state', transfer_row.status,
        'provider_state', transfer_row.rail_state,
        'provider_transaction_id', transfer_row.rail_tx_id,
        'failed_reason', transfer_row.failed_reason,
        'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END
      )),
      p_provider_meta_json => COALESCE(transfer_row.rail_meta_json -> 'provider_submit_diagnostic', '{}'::jsonb) || COALESCE(transfer_row.rail_meta_json, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'provider_transaction_id', transfer_row.rail_tx_id,
        'rail_tx_id', transfer_row.rail_tx_id,
        'provider_external_evidence_present', NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL,
        'provider_acceptance_evidence_present', NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL,
        'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END
      ))
    ) AS classifier_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  ), transfer_classification_totals AS (
    SELECT
      COUNT(*)::integer AS transfer_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_final_money_moved, false) IS TRUE)::integer AS final_money_moved_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_terminal_no_money, false) IS TRUE)::integer AS terminal_no_money_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_pending_non_final, false) IS TRUE)::integer AS pending_non_final_count,
      COUNT(*) FILTER (
        WHERE COALESCE(classified_transfer_rows.is_final_money_moved, false) IS NOT TRUE
          AND COALESCE(classified_transfer_rows.is_terminal_no_money, false) IS NOT TRUE
          AND COALESCE(classified_transfer_rows.is_pending_non_final, false) IS NOT TRUE
      )::integer AS unknown_or_review_count,
      (array_agg(NULLIF(BTRIM(COALESCE(classified_transfer_rows.rail_state, classified_transfer_rows.normalised_transfer_status, classified_transfer_rows.transfer_status, '')), '') ORDER BY COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc) DESC NULLS LAST, classified_transfer_rows.pay_bank_transfer_id DESC))[1] AS last_provider_state,
      (array_agg((COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc))::text ORDER BY COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc) DESC NULLS LAST, classified_transfer_rows.pay_bank_transfer_id DESC))[1] AS last_provider_at_utc
    FROM classified_transfer_rows AS classified_transfer_rows
  )
  SELECT
    COALESCE(transfer_classification_totals.transfer_count, 0),
    COALESCE(transfer_classification_totals.final_money_moved_count, 0),
    COALESCE(transfer_classification_totals.terminal_no_money_count, 0),
    COALESCE(transfer_classification_totals.pending_non_final_count, 0),
    COALESCE(transfer_classification_totals.unknown_or_review_count, 0),
    transfer_classification_totals.last_provider_state,
    transfer_classification_totals.last_provider_at_utc,
    jsonb_strip_nulls(jsonb_build_object(
      'source', 'pay_bank_transfers',
      'bounded_scope', 'pay_batch_id',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END,
      'transfer_count', COALESCE(transfer_classification_totals.transfer_count, 0),
      'final_money_moved_count', COALESCE(transfer_classification_totals.final_money_moved_count, 0),
      'terminal_no_money_count', COALESCE(transfer_classification_totals.terminal_no_money_count, 0),
      'pending_non_final_count', COALESCE(transfer_classification_totals.pending_non_final_count, 0),
      'unknown_or_review_count', COALESCE(transfer_classification_totals.unknown_or_review_count, 0),
      'classification_called', COALESCE(transfer_classification_totals.transfer_count, 0) > 0,
      'last_provider_state', transfer_classification_totals.last_provider_state,
      'last_provider_at_utc', transfer_classification_totals.last_provider_at_utc
    ))
  INTO v_materialised_transfer_count,
       v_materialised_final_money_moved_count,
       v_materialised_terminal_no_money_count,
       v_materialised_pending_non_final_count,
       v_materialised_unknown_or_review_count,
       v_materialised_last_provider_state,
       v_materialised_last_provider_at_utc,
       v_transfer_classification_summary_json
  FROM transfer_classification_totals AS transfer_classification_totals;
  END IF;

  v_transfer_classification_called := COALESCE(v_materialised_transfer_count, 0) > 0;

  IF v_transfer_classification_called IS TRUE THEN
    v_transfer_count := v_materialised_transfer_count;
    v_submitted_count := GREATEST(COALESCE(v_submitted_count, 0), COALESCE(v_materialised_transfer_count, 0));
    v_request_sent_count := GREATEST(COALESCE(v_request_sent_count, 0), COALESCE(v_materialised_transfer_count, 0));
    v_final_money_moved_count := v_materialised_final_money_moved_count;
    v_terminal_no_money_count := v_materialised_terminal_no_money_count;
    v_unknown_count := GREATEST(COALESCE(v_unknown_count, 0), COALESCE(v_materialised_unknown_or_review_count, 0));
    v_review_required_count := GREATEST(COALESCE(v_review_required_count, 0), COALESCE(v_materialised_unknown_or_review_count, 0));
    v_last_provider_state := COALESCE(NULLIF(BTRIM(COALESCE(v_materialised_last_provider_state, '')), ''), v_last_provider_state);
    v_last_provider_at_utc := COALESCE(NULLIF(BTRIM(COALESCE(v_materialised_last_provider_at_utc, '')), ''), v_last_provider_at_utc);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'mode', v_mode,
    'operation_light', true,
    'counts_only', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END,
    'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
    'operation_status', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.status END,
    'operation_phase', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.phase END,
    'runner_state', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.runner_state END,
    'submitted_count', coalesce(v_submitted_count, 0),
    'accepted_count', coalesce(v_accepted_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'unknown_count', coalesce(v_unknown_count, 0),
    'review_required_count', coalesce(v_review_required_count, 0),
    'remaining_ready_count', coalesce(v_remaining_ready_count, 0),
    'last_provider_message', v_last_provider_message,
    'last_provider_state', v_last_provider_state,
    'last_provider_at_utc', v_last_provider_at_utc,
    'transfer_count', coalesce(v_transfer_count, 0),
    'scope_count', coalesce(v_total_scope_count, 0),
    'claimed_count', coalesce(v_claimed_count, 0),
    'request_sent_count', coalesce(v_request_sent_count, 0),
    'terminal_no_money_count', coalesce(v_terminal_no_money_count, 0),
    'final_money_moved_count', coalesce(v_final_money_moved_count, 0),
    'pending_non_final_count', coalesce(v_materialised_pending_non_final_count, 0),
    'unknown_or_review_count', coalesce(v_materialised_unknown_or_review_count, 0),
    'materialised_transfer_count', coalesce(v_materialised_transfer_count, 0),
    'transfer_classification_scope_enabled', v_should_classify_transfers,
    'transfer_classification_summary_json', coalesce(v_transfer_classification_summary_json, '{}'::jsonb),
    'chunk_count', coalesce(v_chunk_count, 0),
    'running_chunk_count', coalesce(v_running_chunk_count, 0),
    'pending_chunk_count', coalesce(v_pending_chunk_count, 0),
    'completed_chunk_count', coalesce(v_completed_chunk_count, 0),
    'failed_chunk_count', coalesce(v_failed_chunk_count, 0),
    'provider_submit_diagnostic_called', false,
    'classification_called', v_transfer_classification_called,
    'provider_event_grouping_called', false
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge_all_current(
  p_actor_user_id uuid,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_active_count integer := 0;
  v_created_count integer := 0;
  v_already_acknowledged_count integer := 0;
  v_acknowledged_count integer := 0;
  v_remaining_count integer := 0;
  v_acknowledged_alerts jsonb := '[]'::jsonb;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ALL_CURRENT_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ALL_CURRENT_ACTOR_REQUIRED')::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge_all_current'),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    0
  );

  WITH active_alert_rows AS (
    SELECT
      active_alert_element.alert_json ->> 'alert_fingerprint' AS active_alert_fingerprint,
      active_alert_element.alert_json ->> 'alert_kind' AS active_alert_kind,
      active_alert_element.alert_json ->> 'entity_kind' AS active_entity_kind,
      (active_alert_element.alert_json ->> 'entity_id')::uuid AS active_entity_id,
      COALESCE(active_alert_element.alert_json -> 'payload_json', '{}'::jsonb) AS active_payload_json
    FROM jsonb_array_elements(COALESCE(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert_element(alert_json)
    WHERE NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'alert_fingerprint', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'alert_kind', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'entity_kind', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'entity_id', '')), '') IS NOT NULL
      AND COALESCE((active_alert_element.alert_json ->> 'acknowledged_for_current_user')::boolean, false) = false
  ),
  deduped_active_alert_rows AS (
    SELECT DISTINCT ON (active_alert_rows.active_alert_fingerprint)
      active_alert_rows.active_alert_fingerprint,
      upper(btrim(active_alert_rows.active_alert_kind)) AS active_alert_kind,
      lower(btrim(active_alert_rows.active_entity_kind)) AS active_entity_kind,
      active_alert_rows.active_entity_id,
      COALESCE(active_alert_rows.active_payload_json, '{}'::jsonb) AS active_payload_json
    FROM active_alert_rows
    ORDER BY active_alert_rows.active_alert_fingerprint ASC
  ),
  upserted_acknowledgements AS (
    INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
      alert_fingerprint,
      alert_kind,
      entity_kind,
      entity_id,
      acknowledged_by_user_id,
      acknowledged_at_utc,
      acknowledge_scope,
      note,
      alert_payload_json,
      resolved_at_ack
    )
    SELECT
      deduped_active_alert_rows.active_alert_fingerprint,
      deduped_active_alert_rows.active_alert_kind,
      deduped_active_alert_rows.active_entity_kind,
      deduped_active_alert_rows.active_entity_id,
      p_actor_user_id,
      now(),
      'USER',
      NULLIF(BTRIM(COALESCE(p_note, '')), ''),
      deduped_active_alert_rows.active_payload_json,
      false
    FROM deduped_active_alert_rows
    WHERE true
    ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
    SET
      note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
      alert_payload_json = CASE
        WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
        ELSE EXCLUDED.alert_payload_json
      END
    RETURNING
      banking_alert_acknowledgement_upsert.alert_fingerprint,
      banking_alert_acknowledgement_upsert.alert_kind,
      banking_alert_acknowledgement_upsert.entity_kind,
      banking_alert_acknowledgement_upsert.entity_id,
      banking_alert_acknowledgement_upsert.acknowledged_at_utc,
      (banking_alert_acknowledgement_upsert.xmax = 0) AS created
  ),
  acknowledgement_summary AS (
    SELECT
      COALESCE(count(*) FILTER (WHERE upserted_acknowledgements.created = true), 0)::integer AS created_alert_count,
      COALESCE(count(*) FILTER (WHERE upserted_acknowledgements.created = false), 0)::integer AS already_acknowledged_alert_count,
      COALESCE(count(*), 0)::integer AS acknowledged_alert_count,
      COALESCE(jsonb_agg(jsonb_build_object(
        'alert_fingerprint', upserted_acknowledgements.alert_fingerprint,
        'alert_kind', upserted_acknowledgements.alert_kind,
        'entity_kind', upserted_acknowledgements.entity_kind,
        'entity_id', upserted_acknowledgements.entity_id::text,
        'acknowledged_at_utc', upserted_acknowledgements.acknowledged_at_utc::text,
        'created', upserted_acknowledgements.created,
        'already_acknowledged', NOT upserted_acknowledgements.created
      ) ORDER BY upserted_acknowledgements.acknowledged_at_utc DESC, upserted_acknowledgements.alert_fingerprint ASC), '[]'::jsonb) AS acknowledged_alerts_json
    FROM upserted_acknowledgements
  ),
  counted_active_alerts AS (
    SELECT COUNT(*)::integer AS active_alert_count
    FROM deduped_active_alert_rows
  )
  SELECT
    COALESCE(counted_active_alerts.active_alert_count, 0),
    COALESCE(acknowledgement_summary.created_alert_count, 0),
    COALESCE(acknowledgement_summary.already_acknowledged_alert_count, 0),
    COALESCE(acknowledgement_summary.acknowledged_alert_count, 0),
    COALESCE(acknowledgement_summary.acknowledged_alerts_json, '[]'::jsonb)
  INTO
    v_active_count,
    v_created_count,
    v_already_acknowledged_count,
    v_acknowledged_count,
    v_acknowledged_alerts
  FROM counted_active_alerts
  CROSS JOIN acknowledgement_summary;

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'clear_all',
    'active_count_before_acknowledge', COALESCE(v_active_count, 0),
    'requested_count', COALESCE(v_active_count, 0),
    'created_count', COALESCE(v_created_count, 0),
    'already_acknowledged_count', COALESCE(v_already_acknowledged_count, 0),
    'acknowledged_count', COALESCE(v_acknowledged_count, 0),
    'remaining_unacknowledged_count', COALESCE(v_remaining_count, 0),
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', COALESCE(v_remaining_count, 0),
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'ignored_count', GREATEST(COALESCE(v_active_count, 0) - COALESCE(v_acknowledged_count, 0), 0),
    'acknowledged_alerts', COALESCE(v_acknowledged_alerts, '[]'::jsonb),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.banking_alert_signal_for_user(uuid, text);

CREATE OR REPLACE FUNCTION public.banking_alert_signal_for_user(
  p_actor_user_id uuid,
  p_last_alert_hash text DEFAULT NULL::text,
  p_alert_context text DEFAULT 'CACHED'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_last_alert_hash text := NULLIF(BTRIM(COALESCE(p_last_alert_hash, '')), '');
  v_alert_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_alert_context, 'CACHED')), ''), '-', '_'));
  v_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_unacknowledged_count integer := 0;
  v_highest_severity text := NULL::text;
  v_highest_label text := NULL::text;
  v_summary_json jsonb := '{}'::jsonb;
  v_live_json jsonb := NULL::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_SIGNAL_FOR_USER_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_SIGNAL_FOR_USER_ACTOR_REQUIRED')::text;
  END IF;

  IF v_alert_context IN (
    'ALERT_PANEL',
    'ALERTS_PANEL',
    'ALERT_MANAGEMENT',
    'ALERT_REFRESH_JOB',
    'EXPLICIT_ALERT_REFRESH',
    'USER_TRIGGERED_ALERTS'
  ) THEN
    v_live_json := public.banking_alerts_active_for_user(
      p_actor_user_id,
      NULL::text,
      NULL::uuid,
      false,
      0,
      v_alert_context
    );

    v_alert_hash := COALESCE(NULLIF(BTRIM(COALESCE(v_live_json->>'banking_alert_hash', '')), ''), v_alert_hash);
    v_summary_hash := COALESCE(NULLIF(BTRIM(COALESCE(v_live_json->>'banking_alert_summary_signature', '')), ''), v_summary_hash);

    BEGIN
      v_unacknowledged_count := COALESCE((v_live_json->>'banking_unacknowledged_alert_count')::integer, 0);
    EXCEPTION WHEN OTHERS THEN
      v_unacknowledged_count := 0;
    END;

    v_highest_severity := NULLIF(BTRIM(COALESCE(v_live_json->>'banking_highest_alert_severity', v_live_json->>'highest_severity', '')), '');
    v_highest_label := NULLIF(BTRIM(COALESCE(v_live_json->>'banking_highest_alert_label', v_live_json->>'highest_label', '')), '');
    v_summary_json := COALESCE(v_live_json, '{}'::jsonb);
  ELSE
    SELECT
      COALESCE(alert_summary.alert_hash, v_alert_hash),
      COALESCE(alert_summary.summary_hash, v_summary_hash),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label,
      COALESCE(alert_summary.summary_json, '{}'::jsonb)
    INTO
      v_alert_hash,
      v_summary_hash,
      v_unacknowledged_count,
      v_highest_severity,
      v_highest_label,
      v_summary_json
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = p_actor_user_id;

    IF NOT FOUND THEN
      v_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_unacknowledged_count := 0;
      v_highest_severity := NULL::text;
      v_highest_label := NULL::text;
      v_summary_json := '{}'::jsonb;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'generated_at_utc', now()::text,
    'actor_user_id', p_actor_user_id::text,
    'cached', v_live_json IS NULL,
    'alert_context', v_alert_context,
    'banking_alert_hash', v_alert_hash,
    'banking_alert_summary_signature', v_summary_hash,
    'banking_alert_summary_changed', COALESCE(v_last_alert_hash IS DISTINCT FROM v_alert_hash, true),
    'banking_unacknowledged_alert_count', COALESCE(v_unacknowledged_count, 0),
    'grouped_banking_unacknowledged_alert_count', COALESCE(v_unacknowledged_count, 0),
    'banking_highest_alert_severity', COALESCE(v_highest_severity, ''),
    'banking_highest_alert_label', COALESCE(v_highest_label, ''),
    'highest_severity', COALESCE(v_highest_severity, ''),
    'highest_label', COALESCE(v_highest_label, ''),
    'summary_is_grouped', true,
    'summary_json', COALESCE(v_summary_json, '{}'::jsonb)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_changes_ping(
  p_last_seen jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_last_seen jsonb := COALESCE(p_last_seen, '{}'::jsonb);
  v_seqs jsonb := '{}'::jsonb;
  v_changed text[] := ARRAY[]::text[];
  v_prev bigint := 0;
  v_cur bigint := 0;
  v_counter_record record;
  v_actor_user_id uuid := NULL::uuid;
  v_last_alert_hash text := NULL::text;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_watched_batch_ids jsonb := '[]'::jsonb;
  v_watched_batch_signals jsonb := '[]'::jsonb;
  v_explicit_entity_keys jsonb := '[]'::jsonb;
  v_ping_context text := NULL::text;
  v_has_watched_batch_ids boolean := false;
  v_is_banking_pay_mode boolean := false;
  v_allow_generic_global_scan boolean := false;
  v_app_counter_mode text := 'SKIPPED';
  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('CHANGES_PING');

  IF COALESCE(jsonb_typeof(v_last_seen), 'null') <> 'object' THEN
    v_last_seen := '{}'::jsonb;
  END IF;

  v_ping_context := UPPER(NULLIF(BTRIM(COALESCE(
    v_last_seen ->> '__changes_ping_context',
    v_last_seen ->> '__route_context',
    v_last_seen ->> 'route_context',
    v_last_seen ->> '__context',
    v_last_seen ->> 'context',
    v_last_seen ->> '__mode',
    v_last_seen ->> 'mode',
    ''
  )), ''));

  IF v_ping_context IS NULL THEN
    v_ping_context := 'UNSPECIFIED';
  END IF;

  BEGIN
    v_actor_user_id := NULLIF(BTRIM(COALESCE(v_last_seen ->> '__banking_actor_user_id', '')), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor_user_id := NULL::uuid;
  END;

  v_last_alert_hash := NULLIF(BTRIM(COALESCE(
    v_last_seen ->> '__banking_alert_hash',
    v_last_seen ->> 'banking_alert_hash',
    ''
  )), '');

  IF jsonb_typeof(v_last_seen -> '__watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> '__watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_batches') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_batches';
  ELSE
    v_watched_batch_ids := '[]'::jsonb;
  END IF;

  IF COALESCE(jsonb_typeof(v_watched_batch_ids), 'null') = 'array' THEN
    v_has_watched_batch_ids := jsonb_array_length(v_watched_batch_ids) > 0;
  ELSE
    v_has_watched_batch_ids := false;
  END IF;

  IF jsonb_typeof(v_last_seen -> '__watched_entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> '__watched_entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> 'watched_entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> '__entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> '__entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> 'entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> 'entity_keys';
  ELSE
    v_explicit_entity_keys := '[]'::jsonb;
  END IF;

  v_is_banking_pay_mode :=
       v_actor_user_id IS NOT NULL
    OR v_has_watched_batch_ids
    OR v_ping_context IN (
      'BANKING',
      'BANKING_PAY',
      'BANKING_PAY_LIST',
      'BANKING_PAY_MODAL',
      'BANKING_PAY_PREVIEW',
      'BANKING_PAY_WATCH',
      'BANKING_PAY_BATCH_WATCH',
      'BANKING_PAY_CHANGES_PING',
      'PAY_BATCH_WATCH',
      'PAY_BATCH_MODAL',
      'PAY_BATCH_LIST'
    );

  v_allow_generic_global_scan :=
       v_is_banking_pay_mode IS NOT TRUE
   AND v_ping_context IN ('GENERIC_APP_COUNTERS', 'APP_CHANGE_COUNTERS', 'GLOBAL_APP_CHANGES', 'NON_BANKING_APP_CHANGES')
   AND LOWER(BTRIM(COALESCE(
      v_last_seen ->> '__allow_global_app_change_counter_scan',
      v_last_seen ->> 'allow_global_app_change_counter_scan',
      'false'
   ))) IN ('true', '1', 'yes', 'y', 'on');


  IF COALESCE(jsonb_typeof(v_explicit_entity_keys), 'null') = 'array'
     AND jsonb_array_length(v_explicit_entity_keys) > 0 THEN
    v_app_counter_mode := 'EXPLICIT_CAPPED_KEYS';

    FOR v_counter_record IN
      WITH raw_entity_keys AS (
        SELECT entity_key_entry.value,
               entity_key_entry.ordinality
        FROM jsonb_array_elements(COALESCE(v_explicit_entity_keys, '[]'::jsonb)) WITH ORDINALITY AS entity_key_entry(value, ordinality)
        LIMIT 25
      ),
      parsed_entity_keys AS (
        SELECT
          CASE
            WHEN jsonb_typeof(raw_entity_keys.value) = 'string'
              THEN NULLIF(BTRIM(TRIM(BOTH '"' FROM raw_entity_keys.value::text)), '')
            WHEN jsonb_typeof(raw_entity_keys.value) = 'object'
              THEN NULLIF(BTRIM(COALESCE(raw_entity_keys.value->>'entity_key', raw_entity_keys.value->>'key', raw_entity_keys.value->>'name', '')), '')
            ELSE NULL::text
          END AS entity_key,
          CASE
            WHEN jsonb_typeof(raw_entity_keys.value) = 'object'
             AND COALESCE(raw_entity_keys.value->>'known_seq', raw_entity_keys.value->>'seq', raw_entity_keys.value->>'last_seen_seq', '') ~ '^[0-9]+$'
              THEN COALESCE(raw_entity_keys.value->>'known_seq', raw_entity_keys.value->>'seq', raw_entity_keys.value->>'last_seen_seq')::bigint
            ELSE NULL::bigint
          END AS known_seq,
          raw_entity_keys.ordinality
        FROM raw_entity_keys
      ),
      requested_entity_keys AS (
        SELECT DISTINCT ON (parsed_entity_keys.entity_key)
          parsed_entity_keys.entity_key,
          parsed_entity_keys.known_seq,
          parsed_entity_keys.ordinality
        FROM parsed_entity_keys
        WHERE parsed_entity_keys.entity_key IS NOT NULL
          AND LENGTH(parsed_entity_keys.entity_key) <= 200
        ORDER BY parsed_entity_keys.entity_key, parsed_entity_keys.ordinality
      )
      SELECT requested_entity_keys.entity_key,
             requested_entity_keys.known_seq,
             COALESCE(change_counter.seq, 0) AS seq
      FROM requested_entity_keys
      LEFT JOIN public.app_change_counters AS change_counter
        ON change_counter.entity_key = requested_entity_keys.entity_key
      ORDER BY requested_entity_keys.ordinality
    LOOP
      v_cur := COALESCE(v_counter_record.seq, 0);

      IF v_counter_record.known_seq IS NOT NULL THEN
        v_prev := COALESCE(v_counter_record.known_seq, 0);
      ELSE
        BEGIN
          v_prev := COALESCE((v_last_seen ->> v_counter_record.entity_key)::bigint, 0);
        EXCEPTION WHEN OTHERS THEN
          v_prev := 0;
        END;
      END IF;

      v_seqs := v_seqs || jsonb_build_object(v_counter_record.entity_key, v_cur);

      IF v_cur > v_prev THEN
        v_changed := array_append(v_changed, v_counter_record.entity_key);
      END IF;
    END LOOP;
  ELSIF v_allow_generic_global_scan THEN
    v_app_counter_mode := 'EXPLICIT_NON_BANKING_GLOBAL_SCAN';

    FOR v_counter_record IN
      SELECT change_counter.entity_key, change_counter.seq
      FROM public.app_change_counters AS change_counter
      ORDER BY change_counter.entity_key
    LOOP
      v_cur := COALESCE(v_counter_record.seq, 0);
      v_prev := 0;

      BEGIN
        v_prev := COALESCE((v_last_seen ->> v_counter_record.entity_key)::bigint, 0);
      EXCEPTION WHEN OTHERS THEN
        v_prev := 0;
      END;

      v_seqs := v_seqs || jsonb_build_object(v_counter_record.entity_key, v_cur);

      IF v_cur > v_prev THEN
        v_changed := array_append(v_changed, v_counter_record.entity_key);
      END IF;
    END LOOP;
  ELSE
    v_app_counter_mode := CASE
      WHEN v_is_banking_pay_mode THEN 'SKIPPED_FOR_BANKING_PAY'
      ELSE 'SKIPPED_NO_EXPLICIT_KEYS'
    END;
  END IF;

  v_result := jsonb_build_object(
    'server_utc', now(),
    'seqs', v_seqs,
    'changed', to_jsonb(v_changed),
    'changes_ping_context', v_ping_context,
    'banking_pay_mode', COALESCE(v_is_banking_pay_mode, false),
    'app_change_counter_mode', v_app_counter_mode,
    'app_change_counter_cap', CASE WHEN v_app_counter_mode = 'EXPLICIT_CAPPED_KEYS' THEN 25 ELSE NULL::integer END
  );

  IF v_actor_user_id IS NOT NULL THEN
    SELECT
      COALESCE(alert_summary.alert_hash, v_cached_alert_hash),
      COALESCE(alert_summary.summary_hash, v_cached_summary_hash),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label
    INTO
      v_cached_alert_hash,
      v_cached_summary_hash,
      v_cached_unacknowledged_count,
      v_cached_highest_severity,
      v_cached_highest_label
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = v_actor_user_id;

    IF NOT FOUND THEN
      v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_cached_unacknowledged_count := 0;
      v_cached_highest_severity := NULL::text;
      v_cached_highest_label := NULL::text;
    END IF;

    v_result := v_result || jsonb_build_object(
      'banking_alert_hash', v_cached_alert_hash,
      'banking_alert_summary_signature', v_cached_summary_hash,
      'banking_alert_summary_changed', COALESCE(v_last_alert_hash IS DISTINCT FROM v_cached_alert_hash, true),
      'banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
      'grouped_banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
      'banking_highest_alert_severity', COALESCE(v_cached_highest_severity, ''),
      'banking_highest_alert_label', COALESCE(v_cached_highest_label, ''),
      'banking_alert_summary_included', false,
      'banking_alert_summary', NULL::jsonb
    );
  END IF;

  IF COALESCE(jsonb_typeof(v_watched_batch_ids), 'null') = 'array' THEN
    WITH raw_watched_batches AS (
      SELECT watched_batch.value,
             watched_batch.ordinality
      FROM jsonb_array_elements(COALESCE(v_watched_batch_ids, '[]'::jsonb)) WITH ORDINALITY AS watched_batch(value, ordinality)
      LIMIT 25
    ),
    parsed_watched_batches AS (
      SELECT
        CASE
          WHEN jsonb_typeof(raw_watched_batches.value) = 'string'
           AND TRIM(BOTH '"' FROM raw_watched_batches.value::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN TRIM(BOTH '"' FROM raw_watched_batches.value::text)::uuid
          WHEN jsonb_typeof(raw_watched_batches.value) = 'object'
           AND COALESCE(raw_watched_batches.value->>'pay_batch_id', raw_watched_batches.value->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(raw_watched_batches.value->>'pay_batch_id', raw_watched_batches.value->>'id')::uuid
          ELSE NULL::uuid
        END AS pay_batch_id,
        CASE
          WHEN jsonb_typeof(raw_watched_batches.value) = 'object'
           AND COALESCE(raw_watched_batches.value->>'known_version', raw_watched_batches.value->>'live_signal_version', '') ~ '^[0-9]+$'
            THEN COALESCE(raw_watched_batches.value->>'known_version', raw_watched_batches.value->>'live_signal_version')::bigint
          ELSE NULL::bigint
        END AS known_version,
        raw_watched_batches.ordinality
      FROM raw_watched_batches
    ),
    requested_watched_batches AS (
      SELECT DISTINCT ON (parsed_watched_batches.pay_batch_id)
        parsed_watched_batches.pay_batch_id,
        parsed_watched_batches.known_version,
        parsed_watched_batches.ordinality
      FROM parsed_watched_batches
      WHERE parsed_watched_batches.pay_batch_id IS NOT NULL
      ORDER BY parsed_watched_batches.pay_batch_id, parsed_watched_batches.ordinality
      LIMIT 25
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'pay_batch_id', requested_watched_batches.pay_batch_id::text,
      'known_version', requested_watched_batches.known_version,
      'live_signal_version', COALESCE(batch_signal.version, 0),
      'payment_status_version', COALESCE(batch_signal.payment_status_version, 0),
      'correction_progress_version', COALESCE(batch_signal.correction_progress_version, 0),
      'alert_version', COALESCE(batch_signal.alert_version, 0),
      'overview_version', COALESCE(batch_signal.overview_version, 0),
      'last_status_hash', batch_signal.last_status_hash,
      'last_alert_hash', batch_signal.last_alert_hash,
      'changed_since_version', requested_watched_batches.known_version IS NOT NULL AND COALESCE(batch_signal.version, 0) > requested_watched_batches.known_version
    ) ORDER BY requested_watched_batches.ordinality), '[]'::jsonb)
    INTO v_watched_batch_signals
    FROM requested_watched_batches
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = requested_watched_batches.pay_batch_id;

    v_result := v_result || jsonb_build_object(
      'watched_batch_signals', COALESCE(v_watched_batch_signals, '[]'::jsonb),
      'watched_batch_signal_hash', 'watched_batch_signals:v2:' || MD5(COALESCE(v_watched_batch_signals::text, '[]')),
      'watched_batch_cap', 25
    );
  END IF;

  RETURN v_result;
END;
$function$;


create or replace function public.banking_pay_operation_config_get(
    p_operation_type text,
    p_phase text,
    p_chunk_type text
)
returns table (
    chunk_size integer,
    min_chunk_size integer,
    max_chunk_size integer,
    max_advance_ms integer,
    lock_seconds integer
)
language plpgsql
security definer
stable
set search_path = public, pg_temp
as $$
declare
    v_operation_type text;
    v_phase text;
    v_chunk_type text;
    v_default_chunk_size integer;
    v_default_min_chunk_size integer;
    v_default_max_chunk_size integer;
    v_default_max_advance_ms integer;
    v_default_lock_seconds integer;
begin
    v_operation_type := coalesce(nullif(btrim(p_operation_type), ''), 'ALL');
    v_phase := coalesce(nullif(btrim(p_phase), ''), 'ALL');
    v_chunk_type := coalesce(nullif(btrim(p_chunk_type), ''), 'CANDIDATE_SCOPE');

    if v_chunk_type in ('TRANSFER_SUBMIT', 'PAYEE_READINESS', 'FRESHNESS_VALIDATE') then
        v_default_chunk_size := 50;
        v_default_min_chunk_size := 1;
        v_default_max_chunk_size := 250;
    else
        v_default_chunk_size := 100;
        v_default_min_chunk_size := 1;
        v_default_max_chunk_size := 500;
    end if;

    v_default_max_advance_ms := 15000;
    v_default_lock_seconds := 60;

    return query
    with candidate_config as (
        select
            config_exact.default_chunk_size,
            config_exact.min_chunk_size,
            config_exact.max_chunk_size,
            config_exact.max_advance_ms,
            config_exact.lock_seconds,
            1 as priority_order
        from public.banking_pay_operation_config as config_exact
        where config_exact.enabled is true
          and config_exact.operation_type = v_operation_type
          and config_exact.phase = v_phase
          and config_exact.chunk_type = v_chunk_type

        union all

        select
            config_operation_default.default_chunk_size,
            config_operation_default.min_chunk_size,
            config_operation_default.max_chunk_size,
            config_operation_default.max_advance_ms,
            config_operation_default.lock_seconds,
            2 as priority_order
        from public.banking_pay_operation_config as config_operation_default
        where config_operation_default.enabled is true
          and config_operation_default.operation_type = v_operation_type
          and config_operation_default.phase = 'ALL'
          and config_operation_default.chunk_type = v_chunk_type

        union all

        select
            config_global_default.default_chunk_size,
            config_global_default.min_chunk_size,
            config_global_default.max_chunk_size,
            config_global_default.max_advance_ms,
            config_global_default.lock_seconds,
            3 as priority_order
        from public.banking_pay_operation_config as config_global_default
        where config_global_default.enabled is true
          and config_global_default.operation_type = 'ALL'
          and config_global_default.phase = 'ALL'
          and config_global_default.chunk_type = v_chunk_type
    )
    select
        selected_config.default_chunk_size,
        selected_config.min_chunk_size,
        selected_config.max_chunk_size,
        selected_config.max_advance_ms,
        selected_config.lock_seconds
    from candidate_config as selected_config
    order by selected_config.priority_order asc
    limit 1;

    if found then
        return;
    end if;

    return query
    select
        v_default_chunk_size,
        v_default_min_chunk_size,
        v_default_max_chunk_size,
        v_default_max_advance_ms,
        v_default_lock_seconds;
end;
$$;


-- ============================================================
-- 3. banking_pay_operation_get
-- ============================================================


DROP FUNCTION IF EXISTS public.banking_pay_operation_get(uuid, uuid);
DROP FUNCTION IF EXISTS public.banking_pay_operation_get(uuid, uuid, text);


CREATE OR REPLACE FUNCTION public.banking_pay_operation_get(
    p_operation_id uuid,
    p_actor_user_id uuid DEFAULT NULL::uuid,
    p_mode text DEFAULT 'PROGRESS_LIGHT'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_mode text := upper(BTRIM(COALESCE(p_mode, 'PROGRESS_LIGHT')));
    v_operation public.banking_pay_operations%ROWTYPE;
    v_progress jsonb := '{}'::jsonb;
    v_result jsonb := '{}'::jsonb;
    v_error_summary jsonb := NULL::jsonb;
    v_heartbeat_age_seconds integer := NULL::integer;
    v_terminal boolean := false;
    v_failed boolean := false;
    v_review_required boolean := false;
    v_status_upper text := NULL::text;
    v_phase_upper text := NULL::text;
    v_operation_type_upper text := NULL::text;
    v_error_code text := NULL::text;
    v_error_message text := NULL::text;
    v_status_text text := NULL::text;
    v_draft_creation_failed_partial boolean := false;
    v_batch_action_blocked boolean := false;
    v_failed_partial_cleanup_status text := NULL::text;
    v_backend_runner_owned boolean := false;
    v_frontend_completion_required boolean := false;
    v_batch_ids jsonb := '[]'::jsonb;
    v_primary_pay_batch_id text := NULL::text;
    v_result_summary jsonb := NULL::jsonb;
BEGIN
    PERFORM public.banking_pay_hot_path_budget_apply('PROGRESS');

    IF p_operation_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'OPERATION_ID_REQUIRED');
    END IF;

    IF v_mode IS NULL OR v_mode = '' THEN
      v_mode := 'PROGRESS_LIGHT';
    END IF;

    IF v_mode NOT IN ('PROGRESS_LIGHT', 'LIGHT') THEN
      RAISE EXCEPTION 'BANKING_PAY_OPERATION_GET_MODE_FORBIDDEN'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_GET_MODE_FORBIDDEN', 'operation_id', p_operation_id::text, 'mode', p_mode)::text;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND (
          p_actor_user_id IS NULL
          OR operation_row.actor_user_id IS NULL
          OR operation_row.actor_user_id = p_actor_user_id
      );

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text);
    END IF;

    v_progress := COALESCE(v_operation.progress_json, '{}'::jsonb);
    v_result := COALESCE(v_operation.result_json, '{}'::jsonb);
    v_status_upper := UPPER(BTRIM(COALESCE(v_operation.status, '')));
    v_phase_upper := UPPER(BTRIM(COALESCE(v_operation.phase, '')));
    v_operation_type_upper := UPPER(BTRIM(COALESCE(v_operation.operation_type, '')));
    v_terminal := v_status_upper IN (
      'COMPLETE',
      'COMPLETED',
      'SUCCESS',
      'SUCCEEDED',
      'DONE',
      'FAILED',
      'ERROR',
      'CANCELLED',
      'CANCELED',
      'REVIEW_REQUIRED',
      'NEEDS_REVIEW',
      'REVIEW'
    );
    v_failed := v_status_upper IN ('FAILED', 'ERROR');
    v_review_required := v_status_upper IN ('REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW') OR COALESCE(v_operation.requires_user_action, false);
    v_heartbeat_age_seconds := CASE WHEN v_operation.heartbeat_at_utc IS NULL THEN NULL ELSE GREATEST(0, EXTRACT(EPOCH FROM (v_now - v_operation.heartbeat_at_utc))::integer) END;

    v_error_summary := CASE
      WHEN v_operation.error_json IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(v_operation.error_json) = 'object' THEN jsonb_strip_nulls(jsonb_build_object(
        'code', COALESCE(NULLIF(BTRIM(v_operation.error_json->>'code'), ''), NULLIF(BTRIM(v_operation.error_json->>'error_code'), '')),
        'message', LEFT(COALESCE(NULLIF(BTRIM(v_operation.error_json->>'message'), ''), NULLIF(BTRIM(v_operation.error_json->>'error'), ''), v_operation.error_json::text), 1000),
        'review_reason_code', COALESCE(NULLIF(BTRIM(v_operation.error_json->>'review_reason_code'), ''), NULLIF(BTRIM(v_operation.error_json->>'provider_submit_review_reason_code'), '')),
        'provider_submission_status', NULLIF(BTRIM(v_operation.error_json->>'provider_submission_status'), '')
      ))
      ELSE jsonb_build_object('message', LEFT(v_operation.error_json::text, 1000))
    END;

    v_error_code := COALESCE(
      NULLIF(BTRIM(COALESCE(v_error_summary->>'code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.error_json->>'code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.error_json->>'error_code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_progress->>'error_code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_progress->>'code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'error_code', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'code', '')), '')
    );

    v_error_message := COALESCE(
      NULLIF(BTRIM(COALESCE(v_error_summary->>'message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.error_json->>'message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.error_json->>'error', '')), ''),
      NULLIF(BTRIM(COALESCE(v_progress->>'error_message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_progress->>'message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'error_message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'message', '')), '')
    );

    v_status_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_progress->>'status_text', '')), ''),
      NULLIF(BTRIM(COALESCE(v_progress->>'last_message', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'status_text', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'last_message', '')), ''),
      CASE
        WHEN v_failed THEN COALESCE(v_error_message, CASE WHEN v_operation_type_upper = 'DRAFT_CREATE' THEN 'Draft creation failed.' ELSE 'Operation failed.' END)
        WHEN v_review_required THEN 'Review required.'
        WHEN v_status_upper IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE') THEN 'Operation complete.'
        ELSE NULL::text
      END
    );

    v_draft_creation_failed_partial := UPPER(BTRIM(COALESCE(
      v_progress->>'draft_creation_failed_partial',
      v_result->>'draft_creation_failed_partial',
      v_operation.error_json->>'draft_creation_failed_partial',
      'false'
    ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON');

    v_batch_action_blocked := UPPER(BTRIM(COALESCE(
      v_progress->>'batch_action_blocked',
      v_result->>'batch_action_blocked',
      v_operation.error_json->>'batch_action_blocked',
      v_progress->>'normal_draft_actions_blocked',
      v_result->>'normal_draft_actions_blocked',
      v_operation.error_json->>'normal_draft_actions_blocked',
      'false'
    ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON');

    v_failed_partial_cleanup_status := COALESCE(
      NULLIF(BTRIM(COALESCE(v_progress->>'failed_partial_cleanup_status', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result->>'failed_partial_cleanup_status', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.error_json->>'failed_partial_cleanup_status', '')), '')
    );

    v_backend_runner_owned := CASE
      WHEN v_operation_type_upper = 'DRAFT_CREATE' THEN true
      ELSE upper(BTRIM(COALESCE(
        v_operation.input_json->>'backend_runner_owned',
        v_operation.input_json->>'backendRunnerOwned',
        v_operation.config_json->>'backend_runner_owned',
        v_operation.config_json->>'backendRunnerOwned',
        v_progress->>'backend_runner_owned',
        v_progress->>'backendRunnerOwned',
        'false'
      ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON')
    END;

    v_frontend_completion_required := CASE
      WHEN v_operation_type_upper = 'DRAFT_CREATE' THEN false
      ELSE upper(BTRIM(COALESCE(
        v_operation.input_json->>'frontend_completion_required',
        v_operation.input_json->>'frontendCompletionRequired',
        v_operation.config_json->>'frontend_completion_required',
        v_operation.config_json->>'frontendCompletionRequired',
        v_progress->>'frontend_completion_required',
        v_progress->>'frontendCompletionRequired',
        'false'
      ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON')
    END;

    SELECT COALESCE(jsonb_agg(batch_id_dedup.batch_id_text ORDER BY batch_id_dedup.batch_id_text), '[]'::jsonb)
    INTO v_batch_ids
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(batch_id_source.batch_id_text), '') AS batch_id_text
      FROM (
        SELECT CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL::text ELSE v_operation.pay_batch_id::text END AS batch_id_text
        UNION ALL SELECT v_progress->>'pay_batch_id'
        UNION ALL SELECT v_progress->>'payBatchId'
        UNION ALL SELECT v_progress->>'primary_pay_batch_id'
        UNION ALL SELECT v_progress->>'primaryPayBatchId'
        UNION ALL SELECT v_result->>'pay_batch_id'
        UNION ALL SELECT v_result->>'payBatchId'
        UNION ALL SELECT v_result->>'primary_pay_batch_id'
        UNION ALL SELECT v_result->>'primaryPayBatchId'
        UNION ALL SELECT v_operation.error_json->>'pay_batch_id'
        UNION ALL SELECT v_operation.error_json->>'payBatchId'
        UNION ALL SELECT v_operation.error_json->>'primary_pay_batch_id'
        UNION ALL SELECT v_operation.error_json->>'primaryPayBatchId'
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'pay_batch_ids') = 'array' THEN v_progress->'pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'payBatchIds') = 'array' THEN v_progress->'payBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'created_pay_batch_ids') = 'array' THEN v_progress->'created_pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'createdPayBatchIds') = 'array' THEN v_progress->'createdPayBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'pay_batch_ids') = 'array' THEN v_result->'pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'payBatchIds') = 'array' THEN v_result->'payBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'created_pay_batch_ids') = 'array' THEN v_result->'created_pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'createdPayBatchIds') = 'array' THEN v_result->'createdPayBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_operation.error_json->'pay_batch_ids') = 'array' THEN v_operation.error_json->'pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_operation.error_json->'payBatchIds') = 'array' THEN v_operation.error_json->'payBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_operation.error_json->'created_pay_batch_ids') = 'array' THEN v_operation.error_json->'created_pay_batch_ids' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_operation.error_json->'createdPayBatchIds') = 'array' THEN v_operation.error_json->'createdPayBatchIds' ELSE '[]'::jsonb END)
        UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_operation.error_json#>'{created_batch_cleanup,discovered_pay_batch_ids}') = 'array' THEN v_operation.error_json#>'{created_batch_cleanup,discovered_pay_batch_ids}' ELSE '[]'::jsonb END)
      ) AS batch_id_source
    ) AS batch_id_dedup
    WHERE batch_id_dedup.batch_id_text IS NOT NULL;

    v_primary_pay_batch_id := COALESCE(
      CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL::text ELSE v_operation.pay_batch_id::text END,
      NULLIF(BTRIM(v_progress->>'primary_pay_batch_id'), ''),
      NULLIF(BTRIM(v_progress->>'primaryPayBatchId'), ''),
      NULLIF(BTRIM(v_progress->>'pay_batch_id'), ''),
      NULLIF(BTRIM(v_progress->>'payBatchId'), ''),
      NULLIF(BTRIM(v_result->>'primary_pay_batch_id'), ''),
      NULLIF(BTRIM(v_result->>'primaryPayBatchId'), ''),
      NULLIF(BTRIM(v_result->>'pay_batch_id'), ''),
      NULLIF(BTRIM(v_result->>'payBatchId'), ''),
      NULLIF(BTRIM(v_operation.error_json->>'primary_pay_batch_id'), ''),
      NULLIF(BTRIM(v_operation.error_json->>'primaryPayBatchId'), ''),
      NULLIF(BTRIM(v_operation.error_json->>'pay_batch_id'), ''),
      NULLIF(BTRIM(v_operation.error_json->>'payBatchId'), '')
    );

    v_result_summary := jsonb_strip_nulls(jsonb_build_object(
      'operation_type', v_operation.operation_type,
      'workbench_session_id', CASE WHEN v_operation.workbench_session_id IS NULL THEN NULL ELSE v_operation.workbench_session_id::text END,
      'pay_batch_id', v_primary_pay_batch_id,
      'primary_pay_batch_id', v_primary_pay_batch_id,
      'pay_batch_ids', v_batch_ids,
      'created_pay_batch_ids', v_batch_ids,
      'created_batch_count', CASE WHEN COALESCE(v_result->>'created_batch_count', '') ~ '^[0-9]+$' THEN (v_result->>'created_batch_count')::integer ELSE jsonb_array_length(v_batch_ids) END,
      'source_session_discarded', COALESCE(v_result->>'source_session_discarded', v_progress->>'source_session_discarded'),
      'last_message', COALESCE(v_result->>'last_message', v_progress->>'last_message', v_progress->>'status_text')
    ) || jsonb_build_object(
      'draft_creation_failed_partial', v_draft_creation_failed_partial,
      'batch_action_blocked', v_batch_action_blocked,
      'failed_partial_cleanup_status', v_failed_partial_cleanup_status
    ));

    RETURN jsonb_strip_nulls(
      jsonb_build_object(
        'ok', true,
        'mode', 'PROGRESS_LIGHT',
        'operation_id', v_operation.id::text,
        'id', v_operation.id::text,
        'pay_batch_id', COALESCE(CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END, v_primary_pay_batch_id),
        'primary_pay_batch_id', v_primary_pay_batch_id,
        'pay_batch_ids', v_batch_ids,
        'created_pay_batch_ids', v_batch_ids,
        'operation_type', v_operation.operation_type,
        'workbench_session_id', CASE WHEN v_operation.workbench_session_id IS NULL THEN NULL ELSE v_operation.workbench_session_id::text END,
        'root_operation_id', CASE WHEN v_operation.root_operation_id IS NULL THEN NULL ELSE v_operation.root_operation_id::text END,
        'idempotency_key', v_operation.idempotency_key,
        'backend_runner_owned', v_backend_runner_owned,
        'frontend_completion_required', v_frontend_completion_required,
        'status', v_operation.status,
        'phase', v_operation.phase,
        'runner_state', v_operation.runner_state,
        'run_after_utc', CASE WHEN v_operation.run_after_utc IS NULL THEN NULL ELSE v_operation.run_after_utc::text END,
        'lease_owner', v_operation.lease_owner,
        'lease_expires_at_utc', CASE WHEN v_operation.lease_expires_at_utc IS NULL THEN NULL ELSE v_operation.lease_expires_at_utc::text END,
        'heartbeat_at_utc', CASE WHEN v_operation.heartbeat_at_utc IS NULL THEN NULL ELSE v_operation.heartbeat_at_utc::text END,
        'heartbeat_age_seconds', v_heartbeat_age_seconds,
        'last_advanced_at_utc', CASE WHEN v_operation.last_advanced_at_utc IS NULL THEN NULL ELSE v_operation.last_advanced_at_utc::text END
      )
      || jsonb_build_object(
        'attempt_count', COALESCE(v_operation.attempt_count, 0),
        'max_attempts', v_operation.max_attempts,
        'requires_user_action', COALESCE(v_operation.requires_user_action, false),
        'resume_reason', v_operation.resume_reason,
        'terminal', v_terminal,
        'failed', v_failed,
        'error_code', v_error_code,
        'error_message', v_error_message,
        'status_text', v_status_text,
        'phase_index', CASE WHEN COALESCE(v_progress->>'phase_index', '') ~ '^[0-9]+$' THEN (v_progress->>'phase_index')::integer ELSE NULL::integer END,
        'phase_total', CASE WHEN COALESCE(v_progress->>'phase_total', '') ~ '^[0-9]+$' THEN (v_progress->>'phase_total')::integer ELSE NULL::integer END,
        'total_units', COALESCE(v_operation.total_units, 0),
        'completed_units', COALESCE(v_operation.completed_units, 0),
        'failed_units', COALESCE(v_operation.failed_units, 0),
        'current_chunk_index', COALESCE(v_operation.current_chunk_index, 0),
        'chunk_count', COALESCE(v_operation.chunk_count, 0),
        'draft_creation_failed_partial', v_draft_creation_failed_partial,
        'batch_action_blocked', v_batch_action_blocked,
        'failed_partial_cleanup_status', v_failed_partial_cleanup_status,
        'server_running', (v_operation.lease_owner IS NOT NULL AND v_operation.lease_expires_at_utc IS NOT NULL AND v_operation.lease_expires_at_utc > v_now),
        'waiting', v_status_upper IN ('WAITING_AUTHORISATION', 'WAITING_PROVIDER', 'WAITING_RETRY'),
        'review_required', v_review_required,
        'counters', jsonb_build_object(
          'total_units', COALESCE(v_operation.total_units, 0),
          'completed_units', COALESCE(v_operation.completed_units, 0),
          'failed_units', COALESCE(v_operation.failed_units, 0),
          'current_chunk_index', COALESCE(v_operation.current_chunk_index, 0),
          'chunk_count', COALESCE(v_operation.chunk_count, 0)
        ),
        'result_summary', CASE WHEN upper(BTRIM(COALESCE(v_operation.operation_type, ''))) = 'DRAFT_CREATE' THEN v_result_summary ELSE NULL::jsonb END,
        'small_error_summary', v_error_summary
      )
      || jsonb_build_object(
        'stale_summary', jsonb_strip_nulls(jsonb_build_object(
          'freshness_status', v_progress->>'freshness_status',
          'freshness_result_hash', v_progress->>'freshness_result_hash',
          'freshness_scope_hash', v_progress->>'freshness_scope_hash',
          'freshness_stale_units', v_progress->>'freshness_stale_units',
          'freshness_pending_units', v_progress->>'freshness_pending_units'
        )),
        'proof_hashes', jsonb_strip_nulls(jsonb_build_object(
          'freshness_result_hash', v_progress->>'freshness_result_hash',
          'freshness_scope_hash', v_progress->>'freshness_scope_hash',
          'prepared_transfer_proof_hash', COALESCE(v_progress->>'prepared_transfer_proof_hash', v_progress#>>'{prepare,prepared_transfer_proof_hash}'),
          'prepared_scope_hash', v_progress->>'prepared_scope_hash',
          'provider_scope_hash', v_progress->>'provider_scope_hash'
        )),
        'provider_counters', jsonb_strip_nulls(jsonb_build_object(
          'submitted', COALESCE(v_progress->>'provider_submitted_count', v_progress->>'submitted_count'),
          'accepted', COALESCE(v_progress->>'provider_accepted_count', v_progress->>'accepted_count'),
          'failed', COALESCE(v_progress->>'provider_failed_count', v_progress->>'failed_count'),
          'unknown', COALESCE(v_progress->>'provider_unknown_count', v_progress->>'unknown_count'),
          'review_required', COALESCE(v_progress->>'provider_review_required_count', v_progress->>'review_required_count'),
          'remaining_ready', COALESCE(v_progress->>'provider_remaining_ready_count', v_progress->>'remaining_ready_count'),
          'last_provider_message', COALESCE(v_progress->>'last_provider_message', v_progress#>>'{provider,last_message}')
        )),
        'last_message', COALESCE(v_progress->>'last_message', v_progress->>'status_text')
      )
      || jsonb_build_object(
        'created_at_utc', CASE WHEN v_operation.created_at_utc IS NULL THEN NULL ELSE v_operation.created_at_utc::text END,
        'started_at_utc', CASE WHEN v_operation.started_at_utc IS NULL THEN NULL ELSE v_operation.started_at_utc::text END,
        'updated_at_utc', CASE WHEN v_operation.updated_at_utc IS NULL THEN NULL ELSE v_operation.updated_at_utc::text END,
        'completed_at_utc', CASE WHEN v_operation.completed_at_utc IS NULL THEN NULL ELSE v_operation.completed_at_utc::text END,
        'failed_at_utc', CASE WHEN v_operation.failed_at_utc IS NULL THEN NULL ELSE v_operation.failed_at_utc::text END
      )
    );
END;
$function$;



-- ============================================================
-- 4. banking_pay_operation_claim_next
-- ============================================================


DROP FUNCTION IF EXISTS public.banking_pay_operation_claim_next(uuid, uuid, text, integer);

DROP FUNCTION IF EXISTS public.banking_pay_operation_claim_next(uuid, uuid, text, integer);

CREATE OR REPLACE FUNCTION public.banking_pay_operation_claim_next(
    p_operation_id uuid DEFAULT NULL::uuid,
    p_actor_user_id uuid DEFAULT NULL::uuid,
    p_lock_owner text DEFAULT NULL::text,
    p_lock_seconds integer DEFAULT 60,
    p_allow_backend_runner_owned boolean DEFAULT false,
    p_operation_types text[] DEFAULT NULL::text[]
)
RETURNS TABLE (
    claimed boolean,
    not_claimed_reason text,
    operation_id uuid,
    operation_type text,
    status text,
    phase text,
    actor_user_id uuid,
    workbench_session_id uuid,
    pay_batch_id uuid,
    root_operation_id uuid,
    idempotency_key text,
    input_json jsonb,
    config_json jsonb,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    total_units integer,
    completed_units integer,
    failed_units integer,
    current_chunk_index integer,
    chunk_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    updated_at_utc timestamptz,
    completed_at_utc timestamptz,
    failed_at_utc timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_operation public.banking_pay_operations%ROWTYPE;
    v_visible public.banking_pay_operations%ROWTYPE;
    v_lock_owner text := COALESCE(NULLIF(BTRIM(COALESCE(p_lock_owner, '')), ''), 'banking-runner:' || pg_backend_pid()::text);
    v_lock_seconds integer := LEAST(GREATEST(COALESCE(p_lock_seconds, 60), 10), 3600);
    v_not_claimed_reason text := NULL::text;
    v_allow_backend_runner_owned boolean := COALESCE(p_allow_backend_runner_owned, false);
    v_operation_types text[] := ARRAY[]::text[];
    v_visible_operation_type text := NULL::text;
    v_visible_backend_runner_claimable boolean := false;
    v_visible_actor_authorised boolean := false;
BEGIN
    PERFORM set_config('lock_timeout', '3s', true);

    SELECT COALESCE(array_agg(DISTINCT supplied_operation_type.normalized_operation_type) FILTER (WHERE supplied_operation_type.normalized_operation_type IS NOT NULL), ARRAY[]::text[])
    INTO v_operation_types
    FROM (
      SELECT NULLIF(upper(BTRIM(COALESCE(operation_type_value, ''))), '') AS normalized_operation_type
      FROM unnest(COALESCE(p_operation_types, ARRAY[]::text[])) AS supplied(operation_type_value)
    ) AS supplied_operation_type;

    IF COALESCE(array_length(v_operation_types, 1), 0) = 0 AND v_allow_backend_runner_owned IS TRUE THEN
      v_operation_types := ARRAY['DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT', 'REMITTANCE_QUEUE']::text[];
    END IF;

    WITH claimable AS (
      SELECT operation_row.id
      FROM public.banking_pay_operations AS operation_row
      WHERE (p_operation_id IS NULL OR operation_row.id = p_operation_id)
        AND (
          COALESCE(array_length(v_operation_types, 1), 0) = 0
          OR upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = ANY(v_operation_types)
        )
        AND (
          p_actor_user_id IS NULL
          OR operation_row.actor_user_id IS NULL
          OR operation_row.actor_user_id = p_actor_user_id
          OR (
            v_allow_backend_runner_owned IS TRUE
            AND upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = ANY(v_operation_types)
            AND (
              upper(BTRIM(COALESCE(operation_row.input_json->>'backend_runner_owned', operation_row.input_json->>'backendRunnerOwned', operation_row.config_json->>'backend_runner_owned', operation_row.config_json->>'backendRunnerOwned', operation_row.progress_json->>'backend_runner_owned', operation_row.progress_json->>'backendRunnerOwned', operation_row.progress_json->>'server_runnable', operation_row.progress_json->>'serverRunnable', 'false'))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON')
              OR (
                operation_row.config_json ? 'frontend_completion_required'
                AND upper(BTRIM(COALESCE(operation_row.config_json->>'frontend_completion_required', ''))) IN ('FALSE', 'F', '0', 'NO', 'N', 'OFF')
              )
              OR (
                operation_row.config_json ? 'frontendCompletionRequired'
                AND upper(BTRIM(COALESCE(operation_row.config_json->>'frontendCompletionRequired', ''))) IN ('FALSE', 'F', '0', 'NO', 'N', 'OFF')
              )
            )
          )
        )
        AND (
          (
            upper(BTRIM(COALESCE(operation_row.status, ''))) = 'RUNNING'
            AND upper(BTRIM(COALESCE(operation_row.runner_state, ''))) IN ('RUNNABLE', 'RUNNING', 'IDLE')
          )
          OR (
            upper(BTRIM(COALESCE(operation_row.status, ''))) = 'WAITING'
            AND upper(BTRIM(COALESCE(operation_row.runner_state, ''))) = 'RUNNABLE'
          )
          OR (
            upper(BTRIM(COALESCE(operation_row.status, ''))) = 'WAITING_PROVIDER'
            AND v_allow_backend_runner_owned IS TRUE
            AND upper(BTRIM(COALESCE(operation_row.runner_state, ''))) IN ('WAITING_PROVIDER', 'RUNNABLE')
            AND (
              (
                upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE'
                AND (
                  upper(BTRIM(COALESCE(operation_row.phase, ''))) IN ('APPLY_RAIL_UPDATES', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT', 'PROVIDER_WAITING', 'WAITING_PROVIDER_CONFIRMATION', 'POLL_PROVIDER', 'PROVIDER_POLL', 'APPLY_PROVIDER_UPDATES', 'CHECK_PROVIDER_OUTCOME')
                  OR upper(BTRIM(COALESCE(operation_row.progress_json->>'phase', operation_row.progress_json->>'operation_phase', operation_row.progress_json->>'operationPhase', operation_row.progress_json->>'next_phase', operation_row.progress_json->>'nextPhase', ''))) IN ('APPLY_RAIL_UPDATES', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT', 'PROVIDER_WAITING', 'WAITING_PROVIDER_CONFIRMATION', 'POLL_PROVIDER', 'PROVIDER_POLL', 'APPLY_PROVIDER_UPDATES', 'CHECK_PROVIDER_OUTCOME')
                  OR upper(BTRIM(COALESCE(operation_row.resume_reason, operation_row.progress_json->>'resume_reason', operation_row.progress_json->>'resumeReason', ''))) IN ('AWAITING_PROVIDER_OUTCOME', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT')
                )
              )
              OR (
                upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'PAYMENT_SETTLEMENT'
                AND (
                  upper(BTRIM(COALESCE(operation_row.phase, ''))) = 'APPLY_SETTLEMENT_CHUNKS'
                  OR upper(BTRIM(COALESCE(operation_row.progress_json->>'phase', operation_row.progress_json->>'operation_phase', operation_row.progress_json->>'operationPhase', operation_row.progress_json->>'next_phase', operation_row.progress_json->>'nextPhase', ''))) = 'APPLY_SETTLEMENT_CHUNKS'
                )
              )
            )
          )
        )
        AND COALESCE(operation_row.requires_user_action, false) = false
        AND COALESCE(operation_row.run_after_utc, v_now) <= v_now
        AND (
          operation_row.lease_owner IS NULL
          OR operation_row.lease_expires_at_utc IS NULL
          OR operation_row.lease_expires_at_utc <= v_now
        )
        AND COALESCE(operation_row.attempt_count, 0) < COALESCE(operation_row.max_attempts, 10)
      ORDER BY COALESCE(operation_row.run_after_utc, operation_row.created_at_utc, v_now), operation_row.created_at_utc, operation_row.id
      LIMIT 1
      FOR UPDATE SKIP LOCKED
    )
    UPDATE public.banking_pay_operations AS operation_update
    SET status = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('WAITING', 'WAITING_PROVIDER') THEN 'RUNNING' ELSE operation_update.status END,
        runner_state = 'RUNNING',
        lease_owner = v_lock_owner,
        lease_expires_at_utc = v_now + make_interval(secs => v_lock_seconds),
        heartbeat_at_utc = v_now,
        last_advanced_at_utc = v_now,
        started_at_utc = COALESCE(operation_update.started_at_utc, v_now),
        locked_by = v_lock_owner,
        lock_expires_at_utc = v_now + make_interval(secs => v_lock_seconds),
        progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_claimed_at_utc', v_now::text,
          'last_claim_lease_owner', v_lock_owner,
          'last_claim_runner_actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
          'last_claim_backend_runner_owned', v_allow_backend_runner_owned,
          'runner_state', 'RUNNING',
          'claim_count', (
            CASE
              WHEN COALESCE(operation_update.progress_json->>'claim_count', '') ~ '^[0-9]+$'
                THEN (operation_update.progress_json->>'claim_count')::integer
              ELSE 0
            END
          ) + 1,
          'backend_runner_claim', v_allow_backend_runner_owned,
          'runner_actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
        )),
        updated_at_utc = v_now
    FROM claimable
    WHERE operation_update.id = claimable.id
    RETURNING operation_update.* INTO v_operation;

    IF FOUND THEN
      RETURN QUERY
      SELECT
        true,
        NULL::text,
        v_operation.id,
        v_operation.operation_type,
        v_operation.status,
        v_operation.phase,
        v_operation.actor_user_id,
        v_operation.workbench_session_id,
        v_operation.pay_batch_id,
        v_operation.root_operation_id,
        v_operation.idempotency_key,
        v_operation.input_json,
        v_operation.config_json,
        jsonb_strip_nulls(COALESCE(v_operation.progress_json, '{}'::jsonb) || jsonb_build_object(
          'runner_state', v_operation.runner_state,
          'run_after_utc', CASE WHEN v_operation.run_after_utc IS NULL THEN NULL ELSE v_operation.run_after_utc::text END,
          'lease_owner', v_operation.lease_owner,
          'lease_expires_at_utc', CASE WHEN v_operation.lease_expires_at_utc IS NULL THEN NULL ELSE v_operation.lease_expires_at_utc::text END,
          'heartbeat_at_utc', CASE WHEN v_operation.heartbeat_at_utc IS NULL THEN NULL ELSE v_operation.heartbeat_at_utc::text END,
          'last_advanced_at_utc', CASE WHEN v_operation.last_advanced_at_utc IS NULL THEN NULL ELSE v_operation.last_advanced_at_utc::text END,
          'requires_user_action', COALESCE(v_operation.requires_user_action, false),
          'resume_reason', v_operation.resume_reason,
          'attempt_count', COALESCE(v_operation.attempt_count, 0),
          'max_attempts', v_operation.max_attempts
        )),
        v_operation.result_json,
        v_operation.error_json,
        v_operation.total_units,
        v_operation.completed_units,
        v_operation.failed_units,
        v_operation.current_chunk_index,
        v_operation.chunk_count,
        v_operation.lease_owner,
        v_operation.lease_expires_at_utc,
        v_operation.created_at_utc,
        v_operation.started_at_utc,
        v_operation.updated_at_utc,
        v_operation.completed_at_utc,
        v_operation.failed_at_utc;
      RETURN;
    END IF;

    IF p_operation_id IS NOT NULL THEN
      SELECT visible_operation.*
      INTO v_visible
      FROM public.banking_pay_operations AS visible_operation
      WHERE visible_operation.id = p_operation_id;

      IF FOUND THEN
        v_visible_operation_type := upper(BTRIM(COALESCE(v_visible.operation_type, '')));
        v_visible_backend_runner_claimable := v_allow_backend_runner_owned IS TRUE
          AND (
            COALESCE(array_length(v_operation_types, 1), 0) = 0
            OR v_visible_operation_type = ANY(v_operation_types)
          )
          AND (
            upper(BTRIM(COALESCE(v_visible.input_json->>'backend_runner_owned', v_visible.input_json->>'backendRunnerOwned', v_visible.config_json->>'backend_runner_owned', v_visible.config_json->>'backendRunnerOwned', v_visible.progress_json->>'backend_runner_owned', v_visible.progress_json->>'backendRunnerOwned', v_visible.progress_json->>'server_runnable', v_visible.progress_json->>'serverRunnable', 'false'))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON')
            OR (
              v_visible.config_json ? 'frontend_completion_required'
              AND upper(BTRIM(COALESCE(v_visible.config_json->>'frontend_completion_required', ''))) IN ('FALSE', 'F', '0', 'NO', 'N', 'OFF')
            )
            OR (
              v_visible.config_json ? 'frontendCompletionRequired'
              AND upper(BTRIM(COALESCE(v_visible.config_json->>'frontendCompletionRequired', ''))) IN ('FALSE', 'F', '0', 'NO', 'N', 'OFF')
            )
          );
        v_visible_actor_authorised := p_actor_user_id IS NULL OR v_visible.actor_user_id IS NULL OR v_visible.actor_user_id = p_actor_user_id OR v_visible_backend_runner_claimable IS TRUE;

        IF v_visible_actor_authorised IS NOT TRUE THEN
          RETURN QUERY
          SELECT
            false,
            'ACTOR_MISMATCH'::text,
            p_operation_id,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::uuid,
            NULL::uuid,
            NULL::uuid,
            NULL::uuid,
            NULL::text,
            NULL::jsonb,
            NULL::jsonb,
            NULL::jsonb,
            NULL::jsonb,
            NULL::jsonb,
            NULL::integer,
            NULL::integer,
            NULL::integer,
            NULL::integer,
            NULL::integer,
            NULL::text,
            NULL::timestamptz,
            NULL::timestamptz,
            NULL::timestamptz,
            NULL::timestamptz,
            NULL::timestamptz,
            NULL::timestamptz;
          RETURN;
        END IF;

        v_not_claimed_reason := CASE
          WHEN COALESCE(array_length(v_operation_types, 1), 0) > 0 AND v_visible_operation_type <> ALL(v_operation_types) THEN 'OPERATION_TYPE_NOT_IN_SCOPE'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) IN ('WAITING_AUTHORISATION', 'REVIEW_REQUIRED', 'COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED') THEN 'NOT_RUNNABLE_STATUS'
          WHEN COALESCE(v_visible.requires_user_action, false) THEN 'REQUIRES_USER_ACTION'
          WHEN COALESCE(v_visible.run_after_utc, v_now) > v_now THEN 'RUN_AFTER_NOT_DUE'
          WHEN v_visible.lease_owner IS NOT NULL AND v_visible.lease_expires_at_utc IS NOT NULL AND v_visible.lease_expires_at_utc > v_now THEN 'LEASE_ACTIVE'
          WHEN COALESCE(v_visible.attempt_count, 0) >= COALESCE(v_visible.max_attempts, 10) THEN 'MAX_ATTEMPTS_REACHED'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'RUNNING'
           AND upper(BTRIM(COALESCE(v_visible.runner_state, ''))) NOT IN ('RUNNABLE', 'RUNNING', 'IDLE') THEN 'RUNNING_NOT_RUNNABLE'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'WAITING'
           AND upper(BTRIM(COALESCE(v_visible.runner_state, ''))) <> 'RUNNABLE' THEN 'WAITING_NOT_RUNNABLE'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'WAITING_PROVIDER'
           AND v_allow_backend_runner_owned IS NOT TRUE THEN 'WAITING_PROVIDER_BACKEND_RUNNER_REQUIRED'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'WAITING_PROVIDER'
           AND upper(BTRIM(COALESCE(v_visible.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN 'WAITING_PROVIDER_OPERATION_TYPE_NOT_CLAIMABLE'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'WAITING_PROVIDER'
           AND upper(BTRIM(COALESCE(v_visible.runner_state, ''))) NOT IN ('WAITING_PROVIDER', 'RUNNABLE') THEN 'WAITING_PROVIDER_NOT_RUNNABLE'
          WHEN upper(BTRIM(COALESCE(v_visible.status, ''))) = 'WAITING_PROVIDER'
           AND NOT (
             (
               upper(BTRIM(COALESCE(v_visible.operation_type, ''))) = 'PAYMENT_EXECUTE'
               AND (
                 upper(BTRIM(COALESCE(v_visible.phase, ''))) IN ('APPLY_RAIL_UPDATES', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT', 'PROVIDER_WAITING', 'WAITING_PROVIDER_CONFIRMATION', 'POLL_PROVIDER', 'PROVIDER_POLL', 'APPLY_PROVIDER_UPDATES', 'CHECK_PROVIDER_OUTCOME')
                 OR upper(BTRIM(COALESCE(v_visible.progress_json->>'phase', v_visible.progress_json->>'operation_phase', v_visible.progress_json->>'operationPhase', v_visible.progress_json->>'next_phase', v_visible.progress_json->>'nextPhase', ''))) IN ('APPLY_RAIL_UPDATES', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT', 'PROVIDER_WAITING', 'WAITING_PROVIDER_CONFIRMATION', 'POLL_PROVIDER', 'PROVIDER_POLL', 'APPLY_PROVIDER_UPDATES', 'CHECK_PROVIDER_OUTCOME')
                 OR upper(BTRIM(COALESCE(v_visible.resume_reason, v_visible.progress_json->>'resume_reason', v_visible.progress_json->>'resumeReason', ''))) IN ('AWAITING_PROVIDER_OUTCOME', 'WAITING_PROVIDER', 'WAIT_PROVIDER', 'PROVIDER_WAIT')
               )
             )
             OR (
               upper(BTRIM(COALESCE(v_visible.operation_type, ''))) = 'PAYMENT_SETTLEMENT'
               AND (
                 upper(BTRIM(COALESCE(v_visible.phase, ''))) = 'APPLY_SETTLEMENT_CHUNKS'
                 OR upper(BTRIM(COALESCE(v_visible.progress_json->>'phase', v_visible.progress_json->>'operation_phase', v_visible.progress_json->>'operationPhase', v_visible.progress_json->>'next_phase', v_visible.progress_json->>'nextPhase', ''))) = 'APPLY_SETTLEMENT_CHUNKS'
               )
             )
           ) THEN 'WAITING_PROVIDER_NOT_RECHECK_PHASE'
          ELSE 'NOT_RUNNABLE'
        END;

        RETURN QUERY
        SELECT
          false,
          v_not_claimed_reason,
          v_visible.id,
          v_visible.operation_type,
          v_visible.status,
          v_visible.phase,
          v_visible.actor_user_id,
          v_visible.workbench_session_id,
          v_visible.pay_batch_id,
          v_visible.root_operation_id,
          v_visible.idempotency_key,
          v_visible.input_json,
          v_visible.config_json,
          jsonb_strip_nulls(COALESCE(v_visible.progress_json, '{}'::jsonb) || jsonb_build_object(
            'runner_state', v_visible.runner_state,
            'run_after_utc', CASE WHEN v_visible.run_after_utc IS NULL THEN NULL ELSE v_visible.run_after_utc::text END,
            'lease_owner', v_visible.lease_owner,
            'lease_expires_at_utc', CASE WHEN v_visible.lease_expires_at_utc IS NULL THEN NULL ELSE v_visible.lease_expires_at_utc::text END,
            'requires_user_action', COALESCE(v_visible.requires_user_action, false),
            'resume_reason', v_visible.resume_reason,
            'attempt_count', COALESCE(v_visible.attempt_count, 0),
            'max_attempts', v_visible.max_attempts,
            'backend_runner_claimable', v_visible_backend_runner_claimable
          )),
          v_visible.result_json,
          v_visible.error_json,
          v_visible.total_units,
          v_visible.completed_units,
          v_visible.failed_units,
          v_visible.current_chunk_index,
          v_visible.chunk_count,
          COALESCE(v_visible.lease_owner, v_visible.locked_by),
          COALESCE(v_visible.lease_expires_at_utc, v_visible.lock_expires_at_utc),
          v_visible.created_at_utc,
          v_visible.started_at_utc,
          v_visible.updated_at_utc,
          v_visible.completed_at_utc,
          v_visible.failed_at_utc;
        RETURN;
      END IF;
    END IF;

    RETURN QUERY
    SELECT
      false,
      CASE WHEN p_operation_id IS NULL THEN 'NO_RUNNABLE_OPERATION' ELSE 'NOT_FOUND_OR_NOT_AUTHORISED' END,
      p_operation_id,
      NULL::text,
      NULL::text,
      NULL::text,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      NULL::text,
      NULL::jsonb,
      NULL::jsonb,
      NULL::jsonb,
      NULL::jsonb,
      NULL::jsonb,
      NULL::integer,
      NULL::integer,
      NULL::integer,
      NULL::integer,
      NULL::integer,
      NULL::text,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz;
END;
$function$;



DROP FUNCTION IF EXISTS public.banking_pay_operation_save_progress(uuid, text, text, integer, integer, integer, integer, integer, jsonb, integer);

CREATE OR REPLACE FUNCTION public.banking_pay_operation_save_progress(
    p_operation_id uuid,
    p_status text DEFAULT NULL::text,
    p_phase text DEFAULT NULL::text,
    p_total_units integer DEFAULT NULL::integer,
    p_completed_units integer DEFAULT NULL::integer,
    p_failed_units integer DEFAULT NULL::integer,
    p_current_chunk_index integer DEFAULT NULL::integer,
    p_chunk_count integer DEFAULT NULL::integer,
    p_progress_json jsonb DEFAULT '{}'::jsonb,
    p_extend_lock_seconds integer DEFAULT NULL::integer
)
RETURNS TABLE (
    saved boolean,
    not_saved_reason text,
    operation_id uuid,
    operation_type text,
    status text,
    phase text,
    actor_user_id uuid,
    workbench_session_id uuid,
    pay_batch_id uuid,
    root_operation_id uuid,
    idempotency_key text,
    input_json jsonb,
    config_json jsonb,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    total_units integer,
    completed_units integer,
    failed_units integer,
    current_chunk_index integer,
    chunk_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    updated_at_utc timestamptz,
    completed_at_utc timestamptz,
    failed_at_utc timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_operation public.banking_pay_operations%ROWTYPE;
    v_status text;
    v_phase text;
    v_total_units integer;
    v_completed_units integer;
    v_failed_units integer;
    v_current_chunk_index integer;
    v_chunk_count integer;
    v_progress_json jsonb := COALESCE(p_progress_json, '{}'::jsonb);
    v_compact_progress_json jsonb := '{}'::jsonb;
    v_extend_lock_seconds integer;
    v_key text;
    v_value jsonb;
    v_runner_state text;
    v_run_after_utc timestamptz;
    v_requires_user_action boolean;
    v_resume_reason text;
BEGIN
    PERFORM set_config('lock_timeout', '3s', true);

    IF p_operation_id IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_SAVE_PROGRESS_OPERATION_ID_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_SAVE_PROGRESS_OPERATION_ID_REQUIRED')::text;
    END IF;

    IF jsonb_typeof(v_progress_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_SAVE_PROGRESS_PROGRESS_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_SAVE_PROGRESS_PROGRESS_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY
        SELECT false, 'NOT_FOUND'::text, p_operation_id, NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::integer, NULL::integer, NULL::integer, NULL::integer, NULL::integer, NULL::text, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz;
        RETURN;
    END IF;

    IF upper(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED') THEN
        RETURN QUERY
        SELECT false, 'TERMINAL'::text, v_operation.id, v_operation.operation_type, v_operation.status, v_operation.phase, v_operation.actor_user_id, v_operation.workbench_session_id, v_operation.pay_batch_id, v_operation.root_operation_id, v_operation.idempotency_key, v_operation.input_json, v_operation.config_json, v_operation.progress_json, v_operation.result_json, v_operation.error_json, v_operation.total_units, v_operation.completed_units, v_operation.failed_units, v_operation.current_chunk_index, v_operation.chunk_count, COALESCE(v_operation.lease_owner, v_operation.locked_by), COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc), v_operation.created_at_utc, v_operation.started_at_utc, v_operation.updated_at_utc, v_operation.completed_at_utc, v_operation.failed_at_utc;
        RETURN;
    END IF;

    FOR v_key, v_value IN SELECT key, value FROM jsonb_each(v_progress_json)
    LOOP
        IF jsonb_typeof(v_value) = 'array' AND jsonb_array_length(v_value) > 25 THEN
            v_compact_progress_json := v_compact_progress_json || jsonb_build_object(v_key, jsonb_build_object('omitted_large_array', true, 'count', jsonb_array_length(v_value)));
        ELSIF v_key IN ('candidate_ids', 'pending_candidate_ids', 'failed_candidate_ids', 'scope_ids', 'pay_batch_item_ids', 'transfer_ids', 'transfer_scope_ids', 'provider_events', 'rows', 'status_rows', 'canonical_preview_lines_json', 'full_preview_json')
              AND jsonb_typeof(v_value) IN ('array', 'object') THEN
            v_compact_progress_json := v_compact_progress_json || jsonb_build_object(v_key, jsonb_build_object('omitted_heavy_field', true, 'json_type', jsonb_typeof(v_value)));
        ELSE
            v_compact_progress_json := v_compact_progress_json || jsonb_build_object(v_key, v_value);
        END IF;
    END LOOP;

    v_status := upper(COALESCE(NULLIF(BTRIM(COALESCE(p_status, '')), ''), v_operation.status, 'RUNNING'));
    v_phase := upper(COALESCE(NULLIF(BTRIM(COALESCE(p_phase, '')), ''), v_operation.phase, 'INITIALISE'));

    IF v_status NOT IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER', 'REVIEW_REQUIRED', 'COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED') THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_SAVE_PROGRESS_STATUS_UNSUPPORTED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_SAVE_PROGRESS_STATUS_UNSUPPORTED', 'operation_id', p_operation_id::text, 'status', v_status)::text;
    END IF;

    v_total_units := GREATEST(COALESCE(p_total_units, v_operation.total_units, 0), 0);
    v_completed_units := GREATEST(COALESCE(p_completed_units, v_operation.completed_units, 0), 0);
    v_failed_units := GREATEST(COALESCE(p_failed_units, v_operation.failed_units, 0), 0);
    v_current_chunk_index := GREATEST(COALESCE(p_current_chunk_index, v_operation.current_chunk_index, 0), 0);
    v_chunk_count := GREATEST(COALESCE(p_chunk_count, v_operation.chunk_count, 0), 0);

    v_runner_state := upper(COALESCE(NULLIF(BTRIM(COALESCE(v_compact_progress_json->>'runner_state', '')), ''), CASE
      WHEN v_status = 'REVIEW_REQUIRED' THEN 'WAITING_USER_REVIEW'
      WHEN v_status = 'WAITING_AUTHORISATION' THEN 'WAITING_USER'
      WHEN v_status = 'WAITING_PROVIDER' THEN 'WAITING_PROVIDER'
      WHEN v_status IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 'RUNNABLE'
      WHEN v_status IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED') THEN v_status
      ELSE COALESCE(v_operation.runner_state, 'RUNNABLE')
    END));

    v_requires_user_action := CASE
      WHEN v_status IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION') THEN true
      WHEN v_compact_progress_json ? 'requires_user_action' THEN lower(BTRIM(COALESCE(v_compact_progress_json->>'requires_user_action', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ELSE COALESCE(v_operation.requires_user_action, false)
    END;

    v_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_compact_progress_json->>'resume_reason', '')), ''), v_operation.resume_reason);

    IF NULLIF(BTRIM(COALESCE(v_compact_progress_json->>'run_after_utc', '')), '') IS NOT NULL THEN
      BEGIN
        v_run_after_utc := (v_compact_progress_json->>'run_after_utc')::timestamptz;
      EXCEPTION WHEN OTHERS THEN
        v_run_after_utc := v_operation.run_after_utc;
      END;
    ELSE
      v_run_after_utc := CASE WHEN v_status IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN COALESCE(v_operation.run_after_utc, v_now) ELSE v_operation.run_after_utc END;
    END IF;

    IF p_extend_lock_seconds IS NOT NULL AND p_extend_lock_seconds > 0 THEN
        v_extend_lock_seconds := LEAST(GREATEST(p_extend_lock_seconds, 10), 3600);
    ELSE
        v_extend_lock_seconds := NULL;
    END IF;

    UPDATE public.banking_pay_operations AS operation_update
    SET status = v_status,
        phase = v_phase,
        total_units = v_total_units,
        completed_units = v_completed_units,
        failed_units = v_failed_units,
        current_chunk_index = v_current_chunk_index,
        chunk_count = v_chunk_count,
        progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || v_compact_progress_json || jsonb_build_object(
          'last_progress_saved_at_utc', v_now::text,
          'phase', v_phase,
          'status', v_status,
          'runner_state', v_runner_state,
          'requires_user_action', v_requires_user_action,
          'resume_reason', v_resume_reason
        )),
        runner_state = v_runner_state,
        run_after_utc = v_run_after_utc,
        requires_user_action = v_requires_user_action,
        resume_reason = v_resume_reason,
        heartbeat_at_utc = v_now,
        last_advanced_at_utc = v_now,
        lease_expires_at_utc = CASE WHEN v_extend_lock_seconds IS NULL THEN operation_update.lease_expires_at_utc ELSE v_now + make_interval(secs => v_extend_lock_seconds) END,
        lock_expires_at_utc = CASE WHEN v_extend_lock_seconds IS NULL THEN operation_update.lock_expires_at_utc ELSE v_now + make_interval(secs => v_extend_lock_seconds) END,
        updated_at_utc = v_now
    WHERE operation_update.id = v_operation.id
    RETURNING operation_update.* INTO v_operation;

    RETURN QUERY
    SELECT true, NULL::text, v_operation.id, v_operation.operation_type, v_operation.status, v_operation.phase, v_operation.actor_user_id, v_operation.workbench_session_id, v_operation.pay_batch_id, v_operation.root_operation_id, v_operation.idempotency_key, v_operation.input_json, v_operation.config_json, v_operation.progress_json, v_operation.result_json, v_operation.error_json, v_operation.total_units, v_operation.completed_units, v_operation.failed_units, v_operation.current_chunk_index, v_operation.chunk_count, COALESCE(v_operation.lease_owner, v_operation.locked_by), COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc), v_operation.created_at_utc, v_operation.started_at_utc, v_operation.updated_at_utc, v_operation.completed_at_utc, v_operation.failed_at_utc;
END;
$function$;





DROP FUNCTION IF EXISTS public.banking_pay_operation_start(text, uuid, text, uuid, uuid, uuid, jsonb, jsonb);



CREATE OR REPLACE FUNCTION public.banking_pay_operation_start(p_operation_type text, p_actor_user_id uuid, p_idempotency_key text, p_workbench_session_id uuid DEFAULT NULL::uuid, p_pay_batch_id uuid DEFAULT NULL::uuid, p_root_operation_id uuid DEFAULT NULL::uuid, p_input_json jsonb DEFAULT '{}'::jsonb, p_config_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(operation_id uuid, operation_type text, status text, phase text, actor_user_id uuid, workbench_session_id uuid, pay_batch_id uuid, root_operation_id uuid, idempotency_key text, input_json jsonb, config_json jsonb, progress_json jsonb, result_json jsonb, error_json jsonb, total_units integer, completed_units integer, failed_units integer, current_chunk_index integer, chunk_count integer, locked_by text, lock_expires_at_utc timestamp with time zone, created_at_utc timestamp with time zone, started_at_utc timestamp with time zone, updated_at_utc timestamp with time zone, completed_at_utc timestamp with time zone, failed_at_utc timestamp with time zone, is_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_operation_type text := upper(NULLIF(BTRIM(COALESCE(p_operation_type, '')), ''));
    v_idempotency_key text := NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), '');
    v_input_json jsonb := COALESCE(p_input_json, '{}'::jsonb);
    v_config_json jsonb := COALESCE(p_config_json, '{}'::jsonb);
    v_compact_input_json jsonb := '{}'::jsonb;
    v_compact_config_json jsonb := '{}'::jsonb;
    v_operation public.banking_pay_operations%ROWTYPE;
    v_existing_by_batch public.banking_pay_operations%ROWTYPE;
    v_allow_restart boolean := false;
    v_initial_status text := 'RUNNING';
    v_initial_phase text := 'INITIALISE';
    v_runner_state text := 'RUNNABLE';
    v_max_attempts integer := 10;
    v_lock_seconds integer := 60;
    v_chunk_config jsonb := '{}'::jsonb;
    v_run_after_utc timestamptz := NULL::timestamptz;
    v_server_runnable boolean := false;
    v_backend_runner_owned boolean := false;
    v_frontend_completion_required boolean := false;
    v_draft_stale_minutes integer := 120;
    v_existing_status text := NULL::text;
    v_existing_draft_is_terminal boolean := false;
    v_existing_draft_is_exhausted boolean := false;
    v_existing_draft_is_stale boolean := false;
    v_terminalise_reason text := NULL::text;
    v_settlement_batch_clean_success boolean := false;
    v_settlement_durable_truth jsonb := '{}'::jsonb;
    v_settlement_batch_status text := NULL::text;
    v_settlement_execution_commit_state text := NULL::text;
    v_settlement_execution_commit_ref text := NULL::text;
    v_settlement_execution_commit_ref_present boolean := false;
    v_settlement_completed_at_utc_present boolean := false;
    v_settlement_freshness_validation_status text := NULL::text;
    v_settlement_freshness_clean boolean := true;
    v_settlement_transfer_count integer := 0;
    v_settlement_terminal_success_transfer_count integer := 0;
    v_settlement_terminal_failed_transfer_count integer := 0;
    v_settlement_pending_or_unknown_transfer_count integer := 0;
    v_settlement_transfer_event_count integer := 0;
    v_settlement_provider_attempt_count integer := 0;
    v_settlement_provider_artifact_count integer := 0;
    v_settlement_candidate_count integer := 0;
    v_settlement_settled_candidate_count integer := 0;
    v_settlement_item_count integer := 0;
    v_settlement_linked_nonvoid_item_count integer := 0;
    v_settlement_covered_nonvoid_item_count integer := 0;
    v_settlement_no_bank_operation_count integer := 0;
    v_settlement_no_bank_scope_count integer := 0;
    v_settlement_settled_no_bank_scope_count integer := 0;
    v_settlement_unresolved_no_bank_scope_count integer := 0;
    v_settlement_authorised_no_bank_scope_count integer := 0;
    v_settlement_unauthorised_no_bank_scope_count integer := 0;
    v_settlement_confirmation_no_bank boolean := false;
    v_settlement_confirmation_mode text := NULL::text;
    v_settlement_confirmation_settlement_mode text := NULL::text;
    v_settlement_confirmation_local_commit_ref text := NULL::text;
    v_settlement_confirmation_auth_authorised boolean := false;
    v_settlement_positive_success boolean := false;
    v_settlement_no_bank_success boolean := false;
    v_settlement_mixed_success boolean := false;
BEGIN
    PERFORM set_config('lock_timeout', '3s', true);

    IF v_operation_type IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_OPERATION_TYPE_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_OPERATION_TYPE_REQUIRED')::text;
    END IF;

    IF v_operation_type NOT IN (
        'DRAFT_CREATE',
        'PAYMENT_EXECUTE',
        'PAYMENT_RETRY_BLOCKED_FUNDS',
        'PAYMENT_SETTLEMENT',
        'REMITTANCE_QUEUE',
        'PREVIEW_REFRESH'
    ) THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_OPERATION_TYPE_UNSUPPORTED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_OPERATION_TYPE_UNSUPPORTED', 'operation_type', v_operation_type)::text;
    END IF;

    IF v_idempotency_key IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_KEY_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_KEY_REQUIRED')::text;
    END IF;

    IF jsonb_typeof(v_input_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_INPUT_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_INPUT_MUST_BE_OBJECT')::text;
    END IF;

    IF jsonb_typeof(v_config_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_CONFIG_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_CONFIG_MUST_BE_OBJECT')::text;
    END IF;

    v_allow_restart := lower(BTRIM(COALESCE(v_input_json->>'explicit_restart', v_input_json->>'allow_restart', v_config_json->>'explicit_restart', v_config_json->>'allow_restart', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_max_attempts := LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'max_attempts', '')), '')::integer, 10), 1), 100);
    v_lock_seconds := LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'lock_seconds', '')), '')::integer, 60), 10), 3600);
    v_server_runnable := v_operation_type IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT', 'REMITTANCE_QUEUE');
    v_backend_runner_owned := v_server_runnable OR lower(BTRIM(COALESCE(v_input_json->>'backend_runner_owned', v_input_json->>'backendRunnerOwned', v_config_json->>'backend_runner_owned', v_config_json->>'backendRunnerOwned', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_frontend_completion_required := CASE
        WHEN v_operation_type IN ('DRAFT_CREATE', 'PAYMENT_SETTLEMENT', 'REMITTANCE_QUEUE') THEN false
        ELSE lower(BTRIM(COALESCE(v_input_json->>'frontend_completion_required', v_input_json->>'frontendCompletionRequired', v_config_json->>'frontend_completion_required', v_config_json->>'frontendCompletionRequired', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    END;
    v_draft_stale_minutes := LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'draft_create_stale_minutes', v_config_json->>'draftCreateStaleMinutes', '')), '')::integer, 120), 5), 1440);

    IF NULLIF(BTRIM(COALESCE(v_config_json->>'run_after_utc', v_config_json->>'runAfterUtc', '')), '') IS NOT NULL THEN
        BEGIN
            v_run_after_utc := COALESCE(v_config_json->>'run_after_utc', v_config_json->>'runAfterUtc')::timestamptz;
        EXCEPTION WHEN OTHERS THEN
            v_run_after_utc := NULL::timestamptz;
        END;
    END IF;

    IF v_server_runnable IS TRUE AND (v_run_after_utc IS NULL OR v_run_after_utc <= v_now) THEN
        v_run_after_utc := v_now;
    END IF;

    IF v_server_runnable IS TRUE THEN
        v_runner_state := 'RUNNABLE';
    END IF;

    IF v_operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
        v_initial_status := 'RUNNING';
        v_initial_phase := COALESCE(NULLIF(BTRIM(COALESCE(v_input_json->>'initial_phase', v_config_json->>'initial_phase', '')), ''), 'INITIALISE');
        v_runner_state := 'RUNNABLE';
        v_chunk_config := jsonb_strip_nulls(jsonb_build_object(
            'freshness_limit', LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'freshness_limit', '')), '')::integer, 100), 1), 100),
            'transfer_scope_limit', LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'transfer_scope_limit', '')), '')::integer, 100), 1), 100),
            'transfer_prepare_chunk_size', LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'transfer_prepare_chunk_size', '')), '')::integer, 25), 1), 25),
            'provider_submit_limit', LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'provider_submit_limit', '')), '')::integer, 25), 1), 25),
            'rail_update_limit', LEAST(GREATEST(COALESCE(NULLIF(BTRIM(COALESCE(v_config_json->>'rail_update_limit', '')), '')::integer, 25), 1), 100),
            'lock_seconds', v_lock_seconds
        ));
    END IF;

    v_compact_input_json := v_input_json
      - 'scope_candidate_ids'
      - 'candidate_ids'
      - 'pending_candidate_ids'
      - 'pay_batch_item_ids'
      - 'transfer_ids'
      - 'pay_batch_item_ids_json'
      - 'transfer_group_json'
      - 'full_preview_json'
      - 'canonical_preview_lines_json';

    v_compact_config_json := jsonb_strip_nulls((v_config_json
      - 'scope_candidate_ids'
      - 'candidate_ids'
      - 'pending_candidate_ids'
      - 'pay_batch_item_ids'
      - 'transfer_ids'
      - 'pay_batch_item_ids_json'
      - 'transfer_group_json'
      - 'full_preview_json'
      - 'canonical_preview_lines_json') || jsonb_build_object(
        'chunks', v_chunk_config,
        'server_runnable', CASE WHEN v_server_runnable THEN v_server_runnable ELSE NULL::boolean END,
        'backend_runner_owned', CASE WHEN v_server_runnable THEN v_backend_runner_owned ELSE NULL::boolean END,
        'frontend_completion_required', CASE WHEN v_server_runnable THEN v_frontend_completion_required ELSE NULL::boolean END,
        'operation_created_for_backend_runner', CASE WHEN v_server_runnable THEN v_backend_runner_owned ELSE NULL::boolean END,
        'run_after_utc', CASE WHEN v_server_runnable AND v_run_after_utc IS NOT NULL THEN v_run_after_utc::text ELSE NULL::text END
      ));

    PERFORM pg_advisory_xact_lock(pg_catalog.hashtextextended('banking_pay_operation_start:' || v_operation_type || ':' || v_idempotency_key, 0));

    IF v_operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') AND p_pay_batch_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(pg_catalog.hashtextextended('banking_pay_operation_start:PAYMENT_EXECUTION_BATCH:' || p_pay_batch_id::text, 0));
    END IF;

    IF v_operation_type = 'PAYMENT_SETTLEMENT' AND p_pay_batch_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(pg_catalog.hashtextextended('banking_pay_operation_start:PAYMENT_SETTLEMENT_BATCH:' || p_pay_batch_id::text, 0));
    END IF;

    IF v_operation_type = 'DRAFT_CREATE' AND p_workbench_session_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(pg_catalog.hashtextextended('banking_pay_operation_start:DRAFT_CREATE_WORKBENCH_SESSION:' || p_workbench_session_id::text, 0));
    END IF;

    SELECT existing_operation.*
    INTO v_operation
    FROM public.banking_pay_operations AS existing_operation
    WHERE existing_operation.idempotency_key = v_idempotency_key
    ORDER BY existing_operation.created_at_utc DESC, existing_operation.id DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
        IF upper(BTRIM(COALESCE(v_operation.operation_type, ''))) <> v_operation_type THEN
            RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_TYPE_MISMATCH'
              USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_TYPE_MISMATCH', 'operation_id', v_operation.id::text)::text;
        END IF;

        IF v_operation_type <> 'DRAFT_CREATE'
           AND p_actor_user_id IS NOT NULL
           AND v_operation.actor_user_id IS NOT NULL
           AND v_operation.actor_user_id <> p_actor_user_id THEN
            RAISE EXCEPTION 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_ACTOR_MISMATCH'
              USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_START_IDEMPOTENCY_ACTOR_MISMATCH', 'operation_id', v_operation.id::text)::text;
        END IF;

        IF v_operation_type = 'DRAFT_CREATE' THEN
            v_existing_status := upper(BTRIM(COALESCE(v_operation.status, '')));
            v_existing_draft_is_terminal := v_existing_status IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED');
            v_existing_draft_is_exhausted := v_existing_status IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'CONTINUING', 'WAITING_RETRY')
              AND COALESCE(v_operation.attempt_count, 0) >= COALESCE(v_operation.max_attempts, 10);
            v_existing_draft_is_stale := v_existing_status IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'CONTINUING', 'WAITING_RETRY')
              AND (v_operation.lease_owner IS NULL OR v_operation.lease_expires_at_utc IS NULL OR v_operation.lease_expires_at_utc <= v_now)
              AND COALESCE(v_operation.last_advanced_at_utc, v_operation.updated_at_utc, v_operation.created_at_utc, v_now) <= v_now - make_interval(mins => v_draft_stale_minutes);

            IF v_existing_draft_is_terminal IS TRUE THEN
                NULL;
            ELSIF v_allow_restart IS TRUE OR v_existing_draft_is_exhausted IS TRUE OR v_existing_draft_is_stale IS TRUE THEN
                v_terminalise_reason := CASE
                    WHEN v_allow_restart IS TRUE THEN 'DRAFT_CREATE_EXPLICIT_RESTART_TERMINATED'
                    WHEN v_existing_draft_is_exhausted IS TRUE THEN 'DRAFT_CREATE_ATTEMPT_LIMIT_EXHAUSTED'
                    ELSE 'STALE_DRAFT_CREATE_TERMINATED'
                END;

                UPDATE public.banking_pay_operations AS stale_operation_update
                SET status = 'FAILED',
                    runner_state = 'FAILED',
                    requires_user_action = false,
                    resume_reason = v_terminalise_reason,
                    lease_owner = NULL::text,
                    lease_expires_at_utc = NULL::timestamptz,
                    locked_by = NULL::text,
                    lock_expires_at_utc = NULL::timestamptz,
                    run_after_utc = NULL::timestamptz,
                    failed_at_utc = COALESCE(stale_operation_update.failed_at_utc, v_now),
                    error_json = jsonb_strip_nulls(COALESCE(stale_operation_update.error_json, '{}'::jsonb) || jsonb_build_object(
                        'code', v_terminalise_reason,
                        'message', 'DRAFT_CREATE operation was terminalised before starting a replacement operation.',
                        'operation_id', stale_operation_update.id::text,
                        'attempt_count', stale_operation_update.attempt_count,
                        'max_attempts', stale_operation_update.max_attempts,
                        'terminalised_at_utc', v_now::text
                    )),
                    progress_json = jsonb_strip_nulls(COALESCE(stale_operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
                        'active_operation_guard', 'DRAFT_CREATE_WORKBENCH_SESSION',
                        'terminalised_by_operation_start', true,
                        'terminalise_reason', v_terminalise_reason,
                        'terminalised_at_utc', v_now::text
                    )),
                    updated_at_utc = v_now
                WHERE stale_operation_update.id = v_operation.id;
            ELSE
        RETURN QUERY
        SELECT
            v_operation.id,
            v_operation.operation_type,
            v_operation.status,
            v_operation.phase,
            v_operation.actor_user_id,
            v_operation.workbench_session_id,
            v_operation.pay_batch_id,
            v_operation.root_operation_id,
            v_operation.idempotency_key,
            v_operation.input_json,
            v_operation.config_json,
            v_operation.progress_json,
            v_operation.result_json,
            v_operation.error_json,
            v_operation.total_units,
            v_operation.completed_units,
            v_operation.failed_units,
            v_operation.current_chunk_index,
            v_operation.chunk_count,
            COALESCE(v_operation.lease_owner, v_operation.locked_by),
            COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
            v_operation.created_at_utc,
            v_operation.started_at_utc,
            v_operation.updated_at_utc,
            v_operation.completed_at_utc,
            v_operation.failed_at_utc,
            true;
        RETURN;

            END IF;
        ELSIF v_operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
            v_existing_status := upper(BTRIM(COALESCE(v_operation.status, '')));

            IF v_existing_status IN ('QUEUED', 'RUNNING', 'WAITING', 'RUNNABLE', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'WAITING_FOR_PROVIDER', 'AWAITING_PROVIDER', 'WAITING_USER', 'WAITING_USER_REVIEW', 'REVIEW_REQUIRED') THEN
                RETURN QUERY
                SELECT
                    v_operation.id,
                    v_operation.operation_type,
                    v_operation.status,
                    v_operation.phase,
                    v_operation.actor_user_id,
                    v_operation.workbench_session_id,
                    v_operation.pay_batch_id,
                    v_operation.root_operation_id,
                    v_operation.idempotency_key,
                    v_operation.input_json,
                    v_operation.config_json,
                    v_operation.progress_json,
                    v_operation.result_json,
                    v_operation.error_json,
                    v_operation.total_units,
                    v_operation.completed_units,
                    v_operation.failed_units,
                    v_operation.current_chunk_index,
                    v_operation.chunk_count,
                    COALESCE(v_operation.lease_owner, v_operation.locked_by),
                    COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                    v_operation.created_at_utc,
                    v_operation.started_at_utc,
                    v_operation.updated_at_utc,
                    v_operation.completed_at_utc,
                    v_operation.failed_at_utc,
                    true;
                RETURN;
            END IF;
        ELSE
            v_existing_status := upper(BTRIM(COALESCE(v_operation.status, '')));

            IF v_operation_type = 'PAYMENT_SETTLEMENT'
               AND p_pay_batch_id IS NOT NULL
               AND v_existing_status IN ('FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED') THEN
                NULL;
            ELSE
                IF v_operation_type IN ('PAYMENT_SETTLEMENT', 'REMITTANCE_QUEUE')
                   AND v_existing_status NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED') THEN
                    UPDATE public.banking_pay_operations AS child_operation_update
                    SET config_json = jsonb_strip_nulls(COALESCE(child_operation_update.config_json, '{}'::jsonb) || jsonb_build_object(
                            'server_runnable', true,
                            'backend_runner_owned', true,
                            'frontend_completion_required', false,
                            'operation_created_for_backend_runner', true,
                            'run_after_utc', COALESCE(child_operation_update.run_after_utc, v_now)::text
                        )),
                        progress_json = jsonb_strip_nulls(COALESCE(child_operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
                            'server_runnable', true,
                            'backend_runner_owned', true,
                            'frontend_completion_required', false,
                            'operation_created_for_backend_runner', true,
                            'operation_reused_for_backend_runner', true,
                            'runner_flags_repaired_at_utc', v_now::text,
                            'run_after_utc', COALESCE(child_operation_update.run_after_utc, v_now)::text
                        )),
                        runner_state = 'RUNNABLE',
                        requires_user_action = false,
                        run_after_utc = COALESCE(child_operation_update.run_after_utc, v_now),
                        updated_at_utc = v_now
                    WHERE child_operation_update.id = v_operation.id
                    RETURNING child_operation_update.* INTO v_operation;
                END IF;

                RETURN QUERY
                SELECT
                    v_operation.id,
                    v_operation.operation_type,
                    v_operation.status,
                    v_operation.phase,
                    v_operation.actor_user_id,
                    v_operation.workbench_session_id,
                    v_operation.pay_batch_id,
                    v_operation.root_operation_id,
                    v_operation.idempotency_key,
                    v_operation.input_json,
                    v_operation.config_json,
                    v_operation.progress_json,
                    v_operation.result_json,
                    v_operation.error_json,
                    v_operation.total_units,
                    v_operation.completed_units,
                    v_operation.failed_units,
                    v_operation.current_chunk_index,
                    v_operation.chunk_count,
                    COALESCE(v_operation.lease_owner, v_operation.locked_by),
                    COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                    v_operation.created_at_utc,
                    v_operation.started_at_utc,
                    v_operation.updated_at_utc,
                    v_operation.completed_at_utc,
                    v_operation.failed_at_utc,
                    true;
                RETURN;
            END IF;
        END IF;
    END IF;

    IF v_operation_type = 'PAYMENT_SETTLEMENT' AND p_pay_batch_id IS NOT NULL THEN
        WITH batch_summary AS (
            SELECT
                batch_row.status AS batch_status,
                batch_row.execution_commit_state AS execution_commit_state,
                NULLIF(BTRIM(COALESCE(batch_row.execution_commit_ref, '')), '') AS execution_commit_ref,
                batch_row.completed_at_utc IS NOT NULL AS completed_at_utc_present,
                batch_row.freshness_validation_status AS freshness_validation_status,
                upper(BTRIM(COALESCE(batch_row.freshness_validation_status, ''))) NOT IN ('STALE', 'FAILED', 'BLOCKED', 'CONFLICT') AS freshness_clean,
                COALESCE(batch_row.execution_intent_json, '{}'::jsonb) AS execution_intent_json,
                COALESCE(batch_row.settlement_confirmation_json, '{}'::jsonb) AS settlement_confirmation_json
            FROM public.pay_batches AS batch_row
            WHERE batch_row.id = p_pay_batch_id
        ), confirmation_summary AS (
            SELECT
                lower(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS no_bank_payment_execution,
                upper(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'confirmation_mode', ''))) AS confirmation_mode,
                upper(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'settlement_mode', ''))) AS settlement_mode,
                NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'local_commit_reference', '')), '') AS local_commit_reference,
                NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'paye_net_state_hash', '')), '') AS confirmation_paye_net_state_hash,
                NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'bank_payment_projection_hash', '')), '') AS confirmation_bank_payment_projection_hash,
                UPPER(NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'projection_scope', '')), '')) AS confirmation_projection_scope,
                NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'auth_request_id', '')), '') AS confirmation_auth_request_id_text,
                NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'execution_operation_id', '')), '') AS confirmation_execution_operation_id_text,
                COALESCE(
                    NULLIF(BTRIM(COALESCE(batch_summary.settlement_confirmation_json->>'settlement_operation_id', '')), ''),
                    NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'settlement_operation_id', '')), '')
                ) AS confirmation_settlement_operation_id_text
            FROM batch_summary
        ), confirmation_auth_summary AS (
            SELECT EXISTS (
                SELECT 1
                FROM public.pay_batch_auth_requests AS auth_request
                CROSS JOIN batch_summary
                CROSS JOIN confirmation_summary
                WHERE auth_request.pay_batch_id = p_pay_batch_id
                  AND upper(BTRIM(COALESCE(auth_request.state, ''))) = 'AUTHORISED'
                  AND auth_request.id::text = confirmation_summary.confirmation_auth_request_id_text
                  AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = confirmation_summary.confirmation_execution_operation_id_text
                  AND lower(BTRIM(COALESCE(auth_request.execution_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                  AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'paye_net_state_hash', '')), '') = confirmation_summary.confirmation_paye_net_state_hash
                  AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'bank_payment_projection_hash', '')), '') = confirmation_summary.confirmation_bank_payment_projection_hash
                  AND UPPER(NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'pay_channel_scope', '')), '')) = confirmation_summary.confirmation_projection_scope
            ) AS confirmation_auth_authorised
        ), transfer_base AS (
            SELECT
                transfer_row.id AS pay_bank_transfer_id,
                upper(BTRIM(COALESCE(transfer_row.status, ''))) AS status_text,
                upper(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS rail_state_text,
                transfer_row.completed_at_utc AS completed_at_utc
            FROM public.pay_bank_transfers AS transfer_row
            WHERE transfer_row.pay_batch_id = p_pay_batch_id
        ), transfer_flags AS (
            SELECT
                transfer_base.pay_bank_transfer_id,
                (
                    transfer_base.status_text IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'VOIDED', 'RETURNED', 'REVERTED', 'BLOCKED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
                    OR transfer_base.rail_state_text IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'VOIDED', 'RETURNED', 'REVERTED', 'BLOCKED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
                ) AS is_failed,
                (
                    transfer_base.status_text IN ('COMPLETED', 'SETTLED', 'PAID', 'CONFIRMED', 'SUCCESS', 'SUCCEEDED')
                    OR transfer_base.rail_state_text IN ('COMPLETED', 'SETTLED', 'PAID', 'CONFIRMED', 'SUCCESS', 'SUCCEEDED')
                    OR transfer_base.completed_at_utc IS NOT NULL
                ) AS has_success_evidence
            FROM transfer_base
        ), transfer_summary AS (
            SELECT
                COUNT(*)::integer AS transfer_count,
                COUNT(*) FILTER (WHERE transfer_flags.has_success_evidence AND transfer_flags.is_failed IS NOT TRUE)::integer AS terminal_success_transfer_count,
                COUNT(*) FILTER (WHERE transfer_flags.is_failed)::integer AS terminal_failed_transfer_count,
                COUNT(*) FILTER (WHERE transfer_flags.has_success_evidence IS NOT TRUE AND transfer_flags.is_failed IS NOT TRUE)::integer AS pending_or_unknown_transfer_count
            FROM transfer_flags
        ), transfer_event_summary AS (
            SELECT COUNT(*)::integer AS transfer_event_count
            FROM public.pay_bank_transfer_events AS transfer_event
            WHERE transfer_event.pay_batch_id = p_pay_batch_id
        ), provider_attempt_summary AS (
            SELECT COUNT(*)::integer AS provider_attempt_count
            FROM public.banking_pay_operation_provider_attempts AS provider_attempt
            LEFT JOIN public.banking_pay_operations AS provider_operation
              ON provider_operation.id = provider_attempt.operation_id
            WHERE provider_attempt.pay_batch_id = p_pay_batch_id
               OR provider_operation.pay_batch_id = p_pay_batch_id
        ), provider_artifact_summary AS (
            SELECT COUNT(*) FILTER (
                WHERE COALESCE(transfer_scope.provider_submit_attempt_count, 0) > 0
                   OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_idempotency_key, '')), '') IS NOT NULL
                   OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_request_id, '')), '') IS NOT NULL
                   OR NULLIF(BTRIM(COALESCE(transfer_scope.provider_transaction_id, '')), '') IS NOT NULL
                   OR transfer_scope.provider_request_prepared_at_utc IS NOT NULL
                   OR transfer_scope.provider_request_sending_at_utc IS NOT NULL
                   OR transfer_scope.provider_request_sent_at_utc IS NOT NULL
                   OR transfer_scope.provider_response_at_utc IS NOT NULL
                   OR upper(BTRIM(COALESCE(transfer_scope.provider_submit_state, 'NOT_READY'))) IN (
                       'CLAIMED',
                       'REQUEST_PREPARING',
                       'REQUEST_SENDING',
                       'REQUEST_SENT_LOCAL',
                       'PROVIDER_ACCEPTED',
                       'PROVIDER_REJECTED',
                       'PROVIDER_UNKNOWN',
                       'CHUNK_FINALISED'
                   )
            )::integer AS provider_artifact_count
            FROM public.banking_pay_operation_transfer_scope AS transfer_scope
            WHERE transfer_scope.pay_batch_id = p_pay_batch_id
        ), candidate_summary AS (
            SELECT
                COUNT(*)::integer AS candidate_count,
                COUNT(*) FILTER (
                    WHERE upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
                       OR batch_candidate.settled_at_utc IS NOT NULL
                )::integer AS settled_candidate_count
            FROM public.pay_batch_candidates AS batch_candidate
            WHERE batch_candidate.pay_batch_id = p_pay_batch_id
        ), no_bank_scope_identity AS (
            SELECT
                settlement_scope.id AS settlement_scope_id,
                settlement_scope.operation_id,
                settlement_scope.status,
                settlement_scope.payload_json,
                COALESCE(
                    NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'auth_request_id', '')), ''),
                    confirmation_summary.confirmation_auth_request_id_text,
                    NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'auth_request_id', '')), '')
                ) AS auth_request_id_text,
                COALESCE(
                    NULLIF(BTRIM(COALESCE(settlement_scope.payload_json->>'execution_operation_id', '')), ''),
                    CASE WHEN settlement_operation.root_operation_id IS NULL THEN NULL::text ELSE settlement_operation.root_operation_id::text END,
                    confirmation_summary.confirmation_execution_operation_id_text,
                    NULLIF(BTRIM(COALESCE(batch_summary.execution_intent_json->>'operation_id', '')), '')
                ) AS execution_operation_id_text,
                (
                    confirmation_summary.confirmation_settlement_operation_id_text IS NULL
                    OR settlement_scope.operation_id::text = confirmation_summary.confirmation_settlement_operation_id_text
                ) AS settlement_operation_matches
            FROM public.banking_pay_operation_settlement_scope AS settlement_scope
            JOIN public.banking_pay_operations AS settlement_operation
              ON settlement_operation.id = settlement_scope.operation_id
            CROSS JOIN batch_summary
            CROSS JOIN confirmation_summary
            WHERE settlement_scope.pay_batch_id = p_pay_batch_id
              AND upper(BTRIM(COALESCE(settlement_scope.pay_channel, ''))) = 'PAYE'
              AND upper(BTRIM(COALESCE(settlement_scope.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
              AND upper(BTRIM(COALESCE(settlement_scope.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
              AND (
                  confirmation_summary.confirmation_settlement_operation_id_text IS NULL
                  OR settlement_scope.operation_id::text = confirmation_summary.confirmation_settlement_operation_id_text
              )
        ), no_bank_scope_base AS (
            SELECT
                no_bank_scope_identity.*,
                EXISTS (
                    SELECT 1
                    FROM public.pay_batch_auth_requests AS auth_request
                    WHERE auth_request.pay_batch_id = p_pay_batch_id
                      AND upper(BTRIM(COALESCE(auth_request.state, ''))) = 'AUTHORISED'
                      AND auth_request.id::text = no_bank_scope_identity.auth_request_id_text
                      AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = no_bank_scope_identity.execution_operation_id_text
                      AND (
                        lower(BTRIM(COALESCE(auth_request.execution_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                        OR lower(BTRIM(COALESCE(auth_request.execution_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                      )
                      AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'paye_net_state_hash', '')), '') = NULLIF(BTRIM(COALESCE(
                        no_bank_scope_identity.payload_json->>'paye_net_state_hash',
                        no_bank_scope_identity.payload_json->>'authorised_paye_net_state_hash',
                        ''
                      )), '')
                      AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'bank_payment_projection_hash', '')), '') = NULLIF(BTRIM(COALESCE(
                        no_bank_scope_identity.payload_json->>'bank_payment_projection_hash',
                        no_bank_scope_identity.payload_json->>'authorised_bank_payment_projection_hash',
                        ''
                      )), '')
                      AND UPPER(NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'pay_channel_scope', '')), '')) = UPPER(NULLIF(BTRIM(COALESCE(
                        no_bank_scope_identity.payload_json->>'projection_scope',
                        no_bank_scope_identity.payload_json->>'authorised_scope',
                        no_bank_scope_identity.payload_json->>'scope',
                        ''
                      )), ''))
                ) AND no_bank_scope_identity.settlement_operation_matches AS is_authorised
            FROM no_bank_scope_identity
        ), no_bank_scope_summary AS (
            SELECT
                COUNT(DISTINCT no_bank_scope_base.operation_id) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED')::integer AS no_bank_operation_count,
                COUNT(*) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED')::integer AS no_bank_scope_count,
                COUNT(*) FILTER (WHERE no_bank_scope_base.status = 'SETTLED')::integer AS settled_no_bank_scope_count,
                COUNT(*) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED' AND no_bank_scope_base.status <> 'SETTLED')::integer AS unresolved_no_bank_scope_count,
                COUNT(*) FILTER (WHERE no_bank_scope_base.status = 'SETTLED' AND no_bank_scope_base.is_authorised)::integer AS authorised_no_bank_scope_count,
                COUNT(*) FILTER (WHERE no_bank_scope_base.status <> 'SKIPPED' AND no_bank_scope_base.is_authorised IS NOT TRUE)::integer AS unauthorised_no_bank_scope_count
            FROM no_bank_scope_base
        ), authorised_no_bank_item_ids AS (
            SELECT DISTINCT scope_item.item_id_text::uuid AS pay_batch_item_id
            FROM no_bank_scope_base
            CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(
                CASE
                    WHEN JSONB_TYPEOF(no_bank_scope_base.payload_json->'pay_batch_item_ids') = 'array'
                      THEN no_bank_scope_base.payload_json->'pay_batch_item_ids'
                    ELSE '[]'::jsonb
                END
            ) AS scope_item(item_id_text)
            WHERE no_bank_scope_base.status = 'SETTLED'
              AND no_bank_scope_base.is_authorised
              AND scope_item.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ), item_summary AS (
            SELECT
                COUNT(*) FILTER (
                    WHERE COALESCE(batch_item.is_voided, false) = false
                      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
                )::integer AS item_count,
                COUNT(*) FILTER (
                    WHERE COALESCE(batch_item.is_voided, false) = false
                      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
                      AND batch_item.pay_bank_transfer_id IS NOT NULL
                )::integer AS linked_nonvoid_item_count,
                COUNT(*) FILTER (
                    WHERE COALESCE(batch_item.is_voided, false) = false
                      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
                      AND (
                        batch_item.pay_bank_transfer_id IS NOT NULL
                        OR EXISTS (
                            SELECT 1
                            FROM authorised_no_bank_item_ids AS authorised_item
                            WHERE authorised_item.pay_batch_item_id = batch_item.id
                        )
                      )
                )::integer AS covered_nonvoid_item_count
            FROM public.pay_batch_candidates AS batch_candidate
            JOIN public.pay_batch_items AS batch_item
              ON batch_item.pay_batch_candidate_id = batch_candidate.id
            WHERE batch_candidate.pay_batch_id = p_pay_batch_id
        )
        SELECT
            batch_summary.batch_status,
            batch_summary.execution_commit_state,
            batch_summary.execution_commit_ref,
            batch_summary.execution_commit_ref IS NOT NULL,
            batch_summary.completed_at_utc_present,
            batch_summary.freshness_validation_status,
            batch_summary.freshness_clean,
            COALESCE(transfer_summary.transfer_count, 0),
            COALESCE(transfer_summary.terminal_success_transfer_count, 0),
            COALESCE(transfer_summary.terminal_failed_transfer_count, 0),
            COALESCE(transfer_summary.pending_or_unknown_transfer_count, 0),
            COALESCE(transfer_event_summary.transfer_event_count, 0),
            COALESCE(provider_attempt_summary.provider_attempt_count, 0),
            COALESCE(provider_artifact_summary.provider_artifact_count, 0),
            COALESCE(candidate_summary.candidate_count, 0),
            COALESCE(candidate_summary.settled_candidate_count, 0),
            COALESCE(item_summary.item_count, 0),
            COALESCE(item_summary.linked_nonvoid_item_count, 0),
            COALESCE(item_summary.covered_nonvoid_item_count, 0),
            COALESCE(no_bank_scope_summary.no_bank_operation_count, 0),
            COALESCE(no_bank_scope_summary.no_bank_scope_count, 0),
            COALESCE(no_bank_scope_summary.settled_no_bank_scope_count, 0),
            COALESCE(no_bank_scope_summary.unresolved_no_bank_scope_count, 0),
            COALESCE(no_bank_scope_summary.authorised_no_bank_scope_count, 0),
            COALESCE(no_bank_scope_summary.unauthorised_no_bank_scope_count, 0),
            COALESCE(confirmation_summary.no_bank_payment_execution, false),
            confirmation_summary.confirmation_mode,
            confirmation_summary.settlement_mode,
            confirmation_summary.local_commit_reference,
            COALESCE(confirmation_auth_summary.confirmation_auth_authorised, false)
        INTO
            v_settlement_batch_status,
            v_settlement_execution_commit_state,
            v_settlement_execution_commit_ref,
            v_settlement_execution_commit_ref_present,
            v_settlement_completed_at_utc_present,
            v_settlement_freshness_validation_status,
            v_settlement_freshness_clean,
            v_settlement_transfer_count,
            v_settlement_terminal_success_transfer_count,
            v_settlement_terminal_failed_transfer_count,
            v_settlement_pending_or_unknown_transfer_count,
            v_settlement_transfer_event_count,
            v_settlement_provider_attempt_count,
            v_settlement_provider_artifact_count,
            v_settlement_candidate_count,
            v_settlement_settled_candidate_count,
            v_settlement_item_count,
            v_settlement_linked_nonvoid_item_count,
            v_settlement_covered_nonvoid_item_count,
            v_settlement_no_bank_operation_count,
            v_settlement_no_bank_scope_count,
            v_settlement_settled_no_bank_scope_count,
            v_settlement_unresolved_no_bank_scope_count,
            v_settlement_authorised_no_bank_scope_count,
            v_settlement_unauthorised_no_bank_scope_count,
            v_settlement_confirmation_no_bank,
            v_settlement_confirmation_mode,
            v_settlement_confirmation_settlement_mode,
            v_settlement_confirmation_local_commit_ref,
            v_settlement_confirmation_auth_authorised
        FROM batch_summary
        CROSS JOIN confirmation_summary
        CROSS JOIN confirmation_auth_summary
        CROSS JOIN transfer_summary
        CROSS JOIN transfer_event_summary
        CROSS JOIN provider_attempt_summary
        CROSS JOIN provider_artifact_summary
        CROSS JOIN candidate_summary
        CROSS JOIN item_summary
        CROSS JOIN no_bank_scope_summary;

        v_settlement_positive_success := (
             upper(BTRIM(COALESCE(v_settlement_batch_status, ''))) = 'SETTLED'
         AND upper(BTRIM(COALESCE(v_settlement_execution_commit_state, ''))) = 'COMMITTED'
         AND COALESCE(v_settlement_execution_commit_ref_present, false)
         AND COALESCE(v_settlement_completed_at_utc_present, false)
         AND COALESCE(v_settlement_transfer_count, 0) > 0
         AND COALESCE(v_settlement_terminal_success_transfer_count, 0) > 0
         AND COALESCE(v_settlement_terminal_failed_transfer_count, 0) = 0
         AND COALESCE(v_settlement_pending_or_unknown_transfer_count, 0) = 0
         AND COALESCE(v_settlement_candidate_count, 0) > 0
         AND COALESCE(v_settlement_settled_candidate_count, 0) = COALESCE(v_settlement_candidate_count, 0)
         AND (COALESCE(v_settlement_item_count, 0) = 0 OR COALESCE(v_settlement_linked_nonvoid_item_count, 0) = COALESCE(v_settlement_item_count, 0))
        );

        v_settlement_no_bank_success := (
             upper(BTRIM(COALESCE(v_settlement_batch_status, ''))) = 'SETTLED'
         AND upper(BTRIM(COALESCE(v_settlement_execution_commit_state, ''))) = 'COMMITTED'
         AND COALESCE(v_settlement_execution_commit_ref, '') LIKE 'NO_BANK_PAYMENT:%'
         AND COALESCE(v_settlement_completed_at_utc_present, false)
         AND COALESCE(v_settlement_transfer_count, 0) = 0
         AND COALESCE(v_settlement_transfer_event_count, 0) = 0
         AND COALESCE(v_settlement_provider_attempt_count, 0) = 0
         AND COALESCE(v_settlement_provider_artifact_count, 0) = 0
         AND COALESCE(v_settlement_candidate_count, 0) > 0
         AND COALESCE(v_settlement_settled_candidate_count, 0) = COALESCE(v_settlement_candidate_count, 0)
         AND COALESCE(v_settlement_confirmation_no_bank, false)
         AND v_settlement_confirmation_local_commit_ref IS NOT NULL
         AND v_settlement_confirmation_local_commit_ref = v_settlement_execution_commit_ref
         AND upper(BTRIM(COALESCE(v_settlement_confirmation_mode, ''))) IN ('NO_BANK_PAYMENT_REVIEW', 'NO_BANK_PAYMENT_EXECUTION', 'NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION')
         AND upper(BTRIM(COALESCE(v_settlement_confirmation_settlement_mode, ''))) IN ('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
         AND COALESCE(v_settlement_confirmation_auth_authorised, false)
         AND COALESCE(v_settlement_no_bank_operation_count, 0) = 1
         AND COALESCE(v_settlement_no_bank_scope_count, 0) > 0
         AND COALESCE(v_settlement_settled_no_bank_scope_count, 0) = COALESCE(v_settlement_no_bank_scope_count, 0)
         AND COALESCE(v_settlement_authorised_no_bank_scope_count, 0) = COALESCE(v_settlement_no_bank_scope_count, 0)
         AND COALESCE(v_settlement_unresolved_no_bank_scope_count, 0) = 0
         AND COALESCE(v_settlement_unauthorised_no_bank_scope_count, 0) = 0
         AND (COALESCE(v_settlement_item_count, 0) = 0 OR COALESCE(v_settlement_covered_nonvoid_item_count, 0) = COALESCE(v_settlement_item_count, 0))
        );

        v_settlement_mixed_success := (
             upper(BTRIM(COALESCE(v_settlement_batch_status, ''))) = 'SETTLED'
         AND upper(BTRIM(COALESCE(v_settlement_execution_commit_state, ''))) = 'COMMITTED'
         AND COALESCE(v_settlement_execution_commit_ref_present, false)
         AND COALESCE(v_settlement_execution_commit_ref, '') NOT LIKE 'NO_BANK_PAYMENT:%'
         AND COALESCE(v_settlement_completed_at_utc_present, false)
         AND COALESCE(v_settlement_transfer_count, 0) > 0
         AND COALESCE(v_settlement_terminal_success_transfer_count, 0) > 0
         AND COALESCE(v_settlement_terminal_failed_transfer_count, 0) = 0
         AND COALESCE(v_settlement_pending_or_unknown_transfer_count, 0) = 0
         AND COALESCE(v_settlement_candidate_count, 0) > 0
         AND COALESCE(v_settlement_settled_candidate_count, 0) = COALESCE(v_settlement_candidate_count, 0)
         AND COALESCE(v_settlement_no_bank_operation_count, 0) = 1
         AND COALESCE(v_settlement_no_bank_scope_count, 0) > 0
         AND COALESCE(v_settlement_settled_no_bank_scope_count, 0) = COALESCE(v_settlement_no_bank_scope_count, 0)
         AND COALESCE(v_settlement_authorised_no_bank_scope_count, 0) = COALESCE(v_settlement_no_bank_scope_count, 0)
         AND COALESCE(v_settlement_unresolved_no_bank_scope_count, 0) = 0
         AND COALESCE(v_settlement_unauthorised_no_bank_scope_count, 0) = 0
         AND (COALESCE(v_settlement_item_count, 0) = 0 OR COALESCE(v_settlement_covered_nonvoid_item_count, 0) = COALESCE(v_settlement_item_count, 0))
        );

        v_settlement_batch_clean_success := (
          COALESCE(v_settlement_positive_success, false)
          OR COALESCE(v_settlement_no_bank_success, false)
          OR COALESCE(v_settlement_mixed_success, false)
        );

        v_settlement_durable_truth := jsonb_build_object(
            'batch_status', v_settlement_batch_status,
            'execution_commit_state', v_settlement_execution_commit_state,
            'execution_commit_ref_present', COALESCE(v_settlement_execution_commit_ref_present, false),
            'execution_commit_ref_is_no_bank', COALESCE(v_settlement_execution_commit_ref, '') LIKE 'NO_BANK_PAYMENT:%',
            'completed_at_utc_present', COALESCE(v_settlement_completed_at_utc_present, false),
            'freshness_validation_status', v_settlement_freshness_validation_status,
            'freshness_clean', COALESCE(v_settlement_freshness_clean, true),
            'freshness_is_diagnostic_only', true,
            'transfer_count', COALESCE(v_settlement_transfer_count, 0),
            'terminal_success_transfer_count', COALESCE(v_settlement_terminal_success_transfer_count, 0),
            'terminal_failed_transfer_count', COALESCE(v_settlement_terminal_failed_transfer_count, 0),
            'pending_or_unknown_transfer_count', COALESCE(v_settlement_pending_or_unknown_transfer_count, 0),
            'transfer_event_count', COALESCE(v_settlement_transfer_event_count, 0),
            'provider_attempt_count', COALESCE(v_settlement_provider_attempt_count, 0),
            'provider_artifact_count', COALESCE(v_settlement_provider_artifact_count, 0),
            'candidate_count', COALESCE(v_settlement_candidate_count, 0),
            'settled_candidate_count', COALESCE(v_settlement_settled_candidate_count, 0),
            'unsettled_candidate_count', GREATEST(COALESCE(v_settlement_candidate_count, 0) - COALESCE(v_settlement_settled_candidate_count, 0), 0),
            'item_count', COALESCE(v_settlement_item_count, 0),
            'linked_nonvoid_item_count', COALESCE(v_settlement_linked_nonvoid_item_count, 0),
            'covered_nonvoid_item_count', COALESCE(v_settlement_covered_nonvoid_item_count, 0),
            'no_bank_operation_count', COALESCE(v_settlement_no_bank_operation_count, 0),
            'no_bank_scope_count', COALESCE(v_settlement_no_bank_scope_count, 0),
            'settled_no_bank_scope_count', COALESCE(v_settlement_settled_no_bank_scope_count, 0),
            'unresolved_no_bank_scope_count', COALESCE(v_settlement_unresolved_no_bank_scope_count, 0),
            'authorised_no_bank_scope_count', COALESCE(v_settlement_authorised_no_bank_scope_count, 0),
            'unauthorised_no_bank_scope_count', COALESCE(v_settlement_unauthorised_no_bank_scope_count, 0),
            'no_bank_confirmation_present', COALESCE(v_settlement_confirmation_no_bank, false),
            'no_bank_confirmation_mode', v_settlement_confirmation_mode,
            'settlement_mode', v_settlement_confirmation_settlement_mode,
            'confirmation_local_commit_ref_matches', (v_settlement_confirmation_local_commit_ref IS NOT NULL AND v_settlement_confirmation_local_commit_ref = v_settlement_execution_commit_ref),
            'confirmation_auth_authorised', COALESCE(v_settlement_confirmation_auth_authorised, false),
            'positive_transfer_backed_success', COALESCE(v_settlement_positive_success, false),
            'pure_no_bank_success', COALESCE(v_settlement_no_bank_success, false),
            'mixed_transfer_and_no_bank_success', COALESCE(v_settlement_mixed_success, false),
            'verified_clean_success', COALESCE(v_settlement_batch_clean_success, false)
        );

        SELECT settlement_operation.*
        INTO v_existing_by_batch
        FROM public.banking_pay_operations AS settlement_operation
        WHERE settlement_operation.pay_batch_id = p_pay_batch_id
          AND settlement_operation.operation_type = 'PAYMENT_SETTLEMENT'
          AND (
                upper(BTRIM(COALESCE(settlement_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER')
             OR upper(BTRIM(COALESCE(settlement_operation.status, ''))) = 'REVIEW_REQUIRED'
             OR (COALESCE(v_settlement_batch_clean_success, false) = true AND upper(BTRIM(COALESCE(settlement_operation.status, ''))) = 'COMPLETE' AND settlement_operation.phase = 'COMPLETE')
             OR (COALESCE(v_settlement_batch_clean_success, false) = true AND upper(BTRIM(COALESCE(settlement_operation.status, ''))) IN ('FAILED', 'CANCELLED', 'CANCELED'))
          )
        ORDER BY
          CASE
            WHEN upper(BTRIM(COALESCE(settlement_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER') THEN 0
            WHEN COALESCE(v_settlement_batch_clean_success, false) = true AND upper(BTRIM(COALESCE(settlement_operation.status, ''))) = 'COMPLETE' THEN 1
            WHEN COALESCE(v_settlement_batch_clean_success, false) = true AND upper(BTRIM(COALESCE(settlement_operation.status, ''))) IN ('FAILED', 'REVIEW_REQUIRED', 'CANCELLED', 'CANCELED') THEN 2
            ELSE 9
          END,
          COALESCE(settlement_operation.completed_at_utc, settlement_operation.updated_at_utc, settlement_operation.created_at_utc) DESC,
          settlement_operation.id DESC
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN
            v_operation := v_existing_by_batch;
            v_existing_status := upper(BTRIM(COALESCE(v_operation.status, '')));

            IF v_existing_status IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER') THEN
                UPDATE public.banking_pay_operations AS settlement_operation_update
                SET config_json = jsonb_strip_nulls(COALESCE(settlement_operation_update.config_json, '{}'::jsonb) || jsonb_build_object(
                        'server_runnable', true,
                        'backend_runner_owned', true,
                        'frontend_completion_required', false,
                        'operation_created_for_backend_runner', true,
                        'run_after_utc', COALESCE(settlement_operation_update.run_after_utc, v_now)::text
                    )),
                    progress_json = jsonb_strip_nulls(COALESCE(settlement_operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
                        'server_runnable', true,
                        'backend_runner_owned', true,
                        'frontend_completion_required', false,
                        'operation_created_for_backend_runner', true,
                        'operation_reused_for_backend_runner', true,
                        'payment_settlement_batch_guard_reused', true,
                        'payment_settlement_batch_guard_reason', 'EXISTING_ACTIVE_SETTLEMENT_OPERATION',
                        'durable_settlement_truth', v_settlement_durable_truth,
                        'runner_flags_repaired_at_utc', v_now::text,
                        'run_after_utc', COALESCE(settlement_operation_update.run_after_utc, v_now)::text
                    )),
                    runner_state = 'RUNNABLE',
                    requires_user_action = false,
                    run_after_utc = COALESCE(settlement_operation_update.run_after_utc, v_now),
                    updated_at_utc = v_now
                WHERE settlement_operation_update.id = v_operation.id
                RETURNING settlement_operation_update.* INTO v_operation;
            ELSIF COALESCE(v_settlement_batch_clean_success, false) = true THEN
                UPDATE public.banking_pay_operations AS settlement_operation_update
                SET status = 'COMPLETE',
                    phase = 'COMPLETE',
                    runner_state = 'COMPLETE',
                    requires_user_action = false,
                    resume_reason = CASE
                        WHEN upper(BTRIM(COALESCE(settlement_operation_update.status, ''))) = 'COMPLETE' THEN COALESCE(settlement_operation_update.resume_reason, 'EXISTING_COMPLETED_SETTLEMENT_OPERATION')
                        ELSE 'BATCH_ALREADY_DURABLY_SETTLED'
                    END,
                    lease_owner = NULL::text,
                    lease_expires_at_utc = NULL::timestamptz,
                    locked_by = NULL::text,
                    lock_expires_at_utc = NULL::timestamptz,
                    run_after_utc = NULL::timestamptz,
                    completed_at_utc = COALESCE(settlement_operation_update.completed_at_utc, v_now),
                    progress_json = jsonb_strip_nulls(COALESCE(settlement_operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
                        'payment_settlement_batch_guard_reused', true,
                        'payment_settlement_batch_guard_reason', CASE
                            WHEN upper(BTRIM(COALESCE(settlement_operation_update.status, ''))) = 'COMPLETE' THEN 'EXISTING_COMPLETED_SETTLEMENT_OPERATION'
                            ELSE 'OBSOLETE_TERMINAL_SETTLEMENT_OPERATION_COMPLETED_BY_DURABLE_SUCCESS'
                        END,
                        'idempotent_settlement_complete', true,
                        'already_settled', true,
                        'obsolete_terminal_status_before_idempotent_completion', CASE
                            WHEN upper(BTRIM(COALESCE(settlement_operation_update.status, ''))) = 'COMPLETE' THEN NULL::text
                            ELSE upper(BTRIM(COALESCE(settlement_operation_update.status, '')))
                        END,
                        'durable_settlement_truth', v_settlement_durable_truth,
                        'batch_guard_checked_at_utc', v_now::text
                    )),
                    result_json = jsonb_strip_nulls(COALESCE(settlement_operation_update.result_json, '{}'::jsonb) || jsonb_build_object(
                        'ok', true,
                        'idempotent_settlement_complete', true,
                        'already_settled', true,
                        'reason', 'BATCH_ALREADY_DURABLY_SETTLED',
                        'durable_settlement_truth', v_settlement_durable_truth
                    )),
                    error_json = CASE
                        WHEN upper(BTRIM(COALESCE(settlement_operation_update.status, ''))) IN ('FAILED', 'REVIEW_REQUIRED', 'CANCELLED', 'CANCELED')
                        THEN jsonb_strip_nulls(COALESCE(settlement_operation_update.error_json, '{}'::jsonb) || jsonb_build_object(
                            'obsolete_by_durable_settlement_success', true,
                            'obsolete_terminal_status_before_idempotent_completion', upper(BTRIM(COALESCE(settlement_operation_update.status, ''))),
                            'durable_settlement_truth', v_settlement_durable_truth,
                            'batch_guard_checked_at_utc', v_now::text
                        ))
                        ELSE settlement_operation_update.error_json
                    END,
                    updated_at_utc = v_now
                WHERE settlement_operation_update.id = v_operation.id
                RETURNING settlement_operation_update.* INTO v_operation;
            END IF;

            RETURN QUERY
            SELECT
                v_operation.id,
                v_operation.operation_type,
                v_operation.status,
                v_operation.phase,
                v_operation.actor_user_id,
                v_operation.workbench_session_id,
                v_operation.pay_batch_id,
                v_operation.root_operation_id,
                v_operation.idempotency_key,
                v_operation.input_json,
                v_operation.config_json,
                v_operation.progress_json,
                v_operation.result_json,
                v_operation.error_json,
                v_operation.total_units,
                v_operation.completed_units,
                v_operation.failed_units,
                v_operation.current_chunk_index,
                v_operation.chunk_count,
                COALESCE(v_operation.lease_owner, v_operation.locked_by),
                COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                v_operation.created_at_utc,
                v_operation.started_at_utc,
                v_operation.updated_at_utc,
                v_operation.completed_at_utc,
                v_operation.failed_at_utc,
                true;
            RETURN;
        ELSIF COALESCE(v_settlement_batch_clean_success, false) = true THEN
            INSERT INTO public.banking_pay_operations (
                operation_type,
                status,
                phase,
                actor_user_id,
                workbench_session_id,
                pay_batch_id,
                root_operation_id,
                idempotency_key,
                input_json,
                config_json,
                progress_json,
                result_json,
                error_json,
                total_units,
                completed_units,
                failed_units,
                current_chunk_index,
                chunk_count,
                locked_by,
                lock_expires_at_utc,
                started_at_utc,
                completed_at_utc,
                run_after_utc,
                lease_owner,
                lease_expires_at_utc,
                heartbeat_at_utc,
                last_advanced_at_utc,
                attempt_count,
                max_attempts,
                requires_user_action,
                runner_state,
                resume_reason
            )
            VALUES (
                v_operation_type,
                'COMPLETE',
                'COMPLETE',
                p_actor_user_id,
                p_workbench_session_id,
                p_pay_batch_id,
                p_root_operation_id,
                v_idempotency_key,
                v_compact_input_json,
                jsonb_strip_nulls(v_compact_config_json || jsonb_build_object(
                    'server_runnable', true,
                    'backend_runner_owned', true,
                    'frontend_completion_required', false,
                    'operation_created_for_backend_runner', true,
                    'idempotent_complete_on_start', true
                )),
                jsonb_strip_nulls(jsonb_build_object(
                    'server_runnable', true,
                    'backend_runner_owned', true,
                    'frontend_completion_required', false,
                    'progress_version', 1,
                    'status_text', 'Payment settlement already complete from durable batch truth.',
                    'operation_created_for_backend_runner', true,
                    'started_by_operation_start', true,
                    'payment_settlement_batch_guard_reused', false,
                    'payment_settlement_batch_guard_reason', 'BATCH_ALREADY_DURABLY_SETTLED',
                    'idempotent_settlement_complete', true,
                    'already_settled', true,
                    'durable_settlement_truth', v_settlement_durable_truth,
                    'created_at_utc', v_now::text
                )),
                jsonb_strip_nulls(jsonb_build_object(
                    'ok', true,
                    'idempotent_settlement_complete', true,
                    'already_settled', true,
                    'reason', 'BATCH_ALREADY_DURABLY_SETTLED',
                    'durable_settlement_truth', v_settlement_durable_truth
                )),
                NULL::jsonb,
                0,
                0,
                0,
                0,
                0,
                NULL::text,
                NULL::timestamptz,
                v_now,
                v_now,
                NULL::timestamptz,
                NULL::text,
                NULL::timestamptz,
                v_now,
                v_now,
                0,
                v_max_attempts,
                false,
                'COMPLETE',
                'BATCH_ALREADY_DURABLY_SETTLED'
            )
            RETURNING * INTO v_operation;

            RETURN QUERY
            SELECT
                v_operation.id,
                v_operation.operation_type,
                v_operation.status,
                v_operation.phase,
                v_operation.actor_user_id,
                v_operation.workbench_session_id,
                v_operation.pay_batch_id,
                v_operation.root_operation_id,
                v_operation.idempotency_key,
                v_operation.input_json,
                v_operation.config_json,
                v_operation.progress_json,
                v_operation.result_json,
                v_operation.error_json,
                v_operation.total_units,
                v_operation.completed_units,
                v_operation.failed_units,
                v_operation.current_chunk_index,
                v_operation.chunk_count,
                COALESCE(v_operation.lease_owner, v_operation.locked_by),
                COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                v_operation.created_at_utc,
                v_operation.started_at_utc,
                v_operation.updated_at_utc,
                v_operation.completed_at_utc,
                v_operation.failed_at_utc,
                false;
            RETURN;
        END IF;
    END IF;

    IF v_operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') AND p_pay_batch_id IS NOT NULL THEN
        SELECT active_operation.*
        INTO v_existing_by_batch
        FROM public.banking_pay_operations AS active_operation
        WHERE active_operation.pay_batch_id = p_pay_batch_id
          AND upper(BTRIM(COALESCE(active_operation.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
          AND NOT (
            upper(BTRIM(COALESCE(active_operation.operation_type, ''))) = 'PAYMENT_EXECUTE'
            AND (
              lower(BTRIM(COALESCE(active_operation.input_json->>'prepare_bank_csv_export_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR upper(BTRIM(COALESCE(active_operation.input_json->>'execution_mode', ''))) = 'BANK_CSV_EXPORT_PREPARE'
              OR BTRIM(COALESCE(active_operation.input_json->>'source', '')) = 'handleBankingPayBatchExportCsv'
              OR lower(COALESCE(active_operation.idempotency_key, '')) LIKE 'bank-csv-export-prepare:%'
            )
          )
          AND upper(BTRIM(COALESCE(active_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'RUNNABLE', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'WAITING_FOR_PROVIDER', 'AWAITING_PROVIDER', 'WAITING_USER', 'WAITING_USER_REVIEW', 'REVIEW_REQUIRED')
        ORDER BY
          CASE upper(BTRIM(COALESCE(active_operation.status, '')))
            WHEN 'RUNNING' THEN 0
            WHEN 'WAITING' THEN 1
            WHEN 'RUNNABLE' THEN 2
            WHEN 'QUEUED' THEN 3
            WHEN 'CONTINUING' THEN 4
            WHEN 'WAITING_RETRY' THEN 5
            WHEN 'WAITING_AUTHORISATION' THEN 6
            WHEN 'WAITING_AUTHORIZATION' THEN 6
            WHEN 'AWAITING_AUTHORISATION' THEN 6
            WHEN 'AWAITING_AUTHORIZATION' THEN 6
            WHEN 'WAITING_PROVIDER' THEN 7
            WHEN 'WAITING_FOR_PROVIDER' THEN 7
            WHEN 'AWAITING_PROVIDER' THEN 7
            WHEN 'WAITING_USER' THEN 8
            WHEN 'WAITING_USER_REVIEW' THEN 8
            WHEN 'REVIEW_REQUIRED' THEN 9
            ELSE 10
          END,
          active_operation.updated_at_utc DESC NULLS LAST,
          active_operation.created_at_utc DESC NULLS LAST,
          active_operation.id DESC
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN
            v_operation := v_existing_by_batch;
            RETURN QUERY
            SELECT
                v_operation.id,
                v_operation.operation_type,
                v_operation.status,
                v_operation.phase,
                v_operation.actor_user_id,
                v_operation.workbench_session_id,
                v_operation.pay_batch_id,
                v_operation.root_operation_id,
                v_operation.idempotency_key,
                v_operation.input_json,
                v_operation.config_json,
                v_operation.progress_json,
                v_operation.result_json,
                v_operation.error_json,
                v_operation.total_units,
                v_operation.completed_units,
                v_operation.failed_units,
                v_operation.current_chunk_index,
                v_operation.chunk_count,
                COALESCE(v_operation.lease_owner, v_operation.locked_by),
                COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                v_operation.created_at_utc,
                v_operation.started_at_utc,
                v_operation.updated_at_utc,
                v_operation.completed_at_utc,
                v_operation.failed_at_utc,
                true;
            RETURN;
        END IF;
    END IF;

    IF v_operation_type = 'DRAFT_CREATE' AND p_workbench_session_id IS NOT NULL THEN
        UPDATE public.banking_pay_operations AS stale_draft_update
        SET status = 'FAILED',
            runner_state = 'FAILED',
            requires_user_action = false,
            resume_reason = CASE
                WHEN v_allow_restart IS TRUE THEN 'DRAFT_CREATE_EXPLICIT_RESTART_TERMINATED'
                WHEN COALESCE(stale_draft_update.attempt_count, 0) >= COALESCE(stale_draft_update.max_attempts, 10) THEN 'DRAFT_CREATE_ATTEMPT_LIMIT_EXHAUSTED'
                ELSE 'STALE_DRAFT_CREATE_TERMINATED'
            END,
            lease_owner = NULL::text,
            lease_expires_at_utc = NULL::timestamptz,
            locked_by = NULL::text,
            lock_expires_at_utc = NULL::timestamptz,
            run_after_utc = NULL::timestamptz,
            failed_at_utc = COALESCE(stale_draft_update.failed_at_utc, v_now),
            error_json = jsonb_strip_nulls(COALESCE(stale_draft_update.error_json, '{}'::jsonb) || jsonb_build_object(
                'code', CASE
                    WHEN v_allow_restart IS TRUE THEN 'DRAFT_CREATE_EXPLICIT_RESTART_TERMINATED'
                    WHEN COALESCE(stale_draft_update.attempt_count, 0) >= COALESCE(stale_draft_update.max_attempts, 10) THEN 'DRAFT_CREATE_ATTEMPT_LIMIT_EXHAUSTED'
                    ELSE 'STALE_DRAFT_CREATE_TERMINATED'
                END,
                'message', 'DRAFT_CREATE operation was terminalised by the active workbench-session guard.',
                'operation_id', stale_draft_update.id::text,
                'attempt_count', stale_draft_update.attempt_count,
                'max_attempts', stale_draft_update.max_attempts,
                'terminalised_at_utc', v_now::text
            )),
            progress_json = jsonb_strip_nulls(COALESCE(stale_draft_update.progress_json, '{}'::jsonb) || jsonb_build_object(
                'active_operation_guard', 'DRAFT_CREATE_WORKBENCH_SESSION',
                'terminalised_by_operation_start', true,
                'terminalised_at_utc', v_now::text
            )),
            updated_at_utc = v_now
        WHERE upper(BTRIM(COALESCE(stale_draft_update.operation_type, ''))) = 'DRAFT_CREATE'
          AND (
            stale_draft_update.workbench_session_id = p_workbench_session_id
            OR COALESCE(stale_draft_update.input_json->>'workbench_session_id', '') = p_workbench_session_id::text
            OR COALESCE(stale_draft_update.input_json->>'workbenchSessionId', '') = p_workbench_session_id::text
            OR COALESCE(stale_draft_update.input_json->>'session_id', '') = p_workbench_session_id::text
            OR COALESCE(stale_draft_update.progress_json->>'workbench_session_id', '') = p_workbench_session_id::text
            OR COALESCE(stale_draft_update.progress_json->>'session_id', '') = p_workbench_session_id::text
          )
          AND upper(BTRIM(COALESCE(stale_draft_update.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'CONTINUING', 'WAITING_RETRY')
          AND (
            v_allow_restart IS TRUE
            OR COALESCE(stale_draft_update.attempt_count, 0) >= COALESCE(stale_draft_update.max_attempts, 10)
            OR (
              (stale_draft_update.lease_owner IS NULL OR stale_draft_update.lease_expires_at_utc IS NULL OR stale_draft_update.lease_expires_at_utc <= v_now)
              AND COALESCE(stale_draft_update.last_advanced_at_utc, stale_draft_update.updated_at_utc, stale_draft_update.created_at_utc, v_now) <= v_now - make_interval(mins => v_draft_stale_minutes)
            )
          );

        SELECT active_draft_operation.*
        INTO v_operation
        FROM public.banking_pay_operations AS active_draft_operation
        WHERE upper(BTRIM(COALESCE(active_draft_operation.operation_type, ''))) = 'DRAFT_CREATE'
          AND (
            active_draft_operation.workbench_session_id = p_workbench_session_id
            OR COALESCE(active_draft_operation.input_json->>'workbench_session_id', '') = p_workbench_session_id::text
            OR COALESCE(active_draft_operation.input_json->>'workbenchSessionId', '') = p_workbench_session_id::text
            OR COALESCE(active_draft_operation.input_json->>'session_id', '') = p_workbench_session_id::text
            OR COALESCE(active_draft_operation.progress_json->>'workbench_session_id', '') = p_workbench_session_id::text
            OR COALESCE(active_draft_operation.progress_json->>'session_id', '') = p_workbench_session_id::text
          )
          AND upper(BTRIM(COALESCE(active_draft_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'CONTINUING', 'WAITING_RETRY')
          AND COALESCE(active_draft_operation.attempt_count, 0) < COALESCE(active_draft_operation.max_attempts, 10)
        ORDER BY active_draft_operation.updated_at_utc DESC NULLS LAST, active_draft_operation.created_at_utc DESC NULLS LAST, active_draft_operation.id DESC
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN
            RETURN QUERY
            SELECT
                v_operation.id,
                v_operation.operation_type,
                v_operation.status,
                v_operation.phase,
                v_operation.actor_user_id,
                v_operation.workbench_session_id,
                v_operation.pay_batch_id,
                v_operation.root_operation_id,
                v_operation.idempotency_key,
                v_operation.input_json,
                v_operation.config_json,
                v_operation.progress_json,
                v_operation.result_json,
                v_operation.error_json,
                v_operation.total_units,
                v_operation.completed_units,
                v_operation.failed_units,
                v_operation.current_chunk_index,
                v_operation.chunk_count,
                COALESCE(v_operation.lease_owner, v_operation.locked_by),
                COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
                v_operation.created_at_utc,
                v_operation.started_at_utc,
                v_operation.updated_at_utc,
                v_operation.completed_at_utc,
                v_operation.failed_at_utc,
                true;
            RETURN;
        END IF;
    END IF;

    INSERT INTO public.banking_pay_operations (
        operation_type,
        status,
        phase,
        actor_user_id,
        workbench_session_id,
        pay_batch_id,
        root_operation_id,
        idempotency_key,
        input_json,
        config_json,
        progress_json,
        result_json,
        error_json,
        total_units,
        completed_units,
        failed_units,
        current_chunk_index,
        chunk_count,
        locked_by,
        lock_expires_at_utc,
        run_after_utc,
        lease_owner,
        lease_expires_at_utc,
        heartbeat_at_utc,
        last_advanced_at_utc,
        attempt_count,
        max_attempts,
        requires_user_action,
        runner_state,
        resume_reason
    )
    VALUES (
        v_operation_type,
        v_initial_status,
        v_initial_phase,
        p_actor_user_id,
        p_workbench_session_id,
        p_pay_batch_id,
        p_root_operation_id,
        v_idempotency_key,
        v_compact_input_json,
        v_compact_config_json,
        jsonb_strip_nulls(jsonb_build_object(
            'server_runnable', v_server_runnable,
            'backend_runner_owned', v_backend_runner_owned,
            'frontend_completion_required', v_frontend_completion_required,
            'progress_version', 1,
            'status_text', CASE
                WHEN v_operation_type = 'DRAFT_CREATE' THEN 'Draft creation operation created for backend runner.'
                WHEN v_operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN 'Payment execution operation created for backend runner.'
                WHEN v_operation_type = 'PAYMENT_SETTLEMENT' THEN 'Payment settlement operation created for backend runner.'
                WHEN v_operation_type = 'REMITTANCE_QUEUE' THEN 'Remittance queue operation created for backend runner.'
                ELSE 'Operation created.'
            END,
            'bounded_chunk_config', v_chunk_config,
            'operation_created_for_backend_runner', v_backend_runner_owned,
            'started_by_operation_start', true,
            'active_operation_guard', CASE WHEN v_operation_type = 'DRAFT_CREATE' THEN 'DRAFT_CREATE_WORKBENCH_SESSION' ELSE NULL::text END,
            'created_at_utc', v_now::text,
            'run_after_utc', CASE WHEN v_run_after_utc IS NULL THEN NULL ELSE v_run_after_utc::text END
        )),
        NULL::jsonb,
        NULL::jsonb,
        0,
        0,
        0,
        0,
        0,
        NULL::text,
        NULL::timestamptz,
        v_run_after_utc,
        NULL::text,
        NULL::timestamptz,
        v_now,
        NULL::timestamptz,
        0,
        v_max_attempts,
        false,
        v_runner_state,
        'OPERATION_STARTED'
    )
    RETURNING * INTO v_operation;

    RETURN QUERY
    SELECT
        v_operation.id,
        v_operation.operation_type,
        v_operation.status,
        v_operation.phase,
        v_operation.actor_user_id,
        v_operation.workbench_session_id,
        v_operation.pay_batch_id,
        v_operation.root_operation_id,
        v_operation.idempotency_key,
        v_operation.input_json,
        v_operation.config_json,
        v_operation.progress_json,
        v_operation.result_json,
        v_operation.error_json,
        v_operation.total_units,
        v_operation.completed_units,
        v_operation.failed_units,
        v_operation.current_chunk_index,
        v_operation.chunk_count,
        COALESCE(v_operation.lease_owner, v_operation.locked_by),
        COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc),
        v_operation.created_at_utc,
        v_operation.started_at_utc,
        v_operation.updated_at_utc,
        v_operation.completed_at_utc,
        v_operation.failed_at_utc,
        false;
END;
$function$;




DROP FUNCTION IF EXISTS public.banking_pay_operation_finish(uuid, text, jsonb, jsonb);

CREATE OR REPLACE FUNCTION public.banking_pay_operation_finish(
    p_operation_id uuid,
    p_status text,
    p_result_json jsonb DEFAULT NULL::jsonb,
    p_error_json jsonb DEFAULT NULL::jsonb
)
RETURNS TABLE (
    finished boolean,
    not_finished_reason text,
    operation_id uuid,
    operation_type text,
    status text,
    phase text,
    actor_user_id uuid,
    workbench_session_id uuid,
    pay_batch_id uuid,
    root_operation_id uuid,
    idempotency_key text,
    input_json jsonb,
    config_json jsonb,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    total_units integer,
    completed_units integer,
    failed_units integer,
    current_chunk_index integer,
    chunk_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    updated_at_utc timestamptz,
    completed_at_utc timestamptz,
    failed_at_utc timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_operation public.banking_pay_operations%ROWTYPE;
    v_status text := upper(NULLIF(BTRIM(COALESCE(p_status, '')), ''));
    v_result_json jsonb := p_result_json;
    v_error_json jsonb := p_error_json;
    v_runner_state text := NULL::text;
    v_requires_user_action boolean := false;
    v_resume_reason text := NULL::text;
BEGIN
    PERFORM set_config('lock_timeout', '3s', true);

    IF p_operation_id IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_OPERATION_ID_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_OPERATION_ID_REQUIRED')::text;
    END IF;

    IF v_status IS NULL OR v_status NOT IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_STATUS_INVALID'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_STATUS_INVALID', 'operation_id', p_operation_id::text, 'status', p_status)::text;
    END IF;

    IF v_result_json IS NOT NULL AND jsonb_typeof(v_result_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_RESULT_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_RESULT_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
    END IF;

    IF v_error_json IS NOT NULL AND jsonb_typeof(v_error_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_ERROR_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_ERROR_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'NOT_FOUND'::text, p_operation_id, NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::integer, NULL::integer, NULL::integer, NULL::integer, NULL::integer, NULL::text, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz;
        RETURN;
    END IF;

    IF upper(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED') THEN
        RETURN QUERY SELECT false, 'ALREADY_TERMINAL'::text, v_operation.id, v_operation.operation_type, v_operation.status, v_operation.phase, v_operation.actor_user_id, v_operation.workbench_session_id, v_operation.pay_batch_id, v_operation.root_operation_id, v_operation.idempotency_key, v_operation.input_json, v_operation.config_json, v_operation.progress_json, v_operation.result_json, v_operation.error_json, v_operation.total_units, v_operation.completed_units, v_operation.failed_units, v_operation.current_chunk_index, v_operation.chunk_count, COALESCE(v_operation.lease_owner, v_operation.locked_by), COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc), v_operation.created_at_utc, v_operation.started_at_utc, v_operation.updated_at_utc, v_operation.completed_at_utc, v_operation.failed_at_utc;
        RETURN;
    END IF;

    v_runner_state := CASE
      WHEN v_status = 'COMPLETE' THEN 'COMPLETE'
      WHEN v_status IN ('CANCELLED', 'CANCELED') THEN 'CANCELLED'
      WHEN v_status = 'FAILED' THEN 'FAILED'
      WHEN v_status = 'REVIEW_REQUIRED' THEN 'WAITING_USER_REVIEW'
      WHEN v_status = 'WAITING_AUTHORISATION' THEN 'WAITING_USER'
      WHEN v_status = 'WAITING_PROVIDER' THEN 'WAITING_PROVIDER'
      ELSE v_operation.runner_state
    END;

    v_requires_user_action := v_status IN ('FAILED', 'REVIEW_REQUIRED', 'WAITING_AUTHORISATION');
    v_resume_reason := CASE
      WHEN v_status = 'COMPLETE' THEN 'OPERATION_COMPLETE'
      WHEN v_status = 'REVIEW_REQUIRED' THEN 'REVIEW_REQUIRED'
      WHEN v_status = 'WAITING_AUTHORISATION' THEN 'AWAITING_PAYMENT_AUTHORISATION'
      WHEN v_status = 'WAITING_PROVIDER' THEN 'AWAITING_PROVIDER_OUTCOME'
      WHEN v_status = 'FAILED' THEN 'OPERATION_FAILED'
      ELSE v_operation.resume_reason
    END;

    UPDATE public.banking_pay_operations AS operation_update
    SET status = v_status,
        runner_state = v_runner_state,
        requires_user_action = v_requires_user_action,
        resume_reason = v_resume_reason,
        result_json = v_result_json,
        error_json = v_error_json,
        lease_owner = NULL::text,
        lease_expires_at_utc = NULL::timestamptz,
        locked_by = NULL::text,
        lock_expires_at_utc = NULL::timestamptz,
        run_after_utc = CASE WHEN v_status IN ('WAITING_PROVIDER') THEN operation_update.run_after_utc ELSE NULL::timestamptz END,
        heartbeat_at_utc = v_now,
        last_advanced_at_utc = v_now,
        completed_at_utc = CASE WHEN v_status IN ('COMPLETE', 'CANCELLED', 'CANCELED') THEN COALESCE(operation_update.completed_at_utc, v_now) ELSE operation_update.completed_at_utc END,
        failed_at_utc = CASE WHEN v_status = 'FAILED' THEN COALESCE(operation_update.failed_at_utc, v_now) ELSE operation_update.failed_at_utc END,
        progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'finished_at_utc', v_now::text,
          'finish_status', v_status,
          'runner_state', v_runner_state,
          'requires_user_action', v_requires_user_action,
          'resume_reason', v_resume_reason
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = v_operation.id
    RETURNING operation_update.* INTO v_operation;

    RETURN QUERY SELECT true, NULL::text, v_operation.id, v_operation.operation_type, v_operation.status, v_operation.phase, v_operation.actor_user_id, v_operation.workbench_session_id, v_operation.pay_batch_id, v_operation.root_operation_id, v_operation.idempotency_key, v_operation.input_json, v_operation.config_json, v_operation.progress_json, v_operation.result_json, v_operation.error_json, v_operation.total_units, v_operation.completed_units, v_operation.failed_units, v_operation.current_chunk_index, v_operation.chunk_count, COALESCE(v_operation.lease_owner, v_operation.locked_by), COALESCE(v_operation.lease_expires_at_utc, v_operation.lock_expires_at_utc), v_operation.created_at_utc, v_operation.started_at_utc, v_operation.updated_at_utc, v_operation.completed_at_utc, v_operation.failed_at_utc;
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_pay_operation_claim_chunk(
  p_operation_id uuid,
  p_phase text,
  p_chunk_type text,
  p_lock_owner text,
  p_lock_seconds integer DEFAULT 60
)
RETURNS TABLE (
  chunk_id uuid,
  operation_id uuid,
  phase text,
  chunk_type text,
  sequence_no integer,
  status text,
  payload_json jsonb,
  result_json jsonb,
  error_json jsonb,
  unit_count integer,
  completed_count integer,
  failed_count integer,
  locked_by text,
  lock_expires_at_utc timestamptz,
  created_at_utc timestamptz,
  started_at_utc timestamptz,
  completed_at_utc timestamptz,
  updated_at_utc timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_phase text := nullif(btrim(coalesce(p_phase, '')), '');
  v_chunk_type text := upper(nullif(btrim(coalesce(p_chunk_type, '')), ''));
  v_lock_owner text := coalesce(nullif(btrim(coalesce(p_lock_owner, '')), ''), 'unknown');
  v_lock_seconds integer := LEAST(GREATEST(coalesce(p_lock_seconds, 60), 5), 3600);
  v_chunk public.banking_pay_operation_chunks%ROWTYPE;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_claim_chunk requires p_operation_id';
  END IF;

  IF v_phase IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_claim_chunk requires p_phase';
  END IF;

  IF v_chunk_type IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_claim_chunk requires p_chunk_type';
  END IF;

  IF v_chunk_type NOT IN (
    'CANDIDATE_SCOPE',
    'TSFIN',
    'PAYEE_READINESS',
    'TRANSFER_GROUP',
    'TRANSFER_SCOPE_ITEM_SEED',
    'TRANSFER_SCOPE_ROLLUP',
    'TRANSFER_SUBMIT',
    'RAIL_UPDATE',
    'SETTLEMENT',
    'REMITTANCE',
    'PAYOUT_NOTICE',
    'PREVIEW_PAGE',
    'FRESHNESS_VALIDATE'
  ) THEN
    RAISE EXCEPTION 'Unsupported banking pay operation chunk_type: %', v_chunk_type;
  END IF;

  WITH claimable_chunk AS (
    SELECT chunk_row.id
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase = v_phase
      AND chunk_row.chunk_type = v_chunk_type
      AND (
        chunk_row.status = 'PENDING'
        OR (
          chunk_row.status = 'RUNNING'
          AND (chunk_row.lock_expires_at_utc IS NULL OR chunk_row.lock_expires_at_utc <= now())
        )
      )
    ORDER BY chunk_row.sequence_no ASC, chunk_row.created_at_utc NULLS FIRST, chunk_row.id
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET status = 'RUNNING',
      locked_by = v_lock_owner,
      lock_expires_at_utc = now() + make_interval(secs => v_lock_seconds),
      started_at_utc = coalesce(chunk_update.started_at_utc, now()),
      updated_at_utc = now()
  FROM claimable_chunk
  WHERE chunk_update.id = claimable_chunk.id
  RETURNING chunk_update.* INTO v_chunk;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT v_chunk.id,
         v_chunk.operation_id,
         v_chunk.phase,
         v_chunk.chunk_type,
         v_chunk.sequence_no,
         v_chunk.status,
         v_chunk.payload_json,
         v_chunk.result_json,
         v_chunk.error_json,
         v_chunk.unit_count,
         v_chunk.completed_count,
         v_chunk.failed_count,
         v_chunk.locked_by,
         v_chunk.lock_expires_at_utc,
         v_chunk.created_at_utc,
         v_chunk.started_at_utc,
         v_chunk.completed_at_utc,
         v_chunk.updated_at_utc;
END;
$function$;

DROP FUNCTION IF EXISTS public.banking_pay_operation_finish_chunk(uuid, text, integer, integer, jsonb, jsonb);

CREATE OR REPLACE FUNCTION public.banking_pay_operation_finish_chunk(
    p_chunk_id uuid,
    p_status text,
    p_completed_count integer DEFAULT NULL::integer,
    p_failed_count integer DEFAULT NULL::integer,
    p_result_json jsonb DEFAULT NULL::jsonb,
    p_error_json jsonb DEFAULT NULL::jsonb
)
RETURNS TABLE (
    finished boolean,
    not_finished_reason text,
    chunk_id uuid,
    operation_id uuid,
    phase text,
    chunk_type text,
    sequence_no integer,
    status text,
    payload_json jsonb,
    result_json jsonb,
    error_json jsonb,
    unit_count integer,
    completed_count integer,
    failed_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    completed_at_utc timestamptz,
    updated_at_utc timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_chunk public.banking_pay_operation_chunks%ROWTYPE;
    v_status text := upper(NULLIF(BTRIM(COALESCE(p_status, '')), ''));
    v_completed_count integer := 0;
    v_failed_count integer := 0;
    v_result_json jsonb := p_result_json;
    v_error_json jsonb := p_error_json;
    v_result_hash text := NULL::text;
    v_error_summary jsonb := NULL::jsonb;
BEGIN
    PERFORM set_config('lock_timeout', '3s', true);

    IF p_chunk_id IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_CHUNK_ID_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_CHUNK_ID_REQUIRED')::text;
    END IF;

    IF v_status IS NULL OR v_status NOT IN ('PENDING', 'COMPLETE', 'FAILED', 'SKIPPED') THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_CHUNK_STATUS_INVALID'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_CHUNK_STATUS_INVALID', 'chunk_id', p_chunk_id::text, 'status', p_status)::text;
    END IF;

    IF v_result_json IS NOT NULL AND jsonb_typeof(v_result_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_CHUNK_RESULT_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_CHUNK_RESULT_MUST_BE_OBJECT', 'chunk_id', p_chunk_id::text)::text;
    END IF;

    IF v_error_json IS NOT NULL AND jsonb_typeof(v_error_json) <> 'object' THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FINISH_CHUNK_ERROR_MUST_BE_OBJECT'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FINISH_CHUNK_ERROR_MUST_BE_OBJECT', 'chunk_id', p_chunk_id::text)::text;
    END IF;

    SELECT chunk_row.*
    INTO v_chunk
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = p_chunk_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'NOT_FOUND'::text, p_chunk_id, NULL::uuid, NULL::text, NULL::text, NULL::integer, NULL::text, NULL::jsonb, NULL::jsonb, NULL::jsonb, NULL::integer, NULL::integer, NULL::integer, NULL::text, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz;
        RETURN;
    END IF;

    IF upper(BTRIM(COALESCE(v_chunk.status, ''))) IN ('COMPLETE', 'FAILED', 'SKIPPED') THEN
        RETURN QUERY SELECT false, 'ALREADY_TERMINAL'::text, v_chunk.id, v_chunk.operation_id, v_chunk.phase, v_chunk.chunk_type, v_chunk.sequence_no, v_chunk.status, v_chunk.payload_json, v_chunk.result_json, v_chunk.error_json, v_chunk.unit_count, v_chunk.completed_count, v_chunk.failed_count, v_chunk.locked_by, v_chunk.lock_expires_at_utc, v_chunk.created_at_utc, v_chunk.started_at_utc, v_chunk.completed_at_utc, v_chunk.updated_at_utc;
        RETURN;
    END IF;

    IF v_status = 'PENDING' THEN
        v_completed_count := COALESCE(p_completed_count, v_chunk.completed_count, 0);
        v_failed_count := COALESCE(p_failed_count, v_chunk.failed_count, 0);
    ELSIF v_status = 'COMPLETE' THEN
        v_completed_count := COALESCE(p_completed_count, v_chunk.unit_count, 1);
        v_failed_count := COALESCE(p_failed_count, 0);
    ELSIF v_status = 'FAILED' THEN
        v_completed_count := COALESCE(p_completed_count, 0);
        v_failed_count := COALESCE(p_failed_count, v_chunk.unit_count, 1);
    ELSE
        v_completed_count := COALESCE(p_completed_count, v_chunk.unit_count, 1);
        v_failed_count := COALESCE(p_failed_count, 0);
    END IF;

    v_completed_count := LEAST(GREATEST(v_completed_count, 0), GREATEST(COALESCE(v_chunk.unit_count, 0), 0));
    v_failed_count := LEAST(GREATEST(v_failed_count, 0), GREATEST(COALESCE(v_chunk.unit_count, 0) - v_completed_count, 0));
    v_result_hash := CASE WHEN v_result_json IS NULL THEN NULL ELSE md5(v_result_json::text) END;
    v_error_summary := CASE WHEN v_error_json IS NULL THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
      'code', COALESCE(NULLIF(BTRIM(v_error_json->>'code'), ''), NULLIF(BTRIM(v_error_json->>'error_code'), '')),
      'message', LEFT(COALESCE(NULLIF(BTRIM(v_error_json->>'message'), ''), NULLIF(BTRIM(v_error_json->>'error'), ''), v_error_json::text), 1000)
    )) END;

    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET status = v_status,
        completed_count = v_completed_count,
        failed_count = v_failed_count,
        result_json = v_result_json,
        error_json = v_error_json,
        locked_by = NULL::text,
        lock_expires_at_utc = NULL::timestamptz,
        completed_at_utc = CASE WHEN v_status = 'PENDING' THEN NULL::timestamptz ELSE COALESCE(chunk_update.completed_at_utc, v_now) END,
        updated_at_utc = v_now
    WHERE chunk_update.id = v_chunk.id
    RETURNING chunk_update.* INTO v_chunk;

    IF v_status = 'PENDING' THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET phase = v_chunk.phase,
            status = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('QUEUED', 'RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 'RUNNING' ELSE operation_update.status END,
            runner_state = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('QUEUED', 'RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 'RUNNABLE' ELSE operation_update.runner_state END,
            run_after_utc = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('QUEUED', 'RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN v_now ELSE operation_update.run_after_utc END,
            heartbeat_at_utc = v_now,
            last_advanced_at_utc = v_now,
            progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
              'last_requeued_chunk_id', v_chunk.id::text,
              'last_requeued_chunk_phase', v_chunk.phase,
              'last_requeued_chunk_type', v_chunk.chunk_type,
              'last_requeued_chunk_status', v_chunk.status,
              'last_requeued_chunk_sequence_no', v_chunk.sequence_no,
              'last_requeued_chunk_completed_count', v_completed_count,
              'last_requeued_chunk_failed_count', v_failed_count,
              'last_requeued_chunk_result_hash', v_result_hash,
              'last_requeued_chunk_error_summary', v_error_summary,
              'last_advanced_at_utc', v_now::text
            )),
            updated_at_utc = v_now
        WHERE operation_update.id = v_chunk.operation_id
          AND upper(BTRIM(COALESCE(operation_update.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED');
    ELSE
        UPDATE public.banking_pay_operations AS operation_update
        SET phase = v_chunk.phase,
            status = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 'RUNNING' ELSE operation_update.status END,
            runner_state = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 'RUNNABLE' ELSE operation_update.runner_state END,
            run_after_utc = CASE WHEN upper(BTRIM(COALESCE(operation_update.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN v_now ELSE operation_update.run_after_utc END,
            heartbeat_at_utc = v_now,
            last_advanced_at_utc = v_now,
            current_chunk_index = COALESCE(operation_update.current_chunk_index, 0) + 1,
            completed_units = COALESCE(operation_update.completed_units, 0) + v_completed_count,
            failed_units = COALESCE(operation_update.failed_units, 0) + v_failed_count,
            progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
              'last_finished_chunk_id', v_chunk.id::text,
              'last_finished_chunk_phase', v_chunk.phase,
              'last_finished_chunk_type', v_chunk.chunk_type,
              'last_finished_chunk_status', v_chunk.status,
              'last_finished_chunk_sequence_no', v_chunk.sequence_no,
              'last_finished_chunk_completed_count', v_completed_count,
              'last_finished_chunk_failed_count', v_failed_count,
              'last_finished_chunk_result_hash', v_result_hash,
              'last_finished_chunk_error_summary', v_error_summary,
              'last_advanced_at_utc', v_now::text
            )),
            updated_at_utc = v_now
        WHERE operation_update.id = v_chunk.operation_id
          AND upper(BTRIM(COALESCE(operation_update.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED');
    END IF;

    RETURN QUERY SELECT true, NULL::text, v_chunk.id, v_chunk.operation_id, v_chunk.phase, v_chunk.chunk_type, v_chunk.sequence_no, v_chunk.status, v_chunk.payload_json, v_chunk.result_json, v_chunk.error_json, v_chunk.unit_count, v_chunk.completed_count, v_chunk.failed_count, v_chunk.locked_by, v_chunk.lock_expires_at_utc, v_chunk.created_at_utc, v_chunk.started_at_utc, v_chunk.completed_at_utc, v_chunk.updated_at_utc;
END;
$function$;

DROP FUNCTION IF EXISTS public.banking_pay_operation_find_active(text, uuid, uuid, uuid);

CREATE OR REPLACE FUNCTION public.banking_pay_operation_find_active(p_operation_type text DEFAULT NULL::text, p_workbench_session_id uuid DEFAULT NULL::uuid, p_pay_batch_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(operation_id uuid, operation_type text, status text, phase text, actor_user_id uuid, workbench_session_id uuid, pay_batch_id uuid, root_operation_id uuid, idempotency_key text, progress_json jsonb, total_units integer, completed_units integer, failed_units integer, current_chunk_index integer, chunk_count integer, locked_by text, lock_expires_at_utc timestamp with time zone, created_at_utc timestamp with time zone, started_at_utc timestamp with time zone, updated_at_utc timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_operation_type text := upper(NULLIF(BTRIM(COALESCE(p_operation_type, '')), ''));
BEGIN
    IF p_workbench_session_id IS NULL AND p_pay_batch_id IS NULL THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FIND_ACTIVE_SCOPE_REQUIRED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FIND_ACTIVE_SCOPE_REQUIRED')::text;
    END IF;

    IF v_operation_type IS NOT NULL
       AND v_operation_type NOT IN (
           'DRAFT_CREATE',
           'PAYMENT_EXECUTE',
           'PAYMENT_RETRY_BLOCKED_FUNDS',
           'PAYMENT_SETTLEMENT',
           'REMITTANCE_QUEUE',
           'PREVIEW_REFRESH'
       ) THEN
        RAISE EXCEPTION 'BANKING_PAY_OPERATION_FIND_ACTIVE_TYPE_UNSUPPORTED'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_FIND_ACTIVE_TYPE_UNSUPPORTED', 'operation_type', v_operation_type)::text;
    END IF;

    RETURN QUERY
    SELECT
        operation_row.id,
        operation_row.operation_type,
        operation_row.status,
        operation_row.phase,
        operation_row.actor_user_id,
        operation_row.workbench_session_id,
        operation_row.pay_batch_id,
        operation_row.root_operation_id,
        operation_row.idempotency_key,
        jsonb_strip_nulls(COALESCE(operation_row.progress_json, '{}'::jsonb) || jsonb_build_object(
            'runner_state', operation_row.runner_state,
            'run_after_utc', CASE WHEN operation_row.run_after_utc IS NULL THEN NULL ELSE operation_row.run_after_utc::text END,
            'requires_user_action', COALESCE(operation_row.requires_user_action, false),
            'resume_reason', operation_row.resume_reason,
            'heartbeat_at_utc', CASE WHEN operation_row.heartbeat_at_utc IS NULL THEN NULL ELSE operation_row.heartbeat_at_utc::text END,
            'last_advanced_at_utc', CASE WHEN operation_row.last_advanced_at_utc IS NULL THEN NULL ELSE operation_row.last_advanced_at_utc::text END,
            'attempt_count', COALESCE(operation_row.attempt_count, 0),
            'max_attempts', operation_row.max_attempts
        )),
        operation_row.total_units,
        operation_row.completed_units,
        operation_row.failed_units,
        operation_row.current_chunk_index,
        operation_row.chunk_count,
        COALESCE(operation_row.lease_owner, operation_row.locked_by),
        COALESCE(operation_row.lease_expires_at_utc, operation_row.lock_expires_at_utc),
        operation_row.created_at_utc,
        operation_row.started_at_utc,
        operation_row.updated_at_utc
    FROM public.banking_pay_operations AS operation_row
    WHERE upper(BTRIM(COALESCE(operation_row.status, ''))) IN (
            'QUEUED',
            'RUNNING',
            'WAITING',
            'RUNNABLE',
            'CONTINUING',
            'WAITING_RETRY',
            'WAITING_AUTHORISATION',
            'WAITING_AUTHORIZATION',
            'AWAITING_AUTHORISATION',
            'AWAITING_AUTHORIZATION',
            'WAITING_PROVIDER',
            'WAITING_FOR_PROVIDER',
            'AWAITING_PROVIDER',
            'WAITING_USER',
            'WAITING_USER_REVIEW',
            'REVIEW_REQUIRED'
          )
      AND (v_operation_type IS NULL OR upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = v_operation_type)
      AND NOT (
        v_operation_type = 'PAYMENT_EXECUTE'
        AND upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE'
        AND (
          lower(BTRIM(COALESCE(operation_row.input_json->>'prepare_bank_csv_export_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR upper(BTRIM(COALESCE(operation_row.input_json->>'execution_mode', ''))) = 'BANK_CSV_EXPORT_PREPARE'
          OR BTRIM(COALESCE(operation_row.input_json->>'source', '')) = 'handleBankingPayBatchExportCsv'
          OR lower(COALESCE(operation_row.idempotency_key, '')) LIKE 'bank-csv-export-prepare:%'
        )
      )
      AND (p_workbench_session_id IS NULL OR operation_row.workbench_session_id = p_workbench_session_id)
      AND (p_pay_batch_id IS NULL OR operation_row.pay_batch_id = p_pay_batch_id)
      AND (
          p_actor_user_id IS NULL
          OR operation_row.actor_user_id IS NULL
          OR operation_row.actor_user_id = p_actor_user_id
      )
    ORDER BY
      CASE upper(BTRIM(COALESCE(operation_row.status, '')))
        WHEN 'RUNNING' THEN 0
        WHEN 'WAITING' THEN 1
        WHEN 'RUNNABLE' THEN 2
        WHEN 'QUEUED' THEN 3
        WHEN 'CONTINUING' THEN 4
        WHEN 'WAITING_RETRY' THEN 5
        WHEN 'WAITING_AUTHORISATION' THEN 6
        WHEN 'WAITING_AUTHORIZATION' THEN 6
        WHEN 'AWAITING_AUTHORISATION' THEN 6
        WHEN 'AWAITING_AUTHORIZATION' THEN 6
        WHEN 'WAITING_PROVIDER' THEN 7
        WHEN 'WAITING_FOR_PROVIDER' THEN 7
        WHEN 'AWAITING_PROVIDER' THEN 7
        WHEN 'WAITING_USER' THEN 8
        WHEN 'WAITING_USER_REVIEW' THEN 8
        WHEN 'REVIEW_REQUIRED' THEN 9
        ELSE 10
      END,
      operation_row.updated_at_utc DESC NULLS LAST,
      operation_row.created_at_utc DESC NULLS LAST,
      operation_row.id DESC
    LIMIT 1;
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_pay_operation_seed_chunks(
  p_operation_id uuid,
  p_phase text,
  p_chunk_type text,
  p_chunk_size integer,
  p_units_json jsonb
)
RETURNS TABLE (
  total_units integer,
  chunk_count integer,
  existing_chunk_count integer,
  new_chunk_count integer
)
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_phase text := nullif(btrim(coalesce(p_phase, '')), '');
  v_chunk_type text := upper(nullif(btrim(coalesce(p_chunk_type, '')), ''));
  v_chunk_size integer := LEAST(GREATEST(coalesce(p_chunk_size, 100), 1), 100);
  v_units_json jsonb := coalesce(p_units_json, '[]'::jsonb);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_type text := NULL::text;
  v_total_units integer := 0;
  v_chunk_count integer := 0;
  v_existing_chunk_count integer := 0;
  v_new_chunk_count integer := 0;
  v_repaired_chunk_count integer := 0;
  v_mismatch_count integer := 0;
  v_legacy_mode boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks requires p_operation_id';
  END IF;

  IF v_phase IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks requires p_phase';
  END IF;

  IF v_chunk_type IS NULL THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks requires p_chunk_type';
  END IF;

  IF v_chunk_type NOT IN (
    'CANDIDATE_SCOPE',
    'TSFIN',
    'PAYEE_READINESS',
    'TRANSFER_GROUP',
    'TRANSFER_SCOPE_ITEM_SEED',
    'TRANSFER_SCOPE_ROLLUP',
    'TRANSFER_SUBMIT',
    'RAIL_UPDATE',
    'SETTLEMENT',
    'REMITTANCE',
    'PAYOUT_NOTICE',
    'PREVIEW_PAGE',
    'FRESHNESS_VALIDATE'
  ) THEN
    RAISE EXCEPTION 'Unsupported banking pay operation chunk_type: %', v_chunk_type;
  END IF;

  IF p_units_json IS NOT NULL AND jsonb_typeof(p_units_json) <> 'array' THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks requires p_units_json to be a JSON array when supplied';
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks operation not found: %', p_operation_id;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.status, ''))) IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'banking_pay_operation_seed_chunks cannot seed chunks for terminal operation % with status %', p_operation_id, v_operation_row.status;
  END IF;

  v_operation_type := upper(btrim(coalesce(v_operation_row.operation_type, '')));
  v_legacy_mode := p_units_json IS NOT NULL
    AND jsonb_array_length(v_units_json) > 0
    AND NOT (
      (v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE')
      OR (v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE'))
    );

  IF v_legacy_mode AND jsonb_array_length(v_units_json) > 25 THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_SEED_CHUNKS_LEGACY_UNITS_TOO_LARGE'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_SEED_CHUNKS_LEGACY_UNITS_TOO_LARGE', 'operation_id', p_operation_id::text, 'chunk_type', v_chunk_type, 'unit_count', jsonb_array_length(v_units_json), 'limit', 25)::text;
  END IF;

  IF v_legacy_mode
     AND upper(btrim(coalesce(v_operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_SEED_CHUNKS_LEGACY_MODE_DISALLOWED_FOR_EXECUTION'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_SEED_CHUNKS_LEGACY_MODE_DISALLOWED_FOR_EXECUTION', 'operation_id', p_operation_id::text, 'chunk_type', v_chunk_type)::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_operation_seed_units;
  CREATE TEMPORARY TABLE pg_temp.tmp_operation_seed_units (
    unit_ordinal bigint NOT NULL,
    candidate_scope_id uuid NULL,
    transfer_scope_id uuid NULL,
    remittance_scope_id uuid NULL,
    scope_unit_id uuid NULL,
    pay_bank_transfer_id uuid NULL,
    unit_key text NULL,
    unit_payload_json jsonb NOT NULL
  ) ON COMMIT DROP;

  IF v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN
    IF p_units_json IS NULL OR jsonb_array_length(v_units_json) = 0 THEN
      RAISE EXCEPTION 'DRAFT_CREATE_CHUNK_UNITS_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'DRAFT_CREATE_CHUNK_UNITS_REQUIRED', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type)::text;
    END IF;

    IF jsonb_array_length(v_units_json) > 100 THEN
      RAISE EXCEPTION 'DRAFT_CREATE_CHUNK_UNITS_TOO_LARGE'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'DRAFT_CREATE_CHUNK_UNITS_TOO_LARGE', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type, 'unit_count', jsonb_array_length(v_units_json), 'limit', 100)::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_units_json) AS supplied_candidate_scope(candidate_scope_id_text)
      WHERE BTRIM(supplied_candidate_scope.candidate_scope_id_text) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) THEN
      RAISE EXCEPTION 'DRAFT_CREATE_CHUNK_UNITS_MUST_BE_UUIDS'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'DRAFT_CREATE_CHUNK_UNITS_MUST_BE_UUIDS', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type)::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_units_json) AS supplied_candidate_scope(candidate_scope_id_text)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_scope AS candidate_scope_row
        WHERE candidate_scope_row.operation_id = p_operation_id
          AND candidate_scope_row.id = BTRIM(supplied_candidate_scope.candidate_scope_id_text)::uuid
          AND upper(btrim(coalesce(candidate_scope_row.status, ''))) NOT IN ('FAILED', 'CANCELLED', 'CANCELED', 'ERROR')
      )
    ) THEN
      RAISE EXCEPTION 'DRAFT_CREATE_CHUNK_SCOPE_ID_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'DRAFT_CREATE_CHUNK_SCOPE_ID_MISMATCH', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type)::text;
    END IF;

    INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, candidate_scope_id, unit_key, unit_payload_json)
    SELECT supplied_scope.ordinality::bigint,
           candidate_scope_row.id,
           candidate_scope_row.candidate_id::text || ':' || candidate_scope_row.pay_channel,
           jsonb_strip_nulls(jsonb_build_object(
             'candidate_scope_id', candidate_scope_row.id::text,
             'pay_batch_id', CASE WHEN candidate_scope_row.pay_batch_id IS NULL THEN NULL ELSE candidate_scope_row.pay_batch_id::text END,
             'candidate_id', candidate_scope_row.candidate_id::text,
             'pay_channel', candidate_scope_row.pay_channel,
             'chunk_sequence', candidate_scope_row.chunk_sequence,
             'status', candidate_scope_row.status
           ))
    FROM jsonb_array_elements_text(v_units_json) WITH ORDINALITY AS supplied_scope(candidate_scope_id_text, ordinality)
    JOIN public.banking_pay_operation_candidate_scope AS candidate_scope_row
      ON candidate_scope_row.operation_id = p_operation_id
     AND candidate_scope_row.id = BTRIM(supplied_scope.candidate_scope_id_text)::uuid
    ORDER BY supplied_scope.ordinality;
  ELSIF v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN
    IF p_units_json IS NOT NULL AND jsonb_array_length(v_units_json) > 0 THEN
      IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(v_units_json) AS supplied_remittance_scope(remittance_scope_id_text)
        WHERE BTRIM(supplied_remittance_scope.remittance_scope_id_text) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) THEN
        RAISE EXCEPTION 'REMITTANCE_CHUNK_UNITS_MUST_BE_UUIDS'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'REMITTANCE_CHUNK_UNITS_MUST_BE_UUIDS', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type)::text;
      END IF;

      IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(v_units_json) AS supplied_remittance_scope(remittance_scope_id_text)
        WHERE NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_remittance_scope AS remittance_scope_row
          WHERE remittance_scope_row.operation_id = p_operation_id
            AND remittance_scope_row.id = BTRIM(supplied_remittance_scope.remittance_scope_id_text)::uuid
            AND upper(btrim(coalesce(remittance_scope_row.status, ''))) IN ('PENDING', 'FAILED')
            AND (
              (
                v_chunk_type = 'PAYOUT_NOTICE'
                AND (
                  upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%PAYOUT%'
                  OR upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%NOTICE%'
                )
              )
              OR (
                v_chunk_type = 'REMITTANCE'
                AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%PAYOUT%'
                AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%NOTICE%'
              )
            )
        )
      ) THEN
        RAISE EXCEPTION 'REMITTANCE_CHUNK_SCOPE_ID_MISMATCH'
          USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'REMITTANCE_CHUNK_SCOPE_ID_MISMATCH', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type)::text;
      END IF;

      INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, remittance_scope_id, unit_key, unit_payload_json)
      SELECT supplied_remittance_scope.ordinality::bigint,
             remittance_scope_row.id,
             remittance_scope_row.deterministic_outbox_key,
             jsonb_strip_nulls(jsonb_build_object(
               'remittance_scope_id', remittance_scope_row.id::text,
               'pay_batch_id', remittance_scope_row.pay_batch_id::text,
               'pay_batch_candidate_id', CASE WHEN remittance_scope_row.pay_batch_candidate_id IS NULL THEN NULL ELSE remittance_scope_row.pay_batch_candidate_id::text END,
               'candidate_id', CASE WHEN remittance_scope_row.candidate_id IS NULL THEN NULL ELSE remittance_scope_row.candidate_id::text END,
               'recipient_kind', remittance_scope_row.recipient_kind,
               'recipient_id', CASE WHEN remittance_scope_row.recipient_id IS NULL THEN NULL ELSE remittance_scope_row.recipient_id::text END,
               'remittance_type', remittance_scope_row.remittance_type,
               'status', remittance_scope_row.status,
               'deterministic_outbox_key', remittance_scope_row.deterministic_outbox_key,
               'outbox_id', CASE WHEN remittance_scope_row.outbox_id IS NULL THEN NULL ELSE remittance_scope_row.outbox_id::text END
             ))
      FROM jsonb_array_elements_text(v_units_json) WITH ORDINALITY AS supplied_remittance_scope(remittance_scope_id_text, ordinality)
      JOIN public.banking_pay_operation_remittance_scope AS remittance_scope_row
        ON remittance_scope_row.operation_id = p_operation_id
       AND remittance_scope_row.id = BTRIM(supplied_remittance_scope.remittance_scope_id_text)::uuid
      WHERE upper(btrim(coalesce(remittance_scope_row.status, ''))) IN ('PENDING', 'FAILED')
        AND (
          (
            v_chunk_type = 'PAYOUT_NOTICE'
            AND (
              upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%PAYOUT%'
              OR upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%NOTICE%'
            )
          )
          OR (
            v_chunk_type = 'REMITTANCE'
            AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%PAYOUT%'
            AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%NOTICE%'
          )
        )
      ORDER BY supplied_remittance_scope.ordinality;
    ELSE
      INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, remittance_scope_id, unit_key, unit_payload_json)
      SELECT row_number() OVER (ORDER BY remittance_scope_row.created_at_utc NULLS FIRST, remittance_scope_row.id)::bigint AS unit_ordinal,
             remittance_scope_row.id,
             remittance_scope_row.deterministic_outbox_key,
             jsonb_strip_nulls(jsonb_build_object(
               'remittance_scope_id', remittance_scope_row.id::text,
               'pay_batch_id', remittance_scope_row.pay_batch_id::text,
               'pay_batch_candidate_id', CASE WHEN remittance_scope_row.pay_batch_candidate_id IS NULL THEN NULL ELSE remittance_scope_row.pay_batch_candidate_id::text END,
               'candidate_id', CASE WHEN remittance_scope_row.candidate_id IS NULL THEN NULL ELSE remittance_scope_row.candidate_id::text END,
               'recipient_kind', remittance_scope_row.recipient_kind,
               'recipient_id', CASE WHEN remittance_scope_row.recipient_id IS NULL THEN NULL ELSE remittance_scope_row.recipient_id::text END,
               'remittance_type', remittance_scope_row.remittance_type,
               'status', remittance_scope_row.status,
               'deterministic_outbox_key', remittance_scope_row.deterministic_outbox_key,
               'outbox_id', CASE WHEN remittance_scope_row.outbox_id IS NULL THEN NULL ELSE remittance_scope_row.outbox_id::text END
             ))
      FROM public.banking_pay_operation_remittance_scope AS remittance_scope_row
      WHERE remittance_scope_row.operation_id = p_operation_id
        AND upper(btrim(coalesce(remittance_scope_row.status, ''))) IN ('PENDING', 'FAILED')
        AND (
          (
            v_chunk_type = 'PAYOUT_NOTICE'
            AND (
              upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%PAYOUT%'
              OR upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) LIKE '%NOTICE%'
            )
          )
          OR (
            v_chunk_type = 'REMITTANCE'
            AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%PAYOUT%'
            AND upper(btrim(coalesce(remittance_scope_row.remittance_type, ''))) NOT LIKE '%NOTICE%'
          )
        )
      ORDER BY remittance_scope_row.created_at_utc NULLS FIRST, remittance_scope_row.id
      LIMIT 100;
    END IF;

  ELSIF v_legacy_mode THEN
    INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, unit_payload_json)
    SELECT unit_values.ordinality::bigint,
           jsonb_strip_nulls(jsonb_build_object('legacy_unit', unit_values.value, 'diagnostic_tiny_compat', true))
    FROM jsonb_array_elements(v_units_json) WITH ORDINALITY AS unit_values(value, ordinality)
    ORDER BY unit_values.ordinality;
  ELSIF v_chunk_type = 'FRESHNESS_VALIDATE' THEN
    INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, scope_unit_id, unit_key, unit_payload_json)
    SELECT scope_unit.unit_ordinal,
           scope_unit.id,
           scope_unit.unit_key,
           jsonb_build_object('scope_unit_id', scope_unit.id::text, 'unit_key', scope_unit.unit_key)
    FROM public.banking_pay_operation_scope_units AS scope_unit
    WHERE scope_unit.operation_id = p_operation_id
      AND scope_unit.phase = 'FRESHNESS'
      AND upper(btrim(coalesce(scope_unit.status, ''))) IN ('PENDING', 'QUEUED', 'READY', 'ERROR')
    ORDER BY scope_unit.unit_ordinal, scope_unit.id
    LIMIT 100;
  ELSIF v_chunk_type IN ('TRANSFER_GROUP', 'TRANSFER_SCOPE_ITEM_SEED', 'TRANSFER_SCOPE_ROLLUP') THEN
    INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, transfer_scope_id, pay_bank_transfer_id, unit_key, unit_payload_json)
    SELECT row_number() OVER (ORDER BY scope_row.created_at_utc NULLS FIRST, scope_row.id)::bigint AS unit_ordinal,
           scope_row.id,
           scope_row.pay_bank_transfer_id,
           scope_row.transfer_group_key,
           jsonb_strip_nulls(jsonb_build_object(
             'transfer_scope_id', scope_row.id::text,
             'pay_batch_id', scope_row.pay_batch_id::text,
             'pay_channel', scope_row.pay_channel,
             'transfer_group_key', scope_row.transfer_group_key,
             'pay_bank_transfer_id', CASE WHEN scope_row.pay_bank_transfer_id IS NULL THEN NULL ELSE scope_row.pay_bank_transfer_id::text END
           ))
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND (
        (v_chunk_type = 'TRANSFER_GROUP' AND upper(btrim(coalesce(scope_row.status, ''))) IN ('PENDING', 'FAILED'))
        OR (v_chunk_type = 'TRANSFER_SCOPE_ITEM_SEED' AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY', 'REVIEW_REQUIRED'))
        OR (v_chunk_type = 'TRANSFER_SCOPE_ROLLUP' AND EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope_items AS scope_item
          WHERE scope_item.operation_id = p_operation_id
            AND scope_item.transfer_scope_id = scope_row.id
            AND upper(btrim(coalesce(scope_item.rollup_status, ''))) IN ('PENDING', 'ERROR')
        ))
      )
    ORDER BY scope_row.created_at_utc NULLS FIRST, scope_row.id
    LIMIT 100;
  ELSIF v_chunk_type = 'TRANSFER_SUBMIT' THEN
    INSERT INTO pg_temp.tmp_operation_seed_units (unit_ordinal, transfer_scope_id, pay_bank_transfer_id, unit_key, unit_payload_json)
    SELECT row_number() OVER (ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id)::bigint AS unit_ordinal,
           scope_row.id,
           scope_row.pay_bank_transfer_id,
           scope_row.transfer_group_key,
           jsonb_strip_nulls(jsonb_build_object(
             'transfer_scope_id', scope_row.id::text,
             'pay_bank_transfer_id', CASE WHEN scope_row.pay_bank_transfer_id IS NULL THEN NULL ELSE scope_row.pay_bank_transfer_id::text END,
             'provider_idempotency_key', scope_row.provider_idempotency_key,
             'provider_request_id', scope_row.provider_request_id
           ))
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL
    ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id
    LIMIT 100;
  ELSE
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  SELECT count(*)::integer
  INTO v_total_units
  FROM pg_temp.tmp_operation_seed_units AS seed_unit;

  IF v_total_units <= 0 THEN
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  v_chunk_count := ((v_total_units + v_chunk_size - 1) / v_chunk_size)::integer;

  WITH expected_chunks AS (
    SELECT (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer AS sequence_no,
           jsonb_strip_nulls(jsonb_build_object(
             'row_backed', NOT v_legacy_mode,
             'legacy_tiny_compat', v_legacy_mode,
             'source_table', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN 'banking_pay_operation_candidate_scope'
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN 'banking_pay_operation_remittance_scope'
               WHEN v_chunk_type = 'FRESHNESS_VALIDATE' THEN 'banking_pay_operation_scope_units'
               WHEN v_chunk_type IN ('TRANSFER_GROUP', 'TRANSFER_SCOPE_ITEM_SEED', 'TRANSFER_SCOPE_ROLLUP', 'TRANSFER_SUBMIT') THEN 'banking_pay_operation_transfer_scope'
               ELSE 'diagnostic_legacy_units'
             END,
             'unit_count', count(*)::integer,
             'unit_ordinal_min', min(seed_unit.unit_ordinal),
             'unit_ordinal_max', max(seed_unit.unit_ordinal),
             'units', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'candidate_scope_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'pay_batch_ids', coalesce(jsonb_agg(DISTINCT to_jsonb((seed_unit.unit_payload_json->>'pay_batch_id'))) FILTER (WHERE NULLIF(seed_unit.unit_payload_json->>'pay_batch_id', '') IS NOT NULL), '[]'::jsonb),
             'transfer_scope_ids', coalesce(jsonb_agg(to_jsonb(seed_unit.transfer_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.transfer_scope_id IS NOT NULL), '[]'::jsonb),
             'remittance_scope_ids', CASE
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'scope_unit_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE coalesce(jsonb_agg(to_jsonb(seed_unit.scope_unit_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.scope_unit_id IS NOT NULL), '[]'::jsonb)
             END,
             'unit_keys_sample', coalesce(jsonb_agg(to_jsonb(seed_unit.unit_key) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.unit_key IS NOT NULL), '[]'::jsonb)
           )) AS payload_json,
           count(*)::integer AS unit_count
    FROM pg_temp.tmp_operation_seed_units AS seed_unit
    GROUP BY (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer
  ), repaired_chunks AS (
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET status = 'PENDING',
        payload_json = expected_chunks.payload_json,
        result_json = NULL::jsonb,
        error_json = NULL::jsonb,
        unit_count = expected_chunks.unit_count,
        completed_count = 0,
        failed_count = 0,
        locked_by = NULL,
        lock_expires_at_utc = NULL,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        updated_at_utc = v_now
    FROM expected_chunks
    WHERE chunk_update.operation_id = p_operation_id
      AND chunk_update.phase = v_phase
      AND chunk_update.chunk_type = v_chunk_type
      AND chunk_update.sequence_no = expected_chunks.sequence_no
      AND v_operation_type = 'REMITTANCE_QUEUE'
      AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE')
      AND chunk_update.status IN ('PENDING', 'FAILED')
      AND (
        chunk_update.unit_count <> expected_chunks.unit_count
        OR chunk_update.payload_json IS DISTINCT FROM expected_chunks.payload_json
      )
      AND (
        chunk_update.payload_json->>'source_table' = 'diagnostic_legacy_units'
        OR lower(coalesce(chunk_update.payload_json->>'row_backed', 'false')) <> 'true'
        OR lower(coalesce(chunk_update.payload_json->>'legacy_tiny_compat', 'false')) = 'true'
      )
    RETURNING 1
  )
  SELECT count(*)::integer
  INTO v_repaired_chunk_count
  FROM repaired_chunks;

  WITH expected_chunks AS (
    SELECT (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer AS sequence_no,
           jsonb_strip_nulls(jsonb_build_object(
             'row_backed', NOT v_legacy_mode,
             'legacy_tiny_compat', v_legacy_mode,
             'source_table', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN 'banking_pay_operation_candidate_scope'
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN 'banking_pay_operation_remittance_scope'
               WHEN v_chunk_type = 'FRESHNESS_VALIDATE' THEN 'banking_pay_operation_scope_units'
               WHEN v_chunk_type IN ('TRANSFER_GROUP', 'TRANSFER_SCOPE_ITEM_SEED', 'TRANSFER_SCOPE_ROLLUP', 'TRANSFER_SUBMIT') THEN 'banking_pay_operation_transfer_scope'
               ELSE 'diagnostic_legacy_units'
             END,
             'unit_count', count(*)::integer,
             'unit_ordinal_min', min(seed_unit.unit_ordinal),
             'unit_ordinal_max', max(seed_unit.unit_ordinal),
             'units', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'candidate_scope_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'pay_batch_ids', coalesce(jsonb_agg(DISTINCT to_jsonb((seed_unit.unit_payload_json->>'pay_batch_id'))) FILTER (WHERE NULLIF(seed_unit.unit_payload_json->>'pay_batch_id', '') IS NOT NULL), '[]'::jsonb),
             'transfer_scope_ids', coalesce(jsonb_agg(to_jsonb(seed_unit.transfer_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.transfer_scope_id IS NOT NULL), '[]'::jsonb),
             'remittance_scope_ids', CASE
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'scope_unit_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE coalesce(jsonb_agg(to_jsonb(seed_unit.scope_unit_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.scope_unit_id IS NOT NULL), '[]'::jsonb)
             END,
             'unit_keys_sample', coalesce(jsonb_agg(to_jsonb(seed_unit.unit_key) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.unit_key IS NOT NULL), '[]'::jsonb)
           )) AS payload_json,
           count(*)::integer AS unit_count
    FROM pg_temp.tmp_operation_seed_units AS seed_unit
    GROUP BY (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer
  )
  SELECT count(*)::integer
  INTO v_mismatch_count
  FROM expected_chunks AS expected_chunk
  JOIN public.banking_pay_operation_chunks AS existing_chunk
    ON existing_chunk.operation_id = p_operation_id
   AND existing_chunk.phase = v_phase
   AND existing_chunk.chunk_type = v_chunk_type
   AND existing_chunk.sequence_no = expected_chunk.sequence_no
  WHERE existing_chunk.unit_count <> expected_chunk.unit_count
     OR existing_chunk.payload_json IS DISTINCT FROM expected_chunk.payload_json;

  IF coalesce(v_mismatch_count, 0) > 0 THEN
    RAISE EXCEPTION 'CHUNK_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'CHUNK_SCOPE_MISMATCH', 'operation_id', p_operation_id::text, 'phase', v_phase, 'chunk_type', v_chunk_type, 'mismatched_chunk_count', v_mismatch_count)::text;
  END IF;

  WITH expected_chunks AS (
    SELECT (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer AS sequence_no,
           jsonb_strip_nulls(jsonb_build_object(
             'row_backed', NOT v_legacy_mode,
             'legacy_tiny_compat', v_legacy_mode,
             'source_table', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN 'banking_pay_operation_candidate_scope'
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN 'banking_pay_operation_remittance_scope'
               WHEN v_chunk_type = 'FRESHNESS_VALIDATE' THEN 'banking_pay_operation_scope_units'
               WHEN v_chunk_type IN ('TRANSFER_GROUP', 'TRANSFER_SCOPE_ITEM_SEED', 'TRANSFER_SCOPE_ROLLUP', 'TRANSFER_SUBMIT') THEN 'banking_pay_operation_transfer_scope'
               ELSE 'diagnostic_legacy_units'
             END,
             'unit_count', count(*)::integer,
             'unit_ordinal_min', min(seed_unit.unit_ordinal),
             'unit_ordinal_max', max(seed_unit.unit_ordinal),
             'units', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'candidate_scope_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'pay_batch_ids', coalesce(jsonb_agg(DISTINCT to_jsonb((seed_unit.unit_payload_json->>'pay_batch_id'))) FILTER (WHERE NULLIF(seed_unit.unit_payload_json->>'pay_batch_id', '') IS NOT NULL), '[]'::jsonb),
             'transfer_scope_ids', coalesce(jsonb_agg(to_jsonb(seed_unit.transfer_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.transfer_scope_id IS NOT NULL), '[]'::jsonb),
             'remittance_scope_ids', CASE
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE '[]'::jsonb
             END,
             'scope_unit_ids', CASE
               WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN coalesce(jsonb_agg(to_jsonb(seed_unit.candidate_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.candidate_scope_id IS NOT NULL), '[]'::jsonb)
               WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN coalesce(jsonb_agg(to_jsonb(seed_unit.remittance_scope_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.remittance_scope_id IS NOT NULL), '[]'::jsonb)
               ELSE coalesce(jsonb_agg(to_jsonb(seed_unit.scope_unit_id::text) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.scope_unit_id IS NOT NULL), '[]'::jsonb)
             END,
             'unit_keys_sample', coalesce(jsonb_agg(to_jsonb(seed_unit.unit_key) ORDER BY seed_unit.unit_ordinal) FILTER (WHERE seed_unit.unit_key IS NOT NULL), '[]'::jsonb)
           )) AS payload_json,
           count(*)::integer AS unit_count
    FROM pg_temp.tmp_operation_seed_units AS seed_unit
    GROUP BY (((seed_unit.unit_ordinal - 1) / v_chunk_size) + 1)::integer
  ), inserted_chunks AS (
    INSERT INTO public.banking_pay_operation_chunks (
      operation_id,
      phase,
      chunk_type,
      sequence_no,
      status,
      payload_json,
      result_json,
      error_json,
      unit_count,
      completed_count,
      failed_count,
      created_at_utc,
      updated_at_utc
    )
    SELECT p_operation_id,
           v_phase,
           v_chunk_type,
           expected_chunks.sequence_no,
           'PENDING',
           expected_chunks.payload_json,
           NULL::jsonb,
           NULL::jsonb,
           expected_chunks.unit_count,
           0,
           0,
           v_now,
           v_now
    FROM expected_chunks
    ORDER BY expected_chunks.sequence_no
    ON CONFLICT (operation_id, phase, chunk_type, sequence_no) DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::integer
  INTO v_new_chunk_count
  FROM inserted_chunks;

  v_existing_chunk_count := v_chunk_count - coalesce(v_new_chunk_count, 0);

  UPDATE public.banking_pay_operations AS operation_update
  SET chunk_count = GREATEST(COALESCE(operation_update.chunk_count, 0), v_chunk_count),
      total_units = GREATEST(COALESCE(operation_update.total_units, 0), v_total_units),
      progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'last_chunk_seed', jsonb_build_object(
          'phase', v_phase,
          'chunk_type', v_chunk_type,
          'seeded_at_utc', v_now::text,
          'total_units', v_total_units,
          'chunk_count', v_chunk_count,
          'new_chunk_count', COALESCE(v_new_chunk_count, 0),
          'repaired_chunk_count', COALESCE(v_repaired_chunk_count, 0),
          'row_backed', NOT v_legacy_mode,
          'source_table', CASE
            WHEN v_operation_type = 'DRAFT_CREATE' AND v_chunk_type = 'CANDIDATE_SCOPE' THEN 'banking_pay_operation_candidate_scope'
            WHEN v_operation_type = 'REMITTANCE_QUEUE' AND v_chunk_type IN ('REMITTANCE', 'PAYOUT_NOTICE') THEN 'banking_pay_operation_remittance_scope'
            WHEN v_chunk_type = 'FRESHNESS_VALIDATE' THEN 'banking_pay_operation_scope_units'
            WHEN v_chunk_type IN ('TRANSFER_GROUP', 'TRANSFER_SCOPE_ITEM_SEED', 'TRANSFER_SCOPE_ROLLUP', 'TRANSFER_SUBMIT') THEN 'banking_pay_operation_transfer_scope'
            ELSE 'diagnostic_legacy_units'
          END
        )
      )),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN QUERY SELECT v_total_units, v_chunk_count, v_existing_chunk_count, coalesce(v_new_chunk_count, 0);
END;
$function$;




create or replace function public.pay_batch_stage_operation_candidate_chunk_context(
    p_operation_id uuid,
    p_pay_batch_id uuid,
    p_candidate_scope_ids jsonb,
    p_actor_user_id uuid
)
returns table (
    candidate_count integer,
    selected_row_count integer,
    timesheet_snapshot_count integer,
    finance_component_count integer
)
language plpgsql
security definer
volatile
set search_path = public, pg_temp
as $$
declare
    v_operation public.banking_pay_operations%rowtype;
    v_pay_batch public.pay_batches%rowtype;
    v_scope_ids jsonb;
    v_candidate_count integer;
    v_selected_row_count integer;
    v_timesheet_snapshot_count integer;
    v_finance_component_count integer;
    v_settings_bank_system text;
    v_settings_external_paye_system text;
    v_settings_rail_provider text;
    v_settings_rail_env text;
    v_need_name_check boolean;
    v_requires_payee_map boolean;
    v_vat_rate_pct numeric;
    v_erni_pct numeric;
    v_week_start date;
    v_scope text;
begin
    v_scope_ids := coalesce(p_candidate_scope_ids, '[]'::jsonb);

    if p_actor_user_id is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires p_actor_user_id';
    end if;

    perform 1
    from public.tms_users as actor_user
    where actor_user.id = p_actor_user_id;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context tms_users row not found: %', p_actor_user_id;
    end if;

    if jsonb_typeof(v_scope_ids) <> 'array' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires p_candidate_scope_ids to be a JSON array';
    end if;

    if jsonb_array_length(v_scope_ids) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires at least one candidate scope id';
    end if;

    if exists (
        select 1
        from jsonb_array_elements(v_scope_ids) as supplied_scope(scope_value)
        where not ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    ) then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires candidate scope ids to be UUID strings';
    end if;

    select operation_row.*
    into v_operation
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
    for update;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context operation not found: %', p_operation_id;
    end if;

    if v_operation.operation_type <> 'DRAFT_CREATE' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
    end if;

    if v_operation.status in ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context cannot stage terminal operation % with status %', p_operation_id, v_operation.status;
    end if;

    if v_operation.actor_user_id is not null and v_operation.actor_user_id <> p_actor_user_id then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context operation % belongs to a different actor', p_operation_id;
    end if;

    select batch_row.*
    into v_pay_batch
    from public.pay_batches as batch_row
    where batch_row.id = p_pay_batch_id
    for update;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch not found: %', p_pay_batch_id;
    end if;

    if v_pay_batch.status <> 'DRAFT' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch % is not DRAFT: %', p_pay_batch_id, v_pay_batch.status;
    end if;

    if v_pay_batch.source_workbench_session_id is not null
       and v_operation.workbench_session_id is not null
       and v_pay_batch.source_workbench_session_id <> v_operation.workbench_session_id then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch % belongs to a different workbench session', p_pay_batch_id;
    end if;

    drop table if exists pg_temp.tmp_pay_build_operation_candidate_scope;
    create temporary table pg_temp.tmp_pay_build_operation_candidate_scope as
    select scope_row.*
    from public.banking_pay_operation_candidate_scope as scope_row
    where scope_row.operation_id = p_operation_id
      and scope_row.pay_batch_id = p_pay_batch_id
      and scope_row.id in (
          select (supplied_scope.scope_value #>> '{}')::uuid
          from jsonb_array_elements(v_scope_ids) as supplied_scope(scope_value)
      )
    order by scope_row.chunk_sequence nulls last, scope_row.pay_channel, scope_row.candidate_id;

    select count(*)::integer
    into v_candidate_count
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope;

    if coalesce(v_candidate_count, 0) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context found no candidate scope rows for operation %, batch %', p_operation_id, p_pay_batch_id;
    end if;

    if coalesce(v_candidate_count, 0) <> jsonb_array_length(v_scope_ids) then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context one or more candidate scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    end if;

    select upper(btrim(coalesce(staged_scope.pay_channel, '')))
    into v_scope
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
    where upper(btrim(coalesce(staged_scope.pay_channel, ''))) in ('PAYE', 'UMBRELLA')
    group by upper(btrim(coalesce(staged_scope.pay_channel, '')))
    order by upper(btrim(coalesce(staged_scope.pay_channel, '')))
    limit 1;

    if v_scope is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context cannot determine pay channel scope for operation %', p_operation_id;
    end if;

    if (
        select count(*)::integer
        from (
            select distinct upper(btrim(coalesce(staged_scope.pay_channel, ''))) as pay_channel_scope
            from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
            where upper(btrim(coalesce(staged_scope.pay_channel, ''))) in ('PAYE', 'UMBRELLA')
        ) as pay_channel_scope_rows
    ) <> 1 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context candidate scope chunk must contain exactly one pay channel scope';
    end if;

    v_week_start := public._pay_week_start_monday(v_pay_batch.pay_date);

    select coalesce(nullif(v_pay_batch.banking_system_snapshot, ''), settings_row.banking_system),
           coalesce(nullif(v_pay_batch.external_paye_system_snapshot, ''), settings_row.external_paye_system),
           coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default),
           coalesce(nullif(v_pay_batch.rail_env_snapshot, ''), settings_row.rail_env_default),
           (coalesce(settings_row.rail_supports_name_check, false) = true and upper(btrim(coalesce(coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default), ''))) <> 'CSV') as need_name_check,
           (upper(btrim(coalesce(coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default), ''))) <> 'CSV') as requires_payee_map
    into v_settings_bank_system,
         v_settings_external_paye_system,
         v_settings_rail_provider,
         v_settings_rail_env,
         v_need_name_check,
         v_requires_payee_map
    from public.settings_defaults as settings_row
    order by settings_row.id asc
    limit 1;

    if v_settings_bank_system is null or v_settings_external_paye_system is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context settings_defaults missing banking_system/external_paye_system';
    end if;

    if v_settings_rail_provider is null or v_settings_rail_env is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context settings_defaults missing rail provider/environment';
    end if;

    select finance_window.vat_rate_pct,
           finance_window.erni_pct
    into v_vat_rate_pct,
         v_erni_pct
    from public.settings_finance_windows as finance_window
    where v_pay_batch.pay_date >= finance_window.date_from
      and v_pay_batch.pay_date <= coalesce(finance_window.date_to, 'infinity'::date)
    order by finance_window.date_from desc
    limit 1;

    if v_vat_rate_pct is null or v_erni_pct is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context no matching finance window for pay date %', v_pay_batch.pay_date;
    end if;

    create temporary table if not exists pg_temp.tmp_pay_build_settings_context (
        banking_system text,
        external_paye_system text,
        rail_provider_default text,
        rail_env_default text,
        need_name_check boolean,
        requires_payee_map boolean,
        vat_rate_pct numeric,
        erni_pct numeric,
        pay_week_start date
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_settings_context;

    insert into pg_temp.tmp_pay_build_settings_context (
        banking_system,
        external_paye_system,
        rail_provider_default,
        rail_env_default,
        need_name_check,
        requires_payee_map,
        vat_rate_pct,
        erni_pct,
        pay_week_start
    ) values (
        v_settings_bank_system,
        v_settings_external_paye_system,
        v_settings_rail_provider,
        v_settings_rail_env,
        v_need_name_check,
        v_requires_payee_map,
        v_vat_rate_pct,
        v_erni_pct,
        v_week_start
    );

    create temporary table if not exists pg_temp.tmp_pay_build_preview_candidates (
        cand jsonb not null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_preview_candidates;

    insert into pg_temp.tmp_pay_build_preview_candidates(cand)
    select candidate_json.cand
    from (
        select staged_scope.effective_paye_candidate_json as cand
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        where jsonb_typeof(staged_scope.effective_paye_candidate_json) = 'object'
          and nullif(btrim(coalesce(staged_scope.effective_paye_candidate_json->>'candidate_id', '')), '') is not null
        union all
        select staged_scope.effective_non_paye_payee_json as cand
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        where jsonb_typeof(staged_scope.effective_non_paye_payee_json) = 'object'
          and nullif(btrim(coalesce(staged_scope.effective_non_paye_payee_json->>'candidate_id', '')), '') is not null
    ) as candidate_json;

    create temporary table if not exists pg_temp.tmp_pay_build_selected_preview_rows (
        preview_row_id text primary key,
        candidate_id uuid not null,
        finance_case_id uuid null,
        timesheet_id uuid null,
        client_id uuid null,
        line_type text null,
        case_type text null,
        pay_channel text null,
        paye_treatment text null,
        routing_kind text null,
        destination_label text null,
        taxability text null,
        beneficiary_name text null,
        masked_bank_account text null,
        bank_details_hash text null,
        item_direction text null,
        item_type_label text null,
        source_ref text null,
        preview_amount_ex_vat numeric(12,2) null,
        draftable boolean not null,
        snooze_allowed boolean not null,
        is_candidate_directed_oneoff_payout boolean not null,
        appears_on_umbrella_remittance boolean not null,
        generates_candidate_payment_advice boolean not null,
        case_components_json jsonb null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_selected_preview_rows;

    insert into pg_temp.tmp_pay_build_selected_preview_rows (
        preview_row_id,
        candidate_id,
        finance_case_id,
        timesheet_id,
        client_id,
        line_type,
        case_type,
        pay_channel,
        paye_treatment,
        routing_kind,
        destination_label,
        taxability,
        beneficiary_name,
        masked_bank_account,
        bank_details_hash,
        item_direction,
        item_type_label,
        source_ref,
        preview_amount_ex_vat,
        draftable,
        snooze_allowed,
        is_candidate_directed_oneoff_payout,
        appears_on_umbrella_remittance,
        generates_candidate_payment_advice,
        case_components_json
    )
    select distinct on (line_rows.preview_row_id)
        line_rows.preview_row_id,
        line_rows.candidate_id,
        line_rows.finance_case_id,
        line_rows.timesheet_id,
        line_rows.client_id,
        line_rows.line_type,
        line_rows.case_type,
        line_rows.pay_channel,
        line_rows.paye_treatment,
        line_rows.routing_kind,
        line_rows.destination_label,
        line_rows.taxability,
        line_rows.beneficiary_name,
        line_rows.masked_bank_account,
        line_rows.bank_details_hash,
        line_rows.item_direction,
        line_rows.item_type_label,
        line_rows.source_ref,
        line_rows.preview_amount_ex_vat,
        line_rows.draftable,
        line_rows.snooze_allowed,
        line_rows.is_candidate_directed_oneoff_payout,
        line_rows.appears_on_umbrella_remittance,
        line_rows.generates_candidate_payment_advice,
        line_rows.case_components_json
    from (
        select
            coalesce(nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'id', '')), '')) as preview_row_id,
            case when coalesce(line_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end as candidate_id,
            case when coalesce(line_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'finance_case_id')::uuid else null::uuid end as finance_case_id,
            case when coalesce(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'timesheet_id')::uuid else null::uuid end as timesheet_id,
            case when coalesce(line_element.value->>'client_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'client_id')::uuid else null::uuid end as client_id,
            nullif(btrim(coalesce(line_element.value->>'line_type', '')), '') as line_type,
            nullif(btrim(coalesce(line_element.value->>'case_type', '')), '') as case_type,
            upper(btrim(coalesce(line_element.value->>'pay_channel', staged_scope.pay_channel, ''))) as pay_channel,
            upper(btrim(coalesce(line_element.value->>'paye_treatment', ''))) as paye_treatment,
            nullif(btrim(coalesce(line_element.value->>'routing_kind', '')), '') as routing_kind,
            nullif(btrim(coalesce(line_element.value->>'destination_label', '')), '') as destination_label,
            nullif(btrim(coalesce(line_element.value->>'taxability', '')), '') as taxability,
            nullif(btrim(coalesce(line_element.value->>'beneficiary_name', '')), '') as beneficiary_name,
            nullif(btrim(coalesce(line_element.value->>'masked_bank_account', '')), '') as masked_bank_account,
            nullif(btrim(coalesce(line_element.value->>'bank_details_hash', '')), '') as bank_details_hash,
            nullif(btrim(coalesce(line_element.value->>'item_direction', '')), '') as item_direction,
            nullif(btrim(coalesce(line_element.value->>'item_type_label', '')), '') as item_type_label,
            nullif(btrim(coalesce(line_element.value->>'source_ref', '')), '') as source_ref,
            round(coalesce(
                case when coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (line_element.value->>'amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (line_element.value->>'preview_amount_ex_vat')::numeric else null::numeric end,
                0::numeric
            ), 2)::numeric(12,2) as preview_amount_ex_vat,
            coalesce(case when lower(coalesce(line_element.value->>'draftable', '')) in ('true', 'false') then (line_element.value->>'draftable')::boolean else null::boolean end, true) as draftable,
            coalesce(case when lower(coalesce(line_element.value->>'snooze_allowed', '')) in ('true', 'false') then (line_element.value->>'snooze_allowed')::boolean else null::boolean end, false) as snooze_allowed,
            coalesce(case when lower(coalesce(line_element.value->>'is_candidate_directed_oneoff_payout', '')) in ('true', 'false') then (line_element.value->>'is_candidate_directed_oneoff_payout')::boolean else null::boolean end, false) as is_candidate_directed_oneoff_payout,
            coalesce(case when lower(coalesce(line_element.value->>'appears_on_umbrella_remittance', '')) in ('true', 'false') then (line_element.value->>'appears_on_umbrella_remittance')::boolean else null::boolean end, false) as appears_on_umbrella_remittance,
            coalesce(case when lower(coalesce(line_element.value->>'generates_candidate_payment_advice', '')) in ('true', 'false') then (line_element.value->>'generates_candidate_payment_advice')::boolean else null::boolean end, false) as generates_candidate_payment_advice,
            coalesce(line_element.value->'case_components', line_element.value->'components', '[]'::jsonb) as case_components_json,
            line_element.ord as line_ordinal
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        cross join lateral jsonb_array_elements(staged_scope.selected_canonical_preview_lines_json) with ordinality as line_element(value, ord)
        where jsonb_typeof(line_element.value) = 'object'
    ) as line_rows
    where line_rows.preview_row_id is not null
      and line_rows.candidate_id is not null
      and line_rows.draftable = true
    order by line_rows.preview_row_id, line_rows.line_ordinal;

    select count(*)::integer
    into v_selected_row_count
    from pg_temp.tmp_pay_build_selected_preview_rows as selected_row;

    if coalesce(v_selected_row_count, 0) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context staged no selected preview rows for operation %, batch %', p_operation_id, p_pay_batch_id;
    end if;

    create temporary table if not exists pg_temp.tmp_pay_build_hidden_template_input_rows (
        candidate_id uuid null,
        finance_case_id uuid null,
        recovery_family text null,
        paye_treatment text null,
        raw_pay_channel text null,
        normalized_pay_channel text null,
        umbrella_id uuid null,
        source_ref text null,
        finance_component_id uuid null,
        frozen_component_key_type text null,
        frozen_component_key_value text null,
        frozen_component_snapshot_json jsonb null,
        frozen_component_classification public.pay_finance_component_classification_enum null,
        frozen_source_basis_json jsonb null,
        frozen_source_pay_method text null,
        frozen_target_pay_method text null,
        frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        frozen_resolution_payload_json jsonb null,
        frozen_resolution_result_json jsonb null,
        frozen_source_amount numeric(12,2) null,
        frozen_outstanding_amount numeric(12,2) null,
        weekly_due numeric(12,2) null,
        minimum_earnings_threshold numeric null,
        take_home_floor_override numeric null,
        default_take_home_floor numeric null,
        payout_status text null,
        next_due_week_start date null,
        sort_order integer null,
        required_identifiers_present boolean not null,
        candidate_selected boolean not null,
        pay_channel_matches_scope boolean not null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_hidden_template_input_rows;

    insert into pg_temp.tmp_pay_build_hidden_template_input_rows (
        candidate_id,
        finance_case_id,
        recovery_family,
        paye_treatment,
        raw_pay_channel,
        normalized_pay_channel,
        umbrella_id,
        source_ref,
        finance_component_id,
        frozen_component_key_type,
        frozen_component_key_value,
        frozen_component_snapshot_json,
        frozen_component_classification,
        frozen_source_basis_json,
        frozen_source_pay_method,
        frozen_target_pay_method,
        frozen_resolution_mode,
        frozen_resolution_payload_json,
        frozen_resolution_result_json,
        frozen_source_amount,
        frozen_outstanding_amount,
        weekly_due,
        minimum_earnings_threshold,
        take_home_floor_override,
        default_take_home_floor,
        payout_status,
        next_due_week_start,
        sort_order,
        required_identifiers_present,
        candidate_selected,
        pay_channel_matches_scope
    )
    select
        case when coalesce(template_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end,
        case when coalesce(template_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'finance_case_id')::uuid else null::uuid end,
        upper(btrim(coalesce(template_element.value->>'recovery_family', ''))),
        upper(nullif(btrim(coalesce(template_element.value->>'paye_treatment', '')), '')),
        upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')),
        case
            when upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) in ('PAYE', 'UMBRELLA') then upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), ''))
            when coalesce(btrim(coalesce(template_element.value->>'pay_channel', '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
            else null::text
        end,
        case when coalesce(template_element.value->>'umbrella_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'umbrella_id')::uuid else null::uuid end,
        nullif(btrim(coalesce(template_element.value->>'source_ref', '')), ''),
        case when coalesce(template_element.value->>'finance_component_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'finance_component_id')::uuid else null::uuid end,
        nullif(btrim(coalesce(template_element.value->>'frozen_component_key_type', '')), ''),
        nullif(btrim(coalesce(template_element.value->>'frozen_component_key_value', '')), ''),
        case when jsonb_typeof(template_element.value->'frozen_component_snapshot_json') = 'object' then template_element.value->'frozen_component_snapshot_json' else null::jsonb end,
        case
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
            else null::public.pay_finance_component_classification_enum
        end,
        case when jsonb_typeof(template_element.value->'frozen_source_basis_json') = 'object' then template_element.value->'frozen_source_basis_json' else null::jsonb end,
        upper(nullif(btrim(coalesce(template_element.value->>'frozen_source_pay_method', '')), '')),
        upper(nullif(btrim(coalesce(template_element.value->>'frozen_target_pay_method', '')), '')),
        case
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_REPLACEMENT_RATE' then 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_AMOUNT' then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
            else null::public.pay_finance_component_resolution_mode_enum
        end,
        case when jsonb_typeof(template_element.value->'frozen_resolution_payload_json') = 'object' then template_element.value->'frozen_resolution_payload_json' else null::jsonb end,
        case when jsonb_typeof(template_element.value->'frozen_resolution_result_json') = 'object' then template_element.value->'frozen_resolution_result_json' else null::jsonb end,
        case when coalesce(template_element.value->>'frozen_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'frozen_source_amount')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'frozen_outstanding_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'frozen_outstanding_amount')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'weekly_due', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'weekly_due')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'minimum_earnings_threshold', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'minimum_earnings_threshold')::numeric else null::numeric end,
        case when coalesce(template_element.value->>'take_home_floor_override', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'take_home_floor_override')::numeric else null::numeric end,
        case when coalesce(template_element.value->>'default_take_home_floor', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'default_take_home_floor')::numeric else null::numeric end,
        nullif(btrim(coalesce(template_element.value->>'payout_status', '')), ''),
        case when coalesce(template_element.value->>'next_due_week_start', '') ~ '^\d{4}-\d{2}-\d{2}$' then (template_element.value->>'next_due_week_start')::date else null::date end,
        case when coalesce(template_element.value->>'sort_order', '') ~ '^-?[0-9]+$' then (template_element.value->>'sort_order')::integer else template_element.ord::integer end,
        (
            (case when coalesce(template_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end) is not null
            and coalesce(template_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            and upper(btrim(coalesce(template_element.value->>'recovery_family', ''))) in ('MANUAL_DEBT_RECOVERY', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY')
        ),
        true,
        case
            when upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) in ('PAYE', 'UMBRELLA') then upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) = v_scope
            when coalesce(btrim(coalesce(template_element.value->>'pay_channel', '')), '') = '' and v_scope = 'PAYE' then true
            else false
        end
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
    cross join lateral jsonb_array_elements(staged_scope.hidden_recovery_template_lines_json) with ordinality as template_element(value, ord)
    where jsonb_typeof(template_element.value) = 'object';

    create temporary table if not exists pg_temp.tmp_pay_build_recovery_template_rows (
        candidate_id uuid not null,
        finance_case_id uuid not null,
        recovery_family text not null,
        paye_treatment text null,
        pay_channel text null,
        umbrella_id uuid null,
        source_ref text null,
        finance_component_id uuid null,
        frozen_component_key_type text null,
        frozen_component_key_value text null,
        frozen_component_snapshot_json jsonb null,
        frozen_component_classification public.pay_finance_component_classification_enum null,
        frozen_source_basis_json jsonb null,
        frozen_source_pay_method text null,
        frozen_target_pay_method text null,
        frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        frozen_resolution_payload_json jsonb null,
        frozen_resolution_result_json jsonb null,
        frozen_source_amount numeric(12,2) null,
        frozen_outstanding_amount numeric(12,2) null,
        weekly_due numeric(12,2) null,
        minimum_earnings_threshold numeric null,
        take_home_floor_override numeric null,
        default_take_home_floor numeric null,
        payout_status text null,
        next_due_week_start date null,
        sort_order integer null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_recovery_template_rows;

    insert into pg_temp.tmp_pay_build_recovery_template_rows (
        candidate_id,
        finance_case_id,
        recovery_family,
        paye_treatment,
        pay_channel,
        umbrella_id,
        source_ref,
        finance_component_id,
        frozen_component_key_type,
        frozen_component_key_value,
        frozen_component_snapshot_json,
        frozen_component_classification,
        frozen_source_basis_json,
        frozen_source_pay_method,
        frozen_target_pay_method,
        frozen_resolution_mode,
        frozen_resolution_payload_json,
        frozen_resolution_result_json,
        frozen_source_amount,
        frozen_outstanding_amount,
        weekly_due,
        minimum_earnings_threshold,
        take_home_floor_override,
        default_take_home_floor,
        payout_status,
        next_due_week_start,
        sort_order
    )
    select distinct on (
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        coalesce(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
        coalesce(hidden_input.source_ref, ''),
        coalesce(hidden_input.normalized_pay_channel, '')
    )
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        hidden_input.paye_treatment,
        hidden_input.normalized_pay_channel,
        hidden_input.umbrella_id,
        hidden_input.source_ref,
        hidden_input.finance_component_id,
        hidden_input.frozen_component_key_type,
        hidden_input.frozen_component_key_value,
        hidden_input.frozen_component_snapshot_json,
        hidden_input.frozen_component_classification,
        hidden_input.frozen_source_basis_json,
        hidden_input.frozen_source_pay_method,
        hidden_input.frozen_target_pay_method,
        hidden_input.frozen_resolution_mode,
        hidden_input.frozen_resolution_payload_json,
        hidden_input.frozen_resolution_result_json,
        hidden_input.frozen_source_amount,
        hidden_input.frozen_outstanding_amount,
        hidden_input.weekly_due,
        hidden_input.minimum_earnings_threshold,
        hidden_input.take_home_floor_override,
        hidden_input.default_take_home_floor,
        hidden_input.payout_status,
        hidden_input.next_due_week_start,
        hidden_input.sort_order
    from pg_temp.tmp_pay_build_hidden_template_input_rows as hidden_input
    where hidden_input.candidate_selected = true
      and hidden_input.required_identifiers_present = true
      and hidden_input.pay_channel_matches_scope = true
    order by
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        coalesce(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
        coalesce(hidden_input.source_ref, ''),
        coalesce(hidden_input.normalized_pay_channel, ''),
        hidden_input.sort_order;

    create temporary table if not exists pg_temp.tmp_pay_build_candidates_ctx (
        id uuid primary key,
        tms_ref text,
        display_name text,
        pay_method text,
        umbrella_id uuid,
        first_name text,
        last_name text,
        account_holder text,
        sort_code text,
        account_number text,
        bank_details_hash text,
        payee_id text,
        payee_account_id text,
        umbrella_vat_chargeable boolean
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_candidates_ctx;

    create temporary table if not exists pg_temp.tmp_pay_build_umbrellas_ctx (
        id uuid primary key,
        name text,
        vat_chargeable boolean,
        sort_code text,
        account_number text,
        bank_details_hash text,
        payee_id text,
        payee_account_id text
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_umbrellas_ctx;

    insert into pg_temp.tmp_pay_build_candidates_ctx (
        id,
        tms_ref,
        display_name,
        pay_method,
        umbrella_id,
        first_name,
        last_name,
        account_holder,
        sort_code,
        account_number,
        bank_details_hash,
        payee_id,
        payee_account_id,
        umbrella_vat_chargeable
    )
    with preview_candidate_rows as (
        select distinct on (preview_candidate_data.preview_candidate_id)
            preview_candidate_data.preview_candidate_id,
            preview_candidate_data.preview_tms_ref,
            preview_candidate_data.preview_display_name,
            preview_candidate_data.preview_pay_method,
            preview_candidate_data.preview_umbrella_id,
            preview_candidate_data.preview_umbrella_vat_chargeable,
            preview_candidate_data.preview_candidate_bank_hash
        from (
            select
                case when coalesce(preview_candidate.cand->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (preview_candidate.cand->>'candidate_id')::uuid else null::uuid end as preview_candidate_id,
                nullif(btrim(coalesce(preview_candidate.cand->>'tms_ref', '')), '') as preview_tms_ref,
                nullif(btrim(coalesce(preview_candidate.cand->>'display_name', '')), '') as preview_display_name,
                upper(nullif(btrim(coalesce(preview_candidate.cand->>'current_pay_method', '')), '')) as preview_pay_method,
                case when coalesce(preview_candidate.cand->>'umbrella_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (preview_candidate.cand->>'umbrella_id')::uuid else null::uuid end as preview_umbrella_id,
                coalesce(case when lower(coalesce(preview_candidate.cand->>'umbrella_vat_chargeable', '')) in ('true', 'false') then (preview_candidate.cand->>'umbrella_vat_chargeable')::boolean else null::boolean end, false) as preview_umbrella_vat_chargeable,
                nullif(btrim(coalesce(preview_candidate.cand->>'candidate_bank_hash', '')), '') as preview_candidate_bank_hash
            from pg_temp.tmp_pay_build_preview_candidates as preview_candidate
        ) as preview_candidate_data
        where preview_candidate_data.preview_candidate_id is not null
        order by preview_candidate_data.preview_candidate_id
    )
    select
        candidate_row.id,
        coalesce(preview_candidate_rows.preview_tms_ref, candidate_row.tms_ref),
        coalesce(preview_candidate_rows.preview_display_name, candidate_row.display_name),
        coalesce(preview_candidate_rows.preview_pay_method, upper(coalesce(candidate_row.pay_method, ''))),
        coalesce(preview_candidate_rows.preview_umbrella_id, candidate_row.umbrella_id),
        candidate_row.first_name,
        candidate_row.last_name,
        candidate_row.account_holder,
        regexp_replace(coalesce(candidate_row.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(candidate_row.account_number, ''), '[^0-9]', '', 'g'), ''),
        coalesce(preview_candidate_rows.preview_candidate_bank_hash, candidate_row.bank_details_hash),
        candidate_payee_map.payee_id,
        candidate_payee_map.payee_account_id,
        coalesce(preview_candidate_rows.preview_umbrella_vat_chargeable, umbrella_row.vat_chargeable, false)
    from (
        select distinct selected_row.candidate_id
        from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
    ) as selected_candidate
    join public.candidates as candidate_row
      on candidate_row.id = selected_candidate.candidate_id
    left join preview_candidate_rows
      on preview_candidate_rows.preview_candidate_id = candidate_row.id
    left join public.umbrellas as umbrella_row
      on umbrella_row.id = coalesce(preview_candidate_rows.preview_umbrella_id, candidate_row.umbrella_id)
    left join public.bank_payee_map as candidate_payee_map
      on upper(coalesce(candidate_payee_map.rail_provider, '')) = upper(btrim(coalesce(v_settings_rail_provider, '')))
     and upper(coalesce(candidate_payee_map.rail_env, '')) = upper(btrim(coalesce(v_settings_rail_env, '')))
     and upper(coalesce(candidate_payee_map.entity_kind, '')) = 'CANDIDATE'
     and candidate_payee_map.entity_id = candidate_row.id
     and candidate_payee_map.bank_details_hash = coalesce(preview_candidate_rows.preview_candidate_bank_hash, candidate_row.bank_details_hash);

    insert into pg_temp.tmp_pay_build_umbrellas_ctx (
        id,
        name,
        vat_chargeable,
        sort_code,
        account_number,
        bank_details_hash,
        payee_id,
        payee_account_id
    )
    select
        umbrella_row.id,
        umbrella_row.name,
        coalesce(umbrella_row.vat_chargeable, false),
        regexp_replace(coalesce(umbrella_row.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(umbrella_row.account_number, ''), '[^0-9]', '', 'g'), ''),
        umbrella_row.bank_details_hash,
        umbrella_payee_map.payee_id,
        umbrella_payee_map.payee_account_id
    from public.umbrellas as umbrella_row
    join (
        select distinct candidate_ctx.umbrella_id
        from pg_temp.tmp_pay_build_candidates_ctx as candidate_ctx
        where candidate_ctx.umbrella_id is not null
    ) as selected_umbrella
      on selected_umbrella.umbrella_id = umbrella_row.id
    left join public.bank_payee_map as umbrella_payee_map
      on upper(coalesce(umbrella_payee_map.rail_provider, '')) = upper(btrim(coalesce(v_settings_rail_provider, '')))
     and upper(coalesce(umbrella_payee_map.rail_env, '')) = upper(btrim(coalesce(v_settings_rail_env, '')))
     and upper(coalesce(umbrella_payee_map.entity_kind, '')) = 'UMBRELLA'
     and umbrella_payee_map.entity_id = umbrella_row.id
     and umbrella_payee_map.bank_details_hash = umbrella_row.bank_details_hash;

    create temporary table if not exists pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
        timesheet_id uuid primary key,
        candidate_id uuid not null,
        client_id uuid null,
        week_ending_date date null,
        source_pay_method text null,
        candidate_pay_method text null,
        baseline_signature text null,
        base_snapshot_json jsonb not null,
        target_snapshot_json jsonb not null,
        target_signature text null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_timesheet_snapshots_ctx;

    insert into pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
        timesheet_id,
        candidate_id,
        client_id,
        week_ending_date,
        source_pay_method,
        candidate_pay_method,
        baseline_signature,
        base_snapshot_json,
        target_snapshot_json,
        target_signature
    )
    select distinct on (snapshot_row.timesheet_id)
        snapshot_row.timesheet_id,
        snapshot_row.candidate_id,
        snapshot_row.client_id,
        snapshot_row.week_ending_date,
        snapshot_row.source_pay_method,
        snapshot_row.candidate_pay_method,
        snapshot_row.baseline_signature,
        snapshot_row.base_snapshot_json,
        snapshot_row.target_snapshot_json,
        snapshot_row.target_signature
    from (
        select
            case when coalesce(snapshot_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'timesheet_id')::uuid else null::uuid end as timesheet_id,
            case when coalesce(snapshot_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end as candidate_id,
            case when coalesce(snapshot_element.value->>'client_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'client_id')::uuid else null::uuid end as client_id,
            case when coalesce(snapshot_element.value->>'week_ending_date', '') ~ '^\d{4}-\d{2}-\d{2}$' then (snapshot_element.value->>'week_ending_date')::date else null::date end as week_ending_date,
            nullif(btrim(coalesce(snapshot_element.value->>'source_pay_method', '')), '') as source_pay_method,
            nullif(btrim(coalesce(snapshot_element.value->>'candidate_pay_method', '')), '') as candidate_pay_method,
            nullif(btrim(coalesce(snapshot_element.value->>'baseline_signature', '')), '') as baseline_signature,
            coalesce(snapshot_element.value->'base_snapshot_json', '{}'::jsonb) as base_snapshot_json,
            coalesce(snapshot_element.value->'target_snapshot_json', '{}'::jsonb) as target_snapshot_json,
            nullif(btrim(coalesce(snapshot_element.value->>'target_signature', '')), '') as target_signature
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        cross join lateral jsonb_array_elements(
            case
                when jsonb_typeof(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots_json') = 'array' then coalesce(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots_json', '[]'::jsonb)
                when jsonb_typeof(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots') = 'array' then coalesce(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots', '[]'::jsonb)
                else '[]'::jsonb
            end
        ) as snapshot_element(value)
        where jsonb_typeof(snapshot_element.value) = 'object'
    ) as snapshot_row
    where snapshot_row.timesheet_id is not null
      and exists (
          select 1
          from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
          where selected_row.timesheet_id = snapshot_row.timesheet_id
            and selected_row.candidate_id = snapshot_row.candidate_id
      )
    order by snapshot_row.timesheet_id, snapshot_row.week_ending_date desc nulls last;

    create temporary table if not exists pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
        finance_case_id uuid primary key,
        beneficiary_name text,
        sort_code text,
        account_number text,
        bank_details_hash text,
        created_by_user_id uuid,
        updated_by_user_id uuid,
        note text
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx;

    insert into pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
        finance_case_id,
        beneficiary_name,
        sort_code,
        account_number,
        bank_details_hash,
        created_by_user_id,
        updated_by_user_id,
        note
    )
    select
        oneoff_details.finance_case_id,
        oneoff_details.beneficiary_name,
        regexp_replace(coalesce(oneoff_details.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(oneoff_details.account_number, ''), '[^0-9]', '', 'g'), ''),
        oneoff_details.bank_details_hash,
        oneoff_details.created_by_user_id,
        oneoff_details.updated_by_user_id,
        oneoff_details.note
    from public.pay_finance_case_oneoff_payout_bank_details as oneoff_details
    where oneoff_details.finance_case_id in (
        select distinct selected_row.finance_case_id
        from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
        where selected_row.finance_case_id is not null
    );

    create temporary table if not exists pg_temp.tmp_pay_build_finance_case_components_ctx (
        id uuid primary key,
        finance_case_id uuid not null,
        candidate_id uuid null,
        linked_timesheet_id uuid null,
        component_key_type text null,
        component_key_value text null,
        classification public.pay_finance_component_classification_enum null,
        source_pay_method text null,
        source_basis_json jsonb null,
        saved_target_pay_method text null,
        saved_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        saved_resolution_payload_json jsonb null,
        saved_resolution_result_json jsonb null,
        source_amount numeric(12,2) null,
        remaining_source_amount numeric(12,2) null,
        allocation_priority_group integer null,
        allocation_priority_order integer null,
        created_at_utc timestamptz null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_finance_case_components_ctx;

    -- Operation-mode staging must use the frozen operation candidate/allocation scope.
    -- Do not rebuild finance component identity from live public.pay_finance_case_components here.
    -- The child batch-builder functions read this temp table, so expose allocation rows in the same shape.
    insert into pg_temp.tmp_pay_build_finance_case_components_ctx (
        id,
        finance_case_id,
        candidate_id,
        linked_timesheet_id,
        component_key_type,
        component_key_value,
        classification,
        source_pay_method,
        source_basis_json,
        saved_target_pay_method,
        saved_resolution_mode,
        saved_resolution_payload_json,
        saved_resolution_result_json,
        source_amount,
        remaining_source_amount,
        allocation_priority_group,
        allocation_priority_order,
        created_at_utc
    )
    select distinct on (coalesce(allocation_row.finance_component_id, allocation_row.id))
        coalesce(allocation_row.finance_component_id, allocation_row.id) as id,
        allocation_row.finance_case_id,
        allocation_row.candidate_id,
        case
            when coalesce(allocation_row.allocation_basis_json #>> '{line,timesheet_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then (allocation_row.allocation_basis_json #>> '{line,timesheet_id}')::uuid
            else null::uuid
        end as linked_timesheet_id,
        coalesce(
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,frozen_component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,economic_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,frozen_component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_type), '')
        ) as component_key_type,
        coalesce(
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,frozen_component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,economic_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,frozen_component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,component_key_value}'), ''),
            allocation_row.operation_source_key
        ) as component_key_value,
        case
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'TAXABLE_CHANNEL_SENSITIVE'
                then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'REIMBURSEMENT_GROSS_FIXED'
                then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'NET_PAY_FIXED_RECOVERY'
                then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
            else null::public.pay_finance_component_classification_enum
        end as classification,
        upper(nullif(btrim(coalesce(
            allocation_row.allocation_basis_json #>> '{line,frozen_source_pay_method}',
            allocation_row.allocation_basis_json #>> '{line,source_pay_method}',
            allocation_row.allocation_basis_json #>> '{component,source_pay_method}',
            allocation_row.pay_channel
        )), '')) as source_pay_method,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_source_basis_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'source_basis_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'source_basis_json', 'null'::jsonb),
            allocation_row.allocation_basis_json
        ) as source_basis_json,
        upper(nullif(btrim(coalesce(
            allocation_row.allocation_basis_json #>> '{line,frozen_target_pay_method}',
            allocation_row.allocation_basis_json #>> '{line,target_pay_method}',
            allocation_row.allocation_basis_json #>> '{component,saved_target_pay_method}',
            allocation_row.pay_channel
        )), '')) as saved_target_pay_method,
        case
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'SUGGESTED_EQUIVALENT_BASIS'
                then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'MANUAL_REPLACEMENT_RATE'
                then 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'MANUAL_AMOUNT'
                then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
            else null::public.pay_finance_component_resolution_mode_enum
        end as saved_resolution_mode,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_resolution_payload_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'resolution_payload_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'saved_resolution_payload_json', 'null'::jsonb),
            '{}'::jsonb
        ) as saved_resolution_payload_json,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_resolution_result_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'resolution_result_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'saved_resolution_result_json', 'null'::jsonb),
            jsonb_build_object('operation_source_key', allocation_row.operation_source_key, 'allocated_amount', allocation_row.allocated_amount)
        ) as saved_resolution_result_json,
        round(abs(coalesce(allocation_row.allocated_amount, 0)), 2)::numeric(12,2) as source_amount,
        round(abs(coalesce(allocation_row.allocated_amount, 0)), 2)::numeric(12,2) as remaining_source_amount,
        0::integer as allocation_priority_group,
        coalesce(allocation_row.sort_order, 0)::integer as allocation_priority_order,
        coalesce(allocation_row.created_at_utc, now()) as created_at_utc
    from public.banking_pay_operation_candidate_allocation_rows as allocation_row
    where allocation_row.operation_id = p_operation_id
      and allocation_row.pay_batch_id = p_pay_batch_id
      and allocation_row.candidate_scope_id in (
          select staged_scope.id
          from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
      )
      and allocation_row.finance_case_id is not null
    order by coalesce(allocation_row.finance_component_id, allocation_row.id), allocation_row.sort_order nulls last, allocation_row.id;

    select count(*)::integer
    into v_timesheet_snapshot_count
    from pg_temp.tmp_pay_build_timesheet_snapshots_ctx as snapshot_ctx;

    select count(*)::integer
    into v_finance_component_count
    from pg_temp.tmp_pay_build_finance_case_components_ctx as component_ctx;

    return query
    select
        coalesce(v_candidate_count, 0),
        coalesce(v_selected_row_count, 0),
        coalesce(v_timesheet_snapshot_count, 0),
        coalesce(v_finance_component_count, 0);
end;
$$;


CREATE OR REPLACE FUNCTION public.pay_batch_shell_ensure_from_operation(p_operation_id uuid, p_workbench_session_id uuid, p_actor_user_id uuid, p_batch_kind text, p_pay_channel text, p_input_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(pay_batch_id uuid, created boolean, scope jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_operation public.banking_pay_operations%ROWTYPE;
    v_session public.banking_pay_workbench_sessions%ROWTYPE;
    v_input_json jsonb := '{}'::jsonb;
    v_supplied_input_json jsonb := COALESCE(p_input_json, '{}'::jsonb);
    v_batch_kind text;
    v_pay_channel text;
    v_pay_channel_raw text;
    v_batch_kind_raw text;
    v_operation_scope text := 'ALL';
    v_scope_entries jsonb := '[]'::jsonb;
    v_scope_invalid_count integer := 0;
    v_scope_values text[] := ARRAY[]::text[];
    v_existing_pay_batch_id uuid;
    v_existing_pay_batch public.pay_batches%ROWTYPE;
    v_existing_pay_batch_count integer := 0;
    v_new_pay_batch_id uuid;
    v_scope_candidate_count integer := 0;
    v_snooze_guard_scope_ids jsonb := '[]'::jsonb;
    v_snooze_guard_json jsonb := '{}'::jsonb;
    v_active_snooze_count integer := 0;
    v_settings_bank_system text;
    v_settings_external_paye_system text;
    v_settings_rail_provider text;
    v_settings_rail_env text;
    v_primary_override_json jsonb := '{}'::jsonb;
    v_secondary_override_json jsonb := '{}'::jsonb;
    v_same_week_override_json jsonb := '{}'::jsonb;
    v_same_week_override_has_values boolean := false;
    v_same_week_override_used boolean := false;
    v_same_week_override_continue boolean := false;
    v_same_week_override_verified boolean := false;
    v_same_week_override_reason text := NULL::text;
    v_same_week_override_verified_at_utc timestamptz := NULL::timestamptz;
    v_same_week_override_verified_by_user_id uuid := NULL::uuid;
    v_same_week_override_purpose text := NULL::text;
    v_same_week_override_guardrail_code text := NULL::text;
    v_same_week_override_proof_valid boolean := false;
    v_same_week_override_required boolean := false;
    v_same_week_override_persisted boolean := false;
    v_paye_guardrails jsonb := '{}'::jsonb;
    v_existing_draft_id_text text := NULL::text;
    v_top_text text;
    v_top_bool boolean;
    v_top_ts timestamptz;
BEGIN
    IF p_operation_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_operation_id';
    END IF;

    IF p_workbench_session_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_workbench_session_id';
    END IF;

    IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_actor_user_id';
    END IF;

    IF jsonb_typeof(v_supplied_input_json) IS DISTINCT FROM 'object' THEN
        v_supplied_input_json := '{}'::jsonb;
    END IF;

    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation tms_users row not found: %', p_actor_user_id;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation not found: %', p_operation_id;
    END IF;

    v_input_json := COALESCE(v_operation.input_json, '{}'::jsonb);

    IF jsonb_typeof(v_input_json) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_OPERATION_INPUT_INVALID',
            'message', 'DRAFT_CREATE operation input_json must be a JSON object.',
            'operation_id', p_operation_id::text
        )::text;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation cannot create shell for terminal operation % with status %', p_operation_id, v_operation.status;
    END IF;

    IF v_operation.actor_user_id IS NOT NULL AND v_operation.actor_user_id <> p_actor_user_id THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation % belongs to a different actor', p_operation_id;
    END IF;

    IF v_operation.workbench_session_id IS NOT NULL AND v_operation.workbench_session_id <> p_workbench_session_id THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation % belongs to a different workbench session', p_operation_id;
    END IF;

    SELECT session_row.*
    INTO v_session
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_workbench_session_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session not found: %', p_workbench_session_id;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN' THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session % is not OPEN: %', p_workbench_session_id, v_session.status;
    END IF;

    IF v_session.discarded_at_utc IS NOT NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session % has been discarded', p_workbench_session_id;
    END IF;

    WITH raw_scope AS (
        SELECT 'pay_channel_scope'::text AS source_key, NULLIF(BTRIM(v_input_json->>'pay_channel_scope'), '') AS raw_value
        UNION ALL SELECT 'payChannelScope', NULLIF(BTRIM(v_input_json->>'payChannelScope'), '')
        UNION ALL SELECT 'draft_scope', NULLIF(BTRIM(v_input_json->>'draft_scope'), '')
        UNION ALL SELECT 'draftScope', NULLIF(BTRIM(v_input_json->>'draftScope'), '')
        UNION ALL SELECT 'scope', NULLIF(BTRIM(v_input_json->>'scope'), '')
    ), normalised_scope AS (
        SELECT
            raw_scope.source_key,
            raw_scope.raw_value,
            BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(raw_scope.raw_value, ''))), '[^A-Z0-9]+', '_', 'g'), '_') AS raw_normalised
        FROM raw_scope
        WHERE raw_scope.raw_value IS NOT NULL
    ), resolved_scope AS (
        SELECT
            normalised_scope.source_key,
            normalised_scope.raw_value,
            CASE
                WHEN normalised_scope.raw_normalised IN ('ALL', 'BOTH', 'MIXED', 'ALL_PAY_CHANNELS', 'BOTH_PAY_CHANNELS', 'PAYE_AND_UMBRELLA', 'PAYE_UMBRELLA', 'PAYE_PLUS_UMBRELLA', 'PAYE_WITH_UMBRELLA', 'BOTH_PAYE_UMBRELLA', 'BOTH_PAYE_AND_UMBRELLA', 'PAYE_AND_NON_PAYE', 'PAYE_NON_PAYE') THEN 'ALL'
                WHEN normalised_scope.raw_normalised IN ('PAYE', 'PAYE_ONLY', 'ONLY_PAYE', 'PAYE_PAY') THEN 'PAYE'
                WHEN normalised_scope.raw_normalised IN ('UMBRELLA', 'UMBRELLAS', 'UMBRELLA_ONLY', 'ONLY_UMBRELLA', 'UMBRELLA_PAY', 'NON_PAYE', 'NONPAYE', 'NON_PAYE_ONLY', 'NONPAYE_ONLY') THEN 'UMBRELLA'
                ELSE NULL::text
            END AS scope_value
        FROM normalised_scope
    )
    SELECT
        COALESCE(jsonb_agg(jsonb_build_object(
            'source', resolved_scope.source_key,
            'raw', resolved_scope.raw_value,
            'value', resolved_scope.scope_value,
            'invalid', (resolved_scope.scope_value IS NULL)
        ) ORDER BY resolved_scope.source_key), '[]'::jsonb),
        COUNT(*) FILTER (WHERE resolved_scope.scope_value IS NULL)::integer,
        COALESCE(ARRAY_AGG(DISTINCT resolved_scope.scope_value) FILTER (WHERE resolved_scope.scope_value IS NOT NULL), ARRAY[]::text[])
    INTO v_scope_entries, v_scope_invalid_count, v_scope_values
    FROM resolved_scope;

    IF COALESCE(v_scope_invalid_count, 0) > 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'BANKING_PAY_CREATE_DRAFT_INVALID_SCOPE',
            'message', 'Create Draft scope stored on the operation is not valid. No draft batch shell has been created.',
            'operation_id', p_operation_id::text,
            'scope_entries', COALESCE(v_scope_entries, '[]'::jsonb)
        )::text;
    END IF;

    IF COALESCE(array_length(v_scope_values, 1), 0) > 1 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'BANKING_PAY_CREATE_DRAFT_SCOPE_CONFLICT',
            'message', 'Create Draft scope stored on the operation is inconsistent. No draft batch shell has been created.',
            'operation_id', p_operation_id::text,
            'scope_entries', COALESCE(v_scope_entries, '[]'::jsonb),
            'scope_values', to_jsonb(v_scope_values)
        )::text;
    END IF;

    v_operation_scope := COALESCE(v_scope_values[1], 'ALL');

    v_pay_channel_raw := BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(p_pay_channel, ''))), '[^A-Z0-9]+', '_', 'g'), '_');

    IF v_pay_channel_raw IN ('PAYE', 'PAYE_ONLY', 'ONLY_PAYE', 'PAYE_PAY') THEN
        v_pay_channel := 'PAYE';
    ELSIF v_pay_channel_raw IN ('UMBRELLA', 'UMBRELLAS', 'UMBRELLA_ONLY', 'ONLY_UMBRELLA', 'UMBRELLA_PAY', 'NON_PAYE', 'NONPAYE', 'NON_PAYE_ONLY', 'NONPAYE_ONLY') THEN
        v_pay_channel := 'UMBRELLA';
    ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_PAY_CHANNEL_INVALID',
            'message', 'pay_batch_shell_ensure_from_operation supports PAYE or UMBRELLA shell creation only.',
            'operation_id', p_operation_id::text,
            'pay_channel', p_pay_channel
        )::text;
    END IF;

    IF v_operation_scope = 'PAYE' AND v_pay_channel <> 'PAYE' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_SCOPE_CHANNEL_MISMATCH',
            'message', 'PAYE-scoped draft operation cannot create an Umbrella shell.',
            'operation_id', p_operation_id::text,
            'operation_scope', v_operation_scope,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    IF v_operation_scope = 'UMBRELLA' AND v_pay_channel <> 'UMBRELLA' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_SCOPE_CHANNEL_MISMATCH',
            'message', 'Umbrella-scoped draft operation cannot create a PAYE shell.',
            'operation_id', p_operation_id::text,
            'operation_scope', v_operation_scope,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    v_batch_kind_raw := BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(NULLIF(p_batch_kind, ''), 'STANDARD_PAYRUN'))), '[^A-Z0-9]+', '_', 'g'), '_');

    IF v_batch_kind_raw IN ('', 'STANDARD_PAYRUN', 'MIXED') THEN
        v_batch_kind := v_pay_channel;
    ELSIF v_batch_kind_raw IN ('PAYE', 'UMBRELLA') THEN
        v_batch_kind := v_batch_kind_raw;
    ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_BATCH_KIND_INVALID',
            'message', 'pay_batch_shell_ensure_from_operation supports PAYE or UMBRELLA batch shells for DRAFT_CREATE.',
            'operation_id', p_operation_id::text,
            'batch_kind', p_batch_kind
        )::text;
    END IF;

    IF v_batch_kind <> v_pay_channel THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_BATCH_KIND_CHANNEL_MISMATCH',
            'message', 'Batch kind and pay channel must match for a DRAFT_CREATE shell.',
            'operation_id', p_operation_id::text,
            'batch_kind', v_batch_kind,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_scope_candidate_count
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel;

    IF COALESCE(v_scope_candidate_count, 0) = 0 THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation found no candidate scope rows for operation %, pay channel %', p_operation_id, v_pay_channel;
    END IF;

    SELECT COALESCE(jsonb_agg(scope_row.id::text ORDER BY scope_row.id::text), '[]'::jsonb)
    INTO v_snooze_guard_scope_ids
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel;

    v_snooze_guard_json := public.pay_workbench_operation_active_snoozes_v1(
        p_operation_id,
        p_workbench_session_id,
        v_snooze_guard_scope_ids
    );
    v_active_snooze_count := CASE
        WHEN COALESCE(v_snooze_guard_json->>'active_snooze_count', '') ~ '^[0-9]{1,9}$'
          THEN (v_snooze_guard_json->>'active_snooze_count')::integer
        ELSE 0
    END;

    IF v_active_snooze_count > 0 THEN
        RAISE EXCEPTION 'ACTIVE_SNOOZE_PREVENTS_DRAFT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_strip_nulls(
                  jsonb_build_object(
                    'code', 'ACTIVE_SNOOZE_PREVENTS_DRAFT',
                    'message', 'One or more selected payments are currently snoozed. Banking Pay has been refreshed so you can review the updated selection.',
                    'operation_id', p_operation_id::text,
                    'workbench_session_id', p_workbench_session_id::text,
                    'pay_channel', v_pay_channel,
                    'refresh_required', true,
                    'next_action', 'REFRESH_WORKBENCH'
                  )
                  || COALESCE(v_snooze_guard_json, '{}'::jsonb)
                )::text;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_existing_pay_batch_count
    FROM (
        SELECT DISTINCT scope_row.pay_batch_id
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.workbench_session_id = p_workbench_session_id
          AND scope_row.pay_batch_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
    ) AS existing_batch_ids;

    IF COALESCE(v_existing_pay_batch_count, 0) > 1 THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation found multiple pay batches for operation %, pay channel %', p_operation_id, v_pay_channel;
    END IF;

    SELECT DISTINCT scope_row.pay_batch_id
    INTO v_existing_pay_batch_id
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND scope_row.pay_batch_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
    ORDER BY scope_row.pay_batch_id
    LIMIT 1;

    IF v_pay_channel = 'PAYE' THEN
        v_primary_override_json := CASE
            WHEN jsonb_typeof(v_input_json->'same_week_paye_override') = 'object' THEN COALESCE(v_input_json->'same_week_paye_override', '{}'::jsonb)
            ELSE '{}'::jsonb
        END;
        v_secondary_override_json := CASE
            WHEN jsonb_typeof(v_input_json->'same_week_paye_override_json') = 'object' THEN COALESCE(v_input_json->'same_week_paye_override_json', '{}'::jsonb)
            ELSE '{}'::jsonb
        END;

        IF v_primary_override_json <> '{}'::jsonb AND v_secondary_override_json <> '{}'::jsonb AND v_primary_override_json <> v_secondary_override_json THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                'message', 'PAYE same-week override proof contains conflicting nested proof objects.',
                'operation_id', p_operation_id::text,
                'field', 'same_week_paye_override_json'
            )::text;
        END IF;

        v_same_week_override_json := CASE
            WHEN v_primary_override_json <> '{}'::jsonb THEN v_primary_override_json
            ELSE v_secondary_override_json
        END;

        FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_reauth_token', 'sameWeekPayeReauthToken', 'reauth_token', 'reauthToken']) LOOP
            IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'Raw PAYE override reauthentication token must not be stored on a draft operation.',
                    'operation_id', p_operation_id::text,
                    'field', v_top_text
                )::text;
            END IF;
        END LOOP;

        v_same_week_override_has_values := (v_same_week_override_json <> '{}'::jsonb)
          AND (
            LOWER(BTRIM(COALESCE(v_same_week_override_json->>'used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(v_same_week_override_json->>'continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(v_same_week_override_json->>'verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reason', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'verified_by_user_id', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'verified_at_utc', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reauth_purpose', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'guardrail_code', '')), '') IS NOT NULL
          );

        IF v_same_week_override_has_values THEN
            v_same_week_override_used := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_continue := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_verified := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_reason := NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reason', '')), '');
            v_same_week_override_verified_by_user_id := CASE
                WHEN COALESCE(v_same_week_override_json->>'verified_by_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_same_week_override_json->>'verified_by_user_id')::uuid
                ELSE NULL::uuid
            END;
            v_same_week_override_verified_at_utc := CASE
                WHEN COALESCE(v_same_week_override_json->>'verified_at_utc', '') ~ '^\d{4}-\d{2}-\d{2}' THEN (v_same_week_override_json->>'verified_at_utc')::timestamptz
                ELSE NULL::timestamptz
            END;
            v_same_week_override_purpose := UPPER(BTRIM(COALESCE(v_same_week_override_json->>'reauth_purpose', '')));
            v_same_week_override_guardrail_code := UPPER(BTRIM(COALESCE(v_same_week_override_json->>'guardrail_code', '')));

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_used THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level used flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'same_week_paye_override_used')::text;
                END IF;
            END IF;

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'override_continue', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'override_continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_continue THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level continue flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'override_continue')::text;
                END IF;
            END IF;

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'override_verified', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'override_verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_verified THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'override_verified')::text;
                END IF;
            END IF;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_reason', 'override_reason']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL
                   AND NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS DISTINCT FROM v_same_week_override_reason THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level reason conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                END IF;
            END LOOP;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_verified_by_user_id', 'override_verified_by_user_id']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL
                   AND NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS DISTINCT FROM v_same_week_override_verified_by_user_id::text THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified user conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                END IF;
            END LOOP;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_verified_at_utc', 'override_verified_at_utc']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                    v_top_ts := CASE
                        WHEN COALESCE(v_input_json->>v_top_text, '') ~ '^\d{4}-\d{2}-\d{2}' THEN (v_input_json->>v_top_text)::timestamptz
                        ELSE NULL::timestamptz
                    END;
                    IF v_top_ts IS NULL OR v_top_ts IS DISTINCT FROM v_same_week_override_verified_at_utc THEN
                        RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified timestamp conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                    END IF;
                END IF;
            END LOOP;

            v_same_week_override_proof_valid := v_same_week_override_used
                AND v_same_week_override_continue
                AND v_same_week_override_verified
                AND v_same_week_override_reason IS NOT NULL
                AND v_same_week_override_verified_by_user_id = p_actor_user_id
                AND v_same_week_override_verified_at_utc IS NOT NULL
                AND v_same_week_override_purpose = 'PAYE_SAME_WEEK_OVERRIDE'
                AND v_same_week_override_guardrail_code = 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED';

            IF v_same_week_override_proof_valid IS NOT TRUE THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'PAYE same-week override proof stored on the draft operation is incomplete or invalid.',
                    'operation_id', p_operation_id::text,
                    'pay_channel', v_pay_channel
                )::text;
            END IF;
        ELSE
            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_reason', 'override_reason', 'same_week_paye_override_verified_by_user_id', 'override_verified_by_user_id', 'same_week_paye_override_verified_at_utc', 'override_verified_at_utc']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                    RAISE EXCEPTION '%', jsonb_build_object(
                        'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                        'message', 'PAYE same-week override proof aliases are present without canonical nested proof.',
                        'operation_id', p_operation_id::text,
                        'field', v_top_text
                    )::text;
                END IF;
            END LOOP;

            IF LOWER(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR LOWER(BTRIM(COALESCE(v_input_json->>'override_continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR LOWER(BTRIM(COALESCE(v_input_json->>'override_verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'PAYE same-week override proof flags are present without canonical nested proof.',
                    'operation_id', p_operation_id::text
                )::text;
            END IF;
        END IF;

        PERFORM pg_advisory_xact_lock(94201, 1);

        v_paye_guardrails := public.pay_paye_guardrails(
            p_pay_date => v_session.pay_date,
            p_ignore_pay_batch_id => v_existing_pay_batch_id,
            p_actor_user_id => p_actor_user_id
        );

        IF COALESCE((v_paye_guardrails->>'ok')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_GUARDRAIL_RESPONSE_INVALID',
                'message', 'Could not confirm PAYE guardrails before creating draft shell.',
                'operation_id', p_operation_id::text,
                'guardrail', v_paye_guardrails
            )::text;
        END IF;

        IF COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false) THEN
            v_existing_draft_id_text := v_paye_guardrails #>> '{existing_paye_draft,pay_batch_id}';
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_DRAFT_ALREADY_EXISTS',
                'message', 'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.',
                'operation_id', p_operation_id::text,
                'pay_channel', v_pay_channel,
                'existing_paye_draft', v_paye_guardrails->'existing_paye_draft',
                'existing_paye_draft_id', v_existing_draft_id_text
            )::text;
        END IF;

        v_same_week_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

        IF v_same_week_override_required AND v_same_week_override_proof_valid IS NOT TRUE THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED',
                'message', 'A same-week PAYE override must be verified before creating this PAYE draft shell.',
                'operation_id', p_operation_id::text,
                'pay_channel', v_pay_channel,
                'guardrail', v_paye_guardrails,
                'no_batch_created', true,
                'no_batch_shell_created', true
            )::text;
        END IF;
    END IF;

    IF v_existing_pay_batch_id IS NOT NULL THEN
        SELECT existing_batch_row.*
        INTO v_existing_pay_batch
        FROM public.pay_batches AS existing_batch_row
        WHERE existing_batch_row.id = v_existing_pay_batch_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation candidate scope references missing pay batch %', v_existing_pay_batch_id;
        END IF;

        IF UPPER(BTRIM(COALESCE(v_existing_pay_batch.status, ''))) <> 'DRAFT' THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % is not DRAFT: %', v_existing_pay_batch_id, v_existing_pay_batch.status;
        END IF;

        IF v_existing_pay_batch.source_workbench_session_id IS DISTINCT FROM p_workbench_session_id THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different workbench session', v_existing_pay_batch_id;
        END IF;

        IF UPPER(BTRIM(COALESCE(v_existing_pay_batch.batch_kind_fixed, ''))) IS DISTINCT FROM v_batch_kind THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % has batch kind %, expected %', v_existing_pay_batch_id, v_existing_pay_batch.batch_kind_fixed, v_batch_kind;
        END IF;

        IF v_existing_pay_batch.source_snapshot_run_id IS DISTINCT FROM v_session.source_snapshot_run_id THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different snapshot run', v_existing_pay_batch_id;
        END IF;

        IF v_existing_pay_batch.source_session_version IS DISTINCT FROM v_session.version THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different session version', v_existing_pay_batch_id;
        END IF;

        IF v_pay_channel = 'UMBRELLA'
           AND (
             COALESCE(v_existing_pay_batch.same_week_paye_override_used, false)
             OR v_existing_pay_batch.same_week_paye_override_reason IS NOT NULL
             OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS NOT NULL
             OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS NOT NULL
           ) THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'UMBRELLA_BATCH_HAS_PAYE_OVERRIDE_PROOF',
                'message', 'Umbrella draft batch shell must not contain PAYE same-week override proof.',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_existing_pay_batch_id::text
            )::text;
        END IF;

        IF v_pay_channel = 'PAYE' AND v_same_week_override_required THEN
            IF COALESCE(v_existing_pay_batch.same_week_paye_override_used, false) IS NOT TRUE
               OR NULLIF(BTRIM(COALESCE(v_existing_pay_batch.same_week_paye_override_reason, '')), '') IS DISTINCT FROM v_same_week_override_reason
               OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS DISTINCT FROM v_same_week_override_verified_by_user_id
               OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS DISTINCT FROM v_same_week_override_verified_at_utc THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'Existing PAYE draft shell does not contain the required verified same-week override proof for this operation.',
                    'operation_id', p_operation_id::text,
                    'pay_batch_id', v_existing_pay_batch_id::text
                )::text;
            END IF;
        END IF;

        UPDATE public.banking_pay_operation_candidate_scope AS scope_update
        SET pay_batch_id = v_existing_pay_batch_id,
            updated_at_utc = now()
        WHERE scope_update.operation_id = p_operation_id
          AND scope_update.workbench_session_id = p_workbench_session_id
          AND scope_update.pay_batch_id IS DISTINCT FROM v_existing_pay_batch_id
          AND UPPER(BTRIM(COALESCE(scope_update.pay_channel, ''))) = v_pay_channel;

        UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
        SET pay_batch_id = v_existing_pay_batch_id,
            updated_at_utc = now()
        WHERE allocation_update.operation_id = p_operation_id
          AND allocation_update.pay_batch_id IS DISTINCT FROM v_existing_pay_batch_id
          AND EXISTS (
              SELECT 1
              FROM public.banking_pay_operation_candidate_scope AS scope_row
              WHERE scope_row.id = allocation_update.candidate_scope_id
                AND scope_row.operation_id = p_operation_id
                AND scope_row.workbench_session_id = p_workbench_session_id
                AND scope_row.pay_batch_id = v_existing_pay_batch_id
                AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
          );

        v_same_week_override_persisted := COALESCE(v_existing_pay_batch.same_week_paye_override_used, false)
            OR v_existing_pay_batch.same_week_paye_override_reason IS NOT NULL
            OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS NOT NULL
            OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS NOT NULL;

        RETURN QUERY
        SELECT
            v_existing_pay_batch_id,
            false,
            jsonb_build_object(
                'operation_id', p_operation_id::text,
                'workbench_session_id', p_workbench_session_id::text,
                'pay_channel', v_pay_channel,
                'batch_kind', v_batch_kind,
                'candidate_scope_count', v_scope_candidate_count,
                'source_snapshot_run_id', CASE WHEN v_existing_pay_batch.source_snapshot_run_id IS NULL THEN NULL ELSE v_existing_pay_batch.source_snapshot_run_id::text END,
                'source_session_version', v_existing_pay_batch.source_session_version,
                'operation_pay_channel_scope', v_operation_scope,
                'same_week_paye_override_required', v_same_week_override_required,
                'same_week_paye_override_persisted', CASE WHEN v_pay_channel = 'PAYE' THEN v_same_week_override_persisted ELSE false END
            );
        RETURN;
    END IF;

    SELECT settings_row.banking_system,
           settings_row.external_paye_system,
           settings_row.rail_provider_default,
           settings_row.rail_env_default
    INTO v_settings_bank_system,
         v_settings_external_paye_system,
         v_settings_rail_provider,
         v_settings_rail_env
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id ASC
    LIMIT 1;

    IF v_settings_bank_system IS NULL OR v_settings_external_paye_system IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation settings_defaults missing banking_system/external_paye_system';
    END IF;

    IF v_settings_rail_provider IS NULL OR v_settings_rail_env IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation settings_defaults missing rail provider/environment';
    END IF;

    v_same_week_override_persisted := v_pay_channel = 'PAYE' AND v_same_week_override_required AND v_same_week_override_proof_valid;

    INSERT INTO public.pay_batches (
        pay_date,
        created_at_utc,
        created_by_user_id,
        status,
        banking_system_snapshot,
        external_paye_system_snapshot,
        rail_provider_snapshot,
        rail_env_snapshot,
        batch_kind_fixed,
        source_workbench_session_id,
        source_snapshot_run_id,
        source_session_version,
        execution_commit_state,
        same_week_paye_override_used,
        same_week_paye_override_reason,
        same_week_paye_override_verified_at_utc,
        same_week_paye_override_verified_by_user_id
    )
    VALUES (
        v_session.pay_date,
        now(),
        p_actor_user_id,
        'DRAFT',
        v_settings_bank_system,
        v_settings_external_paye_system,
        v_settings_rail_provider,
        v_settings_rail_env,
        v_batch_kind,
        p_workbench_session_id,
        v_session.source_snapshot_run_id,
        v_session.version,
        'NOT_SUBMITTED',
        CASE WHEN v_same_week_override_persisted THEN true ELSE false END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_reason ELSE NULL::text END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_verified_at_utc ELSE NULL::timestamptz END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_verified_by_user_id ELSE NULL::uuid END
    )
    RETURNING public.pay_batches.id INTO v_new_pay_batch_id;

    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET pay_batch_id = v_new_pay_batch_id,
        updated_at_utc = now()
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_update.pay_channel, ''))) = v_pay_channel;

    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET pay_batch_id = v_new_pay_batch_id,
        updated_at_utc = now()
    WHERE allocation_update.operation_id = p_operation_id
      AND allocation_update.pay_batch_id IS DISTINCT FROM v_new_pay_batch_id
      AND EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS scope_row
          WHERE scope_row.id = allocation_update.candidate_scope_id
            AND scope_row.operation_id = p_operation_id
            AND scope_row.workbench_session_id = p_workbench_session_id
            AND scope_row.pay_batch_id = v_new_pay_batch_id
            AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
      );

    RETURN QUERY
    SELECT
        v_new_pay_batch_id,
        true,
        jsonb_build_object(
            'operation_id', p_operation_id::text,
            'workbench_session_id', p_workbench_session_id::text,
            'pay_channel', v_pay_channel,
            'batch_kind', v_batch_kind,
            'candidate_scope_count', v_scope_candidate_count,
            'source_snapshot_run_id', CASE WHEN v_session.source_snapshot_run_id IS NULL THEN NULL ELSE v_session.source_snapshot_run_id::text END,
            'source_session_version', v_session.version,
            'operation_pay_channel_scope', v_operation_scope,
            'same_week_paye_override_required', v_same_week_override_required,
            'same_week_paye_override_persisted', v_same_week_override_persisted
        );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_remittance_maybe_queue_for_trigger(uuid, text, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_remittance_maybe_queue_for_trigger(uuid, text, text, uuid, boolean, uuid, boolean);

DROP FUNCTION IF EXISTS public.pay_remittance_maybe_queue_for_trigger(uuid, text, text, uuid);
DROP FUNCTION IF EXISTS public.pay_remittance_maybe_queue_for_trigger(uuid, text, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_remittance_maybe_queue_for_trigger(uuid, text, text, uuid, boolean, uuid, boolean);






DROP FUNCTION IF EXISTS public.pay_workbench_enqueue_candidate_refresh_many(uuid, jsonb, text, uuid);


CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh_many(
  p_session_id uuid,
  p_candidate_ids jsonb,
  p_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_ids_input jsonb := '[]'::jsonb;
  v_skip_candidate_ids_input jsonb := '[]'::jsonb;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_skip_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_requested_count integer := 0;
  v_scope_count integer := 0;
  v_queued_count integer := 0;
  v_reused_count integer := 0;
  v_legacy_queued_count integer := 0;
  v_delta_queued_count integer := 0;
  v_clone_skipped_ready_count integer := 0;
  v_clone_skipped_pending_count integer := 0;
  v_clone_skip_list_count integer := 0;
  v_enqueued_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_enqueued_candidate_count integer := 0;
  v_clone_rebase_queued boolean := false;
  v_candidate_scope_status text := NULL::text;
  v_candidate_state_status text := NULL::text;
  v_candidate_clone_certified boolean := false;
  v_candidate_clone_failed boolean := false;
  v_job_ids_jsonb jsonb := '[]'::jsonb;
  v_source_build_run_ids_jsonb jsonb := '[]'::jsonb;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'SESSION_SOURCE_BUILD_REFRESH');
  v_candidate_id uuid;
  v_refresh_result jsonb := '{}'::jsonb;
  v_job_id_text text := NULL::text;
  v_previous_ready integer := 0;
  v_previous_failed integer := 0;
  v_previous_pending integer := 0;
  v_source_build_limit integer := 25;
  v_pay_channel_scope text := 'ALL';
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF p_candidate_ids IS NULL THEN
    RAISE EXCEPTION 'p_candidate_ids must be supplied';
  END IF;

  IF jsonb_typeof(p_candidate_ids) = 'array' THEN
    v_candidate_ids_input := p_candidate_ids;
  ELSIF jsonb_typeof(p_candidate_ids) = 'object' AND jsonb_typeof(p_candidate_ids->'candidate_ids') = 'array' THEN
    v_candidate_ids_input := p_candidate_ids->'candidate_ids';
    IF jsonb_typeof(p_candidate_ids->'skip_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'skip_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'clone_rebase_skip_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'clone_rebase_skip_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'cloned_ready_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'cloned_ready_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'clone_ready_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'clone_ready_candidate_ids';
    END IF;
  ELSE
    RAISE EXCEPTION 'p_candidate_ids must be a non-empty JSON array or an object containing candidate_ids';
  END IF;

  IF jsonb_array_length(v_candidate_ids_input) = 0 THEN
    RAISE EXCEPTION 'p_candidate_ids must be a non-empty JSON array';
  END IF;

  IF jsonb_array_length(v_candidate_ids_input) > 100 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_MANY_INPUT_TOO_LARGE',
      'message', 'At most 100 candidate ids may be enqueued in one RPC. Seed workbench scope chunks and call again with a capped page.',
      'session_id', p_session_id::text,
      'requested_count', jsonb_array_length(v_candidate_ids_input),
      'max_candidate_ids', 100,
      'recommended_next_api', 'pay_workbench_session_seed_scope_chunk'
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open', p_session_id;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND COALESCE(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found or inactive', p_actor_user_id;
  END IF;

  SELECT COALESCE(array_agg(candidate_input.candidate_id ORDER BY candidate_input.candidate_id), ARRAY[]::uuid[]),
         count(*)::integer
  INTO v_candidate_ids, v_requested_count
  FROM (
    SELECT DISTINCT (candidate_element.value #>> '{}')::uuid AS candidate_id
    FROM jsonb_array_elements(v_candidate_ids_input) AS candidate_element(value)
    WHERE (candidate_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS candidate_input;

  IF COALESCE(v_requested_count, 0) <> jsonb_array_length(v_candidate_ids_input) THEN
    RAISE EXCEPTION 'p_candidate_ids contains invalid candidate id values';
  END IF;

  SELECT COALESCE(array_agg(skip_input.candidate_id ORDER BY skip_input.candidate_id), ARRAY[]::uuid[])
  INTO v_skip_candidate_ids
  FROM (
    SELECT DISTINCT (skip_element.value #>> '{}')::uuid AS candidate_id
    FROM jsonb_array_elements(v_skip_candidate_ids_input) AS skip_element(value)
    WHERE (skip_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS skip_input;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer
  INTO v_scope_count,
       v_previous_ready,
       v_previous_failed,
       v_previous_pending
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = ANY(v_candidate_ids);

  IF v_scope_count <> v_requested_count THEN
    RAISE EXCEPTION 'one or more candidate ids do not belong to session % scope', p_session_id;
  END IF;

  SELECT LEAST(GREATEST(COALESCE(
    CASE
      WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job', '') ~ '^[0-9]{1,9}$'
        THEN (to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job')::integer
      ELSE NULL::integer
    END,
    CASE
      WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job', '') ~ '^[0-9]{1,9}$'
        THEN (to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job')::integer
      ELSE NULL::integer
    END,
    25
  ), 1), 100)
  INTO v_source_build_limit
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  v_source_build_limit := COALESCE(v_source_build_limit, 25);

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_clone_rebase_queued := UPPER(BTRIM(COALESCE(v_session_row.progress_state, ''))) = 'CLONE_REBASING'
    OR LOWER(BTRIM(COALESCE(v_session_row.progress_json->>'clone_rebase_queued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_session_row.progress_json->>'clone_rebase_more_due', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      jsonb_typeof(p_candidate_ids) = 'object'
      AND LOWER(BTRIM(COALESCE(p_candidate_ids->>'clone_rebase_queued', p_candidate_ids->>'clone_rebase_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    );

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_candidate_scope_status := NULL::text;
    v_candidate_state_status := NULL::text;
    v_candidate_clone_certified := false;
    v_candidate_clone_failed := false;

    SELECT UPPER(BTRIM(COALESCE(scope_row.status, ''))),
           UPPER(BTRIM(COALESCE(candidate_state.status, ''))),
           COALESCE(
             LOWER(BTRIM(COALESCE(candidate_state.effective_summary_fragment_json->>'clone_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           )
           OR COALESCE(
             LOWER(BTRIM(COALESCE(candidate_state.effective_candidate_fragment_json->>'clone_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           )
           OR COALESCE(
             LOWER(BTRIM(COALESCE(scope_row.error_json#>>'{clone_eligibility,clone_certified}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           ),
           (
             scope_row.error_json ? 'clone_eligibility'
             OR LOWER(BTRIM(COALESCE(scope_row.error_json->>'clone_eligibility_failed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR LOWER(BTRIM(COALESCE(scope_row.error_json#>>'{clone_eligibility,clone_eligible}', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off')
           )
    INTO v_candidate_scope_status,
         v_candidate_state_status,
         v_candidate_clone_certified,
         v_candidate_clone_failed
    FROM public.banking_pay_workbench_session_scope AS scope_row
    LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
      ON candidate_state.session_id = scope_row.session_id
     AND candidate_state.candidate_id = scope_row.candidate_id
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = v_candidate_id
    LIMIT 1;

    IF v_candidate_id = ANY(COALESCE(v_skip_candidate_ids, ARRAY[]::uuid[]))
       OR (
         COALESCE(v_candidate_clone_certified, false) IS TRUE
         AND v_candidate_scope_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
         AND COALESCE(v_candidate_state_status, 'READY') IN ('READY', 'READY_EMPTY')
       ) THEN
      v_clone_skipped_ready_count := v_clone_skipped_ready_count + 1;
      IF v_candidate_id = ANY(COALESCE(v_skip_candidate_ids, ARRAY[]::uuid[])) THEN
        v_clone_skip_list_count := v_clone_skip_list_count + 1;
      END IF;
      CONTINUE;
    END IF;

    IF COALESCE(v_clone_rebase_queued, false) IS TRUE
       AND COALESCE(v_candidate_clone_failed, false) IS NOT TRUE THEN
      v_clone_skipped_pending_count := v_clone_skipped_pending_count + 1;
      CONTINUE;
    END IF;

    v_refresh_result := public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session_row.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => v_reason,
      p_actor_user_id => p_actor_user_id,
      p_payload_json => jsonb_build_object(
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'session_signature', v_session_row.session_signature,
        'session_version', COALESCE(v_session_row.version, 0),
        'force_broad_legacy', true,
        'force_legacy', true,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'enqueue_origin', 'SESSION_SCOPE_SEED_OR_PAGE',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'delta_refresh_required', false,
        'source_build_action', 'BUILD_SOURCE',
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_limit', v_source_build_limit,
        'limit', v_source_build_limit,
        'refresh_reason', v_reason,
        'reason', v_reason
      )
    );

    v_job_id_text := NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), '');
    IF v_job_id_text IS NOT NULL THEN
      v_job_ids_jsonb := v_job_ids_jsonb || jsonb_build_array(v_job_id_text);
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_refresh_result->>'source_build_run_id', '')), '') IS NOT NULL THEN
      v_source_build_run_ids_jsonb := v_source_build_run_ids_jsonb || jsonb_build_array(v_refresh_result->>'source_build_run_id');
    END IF;

    IF UPPER(BTRIM(COALESCE(v_refresh_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      v_delta_queued_count := v_delta_queued_count + 1;
    ELSE
      v_legacy_queued_count := v_legacy_queued_count + 1;
    END IF;

    IF LOWER(BTRIM(COALESCE(v_refresh_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_reused_count := v_reused_count + 1;
    ELSE
      v_queued_count := v_queued_count + 1;
    END IF;

    IF NOT (v_candidate_id = ANY(COALESCE(v_enqueued_candidate_ids, ARRAY[]::uuid[]))) THEN
      v_enqueued_candidate_ids := array_append(v_enqueued_candidate_ids, v_candidate_id);
    END IF;
  END LOOP;

  v_enqueued_candidate_count := COALESCE(array_length(v_enqueued_candidate_ids, 1), 0);

  SELECT count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer
  INTO v_previous_ready,
       v_previous_failed,
       v_previous_pending
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = ANY(COALESCE(v_enqueued_candidate_ids, ARRAY[]::uuid[]));

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET scope_pending_count = GREATEST(0, COALESCE(session_update.scope_pending_count, 0) + COALESCE(v_enqueued_candidate_count, 0) - COALESCE(v_previous_pending, 0)),
      scope_ready_count = GREATEST(0, COALESCE(session_update.scope_ready_count, 0) - COALESCE(v_previous_ready, 0)),
      scope_failed_count = GREATEST(0, COALESCE(session_update.scope_failed_count, 0) - COALESCE(v_previous_failed, 0)),
      progress_state = CASE WHEN COALESCE(v_legacy_queued_count, 0) + COALESCE(v_delta_queued_count, 0) > 0 THEN 'REFRESHING_CANDIDATES' ELSE session_update.progress_state END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'phase', 'SOURCE_BUILDING',
        'status_text', 'Preparing payment source rows.',
        'last_source_build_enqueue_count', COALESCE(v_legacy_queued_count, 0),
        'last_delta_enqueue_count', COALESCE(v_delta_queued_count, 0),
        'last_clone_skipped_ready_count', COALESCE(v_clone_skipped_ready_count, 0),
        'last_clone_skipped_pending_count', COALESCE(v_clone_skipped_pending_count, 0),
        'last_clone_skip_list_count', COALESCE(v_clone_skip_list_count, 0),
        'last_clone_rebase_queued', COALESCE(v_clone_rebase_queued, false),
        'last_source_build_queued_count', COALESCE(v_queued_count, 0),
        'last_source_build_reused_count', COALESCE(v_reused_count, 0),
        'last_source_build_enqueue_at_utc', v_now::text,
        'last_source_build_limit', v_source_build_limit,
        'next_recommended_action', 'BUILD_SOURCE_CHUNK'
      ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'reason', v_reason,
    'queued_count', COALESCE(v_queued_count, 0),
    'reused_count', COALESCE(v_reused_count, 0),
    'candidate_count', COALESCE(v_requested_count, 0),
    'legacy_queued_count', COALESCE(v_legacy_queued_count, 0),
    'delta_queued_count', COALESCE(v_delta_queued_count, 0),
    'clone_skipped_ready_count', COALESCE(v_clone_skipped_ready_count, 0),
    'clone_skipped_pending_count', COALESCE(v_clone_skipped_pending_count, 0),
    'clone_skip_list_count', COALESCE(v_clone_skip_list_count, 0),
    'clone_rebase_queued', COALESCE(v_clone_rebase_queued, false),
    'enqueued_candidate_count', COALESCE(v_enqueued_candidate_count, 0),
    'job_ids', COALESCE(v_job_ids_jsonb, '[]'::jsonb),
    'source_build_run_ids', COALESCE(v_source_build_run_ids_jsonb, '[]'::jsonb),
    'session_recompute_job_ids', COALESCE(v_job_ids_jsonb, '[]'::jsonb),
    'requires_new_session', false,
    'source_session_discard_required', false,
    'source_build_required', COALESCE(v_legacy_queued_count, 0) > 0,
    'line_work_required', COALESCE(v_legacy_queued_count, 0) > 0,
    'clone_rebase_deferred', COALESCE(v_clone_skipped_pending_count, 0) > 0,
    'first_stage_job_type', CASE
      WHEN COALESCE(v_legacy_queued_count, 0) > 0 THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN COALESCE(v_delta_queued_count, 0) > 0 THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
      WHEN COALESCE(v_clone_skipped_pending_count, 0) > 0 THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      ELSE NULL::text
    END,
    'source_build_limit', v_source_build_limit
  );
END;
$function$;




DROP FUNCTION IF EXISTS public.pay_workbench_session_get_preview_page(uuid, text, jsonb, integer);


CREATE OR REPLACE FUNCTION public.pay_workbench_session_get_preview_page(p_session_id uuid, p_section text, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_requested_section text := lower(COALESCE(NULLIF(BTRIM(p_section), ''), 'canonical_preview_lines'));
  v_resolved_section text := 'canonical_preview_lines';
  v_cursor_section_raw text := NULL::text;
  v_cursor_resolved_section text := NULL::text;
  v_section_alias_applied boolean := false;
  v_cursor_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_cursor_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_cursor_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_last_row_ordinal bigint := NULL::bigint;
  v_last_id uuid := NULL::uuid;
  v_items jsonb := '[]'::jsonb;
  v_returned_count integer := 0;
  v_raw_count integer := 0;
  v_known_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PAGE');

  v_resolved_section := CASE
    WHEN v_requested_section IN ('', 'canonical_preview_lines', 'ready_to_pay', 'ready_preview_lines', 'preview_rows') THEN 'canonical_preview_lines'
    WHEN v_requested_section IN ('cases_resolutions', 'case_resolution_states', 'case_resolutions', 'cases', 'resolutions') THEN 'cases_resolutions'
    WHEN v_requested_section IN ('blocked_for_pay', 'blocked_items', 'blocked_preview_lines', 'blocked_now', 'do_not_pay_items') THEN 'blocked_for_pay'
    WHEN v_requested_section IN ('drafted', 'drafted_rows') THEN 'drafted'
    ELSE v_requested_section
  END;
  v_section_alias_applied := v_requested_section IS DISTINCT FROM v_resolved_section;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'WORKBENCH_SESSION_NOT_FOUND',
      'code', 'WORKBENCH_SESSION_NOT_FOUND',
      'session_id', p_session_id::text,
      'requested_section', v_requested_section,
      'resolved_section', v_resolved_section,
      'section_alias_applied', v_section_alias_applied,
      'section', v_resolved_section,
      'items', '[]'::jsonb,
      'rows', '[]'::jsonb,
      'next_cursor', NULL::jsonb,
      'returned_count', 0,
      'ready', false,
      'ready_flag', false
    );
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL
     OR v_session_row.replacement_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'OBSOLETE_SESSION',
      'code', 'OBSOLETE_SESSION',
      'session_id', p_session_id::text,
      'session_obsolete', true,
      'replacement_required', true,
      'replacement_session_id', CASE WHEN v_session_row.replacement_session_id IS NULL THEN NULL ELSE v_session_row.replacement_session_id::text END,
      'replacement_available', v_session_row.replacement_session_id IS NOT NULL,
      'requested_section', v_requested_section,
      'resolved_section', v_resolved_section,
      'section_alias_applied', v_section_alias_applied,
      'section', v_resolved_section,
      'items', '[]'::jsonb,
      'rows', '[]'::jsonb,
      'next_cursor', NULL::jsonb,
      'returned_count', 0,
      'ready', false,
      'ready_flag', false
    );
  END IF;

  v_cursor_section_raw := lower(COALESCE(NULLIF(BTRIM(v_cursor_json->>'section'), ''), v_resolved_section));
  v_cursor_resolved_section := CASE
    WHEN v_cursor_section_raw IN ('', 'canonical_preview_lines', 'ready_to_pay', 'ready_preview_lines', 'preview_rows') THEN 'canonical_preview_lines'
    WHEN v_cursor_section_raw IN ('cases_resolutions', 'case_resolution_states', 'case_resolutions', 'cases', 'resolutions') THEN 'cases_resolutions'
    WHEN v_cursor_section_raw IN ('blocked_for_pay', 'blocked_items', 'blocked_preview_lines', 'blocked_now', 'do_not_pay_items') THEN 'blocked_for_pay'
    WHEN v_cursor_section_raw IN ('drafted', 'drafted_rows') THEN 'drafted'
    ELSE v_cursor_section_raw
  END;

  IF v_cursor_json ? 'section' AND v_cursor_resolved_section <> v_resolved_section THEN
    RAISE EXCEPTION 'cursor section % does not match requested section %', COALESCE(v_cursor_json->>'section', ''), v_requested_section;
  END IF;

  IF COALESCE(v_cursor_json->>'last_row_ordinal', '') ~ '^[0-9]+$' THEN
    v_last_row_ordinal := (v_cursor_json->>'last_row_ordinal')::bigint;
  END IF;

  IF COALESCE(v_cursor_json->>'last_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_id := (v_cursor_json->>'last_id')::uuid;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_known_count
  FROM public.banking_pay_workbench_preview_rows AS preview_count_row
  WHERE preview_count_row.session_id = p_session_id
    AND preview_count_row.session_version = v_session_row.version
    AND preview_count_row.section = v_resolved_section
    AND preview_count_row.status = 'READY'
    AND (
      v_resolved_section <> 'canonical_preview_lines'
      OR NOT (
        COALESCE(
          lower(BTRIM(COALESCE(preview_count_row.row_json->>'post_draft_unavailable', '')))
            IN ('true', 't', '1', 'yes', 'y', 'on'),
          false
        )
        OR (
          COALESCE(
            lower(BTRIM(COALESCE(preview_count_row.row_json->>'post_draft_overlay_applied', '')))
              IN ('true', 't', '1', 'yes', 'y', 'on'),
            false
          )
          AND UPPER(BTRIM(COALESCE(preview_count_row.row_json->>'post_draft_overlay_operation_type', '')))
            IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
          AND lower(BTRIM(COALESCE(preview_count_row.row_json->>'post_draft_overlay_active', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off')
        )
      )
    );

  WITH page_rows AS (
    SELECT page_source.*,
           ROW_NUMBER() OVER (ORDER BY page_source.row_ordinal, page_source.id) AS page_ordinal
    FROM (
      SELECT
        preview_row.id,
        preview_row.section,
        preview_row.candidate_id,
        preview_row.row_key,
        preview_row.row_ordinal,
        preview_row.row_json,
        preview_row.timesheet_id,
        preview_row.key_type,
        preview_row.key_value,
        preview_row.selected,
        preview_row.selection_state,
        preview_row.status,
        preview_row.session_version
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = v_session_row.version
        AND preview_row.section = v_resolved_section
        AND preview_row.status = 'READY'
        AND (
          v_resolved_section <> 'canonical_preview_lines'
          OR NOT (
            COALESCE(
              lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_unavailable', '')))
                IN ('true', 't', '1', 'yes', 'y', 'on'),
              false
            )
            OR (
              COALESCE(
                lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', '')))
                  IN ('true', 't', '1', 'yes', 'y', 'on'),
                false
              )
              AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_operation_type', '')))
                IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
              AND lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_active', 'true')))
                NOT IN ('false', 'f', '0', 'no', 'n', 'off')
            )
          )
        )
        AND (
          v_last_row_ordinal IS NULL
          OR preview_row.row_ordinal > v_last_row_ordinal
          OR (
            preview_row.row_ordinal = v_last_row_ordinal
            AND v_last_id IS NOT NULL
            AND preview_row.id > v_last_id
          )
        )
      ORDER BY preview_row.row_ordinal, preview_row.id
      LIMIT (v_limit + 1)
    ) AS page_source
  ), limited_rows AS (
    SELECT page_rows.*
    FROM page_rows
    WHERE page_rows.page_ordinal <= v_limit
  ), normalised_rows AS (
    SELECT
      limited_rows.*,
      base_values.base_json,
      display_values.amount_display_text,
      display_values.section_amount_display_text,
      post_draft_values.post_draft_unavailable_bool,
      bool_values.selection_allowed_bool,
      bool_values.draftable_bool,
      bool_values.ready_for_draft_bool,
      bool_values.excluded_bool,
      bool_values.deduction_bool,
      bool_values.materialisable_bool,
      name_values.candidate_display_name_text,
      name_values.candidate_name_text
    FROM limited_rows
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN jsonb_typeof(limited_rows.row_json) = 'object' THEN limited_rows.row_json
          ELSE '{}'::jsonb
        END AS stored_row_json
    ) AS stored_values
    CROSS JOIN LATERAL (
      SELECT
        stored_values.stored_row_json
        || jsonb_build_object(
          'preview_row_id', limited_rows.id::text,
          'row_id', limited_rows.id::text,
          'section', limited_rows.section,
          'row_key', limited_rows.row_key,
          'row_ordinal', limited_rows.row_ordinal,
          'candidate_id', limited_rows.candidate_id::text,
          'timesheet_id', CASE WHEN limited_rows.timesheet_id IS NULL THEN NULL ELSE limited_rows.timesheet_id::text END,
          'key_type', limited_rows.key_type,
          'key_value', limited_rows.key_value,
          'selected', COALESCE(limited_rows.selected, false),
          'selection_state', limited_rows.selection_state,
          'status', limited_rows.status,
          'session_version', limited_rows.session_version,
          'amount_ex_vat', COALESCE(
            stored_values.stored_row_json->'amount_ex_vat',
            stored_values.stored_row_json->'preview_amount_ex_vat',
            stored_values.stored_row_json->'section_amount_ex_vat',
            'null'::jsonb
          )
        ) AS base_json
    ) AS base_values
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(
          NULLIF(base_values.base_json->>'amount_display', ''),
          NULLIF(base_values.base_json->>'section_amount_display', ''),
          NULLIF(base_values.base_json->>'amount_ex_vat', ''),
          NULLIF(base_values.base_json->>'preview_amount_ex_vat', ''),
          NULLIF(base_values.base_json->>'section_amount_ex_vat', '')
        ) AS amount_display_raw,
        COALESCE(
          NULLIF(base_values.base_json->>'section_amount_display', ''),
          NULLIF(base_values.base_json->>'amount_display', ''),
          NULLIF(base_values.base_json->>'section_amount_ex_vat', ''),
          NULLIF(base_values.base_json->>'amount_ex_vat', ''),
          NULLIF(base_values.base_json->>'preview_amount_ex_vat', '')
        ) AS section_amount_display_raw
    ) AS display_raw_values
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN display_raw_values.amount_display_raw ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN to_char(display_raw_values.amount_display_raw::numeric, 'FM999999999999999990.00')
          ELSE display_raw_values.amount_display_raw
        END AS amount_display_text,
        CASE
          WHEN display_raw_values.section_amount_display_raw ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN to_char(display_raw_values.section_amount_display_raw::numeric, 'FM999999999999999990.00')
          ELSE display_raw_values.section_amount_display_raw
        END AS section_amount_display_text
    ) AS display_values
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(
          lower(BTRIM(COALESCE(base_values.base_json->>'post_draft_unavailable', '')))
            IN ('true', 't', '1', 'yes', 'y', 'on'),
          false
        )
        OR (
          COALESCE(
            lower(BTRIM(COALESCE(base_values.base_json->>'post_draft_overlay_applied', '')))
              IN ('true', 't', '1', 'yes', 'y', 'on'),
            false
          )
          AND UPPER(BTRIM(COALESCE(base_values.base_json->>'post_draft_overlay_operation_type', '')))
            IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
          AND lower(BTRIM(COALESCE(base_values.base_json->>'post_draft_overlay_active', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off')
        ) AS post_draft_unavailable_bool
    ) AS post_draft_values
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN post_draft_values.post_draft_unavailable_bool IS TRUE THEN false
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'selection_allowed'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'selection_allowed'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          WHEN limited_rows.section = 'canonical_preview_lines'
               AND COALESCE(limited_rows.selected, false)
               AND UPPER(BTRIM(COALESCE(limited_rows.selection_state, ''))) = 'SELECTED'
               THEN true
          ELSE false
        END AS selection_allowed_bool,
        CASE
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_excluded_from_allocation'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_excluded_from_allocation'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          ELSE false
        END AS excluded_bool,
        CASE
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_recognised_finance_deduction'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_recognised_finance_deduction'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          ELSE false
        END AS deduction_bool,
        CASE
          WHEN post_draft_values.post_draft_unavailable_bool IS TRUE THEN false
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'materialisable'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'materialisable'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          ELSE limited_rows.status = 'READY'
        END AS materialisable_bool,
        CASE
          WHEN post_draft_values.post_draft_unavailable_bool IS TRUE THEN false
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'draftable'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'draftable'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          WHEN limited_rows.section = 'canonical_preview_lines'
               AND COALESCE(limited_rows.selected, false)
               AND UPPER(BTRIM(COALESCE(limited_rows.selection_state, ''))) = 'SELECTED'
               AND limited_rows.status = 'READY'
               THEN true
          ELSE false
        END AS draftable_bool,
        CASE
          WHEN post_draft_values.post_draft_unavailable_bool IS TRUE THEN false
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_ready_for_draft'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'is_ready_for_draft'), '')) IN ('false', 'f', '0', 'no', 'n') THEN false
          WHEN lower(NULLIF(BTRIM(base_values.base_json->>'draftable'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
          WHEN limited_rows.section = 'canonical_preview_lines'
               AND COALESCE(limited_rows.selected, false)
               AND UPPER(BTRIM(COALESCE(limited_rows.selection_state, ''))) = 'SELECTED'
               AND limited_rows.status = 'READY'
               THEN true
          ELSE false
        END AS ready_for_draft_bool
    ) AS bool_values
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(
          NULLIF(BTRIM(base_values.base_json->>'candidate_display_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'candidate_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'worker_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'worker_display_name'), '')
        ) AS candidate_display_name_text,
        COALESCE(
          NULLIF(BTRIM(base_values.base_json->>'candidate_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'candidate_display_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'worker_name'), ''),
          NULLIF(BTRIM(base_values.base_json->>'worker_display_name'), '')
        ) AS candidate_name_text
    ) AS name_values
  )
  SELECT
    COALESCE(jsonb_agg(
      normalised_rows.base_json
      || jsonb_build_object(
        'amount_display', normalised_rows.amount_display_text,
        'section_amount_display', normalised_rows.section_amount_display_text
      )
      || jsonb_strip_nulls(jsonb_build_object(
        'candidate_display_name', normalised_rows.candidate_display_name_text,
        'candidate_name', normalised_rows.candidate_name_text
      ))
      || jsonb_build_object(
        'selection_allowed', normalised_rows.selection_allowed_bool,
        'draftable', normalised_rows.draftable_bool,
        'is_ready_for_draft', normalised_rows.ready_for_draft_bool,
        'is_excluded_from_allocation', normalised_rows.excluded_bool,
        'is_recognised_finance_deduction', normalised_rows.deduction_bool
      )
      || CASE
        WHEN normalised_rows.post_draft_unavailable_bool IS TRUE THEN jsonb_build_object(
          'post_draft_unavailable', true,
          'presentation_section', 'DRAFTED',
          'readiness_state', 'NOT_SELECTABLE',
          'preview_contract',
            CASE
              WHEN jsonb_typeof(normalised_rows.base_json->'preview_contract') = 'object'
                THEN normalised_rows.base_json->'preview_contract'
              ELSE '{}'::jsonb
            END
            || jsonb_build_object(
              'ok', false,
              'status', 'NOT_SELECTABLE',
              'materialisable', false,
              'selection_allowed', false,
              'draftable', false,
              'is_ready_for_draft', false
            )
        )
        WHEN jsonb_typeof(normalised_rows.base_json->'preview_contract') = 'object' THEN '{}'::jsonb
        ELSE jsonb_build_object(
          'preview_contract',
          jsonb_build_object(
            'ok', true,
            'status', 'OK',
            'reasons', '[]'::jsonb,
            'reason_count', 0,
            'key_type', COALESCE(NULLIF(normalised_rows.base_json->>'key_type', ''), normalised_rows.key_type),
            'key_value', COALESCE(NULLIF(normalised_rows.base_json->>'key_value', ''), normalised_rows.key_value),
            'line_key', COALESCE(NULLIF(normalised_rows.base_json->>'line_key', ''), NULLIF(normalised_rows.base_json->>'row_key', ''), normalised_rows.row_key),
            'case_type', COALESCE(NULLIF(normalised_rows.base_json->>'case_type', ''), 'TIMESHEET_PAYMENT'),
            'line_type', NULLIF(normalised_rows.base_json->>'line_type', ''),
            'source_kind', NULLIF(normalised_rows.base_json->>'source_kind', ''),
            'amount_ex_vat', COALESCE(
              normalised_rows.base_json->'amount_ex_vat',
              normalised_rows.base_json->'preview_amount_ex_vat',
              normalised_rows.base_json->'section_amount_ex_vat',
              'null'::jsonb
            ),
            'materialisable', normalised_rows.materialisable_bool,
            'target_section', COALESCE(NULLIF(normalised_rows.base_json->>'target_section', ''), NULLIF(normalised_rows.base_json->>'section', ''), normalised_rows.section),
            'presentation_section', NULLIF(normalised_rows.base_json->>'presentation_section', ''),
            'selection_allowed', normalised_rows.selection_allowed_bool,
            'draftable', normalised_rows.draftable_bool,
            'is_ready_for_draft', normalised_rows.ready_for_draft_bool,
            'is_excluded_from_allocation', normalised_rows.excluded_bool,
            'is_recognised_finance_deduction', normalised_rows.deduction_bool
          )
        )
      END
      ORDER BY normalised_rows.row_ordinal, normalised_rows.id
    ), '[]'::jsonb),
    COUNT(normalised_rows.id)::integer,
    (SELECT COUNT(*)::integer FROM page_rows),
    CASE
      WHEN (SELECT COUNT(*) FROM page_rows) > v_limit THEN (
        SELECT jsonb_build_object(
          'section', v_resolved_section,
          'last_row_ordinal', cursor_row.row_ordinal,
          'last_id', cursor_row.id::text
        )
        FROM limited_rows AS cursor_row
        ORDER BY cursor_row.row_ordinal DESC, cursor_row.id DESC
        LIMIT 1
      )
      ELSE NULL::jsonb
    END
  INTO v_items,
       v_returned_count,
       v_raw_count,
       v_next_cursor
  FROM normalised_rows;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'requested_section', v_requested_section,
    'resolved_section', v_resolved_section,
    'section_alias_applied', v_section_alias_applied,
    'section', v_resolved_section,
    'items', COALESCE(v_items, '[]'::jsonb),
    'rows', COALESCE(v_items, '[]'::jsonb),
    'known_count', COALESCE(v_known_count, 0),
    'total_count_estimate', COALESCE(v_known_count, 0),
    'returned_count', COALESCE(v_returned_count, 0),
    'next_cursor', v_next_cursor,
    'has_more', v_next_cursor IS NOT NULL
  )
  || jsonb_build_object(
    'limit', v_limit,
    'session_version', v_session_row.version,
    'session_signature', v_session_row.session_signature,
    'ready', true,
    'paging_mode', 'preview_rows_keyset_section_row_ordinal_id'
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.pay_batch_execution_summary_get(uuid, uuid);



DROP FUNCTION IF EXISTS public.pay_batch_execution_summary_get(uuid, uuid);


CREATE OR REPLACE FUNCTION public.pay_batch_execution_summary_get(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_mode text DEFAULT 'LIGHT'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_mode text := upper(btrim(coalesce(p_mode, 'LIGHT')));
  v_batch_row public.pay_batches%ROWTYPE;
  v_display_summary jsonb := '{}'::jsonb;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_active_item_count integer := 0;
  v_total_amount numeric := 0;
  v_transfer_count integer := 0;
  v_transfer_pending_count integer := 0;
  v_transfer_completed_count integer := 0;
  v_transfer_failed_count integer := 0;
  v_transfer_unknown_count integer := 0;
  v_active_operation_id uuid := NULL::uuid;
  v_active_operation_type text := NULL::text;
  v_active_operation_status text := NULL::text;
  v_active_operation_phase text := NULL::text;
  v_runner_state text := NULL::text;
  v_operation_progress_json jsonb := '{}'::jsonb;
  v_scope_count integer := 0;
  v_scope_prepared_count integer := 0;
  v_scope_ready_count integer := 0;
  v_scope_claimed_count integer := 0;
  v_scope_accepted_count integer := 0;
  v_scope_rejected_count integer := 0;
  v_scope_unknown_count integer := 0;
  v_scope_review_count integer := 0;
  v_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_completed_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_signal_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_overview_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_last_status_hash text := NULL::text;
  v_last_alert_hash text := NULL::text;
  v_submission_evidence_json jsonb := '{}'::jsonb;
  v_batch_status_raw text := NULL::text;
  v_batch_status_label text := NULL::text;
  v_batch_terminal_with_failed_payments boolean := false;
  v_pending_bank_outcome_count integer := 0;
  v_unknown_bank_outcome_count integer := 0;
  v_terminal_success_payment_count integer := 0;
  v_terminal_failed_payment_count integer := 0;
  v_payment_outcome_summary jsonb := '{}'::jsonb;
  v_paye_missing_count integer := 0;
  v_paye_zero_count integer := 0;
  v_paye_positive_count integer := 0;
  v_positive_bank_payment_count integer := 0;
  v_positive_bank_payment_total numeric(14,2) := 0;
  v_global_invalid_payment_row_count integer := 0;
  v_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_bank_payment_projection_scope text := 'ALL';
  v_scoped_paye_missing_count integer := 0;
  v_scoped_paye_zero_count integer := 0;
  v_scoped_paye_positive_count integer := 0;
  v_scoped_positive_bank_payment_count integer := 0;
  v_scoped_invalid_payment_row_count integer := 0;
  v_scoped_paye_net_state_hash text := NULL::text;
  v_bank_payment_projection_hash text := NULL::text;
  v_current_bank_payment_row_count integer := 0;
  v_current_bank_payment_total numeric(14,2) := 0;
  v_bank_csv_export_json jsonb := '{}'::jsonb;
  v_bank_csv_generated boolean := false;
  v_bank_csv_current boolean := false;
  v_bank_csv_stale_reason text := NULL::text;
  v_stored_csv_scope_raw text := NULL::text;
  v_stored_csv_scope text := NULL::text;
  v_stored_paye_net_state_hash text := NULL::text;
  v_stored_bank_payment_projection_hash text := NULL::text;
  v_stored_bank_csv_row_count integer := NULL::integer;
  v_stored_bank_csv_total numeric(14,2) := NULL::numeric;
  v_paye_net_preflight jsonb := '{}'::jsonb;
  v_bank_csv_scope_preflight jsonb := '{}'::jsonb;
  v_paye_net_complete boolean := false;
  v_all_required_paye_explicit_zero boolean := false;
  v_has_positive_bank_payments boolean := false;
  v_no_bank_payment_execution_eligible boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('DISPLAY');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_ACTOR_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_ACTOR_NOT_FOUND', 'actor_user_id', p_actor_user_id::text)::text;
    END IF;
  END IF;

  IF v_mode IS NULL OR v_mode = '' THEN
    v_mode := 'LIGHT';
  END IF;

  IF v_mode NOT IN ('LIGHT', 'OPERATION_LIGHT') THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_MODE_NOT_SUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_MODE_NOT_SUPPORTED', 'mode', p_mode)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_EXECUTION_SUMMARY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_EXECUTION_SUMMARY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT to_jsonb(summary_row.*)
  INTO v_display_summary
  FROM public.pay_batch_display_summary AS summary_row
  WHERE summary_row.pay_batch_id = p_pay_batch_id;

  IF v_display_summary IS NULL THEN
    v_display_summary := '{}'::jsonb;
  END IF;

  v_bank_csv_export_json := CASE
    WHEN v_batch_row.bank_csv_export_json IS NOT NULL
     AND JSONB_TYPEOF(v_batch_row.bank_csv_export_json) = 'object'
      THEN v_batch_row.bank_csv_export_json
    ELSE '{}'::jsonb
  END;

  v_bank_csv_generated := v_bank_csv_export_json <> '{}'::jsonb
    AND NULLIF(BTRIM(COALESCE(
      v_bank_csv_export_json->>'generated_at_utc',
      v_bank_csv_export_json->>'generatedAtUtc',
      v_bank_csv_export_json->>'filename',
      v_bank_csv_export_json->>'bank_payment_projection_hash',
      v_bank_csv_export_json->>'transfer_hash',
      ''
    )), '') IS NOT NULL;

  v_stored_csv_scope_raw := UPPER(NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'scope',
    v_bank_csv_export_json->>'pay_channel_scope',
    v_bank_csv_export_json->>'payChannelScope',
    ''
  )), ''));

  IF v_stored_csv_scope_raw IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS') THEN
    v_stored_csv_scope := v_stored_csv_scope_raw;
  ELSE
    v_stored_csv_scope := NULL::text;
  END IF;

  v_bank_payment_projection_scope := COALESCE(v_stored_csv_scope, 'ALL');
  v_stored_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'paye_net_state_hash',
    v_bank_csv_export_json->>'current_paye_net_state_hash',
    v_bank_csv_export_json->>'payeNetStateHash',
    ''
  )), '');
  v_stored_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_bank_csv_export_json->>'bank_payment_projection_hash',
    v_bank_csv_export_json->>'current_bank_payment_projection_hash',
    v_bank_csv_export_json->>'bankPaymentProjectionHash',
    ''
  )), '');

  IF COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount', '') ~ '^[0-9]+$' THEN
    v_stored_bank_csv_row_count := COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount')::integer;
  END IF;

  IF COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_stored_bank_csv_total := ROUND(COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount')::numeric, 2)::numeric(14,2);
  END IF;

  WITH global_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      'ALL'
    ) AS projection_row
  ), global_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS paye_missing_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS paye_zero_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'POSITIVE'
      )::integer AS paye_positive_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_bank_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_bank_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM global_projection_rows AS projection_row
  ), scoped_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_bank_payment_projection_scope
    ) AS projection_row
  ), scoped_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS paye_missing_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS paye_zero_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'POSITIVE'
      )::integer AS paye_positive_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_bank_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_bank_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM scoped_projection_rows AS projection_row
  )
  SELECT
    COALESCE(global_projection_summary.paye_missing_count, 0),
    COALESCE(global_projection_summary.paye_zero_count, 0),
    COALESCE(global_projection_summary.paye_positive_count, 0),
    COALESCE(global_projection_summary.positive_bank_payment_count, 0),
    COALESCE(global_projection_summary.positive_bank_payment_total, 0),
    COALESCE(global_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      global_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      global_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(scoped_projection_summary.paye_missing_count, 0),
    COALESCE(scoped_projection_summary.paye_zero_count, 0),
    COALESCE(scoped_projection_summary.paye_positive_count, 0),
    COALESCE(scoped_projection_summary.positive_bank_payment_count, 0),
    COALESCE(scoped_projection_summary.positive_bank_payment_total, 0),
    COALESCE(scoped_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      scoped_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_bank_payment_projection_scope,
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      scoped_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_bank_payment_projection_scope,
        'rows', '[]'::jsonb
      )::text)
    )
  INTO
    v_paye_missing_count,
    v_paye_zero_count,
    v_paye_positive_count,
    v_positive_bank_payment_count,
    v_positive_bank_payment_total,
    v_global_invalid_payment_row_count,
    v_paye_net_state_hash,
    v_all_bank_payment_projection_hash,
    v_scoped_paye_missing_count,
    v_scoped_paye_zero_count,
    v_scoped_paye_positive_count,
    v_scoped_positive_bank_payment_count,
    v_current_bank_payment_total,
    v_scoped_invalid_payment_row_count,
    v_scoped_paye_net_state_hash,
    v_bank_payment_projection_hash
  FROM global_projection_summary
  CROSS JOIN scoped_projection_summary;

  v_paye_missing_count := COALESCE(v_paye_missing_count, 0);
  v_paye_zero_count := COALESCE(v_paye_zero_count, 0);
  v_paye_positive_count := COALESCE(v_paye_positive_count, 0);
  v_positive_bank_payment_count := COALESCE(v_positive_bank_payment_count, 0);
  v_positive_bank_payment_total := ROUND(COALESCE(v_positive_bank_payment_total, 0), 2);
  v_global_invalid_payment_row_count := COALESCE(v_global_invalid_payment_row_count, 0);
  v_scoped_paye_missing_count := COALESCE(v_scoped_paye_missing_count, 0);
  v_scoped_paye_zero_count := COALESCE(v_scoped_paye_zero_count, 0);
  v_scoped_paye_positive_count := COALESCE(v_scoped_paye_positive_count, 0);
  v_scoped_positive_bank_payment_count := COALESCE(v_scoped_positive_bank_payment_count, 0);
  v_scoped_invalid_payment_row_count := COALESCE(v_scoped_invalid_payment_row_count, 0);
  v_current_bank_payment_row_count := v_scoped_positive_bank_payment_count;
  v_current_bank_payment_total := ROUND(COALESCE(v_current_bank_payment_total, 0), 2);

  v_paye_net_complete := v_paye_missing_count = 0;
  v_all_required_paye_explicit_zero := (
    v_paye_missing_count = 0
    AND v_paye_zero_count > 0
    AND v_paye_positive_count = 0
  );
  v_has_positive_bank_payments := v_positive_bank_payment_count > 0;
  v_no_bank_payment_execution_eligible := (
    v_paye_missing_count = 0
    AND v_paye_zero_count > 0
    AND v_positive_bank_payment_count = 0
    AND v_global_invalid_payment_row_count = 0
  );

  v_paye_net_preflight := JSONB_BUILD_OBJECT(
    'scope', 'ALL',
    'missing_explicit_paye_input_count', v_paye_missing_count,
    'explicit_zero_count', v_paye_zero_count,
    'positive_paye_count', v_paye_positive_count,
    'positive_bank_payment_count', v_positive_bank_payment_count,
    'positive_total', v_positive_bank_payment_total,
    'invalid_payment_row_count', v_global_invalid_payment_row_count,
    'paye_net_state_hash', v_paye_net_state_hash,
    'bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'no_bank_payment_execution_eligible', v_no_bank_payment_execution_eligible
  );

  v_bank_csv_scope_preflight := JSONB_BUILD_OBJECT(
    'scope', v_bank_payment_projection_scope,
    'missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'explicit_zero_count', v_scoped_paye_zero_count,
    'positive_paye_count', v_scoped_paye_positive_count,
    'positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'positive_total', v_current_bank_payment_total,
    'invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_hash', v_bank_payment_projection_hash
  );

  IF v_bank_csv_generated IS NOT TRUE THEN
    v_bank_csv_stale_reason := 'CSV_NOT_GENERATED';
  ELSIF v_stored_csv_scope IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_SCOPE_INVALID';
  ELSIF v_scoped_paye_missing_count > 0 THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_REQUIRED';
  ELSIF v_scoped_invalid_payment_row_count > 0 THEN
    v_bank_csv_stale_reason := 'CSV_PAYMENT_PROJECTION_INVALID';
  ELSIF v_stored_paye_net_state_hash IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_STATE_HASH_MISSING';
  ELSIF v_stored_bank_payment_projection_hash IS NULL THEN
    v_bank_csv_stale_reason := 'CSV_BANK_PAYMENT_PROJECTION_HASH_MISSING';
  ELSIF v_stored_paye_net_state_hash <> v_scoped_paye_net_state_hash THEN
    v_bank_csv_stale_reason := 'CSV_PAYE_NET_STATE_CHANGED';
  ELSIF v_stored_bank_payment_projection_hash <> v_bank_payment_projection_hash THEN
    v_bank_csv_stale_reason := 'CSV_BANK_PAYMENT_PROJECTION_CHANGED';
  ELSIF v_stored_bank_csv_row_count IS NOT NULL
    AND v_stored_bank_csv_row_count <> v_current_bank_payment_row_count THEN
    v_bank_csv_stale_reason := 'CSV_ROW_COUNT_CHANGED';
  ELSIF v_stored_bank_csv_total IS NOT NULL
    AND ROUND(v_stored_bank_csv_total, 2) <> ROUND(v_current_bank_payment_total, 2) THEN
    v_bank_csv_stale_reason := 'CSV_TOTAL_CHANGED';
  ELSE
    v_bank_csv_stale_reason := NULL::text;
  END IF;

  v_bank_csv_current := v_bank_csv_generated AND v_bank_csv_stale_reason IS NULL;

  SELECT operation_row.id,
         operation_row.operation_type,
         operation_row.status,
         operation_row.phase,
         operation_row.runner_state,
         coalesce(operation_row.progress_json, '{}'::jsonb)
  INTO v_active_operation_id,
       v_active_operation_type,
       v_active_operation_status,
       v_active_operation_phase,
       v_runner_state,
       v_operation_progress_json
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
    AND upper(btrim(coalesce(operation_row.status, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED')
    AND NOT (
      upper(btrim(coalesce(operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE'
      AND (
        lower(btrim(coalesce(operation_row.input_json->>'prepare_bank_csv_export_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR upper(btrim(coalesce(operation_row.input_json->>'execution_mode', ''))) = 'BANK_CSV_EXPORT_PREPARE'
        OR btrim(coalesce(operation_row.input_json->>'source', '')) = 'handleBankingPayBatchExportCsv'
        OR lower(coalesce(operation_row.idempotency_key, '')) LIKE 'bank-csv-export-prepare:%'
      )
    )
  ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
           operation_row.created_at_utc DESC NULLS LAST,
           operation_row.id DESC
  LIMIT 1;

  SELECT coalesce(signal_row.version, 0),
         coalesce(signal_row.payment_status_version, 0),
         coalesce(signal_row.overview_version, 0),
         coalesce(signal_row.correction_progress_version, 0),
         coalesce(signal_row.alert_version, 0),
         signal_row.last_status_hash,
         signal_row.last_alert_hash
  INTO v_signal_version,
       v_payment_status_version,
       v_overview_version,
       v_correction_progress_version,
       v_alert_version,
       v_last_status_hash,
       v_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS signal_row
  WHERE signal_row.pay_batch_id = p_pay_batch_id;

  SELECT
    CASE WHEN coalesce(v_display_summary->>'candidate_count', v_display_summary->>'pay_batch_candidate_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'candidate_count', v_display_summary->>'pay_batch_candidate_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'item_count', v_display_summary->>'pay_batch_item_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'item_count', v_display_summary->>'pay_batch_item_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'active_item_count', v_display_summary->>'payable_item_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'active_item_count', v_display_summary->>'payable_item_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'total_amount', v_display_summary->>'total_bank_out', v_display_summary->>'amount_total', '0') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN coalesce(v_display_summary->>'total_amount', v_display_summary->>'total_bank_out', v_display_summary->>'amount_total')::numeric ELSE 0::numeric END,
    CASE WHEN coalesce(v_display_summary->>'transfer_count', v_display_summary->>'bank_transfer_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'transfer_count', v_display_summary->>'bank_transfer_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'pending_transfer_count', v_display_summary->>'transfer_pending_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'pending_transfer_count', v_display_summary->>'transfer_pending_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'completed_transfer_count', v_display_summary->>'transfer_completed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'completed_transfer_count', v_display_summary->>'transfer_completed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'failed_transfer_count', v_display_summary->>'transfer_failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'failed_transfer_count', v_display_summary->>'transfer_failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_display_summary->>'unknown_transfer_count', v_display_summary->>'transfer_unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_display_summary->>'unknown_transfer_count', v_display_summary->>'transfer_unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_count', v_operation_progress_json->>'scope_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_count', v_operation_progress_json->>'scope_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_prepared_count', v_operation_progress_json->>'scope_prepared_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_prepared_count', v_operation_progress_json->>'scope_prepared_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_provider_ready_count', v_operation_progress_json->>'remaining_ready_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_provider_ready_count', v_operation_progress_json->>'remaining_ready_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_claimed_count', v_operation_progress_json->>'claimed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_claimed_count', v_operation_progress_json->>'claimed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_accepted_count', v_operation_progress_json->>'accepted_count', v_operation_progress_json->>'last_rail_update_accepted_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_accepted_count', v_operation_progress_json->>'accepted_count', v_operation_progress_json->>'last_rail_update_accepted_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_rejected_count', v_operation_progress_json->>'failed_count', v_operation_progress_json->>'last_rail_update_failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_rejected_count', v_operation_progress_json->>'failed_count', v_operation_progress_json->>'last_rail_update_failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_unknown_count', v_operation_progress_json->>'unknown_count', v_operation_progress_json->>'last_rail_update_unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_unknown_count', v_operation_progress_json->>'unknown_count', v_operation_progress_json->>'last_rail_update_unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'operation_scope_review_required_count', v_operation_progress_json->>'review_required_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_operation_progress_json->>'operation_scope_review_required_count', v_operation_progress_json->>'review_required_count')::integer WHEN v_active_operation_status = 'REVIEW_REQUIRED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'pending_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'pending_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'running_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'running_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'completed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'completed_chunk_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_operation_progress_json->>'failed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_operation_progress_json->>'failed_chunk_count')::integer ELSE 0 END
  INTO v_candidate_count,
       v_item_count,
       v_active_item_count,
       v_total_amount,
       v_transfer_count,
       v_transfer_pending_count,
       v_transfer_completed_count,
       v_transfer_failed_count,
       v_transfer_unknown_count,
       v_scope_count,
       v_scope_prepared_count,
       v_scope_ready_count,
       v_scope_claimed_count,
       v_scope_accepted_count,
       v_scope_rejected_count,
       v_scope_unknown_count,
       v_scope_review_count,
       v_chunk_count,
       v_pending_chunk_count,
       v_running_chunk_count,
       v_completed_chunk_count,
       v_failed_chunk_count;


  v_batch_status_raw := v_batch_row.status;

  WITH transfer_classification AS (
    SELECT
      transfer_row.id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
          OR (
            transfer_row.completed_at_utc IS NOT NULL
            AND UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            AND UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN 'TERMINAL_SUCCESS'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          THEN 'TERMINAL_FAILED'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          THEN 'UNKNOWN'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
          OR UPPER(BTRIM(COALESCE(
            transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
            transfer_row.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
            transfer_row.rail_meta_json ->> 'provider_submission_status',
            ''
          ))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
          THEN 'PENDING'
        ELSE 'UNKNOWN'
      END AS terminal_class
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_SUCCESS')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_FAILED')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'UNKNOWN')::integer
  INTO
    v_transfer_count,
    v_pending_bank_outcome_count,
    v_terminal_success_payment_count,
    v_terminal_failed_payment_count,
    v_unknown_bank_outcome_count
  FROM transfer_classification;

  v_transfer_pending_count := COALESCE(v_pending_bank_outcome_count, 0);
  v_transfer_completed_count := COALESCE(v_terminal_success_payment_count, 0);
  v_transfer_failed_count := COALESCE(v_terminal_failed_payment_count, 0);
  v_transfer_unknown_count := COALESCE(v_unknown_bank_outcome_count, 0);
  v_batch_terminal_with_failed_payments := UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) = 'FAILED';
  v_batch_status_label := public._pay_batch_status_display_label(
    v_batch_status_raw,
    COALESCE(v_pending_bank_outcome_count, 0),
    COALESCE(v_unknown_bank_outcome_count, 0)
  );
  v_payment_outcome_summary := jsonb_build_object(
    'batch_status_raw', v_batch_status_raw,
    'batch_status_label', v_batch_status_label,
    'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
    'transfer_count', COALESCE(v_transfer_count, 0),
    'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
    'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
    'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
    'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
    'all_transfers_terminal', (
      COALESCE(v_transfer_count, 0) > 0
      AND COALESCE(v_pending_bank_outcome_count, 0) = 0
      AND COALESCE(v_unknown_bank_outcome_count, 0) = 0
      AND (COALESCE(v_terminal_success_payment_count, 0) + COALESCE(v_terminal_failed_payment_count, 0)) = COALESCE(v_transfer_count, 0)
    )
  );

  v_submission_evidence_json := jsonb_build_object(
    'operation_light', true,
    'submitted_count', coalesce(v_scope_claimed_count, 0) + coalesce(v_scope_accepted_count, 0) + coalesce(v_scope_rejected_count, 0) + coalesce(v_scope_unknown_count, 0),
    'accepted_count', coalesce(v_scope_accepted_count, 0),
    'failed_count', coalesce(v_scope_rejected_count, 0),
    'unknown_count', coalesce(v_scope_unknown_count, 0),
    'review_required_count', coalesce(v_scope_review_count, 0),
    'remaining_ready_count', coalesce(v_scope_ready_count, 0),
    'last_provider_message', coalesce(v_operation_progress_json->>'last_provider_message', v_operation_progress_json->>'provider_submission_status')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', v_mode,
    'light_mode', true,
    'pay_batch_id', p_pay_batch_id::text,
    'batch_id', p_pay_batch_id::text,
    'batch_status', v_batch_row.status,
    'status', v_batch_row.status,
    'batch_status_raw', v_batch_status_raw,
    'batch_status_label', v_batch_status_label,
    'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
    'payment_outcome_summary', COALESCE(v_payment_outcome_summary, '{}'::jsonb),
    'batch_kind_fixed', v_batch_row.batch_kind_fixed,
    'rail_provider_snapshot', v_batch_row.rail_provider_snapshot,
    'rail_env_snapshot', v_batch_row.rail_env_snapshot,
    'execution_commit_state', v_batch_row.execution_commit_state,
    'execution_commit_ref_present', nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
    'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END,
    'freshness_validation_status', v_batch_row.freshness_validation_status,
    'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
    'freshness_result_hash', v_batch_row.freshness_result_hash,
    'display_summary', coalesce(v_display_summary, '{}'::jsonb),
    'candidate_count', coalesce(v_candidate_count, 0),
    'item_count', coalesce(v_item_count, 0),
    'active_item_count', coalesce(v_active_item_count, 0),
    'total_amount', coalesce(v_total_amount, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'pending_transfer_count', coalesce(v_transfer_pending_count, 0),
    'completed_transfer_count', coalesce(v_transfer_completed_count, 0),
    'failed_transfer_count', coalesce(v_transfer_failed_count, 0),
    'unknown_transfer_count', coalesce(v_transfer_unknown_count, 0),
    'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
    'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
    'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
    'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0)
  ) || jsonb_build_object(
    'active_operation_id', CASE WHEN v_active_operation_id IS NULL THEN NULL ELSE v_active_operation_id::text END,
    'active_operation_type', v_active_operation_type,
    'active_operation_status', v_active_operation_status,
    'active_operation_phase', v_active_operation_phase,
    'runner_state', v_runner_state,
    'operation_progress', coalesce(v_operation_progress_json, '{}'::jsonb),
    'operation_scope_count', coalesce(v_scope_count, 0),
    'operation_scope_prepared_count', coalesce(v_scope_prepared_count, 0),
    'operation_scope_provider_ready_count', coalesce(v_scope_ready_count, 0),
    'operation_scope_claimed_count', coalesce(v_scope_claimed_count, 0),
    'operation_scope_accepted_count', coalesce(v_scope_accepted_count, 0),
    'operation_scope_rejected_count', coalesce(v_scope_rejected_count, 0),
    'operation_scope_unknown_count', coalesce(v_scope_unknown_count, 0),
    'operation_scope_review_required_count', coalesce(v_scope_review_count, 0),
    'chunk_count', coalesce(v_chunk_count, 0),
    'pending_chunk_count', coalesce(v_pending_chunk_count, 0),
    'running_chunk_count', coalesce(v_running_chunk_count, 0),
    'completed_chunk_count', coalesce(v_completed_chunk_count, 0),
    'failed_chunk_count', coalesce(v_failed_chunk_count, 0),
    'submission_evidence', v_submission_evidence_json,
    'live_signal_version', coalesce(v_signal_version, 0),
    'payment_status_version', coalesce(v_payment_status_version, 0),
    'overview_version', coalesce(v_overview_version, 0),
    'correction_progress_version', coalesce(v_correction_progress_version, 0),
    'alert_version', coalesce(v_alert_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'classification_called', false,
    'cancelability_called', false,
    'correction_plan_called', false,
    'provider_diagnostic_called', false,
    'mail_outbox_scanned', false
  ) || jsonb_build_object(
    'paye_net_preflight', v_paye_net_preflight,
    'global_execute_preflight', v_paye_net_preflight,
    'bank_csv_scope_preflight', v_bank_csv_scope_preflight,
    'paye_net_complete', v_paye_net_complete,
    'all_required_paye_explicit_zero', v_all_required_paye_explicit_zero,
    'has_positive_bank_payments', v_has_positive_bank_payments,
    'no_bank_payment_execution_eligible', v_no_bank_payment_execution_eligible,
    'global_invalid_payment_row_count', v_global_invalid_payment_row_count,
    'scoped_invalid_payment_row_count', v_scoped_invalid_payment_row_count,
    'global_missing_explicit_paye_input_count', v_paye_missing_count,
    'global_explicit_zero_count', v_paye_zero_count,
    'global_positive_paye_count', v_paye_positive_count,
    'global_positive_bank_payment_count', v_positive_bank_payment_count,
    'global_positive_bank_payment_total', v_positive_bank_payment_total,
    'scoped_missing_explicit_paye_input_count', v_scoped_paye_missing_count,
    'scoped_explicit_zero_count', v_scoped_paye_zero_count,
    'scoped_positive_paye_count', v_scoped_paye_positive_count,
    'scoped_positive_bank_payment_count', v_scoped_positive_bank_payment_count,
    'paye_net_state_hash', v_paye_net_state_hash,
    'global_paye_net_state_hash', v_paye_net_state_hash,
    'current_paye_net_state_hash', v_paye_net_state_hash,
    'scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'current_scoped_paye_net_state_hash', v_scoped_paye_net_state_hash,
    'bank_payment_projection_scope', v_bank_payment_projection_scope,
    'bank_payment_projection_hash', v_bank_payment_projection_hash,
    'current_bank_payment_projection_hash', v_bank_payment_projection_hash,
    'all_scope_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'global_bank_payment_projection_hash', v_all_bank_payment_projection_hash
  ) || jsonb_build_object(
    'current_bank_payment_row_count', v_current_bank_payment_row_count,
    'current_bank_payment_total', v_current_bank_payment_total,
    'bank_csv_generated', v_bank_csv_generated,
    'bank_csv_current', v_bank_csv_current,
    'bank_csv_stale_reason', v_bank_csv_stale_reason,
    'bank_csv_scope', v_stored_csv_scope,
    'stored_paye_net_state_hash', v_stored_paye_net_state_hash,
    'stored_bank_payment_projection_hash', v_stored_bank_payment_projection_hash,
    'stored_bank_csv_row_count', v_stored_bank_csv_row_count,
    'stored_bank_csv_total', v_stored_bank_csv_total,
    'bank_csv_export_json', v_bank_csv_export_json
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_execute_bank_transfer_chunk_prepare(uuid, uuid, jsonb, uuid);


DROP FUNCTION IF EXISTS public.pay_execute_bank_transfer_chunk_prepare(uuid, uuid, jsonb, uuid);



CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_chunk_prepare(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_transfer_scope_ids jsonb,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_chunk_id uuid := NULL::uuid;
  v_limit integer := 25;
  v_requested_count integer := 0;
  v_prepared_count integer := 0;
  v_reused_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_exists boolean := false;
  v_authorisation_ready_count integer := 0;
  v_item_transfer_linked_count integer := 0;
  v_item_transfer_reused_count integer := 0;
  v_item_transfer_conflict_count integer := 0;
  v_execution_mode_raw text := NULL::text;
  v_execution_mode text := NULL::text;
  v_is_local_manual_mode boolean := false;
  v_pay_channel_scope text := 'ALL';
  v_manual_confirmation_mode text := NULL::text;
  v_csv_uploaded_confirmed boolean := false;
  v_csv_bank_confirm_ref text := NULL::text;
  v_bank_csv_generated boolean := false;
  v_bank_csv_current boolean := false;
  v_bank_csv_scope text := NULL::text;
  v_bank_csv_paye_net_state_hash text := NULL::text;
  v_bank_csv_bank_payment_projection_hash text := NULL::text;
  v_bank_csv_row_count integer := NULL::integer;
  v_bank_csv_total_amount numeric(14,2) := NULL::numeric;
  v_external_settlement_comment text := NULL::text;
  v_payment_date text := NULL::text;
  v_mode_evidence_ready boolean := true;
  v_mode_evidence_code text := NULL::text;
  v_mode_evidence_message text := NULL::text;
  v_provider_scope_evidence_count integer := 0;
  v_provider_attempt_row_count integer := 0;
  v_provider_transfer_event_count integer := 0;
  v_provider_transfer_evidence_count integer := 0;
  v_provider_submit_chunk_count integer := 0;
  v_provider_boundary_evidence_count integer := 0;
  v_next_required_phase text := NULL::text;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_ACTOR_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  v_execution_mode_raw := upper(btrim(coalesce(v_operation_row.input_json->>'execution_mode', '')));
  v_execution_mode := CASE
    WHEN v_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE NULL::text
  END;

  IF v_execution_mode IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_EXECUTION_MODE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_EXECUTION_MODE_INVALID',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode_raw', NULLIF(v_execution_mode_raw, ''),
        'message', 'The durable payment execution mode is missing or unsupported.'
      )::text;
  END IF;

  v_is_local_manual_mode := v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT');
  v_pay_channel_scope := upper(btrim(coalesce(NULLIF(v_operation_row.input_json->>'pay_channel_scope', ''), 'ALL')));
  IF v_pay_channel_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;
  v_manual_confirmation_mode := upper(NULLIF(btrim(coalesce(v_operation_row.input_json->>'manual_confirmation_mode', '')), ''));
  v_csv_uploaded_confirmed := lower(btrim(coalesce(v_operation_row.input_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_csv_bank_confirm_ref := NULLIF(btrim(coalesce(v_operation_row.input_json->>'csv_bank_confirm_ref', '')), '');
  v_bank_csv_generated := lower(btrim(coalesce(v_operation_row.input_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_bank_csv_current := lower(btrim(coalesce(v_operation_row.input_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_bank_csv_scope := upper(NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_scope', '')), ''));
  v_bank_csv_paye_net_state_hash := NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_paye_net_state_hash', '')), '');
  v_bank_csv_bank_payment_projection_hash := NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_bank_payment_projection_hash', '')), '');
  IF coalesce(v_operation_row.input_json->>'bank_csv_row_count', '') ~ '^[0-9]+$' THEN
    v_bank_csv_row_count := (v_operation_row.input_json->>'bank_csv_row_count')::integer;
  END IF;
  IF coalesce(v_operation_row.input_json->>'bank_csv_total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_bank_csv_total_amount := round((v_operation_row.input_json->>'bank_csv_total_amount')::numeric, 2)::numeric(14,2);
  END IF;
  v_external_settlement_comment := NULLIF(btrim(coalesce(v_operation_row.input_json->>'external_settlement_comment', '')), '');
  v_payment_date := NULLIF(btrim(coalesce(v_operation_row.input_json->>'payment_date', '')), '');

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF v_is_local_manual_mode THEN
    SELECT count(*)::integer
    INTO v_provider_scope_evidence_count
    FROM public.banking_pay_operation_transfer_scope AS provider_scope
    WHERE provider_scope.operation_id = p_operation_id
      AND provider_scope.pay_batch_id = p_pay_batch_id
      AND (
        coalesce(provider_scope.provider_submit_ready, false) = true
        OR upper(btrim(coalesce(provider_scope.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
        OR provider_scope.provider_submit_chunk_id IS NOT NULL
        OR provider_scope.provider_submit_claimed_at_utc IS NOT NULL
        OR coalesce(provider_scope.provider_submit_attempt_count, 0) > 0
        OR NULLIF(btrim(coalesce(provider_scope.provider_idempotency_key, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_transaction_id, '')), '') IS NOT NULL
        OR provider_scope.provider_request_prepared_at_utc IS NOT NULL
        OR provider_scope.provider_request_sending_at_utc IS NOT NULL
        OR provider_scope.provider_request_sent_at_utc IS NOT NULL
        OR provider_scope.provider_response_at_utc IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_submission_status, '')), '') IS NOT NULL
      );

    SELECT count(*)::integer
    INTO v_provider_attempt_row_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt
    WHERE provider_attempt.operation_id = p_operation_id
       OR provider_attempt.pay_batch_id = p_pay_batch_id;

    SELECT count(*)::integer
    INTO v_provider_transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE transfer_event.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(transfer_event.event_source, ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
        OR NULLIF(btrim(coalesce(transfer_event.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_event.provider_transaction_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_event.provider_event_id, '')), '') IS NOT NULL
        OR transfer_event.provider_webhook_receipt_id IS NOT NULL
      );

    SELECT count(*)::integer
    INTO v_provider_transfer_evidence_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(transfer_row.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED')
        OR NULLIF(btrim(coalesce(transfer_row.request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        OR transfer_row.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(transfer_row.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
        OR upper(btrim(coalesce(transfer_row.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
        OR upper(btrim(coalesce(transfer_row.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
        OR NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), '') IS NOT NULL
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      );

    SELECT count(*)::integer
    INTO v_provider_submit_chunk_count
    FROM public.banking_pay_operation_chunks AS provider_chunk
    WHERE provider_chunk.operation_id = p_operation_id
      AND (
        upper(btrim(coalesce(provider_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
        OR upper(btrim(coalesce(provider_chunk.phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND', 'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES')
      );

    v_provider_boundary_evidence_count := coalesce(v_provider_scope_evidence_count, 0)
      + coalesce(v_provider_attempt_row_count, 0)
      + coalesce(v_provider_transfer_event_count, 0)
      + coalesce(v_provider_transfer_evidence_count, 0)
      + coalesce(v_provider_submit_chunk_count, 0);

    IF v_provider_boundary_evidence_count > 0 THEN
      UPDATE public.banking_pay_operations AS operation_review
      SET status = 'REVIEW_REQUIRED',
          phase = 'REVIEW_REQUIRED',
          runner_state = 'WAITING_USER_REVIEW',
          requires_user_action = true,
          resume_reason = 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
          progress_json = jsonb_strip_nulls(coalesce(operation_review.progress_json, '{}'::jsonb) || jsonb_build_object(
            'execution_mode', v_execution_mode,
            'provider_submission_required', false,
            'provider_submission_attempted', false,
            'submitted_to_bank', false,
            'review_required', true,
            'review_reason_code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
            'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
            'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
            'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
            'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
            'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
            'provider_boundary_evidence_count', v_provider_boundary_evidence_count,
            'next_required_phase', 'REVIEW_REQUIRED',
            'review_required_at_utc', v_now::text
          )),
          error_json = jsonb_strip_nulls(coalesce(operation_review.error_json, '{}'::jsonb) || jsonb_build_object(
            'code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
            'message', 'Local/manual settlement cannot continue because provider or bank-dispatch evidence already exists.',
            'operation_id', p_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'execution_mode', v_execution_mode,
            'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
            'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
            'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
            'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
            'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
            'detected_at_utc', v_now::text
          )),
          updated_at_utc = v_now
      WHERE operation_review.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'hard_blocker', true,
        'code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
        'message', 'Local/manual settlement cannot continue because provider or bank-dispatch evidence already exists.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode,
        'provider_submission_required', false,
        'provider_submission_attempted', false,
        'submitted_to_bank', false,
        'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
        'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
        'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
        'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
        'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
        'provider_boundary_evidence_count', v_provider_boundary_evidence_count,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
    END IF;

    IF v_execution_mode = 'CSV_SETTLEMENT' THEN
      v_mode_evidence_ready := v_bank_csv_generated
        AND v_bank_csv_current
        AND v_csv_uploaded_confirmed
        AND v_csv_bank_confirm_ref IS NOT NULL
        AND v_manual_confirmation_mode = 'BANK_UPLOAD_CONFIRMED'
        AND v_bank_csv_scope IS NOT DISTINCT FROM v_pay_channel_scope
        AND v_bank_csv_paye_net_state_hash IS NOT NULL
        AND v_bank_csv_bank_payment_projection_hash IS NOT NULL
        AND coalesce(v_bank_csv_row_count, 0) > 0
        AND coalesce(v_bank_csv_total_amount, 0) > 0
        AND v_payment_date IS NOT NULL;
      v_mode_evidence_code := 'CSV_SETTLEMENT_PROOF_REQUIRED';
      v_mode_evidence_message := 'CSV settlement requires the current CloudTMS CSV proof, upload confirmation, bank reference, and payment date before transfer evidence can be prepared.';
    ELSIF v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
      v_mode_evidence_ready := v_external_settlement_comment IS NOT NULL
        AND v_manual_confirmation_mode = 'EXTERNAL_SETTLEMENT_CONFIRMED'
        AND v_payment_date IS NOT NULL;
      v_mode_evidence_code := 'EXTERNAL_SETTLEMENT_CONFIRMATION_REQUIRED';
      v_mode_evidence_message := 'External settlement requires the frozen external/manual confirmation comment, confirmation mode, and payment date before transfer evidence can be prepared.';
    END IF;

  END IF;

  IF p_transfer_scope_ids IS NOT NULL AND jsonb_typeof(p_transfer_scope_ids) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_PAYLOAD_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_PAYLOAD_DISABLED',
        'operation_id', p_operation_id::text,
        'message', 'Transfer chunk prepare is row-backed and chunk-owned. Pass a JSON object with chunk_id, or omit p_transfer_scope_ids so the database claims the next bounded scope page. Array/scalar transfer-scope payloads are disabled.'
      )::text;
  END IF;

  IF p_transfer_scope_ids IS NOT NULL AND jsonb_typeof(p_transfer_scope_ids) = 'object' THEN
    IF COALESCE(nullif(btrim(coalesce(p_transfer_scope_ids->>'chunk_id', p_transfer_scope_ids->>'chunkId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_ID_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
          'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_ID_REQUIRED',
          'operation_id', p_operation_id::text,
          'message', 'When p_transfer_scope_ids is supplied, it must be a JSON object containing a valid chunk_id. Omit p_transfer_scope_ids to let the database claim the next bounded scope page.'
        )::text;
    END IF;

    v_chunk_id := coalesce(p_transfer_scope_ids->>'chunk_id', p_transfer_scope_ids->>'chunkId')::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_scope_request;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_scope_request (
    transfer_scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  IF v_chunk_id IS NOT NULL THEN
    SELECT chunk_row.*
    INTO v_chunk_row
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = v_chunk_id
      AND chunk_row.operation_id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_NOT_FOUND', 'operation_id', p_operation_id::text, 'chunk_id', v_chunk_id::text)::text;
    END IF;

    INSERT INTO pg_temp.tmp_prepare_scope_request (transfer_scope_id)
    SELECT DISTINCT scope_text.transfer_scope_id_text::uuid
    FROM (
      SELECT chunk_scope.value #>> '{}' AS transfer_scope_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfer_scope_ids') = 'array' THEN v_chunk_row.payload_json->'transfer_scope_ids' ELSE '[]'::jsonb END) AS chunk_scope(value)
      UNION ALL
      SELECT coalesce(unit_value.value->>'transfer_scope_id', unit_value.value #>> '{unit,transfer_scope_id}') AS transfer_scope_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'units') = 'array' THEN v_chunk_row.payload_json->'units' ELSE '[]'::jsonb END) AS unit_value(value)
      UNION ALL
      SELECT v_chunk_row.payload_json->>'transfer_scope_id' AS transfer_scope_id_text
    ) AS scope_text
    WHERE nullif(btrim(coalesce(scope_text.transfer_scope_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    LIMIT v_limit;
  ELSE
    INSERT INTO pg_temp.tmp_prepare_scope_request (transfer_scope_id)
    SELECT scope_row.id
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) IN ('ROLLED_UP', 'PENDING')
      AND coalesce(scope_row.provider_review_required, false) = false
      AND coalesce(scope_row.prepared_item_count, 0) > 0
      AND nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
      AND (
        (
          v_execution_mode = 'STANDARD_BANK'
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
        OR (
          v_is_local_manual_mode
          AND coalesce(scope_row.provider_submit_ready, false) = false
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
      )
    ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id
    LIMIT v_limit
    FOR UPDATE SKIP LOCKED;
  END IF;

  SELECT count(*)::integer
  INTO v_requested_count
  FROM pg_temp.tmp_prepare_scope_request AS requested_scope;

  IF coalesce(v_requested_count, 0) <= 0 THEN
    v_next_required_phase := CASE
      WHEN v_execution_mode = 'STANDARD_BANK' THEN 'PROVIDER_SUBMIT_CLAIM'
      ELSE 'PREPARE_BATCH_PROOF'
    END;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
      'requested_scope_count', 0,
      'prepared_count', 0,
      'reused_count', 0,
      'failed_count', 0,
      'item_transfer_linked_count', 0,
      'item_transfer_reused_count', 0,
      'item_transfer_conflict_count', 0,
      'remaining_count', 0,
      'has_more', false,
      'execution_mode', v_execution_mode,
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'local_settlement_evidence_only', v_is_local_manual_mode,
      'next_required_phase', v_next_required_phase
    ) || jsonb_strip_nulls(jsonb_build_object(
      'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
      'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
      'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
      'bank_csv_scope', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_scope ELSE NULL::text END,
      'bank_csv_paye_net_state_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_paye_net_state_hash ELSE NULL::text END,
      'bank_csv_bank_payment_projection_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_bank_payment_projection_hash ELSE NULL::text END,
      'bank_csv_row_count', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_row_count ELSE NULL::integer END,
      'bank_csv_total_amount', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_total_amount ELSE NULL::numeric END,
      'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
      'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
      'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END
    ));
  END IF;


  IF v_is_local_manual_mode AND v_mode_evidence_ready IS NOT TRUE THEN
    UPDATE public.banking_pay_operations AS operation_review
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        resume_reason = v_mode_evidence_code,
        progress_json = jsonb_strip_nulls(coalesce(operation_review.progress_json, '{}'::jsonb) || jsonb_build_object(
          'execution_mode', v_execution_mode,
          'provider_submission_required', false,
          'provider_submission_attempted', false,
          'submitted_to_bank', false,
          'review_required', true,
          'review_reason_code', v_mode_evidence_code,
          'manual_confirmation_mode', v_manual_confirmation_mode,
          'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
          'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
          'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END,
          'next_required_phase', 'REVIEW_REQUIRED',
          'review_required_at_utc', v_now::text
        )),
        error_json = jsonb_strip_nulls(coalesce(operation_review.error_json, '{}'::jsonb) || jsonb_build_object(
          'code', v_mode_evidence_code,
          'message', v_mode_evidence_message,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'execution_mode', v_execution_mode,
          'manual_confirmation_mode', v_manual_confirmation_mode,
          'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
          'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
          'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
          'csv_bank_confirm_ref_present', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref IS NOT NULL ELSE NULL::boolean END,
          'external_settlement_comment_present', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment IS NOT NULL ELSE NULL::boolean END,
          'payment_date_present', v_payment_date IS NOT NULL,
          'detected_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE operation_review.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', false,
      'hard_blocker', true,
      'code', v_mode_evidence_code,
      'message', v_mode_evidence_message,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_mode', v_execution_mode,
      'provider_submission_required', false,
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'manual_confirmation_mode', v_manual_confirmation_mode,
      'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
      'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
      'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
      'csv_bank_confirm_ref_present', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref IS NOT NULL ELSE NULL::boolean END,
      'external_settlement_comment_present', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment IS NOT NULL ELSE NULL::boolean END,
      'payment_date_present', v_payment_date IS NOT NULL,
      'next_required_phase', 'REVIEW_REQUIRED',
      'server_utc', v_now::text
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_scope_eval;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_scope_eval ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_batch_id,
         scope_row.pay_channel,
         scope_row.transfer_group_key,
         scope_row.candidate_id,
         scope_row.umbrella_id,
         scope_row.amount,
         coalesce(nullif(btrim(scope_row.currency), ''), 'GBP') AS currency,
         scope_row.payment_reference,
         scope_row.payee_name,
         scope_row.sort_code,
         scope_row.account_number,
         scope_row.account_type,
         scope_row.bank_details_hash_snapshot,
         scope_row.payee_entity_kind,
         scope_row.payee_entity_id,
         scope_row.grouping_mode_used,
         scope_row.week_ending_bucket,
         scope_row.request_id,
         scope_row.pay_bank_transfer_id,
         scope_row.prepared_item_count,
         scope_row.prepared_amount_total,
         scope_row.prepared_scope_hash,
         scope_row.prepared_result_hash,
         scope_row.provider_review_required,
         scope_row.provider_unsafe_reason,
         upper(btrim(coalesce(scope_row.status, ''))) AS current_scope_status,
         upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) AS current_provider_submit_state,
         CASE
           WHEN v_is_local_manual_mode AND (
             coalesce(scope_row.provider_submit_ready, false) = true
             OR upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
             OR scope_row.provider_submit_chunk_id IS NOT NULL
             OR scope_row.provider_submit_claimed_at_utc IS NOT NULL
             OR coalesce(scope_row.provider_submit_attempt_count, 0) > 0
             OR NULLIF(btrim(coalesce(scope_row.provider_idempotency_key, '')), '') IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_request_id, '')), '') IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_transaction_id, '')), '') IS NOT NULL
             OR scope_row.provider_request_prepared_at_utc IS NOT NULL
             OR scope_row.provider_request_sending_at_utc IS NOT NULL
             OR scope_row.provider_request_sent_at_utc IS NOT NULL
             OR scope_row.provider_response_at_utc IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_submission_status, '')), '') IS NOT NULL
           ) THEN 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE'
           WHEN upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('CLAIMED', 'REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED') THEN 'TRANSFER_SCOPE_PROVIDER_SUBMISSION_ALREADY_STARTED'
           WHEN upper(btrim(coalesce(scope_row.status, ''))) IN ('SUBMITTED', 'COMPLETED', 'COMPLETE') THEN 'TRANSFER_SCOPE_ALREADY_SUBMITTED'
           WHEN existing_transfer.id IS NOT NULL
            AND (
              upper(btrim(coalesce(existing_transfer.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED')
              OR (v_is_local_manual_mode AND nullif(btrim(coalesce(existing_transfer.request_id, '')), '') IS NOT NULL)
              OR nullif(btrim(coalesce(existing_transfer.rail_tx_id, '')), '') IS NOT NULL
              OR existing_transfer.completed_at_utc IS NOT NULL
              OR (
                CASE
                  WHEN v_is_local_manual_mode THEN upper(btrim(coalesce(existing_transfer.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
                  ELSE upper(btrim(coalesce(existing_transfer.rail_state, ''))) NOT IN ('', 'PENDING')
                END
              )
              OR upper(btrim(coalesce(existing_transfer.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
              OR upper(btrim(coalesce(existing_transfer.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            ) THEN 'EXISTING_TRANSFER_PROVIDER_EVIDENCE_PRESENT'
           WHEN coalesce(scope_row.provider_review_required, false) THEN 'PROVIDER_REVIEW_REQUIRED'
           WHEN coalesce(scope_row.prepared_item_count, 0) <= 0 THEN 'TRANSFER_SCOPE_NO_PREPARED_ITEMS'
           WHEN v_is_local_manual_mode AND nullif(btrim(coalesce(scope_row.prepared_scope_hash, '')), '') IS NULL THEN 'TRANSFER_SCOPE_PREPARED_SCOPE_PROOF_MISSING'
           WHEN nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NULL THEN 'TRANSFER_SCOPE_PREPARED_PROOF_MISSING'
           WHEN round(coalesce(scope_row.prepared_amount_total, 0), 2) = 0 THEN 'TRANSFER_SCOPE_ZERO_AMOUNT'
           ELSE NULL::text
         END AS blocker_code
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_prepare_scope_request AS requested_scope
    ON requested_scope.transfer_scope_id = scope_row.id
  LEFT JOIN public.pay_bank_transfers AS existing_transfer
    ON existing_transfer.pay_batch_id = scope_row.pay_batch_id
   AND existing_transfer.pay_channel = scope_row.pay_channel
   AND existing_transfer.transfer_group_key = scope_row.transfer_group_key
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id;

  IF (SELECT count(*) FROM pg_temp.tmp_prepare_scope_eval AS eval_row) <> v_requested_count THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_prepare_scope_eval AS eval_row
    WHERE eval_row.blocker_code IN ('TRANSFER_SCOPE_PROVIDER_SUBMISSION_ALREADY_STARTED', 'TRANSFER_SCOPE_ALREADY_SUBMITTED')
  ) THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PROVIDER_STATE_ALREADY_STARTED',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'message', 'Transfer chunk prepare cannot run against a scope after provider submission has started or completed. Reconcile provider state instead of preparing/resending.'
      )::text;
  END IF;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET status = 'FAILED',
      provider_submit_ready = false,
      provider_submit_state = 'REVIEW_REQUIRED',
      provider_review_required = true,
      provider_unsafe_reason = coalesce(eval_row.blocker_code, 'TRANSFER_SCOPE_NOT_PREPARABLE'),
      updated_at_utc = v_now
  FROM pg_temp.tmp_prepare_scope_eval AS eval_row
  WHERE scope_update.id = eval_row.transfer_scope_id
    AND eval_row.blocker_code IS NOT NULL;

  GET DIAGNOSTICS v_failed_count = ROW_COUNT;

  WITH preparable_scope AS (
    SELECT eval_row.*
    FROM pg_temp.tmp_prepare_scope_eval AS eval_row
    WHERE eval_row.blocker_code IS NULL
  ), upserted_transfers AS (
    INSERT INTO public.pay_bank_transfers (
      pay_batch_id,
      candidate_id,
      umbrella_id,
      pay_channel,
      amount,
      currency,
      status,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      created_at_utc,
      completed_at_utc,
      failed_reason,
      rail_provider,
      rail_env,
      request_id,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket
    )
    SELECT preparable_scope.pay_batch_id,
           preparable_scope.candidate_id,
           preparable_scope.umbrella_id,
           preparable_scope.pay_channel,
           round(coalesce(preparable_scope.prepared_amount_total, preparable_scope.amount, 0), 2),
           preparable_scope.currency,
           'PENDING',
           preparable_scope.payment_reference,
           preparable_scope.payee_name,
           CASE
             WHEN regexp_replace(coalesce(preparable_scope.sort_code, ''), '[^0-9]', '', 'g') ~ '^[0-9]{6}$' THEN regexp_replace(
               regexp_replace(coalesce(preparable_scope.sort_code, ''), '[^0-9]', '', 'g'),
               '^([0-9]{2})([0-9]{2})([0-9]{2})$',
               '\1-\2-\3'
             )
             ELSE NULL::text
           END,
           regexp_replace(coalesce(preparable_scope.account_number, ''), '[^0-9]', '', 'g'),
           preparable_scope.account_type,
           v_now,
           NULL::timestamptz,
           NULL::text,
           v_batch_row.rail_provider_snapshot,
           v_batch_row.rail_env_snapshot,
           CASE
             WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(preparable_scope.request_id), ''), 'op:' || p_operation_id::text || ':scope:' || preparable_scope.transfer_scope_id::text)
             ELSE NULL::text
           END,
           NULL::text,
           NULL::text,
           jsonb_build_object(
             'operation_id', p_operation_id::text,
             'transfer_scope_id', preparable_scope.transfer_scope_id::text,
             'prepared_at_utc', v_now::text,
             'prepared_result_hash', preparable_scope.prepared_result_hash
           ) || CASE
             WHEN v_is_local_manual_mode THEN jsonb_build_object(
               'execution_mode', v_execution_mode,
               'local_settlement_evidence_only', true,
               'provider_submission_required', false,
               'provider_submission_attempted', false,
               'submitted_to_bank', false
             )
             ELSE '{}'::jsonb
           END,
           preparable_scope.bank_details_hash_snapshot,
           preparable_scope.payee_entity_kind,
           preparable_scope.payee_entity_id,
           preparable_scope.transfer_group_key,
           preparable_scope.grouping_mode_used,
           preparable_scope.week_ending_bucket
    FROM preparable_scope
    ON CONFLICT (pay_batch_id, pay_channel, transfer_group_key)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        umbrella_id = EXCLUDED.umbrella_id,
        amount = EXCLUDED.amount,
        currency = EXCLUDED.currency,
        status = CASE WHEN public.pay_bank_transfers.status IN ('PENDING', 'BLOCKED', 'FAILED') THEN 'PENDING' ELSE public.pay_bank_transfers.status END,
        payment_reference = EXCLUDED.payment_reference,
        payee_name = EXCLUDED.payee_name,
        sort_code = EXCLUDED.sort_code,
        account_number = EXCLUDED.account_number,
        account_type = EXCLUDED.account_type,
        rail_provider = EXCLUDED.rail_provider,
        rail_env = EXCLUDED.rail_env,
        request_id = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(public.pay_bank_transfers.request_id, ''), EXCLUDED.request_id)
          ELSE public.pay_bank_transfers.request_id
        END,
        rail_meta_json = jsonb_strip_nulls(coalesce(public.pay_bank_transfers.rail_meta_json, '{}'::jsonb) || coalesce(EXCLUDED.rail_meta_json, '{}'::jsonb)),
        bank_details_hash_snapshot = EXCLUDED.bank_details_hash_snapshot,
        payee_entity_kind = EXCLUDED.payee_entity_kind,
        payee_entity_id = EXCLUDED.payee_entity_id,
        grouping_mode_used = EXCLUDED.grouping_mode_used,
        week_ending_bucket = EXCLUDED.week_ending_bucket
    WHERE public.pay_bank_transfers.status IN ('PENDING', 'BLOCKED', 'FAILED')
    RETURNING public.pay_bank_transfers.id,
              public.pay_bank_transfers.pay_batch_id,
              public.pay_bank_transfers.pay_channel,
              public.pay_bank_transfers.transfer_group_key,
              (xmax = 0) AS was_inserted
  ), linked_scope AS (
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET status = 'PREPARED',
        pay_bank_transfer_id = upserted_transfers.id,
        amount = round(coalesce(eval_row.prepared_amount_total, scope_update.amount, 0), 2),
        provider_submit_ready = CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN true ELSE false END,
        provider_submit_state = CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN 'READY' ELSE 'NOT_READY' END,
        provider_review_required = false,
        provider_unsafe_reason = NULL::text,
        provider_idempotency_key = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(scope_update.provider_idempotency_key), ''), coalesce(nullif(btrim(scope_update.request_id), ''), 'scope:' || scope_update.id::text))
          ELSE NULL::text
        END,
        provider_request_id = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(scope_update.provider_request_id), ''), upserted_transfers.id::text)
          ELSE NULL::text
        END,
        updated_at_utc = v_now
    FROM upserted_transfers
    JOIN pg_temp.tmp_prepare_scope_eval AS eval_row
      ON eval_row.pay_batch_id = upserted_transfers.pay_batch_id
     AND eval_row.pay_channel = upserted_transfers.pay_channel
     AND eval_row.transfer_group_key = upserted_transfers.transfer_group_key
    WHERE scope_update.id = eval_row.transfer_scope_id
      AND eval_row.blocker_code IS NULL
    RETURNING scope_update.id,
              upserted_transfers.was_inserted
  )
  SELECT count(*) FILTER (WHERE linked_scope.was_inserted)::integer,
         count(*) FILTER (WHERE linked_scope.was_inserted IS NOT TRUE)::integer
  INTO v_prepared_count,
       v_reused_count
  FROM linked_scope;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_item_transfer_link;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_item_transfer_link ON COMMIT DROP AS
  SELECT DISTINCT
         scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id AS pay_bank_transfer_id,
         scope_item_row.pay_batch_item_id AS pay_batch_item_id,
         batch_item.pay_bank_transfer_id AS existing_pay_bank_transfer_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_prepare_scope_eval AS eval_row
    ON eval_row.transfer_scope_id = scope_row.id
   AND eval_row.blocker_code IS NULL
  JOIN public.banking_pay_operation_transfer_scope_items AS scope_item_row
    ON scope_item_row.operation_id = p_operation_id
   AND scope_item_row.pay_batch_id = p_pay_batch_id
   AND scope_item_row.transfer_scope_id = scope_row.id
  JOIN public.pay_batch_items AS batch_item
    ON batch_item.id = scope_item_row.pay_batch_item_id
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id = batch_item.pay_batch_candidate_id
   AND batch_candidate.pay_batch_id = p_pay_batch_id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND scope_row.pay_bank_transfer_id IS NOT NULL
    AND COALESCE(batch_item.is_voided, false) = false;

  SELECT COUNT(*) FILTER (
           WHERE link_row.existing_pay_bank_transfer_id IS NOT NULL
             AND link_row.existing_pay_bank_transfer_id <> link_row.pay_bank_transfer_id
         )::integer,
         COUNT(*) FILTER (
           WHERE link_row.existing_pay_bank_transfer_id = link_row.pay_bank_transfer_id
         )::integer
  INTO v_item_transfer_conflict_count,
       v_item_transfer_reused_count
  FROM pg_temp.tmp_prepare_item_transfer_link AS link_row;

  WITH linked_batch_items AS (
    UPDATE public.pay_batch_items AS batch_item_update
    SET pay_bank_transfer_id = link_row.pay_bank_transfer_id,
        updated_at = v_now
    FROM pg_temp.tmp_prepare_item_transfer_link AS link_row
    WHERE batch_item_update.id = link_row.pay_batch_item_id
      AND batch_item_update.pay_bank_transfer_id IS NULL
      AND link_row.pay_bank_transfer_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_prepare_item_transfer_link AS conflict_row
        WHERE conflict_row.pay_batch_item_id = link_row.pay_batch_item_id
          AND conflict_row.existing_pay_bank_transfer_id IS NOT NULL
          AND conflict_row.existing_pay_bank_transfer_id <> conflict_row.pay_bank_transfer_id
      )
    RETURNING batch_item_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_item_transfer_linked_count
  FROM linked_batch_items;

  IF COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_conflict_update
    SET status = 'FAILED',
        provider_submit_ready = false,
        provider_submit_state = 'REVIEW_REQUIRED',
        provider_review_required = true,
        provider_unsafe_reason = 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT',
        updated_at_utc = v_now
    FROM (
      SELECT DISTINCT conflict_link.transfer_scope_id
      FROM pg_temp.tmp_prepare_item_transfer_link AS conflict_link
      WHERE conflict_link.existing_pay_bank_transfer_id IS NOT NULL
        AND conflict_link.existing_pay_bank_transfer_id <> conflict_link.pay_bank_transfer_id
    ) AS conflict_scope
    WHERE scope_conflict_update.id = conflict_scope.transfer_scope_id
      AND scope_conflict_update.operation_id = p_operation_id
      AND scope_conflict_update.pay_batch_id = p_pay_batch_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) IN ('ROLLED_UP', 'PENDING')
      AND coalesce(scope_row.provider_review_required, false) = false
      AND coalesce(scope_row.prepared_item_count, 0) > 0
      AND nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
      AND round(coalesce(scope_row.prepared_amount_total, 0), 2) <> 0
      AND (
        (
          v_execution_mode = 'STANDARD_BANK'
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
        OR (
          v_is_local_manual_mode
          AND coalesce(scope_row.provider_submit_ready, false) = false
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
      )
    LIMIT 1
  )
  INTO v_remaining_exists;

  SELECT count(*)::integer
  INTO v_authorisation_ready_count
  FROM pg_temp.tmp_prepare_scope_eval AS eval_row
  JOIN public.banking_pay_operation_transfer_scope AS scope_row
    ON scope_row.id = eval_row.transfer_scope_id
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = scope_row.pay_bank_transfer_id
   AND transfer_row.pay_batch_id = scope_row.pay_batch_id
  WHERE upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
    AND scope_row.pay_bank_transfer_id IS NOT NULL
    AND (
      (
        v_execution_mode = 'STANDARD_BANK'
        AND coalesce(scope_row.provider_submit_ready, false) = true
        AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      )
      OR (
        v_is_local_manual_mode
        AND v_mode_evidence_ready
        AND coalesce(scope_row.provider_submit_ready, false) = false
        AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        AND coalesce(scope_row.provider_review_required, false) = false
        AND NULLIF(btrim(coalesce(scope_row.provider_unsafe_reason, '')), '') IS NULL
        AND coalesce(scope_row.prepared_item_count, 0) > 0
        AND NULLIF(btrim(coalesce(scope_row.prepared_scope_hash, '')), '') IS NOT NULL
        AND NULLIF(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
        AND round(coalesce(scope_row.prepared_amount_total, 0), 2) = round(coalesce(scope_row.amount, 0), 2)
        AND round(coalesce(scope_row.prepared_amount_total, 0), 2) > 0
        AND upper(btrim(coalesce(transfer_row.status, ''))) = 'PENDING'
        AND transfer_row.pay_channel = scope_row.pay_channel
        AND transfer_row.transfer_group_key = scope_row.transfer_group_key
        AND round(coalesce(transfer_row.amount, 0), 2) = round(coalesce(scope_row.amount, 0), 2)
        AND upper(btrim(coalesce(transfer_row.currency, 'GBP'))) = upper(btrim(coalesce(scope_row.currency, 'GBP')))
        AND NULLIF(btrim(coalesce(transfer_row.request_id, '')), '') IS NULL
        AND NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NULL
        AND transfer_row.completed_at_utc IS NULL
        AND NULLIF(btrim(coalesce(transfer_row.failed_reason, '')), '') IS NULL
        AND upper(btrim(coalesce(transfer_row.rail_state, ''))) IN ('', 'LOCAL', 'PENDING')
        AND (
          SELECT count(*)
          FROM public.banking_pay_operation_transfer_scope_items AS scope_item_count
          WHERE scope_item_count.operation_id = p_operation_id
            AND scope_item_count.pay_batch_id = p_pay_batch_id
            AND scope_item_count.transfer_scope_id = scope_row.id
        ) = coalesce(scope_row.prepared_item_count, 0)
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope_items AS scope_item_check
          JOIN public.pay_batch_items AS batch_item_check
            ON batch_item_check.id = scope_item_check.pay_batch_item_id
          WHERE scope_item_check.operation_id = p_operation_id
            AND scope_item_check.pay_batch_id = p_pay_batch_id
            AND scope_item_check.transfer_scope_id = scope_row.id
            AND batch_item_check.pay_bank_transfer_id IS DISTINCT FROM scope_row.pay_bank_transfer_id
        )
      )
    );

  v_next_required_phase := CASE
    WHEN coalesce(v_item_transfer_conflict_count, 0) > 0 OR coalesce(v_failed_count, 0) > 0 THEN 'REVIEW_REQUIRED'
    WHEN v_remaining_exists THEN 'TRANSFER_CHUNK_PREPARE_PAGE'
    WHEN v_execution_mode = 'STANDARD_BANK' THEN 'PROVIDER_SUBMIT_CLAIM'
    ELSE 'PREPARE_BATCH_PROOF'
  END;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'REVIEW_REQUIRED' ELSE operation_update.status END,
      phase = CASE
        WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'REVIEW_REQUIRED'
        WHEN v_remaining_exists THEN 'PREPARE_TRANSFER_CHUNKS'
        WHEN v_execution_mode = 'STANDARD_BANK' THEN 'CLAIM_PROVIDER_SUBMIT'
        ELSE 'PREPARE_BATCH_PROOF'
      END,
      runner_state = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'WAITING_USER_REVIEW' ELSE operation_update.runner_state END,
      requires_user_action = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN true ELSE operation_update.requires_user_action END,
      progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'last_transfer_chunk_prepare_at_utc', v_now::text,
        'last_transfer_chunk_prepare_scope_count', coalesce(v_requested_count, 0),
        'last_transfer_chunk_prepare_ready_count', coalesce(v_authorisation_ready_count, 0),
        'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
        'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
        'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
        'execution_mode', v_execution_mode,
        'provider_submission_required', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'provider_submission_attempted', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'submitted_to_bank', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'local_settlement_evidence_only', CASE WHEN v_is_local_manual_mode THEN true ELSE NULL::boolean END,
        'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
        'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
        'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
        'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END,
        'review_required', CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN true ELSE NULL::boolean END,
        'review_reason_code', CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT' ELSE NULL::text END,
        'next_required_phase', v_next_required_phase
      )),
      error_json = CASE
        WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN jsonb_strip_nulls(coalesce(operation_update.error_json, '{}'::jsonb) || jsonb_build_object(
          'code', 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT',
          'message', CASE
            WHEN v_is_local_manual_mode THEN 'One or more frozen pay batch items are already linked to a different bank transfer. Local/manual settlement evidence preparation has been blocked for the affected transfer scope.'
            ELSE 'One or more frozen pay batch items are already linked to a different bank transfer. Provider submission has been blocked for the affected transfer scope.'
          END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
          'detected_at_utc', v_now::text
        ))
        ELSE operation_update.error_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', coalesce(v_failed_count, 0) = 0 AND COALESCE(v_item_transfer_conflict_count, 0) = 0,
    'hard_blocker', coalesce(v_failed_count, 0) > 0 OR COALESCE(v_item_transfer_conflict_count, 0) > 0,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
    'requested_scope_count', coalesce(v_requested_count, 0),
    'prepared_count', coalesce(v_prepared_count, 0),
    'reused_count', coalesce(v_reused_count, 0),
    'authorisation_ready_count', coalesce(v_authorisation_ready_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
    'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
    'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
    'remaining_count', CASE WHEN v_remaining_exists THEN 1 ELSE 0 END,
    'has_more', v_remaining_exists,
    'execution_mode', v_execution_mode,
    'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
    'provider_submission_attempted', false,
    'submitted_to_bank', false,
    'provider_submit_ready', CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(v_authorisation_ready_count, 0) > 0 ELSE false END,
    'local_settlement_evidence_only', v_is_local_manual_mode,
    'next_required_phase', v_next_required_phase,
    'server_utc', v_now::text
  ) || jsonb_strip_nulls(jsonb_build_object(
    'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
    'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
    'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
    'bank_csv_scope', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_scope ELSE NULL::text END,
    'bank_csv_paye_net_state_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_paye_net_state_hash ELSE NULL::text END,
    'bank_csv_bank_payment_projection_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_bank_payment_projection_hash ELSE NULL::text END,
    'bank_csv_row_count', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_row_count ELSE NULL::integer END,
    'bank_csv_total_amount', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_total_amount ELSE NULL::numeric END,
    'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
    'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
    'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END
  ));
END;
$function$;




DROP FUNCTION IF EXISTS public.pay_execute_bank_transfer_scope_seed(uuid, uuid, text, uuid, boolean);


CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_seed(p_operation_id uuid, p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid, p_retry_blocked_funds boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_limit integer := 100;
  v_last_pay_batch_item_id uuid := NULL::uuid;
  v_page_count integer := 0;
  v_group_seeded_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_cached_scope_count integer := 0;
  v_existing_scope_count integer := 0;
  v_unseeded_transfer_scope_count integer := 0;
  v_next_transfer_scope_id uuid := NULL::uuid;
  v_review_scope_count integer := 0;
  v_operation_phase text := NULL::text;
  v_transfer_scope_group_seed_complete boolean := false;
  v_membership_seed_required boolean := false;
  v_next_required_phase text := 'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE';
  v_global_projection_missing_paye_count integer := 0;
  v_global_projection_explicit_zero_count integer := 0;
  v_global_projection_positive_payment_count integer := 0;
  v_global_projection_positive_payment_total numeric(14,2) := 0;
  v_global_projection_invalid_payment_row_count integer := 0;
  v_global_projection_paye_net_state_hash text := NULL::text;
  v_global_projection_bank_payment_hash text := NULL::text;
  v_scoped_projection_missing_paye_count integer := 0;
  v_scoped_projection_explicit_zero_count integer := 0;
  v_scoped_projection_positive_payment_count integer := 0;
  v_scoped_projection_positive_payment_total numeric(14,2) := 0;
  v_scoped_projection_invalid_payment_row_count integer := 0;
  v_scoped_projection_paye_net_state_hash text := NULL::text;
  v_scoped_projection_bank_payment_hash text := NULL::text;
  v_allow_explicit_zero_no_bank_scopes boolean := false;
  v_scoped_no_transfer_execution boolean := false;
  v_no_bank_payment_execution boolean := false;
  v_no_bank_proof_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_ACTOR_REQUIRED')::text;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_SCOPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_SCOPE_INVALID', 'pay_channel_scope', p_pay_channel_scope)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))) <> 'PASSED'
     OR nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NULL
     OR coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false) IS TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_FRESHNESS_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_FRESHNESS_REQUIRED',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_batch_row.freshness_validation_status,
        'freshness_result_hash_present', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
      )::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) = 'BLOCKED_FUNDS' AND coalesce(p_retry_blocked_funds, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BLOCKED_FUNDS_RETRY_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BLOCKED_FUNDS_RETRY_REQUIRED', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  WITH global_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      'ALL'
    ) AS projection_row
  ), global_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS missing_paye_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS explicit_zero_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM global_projection_rows AS projection_row
  ), scoped_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_scope
    ) AS projection_row
  ), scoped_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS missing_paye_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS explicit_zero_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM scoped_projection_rows AS projection_row
  )
  SELECT
    COALESCE(global_projection_summary.missing_paye_count, 0),
    COALESCE(global_projection_summary.explicit_zero_count, 0),
    COALESCE(global_projection_summary.positive_payment_count, 0),
    COALESCE(global_projection_summary.positive_payment_total, 0),
    COALESCE(global_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      global_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      global_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(scoped_projection_summary.missing_paye_count, 0),
    COALESCE(scoped_projection_summary.explicit_zero_count, 0),
    COALESCE(scoped_projection_summary.positive_payment_count, 0),
    COALESCE(scoped_projection_summary.positive_payment_total, 0),
    COALESCE(scoped_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      scoped_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      scoped_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'rows', '[]'::jsonb
      )::text)
    )
  INTO
    v_global_projection_missing_paye_count,
    v_global_projection_explicit_zero_count,
    v_global_projection_positive_payment_count,
    v_global_projection_positive_payment_total,
    v_global_projection_invalid_payment_row_count,
    v_global_projection_paye_net_state_hash,
    v_global_projection_bank_payment_hash,
    v_scoped_projection_missing_paye_count,
    v_scoped_projection_explicit_zero_count,
    v_scoped_projection_positive_payment_count,
    v_scoped_projection_positive_payment_total,
    v_scoped_projection_invalid_payment_row_count,
    v_scoped_projection_paye_net_state_hash,
    v_scoped_projection_bank_payment_hash
  FROM global_projection_summary
  CROSS JOIN scoped_projection_summary;

  IF COALESCE(v_global_projection_missing_paye_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_PAYE_NET_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = JSONB_BUILD_OBJECT(
        'code', 'PAYE_NET_REQUIRED_FOR_EXECUTION',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0)
      )::text;
  END IF;

  v_allow_explicit_zero_no_bank_scopes := (
    COALESCE(v_global_projection_missing_paye_count, 0) = 0
    AND COALESCE(v_scoped_projection_explicit_zero_count, 0) > 0
    AND COALESCE(v_scoped_projection_invalid_payment_row_count, 0) = 0
  );

  v_scoped_no_transfer_execution := (
    v_allow_explicit_zero_no_bank_scopes
    AND COALESCE(v_scoped_projection_positive_payment_count, 0) = 0
  );

  v_no_bank_payment_execution := (
    v_scoped_no_transfer_execution
    AND COALESCE(v_global_projection_positive_payment_count, 0) = 0
    AND COALESCE(v_global_projection_invalid_payment_row_count, 0) = 0
  );

  v_no_bank_proof_json := JSONB_BUILD_OBJECT(
    'proof_source', 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_SEED',
    'proof_generated_at_utc', v_now::text,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_channel_scope', v_scope,
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
    'no_bank_payment_execution', v_no_bank_payment_execution,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
    'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
    'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
    'global_positive_bank_payment_total', ROUND(COALESCE(v_global_projection_positive_payment_total, 0), 2),
    'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
    'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
    'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
    'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
    'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
    'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
    'paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
    'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
    'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
    'scoped_bank_payment_projection_hash', v_scoped_projection_bank_payment_hash
  );

  v_operation_phase := upper(btrim(coalesce(v_operation_row.phase, '')));
  v_transfer_scope_group_seed_complete :=
    v_operation_phase IN (
      'SEED_TRANSFER_SCOPE_ITEMS',
      'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE',
      'SEED_TRANSFER_ROLLUP_CHUNKS',
      'ROLLUP_TRANSFER_SCOPE_ITEMS',
      'TRANSFER_SCOPE_ROLLUP_PAGE',
      'PREPARE_TRANSFER_CHUNKS',
      'TRANSFER_CHUNK_PREPARE_PAGE',
      'PREPARE_BATCH_PROOF',
      'PREPARE_BATCH',
      'START_AUTHORISATION_PROOF',
      'START_AUTHORISATION',
      'SUBMIT_PROVIDER_TRANSFERS',
      'SEND_PROVIDER_CHUNK',
      'REQUEST_PROVIDER_SEND',
      'FINALISE_PROVIDER_CHUNK',
      'APPLY_RAIL_UPDATES',
      'QUEUE_REMITTANCES',
      'COMPLETE'
    )
    OR upper(btrim(coalesce(v_operation_row.progress_json->>'transfer_scope_group_seed_complete', ''))) = 'TRUE'
    OR (
      v_operation_row.progress_json ? 'has_more_transfer_groups'
      AND upper(btrim(coalesce(v_operation_row.progress_json->>'has_more_transfer_groups', 'false'))) <> 'TRUE'
      AND v_operation_row.progress_json ? 'last_transfer_scope_seed_at_utc'
    );

  IF coalesce(v_transfer_scope_group_seed_complete, false) THEN
    SELECT count(*)::integer
    INTO v_existing_scope_count
    FROM public.banking_pay_operation_transfer_scope AS existing_scope
    WHERE existing_scope.operation_id = p_operation_id
      AND existing_scope.pay_batch_id = p_pay_batch_id;

    SELECT count(*)::integer
    INTO v_unseeded_transfer_scope_count
    FROM public.banking_pay_operation_transfer_scope AS unseeded_scope
    WHERE unseeded_scope.operation_id = p_operation_id
      AND unseeded_scope.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', unseeded_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
      AND upper(btrim(coalesce(unseeded_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
        'CLAIMED',
        'REQUEST_PREPARING',
        'REQUEST_SENDING',
        'REQUEST_SENT_LOCAL',
        'PROVIDER_ACCEPTED',
        'PROVIDER_REJECTED',
        'PROVIDER_UNKNOWN',
        'CHUNK_FINALISED'
      );

    SELECT next_scope.id
    INTO v_next_transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS next_scope
    WHERE next_scope.operation_id = p_operation_id
      AND next_scope.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', next_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
      AND upper(btrim(coalesce(next_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
        'CLAIMED',
        'REQUEST_PREPARING',
        'REQUEST_SENDING',
        'REQUEST_SENT_LOCAL',
        'PROVIDER_ACCEPTED',
        'PROVIDER_REJECTED',
        'PROVIDER_UNKNOWN',
        'CHUNK_FINALISED'
      )
    ORDER BY next_scope.created_at_utc NULLS FIRST, next_scope.id
    LIMIT 1;

    SELECT count(*)::integer
    INTO v_review_scope_count
    FROM public.banking_pay_operation_transfer_scope AS review_scope
    WHERE review_scope.operation_id = p_operation_id
      AND review_scope.pay_batch_id = p_pay_batch_id
      AND (
        coalesce(review_scope.provider_review_required, false) IS TRUE
        OR upper(btrim(coalesce(review_scope.provider_submit_state, ''))) = 'REVIEW_REQUIRED'
      );

    IF coalesce(v_existing_scope_count, 0) <= 0 THEN
      IF v_scoped_no_transfer_execution THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET pay_batch_id = p_pay_batch_id,
            status = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN 'RUNNING'
              ELSE operation_update.status
            END,
            phase = 'START_AUTHORISATION_PROOF',
            runner_state = 'RUNNABLE',
            requires_user_action = false,
            resume_reason = CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_AUTHORISATION_REQUIRED' ELSE 'NO_TRANSFER_SCOPE_AUTHORISATION_REQUIRED' END,
            run_after_utc = v_now,
            progress_json = JSONB_STRIP_NULLS(
              COALESCE(operation_update.progress_json, '{}'::jsonb)
              || JSONB_BUILD_OBJECT(
                'last_transfer_scope_seed_at_utc', v_now::text,
                'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
                'transfer_scope_group_seed_complete', true,
                'transfer_scope_count', 0,
                'unseeded_transfer_scope_count', 0,
                'membership_seed_required', false,
                'no_transfer_scope', true,
                'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
                'no_bank_payment_execution', v_no_bank_payment_execution,
                'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
                'review_required', false,
                'review_reason_code', NULL::text,
                'has_more_transfer_groups', false,
                'transfer_scope_seed_cursor', NULL::jsonb,
                'next_required_phase', 'START_AUTHORISATION_PROOF'
              )
              || v_no_bank_proof_json
              || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
            ),
            error_json = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN NULL::jsonb
              ELSE operation_update.error_json
            END,
            updated_at_utc = v_now
        WHERE operation_update.id = p_operation_id;

        RETURN JSONB_BUILD_OBJECT(
          'ok', true,
          'code', CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_EXECUTION_READY' ELSE 'NO_TRANSFER_EXECUTION_SCOPE_READY' END,
          'message', CASE WHEN v_no_bank_payment_execution THEN 'All required bank-payment groups are explicit zero; no transfer scope is required and authorisation can continue.' ELSE 'The requested scope contains only explicit-zero PAYE payment groups; no transfer scope is required for this scope and authorisation can continue.' END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'bounded', true,
          'limit', v_limit,
          'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
          'source_item_page_count', 0,
          'group_seeded_count', 0,
          'membership_seeded_count', 0,
          'transfer_scope_count', 0,
          'unseeded_transfer_scope_count', 0,
          'review_scope_count', 0,
          'membership_seed_required', false,
          'no_transfer_scope', true,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
          'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
          'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
          'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
          'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
          'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
          'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
          'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
          'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
          'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
          'paye_net_state_hash', v_global_projection_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
          'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
          'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
          'has_more_transfer_groups', false,
          'has_more_membership_seed', false,
          'next_transfer_scope_id', NULL::text,
          'next_cursor', NULL::jsonb,
          'next_required_phase', 'START_AUTHORISATION_PROOF',
          'server_utc', v_now::text
        );
      END IF;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          phase = 'REVIEW_REQUIRED',
          progress_json = jsonb_strip_nulls(
            coalesce(operation_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_transfer_scope_seed_at_utc', v_now::text,
              'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
              'transfer_scope_group_seed_complete', true,
              'transfer_scope_count', 0,
              'unseeded_transfer_scope_count', 0,
              'membership_seed_required', false,
              'no_transfer_scope', true,
              'next_required_phase', 'REVIEW_REQUIRED'
            )
          ),
          updated_at_utc = v_now
      WHERE operation_update.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'code', 'NO_ELIGIBLE_TRANSFER_SCOPE',
        'message', 'No eligible payable transfer scope was available for this operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'bounded', true,
        'limit', v_limit,
        'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
        'source_item_page_count', 0,
        'group_seeded_count', 0,
        'membership_seeded_count', 0,
        'transfer_scope_count', 0,
        'unseeded_transfer_scope_count', 0,
        'review_scope_count', coalesce(v_review_scope_count, 0),
        'membership_seed_required', false,
        'no_transfer_scope', true,
        'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
        'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
        'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
        'has_more_transfer_groups', false,
        'has_more_membership_seed', false,
        'next_transfer_scope_id', NULL::text,
        'next_cursor', NULL::jsonb,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
    END IF;

    v_membership_seed_required := coalesce(v_unseeded_transfer_scope_count, 0) > 0;
    v_next_required_phase := CASE WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS' ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS' END;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        phase = v_next_required_phase,
        runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
        run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
        progress_json = jsonb_strip_nulls(
          coalesce(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_transfer_scope_seed_at_utc', v_now::text,
            'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
            'transfer_scope_group_seed_complete', true,
            'transfer_scope_count', coalesce(v_existing_scope_count, 0),
            'unseeded_transfer_scope_count', coalesce(v_unseeded_transfer_scope_count, 0),
            'membership_seed_required', coalesce(v_membership_seed_required, false),
            'next_transfer_scope_id', CASE WHEN v_next_transfer_scope_id IS NULL THEN NULL ELSE v_next_transfer_scope_id::text END,
            'next_required_phase', v_next_required_phase,
            'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
            'no_bank_payment_execution', v_no_bank_payment_execution,
            'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes
          )
          || v_no_bank_proof_json
          || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_channel_scope', v_scope,
      'bounded', true,
      'limit', v_limit,
      'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
      'source_item_page_count', 0,
      'group_seeded_count', 0,
      'membership_seeded_count', 0,
      'transfer_scope_count', coalesce(v_existing_scope_count, 0),
      'unseeded_transfer_scope_count', coalesce(v_unseeded_transfer_scope_count, 0),
      'review_scope_count', coalesce(v_review_scope_count, 0),
      'membership_seed_required', coalesce(v_membership_seed_required, false),
      'no_transfer_scope', false,
      'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
      'no_bank_payment_execution', v_no_bank_payment_execution,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
      'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
      'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
      'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
      'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
      'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
      'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
      'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
      'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
      'paye_net_state_hash', v_global_projection_paye_net_state_hash,
      'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
      'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
      'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
      'has_more_transfer_groups', false,
      'has_more_membership_seed', coalesce(v_membership_seed_required, false),
      'next_transfer_scope_id', CASE WHEN v_next_transfer_scope_id IS NULL THEN NULL ELSE v_next_transfer_scope_id::text END,
      'next_cursor', NULL::jsonb,
      'next_required_phase', v_next_required_phase,
      'server_utc', v_now::text
    );
  END IF;

  IF nullif(btrim(coalesce(v_operation_row.progress_json #>> '{transfer_scope_seed_cursor,last_pay_batch_item_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_pay_batch_item_id := (v_operation_row.progress_json #>> '{transfer_scope_seed_cursor,last_pay_batch_item_id}')::uuid;
  END IF;

  IF nullif(btrim(coalesce(v_operation_row.progress_json->>'transfer_scope_count', '')), '') ~ '^[0-9]+$' THEN
    v_cached_scope_count := (v_operation_row.progress_json->>'transfer_scope_count')::integer;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_bank_transfer_scope_source_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_bank_transfer_scope_source_page ON COMMIT DROP AS
  WITH source_rows AS (
    SELECT
      row_number() OVER (ORDER BY batch_item.id)::integer AS page_ordinal,
      batch_item.id AS pay_batch_item_id,
      batch_candidate.id AS pay_batch_candidate_id,
      batch_candidate.candidate_id,
      CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END AS pay_channel,
      batch_item.umbrella_id,
      COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS item_amount,
      batch_candidate.net_bank_amount,
      effective_paye_input.id AS effective_paye_net_input_id,
      effective_paye_input.net_amount AS effective_paye_net_input_amount,
      (
        effective_paye_input.id IS NOT NULL
        AND effective_paye_input.net_amount IS NOT NULL
      ) AS has_effective_paye_input,
      batch_item.payout_instruction_snapshot_json,
      upper(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_kind', '')), '')) AS payee_entity_kind,
      CASE
        WHEN nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (batch_item.payout_instruction_snapshot_json->>'payee_entity_id')::uuid
        ELSE NULL::uuid
      END AS payee_entity_id,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'beneficiary_name', '')), '') AS payee_name,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'sort_code', '')), '') AS sort_code,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'account_number', '')), '') AS account_number,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'account_type', '')), '') AS account_type,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), '') AS bank_details_hash_snapshot,
      CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket')::date ELSE NULL::date END AS week_ending_bucket,
      CASE
        WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'PAYE'
          THEN batch_candidate.candidate_id::text || '|PAYE|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
        WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'UMBRELLA'
          THEN batch_candidate.candidate_id::text || '|UMBRELLA|' || coalesce(CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket') ELSE 'NO_WEEK' END, 'NO_WEEK') || '|' || coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '') || '|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
        ELSE batch_candidate.candidate_id::text || '|OTHER|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
      END AS transfer_group_key
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    LEFT JOIN LATERAL (
      SELECT
        paye_input_row.id,
        paye_input_row.net_amount
      FROM public.pay_batch_paye_net_inputs AS paye_input_row
      WHERE paye_input_row.pay_batch_candidate_id = batch_candidate.id
      ORDER BY paye_input_row.imported_at_utc DESC,
               paye_input_row.id DESC
      LIMIT 1
    ) AS effective_paye_input
      ON true
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND coalesce(batch_item.is_voided, false) = false
      AND batch_item.item_type <> 'DEBT_CREATED'
      AND NOT (
        upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
        AND upper(btrim(coalesce(batch_item.pay_channel, ''))) = 'PAYE'
        AND effective_paye_input.id IS NOT NULL
        AND effective_paye_input.net_amount IS NOT NULL
        AND batch_candidate.net_bank_amount IS NOT NULL
        AND round(batch_candidate.net_bank_amount, 2) = 0
      )
      AND (v_last_pay_batch_item_id IS NULL OR batch_item.id > v_last_pay_batch_item_id)
      AND (
        (v_scope = 'ALL' AND batch_item.pay_channel IN ('PAYE', 'UMBRELLA'))
        OR (v_scope IN ('PAYE', 'UMBRELLA') AND batch_item.pay_channel = v_scope)
        OR (v_scope = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
        OR (upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
      )
    ORDER BY batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT source_rows.*
  FROM source_rows;

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_bank_transfer_scope_group_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_bank_transfer_scope_group_page ON COMMIT DROP AS
  SELECT DISTINCT ON (source_page.pay_channel, source_page.transfer_group_key)
         source_page.pay_channel,
         source_page.transfer_group_key,
         source_page.candidate_id,
         source_page.has_effective_paye_input,
         CASE WHEN source_page.pay_channel = 'UMBRELLA' AND source_page.payee_entity_kind = 'UMBRELLA' THEN source_page.payee_entity_id ELSE NULL::uuid END AS umbrella_id,
         source_page.payee_entity_kind,
         source_page.payee_entity_id,
         'GBP'::text AS currency,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN round(coalesce(source_page.net_bank_amount, 0), 2) ELSE 0::numeric END AS amount,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN 'Pay' ELSE left(coalesce(source_page.payee_name, source_page.candidate_id::text), 18) END AS payment_reference,
         source_page.payee_name,
         source_page.sort_code,
         source_page.account_number,
         source_page.account_type,
         source_page.bank_details_hash_snapshot,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN 'CANDIDATE_DESTINATION' ELSE 'ROW_BACKED_DESTINATION' END AS grouping_mode_used,
         source_page.week_ending_bucket,
         CASE
           WHEN source_page.payout_instruction_snapshot_json IS NULL
             OR source_page.payee_name IS NULL
             OR source_page.bank_details_hash_snapshot IS NULL
             OR length(regexp_replace(coalesce(source_page.sort_code, ''), '[^0-9]', '', 'g')) <> 6
             OR nullif(regexp_replace(coalesce(source_page.account_number, ''), '[^0-9]', '', 'g'), '') IS NULL
             OR (source_page.pay_channel = 'UMBRELLA' AND (source_page.payee_entity_kind IS NULL OR source_page.payee_entity_kind <> 'UMBRELLA' OR source_page.payee_entity_id IS NULL OR source_page.umbrella_id IS NULL OR source_page.payee_entity_id IS DISTINCT FROM source_page.umbrella_id))
             OR (source_page.pay_channel = 'PAYE' AND (source_page.payee_entity_kind IS NULL OR source_page.payee_entity_kind <> 'CANDIDATE' OR source_page.payee_entity_id IS NULL OR source_page.payee_entity_id IS DISTINCT FROM source_page.candidate_id))
             OR (
               source_page.pay_channel = 'PAYE'
               AND upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
               AND source_page.has_effective_paye_input IS NOT TRUE
             )
             OR (source_page.pay_channel = 'PAYE' AND round(coalesce(source_page.net_bank_amount, 0), 2) <= 0)
           THEN 'FAILED'
           ELSE 'PENDING'
         END AS status,
         CASE
           WHEN source_page.pay_channel = 'PAYE'
            AND upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
            AND source_page.has_effective_paye_input IS NOT TRUE
             THEN 'PAYE_NET_REQUIRED_FOR_EXECUTION'
           WHEN source_page.pay_channel = 'PAYE'
            AND round(coalesce(source_page.net_bank_amount, 0), 2) <= 0
             THEN 'TRANSFER_SCOPE_NON_POSITIVE_AMOUNT'
           ELSE 'TRANSFER_GROUP_PAYOUT_INSTRUCTION_INVALID'
         END AS failure_reason
  FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page
  WHERE source_page.page_ordinal <= v_limit
  ORDER BY source_page.pay_channel, source_page.transfer_group_key, source_page.pay_batch_item_id;

  WITH inserted_scope AS (
    INSERT INTO public.banking_pay_operation_transfer_scope (
      operation_id,
      pay_batch_id,
      pay_channel,
      transfer_group_key,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      currency,
      amount,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      grouping_mode_used,
      week_ending_bucket,
      request_id,
      status,
      pay_bank_transfer_id,
      provider_submit_ready,
      provider_submit_state,
      provider_review_required,
      provider_unsafe_reason,
      prepared_item_count,
      prepared_amount_total,
      created_at_utc,
      updated_at_utc
    )
    SELECT p_operation_id,
           p_pay_batch_id,
           group_page.pay_channel,
           group_page.transfer_group_key,
           group_page.candidate_id,
           group_page.umbrella_id,
           group_page.payee_entity_kind,
           group_page.payee_entity_id,
           group_page.currency,
           group_page.amount,
           group_page.payment_reference,
           group_page.payee_name,
           regexp_replace(coalesce(group_page.sort_code, ''), '[^0-9]', '', 'g'),
           regexp_replace(coalesce(group_page.account_number, ''), '[^0-9]', '', 'g'),
           group_page.account_type,
           group_page.bank_details_hash_snapshot,
           group_page.grouping_mode_used,
           group_page.week_ending_bucket,
           'op:' || p_operation_id::text || ':scope:' || md5(group_page.pay_channel || ':' || group_page.transfer_group_key),
           CASE WHEN group_page.status = 'FAILED' THEN 'FAILED' ELSE 'PENDING' END,
           NULL::uuid,
           false,
           CASE WHEN group_page.status = 'FAILED' THEN 'REVIEW_REQUIRED' ELSE 'NOT_READY' END,
           group_page.status = 'FAILED',
           CASE WHEN group_page.status = 'FAILED' THEN group_page.failure_reason ELSE 'TRANSFER_SCOPE_ITEM_SEED_PENDING' END,
           0,
           0,
           v_now,
           v_now
    FROM pg_temp.tmp_bank_transfer_scope_group_page AS group_page
    ON CONFLICT (operation_id, pay_channel, transfer_group_key) DO NOTHING
    RETURNING id
  )
  SELECT count(*)::integer
  INTO v_group_seeded_count
  FROM inserted_scope;

  IF coalesce(v_page_count, 0) > 0 THEN
    SELECT jsonb_build_object('last_pay_batch_item_id', source_page.pay_batch_item_id::text)
    INTO v_next_cursor
    FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page
    WHERE source_page.page_ordinal <= LEAST(v_limit, v_page_count)
    ORDER BY source_page.page_ordinal DESC
    LIMIT 1;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  SELECT count(*)::integer
  INTO v_existing_scope_count
  FROM public.banking_pay_operation_transfer_scope AS existing_scope
  WHERE existing_scope.operation_id = p_operation_id
    AND existing_scope.pay_batch_id = p_pay_batch_id;

  SELECT count(*)::integer
  INTO v_unseeded_transfer_scope_count
  FROM public.banking_pay_operation_transfer_scope AS unseeded_scope
  WHERE unseeded_scope.operation_id = p_operation_id
    AND unseeded_scope.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', unseeded_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
    AND upper(btrim(coalesce(unseeded_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
      'CLAIMED',
      'REQUEST_PREPARING',
      'REQUEST_SENDING',
      'REQUEST_SENT_LOCAL',
      'PROVIDER_ACCEPTED',
      'PROVIDER_REJECTED',
      'PROVIDER_UNKNOWN',
      'CHUNK_FINALISED'
    );

  SELECT next_scope.id
  INTO v_next_transfer_scope_id
  FROM public.banking_pay_operation_transfer_scope AS next_scope
  WHERE next_scope.operation_id = p_operation_id
    AND next_scope.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', next_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
    AND upper(btrim(coalesce(next_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
      'CLAIMED',
      'REQUEST_PREPARING',
      'REQUEST_SENDING',
      'REQUEST_SENT_LOCAL',
      'PROVIDER_ACCEPTED',
      'PROVIDER_REJECTED',
      'PROVIDER_UNKNOWN',
      'CHUNK_FINALISED'
    )
  ORDER BY next_scope.created_at_utc NULLS FIRST, next_scope.id
  LIMIT 1;

  SELECT count(*)::integer
  INTO v_review_scope_count
  FROM public.banking_pay_operation_transfer_scope AS review_scope
  WHERE review_scope.operation_id = p_operation_id
    AND review_scope.pay_batch_id = p_pay_batch_id
    AND (
      coalesce(review_scope.provider_review_required, false) IS TRUE
      OR upper(btrim(coalesce(review_scope.provider_submit_state, ''))) = 'REVIEW_REQUIRED'
    );

  v_cached_scope_count := coalesce(v_existing_scope_count, 0);

  IF coalesce(v_page_count, 0) = 0 AND coalesce(v_cached_scope_count, 0) <= 0 THEN
      IF v_scoped_no_transfer_execution THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET pay_batch_id = p_pay_batch_id,
            status = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN 'RUNNING'
              ELSE operation_update.status
            END,
            phase = 'START_AUTHORISATION_PROOF',
            runner_state = 'RUNNABLE',
            requires_user_action = false,
            resume_reason = CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_AUTHORISATION_REQUIRED' ELSE 'NO_TRANSFER_SCOPE_AUTHORISATION_REQUIRED' END,
            run_after_utc = v_now,
            progress_json = JSONB_STRIP_NULLS(
              COALESCE(operation_update.progress_json, '{}'::jsonb)
              || JSONB_BUILD_OBJECT(
                'last_transfer_scope_seed_at_utc', v_now::text,
                'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
                'transfer_scope_group_seed_complete', true,
                'transfer_scope_count', 0,
                'unseeded_transfer_scope_count', 0,
                'membership_seed_required', false,
                'no_transfer_scope', true,
                'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
                'no_bank_payment_execution', v_no_bank_payment_execution,
                'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
                'review_required', false,
                'review_reason_code', NULL::text,
                'has_more_transfer_groups', false,
                'transfer_scope_seed_cursor', NULL::jsonb,
                'next_required_phase', 'START_AUTHORISATION_PROOF'
              )
              || v_no_bank_proof_json
              || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
            ),
            error_json = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN NULL::jsonb
              ELSE operation_update.error_json
            END,
            updated_at_utc = v_now
        WHERE operation_update.id = p_operation_id;

        RETURN JSONB_BUILD_OBJECT(
          'ok', true,
          'code', CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_EXECUTION_READY' ELSE 'NO_TRANSFER_EXECUTION_SCOPE_READY' END,
          'message', CASE WHEN v_no_bank_payment_execution THEN 'All required bank-payment groups are explicit zero; no transfer scope is required and authorisation can continue.' ELSE 'The requested scope contains only explicit-zero PAYE payment groups; no transfer scope is required for this scope and authorisation can continue.' END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'bounded', true,
          'limit', v_limit,
          'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
          'source_item_page_count', 0,
          'group_seeded_count', 0,
          'membership_seeded_count', 0,
          'transfer_scope_count', 0,
          'unseeded_transfer_scope_count', 0,
          'review_scope_count', 0,
          'membership_seed_required', false,
          'no_transfer_scope', true,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
          'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
          'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
          'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
          'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
          'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
          'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
          'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
          'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
          'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
          'paye_net_state_hash', v_global_projection_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
          'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
          'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
          'has_more_transfer_groups', false,
          'has_more_membership_seed', false,
          'next_transfer_scope_id', NULL::text,
          'next_cursor', NULL::jsonb,
          'next_required_phase', 'START_AUTHORISATION_PROOF',
          'server_utc', v_now::text
        );
      END IF;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          phase = 'REVIEW_REQUIRED',
          progress_json = jsonb_strip_nulls(
            coalesce(operation_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_transfer_scope_seed_at_utc', v_now::text,
              'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
              'transfer_scope_group_seed_complete', true,
              'transfer_scope_count', 0,
              'unseeded_transfer_scope_count', 0,
              'membership_seed_required', false,
              'no_transfer_scope', true,
              'next_required_phase', 'REVIEW_REQUIRED'
            )
          ),
          updated_at_utc = v_now
      WHERE operation_update.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'code', 'NO_ELIGIBLE_TRANSFER_SCOPE',
        'message', 'No eligible payable transfer scope was available for this operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'bounded', true,
        'limit', v_limit,
        'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
        'source_item_page_count', 0,
        'group_seeded_count', 0,
        'membership_seeded_count', 0,
        'transfer_scope_count', 0,
        'unseeded_transfer_scope_count', 0,
        'review_scope_count', coalesce(v_review_scope_count, 0),
        'membership_seed_required', false,
        'no_transfer_scope', true,
        'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
        'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
        'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
        'has_more_transfer_groups', false,
        'has_more_membership_seed', false,
        'next_transfer_scope_id', NULL::text,
        'next_cursor', NULL::jsonb,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
  END IF;

  v_membership_seed_required := coalesce(v_has_more, false) IS NOT TRUE AND coalesce(v_unseeded_transfer_scope_count, 0) > 0;
  v_next_required_phase := CASE
    WHEN coalesce(v_has_more, false) THEN 'TRANSFER_GROUP_SEED_PAGE'
    WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS'
    ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS'
  END;

  UPDATE public.banking_pay_operations AS operation_update
  SET pay_batch_id = p_pay_batch_id,
      phase = CASE
        WHEN coalesce(v_has_more, false) THEN 'SEED_TRANSFER_SCOPE'
        WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS'
        ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS'
      END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_seed_at_utc', v_now::text,
          'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
          'transfer_scope_group_seed_complete', coalesce(v_has_more, false) IS NOT TRUE,
          'transfer_scope_count', coalesce(v_cached_scope_count, 0),
          'unseeded_transfer_scope_count', CASE WHEN coalesce(v_has_more, false) THEN NULL::integer ELSE coalesce(v_unseeded_transfer_scope_count, 0) END,
          'membership_seed_required', coalesce(v_membership_seed_required, false),
          'next_transfer_scope_id', CASE WHEN coalesce(v_membership_seed_required, false) AND v_next_transfer_scope_id IS NOT NULL THEN v_next_transfer_scope_id::text ELSE NULL::text END,
          'has_more_transfer_groups', coalesce(v_has_more, false),
          'transfer_scope_seed_cursor', CASE WHEN coalesce(v_has_more, false) THEN v_next_cursor ELSE NULL::jsonb END,
          'next_required_phase', v_next_required_phase,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes
        )
        || v_no_bank_proof_json
        || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_channel_scope', v_scope,
    'bounded', true,
    'limit', v_limit,
    'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
    'source_item_page_count', LEAST(coalesce(v_page_count, 0), v_limit),
    'group_seeded_count', coalesce(v_group_seeded_count, 0),
    'membership_seeded_count', 0,
    'transfer_scope_count', coalesce(v_cached_scope_count, 0),
    'unseeded_transfer_scope_count', CASE WHEN coalesce(v_has_more, false) THEN NULL::integer ELSE coalesce(v_unseeded_transfer_scope_count, 0) END,
    'review_scope_count', coalesce(v_review_scope_count, 0),
    'membership_seed_required', coalesce(v_membership_seed_required, false),
    'no_transfer_scope', false,
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
    'no_bank_payment_execution', v_no_bank_payment_execution,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
    'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
    'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
    'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
    'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
    'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
    'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
    'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
    'paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
    'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
    'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
    'has_more_transfer_groups', coalesce(v_has_more, false),
    'has_more_membership_seed', coalesce(v_membership_seed_required, false),
    'next_transfer_scope_id', CASE WHEN coalesce(v_membership_seed_required, false) AND v_next_transfer_scope_id IS NOT NULL THEN v_next_transfer_scope_id::text ELSE NULL::text END,
    'next_cursor', CASE WHEN coalesce(v_has_more, false) THEN v_next_cursor ELSE NULL::jsonb END,
    'next_required_phase', v_next_required_phase,
    'server_utc', v_now::text
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_bank_transfers_claim_provider_submit_chunk(uuid, uuid, integer, text, integer);



DROP FUNCTION IF EXISTS public.pay_operation_remittance_scope_seed(uuid, uuid, text, uuid);

CREATE OR REPLACE FUNCTION public.pay_bank_transfers_claim_provider_submit_chunk(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_limit integer DEFAULT 50,
  p_lock_owner text DEFAULT NULL::text,
  p_lock_seconds integer DEFAULT 60
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_limit integer := LEAST(GREATEST(coalesce(p_limit, 25), 1), 25);
  v_lock_seconds integer := LEAST(GREATEST(coalesce(p_lock_seconds, 60), 10), 3600);
  v_lock_owner text := coalesce(nullif(btrim(coalesce(p_lock_owner, '')), ''), 'provider-submit:' || p_operation_id::text);
  v_pay_channel_scope text := 'ALL';
  v_chunk_id uuid := NULL::uuid;
  v_sequence_no integer := 1;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_transfer_rows jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_same_operation_authorised_auth_count integer := 0;
  v_claimed_count integer := 0;
  v_remaining_count integer := 0;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_bank_transfers_claim_provider_submit_chunk: operation_id is required';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_bank_transfers_claim_provider_submit_chunk: pay_batch_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'operation % is not a payment execution operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_SUBMIT_CLAIM_EXECUTION_BOUNDARY_CROSSED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_SUBMIT_CLAIM_EXECUTION_BOUNDARY_CROSSED', 'pay_batch_id', p_pay_batch_id::text, 'operation_id', p_operation_id::text)::text;
  END IF;

  v_pay_channel_scope := upper(btrim(coalesce(
    nullif(btrim(coalesce(v_operation_row.input_json->>'pay_channel_scope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.input_json->>'payChannelScope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.config_json->>'pay_channel_scope', '')), ''),
    nullif(btrim(coalesce(v_operation_row.config_json->>'payChannelScope', '')), ''),
    'ALL'
  )));
  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'LOANS', 'ALL') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  SELECT count(*)::integer,
         coalesce(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc DESC NULLS LAST, auth_request.id), '[]'::jsonb)
  INTO v_same_operation_authorised_auth_count,
       v_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state = 'AUTHORISED'
    AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text;

  IF coalesce(v_same_operation_authorised_auth_count, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'claim_ok', false,
      'claim_blocked', true,
      'claim_blocker_code', 'AUTH_REQUEST_NOT_AUTHORISED_FOR_OPERATION',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'chunk_id', NULL,
      'transfer_scope_ids', '[]'::jsonb,
      'auth_request_ids', '[]'::jsonb,
      'transfers', '[]'::jsonb,
      'claimed_count', 0,
      'remaining_count', 0,
      'provider_submission_status', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
      'review_reason_code', 'AUTH_REQUEST_NOT_AUTHORISED_FOR_OPERATION'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_claimed_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_claimed_scope (
    transfer_scope_id uuid PRIMARY KEY,
    pay_bank_transfer_id uuid NOT NULL,
    claim_ordinal integer NOT NULL
  ) ON COMMIT DROP;

  WITH locked_scope AS (
    SELECT scope_row.id AS transfer_scope_id,
           scope_row.pay_bank_transfer_id,
           scope_row.updated_at_utc
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = scope_row.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = scope_row.pay_batch_id
     AND transfer_row.pay_channel = scope_row.pay_channel
     AND transfer_row.transfer_group_key = scope_row.transfer_group_key
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL
      AND upper(btrim(coalesce(transfer_row.status, ''))) = 'PENDING'
      AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NULL
      AND transfer_row.completed_at_utc IS NULL
      AND nullif(btrim(coalesce(transfer_row.failed_reason, '')), '') IS NULL
      AND (v_pay_channel_scope = 'ALL' OR upper(btrim(coalesce(scope_row.pay_channel, ''))) = v_pay_channel_scope)
    ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id
    LIMIT v_limit
    FOR UPDATE OF scope_row, transfer_row SKIP LOCKED
  ), claimable_scope AS (
    SELECT locked_scope.transfer_scope_id,
           locked_scope.pay_bank_transfer_id,
           row_number() OVER (ORDER BY locked_scope.updated_at_utc NULLS FIRST, locked_scope.transfer_scope_id)::integer AS claim_ordinal
    FROM locked_scope
  )
  INSERT INTO pg_temp.tmp_provider_submit_claimed_scope (transfer_scope_id, pay_bank_transfer_id, claim_ordinal)
  SELECT claimable_scope.transfer_scope_id,
         claimable_scope.pay_bank_transfer_id,
         claimable_scope.claim_ordinal
  FROM claimable_scope;

  SELECT count(*)::integer
  INTO v_claimed_count
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope;

  IF coalesce(v_claimed_count, 0) <= 0 THEN
    SELECT count(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL;

    RETURN jsonb_build_object(
      'ok', false,
      'claim_ok', false,
      'claim_blocked', true,
      'claim_blocker_code', 'PROVIDER_SUBMIT_NO_ELIGIBLE_TRANSFERS',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'chunk_id', NULL,
      'transfer_scope_ids', '[]'::jsonb,
      'auth_request_ids', coalesce(v_auth_request_ids, '[]'::jsonb),
      'transfers', '[]'::jsonb,
      'claimed_count', 0,
      'remaining_count', coalesce(v_remaining_count, 0),
      'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED'
    );
  END IF;

  SELECT (count(*) + 1)::integer
  INTO v_sequence_no
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.operation_id = p_operation_id
    AND chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS'
    AND chunk_row.chunk_type = 'TRANSFER_SUBMIT';

  v_chunk_id := gen_random_uuid();

  SELECT coalesce(jsonb_agg(to_jsonb(claimed_scope.transfer_scope_id::text) ORDER BY claimed_scope.claim_ordinal), '[]'::jsonb),
         coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'transfer_scope_id', claimed_scope.transfer_scope_id::text,
           'pay_bank_transfer_id', transfer_row.id::text,
           'pay_batch_id', transfer_row.pay_batch_id::text,
           'payee_entity_kind', transfer_row.payee_entity_kind,
           'payee_entity_id', CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END,
           'candidate_id', CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END,
           'umbrella_id', CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END,
           'pay_channel', transfer_row.pay_channel,
           'amount', transfer_row.amount,
           'currency', coalesce(nullif(btrim(coalesce(transfer_row.currency, '')), ''), 'GBP'),
           'payment_reference', transfer_row.payment_reference,
           'payee_name', transfer_row.payee_name,
           'sort_code', transfer_row.sort_code,
           'account_number', transfer_row.account_number,
           'account_type', transfer_row.account_type,
           'bank_details_hash_snapshot', transfer_row.bank_details_hash_snapshot,
           'request_id', transfer_row.request_id,
           'idempotency_key', coalesce(nullif(btrim(coalesce(transfer_row.request_id, '')), ''), 'transfer:' || transfer_row.id::text),
           'funding_account_ref', v_batch_row.funding_account_ref,
           'rail_provider', transfer_row.rail_provider,
           'rail_env', transfer_row.rail_env,
           'transfer_group_key', transfer_row.transfer_group_key
         )) ORDER BY claimed_scope.claim_ordinal), '[]'::jsonb)
  INTO v_transfer_scope_ids,
       v_transfer_rows
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = claimed_scope.pay_bank_transfer_id;

  INSERT INTO public.banking_pay_operation_chunks (
    id,
    operation_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  VALUES (
    v_chunk_id,
    p_operation_id,
    'SUBMIT_PROVIDER_TRANSFERS',
    'TRANSFER_SUBMIT',
    v_sequence_no,
    'RUNNING',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
      'transfers', coalesce(v_transfer_rows, '[]'::jsonb),
      'claimed_at_utc', v_now::text,
      'lock_owner', v_lock_owner,
      'row_backed_provider_queue', true
    ),
    jsonb_build_object('provider_submit_stage', 'CLAIMED'),
    NULL::jsonb,
    coalesce(v_claimed_count, 0),
    0,
    0,
    v_lock_owner,
    v_now + make_interval(secs => v_lock_seconds),
    v_now,
    v_now,
    NULL::timestamptz,
    v_now
  );

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = 'CLAIMED',
      provider_submit_ready = false,
      provider_review_required = false,
      provider_unsafe_reason = NULL::text,
      provider_submit_chunk_id = v_chunk_id,
      provider_submit_claimed_at_utc = v_now,
      provider_submit_attempt_count = COALESCE(scope_update.provider_submit_attempt_count, 0) + 1,
      provider_idempotency_key = coalesce(nullif(btrim(scope_update.provider_idempotency_key), ''), coalesce(nullif(btrim(transfer_row.request_id), ''), 'scope:' || scope_update.id::text)),
      provider_request_id = coalesce(nullif(btrim(scope_update.provider_request_id), ''), transfer_row.request_id),
      updated_at_utc = v_now
  FROM pg_temp.tmp_provider_submit_claimed_scope AS claimed_scope
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = claimed_scope.pay_bank_transfer_id
  WHERE scope_update.id = claimed_scope.transfer_scope_id;

  SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
      AND coalesce(scope_row.provider_submit_ready, false) = true
      AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      AND scope_row.pay_bank_transfer_id IS NOT NULL
    LIMIT 1
  ) THEN 1 ELSE 0 END
  INTO v_remaining_count;

  RETURN jsonb_build_object(
    'ok', true,
    'claim_ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', v_chunk_id::text,
    'chunk_type', 'TRANSFER_SUBMIT',
    'phase', 'SUBMIT_PROVIDER_TRANSFERS',
    'sequence_no', v_sequence_no,
    'lock_owner', v_lock_owner,
    'lock_expires_at_utc', (v_now + make_interval(secs => v_lock_seconds))::text,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
    'auth_request_ids', coalesce(v_auth_request_ids, '[]'::jsonb),
    'transfers', coalesce(v_transfer_rows, '[]'::jsonb),
    'unit_count', coalesce(v_claimed_count, 0),
    'claimed_count', coalesce(v_claimed_count, 0),
    'remaining_count', coalesce(v_remaining_count, 0),
    'has_more', coalesce(v_remaining_count, 0) > 0,
    'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED',
    'manual_resolution_required', false
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_operation_remittance_scope_seed(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_scope text DEFAULT 'ALL'::text,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_scope text := upper(BTRIM(COALESCE(p_scope, 'ALL')));
  v_created_count integer := 0;
  v_reused_count integer := 0;
  v_recipient_count integer := 0;
  v_stale_scope_skipped_count integer := 0;
  v_trigger text;
  v_only_confirmed boolean := false;
  v_configured_timing text := 'ON_EXECUTION';
  v_batch_status text := null;
  v_batch_schedule_kind text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;
  v_scheduled_execution_eligible boolean := false;
  v_deferred_by_timing boolean := false;
  v_pending_provider_skipped_count integer := 0;
  v_no_transfer_skipped_count integer := 0;
  v_terminal_no_money_skipped_count integer := 0;
  v_confirmed_scope_row_count integer := 0;
  v_scheduled_scope_row_count integer := 0;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope NOT IN ('ALL', 'CANDIDATE', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'p_scope must be ALL, CANDIDATE, PAYE, or UMBRELLA';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
  END IF;

  IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
    RAISE EXCEPTION 'operation % is not a remittance-capable operation', p_operation_id;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
  END IF;

  IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batches row % not found', p_pay_batch_id;
  END IF;


  v_trigger := upper(btrim(coalesce(
    nullif(btrim(coalesce(v_operation_row.input_json->>'trigger', '')), ''),
    CASE
      WHEN v_operation_row.operation_type = 'PAYMENT_SETTLEMENT' THEN 'ON_PAYMENT_CONFIRMED'
      ELSE 'ON_EXECUTION'
    END
  )));

  v_only_confirmed := lower(btrim(coalesce(v_operation_row.input_json->>'only_confirmed', 'false'))) IN ('true','1','yes','y','on');

  IF v_trigger NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    RAISE EXCEPTION 'unsupported remittance trigger %', v_trigger;
  END IF;

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_remittance_send_timing), ''), 'ON_EXECUTION')
  INTO v_configured_timing
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_configured_timing := upper(coalesce(nullif(btrim(v_configured_timing), ''), 'ON_EXECUTION'));

  IF v_configured_timing NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    v_configured_timing := 'ON_EXECUTION';
  END IF;

  v_deferred_by_timing := v_configured_timing <> v_trigger;

  IF v_batch_row.execution_intent_json IS NOT NULL AND jsonb_typeof(v_batch_row.execution_intent_json) = 'object' THEN
    v_execution_intent_json := v_batch_row.execution_intent_json;
  ELSE
    v_execution_intent_json := '{}'::jsonb;
  END IF;

  IF v_batch_row.settlement_confirmation_json IS NOT NULL AND jsonb_typeof(v_batch_row.settlement_confirmation_json) = 'object' THEN
    v_settlement_confirmation_json := v_batch_row.settlement_confirmation_json;
  ELSE
    v_settlement_confirmation_json := '{}'::jsonb;
  END IF;

  v_batch_status := upper(btrim(coalesce(v_batch_row.status, '')));
  v_batch_schedule_kind := upper(btrim(coalesce(v_batch_row.schedule_kind, v_execution_intent_json->>'schedule_kind', '')));

  IF v_deferred_by_timing THEN
    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'trigger', v_trigger,
      'configured_timing', v_configured_timing,
      'only_confirmed', v_only_confirmed,
      'deferred', true,
      'suppressed', false,
      'scope_rows_created', 0,
      'scope_rows_reused', 0,
      'recipient_count', 0,
      'stale_scope_skipped_count', 0,
      'scheduled_scope_rows', 0,
      'confirmed_scope_rows', 0,
      'pending_provider_skipped_count', 0,
      'no_transfer_skipped_count', 0,
      'terminal_no_money_skipped_count', 0,
      'scheduled_execution_eligible', false,
      'trigger_status', 'REMITTANCE_SCOPE_DEFERRED_BY_CONFIGURED_TIMING'
    );
  END IF;

  v_suppress_remittances :=
    lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances_pending', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_settlement_confirmation_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_settlement_confirmation_json->>'suppress_remittances_pending', 'false'))) IN ('true','1','yes','y','on')
    OR lower(btrim(coalesce(v_operation_row.input_json->>'suppress_remittances', 'false'))) IN ('true','1','yes','y','on');

  IF v_suppress_remittances THEN
    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'trigger', v_trigger,
      'configured_timing', v_configured_timing,
      'only_confirmed', v_only_confirmed,
      'deferred', false,
      'suppressed', true,
      'scope_rows_created', 0,
      'scope_rows_reused', 0,
      'recipient_count', 0,
      'stale_scope_skipped_count', 0,
      'scheduled_scope_rows', 0,
      'confirmed_scope_rows', 0,
      'pending_provider_skipped_count', 0,
      'no_transfer_skipped_count', 0,
      'terminal_no_money_skipped_count', 0,
      'scheduled_execution_eligible', false,
      'trigger_status', 'REMITTANCE_SCOPE_SUPPRESSED'
    );
  END IF;

  v_scheduled_execution_eligible :=
    v_operation_row.operation_type = 'REMITTANCE_QUEUE'
    AND v_trigger = 'ON_EXECUTION'
    AND v_configured_timing = 'ON_EXECUTION'
    AND COALESCE(v_only_confirmed, false) = false
    AND v_batch_schedule_kind = 'SCHEDULED'
    AND v_batch_row.scheduled_at_utc IS NOT NULL
    AND v_batch_status NOT IN (
      'BLOCKED_FUNDS',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'REJECTED',
      'DECLINED',
      'RETURNED',
      'VOID',
      'DELETED'
    )
    AND lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) NOT IN ('true','1','yes','y','on')
    AND (
      v_operation_row.root_operation_id IS NULL
      OR nullif(btrim(coalesce(v_execution_intent_json->>'operation_id', '')), '') IS NULL
      OR v_execution_intent_json->>'operation_id' = v_operation_row.root_operation_id::text
    );

  WITH scoped_item_rows AS (
    SELECT
      batch_candidate.id AS pay_batch_candidate_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_bank_transfer_id,
      upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) AS settlement_status,
      transfer_row.id AS transfer_id,
      upper(BTRIM(COALESCE(transfer_row.status, ''))) AS transfer_status,
      upper(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS transfer_rail_state,
      transfer_row.completed_at_utc,
      COALESCE(transfer_classifier.is_final_money_moved, false) AS is_final_money_moved,
      COALESCE(transfer_classifier.is_terminal_no_money, false) AS is_terminal_no_money,
      COALESCE(transfer_classifier.is_pending_non_final, false) AS is_pending_non_final
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = batch_item.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      transfer_row.status,
      transfer_row.rail_state,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier ON transfer_row.id IS NOT NULL
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      AND (
        v_scope = 'ALL'
        OR (v_scope IN ('CANDIDATE', 'PAYE') AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE')
        OR (v_scope = 'UMBRELLA' AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'UMBRELLA')
      )
  ), scoped_item_flags AS (
    SELECT
      scoped_item_rows.*,
      (
        scoped_item_rows.settlement_status IN ('SETTLED', 'PAID', 'CONFIRMED')
        OR scoped_item_rows.is_final_money_moved
        OR scoped_item_rows.transfer_status IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR scoped_item_rows.transfer_rail_state IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR scoped_item_rows.completed_at_utc IS NOT NULL
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
          WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id
            AND settlement_scope_row.pay_batch_candidate_id = scoped_item_rows.pay_batch_candidate_id
            AND settlement_scope_row.status = 'SETTLED'
            AND (
              (
                scoped_item_rows.pay_bank_transfer_id IS NOT NULL
                AND settlement_scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}' = scoped_item_rows.pay_bank_transfer_id::text
              )
              OR COALESCE(settlement_scope_row.payload_json->'pay_batch_item_ids', '[]'::jsonb) ? scoped_item_rows.pay_batch_item_id::text
            )
        )
      ) AS confirmed_or_final,
      (
        scoped_item_rows.is_pending_non_final
        OR scoped_item_rows.transfer_status IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION', 'WAITING', 'WAITING_BANK_CONFIRM')
        OR scoped_item_rows.transfer_rail_state IN ('PENDING', 'SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION', 'WAITING', 'WAITING_BANK_CONFIRM')
      ) AS pending_provider,
      (
        scoped_item_rows.is_terminal_no_money
        OR scoped_item_rows.transfer_status IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
        OR scoped_item_rows.transfer_rail_state IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
      ) AS terminal_no_money
    FROM scoped_item_rows
  )
  SELECT
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NOT NULL AND scoped_item_flags.pending_provider IS TRUE AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END,
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NULL AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END,
    CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COUNT(*) FILTER (WHERE scoped_item_flags.pay_bank_transfer_id IS NOT NULL AND scoped_item_flags.terminal_no_money IS TRUE AND scoped_item_flags.confirmed_or_final IS NOT TRUE)::integer END
  INTO v_pending_provider_skipped_count,
       v_no_transfer_skipped_count,
       v_terminal_no_money_skipped_count
  FROM scoped_item_flags;

  WITH eligible_item_rows AS (
    SELECT
      batch_candidate.id AS pay_batch_candidate_id,
      batch_candidate.candidate_id,
      upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) AS pay_channel,
      batch_item.umbrella_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_bank_transfer_id,
      transfer_row.transfer_group_key,
      COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS item_amount,
      CASE
        WHEN batch_item.pay_bank_transfer_id IS NOT NULL THEN 'transfer:' || batch_item.pay_bank_transfer_id::text
        ELSE 'batch_candidate:' || batch_candidate.id::text || ':channel:' || upper(BTRIM(COALESCE(batch_item.pay_channel, '')))
      END AS payment_scope_key
    FROM public.pay_batch_candidates AS batch_candidate
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = batch_item.pay_bank_transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      transfer_row.status,
      transfer_row.rail_state,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier ON transfer_row.id IS NOT NULL
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND COALESCE(batch_item.item_type, '') <> 'DEBT_CREATED'
      AND (
        v_scheduled_execution_eligible
        OR upper(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) IN ('SETTLED', 'PAID', 'CONFIRMED')
        OR COALESCE(transfer_classifier.is_final_money_moved, false)
        OR upper(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR upper(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED', 'COMPLETE', 'SETTLED', 'PAID', 'EXECUTED', 'COMMITTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        OR transfer_row.completed_at_utc IS NOT NULL
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
          WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id
            AND settlement_scope_row.pay_batch_candidate_id = batch_candidate.id
            AND settlement_scope_row.status = 'SETTLED'
            AND (
              (
                batch_item.pay_bank_transfer_id IS NOT NULL
                AND settlement_scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}' = batch_item.pay_bank_transfer_id::text
              )
              OR COALESCE(settlement_scope_row.payload_json->'pay_batch_item_ids', '[]'::jsonb) ? batch_item.id::text
            )
        )
      )
      AND (
        v_scope = 'ALL'
        OR (v_scope IN ('CANDIDATE', 'PAYE') AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'PAYE')
        OR (v_scope = 'UMBRELLA' AND upper(BTRIM(COALESCE(batch_item.pay_channel, ''))) = 'UMBRELLA')
      )
  ), candidate_scope AS (
    SELECT
      eligible_item_rows.pay_batch_candidate_id,
      eligible_item_rows.candidate_id,
      'CANDIDATE'::text AS recipient_kind,
      eligible_item_rows.candidate_id AS recipient_id,
      'CANDIDATE_REMITTANCE'::text AS remittance_type,
      'remittance:batch:' || p_pay_batch_id::text || ':candidate:' || eligible_item_rows.candidate_id::text || ':scope:' || eligible_item_rows.payment_scope_key || ':type:CANDIDATE_REMITTANCE' AS deterministic_outbox_key,
      eligible_item_rows.payment_scope_key,
      eligible_item_rows.pay_bank_transfer_id,
      eligible_item_rows.transfer_group_key,
      COALESCE(jsonb_agg(to_jsonb(eligible_item_rows.pay_batch_item_id::text) ORDER BY eligible_item_rows.pay_batch_item_id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) AS total_amount
    FROM eligible_item_rows
    WHERE eligible_item_rows.pay_channel = 'PAYE'
      AND v_scope IN ('ALL', 'CANDIDATE', 'PAYE')
    GROUP BY eligible_item_rows.pay_batch_candidate_id,
             eligible_item_rows.candidate_id,
             eligible_item_rows.payment_scope_key,
             eligible_item_rows.pay_bank_transfer_id,
             eligible_item_rows.transfer_group_key
    HAVING ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) <> 0
  ), umbrella_scope AS (
    SELECT
      eligible_item_rows.pay_batch_candidate_id,
      eligible_item_rows.candidate_id,
      'UMBRELLA'::text AS recipient_kind,
      eligible_item_rows.umbrella_id AS recipient_id,
      'UMBRELLA_REMITTANCE'::text AS remittance_type,
      'remittance:batch:' || p_pay_batch_id::text || ':candidate:' || eligible_item_rows.candidate_id::text || ':umbrella:' || eligible_item_rows.umbrella_id::text || ':scope:' || eligible_item_rows.payment_scope_key || ':type:UMBRELLA_REMITTANCE' AS deterministic_outbox_key,
      eligible_item_rows.payment_scope_key,
      eligible_item_rows.pay_bank_transfer_id,
      eligible_item_rows.transfer_group_key,
      COALESCE(jsonb_agg(to_jsonb(eligible_item_rows.pay_batch_item_id::text) ORDER BY eligible_item_rows.pay_batch_item_id::text), '[]'::jsonb) AS pay_batch_item_ids_json,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) AS total_amount
    FROM eligible_item_rows
    WHERE eligible_item_rows.pay_channel = 'UMBRELLA'
      AND eligible_item_rows.umbrella_id IS NOT NULL
      AND v_scope IN ('ALL', 'UMBRELLA')
    GROUP BY eligible_item_rows.pay_batch_candidate_id,
             eligible_item_rows.candidate_id,
             eligible_item_rows.umbrella_id,
             eligible_item_rows.payment_scope_key,
             eligible_item_rows.pay_bank_transfer_id,
             eligible_item_rows.transfer_group_key
    HAVING ROUND(COALESCE(SUM(eligible_item_rows.item_amount), 0), 2) <> 0
  ), scope_rows AS (
    SELECT candidate_scope.pay_batch_candidate_id,
           candidate_scope.candidate_id,
           candidate_scope.recipient_kind,
           candidate_scope.recipient_id,
           candidate_scope.remittance_type,
           candidate_scope.deterministic_outbox_key,
           jsonb_build_object(
             'pay_batch_id', p_pay_batch_id::text,
             'pay_batch_candidate_id', candidate_scope.pay_batch_candidate_id::text,
             'candidate_id', candidate_scope.candidate_id::text,
             'recipient_kind', candidate_scope.recipient_kind,
             'recipient_id', candidate_scope.recipient_id::text,
             'remittance_type', candidate_scope.remittance_type,
             'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
               'scope_key', candidate_scope.payment_scope_key,
               'pay_bank_transfer_id', CASE WHEN candidate_scope.pay_bank_transfer_id IS NULL THEN NULL ELSE candidate_scope.pay_bank_transfer_id::text END,
               'transfer_group_key', candidate_scope.transfer_group_key,
               'remittance_trigger', CASE WHEN v_scheduled_execution_eligible THEN v_trigger ELSE NULL END,
               'configured_timing', CASE WHEN v_scheduled_execution_eligible THEN v_configured_timing ELSE NULL END,
               'scheduled_execution_eligible', CASE WHEN v_scheduled_execution_eligible THEN true ELSE NULL END,
               'scheduled_at_utc', CASE WHEN v_scheduled_execution_eligible AND v_batch_row.scheduled_at_utc IS NOT NULL THEN v_batch_row.scheduled_at_utc::text ELSE NULL END,
               'schedule_kind', CASE WHEN v_scheduled_execution_eligible THEN v_batch_schedule_kind ELSE NULL END
             )),
             'pay_batch_item_ids', candidate_scope.pay_batch_item_ids_json,
             'item_count', candidate_scope.item_count,
             'total_amount', candidate_scope.total_amount,
             'scope', v_scope
           ) AS payload_json
    FROM candidate_scope

    UNION ALL

    SELECT umbrella_scope.pay_batch_candidate_id,
           umbrella_scope.candidate_id,
           umbrella_scope.recipient_kind,
           umbrella_scope.recipient_id,
           umbrella_scope.remittance_type,
           umbrella_scope.deterministic_outbox_key,
           jsonb_build_object(
             'pay_batch_id', p_pay_batch_id::text,
             'pay_batch_candidate_id', umbrella_scope.pay_batch_candidate_id::text,
             'candidate_id', umbrella_scope.candidate_id::text,
             'recipient_kind', umbrella_scope.recipient_kind,
             'recipient_id', umbrella_scope.recipient_id::text,
             'remittance_type', umbrella_scope.remittance_type,
             'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
               'scope_key', umbrella_scope.payment_scope_key,
               'pay_bank_transfer_id', CASE WHEN umbrella_scope.pay_bank_transfer_id IS NULL THEN NULL ELSE umbrella_scope.pay_bank_transfer_id::text END,
               'transfer_group_key', umbrella_scope.transfer_group_key,
               'remittance_trigger', CASE WHEN v_scheduled_execution_eligible THEN v_trigger ELSE NULL END,
               'configured_timing', CASE WHEN v_scheduled_execution_eligible THEN v_configured_timing ELSE NULL END,
               'scheduled_execution_eligible', CASE WHEN v_scheduled_execution_eligible THEN true ELSE NULL END,
               'scheduled_at_utc', CASE WHEN v_scheduled_execution_eligible AND v_batch_row.scheduled_at_utc IS NOT NULL THEN v_batch_row.scheduled_at_utc::text ELSE NULL END,
               'schedule_kind', CASE WHEN v_scheduled_execution_eligible THEN v_batch_schedule_kind ELSE NULL END
             )),
             'pay_batch_item_ids', umbrella_scope.pay_batch_item_ids_json,
             'item_count', umbrella_scope.item_count,
             'total_amount', umbrella_scope.total_amount,
             'scope', v_scope
           ) AS payload_json
    FROM umbrella_scope
  ), stale_scope AS (
    UPDATE public.banking_pay_operation_remittance_scope AS scope_update
    SET status = 'SKIPPED',
        updated_at_utc = v_now
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.pay_batch_id = p_pay_batch_id
      AND scope_update.status IN ('PENDING', 'FAILED')
      AND NOT EXISTS (
        SELECT 1
        FROM scope_rows
        WHERE scope_rows.deterministic_outbox_key = scope_update.deterministic_outbox_key
      )
    RETURNING scope_update.id
  ), upserted_scope AS (
    INSERT INTO public.banking_pay_operation_remittance_scope (
      operation_id,
      pay_batch_id,
      pay_batch_candidate_id,
      candidate_id,
      recipient_kind,
      recipient_id,
      remittance_type,
      deterministic_outbox_key,
      payload_json,
      status,
      outbox_id,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_operation_id,
      p_pay_batch_id,
      scope_rows.pay_batch_candidate_id,
      scope_rows.candidate_id,
      scope_rows.recipient_kind,
      scope_rows.recipient_id,
      scope_rows.remittance_type,
      scope_rows.deterministic_outbox_key,
      scope_rows.payload_json,
      'PENDING',
      NULL::uuid,
      v_now,
      v_now
    FROM scope_rows
    ON CONFLICT (operation_id, deterministic_outbox_key)
    DO UPDATE
    SET pay_batch_candidate_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.pay_batch_candidate_id ELSE EXCLUDED.pay_batch_candidate_id END,
        candidate_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.candidate_id ELSE EXCLUDED.candidate_id END,
        recipient_kind = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.recipient_kind ELSE EXCLUDED.recipient_kind END,
        recipient_id = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.recipient_id ELSE EXCLUDED.recipient_id END,
        remittance_type = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.remittance_type ELSE EXCLUDED.remittance_type END,
        payload_json = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.payload_json ELSE EXCLUDED.payload_json END,
        status = CASE WHEN public.banking_pay_operation_remittance_scope.status = 'QUEUED' THEN public.banking_pay_operation_remittance_scope.status ELSE EXCLUDED.status END,
        updated_at_utc = v_now
    RETURNING public.banking_pay_operation_remittance_scope.id,
              public.banking_pay_operation_remittance_scope.recipient_kind,
              public.banking_pay_operation_remittance_scope.recipient_id,
              (xmax = 0) AS was_inserted
  )
  SELECT COUNT(*) FILTER (WHERE upserted_scope.was_inserted)::integer,
         COUNT(*) FILTER (WHERE upserted_scope.was_inserted IS NOT TRUE)::integer,
         COUNT(DISTINCT upserted_scope.recipient_kind || ':' || upserted_scope.recipient_id::text)::integer,
         COALESCE((SELECT COUNT(*)::integer FROM stale_scope), 0)
  INTO v_created_count,
       v_reused_count,
       v_recipient_count,
       v_stale_scope_skipped_count
  FROM upserted_scope;

  v_scheduled_scope_row_count := CASE WHEN v_scheduled_execution_eligible THEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) ELSE 0 END;
  v_confirmed_scope_row_count := CASE WHEN v_scheduled_execution_eligible THEN 0 ELSE COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) END;

  UPDATE public.banking_pay_operations AS operation_update
  SET pay_batch_id = p_pay_batch_id,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id
    AND operation_update.pay_batch_id IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'scope', v_scope,
    'trigger', v_trigger,
    'configured_timing', v_configured_timing,
    'only_confirmed', v_only_confirmed,
    'scheduled_execution_eligible', v_scheduled_execution_eligible,
    'deferred', false,
    'suppressed', false,
    'trigger_status', CASE
      WHEN v_scheduled_execution_eligible THEN 'SCHEDULED_ON_EXECUTION_SCOPE_SEEDED'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_pending_provider_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_DEFERRED_PENDING_PROVIDER'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_no_transfer_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_DEFERRED_NO_TRANSFER'
      WHEN COALESCE(v_created_count, 0) + COALESCE(v_reused_count, 0) = 0 AND COALESCE(v_terminal_no_money_skipped_count, 0) > 0 THEN 'STANDARD_REMITTANCE_SCOPE_SKIPPED_TERMINAL_NO_MONEY'
      ELSE 'STANDARD_REMITTANCE_SCOPE_SEEDED'
    END,
    'scope_rows_created', COALESCE(v_created_count, 0),
    'scope_rows_reused', COALESCE(v_reused_count, 0),
    'recipient_count', COALESCE(v_recipient_count, 0),
    'stale_scope_skipped_count', COALESCE(v_stale_scope_skipped_count, 0),
    'scheduled_scope_rows', COALESCE(v_scheduled_scope_row_count, 0),
    'confirmed_scope_rows', COALESCE(v_confirmed_scope_row_count, 0),
    'pending_provider_skipped_count', COALESCE(v_pending_provider_skipped_count, 0),
    'no_transfer_skipped_count', COALESCE(v_no_transfer_skipped_count, 0),
    'terminal_no_money_skipped_count', COALESCE(v_terminal_no_money_skipped_count, 0)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness_chunk(p_operation_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_invalid_scope_unit_count integer := 0;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_ordinal bigint := NULL::bigint;
  v_cursor_unit_key text := NULL::text;
  v_cursor_has_ordinal boolean := false;
  v_cursor_has_unit_key boolean := false;
  v_cursor_operation_id uuid := NULL::uuid;
  v_cursor_pay_batch_id uuid := NULL::uuid;
  v_raw_count integer := 0;
  v_validated_count integer := 0;
  v_fresh_count integer := 0;
  v_stale_count integer := 0;
  v_error_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_diff_samples jsonb := '[]'::jsonb;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_combined_stale_reasons jsonb := '[]'::jsonb;
  v_combined_diff_samples jsonb := '[]'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_prev_fresh_units integer := 0;
  v_prev_stale_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_error_units integer := 0;
  v_new_total_units integer := 0;
  v_new_seeded_units integer := 0;
  v_new_fresh_units integer := 0;
  v_new_stale_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_error_units integer := 0;
  v_new_status text := 'PENDING';
  v_persisted_batch_status text := 'PENDING';
  v_scope_hash text := NULL::text;
  v_prev_result_hash text := NULL::text;
  v_page_result_hash text := NULL::text;
  v_new_result_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
     OR UPPER(BTRIM(COALESCE(v_operation.status, ''))) <> 'RUNNING'
     OR UPPER(BTRIM(COALESCE(v_operation.phase, ''))) NOT IN ('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
     OR v_operation.pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'operation_type', v_operation.operation_type,
              'operation_status', v_operation.status,
              'operation_phase', v_operation.phase,
              'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
              'required_operation_types', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
              'required_status', 'RUNNING',
              'allowed_phases', jsonb_build_array('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation.pay_batch_id
  FOR UPDATE OF batch_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text
            )::text;
  END IF;

  IF v_batch.freshness_operation_id IS NOT NULL
     AND v_batch.freshness_operation_id IS DISTINCT FROM p_operation_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'current_freshness_operation_id', v_batch.freshness_operation_id::text
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_invalid_scope_unit_count
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id;

  IF COALESCE(v_invalid_scope_unit_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'invalid_scope_unit_count', v_invalid_scope_unit_count
            )::text;
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := CASE
    WHEN COALESCE(v_date_context->>'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN (v_date_context->>'london_current_date')::date
    ELSE NULL::date
  END;
  IF v_today_uk IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE',
              'operation_id', p_operation_id::text,
              'message', 'The current Europe/London business date could not be resolved for chunked batch freshness.'
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL THEN
    IF jsonb_typeof(p_cursor_json) <> 'object' THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_MUST_BE_OBJECT'
              )::text;
    END IF;

    v_cursor_has_ordinal := p_cursor_json ? 'last_unit_ordinal';
    v_cursor_has_unit_key := p_cursor_json ? 'last_unit_key';

    IF v_cursor_has_ordinal IS DISTINCT FROM v_cursor_has_unit_key THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_ORDINAL_AND_KEY_REQUIRED_TOGETHER'
              )::text;
    END IF;

    IF v_cursor_has_ordinal THEN
      IF COALESCE(p_cursor_json->>'last_unit_ordinal', '') !~ '^[0-9]+$'
         OR NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '') IS NULL THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_ORDINAL_OR_KEY_INVALID'
                )::text;
      END IF;

      BEGIN
        v_cursor_ordinal := (p_cursor_json->>'last_unit_ordinal')::bigint;
      EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
          RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                    'operation_id', p_operation_id::text,
                    'pay_batch_id', v_operation.pay_batch_id::text,
                    'reason', 'CURSOR_ORDINAL_OUT_OF_RANGE'
                  )::text;
      END;
      v_cursor_unit_key := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '');
    END IF;

    IF p_cursor_json ? 'operation_id' THEN
      IF COALESCE(p_cursor_json->>'operation_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_OPERATION_ID_INVALID'
                )::text;
      END IF;
      v_cursor_operation_id := (p_cursor_json->>'operation_id')::uuid;
      IF v_cursor_operation_id IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'cursor_operation_id', v_cursor_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text
                )::text;
      END IF;
    END IF;

    IF p_cursor_json ? 'pay_batch_id' THEN
      IF COALESCE(p_cursor_json->>'pay_batch_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_PAY_BATCH_ID_INVALID'
                )::text;
      END IF;
      v_cursor_pay_batch_id := (p_cursor_json->>'pay_batch_id')::uuid;
      IF v_cursor_pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'cursor_pay_batch_id', v_cursor_pay_batch_id::text
                )::text;
      END IF;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validate_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validate_page ON COMMIT DROP AS
  SELECT
    scope_unit.operation_id,
    scope_unit.pay_batch_id,
    scope_unit.phase,
    scope_unit.unit_type,
    scope_unit.unit_key,
    scope_unit.unit_payload_json,
    scope_unit.unit_ordinal,
    scope_unit.status,
    row_number() OVER (ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key)::integer AS page_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id = v_operation.pay_batch_id
    AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) IN ('PENDING', 'QUEUED', 'READY')
    AND (
      v_cursor_ordinal IS NULL
      OR scope_unit.unit_ordinal > v_cursor_ordinal
      OR (scope_unit.unit_ordinal = v_cursor_ordinal AND v_cursor_unit_key IS NOT NULL AND scope_unit.unit_key > v_cursor_unit_key)
    )
  ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row;

  v_has_more := COALESCE(v_raw_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validation_result;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validation_result ON COMMIT DROP AS
  WITH page_rows AS (
    SELECT page_row.*,
           CASE
             WHEN COALESCE(page_row.unit_payload_json->>'pay_batch_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (page_row.unit_payload_json->>'pay_batch_item_id')::uuid
             ELSE NULL::uuid
           END AS pay_batch_item_id,
           UPPER(NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_type}', '')), '')) AS stored_key_type,
           NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_value}', '')), '') AS stored_key_value,
           CASE
             WHEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id')::uuid
             ELSE NULL::uuid
           END AS stored_timesheet_id,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_ex_vat}')::numeric ELSE NULL::numeric END AS stored_amount_ex_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_vat}')::numeric ELSE NULL::numeric END AS stored_amount_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_inc_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_inc_vat}')::numeric ELSE NULL::numeric END AS stored_amount_inc_vat
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
  ), live_items AS (
    SELECT
      page_rows.*,
      batch_item.id AS live_pay_batch_item_id,
      batch_item.timesheet_id AS live_timesheet_id,
      batch_item.item_type AS live_item_type,
      batch_item.amount_ex_vat AS live_amount_ex_vat,
      batch_item.amount_vat AS live_amount_vat,
      batch_item.amount_inc_vat AS live_amount_inc_vat,
      COALESCE(batch_item.is_voided, false) AS live_is_voided,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.payout_instruction_snapshot_json,
      NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') AS live_source_ref,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
        LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
      ) AS live_exact_source_ref,
      CASE
        WHEN COALESCE(
          CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
          LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
        ) ~* '^timesheet-expense:' THEN 'TIMESHEET_EXPENSE'
        WHEN batch_item.finance_case_id IS NOT NULL
          OR LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '')) ~* '^advance:' THEN 'FINANCE_CASE'
        WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') IS NOT NULL THEN 'EXACT_SOURCE'
        ELSE 'TIMESHEET_OR_SEGMENT'
      END AS live_source_identity_kind,
      NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') AS live_segment_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
      ) AS live_segment_stable_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
      ) AS live_segment_id,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
        (
          SELECT COALESCE(
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
          )
          FROM public.pay_batch_timesheet_snapshots AS snapshot_row
          WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
            AND snapshot_row.timesheet_id = batch_item.timesheet_id
          ORDER BY snapshot_row.id
          LIMIT 1
        )
      ) AS live_booking_id,
      batch_item.finance_case_id AS live_finance_case_id,
      batch_item.finance_component_id AS live_finance_component_id,
      (
        batch_item.finance_case_id IS NOT NULL
        OR COALESCE(
          NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
          false
        )
      ) AS live_is_finance_source,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL END,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
          ELSE NULL
        END
      ) AS live_finance_source_ref,
      batch_candidate.candidate_id AS live_candidate_id,
      active_snooze.id AS active_snooze_id,
      active_snooze.snooze_kind AS active_snooze_kind,
      active_snooze.snooze_until_date AS active_snooze_until_date,
      active_snooze.source_ref AS active_snooze_source_ref,
      active_snooze.segment_stable_key AS active_snooze_segment_stable_key,
      active_snooze.segment_id AS active_snooze_segment_id,
      active_snooze.booking_id AS active_snooze_booking_id,
      active_snooze.match_scope AS active_snooze_match_scope
    FROM page_rows
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = page_rows.pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = page_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        snooze_row.id,
        snooze_row.snooze_kind,
        snooze_row.snooze_until_date,
        snooze_row.source_ref,
        snooze_row.segment_stable_key,
        snooze_row.segment_id,
        snooze_row.booking_id,
        CASE
          WHEN snooze_row.source_ref IS NOT NULL THEN 'EXACT_SOURCE_REF'
          ELSE 'LEGACY_TIMESHEET_SEGMENT'
        END AS match_scope
      FROM public.pay_item_snoozes AS snooze_row
      WHERE snooze_row.candidate_id = batch_candidate.candidate_id
        AND snooze_row.cleared_at_utc IS NULL
        AND snooze_row.cancelled_at_utc IS NULL
        AND (
          snooze_row.snooze_until_date IS NULL
          OR snooze_row.snooze_until_date >= v_today_uk
        )
        AND (
          (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NOT NULL
            AND LOWER(NULLIF(BTRIM(COALESCE(snooze_row.source_ref, '')), '')) = COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            )
          )
          OR (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NULL
            AND snooze_row.source_ref IS NULL
            AND (
              (
                batch_item.timesheet_id IS NOT NULL
                AND snooze_row.timesheet_id = batch_item.timesheet_id
              )
              OR (
                NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
                  (
                    SELECT COALESCE(
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
                    )
                    FROM public.pay_batch_timesheet_snapshots AS snapshot_row
                    WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
                      AND snapshot_row.timesheet_id = batch_item.timesheet_id
                    ORDER BY snapshot_row.id
                    LIMIT 1
                  )
                )
              )
            )
            AND (
              (
                NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') IS NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') IS NULL
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                )
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                )
              )
              OR (
                NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IN (
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), ''),
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '')
                )
              )
            )
          )
        )
      ORDER BY snooze_row.updated_at_utc DESC, snooze_row.created_at_utc DESC, snooze_row.id
      LIMIT 1
    ) AS active_snooze ON TRUE
  ), resolved AS (
    SELECT
      live_items.*,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM live_items
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => live_items.live_pay_batch_item_id,
      p_pay_batch_id => live_items.pay_batch_id,
      p_timesheet_id => live_items.live_timesheet_id,
      p_item_type => live_items.live_item_type,
      p_frozen_key_type => live_items.frozen_component_key_type,
      p_frozen_key_value => live_items.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(live_items.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(live_items.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
  ), evaluated AS (
    SELECT
      resolved.*,
      (
        CASE WHEN resolved.live_pay_batch_item_id IS NULL THEN jsonb_build_array('PAY_BATCH_ITEM_MISSING') ELSE '[]'::jsonb END
        || CASE WHEN resolved.live_is_voided THEN jsonb_build_array('PAY_BATCH_ITEM_VOIDED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.resolved_key_type IS NULL OR resolved.resolved_key_value IS NULL THEN jsonb_build_array(COALESCE(resolved.key_resolution_failure_reason, 'POST_DRAFT_KEY_RESOLUTION_FAILED')) ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_type IS NOT NULL AND resolved.resolved_key_type IS NOT NULL AND resolved.stored_key_type IS DISTINCT FROM resolved.resolved_key_type THEN jsonb_build_array('ECONOMIC_KEY_TYPE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_value IS NOT NULL AND resolved.resolved_key_value IS NOT NULL AND resolved.stored_key_value IS DISTINCT FROM resolved.resolved_key_value THEN jsonb_build_array('ECONOMIC_KEY_VALUE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_timesheet_id IS NOT NULL AND resolved.resolved_timesheet_id IS NOT NULL AND resolved.stored_timesheet_id IS DISTINCT FROM resolved.resolved_timesheet_id THEN jsonb_build_array('ECONOMIC_TIMESHEET_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_ex_vat IS NOT NULL AND resolved.live_amount_ex_vat IS NOT NULL AND ROUND(resolved.stored_amount_ex_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_ex_vat, 2) THEN jsonb_build_array('AMOUNT_EX_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_vat IS NOT NULL AND resolved.live_amount_vat IS NOT NULL AND ROUND(resolved.stored_amount_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_vat, 2) THEN jsonb_build_array('AMOUNT_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_inc_vat IS NOT NULL AND resolved.live_amount_inc_vat IS NOT NULL AND ROUND(resolved.stored_amount_inc_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_inc_vat, 2) THEN jsonb_build_array('AMOUNT_INC_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE
          WHEN resolved.active_snooze_id IS NOT NULL
            THEN jsonb_build_array('ACTIVE_SNOOZE_CHANGED')
          ELSE '[]'::jsonb
        END
      ) AS stale_reasons_json
    FROM resolved
  )
  SELECT
    evaluated.*,
    (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0) AS is_stale,
    jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'stored_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.stored_timesheet_id IS NULL THEN NULL ELSE evaluated.stored_timesheet_id::text END, 'key_type', evaluated.stored_key_type, 'key_value', evaluated.stored_key_value)),
      'resolved_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END, 'key_type', evaluated.resolved_key_type, 'key_value', evaluated.resolved_key_value)),
      'stale_reasons', evaluated.stale_reasons_json,
      'stored_amount_ex_vat', evaluated.stored_amount_ex_vat,
      'current_amount_ex_vat', evaluated.live_amount_ex_vat,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
        'snooze_id', evaluated.active_snooze_id::text,
        'snooze_kind', evaluated.active_snooze_kind,
        'snooze_until_date', CASE WHEN evaluated.active_snooze_until_date IS NULL THEN NULL ELSE evaluated.active_snooze_until_date::text END,
        'active_as_of_london_date', v_today_uk::text,
        'source_ref', evaluated.active_snooze_source_ref,
        'segment_stable_key', evaluated.active_snooze_segment_stable_key,
        'segment_id', evaluated.active_snooze_segment_id,
        'booking_id', evaluated.active_snooze_booking_id,
        'source_match_scope', evaluated.active_snooze_match_scope
      )) END
    )) AS diff_json,
    md5(jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'resolved_key_type', evaluated.resolved_key_type,
      'resolved_key_value', evaluated.resolved_key_value,
      'resolved_timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END,
      'is_stale', (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0),
      'stale_reasons', evaluated.stale_reasons_json,
      'active_snooze_id', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE evaluated.active_snooze_id::text END,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze_match_scope', evaluated.active_snooze_match_scope,
      'london_current_date', v_today_uk::text
    ))::text) AS proof_hash
  FROM evaluated;

  WITH updated_units AS (
    UPDATE public.banking_pay_operation_scope_units AS scope_unit
    SET status = CASE WHEN result_row.is_stale THEN 'STALE' ELSE 'FRESH' END,
        result_hash = result_row.proof_hash,
        error_json = NULL::jsonb,
        unit_payload_json = COALESCE(scope_unit.unit_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'validation_result', jsonb_build_object(
              'validated_at_utc', v_now::text,
              'is_stale', result_row.is_stale,
              'stale_reasons', result_row.stale_reasons_json,
              'diff', CASE WHEN result_row.is_stale THEN result_row.diff_json ELSE NULL::jsonb END,
              'proof_hash', result_row.proof_hash
            )
          ),
        updated_at_utc = v_now
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE scope_unit.operation_id = result_row.operation_id
      AND scope_unit.phase = result_row.phase
      AND scope_unit.unit_type = result_row.unit_type
      AND scope_unit.unit_key = result_row.unit_key
    RETURNING scope_unit.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'STALE')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'ERROR')::integer
  INTO v_validated_count, v_fresh_count, v_stale_count, v_error_count
  FROM updated_units;

  SELECT COALESCE(jsonb_agg(diff_source.diff_json ORDER BY diff_source.unit_ordinal, diff_source.unit_key), '[]'::jsonb)
  INTO v_diff_samples
  FROM (
    SELECT result_row.diff_json, result_row.unit_ordinal, result_row.unit_key
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE result_row.is_stale = true
    ORDER BY result_row.unit_ordinal, result_row.unit_key
    LIMIT 25
  ) AS diff_source;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_element.value ORDER BY reason_element.value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
  CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(result_row.stale_reasons_json, '[]'::jsonb)) AS reason_element(value)
  WHERE result_row.is_stale = true;

  SELECT md5(COALESCE(string_agg(COALESCE(result_row.proof_hash, 'NO_RESULT'), '|' ORDER BY result_row.unit_ordinal, result_row.unit_key), 'EMPTY_VALIDATION_CHUNK'))
  INTO v_page_result_hash
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation.pay_batch_id::text,
      'last_unit_ordinal', page_row.unit_ordinal,
      'last_unit_key', page_row.unit_key
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_fresh_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0);
  v_prev_stale_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0);
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_error_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0);
  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );
  v_prev_result_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'result_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_result_hash', '')), '')
  );

  v_new_fresh_units := COALESCE(v_prev_fresh_units, 0) + COALESCE(v_fresh_count, 0);
  v_new_stale_units := COALESCE(v_prev_stale_units, 0) + COALESCE(v_stale_count, 0);
  v_new_error_units := COALESCE(v_prev_error_units, 0) + COALESCE(v_error_count, 0);
  v_new_pending_units := GREATEST(COALESCE(v_prev_pending_units, 0) - COALESCE(v_validated_count, 0), 0);
  v_new_seeded_units := GREATEST(COALESCE(v_prev_seeded_units, 0), COALESCE(v_prev_total_units, 0), v_new_fresh_units + v_new_stale_units + v_new_error_units + v_new_pending_units);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0), v_new_seeded_units);

  v_new_status := CASE
    WHEN COALESCE(v_new_pending_units, 0) > 0 OR COALESCE(v_has_more, false) THEN 'PENDING'
    WHEN COALESCE(v_new_error_units, 0) > 0 THEN 'ERROR'
    WHEN COALESCE(v_new_stale_units, 0) > 0 THEN 'STALE'
    ELSE 'PASSED'
  END;
  v_persisted_batch_status := CASE WHEN v_new_status = 'ERROR' THEN 'FAILED' ELSE v_new_status END;

  v_new_result_hash := CASE
    WHEN v_prev_result_hash IS NULL THEN COALESCE(v_page_result_hash, 'EMPTY_RESULT')
    ELSE md5(v_prev_result_hash || '|chunk|' || COALESCE(v_page_result_hash, 'EMPTY_VALIDATION_CHUNK'))
  END;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_union.reason_text ORDER BY reason_union.reason_text), '[]'::jsonb)
  INTO v_combined_stale_reasons
  FROM (
    SELECT previous_reason.value AS reason_text
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_prev_summary->'stale_reasons') = 'array' THEN COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS previous_reason(value)
    UNION ALL
    SELECT current_reason.value AS reason_text
    FROM jsonb_array_elements_text(COALESCE(v_stale_reasons, '[]'::jsonb)) AS current_reason(value)
  ) AS reason_union
  WHERE NULLIF(BTRIM(COALESCE(reason_union.reason_text, '')), '') IS NOT NULL;

  SELECT COALESCE(jsonb_agg(capped_diff.diff_json ORDER BY capped_diff.sample_rank), '[]'::jsonb)
  INTO v_combined_diff_samples
  FROM (
    SELECT diff_union.diff_json, diff_union.sample_rank
    FROM (
      SELECT previous_diff.value AS diff_json, previous_diff.ordinality::integer AS sample_rank
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_prev_summary->'diff_samples') = 'array' THEN COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb) ELSE '[]'::jsonb END
      ) WITH ORDINALITY AS previous_diff(value, ordinality)
      UNION ALL
      SELECT current_diff.value AS diff_json, (1000 + current_diff.ordinality)::integer AS sample_rank
      FROM jsonb_array_elements(COALESCE(v_diff_samples, '[]'::jsonb)) WITH ORDINALITY AS current_diff(value, ordinality)
    ) AS diff_union
    WHERE jsonb_typeof(diff_union.diff_json) = 'object'
    ORDER BY diff_union.sample_rank
    LIMIT 25
  ) AS capped_diff;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', v_new_status,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(v_new_fresh_units, 0),
    'stale_units', COALESCE(v_new_stale_units, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(v_new_error_units, 0),
    'scope_hash', v_scope_hash,
    'result_hash', v_new_result_hash,
    'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
    'last_validated_at_utc', v_now::text,
    'london_current_date', v_today_uk::text,
    'last_validated_count', COALESCE(v_validated_count, 0),
    'last_fresh_count', COALESCE(v_fresh_count, 0),
    'last_stale_count', COALESCE(v_stale_count, 0),
    'last_error_count', COALESCE(v_error_count, 0),
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', v_new_status,
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_stale_units', COALESCE(v_new_stale_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_error_units', COALESCE(v_new_error_units, 0),
          'freshness_scope_hash', v_scope_hash,
          'freshness_result_hash', v_new_result_hash
        )
      ),
      result_json = CASE
        WHEN v_new_status <> 'PENDING' THEN jsonb_set(
          COALESCE(operation_update.result_json, '{}'::jsonb),
          '{freshness}',
          v_new_summary,
          true
        )
        ELSE operation_update.result_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  IF v_operation.pay_batch_id IS NOT NULL THEN
    UPDATE public.pay_batches AS batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_persisted_batch_status,
        freshness_checked_at_utc = CASE WHEN v_new_status <> 'PENDING' THEN v_now ELSE batch_update.freshness_checked_at_utc END,
        freshness_scope_hash = COALESCE(v_scope_hash, batch_update.freshness_scope_hash),
        freshness_result_hash = CASE WHEN v_new_status <> 'PENDING' THEN v_new_result_hash ELSE batch_update.freshness_result_hash END,
        freshness_result_json = jsonb_build_object(
          'ok', true,
          'operation_id', p_operation_id::text,
          'pay_batch_id', v_operation.pay_batch_id::text,
          'phase', 'FRESHNESS',
          'status', v_new_status,
          'is_stale', v_new_status IN ('STALE', 'ERROR'),
          'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
          'diff', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'scope_hash', v_scope_hash,
          'result_hash', v_new_result_hash,
          'summary', v_new_summary,
          'checked_at_utc', CASE WHEN v_new_status <> 'PENDING' THEN v_now::text ELSE NULL END
        )
    WHERE batch_update.id = v_operation.pay_batch_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'london_current_date', v_today_uk::text,
    'validated_count', COALESCE(v_validated_count, 0),
    'fresh_count', COALESCE(v_fresh_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness(p_pay_batch_id uuid, p_actor_user_id uuid, p_allow_large_full_scan boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();

  v_pay_date date;
  v_week_start date;
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
  v_batch_kind_fixed text;
  v_scope text;

  v_ts_ids uuid[] := array[]::uuid[];

  v_is_stale boolean := false;
  v_reasons text[] := array[]::text[];

  v_diffs jsonb := '[]'::jsonb;

  v_ts_changed_ct int := 0;
  v_key_diff_ct int := 0;
  v_finance_reservation_diff_ct int := 0;
  v_snooze_diff_ct int := 0;
  v_restructure_diff_ct int := 0;
  v_writeoff_diff_ct int := 0;
  v_timesheet_override_diff_ct int := 0;
  v_paye_guardrail_diff_ct int := 0;
  v_overpay_ded_diff_ct int := 0;
  v_manual_debt_ded_diff_ct int := 0;
  v_loan_ded_diff_ct int := 0;
  v_ded_diff_ct int := 0;
  v_paye_net_diff_ct int := 0;

  v_batch_created_at_utc timestamptz;
  v_batch_status text;
  v_batch_is_active_reservation boolean := false;
  v_finance_reservation_expected_status text := 'RESERVED';
  v_same_week_paye_override_used boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;

  v_diff_limit int := 500;

  -- Scalable execution guard. Normal execute operation flow must use the
  -- chunked freshness RPCs. This legacy/full validator remains available for
  -- small/manual diagnostics, or explicit admin diagnostics when
  -- p_allow_large_full_scan = true. Counts are derived only from frozen
  -- batch/payment artifacts, never live TSFIN.
  v_allow_large_full_scan boolean := false;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_item_breakdown_count integer := 0;
  v_transfer_count integer := 0;
  v_large_batch boolean := false;
  v_large_batch_reasons jsonb := '[]'::jsonb;
  v_chunked_required_diff jsonb := '[]'::jsonb;
  v_carry_forward_freshness_result jsonb := '{}'::jsonb;
  v_carry_forward_blocker_count integer := 0;
begin
  PERFORM public.banking_pay_hot_path_budget_apply('DIAGNOSTIC');

  v_allow_large_full_scan := coalesce(p_allow_large_full_scan, false);

  if p_pay_batch_id is null then
    raise exception 'pay_batch_validate_freshness: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_batch_validate_freshness: actor_user_id is required';
  end if;

  select
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.created_at_utc,
    upper(coalesce(pb.status, '')),
    coalesce(pb.same_week_paye_override_used, false)
  into
    v_pay_date,
    v_batch_kind_fixed,
    v_batch_created_at_utc,
    v_batch_status,
    v_same_week_paye_override_used
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_pay_date is null then
    raise exception 'pay_batch_validate_freshness: pay_batch_id not found (%).', p_pay_batch_id::text;
  end if;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := CASE
    WHEN COALESCE(v_date_context ->> 'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN (v_date_context ->> 'london_current_date')::date
    ELSE NULL::date
  END;

  IF v_today_uk IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'The current Europe/London business date could not be resolved for full-batch freshness.'
            )::text;
  END IF;

  select count(*)::integer
  into v_candidate_count
  from public.pay_batch_candidates as guard_candidate_count
  where guard_candidate_count.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_item_count
  from public.pay_batch_items as guard_item_count
  join public.pay_batch_candidates as guard_item_candidate
    on guard_item_candidate.id = guard_item_count.pay_batch_candidate_id
  where guard_item_candidate.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_item_breakdown_count
  from public.pay_batch_item_breakdowns as guard_breakdown_count
  join public.pay_batch_items as guard_breakdown_item
    on guard_breakdown_item.id = guard_breakdown_count.pay_batch_item_id
  join public.pay_batch_candidates as guard_breakdown_candidate
    on guard_breakdown_candidate.id = guard_breakdown_item.pay_batch_candidate_id
  where guard_breakdown_candidate.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_transfer_count
  from public.pay_bank_transfers as guard_transfer_count
  where guard_transfer_count.pay_batch_id = p_pay_batch_id;

  v_large_batch := (
    coalesce(v_candidate_count, 0) > 100
    or coalesce(v_item_count, 0) > 250
    or coalesce(v_transfer_count, 0) > 100
    or coalesce(v_item_breakdown_count, 0) > 500
  );

  select coalesce(jsonb_agg(guard_reason.reason_json order by guard_reason.reason_key), '[]'::jsonb)
  into v_large_batch_reasons
  from (
    select
      'candidate_count'::text as reason_key,
      jsonb_build_object('metric', 'candidate_count', 'count', coalesce(v_candidate_count, 0), 'threshold', 100) as reason_json
    where coalesce(v_candidate_count, 0) > 100

    union all

    select
      'item_count'::text as reason_key,
      jsonb_build_object('metric', 'item_count', 'count', coalesce(v_item_count, 0), 'threshold', 250) as reason_json
    where coalesce(v_item_count, 0) > 250

    union all

    select
      'transfer_count'::text as reason_key,
      jsonb_build_object('metric', 'transfer_count', 'count', coalesce(v_transfer_count, 0), 'threshold', 100) as reason_json
    where coalesce(v_transfer_count, 0) > 100

    union all

    select
      'item_breakdown_count'::text as reason_key,
      jsonb_build_object('metric', 'item_breakdown_count', 'count', coalesce(v_item_breakdown_count, 0), 'threshold', 500) as reason_json
    where coalesce(v_item_breakdown_count, 0) > 500
  ) as guard_reason;

  if v_large_batch and v_allow_large_full_scan is not true then
    v_chunked_required_diff := jsonb_build_array(
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', 'FRESHNESS_MODE',
        'key_value', 'FULL_BATCH_SCAN_GUARD',
        'expected', jsonb_build_object(
          'required_path', 'chunked_freshness',
          'seed_rpc', 'pay_batch_freshness_scope_seed',
          'chunk_rpc', 'pay_batch_validate_freshness_chunk',
          'aggregate_rpc', 'pay_batch_freshness_result_get'
        ),
        'actual', jsonb_build_object(
          'requested_path', 'pay_batch_validate_freshness_full_scan',
          'p_allow_large_full_scan', v_allow_large_full_scan,
          'candidate_count', coalesce(v_candidate_count, 0),
          'item_count', coalesce(v_item_count, 0),
          'transfer_count', coalesce(v_transfer_count, 0),
          'item_breakdown_count', coalesce(v_item_breakdown_count, 0),
          'large_batch_reasons', coalesce(v_large_batch_reasons, '[]'::jsonb)
        )
      )
    );

    return jsonb_build_object(
      'is_stale', true,
      'stale_reasons', jsonb_build_array('FULL_BATCH_FRESHNESS_REQUIRES_CHUNKED_VALIDATION'),
      'diff', v_chunked_required_diff,
      'requires_chunked_freshness', true,
      'code', 'FULL_BATCH_FRESHNESS_REQUIRES_CHUNKED_VALIDATION',
      'message', 'This batch is too large for the legacy full-batch freshness validator. Use the chunked freshness operation path.',
      'pay_batch_id', p_pay_batch_id::text,
      'counts', jsonb_build_object(
        'candidate_count', coalesce(v_candidate_count, 0),
        'item_count', coalesce(v_item_count, 0),
        'transfer_count', coalesce(v_transfer_count, 0),
        'item_breakdown_count', coalesce(v_item_breakdown_count, 0)
      ),
      'thresholds', jsonb_build_object(
        'candidate_count', 100,
        'item_count', 250,
        'transfer_count', 100,
        'item_breakdown_count', 500
      ),
      'large_batch_reasons', coalesce(v_large_batch_reasons, '[]'::jsonb)
    );
  end if;

  v_batch_is_active_reservation := public._pay_batch_status_is_active_reservation(v_batch_status);

  if v_batch_status in ('AUTHORISED_FOR_PAYMENT','SCHEDULED','EXECUTING') then
    v_finance_reservation_expected_status := 'COMMITTED';
  else
    v_finance_reservation_expected_status := 'RESERVED';
  end if;

  v_week_start := public._pay_week_start_monday(v_pay_date);

  select
    max(pbi.pay_channel)
  into
    v_scope
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    and pbi.pay_channel in ('PAYE','UMBRELLA');

  v_scope := upper(btrim(coalesce(v_scope,'')));
  if v_scope not in ('PAYE','UMBRELLA') then
    v_scope := null;
  end if;

  select
    coalesce(
      (
        select array_agg(distinct t1.timesheet_id)
        from (
          select pbts.timesheet_id
          from public.pay_batch_timesheet_snapshots pbts
          where pbts.pay_batch_id = p_pay_batch_id
            and pbts.timesheet_id is not null

          union all

          select pbi2.timesheet_id
          from public.pay_batch_items pbi2
          join public.pay_batch_candidates pbc2
            on pbc2.id = pbi2.pay_batch_candidate_id
          where pbc2.pay_batch_id = p_pay_batch_id
            and coalesce(pbi2.is_voided, false) = false
            and not exists (
              select 1
              from public.pay_payment_correction_items as ppc_pbi2_fresh_exclusion
              where ppc_pbi2_fresh_exclusion.pay_batch_item_id = pbi2.id
                and ppc_pbi2_fresh_exclusion.status = 'APPLIED'
                and ppc_pbi2_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
            )
            and pbi2.timesheet_id is not null
        ) t1
      ),
      array[]::uuid[]
    )
  into v_ts_ids;

  create temporary table if not exists pg_temp.tmp_fresh_ts_diffs (
    timesheet_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_text text null,
    actual_text text null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_key_diffs (
    timesheet_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_candidate_earnings (
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    awaiting_net_amount boolean not null,
    earnings_before_loan_ex numeric(12,2) not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_overpay_alloc (
    candidate_id uuid not null,
    advance_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_candidate_expected_overpay (
    candidate_id uuid not null,
    expected_overpayment_recovery_ex numeric(12,2) not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_loan_alloc (
    candidate_id uuid not null,
    loan_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_deduction_diffs (
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_paye_net_diffs (
    candidate_id uuid not null,
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_manual_debt_alloc (
    candidate_id uuid not null,
    finance_case_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_state_diffs (
    timesheet_id uuid null,
    candidate_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_text text null,
    actual_text text null,
    ord int not null
  ) on commit drop;

  truncate table pg_temp.tmp_fresh_ts_diffs;
  truncate table pg_temp.tmp_fresh_key_diffs;
  truncate table pg_temp.tmp_fresh_candidate_earnings;
  truncate table pg_temp.tmp_fresh_expected_overpay_alloc;
  truncate table pg_temp.tmp_fresh_candidate_expected_overpay;
  truncate table pg_temp.tmp_fresh_expected_loan_alloc;
  truncate table pg_temp.tmp_fresh_expected_manual_debt_alloc;
  truncate table pg_temp.tmp_fresh_deduction_diffs;
  truncate table pg_temp.tmp_fresh_paye_net_diffs;
  truncate table pg_temp.tmp_fresh_state_diffs;

  ---------------------------------------------------------------------------
  -- TIMESHEET_CHANGED: Policy X keeps blocking freshness checks in the
  -- economic entitlement keyspace. The legacy whole-snapshot signature
  -- comparison is intentionally disabled as a blocking stale gate here.
  ---------------------------------------------------------------------------
  v_ts_changed_ct := 0;

  ---------------------------------------------------------------------------
  -- RESERVATION_CHANGED: compare this batch's frozen source entitlement
  -- against the current entitlement available before this batch.
  --
  -- Policy X (post-draft): the batch side is resolved only from frozen
  -- batch artifacts via _pay_batch_item_economic_components. Current
  -- live truth is comparison-only via _pay_current_timesheet_entitlement_components.
  -- This section must not call the broad outstanding helper, must not
  -- remap batch items from live TSFIN, and must not validate resolved rows
  -- against target payout amounts.
  ---------------------------------------------------------------------------
  if v_batch_is_active_reservation then
    insert into pg_temp.tmp_fresh_key_diffs (
      timesheet_id,
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with
    this_components_raw as (
      select
        pbec.pay_batch_item_id,
        pbec.timesheet_id,
        upper(nullif(btrim(coalesce(pbec.item_type, '')), '')) as item_type,
        upper(nullif(btrim(coalesce(pbec.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(pbec.key_value, '')), '') as key_value,
        pbec.source_amount_ex_vat as source_amount_ex_vat_raw,
        pbec.target_amount_ex_vat as target_amount_ex_vat_raw,
        nullif(btrim(coalesce(pbec.key_resolution_failure_reason, '')), '') as key_resolution_failure_reason
      from public._pay_batch_item_economic_components(
        p_pay_batch_id => p_pay_batch_id,
        p_pay_batch_item_ids => null::uuid[]
      ) as pbec
      join public.pay_batch_items as pbi_this_fresh
        on pbi_this_fresh.id = pbec.pay_batch_item_id
      join public.pay_batch_candidates as pbc_this_fresh
        on pbc_this_fresh.id = pbi_this_fresh.pay_batch_candidate_id
      where pbc_this_fresh.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_this_fresh.is_voided, false) = false
        and not exists (
          select 1
          from public.pay_payment_correction_items as ppc_this_fresh_exclusion
          where ppc_this_fresh_exclusion.pay_batch_item_id = pbi_this_fresh.id
            and ppc_this_fresh_exclusion.status = 'APPLIED'
            and ppc_this_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
        )
        and upper(nullif(btrim(coalesce(pbec.item_type, '')), '')) in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    ),
    this_component_resolution_failures as (
      select
        tcr.timesheet_id,
        case
          when tcr.key_resolution_failure_reason is not null then tcr.key_resolution_failure_reason
          when tcr.key_type is null or tcr.key_value is null then 'KEY_RESOLUTION_FAILURE'
          when tcr.key_type not in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE') then 'KEY_RESOLUTION_FAILURE'
          when tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$' then 'TS_DAY_KEY_VALUE_NOT_DATE'
          when tcr.source_amount_ex_vat_raw is null then 'SOURCE_RESOLUTION_FAILURE'
          else 'SOURCE_RESOLUTION_FAILURE'
        end as key_type,
        coalesce(tcr.pay_batch_item_id::text, 'UNKNOWN_PAY_BATCH_ITEM') as key_value,
        0::numeric(12,2) as expected_ex,
        1::numeric(12,2) as actual_ex,
        2 as ord
      from this_components_raw as tcr
      where tcr.key_resolution_failure_reason is not null
         or tcr.key_type is null
         or tcr.key_value is null
         or tcr.key_type not in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
         or (tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
         or tcr.source_amount_ex_vat_raw is null
    ),
    this_components as (
      select
        tcr.timesheet_id,
        tcr.key_type,
        tcr.key_value,
        round(sum(round(coalesce(tcr.source_amount_ex_vat_raw, 0), 2)), 2)::numeric(12,2) as current_source_ex_vat
      from this_components_raw as tcr
      where tcr.timesheet_id is not null
        and tcr.key_type is not null
        and tcr.key_value is not null
        and tcr.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
        and tcr.key_resolution_failure_reason is null
        and tcr.source_amount_ex_vat_raw is not null
      group by
        tcr.timesheet_id,
        tcr.key_type,
        tcr.key_value
    ),
    current_truth_baseline as (
      select
        ctec.timesheet_id,
        upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(ctec.key_value, '')), '') as key_value,
        round(sum(coalesce(ctec.truth_ex_vat, 0)), 2)::numeric(12,2) as truth_ex_vat,
        round(sum(coalesce(ctec.baseline_ex_vat, 0)), 2)::numeric(12,2) as baseline_ex_vat
      from public._pay_current_timesheet_entitlement_components(v_ts_ids) as ctec
      where ctec.timesheet_id is not null
        and ctec.key_type is not null
        and btrim(ctec.key_type) <> ''
        and ctec.key_value is not null
        and btrim(ctec.key_value) <> ''
        and upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (
          upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) = 'TS_DAY'
          and nullif(btrim(coalesce(ctec.key_value, '')), '') !~ '^\d{4}-\d{2}-\d{2}$'
        )
      group by
        ctec.timesheet_id,
        upper(nullif(btrim(coalesce(ctec.key_type, '')), '')),
        nullif(btrim(coalesce(ctec.key_value, '')), '')
    ),
    all_reserved as (
      select
        rc.timesheet_id,
        upper(nullif(btrim(coalesce(rc.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(rc.key_value, '')), '') as key_value,
        round(sum(coalesce(rc.amount_ex_vat, 0)), 2)::numeric(12,2) as all_reserved_ex_vat
      from public._pay_reserved_components(v_ts_ids) as rc
      where rc.timesheet_id is not null
        and rc.key_type is not null
        and btrim(rc.key_type) <> ''
        and rc.key_value is not null
        and btrim(rc.key_value) <> ''
        and upper(nullif(btrim(coalesce(rc.key_type, '')), '')) in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (
          upper(nullif(btrim(coalesce(rc.key_type, '')), '')) = 'TS_DAY'
          and nullif(btrim(coalesce(rc.key_value, '')), '') !~ '^\d{4}-\d{2}-\d{2}$'
        )
      group by
        rc.timesheet_id,
        upper(nullif(btrim(coalesce(rc.key_type, '')), '')),
        nullif(btrim(coalesce(rc.key_value, '')), '')
    ),
    reservation_comparison as (
      select
        tc.timesheet_id,
        tc.key_type,
        tc.key_value,
        tc.current_source_ex_vat as expected_ex,
        round(
          coalesce(ctb.truth_ex_vat, 0)
          - coalesce(ctb.baseline_ex_vat, 0)
          - (
              coalesce(ar.all_reserved_ex_vat, 0)
              - coalesce(tc.current_source_ex_vat, 0)
            ),
          2
        )::numeric(12,2) as actual_ex,
        2 as ord
      from this_components as tc
      left join current_truth_baseline as ctb
        on ctb.timesheet_id = tc.timesheet_id
       and ctb.key_type = tc.key_type
       and ctb.key_value = tc.key_value
      left join all_reserved as ar
        on ar.timesheet_id = tc.timesheet_id
       and ar.key_type = tc.key_type
       and ar.key_value = tc.key_value
    ),
    reservation_mismatches as (
      select
        rc.timesheet_id,
        rc.key_type,
        rc.key_value,
        rc.expected_ex,
        rc.actual_ex,
        rc.ord
      from reservation_comparison as rc
      where abs(round(coalesce(rc.actual_ex, 0), 2) - round(coalesce(rc.expected_ex, 0), 2)) > 0.01
    )
    select
      tcrf.timesheet_id,
      tcrf.key_type,
      tcrf.key_value,
      tcrf.expected_ex,
      tcrf.actual_ex,
      tcrf.ord
    from this_component_resolution_failures as tcrf

    union all

    select
      rm.timesheet_id,
      rm.key_type,
      rm.key_value,
      rm.expected_ex,
      rm.actual_ex,
      rm.ord
    from reservation_mismatches as rm;
  end if;

  select count(*)::int
  into v_key_diff_ct
  from pg_temp.tmp_fresh_key_diffs;

  if v_key_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'RESERVATION_CHANGED');
  end if;

  ---------------------------------------------------------------------------
  -- STATE_CHANGED: finance reservation rows, snoozes, restructure/write-off,
  -- timesheet-payment-override changes, and PAYE guardrail changes.
  ---------------------------------------------------------------------------
  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_finance_items as (
    select
      pbi.timesheet_id,
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.finance_case_id,
      pbi.reservation_id,
      pbi.item_type,
      pbi.repayment_week_start,
      round(abs(coalesce(pbi.frozen_source_amount, case when pbi.frozen_target_amount_ex_vat is null and pbi.frozen_resolution_mode is null and pbi.frozen_resolution_result_json is null then pbi.amount_ex_vat else null end, 0)), 2)::numeric(12,2) as reserved_amount_ex
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
      and pbi.finance_case_id is not null
  ),
  reservation_rows as (
    select
      par.id as reservation_id,
      par.finance_case_id,
      par.pay_batch_id,
      par.pay_batch_candidate_id,
      par.pay_batch_item_id,
      round(coalesce(par.reserved_amount, 0), 2)::numeric(12,2) as reserved_amount_ex,
      par.repayment_week_start,
      upper(coalesce(par.status, '')) as reservation_status
    from public.pay_advance_reservations par
    where par.pay_batch_id = p_pay_batch_id
  )
  select
    bfi.timesheet_id,
    bfi.candidate_id,
    'FINANCE_RESERVATION' as key_type,
    bfi.pay_batch_item_id::text as key_value,
    jsonb_build_object(
      'finance_case_id', bfi.finance_case_id::text,
      'reservation_id', case when bfi.reservation_id is null then null else bfi.reservation_id::text end,
      'reserved_amount_ex', bfi.reserved_amount_ex,
      'repayment_week_start', case when bfi.repayment_week_start is null then null else bfi.repayment_week_start::text end,
      'status', v_finance_reservation_expected_status
    )::text as expected_text,
    case
      when rr.reservation_id is null then null
      else jsonb_build_object(
        'reservation_id', rr.reservation_id::text,
        'finance_case_id', rr.finance_case_id::text,
        'reserved_amount_ex', rr.reserved_amount_ex,
        'repayment_week_start', case when rr.repayment_week_start is null then null else rr.repayment_week_start::text end,
        'status', rr.reservation_status
      )::text
    end as actual_text,
    33 as ord
  from batch_finance_items bfi
  left join reservation_rows rr
    on rr.pay_batch_item_id = bfi.pay_batch_item_id
  where rr.reservation_id is null
     or rr.finance_case_id is distinct from bfi.finance_case_id
     or round(coalesce(rr.reserved_amount_ex, 0), 2) <> round(coalesce(bfi.reserved_amount_ex, 0), 2)
     or rr.repayment_week_start is distinct from bfi.repayment_week_start
     or rr.reservation_status <> v_finance_reservation_expected_status
     or (bfi.reservation_id is not null and rr.reservation_id is distinct from bfi.reservation_id);

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_items as (
    select
      pbc.pay_batch_id,
      pbi.timesheet_id,
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      pbi.source_ref,
      coalesce(
        case when pbi.finance_case_id is not null then 'advance:' || pbi.finance_case_id::text else null::text end,
        lower(nullif(btrim(coalesce(pbi.source_ref, '')), ''))
      ) as exact_source_ref,
      case
        when coalesce(
          case when pbi.finance_case_id is not null then 'advance:' || pbi.finance_case_id::text else null::text end,
          lower(nullif(btrim(coalesce(pbi.source_ref, '')), ''))
        ) ~* '^timesheet-expense:' then 'TIMESHEET_EXPENSE'
        when pbi.finance_case_id is not null
          or lower(nullif(btrim(coalesce(pbi.source_ref, '')), '')) ~* '^advance:' then 'FINANCE_CASE'
        when nullif(btrim(coalesce(pbi.source_ref, '')), '') is not null then 'EXACT_SOURCE'
        else 'TIMESHEET_OR_SEGMENT'
      end as source_identity_kind,
      pbi.finance_case_id,
      pbi.segment_key,
      pbi.frozen_source_basis_json,
      pbi.frozen_component_snapshot_json,
      pbi.payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  matched_snoozes as (
    select
      bi.timesheet_id,
      bi.candidate_id,
      bi.pay_batch_item_id,
      active_snooze.id as snooze_id,
      upper(coalesce(active_snooze.snooze_kind, '')) as snooze_kind,
      active_snooze.snooze_until_date,
      active_snooze.note,
      active_snooze.source_ref as snooze_source_ref,
      active_snooze.match_scope,
      bi.exact_source_ref,
      bi.source_identity_kind
    from batch_items as bi
    join lateral (
      select
        snooze_row.id,
        snooze_row.snooze_kind,
        snooze_row.snooze_until_date,
        snooze_row.note,
        snooze_row.source_ref,
        case
          when snooze_row.source_ref is not null then 'EXACT_SOURCE_REF'
          else 'LEGACY_TIMESHEET_SEGMENT'
        end as match_scope
      from public.pay_item_snoozes as snooze_row
      where snooze_row.candidate_id = bi.candidate_id
        and snooze_row.cleared_at_utc is null
        and snooze_row.cancelled_at_utc is null
        and (
          snooze_row.snooze_until_date is null
          or snooze_row.snooze_until_date >= v_today_uk
        )
        and (
          (
            bi.exact_source_ref is not null
            and lower(nullif(btrim(coalesce(snooze_row.source_ref, '')), '')) = bi.exact_source_ref
          )
          or (
            bi.exact_source_ref is null
            and snooze_row.source_ref is null
            and (
              (
                bi.timesheet_id is not null
                and snooze_row.timesheet_id = bi.timesheet_id
              )
              or (
                nullif(btrim(coalesce(snooze_row.booking_id, '')), '') is not null
                and nullif(btrim(coalesce(snooze_row.booking_id, '')), '') = coalesce(
                  nullif(btrim(bi.frozen_source_basis_json #>> '{booking_id}'), ''),
                  nullif(btrim(bi.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{booking_id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
                  (
                    select coalesce(
                      nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
                      nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
                      nullif(btrim(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
                      nullif(btrim(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
                    )
                    from public.pay_batch_timesheet_snapshots as snapshot_row
                    where snapshot_row.pay_batch_id = bi.pay_batch_id
                      and snapshot_row.timesheet_id = bi.timesheet_id
                    order by snapshot_row.id
                    limit 1
                  )
                )
              )
            )
            and (
              (
                nullif(btrim(coalesce(snooze_row.segment_stable_key, '')), '') is null
                and nullif(btrim(coalesce(snooze_row.segment_id, '')), '') is null
              )
              or (
                coalesce(
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(coalesce(bi.segment_key, '')), '')
                ) is not null
                and nullif(btrim(coalesce(snooze_row.segment_stable_key, '')), '') = coalesce(
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  nullif(btrim(coalesce(bi.segment_key, '')), '')
                )
              )
              or (
                coalesce(
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment,id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                ) is not null
                and nullif(btrim(coalesce(snooze_row.segment_id, '')), '') = coalesce(
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.frozen_source_basis_json #>> '{segment,id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  nullif(btrim(bi.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                )
              )
              or (
                nullif(btrim(coalesce(bi.segment_key, '')), '') is not null
                and nullif(btrim(coalesce(bi.segment_key, '')), '') in (
                  nullif(btrim(coalesce(snooze_row.segment_stable_key, '')), ''),
                  nullif(btrim(coalesce(snooze_row.segment_id, '')), '')
                )
              )
            )
          )
        )
      order by snooze_row.updated_at_utc desc, snooze_row.created_at_utc desc, snooze_row.id
      limit 1
    ) as active_snooze on true
  )
  select
    ms.timesheet_id,
    ms.candidate_id,
    'SNOOZE' as key_type,
    ms.pay_batch_item_id::text as key_value,
    'NO_ACTIVE_SNOOZE' as expected_text,
    jsonb_build_object(
      'snooze_id', ms.snooze_id::text,
      'snooze_kind', ms.snooze_kind,
      'snooze_until_date', case when ms.snooze_until_date is null then null else ms.snooze_until_date::text end,
      'note', ms.note,
      'frozen_source_ref', ms.exact_source_ref,
      'snooze_source_ref', ms.snooze_source_ref,
      'source_identity_kind', ms.source_identity_kind,
      'source_match_scope', ms.match_scope
    )::text as actual_text,
    34 as ord
  from matched_snoozes as ms;

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with referenced_finance_cases as (
    select distinct
      pbc.candidate_id,
      coalesce(
        pbi.finance_case_id,
        case
          when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
          else null
        end
      ) as finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and (
        pbi.finance_case_id is not null
        or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
      )
  )
  select
    null::uuid as timesheet_id,
    rfc.candidate_id,
    'RESTRUCTURE' as key_type,
    rfc.finance_case_id::text as key_value,
    'NO_RESTRUCTURE_AFTER_BATCH_CREATED' as expected_text,
    jsonb_build_object(
      'finance_case_id', rfc.finance_case_id::text,
      'event_type', pfce.event_type,
      'event_at_utc', pfce.event_at_utc
    )::text as actual_text,
    35 as ord
  from referenced_finance_cases rfc
  join public.pay_finance_case_events pfce
    on pfce.finance_case_id = rfc.finance_case_id
  where pfce.event_at_utc >= coalesce(v_batch_created_at_utc, v_now_utc)
    and upper(coalesce(pfce.event_type, '')) like '%RESTRUCTURE%';

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with referenced_finance_cases as (
    select distinct
      pbc.candidate_id,
      coalesce(
        pbi.finance_case_id,
        case
          when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
          else null
        end
      ) as finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and (
        pbi.finance_case_id is not null
        or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
      )
  )
  select
    null::uuid as timesheet_id,
    rfc.candidate_id,
    'WRITE_OFF' as key_type,
    rfc.finance_case_id::text as key_value,
    'NOT_WRITTEN_OFF' as expected_text,
    jsonb_build_object(
      'finance_case_id', pa.id::text,
      'written_off_at_utc', pa.written_off_at_utc,
      'status', pa.status::text
    )::text as actual_text,
    36 as ord
  from referenced_finance_cases rfc
  join public.pay_advances pa
    on pa.id = rfc.finance_case_id
  where pa.written_off_at_utc is not null
    and pa.written_off_at_utc >= coalesce(v_batch_created_at_utc, v_now_utc);

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_ts as (
    select distinct
      pbi.timesheet_id,
      pbc.candidate_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi.timesheet_id is not null
  ),
  batch_entitlement_ts as (
    select distinct
      pbi.timesheet_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
      and pbi.timesheet_id is not null
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_entitlement_fresh_exclusion
        where ppc_pbi_entitlement_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_entitlement_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_entitlement_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  override_changes as (
    select
      bt.timesheet_id,
      bt.candidate_id,
      tpo.id as override_id,
      tpo.override_type,
      tpo.created_at_utc,
      tpo.consumed_at_utc,
      tpo.consumed_by_pay_batch_id,
      tpo.cleared_at_utc,
      consumed_batch.status as consumed_batch_status,
      coalesce(tpo.created_at_utc, '-infinity'::timestamptz) >= coalesce(v_batch_created_at_utc, v_now_utc) as created_after_batch,
      coalesce(tpo.cleared_at_utc, '-infinity'::timestamptz) >= coalesce(v_batch_created_at_utc, v_now_utc) as cleared_after_batch,
      coalesce(tpo.consumed_at_utc, '-infinity'::timestamptz) >= coalesce(v_batch_created_at_utc, v_now_utc) as consumed_after_batch,
      (
        upper(coalesce(tpo.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
        and tpo.consumed_by_pay_batch_id = p_pay_batch_id
        and tpo.consumed_at_utc is not null
        and tpo.cleared_at_utc is null
        and coalesce(tpo.created_at_utc, '-infinity'::timestamptz) < coalesce(v_batch_created_at_utc, v_now_utc)
        and exists (
          select 1
          from batch_entitlement_ts bet
          where bet.timesheet_id = bt.timesheet_id
        )
      ) as expected_same_batch_advance_consumption
    from batch_ts bt
    join public.timesheet_payment_overrides tpo
      on tpo.timesheet_id = bt.timesheet_id
    left join public.pay_batches consumed_batch
      on consumed_batch.id = tpo.consumed_by_pay_batch_id
    where upper(coalesce(tpo.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
  )
  select
    oc.timesheet_id,
    oc.candidate_id,
    'TIMESHEET_ADVANCE_OVERRIDE' as key_type,
    oc.timesheet_id::text as key_value,
    'NO_OVERRIDE_CHANGE_AFTER_BATCH_CREATED' as expected_text,
    jsonb_build_object(
      'override_id', oc.override_id::text,
      'override_type', oc.override_type,
      'created_at_utc', oc.created_at_utc,
      'consumed_at_utc', oc.consumed_at_utc,
      'consumed_by_pay_batch_id', case when oc.consumed_by_pay_batch_id is null then null else oc.consumed_by_pay_batch_id::text end,
      'consumed_batch_status', oc.consumed_batch_status,
      'cleared_at_utc', oc.cleared_at_utc
    )::text as actual_text,
    37 as ord
  from override_changes oc
  where oc.created_after_batch
     or oc.cleared_after_batch
     or (
          oc.consumed_after_batch
          and oc.expected_same_batch_advance_consumption is not true
          and (
            oc.consumed_by_pay_batch_id is null
            or upper(coalesce(oc.consumed_batch_status, '')) <> 'CANCELLED'
          )
        );

  select count(*)::int
  into v_finance_reservation_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'FINANCE_RESERVATION';

  if v_finance_reservation_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'FINANCE_RESERVATION_CHANGED');
  end if;

  select count(*)::int
  into v_snooze_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'SNOOZE';

  if v_snooze_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'SNOOZE_CHANGED');
  end if;

  select count(*)::int
  into v_restructure_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'RESTRUCTURE';

  if v_restructure_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'RESTRUCTURE_CHANGED');
  end if;

  select count(*)::int
  into v_writeoff_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'WRITE_OFF';

  if v_writeoff_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'WRITE_OFF_CHANGED');
  end if;

  select count(*)::int
  into v_timesheet_override_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'TIMESHEET_ADVANCE_OVERRIDE';

  if v_timesheet_override_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'TIMESHEET_PAYMENT_OVERRIDE_CHANGED');
  end if;

  if v_scope = 'PAYE' and coalesce(v_batch_kind_fixed, '') <> 'LOANS' then
    v_paye_guardrails := public.pay_paye_guardrails(
      p_pay_date => v_pay_date,
      p_ignore_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id
    );

    if coalesce((v_paye_guardrails->>'create_paye_blocked')::boolean, false) = true
       or (
            coalesce((v_paye_guardrails->>'override_required')::boolean, false) = true
            and coalesce(v_same_week_paye_override_used, false) = false
          )
    then
      insert into pg_temp.tmp_fresh_state_diffs (
        timesheet_id,
        candidate_id,
        key_type,
        key_value,
        expected_text,
        actual_text,
        ord
      )
      values (
        null,
        null,
        'PAYE_GUARDRAILS',
        p_pay_batch_id::text,
        jsonb_build_object(
          'same_week_paye_override_used', coalesce(v_same_week_paye_override_used, false)
        )::text,
        v_paye_guardrails::text,
        38
      );

      select count(*)::int
      into v_paye_guardrail_diff_ct
      from pg_temp.tmp_fresh_state_diffs tsd
      where tsd.key_type = 'PAYE_GUARDRAILS';

      if v_paye_guardrail_diff_ct > 0 then
        v_is_stale := true;
        v_reasons := array_append(v_reasons, 'PAYE_GUARDRAILS_CHANGED');
      end if;
    end if;
  end if;


  ---------------------------------------------------------------------------
  -- DEDUCTION_CHANGED: recompute expected OVERPAYMENT_RECOVERY,
  -- MANUAL_DEBT_RECOVERY, and LOAN_REPAYMENT from frozen batch-local
  -- deduction templates only. No live finance register / pay_advances
  -- authority is permitted in this post-draft branch.
  ---------------------------------------------------------------------------
  if v_scope in ('PAYE','UMBRELLA') then
    create temporary table if not exists pg_temp.tmp_fresh_recovery_templates (
      item_type text not null,
      pay_batch_candidate_id uuid not null,
      candidate_id uuid not null,
      finance_case_id uuid null,
      source_ref text null,
      pay_channel text null,
      umbrella_id uuid null,
      is_mismatch boolean null,
      paye_treatment text null,
      finance_component_id uuid null,
      frozen_component_snapshot_json jsonb null,
      frozen_component_key_type text null,
      frozen_component_key_value text null,
      frozen_component_classification public.pay_finance_component_classification_enum null,
      frozen_source_basis_json jsonb null,
      frozen_source_pay_method text null,
      frozen_target_pay_method text null,
      frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
      frozen_resolution_payload_json jsonb null,
      frozen_resolution_result_json jsonb null,
      frozen_source_amount numeric(12,2) null,
      frozen_target_amount_ex_vat numeric(12,2) null,
      frozen_target_amount_vat numeric(12,2) null,
      frozen_target_amount_inc_vat numeric(12,2) null,
      payout_instruction_snapshot_json jsonb null,
      template_sort_at timestamptz null,
      sort_order integer not null,
      frozen_case_type text null,
      frozen_payout_status text null,
      frozen_remaining_source_amount numeric(12,2) not null,
      frozen_weekly_due_amount numeric(12,2) not null,
      frozen_next_due_week_start date null,
      minimum_earnings_threshold numeric(12,2) null,
      take_home_floor_override numeric(12,2) null,
      default_take_home_floor numeric(12,2) null
    ) on commit drop;

    truncate table pg_temp.tmp_fresh_recovery_templates;

    insert into pg_temp.tmp_fresh_recovery_templates (
      item_type,
      pay_batch_candidate_id,
      candidate_id,
      finance_case_id,
      source_ref,
      pay_channel,
      umbrella_id,
      is_mismatch,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json,
      template_sort_at,
      sort_order,
      frozen_case_type,
      frozen_payout_status,
      frozen_remaining_source_amount,
      frozen_weekly_due_amount,
      frozen_next_due_week_start,
      minimum_earnings_threshold,
      take_home_floor_override,
      default_take_home_floor
    )
    select distinct on (
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      coalesce(
        coalesce(
          pbi_rt.finance_case_id,
          case
            when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
            else null::uuid
          end
        )::text,
        ''
      ),
      coalesce(pbi_rt.finance_component_id::text, ''),
      coalesce(pbi_rt.source_ref, '')
    )
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      pbc_rt.candidate_id,
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      ) as finance_case_id,
      pbi_rt.source_ref,
      pbi_rt.pay_channel,
      pbi_rt.umbrella_id,
      pbi_rt.is_mismatch,
      pbi_rt.paye_treatment,
      pbi_rt.finance_component_id,
      pbi_rt.frozen_component_snapshot_json,
      pbi_rt.frozen_component_key_type,
      pbi_rt.frozen_component_key_value,
      pbi_rt.frozen_component_classification,
      pbi_rt.frozen_source_basis_json,
      pbi_rt.frozen_source_pay_method,
      pbi_rt.frozen_target_pay_method,
      pbi_rt.frozen_resolution_mode,
      pbi_rt.frozen_resolution_payload_json,
      pbi_rt.frozen_resolution_result_json,
      round(coalesce(pbi_rt.frozen_source_amount, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(coalesce(pbi_rt.frozen_target_amount_ex_vat, 0), 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      round(coalesce(pbi_rt.frozen_target_amount_vat, 0), 2)::numeric(12,2) as frozen_target_amount_vat,
      round(coalesce(pbi_rt.frozen_target_amount_inc_vat, 0), 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      pbi_rt.payout_instruction_snapshot_json,
      coalesce(pbi_rt.created_at, pbi_rt.updated_at, now()) as template_sort_at,
      case
        when nullif(btrim(coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order')), '') ~ '^-?[0-9]+$'
          then (coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order'))::integer
        else 2147483647
      end as sort_order,
      upper(coalesce(
        nullif(btrim(pbi_rt.frozen_source_basis_json->>'case_type'), ''),
        case pbi_rt.item_type
          when 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT'
          when 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE'
          when 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_ADJUSTMENT'
          else null
        end
      )) as frozen_case_type,
      upper(nullif(btrim(pbi_rt.frozen_source_basis_json->>'payout_status'), '')) as frozen_payout_status,
      round(greatest(
        coalesce(
          case
            when nullif(btrim(pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'remaining_source_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'outstanding_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'outstanding_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'amount'), '') is not null then abs((pbi_rt.frozen_source_basis_json->>'amount')::numeric)
            when pbi_rt.frozen_source_amount is not null then abs(pbi_rt.frozen_source_amount)
            else 0::numeric
          end,
          0::numeric
        ),
        0::numeric
      ), 2)::numeric(12,2) as frozen_remaining_source_amount,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'weekly_due'), '') is null then 0::numeric(12,2)
        else round(greatest(abs((pbi_rt.frozen_source_basis_json->>'weekly_due')::numeric), 0), 2)::numeric(12,2)
      end as frozen_weekly_due_amount,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'next_due_week_start'), '') is null then null::date
        else (pbi_rt.frozen_source_basis_json->>'next_due_week_start')::date
      end as frozen_next_due_week_start,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold')::numeric, 0), 2)::numeric(12,2)
      end as minimum_earnings_threshold,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'take_home_floor_override'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'take_home_floor_override')::numeric, 0), 2)::numeric(12,2)
      end as take_home_floor_override,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'default_take_home_floor'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'default_take_home_floor')::numeric, 0), 2)::numeric(12,2)
      end as default_take_home_floor
    from public.pay_batch_items pbi_rt
    join public.pay_batch_candidates pbc_rt
      on pbc_rt.id = pbi_rt.pay_batch_candidate_id
    where pbc_rt.pay_batch_id = p_pay_batch_id
      and coalesce(pbi_rt.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_rt_fresh_exclusion
        where ppc_pbi_rt_fresh_exclusion.pay_batch_item_id = pbi_rt.id
          and ppc_pbi_rt_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_rt_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi_rt.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
    order by
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      coalesce(
        coalesce(
          pbi_rt.finance_case_id,
          case
            when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
            else null::uuid
          end
        )::text,
        ''
      ),
      coalesce(pbi_rt.finance_component_id::text, ''),
      coalesce(pbi_rt.source_ref, ''),
      pbi_rt.is_voided desc,
      coalesce(pbi_rt.updated_at, pbi_rt.created_at) desc,
      pbi_rt.id desc;

    insert into pg_temp.tmp_fresh_state_diffs (
      timesheet_id,
      candidate_id,
      key_type,
      key_value,
      expected_text,
      actual_text,
      ord
    )
    select
      null::uuid as timesheet_id,
      pbc_bad.candidate_id,
      'DEDUCTION_TEMPLATE' as key_type,
      pbi_bad.id::text as key_value,
      'FROZEN_TEMPLATE_WITH_FINANCE_CASE_ID' as expected_text,
      jsonb_build_object(
        'pay_batch_item_id', pbi_bad.id::text,
        'item_type', pbi_bad.item_type,
        'source_ref', pbi_bad.source_ref,
        'finance_case_id', pbi_bad.finance_case_id::text
      )::text as actual_text,
      30 as ord
    from public.pay_batch_items pbi_bad
    join public.pay_batch_candidates pbc_bad
      on pbc_bad.id = pbi_bad.pay_batch_candidate_id
    where pbc_bad.pay_batch_id = p_pay_batch_id
      and coalesce(pbi_bad.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_bad_fresh_exclusion
        where ppc_pbi_bad_fresh_exclusion.pay_batch_item_id = pbi_bad.id
          and ppc_pbi_bad_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_bad_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi_bad.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
      and pbi_bad.finance_case_id is null;

    insert into pg_temp.tmp_fresh_expected_overpay_alloc (
      candidate_id,
      advance_id,
      take_ex,
      ord
    )
    with candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        greatest(
          coalesce(
            case
              when v_scope = 'PAYE' then pni.net_amount
              else (
                select sum(pbi_pos.amount_ex_vat)
                from public.pay_batch_items pbi_pos
                where pbi_pos.pay_batch_candidate_id = pbc.id
                  and coalesce(pbi_pos.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_pos_fresh_exclusion
        where ppc_pbi_pos_fresh_exclusion.pay_batch_item_id = pbi_pos.id
          and ppc_pbi_pos_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_pos_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
                  and pbi_pos.amount_ex_vat > 0
                  and pbi_pos.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
              )
            end,
            0
          ),
          0
        )::numeric(12,2) as earnings_pool_ex
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'OVERPAYMENT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    alloc_base as (
      select
        cb.candidate_id,
        ct.finance_case_id,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        cb.earnings_pool_ex,
        sum(ct.frozen_remaining_source_amount) over (
          partition by cb.candidate_id
          order by ct.sort_order, ct.template_sort_at, ct.finance_case_id, ct.finance_component_id, coalesce(ct.source_ref, '')
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      where (v_scope <> 'PAYE' or cb.awaiting_net_amount = false)
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'OVERPAYMENT')) = 'OVERPAYMENT'
    )
    select
      ab.candidate_id,
      ab.finance_case_id as advance_id,
      round(
        least(
          ab.frozen_remaining_source_amount,
          greatest(ab.earnings_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
        ),
        2
      )::numeric(12,2) as take_ex,
      31 as ord
    from alloc_base ab
    where round(
      least(
        ab.frozen_remaining_source_amount,
        greatest(ab.earnings_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
      ),
      2
    ) > 0;

    insert into pg_temp.tmp_fresh_candidate_expected_overpay (
      candidate_id,
      expected_overpayment_recovery_ex
    )
    select
      teo.candidate_id,
      round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpayment_recovery_ex
    from pg_temp.tmp_fresh_expected_overpay_alloc teo
    group by teo.candidate_id;

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_overpay as (
      select
        coalesce(
          pbi.finance_case_id,
          case
            when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
        and pbi.repayment_week_start = v_week_start
      group by 1
    ),
    actual_overpay as (
      select
        teo.advance_id as finance_case_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.advance_id
    ),
    union_keys as (
      select beo.finance_case_id from batch_expected_overpay beo
      union
      select ao.finance_case_id from actual_overpay ao
    )
    select
      'OVERPAYMENT_RECOVERY' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(beo.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(ao.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      31 as ord
    from union_keys uk
    left join batch_expected_overpay beo
      on beo.finance_case_id = uk.finance_case_id
    left join actual_overpay ao
      on ao.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(beo.expected_ex, 0), 2) <> round(coalesce(ao.actual_ex, 0), 2);

    insert into pg_temp.tmp_fresh_expected_loan_alloc (
      candidate_id,
      loan_id,
      take_ex,
      ord
    )
    with batch_expected_overpay_by_candidate as (
      select
        teo.candidate_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpay_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.candidate_id
    ),
    candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        greatest(coalesce(pni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'LOAN_REPAYMENT'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    loan_seed as (
      select
        cb.pay_batch_candidate_id,
        cb.candidate_id,
        ct.finance_case_id,
        ct.template_sort_at,
        ct.sort_order,
        round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        round(greatest(cb.paye_net_amount - coalesce(beo.expected_overpay_ex, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        round(greatest(cb.paye_net_amount - coalesce(beo.expected_overpay_ex, 0), 0), 2)::numeric(12,2) as run_take_home_before_ex
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      left join batch_expected_overpay_by_candidate beo
        on beo.candidate_id = cb.candidate_id
      where cb.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'PAYMENT_ADVANCE')) = 'PAYMENT_ADVANCE'
        and upper(coalesce(ct.frozen_payout_status, 'PAID')) = 'PAID'
        and (ct.frozen_next_due_week_start is null or ct.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2) > 0
    ),
    loan_inputs as (
      select
        ls.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ls.sort_order,
              'finance_case_id', ls.finance_case_id::text,
              'case_type', 'PAYMENT_ADVANCE',
              'payout_status', 'PAID',
              'nominal_due_amount', ls.nominal_due_amount,
              'minimum_earnings_threshold', ls.minimum_earnings_threshold,
              'take_home_floor_override', ls.take_home_floor_override
            )
            order by ls.sort_order, ls.template_sort_at, ls.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ls.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ls.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex
      from loan_seed ls
      group by ls.candidate_id
    ),
    loan_alloc as (
      select
        li.candidate_id,
        lra.finance_case_id,
        round(coalesce(lra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from loan_inputs li
      cross join lateral public._pay_finance_protected_recovery_allocate(
        li.recovery_rows_json,
        li.run_earnings_headroom_ex,
        li.run_take_home_before_ex,
        null::numeric
      ) lra
    )
    select
      la.candidate_id,
      la.finance_case_id as loan_id,
      la.take_ex,
      33 as ord
    from loan_alloc la
    where round(coalesce(la.take_ex, 0), 2) > 0;

    insert into pg_temp.tmp_fresh_expected_manual_debt_alloc (
      candidate_id,
      finance_case_id,
      take_ex,
      ord
    )
    with batch_expected_overpay_by_candidate as (
      select
        teo.candidate_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpay_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.candidate_id
    ),
    batch_expected_loan_by_candidate as (
      select
        tel.candidate_id,
        round(sum(tel.take_ex), 2)::numeric(12,2) as expected_loan_ex
      from pg_temp.tmp_fresh_expected_loan_alloc tel
      group by tel.candidate_id
    ),
    candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        round(greatest(coalesce(pbc.gross_preview, 0), 0), 2)::numeric(12,2) as gross_preview_ex,
        greatest(coalesce(pni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount,
        case
          when v_scope = 'PAYE' then round(greatest(coalesce(pni.net_amount, 0), 0), 2)::numeric(12,2)
          else null::numeric(12,2)
        end as run_take_home_base_ex
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'MANUAL_DEBT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    manual_template_values as (
      select
        cb.pay_batch_candidate_id,
        cb.candidate_id,
        ct.finance_case_id,
        ct.template_sort_at,
        ct.sort_order,
        ct.frozen_case_type,
        ct.frozen_next_due_week_start,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        ct.frozen_weekly_due_amount,
        ct.frozen_remaining_source_amount,
        nullif(ct.default_take_home_floor, 0)::numeric(12,2) as default_take_home_floor,
        round(greatest(cb.gross_preview_ex, 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        case
          when v_scope = 'PAYE' then round(greatest(coalesce(cb.run_take_home_base_ex, 0) - coalesce(beo.expected_overpay_ex, 0) - coalesce(bl.expected_loan_ex, 0), 0), 2)::numeric(12,2)
          else null::numeric(12,2)
        end as run_take_home_before_ex,
        sched_md.scheduled_due_amount
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      left join batch_expected_overpay_by_candidate beo
        on beo.candidate_id = cb.candidate_id
      left join batch_expected_loan_by_candidate bl
        on bl.candidate_id = cb.candidate_id
      left join lateral (
        select
          round(greatest(abs((sched_item.value->>'amount')::numeric), 0), 2)::numeric(12,2) as scheduled_due_amount
        from jsonb_array_elements(
          case
            when jsonb_typeof(coalesce(ct.frozen_source_basis_json->'schedule_json', '[]'::jsonb)) = 'array'
              then coalesce(ct.frozen_source_basis_json->'schedule_json', '[]'::jsonb)
            else '[]'::jsonb
          end
        ) as sched_item(value)
        where nullif(btrim(sched_item.value->>'week_start'), '') is not null
          and (sched_item.value->>'week_start')::date = v_week_start
        limit 1
      ) sched_md on true
      where (v_scope <> 'PAYE' or cb.awaiting_net_amount = false)
    ),
    manual_seed as (
      select
        mtv.candidate_id,
        mtv.finance_case_id,
        mtv.template_sort_at,
        mtv.sort_order,
        round(greatest(least(coalesce(mtv.scheduled_due_amount, mtv.frozen_weekly_due_amount, 0::numeric(12,2)), mtv.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        mtv.minimum_earnings_threshold,
        mtv.take_home_floor_override,
        mtv.run_earnings_headroom_ex,
        mtv.run_take_home_before_ex,
        mtv.default_take_home_floor
      from manual_template_values mtv
      where upper(coalesce(mtv.frozen_case_type, 'MANUAL_DEBT_ADJUSTMENT')) = 'MANUAL_DEBT_ADJUSTMENT'
        and mtv.frozen_remaining_source_amount > 0
        and (mtv.frozen_next_due_week_start is null or mtv.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(mtv.scheduled_due_amount, mtv.frozen_weekly_due_amount, 0::numeric(12,2)), mtv.frozen_remaining_source_amount), 0), 2) > 0
    ),
    manual_inputs as (
      select
        ms.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ms.sort_order,
              'finance_case_id', ms.finance_case_id::text,
              'case_type', 'MANUAL_DEBT_ADJUSTMENT',
              'payout_status', null,
              'nominal_due_amount', ms.nominal_due_amount,
              'minimum_earnings_threshold', ms.minimum_earnings_threshold,
              'take_home_floor_override', ms.take_home_floor_override
            )
            order by ms.sort_order, ms.template_sort_at, ms.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ms.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ms.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex,
        nullif(max(ms.default_take_home_floor), 0)::numeric(12,2) as default_take_home_floor
      from manual_seed ms
      group by ms.candidate_id
    ),
    manual_alloc as (
      select
        mi.candidate_id,
        mdra.finance_case_id,
        round(coalesce(mdra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from manual_inputs mi
      cross join lateral public._pay_finance_protected_recovery_allocate(
        mi.recovery_rows_json,
        mi.run_earnings_headroom_ex,
        mi.run_take_home_before_ex,
        mi.default_take_home_floor
      ) mdra
    )
    select
      ma.candidate_id,
      ma.finance_case_id,
      ma.take_ex,
      32 as ord
    from manual_alloc ma
    where round(coalesce(ma.take_ex, 0), 2) > 0;

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_manual as (
      select
        coalesce(
          pbi_md.finance_case_id,
          case
            when pbi_md.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_md.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi_md.amount_ex_vat, pbi_md.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi_md
      join public.pay_batch_candidates pbc_md
        on pbc_md.id = pbi_md.pay_batch_candidate_id
      where pbc_md.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_md.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_md_fresh_exclusion
        where ppc_pbi_md_fresh_exclusion.pay_batch_item_id = pbi_md.id
          and ppc_pbi_md_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_md_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi_md.item_type = 'MANUAL_DEBT_RECOVERY'
        and pbi_md.repayment_week_start = v_week_start
      group by 1
    ),
    actual_manual as (
      select
        temd.finance_case_id,
        round(sum(temd.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_manual_debt_alloc temd
      group by temd.finance_case_id
    ),
    union_keys as (
      select bem.finance_case_id from batch_expected_manual bem
      union
      select am.finance_case_id from actual_manual am
    )
    select
      'MANUAL_DEBT_RECOVERY' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(bem.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(am.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      32 as ord
    from union_keys uk
    left join batch_expected_manual bem
      on bem.finance_case_id = uk.finance_case_id
    left join actual_manual am
      on am.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(bem.expected_ex, 0), 2) <> round(coalesce(am.actual_ex, 0), 2);

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_loans as (
      select
        coalesce(
          pbi_ln.finance_case_id,
          case
            when pbi_ln.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_ln.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi_ln.amount_ex_vat, pbi_ln.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi_ln
      join public.pay_batch_candidates pbc_ln
        on pbc_ln.id = pbi_ln.pay_batch_candidate_id
      where pbc_ln.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_ln.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_ln_fresh_exclusion
        where ppc_pbi_ln_fresh_exclusion.pay_batch_item_id = pbi_ln.id
          and ppc_pbi_ln_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_ln_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi_ln.item_type = 'LOAN_REPAYMENT'
        and pbi_ln.repayment_week_start = v_week_start
      group by 1
    ),
    actual_loans as (
      select
        tel.loan_id as finance_case_id,
        round(sum(tel.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_loan_alloc tel
      group by tel.loan_id
    ),
    union_keys as (
      select bel.finance_case_id from batch_expected_loans bel
      union
      select al.finance_case_id from actual_loans al
    )
    select
      'LOAN_REPAYMENT' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(bel.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(al.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      33 as ord
    from union_keys uk
    left join batch_expected_loans bel
      on bel.finance_case_id = uk.finance_case_id
    left join actual_loans al
      on al.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(bel.expected_ex, 0), 2) <> round(coalesce(al.actual_ex, 0), 2);

    select count(*)::int
    into v_overpay_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'OVERPAYMENT_RECOVERY';

    select count(*)::int
    into v_manual_debt_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'MANUAL_DEBT_RECOVERY';

    select count(*)::int
    into v_loan_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'LOAN_REPAYMENT';

    v_ded_diff_ct := coalesce(v_overpay_ded_diff_ct, 0)
                     + coalesce(v_manual_debt_ded_diff_ct, 0)
                     + coalesce(v_loan_ded_diff_ct, 0);

    if exists (
      select 1
      from pg_temp.tmp_fresh_state_diffs tsd
      where tsd.key_type = 'DEDUCTION_TEMPLATE'
    ) then
      v_is_stale := true;
      v_reasons := array_append(v_reasons, 'DEDUCTION_TEMPLATE_MISSING');
    end if;

    if v_ded_diff_ct > 0 then
      v_is_stale := true;
      v_reasons := array_append(v_reasons, 'DEDUCTION_CHANGED');
    end if;
  end if;
  ---------------------------------------------------------------------------
  -- PAYE_NET_CHANGED:
  -- PAYE net entry and PAYE net edits are draft-owned mutable batch data,
  -- not live-truth freshness drift. Users must be able to enter, save,
  -- revisit, and amend PAYE net values on an existing draft without making
  -- the batch stale.
  --
  -- Real live-truth drift for the batch remains covered by the economic-key,
  -- reservation, deduction, snooze, override, restructuring, writeoff, and
  -- guardrail checks above. PAYE_NET is therefore intentionally excluded from
  -- stale detection here.
  ---------------------------------------------------------------------------
  if v_scope = 'PAYE' and coalesce(v_batch_kind_fixed,'') <> 'LOANS' then
    v_paye_net_diff_ct := 0;
  end if;

  ---------------------------------------------------------------------------
  -- Build final diff array from the temp diff tables.
  ---------------------------------------------------------------------------
  with diff_rows as (
    select
      t.ord,
      coalesce(t.timesheet_id::text, '') as sort1,
      t.key_type as sort2,
      t.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', t.timesheet_id::text,
        'key_type', t.key_type,
        'key_value', t.key_value,
        'expected', t.expected_text,
        'actual', t.actual_text
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_ts_diffs t0
      order by coalesce(t0.timesheet_id::text, ''), t0.key_type, t0.key_value
      limit v_diff_limit
    ) t

    union all

    select
      k.ord,
      coalesce(k.timesheet_id::text, '') as sort1,
      k.key_type as sort2,
      k.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', k.timesheet_id::text,
        'key_type', k.key_type,
        'key_value', k.key_value,
        'expected', k.expected_ex,
        'actual', k.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_key_diffs k0
      order by coalesce(k0.timesheet_id::text, ''), k0.key_type, k0.key_value
      limit v_diff_limit
    ) k

    union all

    select
      d.ord,
      '' as sort1,
      d.key_type as sort2,
      d.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', d.key_type,
        'key_value', d.key_value,
        'expected', d.expected_ex,
        'actual', d.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_deduction_diffs d0
      order by d0.ord, d0.key_type, d0.key_value
      limit v_diff_limit
    ) d

    union all

    select
      p.ord,
      p.candidate_id::text as sort1,
      p.key_type as sort2,
      p.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', p.key_type,
        'key_value', p.key_value,
        'expected', p.expected_ex,
        'actual', p.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_paye_net_diffs p0
      order by p0.candidate_id::text, p0.key_type, p0.key_value
      limit v_diff_limit
    ) p

    union all

    select
      s.ord,
      coalesce(s.candidate_id::text, coalesce(s.timesheet_id::text, '')) as sort1,
      s.key_type as sort2,
      s.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', s.timesheet_id::text,
        'key_type', s.key_type,
        'key_value', s.key_value,
        'expected', s.expected_text,
        'actual', s.actual_text
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_state_diffs s0
      order by coalesce(s0.candidate_id::text, coalesce(s0.timesheet_id::text, '')), s0.key_type, s0.key_value
      limit v_diff_limit
    ) s

    union all

    select
      99 as ord,
      '' as sort1,
      'INFO' as sort2,
      'COUNTS' as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', 'INFO',
        'key_value', 'COUNTS',
        'expected', jsonb_build_object(
          'ts_changed', v_ts_changed_ct,
          'key_diffs', v_key_diff_ct,
          'finance_reservation_diffs', v_finance_reservation_diff_ct,
          'snooze_diffs', v_snooze_diff_ct,
          'restructure_diffs', v_restructure_diff_ct,
          'writeoff_diffs', v_writeoff_diff_ct,
          'timesheet_override_diffs', v_timesheet_override_diff_ct,
          'paye_guardrail_diffs', v_paye_guardrail_diff_ct,
          'ded_diffs', v_ded_diff_ct,
          'overpayment_ded_diffs', v_overpay_ded_diff_ct,
          'manual_debt_ded_diffs', v_manual_debt_ded_diff_ct,
          'loan_ded_diffs', v_loan_ded_diff_ct,
          'paye_net_diffs', v_paye_net_diff_ct
        ),
        'actual', null
      ) as diff_json
  )
  select
    coalesce(
      jsonb_agg(dr.diff_json order by dr.ord, dr.sort1, dr.sort2, dr.sort3),
      '[]'::jsonb
    )
  into v_diffs
  from diff_rows dr;

  v_carry_forward_freshness_result := public._pay_manual_adjustment_carry_forward_freshness_check(
    p_pay_batch_id,
    NULL::uuid[],
    NULL::uuid[],
    jsonb_build_object('pay_batch_id', p_pay_batch_id::text),
    p_actor_user_id
  );

  v_carry_forward_blocker_count := jsonb_array_length(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb));

  IF COALESCE(v_carry_forward_blocker_count, 0) > 0 THEN
    v_is_stale := true;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_blockers(blocker_value)
      WHERE COALESCE(carry_forward_blockers.blocker_value->>'code', '') IN (
        'MANUAL_ADJUSTMENT_CARRY_FORWARD_CHANGED',
        'MANUAL_ADJUSTMENT_CARRY_FORWARD_AMOUNT_CHANGED',
        'MANUAL_ADJUSTMENT_CARRY_FORWARD_SOURCE_AMOUNT_CHANGED',
        'MANUAL_ADJUSTMENT_CARRY_FORWARD_RESERVED_ELSEWHERE',
        'RESERVED_CARRY_FORWARD_MISSING_FROM_TARGET_BATCH',
        'RESERVED_CARRY_FORWARD_TARGET_ITEM_VOIDED',
        'PENDING_CARRY_FORWARD_NOT_INCLUDED_IN_TARGET_BATCH'
      )
    ) THEN
      v_reasons := array_append(v_reasons, 'Manual adjustment carry-forward changed');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_blockers(blocker_value)
      WHERE COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
    ) THEN
      v_reasons := array_append(v_reasons, 'Manual adjustment carry-forward was consumed elsewhere');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_blockers(blocker_value)
      WHERE COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
    ) THEN
      v_reasons := array_append(v_reasons, 'Source payment scope changed');
    END IF;

    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', NULL,
          'key_type', 'MANUAL_CARRY_FORWARD',
          'key_value', COALESCE(carry_forward_blockers.blocker_value->>'carry_forward_id', carry_forward_blockers.blocker_value->>'code'),
          'expected', jsonb_build_object(
            'status', 'fresh',
            'message', 'Manual adjustment carry-forward remains reserved for this batch with unchanged signed amounts.'
          ),
          'actual', carry_forward_blockers.blocker_value
        )
        ORDER BY COALESCE(carry_forward_blockers.blocker_value->>'carry_forward_id', ''), COALESCE(carry_forward_blockers.blocker_value->>'code', '')
      ),
      '[]'::jsonb
    )
    INTO v_carry_forward_freshness_result
    FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_blockers(blocker_value);

    v_diffs := COALESCE(v_diffs, '[]'::jsonb) || COALESCE(v_carry_forward_freshness_result, '[]'::jsonb);
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS correction_items
    WHERE correction_items.pay_batch_id = p_pay_batch_id
      AND correction_items.status = 'APPLIED'
      AND correction_items.correction_item_kind = 'PRE_BANK_CANCEL'
  ) THEN
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'Payment was cancelled/recalculated');
    v_diffs := COALESCE(v_diffs, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'timesheet_id', NULL,
      'key_type', 'PAYMENT_CORRECTION',
      'key_value', 'PRE_BANK_CANCEL',
      'expected', jsonb_build_object('payment_scope', 'active'),
      'actual', jsonb_build_object('payment_scope', 'cancelled/recalculated')
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS correction_items
    WHERE correction_items.pay_batch_id = p_pay_batch_id
      AND correction_items.status = 'APPLIED'
      AND correction_items.correction_item_kind = 'NO_MONEY_UNWIND'
  ) THEN
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'Financials were rewound');
    v_diffs := COALESCE(v_diffs, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'timesheet_id', NULL,
      'key_type', 'PAYMENT_CORRECTION',
      'key_value', 'NO_MONEY_UNWIND',
      'expected', jsonb_build_object('financials', 'reserved/active'),
      'actual', jsonb_build_object('financials', 'rewound')
    ));
  END IF;

  if array_length(v_reasons,1) is not null then
    select coalesce(array_agg(distinct r order by r), array[]::text[])
    into v_reasons
    from unnest(v_reasons) r;
  end if;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_VALIDATE_FRESHNESS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_date', v_pay_date::text,
        'week_start', v_week_start::text,
        'batch_kind_fixed', coalesce(v_batch_kind_fixed, null),
        'scope', coalesce(v_scope, null),
        'is_stale', v_is_stale,
        'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
        'counts', jsonb_build_object(
          'timesheet_changed', v_ts_changed_ct,
          'stable_key_diffs', v_key_diff_ct,
          'finance_reservation_diffs', v_finance_reservation_diff_ct,
          'snooze_diffs', v_snooze_diff_ct,
          'restructure_diffs', v_restructure_diff_ct,
          'writeoff_diffs', v_writeoff_diff_ct,
          'timesheet_override_diffs', v_timesheet_override_diff_ct,
          'paye_guardrail_diffs', v_paye_guardrail_diff_ct,
          'deduction_diffs', v_ded_diff_ct,
          'overpayment_deduction_diffs', v_overpay_ded_diff_ct,
          'manual_debt_deduction_diffs', v_manual_debt_ded_diff_ct,
          'loan_deduction_diffs', v_loan_ded_diff_ct,
          'paye_net_diffs', v_paye_net_diff_ct
        )
      ),
      'pay_batches',
      p_pay_batch_id::text
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'is_stale', v_is_stale,
    'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
    'diff', coalesce(v_diffs, '[]'::jsonb)
  );
end;
$function$;


DROP FUNCTION IF EXISTS public.pay_batch_get_section_page(uuid, text, jsonb, integer, uuid, jsonb, jsonb);




CREATE OR REPLACE FUNCTION public.pay_batch_get_section_page(p_pay_batch_id uuid, p_section text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100, p_actor_user_id uuid DEFAULT NULL::uuid, p_filters_json jsonb DEFAULT '{}'::jsonb, p_sort_json jsonb DEFAULT '{}'::jsonb, p_purpose text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.pay_batches%ROWTYPE;
  v_section text := LOWER(REPLACE(NULLIF(BTRIM(COALESCE(p_section, '')), ''), '-', '_'));
  v_purpose text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_purpose, '')), ''), '-', '_'));
  v_limit integer := COALESCE(p_limit, 100);
  v_cursor_id uuid := NULL::uuid;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := NULL::jsonb;
  v_returned_count integer := 0;
  v_raw_count integer := 0;
  v_last_cursor_text text := NULL::text;
  v_known_total_count integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_server_time_utc timestamptz := now();
  v_live_signal_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_overview_version bigint := 0;
  v_last_status_hash text := NULL::text;
  v_last_alert_hash text := NULL::text;
  v_known_live_signal_version bigint := NULL::bigint;
  v_changed_since_version boolean := false;
  v_section_page_signature text := NULL::text;
  v_freshness_summary jsonb := '{}'::jsonb;
  v_candidate_scope_type text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id_text text := NULL::text;
  v_candidate_scope_candidate_id_text text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id uuid := NULL::uuid;
  v_candidate_scope_candidate_id uuid := NULL::uuid;
  v_candidate_scope_actual_pay_batch_id uuid := NULL::uuid;
  v_candidate_scope_actual_candidate_id uuid := NULL::uuid;
  v_candidate_scope_enabled boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply(
    CASE
      WHEN v_purpose = 'OVERVIEW' OR v_section IN ('overview', 'overview_items') THEN 'OVERVIEW_PAGE'
      ELSE 'EXPLICIT_DIAGNOSTIC'
    END
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_section IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED')::text;
  END IF;

  IF v_section = 'overview' THEN
    v_section := 'overview_items';
  END IF;

  IF v_section = 'overview_items' THEN
    v_purpose := 'OVERVIEW';
  END IF;

  IF v_purpose IS NULL THEN
    v_purpose := 'SECTION_PAGE';
  END IF;

  IF v_purpose NOT IN (
    'SECTION_PAGE',
    'OVERVIEW',
    'DETAIL',
    'PAYE_WORKSHEET',
    'CURRENT_PAYMENT_STATUS',
    'PAYMENT_ISSUES',
    'REMITTANCE'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE',
              'purpose', v_purpose,
              'allowed_purposes', jsonb_build_array(
                'SECTION_PAGE',
                'OVERVIEW',
                'DETAIL',
                'PAYE_WORKSHEET',
                'CURRENT_PAYMENT_STATUS',
                'PAYMENT_ISSUES',
                'REMITTANCE'
              )
            )::text;
  END IF;

  IF v_purpose = 'OVERVIEW' AND v_section <> 'overview_items' THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED',
              'purpose', v_purpose,
              'section', v_section,
              'message', 'Overview purpose may only load overview_items.'
            )::text;
  END IF;

  IF v_section NOT IN (
    'overview_items',
    'candidates',
    'items',
    'item_breakdowns',
    'transfers',
    'current_payment_status',
    'finance_case_groups',
    'remittances',
    'communications',
    'auth_history',
    'events'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION',
              'section', v_section
            )::text;
  END IF;

  v_limit := GREATEST(1, LEAST(v_limit, CASE WHEN v_section = 'overview_items' OR v_purpose = 'OVERVIEW' THEN 100 ELSE 250 END));

  IF p_cursor_json IS NOT NULL
     AND jsonb_typeof(p_cursor_json) = 'object'
     AND NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_cursor_id := COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id')::uuid;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_filters_json IS NOT NULL AND jsonb_typeof(p_filters_json) = 'object' THEN
    BEGIN
      v_known_live_signal_version := NULLIF(BTRIM(COALESCE(
        p_filters_json ->> 'known_live_signal_version',
        p_filters_json ->> 'known_version',
        p_filters_json ->> 'live_signal_version',
        p_filters_json #>> '{live_signal,version}',
        ''
      )), '')::bigint;
    EXCEPTION WHEN OTHERS THEN
      v_known_live_signal_version := NULL::bigint;
    END;

    v_candidate_scope_type := NULLIF(
      UPPER(REGEXP_REPLACE(BTRIM(COALESCE(
        p_filters_json ->> 'scope_type',
        p_filters_json ->> 'scopeType',
        ''
      )), '[[:space:]-]+', '_', 'g')),
      ''
    );
    v_candidate_scope_pay_batch_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'pay_batch_candidate_id',
      p_filters_json ->> 'payBatchCandidateId',
      ''
    )), '');
    v_candidate_scope_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'candidate_id',
      p_filters_json ->> 'candidateId',
      ''
    )), '');
  END IF;

  IF v_candidate_scope_type = 'PAY_BATCH_CANDIDATE' THEN
    IF v_section <> 'items' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED',
                'section', v_section,
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text IS NULL
       OR v_candidate_scope_candidate_id_text IS NULL THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED',
                'scope_type', v_candidate_scope_type,
                'requires', jsonb_build_array('pay_batch_candidate_id', 'candidate_id')
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_candidate_scope_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_pay_batch_candidate_id := v_candidate_scope_pay_batch_candidate_id_text::uuid;
    v_candidate_scope_candidate_id := v_candidate_scope_candidate_id_text::uuid;

    SELECT
      candidate_scope.pay_batch_id,
      candidate_scope.candidate_id
    INTO
      v_candidate_scope_actual_pay_batch_id,
      v_candidate_scope_actual_candidate_id
    FROM public.pay_batch_candidates AS candidate_scope
    WHERE candidate_scope.id = v_candidate_scope_pay_batch_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_actual_pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH',
                'scope_type', v_candidate_scope_type,
                'pay_batch_id', p_pay_batch_id::text
              )::text;
    END IF;

    IF v_candidate_scope_actual_candidate_id IS DISTINCT FROM v_candidate_scope_candidate_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_enabled := true;
  ELSIF v_section = 'items'
        AND (v_candidate_scope_pay_batch_candidate_id_text IS NOT NULL OR v_candidate_scope_candidate_id_text IS NOT NULL) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED',
              'required_scope_type', 'PAY_BATCH_CANDIDATE'
            )::text;
  END IF;

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash
  INTO
    v_live_signal_version,
    v_payment_status_version,
    v_correction_progress_version,
    v_alert_version,
    v_overview_version,
    v_last_status_hash,
    v_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_live_signal_version := 0;
    v_payment_status_version := 0;
    v_correction_progress_version := 0;
    v_alert_version := 0;
    v_overview_version := 0;
    v_last_status_hash := NULL::text;
    v_last_alert_hash := NULL::text;
  END IF;

  v_changed_since_version := (
    v_known_live_signal_version IS NOT NULL
    AND COALESCE(v_live_signal_version, 0) > v_known_live_signal_version
  );

  v_freshness_summary := jsonb_strip_nulls(jsonb_build_object(
    'freshness_validation_status', v_batch.freshness_validation_status,
    'freshness_checked_at_utc', CASE WHEN v_batch.freshness_checked_at_utc IS NULL THEN NULL::text ELSE v_batch.freshness_checked_at_utc::text END,
    'freshness_result_hash', v_batch.freshness_result_hash,
    'freshness_scope_hash', v_batch.freshness_scope_hash
  ));

  IF v_section = 'overview_items' THEN
    WITH raw_item_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.pay_bank_transfer_id,
        NULLIF(BTRIM(COALESCE(
          pay_bank_transfer_page.payee_name,
          pay_batch_item_page.payout_instruction_snapshot_json->>'payee_name',
          pay_batch_item_page.payout_instruction_snapshot_json->>'account_holder_name',
          pay_batch_candidate_page.candidate_display_name
        )), '') AS payee_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
          pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
          CASE
            WHEN timesheet_display_page.week_ending_date IS NULL THEN NULL::text
            ELSE timesheet_display_page.week_ending_date::text
          END
        )), '') AS week_ending_date,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
          pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
          pay_batch_item_page.frozen_resolution_result_json->>'client_name',
          timesheet_display_page.hospital_norm
        )), '') AS client_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'role',
          pay_batch_item_page.frozen_source_basis_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json->>'role',
          pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
          pay_batch_item_page.frozen_resolution_payload_json->>'role',
          pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
          timesheet_display_page.job_title_norm
        )), '') AS role,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'date',
          CASE
            WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
             AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
            THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
            ELSE NULL::text
          END
        )), '') AS worked_date,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
          THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
          ELSE NULL::text
        END AS additional_code
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.pay_batch_candidate_id = pay_batch_candidate_page.id
      LEFT JOIN public.pay_bank_transfers AS pay_bank_transfer_page
        ON pay_bank_transfer_page.id = pay_batch_item_page.pay_bank_transfer_id
      LEFT JOIN public.timesheets AS timesheet_display_page
        ON timesheet_display_page.timesheet_id = pay_batch_item_page.timesheet_id
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
    ),
    raw_item_rows_with_grouping AS (
      SELECT
        raw_item_rows.*,
        raw_item_rows.item_type AS source_item_type,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN 'TIMESHEET_PAYMENT'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'EXPENSE'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'MILEAGE'
          ELSE 'ITEM'
        END AS overview_group_kind,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN CONCAT_WS('|', 'TIMESHEET_PAYMENT', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'EXPENSE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'MILEAGE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          ELSE CONCAT_WS('|', 'ITEM', raw_item_rows.id::text)
        END AS overview_group_key
      FROM raw_item_rows
    ),
    grouped_rows AS (
      SELECT
        (ARRAY_AGG(group_source.id ORDER BY group_source.id ASC))[1] AS id,
        (ARRAY_AGG(group_source.pay_batch_candidate_id ORDER BY group_source.id ASC))[1] AS pay_batch_candidate_id,
        (ARRAY_AGG(group_source.candidate_id ORDER BY group_source.id ASC))[1] AS candidate_id,
        (ARRAY_AGG(group_source.candidate_tms_ref ORDER BY group_source.id ASC))[1] AS candidate_tms_ref,
        (ARRAY_AGG(group_source.candidate_display_name ORDER BY group_source.id ASC))[1] AS candidate_display_name,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'EXPENSE'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'MILEAGE'
          ELSE (ARRAY_AGG(group_source.item_type ORDER BY group_source.id ASC))[1]
        END AS item_type,
        (ARRAY_AGG(group_source.source_item_type ORDER BY group_source.id ASC))[1] AS source_item_type,
        (ARRAY_AGG(group_source.timesheet_id ORDER BY group_source.id ASC))[1] AS timesheet_id,
        (ARRAY_AGG(group_source.pay_channel ORDER BY group_source.id ASC))[1] AS pay_channel,
        (ARRAY_AGG(group_source.source_ref ORDER BY group_source.id ASC) FILTER (WHERE group_source.source_ref IS NOT NULL))[1] AS source_ref,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'Expense'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'Mileage'
          ELSE (ARRAY_AGG(group_source.description ORDER BY group_source.id ASC))[1]
        END AS description,
        ROUND(SUM(COALESCE(group_source.amount_ex_vat, 0)), 2)::numeric(12,2) AS amount_ex_vat,
        ROUND(SUM(COALESCE(group_source.amount_vat, 0)), 2)::numeric(12,2) AS amount_vat,
        ROUND(SUM(COALESCE(group_source.amount_inc_vat, 0)), 2)::numeric(12,2) AS amount_inc_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_ex_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_ex_vat, group_source.amount_ex_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_ex_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_vat, group_source.amount_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_inc_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_inc_vat, group_source.amount_inc_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_inc_vat,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_type ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_type,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_value ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_value,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_classification::text ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_classification,
        (ARRAY_AGG(group_source.frozen_source_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_source_pay_method IS NOT NULL))[1] AS frozen_source_pay_method,
        (ARRAY_AGG(group_source.frozen_target_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_target_pay_method IS NOT NULL))[1] AS frozen_target_pay_method,
        (ARRAY_AGG(group_source.pay_bank_transfer_id ORDER BY group_source.id ASC) FILTER (WHERE group_source.pay_bank_transfer_id IS NOT NULL))[1] AS pay_bank_transfer_id,
        (ARRAY_AGG(group_source.payee_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.payee_name IS NOT NULL))[1] AS payee_name,
        (ARRAY_AGG(group_source.week_ending_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.week_ending_date IS NOT NULL))[1] AS week_ending_date,
        (ARRAY_AGG(group_source.client_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.client_name IS NOT NULL))[1] AS client_name,
        (ARRAY_AGG(group_source.role ORDER BY group_source.id ASC) FILTER (WHERE group_source.role IS NOT NULL))[1] AS role,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.worked_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.worked_date IS NOT NULL))[1]
          ELSE NULL::text
        END AS worked_date,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.additional_code ORDER BY group_source.id ASC) FILTER (WHERE group_source.additional_code IS NOT NULL))[1]
          ELSE NULL::text
        END AS additional_code,
        group_source.overview_group_kind,
        (COUNT(*) > 1)::boolean AS overview_grouped,
        COUNT(*)::integer AS overview_grouped_item_count,
        TO_JSONB(ARRAY_AGG(group_source.id::text ORDER BY group_source.id ASC)) AS pay_batch_item_ids,
        COALESCE(
          jsonb_agg(
            jsonb_strip_nulls(jsonb_build_object(
              'pay_batch_item_id', group_source.id::text,
              'key_type', group_source.frozen_component_key_type,
              'key_value', group_source.frozen_component_key_value
            ))
            ORDER BY group_source.id ASC
          ) FILTER (
            WHERE group_source.frozen_component_key_type IS NOT NULL
               OR group_source.frozen_component_key_value IS NOT NULL
          ),
          '[]'::jsonb
        ) AS grouped_frozen_economic_keys
      FROM raw_item_rows_with_grouping AS group_source
      GROUP BY
        group_source.overview_group_key,
        group_source.overview_group_kind
    ),
    page_rows AS (
      SELECT grouped_rows.*
      FROM grouped_rows
      WHERE v_cursor_id IS NULL OR grouped_rows.id > v_cursor_id
      ORDER BY grouped_rows.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'id', page_rows.id::text,
              'pay_batch_item_id', page_rows.id::text,
              'pay_batch_item_ids', COALESCE(page_rows.pay_batch_item_ids, '[]'::jsonb),
              'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
              'candidate_id', page_rows.candidate_id::text,
              'candidate_tms_ref', page_rows.candidate_tms_ref,
              'candidate_display_name', page_rows.candidate_display_name,
              'candidate_name', page_rows.candidate_display_name,
              'payee_name', COALESCE(page_rows.payee_name, page_rows.candidate_display_name),
              'item_type', page_rows.item_type,
              'source_item_type', page_rows.source_item_type,
              'overview_group_kind', page_rows.overview_group_kind,
              'overview_grouped', page_rows.overview_grouped,
              'overview_grouped_item_count', page_rows.overview_grouped_item_count,
              'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
              'pay_channel', page_rows.pay_channel,
              'source_ref', page_rows.source_ref,
              'source_reference', page_rows.source_ref,
              'description', page_rows.description
            )
            || jsonb_build_object(
              'amount_ex_vat', page_rows.amount_ex_vat,
              'amount_vat', page_rows.amount_vat,
              'amount_inc_vat', page_rows.amount_inc_vat,
              'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
              'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
              'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat,
              'frozen_economic_key_type', page_rows.frozen_component_key_type,
              'frozen_economic_key_value', page_rows.frozen_component_key_value,
              'grouped_frozen_economic_keys', COALESCE(page_rows.grouped_frozen_economic_keys, '[]'::jsonb),
              'frozen_component_classification', page_rows.frozen_component_classification,
              'frozen_source_pay_method', page_rows.frozen_source_pay_method,
              'frozen_target_pay_method', page_rows.frozen_target_pay_method,
              'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'additional_code', page_rows.additional_code,
              'draft_not_submitted', COALESCE(UPPER(BTRIM(COALESCE(v_batch.status, ''))) IN ('DRAFT', 'DRAFT_CREATED'), false)
                AND COALESCE(UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) IN ('', 'NOT_SUBMITTED', 'NONE'), true)
            )
            || jsonb_build_object(
              'frozen_component_key_type', page_rows.frozen_component_key_type,
              'frozen_component_key_value', page_rows.frozen_component_key_value,
              'line_kind', page_rows.item_type,
              'unit_name', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'unit_label', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'display_context_json', jsonb_strip_nulls(jsonb_build_object(
                'week_ending_date', page_rows.week_ending_date,
                'client_name', page_rows.client_name,
                'role', page_rows.role,
                'worked_date', page_rows.worked_date,
                'additional_code', page_rows.additional_code,
                'overview_group_kind', page_rows.overview_group_kind,
                'overview_grouped_item_count', page_rows.overview_grouped_item_count
              ))
            )
          )
          ORDER BY page_rows.id ASC
        ),
        '[]'::jsonb
      ),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO
      v_items,
      v_raw_count,
      v_last_cursor_text
    FROM page_rows;

ELSIF v_section = 'candidates' THEN
    WITH page_rows AS (
      SELECT
        pay_batch_candidate_page.*,
        latest_paye_net_input.id AS latest_paye_net_input_id,
        latest_paye_net_input.source AS paye_net_source,
        latest_paye_net_input.net_amount AS paye_net_amount,
        latest_paye_net_input.imported_at_utc AS paye_net_imported_at_utc,
        latest_paye_net_input.file_name AS paye_net_file_name,
        latest_paye_net_input.file_hash AS paye_net_file_hash,
        ROW_NUMBER() OVER (ORDER BY pay_batch_candidate_page.id ASC) AS row_ordinal
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      LEFT JOIN LATERAL (
        SELECT
          paye_net_input_page.id,
          paye_net_input_page.source,
          paye_net_input_page.net_amount,
          paye_net_input_page.imported_at_utc,
          paye_net_input_page.file_name,
          paye_net_input_page.file_hash
        FROM public.pay_batch_paye_net_inputs AS paye_net_input_page
        WHERE paye_net_input_page.pay_batch_candidate_id = pay_batch_candidate_page.id
        ORDER BY paye_net_input_page.imported_at_utc DESC, paye_net_input_page.id DESC
        LIMIT 1
      ) AS latest_paye_net_input ON true
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_candidate_page.id > v_cursor_id)
      ORDER BY pay_batch_candidate_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'paye_state', page_rows.paye_state,
            'mismatch_settlement_choice', page_rows.mismatch_settlement_choice,
            'gross_preview', page_rows.gross_preview,
            'net_bank_amount', page_rows.net_bank_amount,
            'debt_created', page_rows.debt_created,
            'loan_repayment_taken', page_rows.loan_repayment_taken,
            'overpayment_recovery_taken', page_rows.overpayment_recovery_taken,
            'awaiting_net_amount', page_rows.awaiting_net_amount,
            'settlement_status', page_rows.settlement_status,
            'settled_at_utc', page_rows.settled_at_utc,
            'settled_via', page_rows.settled_via,
            'remittance_trigger_status', page_rows.remittance_trigger_status,
            'remittance_sent_at_utc', page_rows.remittance_sent_at_utc,
            'last_remittance_error', page_rows.last_remittance_error,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'paye_net_amount', page_rows.paye_net_amount,
            'paye_net_source', page_rows.paye_net_source,
            'paye_net_imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
            'latest_paye_net_input', CASE
              WHEN page_rows.latest_paye_net_input_id IS NULL THEN NULL::jsonb
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'id', page_rows.latest_paye_net_input_id::text,
                'pay_batch_candidate_id', page_rows.id::text,
                'candidate_id', page_rows.candidate_id::text,
                'source', page_rows.paye_net_source,
                'net_amount', page_rows.paye_net_amount,
                'imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
                'file_name', page_rows.paye_net_file_name,
                'file_hash', page_rows.paye_net_file_hash
              ))
            END
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'items' THEN
    WITH candidate_scoped_item_ids AS MATERIALIZED (
      SELECT pay_batch_item_scope.id
      FROM public.pay_batch_items AS pay_batch_item_scope
      JOIN public.pay_batch_candidates AS pay_batch_candidate_scope
        ON pay_batch_candidate_scope.id = pay_batch_item_scope.pay_batch_candidate_id
      WHERE pay_batch_candidate_scope.pay_batch_id = p_pay_batch_id
        AND (
          v_candidate_scope_enabled IS NOT TRUE
          OR (
            pay_batch_candidate_scope.id = v_candidate_scope_pay_batch_candidate_id
            AND pay_batch_candidate_scope.candidate_id = v_candidate_scope_candidate_id
          )
        )
        AND (v_cursor_id IS NULL OR pay_batch_item_scope.id > v_cursor_id)
      ORDER BY pay_batch_item_scope.id ASC
      LIMIT (v_limit + 1)
    ), page_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_candidate_page.paye_state AS candidate_paye_state,
        pay_batch_candidate_page.gross_preview AS candidate_gross_preview,
        pay_batch_candidate_page.net_bank_amount AS candidate_net_bank_amount,
        pay_batch_candidate_page.awaiting_net_amount AS candidate_awaiting_net_amount,
        pay_batch_candidate_page.settlement_status AS candidate_settlement_status,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.segment_key,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.umbrella_id,
        pay_batch_item_page.bank_reference,
        pay_batch_item_page.pay_bank_transfer_id,
        pay_batch_item_page.repayment_week_start,
        pay_batch_item_page.is_voided,
        pay_batch_item_page.is_mismatch,
        pay_batch_item_page.finance_case_id,
        pay_batch_item_page.finance_component_id,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_basis_json,
        pay_batch_item_page.frozen_component_snapshot_json,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.frozen_resolution_mode,
        pay_batch_item_page.frozen_resolution_payload_json,
        pay_batch_item_page.frozen_resolution_result_json,
        pay_batch_item_page.operation_source_key,
        pay_batch_item_page.created_at,
        pay_batch_item_page.updated_at,
        breakdown_display.first_breakdown_id,
        breakdown_display.line_kind,
        breakdown_display.bucket_code,
        breakdown_display.breakdown_unit_name,
        breakdown_display.breakdown_units,
        breakdown_display.breakdown_rate,
        breakdown_display.breakdown_amount_ex_vat,
        breakdown_display.breakdowns_json,
        display_context.week_ending_date,
        display_context.client_name,
        display_context.role,
        display_context.worked_date,
        display_context.source_rate,
        display_context.source_charge_rate,
        display_context.additional_code,
        display_line.unit_name,
        CASE
          WHEN display_line.unit_name IS NOT NULL
           AND display_context.role IS NOT NULL
           AND UPPER(display_line.unit_name) <> UPPER(display_context.role) THEN display_line.unit_name || ' / ' || display_context.role
          ELSE COALESCE(display_line.unit_name, display_context.role)
        END AS unit_label,
        breakdown_display.breakdown_units AS units,
        breakdown_display.breakdown_rate AS rate
      FROM candidate_scoped_item_ids AS candidate_scoped_item
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.id = candidate_scoped_item.id
      JOIN public.pay_batch_candidates AS pay_batch_candidate_page
        ON pay_batch_candidate_page.id = pay_batch_item_page.pay_batch_candidate_id
      LEFT JOIN LATERAL (
        SELECT
          (ARRAY_AGG(breakdown_page_inner.id ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_id,
          (ARRAY_AGG(breakdown_page_inner.line_kind ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS line_kind,
          (ARRAY_AGG(breakdown_page_inner.bucket_code ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS bucket_code,
          (ARRAY_AGG(breakdown_page_inner.unit_name ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_unit_name,
          (ARRAY_AGG(breakdown_page_inner.units ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_units,
          (ARRAY_AGG(breakdown_page_inner.rate ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_rate,
          (ARRAY_AGG(breakdown_page_inner.amount_ex_vat ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_amount_ex_vat,
          (ARRAY_AGG(breakdown_page_inner.meta_json ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_meta_json,
          COALESCE(
            jsonb_agg(
              jsonb_strip_nulls(jsonb_build_object(
                'id', breakdown_page_inner.id::text,
                'line_kind', breakdown_page_inner.line_kind,
                'bucket_code', breakdown_page_inner.bucket_code,
                'unit_name', breakdown_page_inner.unit_name,
                'units', breakdown_page_inner.units,
                'rate', breakdown_page_inner.rate,
                'amount_ex_vat', breakdown_page_inner.amount_ex_vat,
                'amount_vat', breakdown_page_inner.amount_vat,
                'amount_inc_vat', breakdown_page_inner.amount_inc_vat,
                'meta_json', COALESCE(breakdown_page_inner.meta_json, '{}'::jsonb),
                'operation_source_key', breakdown_page_inner.operation_source_key
              ))
              ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC
            ),
            '[]'::jsonb
          ) AS breakdowns_json
        FROM public.pay_batch_item_breakdowns AS breakdown_page_inner
        WHERE breakdown_page_inner.pay_batch_item_id = pay_batch_item_page.id
      ) AS breakdown_display ON true
      LEFT JOIN LATERAL (
        SELECT
          snapshot_page_inner.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_page_inner
        WHERE snapshot_page_inner.pay_batch_id = pay_batch_candidate_page.pay_batch_id
          AND snapshot_page_inner.timesheet_id = pay_batch_item_page.timesheet_id
          AND snapshot_page_inner.candidate_id = pay_batch_candidate_page.candidate_id
          AND (
            snapshot_page_inner.pay_channel IS NOT DISTINCT FROM pay_batch_item_page.pay_channel
            OR snapshot_page_inner.pay_channel IS NULL
            OR pay_batch_item_page.pay_channel IS NULL
          )
        ORDER BY snapshot_page_inner.created_at_utc DESC, snapshot_page_inner.id DESC
        LIMIT 1
      ) AS snapshot_page ON true
      LEFT JOIN public.timesheets AS timesheet_display_page
        ON timesheet_display_page.timesheet_id = pay_batch_item_page.timesheet_id
      CROSS JOIN LATERAL (
        SELECT
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
            pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,week_ending_date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,week_ending_date}',
            snapshot_page.target_snapshot_json->>'week_ending_date',
            CASE WHEN timesheet_display_page.week_ending_date IS NULL THEN NULL ELSE timesheet_display_page.week_ending_date::text END
          )), '') AS week_ending_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
            pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
            pay_batch_item_page.frozen_resolution_result_json->>'client_name',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,client_name}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,client_name}',
            snapshot_page.target_snapshot_json->>'client_name',
            timesheet_display_page.hospital_norm
          )), '') AS client_name,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'role',
            pay_batch_item_page.frozen_source_basis_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json->>'role',
            pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
            pay_batch_item_page.frozen_resolution_payload_json->>'role',
            pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,job_title}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,job_title}',
            snapshot_page.target_snapshot_json->>'role',
            snapshot_page.target_snapshot_json->>'job_title',
            timesheet_display_page.job_title_norm
          )), '') AS role,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,date}',
            snapshot_page.target_snapshot_json->>'date',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
               AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS worked_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_rate',
            pay_batch_item_page.frozen_source_basis_json->>'pay_rate',
            pay_batch_item_page.frozen_source_basis_json->>'rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'pay_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,pay_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,pay_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,pay_rate}'
          )), '') AS source_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_charge_rate',
            pay_batch_item_page.frozen_source_basis_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_charge_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,charge_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_charge_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_charge_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,charge_rate}'
          )), '') AS source_charge_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,additional_code}',
            pay_batch_item_page.frozen_resolution_payload_json->>'additional_code',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,additional_code}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,additional_code}',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS additional_code
      ) AS display_context
      CROSS JOIN LATERAL (
        SELECT
          COALESCE(
            NULLIF(BTRIM(COALESCE(breakdown_display.breakdown_unit_name, '')), ''),
            display_context.additional_code,
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_source_basis_json->>'unit_name', pay_batch_item_page.frozen_source_basis_json->>'unit', '')), ''),
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_snapshot_json->>'unit_name', pay_batch_item_page.frozen_component_snapshot_json->>'unit', '')), ''),
            display_context.role
          ) AS unit_name
      ) AS display_line
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_item_page.id > v_cursor_id)
      ORDER BY pay_batch_item_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_item_id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_paye_state', page_rows.candidate_paye_state,
            'candidate_gross_preview', page_rows.candidate_gross_preview,
            'candidate_net_bank_amount', page_rows.candidate_net_bank_amount,
            'candidate_awaiting_net_amount', page_rows.candidate_awaiting_net_amount,
            'candidate_settlement_status', page_rows.candidate_settlement_status,
            'item_type', page_rows.item_type,
            'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
            'segment_key', page_rows.segment_key,
            'source_ref', page_rows.source_ref,
            'description', page_rows.description,
            'amount_ex_vat', page_rows.amount_ex_vat,
            'amount_vat', page_rows.amount_vat,
            'amount_inc_vat', page_rows.amount_inc_vat,
            'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
            'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
            'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat
          )
          || jsonb_build_object(
            'pay_channel', page_rows.pay_channel,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'bank_reference', page_rows.bank_reference,
            'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
            'repayment_week_start', CASE WHEN page_rows.repayment_week_start IS NULL THEN NULL::text ELSE page_rows.repayment_week_start::text END,
            'is_voided', page_rows.is_voided,
            'is_mismatch', page_rows.is_mismatch,
            'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
            'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
            'frozen_component_key_type', page_rows.frozen_component_key_type,
            'frozen_component_key_value', page_rows.frozen_component_key_value,
            'operation_source_key', page_rows.operation_source_key,
            'created_at', page_rows.created_at,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'week_ending_date', page_rows.week_ending_date,
            'client_name', page_rows.client_name,
            'role', page_rows.role,
            'worked_date', page_rows.worked_date,
            'unit_name', page_rows.unit_name,
            'unit_label', page_rows.unit_label,
            'units', page_rows.units,
            'rate', page_rows.rate,
            'source_rate', page_rows.source_rate,
            'source_charge_rate', page_rows.source_charge_rate,
            'additional_code', page_rows.additional_code,
            'line_kind', page_rows.line_kind,
            'bucket_code', page_rows.bucket_code,
            'breakdown_unit_name', page_rows.breakdown_unit_name,
            'breakdown_amount_ex_vat', page_rows.breakdown_amount_ex_vat,
            'breakdowns', page_rows.breakdowns_json
          )
          || jsonb_build_object(
            'frozen_component_classification', page_rows.frozen_component_classification,
            'frozen_source_basis_json', COALESCE(page_rows.frozen_source_basis_json, '{}'::jsonb),
            'frozen_component_snapshot_json', COALESCE(page_rows.frozen_component_snapshot_json, '{}'::jsonb),
            'frozen_source_pay_method', page_rows.frozen_source_pay_method,
            'frozen_target_pay_method', page_rows.frozen_target_pay_method,
            'frozen_resolution_mode', page_rows.frozen_resolution_mode,
            'frozen_resolution_payload_json', COALESCE(page_rows.frozen_resolution_payload_json, '{}'::jsonb),
            'frozen_resolution_result_json', COALESCE(page_rows.frozen_resolution_result_json, '{}'::jsonb),
            'display_context_json', jsonb_strip_nulls(jsonb_build_object(
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'source_rate', page_rows.source_rate,
              'source_charge_rate', page_rows.source_charge_rate,
              'additional_code', page_rows.additional_code
            ))
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'item_breakdowns' THEN
    WITH page_rows AS (
      SELECT
        breakdown_page.id,
        breakdown_page.pay_batch_item_id,
        item_page.pay_batch_candidate_id,
        candidate_page.candidate_id,
        breakdown_page.line_kind,
        breakdown_page.bucket_code,
        breakdown_page.unit_name,
        breakdown_page.units,
        breakdown_page.rate,
        breakdown_page.amount_ex_vat,
        breakdown_page.amount_vat,
        breakdown_page.amount_inc_vat,
        breakdown_page.meta_json,
        breakdown_page.operation_source_key,
        breakdown_page.created_at_utc
      FROM public.pay_batch_item_breakdowns AS breakdown_page
      JOIN public.pay_batch_items AS item_page
        ON item_page.id = breakdown_page.pay_batch_item_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR breakdown_page.id > v_cursor_id)
      ORDER BY breakdown_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', page_rows.id::text,
          'pay_batch_item_id', page_rows.pay_batch_item_id::text,
          'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
          'candidate_id', page_rows.candidate_id::text,
          'line_kind', page_rows.line_kind,
          'bucket_code', page_rows.bucket_code,
          'unit_name', page_rows.unit_name,
          'units', page_rows.units,
          'rate', page_rows.rate,
          'amount_ex_vat', page_rows.amount_ex_vat,
          'amount_vat', page_rows.amount_vat,
          'amount_inc_vat', page_rows.amount_inc_vat,
          'meta_json', COALESCE(page_rows.meta_json, '{}'::jsonb),
          'operation_source_key', page_rows.operation_source_key,
          'created_at_utc', page_rows.created_at_utc
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section IN ('transfers', 'current_payment_status') THEN
    WITH page_rows AS (
      SELECT
        transfer_page.id,
        transfer_page.pay_batch_id,
        transfer_page.candidate_id,
        transfer_page.umbrella_id,
        transfer_page.pay_channel,
        transfer_page.amount,
        transfer_page.currency,
        transfer_page.status,
        transfer_page.payment_reference,
        transfer_page.payee_name,
        transfer_page.sort_code,
        transfer_page.account_number,
        transfer_page.account_type,
        transfer_page.created_at_utc,
        transfer_page.completed_at_utc,
        transfer_page.failed_reason,
        transfer_page.rail_provider,
        transfer_page.rail_env,
        transfer_page.request_id,
        transfer_page.rail_tx_id,
        transfer_page.rail_state,
        transfer_page.rail_meta_json,
        transfer_page.bank_details_hash_snapshot,
        transfer_page.payee_entity_kind,
        transfer_page.payee_entity_id,
        transfer_page.transfer_group_key,
        transfer_page.grouping_mode_used,
        transfer_page.week_ending_bucket,
        candidate_page.id AS pay_batch_candidate_id,
        candidate_page.candidate_display_name,
        latest_event_page.provider_key AS latest_event_provider_key,
        latest_event_page.provider_transaction_id AS latest_provider_transaction_id,
        latest_event_page.provider_request_id AS latest_provider_request_id,
        latest_event_page.provider_event_key AS latest_provider_event_key,
        latest_event_page.provider_event_id AS latest_provider_event_id,
        latest_event_page.provider_reference AS latest_provider_reference,
        latest_event_page.normalised_state AS latest_event_normalised_state,
        latest_event_page.provider_state AS latest_event_provider_state,
        latest_event_page.provider_failure_reason_code AS latest_provider_failure_reason_code,
        latest_event_page.provider_failure_reason_group AS latest_provider_failure_reason_group,
        latest_event_page.event_time_utc AS latest_event_time_utc,
        latest_event_page.received_at_utc AS latest_event_received_at_utc,
        latest_event_page.correction_disposition AS latest_event_correction_disposition,
        latest_event_page.movement_classification AS latest_event_movement_classification
      FROM public.pay_bank_transfers AS transfer_page
      LEFT JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.pay_batch_id = transfer_page.pay_batch_id
       AND candidate_page.candidate_id = transfer_page.candidate_id
      LEFT JOIN LATERAL (
        SELECT
          event_page.provider_key,
          event_page.provider_transaction_id,
          event_page.provider_request_id,
          event_page.provider_event_key,
          event_page.provider_event_id,
          event_page.provider_reference,
          event_page.normalised_state,
          event_page.provider_state,
          event_page.provider_failure_reason_code,
          event_page.provider_failure_reason_group,
          event_page.event_time_utc,
          event_page.received_at_utc,
          event_page.correction_disposition,
          event_page.movement_classification
        FROM public.pay_bank_transfer_events AS event_page
        WHERE event_page.pay_batch_id = transfer_page.pay_batch_id
          AND event_page.pay_bank_transfer_id = transfer_page.id
        ORDER BY COALESCE(event_page.event_time_utc, event_page.received_at_utc, event_page.created_at_utc) DESC NULLS LAST,
                 event_page.id DESC
        LIMIT 1
      ) AS latest_event_page ON true
      WHERE transfer_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR transfer_page.id > v_cursor_id)
      ORDER BY transfer_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', CASE WHEN page_rows.candidate_id IS NULL THEN NULL::text ELSE page_rows.candidate_id::text END,
            'pay_batch_candidate_id', CASE WHEN page_rows.pay_batch_candidate_id IS NULL THEN NULL::text ELSE page_rows.pay_batch_candidate_id::text END,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_name', page_rows.candidate_display_name,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'pay_channel', page_rows.pay_channel,
            'amount', page_rows.amount,
            'currency', page_rows.currency,
            'status', page_rows.status,
            'payment_reference', page_rows.payment_reference,
            'payee_name', page_rows.payee_name,
            'sort_code', page_rows.sort_code,
            'account_number', page_rows.account_number,
            'account_type', page_rows.account_type
          )
          || jsonb_build_object(
            'created_at_utc', page_rows.created_at_utc,
            'completed_at_utc', page_rows.completed_at_utc,
            'failed_reason', page_rows.failed_reason,
            'rail_provider', page_rows.rail_provider,
            'rail_env', page_rows.rail_env,
            'request_id', page_rows.request_id,
            'rail_tx_id', page_rows.rail_tx_id,
            'rail_state', page_rows.rail_state,
            'rail_meta_json', COALESCE(page_rows.rail_meta_json, '{}'::jsonb),
            'bank_details_hash_snapshot', page_rows.bank_details_hash_snapshot,
            'payee_entity_kind', page_rows.payee_entity_kind,
            'payee_entity_id', CASE WHEN page_rows.payee_entity_id IS NULL THEN NULL::text ELSE page_rows.payee_entity_id::text END,
            'transfer_group_key', page_rows.transfer_group_key,
            'grouping_mode_used', page_rows.grouping_mode_used,
            'week_ending_bucket', CASE WHEN page_rows.week_ending_bucket IS NULL THEN NULL::text ELSE page_rows.week_ending_bucket::text END
          )
          || CASE
            WHEN v_section = 'current_payment_status' THEN jsonb_build_object(
              'payment_lifecycle_state', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state',
              'payment_lifecycle_label', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_label',
              'recommended_action', transfer_diagnostic.diagnostic_json->>'recommended_action',
              'row_cancel_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
              'can_no_money_unwind', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
              'can_recover_overpayment', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
              'provider_outcome_unknown_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
              'provider_webhook_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
              'terminal_no_money_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
              'pending_provider_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
              'status_update_signature', NULLIF(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'status_update_signature', '')), ''),
              'provider_submission_status', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json->>'provider_submission_status',
                page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
                page_rows.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
                page_rows.rail_meta_json->>'provider_submission_status',
                ''
              )), ''),
              'money_movement_cash_state', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}',
                transfer_diagnostic.diagnostic_json->>'cash_state',
                page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}',
                ''
              )), ''),
              'is_final_money_moved', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','BANK_CONFIRMED','MANUAL_CONFIRM')
              ),
              'safe_retry_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'safe_retry_available', page_rows.rail_meta_json #>> '{provider_submit_diagnostic,safe_retry_available}', 'false'))) IN ('true','1','yes','y','on'),
              'payment_status_raw', page_rows.status,
              'payment_status_bucket', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                ) THEN 'SENT_CONFIRMED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                  THEN 'FAILED_RETURNED'
                WHEN UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state', ''))) IN ('PROVIDER_OUTCOME_UNKNOWN','CHECK_REQUIRED','UNKNOWN')
                  OR UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'recommended_action', ''))) = 'CHECK_PROVIDER_STATUS'
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  THEN 'CHECK_REQUIRED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
                  OR NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), '') IS NOT NULL
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', page_rows.rail_meta_json->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
                  THEN 'PENDING_SUBMITTED'
                ELSE 'NOT_SENT'
              END,
              'payment_status_label', public._pay_bank_transfer_status_display_label(
                page_rows.status,
                page_rows.rail_state,
                COALESCE(
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}'), ''),
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'cash_state'), ''),
                  NULLIF(BTRIM(page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}'), ''),
                  CASE
                    WHEN LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on') THEN 'FINAL_PAID'
                    ELSE NULL::text
                  END
                )
              ),
              'payment_terminal_success', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
              ),
              'payment_terminal_failed', (
                UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal_timestamp', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'payment_terminal_at_utc', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'provider', COALESCE(page_rows.rail_provider, page_rows.latest_event_provider_key),
              'rail', page_rows.rail_env,
              'rail_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), ''),
              'provider_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_transaction_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', page_rows.rail_meta_json #>> '{provider_transaction_id}', '')), ''),
              'provider_request_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_request_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', page_rows.request_id, '')), ''),
              'provider_event_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_event_id, page_rows.latest_provider_event_key, '')), ''),
              'provider_reference', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_reference, page_rows.payment_reference, '')), ''),
              'provider_failure_reason_code', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_code, '')), ''),
              'provider_failure_reason_group', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_group, '')), ''),
              'action_review_status', COALESCE(NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'recommended_action'), ''), NULLIF(BTRIM(page_rows.latest_event_correction_disposition), ''))
            )
            ELSE '{}'::jsonb
          END
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows
    LEFT JOIN LATERAL (
      SELECT CASE
        WHEN v_section = 'current_payment_status' THEN public.pay_payment_cancelability_diagnostic(
          p_pay_batch_id,
          jsonb_build_object(
            'scope_type', 'TRANSFER',
            'pay_bank_transfer_ids', jsonb_build_array(page_rows.id::text)
          ),
          p_actor_user_id,
          'CURRENT_PAYMENT_STATUS'
        )
        ELSE '{}'::jsonb
      END AS diagnostic_json
    ) AS transfer_diagnostic ON true;

  ELSIF v_section = 'finance_case_groups' THEN
    WITH group_keys AS (
      SELECT COALESCE(item_page.finance_case_id, item_page.finance_component_id) AS group_id
      FROM public.pay_batch_items AS item_page
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (item_page.finance_case_id IS NOT NULL OR item_page.finance_component_id IS NOT NULL)
      GROUP BY COALESCE(item_page.finance_case_id, item_page.finance_component_id)
    ),
    page_rows AS (
      SELECT
        group_keys.group_id,
        (ARRAY_AGG(item_page.finance_case_id ORDER BY item_page.finance_case_id::text) FILTER (WHERE item_page.finance_case_id IS NOT NULL))[1] AS finance_case_id,
        (ARRAY_AGG(item_page.finance_component_id ORDER BY item_page.finance_component_id::text) FILTER (WHERE item_page.finance_component_id IS NOT NULL))[1] AS finance_component_id,
        COUNT(*)::integer AS item_count,
        ROUND(COALESCE(SUM(COALESCE(item_page.amount_ex_vat, 0)), 0), 2)::numeric AS total_amount_ex_vat,
        COALESCE(jsonb_agg(DISTINCT item_page.item_type) FILTER (WHERE item_page.item_type IS NOT NULL), '[]'::jsonb) AS item_types,
        COALESCE(jsonb_agg(DISTINCT candidate_page.candidate_id::text) FILTER (WHERE candidate_page.candidate_id IS NOT NULL), '[]'::jsonb) AS candidate_ids
      FROM group_keys
      JOIN public.pay_batch_items AS item_page
        ON COALESCE(item_page.finance_case_id, item_page.finance_component_id) = group_keys.group_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR group_keys.group_id > v_cursor_id)
      GROUP BY group_keys.group_id
      ORDER BY group_keys.group_id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(jsonb_build_object(
        'group_id', page_rows.group_id::text,
        'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
        'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
        'item_count', page_rows.item_count,
        'total_amount_ex_vat', page_rows.total_amount_ex_vat,
        'item_types', page_rows.item_types,
        'candidate_ids', page_rows.candidate_ids
      ) ORDER BY page_rows.group_id ASC), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.group_id::text ORDER BY page_rows.group_id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'remittances' THEN
    WITH page_rows AS (
      SELECT
        mail_page.id,
        mail_page.type,
        mail_page."to" AS mail_to,
        mail_page.cc,
        mail_page.bcc,
        mail_page.subject,
        mail_page.status::text AS status,
        mail_page.provider_status,
        mail_page.recipient_kind,
        mail_page.recipient_id,
        mail_page.context_kind,
        mail_page.context_id,
        mail_page.reference,
        mail_page.created_at_utc,
        mail_page.sent_at,
        mail_page.failed_at,
        mail_page.last_error,
        mail_page.deterministic_outbox_key
      FROM public.mail_outbox AS mail_page
      WHERE (
           mail_page.payment_scope_json->>'pay_batch_id' = p_pay_batch_id::text
        OR (LOWER(COALESCE(mail_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND mail_page.context_id = p_pay_batch_id)
        OR mail_page.reference = p_pay_batch_id::text
        OR mail_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR mail_page.id > v_cursor_id)
      ORDER BY mail_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'communications' THEN
    WITH page_rows AS (
      SELECT
        comms_page.id,
        comms_page.channel,
        comms_page.status,
        comms_page.to_address,
        comms_page.provider_key,
        comms_page.provider_message_id,
        comms_page.recipient_kind,
        comms_page.recipient_id,
        comms_page.context_kind,
        comms_page.context_id,
        comms_page.created_at_utc,
        comms_page.sent_at,
        comms_page.delivered_at,
        comms_page.read_at,
        comms_page.failed_at,
        comms_page.last_error,
        comms_page.deterministic_outbox_key
      FROM public.comms_outbox AS comms_page
      WHERE (
           (LOWER(COALESCE(comms_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND comms_page.context_id = p_pay_batch_id)
        OR comms_page.provider_payload_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.provider_response_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR comms_page.id > v_cursor_id)
      ORDER BY comms_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'auth_history' THEN
    WITH page_rows AS (
      SELECT
        auth_page.id,
        auth_page.pay_batch_id,
        auth_page.requested_by_user_id,
        auth_page.required_quantity,
        auth_page.schedule_kind,
        auth_page.scheduled_at_utc,
        auth_page.funding_account_ref,
        auth_page.state,
        auth_page.golden_key_used,
        auth_page.golden_key_user_id,
        auth_page.created_at_utc,
        auth_page.finalised_at_utc,
        auth_page.finalised_by_user_id,
        auth_page.execution_intent_json
      FROM public.pay_batch_auth_requests AS auth_page
      WHERE auth_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR auth_page.id > v_cursor_id)
      ORDER BY auth_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'events' THEN
    WITH page_rows AS (
      SELECT
        event_page.id,
        event_page.pay_batch_id,
        event_page.pay_bank_transfer_id,
        event_page.candidate_id,
        event_page.umbrella_id,
        event_page.provider_key,
        event_page.provider_event_id,
        event_page.provider_reference,
        event_page.provider_state,
        event_page.normalised_state,
        event_page.event_source,
        event_page.event_time_utc,
        event_page.received_at_utc,
        event_page.amount,
        event_page.currency,
        event_page.mapping_status,
        event_page.movement_classification,
        event_page.correction_disposition,
        event_page.mapping_method,
        event_page.created_at_utc
      FROM public.pay_bank_transfer_events AS event_page
      WHERE event_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR event_page.id > v_cursor_id)
      ORDER BY event_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;
  END IF;

  v_raw_count := COALESCE(v_raw_count, 0);

  IF v_raw_count > v_limit THEN
    v_next_cursor := jsonb_build_object(
      'last_id',
      COALESCE(
        v_items -> (v_limit - 1) ->> 'id',
        v_items -> (v_limit - 1) ->> 'group_id',
        v_last_cursor_text
      )
    );

    SELECT COALESCE(jsonb_agg(trimmed_items.value ORDER BY trimmed_items.ordinality), '[]'::jsonb)
    INTO v_items
    FROM jsonb_array_elements(COALESCE(v_items, '[]'::jsonb)) WITH ORDINALITY AS trimmed_items(value, ordinality)
    WHERE trimmed_items.ordinality <= v_limit;

    v_returned_count := v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
    v_returned_count := v_raw_count;
  END IF;

  v_section_page_signature := 'pay_batch_section_page:v2:' || MD5(
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'section', v_section,
      'purpose', v_purpose,
      'items', COALESCE(v_items, '[]'::jsonb),
      'next_cursor', v_next_cursor,
      'live_signal_version', COALESCE(v_live_signal_version, 0),
      'payment_status_version', COALESCE(v_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_correction_progress_version, 0),
      'overview_version', COALESCE(v_overview_version, 0),
      'candidate_scope', CASE
        WHEN v_candidate_scope_enabled THEN jsonb_build_object(
          'scope_type', 'PAY_BATCH_CANDIDATE',
          'pay_batch_candidate_id', v_candidate_scope_pay_batch_candidate_id::text,
          'candidate_id', v_candidate_scope_candidate_id::text
        )
        ELSE NULL::jsonb
      END
    )::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'section', v_section,
    'purpose', v_purpose,
    'items', COALESCE(v_items, '[]'::jsonb),
    'next_cursor', v_next_cursor,
    'returned_count', COALESCE(v_returned_count, 0),
    'known_total_count', v_known_total_count,
    'pay_batch_id', p_pay_batch_id::text,
    'server_time_utc', v_server_time_utc::text,
    'section_page_signature', v_section_page_signature,
    'live_signal_version', COALESCE(v_live_signal_version, 0),
    'payment_status_version', COALESCE(v_payment_status_version, 0),
    'correction_progress_version', COALESCE(v_correction_progress_version, 0),
    'alert_version', COALESCE(v_alert_version, 0),
    'overview_version', COALESCE(v_overview_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'known_live_signal_version', v_known_live_signal_version,
    'changed_since_version', COALESCE(v_changed_since_version, false),
    'batch_status', v_batch.status,
    'execution_commit_state', v_batch.execution_commit_state,
    'freshness', v_freshness_summary,
    'limit', v_limit,
    'scope_type', CASE WHEN v_candidate_scope_enabled THEN 'PAY_BATCH_CANDIDATE' ELSE NULL::text END,
    'pay_batch_candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_pay_batch_candidate_id::text ELSE NULL::text END,
    'candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_candidate_id::text ELSE NULL::text END
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_reconcile_successful_source_build(p_session_id uuid, p_candidate_id uuid, p_source_build_run_id uuid, p_source_change_seq bigint, p_session_version bigint DEFAULT NULL::bigint, p_success_job_id uuid DEFAULT NULL::uuid, p_refresh_scope_kind text DEFAULT NULL::text, p_targeted_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_linked_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_recompute_session_progress boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_session_version bigint := NULL::bigint;
  v_refresh_scope_kind text := NULL::text;
  v_current_source_row_count integer := 0;
  v_current_source_identity_count integer := 0;
  v_source_rows_superseded integer := 0;
  v_source_build_jobs_superseded integer := 0;
  v_scope_rows_repaired integer := 0;
  v_progress_json jsonb := '{}'::jsonb;
  v_counter_reconciled boolean := false;
  v_progress_state text := NULL::text;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_session_progress_lock_acquired boolean := false;
  v_reconciliation_deferred boolean := false;
  v_reconciliation_deferred_reason text := NULL::text;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  IF p_source_build_run_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED')::text;
  END IF;

  IF p_source_change_seq IS NULL OR p_source_change_seq < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED')::text;
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SOURCE_LINES_TABLE_MISSING',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  v_session_version := COALESCE(p_session_version, v_session_row.version);
  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(p_refresh_scope_kind, ''))), '');

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets ON COMMIT DROP AS
    SELECT DISTINCT scope_ids.timesheet_id
    FROM (
      SELECT NULLIF(BTRIM(target_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS target_values(value)
      WHERE NULLIF(BTRIM(target_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION

      SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_linked_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_linked_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS scope_ids
    WHERE scope_ids.timesheet_id IS NOT NULL;

  SELECT COUNT(*)::integer,
         COUNT(DISTINCT jsonb_build_object(
           'timesheet_id', COALESCE(current_source.timesheet_id::text, '00000000-0000-0000-0000-000000000000'),
           'line_key', current_source.line_key,
           'parent_line_key', COALESCE(current_source.parent_line_key, ''),
           'split_suffix', COALESCE(current_source.split_suffix, ''),
           'section', COALESCE(current_source.section, '')
         ))::integer
  INTO v_current_source_row_count,
       v_current_source_identity_count
  FROM public.banking_pay_workbench_candidate_source_lines AS current_source
  WHERE current_source.session_id = p_session_id
    AND current_source.candidate_id = p_candidate_id
    AND current_source.session_version = v_session_version
    AND current_source.source_build_run_id = p_source_build_run_id
    AND current_source.source_change_seq = p_source_change_seq
    AND current_source.status = 'CURRENT';

  IF COALESCE(v_current_source_row_count, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SUCCESSFUL_SOURCE_BUILD_HAS_NO_CURRENT_SOURCE_ROWS',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'source_rows_superseded', 0,
      'source_build_jobs_superseded', 0,
      'scope_rows_repaired', 0,
      'deferred', false,
      'progress_recomputed', false,
      'counter_reconciled', false,
      'retry_safe', true
    );
  END IF;

  WITH current_identity AS (
    SELECT DISTINCT
      current_source.timesheet_id,
      current_source.line_key,
      current_source.parent_line_key,
      current_source.split_suffix,
      current_source.section
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
  ), source_rows_to_supersede AS (
    SELECT older_source.id,
           older_source.status AS previous_status
    FROM public.banking_pay_workbench_candidate_source_lines AS older_source
    JOIN current_identity AS current_source
      ON COALESCE(older_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
           = COALESCE(current_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND older_source.line_key = current_source.line_key
     AND COALESCE(older_source.parent_line_key, '') = COALESCE(current_source.parent_line_key, '')
     AND COALESCE(older_source.split_suffix, '') = COALESCE(current_source.split_suffix, '')
     AND COALESCE(older_source.section, '') = COALESCE(current_source.section, '')
    WHERE older_source.session_id = p_session_id
      AND older_source.candidate_id = p_candidate_id
      AND older_source.session_version = v_session_version
      AND older_source.source_change_seq < p_source_change_seq
      AND UPPER(BTRIM(COALESCE(older_source.status, ''))) IN ('CURRENT', 'DIRTY', 'ERROR')
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR older_source.timesheet_id IS NULL
        OR older_source.timesheet_id IN (
          SELECT scoped_timesheets.timesheet_id
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
        )
        OR NOT EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS any_scoped_timesheets
        )
      )
  )
  UPDATE public.banking_pay_workbench_candidate_source_lines AS update_source
  SET status = 'SUPERSEDED',
      source_row_json = jsonb_strip_nulls(
        COALESCE(update_source.source_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'previous_status', source_rows_to_supersede.previous_status,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_rows_to_supersede
  WHERE update_source.id = source_rows_to_supersede.id;

  GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;

  WITH successful_scope_timesheets AS (
    SELECT DISTINCT current_source.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
      AND current_source.timesheet_id IS NOT NULL

    UNION

    SELECT scoped_timesheets.timesheet_id
    FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
  ), source_build_jobs_to_supersede AS (
    SELECT
      job_row.id,
      job_seq.job_source_change_seq,
      job_scope_kind.job_refresh_scope_kind,
      job_scope.scoped_timesheet_count,
      job_scope.success_scope_overlap_count
    FROM public.banking_pay_workbench_jobs AS job_row
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN COALESCE(job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_seq')::bigint
        WHEN COALESCE(job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_sequence')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_sequence}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_sequence}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{result_json,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{completion_json,result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{completion_json,result_json,source_change_seq}')::bigint
        ELSE NULL::bigint
      END AS job_source_change_seq
    ) AS job_seq
    CROSS JOIN LATERAL (
      SELECT NULLIF(UPPER(BTRIM(COALESCE(
        job_row.payload_json->>'refresh_scope_kind',
        job_row.payload_json#>>'{source_build,refresh_scope_kind}',
        job_row.payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
        job_row.payload_json#>>'{result_json,refresh_scope_kind}',
        job_row.payload_json#>>'{completion_json,result_json,refresh_scope_kind}',
        ''
      ))), '') AS job_refresh_scope_kind
    ) AS job_scope_kind
    CROSS JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS scoped_timesheet_count,
        COUNT(*) FILTER (
          WHERE job_scope_timesheet_ids.timesheet_id IN (
            SELECT successful_scope_timesheets.timesheet_id
            FROM successful_scope_timesheets
          )
        )::integer AS success_scope_overlap_count
      FROM (
        SELECT DISTINCT parsed_job_scope_values.timesheet_id_text::uuid AS timesheet_id
        FROM (
          SELECT NULLIF(BTRIM(target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS target_values(value)

          UNION

          SELECT NULLIF(BTRIM(target_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS target_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_target_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids') = 'array' THEN job_row.payload_json->'linked_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'linked_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS linked_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,linked_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(COALESCE(
            job_row.payload_json->>'timesheet_id',
            job_row.payload_json->>'real_business_timesheet_id',
            job_row.payload_json#>>'{trigger,timesheet_id}',
            job_row.payload_json#>>'{source_build,timesheet_id}',
            job_row.payload_json#>>'{source_build,real_business_timesheet_id}',
            job_row.payload_json#>>'{result_json,timesheet_id}',
            ''
          )), '') AS timesheet_id_text
        ) AS parsed_job_scope_values
        WHERE parsed_job_scope_values.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS job_scope_timesheet_ids
    ) AS job_scope
    WHERE job_row.session_id = p_session_id
      AND job_row.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(job_row.status, ''))) IN ('FAILED', 'DEAD')
      AND CASE
            WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN (
              'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
              'CANDIDATE_SOURCE_BUILD',
              'CANDIDATE_SOURCE_BUILD_CHUNK',
              'SOURCE_BUILD',
              'SOURCE_BUILD_PAGE'
            ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            ELSE UPPER(BTRIM(COALESCE(job_row.job_type, '')))
          END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND NOT (
        COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_by_newer_session_version_at_utc'
        OR COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_at_utc'
        OR UPPER(BTRIM(COALESCE(job_row.last_error_json->>'code', ''))) = 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION'
      )
      AND (
        COALESCE(job_row.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
        OR (job_row.payload_json->>'session_version')::bigint = v_session_version
      )
      AND job_seq.job_source_change_seq < p_source_change_seq
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR COALESCE(job_scope.success_scope_overlap_count, 0) > 0
        OR (
          COALESCE(job_scope.scoped_timesheet_count, 0) = 0
          AND COALESCE(job_scope_kind.job_refresh_scope_kind, '') IN ('', 'TARGETED_TIMESHEETS')
        )
      )
  )
  UPDATE public.banking_pay_workbench_jobs AS update_job
  SET payload_json = jsonb_strip_nulls(
        COALESCE(update_job.payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'superseded_refresh_scope_kind', v_refresh_scope_kind,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_build_jobs_to_supersede
  WHERE update_job.id = source_build_jobs_to_supersede.id;

  GET DIAGNOSTICS v_source_build_jobs_superseded = ROW_COUNT;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
          WHERE line_work_pending.session_id = p_session_id
            AND line_work_pending.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) IN ('PENDING', 'READY', 'RUNNING', 'PROCESSING', 'QUEUED')
        ) THEN scope_update.status
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
          WHERE line_work_ready.session_id = p_session_id
            AND line_work_ready.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) IN ('MATERIALISED', 'MATERIALIZED')
        ) THEN 'MATERIALISED'
        ELSE 'SOURCE_READY'
      END,
      dirty = false,
      error_json = CASE
        WHEN scope_update.error_json IS NULL
          OR scope_update.error_json = '{}'::jsonb
          OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
            'SOURCE_BUILD_ERROR',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            '42P01'
          )
          THEN NULL::jsonb
        ELSE scope_update.error_json
      END,
      pending_job_id = CASE
        WHEN scope_update.pending_job_id = p_success_job_id THEN NULL::uuid
        WHEN scope_update.pending_job_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_jobs AS active_pending_job
            WHERE active_pending_job.id = scope_update.pending_job_id
              AND UPPER(BTRIM(COALESCE(active_pending_job.status, ''))) IN ('QUEUED', 'RUNNING')
          ) THEN NULL::uuid
        ELSE scope_update.pending_job_id
      END,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id
    AND (
      COALESCE(scope_update.dirty, false) IS TRUE
      OR UPPER(BTRIM(COALESCE(scope_update.status, ''))) IN ('SOURCE_BUILD_ERROR', 'ERROR', 'FAILED')
      OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
        'SOURCE_BUILD_ERROR',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        '42P01'
      )
      OR scope_update.pending_job_id = p_success_job_id
    )
    AND EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS current_source_exists
      WHERE current_source_exists.session_id = p_session_id
        AND current_source_exists.candidate_id = p_candidate_id
        AND current_source_exists.session_version = v_session_version
        AND current_source_exists.source_build_run_id = p_source_build_run_id
        AND current_source_exists.source_change_seq = p_source_change_seq
        AND current_source_exists.status = 'CURRENT'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS unresolved_source_row
      WHERE unresolved_source_row.session_id = p_session_id
        AND unresolved_source_row.candidate_id = p_candidate_id
        AND unresolved_source_row.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(unresolved_source_row.status, ''))) IN ('DIRTY', 'ERROR')
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_jobs AS active_source_job
      WHERE active_source_job.session_id = p_session_id
        AND active_source_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(active_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
        AND CASE
              WHEN UPPER(BTRIM(COALESCE(active_source_job.job_type, ''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE'
              ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              ELSE UPPER(BTRIM(COALESCE(active_source_job.job_type, '')))
            END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND (
          COALESCE(active_source_job.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
          OR (active_source_job.payload_json->>'session_version')::bigint = v_session_version
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS line_work_error
      WHERE line_work_error.session_id = p_session_id
        AND line_work_error.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(line_work_error.status, ''))) IN ('ERROR', 'FAILED')
    );

  GET DIAGNOSTICS v_scope_rows_repaired = ROW_COUNT;

  IF COALESCE(p_recompute_session_progress, true) THEN
    BEGIN
      PERFORM 1
      FROM public.banking_pay_workbench_sessions AS session_progress_lock
      WHERE session_progress_lock.id = p_session_id
        AND UPPER(BTRIM(COALESCE(session_progress_lock.status, ''))) = 'OPEN'
        AND session_progress_lock.discarded_at_utc IS NULL
        AND COALESCE(session_progress_lock.version, 1) = COALESCE(v_session_version, 1)
        AND session_progress_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_progress_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      v_session_progress_lock_acquired := FOUND;
    EXCEPTION
      WHEN lock_not_available THEN
        v_session_progress_lock_acquired := false;
        v_reconciliation_deferred := true;
        v_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_session_progress_lock_acquired THEN
      v_progress_json := public.pay_workbench_session_get_progress_light(p_session_id);

      IF COALESCE((v_progress_json->>'ok')::boolean, false) THEN
      v_progress_state := UPPER(BTRIM(COALESCE(v_progress_json->>'progress_state', v_progress_json->>'phase', '')));
      IF v_progress_state = '' THEN
        v_progress_state := v_session_row.progress_state;
      END IF;

      v_section_counts_json := CASE
        WHEN jsonb_typeof(v_progress_json->'section_counts_json') = 'object'
          THEN v_progress_json->'section_counts_json'
        ELSE '{}'::jsonb
      END;
      v_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(v_progress_json->'candidate_sample_rows_json') = 'array'
          THEN v_progress_json->'candidate_sample_rows_json'
        ELSE '[]'::jsonb
      END;

      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_total_count = CASE WHEN COALESCE(v_progress_json->>'scope_total_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_total_count')::integer ELSE COALESCE(session_update.scope_total_count, 0) END,
          scope_seeded_count = CASE WHEN COALESCE(v_progress_json->>'scope_seeded_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_seeded_count')::integer ELSE COALESCE(session_update.scope_seeded_count, 0) END,
          scope_ready_count = CASE WHEN COALESCE(v_progress_json->>'scope_ready_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_ready_count')::integer ELSE COALESCE(session_update.scope_ready_count, 0) END,
          scope_pending_count = CASE WHEN COALESCE(v_progress_json->>'scope_pending_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_pending_count')::integer ELSE COALESCE(session_update.scope_pending_count, 0) END,
          scope_failed_count = CASE WHEN COALESCE(v_progress_json->>'scope_failed_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_failed_count')::integer ELSE COALESCE(session_update.scope_failed_count, 0) END,
          line_units_total = CASE WHEN COALESCE(v_progress_json->>'line_units_total', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_total')::integer ELSE COALESCE(session_update.line_units_total, 0) END,
          line_units_pending = CASE WHEN COALESCE(v_progress_json->>'line_units_pending', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_pending')::integer ELSE COALESCE(session_update.line_units_pending, 0) END,
          line_units_ready = CASE WHEN COALESCE(v_progress_json->>'line_units_ready', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_ready')::integer ELSE COALESCE(session_update.line_units_ready, 0) END,
          line_units_failed = CASE WHEN COALESCE(v_progress_json->>'line_units_failed', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_failed')::integer ELSE COALESCE(session_update.line_units_failed, 0) END,
          preview_row_count = CASE WHEN COALESCE(v_progress_json->>'preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'preview_row_count')::integer ELSE COALESCE(session_update.preview_row_count, 0) END,
          selected_row_count = CASE WHEN COALESCE(v_progress_json->>'selected_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'selected_row_count')::integer ELSE COALESCE(session_update.selected_row_count, 0) END,
          section_counts_json = v_section_counts_json,
          candidate_sample_rows_json = v_candidate_sample_rows_json,
          progress_state = COALESCE(NULLIF(v_progress_state, ''), session_update.progress_state),
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || COALESCE(v_progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_source_build_reconciliation', jsonb_build_object(
                'applied_at_utc', v_now::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', p_source_build_run_id::text,
                'source_change_seq', p_source_change_seq,
                'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
                'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
                'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0)
              ),
              'counter_reconciled', true,
              'counter_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = p_session_id
      RETURNING session_update.*
      INTO v_session_row;

        v_counter_reconciled := true;
      END IF;
    ELSIF v_reconciliation_deferred IS NOT TRUE THEN
      v_reconciliation_deferred := true;
      v_reconciliation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
    END IF;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_source_build_reconciliation',
    p_session_id::text,
    'RECONCILE_SUCCESSFUL_SOURCE_BUILD',
    NULL::jsonb,
    jsonb_build_object(
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'current_source_row_count', COALESCE(v_current_source_row_count, 0),
      'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
      'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
      'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
      'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
      'deferred', COALESCE(v_reconciliation_deferred, false),
      'deferred_reason', v_reconciliation_deferred_reason,
      'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
      'counter_reconciled', COALESCE(v_counter_reconciled, false),
      'retry_safe', COALESCE(v_reconciliation_deferred, false),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    'NEWER_SOURCE_BUILD_SUCCEEDED',
    v_session_row.actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'skipped', false,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_build_run_id', p_source_build_run_id::text,
    'source_change_seq', p_source_change_seq,
    'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
    'refresh_scope_kind', v_refresh_scope_kind,
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
    'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
    'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
    'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
    'deferred', COALESCE(v_reconciliation_deferred, false),
    'reason', v_reconciliation_deferred_reason,
    'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
    'counter_reconciled', COALESCE(v_counter_reconciled, false),
    'progress_phase', CASE WHEN v_progress_json = '{}'::jsonb THEN NULL ELSE v_progress_json->>'phase' END,
    'progress_blocker_codes', CASE WHEN v_progress_json = '{}'::jsonb THEN '[]'::jsonb ELSE COALESCE(v_progress_json->'blocker_codes', '[]'::jsonb) END,
    'retry_safe', COALESCE(v_reconciliation_deferred, false),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_bank_csv_export_summary_get(
    p_pay_batch_id uuid,
    p_scope text DEFAULT 'ALL'::text,
    p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
    v_batch_row public.pay_batches%ROWTYPE;
    v_batch_status_upper text := NULL;
    v_execution_commit_state text := 'NOT_SUBMITTED';
    v_execution_commit_ref text := NULL;
    v_execution_committed_at_utc timestamptz := NULL;
    v_pre_execution_export boolean := false;

    v_row_count integer := 0;
    v_total_amount numeric := 0;
    v_current_transfer_hash text := NULL;
    v_current_transfer_hash_basis text := NULL;

    v_pending_row_count integer := 0;
    v_pending_total_amount numeric := 0;
    v_pending_transfer_hash text := NULL;

    v_stable_row_count integer := 0;
    v_stable_total_amount numeric := 0;
    v_stable_transfer_hash text := NULL;

    v_blocked_row_count integer := 0;
    v_all_transfer_count integer := 0;
    v_pay_channels_included jsonb := '[]'::jsonb;
    v_status_counts jsonb := '{}'::jsonb;
    v_provider_counts jsonb := '{}'::jsonb;
    v_rail_env_counts jsonb := '{}'::jsonb;
    v_exportable_status_filter text := NULL;
    v_bank_csv_export_hash text := NULL;
BEGIN
    IF p_pay_batch_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_ID_REQUIRED',
            'message', 'pay_bank_csv_export_summary_get: pay_batch_id is required'
        )::text;
    END IF;

    IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'INVALID_SCOPE',
            'message', 'pay_bank_csv_export_summary_get: scope must be ALL, PAYE, or UMBRELLA',
            'scope', p_scope
        )::text;
    END IF;

    IF p_actor_user_id IS NOT NULL THEN
        PERFORM 1
        FROM public.tms_users AS actor_user
        WHERE actor_user.id = p_actor_user_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
                'code', 'ACTOR_USER_NOT_FOUND',
                'message', 'pay_bank_csv_export_summary_get: actor user was not found',
                'actor_user_id', p_actor_user_id::text,
                'pay_batch_id', p_pay_batch_id::text
            )::text;
        END IF;
    END IF;

    SELECT pay_batch.*
    INTO v_batch_row
    FROM public.pay_batches AS pay_batch
    WHERE pay_batch.id = p_pay_batch_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'pay_bank_csv_export_summary_get: pay batch was not found',
            'pay_batch_id', p_pay_batch_id::text
        )::text;
    END IF;

    v_batch_status_upper := upper(btrim(coalesce(v_batch_row.status, '')));
    v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));

    IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
        v_execution_commit_state := 'NOT_SUBMITTED';
    END IF;

    v_execution_commit_ref := nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '');
    v_execution_committed_at_utc := v_batch_row.execution_committed_at_utc;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch_row.bank_csv_export_json->>'transfer_hash', '')), '');

    v_pre_execution_export := (
        v_batch_row.cancelled_at_utc IS NULL
        AND v_batch_status_upper NOT IN ('CANCELLED', 'CANCELED')
        AND v_execution_commit_state = 'NOT_SUBMITTED'
        AND v_execution_commit_ref IS NULL
        AND v_execution_committed_at_utc IS NULL
    );

    SELECT
        count(*)::integer,
        round(coalesce(sum(CASE WHEN upper(coalesce(pending_transfer.status, '')) = 'PENDING' THEN pending_transfer.amount ELSE 0 END), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', pending_transfer.id,
                'candidate_id', pending_transfer.candidate_id,
                'umbrella_id', pending_transfer.umbrella_id,
                'pay_channel', pending_transfer.pay_channel,
                'amount', pending_transfer.amount,
                'currency', pending_transfer.currency,
                'payment_reference', pending_transfer.payment_reference,
                'payee_name', pending_transfer.payee_name,
                'sort_code_digits', pending_transfer.sort_code_digits,
                'account_number_digits', pending_transfer.account_number_digits,
                'account_type', pending_transfer.account_type,
                'bank_details_hash_snapshot', pending_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', pending_transfer.payee_entity_kind,
                'payee_entity_id', pending_transfer.payee_entity_id,
                'transfer_group_key', pending_transfer.transfer_group_key
            )
            ORDER BY pending_transfer.id
        )::text, '[]'))
    INTO
        v_pending_row_count,
        v_pending_total_amount,
        v_pending_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key,
            transfer_row.status AS status
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) = 'PENDING'
        ORDER BY transfer_row.id
    ) AS pending_transfer;

    SELECT
        count(*)::integer,
        round(coalesce(sum(stable_transfer.amount), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', stable_transfer.id,
                'candidate_id', stable_transfer.candidate_id,
                'umbrella_id', stable_transfer.umbrella_id,
                'pay_channel', stable_transfer.pay_channel,
                'amount', stable_transfer.amount,
                'currency', stable_transfer.currency,
                'payment_reference', stable_transfer.payment_reference,
                'payee_name', stable_transfer.payee_name,
                'sort_code_digits', stable_transfer.sort_code_digits,
                'account_number_digits', stable_transfer.account_number_digits,
                'account_type', stable_transfer.account_type,
                'bank_details_hash_snapshot', stable_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', stable_transfer.payee_entity_kind,
                'payee_entity_id', stable_transfer.payee_entity_id,
                'transfer_group_key', stable_transfer.transfer_group_key
            )
            ORDER BY stable_transfer.id
        )::text, '[]'))
    INTO
        v_stable_row_count,
        v_stable_total_amount,
        v_stable_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED'
        ORDER BY transfer_row.id
    ) AS stable_transfer;

    IF v_pre_execution_export THEN
        v_row_count := coalesce(v_pending_row_count, 0);
        v_total_amount := coalesce(v_pending_total_amount, 0);
        v_current_transfer_hash := v_pending_transfer_hash;
        v_current_transfer_hash_basis := 'PENDING_TRANSFER_HASH';
        v_exportable_status_filter := 'PENDING';
    ELSE
        v_row_count := coalesce(v_stable_row_count, 0);
        v_total_amount := coalesce(v_stable_total_amount, 0);
        v_current_transfer_hash := v_stable_transfer_hash;
        v_current_transfer_hash_basis := 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH';
        v_exportable_status_filter := 'ALL_NON_BLOCKED';
    END IF;

    SELECT count(*)::integer
    INTO v_all_transfer_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope);

    SELECT count(*)::integer
    INTO v_blocked_row_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
      AND upper(coalesce(transfer_row.status, '')) = 'BLOCKED';

    SELECT coalesce(jsonb_agg(to_jsonb(pay_channel_values.pay_channel) ORDER BY pay_channel_values.pay_channel), '[]'::jsonb)
    INTO v_pay_channels_included
    FROM (
        SELECT DISTINCT upper(coalesce(transfer_row.pay_channel, '')) AS pay_channel
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
    ) AS pay_channel_values
    WHERE pay_channel_values.pay_channel <> '';

    SELECT coalesce(jsonb_object_agg(status_counts.status_key, status_counts.status_count ORDER BY status_counts.status_key), '{}'::jsonb)
    INTO v_status_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.status, '')) AS status_key,
            count(*)::integer AS status_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
        GROUP BY upper(coalesce(transfer_row.status, ''))
    ) AS status_counts
    WHERE status_counts.status_key <> '';

    SELECT coalesce(jsonb_object_agg(provider_counts.provider_key, provider_counts.provider_count ORDER BY provider_counts.provider_key), '{}'::jsonb)
    INTO v_provider_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_provider, '')) AS provider_key,
            count(*)::integer AS provider_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_provider, ''))
    ) AS provider_counts
    WHERE provider_counts.provider_key <> '';

    SELECT coalesce(jsonb_object_agg(env_counts.env_key, env_counts.env_count ORDER BY env_counts.env_key), '{}'::jsonb)
    INTO v_rail_env_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_env, '')) AS env_key,
            count(*)::integer AS env_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_env, ''))
    ) AS env_counts
    WHERE env_counts.env_key <> '';

    RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'pay_channel_scope', v_scope,
        'pre_execution_export', v_pre_execution_export,
        'exportable_status_filter', v_exportable_status_filter,
        'row_count', coalesce(v_row_count, 0),
        'total_amount', coalesce(v_total_amount, 0),
        'transfer_hash', v_current_transfer_hash,
        'current_transfer_hash', v_current_transfer_hash,
        'current_transfer_hash_basis', v_current_transfer_hash_basis,
        'pending_transfer_hash', v_pending_transfer_hash,
        'stable_transfer_hash', v_stable_transfer_hash,
        'provider_snapshot', nullif(btrim(coalesce(v_batch_row.rail_provider_snapshot, '')), ''),
        'rail_env_snapshot', nullif(btrim(coalesce(v_batch_row.rail_env_snapshot, '')), ''),
        'freshness_validation_status', nullif(upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))), ''),
        'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), ''),
        'freshness_scope_hash', nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'bank_csv_export_hash', v_bank_csv_export_hash,
        'csv_export_matches_current_transfers', CASE WHEN v_bank_csv_export_hash IS NULL OR v_current_transfer_hash IS NULL THEN NULL ELSE v_bank_csv_export_hash = v_current_transfer_hash END,
        'pending_row_count', coalesce(v_pending_row_count, 0),
        'pending_total_amount', coalesce(v_pending_total_amount, 0),
        'stable_row_count', coalesce(v_stable_row_count, 0),
        'stable_total_amount', coalesce(v_stable_total_amount, 0),
        'blocked_row_count', coalesce(v_blocked_row_count, 0),
        'all_transfer_count', coalesce(v_all_transfer_count, 0),
        'pay_channels_included', coalesce(v_pay_channels_included, '[]'::jsonb),
        'status_counts', coalesce(v_status_counts, '{}'::jsonb),
        'provider_counts', coalesce(v_provider_counts, '{}'::jsonb),
        'rail_env_counts', coalesce(v_rail_env_counts, '{}'::jsonb),
        'summary_source', 'pay_bank_transfers',
        'policy_x_authority', 'FROZEN_MATERIALISED_TRANSFER_ROWS',
        'generated_at_utc', now()::text
    ));
END;
$function$;





DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);

DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);

DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);
CREATE OR REPLACE FUNCTION public.pay_bank_transfer_execution_classify(p_pay_batch_id uuid, p_pay_channel_scope text DEFAULT 'ALL'::text, p_operation_id uuid DEFAULT NULL::uuid, p_include_unscoped_transfers boolean DEFAULT true, p_action_context text DEFAULT NULL::text)
 RETURNS TABLE(pay_bank_transfer_id uuid, pay_batch_id uuid, pay_channel text, transfer_group_key text, scope_id uuid, scope_operation_id uuid, scope_status text, scope_request_id text, status_upper text, rail_state_upper text, amount numeric, currency text, has_route_ready boolean, has_local_prepare_identity boolean, has_provider_submission_evidence boolean, has_provider_event_evidence boolean, has_provider_attempt_without_external_id boolean, has_operation_submit_attempt boolean, has_ambiguous_external_evidence boolean, is_failed_or_blocked boolean, is_terminal_or_completed boolean, evidence_classification text, is_authorisation_ready boolean, is_unattempted_submit_eligible boolean, is_safe_local_cleanup boolean, is_canonical_pending_status boolean, has_auth_prepared_scope boolean, has_different_operation_scope boolean, has_stale_auth_request_evidence boolean, auth_request_id uuid, auth_request_state text, auth_request_operation_id uuid, has_same_operation_active_auth_request boolean, has_other_operation_active_auth_request boolean, has_cancellable_local_auth_request boolean, has_non_cancellable_auth_request boolean, has_authorised_auth_without_provider_submission boolean, has_auth_request_provider_risk boolean, auth_request_unsafe_reason text, unsafe_reason text, has_same_operation_authorised_auth_request boolean, has_pending_authorisation_auth_request boolean, is_provider_submit_ready boolean, provider_submit_unsafe_reason text, has_provider_submit_blocker boolean, provider_failure_reason_code text, provider_failure_reason_group text, provider_failure_reason_label text, is_success_only boolean, should_touch_payment_status boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := 'ALL';
  v_action_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_action_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;


  IF v_action_context IS NULL THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_REQUIRED',
              'message', 'pay_bank_transfer_execution_classify requires an explicit action/diagnostic context.'
            )::text;
  END IF;

  IF v_action_context IN (
    'PAY_BATCHES_LIST',
    'BATCH_LIST',
    'LIST',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'OPERATION_GET',
    'OPERATION_PROGRESS',
    'PROGRESS_POLLING',
    'WORKER_PROOF',
    'OPERATION_WORKER_PROOF',
    'EXECUTION_WORKER_PROOF',
    'EXECUTION_HOT_PATH',
    'PAY_EXECUTE_BANK_HOT_PATH'
  ) THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_ALLOWED',
              'context', v_action_context,
              'message', 'Live transfer execution classification is blocked from list, bootstrap, Overview, operation GET/progress, and worker proof paths. Execution must use persisted operation proofs and counters.'
            )::text;
  END IF;

  IF v_action_context NOT IN (
    'CURRENT_PAYMENT_STATUS',
    'CURRENT_PAYMENT_STATUS_TAB',
    'PAYMENT_STATUS_TAB',
    'PAYMENT_ISSUES_TAB',
    'PAYMENT_ISSUE_REVIEW',
    'CANCELLATION_ACTION',
    'CANCEL_PAYMENT_ACTION',
    'CORRECTION_REVIEW',
    'CORRECTION_ACTION',
    'PROVIDER_DIAGNOSTIC_TAB',
    'PROVIDER_DIAGNOSTIC_ACTION',
    'AUTHORISATION_ACTION',
    'AUTHORIZATION_ACTION',
    'PREPARE_ACTION',
    'SCHEDULE_ACTION',
    'USER_TRIGGERED_DIAGNOSTIC',
    'EXPLICIT_DIAGNOSTIC'
  ) THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFER_EXECUTION_CLASSIFY_CONTEXT_NOT_EXPLICIT',
              'context', v_action_context,
              'message', 'Live transfer execution classification is only allowed from explicit action or diagnostic flows.'
            )::text;
  END IF;

  v_scope := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  IF v_scope = '' THEN
    v_scope := 'ALL';
  END IF;

  RETURN QUERY
  WITH batch_context AS (
    SELECT
      batch_rows.id AS pay_batch_id,
      batch_rows.status AS batch_status,
      batch_rows.schedule_kind AS batch_schedule_kind,
      batch_rows.scheduled_at_utc AS batch_scheduled_at_utc,
      batch_rows.cancelled_at_utc AS batch_cancelled_at_utc,
      batch_rows.execution_commit_state AS batch_execution_commit_state
    FROM public.pay_batches AS batch_rows
    WHERE batch_rows.id = p_pay_batch_id
  ), latest_auth_request AS (
    SELECT
      auth_request_rows.id AS auth_request_id,
      auth_request_rows.state AS auth_request_state,
      CASE
        WHEN NULLIF(btrim(COALESCE(auth_request_rows.execution_intent_json->>'operation_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (auth_request_rows.execution_intent_json->>'operation_id')::uuid
        ELSE NULL::uuid
      END AS auth_request_operation_id,
      ROW_NUMBER() OVER (ORDER BY auth_request_rows.created_at_utc DESC NULLS LAST, auth_request_rows.id DESC) AS auth_request_ordinal
    FROM public.pay_batch_auth_requests AS auth_request_rows
    WHERE auth_request_rows.pay_batch_id = p_pay_batch_id
      AND upper(btrim(COALESCE(auth_request_rows.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION', 'AUTHORISED', 'AUTHORIZED')
  ), transfer_rows AS (
    SELECT
      transfer_source_rows.id AS pay_bank_transfer_id,
      transfer_source_rows.pay_batch_id,
      transfer_source_rows.pay_channel,
      transfer_source_rows.transfer_group_key,
      latest_scope_rows.scope_id,
      latest_scope_rows.scope_operation_id,
      latest_scope_rows.scope_status,
      latest_scope_rows.scope_request_id,
      upper(btrim(COALESCE(transfer_source_rows.status, ''))) AS status_upper,
      upper(btrim(COALESCE(transfer_source_rows.rail_state, ''))) AS rail_state_upper,
      transfer_source_rows.amount,
      transfer_source_rows.currency,
      transfer_source_rows.request_id,
      transfer_source_rows.payment_reference,
      transfer_source_rows.rail_tx_id,
      COALESCE(transfer_source_rows.rail_meta_json, '{}'::jsonb) AS rail_meta_json,
      transfer_source_rows.completed_at_utc,
      transfer_source_rows.failed_reason,
      transfer_source_rows.payee_name,
      transfer_source_rows.sort_code,
      transfer_source_rows.account_number,
      transfer_source_rows.account_type
    FROM public.pay_bank_transfers AS transfer_source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = transfer_source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        scope_rows.id AS scope_id,
        scope_rows.operation_id AS scope_operation_id,
        scope_rows.status AS scope_status,
        scope_rows.request_id AS scope_request_id
      FROM public.banking_pay_operation_transfer_scope AS scope_rows
      WHERE scope_rows.pay_batch_id = transfer_source_rows.pay_batch_id
        AND scope_rows.pay_channel = transfer_source_rows.pay_channel
        AND (
          scope_rows.pay_bank_transfer_id = transfer_source_rows.id
          OR (
            scope_rows.pay_bank_transfer_id IS NULL
            AND NULLIF(btrim(COALESCE(scope_rows.transfer_group_key, '')), '') IS NOT NULL
            AND scope_rows.transfer_group_key = transfer_source_rows.transfer_group_key
          )
        )
        AND (p_operation_id IS NULL OR scope_rows.operation_id = p_operation_id)
      ORDER BY scope_rows.updated_at_utc DESC NULLS LAST, scope_rows.created_at_utc DESC NULLS LAST, scope_rows.id DESC
      LIMIT 1
    ) AS latest_scope_rows ON true
    WHERE transfer_source_rows.pay_batch_id = p_pay_batch_id
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(transfer_source_rows.pay_channel, ''))) = v_scope)
      AND (
        COALESCE(p_include_unscoped_transfers, true)
        OR p_operation_id IS NULL
        OR latest_scope_rows.scope_operation_id = p_operation_id
      )
  ), scope_without_transfer_rows AS (
    SELECT
      NULL::uuid AS pay_bank_transfer_id,
      scope_source_rows.pay_batch_id,
      scope_source_rows.pay_channel,
      scope_source_rows.transfer_group_key,
      scope_source_rows.id AS scope_id,
      scope_source_rows.operation_id AS scope_operation_id,
      scope_source_rows.status AS scope_status,
      scope_source_rows.request_id AS scope_request_id,
      upper(btrim(COALESCE(scope_source_rows.status, ''))) AS status_upper,
      NULL::text AS rail_state_upper,
      scope_source_rows.amount,
      scope_source_rows.currency,
      scope_source_rows.request_id,
      scope_source_rows.payment_reference,
      NULL::text AS rail_tx_id,
      jsonb_build_object(
        'scope_id', scope_source_rows.id::text,
        'operation_id', scope_source_rows.operation_id::text,
        'scope_status', scope_source_rows.status,
        'local_scope_row', true
      ) AS rail_meta_json,
      NULL::timestamptz AS completed_at_utc,
      NULL::text AS failed_reason,
      scope_source_rows.payee_name,
      scope_source_rows.sort_code,
      scope_source_rows.account_number,
      scope_source_rows.account_type
    FROM public.banking_pay_operation_transfer_scope AS scope_source_rows
    WHERE scope_source_rows.pay_batch_id = p_pay_batch_id
      AND scope_source_rows.pay_bank_transfer_id IS NULL
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(scope_source_rows.pay_channel, ''))) = v_scope)
      AND (p_operation_id IS NULL OR scope_source_rows.operation_id = p_operation_id)
  ), source_rows AS (
    SELECT * FROM transfer_rows
    UNION ALL
    SELECT * FROM scope_without_transfer_rows
  ), classified_rows AS (
    SELECT
      source_rows.*,
      batch_context_rows.batch_status,
      batch_context_rows.batch_schedule_kind,
      batch_context_rows.batch_scheduled_at_utc,
      batch_context_rows.batch_cancelled_at_utc,
      COALESCE(provider_evidence_rows.evidence_class, 'LOCAL_PREPARED_ONLY') AS provider_evidence_class,
      COALESCE(provider_evidence_rows.provider_submitted, false) AS provider_submitted,
      COALESCE(provider_evidence_rows.provider_request_sent, false) AS provider_request_sent,
      COALESCE(provider_evidence_rows.provider_response_present, false) AS provider_response_present,
      COALESCE(provider_evidence_rows.provider_event_present, false) AS provider_event_present,
      COALESCE(provider_evidence_rows.provider_external_id_present, false) AS provider_external_id_present,
      COALESCE(provider_evidence_rows.local_prepared_only, source_rows.pay_bank_transfer_id IS NOT NULL OR source_rows.scope_id IS NOT NULL) AS local_prepared_only,
      COALESCE(provider_evidence_rows.cash_state, 'NO_TRANSFER_EVIDENCE') AS provider_cash_state,
      provider_evidence_rows.blocker_code AS provider_blocker_code,
      COALESCE(provider_evidence_rows.support_details_json, '{}'::jsonb) AS provider_support_details_json,
      COALESCE(rail_classification_rows.cash_state, 'UNKNOWN') AS rail_cash_state,
      COALESCE(rail_classification_rows.is_final_money_moved, false) AS rail_is_final_money_moved,
      COALESCE(rail_classification_rows.is_terminal_no_money, false) AS rail_is_terminal_no_money,
      COALESCE(rail_classification_rows.is_pending_non_final, false) AS rail_is_pending_non_final,
      auth_rows.auth_request_id,
      auth_rows.auth_request_state,
      auth_rows.auth_request_operation_id
    FROM source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT evidence_rows.*
      FROM public._pay_bank_transfer_provider_evidence_classify(
        source_rows.pay_batch_id,
        source_rows.pay_bank_transfer_id,
        CASE
          WHEN source_rows.pay_bank_transfer_id IS NOT NULL THEN jsonb_build_object('scope_type', 'TRANSFER', 'pay_bank_transfer_id', source_rows.pay_bank_transfer_id::text)
          ELSE jsonb_build_object('scope_type', 'BATCH')
        END,
        p_operation_id
      ) AS evidence_rows
      WHERE source_rows.pay_bank_transfer_id IS NOT NULL
      LIMIT 1
    ) AS provider_evidence_rows ON true
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_rows.status_upper,
      source_rows.rail_state_upper,
      source_rows.rail_meta_json,
      source_rows.rail_meta_json
    ) AS rail_classification_rows ON true
    LEFT JOIN LATERAL (
      SELECT latest_auth_request.auth_request_id, latest_auth_request.auth_request_state, latest_auth_request.auth_request_operation_id
      FROM latest_auth_request
      WHERE latest_auth_request.auth_request_ordinal = 1
      LIMIT 1
    ) AS auth_rows ON true
  ), lifecycle_rows AS (
    SELECT
      classified_rows.*,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_rows
        WHERE correction_item_rows.pay_batch_id = classified_rows.pay_batch_id
          AND correction_item_rows.correction_item_kind = 'PRE_BANK_CANCEL'
          AND upper(btrim(COALESCE(correction_item_rows.status, ''))) = 'APPLIED'
          AND (
            correction_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS item_rows
              WHERE item_rows.pay_batch_candidate_id = correction_item_rows.pay_batch_candidate_id
                AND item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_pre_bank_cancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS unwind_work_item_rows
        JOIN public.pay_payment_correction_requests AS unwind_request_rows
          ON unwind_request_rows.id = unwind_work_item_rows.correction_request_id
        WHERE unwind_request_rows.pay_batch_id = classified_rows.pay_batch_id
          AND upper(btrim(COALESCE(unwind_request_rows.correction_kind, ''))) IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
          AND upper(btrim(COALESCE(unwind_work_item_rows.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED')
          AND (
            unwind_work_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS unwind_item_rows
              WHERE unwind_item_rows.pay_batch_candidate_id = unwind_work_item_rows.pay_batch_candidate_id
                AND unwind_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS operation_rows
        WHERE operation_rows.pay_batch_id = classified_rows.pay_batch_id
          AND (
            upper(btrim(COALESCE(operation_rows.status, ''))) = 'RETRY_LATER'
            OR upper(btrim(COALESCE(operation_rows.phase, ''))) = 'RETRY_LATER'
            OR upper(NULLIF(btrim(COALESCE(operation_rows.error_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.result_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.progress_json->>'retry_state', '')), '')) = 'RETRY_LATER'
          )
      ) AS has_retry_later_state
    FROM classified_rows
  ), final_rows AS (
    SELECT
      lifecycle_rows.*,
      CASE
        WHEN lifecycle_rows.provider_cash_state = 'FINAL_PAID' OR lifecycle_rows.rail_is_final_money_moved THEN 'PAID_OR_SETTLED'
        WHEN lifecycle_rows.provider_evidence_class = 'PROVIDER_OUTCOME_UNKNOWN'
          OR (lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'UNKNOWN')
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.rail_cash_state = 'UNKNOWN'
            AND (
              lifecycle_rows.status_upper IN ('COMMITTED', 'EXECUTED')
              OR lifecycle_rows.rail_state_upper IN ('COMMITTED', 'EXECUTED')
            )
          ) THEN 'PROVIDER_OUTCOME_UNKNOWN'
        WHEN lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'PENDING_NON_FINAL' THEN 'PROVIDER_SUBMITTED_PENDING'
        WHEN lifecycle_rows.has_applied_pre_bank_cancel
          OR (
            NOT lifecycle_rows.provider_submitted
            AND (
              upper(COALESCE(lifecycle_rows.batch_status, '')) IN ('CANCELLED', 'CANCELED')
              OR lifecycle_rows.batch_cancelled_at_utc IS NOT NULL
            )
          )
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.status_upper IN (
              'CANCELLED',
              'CANCELED',
              'CANCELLED_BEFORE_BANK_SUBMISSION',
              'CANCELED_BEFORE_BANK_SUBMISSION',
              'LOCALLY_CANCELLED',
              'LOCAL_CANCELLED',
              'VOIDED'
            )
          ) THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
        WHEN lifecycle_rows.has_applied_no_money_unwind THEN 'FINANCIALS_REWOUND'
        WHEN lifecycle_rows.provider_submitted
          AND (
            lifecycle_rows.provider_cash_state = 'TERMINAL_NO_MONEY'
            OR lifecycle_rows.rail_is_terminal_no_money
          ) THEN
          CASE WHEN lifecycle_rows.status_upper IN ('CANCELLED', 'CANCELED') OR lifecycle_rows.rail_state_upper IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN 'PROVIDER_CANCELLED_NO_MONEY' ELSE 'PROVIDER_FAILED_NO_MONEY' END
        WHEN lifecycle_rows.has_retry_later_state AND NOT lifecycle_rows.provider_submitted THEN 'PROVIDER_OUTAGE_RETRY_LATER'
        WHEN upper(COALESCE(lifecycle_rows.batch_status, '')) = 'SCHEDULED' OR lifecycle_rows.batch_scheduled_at_utc IS NOT NULL OR lifecycle_rows.status_upper = 'SCHEDULED' THEN 'SCHEDULED_LOCAL_NOT_SENT'
        ELSE 'LOCAL_PREPARED_NOT_SENT'
      END AS derived_lifecycle_state
    FROM lifecycle_rows
  )
  SELECT
    final_rows.pay_bank_transfer_id,
    final_rows.pay_batch_id,
    final_rows.pay_channel,
    final_rows.transfer_group_key,
    final_rows.scope_id,
    final_rows.scope_operation_id,
    final_rows.scope_status,
    final_rows.scope_request_id,
    final_rows.status_upper,
    final_rows.rail_state_upper,
    final_rows.amount,
    final_rows.currency,
    (
      COALESCE(final_rows.amount, 0) > 0
      AND NULLIF(btrim(COALESCE(final_rows.currency, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.payee_name, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.sort_code, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.account_number, '')), '') IS NOT NULL
    ) AS has_route_ready,
    final_rows.local_prepared_only,
    final_rows.provider_submitted,
    final_rows.provider_event_present,
    (final_rows.provider_request_sent AND NOT final_rows.provider_external_id_present) AS has_provider_attempt_without_external_id,
    COALESCE(NULLIF(final_rows.provider_support_details_json->>'operation_submit_attempt_count', '')::integer, 0) > 0 AS has_operation_submit_attempt,
    final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' AS has_ambiguous_external_evidence,
    final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') AS is_failed_or_blocked,
    final_rows.derived_lifecycle_state IN ('PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND') AS is_terminal_or_completed,
    final_rows.derived_lifecycle_state AS evidence_classification,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
    ) AS is_authorisation_ready,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
    ) AS is_unattempted_submit_eligible,
    (NOT final_rows.provider_submitted AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')) AS is_safe_local_cleanup,
    final_rows.status_upper IN ('', 'PENDING', 'PREPARED', 'READY', 'SCHEDULED', 'QUEUED', 'SUBMITTED', 'SENT', 'PROCESSING', 'ACCEPTED') AS is_canonical_pending_status,
    final_rows.auth_request_id IS NOT NULL AS has_auth_prepared_scope,
    (final_rows.auth_request_operation_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_different_operation_scope,
    false AS has_stale_auth_request_evidence,
    final_rows.auth_request_id,
    final_rows.auth_request_state,
    final_rows.auth_request_operation_id,
    (final_rows.auth_request_id IS NOT NULL AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_other_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND NOT final_rows.provider_submitted) AS has_cancellable_local_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND final_rows.provider_submitted) AS has_non_cancellable_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND NOT final_rows.provider_submitted) AS has_authorised_auth_without_provider_submission,
    final_rows.provider_submitted AS has_auth_request_provider_risk,
    CASE WHEN final_rows.provider_submitted THEN 'Provider evidence exists; local authorisation cleanup must not treat this as not sent.' ELSE NULL::text END AS auth_request_unsafe_reason,
    CASE
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown; check provider before retry, cancel, or unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_SUBMITTED_PENDING' THEN 'Provider submission is pending; provider state must be checked before unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'Payment is paid/settled; use recovery workflow rather than no-money unwind.'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'Payment financials have already been rewound; do not submit, cancel, or unwind again.'
      ELSE NULL::text
    END AS unsafe_reason,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_authorised_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION')) AS has_pending_authorisation_auth_request,
    (
      final_rows.auth_request_id IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
      AND COALESCE(final_rows.amount, 0) > 0
    ) AS is_provider_submit_ready,
    CASE
      WHEN final_rows.provider_submitted THEN 'PROVIDER_SUBMISSION_ALREADY_EXISTS'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'PAYMENT_ALREADY_PAID_OR_SETTLED'
      WHEN final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') THEN 'TERMINAL_NO_MONEY_REWIND_REQUIRED'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'FINANCIALS_ALREADY_REWOUND'
      WHEN final_rows.auth_request_id IS NULL THEN 'NO_AUTHORISED_PAYMENT_AUTH_REQUEST'
      WHEN upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED') THEN 'PAYMENT_AUTHORISATION_NOT_COMPLETE'
      ELSE NULL::text
    END AS provider_submit_unsafe_reason,
    (
      final_rows.provider_submitted
      OR final_rows.derived_lifecycle_state IN ('PROVIDER_OUTCOME_UNKNOWN', 'PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND')
      OR final_rows.auth_request_id IS NULL
      OR upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED')
    ) AS has_provider_submit_blocker,
    (
      SELECT latest_event.provider_failure_reason_code
      FROM public.pay_bank_transfer_events AS latest_event
      WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        AND latest_event.provider_failure_reason_code IS NOT NULL
      ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
      LIMIT 1
    ) AS provider_failure_reason_code,
    COALESCE(
      (
        SELECT latest_event.provider_failure_reason_group
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
          AND latest_event.provider_failure_reason_group IS NOT NULL
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_group'
    ) AS provider_failure_reason_group,
    COALESCE(
      (
        SELECT public._banking_provider_failure_reason_normalise(
          latest_event.provider_key,
          COALESCE(latest_event.provider_state, latest_event.normalised_state),
          latest_event.provider_failure_reason_code,
          COALESCE(latest_event.raw_payload->>'provider_failure_reason_text', latest_event.raw_payload->>'failure_reason', latest_event.raw_payload->>'reason', latest_event.raw_payload->>'message'),
          COALESCE(latest_event.raw_payload, '{}'::jsonb)
        )->>'failure_reason_label'
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_label'
    ) AS provider_failure_reason_label,
    (final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED') AS is_success_only,
    (final_rows.pay_bank_transfer_id IS NOT NULL OR final_rows.scope_id IS NOT NULL) AS should_touch_payment_status
  FROM final_rows
  ORDER BY final_rows.pay_channel, final_rows.transfer_group_key NULLS LAST, final_rows.pay_bank_transfer_id NULLS LAST, final_rows.scope_id NULLS LAST;
END;
$function$;







CREATE OR REPLACE FUNCTION public.pay_execute_operation_cleanup_failed_local_artifacts(
  p_operation_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_failure_phase text DEFAULT NULL::text,
  p_failure_error_json jsonb DEFAULT '{}'::jsonb,
  p_dry_run boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_type_upper text := NULL::text;
  v_failure_phase text := NULL::text;
  v_failure_error_json jsonb := '{}'::jsonb;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_batch_execution_boundary_crossed boolean := false;
  v_chunk_id uuid := NULL::uuid;
  v_provider_state_risk_count integer := 0;
  v_provider_chunk_risk_count integer := 0;
  v_transfer_event_risk_count integer := 0;
  v_scope_rows_considered integer := 0;
  v_transfer_rows_considered integer := 0;
  v_scope_rows_deleted integer := 0;
  v_transfer_rows_deleted integer := 0;
  v_item_links_cleared integer := 0;
  v_bank_references_cleared integer := 0;
  v_chunks_marked_failed integer := 0;
  v_chunks_marked_skipped integer := 0;
  v_locks_released integer := 0;
  v_review_required boolean := false;
  v_safe_to_retry boolean := false;
  v_retry_blocked boolean := true;
  v_retry_blocked_reason text := NULL::text;
  v_cleanup_mode text := 'REVIEW_REQUIRED';
  v_deleted_scope_ids jsonb := '[]'::jsonb;
  v_deleted_transfer_ids jsonb := '[]'::jsonb;
  v_safe_scope_ids jsonb := '[]'::jsonb;
  v_safe_transfer_ids jsonb := '[]'::jsonb;
  v_unsafe_reasons jsonb := '[]'::jsonb;
  v_active_auth_request_count integer := 0;
  v_operation_active_auth_request_count integer := 0;
  v_auth_requests_cancelled integer := 0;
  v_auth_tokens_voided integer := 0;
  v_batch_execution_intent_cleared integer := 0;
  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: operation_id is required'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_failure_error_json IS NOT NULL AND jsonb_typeof(p_failure_error_json) = 'object' THEN
    v_failure_error_json := p_failure_error_json;
  ELSE
    v_failure_error_json := '{}'::jsonb;
  END IF;

  v_failure_phase := NULLIF(BTRIM(COALESCE(p_failure_phase, v_failure_error_json->>'phase', v_failure_error_json->>'failure_phase', '')), '');

  IF COALESCE(v_failure_error_json->>'chunk_id', v_failure_error_json->>'provider_chunk_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_chunk_id := COALESCE(v_failure_error_json->>'chunk_id', v_failure_error_json->>'provider_chunk_id')::uuid;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF v_operation_row.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_NOT_FOUND',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: operation not found',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id);
  IF v_failure_phase IS NULL THEN
    v_failure_phase := NULLIF(BTRIM(COALESCE(v_operation_row.phase, '')), '');
  END IF;

  v_operation_type_upper := upper(BTRIM(COALESCE(v_operation_row.operation_type, '')));
  IF v_operation_type_upper NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_TYPE_NOT_SUPPORTED',
      'message', 'Only PAYMENT_EXECUTE and PAYMENT_RETRY_BLOCKED_FUNDS operations are supported.',
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF upper(BTRIM(COALESCE(v_operation_row.status, ''))) = 'COMPLETE' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'COMPLETE_OPERATION_CANNOT_BE_CLEANED',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id
  FOR UPDATE;

  IF v_batch_row.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'PAY_BATCH_NOT_FOUND',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation_row.pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_batch_execution_boundary_crossed := (
    upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
    OR NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
    OR v_batch_row.execution_committed_at_utc IS NOT NULL
  );

  SELECT COUNT(*)::integer
  INTO v_scope_rows_considered
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_operation_row.pay_batch_id
    AND (v_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = v_chunk_id);

  SELECT COUNT(DISTINCT scope_row.pay_bank_transfer_id)::integer
  INTO v_transfer_rows_considered
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_operation_row.pay_batch_id
    AND scope_row.pay_bank_transfer_id IS NOT NULL
    AND (v_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = v_chunk_id);

  SELECT COUNT(*)::integer
  INTO v_provider_state_risk_count
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_operation_row.pay_batch_id
    AND (v_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = v_chunk_id)
    AND upper(BTRIM(COALESCE(scope_row.provider_submit_state, ''))) IN (
      'REQUEST_SENDING',
      'REQUEST_SENT_LOCAL',
      'PROVIDER_ACCEPTED',
      'PROVIDER_REJECTED',
      'PROVIDER_UNKNOWN',
      'REVIEW_REQUIRED',
      'CHUNK_FINALISED'
    );

  SELECT COUNT(*)::integer
  INTO v_provider_chunk_risk_count
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.operation_id = p_operation_id
    AND (v_chunk_id IS NULL OR chunk_row.id = v_chunk_id)
    AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
    AND (
      upper(BTRIM(COALESCE(chunk_row.status, ''))) IN ('RUNNING', 'COMPLETE', 'FAILED')
      OR chunk_row.started_at_utc IS NOT NULL
      OR COALESCE(chunk_row.result_json, '{}'::jsonb) <> '{}'::jsonb
      OR COALESCE(chunk_row.error_json, '{}'::jsonb) <> '{}'::jsonb
    );

  SELECT COUNT(*)::integer
  INTO v_transfer_event_risk_count
  FROM public.pay_bank_transfer_events AS event_row
  WHERE event_row.pay_batch_id = v_operation_row.pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_operation_row.pay_batch_id
        AND (v_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = v_chunk_id)
        AND scope_row.pay_bank_transfer_id = event_row.pay_bank_transfer_id
    );

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE auth_request.execution_intent_json->>'operation_id' = p_operation_id::text)::integer
  INTO v_active_auth_request_count,
       v_operation_active_auth_request_count
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
    AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

  v_review_required := v_batch_execution_boundary_crossed
    OR COALESCE(v_provider_state_risk_count, 0) > 0
    OR COALESCE(v_provider_chunk_risk_count, 0) > 0
    OR COALESCE(v_transfer_event_risk_count, 0) > 0
    OR COALESCE(v_active_auth_request_count, 0) > COALESCE(v_operation_active_auth_request_count, 0);

  IF v_review_required THEN
    v_retry_blocked := true;
    v_safe_to_retry := false;
    v_retry_blocked_reason := CASE
      WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED'
      WHEN COALESCE(v_provider_state_risk_count, 0) > 0 THEN 'PROVIDER_STATE_REQUIRES_RECONCILIATION'
      WHEN COALESCE(v_provider_chunk_risk_count, 0) > 0 THEN 'PROVIDER_SUBMIT_CHUNK_REQUIRES_RECONCILIATION'
      WHEN COALESCE(v_transfer_event_risk_count, 0) > 0 THEN 'TRANSFER_EVENT_PRESENT'
      ELSE 'ACTIVE_AUTH_REQUEST_PRESENT'
    END;
    v_cleanup_mode := 'REVIEW_REQUIRED_' || v_retry_blocked_reason;
    v_unsafe_reasons := jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'reason', v_retry_blocked_reason,
      'provider_state_risk_count', COALESCE(v_provider_state_risk_count, 0),
      'provider_chunk_risk_count', COALESCE(v_provider_chunk_risk_count, 0),
      'transfer_event_risk_count', COALESCE(v_transfer_event_risk_count, 0),
      'active_auth_request_count', COALESCE(v_active_auth_request_count, 0)
    )));
  ELSE
    v_retry_blocked := false;
    v_safe_to_retry := true;
    v_cleanup_mode := CASE WHEN COALESCE(p_dry_run, false) THEN 'DRY_RUN_BOUNDED_LOCAL_CLEANUP' ELSE 'CLEANED_BOUNDED_LOCAL_ARTIFACTS' END;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_cleanup_scope_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_cleanup_scope_ids AS
  SELECT scope_row.id AS scope_id,
         scope_row.pay_bank_transfer_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_operation_row.pay_batch_id
    AND (v_chunk_id IS NULL OR scope_row.provider_submit_chunk_id = v_chunk_id)
    AND COALESCE(v_review_required, false) IS FALSE
  ORDER BY scope_row.id
  LIMIT 100;

  SELECT COALESCE(jsonb_agg(to_jsonb(cleanup_scope.scope_id::text) ORDER BY cleanup_scope.scope_id), '[]'::jsonb)
  INTO v_safe_scope_ids
  FROM pg_temp.tmp_cleanup_scope_ids AS cleanup_scope;

  SELECT COALESCE(jsonb_agg(DISTINCT to_jsonb(cleanup_scope.pay_bank_transfer_id::text)), '[]'::jsonb)
  INTO v_safe_transfer_ids
  FROM pg_temp.tmp_cleanup_scope_ids AS cleanup_scope
  WHERE cleanup_scope.pay_bank_transfer_id IS NOT NULL;

  IF COALESCE(p_dry_run, false) IS FALSE AND COALESCE(v_review_required, false) IS FALSE THEN
    WITH same_operation_auth_requests AS (
      SELECT auth_request.id
      FROM public.pay_batch_auth_requests AS auth_request
      WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
        AND auth_request.state IN ('AWAITING', 'AUTHORISED')
        AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text
    ), cancelled_auth_requests AS (
      UPDATE public.pay_batch_auth_requests AS auth_request_update
      SET state = 'CANCELLED',
          finalised_at_utc = COALESCE(auth_request_update.finalised_at_utc, v_now),
          finalised_by_user_id = COALESCE(auth_request_update.finalised_by_user_id, v_effective_actor_user_id),
          execution_intent_json = jsonb_strip_nulls(COALESCE(auth_request_update.execution_intent_json, '{}'::jsonb) || jsonb_build_object(
            'cancelled_by_bounded_execution_cleanup', true,
            'cleanup_operation_id', p_operation_id::text,
            'cleanup_at_utc', v_now::text,
            'failure_phase', v_failure_phase
          ))
      FROM same_operation_auth_requests
      WHERE auth_request_update.id = same_operation_auth_requests.id
      RETURNING auth_request_update.id
    )
    SELECT COUNT(*)::integer
    INTO v_auth_requests_cancelled
    FROM cancelled_auth_requests;

    WITH voided_tokens AS (
      UPDATE public.pay_batch_auth_tokens AS auth_token_update
      SET used_at_utc = COALESCE(auth_token_update.used_at_utc, v_now),
          expires_at_utc = CASE WHEN auth_token_update.expires_at_utc > v_now THEN v_now ELSE auth_token_update.expires_at_utc END
      WHERE auth_token_update.auth_request_id IN (
        SELECT auth_request.id
        FROM public.pay_batch_auth_requests AS auth_request
        WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
          AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text
          AND auth_request.state = 'CANCELLED'
      )
        AND (auth_token_update.used_at_utc IS NULL OR auth_token_update.expires_at_utc > v_now)
      RETURNING auth_token_update.token
    )
    SELECT COUNT(*)::integer
    INTO v_auth_tokens_voided
    FROM voided_tokens;

    WITH item_rows_to_clear AS (
      SELECT item_row.id AS pay_batch_item_id,
             item_row.bank_reference AS previous_bank_reference,
             transfer_row.payment_reference AS transfer_payment_reference
      FROM public.pay_batch_items AS item_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = item_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_operation_row.pay_batch_id
      JOIN pg_temp.tmp_cleanup_scope_ids AS cleanup_scope
        ON cleanup_scope.pay_bank_transfer_id = item_row.pay_bank_transfer_id
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = cleanup_scope.pay_bank_transfer_id
    ), cleared_item_links AS (
      UPDATE public.pay_batch_items AS item_update
      SET pay_bank_transfer_id = NULL,
          bank_reference = CASE WHEN item_update.bank_reference = item_rows_to_clear.transfer_payment_reference THEN NULL ELSE item_update.bank_reference END,
          updated_at = v_now
      FROM item_rows_to_clear
      WHERE item_update.id = item_rows_to_clear.pay_batch_item_id
      RETURNING item_update.id,
                item_rows_to_clear.previous_bank_reference,
                item_rows_to_clear.transfer_payment_reference
    )
    SELECT COUNT(*)::integer,
           COALESCE((COUNT(*) FILTER (
             WHERE cleared_item_links.previous_bank_reference = cleared_item_links.transfer_payment_reference
               AND NULLIF(BTRIM(COALESCE(cleared_item_links.previous_bank_reference, '')), '') IS NOT NULL
           )), 0)::integer
    INTO v_item_links_cleared,
         v_bank_references_cleared
    FROM cleared_item_links;

    WITH deleted_scope_rows AS (
      DELETE FROM public.banking_pay_operation_transfer_scope AS scope_delete
      USING pg_temp.tmp_cleanup_scope_ids AS cleanup_scope
      WHERE scope_delete.id = cleanup_scope.scope_id
        AND scope_delete.operation_id = p_operation_id
        AND scope_delete.pay_batch_id = v_operation_row.pay_batch_id
      RETURNING scope_delete.id
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(deleted_scope_rows.id::text) ORDER BY deleted_scope_rows.id), '[]'::jsonb)
    INTO v_scope_rows_deleted,
         v_deleted_scope_ids
    FROM deleted_scope_rows;

    WITH deleted_transfer_rows AS (
      DELETE FROM public.pay_bank_transfers AS transfer_delete
      WHERE transfer_delete.pay_batch_id = v_operation_row.pay_batch_id
        AND transfer_delete.id IN (SELECT cleanup_scope.pay_bank_transfer_id FROM pg_temp.tmp_cleanup_scope_ids AS cleanup_scope WHERE cleanup_scope.pay_bank_transfer_id IS NOT NULL)
        AND transfer_delete.status = 'PENDING'
        AND transfer_delete.rail_tx_id IS NULL
        AND transfer_delete.completed_at_utc IS NULL
        AND transfer_delete.failed_reason IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.banking_pay_operation_transfer_scope AS remaining_scope WHERE remaining_scope.pay_bank_transfer_id = transfer_delete.id)
        AND NOT EXISTS (SELECT 1 FROM public.pay_batch_items AS remaining_item WHERE remaining_item.pay_bank_transfer_id = transfer_delete.id)
        AND NOT EXISTS (SELECT 1 FROM public.pay_bank_transfer_events AS transfer_event WHERE transfer_event.pay_bank_transfer_id = transfer_delete.id)
      RETURNING transfer_delete.id
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(deleted_transfer_rows.id::text) ORDER BY deleted_transfer_rows.id), '[]'::jsonb)
    INTO v_transfer_rows_deleted,
         v_deleted_transfer_ids
    FROM deleted_transfer_rows;

    WITH chunks_to_mutate AS (
      SELECT operation_chunk.id AS operation_chunk_id,
             operation_chunk.status AS previous_status,
             (operation_chunk.locked_by IS NOT NULL OR operation_chunk.lock_expires_at_utc IS NOT NULL) AS had_lock
      FROM public.banking_pay_operation_chunks AS operation_chunk
      WHERE operation_chunk.operation_id = p_operation_id
        AND operation_chunk.status IN ('PENDING', 'RUNNING')
        AND NOT (operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT')
      ORDER BY operation_chunk.sequence_no, operation_chunk.id
      LIMIT 100
    ), mutated_chunks AS (
      UPDATE public.banking_pay_operation_chunks AS operation_chunk_update
      SET status = CASE WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN 'FAILED' ELSE 'SKIPPED' END,
          error_json = CASE WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN jsonb_build_object('code', 'PAYMENT_EXECUTE_BOUNDED_LOCAL_CLEANUP', 'operation_id', p_operation_id::text, 'failure_phase', v_failure_phase, 'cleanup_at_utc', v_now::text) ELSE operation_chunk_update.error_json END,
          locked_by = NULL::text,
          lock_expires_at_utc = NULL::timestamptz,
          completed_at_utc = COALESCE(operation_chunk_update.completed_at_utc, v_now),
          updated_at_utc = v_now
      FROM chunks_to_mutate
      WHERE operation_chunk_update.id = chunks_to_mutate.operation_chunk_id
      RETURNING chunks_to_mutate.previous_status,
                chunks_to_mutate.had_lock
    )
    SELECT COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'RUNNING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'PENDING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.had_lock)), 0)::integer
    INTO v_chunks_marked_failed,
         v_chunks_marked_skipped,
         v_locks_released
    FROM mutated_chunks;

    UPDATE public.pay_batches AS batch_update
    SET execution_intent_json = CASE
          WHEN NULLIF(BTRIM(COALESCE(batch_update.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text THEN NULL::jsonb
          ELSE batch_update.execution_intent_json
        END
    WHERE batch_update.id = v_operation_row.pay_batch_id
      AND v_batch_execution_boundary_crossed IS FALSE;
    GET DIAGNOSTICS v_batch_execution_intent_cleared = ROW_COUNT;
  END IF;

  IF COALESCE(p_dry_run, false) IS FALSE THEN
    UPDATE public.banking_pay_operations AS operation_update
    SET status = CASE WHEN v_review_required THEN 'REVIEW_REQUIRED' ELSE 'FAILED' END,
        runner_state = CASE WHEN v_review_required THEN 'WAITING_USER_REVIEW' ELSE 'FAILED' END,
        run_after_utc = NULL::timestamptz,
        requires_user_action = v_review_required,
        resume_reason = CASE WHEN v_review_required THEN COALESCE(v_retry_blocked_reason, 'PAYMENT_EXECUTION_CLEANUP_REVIEW_REQUIRED') ELSE 'PAYMENT_EXECUTION_LOCAL_ARTIFACTS_CLEANED' END,
        error_json = jsonb_strip_nulls(COALESCE(operation_update.error_json, '{}'::jsonb) || jsonb_build_object(
          'cleanup_at_utc', v_now::text,
          'cleanup_mode', v_cleanup_mode,
          'retry_blocked_reason', v_retry_blocked_reason,
          'failure_phase', v_failure_phase
        )),
        locked_by = NULL::text,
        lock_expires_at_utc = NULL::timestamptz,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    BEGIN
      PERFORM public.pay_batch_display_summary_touch(v_operation_row.pay_batch_id);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    BEGIN
      PERFORM public.banking_pay_batch_signal_touch(
        v_operation_row.pay_batch_id,
        CASE WHEN v_review_required THEN 'PAYMENT_EXECUTION_CLEANUP_REVIEW_REQUIRED' ELSE 'PAYMENT_EXECUTION_LOCAL_ARTIFACTS_CLEANED' END,
        'pay_execute_operation_cleanup_failed_local_artifacts',
        jsonb_strip_nulls(jsonb_build_object(
          'operation_id', p_operation_id::text,
          'cleanup_mode', v_cleanup_mode,
          'retry_blocked_reason', v_retry_blocked_reason
        )),
        true,
        false,
        v_review_required,
        true
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  v_result := jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'dry_run', COALESCE(p_dry_run, false),
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_operation_row.pay_batch_id::text,
    'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
    'failure_phase', v_failure_phase,
    'cleanup_mode', v_cleanup_mode,
    'retry_blocked_reason', v_retry_blocked_reason,
    'safe_to_retry', v_safe_to_retry,
    'retry_blocked', v_retry_blocked,
    'review_required', v_review_required,
    'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
    'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
    'provider_state_risk_count', COALESCE(v_provider_state_risk_count, 0),
    'provider_chunk_risk_count', COALESCE(v_provider_chunk_risk_count, 0),
    'transfer_event_risk_count', COALESCE(v_transfer_event_risk_count, 0),
    'scope_rows_deleted', COALESCE(v_scope_rows_deleted, 0),
    'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
    'item_links_cleared', COALESCE(v_item_links_cleared, 0),
    'bank_references_cleared', COALESCE(v_bank_references_cleared, 0),
    'chunks_marked_failed', COALESCE(v_chunks_marked_failed, 0),
    'chunks_marked_skipped', COALESCE(v_chunks_marked_skipped, 0),
    'locks_released', COALESCE(v_locks_released, 0),
    'safe_scope_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_scope_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_scope_ids, '[]'::jsonb) END,
    'safe_transfer_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_transfer_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_transfer_ids, '[]'::jsonb) END,
    'unsafe_reasons', COALESCE(v_unsafe_reasons, '[]'::jsonb),
    'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
    'operation_active_auth_request_count', COALESCE(v_operation_active_auth_request_count, 0),
    'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
    'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
    'batch_execution_intent_cleared', COALESCE(v_batch_execution_intent_cleared, 0),
    'batch_execution_boundary_crossed', v_batch_execution_boundary_crossed,
    'execution_commit_state', upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))),
    'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
    'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL
  ));

  RETURN v_result;
END;
$function$;













DROP FUNCTION IF EXISTS public.pay_provider_submit_diagnostic_get(uuid, uuid, uuid, uuid, boolean);
CREATE OR REPLACE FUNCTION public.pay_provider_submit_diagnostic_get(
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_transfer_id uuid DEFAULT NULL::uuid,
  p_chunk_id uuid DEFAULT NULL::uuid,
  p_counts_only boolean DEFAULT false,
  p_provider_diagnostic_context text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_batch_id_from_scope uuid := NULL::uuid;
  v_operation_count integer := 0;
  v_chunk_count integer := 0;
  v_transfer_count integer := 0;
  v_active_auth_request_count integer := 0;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_stale_empty_submit_chunk_count integer := 0;
  v_stale_unresolved_submit_chunk_count integer := 0;
  v_request_sent_no_response_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_accepted_count integer := 0;
  v_provider_submission_blocked_pre_call_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_mixed_provider_submit_outcome boolean := false;
  v_payment_provider_review_required boolean := false;
  v_provider_submit_actual_context boolean := false;
  v_operation_review_required boolean := false;
  v_provider_submission_status text := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
  v_review_reason_code text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_call_stage text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_submission_attempted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_response_received boolean := false;
  v_provider_response_present boolean := false;
  v_provider_submission_accepted boolean := false;
  v_provider_submission_rejected boolean := false;
  v_provider_submission_failed boolean := false;
  v_provider_submission_unknown boolean := false;
  v_provider_acceptance_evidence_present boolean := false;
  v_stale_submit_chunk boolean := false;
  v_unfinalised_submit_chunk boolean := false;
  v_chunk_lock_expired boolean := false;
  v_manual_resolution_required boolean := false;
  v_safe_retry_available boolean := false;
  v_automatic_retry_blocked boolean := false;
  v_retry_blocked_reason text := NULL::text;
  v_recommended_action text := 'No provider submission attempt has been recorded for this scope.';
  v_operation_ids jsonb := '[]'::jsonb;
  v_current_operation_ids jsonb := '[]'::jsonb;
  v_related_operation_ids jsonb := '[]'::jsonb;
  v_diagnostic_operation_id text := NULL::text;
  v_chunk_ids jsonb := '[]'::jsonb;
  v_transfer_ids jsonb := '[]'::jsonb;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_primary_operation_id text := NULL::text;
  v_primary_chunk_id text := NULL::text;
  v_primary_transfer_id text := NULL::text;
  v_primary_transfer_scope_id text := NULL::text;
  v_primary_auth_request_id text := NULL::text;
  v_primary_rail_provider text := NULL::text;
  v_primary_rail_env text := NULL::text;
  v_primary_rail_tx_id text := NULL::text;
  v_primary_rail_state text := NULL::text;
  v_primary_provider_transaction_id text := NULL::text;
  v_primary_provider_reference text := NULL::text;
  v_primary_provider_state text := NULL::text;
  v_primary_request_id text := NULL::text;
  v_primary_idempotency_key text := NULL::text;
  v_primary_local_provider_request_id text := NULL::text;
  v_primary_provider_http_status text := NULL::text;
  v_primary_provider_error_code text := NULL::text;
  v_primary_provider_error_message_redacted text := NULL::text;
  v_primary_provider_response_redacted jsonb := NULL::jsonb;
  v_primary_provider_error_redacted jsonb := NULL::jsonb;
  v_chunk_started_at_utc text := NULL::text;
  v_chunk_completed_at_utc text := NULL::text;
  v_chunk_lock_expires_at_utc text := NULL::text;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_ids jsonb := '{}'::jsonb;
  v_batch_level_cleaned_local_blocked_pre_call_neutralised boolean := false;
  v_provider_diagnostic_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_provider_diagnostic_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL AND p_operation_id IS NULL AND p_transfer_id IS NULL AND p_chunk_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'IDENTIFIER_REQUIRED',
      'message', 'pay_provider_submit_diagnostic_get: at least one identifier is required'
    )::text USING ERRCODE = 'P0001';
  END IF;


  IF v_provider_diagnostic_context IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_REQUIRED',
      'message', 'pay_provider_submit_diagnostic_get requires an explicit provider diagnostic context.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_provider_diagnostic_context IN (
    'PROVIDER_STAGE_RECORD',
    'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
    'PROVIDER_SUBMIT_STAGE_RECORD',
    'OPERATION_GET',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'PREVIEW_OPEN',
    'PROGRESS_POLLING',
    'OPERATION_PROGRESS',
    'EXECUTION_HOT_PATH',
    'EXECUTION_WORKER',
    'OPERATION_WORKER',
    'PROVIDER_SUBMIT_CHUNK',
    'PROVIDER_SUBMIT_STAGE',
    'OPERATION_ADVANCE',
    'PAY_EXECUTE_BANK'
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_NOT_ALLOWED',
      'context', v_provider_diagnostic_context,
      'message', 'Provider submit diagnostics are blocked from provider stage record, operation GET/progress, list, bootstrap, Overview, preview, progress polling, and execution hot paths.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_provider_diagnostic_context NOT IN (
    'PROVIDER_DIAGNOSTIC_TAB',
    'PROVIDER_DIAGNOSTIC_ACTION',
    'EXPLICIT_PROVIDER_DIAGNOSTIC',
    'USER_TRIGGERED_PROVIDER_DIAGNOSTIC',
    'PROVIDER_REVIEW',
    'PROVIDER_REPAIR',
    'PAYMENT_ISSUES_PROVIDER_DIAGNOSTIC',
    'CURRENT_PAYMENT_STATUS_PROVIDER_DETAIL'
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT',
      'context', v_provider_diagnostic_context,
      'message', 'Provider submit diagnostics are only allowed from an explicit provider diagnostics tab/action or provider review/repair flow.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_pay_batch_id IS NOT NULL THEN
    PERFORM 1 FROM public.pay_batches AS batch_check WHERE batch_check.id = p_pay_batch_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'PAY_BATCH_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: pay batch not found',
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: operation not found',
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: operation does not belong to supplied pay batch',
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_transfer_id IS NOT NULL THEN
    SELECT transfer_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.id = p_transfer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: transfer not found',
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to supplied pay batch',
        'transfer_id', p_transfer_id::text,
        'transfer_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operation_chunks AS chunk_row
    JOIN public.banking_pay_operations AS operation_row
      ON operation_row.id = chunk_row.operation_id
    WHERE chunk_row.id = p_chunk_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: chunk not found',
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: chunk operation does not belong to supplied pay batch',
        'chunk_id', p_chunk_id::text,
        'chunk_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;



  PERFORM set_config('lock_timeout', '3s', true);

  IF p_operation_id IS NOT NULL AND COALESCE(p_counts_only, false) IS TRUE THEN
    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_chunks;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id uuid PRIMARY KEY,
      operation_id uuid NOT NULL,
      pay_batch_id uuid,
      phase text,
      chunk_type text,
      sequence_no integer,
      status text,
      payload_json jsonb,
      result_json jsonb,
      error_json jsonb,
      unit_count integer,
      completed_count integer,
      failed_count integer,
      locked_by text,
      lock_expires_at_utc timestamptz,
      started_at_utc timestamptz,
      completed_at_utc timestamptz,
      created_at_utc timestamptz,
      updated_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id,
      operation_id,
      pay_batch_id,
      phase,
      chunk_type,
      sequence_no,
      status,
      payload_json,
      result_json,
      error_json,
      unit_count,
      completed_count,
      failed_count,
      locked_by,
      lock_expires_at_utc,
      started_at_utc,
      completed_at_utc,
      created_at_utc,
      updated_at_utc
    )
    SELECT chunk_row.id,
           chunk_row.operation_id,
           v_effective_pay_batch_id,
           chunk_row.phase,
           chunk_row.chunk_type,
           chunk_row.sequence_no,
           chunk_row.status,
           COALESCE(chunk_row.payload_json, '{}'::jsonb),
           chunk_row.result_json,
           chunk_row.error_json,
           chunk_row.unit_count,
           chunk_row.completed_count,
           chunk_row.failed_count,
           chunk_row.locked_by,
           chunk_row.lock_expires_at_utc,
           chunk_row.started_at_utc,
           chunk_row.completed_at_utc,
           chunk_row.created_at_utc,
           chunk_row.updated_at_utc
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
      AND (p_chunk_id IS NULL OR chunk_row.id = p_chunk_id)
    ORDER BY chunk_row.sequence_no, chunk_row.created_at_utc NULLS FIRST, chunk_row.id
    ON CONFLICT (chunk_id) DO NOTHING;

    IF p_chunk_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_chunks AS exact_chunk_check
      WHERE exact_chunk_check.chunk_id = p_chunk_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: chunk does not belong to supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfer_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfer_ids (
      transfer_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT operation_scope.pay_bank_transfer_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE p_chunk_id IS NULL
      AND operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND operation_scope.pay_bank_transfer_id IS NOT NULL
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT transfer_row.id
    FROM public.pay_bank_transfers AS transfer_row
    WHERE p_chunk_id IS NOT NULL
      AND p_transfer_id IS NOT NULL
      AND transfer_row.id = p_transfer_id
      AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
        WHERE operation_scope_check.operation_id = p_operation_id
          AND (v_effective_pay_batch_id IS NULL OR operation_scope_check.pay_batch_id = v_effective_pay_batch_id)
          AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
      )
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT transfer_uuid.transfer_id
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    CROSS JOIN LATERAL (
      SELECT transfer_id_element.value AS transfer_id_text
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_id_element(value)
      UNION ALL
      SELECT COALESCE(transfer_payload.value->>'pay_bank_transfer_id', transfer_payload.value->>'transfer_id', transfer_payload.value->>'id') AS transfer_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_payload(value)
    ) AS transfer_text
    CROSS JOIN LATERAL (
      SELECT transfer_text.transfer_id_text::uuid AS transfer_id
      WHERE NULLIF(BTRIM(COALESCE(transfer_text.transfer_id_text, '')), '') ~* v_uuid_regex
    ) AS transfer_uuid
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = transfer_uuid.transfer_id
     AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
    WHERE p_transfer_id IS NULL OR transfer_uuid.transfer_id = p_transfer_id
    ON CONFLICT DO NOTHING;

    IF p_transfer_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_check
      WHERE exact_transfer_check.transfer_id = p_transfer_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to the supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id uuid PRIMARY KEY,
      pay_batch_id uuid NOT NULL,
      status text,
      rail_provider text,
      rail_env text,
      request_id text,
      rail_tx_id text,
      rail_state text,
      rail_meta_json jsonb,
      payment_reference text,
      created_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id,
      pay_batch_id,
      status,
      rail_provider,
      rail_env,
      request_id,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      payment_reference,
      created_at_utc
    )
    SELECT transfer_row.id,
           transfer_row.pay_batch_id,
           transfer_row.status,
           transfer_row.rail_provider,
           transfer_row.rail_env,
           transfer_row.request_id,
           transfer_row.rail_tx_id,
           transfer_row.rail_state,
           COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
           transfer_row.payment_reference,
           transfer_row.created_at_utc
    FROM public.pay_bank_transfers AS transfer_row
    JOIN pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_id
      ON exact_transfer_id.transfer_id = transfer_row.id
    WHERE v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id
    ON CONFLICT (transfer_id) DO NOTHING;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_markers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_markers (
      source_kind text NOT NULL,
      source_id text,
      chunk_id uuid,
      transfer_id uuid,
      provider_submission_status text,
      review_reason_code text,
      provider_request_sent boolean NOT NULL DEFAULT false,
      provider_response_present boolean NOT NULL DEFAULT false,
      provider_response_received boolean NOT NULL DEFAULT false,
      provider_accepted boolean NOT NULL DEFAULT false,
      provider_rejected boolean NOT NULL DEFAULT false,
      provider_unknown boolean NOT NULL DEFAULT false,
      provider_malformed boolean NOT NULL DEFAULT false,
      provider_blocked_pre_call boolean NOT NULL DEFAULT false,
      unfinalised_submit_chunk boolean NOT NULL DEFAULT false,
      marker_json jsonb NOT NULL DEFAULT '{}'::jsonb
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'chunk_diagnostic'::text,
           selected_chunk.chunk_id::text,
           selected_chunk.chunk_id,
           exact_chunk_transfer.transfer_id,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'outcome_code', ''))),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))),
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_called', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_dispatched_at_utc', chunk_diag.provider_submit_diagnostic->>'request_sent_at_utc', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', chunk_diag.provider_submit_diagnostic->>'provider_http_status', chunk_diag.provider_submit_diagnostic->>'provider_error_code', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'rail_tx_id', chunk_diag.provider_submit_diagnostic->>'provider_transaction_id', chunk_diag.provider_submit_diagnostic->>'provider_payment_id', chunk_diag.provider_submit_diagnostic->>'provider_reference', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc <= v_now),
           jsonb_strip_nulls(COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) || jsonb_build_object('chunk_id', selected_chunk.chunk_id::text))
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    LEFT JOIN LATERAL (
      SELECT COALESCE(
        CASE WHEN jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.payload_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.payload_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        '{}'::jsonb
      ) AS provider_submit_diagnostic
    ) AS chunk_diag ON true
    LEFT JOIN LATERAL (
      SELECT exact_transfer.transfer_id
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer
      ORDER BY exact_transfer.transfer_id
      LIMIT 1
    ) AS exact_chunk_transfer ON true
    WHERE COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) <> '{}'::jsonb
       OR upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING';

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_meta'::text,
           selected_transfer.transfer_id::text,
           NULL::uuid,
           selected_transfer.transfer_id,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))),
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object('transfer_id', selected_transfer.transfer_id::text))
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
    WHERE COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) <> '{}'::jsonb
       OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_state, '')), '') IS NOT NULL;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_event'::text,
           transfer_event.id::text,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))),
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent}', transfer_event.raw_payload #>> '{provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', transfer_event.raw_payload #>> '{provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_called}', transfer_event.raw_payload #>> '{provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_sent_at_utc}', transfer_event.raw_payload #>> '{request_sent_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_present}', transfer_event.raw_payload #>> '{provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_http_status}', transfer_event.raw_payload #>> '{provider_http_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_error_code}', transfer_event.raw_payload #>> '{provider_error_code}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT', 'SUBMITTED', 'SENT', 'PROCESSING', 'PENDING', 'COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_accepted}', transfer_event.raw_payload #>> '{provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED', 'FAILED', 'ERROR')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected}', transfer_event.raw_payload #>> '{provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown}', transfer_event.raw_payload #>> '{provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(transfer_event.raw_payload, '{}'::jsonb) || jsonb_build_object(
             'pay_bank_transfer_event_id', transfer_event.id::text,
             'event_source', transfer_event.event_source,
             'normalised_state', transfer_event.normalised_state,
             'provider_state', transfer_event.provider_state
           ))
    FROM public.pay_bank_transfer_events AS transfer_event
    JOIN pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
      ON selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
    WHERE transfer_event.pay_bank_transfer_id IS NOT NULL;

    SELECT COUNT(*)::integer INTO v_operation_count FROM public.banking_pay_operations AS exact_operation WHERE exact_operation.id = p_operation_id;
    SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;
    SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_accepted)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_request_sent OR marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_unknown)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_rejected)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_blocked_pre_call)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_malformed)::integer,
           COUNT(DISTINCT marker.chunk_id) FILTER (WHERE marker.unfinalised_submit_chunk)::integer,
           COALESCE(BOOL_OR(marker.unfinalised_submit_chunk), false)
    INTO v_provider_acceptance_evidence_count,
         v_provider_response_present_count,
         v_provider_request_sent_count,
         v_provider_submission_unknown_count,
         v_provider_submission_rejected_count,
         v_provider_submission_blocked_pre_call_count,
         v_provider_submission_malformed_response_count,
         v_unfinalised_submit_chunk_count,
         v_chunk_lock_expired
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker;

    v_provider_submission_accepted_count := COALESCE(v_provider_acceptance_evidence_count, 0);
    v_stale_unresolved_submit_chunk_count := CASE
      WHEN COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_unfinalised_submit_chunk_count
      ELSE 0
    END;
    v_stale_empty_submit_chunk_count := v_stale_unresolved_submit_chunk_count;
    v_request_sent_no_response_count := CASE
      WHEN COALESCE(v_provider_request_sent_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_provider_request_sent_count
      ELSE 0
    END;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.sequence_no NULLS LAST, selected_chunk.created_at_utc NULLS FIRST, selected_chunk.chunk_id), '[]'::jsonb),
           MIN(selected_chunk.chunk_id::text),
           MIN(selected_chunk.started_at_utc)::text,
           MIN(selected_chunk.completed_at_utc)::text,
           MIN(selected_chunk.lock_expires_at_utc)::text
    INTO v_chunk_ids,
         v_primary_chunk_id,
         v_chunk_started_at_utc,
         v_chunk_completed_at_utc,
         v_chunk_lock_expires_at_utc
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
           MIN(selected_transfer.transfer_id::text),
           MIN(selected_transfer.rail_provider),
           MIN(selected_transfer.rail_env),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
    INTO v_transfer_ids,
         v_primary_transfer_id,
         v_primary_rail_provider,
         v_primary_rail_env,
         v_primary_rail_tx_id,
         v_primary_rail_state,
         v_primary_request_id
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COALESCE(jsonb_agg(to_jsonb(operation_scope.id::text) ORDER BY operation_scope.id), '[]'::jsonb),
           MIN(operation_scope.id::text)
    INTO v_transfer_scope_ids,
         v_primary_transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
      AND (
        p_chunk_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_scope
          WHERE exact_transfer_scope.transfer_id = operation_scope.pay_bank_transfer_id
        )
      );

    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb),
           MIN(auth_request.id::text)
    INTO v_active_auth_request_count,
         v_auth_request_ids,
         v_primary_auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text;

    v_diagnostic_operation_id := p_operation_id::text;
    v_primary_operation_id := p_operation_id::text;
    v_current_operation_ids := jsonb_build_array(p_operation_id::text);
    v_related_operation_ids := '[]'::jsonb;
    v_operation_ids := jsonb_build_array(p_operation_id::text);

    SELECT marker.marker_json->>'provider_transaction_id',
           marker.marker_json->>'provider_reference',
           marker.marker_json->>'provider_state',
           COALESCE(marker.marker_json->>'request_id', v_primary_request_id),
           COALESCE(marker.marker_json->>'idempotency_key', v_primary_request_id),
           marker.marker_json->>'local_provider_request_id',
           marker.marker_json->>'provider_http_status',
           marker.marker_json->>'provider_error_code',
           marker.marker_json->>'provider_error_message_redacted',
           marker.marker_json->'provider_response_redacted',
           marker.marker_json->'provider_error_redacted'
    INTO v_primary_provider_transaction_id,
         v_primary_provider_reference,
         v_primary_provider_state,
         v_primary_request_id,
         v_primary_idempotency_key,
         v_primary_local_provider_request_id,
         v_primary_provider_http_status,
         v_primary_provider_error_code,
         v_primary_provider_error_message_redacted,
         v_primary_provider_response_redacted,
         v_primary_provider_error_redacted
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker
    WHERE marker.provider_accepted OR marker.provider_rejected OR marker.provider_response_present OR marker.provider_request_sent
    ORDER BY CASE WHEN marker.provider_accepted THEN 0 WHEN marker.provider_rejected THEN 1 WHEN marker.provider_response_present THEN 2 ELSE 3 END,
             marker.source_kind,
             marker.source_id
    LIMIT 1;

    v_provider_submit_actual_context := COALESCE(v_chunk_count, 0) > 0
      OR COALESCE(v_transfer_count, 0) > 0
      OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      OR COALESCE(v_provider_response_present_count, 0) > 0
      OR COALESCE(v_provider_request_sent_count, 0) > 0
      OR COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;

    v_mixed_provider_submit_outcome := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      AND (
        COALESCE(v_provider_submission_rejected_count, 0) > 0
        OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
        OR COALESCE(v_provider_submission_unknown_count, 0) > 0
        OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        OR COALESCE(v_request_sent_no_response_count, 0) > 0
        OR COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
      );

    IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
      v_review_reason_code := CASE WHEN v_mixed_provider_submit_outcome THEN 'MIXED_PROVIDER_SUBMIT_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_accepted := true;
      v_provider_acceptance_evidence_present := true;
      v_manual_resolution_required := COALESCE(v_mixed_provider_submit_outcome, false);
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := CASE WHEN v_mixed_provider_submit_outcome THEN 'PROVIDER_SUBMISSION_MIXED_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_recommended_action := CASE WHEN v_mixed_provider_submit_outcome THEN 'Provider acceptance evidence exists for at least one transfer, but not all outcomes are resolved. Reconcile before retry.' ELSE 'Provider acceptance evidence exists. Do not retry unless reconciled.' END;
    ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
      v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_rejected := true;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_REJECTED';
      v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
    ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
      v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
      v_recommended_action := 'Provider returned an unusable response. Check bank records before retry.';
    ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0 OR COALESCE(v_request_sent_no_response_count, 0) > 0 OR (COALESCE(v_provider_request_sent_count, 0) > 0 AND COALESCE(v_provider_response_present_count, 0) = 0) THEN
      v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check bank records before retry.';
    ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_call_stage := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_submission_unknown := true;
      v_stale_submit_chunk := true;
      v_unfinalised_submit_chunk := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_recommended_action := 'Check bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
    ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
      v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_retry_blocked_reason := NULL::text;
      v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
    ELSE
      v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
      v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_recommended_action := 'No provider submission attempt has been recorded for this scope.';
    END IF;

    v_payment_provider_review_required := COALESCE(v_provider_submit_actual_context, false) IS TRUE
      AND v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_ACCEPTED',
        'PROVIDER_SUBMISSION_REJECTED',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
      );

    v_counts := jsonb_build_object(
      'operation_count', COALESCE(v_operation_count, 0),
      'chunk_count', COALESCE(v_chunk_count, 0),
      'transfer_count', COALESCE(v_transfer_count, 0),
      'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
      'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
    );

    v_ids := jsonb_build_object(
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
      'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
    );

    v_provider_submit_diagnostic := jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'EXACT_OPERATION_COUNTS_ONLY',
      'generated_at_utc', v_now::text,
      'review_reason_code', v_review_reason_code,
      'provider_submission_status', v_provider_submission_status,
      'provider_call_stage', v_provider_call_stage,
      'provider_submission_attempted', v_provider_submission_attempted,
      'provider_request_sent', v_provider_request_sent,
      'provider_response_received', v_provider_response_received,
      'provider_response_present', v_provider_response_present,
      'provider_submission_accepted', v_provider_submission_accepted,
      'provider_submission_rejected', v_provider_submission_rejected,
      'provider_submission_failed', v_provider_submission_failed,
      'provider_submission_unknown', v_provider_submission_unknown,
      'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'stale_submit_chunk', v_stale_submit_chunk,
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
      'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
      'chunk_started_at_utc', v_chunk_started_at_utc,
      'chunk_completed_at_utc', v_chunk_completed_at_utc,
      'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'automatic_retry_blocked', v_automatic_retry_blocked,
      'retry_blocked_reason', v_retry_blocked_reason,
      'recommended_action', v_recommended_action
    )
    || jsonb_build_object(
      'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_id', v_primary_chunk_id,
      'chunk_ids', v_chunk_ids,
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', v_transfer_ids,
      'transfer_scope_id', v_primary_transfer_scope_id,
      'transfer_scope_ids', v_transfer_scope_ids,
      'auth_request_id', v_primary_auth_request_id,
      'auth_request_ids', v_auth_request_ids,
      'rail_provider', v_primary_rail_provider,
      'rail_env', v_primary_rail_env,
      'rail_tx_id', v_primary_rail_tx_id,
      'rail_state', v_primary_rail_state,
      'provider_transaction_id', v_primary_provider_transaction_id,
      'provider_reference', v_primary_provider_reference,
      'provider_state', v_primary_provider_state,
      'request_id', v_primary_request_id,
      'idempotency_key', v_primary_idempotency_key,
      'local_provider_request_id', v_primary_local_provider_request_id,
      'provider_http_status', v_primary_provider_http_status,
      'provider_error_code', v_primary_provider_error_code,
      'provider_error_message_redacted', v_primary_provider_error_message_redacted,
      'provider_response_redacted', v_primary_provider_response_redacted,
      'provider_error_redacted', v_primary_provider_error_redacted
    );
    RETURN jsonb_build_object(
      'ok', true,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_review_reason_code,
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'recommended_action', v_recommended_action,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'counts', v_counts,
      'ids', v_ids,
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
      'counts_only', true,
      'exact_scope_mode', true
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_operations;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunks;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfers;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_sources;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfer_flags;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_flags;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id uuid PRIMARY KEY,
    pay_batch_id uuid,
    operation_status text,
    operation_phase text,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    created_at_utc timestamptz,
    updated_at_utc timestamptz
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id,
    pay_batch_id,
    operation_status,
    operation_phase,
    progress_json,
    result_json,
    error_json,
    created_at_utc,
    updated_at_utc
  )
  SELECT operation_row.id,
         operation_row.pay_batch_id,
         operation_row.status,
         operation_row.phase,
         COALESCE(operation_row.progress_json, '{}'::jsonb),
         operation_row.result_json,
         operation_row.error_json,
         operation_row.created_at_utc,
         operation_row.updated_at_utc
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (
      (p_operation_id IS NOT NULL AND operation_row.id = p_operation_id)
      OR (v_effective_pay_batch_id IS NOT NULL AND operation_row.pay_batch_id = v_effective_pay_batch_id)
      OR (p_chunk_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_chunks AS chunk_filter
        WHERE chunk_filter.id = p_chunk_id
          AND chunk_filter.operation_id = operation_row.id
      ))
    )
  ON CONFLICT (operation_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id uuid PRIMARY KEY,
    operation_id uuid NOT NULL,
    pay_batch_id uuid,
    phase text NOT NULL,
    chunk_type text NOT NULL,
    sequence_no integer NOT NULL,
    status text NOT NULL,
    payload_json jsonb NOT NULL,
    result_json jsonb,
    error_json jsonb,
    unit_count integer NOT NULL,
    completed_count integer NOT NULL,
    failed_count integer NOT NULL,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz NOT NULL,
    started_at_utc timestamptz,
    completed_at_utc timestamptz,
    updated_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id,
    operation_id,
    pay_batch_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  SELECT chunk_row.id,
         chunk_row.operation_id,
         operation_row.pay_batch_id,
         chunk_row.phase,
         chunk_row.chunk_type,
         chunk_row.sequence_no,
         chunk_row.status,
         COALESCE(chunk_row.payload_json, '{}'::jsonb),
         chunk_row.result_json,
         chunk_row.error_json,
         chunk_row.unit_count,
         chunk_row.completed_count,
         chunk_row.failed_count,
         chunk_row.locked_by,
         chunk_row.lock_expires_at_utc,
         chunk_row.created_at_utc,
         chunk_row.started_at_utc,
         chunk_row.completed_at_utc,
         chunk_row.updated_at_utc
  FROM public.banking_pay_operation_chunks AS chunk_row
  JOIN public.banking_pay_operations AS operation_row
    ON operation_row.id = chunk_row.operation_id
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
    AND (
      (p_chunk_id IS NOT NULL AND chunk_row.id = p_chunk_id)
      OR (p_operation_id IS NOT NULL AND chunk_row.operation_id = p_operation_id)
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
        WHERE selected_operation.operation_id = chunk_row.operation_id
      )
    )
  ON CONFLICT (chunk_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (
    chunk_id uuid NOT NULL,
    transfer_id uuid NOT NULL,
    PRIMARY KEY (chunk_id, transfer_id)
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids'
      ELSE '[]'::jsonb
    END
  ) AS transfer_id_text(value)
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers'
      ELSE '[]'::jsonb
    END
  ) AS transfer_payload(value)
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'transfer_id', '')), '')
    ) AS value
  ) AS transfer_id_text
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id uuid PRIMARY KEY,
    pay_batch_id uuid NOT NULL,
    status text NOT NULL,
    rail_provider text NOT NULL,
    rail_env text NOT NULL,
    request_id text,
    rail_tx_id text,
    rail_state text,
    rail_meta_json jsonb,
    payment_reference text,
    created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id,
    pay_batch_id,
    status,
    rail_provider,
    rail_env,
    request_id,
    rail_tx_id,
    rail_state,
    rail_meta_json,
    payment_reference,
    created_at_utc
  )
  SELECT transfer_row.id,
         transfer_row.pay_batch_id,
         transfer_row.status,
         transfer_row.rail_provider,
         transfer_row.rail_env,
         transfer_row.request_id,
         transfer_row.rail_tx_id,
         transfer_row.rail_state,
         transfer_row.rail_meta_json,
         transfer_row.payment_reference,
         transfer_row.created_at_utc
  FROM public.pay_bank_transfers AS transfer_row
  WHERE (p_transfer_id IS NOT NULL AND transfer_row.id = p_transfer_id)
     OR EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
       WHERE selected_chunk_transfer.transfer_id = transfer_row.id
     )
     OR (
       p_transfer_id IS NULL
       AND p_chunk_id IS NULL
       AND v_effective_pay_batch_id IS NOT NULL
       AND transfer_row.pay_batch_id = v_effective_pay_batch_id
     )
  ON CONFLICT (transfer_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type text NOT NULL,
    operation_id uuid,
    chunk_id uuid,
    transfer_id uuid,
    event_id uuid,
    diagnostic jsonb NOT NULL,
    provider_submission_status text,
    review_reason_code text,
    provider_call_stage text,
    provider_submission_attempted boolean NOT NULL DEFAULT false,
    provider_request_sent boolean NOT NULL DEFAULT false,
    provider_response_received boolean NOT NULL DEFAULT false,
    provider_response_present boolean NOT NULL DEFAULT false,
    provider_submission_accepted boolean NOT NULL DEFAULT false,
    provider_submission_rejected boolean NOT NULL DEFAULT false,
    provider_submission_failed boolean NOT NULL DEFAULT false,
    provider_submission_unknown boolean NOT NULL DEFAULT false,
    provider_acceptance_evidence_present boolean NOT NULL DEFAULT false,
    manual_resolution_required boolean NOT NULL DEFAULT false,
    safe_retry_available boolean NOT NULL DEFAULT false,
    provider_http_status text,
    provider_error_code text,
    provider_error_message_redacted text,
    provider_transaction_id text,
    provider_reference text,
    provider_state text,
    rail_tx_id text,
    rail_state text,
    request_id text,
    idempotency_key text,
    local_provider_request_id text,
    provider_response_redacted jsonb,
    provider_error_redacted jsonb
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type,
    operation_id,
    chunk_id,
    transfer_id,
    event_id,
    diagnostic,
    provider_submission_status,
    review_reason_code,
    provider_call_stage,
    provider_submission_attempted,
    provider_request_sent,
    provider_response_received,
    provider_response_present,
    provider_submission_accepted,
    provider_submission_rejected,
    provider_submission_failed,
    provider_submission_unknown,
    provider_acceptance_evidence_present,
    manual_resolution_required,
    safe_retry_available,
    provider_http_status,
    provider_error_code,
    provider_error_message_redacted,
    provider_transaction_id,
    provider_reference,
    provider_state,
    rail_tx_id,
    rail_state,
    request_id,
    idempotency_key,
    local_provider_request_id,
    provider_response_redacted,
    provider_error_redacted
  )
  WITH raw_diagnostics AS (
    SELECT 'operation_progress'::text AS source_type,
           selected_operation.operation_id,
           NULL::uuid AS chunk_id,
           NULL::uuid AS transfer_id,
           NULL::uuid AS event_id,
           selected_operation.progress_json->'provider_submit_diagnostic' AS diagnostic
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.progress_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_result'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_error'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_result'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_error'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_meta'::text,
           NULL::uuid,
           NULL::uuid,
           selected_transfer.transfer_id,
           NULL::uuid,
           selected_transfer.rail_meta_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
    WHERE jsonb_typeof(selected_transfer.rail_meta_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_event'::text,
           NULL::uuid,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           transfer_event.id,
           transfer_event.raw_payload->'provider_submit_diagnostic'
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE jsonb_typeof(transfer_event.raw_payload->'provider_submit_diagnostic') = 'object'
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
        WHERE selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
      )
  )
  SELECT raw_diagnostics.source_type,
         raw_diagnostics.operation_id,
         raw_diagnostics.chunk_id,
         raw_diagnostics.transfer_id,
         raw_diagnostics.event_id,
         raw_diagnostics.diagnostic,
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_status', raw_diagnostics.diagnostic->>'outcome_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'review_reason_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_call_stage', '')), ''),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_attempted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_accepted', raw_diagnostics.diagnostic->>'provider_accepted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_rejected', raw_diagnostics.diagnostic->>'provider_rejected', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_failed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_unknown', raw_diagnostics.diagnostic->>'provider_unknown', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'safe_retry_available', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_http_status', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_message_redacted', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_transaction_id', raw_diagnostics.diagnostic->>'provider_payment_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_reference', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_tx_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'request_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'idempotency_key', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'local_provider_request_id', '')), ''),
         raw_diagnostics.diagnostic->'provider_response_redacted',
         raw_diagnostics.diagnostic->'provider_error_redacted'
  FROM raw_diagnostics
  WHERE jsonb_typeof(raw_diagnostics.diagnostic) = 'object'
    AND raw_diagnostics.diagnostic <> '{}'::jsonb;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response
  )
  SELECT selected_transfer.transfer_id,
         (
           (
             NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
             AND UPPER(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
           )
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
                upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
                AND upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
                AND EXISTS (
                  SELECT 1
                  FROM (VALUES
                    (transfer_event.provider_event_id),
                    (transfer_event.provider_reference),
                    (transfer_event.raw_payload #>> '{provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{payment_id}'),
                    (transfer_event.raw_payload #>> '{external_payment_id}'),
                    (transfer_event.raw_payload #>> '{revolut_payment_id}'),
                    (transfer_event.raw_payload #>> '{rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
                  ) AS provider_identifier(identifier_value)
                  WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> selected_transfer.transfer_id::text
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), ''), '__NO_EVENT_IDEMPOTENCY_KEY__')
                )
              ), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
           OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME')), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
           OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')), false)
           OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           OR COALESCE(BOOL_OR(
             upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'NO_PROVIDER_SUBMISSION_ATTEMPTED'
             AND selected_source.provider_submission_attempted IS FALSE
             AND selected_source.provider_request_sent IS FALSE
             AND selected_source.provider_response_received IS FALSE
             AND selected_source.provider_response_present IS FALSE
           ), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
         )
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
    ON selected_source.transfer_id = selected_transfer.transfer_id
  LEFT JOIN public.pay_bank_transfer_events AS transfer_event
    ON transfer_event.pay_bank_transfer_id = selected_transfer.transfer_id
  GROUP BY selected_transfer.transfer_id,
           selected_transfer.request_id,
           selected_transfer.payment_reference,
           selected_transfer.rail_tx_id
  ON CONFLICT (transfer_id) DO NOTHING;

  UPDATE pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag_update
  SET has_provider_unknown = true
  WHERE transfer_flag_update.has_provider_request_sent IS TRUE
    AND transfer_flag_update.has_provider_response IS NOT TRUE
    AND transfer_flag_update.has_provider_acceptance_evidence IS NOT TRUE;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false,
    has_durable_provider_request_impossible boolean NOT NULL DEFAULT false,
    is_stale_unresolved boolean NOT NULL DEFAULT false,
    is_stale_request_sent_no_response boolean NOT NULL DEFAULT false,
    is_stale_claim_or_pre_call_only boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response,
    has_durable_provider_request_impossible,
    is_stale_unresolved,
    is_stale_request_sent_no_response,
    is_stale_claim_or_pre_call_only
  )
  SELECT chunk_eval.chunk_id,
         chunk_eval.has_provider_acceptance_evidence,
         chunk_eval.has_provider_response,
         chunk_eval.has_provider_request_sent,
         chunk_eval.has_provider_rejection,
         chunk_eval.has_provider_unknown OR (chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent),
         chunk_eval.has_provider_blocked_pre_call,
         chunk_eval.has_provider_malformed_response,
         chunk_eval.has_durable_provider_request_impossible,
         chunk_eval.is_stale_unresolved,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent IS NOT TRUE
  FROM (
    SELECT selected_chunk.chunk_id,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
           ) AS has_provider_acceptance_evidence,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           ) AS has_provider_response,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE')), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_call_stage, ''))) IN ('PROVIDER_PAYMENT_CREATE_REQUEST_SENT', 'PROVIDER_PAYMENT_CREATE_RESPONSE_RECEIVED', 'PROVIDER_PAYMENT_CREATE_ACCEPTED', 'PROVIDER_PAYMENT_CREATE_REJECTED', 'PROVIDER_PAYMENT_CREATE_UNKNOWN', 'PROVIDER_PAYMENT_CREATE_MALFORMED', 'RAIL_UPDATE_APPLY_STARTED', 'RAIL_UPDATE_APPLY_FAILED')), false)
           ) AS has_provider_request_sent,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_rejection), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
             OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
           ) AS has_provider_rejection,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_unknown), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
           ) AS has_provider_unknown,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_blocked_pre_call), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           ) AS has_provider_blocked_pre_call,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_malformed_response), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
           ) AS has_provider_malformed_response,
           COALESCE(BOOL_OR(
             lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
           ), false) AS has_durable_provider_request_impossible,
           (
             upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND upper(BTRIM(COALESCE(selected_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
             AND selected_chunk.completed_at_utc IS NULL
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
             )
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
               OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
               OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
               OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
             )
             AND COALESCE(BOOL_OR(
               lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
             ), false) IS NOT TRUE
           ) AS is_stale_unresolved
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag
      ON transfer_flag.transfer_id = selected_chunk_transfer.transfer_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
      ON selected_source.chunk_id = selected_chunk.chunk_id
    GROUP BY selected_chunk.chunk_id,
             selected_chunk.status,
             selected_chunk.chunk_type,
             selected_chunk.completed_at_utc,
             selected_chunk.lock_expires_at_utc
  ) AS chunk_eval
  ON CONFLICT (chunk_id) DO NOTHING;

  SELECT COUNT(*)::integer INTO v_operation_count FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;
  SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;
  SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_response)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_request_sent)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_unknown)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_rejection)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_blocked_pre_call)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_malformed_response)::integer
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count
  FROM pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag;

  SELECT GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_response_present_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_response), 0))::integer,
         GREATEST(COALESCE(v_provider_request_sent_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_request_sent), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_unknown_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_unknown OR chunk_flag.is_stale_unresolved), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_rejected_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_rejection), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_accepted_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_blocked_pre_call_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_blocked_pre_call), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_malformed_response_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_malformed_response), 0))::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_unresolved), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_request_sent_no_response), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'), 0)::integer,
         COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING' AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)), false)
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count,
       v_stale_unresolved_submit_chunk_count,
       v_request_sent_no_response_count,
       v_unfinalised_submit_chunk_count,
       v_chunk_lock_expired
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS chunk_flag
    ON chunk_flag.chunk_id = selected_chunk.chunk_id;

  v_stale_empty_submit_chunk_count := COALESCE(v_stale_unresolved_submit_chunk_count, 0);

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_operation.operation_id::text) ORDER BY selected_operation.operation_id), '[]'::jsonb),
         MIN(selected_operation.operation_id::text)
  INTO v_operation_ids,
       v_primary_operation_id
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  IF p_operation_id IS NOT NULL THEN
    v_diagnostic_operation_id := p_operation_id::text;
  ELSIF p_chunk_id IS NOT NULL THEN
    SELECT selected_chunk.operation_id::text
    INTO v_diagnostic_operation_id
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    WHERE selected_chunk.chunk_id = p_chunk_id
    LIMIT 1;
  ELSE
    v_diagnostic_operation_id := NULL::text;
  END IF;

  IF v_diagnostic_operation_id IS NOT NULL THEN
    v_primary_operation_id := v_diagnostic_operation_id;
    v_current_operation_ids := jsonb_build_array(v_diagnostic_operation_id);

    SELECT COALESCE(jsonb_agg(to_jsonb(related_operation.value) ORDER BY related_operation.value), '[]'::jsonb)
    INTO v_related_operation_ids
    FROM (
      SELECT DISTINCT selected_operation.operation_id::text AS value
      FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
      WHERE selected_operation.operation_id::text <> v_diagnostic_operation_id
    ) AS related_operation;
  ELSE
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := COALESCE(v_operation_ids, '[]'::jsonb);
  END IF;

  SELECT COALESCE(BOOL_OR(UPPER(BTRIM(COALESCE(selected_operation.operation_status, ''))) = 'REVIEW_REQUIRED'), false)
  INTO v_operation_review_required
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.chunk_id), '[]'::jsonb),
         MIN(selected_chunk.chunk_id::text),
         MIN(selected_chunk.started_at_utc)::text,
         MIN(selected_chunk.completed_at_utc)::text,
         MIN(selected_chunk.lock_expires_at_utc)::text
  INTO v_chunk_ids,
       v_primary_chunk_id,
       v_chunk_started_at_utc,
       v_chunk_completed_at_utc,
       v_chunk_lock_expires_at_utc
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
         MIN(selected_transfer.transfer_id::text),
         MIN(selected_transfer.rail_provider),
         MIN(selected_transfer.rail_env),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
  INTO v_transfer_ids,
       v_primary_transfer_id,
       v_primary_rail_provider,
       v_primary_rail_env,
       v_primary_rail_tx_id,
       v_primary_rail_state,
       v_primary_request_id
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT selected_source.provider_transaction_id,
         selected_source.provider_reference,
         selected_source.provider_state,
         COALESCE(selected_source.request_id, v_primary_request_id),
         COALESCE(selected_source.idempotency_key, v_primary_request_id),
         selected_source.local_provider_request_id,
         selected_source.provider_http_status,
         selected_source.provider_error_code,
         selected_source.provider_error_message_redacted,
         selected_source.provider_response_redacted,
         selected_source.provider_error_redacted,
         COALESCE(selected_source.provider_call_stage, v_provider_call_stage)
  INTO v_primary_provider_transaction_id,
       v_primary_provider_reference,
       v_primary_provider_state,
       v_primary_request_id,
       v_primary_idempotency_key,
       v_primary_local_provider_request_id,
       v_primary_provider_http_status,
       v_primary_provider_error_code,
       v_primary_provider_error_message_redacted,
       v_primary_provider_response_redacted,
       v_primary_provider_error_redacted,
       v_provider_call_stage
  FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
  WHERE NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.provider_reference, selected_source.provider_state, selected_source.provider_error_code, selected_source.request_id, selected_source.idempotency_key, selected_source.provider_call_stage, '')), '') IS NOT NULL
  ORDER BY CASE
             WHEN (
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) OR (
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) THEN 0
             WHEN selected_source.provider_response_present OR selected_source.provider_response_received THEN 1
             WHEN selected_source.provider_request_sent THEN 2
             ELSE 3
           END,
           selected_source.source_type
  LIMIT 1;

  IF v_primary_idempotency_key IS NULL THEN
    v_primary_idempotency_key := v_primary_request_id;
  END IF;

  IF v_primary_provider_reference IS NOT NULL
     AND v_primary_provider_reference IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_reference := NULL::text;
  END IF;

  IF v_primary_provider_transaction_id IS NOT NULL
     AND v_primary_provider_transaction_id IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_transaction_id := NULL::text;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(scope_values.transfer_scope_id::text) ORDER BY scope_values.transfer_scope_id), '[]'::jsonb),
         MIN(scope_values.transfer_scope_id::text)
  INTO v_transfer_scope_ids,
       v_primary_transfer_scope_id
  FROM (
    SELECT DISTINCT transfer_scope.id AS transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope
    WHERE (
        EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
          WHERE selected_operation.operation_id = transfer_scope.operation_id
        )
        OR (v_effective_pay_batch_id IS NOT NULL AND transfer_scope.pay_batch_id = v_effective_pay_batch_id)
      )
      AND (p_transfer_id IS NULL OR transfer_scope.pay_bank_transfer_id = p_transfer_id)
  ) AS scope_values;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_values.auth_request_id::text) ORDER BY auth_values.auth_request_id), '[]'::jsonb),
         MIN(auth_values.auth_request_id::text)
  INTO v_active_auth_request_count,
       v_auth_request_ids,
       v_primary_auth_request_id
  FROM (
    SELECT DISTINCT auth_request.id AS auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND (p_operation_id IS NULL OR auth_request.execution_intent_json->>'operation_id' = p_operation_id::text)
  ) AS auth_values;

  IF p_operation_id IS NULL
     AND p_transfer_id IS NULL
     AND p_chunk_id IS NULL
     AND v_effective_pay_batch_id IS NOT NULL
     AND COALESCE(v_transfer_count, 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_ids), 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_scope_ids), 0) = 0
     AND COALESCE(v_active_auth_request_count, 0) = 0
     AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     AND COALESCE(v_provider_response_present_count, 0) = 0
     AND COALESCE(v_provider_request_sent_count, 0) = 0
     AND COALESCE(v_provider_submission_unknown_count, 0) = 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0
     AND COALESCE(v_unfinalised_submit_chunk_count, 0) = 0
     AND COALESCE(v_provider_submission_rejected_count, 0) = 0
     AND COALESCE(v_provider_submission_malformed_response_count, 0) = 0
     AND COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
     AND NOT EXISTS (
       SELECT 1
       FROM public.pay_bank_transfer_events AS batch_provider_event
       WHERE batch_provider_event.pay_batch_id = v_effective_pay_batch_id
         AND upper(BTRIM(COALESCE(batch_provider_event.event_source, ''))) IN (
           'PROVIDER_RESPONSE',
           'PROVIDER_POLL',
           'PROVIDER_WEBHOOK',
           'WEBHOOK',
           'POLL',
           'RAIL_PROVIDER',
           'PROVIDER',
           'PROVIDER_SETTLEMENT',
           'RAIL_PROVIDER_SETTLEMENT'
         )
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
       LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS selected_chunk_flag
         ON selected_chunk_flag.chunk_id = selected_chunk.chunk_id
       WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'SKIPPED', 'CANCELLED', 'CANCELED')
          OR COALESCE(selected_chunk_flag.has_provider_blocked_pre_call, false) IS NOT TRUE
          OR COALESCE(selected_chunk_flag.has_provider_acceptance_evidence, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_request_sent, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_rejection, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_unknown, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_malformed_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_unresolved, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_request_sent_no_response, false) IS TRUE
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
       WHERE selected_source.provider_submission_attempted IS TRUE
          OR selected_source.provider_request_sent IS TRUE
          OR selected_source.provider_response_received IS TRUE
          OR selected_source.provider_response_present IS TRUE
          OR selected_source.provider_submission_accepted IS TRUE
          OR selected_source.provider_submission_rejected IS TRUE
          OR (
            selected_source.provider_submission_failed IS TRUE
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND selected_source.provider_submission_attempted IS NOT TRUE
              AND selected_source.provider_request_sent IS NOT TRUE
              AND selected_source.provider_response_received IS NOT TRUE
              AND selected_source.provider_response_present IS NOT TRUE
              AND selected_source.provider_submission_accepted IS NOT TRUE
              AND selected_source.provider_submission_rejected IS NOT TRUE
              AND selected_source.provider_submission_unknown IS NOT TRUE
              AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
              AND NULLIF(BTRIM(COALESCE(
                selected_source.provider_transaction_id,
                selected_source.rail_tx_id,
                selected_source.provider_reference,
                selected_source.provider_state,
                selected_source.provider_http_status,
                ''
              )), '') IS NULL
              AND (
                NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                  'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                  'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                )
              )
            )
          )
          OR selected_source.provider_submission_unknown IS TRUE
          OR selected_source.provider_acceptance_evidence_present IS TRUE
          OR upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN (
            'PROVIDER_SUBMISSION_ACCEPTED',
            'PROVIDER_SUBMISSION_REJECTED',
            'PROVIDER_SUBMISSION_FAILED',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
          )
          OR NULLIF(BTRIM(COALESCE(
            selected_source.provider_transaction_id,
            selected_source.rail_tx_id,
            selected_source.provider_reference,
            selected_source.provider_state,
            selected_source.provider_http_status,
            ''
          )), '') IS NOT NULL
          OR (
            NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NOT NULL
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
              )
            )
          )
     ) THEN
    v_batch_level_cleaned_local_blocked_pre_call_neutralised := true;

    v_operation_count := 0;
    v_chunk_count := 0;
    v_provider_submission_blocked_pre_call_count := 0;
    v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
    v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_accepted := false;
    v_provider_submission_rejected := false;
    v_provider_submission_failed := false;
    v_provider_submission_unknown := false;
    v_provider_acceptance_evidence_present := false;
    v_stale_submit_chunk := false;
    v_unfinalised_submit_chunk := false;
    v_chunk_lock_expired := false;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := false;
    v_retry_blocked_reason := NULL::text;
    v_recommended_action := 'No provider submission attempt has been recorded for this scope.';

    v_operation_ids := '[]'::jsonb;
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := '[]'::jsonb;
    v_diagnostic_operation_id := NULL::text;
    v_chunk_ids := '[]'::jsonb;
    v_primary_operation_id := NULL::text;
    v_primary_chunk_id := NULL::text;
    v_primary_request_id := NULL::text;
    v_primary_idempotency_key := NULL::text;
    v_primary_local_provider_request_id := NULL::text;
    v_primary_provider_http_status := NULL::text;
    v_primary_provider_error_code := NULL::text;
    v_primary_provider_error_message_redacted := NULL::text;
    v_primary_provider_response_redacted := NULL::jsonb;
    v_primary_provider_error_redacted := NULL::jsonb;
    v_chunk_started_at_utc := NULL::text;
    v_chunk_completed_at_utc := NULL::text;
    v_chunk_lock_expires_at_utc := NULL::text;
  END IF;

  v_provider_submit_actual_context := (
    COALESCE(v_operation_count, 0) > 0
    OR COALESCE(v_chunk_count, 0) > 0
    OR COALESCE(v_transfer_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
    OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_rejected_count, 0) > 0
    OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
  );

  v_mixed_provider_submit_outcome := (
    COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    AND (
      COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
      OR COALESCE(v_request_sent_no_response_count, 0) > 0
      OR (
        COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND (COALESCE(v_operation_review_required, false) IS TRUE OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0)
      )
      OR (
        COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
        AND (
          COALESCE(v_operation_review_required, false) IS TRUE
          OR COALESCE(v_provider_submission_unknown_count, 0) > 0
          OR COALESCE(v_provider_submission_rejected_count, 0) > 0
          OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
          OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        )
      )
    )
  );

  IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
    v_review_reason_code := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'PROVIDER_RESPONSE_RECEIVED');
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_accepted := true;
    v_provider_acceptance_evidence_present := true;
    v_stale_submit_chunk := COALESCE(v_stale_empty_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_recommended_action := 'Provider acceptance evidence exists. Do not retry unless reconciled.';
  ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
    v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
    v_recommended_action := 'Provider returned an unusable response. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0 THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_request_sent_no_response_count, 0) > 0
     OR (
       COALESCE(v_provider_request_sent_count, 0) > 0
       AND COALESCE(v_provider_response_present_count, 0) = 0
       AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     ) THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK');
    v_provider_submission_attempted := NULL::boolean;
    v_provider_request_sent := NULL::boolean;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := true;
    v_unfinalised_submit_chunk := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_recommended_action := 'Check Revolut/bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
  ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
    v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_rejected := true;
    v_provider_submission_failed := true;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
  ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
    v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_failed := true;
    v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
  END IF;

  IF COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE THEN
    v_review_reason_code := 'MIXED_PROVIDER_SUBMIT_OUTCOME';
    v_provider_submission_unknown := true;
    v_provider_submission_rejected := COALESCE(v_provider_submission_rejected_count, 0) > 0;
    v_provider_submission_failed := COALESCE(v_provider_submission_rejected_count, 0) > 0 OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_MIXED_OUTCOME';
    v_recommended_action := 'Provider acceptance evidence exists for at least one transfer, but not all provider-submit outcomes are resolved. Reconcile accepted provider transfer(s) and unresolved/rejected/malformed transfer(s) before retry.';
  END IF;

  v_payment_provider_review_required := (
    COALESCE(v_provider_submit_actual_context, false) IS TRUE
    AND v_provider_submission_status <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
    AND (
      COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE
      OR v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
        'PROVIDER_SUBMISSION_REJECTED',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      )
      OR (
        v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
        AND COALESCE(v_operation_review_required, false) IS TRUE
      )
    )
  );

  v_counts := jsonb_build_object(
    'operation_count', COALESCE(v_operation_count, 0),
    'chunk_count', COALESCE(v_chunk_count, 0),
    'transfer_count', COALESCE(v_transfer_count, 0),
    'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
    'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'operation_review_required', COALESCE(v_operation_review_required, false),
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
  );

  v_ids := jsonb_build_object(
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
    'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
    'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
    'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
  );

  v_provider_submit_diagnostic := jsonb_build_object(
    'diagnostic_version', 1,
    'generated_at_utc', v_now::text,
    'review_reason_code', v_review_reason_code,
    'provider_submission_status', v_provider_submission_status,
    'provider_call_stage', v_provider_call_stage,
    'provider_submission_attempted', v_provider_submission_attempted,
    'provider_request_sent', v_provider_request_sent,
    'provider_response_received', v_provider_response_received,
    'provider_response_present', v_provider_response_present,
    'provider_submission_accepted', v_provider_submission_accepted,
    'provider_submission_rejected', v_provider_submission_rejected,
    'provider_submission_failed', v_provider_submission_failed,
    'provider_submission_unknown', v_provider_submission_unknown,
    'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'stale_submit_chunk', v_stale_submit_chunk,
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
    'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
    'chunk_started_at_utc', v_chunk_started_at_utc,
    'chunk_completed_at_utc', v_chunk_completed_at_utc
  )
  || jsonb_build_object(
    'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'automatic_retry_blocked', v_automatic_retry_blocked,
    'retry_blocked_reason', v_retry_blocked_reason,
    'recommended_action', v_recommended_action,
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_id', v_primary_chunk_id,
    'chunk_ids', v_chunk_ids,
    'transfer_id', v_primary_transfer_id,
    'transfer_ids', v_transfer_ids,
    'transfer_scope_id', v_primary_transfer_scope_id,
    'transfer_scope_ids', v_transfer_scope_ids,
    'auth_request_id', v_primary_auth_request_id,
    'auth_request_ids', v_auth_request_ids,
    'rail_provider', v_primary_rail_provider,
    'rail_env', v_primary_rail_env,
    'rail_tx_id', v_primary_rail_tx_id,
    'rail_state', v_primary_rail_state,
    'provider_transaction_id', v_primary_provider_transaction_id,
    'provider_reference', v_primary_provider_reference,
    'provider_state', v_primary_provider_state,
    'request_id', v_primary_request_id,
    'idempotency_key', v_primary_idempotency_key,
    'local_provider_request_id', v_primary_local_provider_request_id,
    'provider_http_status', v_primary_provider_http_status,
    'provider_error_code', v_primary_provider_error_code,
    'provider_error_message_redacted', v_primary_provider_error_message_redacted,
    'provider_response_redacted', v_primary_provider_response_redacted,
    'provider_error_redacted', v_primary_provider_error_redacted
  );

  RETURN jsonb_build_object(
    'ok', true,
    'provider_submit_diagnostic', v_provider_submit_diagnostic,
    'provider_submission_status', v_provider_submission_status,
    'review_reason_code', v_review_reason_code,
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'recommended_action', v_recommended_action,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'counts', v_counts,
    'ids', v_ids,
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
    'counts_only', COALESCE(p_counts_only, false)
  );

END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_diagnostic_finalise(
  p_operation_id uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_chunk_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_reason_code text DEFAULT NULL::text,
  p_failure_error_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_reason_code text := upper(btrim(coalesce(p_reason_code, 'PROVIDER_CHUNK_FINALISE')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_effective_pay_batch_id uuid := NULL::uuid;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_accepted_count integer := 0;
  v_rejected_count integer := 0;
  v_unknown_count integer := 0;
  v_review_required_count integer := 0;
  v_remaining_running_count integer := 0;
  v_provider_message text := NULL::text;
  v_chunk_finish_status text := 'COMPLETE';
  v_manual_review_required boolean := false;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_result_json jsonb := '{}'::jsonb;
  v_error_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_failure_error_json IS NOT NULL AND jsonb_typeof(p_failure_error_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_ERROR_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_ERROR_JSON_MUST_BE_OBJECT')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  v_effective_pay_batch_id := coalesce(p_pay_batch_id, v_operation_row.pay_batch_id);

  IF v_effective_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_effective_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', v_effective_pay_batch_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text)::text;
  END IF;

  SELECT chunk_row.*
  INTO v_chunk_row
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.id = p_chunk_id
    AND chunk_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_NOT_FOUND', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  IF NOT (upper(btrim(coalesce(v_chunk_row.phase, ''))) = 'SUBMIT_PROVIDER_TRANSFERS' OR upper(btrim(coalesce(v_chunk_row.chunk_type, ''))) = 'TRANSFER_SUBMIT') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_NOT_PROVIDER_SUBMIT_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_NOT_PROVIDER_SUBMIT_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text, 'phase', v_chunk_row.phase, 'chunk_type', v_chunk_row.chunk_type)::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_finalise_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_finalise_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         upper(btrim(coalesce(scope_row.provider_submit_state, ''))) AS provider_submit_state,
         coalesce(scope_row.provider_review_required, false) AS provider_review_required,
         scope_row.provider_unsafe_reason,
         upper(btrim(coalesce(scope_row.status, ''))) AS scope_status
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_effective_pay_batch_id
    AND scope_row.provider_submit_chunk_id = p_chunk_id
  FOR UPDATE;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE finalise_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state IN ('PROVIDER_ACCEPTED', 'CHUNK_FINALISED') OR finalise_scope.scope_status IN ('SUBMITTED', 'COMPLETED'))::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state = 'PROVIDER_REJECTED')::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state = 'PROVIDER_UNKNOWN')::integer,
         count(*) FILTER (WHERE finalise_scope.provider_review_required IS TRUE OR finalise_scope.provider_submit_state = 'REVIEW_REQUIRED')::integer,
         coalesce(jsonb_agg(to_jsonb(finalise_scope.transfer_scope_id::text) ORDER BY finalise_scope.transfer_scope_id), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_accepted_count,
       v_rejected_count,
       v_unknown_count,
       v_review_required_count,
       v_transfer_scope_ids
  FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope;

  IF coalesce(v_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_NO_SCOPE_FOR_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_NO_SCOPE_FOR_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  v_manual_review_required := coalesce(v_review_required_count, 0) > 0 OR coalesce(v_unknown_count, 0) > 0;
  v_provider_message := nullif(btrim(coalesce(
    p_failure_error_json->>'message',
    p_failure_error_json->>'provider_error_message_redacted',
    v_chunk_row.result_json->>'message',
    v_chunk_row.error_json->>'message',
    NULL::text
  )), '');

  IF coalesce(v_rejected_count, 0) > 0 OR coalesce(v_unknown_count, 0) > 0 OR coalesce(v_review_required_count, 0) > 0 THEN
    v_chunk_finish_status := 'FAILED';
  ELSE
    v_chunk_finish_status := 'COMPLETE';
  END IF;

  v_result_json := jsonb_strip_nulls(
    coalesce(v_chunk_row.result_json, '{}'::jsonb)
    || jsonb_build_object(
      'provider_chunk_finalised', true,
      'provider_chunk_finalised_at_utc', v_now::text,
      'provider_chunk_finalise_reason_code', v_reason_code,
      'transfer_scope_count', coalesce(v_scope_count, 0),
      'transfer_count', coalesce(v_transfer_count, 0),
      'accepted_count', coalesce(v_accepted_count, 0),
      'rejected_count', coalesce(v_rejected_count, 0),
      'unknown_count', coalesce(v_unknown_count, 0),
      'review_required_count', coalesce(v_review_required_count, 0),
      'last_provider_message', v_provider_message
    )
  );

  v_error_json := CASE
    WHEN v_chunk_finish_status = 'FAILED' THEN jsonb_strip_nulls(
      coalesce(v_chunk_row.error_json, '{}'::jsonb)
      || jsonb_build_object(
        'code', CASE WHEN v_manual_review_required THEN 'PROVIDER_CHUNK_REVIEW_REQUIRED' ELSE 'PROVIDER_CHUNK_REJECTED' END,
        'message', coalesce(v_provider_message, 'Provider chunk requires review or failed outcome handling.'),
        'provider_chunk_finalised_at_utc', v_now::text,
        'provider_chunk_finalise_reason_code', v_reason_code,
        'failure_error_json', coalesce(p_failure_error_json, '{}'::jsonb)
      )
    )
    ELSE v_chunk_row.error_json
  END;

  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET status = v_chunk_finish_status,
      result_json = v_result_json,
      error_json = v_error_json,
      completed_count = CASE WHEN v_chunk_finish_status = 'COMPLETE' THEN greatest(coalesce(chunk_update.completed_count, 0), coalesce(v_transfer_count, chunk_update.unit_count, 0)) ELSE coalesce(chunk_update.completed_count, 0) END,
      failed_count = CASE WHEN v_chunk_finish_status = 'FAILED' THEN greatest(coalesce(chunk_update.failed_count, 0), greatest(coalesce(v_rejected_count, 0) + coalesce(v_unknown_count, 0) + coalesce(v_review_required_count, 0), 1)) ELSE coalesce(chunk_update.failed_count, 0) END,
      completed_at_utc = coalesce(chunk_update.completed_at_utc, v_now),
      updated_at_utc = v_now
  WHERE chunk_update.id = p_chunk_id
    AND chunk_update.operation_id = p_operation_id;

  IF v_chunk_finish_status = 'FAILED' OR v_manual_review_required THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET provider_review_required = true,
        provider_submit_ready = false,
        provider_submit_state = CASE
          WHEN upper(btrim(coalesce(scope_update.provider_submit_state, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN scope_update.provider_submit_state
          ELSE 'REVIEW_REQUIRED'
        END,
        provider_unsafe_reason = coalesce(nullif(btrim(scope_update.provider_unsafe_reason), ''), CASE WHEN coalesce(v_unknown_count, 0) > 0 THEN 'PROVIDER_UNKNOWN' ELSE 'PROVIDER_CHUNK_FINALISE_FAILED' END),
        updated_at_utc = v_now
    WHERE scope_update.id IN (SELECT finalise_scope.transfer_scope_id FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope)
      AND scope_update.operation_id = p_operation_id;

    UPDATE public.banking_pay_operations AS operation_update
    SET status = 'REVIEW_REQUIRED',
        runner_state = 'REVIEW_REQUIRED',
        requires_user_action = true,
        resume_reason = coalesce(nullif(btrim(operation_update.resume_reason), ''), 'PROVIDER_CHUNK_REVIEW_REQUIRED'),
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_provider_chunk_finalised_at_utc', v_now::text,
          'last_provider_chunk_id', p_chunk_id::text,
          'last_provider_chunk_status', v_chunk_finish_status,
          'last_provider_message', v_provider_message,
          'provider_review_required', true
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;
  ELSE
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET provider_submit_state = CASE WHEN upper(btrim(coalesce(scope_update.provider_submit_state, ''))) = 'PROVIDER_ACCEPTED' THEN 'CHUNK_FINALISED' ELSE scope_update.provider_submit_state END,
        updated_at_utc = v_now
    WHERE scope_update.id IN (SELECT finalise_scope.transfer_scope_id FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope)
      AND scope_update.operation_id = p_operation_id;

    SELECT count(*)::integer
    INTO v_remaining_running_count
    FROM public.banking_pay_operation_chunks AS remaining_chunk
    WHERE remaining_chunk.operation_id = p_operation_id
      AND (remaining_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR remaining_chunk.chunk_type = 'TRANSFER_SUBMIT')
      AND upper(btrim(coalesce(remaining_chunk.status, ''))) IN ('PENDING', 'RUNNING');

    UPDATE public.banking_pay_operations AS operation_update
    SET runner_state = CASE WHEN coalesce(v_remaining_running_count, 0) > 0 THEN operation_update.runner_state ELSE 'RUNNABLE' END,
        run_after_utc = CASE WHEN coalesce(v_remaining_running_count, 0) > 0 THEN operation_update.run_after_utc ELSE v_now END,
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_provider_chunk_finalised_at_utc', v_now::text,
          'last_provider_chunk_id', p_chunk_id::text,
          'last_provider_chunk_status', v_chunk_finish_status,
          'remaining_provider_submit_chunk_count', coalesce(v_remaining_running_count, 0)
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_effective_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'finalised_chunk_count', 1,
    'finalised_chunk_ids', jsonb_build_array(p_chunk_id::text),
    'chunk_status', v_chunk_finish_status,
    'provider_submit_diagnostic_used', false,
    'operation_wide_finalise', false,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
    'transfer_scope_count', coalesce(v_scope_count, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'accepted_count', coalesce(v_accepted_count, 0),
    'rejected_count', coalesce(v_rejected_count, 0),
    'unknown_count', coalesce(v_unknown_count, 0),
    'review_required_count', coalesce(v_review_required_count, 0),
    'manual_resolution_required', coalesce(v_manual_review_required, false),
    'last_provider_message', v_provider_message,
    'reason_code', v_reason_code,
    'server_utc', v_now::text
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_execute_provider_submit_review_resolve(
  p_pay_batch_id uuid,
  p_operation_id uuid,
  p_resolution_action text,
  p_confirmation_json jsonb,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_resolution_action text := upper(btrim(coalesce(p_resolution_action, '')));
  v_confirmation_json jsonb := '{}'::jsonb;
  v_checked_provider_or_bank boolean := false;
  v_confirmed_no_payment_made boolean := false;
  v_provider_checked text := NULL::text;
  v_checked_at_text text := NULL::text;
  v_checked_at_utc timestamptz := NULL::timestamptz;
  v_notes text := NULL::text;
  v_confirmation_redacted jsonb := '{}'::jsonb;
  v_chunk_id uuid := NULL::uuid;
  v_requested_scope_count integer := 0;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_reset_scope_count integer := 0;
  v_reset_transfer_count integer := 0;
  v_chunk_rows_updated integer := 0;
  v_remaining_review_scope_count integer := 0;
  v_remaining_ready_scope_count integer := 0;
  v_attempt_rows integer := 0;
  v_resolved_transfer_scope_ids jsonb := '[]'::jsonb;
  v_resolved_transfer_ids jsonb := '[]'::jsonb;
  v_backend_work_remaining boolean := false;
  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_pay_batch_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_operation_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_actor_user_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_resolution_action <> 'CONFIRM_NO_PAYMENT_MADE_AND_RESET_FOR_RETRY' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'UNSUPPORTED_RESOLUTION_ACTION',
      'message', 'Unsupported provider-submit review resolution action',
      'resolution_action', coalesce(p_resolution_action, '')
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_confirmation_json IS NULL OR jsonb_typeof(p_confirmation_json) <> 'object' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'CONFIRMATION_JSON_REQUIRED',
      'message', 'p_confirmation_json must be a JSON object'
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_confirmation_json := p_confirmation_json;
  v_checked_provider_or_bank := lower(btrim(coalesce(v_confirmation_json->>'checked_provider_or_bank', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_confirmed_no_payment_made := lower(btrim(coalesce(v_confirmation_json->>'confirmed_no_payment_made', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_checked := upper(btrim(coalesce(v_confirmation_json->>'provider_checked', '')));
  v_checked_at_text := NULLIF(btrim(coalesce(v_confirmation_json->>'checked_at_utc', '')), '');
  v_notes := NULLIF(btrim(coalesce(v_confirmation_json->>'notes', '')), '');

  IF COALESCE(v_confirmation_json->>'chunk_id', v_confirmation_json->>'provider_chunk_id', '') ~* v_uuid_regex THEN
    v_chunk_id := COALESCE(v_confirmation_json->>'chunk_id', v_confirmation_json->>'provider_chunk_id')::uuid;
  END IF;

  IF v_checked_at_text IS NOT NULL THEN
    BEGIN
      v_checked_at_utc := v_checked_at_text::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
        'code', 'CHECKED_AT_UTC_INVALID',
        'checked_at_utc', v_checked_at_text
      )::text USING ERRCODE = 'P0001';
    END;
  ELSE
    v_checked_at_utc := v_now;
  END IF;

  IF v_checked_provider_or_bank IS NOT TRUE OR v_confirmed_no_payment_made IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PROVIDER_REVIEW_CONFIRMATION_REQUIRED',
      'message', 'Resolution requires confirmation that the provider/bank was checked and no payment was made.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'ACTOR_USER_NOT_ACTIVE',
      'actor_user_id', p_actor_user_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_NOT_FOUND',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_BATCH_MISMATCH',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', v_operation_row.pay_batch_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_TYPE_NOT_SUPPORTED',
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_review_resolve_scope_request;
  CREATE TEMPORARY TABLE pg_temp.tmp_review_resolve_scope_request (
    transfer_scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  IF v_chunk_id IS NOT NULL THEN
    INSERT INTO pg_temp.tmp_review_resolve_scope_request (transfer_scope_id)
    SELECT scope_row.id
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND scope_row.provider_submit_chunk_id = v_chunk_id
    ORDER BY scope_row.id
    LIMIT 100
    ON CONFLICT DO NOTHING;
  END IF;

  IF jsonb_typeof(v_confirmation_json->'transfer_scope_ids') = 'array' THEN
    INSERT INTO pg_temp.tmp_review_resolve_scope_request (transfer_scope_id)
    SELECT DISTINCT scope_id_value.scope_id_text::uuid
    FROM (
      SELECT scope_value.value #>> '{}' AS scope_id_text
      FROM jsonb_array_elements(v_confirmation_json->'transfer_scope_ids') AS scope_value(value)
    ) AS scope_id_value
    WHERE scope_id_value.scope_id_text ~* v_uuid_regex
    LIMIT 100
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_requested_scope_count
  FROM pg_temp.tmp_review_resolve_scope_request AS requested_scope;

  IF v_requested_scope_count <= 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_REQUIRED',
      'message', 'Review resolution requires a provider chunk id or capped transfer_scope_ids.',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_requested_scope_count > 100 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_TOO_LARGE',
      'scope_count', v_requested_scope_count,
      'limit', 100
    )::text USING ERRCODE = 'P0001';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_review_resolve_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_review_resolve_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         scope_row.provider_submit_state AS previous_provider_submit_state,
         scope_row.provider_idempotency_key,
         scope_row.provider_request_id,
         scope_row.provider_transaction_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_review_resolve_scope_request AS requested_scope
    ON requested_scope.transfer_scope_id = scope_row.id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
  FOR UPDATE OF scope_row;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE resolve_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         COALESCE(jsonb_agg(to_jsonb(resolve_scope.transfer_scope_id::text) ORDER BY resolve_scope.transfer_scope_id), '[]'::jsonb),
         COALESCE(jsonb_agg(to_jsonb(resolve_scope.pay_bank_transfer_id::text) ORDER BY resolve_scope.pay_bank_transfer_id) FILTER (WHERE resolve_scope.pay_bank_transfer_id IS NOT NULL), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_resolved_transfer_scope_ids,
       v_resolved_transfer_ids
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope;

  IF v_scope_count <> v_requested_scope_count THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_NOT_FOUND_OR_NOT_IN_OPERATION',
      'requested_scope_count', v_requested_scope_count,
      'matched_scope_count', v_scope_count,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_confirmation_redacted := jsonb_strip_nulls(v_confirmation_json
    - 'account_number'
    - 'sort_code'
    - 'iban'
    - 'access_token'
    - 'authorization'
    || jsonb_build_object(
      'checked_provider_or_bank', v_checked_provider_or_bank,
      'confirmed_no_payment_made', v_confirmed_no_payment_made,
      'provider_checked', NULLIF(v_provider_checked, ''),
      'checked_at_utc', v_checked_at_utc::text,
      'notes_present', v_notes IS NOT NULL,
      'actor_user_id', p_actor_user_id::text
    )
  );

  UPDATE public.pay_bank_transfers AS transfer_update
  SET status = 'PENDING',
      rail_tx_id = NULL::text,
      rail_state = NULL::text,
      completed_at_utc = NULL::timestamptz,
      failed_reason = NULL::text,
      rail_meta_json = jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'manual_provider_review_resolved_at_utc', v_now::text,
        'manual_provider_review_resolution', 'CONFIRMED_NO_PAYMENT_MADE',
        'manual_provider_review_actor_user_id', p_actor_user_id::text,
        'manual_provider_review_operation_id', p_operation_id::text,
        'manual_provider_review_chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'manual_provider_review_checked_at_utc', v_checked_at_utc::text,
        'provider_submit_diagnostic', jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object(
          'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
          'review_reason_code', 'MANUAL_CONFIRMED_NO_PAYMENT_MADE',
          'manual_resolution_required', false,
          'manual_resolution_at_utc', v_now::text,
          'manual_resolution_actor_user_id', p_actor_user_id::text
        ))
      ))
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  WHERE transfer_update.id = resolve_scope.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_reset_transfer_count = ROW_COUNT;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = 'READY',
      provider_submit_ready = true,
      provider_submit_chunk_id = NULL::uuid,
      provider_submit_claimed_at_utc = NULL::timestamptz,
      provider_request_prepared_at_utc = NULL::timestamptz,
      provider_request_sending_at_utc = NULL::timestamptz,
      provider_request_sent_at_utc = NULL::timestamptz,
      provider_response_at_utc = NULL::timestamptz,
      provider_submission_status = 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
      provider_review_required = false,
      provider_unsafe_reason = NULL::text,
      status = 'PREPARED',
      updated_at_utc = v_now
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  WHERE scope_update.id = resolve_scope.transfer_scope_id
    AND scope_update.operation_id = p_operation_id
    AND scope_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_reset_scope_count = ROW_COUNT;

  IF v_chunk_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET status = 'COMPLETE',
        result_json = jsonb_strip_nulls(COALESCE(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
          'manual_review_resolved', true,
          'manual_review_resolved_at_utc', v_now::text,
          'resolution_action', v_resolution_action,
          'confirmation', v_confirmation_redacted,
          'resolved_transfer_scope_count', COALESCE(v_reset_scope_count, 0),
          'resolved_transfer_count', COALESCE(v_reset_transfer_count, 0)
        )),
        error_json = NULL::jsonb,
        completed_at_utc = COALESCE(chunk_update.completed_at_utc, v_now),
        updated_at_utc = v_now
    WHERE chunk_update.id = v_chunk_id
      AND chunk_update.operation_id = p_operation_id;
    GET DIAGNOSTICS v_chunk_rows_updated = ROW_COUNT;
  END IF;

  SELECT count(*)::integer
  INTO v_attempt_rows
  FROM (
    SELECT public.banking_pay_operation_provider_attempt_record(
      p_operation_id => p_operation_id,
      p_pay_batch_id => p_pay_batch_id,
      p_transfer_scope_id => resolve_scope.transfer_scope_id,
      p_provider_chunk_id => v_chunk_id,
      p_idempotency_key => resolve_scope.provider_idempotency_key,
      p_request_id => resolve_scope.provider_request_id,
      p_provider_transaction_id => resolve_scope.provider_transaction_id,
      p_previous_state => resolve_scope.previous_provider_submit_state,
      p_new_state => 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
      p_lease_owner => NULL::text,
      p_request_json => NULL::jsonb,
      p_response_json => NULL::jsonb,
      p_error_json => jsonb_build_object('manual_review_resolution', v_confirmation_redacted),
      p_actor_user_id => p_actor_user_id
    ) AS attempt_result
    FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  ) AS attempt_calls;

  SELECT count(*)::integer
  INTO v_remaining_review_scope_count
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND (
      coalesce(scope_row.provider_review_required, false) = true
      OR upper(btrim(coalesce(scope_row.provider_submit_state, ''))) IN ('PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'PROVIDER_REJECTED')
    );

  SELECT count(*)::integer
  INTO v_remaining_ready_scope_count
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
    AND coalesce(scope_row.provider_submit_ready, false) = true
    AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY';

  v_backend_work_remaining := COALESCE(v_remaining_review_scope_count, 0) = 0 AND COALESCE(v_remaining_ready_scope_count, 0) > 0;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'REVIEW_REQUIRED' ELSE 'RUNNING' END,
      runner_state = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'WAITING_USER_REVIEW' ELSE 'RUNNABLE' END,
      requires_user_action = COALESCE(v_remaining_review_scope_count, 0) > 0,
      run_after_utc = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN NULL::timestamptz ELSE v_now END,
      resume_reason = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'PROVIDER_REVIEW_REMAINS' ELSE 'PROVIDER_REVIEW_RESOLVED_CONTINUE_EXECUTION' END,
      progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'provider_review_resolved_at_utc', v_now::text,
        'provider_review_resolution_action', v_resolution_action,
        'provider_review_resolved_scope_count', COALESCE(v_reset_scope_count, 0),
        'provider_review_remaining_scope_count', COALESCE(v_remaining_review_scope_count, 0),
        'provider_ready_scope_count_after_review', COALESCE(v_remaining_ready_scope_count, 0),
        'next_required_phase', CASE WHEN COALESCE(v_remaining_ready_scope_count, 0) > 0 THEN 'CLAIM_PROVIDER_SUBMIT_CHUNK' ELSE operation_update.progress_json->>'next_required_phase' END
      )),
      error_json = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) = 0 THEN NULL::jsonb ELSE operation_update.error_json END,
      locked_by = NULL::text,
      lock_expires_at_utc = NULL::timestamptz,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  BEGIN
    PERFORM public.pay_batch_display_summary_touch(p_pay_batch_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    PERFORM public.banking_pay_batch_signal_touch(
      p_pay_batch_id,
      'PROVIDER_SUBMIT_REVIEW_RESOLVED',
      'pay_execute_provider_submit_review_resolve',
      jsonb_strip_nulls(jsonb_build_object(
        'operation_id', p_operation_id::text,
        'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'resolution_action', v_resolution_action,
        'resolved_scope_count', COALESCE(v_reset_scope_count, 0),
        'remaining_review_scope_count', COALESCE(v_remaining_review_scope_count, 0)
      )),
      true,
      false,
      COALESCE(v_remaining_review_scope_count, 0) > 0,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  v_result := jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'manual_review_resolved', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
    'resolution_action', v_resolution_action,
    'resolution_scope', CASE WHEN v_chunk_id IS NOT NULL THEN 'PROVIDER_CHUNK' ELSE 'TRANSFER_SCOPE_IDS' END,
    'confirmed_no_payment_made', v_confirmed_no_payment_made,
    'checked_provider_or_bank', v_checked_provider_or_bank,
    'provider_checked', NULLIF(v_provider_checked, ''),
    'checked_at_utc', v_checked_at_utc::text,
    'notes_present', v_notes IS NOT NULL,
    'resolved_transfer_scope_ids', COALESCE(v_resolved_transfer_scope_ids, '[]'::jsonb),
    'resolved_transfer_ids', COALESCE(v_resolved_transfer_ids, '[]'::jsonb),
    'resolved_transfer_scope_count', COALESCE(v_reset_scope_count, 0),
    'resolved_transfer_count', COALESCE(v_reset_transfer_count, 0),
    'chunk_rows_updated', COALESCE(v_chunk_rows_updated, 0),
    'provider_attempt_rows_recorded', COALESCE(v_attempt_rows, 0),
    'remaining_review_scope_count', COALESCE(v_remaining_review_scope_count, 0),
    'provider_ready_scope_count_after_review', COALESCE(v_remaining_ready_scope_count, 0),
    'backend_work_remaining', COALESCE(v_backend_work_remaining, false),
    'operation_runnable', COALESCE(v_remaining_review_scope_count, 0) = 0,
    'server_utc', v_now::text
  ));

  RETURN v_result;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_stage_record(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_chunk_id uuid,
  p_transfer_ids jsonb DEFAULT '[]'::jsonb,
  p_stage text DEFAULT NULL::text,
  p_provider_submit_diagnostic jsonb DEFAULT '{}'::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_stage text := upper(btrim(coalesce(p_stage, p_provider_submit_diagnostic->>'stage', p_provider_submit_diagnostic->>'provider_call_stage', '')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_diag jsonb := '{}'::jsonb;
  v_transfer_scope_ids_json jsonb := '[]'::jsonb;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_new_chunk_status text := 'RUNNING';
  v_scope_provider_state text := NULL::text;
  v_transfer_rail_state text := NULL::text;
  v_provider_transaction_id text := NULL::text;
  v_request_id text := NULL::text;
  v_idempotency_key text := NULL::text;
  v_provider_error_json jsonb := NULL::jsonb;
  v_provider_response_json jsonb := NULL::jsonb;
  v_attempt_state text := NULL::text;
  v_attempt_rows integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_CHUNK_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_CHUNK_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_provider_submit_diagnostic IS NOT NULL AND jsonb_typeof(p_provider_submit_diagnostic) <> 'object' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_DIAGNOSTIC_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_DIAGNOSTIC_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_stage IS NULL OR v_stage = '' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_stage NOT IN (
    'CLAIMED',
    'REQUEST_PREPARING',
    'REQUEST_SENDING',
    'REQUEST_SENT_LOCAL',
    'PROVIDER_ACCEPTED',
    'PROVIDER_REJECTED',
    'PROVIDER_UNKNOWN',
    'REVIEW_REQUIRED',
    'CHUNK_FINALISED'
  ) THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_INVALID', 'operation_id', p_operation_id::text, 'stage', v_stage)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NULL OR v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT chunk_row.*
  INTO v_chunk_row
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.id = p_chunk_id
    AND chunk_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_CHUNK_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_CHUNK_NOT_FOUND', 'chunk_id', p_chunk_id::text)::text;
  END IF;

  IF NOT (upper(btrim(coalesce(v_chunk_row.phase, ''))) = 'SUBMIT_PROVIDER_TRANSFERS' OR upper(btrim(coalesce(v_chunk_row.chunk_type, ''))) = 'TRANSFER_SUBMIT') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_NOT_TRANSFER_SUBMIT_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_NOT_TRANSFER_SUBMIT_CHUNK', 'chunk_id', p_chunk_id::text, 'phase', v_chunk_row.phase, 'chunk_type', v_chunk_row.chunk_type)::text;
  END IF;

  v_diag := coalesce(p_provider_submit_diagnostic, '{}'::jsonb)
    - 'access_token'
    - 'authorization'
    - 'Authorization'
    - 'bearer_token'
    - 'token'
    - 'account_number'
    - 'sort_code'
    - 'iban'
    - 'source_account_number'
    - 'beneficiary_account_number';

  DROP TABLE IF EXISTS pg_temp.tmp_provider_stage_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_stage_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         scope_row.provider_submit_state AS previous_state,
         COALESCE(NULLIF(BTRIM(scope_row.provider_idempotency_key), ''), NULLIF(BTRIM(transfer_row.request_id), ''), 'scope:' || scope_row.id::text) AS provider_idempotency_key,
         COALESCE(NULLIF(BTRIM(scope_row.provider_request_id), ''), NULLIF(BTRIM(transfer_row.request_id), '')) AS provider_request_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = scope_row.pay_bank_transfer_id
   AND transfer_row.pay_batch_id = scope_row.pay_batch_id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND scope_row.provider_submit_chunk_id = p_chunk_id
  FOR UPDATE OF scope_row, transfer_row;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE stage_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         coalesce(jsonb_agg(to_jsonb(stage_scope.transfer_scope_id::text) ORDER BY stage_scope.transfer_scope_id), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_transfer_scope_ids_json
  FROM pg_temp.tmp_provider_stage_scope AS stage_scope;

  IF coalesce(v_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_NO_SCOPE_FOR_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_NO_SCOPE_FOR_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  v_provider_transaction_id := nullif(btrim(coalesce(v_diag->>'provider_transaction_id', v_diag->>'provider_payment_id', v_diag->>'rail_tx_id', '')), '');
  v_request_id := nullif(btrim(coalesce(v_diag->>'request_id', v_diag->>'local_provider_request_id', '')), '');
  v_idempotency_key := nullif(btrim(coalesce(v_diag->>'idempotency_key', v_request_id, '')), '');
  v_provider_response_json := CASE WHEN jsonb_typeof(v_diag->'provider_response_redacted') = 'object' THEN v_diag->'provider_response_redacted' ELSE NULL::jsonb END;
  v_provider_error_json := CASE WHEN jsonb_typeof(v_diag->'provider_error_redacted') = 'object' THEN v_diag->'provider_error_redacted' ELSE NULL::jsonb END;

  v_scope_provider_state := v_stage;
  v_transfer_rail_state := CASE v_stage
    WHEN 'PROVIDER_ACCEPTED' THEN 'ACCEPTED'
    WHEN 'PROVIDER_REJECTED' THEN 'REJECTED'
    WHEN 'PROVIDER_UNKNOWN' THEN 'UNKNOWN'
    WHEN 'REQUEST_SENT_LOCAL' THEN 'REQUEST_SENT_LOCAL'
    WHEN 'REQUEST_SENDING' THEN 'REQUEST_SENDING'
    ELSE NULL::text
  END;

  v_new_chunk_status := CASE
    WHEN v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED') THEN 'COMPLETE'
    ELSE 'RUNNING'
  END;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = v_scope_provider_state,
      provider_submit_ready = false,
      provider_review_required = v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED'),
      provider_unsafe_reason = CASE
        WHEN v_stage = 'PROVIDER_REJECTED' THEN 'PROVIDER_REJECTED'
        WHEN v_stage = 'PROVIDER_UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        WHEN v_stage = 'REVIEW_REQUIRED' THEN coalesce(nullif(btrim(v_diag->>'review_reason_code'), ''), 'REVIEW_REQUIRED')
        ELSE NULL::text
      END,
      provider_idempotency_key = COALESCE(v_idempotency_key, scope_update.provider_idempotency_key),
      provider_request_id = COALESCE(v_request_id, scope_update.provider_request_id),
      provider_transaction_id = CASE WHEN v_stage = 'PROVIDER_ACCEPTED' THEN COALESCE(v_provider_transaction_id, scope_update.provider_transaction_id) ELSE scope_update.provider_transaction_id END,
      provider_request_prepared_at_utc = CASE WHEN v_stage = 'REQUEST_PREPARING' THEN COALESCE(scope_update.provider_request_prepared_at_utc, v_now) ELSE scope_update.provider_request_prepared_at_utc END,
      provider_request_sending_at_utc = CASE WHEN v_stage = 'REQUEST_SENDING' THEN COALESCE(scope_update.provider_request_sending_at_utc, v_now) ELSE scope_update.provider_request_sending_at_utc END,
      provider_request_sent_at_utc = CASE WHEN v_stage IN ('REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN') THEN COALESCE(scope_update.provider_request_sent_at_utc, v_now) ELSE scope_update.provider_request_sent_at_utc END,
      provider_response_at_utc = CASE WHEN v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN') THEN COALESCE(scope_update.provider_response_at_utc, v_now) ELSE scope_update.provider_response_at_utc END,
      provider_submission_status = v_stage,
      status = CASE
        WHEN v_stage = 'PROVIDER_ACCEPTED' THEN 'SUBMITTED'
        WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'FAILED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.id IN (SELECT stage_scope.transfer_scope_id FROM pg_temp.tmp_provider_stage_scope AS stage_scope);

  UPDATE public.pay_bank_transfers AS transfer_update
  SET request_id = coalesce(nullif(btrim(transfer_update.request_id), ''), v_request_id),
      rail_tx_id = CASE WHEN v_stage = 'PROVIDER_ACCEPTED' THEN coalesce(nullif(btrim(transfer_update.rail_tx_id), ''), v_provider_transaction_id) ELSE transfer_update.rail_tx_id END,
      rail_state = coalesce(v_transfer_rail_state, transfer_update.rail_state),
      rail_meta_json = jsonb_strip_nulls(coalesce(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'provider_stage', v_stage,
        'provider_stage_recorded_at_utc', v_now::text,
        'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
        'request_id_present', v_request_id IS NOT NULL,
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text
      )),
      failed_reason = CASE WHEN v_stage = 'PROVIDER_REJECTED' THEN coalesce(nullif(btrim(v_diag->>'provider_error_message_redacted'), ''), 'PROVIDER_REJECTED') ELSE transfer_update.failed_reason END
  FROM pg_temp.tmp_provider_stage_scope AS stage_scope
  WHERE transfer_update.id = stage_scope.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET status = v_new_chunk_status,
      result_json = jsonb_strip_nulls(coalesce(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
        'provider_stage', v_stage,
        'provider_stage_recorded_at_utc', v_now::text,
        'provider_submission_status', v_scope_provider_state,
        'transfer_scope_ids', coalesce(v_transfer_scope_ids_json, '[]'::jsonb),
        'provider_request_sent', v_stage IN ('REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN'),
        'provider_response_present', v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN'),
        'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
        'request_id_present', v_request_id IS NOT NULL
      )),
      completed_count = CASE WHEN v_new_chunk_status = 'COMPLETE' AND v_stage = 'PROVIDER_ACCEPTED' THEN coalesce(chunk_update.unit_count, v_scope_count, 0) ELSE chunk_update.completed_count END,
      failed_count = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN coalesce(chunk_update.unit_count, v_scope_count, 0) ELSE chunk_update.failed_count END,
      completed_at_utc = CASE WHEN v_new_chunk_status = 'COMPLETE' THEN coalesce(chunk_update.completed_at_utc, v_now) ELSE chunk_update.completed_at_utc END,
      updated_at_utc = v_now
  WHERE chunk_update.id = p_chunk_id
    AND chunk_update.operation_id = p_operation_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'REVIEW_REQUIRED' ELSE operation_update.status END,
      runner_state = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'REVIEW_REQUIRED' ELSE operation_update.runner_state END,
      requires_user_action = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN true ELSE operation_update.requires_user_action END,
      resume_reason = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'PROVIDER_SUBMIT_REVIEW_REQUIRED' ELSE operation_update.resume_reason END,
      progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'provider_submit_stage_last_recorded', v_stage,
        'provider_submit_stage_last_recorded_at_utc', v_now::text,
        'last_provider_submit_chunk_id', p_chunk_id::text,
        'provider_submission_status', v_scope_provider_state,
        'transfer_scope_count', coalesce(v_scope_count, 0)
      )),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  v_attempt_state := CASE
    WHEN v_stage = 'PROVIDER_ACCEPTED' THEN 'PROVIDER_ACCEPTED'
    WHEN v_stage = 'PROVIDER_REJECTED' THEN 'PROVIDER_REJECTED'
    WHEN v_stage IN ('PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'PROVIDER_UNKNOWN'
    ELSE v_stage
  END;

  SELECT count(*)::integer
  INTO v_attempt_rows
  FROM (
    SELECT public.banking_pay_operation_provider_attempt_record(
      p_operation_id => p_operation_id,
      p_pay_batch_id => p_pay_batch_id,
      p_transfer_scope_id => stage_scope.transfer_scope_id,
      p_provider_chunk_id => p_chunk_id,
      p_idempotency_key => COALESCE(v_idempotency_key, stage_scope.provider_idempotency_key),
      p_request_id => COALESCE(v_request_id, stage_scope.provider_request_id),
      p_provider_transaction_id => v_provider_transaction_id,
      p_previous_state => stage_scope.previous_state,
      p_new_state => v_attempt_state,
      p_lease_owner => v_chunk_row.locked_by,
      p_request_json => NULL::jsonb,
      p_response_json => v_provider_response_json,
      p_error_json => v_provider_error_json,
      p_actor_user_id => p_actor_user_id
    ) AS attempt_result
    FROM pg_temp.tmp_provider_stage_scope AS stage_scope
  ) AS attempt_calls;

  RETURN jsonb_build_object(
    'ok', true,
    'recorded', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'stage', v_stage,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids_json, '[]'::jsonb),
    'transfer_scope_count', coalesce(v_scope_count, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'attempt_rows_recorded', coalesce(v_attempt_rows, 0),
    'legacy_transfer_ids_ignored', p_transfer_ids IS NOT NULL AND jsonb_typeof(p_transfer_ids) = 'array' AND jsonb_array_length(p_transfer_ids) > 0,
    'provider_submission_status', v_scope_provider_state,
    'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
    'request_id_present', v_request_id IS NOT NULL,
    'recorded_at_utc', v_now::text
  );
END;
$function$;








CREATE OR REPLACE FUNCTION public._pay_batch_item_economic_components(
  p_pay_batch_id uuid DEFAULT NULL,
  p_pay_batch_item_ids uuid[] DEFAULT NULL
)
RETURNS TABLE(
  pay_batch_id uuid,
  pay_batch_item_id uuid,
  timesheet_id uuid,
  item_type text,
  key_type text,
  key_value text,
  source_amount_ex_vat numeric,
  source_amount_inc_vat numeric,
  target_amount_ex_vat numeric,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL
     AND COALESCE(array_length(p_pay_batch_item_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION '_pay_batch_item_economic_components requires p_pay_batch_id or p_pay_batch_item_ids';
  END IF;

  RETURN QUERY
  WITH input_item_ids AS (
    SELECT DISTINCT input_ids.item_id
    FROM unnest(COALESCE(p_pay_batch_item_ids, ARRAY[]::uuid[])) AS input_ids(item_id)
    WHERE input_ids.item_id IS NOT NULL
  ),
  base_items AS (
    SELECT
      pay_batch_candidate_row.pay_batch_id AS batch_id,
      pay_batch_item_row.id AS batch_item_id,
      pay_batch_item_row.timesheet_id AS item_timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_row.item_type, '')), '')) AS item_type_norm,
      pay_batch_item_row.item_type AS item_type_raw,
      pay_batch_item_row.segment_key AS item_segment_key,
      pay_batch_item_row.source_ref AS item_source_ref,
      pay_batch_item_row.amount_ex_vat AS item_amount_ex_vat,
      pay_batch_item_row.amount_inc_vat AS item_amount_inc_vat,
      pay_batch_item_row.finance_case_id AS item_finance_case_id,
      pay_batch_item_row.finance_component_id AS item_finance_component_id,
      pay_batch_item_row.frozen_target_amount_ex_vat AS item_frozen_target_amount_ex_vat,
      pay_batch_item_row.frozen_source_amount AS item_frozen_source_amount,
      pay_batch_item_row.frozen_resolution_mode AS item_frozen_resolution_mode,
      pay_batch_item_row.frozen_resolution_payload_json AS item_frozen_resolution_payload_json,
      pay_batch_item_row.frozen_resolution_result_json AS item_frozen_resolution_result_json,
      pay_batch_item_row.frozen_component_key_type AS item_frozen_key_type,
      pay_batch_item_row.frozen_component_key_value AS item_frozen_key_value,
      CASE
        WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)) = 'object'
          THEN COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END AS item_frozen_component_snapshot_json,
      CASE
        WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)) = 'object'
          THEN COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END AS item_frozen_source_basis_json
    FROM public.pay_batch_items AS pay_batch_item_row
    JOIN public.pay_batch_candidates AS pay_batch_candidate_row
      ON pay_batch_candidate_row.id = pay_batch_item_row.pay_batch_candidate_id
    WHERE (p_pay_batch_id IS NULL OR pay_batch_candidate_row.pay_batch_id = p_pay_batch_id)
      AND (
        COALESCE(array_length(p_pay_batch_item_ids, 1), 0) = 0
        OR EXISTS (
          SELECT 1
          FROM input_item_ids AS input_filter
          WHERE input_filter.item_id = pay_batch_item_row.id
        )
      )
  ),
  single_breakdown_meta AS (
    SELECT
      breakdown_row.pay_batch_item_id AS batch_item_id,
      COUNT(*)::integer AS breakdown_count,
      CASE
        WHEN COUNT(*) = 1 THEN (ARRAY_AGG(breakdown_row.meta_json ORDER BY breakdown_row.id))[1]
        ELSE '{}'::jsonb
      END AS single_meta_json
    FROM public.pay_batch_item_breakdowns AS breakdown_row
    JOIN base_items AS base_for_breakdown
      ON base_for_breakdown.batch_item_id = breakdown_row.pay_batch_item_id
    GROUP BY breakdown_row.pay_batch_item_id
  ),
  snapshot_choice AS (
    SELECT
      distinct_item_pairs.batch_id,
      distinct_item_pairs.item_timesheet_id,
      (
        SELECT snapshot_row.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_row
        WHERE snapshot_row.pay_batch_id = distinct_item_pairs.batch_id
          AND snapshot_row.timesheet_id = distinct_item_pairs.item_timesheet_id
        ORDER BY snapshot_row.created_at_utc DESC, snapshot_row.id DESC
        LIMIT 1
      ) AS target_snapshot_json
    FROM (
      SELECT DISTINCT
        base_item_rows.batch_id,
        base_item_rows.item_timesheet_id
      FROM base_items AS base_item_rows
      WHERE base_item_rows.item_timesheet_id IS NOT NULL
    ) AS distinct_item_pairs
  ),
  prepared_items AS (
    SELECT
      base_item_rows.batch_id,
      base_item_rows.batch_item_id,
      base_item_rows.item_timesheet_id,
      base_item_rows.item_type_norm,
      base_item_rows.item_type_raw,
      base_item_rows.item_segment_key,
      base_item_rows.item_source_ref,
      base_item_rows.item_amount_ex_vat,
      base_item_rows.item_amount_inc_vat,
      base_item_rows.item_finance_case_id,
      base_item_rows.item_finance_component_id,
      base_item_rows.item_frozen_target_amount_ex_vat,
      base_item_rows.item_frozen_source_amount,
      base_item_rows.item_frozen_resolution_mode,
      base_item_rows.item_frozen_resolution_payload_json,
      base_item_rows.item_frozen_resolution_result_json,
      base_item_rows.item_frozen_key_type,
      base_item_rows.item_frozen_key_value,
      base_item_rows.item_frozen_component_snapshot_json,
      base_item_rows.item_frozen_source_basis_json,
      CASE
        WHEN COALESCE(breakdown_meta.breakdown_count, 0) = 1
         AND jsonb_typeof(COALESCE(breakdown_meta.single_meta_json, '{}'::jsonb)) = 'object'
          THEN COALESCE(breakdown_meta.single_meta_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END AS item_single_breakdown_meta_json,
      CASE
        WHEN jsonb_typeof(COALESCE(snapshot_choice_rows.target_snapshot_json, '{}'::jsonb)) = 'object'
          THEN COALESCE(snapshot_choice_rows.target_snapshot_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END AS target_snapshot_json
    FROM base_items AS base_item_rows
    LEFT JOIN single_breakdown_meta AS breakdown_meta
      ON breakdown_meta.batch_item_id = base_item_rows.batch_item_id
    LEFT JOIN snapshot_choice AS snapshot_choice_rows
      ON snapshot_choice_rows.batch_id = base_item_rows.batch_id
     AND snapshot_choice_rows.item_timesheet_id = base_item_rows.item_timesheet_id
  ),
  resolved_items AS (
    SELECT
      prepared_item_rows.batch_id,
      prepared_item_rows.batch_item_id,
      prepared_item_rows.item_timesheet_id,
      prepared_item_rows.item_type_norm,
      prepared_item_rows.item_type_raw,
      prepared_item_rows.item_amount_ex_vat,
      prepared_item_rows.item_amount_inc_vat,
      prepared_item_rows.item_finance_case_id,
      prepared_item_rows.item_finance_component_id,
      prepared_item_rows.item_frozen_target_amount_ex_vat,
      prepared_item_rows.item_frozen_source_amount,
      prepared_item_rows.item_frozen_resolution_mode,
      prepared_item_rows.item_frozen_resolution_payload_json,
      prepared_item_rows.item_frozen_resolution_result_json,
      prepared_item_rows.item_frozen_component_snapshot_json,
      prepared_item_rows.item_frozen_source_basis_json,
      prepared_item_rows.item_single_breakdown_meta_json,
      prepared_item_rows.target_snapshot_json,
      resolved_key_rows.key_type AS resolved_key_type,
      resolved_key_rows.key_value AS resolved_key_value,
      resolved_key_rows.key_resolution_source AS resolved_key_source,
      resolved_key_rows.key_resolution_failure_reason AS resolved_key_failure_reason
    FROM prepared_items AS prepared_item_rows
    JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => prepared_item_rows.batch_item_id,
      p_pay_batch_id => prepared_item_rows.batch_id,
      p_timesheet_id => prepared_item_rows.item_timesheet_id,
      p_item_type => prepared_item_rows.item_type_norm,
      p_frozen_key_type => prepared_item_rows.item_frozen_key_type,
      p_frozen_key_value => prepared_item_rows.item_frozen_key_value,
      p_frozen_component_snapshot_json => prepared_item_rows.item_frozen_component_snapshot_json,
      p_frozen_source_basis_json => prepared_item_rows.item_frozen_source_basis_json,
      p_breakdown_meta_json => prepared_item_rows.item_single_breakdown_meta_json,
      p_target_snapshot_json => prepared_item_rows.target_snapshot_json
    ) AS resolved_key_rows
      ON true
  ),
  amount_candidates AS (
    SELECT
      resolved_item_rows.batch_id,
      resolved_item_rows.batch_item_id,
      resolved_item_rows.item_timesheet_id,
      resolved_item_rows.item_type_norm,
      resolved_item_rows.item_type_raw,
      resolved_item_rows.item_amount_ex_vat,
      resolved_item_rows.item_amount_inc_vat,
      resolved_item_rows.resolved_key_type,
      resolved_item_rows.resolved_key_value,
      resolved_item_rows.resolved_key_source,
      resolved_item_rows.resolved_key_failure_reason,
      (
           resolved_item_rows.item_finance_case_id IS NOT NULL
        OR resolved_item_rows.item_finance_component_id IS NOT NULL
        OR resolved_item_rows.item_frozen_target_amount_ex_vat IS NOT NULL
        OR resolved_item_rows.item_frozen_resolution_mode IS NOT NULL
        OR resolved_item_rows.item_frozen_resolution_payload_json IS NOT NULL
        OR resolved_item_rows.item_frozen_resolution_result_json IS NOT NULL
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'target_amount_ex_vat'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'target_pay_ex_vat'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'target_pay_amount_ex_vat'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'frozen_target_amount_ex_vat'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'target_rate'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'target_units'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'resolution_mode'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'saved_resolution_mode'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'saved_resolution_payload_json'
        OR resolved_item_rows.item_frozen_component_snapshot_json ? 'saved_resolution_result_json'
        OR resolved_item_rows.item_single_breakdown_meta_json ? 'target_amount_ex_vat'
        OR resolved_item_rows.item_single_breakdown_meta_json ? 'target_pay_ex_vat'
        OR resolved_item_rows.item_single_breakdown_meta_json ? 'target_rate'
        OR resolved_item_rows.item_single_breakdown_meta_json ? 'resolution_mode'
      ) AS item_has_source_target_split,
      public._pay_batch_item_source_reservation_amount_ex_vat(resolved_item_rows.batch_item_id) AS entitlement_source_amount_ex_vat,
      (
        SELECT target_candidates.target_text_value::numeric
        FROM (
          VALUES
            (resolved_item_rows.item_frozen_target_amount_ex_vat::text),
            (resolved_item_rows.item_amount_ex_vat::text),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'frozen_target_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'target_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'target_pay_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'target_pay_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'amount_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'target_amount_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'target_pay_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'amount_ex_vat')
        ) AS target_candidates(target_text_value)
        WHERE target_candidates.target_text_value IS NOT NULL
          AND BTRIM(target_candidates.target_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_target_amount_ex_vat,
      (
        SELECT source_candidates.source_text_value::numeric
        FROM (
          VALUES
            (resolved_item_rows.item_frozen_source_amount::text),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_pay_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'reserved_source_amount'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_amount_ex_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_pay_ex_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'pay_ex_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_reservation_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_entitlement_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_pay_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_reservation_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_entitlement_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_amount_ex_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_pay_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_reservation_amount_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_entitlement_amount_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_amount_ex_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_pay_ex_vat')
        ) AS source_candidates(source_text_value)
        WHERE source_candidates.source_text_value IS NOT NULL
          AND BTRIM(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_artifact_source_amount_ex_vat,
      (
        SELECT source_inc_candidates.source_inc_text_value::numeric
        FROM (
          VALUES
            (resolved_item_rows.item_frozen_source_basis_json->>'source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_pay_inc_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_entitlement_amount_inc_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'source_reservation_amount_inc_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'pay_inc_vat'),
            (resolved_item_rows.item_frozen_source_basis_json->>'amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_pay_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_entitlement_amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'source_reservation_amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'basis_source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json->>'reserved_source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_inc_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_inc_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_inc_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_inc_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,pay_inc_vat}'),
            (resolved_item_rows.item_frozen_component_snapshot_json#>>'{source_basis_json,amount_inc_vat}'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_pay_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_entitlement_amount_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_payload_json->>'source_reservation_amount_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_amount_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_pay_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_entitlement_amount_inc_vat'),
            (resolved_item_rows.item_frozen_resolution_result_json->>'source_reservation_amount_inc_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_amount_inc_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_pay_inc_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_entitlement_amount_inc_vat'),
            (resolved_item_rows.item_single_breakdown_meta_json->>'source_reservation_amount_inc_vat')
        ) AS source_inc_candidates(source_inc_text_value)
        WHERE source_inc_candidates.source_inc_text_value IS NOT NULL
          AND BTRIM(source_inc_candidates.source_inc_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_artifact_source_amount_inc_vat
    FROM resolved_items AS resolved_item_rows
  ),
  final_rows AS (
    SELECT
      amount_candidate_rows.batch_id,
      amount_candidate_rows.batch_item_id,
      amount_candidate_rows.item_timesheet_id,
      amount_candidate_rows.item_type_raw,
      amount_candidate_rows.resolved_key_type,
      amount_candidate_rows.resolved_key_value,
      amount_candidate_rows.resolved_key_source,
      amount_candidate_rows.resolved_key_failure_reason,
      ROUND(ABS(
        CASE
          WHEN amount_candidate_rows.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN COALESCE(
              amount_candidate_rows.entitlement_source_amount_ex_vat,
              amount_candidate_rows.raw_artifact_source_amount_ex_vat,
              CASE
                WHEN amount_candidate_rows.item_has_source_target_split THEN NULL::numeric
                ELSE COALESCE(amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
              END
            )
          ELSE COALESCE(amount_candidate_rows.raw_artifact_source_amount_ex_vat, amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
        END
      ), 2)::numeric AS final_source_amount_ex_vat,
      ROUND(ABS(COALESCE(
        amount_candidate_rows.raw_artifact_source_amount_inc_vat,
        CASE
          WHEN amount_candidate_rows.item_has_source_target_split THEN NULL::numeric
          ELSE amount_candidate_rows.item_amount_inc_vat
        END,
        CASE
          WHEN amount_candidate_rows.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN COALESCE(
              amount_candidate_rows.entitlement_source_amount_ex_vat,
              amount_candidate_rows.raw_artifact_source_amount_ex_vat,
              CASE
                WHEN amount_candidate_rows.item_has_source_target_split THEN NULL::numeric
                ELSE COALESCE(amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
              END
            )
          ELSE COALESCE(amount_candidate_rows.raw_artifact_source_amount_ex_vat, amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
        END
      )), 2)::numeric AS final_source_amount_inc_vat,
      ROUND(ABS(COALESCE(
        amount_candidate_rows.raw_target_amount_ex_vat,
        amount_candidate_rows.item_amount_ex_vat,
        CASE
          WHEN amount_candidate_rows.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN COALESCE(amount_candidate_rows.entitlement_source_amount_ex_vat, amount_candidate_rows.raw_artifact_source_amount_ex_vat)
          ELSE amount_candidate_rows.raw_artifact_source_amount_ex_vat
        END
      )), 2)::numeric AS final_target_amount_ex_vat,
      CASE
        WHEN amount_candidate_rows.resolved_key_failure_reason IS NOT NULL
          THEN amount_candidate_rows.resolved_key_failure_reason
        WHEN amount_candidate_rows.resolved_key_type IS NULL OR BTRIM(COALESCE(amount_candidate_rows.resolved_key_type, '')) = ''
          THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
        WHEN amount_candidate_rows.resolved_key_value IS NULL OR BTRIM(COALESCE(amount_candidate_rows.resolved_key_value, '')) = ''
          THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
        WHEN amount_candidate_rows.resolved_key_type = 'TS_DAY'
         AND amount_candidate_rows.resolved_key_value !~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'TS_DAY_KEY_VALUE_NOT_DATE'
        WHEN ROUND(ABS(
          CASE
            WHEN amount_candidate_rows.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
              THEN COALESCE(
                amount_candidate_rows.entitlement_source_amount_ex_vat,
                amount_candidate_rows.raw_artifact_source_amount_ex_vat,
                CASE
                  WHEN amount_candidate_rows.item_has_source_target_split THEN NULL::numeric
                  ELSE COALESCE(amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
                END
              )
            ELSE COALESCE(amount_candidate_rows.raw_artifact_source_amount_ex_vat, amount_candidate_rows.raw_target_amount_ex_vat, amount_candidate_rows.item_amount_ex_vat)
          END
        ), 2) IS NULL
          THEN 'SOURCE_AMOUNT_NOT_RESOLVED'
        WHEN ROUND(ABS(COALESCE(
          amount_candidate_rows.raw_target_amount_ex_vat,
          amount_candidate_rows.item_amount_ex_vat,
          CASE
            WHEN amount_candidate_rows.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
              THEN COALESCE(amount_candidate_rows.entitlement_source_amount_ex_vat, amount_candidate_rows.raw_artifact_source_amount_ex_vat)
            ELSE amount_candidate_rows.raw_artifact_source_amount_ex_vat
          END
        )), 2) IS NULL
          THEN 'TARGET_AMOUNT_NOT_RESOLVED'
        ELSE NULL::text
      END AS final_failure_reason
    FROM amount_candidates AS amount_candidate_rows
  )
  SELECT
    final_rows.batch_id AS pay_batch_id,
    final_rows.batch_item_id AS pay_batch_item_id,
    final_rows.item_timesheet_id AS timesheet_id,
    final_rows.item_type_raw AS item_type,
    CASE WHEN final_rows.final_failure_reason IS NULL THEN final_rows.resolved_key_type ELSE NULL::text END AS key_type,
    CASE WHEN final_rows.final_failure_reason IS NULL THEN final_rows.resolved_key_value ELSE NULL::text END AS key_value,
    CASE WHEN final_rows.final_source_amount_ex_vat IS NULL THEN NULL::numeric ELSE ROUND(final_rows.final_source_amount_ex_vat, 2)::numeric END AS source_amount_ex_vat,
    CASE WHEN final_rows.final_source_amount_inc_vat IS NULL THEN NULL::numeric ELSE ROUND(final_rows.final_source_amount_inc_vat, 2)::numeric END AS source_amount_inc_vat,
    CASE WHEN final_rows.final_target_amount_ex_vat IS NULL THEN NULL::numeric ELSE ROUND(final_rows.final_target_amount_ex_vat, 2)::numeric END AS target_amount_ex_vat,
    CASE WHEN final_rows.final_failure_reason IS NULL THEN final_rows.resolved_key_source ELSE 'KEY_RESOLUTION_FAILED' END AS key_resolution_source,
    final_rows.final_failure_reason AS key_resolution_failure_reason
  FROM final_rows
  ORDER BY final_rows.batch_id, final_rows.batch_item_id;
END;
$function$;




CREATE OR REPLACE FUNCTION public.banking_get_capabilities()

  
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text;
  v_env text;

  v_supports_scheduling boolean;
  v_supports_name_check boolean;
  v_supports_auto_execute boolean;

  v_supports_csv_confirm boolean;

  -- ✅ C: include default funding account in capabilities output
  v_rail_default_funding_account_ref text;

  -- ✅ NEW: payroll testing flag (simulate payments; no real bank payments)
  v_payroll_testing boolean;

  -- ✅ NEW: PAYE remittances gate
  v_paye_remittances_enabled boolean;
begin
  -- settings_defaults is expected to have a single row; do not assume an id column.
  select
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_scheduling,
    sd.rail_supports_name_check,
    sd.rail_supports_auto_execute,
    sd.rail_default_funding_account_ref,
    sd.payroll_testing,
    sd.paye_remittances_enabled
  into
    v_provider,
    v_env,
    v_supports_scheduling,
    v_supports_name_check,
    v_supports_auto_execute,
    v_rail_default_funding_account_ref,
    v_payroll_testing,
    v_paye_remittances_enabled
  from public.settings_defaults sd
  limit 1;

  v_provider := upper(btrim(coalesce(v_provider, 'CSV')));
  v_env := upper(btrim(coalesce(v_env, 'PROD')));

  v_supports_scheduling := coalesce(v_supports_scheduling, false);
  v_supports_name_check := coalesce(v_supports_name_check, false);
  v_supports_auto_execute := coalesce(v_supports_auto_execute, false);

  v_payroll_testing := coalesce(v_payroll_testing, false);
  v_paye_remittances_enabled := coalesce(v_paye_remittances_enabled, false);

  -- CSV rail implies manual bank confirmation (upload + confirm).
  v_supports_csv_confirm := (v_provider = 'CSV');

  return jsonb_build_object(
    'rail_provider', v_provider,
    'rail_env', v_env,
    'supports_scheduling', v_supports_scheduling,
    'supports_name_check', v_supports_name_check,
    'supports_auto_execute', v_supports_auto_execute,
    'supports_csv_confirm', v_supports_csv_confirm,
    'requires_manual_bank_confirm', v_supports_csv_confirm,

    -- ✅ NEW: surface test-mode switch for UI/backend consistency
    'payroll_testing', v_payroll_testing,

    -- ✅ NEW: PAYE remittance gate (UI can block PAYE remittance send)
    'paye_remittances_enabled', v_paye_remittances_enabled,

    -- ✅ C: surface saved default so UI can preselect consistently
    'rail_default_funding_account_ref', v_rail_default_funding_account_ref
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_timesheet_components(p_snapshot_json jsonb)
RETURNS TABLE (
  key_type text,
  key_value text,
  amount_ex_vat numeric,
  amount_inc_vat numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
with
seg_raw as (
  select
    nullif(btrim(coalesce(seg->>'segment_id','')), '') as segment_id,
    nullif(btrim(coalesce(seg->>'date','')), '') as seg_date_raw,
    coalesce(nullif(seg->>'exclude_from_pay','')::boolean, false) as exclude_from_pay,
    case
      when coalesce(seg->>'pay_amount','') ~ '^-?\d+(\.\d+)?$' then (seg->>'pay_amount')::numeric
      else 0::numeric
    end as pay_amount_ex
  from jsonb_array_elements(coalesce(p_snapshot_json->'segments','[]'::jsonb)) as seg
  where seg is not null and jsonb_typeof(seg) = 'object'
),
seg_norm as (
  select
    case
      when sr.seg_date_raw ~ '^\d{4}-\d{2}-\d{2}$' then 'TS_DAY'
      else 'TS_TOTAL'
    end as key_type,
    case
      when sr.seg_date_raw ~ '^\d{4}-\d{2}-\d{2}$' then sr.seg_date_raw
      else 'TOTAL'
    end as key_value,
    round(
      sum(
        case
          when sr.exclude_from_pay then 0::numeric
          else coalesce(sr.pay_amount_ex,0)
        end
      ),
      2
    ) as amount_ex_vat
  from seg_raw sr
  where sr.segment_id is not null
  group by 1,2
),
add_kv as (
  select
    upper(btrim(e.key)) as code,
    e.value as obj
  from jsonb_each(coalesce(p_snapshot_json->'additional_units_json','{}'::jsonb)) as e
  where e.key is not null
    and btrim(e.key) <> ''
    and e.value is not null
    and jsonb_typeof(e.value) = 'object'
),
add_by_code as (
  select
    'ADDITIONAL_CODE'::text as key_type,
    ak.code as key_value,
    round(
      coalesce(
        case when coalesce(ak.obj->>'pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'pay_ex_vat')::numeric end,
        case when coalesce(ak.obj->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'amount_ex_vat')::numeric end,
        (
          coalesce(
            case when coalesce(ak.obj->>'unit_count','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'unit_count')::numeric end,
            case when coalesce(ak.obj->>'units_week','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'units_week')::numeric end,
            0::numeric
          )
          *
          coalesce(
            case when coalesce(ak.obj->>'pay_rate','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'pay_rate')::numeric end,
            case when coalesce(ak.obj->>'rate','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'rate')::numeric end,
            0::numeric
          )
        ),
        0::numeric
      ),
      2
    ) as amount_ex_vat
  from add_kv ak
),
add_sum as (
  select
    round(coalesce(sum(abc.amount_ex_vat),0),2) as sum_ex
  from add_by_code abc
),
add_total_fallback as (
  select
    'ADDITIONAL_CODE'::text as key_type,
    'TOTAL'::text as key_value,
    round(
      case
        when coalesce(p_snapshot_json->>'additional_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (p_snapshot_json->>'additional_pay_ex_vat')::numeric
        else 0::numeric
      end,
      2
    ) as amount_ex_vat
  where (select coalesce(a.sum_ex,0) from add_sum a) = 0
    and (
      coalesce(p_snapshot_json->>'additional_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      and (p_snapshot_json->>'additional_pay_ex_vat')::numeric <> 0
    )
),
exp_vals as (
  select
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,travel_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,travel_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as travel_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as accom_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,other_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,other_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as other_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,mileage_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as mileage_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,expenses_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as expenses_rollup_ex
),
exp_has_cats as (
  select
    (coalesce(ev.travel_ex,0) <> 0)
    or (coalesce(ev.accom_ex,0) <> 0)
    or (coalesce(ev.other_ex,0) <> 0)
    or (coalesce(ev.mileage_ex,0) <> 0) as has_any_cat
  from exp_vals ev
),
exp_components as (
  select 'EXPENSE_CODE'::text as key_type, 'TRAVEL'::text as key_value, ev.travel_ex as amount_ex_vat
  from exp_vals ev
  where coalesce(ev.travel_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'ACCOMMODATION'::text, ev.accom_ex
  from exp_vals ev
  where coalesce(ev.accom_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'OTHER'::text, ev.other_ex
  from exp_vals ev
  where coalesce(ev.other_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'MILEAGE'::text, ev.mileage_ex
  from exp_vals ev
  where coalesce(ev.mileage_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'EXPENSES'::text, ev.expenses_rollup_ex
  from exp_vals ev
  where (select eh.has_any_cat from exp_has_cats eh) = false
    and coalesce(ev.expenses_rollup_ex,0) <> 0
),
adj_components as (
  select
    'ADJUSTMENT_CODE'::text as key_type,
    nullif(btrim(coalesce(adj->>'id','')), '') as key_value,
    round(
      case
        when coalesce(adj->>'delta_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (adj->>'delta_pay_ex_vat')::numeric
        else 0::numeric
      end,
      2
    ) as amount_ex_vat
  from jsonb_array_elements(coalesce(p_snapshot_json->'adjustments','[]'::jsonb)) as adj
  where adj is not null
    and jsonb_typeof(adj)='object'
    and nullif(btrim(coalesce(adj->>'id','')), '') is not null
    and (
      coalesce(adj->>'delta_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      and (adj->>'delta_pay_ex_vat')::numeric <> 0
    )
)
select
  s.key_type,
  s.key_value,
  s.amount_ex_vat,
  s.amount_ex_vat as amount_inc_vat
from seg_norm s

union all
select
  abc.key_type,
  abc.key_value,
  abc.amount_ex_vat,
  abc.amount_ex_vat
from add_by_code abc
where abc.amount_ex_vat <> 0

union all
select
  atf.key_type,
  atf.key_value,
  atf.amount_ex_vat,
  atf.amount_ex_vat
from add_total_fallback atf

union all
select
  ec.key_type,
  ec.key_value,
  ec.amount_ex_vat,
  ec.amount_ex_vat
from exp_components ec

union all
select
  ac.key_type,
  ac.key_value,
  ac.amount_ex_vat,
  ac.amount_ex_vat
from adj_components ac;
$$;



CREATE OR REPLACE FUNCTION public._pay_reserved_components(p_timesheet_ids uuid[], p_exclude_pay_batch_id uuid)
RETURNS TABLE (
  timesheet_id uuid,
  key_type text,
  key_value text,
  amount_ex_vat numeric,
  amount_inc_vat numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
WITH
inp AS (
  SELECT COALESCE(
    (
      SELECT array_agg(DISTINCT input_values.timesheet_id_value ORDER BY input_values.timesheet_id_value)
      FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_values(timesheet_id_value)
      WHERE input_values.timesheet_id_value IS NOT NULL
    ),
    ARRAY[]::uuid[]
  ) AS ts_ids
),
rotation_scope_rows AS (
  SELECT
    scope_rows.requested_timesheet_id,
    scope_rows.booking_id,
    scope_rows.canonical_timesheet_id,
    scope_rows.family_timesheet_id,
    scope_rows.family_is_current,
    scope_rows.family_version,
    scope_rows.requested_is_canonical
  FROM inp AS input_scope
  JOIN public._pay_timesheet_rotation_scope(input_scope.ts_ids) AS scope_rows
    ON true
),
rotation_scope_keyed AS (
  SELECT
    rotation_scope_rows.requested_timesheet_id,
    rotation_scope_rows.booking_id,
    rotation_scope_rows.canonical_timesheet_id,
    rotation_scope_rows.family_timesheet_id,
    rotation_scope_rows.family_is_current,
    rotation_scope_rows.family_version,
    rotation_scope_rows.requested_is_canonical,
    COALESCE(rotation_scope_rows.booking_id, rotation_scope_rows.requested_timesheet_id::text) AS scope_family_key
  FROM rotation_scope_rows
  WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
),
projection_targets AS (
  SELECT
    rotation_scope_keyed.scope_family_key,
    COALESCE(
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.canonical_timesheet_id ORDER BY rotation_scope_keyed.canonical_timesheet_id)
        FILTER (
          WHERE COALESCE(rotation_scope_keyed.requested_is_canonical, false) = true
            AND rotation_scope_keyed.canonical_timesheet_id IS NOT NULL
        )
      )[1],
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.requested_timesheet_id ORDER BY rotation_scope_keyed.requested_timesheet_id)
        FILTER (WHERE rotation_scope_keyed.requested_timesheet_id IS NOT NULL)
      )[1],
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.canonical_timesheet_id ORDER BY rotation_scope_keyed.canonical_timesheet_id)
        FILTER (WHERE rotation_scope_keyed.canonical_timesheet_id IS NOT NULL)
      )[1]
    ) AS projected_timesheet_id
  FROM rotation_scope_keyed
  GROUP BY rotation_scope_keyed.scope_family_key
),
family_to_projection AS (
  SELECT DISTINCT
    rotation_scope_keyed.family_timesheet_id,
    projection_targets.projected_timesheet_id
  FROM rotation_scope_keyed
  JOIN projection_targets
    ON projection_targets.scope_family_key = rotation_scope_keyed.scope_family_key
  WHERE rotation_scope_keyed.family_timesheet_id IS NOT NULL
    AND projection_targets.projected_timesheet_id IS NOT NULL
),
active_batch_item_ids AS (
  SELECT DISTINCT
    pay_batch_item_row.id AS pay_batch_item_id,
    family_to_projection.projected_timesheet_id AS projected_timesheet_id
  FROM family_to_projection
  JOIN public.pay_batch_items AS pay_batch_item_row
    ON pay_batch_item_row.timesheet_id = family_to_projection.family_timesheet_id
  JOIN public.pay_batch_candidates AS pay_batch_candidate_row
    ON pay_batch_candidate_row.id = pay_batch_item_row.pay_batch_candidate_id
  JOIN public.pay_batches AS pay_batch_row
    ON pay_batch_row.id = pay_batch_candidate_row.pay_batch_id
  LEFT JOIN public.pay_bank_transfers AS pay_bank_transfer_row
    ON pay_bank_transfer_row.id = pay_batch_item_row.pay_bank_transfer_id
  WHERE pay_batch_item_row.timesheet_id IS NOT NULL
    AND COALESCE(pay_batch_item_row.is_voided, false) = false
    AND upper(coalesce(pay_batch_item_row.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND public._pay_batch_status_is_active_reservation(pay_batch_row.status)
    AND (p_exclude_pay_batch_id IS NULL OR pay_batch_row.id <> p_exclude_pay_batch_id)
    AND UPPER(BTRIM(COALESCE(pay_batch_item_row.item_type, ''))) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_correction_row
      WHERE applied_correction_row.pay_batch_item_id = pay_batch_item_row.id
        AND applied_correction_row.status = 'APPLIED'
        AND applied_correction_row.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(pay_batch_candidate_row.settlement_status, ''))) = 'SETTLED'
      OR pay_batch_candidate_row.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(pay_bank_transfer_row.status, ''))) = 'COMPLETED'
      OR pay_bank_transfer_row.completed_at_utc IS NOT NULL
    )
),
open_correction_exact_item_ids AS (
  SELECT DISTINCT
    open_correction_request_row.id AS correction_request_id,
    open_correction_request_row.pay_batch_id AS pay_batch_id,
    parsed_exact_item_ids.pay_batch_item_id AS pay_batch_item_id
  FROM public.pay_payment_correction_requests AS open_correction_request_row
  JOIN LATERAL (
    SELECT DISTINCT
      exact_item_text_values.item_id_text::uuid AS pay_batch_item_id
    FROM (
      SELECT item_array_values.item_id_text
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(open_correction_request_row.plan_json->'selected_pay_batch_item_ids') = 'array'
            THEN open_correction_request_row.plan_json->'selected_pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_request_row.plan_json#>'{selection,selected_pay_batch_item_ids}') = 'array'
            THEN open_correction_request_row.plan_json#>'{selection,selected_pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_request_row.plan_json#>'{selection,pay_batch_item_ids}') = 'array'
            THEN open_correction_request_row.plan_json#>'{selection,pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_request_row.plan_json#>'{work_expansion_plan,selected_pay_batch_item_ids}') = 'array'
            THEN open_correction_request_row.plan_json#>'{work_expansion_plan,selected_pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_request_row.selection_json->'selected_pay_batch_item_ids') = 'array'
            THEN open_correction_request_row.selection_json->'selected_pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_request_row.selection_json->'pay_batch_item_ids') = 'array'
            THEN open_correction_request_row.selection_json->'pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_request_row.selection_json->'expected_pay_batch_item_ids') = 'array'
            THEN open_correction_request_row.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_array_values(item_id_text)

      UNION ALL

      SELECT open_correction_request_row.selection_json->>'pay_batch_item_id'
      WHERE open_correction_request_row.selection_json ? 'pay_batch_item_id'

      UNION ALL

      SELECT open_correction_request_row.selection_json->>'expected_pay_batch_item_id'
      WHERE open_correction_request_row.selection_json ? 'expected_pay_batch_item_id'
    ) AS exact_item_text_values
    WHERE nullif(btrim(coalesce(exact_item_text_values.item_id_text, '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(exact_item_text_values.item_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_exact_item_ids
    ON true
  JOIN public.pay_batch_items AS exact_pay_batch_item_row
    ON exact_pay_batch_item_row.id = parsed_exact_item_ids.pay_batch_item_id
  JOIN public.pay_batch_candidates AS exact_pay_batch_candidate_row
    ON exact_pay_batch_candidate_row.id = exact_pay_batch_item_row.pay_batch_candidate_id
   AND exact_pay_batch_candidate_row.pay_batch_id = open_correction_request_row.pay_batch_id
  WHERE open_correction_request_row.status IN ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED')
    AND open_correction_request_row.correction_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
    AND (p_exclude_pay_batch_id IS NULL OR open_correction_request_row.pay_batch_id <> p_exclude_pay_batch_id)
),
open_correction_hold_item_ids AS (
  SELECT DISTINCT
    open_correction_exact_item_ids.pay_batch_item_id AS pay_batch_item_id,
    family_to_projection.projected_timesheet_id AS projected_timesheet_id
  FROM open_correction_exact_item_ids
  JOIN public.pay_batch_items AS selected_pay_batch_item_row
    ON selected_pay_batch_item_row.id = open_correction_exact_item_ids.pay_batch_item_id
  JOIN family_to_projection
    ON family_to_projection.family_timesheet_id = selected_pay_batch_item_row.timesheet_id
  JOIN public.pay_batch_candidates AS selected_pay_batch_candidate_row
    ON selected_pay_batch_candidate_row.id = selected_pay_batch_item_row.pay_batch_candidate_id
   AND selected_pay_batch_candidate_row.pay_batch_id = open_correction_exact_item_ids.pay_batch_id
  LEFT JOIN public.pay_bank_transfers AS selected_pay_bank_transfer_row
    ON selected_pay_bank_transfer_row.id = selected_pay_batch_item_row.pay_bank_transfer_id
  WHERE selected_pay_batch_item_row.timesheet_id IS NOT NULL
    AND COALESCE(selected_pay_batch_item_row.is_voided, false) = false
    AND upper(coalesce(selected_pay_batch_item_row.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND (p_exclude_pay_batch_id IS NULL OR selected_pay_batch_candidate_row.pay_batch_id <> p_exclude_pay_batch_id)
    AND UPPER(BTRIM(COALESCE(selected_pay_batch_item_row.item_type, ''))) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_correction_row
      WHERE applied_correction_row.pay_batch_item_id = selected_pay_batch_item_row.id
        AND applied_correction_row.status = 'APPLIED'
        AND applied_correction_row.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(selected_pay_batch_candidate_row.settlement_status, ''))) = 'SETTLED'
      OR selected_pay_batch_candidate_row.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(selected_pay_bank_transfer_row.status, ''))) = 'COMPLETED'
      OR selected_pay_bank_transfer_row.completed_at_utc IS NOT NULL
    )
),
unresolved_terminal_failure_hold_item_ids AS (
  SELECT DISTINCT
    terminal_failure_item_row.id AS pay_batch_item_id,
    family_to_projection.projected_timesheet_id AS projected_timesheet_id
  FROM family_to_projection
  JOIN public.pay_batch_items AS terminal_failure_item_row
    ON terminal_failure_item_row.timesheet_id = family_to_projection.family_timesheet_id
  JOIN public.pay_batch_candidates AS terminal_failure_candidate_row
    ON terminal_failure_candidate_row.id = terminal_failure_item_row.pay_batch_candidate_id
  JOIN public.pay_bank_transfer_events AS terminal_failure_event_row
    ON terminal_failure_event_row.pay_batch_id = terminal_failure_candidate_row.pay_batch_id
   AND terminal_failure_event_row.pay_bank_transfer_id = terminal_failure_item_row.pay_bank_transfer_id
   AND terminal_failure_event_row.mapping_status = 'MATCHED'
   AND terminal_failure_event_row.normalised_state IN ('FAILED','DECLINED','REJECTED','CANCELLED')
  LEFT JOIN public.pay_bank_transfers AS terminal_failure_transfer_row
    ON terminal_failure_transfer_row.id = terminal_failure_item_row.pay_bank_transfer_id
  WHERE terminal_failure_item_row.timesheet_id IS NOT NULL
    AND COALESCE(terminal_failure_item_row.is_voided, false) = false
    AND upper(coalesce(terminal_failure_item_row.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND (p_exclude_pay_batch_id IS NULL OR terminal_failure_candidate_row.pay_batch_id <> p_exclude_pay_batch_id)
    AND UPPER(BTRIM(COALESCE(terminal_failure_item_row.item_type, ''))) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_correction_row
      WHERE applied_correction_row.pay_batch_item_id = terminal_failure_item_row.id
        AND applied_correction_row.status = 'APPLIED'
        AND applied_correction_row.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(terminal_failure_candidate_row.settlement_status, ''))) = 'SETTLED'
      OR terminal_failure_candidate_row.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(terminal_failure_transfer_row.status, ''))) = 'COMPLETED'
      OR terminal_failure_transfer_row.completed_at_utc IS NOT NULL
    )
),
active_item_ids AS (
  SELECT active_batch_item_ids.pay_batch_item_id, active_batch_item_ids.projected_timesheet_id
  FROM active_batch_item_ids
  UNION
  SELECT open_correction_hold_item_ids.pay_batch_item_id, open_correction_hold_item_ids.projected_timesheet_id
  FROM open_correction_hold_item_ids
  UNION
  SELECT unresolved_terminal_failure_hold_item_ids.pay_batch_item_id, unresolved_terminal_failure_hold_item_ids.projected_timesheet_id
  FROM unresolved_terminal_failure_hold_item_ids
),
active_item_id_array AS (
  SELECT
    CASE
      WHEN COUNT(*) = 0 THEN ARRAY['00000000-0000-0000-0000-000000000000'::uuid]
      ELSE ARRAY_AGG(active_item_ids.pay_batch_item_id ORDER BY active_item_ids.pay_batch_item_id)
    END AS pay_batch_item_ids
  FROM active_item_ids
),
reserved_keyed_raw AS (
  SELECT
    active_item_rows.pay_batch_item_id,
    active_item_rows.projected_timesheet_id AS timesheet_id,
    UPPER(NULLIF(BTRIM(COALESCE(economic_component_rows.key_type, '')), '')) AS key_type,
    NULLIF(BTRIM(COALESCE(economic_component_rows.key_value, '')), '') AS key_value,
    ROUND(COALESCE(economic_component_rows.source_amount_ex_vat, 0), 2) AS amount_ex_vat,
    ROUND(COALESCE(economic_component_rows.source_amount_inc_vat, 0), 2) AS amount_inc_vat
  FROM active_item_id_array
  JOIN LATERAL public._pay_batch_item_economic_components(
    p_pay_batch_id => NULL::uuid,
    p_pay_batch_item_ids => active_item_id_array.pay_batch_item_ids
  ) AS economic_component_rows
    ON true
  JOIN active_item_ids AS active_item_rows
    ON active_item_rows.pay_batch_item_id = economic_component_rows.pay_batch_item_id
  WHERE active_item_rows.projected_timesheet_id IS NOT NULL
    AND UPPER(BTRIM(COALESCE(economic_component_rows.item_type, ''))) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND economic_component_rows.key_resolution_failure_reason IS NULL
    AND economic_component_rows.source_amount_ex_vat IS NOT NULL
    AND UPPER(BTRIM(COALESCE(economic_component_rows.key_type, ''))) IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
),
reserved_keyed AS (
  SELECT
    reserved_keyed_raw.pay_batch_item_id,
    reserved_keyed_raw.timesheet_id,
    reserved_keyed_raw.key_type,
    reserved_keyed_raw.key_value,
    ROUND(SUM(COALESCE(reserved_keyed_raw.amount_ex_vat, 0)), 2) AS amount_ex_vat,
    ROUND(SUM(COALESCE(reserved_keyed_raw.amount_inc_vat, 0)), 2) AS amount_inc_vat
  FROM reserved_keyed_raw
  WHERE reserved_keyed_raw.timesheet_id IS NOT NULL
    AND reserved_keyed_raw.key_type IS NOT NULL
    AND BTRIM(reserved_keyed_raw.key_type) <> ''
    AND reserved_keyed_raw.key_value IS NOT NULL
    AND BTRIM(reserved_keyed_raw.key_value) <> ''
    AND NOT (reserved_keyed_raw.key_type = 'TS_DAY' AND reserved_keyed_raw.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  GROUP BY
    reserved_keyed_raw.pay_batch_item_id,
    reserved_keyed_raw.timesheet_id,
    reserved_keyed_raw.key_type,
    reserved_keyed_raw.key_value
),
reserved_components AS (
  SELECT
    reserved_keyed_rows.timesheet_id,
    reserved_keyed_rows.key_type,
    reserved_keyed_rows.key_value,
    ROUND(SUM(COALESCE(reserved_keyed_rows.amount_ex_vat, 0)), 2) AS amount_ex_vat,
    ROUND(SUM(COALESCE(reserved_keyed_rows.amount_inc_vat, 0)), 2) AS amount_inc_vat
  FROM reserved_keyed AS reserved_keyed_rows
  GROUP BY
    reserved_keyed_rows.timesheet_id,
    reserved_keyed_rows.key_type,
    reserved_keyed_rows.key_value
)
SELECT
  reserved_component_rows.timesheet_id,
  reserved_component_rows.key_type,
  reserved_component_rows.key_value,
  reserved_component_rows.amount_ex_vat,
  reserved_component_rows.amount_inc_vat
FROM reserved_components AS reserved_component_rows
WHERE reserved_component_rows.timesheet_id IS NOT NULL
  AND reserved_component_rows.key_type IS NOT NULL
  AND reserved_component_rows.key_value IS NOT NULL
  AND (
    ROUND(COALESCE(reserved_component_rows.amount_ex_vat, 0), 2) <> 0
    OR ROUND(COALESCE(reserved_component_rows.amount_inc_vat, 0), 2) <> 0
  );
$$;


-- =========================================================
-- NEW - public._pay_reserved_components - wrapper uuid array.txt
-- =========================================================

CREATE OR REPLACE FUNCTION public._pay_reserved_components(p_timesheet_ids uuid[])
RETURNS TABLE (
  timesheet_id uuid,
  key_type text,
  key_value text,
  amount_ex_vat numeric,
  amount_inc_vat numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
SELECT
  reserved_component_rows.timesheet_id,
  reserved_component_rows.key_type,
  reserved_component_rows.key_value,
  reserved_component_rows.amount_ex_vat,
  reserved_component_rows.amount_inc_vat
FROM public._pay_reserved_components(p_timesheet_ids, NULL::uuid) AS reserved_component_rows;
$$;



-- =========================================================
-- NEW - public._pay_outstanding_components - overload exclude pay batch.txt
-- =========================================================
CREATE OR REPLACE FUNCTION public._pay_outstanding_components(p_timesheet_ids uuid[], p_exclude_pay_batch_id uuid)
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, reserved_ex_vat numeric, outstanding_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric, reserved_inc_vat numeric, outstanding_inc_vat numeric, reservation_overrun_detected boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with
inp as (
  select coalesce(
    (
      select array_agg(distinct t_input.x order by t_input.x)
      from unnest(coalesce(p_timesheet_ids, array[]::uuid[])) as t_input(x)
      where t_input.x is not null
    ),
    array[]::uuid[]
  ) as ts_ids
),
rotation_scope_rows as (
  select
    scope_rows.requested_timesheet_id,
    scope_rows.booking_id,
    scope_rows.canonical_timesheet_id,
    scope_rows.family_timesheet_id,
    scope_rows.family_is_current,
    scope_rows.family_version,
    scope_rows.requested_is_canonical
  from inp as input_scope
  join public._pay_timesheet_rotation_scope(input_scope.ts_ids) as scope_rows
    on true
),
rotation_scope_keyed as (
  select
    rotation_scope_rows.requested_timesheet_id,
    rotation_scope_rows.booking_id,
    rotation_scope_rows.canonical_timesheet_id,
    rotation_scope_rows.family_timesheet_id,
    rotation_scope_rows.family_is_current,
    rotation_scope_rows.family_version,
    rotation_scope_rows.requested_is_canonical,
    coalesce(rotation_scope_rows.booking_id, rotation_scope_rows.requested_timesheet_id::text) as scope_family_key
  from rotation_scope_rows
  where rotation_scope_rows.requested_timesheet_id is not null
),
projection_targets as (
  select
    rotation_scope_keyed.scope_family_key,
    coalesce(
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (
          where coalesce(rotation_scope_keyed.requested_is_canonical, false) = true
            and rotation_scope_keyed.canonical_timesheet_id is not null
        )
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.requested_timesheet_id order by rotation_scope_keyed.requested_timesheet_id)
        filter (where rotation_scope_keyed.requested_timesheet_id is not null)
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (where rotation_scope_keyed.canonical_timesheet_id is not null)
      )[1]
    ) as projected_timesheet_id
  from rotation_scope_keyed
  group by rotation_scope_keyed.scope_family_key
),
family_to_projection as (
  select distinct
    rotation_scope_keyed.family_timesheet_id,
    projection_targets.projected_timesheet_id
  from rotation_scope_keyed
  join projection_targets
    on projection_targets.scope_family_key = rotation_scope_keyed.scope_family_key
  where rotation_scope_keyed.family_timesheet_id is not null
    and projection_targets.projected_timesheet_id is not null
),
timesheet_entitlement_components as (
  select
    entitlement_rows.timesheet_id,
    entitlement_rows.key_type,
    entitlement_rows.key_value,
    entitlement_rows.truth_ex_vat,
    entitlement_rows.baseline_ex_vat,
    entitlement_rows.truth_inc_vat,
    entitlement_rows.baseline_inc_vat
  from public._pay_current_timesheet_entitlement_components((select input_scope.ts_ids from inp as input_scope)) as entitlement_rows
),
reserved_components as (
  select
    reserved_component_rows.timesheet_id,
    reserved_component_rows.key_type,
    reserved_component_rows.key_value,
    reserved_component_rows.amount_ex_vat,
    reserved_component_rows.amount_inc_vat
  from public._pay_reserved_components(
    (select input_scope.ts_ids from inp as input_scope),
    p_exclude_pay_batch_id
  ) as reserved_component_rows
),
component_truth_raw as (
  select
    family_to_projection.projected_timesheet_id as timesheet_id,
    upper(nullif(btrim(coalesce(finance_component_rows.component_key_type,'')), '')) as raw_key_type,
    nullif(btrim(coalesce(finance_component_rows.component_key_value,'')), '') as raw_key_value,
    case
      when jsonb_typeof(coalesce(finance_component_rows.source_basis_json, '{}'::jsonb)) = 'object'
        then coalesce(finance_component_rows.source_basis_json, '{}'::jsonb)
      else '{}'::jsonb
    end as source_basis_json,
    round(
      case
        when pay_advance_rows.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
          then coalesce(finance_component_rows.remaining_source_amount,0) * -1
        when pay_advance_rows.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
          then coalesce(finance_component_rows.remaining_source_amount,0)
        else 0
      end,
      2
    ) as signed_amount
  from family_to_projection
  join public.pay_finance_case_components as finance_component_rows
    on finance_component_rows.linked_timesheet_id = family_to_projection.family_timesheet_id
  join public.pay_advances as pay_advance_rows
    on pay_advance_rows.id = finance_component_rows.finance_case_id
  where finance_component_rows.linked_timesheet_id is not null
    and family_to_projection.projected_timesheet_id is not null
    and finance_component_rows.closed_at_utc is null
    and coalesce(finance_component_rows.remaining_source_amount,0) > 0
    and pay_advance_rows.case_type in (
      'OVERPAYMENT'::public.pay_finance_case_type_enum,
      'UNDERPAYMENT'::public.pay_finance_case_type_enum
    )
),
component_truth_prepared as (
  select
    component_truth_raw_rows.timesheet_id,
    component_truth_raw_rows.raw_key_type,
    component_truth_raw_rows.raw_key_value,
    component_truth_raw_rows.source_basis_json,
    component_truth_raw_rows.signed_amount,
    coalesce(
      upper(nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'item_type', '')), '')),
      case
        when component_truth_raw_rows.raw_key_type in ('TS_DAY','TS_TOTAL','CASE_TOTAL')
          then 'SEGMENT_DELTA'
        when nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'work_date','')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          then 'SEGMENT_DELTA'
        when component_truth_raw_rows.raw_key_type = 'ADJUSTMENT_CODE'
          then 'ADJUSTMENT_DELTA'
        when nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'adjustment_id','')), '') is not null
          then 'ADJUSTMENT_DELTA'
        when component_truth_raw_rows.raw_key_type = 'EXPENSE_CODE'
         and upper(coalesce(component_truth_raw_rows.raw_key_value, '')) = 'MILEAGE'
          then 'MILEAGE_DELTA'
        when component_truth_raw_rows.raw_key_type in ('ADDITIONAL_CODE','EXPENSE_CODE')
          then 'EXPENSE_DELTA'
        when nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'additional_code','')), '') is not null
          then 'EXPENSE_DELTA'
        when nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'expense_code','')), '') is not null
          then 'EXPENSE_DELTA'
        else null::text
      end
    ) as resolver_item_type,
    nullif(btrim(coalesce(component_truth_raw_rows.source_basis_json->>'work_date','')), '') as source_work_date_text
  from component_truth_raw as component_truth_raw_rows
),
component_truth_keyed as (
  select
    component_truth_prepared_rows.timesheet_id,
    resolved_component_keys.key_type,
    resolved_component_keys.key_value,
    component_truth_prepared_rows.signed_amount
  from component_truth_prepared as component_truth_prepared_rows
  join lateral public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => component_truth_prepared_rows.timesheet_id,
    p_live_source_json => component_truth_prepared_rows.source_basis_json || jsonb_build_object(
      'timesheet_id', component_truth_prepared_rows.timesheet_id::text,
      'item_type', component_truth_prepared_rows.resolver_item_type,
      'component_key_type', component_truth_prepared_rows.raw_key_type,
      'component_key_value', component_truth_prepared_rows.raw_key_value,
      'work_date', component_truth_prepared_rows.source_work_date_text,
      'live_truth_used', true
    ),
    p_item_type => component_truth_prepared_rows.resolver_item_type,
    p_key_type_hint => component_truth_prepared_rows.raw_key_type,
    p_key_value_hint => component_truth_prepared_rows.raw_key_value,
    p_work_date => case
      when component_truth_prepared_rows.source_work_date_text ~ '^\d{4}-\d{2}-\d{2}$'
        then component_truth_prepared_rows.source_work_date_text::date
      when component_truth_prepared_rows.raw_key_type = 'TS_DAY'
       and component_truth_prepared_rows.raw_key_value ~ '^\d{4}-\d{2}-\d{2}$'
        then component_truth_prepared_rows.raw_key_value::date
      else null::date
    end
  ) as resolved_component_keys
    on true
  where resolved_component_keys.key_resolution_failure_reason is null
),
component_truth as (
  select
    component_truth_keyed_rows.timesheet_id,
    component_truth_keyed_rows.key_type,
    component_truth_keyed_rows.key_value,
    round(sum(component_truth_keyed_rows.signed_amount), 2) as truth_ex_vat,
    round(sum(component_truth_keyed_rows.signed_amount), 2) as truth_inc_vat
  from component_truth_keyed as component_truth_keyed_rows
  where component_truth_keyed_rows.key_type is not null
    and btrim(component_truth_keyed_rows.key_type) <> ''
    and component_truth_keyed_rows.key_value is not null
    and btrim(component_truth_keyed_rows.key_value) <> ''
  group by
    component_truth_keyed_rows.timesheet_id,
    component_truth_keyed_rows.key_type,
    component_truth_keyed_rows.key_value
),
component_keys as (
  select distinct
    component_truth_keys.timesheet_id,
    component_truth_keys.key_type,
    component_truth_keys.key_value
  from component_truth as component_truth_keys
),
component_joined as (
  select
    component_keys.timesheet_id,
    component_keys.key_type,
    component_keys.key_value,
    coalesce(component_truth.truth_ex_vat,0) as truth_ex_vat,
    0::numeric as baseline_ex_vat,
    coalesce(reserved_components.amount_ex_vat,0) as reserved_ex_vat,
    coalesce(component_truth.truth_inc_vat,0) as truth_inc_vat,
    0::numeric as baseline_inc_vat,
    coalesce(reserved_components.amount_inc_vat,0) as reserved_inc_vat
  from component_keys
  left join component_truth
    on component_truth.timesheet_id = component_keys.timesheet_id
   and component_truth.key_type = component_keys.key_type
   and component_truth.key_value = component_keys.key_value
  left join reserved_components
    on reserved_components.timesheet_id = component_keys.timesheet_id
   and reserved_components.key_type = component_keys.key_type
   and reserved_components.key_value = component_keys.key_value
),
all_legacy_keys as (
  select distinct
    legacy_key_rows.timesheet_id,
    legacy_key_rows.key_type,
    legacy_key_rows.key_value
  from (
    select
      timesheet_entitlement_components.timesheet_id,
      timesheet_entitlement_components.key_type,
      timesheet_entitlement_components.key_value
    from timesheet_entitlement_components
    union all
    select
      reserved_components.timesheet_id,
      reserved_components.key_type,
      reserved_components.key_value
    from reserved_components
  ) as legacy_key_rows
),
legacy_joined as (
  select
    all_legacy_keys.timesheet_id,
    all_legacy_keys.key_type,
    all_legacy_keys.key_value,
    coalesce(timesheet_entitlement_components.truth_ex_vat,0) as truth_ex_vat,
    coalesce(timesheet_entitlement_components.baseline_ex_vat,0) as baseline_ex_vat,
    coalesce(reserved_components.amount_ex_vat,0) as reserved_ex_vat,
    coalesce(timesheet_entitlement_components.truth_inc_vat,0) as truth_inc_vat,
    coalesce(timesheet_entitlement_components.baseline_inc_vat,0) as baseline_inc_vat,
    coalesce(reserved_components.amount_inc_vat,0) as reserved_inc_vat
  from all_legacy_keys
  left join timesheet_entitlement_components
    on timesheet_entitlement_components.timesheet_id = all_legacy_keys.timesheet_id
   and timesheet_entitlement_components.key_type = all_legacy_keys.key_type
   and timesheet_entitlement_components.key_value = all_legacy_keys.key_value
  left join reserved_components
    on reserved_components.timesheet_id = all_legacy_keys.timesheet_id
   and reserved_components.key_type = all_legacy_keys.key_type
   and reserved_components.key_value = all_legacy_keys.key_value
),
final_rows as (
  select
    component_joined.timesheet_id,
    component_joined.key_type,
    component_joined.key_value,
    component_joined.truth_ex_vat,
    component_joined.baseline_ex_vat,
    component_joined.reserved_ex_vat,
    component_joined.truth_inc_vat,
    component_joined.baseline_inc_vat,
    component_joined.reserved_inc_vat
  from component_joined

  union all

  select
    legacy_joined.timesheet_id,
    legacy_joined.key_type,
    legacy_joined.key_value,
    legacy_joined.truth_ex_vat,
    legacy_joined.baseline_ex_vat,
    legacy_joined.reserved_ex_vat,
    legacy_joined.truth_inc_vat,
    legacy_joined.baseline_inc_vat,
    legacy_joined.reserved_inc_vat
  from legacy_joined
  where not exists (
    select 1
    from component_truth
    where component_truth.timesheet_id = legacy_joined.timesheet_id
      and component_truth.key_type = legacy_joined.key_type
      and component_truth.key_value = legacy_joined.key_value
  )
)
select
  final_rows.timesheet_id,
  final_rows.key_type,
  final_rows.key_value,
  round(final_rows.truth_ex_vat,2) as truth_ex_vat,
  round(final_rows.baseline_ex_vat,2) as baseline_ex_vat,
  round(final_rows.reserved_ex_vat,2) as reserved_ex_vat,
  round(final_rows.truth_ex_vat - final_rows.baseline_ex_vat - final_rows.reserved_ex_vat,2) as outstanding_ex_vat,
  round(final_rows.truth_inc_vat,2) as truth_inc_vat,
  round(final_rows.baseline_inc_vat,2) as baseline_inc_vat,
  round(final_rows.reserved_inc_vat,2) as reserved_inc_vat,
  round(final_rows.truth_inc_vat - final_rows.baseline_inc_vat - final_rows.reserved_inc_vat,2) as outstanding_inc_vat,
  (
    round(abs(final_rows.reserved_ex_vat),2) >
    round(abs(greatest(final_rows.truth_ex_vat - final_rows.baseline_ex_vat, 0)),2)
  ) as reservation_overrun_detected
from final_rows
where final_rows.timesheet_id is not null
  and final_rows.key_type is not null
  and final_rows.key_value is not null;
$function$;


-- =========================================================
-- NEW - public._pay_outstanding_components - wrapper uuid array.txt
-- =========================================================

CREATE OR REPLACE FUNCTION public._pay_outstanding_components(p_timesheet_ids uuid[])
RETURNS TABLE(
  timesheet_id uuid,
  key_type text,
  key_value text,
  truth_ex_vat numeric,
  baseline_ex_vat numeric,
  reserved_ex_vat numeric,
  outstanding_ex_vat numeric,
  truth_inc_vat numeric,
  baseline_inc_vat numeric,
  reserved_inc_vat numeric,
  outstanding_inc_vat numeric,
  reservation_overrun_detected boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
SELECT
  outstanding_component_rows.timesheet_id,
  outstanding_component_rows.key_type,
  outstanding_component_rows.key_value,
  outstanding_component_rows.truth_ex_vat,
  outstanding_component_rows.baseline_ex_vat,
  outstanding_component_rows.reserved_ex_vat,
  outstanding_component_rows.outstanding_ex_vat,
  outstanding_component_rows.truth_inc_vat,
  outstanding_component_rows.baseline_inc_vat,
  outstanding_component_rows.reserved_inc_vat,
  outstanding_component_rows.outstanding_inc_vat,
  outstanding_component_rows.reservation_overrun_detected
FROM public._pay_outstanding_components(p_timesheet_ids, NULL::uuid) AS outstanding_component_rows;
$function$;











CREATE OR REPLACE FUNCTION public._pay_candidate_week_totals(p_candidate_ids uuid[], p_week_start date)
RETURNS TABLE (
  candidate_id uuid,
  week_start date,
  paid_wtd numeric,
  loan_repaid_wtd numeric,
  overpay_recovered_wtd numeric
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAY_CANDIDATE_WEEK_TOTALS_START',
    jsonb_build_object(
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'week_start', p_week_start
    ),
    'pay_candidate_week_totals',
    COALESCE(p_week_start::text, 'NO_WEEK_START'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN QUERY
  WITH
  inp AS (
    SELECT
      COALESCE(
        (
          SELECT array_agg(DISTINCT input_candidate_ids.candidate_id_value)
          FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS input_candidate_ids(candidate_id_value)
          WHERE input_candidate_ids.candidate_id_value IS NOT NULL
        ),
        ARRAY[]::uuid[]
      ) AS cand_ids,
      p_week_start AS week_start,
      (p_week_start + INTERVAL '6 days')::date AS week_end
  ),
  eligible_batches AS (
    SELECT
      public.pay_batches.id AS pay_batch_id
    FROM inp
    JOIN public.pay_batches
      ON public.pay_batches.pay_date >= inp.week_start
     AND public.pay_batches.pay_date <= inp.week_end
    WHERE public.pay_batches.cancelled_at_utc IS NULL
      AND upper(coalesce(public.pay_batches.batch_kind_fixed,'')) <> 'LOANS'
  ),
  settled_candidate_rows AS (
    SELECT
      public.pay_batch_candidates.id AS pay_batch_candidate_id,
      public.pay_batch_candidates.candidate_id,
      public.pay_batch_candidates.pay_batch_id,
      COALESCE(public.pay_batch_candidates.net_bank_amount,0)::numeric AS net_bank_amount
    FROM inp
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.candidate_id = ANY(inp.cand_ids)
    JOIN eligible_batches
      ON eligible_batches.pay_batch_id = public.pay_batch_candidates.pay_batch_id
    WHERE public.pay_batch_candidates.settled_at_utc IS NOT NULL
      AND upper(coalesce(public.pay_batch_candidates.settlement_status,'')) = 'SETTLED'
  ),
  corrected_candidate_item_amounts AS (
    SELECT
      settled_candidate_rows.pay_batch_candidate_id,
      round(
        COALESCE(
          sum(COALESCE(public.pay_batch_items.amount_inc_vat, public.pay_batch_items.amount_ex_vat, 0)),
          0
        ),
        2
      ) AS corrected_amount_inc_vat
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    JOIN public.pay_payment_correction_items
      ON public.pay_payment_correction_items.pay_batch_item_id = public.pay_batch_items.id
     AND public.pay_payment_correction_items.status = 'APPLIED'
     AND public.pay_payment_correction_items.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    GROUP BY settled_candidate_rows.pay_batch_candidate_id
  ),
  paid AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(
        COALESCE(
          sum(
            COALESCE(settled_candidate_rows.net_bank_amount,0)
            - COALESCE(corrected_candidate_item_amounts.corrected_amount_inc_vat,0)
          ),
          0
        ),
        2
      ) AS paid_wtd
    FROM settled_candidate_rows
    LEFT JOIN corrected_candidate_item_amounts
      ON corrected_candidate_item_amounts.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    GROUP BY settled_candidate_rows.candidate_id
  ),
  loan_rep AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(sum(abs(coalesce(public.pay_batch_items.amount_ex_vat, public.pay_batch_items.amount_inc_vat, 0))),2) AS loan_repaid_wtd
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    WHERE COALESCE(public.pay_batch_items.is_voided, false) = false
      AND public.pay_batch_items.item_type = 'LOAN_REPAYMENT'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    GROUP BY settled_candidate_rows.candidate_id
  ),
  overpay_rec AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(sum(abs(coalesce(public.pay_batch_items.amount_ex_vat, public.pay_batch_items.amount_inc_vat, 0))),2) AS overpay_recovered_wtd
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    WHERE COALESCE(public.pay_batch_items.is_voided, false) = false
      AND public.pay_batch_items.item_type = 'OVERPAYMENT_RECOVERY'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    GROUP BY settled_candidate_rows.candidate_id
  )
  SELECT
    public.candidates.id AS candidate_id,
    (SELECT inp.week_start FROM inp) AS week_start,
    COALESCE(paid.paid_wtd,0) AS paid_wtd,
    COALESCE(loan_rep.loan_repaid_wtd,0) AS loan_repaid_wtd,
    COALESCE(overpay_rec.overpay_recovered_wtd,0) AS overpay_recovered_wtd
  FROM inp
  JOIN public.candidates
    ON public.candidates.id = ANY(inp.cand_ids)
  LEFT JOIN paid
    ON paid.candidate_id = public.candidates.id
  LEFT JOIN loan_rep
    ON loan_rep.candidate_id = public.candidates.id
  LEFT JOIN overpay_rec
    ON overpay_rec.candidate_id = public.candidates.id;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAY_CANDIDATE_WEEK_TOTALS_RESULT',
    jsonb_build_object(
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'week_start', p_week_start
    ),
    'pay_candidate_week_totals',
    COALESCE(p_week_start::text, 'NO_WEEK_START'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      NULL::uuid,
      'PAY_CANDIDATE_WEEK_TOTALS_ERROR',
      jsonb_build_object(
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'week_start', p_week_start,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_candidate_week_totals',
      COALESCE(p_week_start::text, 'NO_WEEK_START'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
END;
$function$;


DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(
  date,
  date,
  uuid,
  jsonb,
  uuid,
  uuid,
  uuid[],
  text,
  public.pay_override_mode_enum
);




DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(date, date, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum, boolean, boolean, uuid, timestamptz);
DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(date, date, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum, boolean, boolean, uuid, timestamptz, uuid, boolean);



CREATE OR REPLACE FUNCTION public.pay_create_draft_batches_split(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_preview_decisions_json jsonb,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[],
  p_override_reason text DEFAULT NULL::text,
  p_override_mode pay_override_mode_enum DEFAULT 'NONE'::pay_override_mode_enum,
  p_override_continue boolean DEFAULT false,
  p_override_verified boolean DEFAULT false,
  p_override_verified_by_user_id uuid DEFAULT NULL::uuid,
  p_override_verified_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_status text := NULL::text;
  v_is_terminal boolean := false;
  v_requires_operation_runner boolean := false;
  v_expected_source_session_version bigint := NULL::bigint;
  v_expected_source_snapshot_run_id uuid := NULL::uuid;
  v_operation_input_pay_date date := NULL::date;
  v_operation_input_week_ending_cutoff date := NULL::date;
  v_scope_count integer := 0;
  v_invalid_scope_count integer := 0;
  v_candidate_count integer := 0;
  v_paye_scope_count integer := 0;
  v_umbrella_scope_count integer := 0;
  v_distinct_batch_count integer := 0;
  v_paye_batch_count integer := 0;
  v_umbrella_batch_count integer := 0;
  v_cross_channel_shared_batch_count integer := 0;
  v_paye_batch_id uuid := NULL::uuid;
  v_umbrella_batch_id uuid := NULL::uuid;
  v_scope_status_counts jsonb := '{}'::jsonb;
  v_scope_batch_ids jsonb := '[]'::jsonb;
  v_operation_batch_ids jsonb := '[]'::jsonb;
  v_invalid_batch_count integer := 0;
  v_post_shell_phase boolean := false;
BEGIN
  IF COALESCE(p_allow_legacy_unchunked, false) IS TRUE THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED', 'message', 'Legacy split all-at-once draft creation is permanently disabled. Use the Banking Pay DRAFT_CREATE operation flow.', 'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END, 'allow_legacy_unchunked', true)::text;
  END IF;
  IF p_pay_date IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'pay_date is required'; END IF;
  IF p_week_ending_cutoff IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'week_ending_cutoff is required'; END IF;
  IF p_actor_user_id IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'actor_user_id is required'; END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_REQUIRED',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_REQUIRED', 'message', 'Split draft creation requires an operation-scoped Banking Pay DRAFT_CREATE operation.', 'pay_date', p_pay_date::text, 'week_ending_cutoff', p_week_ending_cutoff::text)::text;
  END IF;

  SELECT operation_row.* INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE OF operation_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_NOT_FOUND', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;
  IF v_operation_row.operation_type IS DISTINCT FROM 'DRAFT_CREATE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_TYPE_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'actual_operation_type', v_operation_row.operation_type)::text;
  END IF;
  IF v_operation_row.actor_user_id IS NULL OR v_operation_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_ACTOR_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_ACTOR_INVALID', 'operation_id', p_operation_id::text)::text;
  END IF;

  v_operation_status := UPPER(BTRIM(COALESCE(v_operation_row.status, '')));
  IF v_operation_status NOT IN ('QUEUED', 'RUNNING', 'WAITING', 'COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_STATUS_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_STATUS_INVALID', 'operation_id', p_operation_id::text, 'operation_status', v_operation_row.status)::text;
  END IF;
  v_is_terminal := v_operation_status IN ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED');
  v_requires_operation_runner := v_operation_status IN ('QUEUED', 'RUNNING', 'WAITING');

  IF v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SESSION_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_SESSION_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT session_row.* INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_operation_row.workbench_session_id
  FOR UPDATE OF session_row;
  IF NOT FOUND OR v_session_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_SESSION_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_SESSION_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_operation_row.workbench_session_id::text)::text;
  END IF;
  IF v_session_row.pay_date IS DISTINCT FROM p_pay_date OR v_session_row.week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_CONTEXT_MISMATCH',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_CONTEXT_MISMATCH', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'expected_pay_date', v_session_row.pay_date::text, 'supplied_pay_date', p_pay_date::text, 'expected_week_ending_cutoff', v_session_row.week_ending_cutoff::text, 'supplied_week_ending_cutoff', p_week_ending_cutoff::text, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF COALESCE(v_operation_row.input_json->>'source_session_version', '') !~ '^[1-9][0-9]*$'
     OR COALESCE(v_operation_row.input_json->>'source_snapshot_run_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(v_operation_row.input_json->>'pay_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR COALESCE(NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''), v_operation_row.input_json->>'week_ending_cutoff_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_REQUIRED',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_REQUIRED',
        'operation_id', p_operation_id::text,
        'workbench_session_id', v_session_row.id::text,
        'source_session_version_present', COALESCE(v_operation_row.input_json->>'source_session_version', '') ~ '^[1-9][0-9]*$',
        'source_snapshot_run_id_present', COALESCE(v_operation_row.input_json->>'source_snapshot_run_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
        'pay_date_present', COALESCE(v_operation_row.input_json->>'pay_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
        'week_ending_cutoff_present', COALESCE(NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''), v_operation_row.input_json->>'week_ending_cutoff_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
        'refresh_required', NOT v_is_terminal,
        'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
      )::text;
  END IF;

  BEGIN
    v_expected_source_session_version := (v_operation_row.input_json->>'source_session_version')::bigint;
    v_expected_source_snapshot_run_id := (v_operation_row.input_json->>'source_snapshot_run_id')::uuid;
    v_operation_input_pay_date := (v_operation_row.input_json->>'pay_date')::date;
    v_operation_input_week_ending_cutoff := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''),
      v_operation_row.input_json->>'week_ending_cutoff_date'
    )::date;
  EXCEPTION
    WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_INVALID',
        DETAIL = jsonb_build_object(
          'ok', false,
          'code', 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_INVALID',
          'operation_id', p_operation_id::text,
          'workbench_session_id', v_session_row.id::text,
          'refresh_required', NOT v_is_terminal,
          'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
        )::text;
  END;

  IF v_operation_input_pay_date IS DISTINCT FROM p_pay_date
     OR v_operation_input_week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff
     OR v_operation_input_pay_date IS DISTINCT FROM v_session_row.pay_date
     OR v_operation_input_week_ending_cutoff IS DISTINCT FROM v_session_row.week_ending_cutoff THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_CONTEXT_MISMATCH',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_CONTEXT_MISMATCH',
        'operation_id', p_operation_id::text,
        'workbench_session_id', v_session_row.id::text,
        'operation_pay_date', v_operation_input_pay_date::text,
        'supplied_pay_date', p_pay_date::text,
        'session_pay_date', v_session_row.pay_date::text,
        'operation_week_ending_cutoff', v_operation_input_week_ending_cutoff::text,
        'supplied_week_ending_cutoff', p_week_ending_cutoff::text,
        'session_week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'refresh_required', NOT v_is_terminal,
        'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
      )::text;
  END IF;

  IF NOT v_is_terminal AND (
    v_session_row.status IS DISTINCT FROM 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL OR v_session_row.replacement_session_id IS NOT NULL
    OR v_session_row.version IS DISTINCT FROM v_expected_source_session_version OR v_session_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_SESSION_STALE', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_SESSION_STALE', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'refresh_required', true, 'next_action', 'REFRESH_WORKBENCH')::text;
  END IF;

  PERFORM scope_row.id
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
  ORDER BY scope_row.id
  FOR UPDATE OF scope_row;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (
      WHERE scope_row.workbench_session_id IS DISTINCT FROM v_session_row.id
         OR scope_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
         OR scope_row.source_session_version IS DISTINCT FROM v_expected_source_session_version
         OR UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) NOT IN ('PAYE', 'UMBRELLA')
         OR scope_row.status NOT IN ('PENDING', 'SCOPED', 'ALLOCATED', 'DRAFTED', 'FAILED')
    )::integer,
    COUNT(DISTINCT scope_row.candidate_id)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(scope_row.pay_channel)) = 'PAYE')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(scope_row.pay_channel)) = 'UMBRELLA')::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL)::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL AND UPPER(BTRIM(scope_row.pay_channel)) = 'PAYE')::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL AND UPPER(BTRIM(scope_row.pay_channel)) = 'UMBRELLA')::integer,
    COALESCE(jsonb_agg(DISTINCT scope_row.pay_batch_id::text ORDER BY scope_row.pay_batch_id::text) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL), '[]'::jsonb)
  INTO v_scope_count, v_invalid_scope_count, v_candidate_count, v_paye_scope_count, v_umbrella_scope_count,
       v_distinct_batch_count, v_paye_batch_count, v_umbrella_batch_count, v_scope_batch_ids
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id;

  SELECT COUNT(*)::integer INTO v_cross_channel_shared_batch_count
  FROM (
    SELECT scope_batch.pay_batch_id
    FROM public.banking_pay_operation_candidate_scope AS scope_batch
    WHERE scope_batch.operation_id = p_operation_id AND scope_batch.pay_batch_id IS NOT NULL
    GROUP BY scope_batch.pay_batch_id
    HAVING COUNT(DISTINCT UPPER(BTRIM(scope_batch.pay_channel))) > 1
  ) AS shared_batch;

  SELECT scope_batch.pay_batch_id INTO v_paye_batch_id
  FROM public.banking_pay_operation_candidate_scope AS scope_batch
  WHERE scope_batch.operation_id = p_operation_id AND UPPER(BTRIM(scope_batch.pay_channel)) = 'PAYE' AND scope_batch.pay_batch_id IS NOT NULL
  GROUP BY scope_batch.pay_batch_id ORDER BY scope_batch.pay_batch_id LIMIT 1;
  SELECT scope_batch.pay_batch_id INTO v_umbrella_batch_id
  FROM public.banking_pay_operation_candidate_scope AS scope_batch
  WHERE scope_batch.operation_id = p_operation_id AND UPPER(BTRIM(scope_batch.pay_channel)) = 'UMBRELLA' AND scope_batch.pay_batch_id IS NOT NULL
  GROUP BY scope_batch.pay_batch_id ORDER BY scope_batch.pay_batch_id LIMIT 1;

  SELECT COALESCE(jsonb_object_agg(status_count.status, status_count.row_count), '{}'::jsonb) INTO v_scope_status_counts
  FROM (
    SELECT scope_status.status, COUNT(*)::integer AS row_count
    FROM public.banking_pay_operation_candidate_scope AS scope_status
    WHERE scope_status.operation_id = p_operation_id
    GROUP BY scope_status.status
  ) AS status_count;

  IF COALESCE(v_invalid_scope_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_CANDIDATE_SCOPE_AUTHORITY_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_CANDIDATE_SCOPE_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'invalid_scope_count', v_invalid_scope_count, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF COALESCE(v_distinct_batch_count, 0) > 2 OR COALESCE(v_paye_batch_count, 0) > 1 OR COALESCE(v_umbrella_batch_count, 0) > 1 OR COALESCE(v_cross_channel_shared_batch_count, 0) > 0
     OR (v_operation_row.pay_batch_id IS NOT NULL AND COALESCE(v_distinct_batch_count, 0) > 0 AND NOT EXISTS (SELECT 1 FROM public.banking_pay_operation_candidate_scope AS primary_scope WHERE primary_scope.operation_id = p_operation_id AND primary_scope.pay_batch_id = v_operation_row.pay_batch_id)) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_SPLIT_BATCH_AUTHORITY_INVALID',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_SPLIT_BATCH_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'distinct_pay_batch_count', COALESCE(v_distinct_batch_count, 0), 'paye_batch_count', COALESCE(v_paye_batch_count, 0), 'umbrella_batch_count', COALESCE(v_umbrella_batch_count, 0), 'cross_channel_shared_batch_count', COALESCE(v_cross_channel_shared_batch_count, 0), 'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF v_operation_row.phase NOT IN ('INITIALISE', 'VALIDATE_SESSION', 'SYNC_SELECTED_ROWS', 'WAIT_FOR_PREVIEW_READY', 'SEED_CANDIDATE_SCOPE') AND COALESCE(v_scope_count, 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_CANDIDATE_SCOPE_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_CANDIDATE_SCOPE_REQUIRED', 'operation_id', p_operation_id::text, 'phase', v_operation_row.phase, 'workbench_session_id', v_session_row.id::text)::text;
  END IF;

  v_post_shell_phase := UPPER(BTRIM(COALESCE(v_operation_row.phase, ''))) IN ('SEED_DRAFT_CHUNKS', 'INSERT_CANDIDATES', 'INSERT_ITEMS', 'APPLY_FINANCE_ADJUSTMENTS', 'FINALISE_RESERVATIONS', 'POPULATE_CANDIDATE_SUMMARIES', 'CREATE_TIMESHEET_SNAPSHOTS', 'BUILD_ITEM_BREAKDOWNS', 'ASSERT_INTEGRITY', 'POST_CREATE_REFRESH', 'COMPLETE');
  IF (v_post_shell_phase OR v_operation_status = 'COMPLETE') AND (
       (COALESCE(v_paye_scope_count, 0) > 0 AND COALESCE(v_paye_batch_count, 0) <> 1)
       OR (COALESCE(v_umbrella_scope_count, 0) > 0 AND COALESCE(v_umbrella_batch_count, 0) <> 1)
     ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_SPLIT_BATCH_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_SPLIT_BATCH_REQUIRED', 'operation_id', p_operation_id::text, 'paye_scope_count', v_paye_scope_count, 'paye_batch_count', v_paye_batch_count, 'umbrella_scope_count', v_umbrella_scope_count, 'umbrella_batch_count', v_umbrella_batch_count)::text;
  END IF;

  PERFORM batch_row.id
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id OR batch_row.id IN (SELECT DISTINCT candidate_scope.pay_batch_id FROM public.banking_pay_operation_candidate_scope AS candidate_scope WHERE candidate_scope.operation_id = p_operation_id AND candidate_scope.pay_batch_id IS NOT NULL)
  ORDER BY batch_row.id FOR UPDATE OF batch_row;

  SELECT COALESCE(jsonb_agg(batch_row.id::text ORDER BY batch_row.id::text), '[]'::jsonb),
         COUNT(*) FILTER (
           WHERE batch_row.source_workbench_session_id IS DISTINCT FROM v_session_row.id
              OR batch_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
              OR batch_row.source_session_version IS DISTINCT FROM v_expected_source_session_version
              OR batch_row.pay_date IS DISTINCT FROM p_pay_date
              OR EXISTS (
                SELECT 1
                FROM public.banking_pay_operation_candidate_scope AS batch_scope
                WHERE batch_scope.operation_id = p_operation_id
                  AND batch_scope.pay_batch_id = batch_row.id
                  AND (
                    NULLIF(UPPER(BTRIM(COALESCE(batch_row.batch_kind_fixed, ''))), '') IS NULL
                    OR UPPER(BTRIM(COALESCE(batch_scope.pay_channel, ''))) IS DISTINCT FROM UPPER(BTRIM(batch_row.batch_kind_fixed))
                  )
              )
              OR (NOT v_is_terminal AND (UPPER(BTRIM(COALESCE(batch_row.status, ''))) <> 'DRAFT' OR UPPER(BTRIM(COALESCE(batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'))
         )::integer
  INTO v_operation_batch_ids, v_invalid_batch_count
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id OR batch_row.id IN (SELECT DISTINCT candidate_scope.pay_batch_id FROM public.banking_pay_operation_candidate_scope AS candidate_scope WHERE candidate_scope.operation_id = p_operation_id AND candidate_scope.pay_batch_id IS NOT NULL);

  IF COALESCE(v_invalid_batch_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_BATCH_AUTHORITY_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_BATCH_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'pay_batch_ids', v_operation_batch_ids, 'invalid_batch_count', v_invalid_batch_count, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  RETURN jsonb_build_object(
    'ok', v_operation_status NOT IN ('FAILED', 'CANCELLED'),
    'operation_mode', true, 'legacy_unchunked_permanently_disabled', true, 'no_direct_batch_creation', true,
    'split_authority', 'OPERATION_CANDIDATE_SCOPE_PAY_CHANNEL', 'requires_operation_runner', v_requires_operation_runner, 'terminal', v_is_terminal,
    'operation_id', v_operation_row.id::text, 'operation_type', v_operation_row.operation_type, 'status', v_operation_row.status, 'phase', v_operation_row.phase,
    'actor_user_id', v_operation_row.actor_user_id::text, 'workbench_session_id', v_session_row.id::text,
    'workbench_session_version', v_expected_source_session_version, 'source_snapshot_run_id', CASE WHEN v_expected_source_snapshot_run_id IS NULL THEN NULL ELSE v_expected_source_snapshot_run_id::text END,
    'pay_date', v_session_row.pay_date::text, 'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'candidate_scope_count', COALESCE(v_scope_count, 0), 'candidate_count', COALESCE(v_candidate_count, 0),
    'paye_candidate_scope_count', COALESCE(v_paye_scope_count, 0), 'umbrella_candidate_scope_count', COALESCE(v_umbrella_scope_count, 0),
    'distinct_pay_batch_count', COALESCE(v_distinct_batch_count, 0), 'paye_pay_batch_count', COALESCE(v_paye_batch_count, 0), 'umbrella_pay_batch_count', COALESCE(v_umbrella_batch_count, 0),
    'paye_pay_batch_id', CASE WHEN v_paye_batch_id IS NULL THEN NULL ELSE v_paye_batch_id::text END, 'umbrella_pay_batch_id', CASE WHEN v_umbrella_batch_id IS NULL THEN NULL ELSE v_umbrella_batch_id::text END,
    'scope_status_counts', COALESCE(v_scope_status_counts, '{}'::jsonb), 'scope_pay_batch_ids', COALESCE(v_scope_batch_ids, '[]'::jsonb), 'operation_pay_batch_ids', COALESCE(v_operation_batch_ids, '[]'::jsonb),
    'pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
    'total_units', v_operation_row.total_units, 'completed_units', v_operation_row.completed_units, 'failed_units', v_operation_row.failed_units,
    'current_chunk_index', v_operation_row.current_chunk_index, 'chunk_count', v_operation_row.chunk_count,
    'progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
    'result_json', CASE WHEN v_operation_status IN ('COMPLETE', 'REVIEW_REQUIRED') THEN v_operation_row.result_json ELSE NULL END,
    'error_json', CASE WHEN v_operation_status IN ('FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN v_operation_row.error_json ELSE NULL END,
    'message', 'PAYE and UMBRELLA draft splitting is controlled by the scalable Banking Pay DRAFT_CREATE operation runner.'
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.bank_name_check_record_result(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_bank_details_hash text,
  p_status text,
  p_result_json jsonb,
  p_checked_at_utc timestamptz,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_provided_hash text := btrim(coalesce(p_bank_details_hash, ''));

  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_hash_is_valid boolean := false;
  v_now timestamptz := now();

  v_inserted boolean := false;
  v_action text := null;
  v_row_json jsonb;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;
  if v_status not in ('UNVERIFIED', 'PASS', 'NEAR_MATCH', 'FAIL', 'UNAVAILABLE') then
    raise exception '%', jsonb_build_object('error', 'INVALID_STATUS')::text;
  end if;
  if v_provided_hash = '' then
    raise exception '%', jsonb_build_object('error', 'BANK_DETAILS_HASH_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  v_hash_is_valid := (v_current_hash is not null and v_current_hash = v_provided_hash);

  if not v_hash_is_valid and v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_provided_hash
    )
    into v_hash_is_valid;
  end if;

  if not v_hash_is_valid then
    return jsonb_build_object(
      'ok', true,
      'action', 'ignored_stale_hash',
      'ignored', true,
      'reason', 'STALE_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'current_bank_details_hash', v_current_hash,
      'provided_bank_details_hash', v_provided_hash
    );
  end if;

  with upserted as (
    insert into public.bank_name_checks (
      rail_provider,
      rail_env,
      entity_kind,
      entity_id,
      bank_details_hash,
      status,
      checked_at_utc,
      result_json,
      created_at_utc,
      updated_at_utc,
      override_reason,
      override_by_user_id,
      override_at_utc,
      override_hash
    )
    values (
      v_provider,
      v_env,
      v_kind,
      p_entity_id,
      v_provided_hash,
      v_status,
      coalesce(p_checked_at_utc, v_now),
      p_result_json,
      v_now,
      v_now,
      null::text,
      null::uuid,
      null::timestamptz,
      null::text
    )
    on conflict (rail_provider, rail_env, entity_kind, entity_id, bank_details_hash)
    do update set
      status = excluded.status,
      checked_at_utc = excluded.checked_at_utc,
      result_json = excluded.result_json,
      updated_at_utc = v_now,
      override_reason = case
        when excluded.status = 'PASS' then null::text
        else public.bank_name_checks.override_reason
      end,
      override_by_user_id = case
        when excluded.status = 'PASS' then null::uuid
        else public.bank_name_checks.override_by_user_id
      end,
      override_at_utc = case
        when excluded.status = 'PASS' then null::timestamptz
        else public.bank_name_checks.override_at_utc
      end,
      override_hash = case
        when excluded.status = 'PASS' then null::text
        else public.bank_name_checks.override_hash
      end
    returning
      public.bank_name_checks.*,
      (xmax = 0) as inserted_flag
  )
  select
    u.inserted_flag,
    jsonb_build_object(
      'id', u.id::text,
      'rail_provider', u.rail_provider,
      'rail_env', u.rail_env,
      'entity_kind', u.entity_kind,
      'entity_id', u.entity_id::text,
      'bank_details_hash', u.bank_details_hash,
      'status', u.status,
      'checked_at_utc', u.checked_at_utc,
      'result_json', u.result_json,
      'override_reason', u.override_reason,
      'override_by_user_id', case when u.override_by_user_id is null then null else u.override_by_user_id::text end,
      'override_at_utc', u.override_at_utc,
      'override_hash', u.override_hash,
      'created_at_utc', u.created_at_utc,
      'updated_at_utc', u.updated_at_utc
    )
  into
    v_inserted,
    v_row_json
  from upserted u
  limit 1;

  v_action := case when v_inserted then 'inserted' else 'updated' end;

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'ignored', false,
    'row', v_row_json
  );
end;
$function$;



DROP FUNCTION IF EXISTS public.bank_name_check_set_override(text, text, text, uuid, text, uuid);

CREATE OR REPLACE FUNCTION public.bank_name_check_set_override(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_reason text,
  p_actor_user_id uuid,
  p_bank_details_hash text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_requested_hash text := nullif(btrim(coalesce(p_bank_details_hash, '')), '');
  v_now timestamptz := now();

  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_target_hash text := null;
  v_target_is_valid_oneoff boolean := false;

  v_before public.bank_name_checks%rowtype;
  v_row public.bank_name_checks%rowtype;

  v_before_json jsonb := null;
  v_after_json jsonb := null;

  v_inserted boolean := false;
  v_action text := null;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;
  if v_reason is null then
    raise exception '%', jsonb_build_object('error', 'REASON_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  if v_requested_hash is null then
    v_target_hash := v_current_hash;
  elsif v_current_hash is not null and v_current_hash = v_requested_hash then
    v_target_hash := v_current_hash;
  elsif v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_requested_hash
    )
    into v_target_is_valid_oneoff;

    if v_target_is_valid_oneoff then
      v_target_hash := v_requested_hash;
    end if;
  end if;

  if v_target_hash is null then
    if v_requested_hash is null then
      raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'INVALID_TARGET_BANK_DETAILS_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'bank_details_hash', v_requested_hash
    )::text;
  end if;

  select bnc.*
  into v_before
  from public.bank_name_checks bnc
  where bnc.rail_provider = v_provider
    and bnc.rail_env = v_env
    and bnc.entity_kind = v_kind
    and bnc.entity_id = p_entity_id
    and bnc.bank_details_hash = v_target_hash
  limit 1;

  if v_before.id is not null then
    v_before_json := jsonb_build_object(
      'id', v_before.id::text,
      'rail_provider', v_before.rail_provider,
      'rail_env', v_before.rail_env,
      'entity_kind', v_before.entity_kind,
      'entity_id', v_before.entity_id::text,
      'bank_details_hash', v_before.bank_details_hash,
      'status', v_before.status,
      'checked_at_utc', v_before.checked_at_utc,
      'result_json', v_before.result_json,
      'override_reason', v_before.override_reason,
      'override_by_user_id', case when v_before.override_by_user_id is null then null else v_before.override_by_user_id::text end,
      'override_at_utc', v_before.override_at_utc,
      'override_hash', v_before.override_hash,
      'created_at_utc', v_before.created_at_utc,
      'updated_at_utc', v_before.updated_at_utc
    );
  end if;

  with upserted as (
    insert into public.bank_name_checks (
      rail_provider,
      rail_env,
      entity_kind,
      entity_id,
      bank_details_hash,
      status,
      checked_at_utc,
      result_json,
      override_reason,
      override_by_user_id,
      override_at_utc,
      override_hash,
      created_at_utc,
      updated_at_utc
    )
    values (
      v_provider,
      v_env,
      v_kind,
      p_entity_id,
      v_target_hash,
      'UNVERIFIED',
      null,
      null,
      v_reason,
      p_actor_user_id,
      v_now,
      v_target_hash,
      v_now,
      v_now
    )
    on conflict (rail_provider, rail_env, entity_kind, entity_id, bank_details_hash)
    do update set
      override_reason = excluded.override_reason,
      override_by_user_id = excluded.override_by_user_id,
      override_at_utc = excluded.override_at_utc,
      override_hash = excluded.override_hash,
      updated_at_utc = v_now
    returning public.bank_name_checks.*
  )
  select u.*
  into v_row
  from upserted u
  limit 1;

  v_inserted := (v_row.created_at_utc is not null and v_row.updated_at_utc is not null and v_row.created_at_utc = v_row.updated_at_utc);
  v_action := case when v_inserted then 'inserted' else 'updated' end;

  v_after_json := jsonb_build_object(
    'id', v_row.id::text,
    'rail_provider', v_row.rail_provider,
    'rail_env', v_row.rail_env,
    'entity_kind', v_row.entity_kind,
    'entity_id', v_row.entity_id::text,
    'bank_details_hash', v_row.bank_details_hash,
    'status', v_row.status,
    'checked_at_utc', v_row.checked_at_utc,
    'result_json', v_row.result_json,
    'override_reason', v_row.override_reason,
    'override_by_user_id', case when v_row.override_by_user_id is null then null else v_row.override_by_user_id::text end,
    'override_at_utc', v_row.override_at_utc,
    'override_hash', v_row.override_hash,
    'created_at_utc', v_row.created_at_utc,
    'updated_at_utc', v_row.updated_at_utc
  );

  perform public._audit_insert(
    'bank_name_checks',
    v_row.id::text,
    'BANK_NAME_CHECK_OVERRIDE_SET',
    v_before_json,
    v_after_json,
    v_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'row', v_after_json
  );
end;
$function$;

DROP FUNCTION IF EXISTS public.bank_name_check_clear_override(text, text, text, uuid, uuid);

CREATE OR REPLACE FUNCTION public.bank_name_check_clear_override(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_actor_user_id uuid,
  p_bank_details_hash text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_requested_hash text := nullif(btrim(coalesce(p_bank_details_hash, '')), '');

  v_now timestamptz := now();
  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_target_hash text := null;
  v_target_is_valid_oneoff boolean := false;

  v_updated integer := 0;
  v_row public.bank_name_checks%rowtype;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  if v_requested_hash is null then
    v_target_hash := v_current_hash;
  elsif v_current_hash is not null and v_current_hash = v_requested_hash then
    v_target_hash := v_current_hash;
  elsif v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_requested_hash
    )
    into v_target_is_valid_oneoff;

    if v_target_is_valid_oneoff then
      v_target_hash := v_requested_hash;
    end if;
  end if;

  if v_target_hash is null then
    if v_requested_hash is null then
      raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'INVALID_TARGET_BANK_DETAILS_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'bank_details_hash', v_requested_hash
    )::text;
  end if;

  update public.bank_name_checks bnc
  set
    override_reason = null,
    override_by_user_id = null,
    override_at_utc = null,
    override_hash = null,
    updated_at_utc = v_now
  where bnc.rail_provider = v_provider
    and bnc.rail_env = v_env
    and bnc.entity_kind = v_kind
    and bnc.entity_id = p_entity_id
    and bnc.bank_details_hash = v_target_hash;

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return jsonb_build_object(
      'ok', true,
      'did_update', false,
      'row', null
    );
  end if;

  select bnc2.*
  into v_row
  from public.bank_name_checks bnc2
  where bnc2.rail_provider = v_provider
    and bnc2.rail_env = v_env
    and bnc2.entity_kind = v_kind
    and bnc2.entity_id = p_entity_id
    and bnc2.bank_details_hash = v_target_hash
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'did_update', true,
    'row', jsonb_build_object(
      'rail_provider', v_row.rail_provider,
      'rail_env', v_row.rail_env,
      'entity_kind', v_row.entity_kind,
      'entity_id', v_row.entity_id::text,
      'bank_details_hash', v_row.bank_details_hash,
      'status', v_row.status,
