    )
    SELECT
      p_correction_request_id,
      v_request.pay_batch_id,
      untransferred_work.pay_batch_candidate_id,
      NULL::uuid,
      untransferred_work.candidate_id,
      untransferred_work.umbrella_id,
      v_work_kind,
      jsonb_build_object(
        'scope_type', 'CANDIDATES',
