      NULL::timestamptz,
      jsonb_build_object(
        'created_by', 'pay_payment_correction_expand_work',
        'work_unit', 'CANDIDATE_PAYEE_UNTRANSFERRED',
        'item_count', untransferred_work.item_count,
        'candidate_count', 1,
        'amount_inc_vat', untransferred_work.amount_inc_vat
