CREATE OR REPLACE FUNCTION public.pay_workbench_session_compact_progress_json(p_progress_json jsonb DEFAULT '{}'::jsonb, p_keep_active_jobs boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_progress_json jsonb := '{}'::jsonb;
  v_active_jobs_original_count integer := 0;
  v_active_jobs_retained_json jsonb := '[]'::jsonb;
BEGIN
  v_progress_json := CASE
    WHEN jsonb_typeof(COALESCE(p_progress_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_progress_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  -- Never persist recursively embedded live progress, stale queue snapshots, or bulky
  -- historical/debug chains inside the session's current progress blob.
  v_progress_json := v_progress_json
    - 'progress_json'
    - 'progressJson'
    - 'raw_progress_json'
    - 'stored_progress_json'
    - 'previous_progress_json'
    - 'old_progress_json'
    - 'nested_progress_json'
    - 'historical_progress_json'
    - 'progress_history'
    - 'history'
    - 'debug_history'
    - 'timing_history'
    - 'large_debug_json'
    - 'source_build_debug_json'
    - 'source_build_diagnostics_json'
    - 'candidate_source_build_diagnostics'
    - 'candidate_source_build_diagnostics_json'
    - 'candidate_source_diagnostics_json'
    - 'candidate_line_work_diagnostics_json'
    - 'legacy_compare_json'
    - 'shadow_compare_json'
    - 'old_active_jobs'
    - 'old_pending_jobs'
    - 'old_current_phase'
    - 'old_blocker_codes'
    - 'old_candidate_counts'
    - 'old_line_counts'
    - 'old_job_counts'
    - 'recent_jobs'
    - 'recent_jobs_json'
    - 'recent_job_results'
    - 'job_payloads'
    - 'job_payload_json'
    - 'last_error_stack'
    - 'error_stack'
    - 'stack_trace';

  IF COALESCE(p_keep_active_jobs, true) IS TRUE THEN
    IF jsonb_typeof(v_progress_json->'active_jobs') IS DISTINCT FROM 'array' THEN
      v_progress_json := v_progress_json - 'active_jobs';
    ELSE
      v_active_jobs_original_count := jsonb_array_length(v_progress_json->'active_jobs');
      IF v_active_jobs_original_count > 20 THEN
        SELECT COALESCE(jsonb_agg(active_job_item.value ORDER BY active_job_item.ordinality), '[]'::jsonb)
        INTO v_active_jobs_retained_json
        FROM (
          SELECT retained_jobs.value, retained_jobs.ordinality
          FROM jsonb_array_elements(v_progress_json->'active_jobs') WITH ORDINALITY AS retained_jobs(value, ordinality)
          ORDER BY retained_jobs.ordinality DESC
          LIMIT 20
        ) AS active_job_item;

        v_progress_json := jsonb_set(
            v_progress_json,
            ARRAY['active_jobs'],
            COALESCE(v_active_jobs_retained_json, '[]'::jsonb),
            true
          )
          || jsonb_build_object(
            'active_jobs_truncated', true,
            'active_jobs_original_count', v_active_jobs_original_count,
            'active_jobs_retained_count', jsonb_array_length(COALESCE(v_active_jobs_retained_json, '[]'::jsonb))
          );
      END IF;
    END IF;
  ELSE
    v_progress_json := v_progress_json
      - 'active_jobs'
      - 'pending_jobs'
      - 'pending_job_ids_json';
  END IF;

  IF jsonb_typeof(v_progress_json->'job_counts') IS DISTINCT FROM 'object' THEN
    v_progress_json := v_progress_json - 'job_counts';
  END IF;

  IF jsonb_typeof(v_progress_json->'candidate_counts') IS DISTINCT FROM 'object' THEN
    v_progress_json := v_progress_json - 'candidate_counts';
  END IF;

  IF jsonb_typeof(v_progress_json->'line_counts') IS DISTINCT FROM 'object' THEN
    v_progress_json := v_progress_json - 'line_counts';
  END IF;

  IF jsonb_typeof(v_progress_json->'section_counts_json') IS DISTINCT FROM 'object' THEN
    v_progress_json := v_progress_json - 'section_counts_json';
  END IF;

  IF jsonb_typeof(v_progress_json->'candidate_sample_rows_json') IS DISTINCT FROM 'array' THEN
    v_progress_json := v_progress_json - 'candidate_sample_rows_json';
  END IF;

  RETURN jsonb_strip_nulls(v_progress_json);
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_advance_state_refresh(p_timesheet_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canonical_timesheet_id uuid := NULL;
  v_latest_override_created_at_utc timestamptz := NULL;
  v_existing_consumed_at_utc timestamptz := NULL;
  v_authorisation_event_at_utc timestamptz := NULL;
  v_new_consumed_at_utc timestamptz := NULL;
  v_active_advance boolean := false;
  v_cache public.timesheet_summary_pay_state_cache%ROWTYPE;
  v_new_badges text[] := ARRAY[]::text[];
  v_summary_state_applies boolean := false;
  v_cache_updated boolean := false;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'INVALID_PAYLOAD',
      'message', 'p_timesheet_id is required'
    );
  END IF;

  SELECT rs.canonical_timesheet_id
    INTO v_canonical_timesheet_id
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  WHERE rs.canonical_timesheet_id IS NOT NULL
  ORDER BY COALESCE(rs.requested_is_canonical, false) DESC, rs.family_version DESC NULLS LAST, rs.canonical_timesheet_id
  LIMIT 1;

  IF v_canonical_timesheet_id IS NULL THEN
    v_canonical_timesheet_id := p_timesheet_id;
  END IF;

  SELECT payment_override.created_at_utc
    INTO v_latest_override_created_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  JOIN public.timesheet_payment_overrides AS payment_override
    ON payment_override.timesheet_id = rs.family_timesheet_id
  WHERE payment_override.cleared_at_utc IS NULL
    AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
  ORDER BY payment_override.created_at_utc DESC, payment_override.id DESC
  LIMIT 1;

  IF v_latest_override_created_at_utc IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'NO_ACTIVE_ADVANCE_THIS_PAYMENT_OVERRIDE',
      'timesheet_id', v_canonical_timesheet_id,
      'cache_updated', false
    );
  END IF;

  SELECT MAX(existing_cache.advance_authorisation_consumed_at_utc)
    INTO v_existing_consumed_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  LEFT JOIN public.timesheet_summary_pay_state_cache AS existing_cache
    ON existing_cache.timesheet_id = rs.family_timesheet_id;

  SELECT GREATEST(
           MAX(family_timesheet.authorised_at_server),
           MAX(family_timesheet.revoked_at),
           MAX(family_financial.authorised_at_utc)
         )
    INTO v_authorisation_event_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  LEFT JOIN public.timesheets AS family_timesheet
    ON family_timesheet.timesheet_id = rs.family_timesheet_id
  LEFT JOIN public.timesheets_financials AS family_financial
    ON family_financial.timesheet_id = rs.family_timesheet_id;

  IF v_existing_consumed_at_utc IS NOT NULL
     AND v_existing_consumed_at_utc >= v_latest_override_created_at_utc THEN
    v_new_consumed_at_utc := v_existing_consumed_at_utc;
  ELSIF v_authorisation_event_at_utc IS NOT NULL
        AND v_authorisation_event_at_utc >= v_latest_override_created_at_utc THEN
    v_new_consumed_at_utc := v_authorisation_event_at_utc;
  ELSE
    v_new_consumed_at_utc := NULL::timestamptz;
  END IF;

  v_active_advance := (
    v_latest_override_created_at_utc IS NOT NULL
    AND (
      v_new_consumed_at_utc IS NULL
      OR v_new_consumed_at_utc < v_latest_override_created_at_utc
    )
  );

  SELECT c.*
    INTO v_cache
  FROM public.timesheet_summary_pay_state_cache AS c
  WHERE c.timesheet_id = v_canonical_timesheet_id
  LIMIT 1
  FOR UPDATE;

  IF v_cache.timesheet_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SUMMARY_PAY_STATE_CACHE_ROW_NOT_FOUND',
      'timesheet_id', v_canonical_timesheet_id,
      'active_advance', v_active_advance,
      'advance_override_created_at_utc', v_latest_override_created_at_utc,
      'advance_authorisation_consumed_at_utc', v_new_consumed_at_utc,
      'cache_updated', false
    );
  END IF;

  v_new_badges := COALESCE(v_cache.summary_badge_codes, ARRAY[]::text[]);
  v_new_badges := ARRAY_REMOVE(v_new_badges, NULL);
  v_new_badges := ARRAY_REMOVE(v_new_badges, '__PAY_BADGE_ADV__');
  IF COALESCE(v_active_advance, false) THEN
    v_new_badges := ARRAY_PREPEND('__PAY_BADGE_ADV__', v_new_badges);
  END IF;

  v_summary_state_applies := (
    COALESCE(v_active_advance, false)
    OR COALESCE(v_cache.active_processing, false)
    OR ABS(COALESCE(v_cache.paid_to_date_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.reserved_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.outstanding_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.net_delta_ex_vat, 0)) > 0.005
    OR v_cache.last_paid_at_utc IS NOT NULL
    OR UPPER(COALESCE(v_cache.summary_pay_status_code, '')) IN ('PAID', 'PARTIALLY_PAID', 'PROCESSING', 'OVERPAID')
    OR COALESCE(ARRAY_LENGTH(v_new_badges, 1), 0) > 0
  );

  UPDATE public.timesheet_summary_pay_state_cache AS c
     SET active_advance = COALESCE(v_active_advance, false),
         advance_override_created_at_utc = v_latest_override_created_at_utc,
         advance_authorisation_consumed_at_utc = v_new_consumed_at_utc,
         summary_state_applies = COALESCE(v_summary_state_applies, false),
         summary_badge_codes = COALESCE(v_new_badges, ARRAY[]::text[]),
         refreshed_at_utc = now(),
         refreshed_by_user_id = COALESCE(p_actor_user_id, c.refreshed_by_user_id)
   WHERE c.timesheet_id = v_canonical_timesheet_id
   RETURNING c.* INTO v_cache;

  v_cache_updated := FOUND;

  RETURN jsonb_build_object(
    'ok', true,
    'timesheet_id', v_canonical_timesheet_id,
    'requested_timesheet_id', p_timesheet_id,
    'active_advance', COALESCE(v_active_advance, false),
    'advance_override_created_at_utc', v_latest_override_created_at_utc,
    'advance_authorisation_consumed_at_utc', v_new_consumed_at_utc,
    'summary_badge_codes', TO_JSONB(COALESCE(v_new_badges, ARRAY[]::text[])),
    'summary_state_applies', COALESCE(v_summary_state_applies, false),
    'cache_updated', COALESCE(v_cache_updated, false)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_pay_state_patch_lightweight(p_timesheet_ids uuid[], p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested_ids uuid[] := ARRAY[]::uuid[];
  v_target_ids uuid[] := ARRAY[]::uuid[];
  v_patched_count integer := 0;
  v_legacy_state_rows_updated integer := 0;
  v_fallback_reason_codes text[] := ARRAY[]::text[];
  v_fallback_required boolean := false;
  v_diag_started_at timestamptz := clock_timestamp();
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(p_timesheet_ids), 0) > 0 THEN p_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'entry',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count_raw', COALESCE(CARDINALITY(p_timesheet_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT input_rows.timesheet_id ORDER BY input_rows.timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_requested_ids
  FROM UNNEST(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_rows(timesheet_id)
  WHERE input_rows.timesheet_id IS NOT NULL;

  IF COALESCE(CARDINALITY(v_requested_ids), 0) = 0 THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      NULL::text,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
        'stage', 'return_zero_requested',
        'requested_count', 0,
        'target_count', 0,
        'patched_count', 0,
        'legacy_state_rows_updated', 0,
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'requested_count', 0,
      'target_count', 0,
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  IF CARDINALITY(v_requested_ids) > 100 THEN
    RAISE EXCEPTION 'pay_timesheet_summary_pay_state_patch_lightweight accepts at most 100 distinct timesheet ids per call';
  END IF;

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT resolved_rows.target_timesheet_id ORDER BY resolved_rows.target_timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_target_ids
  FROM (
    SELECT
      COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) AS target_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_requested_ids) AS rotation_rows
  ) AS resolved_rows
  JOIN public.timesheets AS target_timesheet
    ON target_timesheet.timesheet_id = resolved_rows.target_timesheet_id
  WHERE resolved_rows.target_timesheet_id IS NOT NULL;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_requested_ids), 0) > 0 THEN v_requested_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'rotation_scope_done',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(CARDINALITY(v_target_ids), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', 0,
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  WITH
  target_ids AS MATERIALIZED (
    SELECT target_values.timesheet_id
    FROM UNNEST(v_target_ids) AS target_values(timesheet_id)
  ),
  target_id_array AS MATERIALIZED (
    SELECT ARRAY_AGG(target_ids.timesheet_id ORDER BY target_ids.timesheet_id) AS timesheet_ids
    FROM target_ids
  ),
  family_scope AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(target_id_array.timesheet_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  ),
  fallback_reasons AS MATERIALIZED (
    SELECT 'PAY_BATCH_ITEM_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.timesheet_id = family_scope.family_timesheet_id
      WHERE COALESCE(batch_item.is_voided, false) = false
    )

    UNION ALL

    SELECT 'MATERIAL_LEGACY_PAY_STATE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheet_pay_state AS legacy_state
        ON legacy_state.timesheet_id = family_scope.family_timesheet_id
      WHERE legacy_state.last_settled_snapshot_json IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(legacy_state.last_settled_signature, '')), '') IS NOT NULL
         OR legacy_state.last_settled_pay_batch_id IS NOT NULL
         OR legacy_state.last_settled_at_utc IS NOT NULL
         OR legacy_state.summary_pay_paid_at_utc IS NOT NULL
         OR ABS(COALESCE(legacy_state.summary_net_delta_ex_vat, 0)) > 0.01
         OR UPPER(BTRIM(COALESCE(legacy_state.summary_pay_status_code, ''))) NOT IN ('', 'UNPAID')
         OR UPPER(BTRIM(COALESCE(legacy_state.summary_pay_icon_code, ''))) NOT IN ('', 'NONE')
    )

    UNION ALL

    SELECT 'MATERIAL_SUMMARY_CACHE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheet_summary_pay_state_cache AS summary_cache
        ON summary_cache.timesheet_id = family_scope.family_timesheet_id
      WHERE COALESCE(summary_cache.summary_state_applies, false) = true
         OR summary_cache.last_paid_at_utc IS NOT NULL
         OR ABS(COALESCE(summary_cache.paid_to_date_ex_vat, 0)) > 0.01
         OR ABS(COALESCE(summary_cache.reserved_ex_vat, 0)) > 0.01
         OR COALESCE(summary_cache.active_advance, false) = true
         OR summary_cache.advance_override_created_at_utc IS NOT NULL
         OR summary_cache.advance_authorisation_consumed_at_utc IS NOT NULL
         OR COALESCE(summary_cache.active_processing, false) = true
         OR UPPER(BTRIM(COALESCE(summary_cache.summary_pay_status_code, ''))) NOT IN ('', 'UNPAID')
         OR UPPER(BTRIM(COALESCE(summary_cache.summary_pay_icon_code, ''))) NOT IN ('', 'NONE')
         OR CARDINALITY(COALESCE(summary_cache.summary_badge_codes, ARRAY[]::text[])) > 0
    )

    UNION ALL

    SELECT 'ACTIVE_PAYMENT_CORRECTION_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS correction_item
      LEFT JOIN public.pay_batch_items AS correction_batch_item
        ON correction_batch_item.id = correction_item.pay_batch_item_id
      JOIN family_scope
        ON family_scope.family_timesheet_id = COALESCE(
          correction_item.timesheet_id,
          correction_batch_item.timesheet_id
        )
      JOIN public.pay_payment_correction_requests AS correction_request
        ON correction_request.id = correction_item.correction_request_id
      WHERE correction_request.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
        AND correction_item.status NOT IN ('APPLIED', 'SKIPPED')
    )

    UNION ALL

    SELECT 'OPEN_FINANCE_COMPONENT_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_finance_case_components AS finance_component
        ON finance_component.linked_timesheet_id = family_scope.family_timesheet_id
      WHERE finance_component.closed_at_utc IS NULL
         OR ABS(COALESCE(finance_component.remaining_source_amount, 0)) > 0.01
    )

    UNION ALL

    SELECT 'ACTIVE_ADVANCE_CASE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_advances AS pay_advance
        ON pay_advance.linked_timesheet_id = family_scope.family_timesheet_id
      WHERE UPPER(BTRIM(COALESCE(pay_advance.status::text, ''))) NOT IN ('', 'PAID_OFF')
         OR ABS(COALESCE(pay_advance.outstanding_amount, 0)) > 0.01
    )

    UNION ALL

    SELECT 'PAID_LOCKED_OR_PAY_ON_HOLD_TSFIN_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheets_financials AS family_financial
        ON family_financial.timesheet_id = family_scope.family_timesheet_id
      WHERE family_financial.paid_at_utc IS NOT NULL
         OR family_financial.locked_by_invoice_id IS NOT NULL
         OR family_financial.locked_at_utc IS NOT NULL
         OR family_financial.unlocked_by_credit_note_id IS NOT NULL
         OR COALESCE(family_financial.pay_on_hold, false) = true
         OR family_financial.pay_on_hold_since_utc IS NOT NULL
         OR family_financial.remittance_last_sent_at_utc IS NOT NULL
         OR COALESCE(family_financial.remittance_send_count, 0) > 0
    )
  )
  SELECT COALESCE(
    ARRAY_AGG(fallback_reasons.reason_code ORDER BY fallback_reasons.reason_code),
    ARRAY[]::text[]
  )
  INTO v_fallback_reason_codes
  FROM fallback_reasons;

  v_fallback_required := COALESCE(CARDINALITY(v_fallback_reason_codes), 0) > 0;

  IF v_fallback_required IS TRUE THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
        'stage', 'fallback_required_deferred_full_summary_refresh',
        'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
        'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
        'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
        'fallback_required', true,
        'fallback_reason_codes', to_jsonb(v_fallback_reason_codes),
        'patched_count', 0,
        'legacy_state_rows_updated', 0,
        'policy_x_authority_scope', 'MATERIAL_PAY_STATE_REQUIRES_NON_MODAL_FULL_REFRESH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'fallback_required', true,
      'fallback_deferred', true,
      'deferred_full_refresh_required', true,
      'fallback_reason_codes', to_jsonb(v_fallback_reason_codes),
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', CARDINALITY(v_target_ids),
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  WITH
  target_ids AS MATERIALIZED (
    SELECT target_values.timesheet_id
    FROM UNNEST(v_target_ids) AS target_values(timesheet_id)
  ),
  target_id_array AS MATERIALIZED (
    SELECT ARRAY_AGG(target_ids.timesheet_id ORDER BY target_ids.timesheet_id) AS timesheet_ids
    FROM target_ids
  ),
  family_scope AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(target_id_array.timesheet_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  ),
  existing_cache AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      summary_cache.paid_to_date_ex_vat,
      summary_cache.last_paid_at_utc,
      summary_cache.reserved_ex_vat,
      summary_cache.outstanding_ex_vat,
      summary_cache.net_delta_ex_vat,
      summary_cache.active_advance,
      summary_cache.active_processing,
      summary_cache.summary_state_applies,
      summary_cache.advance_override_created_at_utc,
      summary_cache.advance_authorisation_consumed_at_utc,
      summary_cache.summary_pay_status_code,
      summary_cache.summary_pay_icon_code,
      summary_cache.summary_badge_codes
    FROM target_ids
    LEFT JOIN public.timesheet_summary_pay_state_cache AS summary_cache
      ON summary_cache.timesheet_id = target_ids.timesheet_id
  ),
  current_tsfin_totals AS MATERIALIZED (
    SELECT DISTINCT ON (target_ids.timesheet_id)
      target_ids.timesheet_id,
      ROUND(COALESCE(current_financial.total_pay_ex_vat, 0), 2)::numeric AS current_total_pay_ex_vat
    FROM target_ids
    LEFT JOIN public.timesheets_financials AS current_financial
      ON current_financial.timesheet_id = target_ids.timesheet_id
     AND COALESCE(current_financial.is_current, false) = true
    ORDER BY
      target_ids.timesheet_id,
      current_financial.computed_at_utc DESC NULLS LAST,
      current_financial.updated_at DESC NULLS LAST,
      current_financial.created_at DESC NULLS LAST,
      current_financial.id DESC
  ),
  legacy_ranked AS MATERIALIZED (
    SELECT
      family_scope.projected_timesheet_id AS timesheet_id,
      legacy_state.summary_pay_status_code,
      legacy_state.summary_pay_icon_code,
      legacy_state.summary_pay_paid_at_utc,
      legacy_state.summary_net_delta_ex_vat,
      COALESCE(legacy_state.last_settled_at_utc, legacy_state.summary_pay_paid_at_utc) AS last_paid_at_utc,
      ROW_NUMBER() OVER (
        PARTITION BY family_scope.projected_timesheet_id
        ORDER BY
          CASE WHEN NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_status_code, '')), '') IS NOT NULL THEN 0 ELSE 1 END,
          COALESCE(legacy_state.last_settled_at_utc, legacy_state.summary_pay_paid_at_utc) DESC NULLS LAST,
          family_scope.family_timesheet_id
      ) AS row_rank
    FROM family_scope
    JOIN public.timesheet_pay_state AS legacy_state
      ON legacy_state.timesheet_id = family_scope.family_timesheet_id
  ),
  legacy_state AS MATERIALIZED (
    SELECT
      legacy_ranked.timesheet_id,
      legacy_ranked.summary_pay_status_code,
      legacy_ranked.summary_pay_icon_code,
      legacy_ranked.summary_pay_paid_at_utc,
      legacy_ranked.summary_net_delta_ex_vat,
      legacy_ranked.last_paid_at_utc
    FROM legacy_ranked
    WHERE legacy_ranked.row_rank = 1
  ),
  latest_advance_override AS MATERIALIZED (
    SELECT DISTINCT ON (family_scope.projected_timesheet_id)
      family_scope.projected_timesheet_id AS timesheet_id,
      payment_override.id AS override_id,
      payment_override.created_at_utc AS override_created_at_utc
    FROM family_scope
    JOIN public.timesheet_payment_overrides AS payment_override
      ON payment_override.timesheet_id = family_scope.family_timesheet_id
    WHERE payment_override.cleared_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
    ORDER BY
      family_scope.projected_timesheet_id,
      payment_override.created_at_utc DESC,
      payment_override.id DESC
  ),
  current_authorisation_state AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      GREATEST(
        MAX(family_timesheet.authorised_at_server),
        MAX(family_timesheet.revoked_at),
        MAX(family_financial.authorised_at_utc)
      ) AS authorised_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheets AS family_timesheet
      ON family_timesheet.timesheet_id = family_scope.family_timesheet_id
    LEFT JOIN public.timesheets_financials AS family_financial
      ON family_financial.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  existing_display_cache AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      MAX(existing_family_cache.advance_authorisation_consumed_at_utc) AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheet_summary_pay_state_cache AS existing_family_cache
      ON existing_family_cache.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  advance_state_prepared AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      latest_advance_override.override_created_at_utc,
      current_authorisation_state.authorised_at_utc,
      CASE
        WHEN latest_advance_override.override_created_at_utc IS NULL
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN existing_display_cache.advance_authorisation_consumed_at_utc
             >= latest_advance_override.override_created_at_utc
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN current_authorisation_state.authorised_at_utc
             >= latest_advance_override.override_created_at_utc
          THEN current_authorisation_state.authorised_at_utc
        ELSE NULL::timestamptz
      END AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN latest_advance_override
      ON latest_advance_override.timesheet_id = target_ids.timesheet_id
    LEFT JOIN current_authorisation_state
      ON current_authorisation_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN existing_display_cache
      ON existing_display_cache.timesheet_id = target_ids.timesheet_id
  ),
  advance_state AS MATERIALIZED (
    SELECT
      advance_state_prepared.timesheet_id,
      advance_state_prepared.override_created_at_utc,
      advance_state_prepared.advance_authorisation_consumed_at_utc,
      (
        advance_state_prepared.override_created_at_utc IS NOT NULL
        AND (
          advance_state_prepared.advance_authorisation_consumed_at_utc IS NULL
          OR advance_state_prepared.advance_authorisation_consumed_at_utc
               < advance_state_prepared.override_created_at_utc
        )
      ) AS active_advance
    FROM advance_state_prepared
  ),
  active_batch_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM family_scope
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.timesheet_id = family_scope.family_timesheet_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    JOIN public.pay_batches AS pay_batch
      ON pay_batch.id = batch_candidate.pay_batch_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
     AND bank_transfer.pay_batch_id = pay_batch.id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      bank_transfer.status,
      bank_transfer.rail_state,
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb),
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier
      ON bank_transfer.id IS NOT NULL
    WHERE COALESCE(batch_item.is_voided, false) = false
      AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'EXPENSE_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND public._pay_batch_status_is_active_reservation(pay_batch.status)
      AND UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) NOT IN (
        'SETTLED',
        'PAID',
        'CONFIRMED'
      )
      AND batch_candidate.settled_at_utc IS NULL
      AND COALESCE(transfer_classifier.is_final_money_moved, false) = false
      AND COALESCE(transfer_classifier.is_terminal_no_money, false) = false
      AND bank_transfer.completed_at_utc IS NULL
  ),
  active_correction_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM public.pay_payment_correction_items AS correction_item
    LEFT JOIN public.pay_batch_items AS correction_batch_item
      ON correction_batch_item.id = correction_item.pay_batch_item_id
    JOIN family_scope
      ON family_scope.family_timesheet_id = COALESCE(
        correction_item.timesheet_id,
        correction_batch_item.timesheet_id
      )
    JOIN public.pay_payment_correction_requests AS correction_request
      ON correction_request.id = correction_item.correction_request_id
    WHERE correction_request.status IN (
      'REQUESTED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED',
      'EXPANDED',
      'PROCESSING',
      'BLOCKED'
    )
      AND correction_item.status NOT IN ('APPLIED', 'SKIPPED')
  ),
  prepared AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      ROUND(COALESCE(existing_cache.paid_to_date_ex_vat, 0), 2)::numeric AS paid_to_date_ex_vat,
      COALESCE(existing_cache.last_paid_at_utc, legacy_state.last_paid_at_utc) AS last_paid_at_utc,
      ROUND(COALESCE(existing_cache.reserved_ex_vat, 0), 2)::numeric AS reserved_ex_vat,
      ROUND(
        COALESCE(current_tsfin_totals.current_total_pay_ex_vat, 0)
        - COALESCE(existing_cache.paid_to_date_ex_vat, 0)
        - COALESCE(existing_cache.reserved_ex_vat, 0),
        2
      )::numeric AS outstanding_ex_vat,
      ROUND(
        COALESCE(current_tsfin_totals.current_total_pay_ex_vat, 0)
        - COALESCE(existing_cache.paid_to_date_ex_vat, 0),
        2
      )::numeric AS net_delta_ex_vat,
      COALESCE(advance_state.active_advance, false) AS active_advance,
      (
        COALESCE(existing_cache.active_processing, false)
        OR active_batch_processing.timesheet_id IS NOT NULL
        OR active_correction_processing.timesheet_id IS NOT NULL
      ) AS active_processing,
      advance_state.override_created_at_utc AS advance_override_created_at_utc,
      advance_state.advance_authorisation_consumed_at_utc,
      COALESCE(
        NULLIF(BTRIM(COALESCE(existing_cache.summary_pay_status_code, '')), ''),
        NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_status_code, '')), ''),
        CASE
          WHEN (
            COALESCE(existing_cache.active_processing, false)
            OR active_batch_processing.timesheet_id IS NOT NULL
            OR active_correction_processing.timesheet_id IS NOT NULL
          ) THEN 'PROCESSING'
          ELSE 'UNPAID'
        END
      ) AS summary_pay_status_code,
      COALESCE(
        NULLIF(BTRIM(COALESCE(existing_cache.summary_pay_icon_code, '')), ''),
        NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_icon_code, '')), ''),
        CASE
          WHEN (
            COALESCE(existing_cache.active_processing, false)
            OR active_batch_processing.timesheet_id IS NOT NULL
            OR active_correction_processing.timesheet_id IS NOT NULL
          ) THEN 'CLOCK'
          ELSE 'NONE'
        END
      ) AS summary_pay_icon_code,
      ARRAY_REMOVE(
        ARRAY_REMOVE(
          ARRAY_REMOVE(COALESCE(existing_cache.summary_badge_codes, ARRAY[]::text[]), NULL::text),
          '__PAY_BADGE_ADV__'
        ),
        '__PAY_BADGE_PROCESSING__'
      ) AS badge_codes_without_dynamic_state,
      COALESCE(existing_cache.summary_state_applies, false) AS existing_summary_state_applies
    FROM target_ids
    LEFT JOIN existing_cache
      ON existing_cache.timesheet_id = target_ids.timesheet_id
    LEFT JOIN legacy_state
      ON legacy_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN current_tsfin_totals
      ON current_tsfin_totals.timesheet_id = target_ids.timesheet_id
    LEFT JOIN advance_state
      ON advance_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_batch_processing
      ON active_batch_processing.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_correction_processing
      ON active_correction_processing.timesheet_id = target_ids.timesheet_id
  ),
  final_values AS MATERIALIZED (
    SELECT
      prepared.timesheet_id,
      prepared.paid_to_date_ex_vat,
      prepared.last_paid_at_utc,
      prepared.reserved_ex_vat,
      prepared.outstanding_ex_vat,
      prepared.net_delta_ex_vat,
      prepared.active_advance,
      prepared.active_processing,
      prepared.advance_override_created_at_utc,
      prepared.advance_authorisation_consumed_at_utc,
      prepared.summary_pay_status_code,
      prepared.summary_pay_icon_code,
      ARRAY_REMOVE(
        ARRAY[
          CASE WHEN prepared.active_advance THEN '__PAY_BADGE_ADV__' ELSE NULL::text END,
          CASE WHEN prepared.active_processing AND prepared.summary_pay_status_code <> 'PROCESSING' THEN '__PAY_BADGE_PROCESSING__' ELSE NULL::text END
        ]::text[] || prepared.badge_codes_without_dynamic_state,
        NULL::text
      ) AS summary_badge_codes,
      (
        prepared.existing_summary_state_applies
        OR prepared.active_advance
        OR prepared.active_processing
        OR prepared.last_paid_at_utc IS NOT NULL
        OR ABS(COALESCE(prepared.paid_to_date_ex_vat, 0)) > 0.01
        OR ABS(COALESCE(prepared.reserved_ex_vat, 0)) > 0.01
      ) AS summary_state_applies
    FROM prepared
  )
  INSERT INTO public.timesheet_summary_pay_state_cache AS summary_cache (
    timesheet_id,
    paid_to_date_ex_vat,
    last_paid_at_utc,
    reserved_ex_vat,
    outstanding_ex_vat,
    net_delta_ex_vat,
    active_advance,
    active_processing,
    summary_state_applies,
    advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_badge_codes,
    refreshed_at_utc,
    refreshed_by_user_id
  )
  SELECT
    final_values.timesheet_id,
    final_values.paid_to_date_ex_vat,
    final_values.last_paid_at_utc,
    final_values.reserved_ex_vat,
    final_values.outstanding_ex_vat,
    final_values.net_delta_ex_vat,
    final_values.active_advance,
    final_values.active_processing,
    final_values.summary_state_applies,
    final_values.advance_override_created_at_utc,
    final_values.advance_authorisation_consumed_at_utc,
    final_values.summary_pay_status_code,
    final_values.summary_pay_icon_code,
    final_values.summary_badge_codes,
    clock_timestamp(),
    p_actor_user_id
  FROM final_values
  ON CONFLICT (timesheet_id) DO UPDATE
  SET
    paid_to_date_ex_vat = EXCLUDED.paid_to_date_ex_vat,
    last_paid_at_utc = EXCLUDED.last_paid_at_utc,
    reserved_ex_vat = EXCLUDED.reserved_ex_vat,
    outstanding_ex_vat = EXCLUDED.outstanding_ex_vat,
    net_delta_ex_vat = EXCLUDED.net_delta_ex_vat,
    active_advance = EXCLUDED.active_advance,
    active_processing = EXCLUDED.active_processing,
    summary_state_applies = EXCLUDED.summary_state_applies,
    advance_override_created_at_utc = EXCLUDED.advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc = EXCLUDED.advance_authorisation_consumed_at_utc,
    summary_pay_status_code = EXCLUDED.summary_pay_status_code,
    summary_pay_icon_code = EXCLUDED.summary_pay_icon_code,
    summary_badge_codes = EXCLUDED.summary_badge_codes,
    refreshed_at_utc = EXCLUDED.refreshed_at_utc,
    refreshed_by_user_id = EXCLUDED.refreshed_by_user_id
  WHERE summary_cache.paid_to_date_ex_vat IS DISTINCT FROM EXCLUDED.paid_to_date_ex_vat
     OR summary_cache.last_paid_at_utc IS DISTINCT FROM EXCLUDED.last_paid_at_utc
     OR summary_cache.reserved_ex_vat IS DISTINCT FROM EXCLUDED.reserved_ex_vat
     OR summary_cache.outstanding_ex_vat IS DISTINCT FROM EXCLUDED.outstanding_ex_vat
     OR summary_cache.net_delta_ex_vat IS DISTINCT FROM EXCLUDED.net_delta_ex_vat
     OR summary_cache.active_advance IS DISTINCT FROM EXCLUDED.active_advance
     OR summary_cache.active_processing IS DISTINCT FROM EXCLUDED.active_processing
     OR summary_cache.summary_state_applies IS DISTINCT FROM EXCLUDED.summary_state_applies
     OR summary_cache.advance_override_created_at_utc IS DISTINCT FROM EXCLUDED.advance_override_created_at_utc
     OR summary_cache.advance_authorisation_consumed_at_utc IS DISTINCT FROM EXCLUDED.advance_authorisation_consumed_at_utc
     OR summary_cache.summary_pay_status_code IS DISTINCT FROM EXCLUDED.summary_pay_status_code
     OR summary_cache.summary_pay_icon_code IS DISTINCT FROM EXCLUDED.summary_pay_icon_code
     OR summary_cache.summary_badge_codes IS DISTINCT FROM EXCLUDED.summary_badge_codes
     OR summary_cache.refreshed_by_user_id IS DISTINCT FROM EXCLUDED.refreshed_by_user_id;

  GET DIAGNOSTICS v_patched_count = ROW_COUNT;

  WITH legacy_projection AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_target_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  )
  UPDATE public.timesheet_pay_state AS legacy_state
  SET
    summary_pay_status_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
      ELSE summary_cache.summary_pay_status_code
    END,
    summary_pay_icon_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
      ELSE summary_cache.summary_pay_icon_code
    END,
    summary_pay_paid_at_utc = summary_cache.last_paid_at_utc,
    summary_net_delta_ex_vat = summary_cache.net_delta_ex_vat
  FROM legacy_projection
  JOIN public.timesheet_summary_pay_state_cache AS summary_cache
    ON summary_cache.timesheet_id = legacy_projection.projected_timesheet_id
  WHERE legacy_state.timesheet_id = legacy_projection.family_timesheet_id
    AND summary_cache.timesheet_id = ANY (v_target_ids)
    AND COALESCE(summary_cache.summary_state_applies, false) = true
    AND (
      legacy_state.summary_pay_status_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
        ELSE summary_cache.summary_pay_status_code
      END
      OR legacy_state.summary_pay_icon_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
        ELSE summary_cache.summary_pay_icon_code
      END
      OR legacy_state.summary_pay_paid_at_utc IS DISTINCT FROM summary_cache.last_paid_at_utc
      OR legacy_state.summary_net_delta_ex_vat IS DISTINCT FROM summary_cache.net_delta_ex_vat
    );

  GET DIAGNOSTICS v_legacy_state_rows_updated = ROW_COUNT;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'return',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'patched_count', v_patched_count,
      'legacy_state_rows_updated', v_legacy_state_rows_updated,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH_DISPLAY_PATCH_NO_BANKING_PAY_RECALC',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'ordinary_manual_save_lightweight',
    'fallback_required', false,
    'requested_count', CARDINALITY(v_requested_ids),
    'target_count', CARDINALITY(v_target_ids),
    'patched_count', v_patched_count,
    'legacy_state_rows_updated', v_legacy_state_rows_updated
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_delta_refresh_family_key(
  p_session_id uuid,
  p_candidate_id uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb,
  p_fallback_session_version bigint DEFAULT NULL::bigint,
  p_fallback_projection_mode text DEFAULT NULL::text,
  p_fallback_projection_class text DEFAULT NULL::text,
  p_fallback_refresh_scope_kind text DEFAULT NULL::text
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_session_id_text text := NULLIF(BTRIM(COALESCE(
    CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    v_payload_json->>'session_id',
    v_payload_json->>'workbench_session_id',
    v_payload_json->>'source_session_id',
    v_payload_json->>'target_session_id',
    ''
  )), '');
  v_candidate_id_text text := NULLIF(BTRIM(COALESCE(
    CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    v_payload_json->>'candidate_id',
    v_payload_json#>>'{candidate,id}',
    ''
  )), '');
  v_session_version_text text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_version',
    v_payload_json->>'workbench_session_version',
    v_payload_json->>'version',
    CASE WHEN p_fallback_session_version IS NULL THEN NULL ELSE p_fallback_session_version::text END,
    '0'
  )), '');
  v_session_version bigint := 0;
  v_projection_mode text := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'projection_mode', ''),
    NULLIF(v_payload_json->>'resolved_mode', ''),
    NULLIF(v_payload_json->>'mode', ''),
    NULLIF(p_fallback_projection_mode, ''),
    'DELTA'
  )));
  v_projection_class text := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'projection_class', ''),
    NULLIF(v_payload_json->>'classifier_projection_class', ''),
    NULLIF(v_payload_json#>>'{classifier_result,projection_class}', ''),
    NULLIF(p_fallback_projection_class, ''),
    'UNKNOWN'
  )));
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_timesheet_family_hash text := NULL::text;
  v_refresh_scope_kind text := NULL::text;
BEGIN
  IF v_session_version_text ~ '^-?[0-9]{1,18}$' THEN
    v_session_version := v_session_version_text::bigint;
  ELSE
    v_session_version := COALESCE(p_fallback_session_version, 0);
  END IF;

  SELECT COALESCE(jsonb_agg(sorted_ids.timesheet_id_text ORDER BY sorted_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(raw_ids.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN NULLIF(BTRIM(COALESCE(v_payload_json->>'targeted_timesheet_id', v_payload_json->>'timesheet_id', '')), '') IS NOT NULL THEN jsonb_build_array(COALESCE(v_payload_json->>'targeted_timesheet_id', v_payload_json->>'timesheet_id'))
        ELSE '[]'::jsonb
      END
    ) AS raw_ids(value)
    WHERE NULLIF(BTRIM(raw_ids.value), '') ~* v_uuid_re
  ) AS sorted_ids;

  SELECT COALESCE(jsonb_agg(sorted_ids.timesheet_id_text ORDER BY sorted_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(raw_ids.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        ELSE '[]'::jsonb
      END
    ) AS raw_ids(value)
    WHERE NULLIF(BTRIM(raw_ids.value), '') ~* v_uuid_re
  ) AS sorted_ids;

  v_refresh_scope_kind := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'refresh_scope_kind', ''),
    NULLIF(v_payload_json->>'scope_kind', ''),
    NULLIF(v_payload_json#>>'{source_build,refresh_scope_kind}', ''),
    NULLIF(v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}', ''),
    NULLIF(p_fallback_refresh_scope_kind, ''),
    CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END
  )));

  v_timesheet_family_hash := md5(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)::text || ':' || COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)::text);

  RETURN 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id_text, 'none')
    || ':version:' || COALESCE(v_session_version, 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(v_projection_mode, ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(v_refresh_scope_kind, ''), 'CANDIDATE_FULL_LIVE')
    || ':candidate:' || COALESCE(v_candidate_id_text, 'none')
    || ':timesheets:' || v_timesheet_family_hash;
END;
$function$;
CREATE OR REPLACE FUNCTION public.pay_workbench_compact_job_result_json(p_result_json jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_result_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_next_cursor_json jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
    WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
    WHEN jsonb_typeof(v_result_json->'nextCursorJson') = 'object' THEN v_result_json->'nextCursorJson'
    WHEN jsonb_typeof(v_result_json->'nextCursor') = 'object' THEN v_result_json->'nextCursor'
    ELSE NULL::jsonb
  END;
  v_targeted_timesheet_ids jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
    ELSE NULL::jsonb
  END;
  v_linked_timesheet_ids jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
    ELSE NULL::jsonb
  END;
BEGIN
  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', CASE WHEN v_result_json ? 'ok' THEN v_result_json->'ok' ELSE NULL END,
    'has_more', CASE WHEN v_result_json ? 'has_more' THEN v_result_json->'has_more' WHEN v_result_json ? 'more_due' THEN v_result_json->'more_due' ELSE NULL END,
    'more_due', CASE WHEN v_result_json ? 'more_due' THEN v_result_json->'more_due' WHEN v_result_json ? 'has_more' THEN v_result_json->'has_more' ELSE NULL END,
    'next_cursor_json', v_next_cursor_json,
    'next_cursor', v_next_cursor_json,
    'processed_count', CASE WHEN v_result_json ? 'processed_count' THEN v_result_json->'processed_count' ELSE NULL END,
    'seeded_count', CASE WHEN v_result_json ? 'seeded_count' THEN v_result_json->'seeded_count' ELSE NULL END,
    'new_scope_count', CASE WHEN v_result_json ? 'new_scope_count' THEN v_result_json->'new_scope_count' ELSE NULL END,
    'ready_count_delta', CASE WHEN v_result_json ? 'ready_count_delta' THEN v_result_json->'ready_count_delta' ELSE NULL END,
    'materialised_count', CASE WHEN v_result_json ? 'materialised_count' THEN v_result_json->'materialised_count' WHEN v_result_json ? 'materialized_count' THEN v_result_json->'materialized_count' ELSE NULL END,
    'error_count', CASE WHEN v_result_json ? 'error_count' THEN v_result_json->'error_count' WHEN v_result_json ? 'materialisation_error_count' THEN v_result_json->'materialisation_error_count' ELSE NULL END,
    'source_rows_written', CASE WHEN v_result_json ? 'source_rows_written' THEN v_result_json->'source_rows_written' ELSE NULL END,
    'current_source_row_count', CASE WHEN v_result_json ? 'current_source_row_count' THEN v_result_json->'current_source_row_count' ELSE NULL END,
    'line_rows_written', CASE WHEN v_result_json ? 'line_rows_written' THEN v_result_json->'line_rows_written' ELSE NULL END,
    'preview_rows_written', CASE WHEN v_result_json ? 'preview_rows_written' THEN v_result_json->'preview_rows_written' ELSE NULL END,
    'source_build_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    'session_id', NULLIF(BTRIM(COALESCE(v_result_json->>'session_id', v_result_json->>'workbench_session_id', '')), ''),
    'candidate_id', NULLIF(BTRIM(COALESCE(v_result_json->>'candidate_id', '')), ''),
    'snapshot_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'snapshot_run_id', v_result_json->>'source_snapshot_run_id', '')), ''),
    'projection_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', v_result_json->>'delta_projection_run_id', '')), ''),
    'timesheet_id', NULLIF(BTRIM(COALESCE(v_result_json->>'timesheet_id', v_result_json->>'targeted_timesheet_id', v_result_json->>'real_business_timesheet_id', '')), ''),
    'real_business_timesheet_id', NULLIF(BTRIM(COALESCE(v_result_json->>'real_business_timesheet_id', v_result_json->>'timesheet_id', '')), ''),
    'source_change_seq', CASE WHEN v_result_json ? 'source_change_seq' THEN v_result_json->'source_change_seq' ELSE NULL END,
    'source_change_sequence', CASE WHEN v_result_json ? 'source_change_sequence' THEN v_result_json->'source_change_sequence' WHEN v_result_json ? 'source_change_seq' THEN v_result_json->'source_change_seq' ELSE NULL END,
    'session_version', CASE WHEN v_result_json ? 'session_version' THEN v_result_json->'session_version' ELSE NULL END,
    'projection_mode', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_mode', '')), ''),
    'projection_class', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''),
    'refresh_scope_kind', NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
    'targeted_timesheet_ids', v_targeted_timesheet_ids,
    'linked_timesheet_ids', v_linked_timesheet_ids,
    'fallback_required', CASE WHEN v_result_json ? 'fallback_required' THEN v_result_json->'fallback_required' ELSE NULL END,
    'fallback_reason', NULLIF(BTRIM(COALESCE(v_result_json->>'fallback_reason', '')), ''),
    'delta_refresh_complete', CASE WHEN v_result_json ? 'delta_refresh_complete' THEN v_result_json->'delta_refresh_complete' ELSE NULL END,
    'made_progress', CASE WHEN v_result_json ? 'made_progress' THEN v_result_json->'made_progress' ELSE NULL END,
    'shadow_compare_required', CASE WHEN v_result_json ? 'shadow_compare_required' THEN v_result_json->'shadow_compare_required' ELSE NULL END,
    'shadow_compare_enforced', CASE WHEN v_result_json ? 'shadow_compare_enforced' THEN v_result_json->'shadow_compare_enforced' ELSE NULL END,
    'shadow_compare_failed', CASE WHEN v_result_json ? 'shadow_compare_failed' THEN v_result_json->'shadow_compare_failed' ELSE NULL END,
    'shadow_compare_status', NULLIF(BTRIM(COALESCE(v_result_json->>'shadow_compare_status', '')), ''),
    'phase', NULLIF(BTRIM(COALESCE(v_result_json->>'phase', v_result_json->>'next_phase', '')), ''),
    'write_phase', NULLIF(BTRIM(COALESCE(v_result_json->>'write_phase', '')), '')
  ));
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_workbench_repair_invalid_source_build_poison(p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT 'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_POISON_REPAIR'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 10), 100));
  v_reason text := COALESCE(NULLIF(BTRIM(p_reason), ''), 'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_POISON_REPAIR');
  v_repair_row record;
  v_processed_count integer := 0;
  v_repaired_count integer := 0;
  v_skipped_count integer := 0;
  v_restored_source_row_count integer := 0;
  v_total_restored_source_row_count integer := 0;
  v_requeued_line_seed_count integer := 0;
  v_repaired_scope_count integer := 0;
  v_repaired_session_count integer := 0;
  v_repairs_json jsonb := '[]'::jsonb;
  v_skips_json jsonb := '[]'::jsonb;
  v_source_rows_before_json jsonb := '{}'::jsonb;
  v_source_rows_after_json jsonb := '{}'::jsonb;
  v_bad_job_audit_before_json jsonb := '{}'::jsonb;
  v_bad_job_audit_after_json jsonb := '{}'::jsonb;
  v_line_seed_before_json jsonb := NULL::jsonb;
  v_line_seed_after_json jsonb := NULL::jsonb;
  v_scope_before_json jsonb := NULL::jsonb;
  v_scope_after_json jsonb := NULL::jsonb;
  v_session_before_json jsonb := NULL::jsonb;
  v_session_after_json jsonb := NULL::jsonb;
  v_progress_recompute_json jsonb := '{}'::jsonb;
  v_progress_recompute_failed boolean := false;
  v_progress_recompute_error_json jsonb := NULL::jsonb;
  v_source_row_object_id text := NULL::text;
  v_zero_repair_row record;
  v_zero_source_row_repaired_count integer := 0;
  v_corrected_source_build_job_queued_count integer := 0;
  v_corrected_source_build_job_reused_count integer := 0;
  v_corrected_source_build_job_succeeded_reused_count integer := 0;
  v_line_seed_attempt_count_reset_count integer := 0;
  v_zero_source_row_repairs_json jsonb := '[]'::jsonb;
  v_zero_source_row_skips_json jsonb := '[]'::jsonb;
  v_zero_corrected_job_id uuid := NULL::uuid;
  v_zero_corrected_job_status text := NULL::text;
  v_zero_corrected_job_payload_json jsonb := '{}'::jsonb;
  v_zero_existing_corrected_failed_job_id uuid := NULL::uuid;
  v_zero_source_change_seq bigint := 0;
  v_zero_session_version bigint := 0;
  v_zero_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_zero_pay_channel_scope text := 'ALL';
  v_zero_reason text := NULL::text;
  v_zero_source_session_id uuid := NULL::uuid;
  v_zero_source_session_id_text text := NULL::text;
  v_zero_source_session_version bigint := NULL::bigint;
  v_zero_source_session_signature text := NULL::text;
  v_zero_source_snapshot_run_id uuid := NULL::uuid;
  v_zero_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_zero_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_zero_source_build_seed_text text := NULL::text;
  v_zero_source_build_hash text := NULL::text;
  v_zero_source_build_run_id uuid := NULL::uuid;
  v_zero_corrected_dedupe_key text := NULL::text;
  v_zero_corrected_payload_json jsonb := '{}'::jsonb;
  v_zero_corrected_job_action text := NULL::text;
  v_zero_scope_before_json jsonb := NULL::jsonb;
  v_zero_scope_after_json jsonb := NULL::jsonb;
  v_zero_bad_job_before_json jsonb := NULL::jsonb;
  v_zero_bad_job_after_json jsonb := NULL::jsonb;
  v_zero_corrected_job_before_json jsonb := NULL::jsonb;
  v_zero_corrected_job_after_json jsonb := NULL::jsonb;
  v_zero_session_before_json jsonb := NULL::jsonb;
  v_zero_session_after_json jsonb := NULL::jsonb;
  v_post_recompute_progress_state text := NULL::text;
  v_post_recompute_scope_failed_count integer := NULL::integer;
  v_post_recompute_scope_pending_count integer := NULL::integer;
  v_orphan_repair_row record;
  v_orphan_enqueue_result jsonb := '{}'::jsonb;
  v_orphan_enqueue_error_json jsonb := NULL::jsonb;
  v_orphan_enqueue_job_id_text text := NULL::text;
  v_orphan_enqueue_job_id uuid := NULL::uuid;
  v_orphan_enqueue_job_type text := NULL::text;
  v_orphan_enqueue_job_status text := NULL::text;
  v_orphan_enqueue_source_build_run_id_text text := NULL::text;
  v_orphan_enqueue_valid boolean := false;
  v_orphan_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_orphan_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_orphan_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_orphan_pay_channel_scope text := 'ALL';
  v_orphan_source_change_seq bigint := 0;
  v_orphan_scope_before_json jsonb := NULL::jsonb;
  v_orphan_scope_after_json jsonb := NULL::jsonb;
  v_orphan_bad_job_before_json jsonb := NULL::jsonb;
  v_orphan_bad_job_after_json jsonb := NULL::jsonb;
  v_orphan_session_before_json jsonb := NULL::jsonb;
  v_orphan_session_after_json jsonb := NULL::jsonb;
  v_orphan_pending_repaired_count integer := 0;
  v_orphan_pending_failed_closed_count integer := 0;
  v_orphan_pending_repairs_json jsonb := '[]'::jsonb;
  v_orphan_pending_skips_json jsonb := '[]'::jsonb;
BEGIN
  FOR v_repair_row IN
    WITH poisoned_scope AS (
      SELECT
        scope_row.id AS scope_id,
        scope_row.session_id,
        scope_row.candidate_id,
        scope_row.status AS scope_status,
        scope_row.pending_job_id AS scope_pending_job_id,
        scope_row.dirty AS scope_dirty,
        scope_row.error_json AS scope_error_json,
        scope_row.updated_at_utc AS scope_updated_at_utc,
        NULLIF(BTRIM(COALESCE(
          scope_row.error_json->>'job_id',
          scope_row.error_json#>>'{job,job_id}',
          scope_row.error_json#>>'{source_build,job_id}',
          scope_row.error_json#>>'{last_error_json,job_id}',
          scope_row.error_json#>>'{job_error_json,job_id}',
          ''
        )), '') AS bad_job_id_text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_ERROR'
        AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
      LIMIT v_limit
      FOR UPDATE OF scope_row SKIP LOCKED
    ), bad_scope AS (
      SELECT
        poisoned_scope.*,
        bad_job_id.bad_job_id,
        bad_job.job_type AS bad_job_type,
        bad_job.status AS bad_job_status,
        bad_job.attempt_count AS bad_job_attempt_count,
        bad_job.max_attempts AS bad_job_max_attempts,
        bad_job.dedupe_key AS bad_job_dedupe_key,
        bad_job.payload_json AS bad_job_payload_json,
        bad_job.last_error_json AS bad_job_last_error_json,
        bad_job.created_at_utc AS bad_job_created_at_utc,
        bad_job.updated_at_utc AS bad_job_updated_at_utc,
        bad_job.failed_at_utc AS bad_job_failed_at_utc,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS bad_source_build_run_id_text,
        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
      FROM poisoned_scope
      JOIN LATERAL (
        SELECT poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = poisoned_scope.session_id
        AND bad_job.candidate_id = poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%WORKBENCH_SOURCE_BUILD_JOB_FAILED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
    ), candidate_runs AS (
      SELECT
        bad_scope.*,
        source_line.source_build_run_id,
        source_line.source_change_seq,
        COUNT(*)::integer AS source_rows_error_count,
        MIN(source_line.created_at_utc) AS source_rows_first_created_at_utc,
        MAX(source_line.updated_at_utc) AS source_rows_last_updated_at_utc
      FROM bad_scope
      JOIN public.banking_pay_workbench_candidate_source_lines AS source_line
        ON source_line.session_id = bad_scope.session_id
       AND source_line.candidate_id = bad_scope.candidate_id
       AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
      GROUP BY
        bad_scope.scope_id,
        bad_scope.session_id,
        bad_scope.candidate_id,
        bad_scope.scope_status,
        bad_scope.scope_pending_job_id,
        bad_scope.scope_dirty,
        bad_scope.scope_error_json,
        bad_scope.scope_updated_at_utc,
        bad_scope.bad_job_id_text,
        bad_scope.bad_job_id,
        bad_scope.bad_job_type,
        bad_scope.bad_job_status,
        bad_scope.bad_job_attempt_count,
        bad_scope.bad_job_max_attempts,
        bad_scope.bad_job_dedupe_key,
        bad_scope.bad_job_payload_json,
        bad_scope.bad_job_last_error_json,
        bad_scope.bad_job_created_at_utc,
        bad_scope.bad_job_updated_at_utc,
        bad_scope.bad_job_failed_at_utc,
        bad_scope.bad_source_build_run_id_text,
        bad_scope.live_candidate_change_seq,
        source_line.source_build_run_id,
        source_line.source_change_seq
    ), repair_choices AS (
      SELECT
        candidate_runs.*,
        good_source_job.id AS good_source_build_job_id,
        good_source_job.status AS good_source_build_job_status,
        good_source_job.updated_at_utc AS good_source_build_job_updated_at_utc,
        line_seed_job.id AS line_seed_job_id,
        line_seed_job.status AS line_seed_job_status,
        line_seed_job.attempt_count AS line_seed_attempt_count,
        line_seed_job.max_attempts AS line_seed_max_attempts,
        line_seed_job.updated_at_utc AS line_seed_updated_at_utc,
        line_seed_job.last_error_json AS line_seed_last_error_json
      FROM candidate_runs
      JOIN LATERAL (
        SELECT source_job.*
        FROM public.banking_pay_workbench_jobs AS source_job
        CROSS JOIN LATERAL (
          SELECT
            NULLIF(BTRIM(COALESCE(
              source_job.payload_json->>'source_build_run_id',
              source_job.payload_json#>>'{source_build,source_build_run_id}',
              source_job.payload_json#>>'{source_build,run_id}',
              source_job.payload_json#>>'{cursor,source_build_run_id}',
              source_job.payload_json#>>'{cursor_json,source_build_run_id}',
              source_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text,
            COALESCE(
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{result_json,source_change_seq}')::bigint ELSE NULL::bigint END
            ) AS source_change_seq
        ) AS source_job_extract
        WHERE source_job.session_id = candidate_runs.session_id
          AND source_job.candidate_id = candidate_runs.candidate_id
          AND source_job.id <> candidate_runs.bad_job_id
          AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
            'CANDIDATE_SOURCE_BUILD',
            'CANDIDATE_SOURCE_BUILD_CHUNK',
            'SOURCE_BUILD',
            'SOURCE_BUILD_PAGE'
          )
          AND UPPER(BTRIM(COALESCE(source_job.status, ''))) = 'SUCCEEDED'
          AND source_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND (
            source_job_extract.source_change_seq IS NULL
            OR source_job_extract.source_change_seq = candidate_runs.source_change_seq
          )
        ORDER BY source_job.updated_at_utc DESC NULLS LAST, source_job.created_at_utc DESC NULLS LAST, source_job.id DESC
        LIMIT 1
      ) AS good_source_job ON true
      JOIN LATERAL (
        SELECT line_job.*
        FROM public.banking_pay_workbench_jobs AS line_job
        CROSS JOIN LATERAL (
          SELECT NULLIF(BTRIM(COALESCE(
            line_job.payload_json->>'source_build_run_id',
            line_job.payload_json#>>'{source_build,source_build_run_id}',
            line_job.payload_json#>>'{source_build,run_id}',
            line_job.payload_json#>>'{cursor,source_build_run_id}',
            line_job.payload_json#>>'{cursor_json,source_build_run_id}',
            line_job.payload_json#>>'{source_build_cursor,source_build_run_id}',
            line_job.payload_json#>>'{result_json,source_build_run_id}',
            ''
          )), '') AS source_build_run_id_text
        ) AS line_job_extract
        WHERE line_job.session_id = candidate_runs.session_id
          AND line_job.candidate_id = candidate_runs.candidate_id
          AND UPPER(BTRIM(COALESCE(line_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE',
            'CANDIDATE_LINE_WORK_SEED',
            'CANDIDATE_LINE_WORK_SEED_PAGE',
            'LINE_WORK_SEED_PAGE',
            'SNAPSHOT_CANDIDATE_REFRESH',
            'CANDIDATE_REFRESH'
          )
          AND UPPER(BTRIM(COALESCE(line_job.status, ''))) IN ('FAILED', 'DEAD')
          AND line_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND COALESCE(line_job.last_error_json, '{}'::jsonb)::text ILIKE '%SOURCE_ROWS_MISSING%'
        ORDER BY line_job.updated_at_utc DESC NULLS LAST, line_job.created_at_utc DESC NULLS LAST, line_job.id DESC
        LIMIT 1
      ) AS line_seed_job ON true
      ORDER BY
        CASE WHEN candidate_runs.source_change_seq = candidate_runs.live_candidate_change_seq THEN 0 ELSE 1 END,
        candidate_runs.source_change_seq DESC,
        good_source_job.updated_at_utc DESC NULLS LAST,
        line_seed_job.updated_at_utc DESC NULLS LAST
      LIMIT v_limit
    )
    SELECT *
    FROM repair_choices
  LOOP
    v_processed_count := v_processed_count + 1;
    v_restored_source_row_count := 0;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_line_seed_before_json := NULL::jsonb;
    v_line_seed_after_json := NULL::jsonb;
    v_scope_before_json := NULL::jsonb;
    v_scope_after_json := NULL::jsonb;
    v_session_before_json := NULL::jsonb;
    v_session_after_json := NULL::jsonb;
    v_source_row_object_id := v_repair_row.source_build_run_id::text;

    v_bad_job_audit_before_json := jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'job_type', v_repair_row.bad_job_type,
      'status', v_repair_row.bad_job_status,
      'attempt_count', v_repair_row.bad_job_attempt_count,
      'max_attempts', v_repair_row.bad_job_max_attempts,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', v_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );
    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_before_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    WITH restored_source_rows AS (
      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
      SET status = 'CURRENT',
          source_row_json = jsonb_strip_nulls(
            (COALESCE(source_line.source_row_json, '{}'::jsonb) - 'stale_source_build_error' - 'source_build_error')
            || jsonb_build_object(
              'source_build_poison_repair', jsonb_build_object(
                'code', 'SOURCE_BUILD_ROWS_RESTORED',
                'repaired_at_utc', v_now::text,
                'session_id', v_repair_row.session_id::text,
                'candidate_id', v_repair_row.candidate_id::text,
                'bad_job_id', v_repair_row.bad_job_id::text,
                'source_build_run_id', v_repair_row.source_build_run_id::text,
                'source_change_seq', v_repair_row.source_change_seq,
                'line_seed_job_id', v_repair_row.line_seed_job_id::text,
                'reason', v_reason,
                'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
              )
            )
          ),
          updated_at_utc = v_now
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
        AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS existing_current_source_line
          WHERE existing_current_source_line.id <> source_line.id
            AND existing_current_source_line.session_id = source_line.session_id
            AND existing_current_source_line.candidate_id = source_line.candidate_id
            AND existing_current_source_line.session_version = source_line.session_version
            AND existing_current_source_line.source_change_seq = source_line.source_change_seq
            AND existing_current_source_line.source_build_run_id = source_line.source_build_run_id
            AND COALESCE(existing_current_source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
            AND existing_current_source_line.line_key = source_line.line_key
            AND UPPER(BTRIM(COALESCE(existing_current_source_line.status, ''))) = 'CURRENT'
        )
      RETURNING source_line.id
    )
    SELECT COUNT(*)::integer
    INTO v_restored_source_row_count
    FROM restored_source_rows;

    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_after_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    PERFORM public._audit_insert(
      'banking_pay_workbench_candidate_source_lines',
      v_source_row_object_id,
      'SOURCE_BUILD_ROWS_RESTORED',
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'status_counts', COALESCE(v_source_rows_before_json, '[]'::jsonb),
        'old_status', 'ERROR',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
        'affected_row_count', COALESCE(v_restored_source_row_count, 0),
        'status_counts', COALESCE(v_source_rows_after_json, '[]'::jsonb),
        'new_status', 'CURRENT',
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      'SOURCE_BUILD_ROWS_RESTORED',
      NULL
    );

    IF COALESCE(v_restored_source_row_count, 0) <= 0 THEN
      v_skipped_count := v_skipped_count + 1;
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'reason', 'NO_ERROR_SOURCE_ROWS_RESTORED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
            'source_build_poison_repair_source_build_run_id', v_repair_row.source_build_run_id::text,
            'source_build_poison_repair_source_change_seq', v_repair_row.source_change_seq,
            'source_build_poison_repair_line_seed_job_id', v_repair_row.line_seed_job_id::text,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'repaired_source_build_run_id', v_repair_row.source_build_run_id::text,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_bad_job_audit_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.bad_job_id::text,
      'FAILED',
      v_bad_job_audit_before_json,
      v_bad_job_audit_after_json,
      'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_before_json
    FROM public.banking_pay_workbench_jobs AS line_seed_job
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS line_seed_job
    SET status = 'QUEUED',
        attempt_count = 0,
        run_at_utc = v_now,
        started_at_utc = NULL::timestamptz,
        completed_at_utc = NULL::timestamptz,
        failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        payload_json = jsonb_strip_nulls(
          (COALESCE(line_seed_job.payload_json, '{}'::jsonb) - 'last_failure_json')
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
              'requeued_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'attempt_count_reset_to', 0,
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        updated_at_utc = v_now
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
      AND UPPER(BTRIM(COALESCE(line_seed_job.status, ''))) IN ('FAILED', 'DEAD')
    RETURNING jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.line_seed_job_id::text,
      'REQUEUED',
      v_line_seed_before_json,
      v_line_seed_after_json,
      'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
      NULL
    );

    IF v_line_seed_after_json IS NOT NULL THEN
      v_line_seed_attempt_count_reset_count := v_line_seed_attempt_count_reset_count + 1;
    END IF;

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'LINE_WORK_PENDING',
        dirty = true,
        pending_job_id = v_repair_row.line_seed_job_id,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_repair_row.scope_id
      AND scope_row.session_id = v_repair_row.session_id
      AND scope_row.candidate_id = v_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_repair_row.candidate_id::text,
      'SOURCE_BUILD_POISON_REPAIRED',
      v_scope_before_json,
      v_scope_after_json,
      'SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          (
            public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
            - 'last_source_build_failure_at_utc'
            - 'last_source_build_failure_job_id'
            - 'last_source_build_failure_code'
            - 'last_source_build_failure_source_build_run_id'
            - 'last_source_build_source_rows_marked_error_count'
            - 'blocker_codes'
            - 'draft_blocker_codes'
            - 'session_blocker_codes'
          )
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
              'repaired_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'line_seed_job_id', v_repair_row.line_seed_job_id::text,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_repair_row.session_id,
        p_apply => true,
        p_reason => 'SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_repair_row.session_id::text,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_session_before_json,
      v_session_after_json,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_total_restored_source_row_count := v_total_restored_source_row_count + COALESCE(v_restored_source_row_count, 0);
    v_requeued_line_seed_count := v_requeued_line_seed_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
      'line_seed_requeued', true,
      'line_seed_attempt_count_reset', v_line_seed_after_json IS NOT NULL,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_zero_repair_row IN
    WITH zero_poisoned_scope AS (
      SELECT
        scope_row.id AS scope_id,
        scope_row.session_id,
        scope_row.candidate_id,
        scope_row.status AS scope_status,
        scope_row.pending_job_id AS scope_pending_job_id,
        scope_row.dirty AS scope_dirty,
        scope_row.error_json AS scope_error_json,
        scope_row.updated_at_utc AS scope_updated_at_utc,
        NULLIF(BTRIM(COALESCE(
          scope_row.error_json->>'job_id',
          scope_row.error_json#>>'{job,job_id}',
          scope_row.error_json#>>'{source_build,job_id}',
          scope_row.error_json#>>'{last_error_json,job_id}',
          scope_row.error_json#>>'{job_error_json,job_id}',
          ''
        )), '') AS bad_job_id_text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_ERROR'
        AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
      LIMIT GREATEST(v_limit - v_processed_count, 0)
      FOR UPDATE OF scope_row SKIP LOCKED
    ), zero_bad_scope AS (
      SELECT
        zero_poisoned_scope.*,
        bad_job.id AS bad_job_id,
        bad_job.job_type AS bad_job_type,
        bad_job.status AS bad_job_status,
        bad_job.attempt_count AS bad_job_attempt_count,
        bad_job.max_attempts AS bad_job_max_attempts,
        bad_job.dedupe_key AS bad_job_dedupe_key,
        COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
        bad_job.last_error_json AS bad_job_last_error_json,
        bad_job.created_at_utc AS bad_job_created_at_utc,
        bad_job.updated_at_utc AS bad_job_updated_at_utc,
        bad_job.failed_at_utc AS bad_job_failed_at_utc,
        target_session.version AS target_session_version,
        target_session.session_signature AS target_session_signature,
        target_session.source_snapshot_run_id AS target_source_snapshot_run_id,
        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS bad_source_build_run_id_text,
        COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) AS source_rows_marked_error_count,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_session_id',
          bad_job.payload_json->>'clone_from_session_id',
          bad_job.payload_json#>>'{source_build,source_session_id}',
          bad_job.payload_json#>>'{source_build,clone_from_session_id}',
          zero_poisoned_scope.scope_error_json->>'source_session_id',
          zero_poisoned_scope.scope_error_json->>'clone_from_session_id',
          ''
        )), '') AS source_session_id_text,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (zero_poisoned_scope.scope_error_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          COALESCE(app_counter.seq, 0)::bigint,
          0::bigint
        ) AS repaired_source_change_seq,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'session_version')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,session_version}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,session_version}')::bigint ELSE NULL::bigint END,
          target_session.version,
          1::bigint
        ) AS repaired_session_version,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'refresh_scope_kind',
          bad_job.payload_json#>>'{source_build,refresh_scope_kind}',
          zero_poisoned_scope.scope_error_json->>'refresh_scope_kind',
          ''
        ))), ''), 'CANDIDATE_FULL_LIVE') AS repaired_refresh_scope_kind,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'pay_channel_scope',
          bad_job.payload_json#>>'{source_build,pay_channel_scope}',
          zero_poisoned_scope.scope_error_json->>'pay_channel_scope',
          ''
        ))), ''), 'ALL') AS repaired_pay_channel_scope,
        COALESCE(NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'fallback_reason',
          bad_job.payload_json->>'refresh_reason',
          bad_job.payload_json->>'reason',
          bad_job.payload_json#>>'{source_build,reason}',
          zero_poisoned_scope.scope_error_json->>'reason',
          ''
        )), ''), 'CLONE_REBASE_INELIGIBLE') AS repaired_reason
      FROM zero_poisoned_scope
      JOIN LATERAL (
        SELECT zero_poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE zero_poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      JOIN public.banking_pay_workbench_sessions AS target_session
        ON target_session.id = zero_poisoned_scope.session_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || zero_poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = zero_poisoned_scope.session_id
        AND bad_job.candidate_id = zero_poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
        AND COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) = 0
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS error_source_line
          WHERE error_source_line.session_id = zero_poisoned_scope.session_id
            AND error_source_line.candidate_id = zero_poisoned_scope.candidate_id
            AND UPPER(BTRIM(COALESCE(error_source_line.status, ''))) = 'ERROR'
        )
    ), zero_authority AS (
      SELECT
        zero_bad_scope.*,
        source_session.id AS source_session_id,
        source_session.version AS source_session_version,
        source_session.session_signature AS source_session_signature,
        source_session.source_snapshot_run_id AS source_snapshot_run_id,
        COALESCE(targeted_ids.targeted_timesheet_ids_json, '[]'::jsonb) AS targeted_timesheet_ids_json,
        COALESCE(linked_ids.linked_timesheet_ids_json, '[]'::jsonb) AS linked_timesheet_ids_json,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NULL THEN true
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               AND source_session.id IS NOT NULL THEN true
          ELSE false
        END AS authority_ok,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND zero_bad_scope.source_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN 'ZERO_SOURCE_ROW_REPAIR_INVALID_SOURCE_SESSION_ID'
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND source_session.id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_SOURCE_SESSION_NOT_FOUND'
          WHEN zero_bad_scope.target_session_signature IS NULL
               OR zero_bad_scope.target_source_snapshot_run_id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'
          ELSE NULL::text
        END AS authority_skip_reason
      FROM zero_bad_scope
      LEFT JOIN public.banking_pay_workbench_sessions AS source_session
        ON source_session.id = CASE
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN zero_bad_scope.source_session_id_text::uuid
          ELSE NULL::uuid
        END
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(targeted_sorted.timesheet_id_text ORDER BY targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
        FROM (
          SELECT DISTINCT targeted_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(targeted_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'targeted_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS targeted_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(targeted_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,targeted_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS targeted_nested_value(value)
          ) AS targeted_raw
          WHERE targeted_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS targeted_sorted
      ) AS targeted_ids
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(linked_sorted.timesheet_id_text ORDER BY linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
        FROM (
          SELECT DISTINCT linked_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(linked_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'linked_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS linked_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(linked_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,linked_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS linked_nested_value(value)
          ) AS linked_raw
          WHERE linked_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS linked_sorted
      ) AS linked_ids
    )
    SELECT *
    FROM zero_authority
  LOOP
    v_processed_count := v_processed_count + 1;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_zero_corrected_job_id := NULL::uuid;
    v_zero_corrected_job_status := NULL::text;
    v_zero_corrected_job_payload_json := '{}'::jsonb;
    v_zero_existing_corrected_failed_job_id := NULL::uuid;
    v_zero_corrected_job_action := NULL::text;
    v_zero_source_change_seq := COALESCE(v_zero_repair_row.repaired_source_change_seq, 0);
    v_zero_session_version := COALESCE(v_zero_repair_row.repaired_session_version, v_zero_repair_row.target_session_version, 1);
    v_zero_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_refresh_scope_kind)), ''), 'CANDIDATE_FULL_LIVE');
    v_zero_pay_channel_scope := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_pay_channel_scope)), ''), 'ALL');
    v_zero_reason := COALESCE(NULLIF(BTRIM(v_zero_repair_row.repaired_reason), ''), 'CLONE_REBASE_INELIGIBLE');
    v_zero_source_session_id := v_zero_repair_row.source_session_id;
    v_zero_source_session_id_text := v_zero_repair_row.source_session_id_text;
    v_zero_source_session_version := v_zero_repair_row.source_session_version;
    v_zero_source_session_signature := v_zero_repair_row.source_session_signature;
    v_zero_source_snapshot_run_id := v_zero_repair_row.source_snapshot_run_id;
    v_zero_targeted_timesheet_ids_json := COALESCE(v_zero_repair_row.targeted_timesheet_ids_json, '[]'::jsonb);
    v_zero_linked_timesheet_ids_json := COALESCE(v_zero_repair_row.linked_timesheet_ids_json, '[]'::jsonb);

    IF COALESCE(v_zero_repair_row.authority_ok, false) IS NOT TRUE THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_zero_source_build_seed_text := concat_ws(
      ':',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'ZERO_SOURCE_ROW_POISON_REPAIR',
      'target_session_id', v_zero_repair_row.session_id::text,
      'target_session_version', COALESCE(v_zero_session_version, 1)::text,
      'target_session_signature', COALESCE(v_zero_repair_row.target_session_signature, ''),
      'target_snapshot_run_id', COALESCE(v_zero_repair_row.target_source_snapshot_run_id::text, ''),
      'source_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'source_session_version', COALESCE(v_zero_source_session_version::text, ''),
      'source_session_signature', COALESCE(v_zero_source_session_signature, ''),
      'source_snapshot_run_id', COALESCE(v_zero_source_snapshot_run_id::text, ''),
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0)::text,
      'refresh_scope_kind', v_zero_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb)::text,
      'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb)::text,
      'pay_channel_scope', v_zero_pay_channel_scope,
      'clone_from_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'clone_to_session_id', v_zero_repair_row.session_id::text,
      'reason', v_zero_reason
    );
    v_zero_source_build_hash := md5(v_zero_source_build_seed_text);
    v_zero_source_build_run_id := (
      substr(v_zero_source_build_hash, 1, 8) || '-' ||
      substr(v_zero_source_build_hash, 9, 4) || '-' ||
      substr(v_zero_source_build_hash, 13, 4) || '-' ||
      substr(v_zero_source_build_hash, 17, 4) || '-' ||
      substr(v_zero_source_build_hash, 21, 12)
    )::uuid;
    v_zero_corrected_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD:session:' || v_zero_repair_row.session_id::text || ':candidate:' || v_zero_repair_row.candidate_id::text || ':clone_ineligible:corrected:' || v_zero_source_build_run_id::text;

    v_zero_corrected_payload_json := jsonb_strip_nulls(
      jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'session_version', v_zero_session_version,
        'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
        'source_build_run_id', v_zero_source_build_run_id::text,
        'operation_type', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
        'fallback_reason', v_zero_reason,
        'refresh_reason', v_zero_reason,
        'reason', v_zero_reason,
        'refresh_scope_kind', v_zero_refresh_scope_kind,
        'pay_channel_scope', v_zero_pay_channel_scope,
        'source_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
        'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
        'clone_to_session_id', v_zero_repair_row.session_id::text,
        'target_session_signature', v_zero_repair_row.target_session_signature,
        'source_session_signature', v_zero_source_session_signature,
        'force_legacy', true,
        'source_build_required', true,
        'line_work_required', true,
        'delta_refresh_required', false
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
        'zero_source_row_poison_repair', true,
        'zero_source_row_bad_job_id', v_zero_repair_row.bad_job_id::text,
        'zero_source_row_original_dedupe_key', v_zero_repair_row.bad_job_dedupe_key,
        'source_build_run_id_source', jsonb_build_object(
          'method', 'DETERMINISTIC_MD5_UUID_FROM_AUTHORITY_INPUTS',
          'seed_text', v_zero_source_build_seed_text,
          'target_session_id', v_zero_repair_row.session_id::text,
          'target_session_version', v_zero_session_version,
          'target_session_signature', v_zero_repair_row.target_session_signature,
          'target_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
          'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
          'source_session_version', v_zero_source_session_version,
          'source_session_signature', v_zero_source_session_signature,
          'source_snapshot_run_id', CASE WHEN v_zero_source_snapshot_run_id IS NULL THEN NULL ELSE v_zero_source_snapshot_run_id::text END,
          'candidate_id', v_zero_repair_row.candidate_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_zero_pay_channel_scope,
          'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
          'clone_to_session_id', v_zero_repair_row.session_id::text
        )
      )
      || jsonb_build_object(
        'source_build', jsonb_build_object(
          'required', true,
          'run_id', v_zero_source_build_run_id::text,
          'source_build_run_id', v_zero_source_build_run_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
          'session_version', v_zero_session_version,
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'pay_channel_scope', v_zero_pay_channel_scope,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'reason', v_zero_reason
        ),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
    );

    SELECT corrected_job.id,
           corrected_job.status,
           COALESCE(corrected_job.payload_json, '{}'::jsonb)
    INTO v_zero_corrected_job_id,
         v_zero_corrected_job_status,
         v_zero_corrected_job_payload_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.session_id = v_zero_repair_row.session_id
      AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
      AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
      AND corrected_job.status IN ('QUEUED', 'RUNNING')
    ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
             corrected_job.updated_at_utc DESC NULLS LAST,
             corrected_job.created_at_utc DESC NULLS LAST,
             corrected_job.id DESC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF v_zero_corrected_job_id IS NOT NULL THEN
      v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB';
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      SELECT corrected_job.id,
             corrected_job.status,
             COALESCE(corrected_job.payload_json, '{}'::jsonb)
      INTO v_zero_corrected_job_id,
           v_zero_corrected_job_status,
           v_zero_corrected_job_payload_json
      FROM public.banking_pay_workbench_jobs AS corrected_job
      WHERE corrected_job.session_id = v_zero_repair_row.session_id
        AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
        AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
        AND corrected_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
               corrected_job.updated_at_utc DESC NULLS LAST,
               corrected_job.created_at_utc DESC NULLS LAST,
               corrected_job.id DESC
      LIMIT 1;

      IF v_zero_corrected_job_id IS NOT NULL THEN
        v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB_NOT_LOCKED';
        v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
      ELSE
        SELECT corrected_job.id,
               corrected_job.status,
               COALESCE(corrected_job.payload_json, '{}'::jsonb)
        INTO v_zero_corrected_job_id,
             v_zero_corrected_job_status,
             v_zero_corrected_job_payload_json
        FROM public.banking_pay_workbench_jobs AS corrected_job
        WHERE corrected_job.session_id = v_zero_repair_row.session_id
          AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
          AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
          AND corrected_job.status = 'SUCCEEDED'
        ORDER BY corrected_job.completed_at_utc DESC NULLS LAST,
                 corrected_job.updated_at_utc DESC NULLS LAST,
                 corrected_job.created_at_utc DESC NULLS LAST,
                 corrected_job.id DESC
        LIMIT 1;

        IF v_zero_corrected_job_id IS NOT NULL THEN
          v_zero_corrected_job_action := 'REUSED_SUCCEEDED_CORRECTED_SOURCE_BUILD_JOB';
          v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
        ELSE
          SELECT corrected_job.id
          INTO v_zero_existing_corrected_failed_job_id
          FROM public.banking_pay_workbench_jobs AS corrected_job
          CROSS JOIN LATERAL (
            SELECT NULLIF(BTRIM(COALESCE(
              corrected_job.payload_json->>'source_build_run_id',
              corrected_job.payload_json#>>'{source_build,source_build_run_id}',
              corrected_job.payload_json#>>'{source_build,run_id}',
              corrected_job.payload_json#>>'{cursor,source_build_run_id}',
              corrected_job.payload_json#>>'{cursor_json,source_build_run_id}',
              corrected_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text
          ) AS corrected_extract
          WHERE corrected_job.session_id = v_zero_repair_row.session_id
            AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
            AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
            AND corrected_job.status IN ('FAILED', 'DEAD')
            AND corrected_extract.source_build_run_id_text = v_zero_source_build_run_id::text
          ORDER BY corrected_job.updated_at_utc DESC NULLS LAST,
                   corrected_job.created_at_utc DESC NULLS LAST,
                   corrected_job.id DESC
          LIMIT 1;

          IF v_zero_existing_corrected_failed_job_id IS NOT NULL THEN
            v_skipped_count := v_skipped_count + 1;
            v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'corrected_source_build_run_id', v_zero_source_build_run_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            CONTINUE;
          END IF;

          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_zero_corrected_dedupe_key,
            v_zero_repair_row.target_source_snapshot_run_id,
            v_zero_repair_row.session_id,
            v_zero_repair_row.candidate_id,
            v_zero_corrected_payload_json,
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_zero_corrected_job_id, v_zero_corrected_job_status, v_zero_corrected_job_payload_json;

          IF v_zero_corrected_job_id IS NOT NULL THEN
            v_zero_corrected_job_action := 'QUEUED_CORRECTED_SOURCE_BUILD_JOB';
            v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
          ELSE
            SELECT corrected_job.id,
                   corrected_job.status,
                   COALESCE(corrected_job.payload_json, '{}'::jsonb)
            INTO v_zero_corrected_job_id,
                 v_zero_corrected_job_status,
                 v_zero_corrected_job_payload_json
            FROM public.banking_pay_workbench_jobs AS corrected_job
            WHERE corrected_job.session_id = v_zero_repair_row.session_id
              AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
              AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
              AND corrected_job.status IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
            ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 WHEN corrected_job.status = 'RUNNING' THEN 1 ELSE 2 END,
                     corrected_job.updated_at_utc DESC NULLS LAST,
                     corrected_job.created_at_utc DESC NULLS LAST,
                     corrected_job.id DESC
            LIMIT 1;

            IF v_zero_corrected_job_id IS NOT NULL THEN
              v_zero_corrected_job_action := 'REUSED_CORRECTED_SOURCE_BUILD_JOB_AFTER_CONFLICT';
              IF v_zero_corrected_job_status = 'SUCCEEDED' THEN
                v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
              ELSE
                v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_zero_corrected_job_id IS NULL THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    SELECT jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job.id::text,
      'job_type', bad_job.job_type,
      'status', bad_job.status,
      'attempt_count', bad_job.attempt_count,
      'max_attempts', bad_job.max_attempts,
      'dedupe_key', bad_job.dedupe_key,
      'payload_json', bad_job.payload_json,
      'last_error_json', bad_job.last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_before_json
    FROM public.banking_pay_workbench_jobs AS bad_job
    WHERE bad_job.id = v_zero_repair_row.bad_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'zero_source_row_repair_resolved', true,
            'zero_source_row_repair_resolved_at_utc', v_now::text,
            'zero_source_row_corrected_job_id', v_zero_corrected_job_id::text,
            'zero_source_row_corrected_source_build_run_id', v_zero_source_build_run_id::text,
            'zero_source_row_corrected_dedupe_key', v_zero_corrected_dedupe_key,
            'source_rows_marked_error_count', COALESCE(v_zero_repair_row.source_rows_marked_error_count, 0),
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_zero_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'zero_source_row_repair_resolved', true,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_repair_row.bad_job_id::text,
      'ZERO_SOURCE_ROW_BAD_JOB_MARKED_NON_BLOCKING',
      v_zero_bad_job_before_json,
      v_zero_bad_job_after_json,
      'ZERO_SOURCE_ROW_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', corrected_job.id::text,
      'job_type', corrected_job.job_type,
      'status', corrected_job.status,
      'dedupe_key', corrected_job.dedupe_key,
      'session_id', CASE WHEN corrected_job.session_id IS NULL THEN NULL ELSE corrected_job.session_id::text END,
      'candidate_id', CASE WHEN corrected_job.candidate_id IS NULL THEN NULL ELSE corrected_job.candidate_id::text END,
      'source_build_run_id', v_zero_source_build_run_id::text,
      'payload_json', corrected_job.payload_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_corrected_job_after_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.id = v_zero_corrected_job_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_corrected_job_id::text,
      COALESCE(v_zero_corrected_job_action, 'CORRECTED_SOURCE_BUILD_JOB_REUSED'),
      v_zero_corrected_job_before_json,
      v_zero_corrected_job_after_json,
      'ZERO_SOURCE_ROW_CORRECTED_SOURCE_BUILD_JOB_READY',
      NULL
    );

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_zero_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'SOURCE_BUILD_PENDING',
        pending_job_id = v_zero_corrected_job_id,
        seeded = false,
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_zero_repair_row.scope_id
      AND scope_row.session_id = v_zero_repair_row.session_id
      AND scope_row.candidate_id = v_zero_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_zero_repair_row.candidate_id::text,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      v_zero_scope_before_json,
      v_zero_scope_after_json,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_failed_count', session_row.scope_failed_count,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_ready_count', session_row.scope_ready_count,
      'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
      'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
      'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
          - 'last_source_build_failure_at_utc'
          - 'last_source_build_failure_job_id'
          - 'last_source_build_failure_code'
          - 'last_source_build_failure_source_build_run_id'
          - 'last_source_build_source_rows_marked_error_count'
          - 'blocker_codes'
          - 'draft_blocker_codes'
          - 'session_blocker_codes'
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_zero_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_zero_repair_row.session_id,
        p_apply => true,
        p_reason => 'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_job_id', v_zero_corrected_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT session_row.progress_state,
           session_row.scope_failed_count,
           session_row.scope_pending_count,
           jsonb_build_object(
             'id', session_row.id::text,
             'status', session_row.status,
             'progress_state', session_row.progress_state,
             'scope_failed_count', session_row.scope_failed_count,
             'scope_pending_count', session_row.scope_pending_count,
             'scope_ready_count', session_row.scope_ready_count,
             'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
             'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
             'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
             'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
             'bad_job_id', v_zero_repair_row.bad_job_id::text,
             'corrected_source_build_job_id', v_zero_corrected_job_id::text,
             'corrected_source_build_run_id', v_zero_source_build_run_id::text,
             'recompute_failed', v_progress_recompute_failed,
             'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
             'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
           )
    INTO v_post_recompute_progress_state,
         v_post_recompute_scope_failed_count,
         v_post_recompute_scope_pending_count,
         v_zero_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_zero_repair_row.session_id::text,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_zero_session_before_json,
      v_zero_session_after_json,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_zero_source_row_repaired_count := v_zero_source_row_repaired_count + 1;
    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_zero_source_row_repairs_json := v_zero_source_row_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_job_status', v_zero_corrected_job_status,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'post_recompute_progress_state', v_post_recompute_progress_state,
      'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
      'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
      'corrected_job_action', v_zero_corrected_job_action,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'zero_source_row_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_orphan_repair_row IN
    SELECT
      scope_row.id AS scope_id,
      scope_row.session_id,
      scope_row.candidate_id,
      scope_row.status AS scope_status,
      scope_row.pending_job_id AS bad_job_id,
      scope_row.dirty AS scope_dirty,
      scope_row.seeded AS scope_seeded,
      scope_row.error_json AS scope_error_json,
      scope_row.updated_at_utc AS scope_updated_at_utc,
      bad_job.job_type AS bad_job_type,
      bad_job.status AS bad_job_status,
      bad_job.dedupe_key AS bad_job_dedupe_key,
      COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
      bad_job.last_error_json AS bad_job_last_error_json,
      bad_job.failed_at_utc AS bad_job_failed_at_utc,
      target_session.actor_user_id AS session_actor_user_id,
      target_session.version AS session_version,
      target_session.session_signature,
      target_session.source_snapshot_run_id,
      COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_jobs AS bad_job
      ON bad_job.id = scope_row.pending_job_id
    JOIN public.banking_pay_workbench_sessions AS target_session
      ON target_session.id = scope_row.session_id
    LEFT JOIN public.app_change_counters AS app_counter
      ON app_counter.entity_key = 'pay_candidate:' || scope_row.candidate_id::text
    WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(scope_row.dirty, false) IS TRUE
      AND scope_row.pending_job_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
        'CANDIDATE_SOURCE_BUILD',
        'CANDIDATE_SOURCE_BUILD_CHUNK',
        'SOURCE_BUILD',
        'SOURCE_BUILD_PAGE'
      )
      AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND bad_job.session_id = scope_row.session_id
      AND bad_job.candidate_id = scope_row.candidate_id
      AND NULLIF(BTRIM(COALESCE(
        bad_job.payload_json->>'source_build_run_id',
        bad_job.payload_json#>>'{source_build,source_build_run_id}',
        bad_job.payload_json#>>'{source_build,run_id}',
        bad_job.payload_json#>>'{cursor,source_build_run_id}',
        bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
        bad_job.payload_json#>>'{result_json,source_build_run_id}',
        ''
      )), '') IS NULL
      AND (
        COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR COALESCE(bad_job.payload_json#>'{last_failure_json}', '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR (
          lower(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND UPPER(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure_reason', ''))) = 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE'
        )
        OR lower(BTRIM(COALESCE(bad_job.payload_json->>'invalid_source_build_without_run_id_failed_closed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND UPPER(BTRIM(COALESCE(target_session.status, ''))) = 'OPEN'
      AND target_session.discarded_at_utc IS NULL
      AND target_session.source_snapshot_run_id IS NOT NULL
      AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
      AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
    ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
    LIMIT GREATEST(v_limit - v_processed_count, 0)
  LOOP
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS locked_session
    WHERE locked_session.id = v_orphan_repair_row.session_id
      AND UPPER(BTRIM(COALESCE(locked_session.status, ''))) = 'OPEN'
      AND locked_session.discarded_at_utc IS NULL
      AND locked_session.source_snapshot_run_id IS NOT NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_SESSION_NO_LONGER_OPEN',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS locked_scope
    JOIN public.banking_pay_workbench_jobs AS locked_bad_job
      ON locked_bad_job.id = locked_scope.pending_job_id
    WHERE locked_scope.id = v_orphan_repair_row.scope_id
      AND locked_scope.session_id = v_orphan_repair_row.session_id
      AND locked_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(locked_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(locked_scope.dirty, false) IS TRUE
      AND locked_scope.pending_job_id = v_orphan_repair_row.bad_job_id
      AND UPPER(BTRIM(COALESCE(locked_bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND locked_bad_job.session_id = locked_scope.session_id
      AND locked_bad_job.candidate_id = locked_scope.candidate_id
    FOR UPDATE OF locked_scope, locked_bad_job;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_STATE_ALREADY_CHANGED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_processed_count := v_processed_count + 1;
    v_orphan_enqueue_result := '{}'::jsonb;
    v_orphan_enqueue_error_json := NULL::jsonb;
    v_orphan_enqueue_job_id_text := NULL::text;
    v_orphan_enqueue_job_id := NULL::uuid;
    v_orphan_enqueue_job_type := NULL::text;
    v_orphan_enqueue_job_status := NULL::text;
    v_orphan_enqueue_source_build_run_id_text := NULL::text;
    v_orphan_enqueue_valid := false;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;

    WITH targeted_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids_requested}')
    ), targeted_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(targeted_value.value), '')
      FROM targeted_arrays AS targeted_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(targeted_array.value_json) = 'array' THEN targeted_array.value_json ELSE '[]'::jsonb END
      ) AS targeted_value(value)
    )
    SELECT COALESCE(jsonb_agg(targeted_ids.timesheet_id_text ORDER BY targeted_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_targeted_timesheet_ids_json
    FROM (
      SELECT DISTINCT targeted_value.timesheet_id_text
      FROM targeted_values AS targeted_value
      WHERE targeted_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS targeted_ids;

    WITH linked_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids_requested}')
    ), linked_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(linked_value.value), '')
      FROM linked_arrays AS linked_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(linked_array.value_json) = 'array' THEN linked_array.value_json ELSE '[]'::jsonb END
      ) AS linked_value(value)
    )
    SELECT COALESCE(jsonb_agg(linked_ids.timesheet_id_text ORDER BY linked_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_linked_timesheet_ids_json
    FROM (
      SELECT DISTINCT linked_value.timesheet_id_text
      FROM linked_values AS linked_value
      WHERE linked_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS linked_ids;

    v_orphan_refresh_scope_kind := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'refresh_scope_kind', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,refresh_scope_kind}', ''),
      CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END
    )));

    IF v_orphan_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
      v_orphan_refresh_scope_kind := CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END;
    END IF;

    v_orphan_pay_channel_scope := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'pay_channel_scope', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,pay_channel_scope}', ''),
      'ALL'
    )));

    IF v_orphan_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
      v_orphan_pay_channel_scope := 'ALL';
    END IF;

    v_orphan_source_change_seq := COALESCE(
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
      v_orphan_repair_row.live_candidate_change_seq,
      0::bigint
    );

    v_orphan_scope_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.scope_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'status', v_orphan_repair_row.scope_status,
      'dirty', v_orphan_repair_row.scope_dirty,
      'seeded', v_orphan_repair_row.scope_seeded,
      'pending_job_id', v_orphan_repair_row.bad_job_id::text,
      'error_json', v_orphan_repair_row.scope_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    v_orphan_bad_job_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.bad_job_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', v_orphan_repair_row.bad_job_type,
      'status', v_orphan_repair_row.bad_job_status,
      'dedupe_key', v_orphan_repair_row.bad_job_dedupe_key,
      'source_build_run_id', NULL::text,
      'last_error_json', v_orphan_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    BEGIN
      v_orphan_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_orphan_repair_row.source_snapshot_run_id,
        p_candidate_id => v_orphan_repair_row.candidate_id,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIR',
        p_actor_user_id => v_orphan_repair_row.session_actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_orphan_repair_row.session_id::text,
            'source_session_id', v_orphan_repair_row.session_id::text,
            'source_snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'session_version', v_orphan_repair_row.session_version,
            'session_signature', v_orphan_repair_row.session_signature,
            'force_legacy', true,
            'fallback_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'projection_class', COALESCE(NULLIF(BTRIM(v_orphan_repair_row.bad_job_payload_json->>'projection_class'), ''), 'POST_DRAFT_PATCH_COMPLEX')
          )
          || jsonb_build_object(
            'source_change_seq', COALESCE(v_orphan_source_change_seq, 0),
            'refresh_scope_kind', v_orphan_refresh_scope_kind,
            'pay_channel_scope', v_orphan_pay_channel_scope,
            'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'enqueue_origin', 'PAY_WORKBENCH_REPAIR_INVALID_SOURCE_BUILD_POISON',
            'source_build_poison_repair', true,
            'invalid_source_build_bad_job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_request_reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        )
      );
    EXCEPTION WHEN OTHERS THEN
      v_orphan_enqueue_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
    END;

    v_orphan_enqueue_job_id_text := NULLIF(BTRIM(COALESCE(v_orphan_enqueue_result->>'job_id', '')), '');

    IF v_orphan_enqueue_error_json IS NULL
       AND v_orphan_enqueue_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_orphan_enqueue_job_id := v_orphan_enqueue_job_id_text::uuid;

      SELECT
        successor_job.job_type,
        successor_job.status,
        NULLIF(BTRIM(COALESCE(
          successor_job.payload_json->>'source_build_run_id',
          successor_job.payload_json#>>'{source_build,source_build_run_id}',
          successor_job.payload_json#>>'{source_build,run_id}',
          ''
        )), '')
      INTO
        v_orphan_enqueue_job_type,
        v_orphan_enqueue_job_status,
        v_orphan_enqueue_source_build_run_id_text
      FROM public.banking_pay_workbench_jobs AS successor_job
      WHERE successor_job.id = v_orphan_enqueue_job_id
        AND successor_job.session_id = v_orphan_repair_row.session_id
        AND successor_job.candidate_id = v_orphan_repair_row.candidate_id
      FOR UPDATE;

      v_orphan_enqueue_valid := FOUND
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_status, ''))) IN ('QUEUED', 'RUNNING')
        AND v_orphan_enqueue_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    END IF;

    IF v_orphan_enqueue_valid IS NOT TRUE THEN
      v_orphan_enqueue_error_json := COALESCE(
        v_orphan_enqueue_error_json,
        jsonb_build_object(
          'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'enqueue_result', COALESCE(v_orphan_enqueue_result, '{}'::jsonb),
          'successor_job_id', v_orphan_enqueue_job_id_text,
          'successor_job_type', v_orphan_enqueue_job_type,
          'successor_job_status', v_orphan_enqueue_job_status,
          'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        )
      );

      UPDATE public.banking_pay_workbench_session_scope AS failed_scope
      SET status = 'SOURCE_BUILD_ERROR',
          dirty = true,
          pending_job_id = NULL::uuid,
          error_json = jsonb_build_object(
            'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
            'job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_error_json', v_orphan_enqueue_error_json,
            'reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          ),
          updated_at_utc = v_now
      WHERE failed_scope.id = v_orphan_repair_row.scope_id
        AND failed_scope.session_id = v_orphan_repair_row.session_id
        AND failed_scope.candidate_id = v_orphan_repair_row.candidate_id
        AND (
          failed_scope.pending_job_id = v_orphan_repair_row.bad_job_id
          OR (v_orphan_enqueue_job_id IS NOT NULL AND failed_scope.pending_job_id = v_orphan_enqueue_job_id)
        );

      UPDATE public.banking_pay_workbench_jobs AS bad_job_update
      SET payload_json = jsonb_strip_nulls(
            COALESCE(bad_job_update.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'source_build_poison_repair_attempted', true,
              'source_build_poison_repair_attempted_at_utc', v_now::text,
              'source_build_poison_repair_successor_created', false,
              'source_build_poison_repair_error_json', v_orphan_enqueue_error_json,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          ),
          updated_at_utc = v_now
      WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id;

      BEGIN
        v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
          p_session_id => v_orphan_repair_row.session_id,
          p_apply => true,
          p_reason => 'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
          p_write_progress_json => true
        );
      EXCEPTION WHEN OTHERS THEN
        v_progress_recompute_failed := true;
        v_progress_recompute_error_json := jsonb_build_object(
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;

      SELECT jsonb_build_object(
        'id', failed_scope.id::text,
        'session_id', failed_scope.session_id::text,
        'candidate_id', failed_scope.candidate_id::text,
        'status', failed_scope.status,
        'dirty', failed_scope.dirty,
        'seeded', failed_scope.seeded,
        'pending_job_id', CASE WHEN failed_scope.pending_job_id IS NULL THEN NULL ELSE failed_scope.pending_job_id::text END,
        'error_json', failed_scope.error_json,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
      INTO v_orphan_scope_after_json
      FROM public.banking_pay_workbench_session_scope AS failed_scope
      WHERE failed_scope.id = v_orphan_repair_row.scope_id;

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_scope',
        v_orphan_repair_row.candidate_id::text,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        v_orphan_scope_before_json,
        v_orphan_scope_after_json,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        NULL
      );

      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_failed_closed_count := v_orphan_pending_failed_closed_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'scope_failed_closed', true,
        'failed_job_reference_cleared', true,
        'repair_error_json', v_orphan_enqueue_error_json,
        'progress_recompute_failed', v_progress_recompute_failed,
        'progress_recompute_error_json', v_progress_recompute_error_json,
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id
      AND repaired_scope.session_id = v_orphan_repair_row.session_id
      AND repaired_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(repaired_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(repaired_scope.dirty, false) IS TRUE
      AND repaired_scope.pending_job_id = v_orphan_enqueue_job_id
      AND repaired_scope.error_json IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED',
                'session_id', v_orphan_repair_row.session_id::text,
                'candidate_id', v_orphan_repair_row.candidate_id::text,
                'bad_job_id', v_orphan_repair_row.bad_job_id::text,
                'successor_job_id', v_orphan_enqueue_job_id::text,
                'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
                'message', 'The canonical candidate refresh helper did not replace the failed pending job reference with the validated successor.'
              )::text;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_successor_job_id', v_orphan_enqueue_job_id::text,
            'source_build_poison_repair_successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
            'source_build_poison_repair_successor_status', v_orphan_enqueue_job_status,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'id', bad_job_update.id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_bad_job_after_json;

    SELECT jsonb_build_object(
      'id', repaired_scope.id::text,
      'session_id', repaired_scope.session_id::text,
      'candidate_id', repaired_scope.candidate_id::text,
      'status', repaired_scope.status,
      'dirty', repaired_scope.dirty,
      'seeded', repaired_scope.seeded,
      'pending_job_id', CASE WHEN repaired_scope.pending_job_id IS NULL THEN NULL ELSE repaired_scope.pending_job_id::text END,
      'error_json', repaired_scope.error_json,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_scope_after_json
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id
    FOR UPDATE;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_orphan_repair_row.session_id,
        p_apply => true,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'successor_job_id', v_orphan_enqueue_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_orphan_repair_row.bad_job_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_bad_job_before_json,
      v_orphan_bad_job_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_orphan_repair_row.candidate_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_scope_before_json,
      v_orphan_scope_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_orphan_repair_row.session_id::text,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      v_orphan_session_before_json,
      v_orphan_session_after_json,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;
    v_orphan_pending_repaired_count := v_orphan_pending_repaired_count + 1;

    IF lower(BTRIM(COALESCE(v_orphan_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
    END IF;

    v_orphan_pending_repairs_json := v_orphan_pending_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_job_status', v_orphan_enqueue_job_status,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'refresh_scope_kind', v_orphan_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
      'failed_job_reference_replaced', true,
      'scope_dirty_preserved', true,
      'session_progress_recomputed', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_orphan_enqueue_job_id::text,
      'corrected_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'orphaned_pending_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'reason', v_reason,
    'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'processed_count', v_processed_count,
    'repaired_count', v_repaired_count,
    'skipped_count', v_skipped_count,
    'source_rows_restored_count', v_total_restored_source_row_count,
    'line_seed_requeued_count', v_requeued_line_seed_count,
    'scope_repaired_count', v_repaired_scope_count,
    'session_progress_repaired_count', v_repaired_session_count,
    'zero_source_row_repaired_count', v_zero_source_row_repaired_count,
    'corrected_source_build_job_queued_count', v_corrected_source_build_job_queued_count,
    'corrected_source_build_job_reused_count', v_corrected_source_build_job_reused_count,
    'corrected_source_build_job_succeeded_reused_count', v_corrected_source_build_job_succeeded_reused_count,
    'line_seed_attempt_count_reset_count', v_line_seed_attempt_count_reset_count,
    'post_recompute_progress_state', v_post_recompute_progress_state,
    'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
    'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
    'zero_source_row_repairs', COALESCE(v_zero_source_row_repairs_json, '[]'::jsonb),
    'zero_source_row_skips', COALESCE(v_zero_source_row_skips_json, '[]'::jsonb),
    'orphaned_pending_repaired_count', v_orphan_pending_repaired_count,
    'orphaned_pending_failed_closed_count', v_orphan_pending_failed_closed_count,
    'orphaned_pending_repairs', COALESCE(v_orphan_pending_repairs_json, '[]'::jsonb),
    'orphaned_pending_skips', COALESCE(v_orphan_pending_skips_json, '[]'::jsonb),
    'repairs', COALESCE(v_repairs_json, '[]'::jsonb),
    'skips', COALESCE(v_skips_json, '[]'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_workbench_normalise_timesheet_rotation_scope_payload(
  p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[],
  p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[]
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_requested_targeted uuid[] := ARRAY[]::uuid[];
  v_requested_linked uuid[] := ARRAY[]::uuid[];
  v_requested_all uuid[] := ARRAY[]::uuid[];
  v_targeted_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_semantic_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_canonical_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_canonical_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_canonical_timesheet_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  SELECT COALESCE(array_agg(DISTINCT raw_id ORDER BY raw_id), ARRAY[]::uuid[])
  INTO v_requested_targeted
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS raw(raw_id)
  WHERE raw.raw_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT raw_id ORDER BY raw_id), ARRAY[]::uuid[])
  INTO v_requested_linked
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS raw(raw_id)
  WHERE raw.raw_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT raw_id ORDER BY raw_id), ARRAY[]::uuid[])
  INTO v_requested_all
  FROM (
    SELECT unnest(v_requested_targeted) AS raw_id
    UNION ALL
    SELECT unnest(v_requested_linked) AS raw_id
  ) AS raw
  WHERE raw.raw_id IS NOT NULL;

  IF COALESCE(array_length(v_requested_all, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'targeted_timesheet_ids', '[]'::jsonb,
      'linked_timesheet_ids', '[]'::jsonb,
      'family_timesheet_ids', '[]'::jsonb,
      'canonical_timesheet_ids', '[]'::jsonb,
      'queue_identity_targeted_timesheet_ids', '[]'::jsonb,
      'queue_identity_linked_timesheet_ids', '[]'::jsonb,
      'queue_identity_timesheet_ids', '[]'::jsonb,
      'requested_timesheet_ids', '[]'::jsonb,
      'requested_targeted_timesheet_ids', '[]'::jsonb,
      'requested_linked_timesheet_ids', '[]'::jsonb,
      'rotation_family_resolved', false,
      'queue_identity_preserves_targeted_linked_semantics', true,
      'linked_timesheets_promoted_to_targeted', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  IF COALESCE(array_length(v_requested_targeted, 1), 0) > 0 THEN
    SELECT
      COALESCE(array_agg(target_scope.family_id ORDER BY target_scope.family_id), ARRAY[]::uuid[]),
      COALESCE(array_agg(target_scope.canonical_id ORDER BY target_scope.canonical_id), ARRAY[]::uuid[])
    INTO v_targeted_family_timesheet_ids, v_targeted_canonical_timesheet_ids
    FROM (
      SELECT DISTINCT
        COALESCE(scope_row.family_timesheet_id, scope_row.canonical_timesheet_id, scope_row.requested_timesheet_id) AS family_id,
        COALESCE(scope_row.canonical_timesheet_id, scope_row.family_timesheet_id, scope_row.requested_timesheet_id) AS canonical_id
      FROM public._pay_timesheet_rotation_scope(v_requested_targeted) AS scope_row
      WHERE COALESCE(scope_row.family_timesheet_id, scope_row.canonical_timesheet_id, scope_row.requested_timesheet_id) IS NOT NULL
    ) AS target_scope;
  END IF;

  IF COALESCE(array_length(v_targeted_family_timesheet_ids, 1), 0) = 0 THEN
    v_targeted_family_timesheet_ids := v_requested_targeted;
  END IF;

  IF COALESCE(array_length(v_targeted_canonical_timesheet_ids, 1), 0) = 0 THEN
    v_targeted_canonical_timesheet_ids := v_targeted_family_timesheet_ids;
  END IF;

  IF COALESCE(array_length(v_requested_linked, 1), 0) > 0 THEN
    SELECT
      COALESCE(array_agg(linked_scope.family_id ORDER BY linked_scope.family_id), ARRAY[]::uuid[]),
      COALESCE(array_agg(linked_scope.canonical_id ORDER BY linked_scope.canonical_id), ARRAY[]::uuid[])
    INTO v_linked_family_timesheet_ids, v_linked_canonical_timesheet_ids
    FROM (
      SELECT DISTINCT
        COALESCE(scope_row.family_timesheet_id, scope_row.canonical_timesheet_id, scope_row.requested_timesheet_id) AS family_id,
        COALESCE(scope_row.canonical_timesheet_id, scope_row.family_timesheet_id, scope_row.requested_timesheet_id) AS canonical_id
      FROM public._pay_timesheet_rotation_scope(v_requested_linked) AS scope_row
      WHERE COALESCE(scope_row.family_timesheet_id, scope_row.canonical_timesheet_id, scope_row.requested_timesheet_id) IS NOT NULL
    ) AS linked_scope;
  END IF;

  IF COALESCE(array_length(v_linked_family_timesheet_ids, 1), 0) = 0 THEN
    v_linked_family_timesheet_ids := v_requested_linked;
  END IF;

  IF COALESCE(array_length(v_linked_canonical_timesheet_ids, 1), 0) = 0 THEN
    v_linked_canonical_timesheet_ids := v_linked_family_timesheet_ids;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT linked_only.linked_id ORDER BY linked_only.linked_id), ARRAY[]::uuid[])
  INTO v_semantic_linked_timesheet_ids
  FROM unnest(COALESCE(v_linked_family_timesheet_ids, ARRAY[]::uuid[])) AS linked_only(linked_id)
  WHERE linked_only.linked_id IS NOT NULL
    AND NOT (linked_only.linked_id = ANY(COALESCE(v_targeted_family_timesheet_ids, ARRAY[]::uuid[])));

  SELECT COALESCE(array_agg(DISTINCT family_scope.family_id ORDER BY family_scope.family_id), ARRAY[]::uuid[])
  INTO v_family_timesheet_ids
  FROM (
    SELECT unnest(COALESCE(v_targeted_family_timesheet_ids, ARRAY[]::uuid[])) AS family_id
    UNION ALL
    SELECT unnest(COALESCE(v_linked_family_timesheet_ids, ARRAY[]::uuid[])) AS family_id
  ) AS family_scope
  WHERE family_scope.family_id IS NOT NULL;

  IF COALESCE(array_length(v_family_timesheet_ids, 1), 0) = 0 THEN
    v_family_timesheet_ids := v_requested_all;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT canonical_scope.canonical_id ORDER BY canonical_scope.canonical_id), ARRAY[]::uuid[])
  INTO v_canonical_timesheet_ids
  FROM (
    SELECT unnest(COALESCE(v_targeted_canonical_timesheet_ids, ARRAY[]::uuid[])) AS canonical_id
    UNION ALL
    SELECT unnest(COALESCE(v_linked_canonical_timesheet_ids, ARRAY[]::uuid[])) AS canonical_id
  ) AS canonical_scope
  WHERE canonical_scope.canonical_id IS NOT NULL;

  IF COALESCE(array_length(v_canonical_timesheet_ids, 1), 0) = 0 THEN
    v_canonical_timesheet_ids := v_family_timesheet_ids;
  END IF;

  RETURN jsonb_build_object(
    'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_family_timesheet_ids), '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(to_jsonb(v_semantic_linked_timesheet_ids), '[]'::jsonb),
    'family_timesheet_ids', COALESCE(to_jsonb(v_family_timesheet_ids), '[]'::jsonb),
    'canonical_timesheet_ids', COALESCE(to_jsonb(v_canonical_timesheet_ids), '[]'::jsonb),
    'targeted_family_timesheet_ids', COALESCE(to_jsonb(v_targeted_family_timesheet_ids), '[]'::jsonb),
    'linked_family_timesheet_ids', COALESCE(to_jsonb(v_linked_family_timesheet_ids), '[]'::jsonb),
    'queue_identity_targeted_timesheet_ids', COALESCE(to_jsonb(v_family_timesheet_ids), '[]'::jsonb),
    'queue_identity_linked_timesheet_ids', '[]'::jsonb,
    'queue_identity_timesheet_ids', COALESCE(to_jsonb(v_family_timesheet_ids), '[]'::jsonb),
    'requested_timesheet_ids', COALESCE(to_jsonb(v_requested_all), '[]'::jsonb),
    'requested_targeted_timesheet_ids', COALESCE(to_jsonb(v_requested_targeted), '[]'::jsonb),
    'requested_linked_timesheet_ids', COALESCE(to_jsonb(v_requested_linked), '[]'::jsonb),
    'rotation_family_resolved', true,
    'rotation_family_scope_for_queue_identity', true,
    'queue_identity_preserves_targeted_linked_semantics', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_authorise_delta_hotkey_preflight(p_session_id uuid, p_candidate_id uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_source_change_seq bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_family_scope jsonb := '{}'::jsonb;
  v_targeted_json jsonb := '[]'::jsonb;
  v_linked_json jsonb := '[]'::jsonb;
  v_queue_targeted_json jsonb := '[]'::jsonb;
  v_queue_linked_json jsonb := '[]'::jsonb;
  v_requested_json jsonb := '[]'::jsonb;
  v_family_key text := NULL::text;
  v_delta_hash text := NULL::text;
  v_latest_seq bigint := 0;
  v_payload_seq bigint := 0;
  v_live_seq bigint := 0;
  v_existing_queued public.banking_pay_workbench_jobs%ROWTYPE;
  v_running public.banking_pay_workbench_jobs%ROWTYPE;
  v_existing_seq bigint := 0;
  v_existing_event_count integer := 0;
  v_new_event_count integer := 1;
  v_new_projection_run_id uuid := gen_random_uuid();
  v_dedupe_key text := NULL::text;
  v_payload_new jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_job_status text := NULL::text;
  v_inserted boolean := false;
  v_insert_count integer := 0;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), NULLIF(BTRIM(COALESCE(v_payload->>'reason_latest', v_payload->>'reason', '')), ''), 'AUTHORISE_UNAUTHORISE_DELTA_PREFLIGHT');
  v_lifecycle_context text := LOWER(BTRIM(COALESCE(v_payload->>'lifecycle_mutation_context', v_payload->>'mutation_context', v_payload->>'lifecycle_context', '')));
  v_is_authorise_boundary boolean := false;
  v_is_archive_boundary boolean := false;
  v_is_lifecycle_boundary boolean := false;
  v_is_ordinary_save_no_dirty boolean := false;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'SESSION_OR_CANDIDATE_REQUIRED');
  END IF;

  v_is_authorise_boundary :=
    lower(BTRIM(COALESCE(v_payload->>'authorise_boundary_changed', v_payload->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR lower(BTRIM(COALESCE(v_payload->>'unauthorise_boundary_changed', v_payload->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR v_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
    OR LOWER(COALESCE(v_reason, '')) LIKE '%authorise%'
    OR LOWER(COALESCE(v_reason, '')) LIKE '%unauthorise%';

  v_is_archive_boundary :=
    lower(BTRIM(COALESCE(v_payload->>'archive_boundary_changed', v_payload->>'timesheet_archive_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR lower(BTRIM(COALESCE(v_payload->>'unarchive_boundary_changed', v_payload->>'timesheet_unarchive_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR v_lifecycle_context IN ('timesheet_archive', 'archive_timesheet', 'timesheet_unarchive', 'unarchive_timesheet')
    OR LOWER(COALESCE(v_reason, '')) LIKE '%archive%'
    OR LOWER(COALESCE(v_reason, '')) LIKE '%unarchive%';

  v_is_lifecycle_boundary := COALESCE(v_is_authorise_boundary, false) OR COALESCE(v_is_archive_boundary, false);
  v_is_ordinary_save_no_dirty := lower(BTRIM(COALESCE(v_payload->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) IN ('true','t','1','yes','y','on');

  IF v_is_lifecycle_boundary IS TRUE THEN
    -- Lifecycle transitions must reach the normal dirty/classifier path so
    -- retained settled history is rebuilt into finance-case authority.  A
    -- delta hotkey can legitimately produce zero current rows and would skip
    -- that reconciliation entirely.
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'PROCEED',
      'match_found', false,
      'reason', 'TIMESHEET_LIFECYCLE_REQUIRES_SOURCE_BUILD',
      'authorise_boundary_changed', COALESCE(v_is_authorise_boundary, false),
      'archive_boundary_changed', COALESCE(v_is_archive_boundary, false),
      'source_build_required', true,
      'classifier_work_skipped', false,
      'dirty_marking_skipped', false,
      'session_progress_dirtying_skipped', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  IF v_is_ordinary_save_no_dirty IS TRUE
     OR COALESCE(array_length(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[]), 1), 0) = 0 THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'NOT_TARGETED_AUTHORISE_UNAUTHORISE_DELTA');
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND session_row.status = 'OPEN'
    AND session_row.discarded_at_utc IS NULL;

  IF v_session_row.id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'NO_OPEN_WORKBENCH_SESSION');
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_payload_seq := GREATEST(
    COALESCE(p_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_payload->>'source_change_sequence')::bigint END, 0)
  );
  v_latest_seq := GREATEST(COALESCE(v_payload_seq, 0), COALESCE(v_live_seq, 0));

  v_family_scope := public._pay_workbench_normalise_timesheet_rotation_scope_payload(
    COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[]),
    COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])
  );
  v_targeted_json := COALESCE(v_family_scope->'targeted_timesheet_ids', '[]'::jsonb);
  v_linked_json := COALESCE(v_family_scope->'linked_timesheet_ids', '[]'::jsonb);
  v_queue_targeted_json := COALESCE(v_family_scope->'queue_identity_targeted_timesheet_ids', v_family_scope->'family_timesheet_ids', v_targeted_json, '[]'::jsonb);
  v_queue_linked_json := COALESCE(v_family_scope->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  v_requested_json := COALESCE(v_family_scope->'requested_timesheet_ids', v_targeted_json);

  v_delta_hash := md5(COALESCE(v_queue_targeted_json, '[]'::jsonb)::text || ':' || COALESCE(v_queue_linked_json, '[]'::jsonb)::text);
  v_family_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || p_session_id::text
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:DELTA'
    || ':projection_class:NORMAL_TIMESHEET'
    || ':refresh_scope:TARGETED_TIMESHEETS'
    || ':candidate:' || p_candidate_id::text
    || ':timesheets:' || v_delta_hash;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_key, 24062026));

  SELECT queued_job.*
  INTO v_existing_queued
  FROM public.banking_pay_workbench_jobs AS queued_job
  WHERE queued_job.session_id = p_session_id
    AND queued_job.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(queued_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
    AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
    AND (
      queued_job.dedupe_key = v_family_key
      OR queued_job.dedupe_key LIKE v_family_key || ':waiting_after_running:%'
      OR COALESCE(queued_job.payload_json->>'normalised_delta_family_key', queued_job.payload_json->>'delta_family_key', queued_job.payload_json->>'delta_coalescing_key', '') = v_family_key
    )
  ORDER BY CASE WHEN queued_job.dedupe_key = v_family_key THEN 0 ELSE 1 END,
           queued_job.run_at_utc ASC,
           queued_job.created_at_utc ASC,
           queued_job.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_queued.id IS NOT NULL THEN
    v_existing_seq := GREATEST(
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'latest_source_change_seq', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'latest_source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'source_change_sequence')::bigint END, 0)
    );
    v_existing_event_count := CASE WHEN COALESCE(v_existing_queued.payload_json->>'coalesced_event_count', '') ~ '^\d{1,9}$' THEN GREATEST((v_existing_queued.payload_json->>'coalesced_event_count')::integer, 1) ELSE 1 END;
    v_new_event_count := v_existing_event_count + 1;
    v_latest_seq := GREATEST(v_latest_seq, v_existing_seq);
    v_dedupe_key := CASE WHEN v_existing_queued.dedupe_key LIKE v_family_key || ':waiting_after_running:%' THEN v_existing_queued.dedupe_key ELSE v_family_key END;

    v_payload_new := jsonb_strip_nulls(
      (
        public._pay_workbench_merge_targeted_scope_payload(COALESCE(v_existing_queued.payload_json, '{}'::jsonb), COALESCE(v_payload, '{}'::jsonb))
        - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
        - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
        - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
        - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present'
        - 'old_row_json' - 'new_row_json' - 'source_row_json' - 'work_payload_json' - 'result_row_json'
        - 'preview_row_json' - 'projection_rows' - 'projected_rows'
      )
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'phase', 'INIT_PREFLIGHT',
        'run_mode', 'LATEST_STATE_HEAD',
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'projection_run_id', v_new_projection_run_id::text,
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'workbench_session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope->'requested_targeted_timesheet_ids', v_requested_json),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope->'requested_linked_timesheet_ids', '[]'::jsonb),
        'source_change_seq', v_latest_seq,
        'source_change_sequence', v_latest_seq,
        'latest_source_change_seq', v_latest_seq,
        'delta_coalescing_key', v_family_key,
        'delta_family_key', v_family_key,
        'normalised_delta_family_key', v_family_key,
        'delta_coalescing_hash', md5(v_family_key),
        'coalesced_event_count', v_new_event_count,
        'coalesced_source_change_seqs', jsonb_build_array(v_existing_seq, v_latest_seq),
        'latest_event_at_utc', v_now::text,
        'reason', v_reason,
        'early_preflight_action', 'REUSED_QUEUED_SAME_FAMILY_JOB',
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped_by_dirty_apply_preflight', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    UPDATE public.banking_pay_workbench_jobs AS job_update
    SET dedupe_key = v_dedupe_key,
        priority = LEAST(job_update.priority, 43),
        run_at_utc = LEAST(job_update.run_at_utc, v_now),
        payload_json = v_payload_new,
        updated_at_utc = v_now,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL::jsonb
    WHERE job_update.id = v_existing_queued.id
    RETURNING job_update.id, job_update.status
    INTO v_job_id, v_job_status;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_job_id::text,
      'EARLY_PREFLIGHT_REUSED_QUEUED_SAME_FAMILY_JOB',
      NULL::jsonb,
      jsonb_build_object(
        'id', v_job_id::text,
        'session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'normalised_delta_family_key', v_family_key,
        'existing_job_id', v_existing_queued.id::text,
        'latest_source_change_seq', v_latest_seq,
        'previous_job_source_change_seq', v_existing_seq,
        'coalesced_event_count', v_new_event_count,
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped', true,
        'trigger_reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      'EARLY_PREFLIGHT_REUSED_QUEUED_SAME_FAMILY_JOB',
      COALESCE(p_actor_user_id, v_session_row.actor_user_id)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'REUSED_QUEUED_SAME_FAMILY_JOB',
      'match_found', true,
      'job_id', v_job_id::text,
      'status', v_job_status,
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'coalesced_event_count', v_new_event_count,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped', true,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'dirty_apply_can_complete_cleanly', true
    );
  END IF;

  SELECT running_job.*
  INTO v_running
  FROM public.banking_pay_workbench_jobs AS running_job
  WHERE running_job.session_id = p_session_id
    AND running_job.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(running_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
    AND UPPER(BTRIM(COALESCE(running_job.status, ''))) = 'RUNNING'
    AND (
      running_job.dedupe_key = v_family_key
      OR COALESCE(running_job.payload_json->>'normalised_delta_family_key', running_job.payload_json->>'delta_family_key', running_job.payload_json->>'delta_coalescing_key', '') = v_family_key
    )
  ORDER BY running_job.started_at_utc ASC NULLS LAST, running_job.created_at_utc ASC, running_job.id ASC
  LIMIT 1;

  IF v_running.id IS NOT NULL THEN
    v_dedupe_key := v_family_key || ':waiting_after_running:' || v_running.id::text;
    v_payload_new := jsonb_strip_nulls(
      (COALESCE(v_payload, '{}'::jsonb)
        - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
        - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
        - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
        - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present'
        - 'old_row_json' - 'new_row_json' - 'source_row_json' - 'work_payload_json' - 'result_row_json'
        - 'preview_row_json' - 'projection_rows' - 'projected_rows')
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'phase', 'INIT_PREFLIGHT',
        'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'projection_run_id', v_new_projection_run_id::text,
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'workbench_session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope->'requested_targeted_timesheet_ids', v_requested_json),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope->'requested_linked_timesheet_ids', '[]'::jsonb),
        'source_change_seq', v_latest_seq,
        'source_change_sequence', v_latest_seq,
        'latest_source_change_seq', v_latest_seq,
        'delta_coalescing_key', v_family_key,
        'delta_family_key', v_family_key,
        'normalised_delta_family_key', v_family_key,
        'delta_coalescing_hash', md5(v_family_key),
        'dedupe_key', v_dedupe_key,
        'delta_active_running_job_id', v_running.id::text,
        'waiting_after_running_delta_job', true,
        'coalesced_event_count', 1,
        'coalesced_source_change_seqs', jsonb_build_array(v_latest_seq),
        'latest_event_at_utc', v_now::text,
        'reason', v_reason,
        'early_preflight_action', 'UPDATED_WAITING_AFTER_RUNNING_JOB',
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped_by_dirty_apply_preflight', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    INSERT INTO public.banking_pay_workbench_jobs AS waiting_job (
      job_type, status, priority, run_at_utc, attempt_count, max_attempts, dedupe_key,
      snapshot_run_id, session_id, candidate_id, payload_json,
      created_at_utc, updated_at_utc, started_at_utc, completed_at_utc, failed_at_utc, last_error_json
    )
    VALUES (
      'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'QUEUED', 43, v_now, 0, 8, v_dedupe_key,
      v_session_row.source_snapshot_run_id, p_session_id, p_candidate_id, v_payload_new,
      v_now, v_now, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::jsonb
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(waiting_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(waiting_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = jsonb_strip_nulls(
          (public._pay_workbench_merge_targeted_scope_payload(COALESCE(waiting_job.payload_json, '{}'::jsonb), EXCLUDED.payload_json)
            - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
            - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
            - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
            - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present')
          || jsonb_build_object(
            'cursor_json', '{}'::jsonb,
            'continuation', false,
            'projection_run_id', v_new_projection_run_id::text,
            'phase', 'INIT_PREFLIGHT',
            'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
            'latest_source_change_seq', v_latest_seq,
            'source_change_seq', v_latest_seq,
            'source_change_sequence', v_latest_seq,
            'normalised_delta_family_key', v_family_key,
            'delta_family_key', v_family_key,
            'delta_coalescing_key', v_family_key,
            'coalesced_event_count', CASE WHEN COALESCE(waiting_job.payload_json->>'coalesced_event_count', '') ~ '^\d{1,9}$' THEN (waiting_job.payload_json->>'coalesced_event_count')::integer + 1 ELSE 2 END,
            'latest_event_at_utc', v_now::text,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true
          )
        ),
        updated_at_utc = v_now,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL::jsonb
    WHERE UPPER(BTRIM(COALESCE(waiting_job.status, ''))) = 'QUEUED'
    RETURNING waiting_job.id, waiting_job.status, (xmax = 0)
    INTO v_job_id, v_job_status, v_inserted;

    GET DIAGNOSTICS v_insert_count = ROW_COUNT;

    IF COALESCE(v_insert_count, 0) = 0 THEN
      SELECT queued_job.id, queued_job.status
      INTO v_job_id, v_job_status
      FROM public.banking_pay_workbench_jobs AS queued_job
      WHERE queued_job.dedupe_key = v_dedupe_key
        AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
      LIMIT 1;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      COALESCE(v_job_id::text, v_running.id::text),
      'EARLY_PREFLIGHT_UPDATED_WAITING_AFTER_RUNNING_JOB',
      NULL::jsonb,
      jsonb_build_object(
        'id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
        'running_job_id', v_running.id::text,
        'session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'normalised_delta_family_key', v_family_key,
        'latest_source_change_seq', v_latest_seq,
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped', true,
        'trigger_reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      'EARLY_PREFLIGHT_UPDATED_WAITING_AFTER_RUNNING_JOB',
      COALESCE(p_actor_user_id, v_session_row.actor_user_id)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'UPDATED_WAITING_AFTER_RUNNING_JOB',
      'match_found', true,
      'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
      'running_job_id', v_running.id::text,
      'status', COALESCE(v_job_status, 'QUEUED'),
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped', true,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'dirty_apply_can_complete_cleanly', true
    );
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_session_id::text || ':' || p_candidate_id::text,
    'EARLY_PREFLIGHT_NO_MATCH_PROCEED',
    NULL::jsonb,
    jsonb_build_object(
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'candidate_id', p_candidate_id::text,
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'dirty_marking_skipped', false,
      'session_progress_dirtying_skipped', false,
      'trigger_reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    'EARLY_PREFLIGHT_NO_MATCH_PROCEED',
    COALESCE(p_actor_user_id, v_session_row.actor_user_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'PROCEED',
    'match_found', false,
    'candidate_id', p_candidate_id::text,
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'targeted_timesheet_ids', v_targeted_json,
    'linked_timesheet_ids', v_linked_json,
    'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
    'normalised_delta_family_key', v_family_key,
    'latest_source_change_seq', v_latest_seq
  );
END;
$function$;






CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_audit(p_action text, p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_after_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text := COALESCE(NULLIF(BTRIM(p_action), ''), 'CANDIDATE_SERIAL_EVENT');
  v_candidate_id uuid := p_candidate_id;
  v_after jsonb := CASE WHEN jsonb_typeof(COALESCE(p_after_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_after_json, '{}'::jsonb) ELSE '{}'::jsonb END;
BEGIN
  IF v_candidate_id IS NULL THEN
    v_candidate_id := public._pay_workbench_candidate_serial_candidate_id(NULL::uuid, v_after);
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    COALESCE(p_job_id::text, CASE WHEN v_candidate_id IS NULL THEN NULL ELSE 'candidate:' || v_candidate_id::text END),
    v_action,
    NULL::jsonb,
    jsonb_strip_nulls(
      jsonb_build_object(
        'job_id', CASE WHEN p_job_id IS NULL THEN NULL ELSE p_job_id::text END,
        'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_candidate_id)
      ) || v_after
    ),
    COALESCE(NULLIF(BTRIM(p_reason), ''), v_action),
    p_actor_user_id
  );
EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_active_state(p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, clock_timestamp());
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
  v_serial_key text := public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json));
  v_candidate_job boolean := false;
  v_is_chain_continuation boolean := false;
  v_projection_run_id_text text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_active_job_id uuid := NULL::uuid;
  v_active_job_type text := NULL::text;
  v_active_job_status text := NULL::text;
  v_active_job_started_at_utc timestamptz := NULL::timestamptz;
  v_active_job_run_at_utc timestamptz := NULL::timestamptz;
  v_active_chain_id text := NULL::text;
  v_queued_chain_job_id uuid := NULL::uuid;
  v_queued_chain_job_type text := NULL::text;
  v_queued_chain_job_status text := NULL::text;
  v_queued_chain_started_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_run_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_id text := NULL::text;
  v_projection_blocker_id uuid := NULL::uuid;
  v_projection_blocker_status text := NULL::text;
  v_projection_blocker_started_at_utc timestamptz := NULL::timestamptz;
  v_projection_blocker_updated_at_utc timestamptz := NULL::timestamptz;
  v_blocked boolean := false;
  v_reason text := NULL::text;
BEGIN
  v_candidate_job := public._pay_workbench_candidate_serial_is_candidate_job(p_job_type, v_candidate_id, v_payload);

  IF v_candidate_id IS NULL OR v_candidate_job IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'blocked', false,
      'candidate_serial_blocked', false,
      'reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_serial_wait_reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'candidate_serial_key', v_serial_key
    );
  END IF;

  v_is_chain_continuation := (
    lower(BTRIM(COALESCE(v_payload->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
    OR lower(BTRIM(COALESCE(v_payload->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      lower(BTRIM(COALESCE(v_payload->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NULLIF(BTRIM(COALESCE(v_payload->>'fallback_reason', '')), '') IS NOT NULL
    )
    OR (
      NULLIF(BTRIM(COALESCE(v_payload->>'source_job_id', v_payload->>'continuation_source_job_id', v_payload->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
      AND UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
    )
  );

  v_projection_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,cursor,projection_run_id}', '')), '')
  );
  IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_projection_run_id := v_projection_run_id_text::uuid;
  END IF;

  SELECT running_job.id,
         running_job.job_type,
         running_job.status,
         running_job.started_at_utc,
         running_job.run_at_utc,
         COALESCE(NULLIF(BTRIM(COALESCE(running_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(running_job.payload_json->>'source_job_id', '')), ''), running_job.id::text)
  INTO v_active_job_id, v_active_job_type, v_active_job_status, v_active_job_started_at_utc, v_active_job_run_at_utc, v_active_chain_id
  FROM public.banking_pay_workbench_jobs AS running_job
  WHERE UPPER(BTRIM(COALESCE(running_job.status, ''))) = 'RUNNING'
    AND running_job.id IS DISTINCT FROM p_job_id
    AND public._pay_workbench_candidate_serial_candidate_id(running_job.candidate_id, running_job.payload_json) = v_candidate_id
    AND public._pay_workbench_candidate_serial_is_candidate_job(running_job.job_type, running_job.candidate_id, running_job.payload_json)
  ORDER BY running_job.started_at_utc ASC NULLS FIRST, running_job.created_at_utc ASC, running_job.id ASC
  LIMIT 1;

  IF v_active_job_id IS NOT NULL THEN
    v_blocked := true;
    v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_JOB';
  END IF;

  IF v_blocked IS NOT TRUE AND v_is_chain_continuation IS NOT TRUE THEN
    SELECT queued_job.id,
           queued_job.job_type,
           queued_job.status,
           queued_job.started_at_utc,
           queued_job.run_at_utc,
           COALESCE(NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', '')), ''), queued_job.id::text)
    INTO v_queued_chain_job_id, v_queued_chain_job_type, v_queued_chain_job_status, v_queued_chain_started_at_utc, v_queued_chain_run_at_utc, v_queued_chain_id
    FROM public.banking_pay_workbench_jobs AS queued_job
    WHERE UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
      AND queued_job.id IS DISTINCT FROM p_job_id
      AND public._pay_workbench_candidate_serial_candidate_id(queued_job.candidate_id, queued_job.payload_json) = v_candidate_id
      AND public._pay_workbench_candidate_serial_is_candidate_job(queued_job.job_type, queued_job.candidate_id, queued_job.payload_json)
      AND (
        lower(BTRIM(COALESCE(queued_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR UPPER(BTRIM(COALESCE(queued_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
        OR lower(BTRIM(COALESCE(queued_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR (
          lower(BTRIM(COALESCE(queued_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
        )
        OR NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', queued_job.payload_json->>'continuation_source_job_id', queued_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
      )
    ORDER BY queued_job.run_at_utc ASC, queued_job.priority ASC, queued_job.created_at_utc ASC, queued_job.id ASC
    LIMIT 1;

    IF v_queued_chain_job_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_CONTINUATION';
    END IF;
  END IF;

  IF v_blocked IS NOT TRUE THEN
    SELECT projection_run.id, projection_run.status, projection_run.started_at_utc, projection_run.updated_at_utc
    INTO v_projection_blocker_id, v_projection_blocker_status, v_projection_blocker_started_at_utc, v_projection_blocker_updated_at_utc
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.candidate_id = v_candidate_id
      AND UPPER(BTRIM(COALESCE(projection_run.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
      AND (v_projection_run_id IS NULL OR projection_run.id IS DISTINCT FROM v_projection_run_id)
    ORDER BY projection_run.started_at_utc ASC NULLS FIRST, projection_run.updated_at_utc ASC NULLS FIRST, projection_run.id ASC
    LIMIT 1;

    IF v_projection_blocker_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_PROJECTION_RUN';
    END IF;
  END IF;

  IF v_blocked IS TRUE THEN
    PERFORM public._pay_workbench_candidate_serial_audit(
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      p_job_id,
      v_candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'candidate_serial_key', v_serial_key,
        'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
        'blocked_job_type', v_active_job_type,
        'blocked_job_status', v_active_job_status,
        'blocked_job_started_at_utc', v_active_job_started_at_utc,
        'blocked_job_run_at_utc', v_active_job_run_at_utc,
        'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
        'blocked_chain_job_type', v_queued_chain_job_type,
        'blocked_chain_job_status', v_queued_chain_job_status,
        'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
        'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
        'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
        'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
        'projection_status', v_projection_blocker_status,
        'projection_started_at_utc', v_projection_blocker_started_at_utc,
        'projection_updated_at_utc', v_projection_blocker_updated_at_utc,
        'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED')
      )),
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      NULL::uuid
    );
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'blocked', COALESCE(v_blocked, false),
    'candidate_serial_blocked', COALESCE(v_blocked, false),
    'reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_id', v_candidate_id::text,
    'candidate_serial_key', v_serial_key,
    'is_chain_continuation', COALESCE(v_is_chain_continuation, false),
    'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocking_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocked_job_type', v_active_job_type,
    'blocked_job_status', v_active_job_status,
    'blocking_status', COALESCE(v_active_job_status, v_queued_chain_job_status, v_projection_blocker_status),
    'blocked_job_started_at_utc', v_active_job_started_at_utc,
    'blocked_job_run_at_utc', v_active_job_run_at_utc,
    'blocking_started_at_utc', COALESCE(v_active_job_started_at_utc, v_queued_chain_started_at_utc, v_projection_blocker_started_at_utc),
    'blocking_run_at_utc', COALESCE(v_active_job_run_at_utc, v_queued_chain_run_at_utc, v_projection_blocker_updated_at_utc),
    'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
    'blocked_chain_job_type', v_queued_chain_job_type,
    'blocked_chain_job_status', v_queued_chain_job_status,
    'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
    'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
    'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
    'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'blocking_projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'projection_status', v_projection_blocker_status,
    'projection_started_at_utc', v_projection_blocker_started_at_utc,
    'projection_updated_at_utc', v_projection_blocker_updated_at_utc
  ));
END;
$function$;



CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_try_gate(p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
  v_serial_key text := public._pay_workbench_candidate_serial_key(v_candidate_id);
  v_required boolean := false;
  v_locked boolean := false;
  v_state jsonb := '{}'::jsonb;
  v_blocked boolean := false;
  v_reason text := NULL::text;
  v_result jsonb := '{}'::jsonb;
BEGIN
  v_required := public._pay_workbench_candidate_serial_is_candidate_job(p_job_type, v_candidate_id, v_payload);

  IF v_candidate_id IS NULL OR v_serial_key IS NULL OR v_required IS NOT TRUE THEN
    v_state := public._pay_workbench_candidate_serial_active_state(p_job_id, v_candidate_id, p_job_type, v_payload, NULL::timestamptz);
    RETURN COALESCE(v_state, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'ok', true, 'allowed', true, 'blocked', false, 'candidate_serial_blocked', false,
      'reason', COALESCE(v_state->>'reason', 'NO_CANDIDATE_SERIAL_SCOPE'),
      'candidate_serial_wait_reason', COALESCE(v_state->>'candidate_serial_wait_reason', v_state->>'reason', 'NO_CANDIDATE_SERIAL_SCOPE'),
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'candidate_serial_key', v_serial_key,
      'candidate_serial_gate_reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'candidate_serial_gate_decision', 'BYPASSED',
      'advisory_lock_attempted', false
    ));
  END IF;

  v_locked := COALESCE(pg_try_advisory_xact_lock(hashtextextended(v_serial_key, 24062027)), false);
  v_state := public._pay_workbench_candidate_serial_active_state(p_job_id, v_candidate_id, p_job_type, v_payload, NULL::timestamptz);
  v_blocked := v_locked IS NOT TRUE
    OR lower(BTRIM(COALESCE(v_state->>'blocked', v_state->>'candidate_serial_blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := CASE
    WHEN v_locked IS NOT TRUE THEN 'CANDIDATE_SERIAL_BLOCKED_BY_ADVISORY_LOCK'
    ELSE COALESCE(NULLIF(BTRIM(COALESCE(v_state->>'reason', '')), ''), CASE WHEN v_blocked THEN 'CANDIDATE_SERIAL_BLOCKED' ELSE 'CANDIDATE_SERIAL_CLEAR' END)
  END;

  v_result := COALESCE(v_state, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'ok', true, 'allowed', NOT COALESCE(v_blocked, false), 'blocked', COALESCE(v_blocked, false),
    'candidate_serial_blocked', COALESCE(v_blocked, false), 'reason', v_reason,
    'candidate_serial_wait_reason', v_reason, 'candidate_id', v_candidate_id::text,
    'candidate_serial_key', v_serial_key,
    'candidate_serial_gate_reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
    'candidate_serial_gate_decision', CASE WHEN v_blocked THEN 'BLOCKED' ELSE 'GRANTED' END,
    'advisory_lock_attempted', true, 'advisory_lock_granted', COALESCE(v_locked, false)
  ));

  PERFORM public._pay_workbench_candidate_serial_audit(
    CASE WHEN v_blocked THEN 'CANDIDATE_SERIAL_GATE_BLOCKED' ELSE 'CANDIDATE_SERIAL_GATE_GRANTED' END,
    p_job_id, v_candidate_id, v_result || jsonb_build_object('job_type', p_job_type),
    COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), v_reason), NULL::uuid
  );
  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public._pay_workbench_candidate_serial_try_gate(uuid, uuid, text, jsonb, text) FROM PUBLIC, anon, authenticated, service_role;


CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_is_candidate_job(p_job_type text, p_candidate_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
BEGIN
  IF v_candidate_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_job_type IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN
    RETURN false;
  END IF;

  IF v_job_type IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RETURN true;
  END IF;

  IF v_job_type LIKE E'WORKBENCH_CANDIDATE\\_%' ESCAPE E'\\' THEN
    RETURN true;
  END IF;

  IF v_job_type LIKE E'WORKBENCH\\_%' ESCAPE E'\\'
     AND (
       COALESCE(p_payload_json, '{}'::jsonb) ? 'candidate_id'
       OR COALESCE(p_payload_json, '{}'::jsonb) ? 'candidateId'
       OR COALESCE(p_payload_json, '{}'::jsonb) ? 'candidate_uuid'
       OR COALESCE(p_payload_json, '{}'::jsonb)#>>'{candidate,id}' IS NOT NULL
     ) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$function$;
CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_key(p_candidate_id uuid)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_candidate_id IS NULL THEN NULL::text
    ELSE 'WORKBENCH_CANDIDATE_SERIAL:candidate:' || p_candidate_id::text
  END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_candidate_id(p_candidate_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate_id uuid := NULL::uuid;
  v_candidate_count integer := 0;
BEGIN
  IF p_candidate_id IS NOT NULL THEN
    RETURN p_candidate_id;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public._pay_workbench_candidate_serial_candidate_ids(p_candidate_id, p_payload_json) AS candidate_ids(candidate_id);

  IF COALESCE(v_candidate_count, 0) = 1 THEN
    SELECT candidate_ids.candidate_id
    INTO v_candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(p_candidate_id, p_payload_json) AS candidate_ids(candidate_id)
    LIMIT 1;

    RETURN v_candidate_id;
  END IF;

  RETURN NULL::uuid;
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_workbench_delta_projection_terminalise_if_orphaned(p_projection_run_id uuid, p_session_id uuid, p_candidate_id uuid, p_superseded_job_id uuid, p_payload_source_change_seq bigint DEFAULT 0, p_cursor_source_change_seq bigint DEFAULT 0, p_projection_run_source_change_seq bigint DEFAULT 0, p_live_candidate_source_change_seq bigint DEFAULT 0, p_reason text DEFAULT 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM'::text, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_reason text := COALESCE(NULLIF(BTRIM(p_reason), ''), 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM');
  v_run public.banking_pay_workbench_candidate_delta_projection_runs%ROWTYPE;
  v_status_before text := NULL::text;
  v_status_after text := NULL::text;
  v_effective_projection_source_change_seq bigint := 0;
  v_effective_latest_source_seq bigint := 0;
  v_active_job_id uuid := NULL::uuid;
  v_active_job_type text := NULL::text;
  v_active_job_status text := NULL::text;
  v_skip_reason text := NULL::text;
BEGIN
  IF p_projection_run_id IS NULL
     OR p_session_id IS NULL
     OR p_candidate_id IS NULL
     OR p_superseded_job_id IS NULL THEN
    v_skip_reason := 'MISSING_REQUIRED_SCOPE';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', CASE WHEN p_projection_run_id IS NULL THEN NULL ELSE p_projection_run_id::text END,
      'projection_run_terminalised', false,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  SELECT projection_run.*
  INTO v_run
  FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
  WHERE projection_run.id = p_projection_run_id
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    v_skip_reason := 'PROJECTION_RUN_LOCKED_OR_NOT_FOUND';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  v_status_before := v_run.status;
  v_effective_projection_source_change_seq := GREATEST(COALESCE(p_projection_run_source_change_seq, 0), COALESCE(v_run.source_change_seq, 0));
  v_effective_latest_source_seq := GREATEST(COALESCE(p_payload_source_change_seq, 0), COALESCE(p_live_candidate_source_change_seq, 0));

  IF v_run.session_id IS DISTINCT FROM p_session_id
     OR v_run.candidate_id IS DISTINCT FROM p_candidate_id THEN
    v_skip_reason := 'PROJECTION_SCOPE_MISMATCH';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_status_before', v_status_before,
      'projection_run_status_after', v_status_before,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'projection_run_session_id', v_run.session_id::text,
      'projection_run_candidate_id', v_run.candidate_id::text,
      'job_session_id', p_session_id::text,
      'job_candidate_id', p_candidate_id::text,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  IF UPPER(BTRIM(COALESCE(v_run.status, ''))) NOT IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS') THEN
    v_skip_reason := 'PROJECTION_RUN_ALREADY_TERMINAL';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_status_before', v_status_before,
      'projection_run_status_after', v_status_before,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  IF NOT (
    (COALESCE(v_effective_projection_source_change_seq, 0) > 0 AND COALESCE(v_effective_latest_source_seq, 0) > COALESCE(v_effective_projection_source_change_seq, 0))
    OR (COALESCE(p_cursor_source_change_seq, 0) > 0 AND COALESCE(v_effective_latest_source_seq, 0) > COALESCE(p_cursor_source_change_seq, 0))
  ) THEN
    v_skip_reason := 'NOT_STALE_AGAINST_LIVE_SOURCE_SEQ';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_status_before', v_status_before,
      'projection_run_status_after', v_status_before,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'payload_source_change_seq', p_payload_source_change_seq,
      'cursor_source_change_seq', p_cursor_source_change_seq,
      'projection_run_source_change_seq', v_effective_projection_source_change_seq,
      'live_candidate_source_change_seq', p_live_candidate_source_change_seq,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  SELECT active_projection_job.id,
         active_projection_job.job_type,
         active_projection_job.status
  INTO v_active_job_id,
       v_active_job_type,
       v_active_job_status
  FROM public.banking_pay_workbench_jobs AS active_projection_job
  WHERE active_projection_job.id IS DISTINCT FROM p_superseded_job_id
    AND UPPER(BTRIM(COALESCE(active_projection_job.status, ''))) IN ('QUEUED', 'RUNNING')
    AND (
      COALESCE(active_projection_job.payload_json->>'projection_run_id', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{cursor,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{cursor,cursor,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{cursor_json,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{cursor_json,cursor,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{result_json,next_cursor,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{result_json,next_cursor,cursor,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{result_json,next_cursor_json,projection_run_id}', '') = p_projection_run_id::text
      OR COALESCE(active_projection_job.payload_json#>>'{result_json,next_cursor_json,cursor,projection_run_id}', '') = p_projection_run_id::text
    )
  ORDER BY CASE WHEN UPPER(BTRIM(COALESCE(active_projection_job.status, ''))) = 'RUNNING' THEN 0 ELSE 1 END,
           active_projection_job.run_at_utc ASC,
           active_projection_job.created_at_utc ASC,
           active_projection_job.id ASC
  LIMIT 1;

  IF v_active_job_id IS NOT NULL THEN
    v_skip_reason := 'ACTIVE_JOB_CAN_COMPLETE_PROJECTION';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_status_before', v_status_before,
      'projection_run_status_after', v_status_before,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'active_continuation_job_exists', true,
      'active_continuation_job_id', v_active_job_id::text,
      'active_continuation_job_type', v_active_job_type,
      'active_continuation_job_status', v_active_job_status,
      'no_active_continuation_job', false,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
  SET status = 'FAILED',
      fallback_required = false,
      fallback_reason = 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
      completed_at_utc = v_now,
      updated_at_utc = v_now,
      diagnostics_json = jsonb_strip_nulls(
        COALESCE(projection_run.diagnostics_json, '{}'::jsonb)
        || jsonb_build_object(
          'stale_continuation_superseded_before_claim', true,
          'terminalised_by', 'pay_workbench_claim_due_jobs',
          'terminalised_reason', v_reason,
          'terminalised_at_utc', v_now::text,
          'superseded_continuation_job_id', p_superseded_job_id::text,
          'payload_source_change_seq', p_payload_source_change_seq,
          'cursor_source_change_seq', p_cursor_source_change_seq,
          'projection_run_source_change_seq', v_effective_projection_source_change_seq,
          'live_candidate_source_change_seq', p_live_candidate_source_change_seq,
          'newer_source_change_seq', v_effective_latest_source_seq,
          'superseded_by_newer_source_change_seq', true,
          'projection_status_before', v_status_before,
          'projection_status_after', 'FAILED',
          'no_active_continuation_job', true,
          'candidate_serial_unblocked', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      )
  WHERE projection_run.id = p_projection_run_id
    AND projection_run.session_id = p_session_id
    AND projection_run.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(projection_run.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
  RETURNING projection_run.status
  INTO v_status_after;

  IF NOT FOUND THEN
    v_skip_reason := 'PROJECTION_RUN_STATUS_CHANGED_BEFORE_TERMINALISE';
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'projection_run_id', p_projection_run_id::text,
      'projection_run_terminalised', false,
      'projection_run_status_before', v_status_before,
      'projection_run_status_after', v_status_before,
      'projection_run_terminalised_reason', v_reason,
      'skip_reason', v_skip_reason,
      'no_active_continuation_job', true,
      'superseded_continuation_job_id', p_superseded_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  BEGIN
    PERFORM public._audit_insert(
      'banking_pay_workbench_candidate_delta_projection_run',
      p_projection_run_id::text,
      'STALE_CONTINUATION_PROJECTION_RUN_TERMINALISED_BEFORE_CLAIM',
      jsonb_strip_nulls(jsonb_build_object(
        'projection_run_id', p_projection_run_id::text,
        'status', v_status_before,
        'source_change_seq', v_effective_projection_source_change_seq
      )),
      jsonb_strip_nulls(jsonb_build_object(
        'projection_run_id', p_projection_run_id::text,
        'projection_run_terminalised', true,
        'projection_run_status_before', v_status_before,
        'projection_run_status_after', COALESCE(v_status_after, 'FAILED'),
        'projection_run_terminalised_reason', v_reason,
        'terminalised_by', 'pay_workbench_claim_due_jobs',
        'superseded_continuation_job_id', p_superseded_job_id::text,
        'payload_source_change_seq', p_payload_source_change_seq,
        'cursor_source_change_seq', p_cursor_source_change_seq,
        'projection_run_source_change_seq', v_effective_projection_source_change_seq,
        'live_candidate_source_change_seq', p_live_candidate_source_change_seq,
        'newer_source_change_seq', v_effective_latest_source_seq,
        'no_active_continuation_job', true,
        'candidate_serial_unblocked', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )),
      v_reason,
      p_actor_user_id
    );
  EXCEPTION WHEN OTHERS THEN
    -- Audit must not re-open the ghost projection-run blocker if the state transition succeeded.
    NULL;
  END;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'projection_run_id', p_projection_run_id::text,
    'projection_run_terminalised', true,
    'projection_run_status_before', v_status_before,
    'projection_run_status_after', COALESCE(v_status_after, 'FAILED'),
    'projection_run_terminalised_reason', v_reason,
    'terminalised_by', 'pay_workbench_claim_due_jobs',
    'superseded_continuation_job_id', p_superseded_job_id::text,
    'payload_source_change_seq', p_payload_source_change_seq,
    'cursor_source_change_seq', p_cursor_source_change_seq,
    'projection_run_source_change_seq', v_effective_projection_source_change_seq,
    'live_candidate_source_change_seq', p_live_candidate_source_change_seq,
    'newer_source_change_seq', v_effective_latest_source_seq,
    'active_continuation_job_exists', false,
    'no_active_continuation_job', true,
    'candidate_serial_unblocked', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  ));
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(
  p_snooze_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.pay_snooze_resolution_transition_v1(
    p_snooze_id => p_snooze_id,
    p_actor_user_id => p_actor_user_id,
    p_transition_reason => 'MANUAL_UNSNOOZE'
  );

  RETURN jsonb_strip_nulls(
    COALESCE(v_result, '{}'::jsonb)
    || jsonb_build_object(
      'code', CASE
        WHEN COALESCE((v_result->>'review_required')::boolean, false)
          THEN 'RATE_RESOLUTION_REQUIRES_REVIEW_AFTER_UNSNOOZE'
        ELSE NULL
      END,
      'reason', CASE
        WHEN COALESCE((v_result->>'review_required')::boolean, false)
          THEN 'CROSS_PAY_WEEK_OR_STALE_SAME_WEEK_UNSNOOZE'
        ELSE COALESCE(v_result->>'reason', 'MANUAL_UNSNOOZE')
      END,
      'manual_unsnooze', true
    )
  );
END;
$function$;


-- GENUINELY NEW IMPLEMENTATION UNIT
-- Records initial post-commit cleanup failures, or releases only the rows owned by
-- an exact retry claim. Duplicate input keys are reduced before the upsert.
DROP FUNCTION IF EXISTS public.timesheet_r2_cleanup_record_v1(text, uuid, uuid[], jsonb);

CREATE OR REPLACE FUNCTION public.timesheet_r2_cleanup_record_v1(p_delete_operation_id text, p_requested_timesheet_id uuid, p_deleted_timesheet_ids uuid[], p_failures jsonb, p_claim_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_operation_id text := NULLIF(BTRIM(COALESCE(p_delete_operation_id, '')), '');
  v_failures jsonb := COALESCE(p_failures, '[]'::jsonb);
  v_input_count integer := 0;
  v_valid_count integer := 0;
  v_recorded_count integer := 0;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF v_operation_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'DELETE_OPERATION_ID_REQUIRED';
  END IF;
  IF jsonb_typeof(v_failures) <> 'array' THEN
    RAISE EXCEPTION USING MESSAGE = 'FAILURES_MUST_BE_JSON_ARRAY';
  END IF;

  v_input_count := jsonb_array_length(v_failures);
  IF v_input_count > 256 THEN
    RAISE EXCEPTION USING MESSAGE = 'R2_CLEANUP_FAILURE_LIMIT_EXCEEDED';
  END IF;

  IF p_claim_token IS NULL THEN
    WITH parsed AS (
      SELECT
        CASE
          WHEN jsonb_typeof(item.value -> 'r2_key') = 'string'
           AND NULLIF(BTRIM(item.value ->> 'r2_key'), '') IS NOT NULL
            THEN item.value ->> 'r2_key'
          ELSE NULL
        END AS r2_key,
        GREATEST(COALESCE(NULLIF(item.value ->> 'attempt_count', '')::integer, 1), 1) AS attempt_count,
        LEFT(
          COALESCE(NULLIF(BTRIM(item.value ->> 'error'), ''), 'R2_DELETE_FAILED'),
          2000
        ) AS error_text,
        item.ordinality
      FROM jsonb_array_elements(v_failures) WITH ORDINALITY AS item(value, ordinality)
    ), deduplicated AS (
      SELECT DISTINCT ON (parsed.r2_key COLLATE "C")
        parsed.r2_key,
        parsed.attempt_count,
        parsed.error_text
      FROM parsed
      WHERE parsed.r2_key IS NOT NULL
      ORDER BY parsed.r2_key COLLATE "C", parsed.ordinality DESC
    ), inserted AS (
      INSERT INTO public.timesheet_r2_cleanup_queue AS q (
        delete_operation_id,
        r2_key,
        requested_timesheet_id,
        deleted_timesheet_ids,
        status,
        attempt_count,
        last_error,
        claim_token,
        claimed_at_utc,
        next_attempt_at_utc,
        first_failed_at_utc,
        last_attempt_at_utc,
        completed_at_utc
      )
      SELECT
        v_operation_id,
        d.r2_key,
        p_requested_timesheet_id,
        COALESCE(p_deleted_timesheet_ids, ARRAY[]::uuid[]),
        'PENDING',
        d.attempt_count,
        d.error_text,
        NULL,
        NULL,
        v_now + make_interval(
          secs => LEAST(
            3600,
            15 * power(2::numeric, LEAST(GREATEST(d.attempt_count - 1, 0), 8))::integer
          )
        ),
        v_now,
        v_now,
        NULL
      FROM deduplicated AS d
      ON CONFLICT (delete_operation_id, r2_key) DO UPDATE
      SET requested_timesheet_id = COALESCE(EXCLUDED.requested_timesheet_id, q.requested_timesheet_id),
          deleted_timesheet_ids = CASE
            WHEN COALESCE(array_length(EXCLUDED.deleted_timesheet_ids, 1), 0) > 0
              THEN EXCLUDED.deleted_timesheet_ids
            ELSE q.deleted_timesheet_ids
          END,
          status = 'PENDING',
          attempt_count = GREATEST(q.attempt_count, EXCLUDED.attempt_count),
          last_error = EXCLUDED.last_error,
          claim_token = NULL,
          claimed_at_utc = NULL,
          next_attempt_at_utc = EXCLUDED.next_attempt_at_utc,
          last_attempt_at_utc = v_now,
          completed_at_utc = NULL
      WHERE q.status <> 'COMPLETE'
      RETURNING 1
    )
    SELECT
      (SELECT COUNT(*) FROM deduplicated),
      (SELECT COUNT(*) FROM inserted)
    INTO v_valid_count, v_recorded_count;
  ELSE
    WITH parsed AS (
      SELECT
        CASE
          WHEN jsonb_typeof(item.value -> 'r2_key') = 'string'
           AND NULLIF(BTRIM(item.value ->> 'r2_key'), '') IS NOT NULL
            THEN item.value ->> 'r2_key'
          ELSE NULL
        END AS r2_key,
        LEFT(
          COALESCE(NULLIF(BTRIM(item.value ->> 'error'), ''), 'R2_DELETE_FAILED'),
          2000
        ) AS error_text,
        item.ordinality
      FROM jsonb_array_elements(v_failures) WITH ORDINALITY AS item(value, ordinality)
    ), deduplicated AS (
      SELECT DISTINCT ON (parsed.r2_key COLLATE "C")
        parsed.r2_key,
        parsed.error_text
      FROM parsed
      WHERE parsed.r2_key IS NOT NULL
      ORDER BY parsed.r2_key COLLATE "C", parsed.ordinality DESC
    ), released AS (
      UPDATE public.timesheet_r2_cleanup_queue AS q
         SET status = 'PENDING',
             last_error = d.error_text,
             claim_token = NULL,
             claimed_at_utc = NULL,
             next_attempt_at_utc = v_now + make_interval(
               secs => LEAST(
                 3600,
                 15 * power(2::numeric, LEAST(GREATEST(q.attempt_count - 1, 0), 8))::integer
               )
             ),
             last_attempt_at_utc = v_now,
             completed_at_utc = NULL
        FROM deduplicated AS d
       WHERE q.delete_operation_id = v_operation_id
         AND q.r2_key = d.r2_key
         AND q.status = 'IN_PROGRESS'
         AND q.claim_token = p_claim_token
      RETURNING 1
    )
    SELECT
      (SELECT COUNT(*) FROM deduplicated),
      (SELECT COUNT(*) FROM released)
    INTO v_valid_count, v_recorded_count;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'delete_operation_id', v_operation_id,
    'claim_token', p_claim_token,
    'input_count', v_input_count,
    'valid_distinct_keys', v_valid_count,
    'recorded', v_recorded_count,
    'stale_or_complete_ignored', GREATEST(v_valid_count - v_recorded_count, 0)
  );
END;
$function$;



REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_record_v1(text, uuid, uuid[], jsonb, uuid) FROM PUBLIC;
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_record_v1(text, uuid, uuid[], jsonb, uuid) FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_record_v1(text, uuid, uuid[], jsonb, uuid) FROM authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.timesheet_r2_cleanup_record_v1(text, uuid, uuid[], jsonb, uuid) TO service_role';
  END IF;
END
$do$;


-- GENUINELY NEW IMPLEMENTATION UNIT
-- Completes only rows owned by the exact live retry claim; a stale worker cannot
-- complete a row that has already been reclaimed with a newer token.
DROP FUNCTION IF EXISTS public.timesheet_r2_cleanup_complete_v1(text, text[]);


CREATE OR REPLACE FUNCTION public.timesheet_r2_cleanup_complete_v1(p_delete_operation_id text, p_claim_token uuid, p_r2_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_operation_id text := NULLIF(BTRIM(COALESCE(p_delete_operation_id, '')), '');
  v_keys text[] := ARRAY[]::text[];
  v_count integer := 0;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF v_operation_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'DELETE_OPERATION_ID_REQUIRED';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'R2_CLEANUP_CLAIM_TOKEN_REQUIRED';
  END IF;

  SELECT COALESCE(
           array_agg(exact_key.r2_key ORDER BY exact_key.r2_key COLLATE "C"),
           ARRAY[]::text[]
         )
    INTO v_keys
  FROM (
    SELECT DISTINCT key_value.value COLLATE "C" AS r2_key
    FROM unnest(COALESCE(p_r2_keys, ARRAY[]::text[])) AS key_value(value)
    WHERE key_value.value IS NOT NULL
      AND NULLIF(BTRIM(key_value.value), '') IS NOT NULL
  ) AS exact_key;

  IF COALESCE(array_length(v_keys, 1), 0) > 256 THEN
    RAISE EXCEPTION USING MESSAGE = 'R2_CLEANUP_KEY_LIMIT_EXCEEDED';
  END IF;

  UPDATE public.timesheet_r2_cleanup_queue AS q
     SET status = 'COMPLETE',
         last_error = NULL,
         last_attempt_at_utc = v_now,
         next_attempt_at_utc = v_now,
         completed_at_utc = v_now,
         claim_token = NULL,
         claimed_at_utc = NULL
   WHERE q.delete_operation_id = v_operation_id
     AND q.r2_key = ANY(v_keys)
     AND q.status = 'IN_PROGRESS'
     AND q.claim_token = p_claim_token;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object(
    'ok', true,
    'delete_operation_id', v_operation_id,
    'claim_token', p_claim_token,
    'requested', COALESCE(array_length(v_keys, 1), 0),
    'completed', v_count,
    'stale_or_missing_ignored', GREATEST(COALESCE(array_length(v_keys, 1), 0) - v_count, 0)
  );
END;
$function$;



REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_complete_v1(text, uuid, text[]) FROM PUBLIC;
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_complete_v1(text, uuid, text[]) FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_complete_v1(text, uuid, text[]) FROM authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.timesheet_r2_cleanup_complete_v1(text, uuid, text[]) TO service_role';
  END IF;
END
$do$;


-- GENUINELY NEW IMPLEMENTATION UNIT
-- Transaction-scoped, exact-row, one-use authority consumed by the Archive row guard.
-- A caller-settable session value is not authority: a matching protected capability
-- must also exist for the current backend, transaction, timesheet and action.
CREATE TABLE IF NOT EXISTS public.timesheet_archive_transition_capability (
  capability_token uuid NOT NULL,
  backend_pid integer NOT NULL,
  transaction_id bigint NOT NULL,
  timesheet_id uuid NOT NULL,
  action text NOT NULL,
  created_at_utc timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT timesheet_archive_transition_capability_pk
    PRIMARY KEY (capability_token, timesheet_id),
  CONSTRAINT timesheet_archive_transition_capability_action_ck
    CHECK (action IN ('ARCHIVE', 'UNARCHIVE'))
);

COMMENT ON TABLE public.timesheet_archive_transition_capability IS
  'Ephemeral exact-row capabilities created and consumed inside timesheet_archive_transition_v1 in one transaction.';

ALTER TABLE public.timesheet_archive_transition_capability ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.timesheet_archive_transition_capability FROM PUBLIC;

DO $do$
DECLARE
  v_role text;
BEGIN
  FOREACH v_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role']::text[] LOOP
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = v_role) THEN
      EXECUTE pg_catalog.format(
        'REVOKE ALL ON TABLE public.timesheet_archive_transition_capability FROM %I',
        v_role
      );
    END IF;
  END LOOP;
END
$do$;


-- CANDIDATE AMENDED AND RETURNED
-- Archive metadata can change only through an exact, transaction-scoped,
-- one-use capability created by timesheet_archive_transition_v1.
CREATE OR REPLACE FUNCTION public.timesheet_archive_row_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_archive_fields_changed boolean := false;
  v_transition_action text := NULL;
  v_capability_token uuid := NULL;
  v_capability_consumed boolean := false;
  v_old_without_archive jsonb;
  v_new_without_archive jsonb;
BEGIN
  -- Archive metadata cannot be manufactured while inserting a new timesheet.
  -- Every Archive starts from an existing authoritative row and must pass
  -- through timesheet_archive_transition_v1.
  IF TG_OP = 'INSERT' THEN
    IF NEW.archived_at_utc IS NOT NULL
       OR NEW.archived_by_user_id IS NOT NULL
       OR NEW.archived_reason_code IS NOT NULL THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_RPC_REQUIRED',
        DETAIL = jsonb_build_object(
          'timesheet_id', NEW.timesheet_id,
          'action', 'ARCHIVE',
          'reason', 'archive_metadata_on_insert_is_forbidden'
        )::text;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.archived_at_utc IS NOT NULL THEN
      RAISE EXCEPTION USING
        MESSAGE = 'TIMESHEET_ARCHIVED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'reason', 'ordinary_delete_for_archived_timesheet_is_forbidden'
        )::text;
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.archived_at_utc IS NULL THEN
    IF NEW.archived_by_user_id IS NOT NULL OR NEW.archived_reason_code IS NOT NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_METADATA_INVALID';
    END IF;
  ELSE
    IF NEW.archived_by_user_id IS NULL OR NULLIF(BTRIM(NEW.archived_reason_code), '') IS NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_METADATA_INVALID';
    END IF;
    IF NEW.authorised_at_server IS NOT NULL THEN
      RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_MUST_BE_UNAUTHORISED_BEFORE_ARCHIVE';
    END IF;
  END IF;

  v_archive_fields_changed :=
    NEW.archived_at_utc IS DISTINCT FROM OLD.archived_at_utc
    OR NEW.archived_by_user_id IS DISTINCT FROM OLD.archived_by_user_id
    OR NEW.archived_reason_code IS DISTINCT FROM OLD.archived_reason_code;

  IF v_archive_fields_changed THEN
    IF OLD.archived_at_utc IS NULL AND NEW.archived_at_utc IS NOT NULL THEN
      v_transition_action := 'ARCHIVE';
    ELSIF OLD.archived_at_utc IS NOT NULL AND NEW.archived_at_utc IS NULL THEN
      v_transition_action := 'UNARCHIVE';
    ELSE
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_INVALID',
        DETAIL = jsonb_build_object('timesheet_id', OLD.timesheet_id)::text;
    END IF;

    v_old_without_archive := to_jsonb(OLD) - ARRAY[
      'archived_at_utc', 'archived_by_user_id', 'archived_reason_code', 'updated_at'
    ];
    v_new_without_archive := to_jsonb(NEW) - ARRAY[
      'archived_at_utc', 'archived_by_user_id', 'archived_reason_code', 'updated_at'
    ];

    IF v_new_without_archive IS DISTINCT FROM v_old_without_archive THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_METADATA_ONLY',
        DETAIL = jsonb_build_object('timesheet_id', OLD.timesheet_id)::text;
    END IF;

    BEGIN
      v_capability_token := NULLIF(
        current_setting('cloudtms.archive_transition_capability', true),
        ''
      )::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        v_capability_token := NULL;
    END;

    IF v_capability_token IS NOT NULL THEN
      DELETE FROM public.timesheet_archive_transition_capability AS capability
      WHERE capability.capability_token = v_capability_token
        AND capability.backend_pid = pg_backend_pid()
        AND capability.transaction_id = txid_current()
        AND capability.timesheet_id = OLD.timesheet_id
        AND capability.action = v_transition_action
      RETURNING true INTO v_capability_consumed;
    END IF;

    IF COALESCE(v_capability_consumed, false) IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_TRANSITION_RPC_REQUIRED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'action', v_transition_action
        )::text;
    END IF;
  ELSIF OLD.archived_at_utc IS NOT NULL THEN
    v_old_without_archive := to_jsonb(OLD) - ARRAY['updated_at'];
    v_new_without_archive := to_jsonb(NEW) - ARRAY['updated_at'];
    IF v_new_without_archive IS DISTINCT FROM v_old_without_archive THEN
      RAISE EXCEPTION USING
        MESSAGE = 'TIMESHEET_ARCHIVED',
        DETAIL = jsonb_build_object(
          'timesheet_id', OLD.timesheet_id,
          'reason', 'archived_timesheet_content_is_read_only'
        )::text;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.timesheet_archive_row_guard_v1() FROM PUBLIC;

-- CANDIDATE AMENDED AND RETURNED
-- Archive authority is an exact transaction-scoped, one-use capability consumed by the row guard.
CREATE OR REPLACE FUNCTION public.timesheet_archive_transition_v1(
  p_timesheet_id uuid,
  p_action text,
  p_removal_kind text DEFAULT 'STANDARD_DELETE'::text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_expected_timesheet_id uuid DEFAULT NULL::uuid,
  p_expected_row_signature text DEFAULT NULL::text,
  p_now_utc timestamp with time zone DEFAULT now()
) RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_action text := UPPER(NULLIF(BTRIM(COALESCE(p_action, '')), ''));
  v_kind text := UPPER(NULLIF(BTRIM(COALESCE(p_removal_kind, 'STANDARD_DELETE')), ''));
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_preview jsonb := '{}'::jsonb;
  v_recheck jsonb := '{}'::jsonb;
  v_decision text := NULL;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_recheck_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_recheck_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_advance jsonb := '{}'::jsonb;
  v_archive_before jsonb := '{}'::jsonb;
  v_target_count integer := 0;
  v_archived_count integer := 0;
  v_unarchived_count integer := 0;
  v_already_archived_count integer := 0;
  v_actor_display text := NULL;
  v_actor_role text := NULL;
  v_current_timesheet_id uuid := NULL;
  v_primary_contract_week_id uuid := NULL;
  v_signature_payload jsonb := '{}'::jsonb;
  v_current_row_signature text := NULL;
  v_archive_capability_token uuid := NULL;
  v_remaining_capability_count integer := 0;
BEGIN
  PERFORM set_config('lock_timeout', '1500ms', true);

  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ID_REQUIRED';
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_USER_ID_REQUIRED';
  END IF;
  IF p_expected_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'EXPECTED_TIMESHEET_ID_REQUIRED',
      DETAIL = jsonb_build_object(
        'requested_timesheet_id', p_timesheet_id,
        'message', 'The current Timesheet identity is required. Refresh before continuing.'
      )::text;
  END IF;
  IF NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '') IS NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'EXPECTED_ROW_SIGNATURE_REQUIRED',
      DETAIL = jsonb_build_object(
        'requested_timesheet_id', p_timesheet_id,
        'expected_timesheet_id', p_expected_timesheet_id,
        'message', 'The current Timesheet lifecycle signature is required. Refresh before continuing.'
      )::text;
  END IF;
  IF v_action IS NULL OR v_action NOT IN ('ARCHIVE', 'UNARCHIVE') THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_ARCHIVE_ACTION';
  END IF;
  IF v_kind IS NULL OR v_kind NOT IN (
    'STANDARD_DELETE',
    'WEEKLY_CHAIN_DELETE_PARENT',
    'WEEKLY_MANUAL_ADJUSTMENT_DELETE'
  ) THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_REMOVAL_KIND';
  END IF;

  SELECT
    COALESCE(
      NULLIF(BTRIM(actor.display_name), ''),
      NULLIF(BTRIM(actor.email), ''),
      'a CloudTMS administrator'
    ),
    actor.role
  INTO v_actor_display, v_actor_role
  FROM public.tms_users AS actor
  WHERE actor.id = p_actor_user_id
    AND actor.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  END IF;

  IF v_kind = 'STANDARD_DELETE' THEN
    v_preview := public.timesheet_standard_delete_preview_v1(
      p_timesheet_id,
      p_actor_user_id,
      p_expected_timesheet_id,
      p_expected_row_signature
    );

    -- A caller may enter through the ordinary Delete/Unarchive route without
    -- knowing that the installed target resolver owns a weekly unit.  Follow
    -- the authoritative preview redirect rather than archiving only one row.
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_preview -> 'blockers', '[]'::jsonb)) AS blocker(value)
      WHERE blocker.value ->> 'code' = 'WEEKLY_CHAIN_PREVIEW_REQUIRED'
    ) THEN
      v_kind := 'WEEKLY_CHAIN_DELETE_PARENT';
      v_preview := public.timesheet_weekly_chain_delete_preview(p_timesheet_id, p_actor_user_id);
    ELSIF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_preview -> 'blockers', '[]'::jsonb)) AS blocker(value)
      WHERE blocker.value ->> 'code' = 'WEEKLY_MANUAL_ADJUSTMENT_PREVIEW_REQUIRED'
    ) THEN
      v_kind := 'WEEKLY_MANUAL_ADJUSTMENT_DELETE';
      v_preview := public.timesheet_weekly_manual_adjustment_delete_preview(p_timesheet_id, p_actor_user_id);
    END IF;
  ELSIF v_kind = 'WEEKLY_CHAIN_DELETE_PARENT' THEN
    v_preview := public.timesheet_weekly_chain_delete_preview(p_timesheet_id, p_actor_user_id);
  ELSE
    v_preview := public.timesheet_weekly_manual_adjustment_delete_preview(p_timesheet_id, p_actor_user_id);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
  FROM (
    SELECT value::uuid AS id
    FROM jsonb_array_elements_text(COALESCE(v_preview -> 'timesheet_ids', '[]'::jsonb)) AS values(value)
  ) AS parsed;

  SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), ARRAY[]::uuid[])
    INTO v_contract_week_ids
  FROM (
    SELECT value::uuid AS id
    FROM jsonb_array_elements_text(COALESCE(v_preview -> 'contract_week_ids', '[]'::jsonb)) AS values(value)
  ) AS parsed;

  IF COALESCE(array_length(v_timesheet_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'REMOVAL_UNIT_EMPTY',
      'preview', v_preview
    );
  END IF;

  IF array_length(v_timesheet_ids, 1) > 32 THEN
    RAISE EXCEPTION USING MESSAGE = 'REMOVAL_UNIT_TOO_LARGE';
  END IF;

  -- Lock the bounded unit in a deterministic order.  FK-backed writers that
  -- create new financial history cannot acquire a conflicting key-share lock
  -- until this transition commits or rolls back.
  PERFORM 1
  FROM public.timesheets AS t
  WHERE t.timesheet_id = ANY(v_timesheet_ids)
  ORDER BY t.timesheet_id
  FOR UPDATE;

  SELECT COUNT(*)
    INTO v_target_count
  FROM public.timesheets AS t
  WHERE t.timesheet_id = ANY(v_timesheet_ids);

  IF v_target_count <> array_length(v_timesheet_ids, 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'REMOVAL_UNIT_CHANGED';
  END IF;

  PERFORM 1
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id = ANY(v_timesheet_ids)
    AND tf.is_current = true
  ORDER BY tf.timesheet_id, tf.id
  FOR UPDATE;

  PERFORM 1
  FROM public.contract_weeks AS cw
  WHERE cw.id = ANY(v_contract_week_ids)
  ORDER BY cw.id
  FOR UPDATE;



  IF v_kind = 'STANDARD_DELETE' THEN
    v_recheck := public.timesheet_standard_delete_preview_v1(
      p_timesheet_id,
      p_actor_user_id,
      p_expected_timesheet_id,
      p_expected_row_signature
    );
  ELSIF v_kind = 'WEEKLY_CHAIN_DELETE_PARENT' THEN
    v_recheck := public.timesheet_weekly_chain_delete_preview(p_timesheet_id, p_actor_user_id);
  ELSE
    v_recheck := public.timesheet_weekly_manual_adjustment_delete_preview(p_timesheet_id, p_actor_user_id);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), ARRAY[]::uuid[])
    INTO v_recheck_timesheet_ids
  FROM (
    SELECT value::uuid AS id
    FROM jsonb_array_elements_text(COALESCE(v_recheck -> 'timesheet_ids', '[]'::jsonb)) AS values(value)
  ) AS parsed;

  SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), ARRAY[]::uuid[])
    INTO v_recheck_contract_week_ids
  FROM (
    SELECT value::uuid AS id
    FROM jsonb_array_elements_text(COALESCE(v_recheck -> 'contract_week_ids', '[]'::jsonb)) AS values(value)
  ) AS parsed;

  IF v_recheck_timesheet_ids IS DISTINCT FROM v_timesheet_ids
     OR v_recheck_contract_week_ids IS DISTINCT FROM v_contract_week_ids THEN
    RAISE EXCEPTION USING MESSAGE = 'REMOVAL_UNIT_CHANGED';
  END IF;

  v_current_timesheet_id := NULLIF(
    BTRIM(COALESCE(v_recheck ->> 'current_timesheet_id', '')),
    ''
  )::uuid;

  IF v_current_timesheet_id IS NULL
     OR NOT (v_current_timesheet_id = ANY(v_timesheet_ids)) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'CURRENT_TIMESHEET_NOT_FOUND',
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids)
    );
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE t.archived_at_utc IS NOT NULL),
    COALESCE(jsonb_object_agg(
      t.timesheet_id::text,
      jsonb_build_object(
        'archived_at_utc', t.archived_at_utc,
        'archived_by_user_id', t.archived_by_user_id,
        'archived_reason_code', t.archived_reason_code
      )
    ), '{}'::jsonb)
  INTO v_already_archived_count, v_archive_before
  FROM public.timesheets AS t
  WHERE t.timesheet_id = ANY(v_timesheet_ids);

  IF v_action = 'ARCHIVE'
     AND v_already_archived_count = array_length(v_timesheet_ids, 1) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'ARCHIVE',
      'already_archived', true,
      'decision', 'ARCHIVED',
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids),
      'archive_state', public.timesheet_archive_state_v1(p_timesheet_id)
    );
  END IF;

  IF v_action = 'UNARCHIVE' AND v_already_archived_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'UNARCHIVE',
      'already_unarchived', true,
      'decision', 'ACTIVE',
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids),
      'advance_restored', false,
      'archive_state', public.timesheet_archive_state_v1(p_timesheet_id)
    );
  END IF;

  IF v_already_archived_count > 0
     AND v_already_archived_count <> array_length(v_timesheet_ids, 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_UNIT_PARTIAL_STATE';
  END IF;

  -- Idempotent already-completed outcomes above deliberately precede the
  -- stale guards so a retry after an unknown response can reconcile safely
  -- without replaying any Archive, Unarchive, Advance or audit mutation.
  IF p_expected_timesheet_id IS DISTINCT FROM v_current_timesheet_id THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'EXPECTED_TIMESHEET_MISMATCH',
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current_timesheet_id,
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids)
    );
  END IF;

  v_primary_contract_week_id := v_contract_week_ids[1];
  v_signature_payload := public.timesheet_lifecycle_guard_signature_v1(
    v_current_timesheet_id,
    v_primary_contract_week_id,
    false
  );
  v_current_row_signature := NULLIF(BTRIM(COALESCE(
    v_signature_payload ->> 'backend_row_signature',
    v_signature_payload ->> 'row_signature',
    v_signature_payload ->> 'signature',
    ''
  )), '');

  IF v_current_row_signature IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'ROW_SIGNATURE_UNAVAILABLE',
      'current_timesheet_id', v_current_timesheet_id,
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids)
    );
  END IF;

  IF v_current_row_signature IS DISTINCT FROM BTRIM(p_expected_row_signature) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'ROW_SIGNATURE_MISMATCH',
      'expected_row_signature', BTRIM(p_expected_row_signature),
      'current_row_signature', v_current_row_signature,
      'current_timesheet_id', v_current_timesheet_id,
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids)
    );
  END IF;

  IF v_action = 'ARCHIVE' THEN
    v_decision := COALESCE(v_recheck ->> 'decision', 'BLOCKED');

    IF v_decision = 'PERMANENT_DELETE' THEN
      RETURN jsonb_build_object(
        'ok', false,
        'action', 'ARCHIVE',
        'decision', 'PERMANENT_DELETE',
        'error_code', 'ARCHIVE_NOT_REQUIRED',
        'timesheet_ids', to_jsonb(v_timesheet_ids),
        'contract_week_ids', to_jsonb(v_contract_week_ids)
      );
    END IF;

    IF v_decision <> 'ARCHIVE_REQUIRED' THEN
      RETURN jsonb_build_object(
        'ok', false,
        'action', 'ARCHIVE',
        'decision', 'BLOCKED',
        'error_code', 'ARCHIVE_BLOCKED',
        'blockers', COALESCE(v_recheck -> 'blockers', v_recheck -> 'blocked_reasons', '[]'::jsonb),
        'timesheet_ids', to_jsonb(v_timesheet_ids),
        'contract_week_ids', to_jsonb(v_contract_week_ids)
      );
    END IF;

    v_advance := COALESCE(v_recheck -> 'advance', '{}'::jsonb);

    -- Archive is metadata-only. Active, clearable, consumed and historical
    -- Advance rows remain unchanged and continue to be reported by the preview.
    v_archive_capability_token := gen_random_uuid();

    INSERT INTO public.timesheet_archive_transition_capability (
      capability_token,
      backend_pid,
      transaction_id,
      timesheet_id,
      action
    )
    SELECT
      v_archive_capability_token,
      pg_backend_pid(),
      txid_current(),
      target_id,
      'ARCHIVE'
    FROM unnest(v_timesheet_ids) AS targets(target_id);

    PERFORM set_config(
      'cloudtms.archive_transition_capability',
      v_archive_capability_token::text,
      true
    );

    UPDATE public.timesheets AS t
       SET archived_at_utc = v_now,
           archived_by_user_id = p_actor_user_id,
           archived_reason_code = 'FINANCIAL_HISTORY_PREVENTED_DELETE',
           updated_at = v_now
     WHERE t.timesheet_id = ANY(v_timesheet_ids)
       AND t.archived_at_utc IS NULL;
    GET DIAGNOSTICS v_archived_count = ROW_COUNT;

    PERFORM set_config('cloudtms.archive_transition_capability', '', true);

    SELECT COUNT(*)
      INTO v_remaining_capability_count
    FROM public.timesheet_archive_transition_capability AS capability
    WHERE capability.capability_token = v_archive_capability_token
      AND capability.backend_pid = pg_backend_pid()
      AND capability.transaction_id = txid_current();

    IF v_remaining_capability_count <> 0 THEN
      RAISE EXCEPTION USING
        MESSAGE = 'ARCHIVE_CAPABILITY_NOT_CONSUMED',
        DETAIL = jsonb_build_object(
          'remaining_capabilities', v_remaining_capability_count,
          'target_count', array_length(v_timesheet_ids, 1)
        )::text;
    END IF;

    IF v_archived_count <> array_length(v_timesheet_ids, 1) THEN
      RAISE EXCEPTION USING MESSAGE = 'ARCHIVE_COUNT_MISMATCH';
    END IF;

    INSERT INTO public.audit_events (
      ts_utc,
      actor_user_id,
      actor_display,
      actor_role_at_time,
      object_type,
      object_id_text,
      action,
      before_json,
      after_json,
      reason
    )
    SELECT
      v_now,
      p_actor_user_id,
      v_actor_display,
      v_actor_role,
      'timesheets',
      target_id::text,
      'TIMESHEET_ARCHIVED',
      COALESCE(v_archive_before -> target_id::text, jsonb_build_object('archived_at_utc', NULL)),
      jsonb_build_object(
        'archived_at_utc', v_now,
        'archived_by_user_id', p_actor_user_id,
        'archived_reason_code', 'FINANCIAL_HISTORY_PREVENTED_DELETE',
        'target_unit_ids', to_jsonb(v_timesheet_ids),
        'active_advance_detected', COALESCE((v_advance ->> 'active')::boolean, false),
        'advance_unchanged', true,
        'related_pay_batch_id', v_advance -> 'related_pay_batch_id',
        'related_pay_batch_status', v_advance -> 'related_pay_batch_status'
      ),
      'FINANCIAL_HISTORY_PREVENTED_DELETE'
    FROM unnest(v_timesheet_ids) AS targets(target_id);

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'ARCHIVE',
      'decision', 'ARCHIVED',
      'already_archived', false,
      'archived_count', v_archived_count,
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'contract_week_ids', to_jsonb(v_contract_week_ids),
      'advance', v_advance || jsonb_build_object(
        'unchanged', true
      ),
      'archive_state', public.timesheet_archive_state_v1(p_timesheet_id)
    );
  END IF;

  -- UNARCHIVE is metadata-only. It does not change Advance, authorisation,
  -- processing, TSFIN, pay-state, batch, invoice or contract data.
  v_archive_capability_token := gen_random_uuid();

  INSERT INTO public.timesheet_archive_transition_capability (
    capability_token,
    backend_pid,
    transaction_id,
    timesheet_id,
    action
  )
  SELECT
    v_archive_capability_token,
    pg_backend_pid(),
    txid_current(),
    target_id,
    'UNARCHIVE'
  FROM unnest(v_timesheet_ids) AS targets(target_id);

  PERFORM set_config(
    'cloudtms.archive_transition_capability',
    v_archive_capability_token::text,
    true
  );

  UPDATE public.timesheets AS t
     SET archived_at_utc = NULL,
         archived_by_user_id = NULL,
         archived_reason_code = NULL,
         updated_at = v_now
   WHERE t.timesheet_id = ANY(v_timesheet_ids)
     AND t.archived_at_utc IS NOT NULL;
  GET DIAGNOSTICS v_unarchived_count = ROW_COUNT;

  PERFORM set_config('cloudtms.archive_transition_capability', '', true);

  SELECT COUNT(*)
    INTO v_remaining_capability_count
  FROM public.timesheet_archive_transition_capability AS capability
  WHERE capability.capability_token = v_archive_capability_token
    AND capability.backend_pid = pg_backend_pid()
    AND capability.transaction_id = txid_current();

  IF v_remaining_capability_count <> 0 THEN
    RAISE EXCEPTION USING
      MESSAGE = 'ARCHIVE_CAPABILITY_NOT_CONSUMED',
      DETAIL = jsonb_build_object(
        'remaining_capabilities', v_remaining_capability_count,
        'target_count', array_length(v_timesheet_ids, 1)
      )::text;
  END IF;

  IF v_unarchived_count <> array_length(v_timesheet_ids, 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'UNARCHIVE_COUNT_MISMATCH';
  END IF;

  INSERT INTO public.audit_events (
    ts_utc,
    actor_user_id,
    actor_display,
    actor_role_at_time,
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason
  )
  SELECT
    v_now,
    p_actor_user_id,
    v_actor_display,
    v_actor_role,
    'timesheets',
    target_id::text,
    'TIMESHEET_UNARCHIVED',
    COALESCE(v_archive_before -> target_id::text, jsonb_build_object('archived_at_utc', true)),
    jsonb_build_object(
      'archived_at_utc', NULL,
      'archived_by_user_id', NULL,
      'archived_reason_code', NULL,
      'target_unit_ids', to_jsonb(v_timesheet_ids),
      'advance_restored', false,
      'advance_unchanged', true
    ),
    'USER_CONFIRMED_UNARCHIVE'
  FROM unnest(v_timesheet_ids) AS targets(target_id);

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'UNARCHIVE',
    'decision', 'ACTIVE',
    'already_unarchived', false,
    'unarchived_count', v_unarchived_count,
    'timesheet_ids', to_jsonb(v_timesheet_ids),
    'contract_week_ids', to_jsonb(v_contract_week_ids),
    'advance_restored', false,
    'advance_unchanged', true,
    'archive_state', public.timesheet_archive_state_v1(p_timesheet_id)
  );
EXCEPTION
  WHEN lock_not_available OR deadlock_detected THEN
    RETURN jsonb_build_object(
      'ok', false,
      'action', v_action,
      'decision', 'BLOCKED',
      'error_code', 'LOCK_TIMEOUT',
      'message', 'The timesheet removal unit is currently being changed. Refresh and try again.'
    );
END;
$function$;

-- Archive/Unarchive accepts an actor UUID and is therefore exposed only to the
-- authenticated Worker/service boundary that derives that actor.
REVOKE ALL ON FUNCTION public.timesheet_archive_transition_v1(uuid, text, text, uuid, uuid, text, timestamptz) FROM PUBLIC;
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON FUNCTION public.timesheet_archive_transition_v1(uuid, text, text, uuid, uuid, text, timestamptz) FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON FUNCTION public.timesheet_archive_transition_v1(uuid, text, text, uuid, uuid, text, timestamptz) FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION public.timesheet_archive_transition_v1(uuid, text, text, uuid, uuid, text, timestamptz) TO service_role;
  END IF;
END
$do$;

-- GENUINELY NEW IMPLEMENTATION UNIT
-- Bounded, due-time-aware, lease-based and idempotent retry claim.
CREATE OR REPLACE FUNCTION public.timesheet_r2_cleanup_claim_v1(
  p_limit integer DEFAULT 50,
  p_lease_seconds integer DEFAULT 300
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_lease_seconds integer := LEAST(GREATEST(COALESCE(p_lease_seconds, 300), 30), 3600);
  v_claim_token uuid := gen_random_uuid();
  v_now timestamptz := clock_timestamp();
  v_rows jsonb := '[]'::jsonb;
  v_more_due boolean := false;
BEGIN
  WITH claimable AS (
    SELECT q.delete_operation_id, q.r2_key
    FROM public.timesheet_r2_cleanup_queue AS q
    WHERE (
      q.status = 'PENDING'
      AND q.next_attempt_at_utc <= v_now
    ) OR (
      q.status = 'IN_PROGRESS'
      AND q.claimed_at_utc < v_now - make_interval(secs => v_lease_seconds)
    )
    ORDER BY
      CASE WHEN q.status = 'IN_PROGRESS' THEN 0 ELSE 1 END,
      q.next_attempt_at_utc,
      q.last_attempt_at_utc,
      q.delete_operation_id,
      q.r2_key
    FOR UPDATE SKIP LOCKED
    LIMIT v_limit
  ), claimed AS (
    UPDATE public.timesheet_r2_cleanup_queue AS q
       SET status = 'IN_PROGRESS',
           claim_token = v_claim_token,
           claimed_at_utc = v_now,
           last_attempt_at_utc = v_now,
           attempt_count = q.attempt_count + 1
      FROM claimable AS c
     WHERE q.delete_operation_id = c.delete_operation_id
       AND q.r2_key = c.r2_key
    RETURNING q.delete_operation_id, q.r2_key, q.requested_timesheet_id,
              q.deleted_timesheet_ids, q.attempt_count, q.claim_token
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'delete_operation_id', c.delete_operation_id,
        'r2_key', c.r2_key,
        'requested_timesheet_id', c.requested_timesheet_id,
        'deleted_timesheet_ids', to_jsonb(c.deleted_timesheet_ids),
        'attempt_count', c.attempt_count,
        'claim_token', c.claim_token
      )
      ORDER BY c.delete_operation_id, c.r2_key
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM claimed AS c;

  SELECT EXISTS (
    SELECT 1
    FROM public.timesheet_r2_cleanup_queue AS q
    WHERE (q.status = 'PENDING' AND q.next_attempt_at_utc <= v_now)
       OR (
         q.status = 'IN_PROGRESS'
         AND q.claimed_at_utc < v_now - make_interval(secs => v_lease_seconds)
       )
  )
  INTO v_more_due;

  RETURN jsonb_build_object(
    'ok', true,
    'claim_token', v_claim_token,
    'count', jsonb_array_length(v_rows),
    'more_due', v_more_due,
    'items', v_rows
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_claim_v1(integer, integer) FROM PUBLIC;
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_claim_v1(integer, integer) FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.timesheet_r2_cleanup_claim_v1(integer, integer) FROM authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.timesheet_r2_cleanup_claim_v1(integer, integer) TO service_role';
  END IF;
END
$do$;


-- CloudTMS Retention Marker / Unprocess handover
-- Disposition: genuinely new implementation unit.
-- Purpose: normalise the sticky retention/Unprocess contract across every
-- successful shape emitted by bulk_process_row_context_v1, without using
-- payment state as an Unprocess authority.

CREATE OR REPLACE FUNCTION public.bulk_process_retention_contract_patch_v1(
  p_payload jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_uuid_re constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$';
  v_timesheet_id_text text;
  v_timesheet_id uuid;
  v_timesheet_scope public.timesheet_scope_enum;
  v_booking_id text;
  v_has_retained boolean := false;
  v_base_can_unprocess boolean := false;
  v_visible_present boolean := false;
  v_existing_visible boolean := false;
  v_action_eligible boolean := false;
  v_can_unprocess boolean := false;
  v_existing_reason text;
  v_reason text;
  v_message text;
  v_contract jsonb;
  v_action_flags jsonb;
  v_row_patch jsonb;
  v_row jsonb;
  v_data_row jsonb;
  v_details jsonb;
BEGIN
  v_timesheet_id_text := NULLIF(BTRIM(COALESCE(
    v_payload->>'timesheet_id',
    v_payload->>'current_timesheet_id',
    v_payload#>>'{row,timesheet_id}',
    v_payload#>>'{row,current_timesheet_id}',
    v_payload#>>'{data_row,timesheet_id}',
    v_payload#>>'{data_row,current_timesheet_id}',
    v_payload#>>'{row_patch,timesheet_id}',
    v_payload#>>'{row_patch,current_timesheet_id}',
    v_payload#>>'{details,timesheet_id}',
    ''
  )), '');

  IF v_timesheet_id_text IS NOT NULL AND v_timesheet_id_text ~* v_uuid_re THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_timesheet_id IS NOT NULL THEN
    SELECT timesheet_row.sheet_scope, timesheet_row.booking_id
      INTO v_timesheet_scope, v_booking_id
    FROM public.timesheets AS timesheet_row
    WHERE timesheet_row.timesheet_id = v_timesheet_id;

    IF v_timesheet_scope = 'WEEKLY'::public.timesheet_scope_enum THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.timesheets AS unit_timesheet
        JOIN public.timesheet_financial_retention AS retention_row
          ON retention_row.timesheet_id = unit_timesheet.timesheet_id
        WHERE unit_timesheet.booking_id = v_booking_id
      )
      INTO v_has_retained;
    ELSE
      SELECT EXISTS (
        SELECT 1
        FROM public.timesheet_financial_retention AS retention_row
        WHERE retention_row.timesheet_id = v_timesheet_id
      )
      INTO v_has_retained;
    END IF;
  END IF;

  v_base_can_unprocess := LOWER(NULLIF(BTRIM(COALESCE(
    v_payload->>'can_unprocess',
    v_payload#>>'{action_flags,can_unprocess}',
    v_payload#>>'{row,can_unprocess}',
    v_payload#>>'{row,action_flags,can_unprocess}',
    v_payload#>>'{data_row,can_unprocess}',
    v_payload#>>'{data_row,action_flags,can_unprocess}',
    v_payload#>>'{row_patch,can_unprocess}',
    v_payload#>>'{details,can_unprocess}',
    v_payload#>>'{details,action_flags,can_unprocess}',
    ''
  )), '')) IN ('true', '1', 'yes', 'y', 'on');

  v_visible_present :=
       v_payload ? 'unprocess_action_visible'
    OR COALESCE(v_payload->'action_flags', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload->'row', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload#>'{row,action_flags}', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload->'data_row', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload#>'{data_row,action_flags}', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload->'row_patch', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload->'details', '{}'::jsonb) ? 'unprocess_action_visible'
    OR COALESCE(v_payload#>'{details,action_flags}', '{}'::jsonb) ? 'unprocess_action_visible';

  v_existing_visible := LOWER(NULLIF(BTRIM(COALESCE(
    v_payload->>'unprocess_action_visible',
    v_payload#>>'{action_flags,unprocess_action_visible}',
    v_payload#>>'{row,unprocess_action_visible}',
    v_payload#>>'{row,action_flags,unprocess_action_visible}',
    v_payload#>>'{data_row,unprocess_action_visible}',
    v_payload#>>'{data_row,action_flags,unprocess_action_visible}',
    v_payload#>>'{row_patch,unprocess_action_visible}',
    v_payload#>>'{details,unprocess_action_visible}',
    v_payload#>>'{details,action_flags,unprocess_action_visible}',
    ''
  )), '')) IN ('true', '1', 'yes', 'y', 'on');

  v_action_eligible := CASE WHEN v_visible_present THEN v_existing_visible ELSE v_base_can_unprocess END;
  v_can_unprocess := v_base_can_unprocess AND NOT v_has_retained;

  v_existing_reason := NULLIF(BTRIM(COALESCE(
    v_payload->>'unprocess_block_reason',
    v_payload#>>'{action_flags,unprocess_block_reason}',
    v_payload#>>'{row,unprocess_block_reason}',
    v_payload#>>'{row,action_flags,unprocess_block_reason}',
    v_payload#>>'{data_row,unprocess_block_reason}',
    v_payload#>>'{data_row,action_flags,unprocess_block_reason}',
    v_payload#>>'{row_patch,unprocess_block_reason}',
    v_payload#>>'{details,unprocess_block_reason}',
    v_payload#>>'{details,action_flags,unprocess_block_reason}',
    ''
  )), '');

  v_reason := COALESCE(
    v_existing_reason,
    CASE
      WHEN v_has_retained AND v_action_eligible THEN 'FINANCIAL_HISTORY_PREVENTS_UNPROCESS'
      ELSE NULL::text
    END
  );

  v_message := CASE
    WHEN v_reason = 'FINANCIAL_HISTORY_PREVENTS_UNPROCESS'
    THEN 'This timesheet has already been financially linked and cannot be unprocessed. You can archive the timesheet instead.'
    ELSE NULL::text
  END;

  v_contract := JSONB_BUILD_OBJECT(
    'has_retained_financial_history', v_has_retained,
    'can_unprocess', v_can_unprocess,
    'unprocess_block_reason', v_reason,
    'unprocess_action_visible', v_action_eligible,
    'unprocess_block_message', v_message
  );

  v_action_flags := COALESCE(v_payload->'action_flags', '{}'::jsonb) || v_contract;
  v_row_patch := COALESCE(v_payload->'row_patch', '{}'::jsonb) || v_contract;

  v_row := COALESCE(v_payload->'row', '{}'::jsonb)
    || v_contract
    || JSONB_BUILD_OBJECT(
      'action_flags', COALESCE(v_payload#>'{row,action_flags}', '{}'::jsonb) || v_contract,
      'row_patch', COALESCE(v_payload#>'{row,row_patch}', '{}'::jsonb) || v_contract
    );

  v_data_row := COALESCE(v_payload->'data_row', v_payload->'row', '{}'::jsonb)
    || v_contract
    || JSONB_BUILD_OBJECT(
      'action_flags', COALESCE(v_payload#>'{data_row,action_flags}', v_payload#>'{row,action_flags}', '{}'::jsonb) || v_contract,
      'row_patch', COALESCE(v_payload#>'{data_row,row_patch}', v_payload#>'{row,row_patch}', '{}'::jsonb) || v_contract
    );

  v_details := COALESCE(v_payload->'details', '{}'::jsonb)
    || v_contract
    || JSONB_BUILD_OBJECT(
      'action_flags', COALESCE(v_payload#>'{details,action_flags}', '{}'::jsonb) || v_contract,
      'row_patch', COALESCE(v_payload#>'{details,row_patch}', '{}'::jsonb) || v_contract
    );

  RETURN v_payload
    || v_contract
    || JSONB_BUILD_OBJECT(
      'action_flags', v_action_flags,
      'row_patch', v_row_patch,
      'row', v_row,
      'data_row', v_data_row,
      'details', v_details
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.bulk_process_retention_contract_patch_v1(jsonb) FROM PUBLIC;
DO $do$
DECLARE
  v_role name;
BEGIN
  FOREACH v_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role']::name[] LOOP
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS r WHERE r.rolname = v_role) THEN
      EXECUTE pg_catalog.format(
        'REVOKE ALL ON FUNCTION public.bulk_process_retention_contract_patch_v1(jsonb) FROM %I',
        v_role
      );
    END IF;
  END LOOP;
END
$do$;



CREATE OR REPLACE FUNCTION public.timesheet_standard_delete_preview_v1(p_timesheet_id uuid, p_actor_user_id uuid, p_expected_timesheet_id uuid DEFAULT NULL::uuid, p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested public.timesheets%ROWTYPE;
  v_current public.timesheets%ROWTYPE;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_nhsp_shift_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_primary_contract_week_id uuid := NULL;
  v_history jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_decision text := 'BLOCKED';
  v_signature_payload jsonb := '{}'::jsonb;
  v_current_signature text := NULL;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ID_REQUIRED';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_USER_ID_REQUIRED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor
    WHERE actor.id = p_actor_user_id
      AND actor.is_active = true
  ) THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  END IF;

  SELECT t.*
    INTO v_requested
  FROM public.timesheets AS t
  WHERE t.timesheet_id = p_timesheet_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  SELECT t.*
    INTO v_current
  FROM public.timesheets AS t
  WHERE t.booking_id = v_requested.booking_id
    AND t.is_current = true
  ORDER BY t.version DESC NULLS LAST,
           t.updated_at DESC NULLS LAST,
           t.created_at DESC NULLS LAST,
           t.timesheet_id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'requested_timesheet_id', p_timesheet_id,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  -- The installed standard-delete path removes the authoritative current row only.
  -- Weekly parent/manual paths resolve their own larger units in their existing previews.
  v_timesheet_ids := ARRAY[v_current.timesheet_id]::uuid[];

  SELECT COALESCE(array_agg(DISTINCT cw.id ORDER BY cw.id), ARRAY[]::uuid[])
    INTO v_contract_week_ids
  FROM public.contract_weeks AS cw
  WHERE cw.timesheet_id = v_current.timesheet_id;

  v_primary_contract_week_id := v_contract_week_ids[1];

  SELECT COALESCE(array_agg(DISTINCT nhsp_shift.id ORDER BY nhsp_shift.id), ARRAY[]::uuid[])
    INTO v_nhsp_shift_ids
  FROM public.nhsp_shifts AS nhsp_shift
  WHERE nhsp_shift.timesheet_id = ANY(v_timesheet_ids);

  SELECT COALESCE(array_agg(DISTINCT source_contract_week.id ORDER BY source_contract_week.id), ARRAY[]::uuid[])
    INTO v_preserved_source_contract_week_ids
  FROM public.contract_weeks AS target_contract_week
  JOIN public.contract_weeks AS source_contract_week
    ON source_contract_week.contract_id = target_contract_week.contract_id
   AND source_contract_week.week_ending_date = target_contract_week.week_ending_date
   AND COALESCE(source_contract_week.additional_seq, 0) = 0
   AND COALESCE(source_contract_week.is_adjustment, false) = false
  WHERE target_contract_week.id = ANY(v_contract_week_ids)
    AND source_contract_week.id <> ALL(v_contract_week_ids);

  SELECT COALESCE(array_agg(DISTINCT preserved_row.preserved_timesheet_id ORDER BY preserved_row.preserved_timesheet_id), ARRAY[]::uuid[])
    INTO v_preserved_source_timesheet_ids
  FROM (
    SELECT source_contract_week.timesheet_id AS preserved_timesheet_id
    FROM public.contract_weeks AS source_contract_week
    WHERE source_contract_week.id = ANY(v_preserved_source_contract_week_ids)
      AND source_contract_week.timesheet_id IS NOT NULL

    UNION

    SELECT target_timesheet.parent_timesheet_id AS preserved_timesheet_id
    FROM public.timesheets AS target_timesheet
    WHERE target_timesheet.timesheet_id = ANY(v_timesheet_ids)
      AND target_timesheet.parent_timesheet_id IS NOT NULL
  ) AS preserved_row
  WHERE preserved_row.preserved_timesheet_id IS NOT NULL
    AND preserved_row.preserved_timesheet_id <> ALL(v_timesheet_ids);

  IF p_expected_timesheet_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_ID_REQUIRED',
      'current_timesheet_id', v_current.timesheet_id,
      'message', 'The current Timesheet identity is required. Refresh before continuing.'
    ));
  ELSIF p_expected_timesheet_id IS DISTINCT FROM v_current.timesheet_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_MISMATCH',
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current.timesheet_id
    ));
  END IF;

  v_signature_payload := public.timesheet_lifecycle_guard_signature_v1(
    v_current.timesheet_id,
    v_primary_contract_week_id,
    false
  );
  v_current_signature := NULLIF(BTRIM(COALESCE(
    v_signature_payload ->> 'backend_row_signature',
    v_signature_payload ->> 'row_signature',
    v_signature_payload ->> 'signature',
    ''
  )), '');

  IF NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '') IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_ROW_SIGNATURE_REQUIRED',
      'current_row_signature', v_current_signature,
      'message', 'The current Timesheet lifecycle signature is required. Refresh before continuing.'
    ));
  ELSIF v_current_signature IS DISTINCT FROM BTRIM(p_expected_row_signature) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'ROW_SIGNATURE_MISMATCH',
      'expected_row_signature', BTRIM(p_expected_row_signature),
      'current_row_signature', v_current_signature
    ));
  END IF;

  IF v_current.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum THEN
    IF COALESCE(v_current.is_adjustment, false)
       OR EXISTS (
         SELECT 1
         FROM public.contract_weeks AS cw
         WHERE cw.timesheet_id = v_current.timesheet_id
           AND (COALESCE(cw.is_adjustment, false) OR COALESCE(cw.additional_seq, 0) > 0)
       ) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_MANUAL_ADJUSTMENT_PREVIEW_REQUIRED'
      ));
    ELSE
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_CHAIN_PREVIEW_REQUIRED'
      ));
    END IF;
  END IF;

  IF UPPER(COALESCE(v_current.adjustment_origin, '')) IN ('IMPORT_CORRECTION', 'IMPORT_CANCELLATION')
     OR NULLIF(BTRIM(COALESCE(v_current.correction_kind, '')), '') IS NOT NULL
     OR v_current.correction_id IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'IMPORT_DERIVED_CHILD',
      'message', 'Import-derived children must be handled through the parent-chain removal path.'
    ));
  END IF;

  v_history := public.timesheet_removal_financial_history_v1(
    v_timesheet_ids,
    ARRAY[v_current.booking_id]::text[],
    v_contract_week_ids
  );

  v_blockers := v_blockers || COALESCE(v_history -> 'blockers', '[]'::jsonb);

  IF jsonb_array_length(v_blockers) > 0 THEN
    v_decision := 'BLOCKED';
  ELSIF COALESCE((v_history ->> 'archive_required')::boolean, false) THEN
    v_decision := 'ARCHIVE_REQUIRED';
  ELSE
    v_decision := 'PERMANENT_DELETE';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', 'STANDARD_DELETE',
    'decision', v_decision,
    'eligible', v_decision = 'PERMANENT_DELETE',
    'requested_timesheet_id', p_timesheet_id,
    'current_timesheet_id', v_current.timesheet_id,
    'was_stale', v_current.timesheet_id IS DISTINCT FROM p_timesheet_id,
    'booking_id', v_current.booking_id,
    'timesheet_ids', to_jsonb(v_timesheet_ids),
    'contract_week_ids', to_jsonb(v_contract_week_ids),
    'nhsp_shift_ids', to_jsonb(v_nhsp_shift_ids),
    'preserved_source_timesheet_ids', to_jsonb(v_preserved_source_timesheet_ids),
    'preserved_source_contract_week_ids', to_jsonb(v_preserved_source_contract_week_ids),
    'blockers', v_blockers,
    'blocked_reasons', v_blockers,
    'retention_reasons', COALESCE(v_history -> 'retention_reasons', '[]'::jsonb),
    'advance', COALESCE(v_history -> 'advance', '{}'::jsonb),
    'current_row_signature', v_current_signature
  );
END;
$function$;



-- Source-boundary hardening: this RPC accepts an actor UUID and must only be
-- reached through the authenticated Worker/service boundary that derives it.
REVOKE ALL ON FUNCTION public.timesheet_standard_delete_preview_v1(uuid, uuid, uuid, text) FROM PUBLIC;
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON FUNCTION public.timesheet_standard_delete_preview_v1(uuid, uuid, uuid, text) FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON FUNCTION public.timesheet_standard_delete_preview_v1(uuid, uuid, uuid, text) FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION public.timesheet_standard_delete_preview_v1(uuid, uuid, uuid, text) TO service_role;
  END IF;
END
$do$;



CREATE OR REPLACE FUNCTION public.invoice_line_archived_timesheet_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current_timesheet_id uuid;
  v_archived_at_utc timestamptz;
BEGIN
  -- Exact identity is authoritative whenever the invoice-line mutation supplies
  -- a timesheet_id.  Do not replace it with the current row for the booking:
  -- a historical exact identity can itself be Archived.
  IF NEW.timesheet_id IS NOT NULL THEN
    SELECT
      t.timesheet_id,
      t.archived_at_utc
    INTO
      v_current_timesheet_id,
      v_archived_at_utc
    FROM public.timesheets AS t
    WHERE t.timesheet_id = NEW.timesheet_id
    FOR KEY SHARE OF t;
  ELSIF NULLIF(BTRIM(COALESCE(NEW.booking_id, '')), '') IS NOT NULL THEN
    -- Booking lookup is fallback-only when the caller supplied no exact ID.
    SELECT
      t.timesheet_id,
      t.archived_at_utc
    INTO
      v_current_timesheet_id,
      v_archived_at_utc
    FROM public.timesheets AS t
    WHERE t.is_current = true
      AND t.booking_id = NEW.booking_id
    ORDER BY t.timesheet_id
    LIMIT 1
    FOR KEY SHARE OF t;
  END IF;

  IF v_current_timesheet_id IS NOT NULL
     AND v_archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_ARCHIVED',
      DETAIL = jsonb_build_object(
        'timesheet_id', v_current_timesheet_id,
        'reason', 'archived_timesheet_cannot_be_added_to_invoice'
      )::text;
  END IF;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.invoice_line_archived_timesheet_guard_v1() FROM PUBLIC;


CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_mark_v1(
  p_timesheet_ids uuid[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_requested_count integer := 0;
  v_locked_count integer := 0;
  v_inserted_count integer := 0;
BEGIN
  SELECT COALESCE(array_agg(DISTINCT requested.timesheet_id ORDER BY requested.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
  FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS requested(timesheet_id)
  WHERE requested.timesheet_id IS NOT NULL;

  v_requested_count := COALESCE(array_length(v_timesheet_ids, 1), 0);

  IF v_requested_count = 0 THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_IDS_REQUIRED',
      DETAIL = jsonb_build_object('function', 'timesheet_financial_retention_mark_v1')::text;
  END IF;

  IF v_requested_count > 1000 THEN
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_MARK_SCOPE_TOO_LARGE',
      DETAIL = jsonb_build_object('maximum', 1000, 'actual', v_requested_count)::text;
  END IF;

  SELECT COUNT(*)::integer
    INTO v_locked_count
  FROM (
    SELECT t.timesheet_id
    FROM public.timesheets AS t
    JOIN unnest(v_timesheet_ids) AS requested(timesheet_id)
      ON requested.timesheet_id = t.timesheet_id
    ORDER BY t.timesheet_id
    FOR KEY SHARE OF t
  ) AS locked_timesheets;

  IF v_locked_count IS DISTINCT FROM v_requested_count THEN
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_MARK_TIMESHEET_NOT_FOUND',
      DETAIL = jsonb_build_object(
        'requested_count', v_requested_count,
        'locked_count', v_locked_count,
        'timesheet_ids', to_jsonb(v_timesheet_ids)
      )::text;
  END IF;

  INSERT INTO public.timesheet_financial_retention(timesheet_id)
  SELECT requested.timesheet_id
  FROM unnest(v_timesheet_ids) AS requested(timesheet_id)
  ORDER BY requested.timesheet_id
  ON CONFLICT (timesheet_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'requested_count', v_requested_count,
    'locked_count', v_locked_count,
    'inserted_count', v_inserted_count,
    'already_marked_count', v_requested_count - v_inserted_count
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.timesheet_financial_retention_mark_v1(uuid[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_mark_v1(uuid[]) FROM anon;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_mark_v1(uuid[]) FROM authenticated;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_mark_v1(uuid[]) FROM service_role;

-- GENUINELY NEW IMPLEMENTATION UNIT
-- Statement-level capture for independent durable financial roots. INSERT inspects
-- NEW transition rows once. UPDATE emits only identities crossing into or out of
-- retained state, identities moved between rows, and force-include array deltas.
-- OLD identities are deliberately captured as well as NEW identities so a durable
-- relationship cannot disappear or move during live backfill without becoming sticky.
CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_capture_trigger_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF TG_TABLE_SCHEMA IS DISTINCT FROM 'public' THEN
    RAISE EXCEPTION USING MESSAGE = 'RETENTION_CAPTURE_UNEXPECTED_SCHEMA';
  END IF;

  IF TG_TABLE_NAME = 'timesheets_financials' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids
      FROM new_rows AS n
      WHERE n.timesheet_id IS NOT NULL
        AND (
          n.paid_at_utc IS NOT NULL
          OR n.paid_by_user_id IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(n.payment_reference, '')), '') IS NOT NULL
          OR n.remittance_last_sent_at_utc IS NOT NULL
          OR COALESCE(n.remittance_send_count, 0) > 0
        );
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id
        FROM old_rows AS o
        JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL
          AND (
            o.paid_at_utc IS NOT NULL
            OR o.paid_by_user_id IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(o.payment_reference, '')), '') IS NOT NULL
            OR o.remittance_last_sent_at_utc IS NOT NULL
            OR COALESCE(o.remittance_send_count, 0) > 0
          )
          AND (
            o.timesheet_id IS DISTINCT FROM n.timesheet_id
            OR NOT (
              n.paid_at_utc IS NOT NULL
              OR n.paid_by_user_id IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(n.payment_reference, '')), '') IS NOT NULL
              OR n.remittance_last_sent_at_utc IS NOT NULL
              OR COALESCE(n.remittance_send_count, 0) > 0
            )
          )
        UNION
        SELECT n.timesheet_id
        FROM new_rows AS n
        JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL
          AND (
            n.paid_at_utc IS NOT NULL
            OR n.paid_by_user_id IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(n.payment_reference, '')), '') IS NOT NULL
            OR n.remittance_last_sent_at_utc IS NOT NULL
            OR COALESCE(n.remittance_send_count, 0) > 0
          )
          AND (
            o.timesheet_id IS DISTINCT FROM n.timesheet_id
            OR NOT (
              o.paid_at_utc IS NOT NULL
              OR o.paid_by_user_id IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(o.payment_reference, '')), '') IS NOT NULL
              OR o.remittance_last_sent_at_utc IS NOT NULL
              OR COALESCE(o.remittance_send_count, 0) > 0
            )
          )
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids
      FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_batch_items' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids
      FROM new_rows AS n
      WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id
        FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id
        FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_batches' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT ids.timesheet_id ORDER BY ids.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids
      FROM new_rows AS n
      CROSS JOIN LATERAL unnest(COALESCE(n.force_include_timesheet_ids, ARRAY[]::uuid[])) AS ids(timesheet_id)
      WHERE ids.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT old_ids.timesheet_id
        FROM old_rows AS o
        JOIN new_rows AS n ON n.id = o.id
        CROSS JOIN LATERAL unnest(COALESCE(o.force_include_timesheet_ids, ARRAY[]::uuid[])) AS old_ids(timesheet_id)
        WHERE old_ids.timesheet_id IS NOT NULL
          AND NOT (old_ids.timesheet_id = ANY(COALESCE(n.force_include_timesheet_ids, ARRAY[]::uuid[])))
        UNION
        SELECT new_ids.timesheet_id
        FROM new_rows AS n
        JOIN old_rows AS o ON o.id = n.id
        CROSS JOIN LATERAL unnest(COALESCE(n.force_include_timesheet_ids, ARRAY[]::uuid[])) AS new_ids(timesheet_id)
        WHERE new_ids.timesheet_id IS NOT NULL
          AND NOT (new_ids.timesheet_id = ANY(COALESCE(o.force_include_timesheet_ids, ARRAY[]::uuid[])))
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_batch_timesheet_snapshots' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheet_pay_state' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids
      FROM new_rows AS n
      WHERE n.timesheet_id IS NOT NULL
        AND (
          n.last_settled_pay_batch_id IS NOT NULL
          OR n.last_settled_at_utc IS NOT NULL
          OR n.last_settled_signature IS NOT NULL
          OR n.last_settled_snapshot_json IS NOT NULL
          OR n.summary_pay_paid_at_utc IS NOT NULL
          OR UPPER(COALESCE(n.summary_pay_status_code, 'UNPAID')) IN (
            'PAID', 'PARTIALLY_PAID', 'PART_PAID', 'OVERPAID', 'UNDERPAID', 'PROCESSING'
          )
        );
    ELSE
      WITH old_retained AS (
        SELECT o.timesheet_id
        FROM old_rows AS o
        WHERE o.timesheet_id IS NOT NULL
          AND (
            o.last_settled_pay_batch_id IS NOT NULL
            OR o.last_settled_at_utc IS NOT NULL
            OR o.last_settled_signature IS NOT NULL
            OR o.last_settled_snapshot_json IS NOT NULL
            OR o.summary_pay_paid_at_utc IS NOT NULL
            OR UPPER(COALESCE(o.summary_pay_status_code, 'UNPAID')) IN (
              'PAID', 'PARTIALLY_PAID', 'PART_PAID', 'OVERPAID', 'UNDERPAID', 'PROCESSING'
            )
          )
      ), new_retained AS (
        SELECT n.timesheet_id
        FROM new_rows AS n
        WHERE n.timesheet_id IS NOT NULL
          AND (
            n.last_settled_pay_batch_id IS NOT NULL
            OR n.last_settled_at_utc IS NOT NULL
            OR n.last_settled_signature IS NOT NULL
            OR n.last_settled_snapshot_json IS NOT NULL
            OR n.summary_pay_paid_at_utc IS NOT NULL
            OR UPPER(COALESCE(n.summary_pay_status_code, 'UNPAID')) IN (
              'PAID', 'PARTIALLY_PAID', 'PART_PAID', 'OVERPAID', 'UNDERPAID', 'PROCESSING'
            )
          )
      ), changed AS (
        SELECT old_retained.timesheet_id
        FROM old_retained
        WHERE NOT EXISTS (
          SELECT 1 FROM new_retained WHERE new_retained.timesheet_id = old_retained.timesheet_id
        )
        UNION
        SELECT new_retained.timesheet_id
        FROM new_retained
        WHERE NOT EXISTS (
          SELECT 1 FROM old_retained WHERE old_retained.timesheet_id = new_retained.timesheet_id
        )
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheet_pay_state_history' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'ts_pay_adjustments' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_finance_case_components' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.linked_timesheet_id ORDER BY n.linked_timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.linked_timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.linked_timesheet_id AS timesheet_id
        FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.linked_timesheet_id IS NOT NULL
          AND o.linked_timesheet_id IS DISTINCT FROM n.linked_timesheet_id
        UNION
        SELECT n.linked_timesheet_id
        FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.linked_timesheet_id IS NOT NULL
          AND o.linked_timesheet_id IS DISTINCT FROM n.linked_timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_advances' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.linked_timesheet_id ORDER BY n.linked_timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.linked_timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.linked_timesheet_id AS timesheet_id
        FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.linked_timesheet_id IS NOT NULL
          AND o.linked_timesheet_id IS DISTINCT FROM n.linked_timesheet_id
        UNION
        SELECT n.linked_timesheet_id
        FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.linked_timesheet_id IS NOT NULL
          AND o.linked_timesheet_id IS DISTINCT FROM n.linked_timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_payment_correction_items' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_manual_adjustment_carry_forwards' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheet_payment_overrides' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(array_agg(DISTINCT n.timesheet_id ORDER BY n.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM new_rows AS n WHERE n.timesheet_id IS NOT NULL;
    ELSE
      WITH changed AS (
        SELECT o.timesheet_id FROM old_rows AS o JOIN new_rows AS n ON n.id = o.id
        WHERE o.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
        UNION
        SELECT n.timesheet_id FROM new_rows AS n JOIN old_rows AS o ON o.id = n.id
        WHERE n.timesheet_id IS NOT NULL AND o.timesheet_id IS DISTINCT FROM n.timesheet_id
      )
      SELECT COALESCE(array_agg(changed.timesheet_id ORDER BY changed.timesheet_id), ARRAY[]::uuid[])
        INTO v_timesheet_ids FROM changed;
    END IF;

  ELSE
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_CAPTURE_UNEXPECTED_TABLE',
      DETAIL = jsonb_build_object(
        'table_schema', TG_TABLE_SCHEMA,
        'table_name', TG_TABLE_NAME,
        'operation', TG_OP
      )::text;
  END IF;

  IF COALESCE(array_length(v_timesheet_ids, 1), 0) > 0 THEN
    PERFORM public.timesheet_financial_retention_mark_v1(v_timesheet_ids);
  END IF;

  RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION public.timesheet_financial_retention_capture_trigger_v1() FROM PUBLIC;
DO $do$
DECLARE
  v_role name;
BEGIN
  FOREACH v_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role']::name[] LOOP
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = v_role) THEN
      EXECUTE pg_catalog.format(
        'REVOKE ALL ON FUNCTION public.timesheet_financial_retention_capture_trigger_v1() FROM %I',
        v_role
      );
    END IF;
  END LOOP;
END
$do$;

CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_backfill_v1(
  p_after_timesheet_id uuid DEFAULT NULL::uuid,
  p_limit integer DEFAULT 500
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 1000);
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_mark_result jsonb := '{}'::jsonb;
  v_next_after_timesheet_id uuid := NULL;
BEGIN
  WITH retained_candidates AS MATERIALIZED (
    SELECT tf.timesheet_id
    FROM public.timesheets_financials AS tf
    WHERE tf.timesheet_id IS NOT NULL
      AND (
        tf.paid_at_utc IS NOT NULL
        OR tf.paid_by_user_id IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(tf.payment_reference, '')), '') IS NOT NULL
        OR tf.remittance_last_sent_at_utc IS NOT NULL
        OR COALESCE(tf.remittance_send_count, 0) > 0
      )
    UNION
    SELECT pbi.timesheet_id
    FROM public.pay_batch_items AS pbi
    WHERE pbi.timesheet_id IS NOT NULL
    UNION
    SELECT forced.timesheet_id
    FROM public.pay_batches AS pb
    CROSS JOIN LATERAL unnest(COALESCE(pb.force_include_timesheet_ids, ARRAY[]::uuid[])) AS forced(timesheet_id)
    WHERE forced.timesheet_id IS NOT NULL
    UNION
    SELECT snapshot.timesheet_id
    FROM public.pay_batch_timesheet_snapshots AS snapshot
    WHERE snapshot.timesheet_id IS NOT NULL
    UNION
    SELECT state.timesheet_id
    FROM public.timesheet_pay_state AS state
    WHERE state.timesheet_id IS NOT NULL
      AND (
        state.last_settled_pay_batch_id IS NOT NULL
        OR state.last_settled_at_utc IS NOT NULL
        OR state.last_settled_signature IS NOT NULL
        OR state.last_settled_snapshot_json IS NOT NULL
        OR state.summary_pay_paid_at_utc IS NOT NULL
        OR UPPER(COALESCE(state.summary_pay_status_code, 'UNPAID')) IN (
          'PAID', 'PARTIALLY_PAID', 'PART_PAID', 'OVERPAID', 'UNDERPAID', 'PROCESSING'
        )
      )
    UNION
    SELECT history.timesheet_id
    FROM public.timesheet_pay_state_history AS history
    WHERE history.timesheet_id IS NOT NULL
    UNION
    SELECT adjustment.timesheet_id
    FROM public.ts_pay_adjustments AS adjustment
    WHERE adjustment.timesheet_id IS NOT NULL
    UNION
    SELECT component.linked_timesheet_id
    FROM public.pay_finance_case_components AS component
    WHERE component.linked_timesheet_id IS NOT NULL
    UNION
    SELECT advance.linked_timesheet_id
    FROM public.pay_advances AS advance
    WHERE advance.linked_timesheet_id IS NOT NULL
    UNION
    SELECT correction.timesheet_id
    FROM public.pay_payment_correction_items AS correction
    WHERE correction.timesheet_id IS NOT NULL
    UNION
    SELECT carry_forward.timesheet_id
    FROM public.pay_manual_adjustment_carry_forwards AS carry_forward
    WHERE carry_forward.timesheet_id IS NOT NULL
    UNION
    SELECT override_row.timesheet_id
    FROM public.timesheet_payment_overrides AS override_row
    WHERE override_row.timesheet_id IS NOT NULL
  ), next_page AS (
    SELECT retained.timesheet_id
    FROM retained_candidates AS retained
    WHERE (p_after_timesheet_id IS NULL OR retained.timesheet_id > p_after_timesheet_id)
      AND EXISTS (
        SELECT 1
        FROM public.timesheets AS existing_timesheet
        WHERE existing_timesheet.timesheet_id = retained.timesheet_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.timesheet_financial_retention AS marker
        WHERE marker.timesheet_id = retained.timesheet_id
      )
    ORDER BY retained.timesheet_id
    LIMIT v_limit
  )
  SELECT COALESCE(array_agg(next_page.timesheet_id ORDER BY next_page.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
  FROM next_page;

  IF COALESCE(array_length(v_timesheet_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'done', true,
      'page_count', 0,
      'next_after_timesheet_id', p_after_timesheet_id,
      'mark_result', jsonb_build_object(
        'requested_count', 0,
        'inserted_count', 0,
        'already_marked_count', 0
      )
    );
  END IF;

  v_mark_result := public.timesheet_financial_retention_mark_v1(v_timesheet_ids);
  v_next_after_timesheet_id := v_timesheet_ids[array_length(v_timesheet_ids, 1)];

  RETURN jsonb_build_object(
    'ok', true,
    'done', COALESCE(array_length(v_timesheet_ids, 1), 0) < v_limit,
    'page_count', COALESCE(array_length(v_timesheet_ids, 1), 0),
    'next_after_timesheet_id', v_next_after_timesheet_id,
    'mark_result', v_mark_result
  );
END;
$function$;


REVOKE ALL ON FUNCTION public.timesheet_financial_retention_backfill_v1(uuid, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_backfill_v1(uuid, integer) FROM anon;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_backfill_v1(uuid, integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.timesheet_financial_retention_backfill_v1(uuid, integer) TO service_role;

CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_completeness_v1(
  p_sample_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
WITH retained_sources AS MATERIALIZED (
  SELECT tf.timesheet_id, 'TIMESHEETS_FINANCIALS_PAYMENT_OR_REMITTANCE'::text AS source_code
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id IS NOT NULL
    AND (
      tf.paid_at_utc IS NOT NULL
      OR tf.paid_by_user_id IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(tf.payment_reference, '')), '') IS NOT NULL
      OR tf.remittance_last_sent_at_utc IS NOT NULL
      OR COALESCE(tf.remittance_send_count, 0) > 0
    )
  UNION ALL
  SELECT pbi.timesheet_id, 'PAY_BATCH_ITEM' FROM public.pay_batch_items AS pbi WHERE pbi.timesheet_id IS NOT NULL
  UNION ALL
  SELECT forced.timesheet_id, 'PAY_BATCH_FORCE_INCLUDE'
  FROM public.pay_batches AS pb
  CROSS JOIN LATERAL unnest(COALESCE(pb.force_include_timesheet_ids, ARRAY[]::uuid[])) AS forced(timesheet_id)
  WHERE forced.timesheet_id IS NOT NULL
  UNION ALL
  SELECT snapshot.timesheet_id, 'PAY_BATCH_TIMESHEET_SNAPSHOT' FROM public.pay_batch_timesheet_snapshots AS snapshot WHERE snapshot.timesheet_id IS NOT NULL
  UNION ALL
  SELECT state.timesheet_id, 'TIMESHEET_PAY_STATE'
  FROM public.timesheet_pay_state AS state
  WHERE state.timesheet_id IS NOT NULL
    AND (
      state.last_settled_pay_batch_id IS NOT NULL
      OR state.last_settled_at_utc IS NOT NULL
      OR state.last_settled_signature IS NOT NULL
      OR state.last_settled_snapshot_json IS NOT NULL
      OR state.summary_pay_paid_at_utc IS NOT NULL
      OR UPPER(COALESCE(state.summary_pay_status_code, 'UNPAID')) IN (
        'PAID', 'PARTIALLY_PAID', 'PART_PAID', 'OVERPAID', 'UNDERPAID', 'PROCESSING'
      )
    )
  UNION ALL
  SELECT history.timesheet_id, 'TIMESHEET_PAY_STATE_HISTORY' FROM public.timesheet_pay_state_history AS history WHERE history.timesheet_id IS NOT NULL
  UNION ALL
  SELECT adjustment.timesheet_id, 'TS_PAY_ADJUSTMENT' FROM public.ts_pay_adjustments AS adjustment WHERE adjustment.timesheet_id IS NOT NULL
  UNION ALL
  SELECT component.linked_timesheet_id, 'PAY_FINANCE_CASE_COMPONENT' FROM public.pay_finance_case_components AS component WHERE component.linked_timesheet_id IS NOT NULL
  UNION ALL
  SELECT advance.linked_timesheet_id, 'PAY_ADVANCE' FROM public.pay_advances AS advance WHERE advance.linked_timesheet_id IS NOT NULL
  UNION ALL
  SELECT correction.timesheet_id, 'PAY_PAYMENT_CORRECTION_ITEM' FROM public.pay_payment_correction_items AS correction WHERE correction.timesheet_id IS NOT NULL
  UNION ALL
  SELECT carry_forward.timesheet_id, 'PAY_MANUAL_ADJUSTMENT_CARRY_FORWARD' FROM public.pay_manual_adjustment_carry_forwards AS carry_forward WHERE carry_forward.timesheet_id IS NOT NULL
  UNION ALL
  SELECT override_row.timesheet_id, 'TIMESHEET_PAYMENT_OVERRIDE' FROM public.timesheet_payment_overrides AS override_row WHERE override_row.timesheet_id IS NOT NULL
), retained_candidates AS MATERIALIZED (
  SELECT DISTINCT retained_sources.timesheet_id
  FROM retained_sources
), missing AS MATERIALIZED (
  SELECT candidate.timesheet_id
  FROM retained_candidates AS candidate
  LEFT JOIN public.timesheet_financial_retention AS marker
    ON marker.timesheet_id = candidate.timesheet_id
  WHERE marker.timesheet_id IS NULL
), orphaned AS MATERIALIZED (
  SELECT candidate.timesheet_id
  FROM retained_candidates AS candidate
  LEFT JOIN public.timesheets AS t ON t.timesheet_id = candidate.timesheet_id
  WHERE t.timesheet_id IS NULL
), source_counts AS (
  SELECT retained_sources.source_code, COUNT(DISTINCT retained_sources.timesheet_id)::integer AS timesheet_count
  FROM retained_sources
  GROUP BY retained_sources.source_code
)
SELECT jsonb_build_object(
  'ok', true,
  'complete', (SELECT COUNT(*) FROM missing) = 0 AND (SELECT COUNT(*) FROM orphaned) = 0,
  'retained_identity_count', (SELECT COUNT(*) FROM retained_candidates),
  'marker_count', (SELECT COUNT(*) FROM public.timesheet_financial_retention),
  'missing_marker_count', (SELECT COUNT(*) FROM missing),
  'orphaned_retained_identity_count', (SELECT COUNT(*) FROM orphaned),
  'missing_marker_sample', COALESCE((
    SELECT jsonb_agg(sample.timesheet_id ORDER BY sample.timesheet_id)
    FROM (
      SELECT missing.timesheet_id
      FROM missing
      ORDER BY missing.timesheet_id
      LIMIT LEAST(GREATEST(COALESCE(p_sample_limit, 100), 1), 1000)
    ) AS sample
  ), '[]'::jsonb),
  'orphaned_identity_sample', COALESCE((
    SELECT jsonb_agg(sample.timesheet_id ORDER BY sample.timesheet_id)
    FROM (
      SELECT orphaned.timesheet_id
      FROM orphaned
      ORDER BY orphaned.timesheet_id
      LIMIT LEAST(GREATEST(COALESCE(p_sample_limit, 100), 1), 1000)
    ) AS sample
  ), '[]'::jsonb),
  'source_counts', COALESCE((
    SELECT jsonb_object_agg(source_counts.source_code, source_counts.timesheet_count ORDER BY source_counts.source_code)
    FROM source_counts
  ), '{}'::jsonb)
);
$function$;

REVOKE ALL ON FUNCTION public.timesheet_financial_retention_completeness_v1(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_completeness_v1(integer) FROM anon;
REVOKE ALL ON FUNCTION public.timesheet_financial_retention_completeness_v1(integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.timesheet_financial_retention_completeness_v1(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.timesheet_financial_retention_assert_complete_v1()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb := public.timesheet_financial_retention_completeness_v1(100);
BEGIN
  IF COALESCE((v_result ->> 'complete')::boolean, false) IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING
      MESSAGE = 'RETENTION_MARKER_BACKFILL_INCOMPLETE',
      DETAIL = v_result::text;
  END IF;

  RETURN v_result;
END;
$function$;

